DELETE FROM `chatbot_learned_qa` WHERE `answer_text` LIKE '%chưa có trong CSDL%' OR `answer_text` LIKE '%Gợi ý tự nấu%' OR `answer_text` LIKE '%tự nấu do%' OR (`source_type`='AUTO_LEARNED' AND (`matched_recipe_ids` IS NULL OR `matched_recipe_ids`='' OR `matched_recipe_ids`='[]'));

ON DUPLICATE KEY UPDATE `answer_text`=VALUES(`answer_text`),`keywords_text`=VALUES(`keywords_text`),`matched_recipe_ids`=COALESCE(NULLIF(`matched_recipe_ids`,'[]'),VALUES(`matched_recipe_ids`)),`quality_score`=GREATEST(`quality_score`,VALUES(`quality_score`)),`is_verified`=1;

