INSERT INTO `categories` (`category_id`,`name`,`slug`,`icon`,`description`,`image_url`,`recipe_count`) VALUES
(1,'Món chính','mon-chinh','fa-utensils','Các món mặn, kho, rim, bún cơm đặc sản 3 miền đậm đà cho bữa chính.','https://www.cet.edu.vn/wp-content/uploads/2018/03/thit-kho-tau-trung-cut.jpg',71),
(2,'Món canh - Súp','mon-canh-sup','fa-bowl-food','Canh chua, súp bổ dưỡng và bún phở bánh canh nước dùng thanh ngọt.','https://cdn2.fptshop.com.vn/unsafe/2024_3_23_638467922672032197_batch_cach-nau-canh-chua-ca-loc.jpg',47),
(3,'Món xào','mon-xao','fa-fire','Món xào nhanh lửa lớn giữ trọn độ giòn xanh và hương vị núi rừng - biển cả.','https://cdn2.fptshop.com.vn/unsafe/thit_bo_xao_thap_cam_2_7bb704dd0b.png',28),
(4,'Món nướng - Chiên','mon-nuong-chien','fa-drumstick-bite','Món nướng than thơm lừng và bánh chả chiên giòn rụm vàng ươm.','https://www.huongnghiepaau.com/wp-content/uploads/2018/06/ga-nuong-mat-ong.jpg',43),
(5,'Món chay','mon-chay','fa-leaf','Thực đơn thuần thực vật thanh tịnh, giàu đạm và cân bằng dinh dưỡng.','https://cdn.tgdd.vn/2024/01/CookRecipe/GalleryStep/thanh-pham-44.jpg',31),
(6,'Món tráng miệng','mon-trang-mieng','fa-ice-cream','Chè truyền thống 3 miền, tào phớ, bánh quê và tráng miệng thanh mát.','https://www.lorca.vn/wp-content/uploads/2022/11/maxresdefault-8.jpg',26),
(7,'Đồ uống','do-uong','fa-mug-hot','Cà phê trứng, nước sấu, nước thảo mộc, trà trái cây và sữa hạt bổ dưỡng.','https://cdn2.fptshop.com.vn/unsafe/640x0/filters:format(webp):quality(75)/cach_lam_tra_dao_cam_sa_2313d177e5.jpg',20),
(8,'Món khai vị','mon-khai-vi','fa-plate-wheat','Gỏi nộm thanh mát, phở cuốn, bánh bèo nậm và món khai tiệc tinh tế.','https://www.cet.edu.vn/wp-content/uploads/2018/11/goi-cuon-tom-thit.jpg',34)
