INSERT INTO `recipes` (`recipe_id`,`dish_id`,`category_id`,`title`,`slug`,`description`,`image_url`,`cuisine`,`servings`,`prep_time`,`cook_time`,`difficulty`,`occasion`,`calories`,`protein`,`carbs`,`fat`,`fiber`,`rating`,`review_count`,`views`,`is_featured`,`is_new`,`tags_json`,`source_type`,`created_by`,`status`,`rejection_reason`,`reviewed_by`) VALUES
(1,1,2,'Phở bò Hà Nội truyền thống','pho-bo-ha-noi-truyen-thong','Bát phở bò ngào ngạt hương thơm của hồi quế, nước dùng trong veo ngọt thanh từ xương ống bò hầm kỹ.','https://file.hstatic.net/200000700229/file/cach-nau-pho-bo-ha-noi-3.jpg','Món Việt',4,30,120,'Khó','Tết cổ truyền',446,30.80,44.10,15.60,2.20,4.90,2,4520,1,0,'[]','DB',1,'APPROVED',NULL,1),
(2,2,4,'Bún chả Hà Nội nướng than hoa','bun-cha-ha-noi-nuong-than-hoa','Chả miếng vàng óng, chả viên mềm thơm đượm khói than, ăn kèm bát nước mắm chua ngọt và bún tươi mát rượi.','https://giadinh.mediacdn.vn/296230595582509056/2025/10/1/buoc-11-thanh-pham-11-7068-1681636164-17592945738612024306639.jpg','Món Việt',4,40,35,'Trung bình','Tiệc gia đình',469,51.00,49.30,6.50,1.60,4.80,1,3890,1,0,'[]','DB',1,'APPROVED',NULL,1),
(3,3,1,'Cơm tấm sườn nướng mật ong Sài Gòn','com-tam-suon-nuong-mat-ong','Miếng sườn cốt lết dày dặn ngấm đẫm sốt sả mật ong nướng vàng ươm, ăn kèm mỡ hành béo ngậy và nước mắm kẹo.','https://beptruong.edu.vn/wp-content/uploads/2018/06/cach-uop-suon-nuong.jpg','Món Việt',2,30,25,'Dễ',NULL,774,55.30,97.30,17.00,2.00,4.70,1,2840,1,1,'[]','DB',1,'APPROVED',NULL,1),
(4,4,8,'Gỏi cuốn tôm thịt thanh mát','goi-cuon-tom-thit-thanh-mat','Từng cuốn gỏi trong veo lộ rõ tôm đỏ hồng và thịt luộc ngọt mềm, cuốn tròn cùng rau sống chấm tương đen bùi béo.','https://afamilycdn.com/150157425591193600/2024/5/26/cach-lam-goi-cuon-tom-thit-thanh-mat-cho-ngay-he2-16203049-1716723175675-1716723175867430017227.jpg','Món Việt',3,25,15,'Dễ','Tiệc gia đình',364,47.50,22.20,9.80,2.20,4.90,1,4120,1,0,'[]','DB',1,'APPROVED',NULL,1),
(5,5,2,'Canh chua cá basa bông điên điển','canh-chua-ca-basa','Vị chua thanh mát của me hòa quyện với bùi béo của cá basa tươi, dứa thơm lừng và đậu bắp giòn ngọt miền Tây.','https://www.adcfoods.com/wp-content/uploads/2021/02/cach-nau-mon-canh-chua-ca-basa-800x675.jpg','Món Việt',4,20,20,'Dễ',NULL,222,18.90,9.60,12.10,1.00,4.60,1,1950,1,1,'[]','DB',1,'APPROVED',NULL,1),
(6,6,1,'Thịt kho tàu nước dừa trứng vịt','thit-kho-tau-nuoc-dua','Món ăn biểu tượng ngày Tết với miếng thịt ba chỉ vuông vức mềm tan ngập trong nước dừa xiêm hổ phách sánh mượt.','https://cdn.tgdd.vn/2021/02/CookProductThumb/Screenshot3-620x620.jpg','Món Việt',4,25,65,'Trung bình','Tết cổ truyền',376,50.90,11.70,12.60,1.20,4.90,1,5210,1,0,'[]','DB',1,'APPROVED',NULL,1),
(7,7,6,'Chè bưởi An Giang giòn sần sật','che-buoi-an-giang','Cùi bưởi giòn giòn không chút đắng, đỗ xanh bở tơi ngậy thơm chan cùng nước cốt dừa béo ngọt nức mũi.','https://tinhdaubuoi.vn/data/upload_file/Image/Buoi-trong-am-thuc/cach-nau-che-buoi-an-giang-7.jpeg','Món Việt',4,45,30,'Dễ','Rằm tháng Giêng',426,7.00,66.50,16.00,2.90,4.80,1,2680,1,0,'[]','DB',1,'APPROVED',NULL,1),
(8,8,4,'Gà nướng sả ớt da giòn thơm lừng','ga-nuong-sa-ot-da-gion','Thịt gà ta chắc ngọt thấm đẫm sả ớt cay nồng, lớp da gà vàng ruộm bóng loáng thích hợp cho tiệc sum họp cuối tuần.','https://barona.vn/storage/meo-vat/54/ga-nuong-sa-ot.jpg','Món Việt',4,30,45,'Trung bình','Tiệc gia đình',593,94.50,12.80,15.90,0.20,4.80,1,3100,1,1,'[]','DB',1,'APPROVED',NULL,1),
(9,9,3,'Rau muống xào tỏi xanh mướt giòn rụm','rau-muong-xao-toi','Món ăn dân dã thân thương nhưng đòi hỏi lửa lớn để cọng rau giữ nguyên sắc xanh bóng, tỏi phi thơm nồng nàn.','https://beptruong.edu.vn/wp-content/uploads/2021/04/mon-rau-muong-xao-xanh-muot.jpg','Món Việt',3,10,10,'Dễ',NULL,129,5.10,10.40,8.70,3.30,4.70,1,1820,1,0,'[]','DB',1,'APPROVED',NULL,1),
(10,10,5,'Đậu hũ sốt cà chua thanh đạm','dau-hu-sot-ca-chua','Miếng đậu phụ vàng giòn ngập tràn trong làn sốt cà chua đỏ tươi óng ánh, thơm phưng phức hành hoa.','https://cdn.tgdd.vn/2023/10/CookRecipe/GalleryStep/thanh-pham-56.jpg','Món Việt',2,10,15,'Dễ',NULL,292,13.60,13.20,22.40,2.00,4.60,1,1640,1,1,'[]','DB',1,'APPROVED',NULL,1),
(11,11,2,'Bún bò Huế cay nồng chuẩn vị Cố đô','bun-bo-hue-cay-nong','Sợi bún to tròn trong tô nước dùng đậm đà hương mắm ruốc và sả ớt, kèm bắp bò hoa và chả cua thơm giòn.','https://luhanhvietnam.com.vn/du-lich/vnt_upload/news/12_2020/2222bun-bo-hue-cookingwithmamamui_1.jpg','Món Việt',4,40,90,'Khó','Tiệc gia đình',565,56.90,38.70,18.90,1.40,4.90,1,4850,1,0,'[]','DB',1,'APPROVED',NULL,1),
(12,12,4,'Bánh xèo miền Trung giòn rụm nhân tôm thịt','banh-xeo-mien-trung','Vỏ bánh xèo mỏng tang vàng ươm nghệ tươi, giòn rụm cuốn bánh tráng rau rừng chấm nước mắm đậu phộng sánh béo.','https://khietminhbakery.com/wp-content/uploads/2025/09/banh-xeo-mien-trung-voi-vo-banh-mong-gion-nhan-tom-thit-tuoi-ngon.jpg','Món Việt',3,30,25,'Trung bình',NULL,560,42.00,69.70,12.40,4.10,4.80,1,3240,1,0,'[]','DB',1,'APPROVED',NULL,1),
(13,13,7,'Sinh tố bơ sáp nước cốt dừa béo mịn','sinh-to-bo-sap','Thức uống bổ dưỡng từ bơ sáp Đắk Lắk dẻo quánh, vị béo ngọt tự nhiên kết hợp cùng sữa tươi và đá tuyết mát lạnh.','https://cdn2.fptshop.com.vn/unsafe/828x0/filters:format(webp):quality(75)/sinh_to_bo_sua_chua_nuoc_cot_dua_thumb_ba672ff94b.png','Món Việt',2,10,5,'Dễ',NULL,180,3.30,19.80,10.90,2.80,4.70,1,1450,1,0,'[]','DB',1,'APPROVED',NULL,1),
(14,14,1,'Gà kho gừng ấm nồng ngày trở gió','ga-kho-gung-am-nong','Từng miếng thịt gà ta vàng ươm thơm lừng mùi gừng tươi cay ấm, nước kho sền sệt quyện chặt đưa cơm ngày mưa.','https://cdn2.fptshop.com.vn/unsafe/Uploads/images/tin-tuc/163733/Originals/ga-kho-gung-5.jpg','Món Việt',3,15,25,'Trung bình','Giáng sinh',325,53.50,11.00,6.20,0.90,4.80,1,2210,1,0,'[]','DB',1,'APPROVED',NULL,1),
(15,15,8,'Chả giò rế tôm thịt giòn rụm cung đình','cha-gio-re-tom-thit','Vỏ bánh tráng rế đan lưới chiên giòn tan trong miệng, nhân tôm thịt nấm mèo đậm đà hương vị truyền thống.','https://afamilycdn.com/2017/cha-gio-re-tom-thit-6-1510669094692.jpg','Món Việt',4,35,20,'Trung bình','Tết cổ truyền',853,32.70,3.20,79.70,0.80,4.90,1,3780,1,0,'[]','DB',1,'APPROVED',NULL,1),
