(120,120,1,'Bún đậu mắm tôm đầy đủ','bun-dau-mam-tom-day-du','Mẹt bún lá, đậu hũ rán giòn rụm, thịt bắp heo luộc ngọt thịt, chả cốm thơm dẻo chấm mắm tôm đánh bông vị tắc.','https://file.hstatic.net/1000394081/article/bun-dau-mam-tom-thap-cam_2321472f6d634b1192e171c5e659e187.jpg','Món Việt',4,20,20,'Dễ',NULL,664,35.50,46.70,38.10,1.90,4.60,2,180,1,0,'["hà nội", "bún", "đặc sản"]','DB',1,'APPROVED',NULL,1),
(121,121,1,'Bò né chảo gang ốp la','bo-ne-chao-gang-op-la','Thịt bò thăn áp chảo gang xèo xèo cùng trứng ốp la lòng đào, cà chua hành tây thơm lừng ăn kèm bánh mì giòn.','https://ngantho.vn/wp-content/uploads/2023/07/nuoc-cham-bo-ne-e1689346923375.jpeg','Món Việt',4,15,12,'Dễ',NULL,601,42.30,37.90,29.80,2.70,4.70,3,191,0,0,'["bữa sáng", "món bò", "chảo gang"]','DB',1,'APPROVED',NULL,1),
(122,122,1,'Vịt kho gừng thơm nồng','vit-kho-gung-thom-nong','Thịt vịt săn ngọt quyện cùng hương gừng sợi cay ấm, khử sạch mùi hôi, cực kỳ đưa cơm vào ngày mưa mát.','https://cooponline.vn/tin-tuc/wp-content/uploads/2026/05/cach-lam-vit-kho-gung-thom-nong-dam-da-dua-com-4.png','Món Việt',4,20,30,'Dễ',NULL,506,35.00,10.40,35.30,0.60,4.80,4,202,0,0,'["món kho", "vịt", "cơm gia đình"]','DB',1,'APPROVED',NULL,1),
(123,123,1,'Cá chép om dưa cải chua','ca-chep-om-dua-cai-chua','Cá chép chiên vàng sơ ôm trọn vị chua dịu của dưa cải, cà chua và thì là dậy hương, ăn cùng bún tươi rất tròn vị.','https://icdn.one/upload/2020/11/12/20201112100947-f4c522ff.jpg','Món Việt',4,20,25,'Trung bình',NULL,374,38.60,7.80,20.40,3.10,4.90,5,213,0,0,'["món om", "cá chép", "cơm gia đình"]','DB',1,'APPROVED',NULL,1),
(124,124,1,'Sườn cốt lết rim tỏi ớt','suon-cot-let-rim-toi-ot','Miếng sườn cốt lết mềm mọng không khô xác, phủ đều lớp sốt tỏi ớt mặn ngọt óng ánh thơm lừng.','https://cdn.tgdd.vn/2021/05/CookProduct/maxredefault-1200x676.jpg','Món Việt',4,15,20,'Dễ',NULL,459,36.10,10.40,30.10,0.40,4.60,6,224,0,0,'["món rim", "sườn", "cơm văn phòng"]','DB',1,'APPROVED',NULL,1),
(125,125,1,'Chả cá Lã Vọng Hà Nội','cha-ca-la-vong-ha-noi','Chả cá lăng/cá lóc ướp riềng mẻ nghệ nướng vàng xém cạnh, xào nóng tại bàn cùng thật nhiều thì là hành lá ăn bún mắm tôm.','https://cdn2.fptshop.com.vn/unsafe/1920x0/filters:format(webp):quality(75)/2024_3_31_638475244568544831_cha-ca-la-vong-ha-noi.jpg','Món Việt',4,25,18,'Trung bình',NULL,521,41.20,40.30,22.90,3.40,4.70,7,235,1,0,'["hà nội", "đặc sản", "chả cá"]','DB',1,'APPROVED',NULL,1)
INSERT INTO `recipes` (`recipe_id`,`dish_id`,`category_id`,`title`,`slug`,`description`,`image_url`,`cuisine`,`servings`,`prep_time`,`cook_time`,`difficulty`,`occasion`,`calories`,`protein`,`carbs`,`fat`,`fiber`,`rating`,`review_count`,`views`,`is_featured`,`is_new`,`tags_json`,`source_type`,`created_by`,`status`,`rejection_reason`,`reviewed_by`) VALUES
(126,126,1,'Bún chả cá Đà Nẵng','bun-cha-ca-da-nang','Nước dùng ngọt thanh vị cá kết hợp bí đỏ, bắp cải và măng tươi, ăn kèm chả cá thác lác chiên dai ngọt trứ danh miền Trung.','https://cdn2.fptshop.com.vn/unsafe/Uploads/images/tin-tuc/163071/Originals/bun-cha-ca-5.jpg','Món Việt',4,25,35,'Trung bình',NULL,334,22.90,51.30,5.20,3.70,4.80,2,246,0,0,'["đà nẵng", "bún", "miền trung"]','DB',1,'APPROVED',NULL,1),
(127,127,1,'Hủ tiếu Nam Vang thanh ngọt','hu-tieu-nam-vang-thanh-ngot','Sợi hủ tiếu dai ngon quyện nước hầm xương thơm mùi tôm khô mực khô, đầy ắp thịt băm, tôm sú và trứng cút.','https://cdn.tgdd.vn/Files/2017/03/21/963404/cach-nau-hu-tieu-nam-vang-ngon-dung-dieu-tai-nha-202208251951367231.jpg','Món Việt',4,30,50,'Khó',NULL,631,45.60,68.60,18.60,2.00,4.90,3,257,1,0,'["miền nam", "bữa sáng", "hủ tiếu"]','DB',1,'APPROVED',NULL,1),
(128,128,1,'Cơm chiên Dương Châu hạt tơi','com-chien-duong-chau-hat-toi','Hạt cơm nguội tơi vàng ươm áo trứng kết hợp lạp xưởng, tôm sú, đậu Hà Lan và cà rốt bắt mắt, đầy đủ dinh dưỡng.','https://cdn.tgdd.vn/Files/2019/12/30/1229114/cach-lam-com-chien-duong-chau-sieu-hap-dan-chong-ngan-ngay-tet-hat-com-vang-uom-toi-va-tham-vi-202203031505257988.jpg','Món Việt',4,15,15,'Dễ',NULL,494,21.50,53.10,21.40,2.40,4.60,4,268,0,0,'["cơm chiên", "ăn nhanh", "trẻ em thích"]','DB',1,'APPROVED',NULL,1),
(129,129,1,'Bò lúc lắc khoai tây chiên','bo-luc-lac-khoai-tay-chien','Thịt bò cắt khối vuông mềm mọng cháy cạnh vừa tới hòa cùng ớt chuông giòn ngọt và khoai tây chiên vàng ươm.','https://www.cet.edu.vn/wp-content/uploads/2018/03/bo-luc-lac-khoai-tay-chien.jpg','Món Việt',4,20,15,'Trung bình',NULL,542,35.60,20.90,34.30,3.30,4.70,5,279,1,0,'["món bò", "tiệc gia đình", "áp chảo"]','DB',1,'APPROVED',NULL,1),
(130,130,1,'Lươn om chuối đậu nghệ vàng','luon-om-chuoi-dau-nghe-vang','Lươn đồng làm sạch khéo léo, om cùng chuối xanh bùi bở, đậu hũ rán và nước nghệ mẻ thơm nức chuẩn vị Bắc Bộ.','https://giadinh.mediacdn.vn/296230595582509056/2024/5/30/om-luon-chuoi-me-38378903462253738842341475930583163286911343n-1698034328-997-width780height977-1717089074001-17170890740981779781105.jpg','Món Việt',4,25,30,'Trung bình',NULL,528,33.80,21.20,34.40,3.40,4.80,6,290,0,0,'["bắc bộ", "món om", "truyền thống"]','DB',1,'APPROVED',NULL,1),
(131,131,1,'Gà nấu đậu Hà Lan bánh mì','ga-nau-dau-ha-lan-banh-mi','Đùi gà mềm tan trong nước sốt cà chua sánh mịn thơm mùi khoai tây, cà rốt và đậu Hà Lan, chấm bánh mì nóng tuyệt ngon.','https://cdn.tgdd.vn/2021/08/CookProduct/thum-1200x676-1.jpg','Món Việt',4,20,35,'Dễ','Cuối tuần',576,41.80,57.60,19.00,7.30,4.90,7,301,0,0,'["món hầm", "bánh mì", "tiệc gia đình"]','DB',1,'APPROVED',NULL,1),
(132,132,1,'Cá nục kho cà chua mía','ca-nuc-kho-ca-chua-mia','Cá nục kho nhừ ngọt đậm đà trên lớp mía chẻ thơm dịu và sốt cà chua sánh đỏ, mềm xương ăn cực kỳ bắt cơm.','https://cdn2.fptshop.com.vn/unsafe/2024_1_20_638413157543493564_ca-nuc-kho-ca-chua-anh-dai-dien.jpg','Món Việt',4,20,40,'Dễ',NULL,308,32.70,9.70,15.10,1.20,4.60,2,312,0,0,'["cá biển", "món kho", "cơm gia đình"]','DB',1,'APPROVED',NULL,1),
(133,133,1,'Thịt đông dưa hành miền Bắc','thit-dong-dua-hanh-mien-bac','Món cổ truyền ngày Tết với thịt chân giò, tai heo và nấm mèo ninh mềm trong lớp thạch đông trong suốt, ăn kèm dưa cải chua.','https://cdn.tgdd.vn/2020/08/CookProduct/Untitled-1-1200x676-9.jpg','Món Việt',6,25,50,'Trung bình','Tết',292,19.20,10.30,19.50,5.40,4.70,3,323,0,0,'["tết", "bắc bộ", "truyền thống"]','DB',1,'APPROVED',NULL,1),
(134,134,1,'Ức gà sốt cà chua đậm đà','uc-ga-sot-ca-chua-dam-da','Ức gà áp chảo mềm mọng quyện trong lớp sốt cà chua chín đỏ sánh mịn, vị chua ngọt hài hòa cực kỳ hao cơm mà vẫn giàu đạm ít béo.','https://cdn.tgdd.vn/2022/04/CookRecipe/GalleryStep/4F49A79C-616B-4462-BC1B-470532C816C8.jpg','Món Việt',4,15,20,'Dễ',NULL,289,40.90,10.90,8.50,1.90,4.80,4,334,1,0,'["ức gà", "eat clean", "cơm gia đình", "sốt cà chua"]','DB',1,'APPROVED',NULL,1),
(135,135,2,'Phở gà ta lá chanh Hà Nội','pho-ga-ta-la-chanh-ha-noi','Bát phở gà nước dùng trong vắt thơm lừng thảo quả quế hồi, thịt gà ta da giòn vàng ươm cùng lá chanh thái chỉ.','https://cdn2.fptshop.com.vn/unsafe/800x0/cach_lam_pho_ga_ha_noi_11_13124be2b6.jpg','Món Việt',4,25,45,'Trung bình',NULL,498,37.50,46.50,17.40,2.10,4.90,5,345,1,0,'["hà nội", "phở", "bữa sáng"]','DB',1,'APPROVED',NULL,1),
(136,136,2,'Bún riêu cua đồng ốc bươu','bun-rieu-cua-dong-oc-buou','Riêu cua đồng đóng tảng béo ngậy gạch cua cùng ốc bươu giòn sần sật, đậu hũ chiên vàng trong nước dùng chua dịu cà chua.','https://cdn.tgdd.vn/Files/2019/03/07/1153440/cach-nau-bun-rieu-cua-dong-ngon-dam-da-chuan-vi-tai-nha-202112291555189914.jpg','Món Việt',4,30,40,'Khó',NULL,365,27.50,50.00,6.30,2.80,4.60,6,356,1,0,'["bún riêu", "truyền thống", "cuối tuần"]','DB',1,'APPROVED',NULL,1),
(137,137,2,'Canh khổ qua nhồi thịt thanh nhiệt','canh-kho-qua-nhoi-thit-thanh-nhiet','Khổ qua giòn nhẹ bớt đắng ôm lấy phần nhân thịt băm giò sống nấm mèo dai ngọt trong nước canh trong thanh mát.','https://cdn.tgdd.vn/Files/2018/01/28/1062511/cach-lam-canh-kho-qua-nhoi-thit-ngon-ngot-thanh-mat-202208261429458825.jpg','Món Việt',4,25,25,'Trung bình','Tết',251,16.50,16.20,13.90,7.10,4.70,7,367,0,0,'["thanh nhiệt", "món canh", "tết"]','DB',1,'APPROVED',NULL,1),
(138,138,2,'Canh bầu nấu tôm khô ngọt thanh','canh-bau-nau-tom-kho-ngot-thanh','Bát canh bầu non mềm ngọt tự nhiên quyện vị tôm khô bùi thơm và hành lá tiêu xay, chế biến cực nhanh cho bữa cơm hè.','https://cdn.tgdd.vn/2021/09/CookProduct/thum1200-1200x676-4.jpg','Món Việt',4,12,12,'Dễ',NULL,80,8.50,5.90,3.00,1.00,4.80,2,378,0,0,'["mùa hè", "món canh", "nhanh gọn"]','DB',1,'APPROVED',NULL,1),
(139,139,2,'Canh mướp hương mồng tơi thịt băm','canh-muop-huong-mong-toi-thit-bam','Canh mướp hương thơm ngào ngạt hòa quyện rau mồng tơi xanh mướt cùng thịt heo băm, giải nhiệt nhẹ nhàng.','https://cdn.tgdd.vn/2021/07/CookProduct/z255031401612445572611f3d66e04c22921306cf33949-1200x676-1.jpg','Món Việt',4,10,10,'Dễ',NULL,148,8.60,5.20,10.70,1.80,4.90,3,389,0,0,'["mùa hè", "món canh", "giải nhiệt"]','DB',1,'APPROVED',NULL,1),
(140,140,2,'Canh măng giò heo ngày Tết','canh-mang-gio-heo-ngay-tet','Chân giò heo hầm mềm béo ngậy cùng măng khô dai giòn thơm phức nước dùng trong, món canh truyền thống không thể thiếu dịp sum họp.','https://thucphamquocte.vn/wp-content/uploads/2024/01/canh-mang-gio-heo-ngay-tet.jpg','Món Việt',4,30,55,'Trung bình','Tết',599,39.00,22.60,38.90,12.20,4.60,4,400,0,0,'["tết", "món canh", "bắc bộ"]','DB',1,'APPROVED',NULL,1),
(141,141,2,'Canh cua nấu rau đay mồng tơi','canh-cua-nau-rau-day-mong-toi','Riêu cua đồng béo thơm hòa với rau đay, mồng tơi và mướp hương ngọt lịm, giải nhiệt tuyệt vời trưa hè.','https://www.lorca.vn/wp-content/uploads/2023/06/canh-cua-dong-mong-toi.jpeg','Món Việt',4,20,15,'Dễ',NULL,97,12.10,6.90,2.80,2.30,4.70,5,411,0,0,'["mùa hè", "truyền thống", "canh cua"]','DB',1,'APPROVED',NULL,1),
(142,142,2,'Canh chua cá lóc miền Tây','canh-chua-ca-loc-mien-tay','Canh chua cá lóc đậm hương vị Nam Bộ với nước me chua thanh, bạc hà, đậu bắp, giá đỗ, dứa và rau om ngò gai thơm lừng.','https://cookbeo.com/media/2020/05/895368695/mon-canh-chua-ca-loc.jpg','Món Việt',4,20,20,'Dễ',NULL,220,28.60,20.10,4.10,3.70,4.80,6,422,1,0,'["miền tây", "canh chua", "cá lóc"]','DB',1,'APPROVED',NULL,1),
(143,143,2,'Súp gà kem bắp ngọt sánh mịn','sup-ga-kem-bap-ngot-sanh-min','Chén súp gà xé phay sánh mượt cùng bắp ngọt hạt vàng ươm, nấm hương và lòng trắng trứng vân mây bổ dưỡng cho mọi lứa tuổi.','https://cdn.tgdd.vn/2021/08/CookProduct/tp1200-1200x676-7.jpg','Món Việt',4,15,25,'Dễ',NULL,288,31.30,22.90,8.00,1.90,4.90,7,433,0,0,'["súp", "dễ tiêu", "trẻ em thích"]','DB',1,'APPROVED',NULL,1),
(144,144,2,'Canh chua sườn non lá giang','canh-chua-suon-non-la-giang','Vị chua thanh dịu của lá giang vò nát hòa quyện sườn non ninh mềm ngọt nước, đậm chất ẩm thực đồng quê Nam Bộ.','https://cdn.tgdd.vn/2021/11/CookDishThumb/cach-nau-canh-cai-chua-suon-non-chua-ngot-ngon-hap-dan-giai-thumb-620x620.jpg','Món Việt',4,15,35,'Dễ',NULL,378,26.20,6.40,27.00,1.00,4.60,2,444,0,0,'["món canh", "sườn non", "miền nam"]','DB',1,'APPROVED',NULL,1),
(145,145,2,'Canh gà nấu cà chua dứa','canh-ga-nau-ca-chua-dua','Tô canh gà thanh ngọt tự nhiên từ ức gà mềm kết hợp vị chua dịu của cà chua chín và dứa tươi, điểm hương rau om giải nhiệt ngày hè.','https://file.hstatic.net/200000700229/article/nau-canh-ga-nam-7_19a8611bb27b45148ed7dc5157923854.jpg','Món Việt',4,15,20,'Dễ',NULL,185,28.70,9.30,3.40,1.70,4.70,3,455,0,0,'["ức gà", "món canh", "thanh đạm", "cà chua"]','DB',1,'APPROVED',NULL,1),
(146,146,2,'Miến măng gà thanh ngọt','mien-mang-ga-thanh-ngot','Tô miến dong dai ngon hòa cùng thịt gà xé mềm, măng khô giòn sần sật và nước dùng thơm mùi hành phi gừng ấm.','https://storage.googleapis.com/onelife-public/cach_nau_mien_mang_ga_thumbnail_038025ee9b/cach_nau_mien_mang_ga_thumbnail_038025ee9b.jpg','Món Việt',4,25,35,'Dễ',NULL,496,30.90,61.20,13.50,8.30,4.80,4,466,0,0,'["bữa sáng", "miến", "truyền thống"]','DB',1,'APPROVED',NULL,1),
(147,147,3,'Lòng gà xào mướp giá thơm lừng','long-ga-xao-muop-gia-thom-lung','Lòng gà sạch giòn sần sật kết hợp mướp hương ngọt mềm và giá đỗ thanh giòn, món xào đưa cơm chuẩn vị nhà.','https://cdn.tgdd.vn/Files/2017/05/27/986726/cach-lam-long-ga-xao-muop-huong-ai-cung-tam-tac-khen-ngon-202208231533017843.jpg','Món Việt',4,20,10,'Trung bình',NULL,204,18.50,9.70,10.70,1.90,4.90,5,477,0,0,'["món xào", "cơm gia đình", "nhanh gọn"]','DB',1,'APPROVED',NULL,1),
(148,148,3,'Thịt bò xào hoa thiên lý','thit-bo-xao-hoa-thien-ly','Hoa thiên lý giòn xanh thanh mát giàu dinh dưỡng đảo nhanh trên lửa lớn cùng thịt bò thăn mềm ngọt thấm tỏi thơm.','https://cdn.tgdd.vn/Files/2019/09/03/1194709/thit-bo-xao-hoa-thien-ly-mem-thom-hap-dan-cho-bua-com-trua-201909032251071346.jpg','Món Việt',4,15,8,'Dễ',NULL,272,22.20,7.90,16.50,2.20,4.60,6,488,0,0,'["món bò", "mùa hè", "nhanh gọn"]','DB',1,'APPROVED',NULL,1),
(149,149,3,'Mực xào cần tỏi hành tây','muc-xao-can-toi-hanh-tay','Mực ống khứa vảy rồng trắng giòn không tanh hòa cùng cần tây thơm lừng, hành tây và cà chua tạo vị thanh giòn hấp dẫn.','https://thucthan.com/media/2019/05/muc-xao-can-toi/muc-xao-can-toi.jpg','Món Việt',4,15,10,'Dễ',NULL,182,18.80,11.20,6.80,1.50,4.70,7,499,0,0,'["hải sản", "món xào", "mực"]','DB',1,'APPROVED',NULL,1),
(150,150,3,'Ếch xào sả ớt đậm đà','ech-xao-sa-ot-dam-da','Thịt đùi ếch săn ngọt chắc thịt xào lăn quyện nước sốt sả ớt vàng nghệ cay thơm ấm bụng, món ngon đổi vị cuối tuần.','https://cdn2.fptshop.com.vn/unsafe/1920x0/filters:format(webp):quality(75)/2023_10_8_638323794502690468_ech-xao-sa-ot-0.jpg','Món Việt',4,20,15,'Trung bình',NULL,192,22.00,10.40,6.80,0.60,4.80,2,510,0,0,'["món xào", "cay nồng", "đặc sản"]','DB',1,'APPROVED',NULL,1)
INSERT INTO `recipes` (`recipe_id`,`dish_id`,`category_id`,`title`,`slug`,`description`,`image_url`,`cuisine`,`servings`,`prep_time`,`cook_time`,`difficulty`,`occasion`,`calories`,`protein`,`carbs`,`fat`,`fiber`,`rating`,`review_count`,`views`,`is_featured`,`is_new`,`tags_json`,`source_type`,`created_by`,`status`,`rejection_reason`,`reviewed_by`) VALUES
(151,151,3,'Su su xào tỏi cà rốt thanh mát','su-su-xao-toi-ca-rot-thanh-mat','Su su non thái lát kết hợp cà rốt tỉa sợi giòn ngọt tự nhiên, xào nhanh với tỏi thơm ít dầu cho bữa cơm gia đình nhẹ nhàng.','https://cdn.tgdd.vn/2021/07/CookProduct/sthum-1200x676.jpg','Món Việt',4,12,8,'Dễ',NULL,71,1.40,8.90,3.90,2.60,4.90,3,521,0,0,'["món rau", "nhanh gọn", "eat clean"]','DB',1,'APPROVED',NULL,1),
(152,152,3,'Cải thìa xào tỏi dầu hào xanh mướt','cai-thia-xao-toi-dau-hao-xanh-muot','Ngọn cải thìa chần sơ giữ màu xanh ngọc giòn rụm, rưới sốt tỏi phi dầu hào bóng bẩy cực kỳ bắt mắt.','https://cdn.tgdd.vn/2021/04/CookRecipe/GalleryStep/thanh-pham-194.jpg','Món Việt',4,10,6,'Dễ',NULL,77,2.40,6.50,5.30,1.30,4.60,4,532,0,0,'["món rau", "xanh mướt", "nhanh gọn"]','DB',1,'APPROVED',NULL,1),
(153,153,3,'Bạch tuộc xào sa tế sả ớt','bach-tuoc-xao-sa-te-sa-ot','Râu bạch tuộc cắt miếng vừa giòn sần sật áo đều sốt sa tế đỏ au thơm mùi sả và hành tây, hấp dẫn khó cưỡng.','https://i.vietgiaitri.com/2022/2/19/cach-nau-3-mon-bach-tuoc-xao-sa-te-sa-ot-va-chua-ngot-thom-ngon-don-gian-fc9-6321076.jpg','Món Việt',4,15,10,'Dễ',NULL,217,20.20,11.20,9.80,1.30,4.70,5,543,0,0,'["hải sản", "món nhậu", "cay ngon"]','DB',1,'APPROVED',NULL,1),
(154,154,3,'Miến xào lươn giòn Nghệ An','mien-xao-luon-gion-nghe-an','Lươn chiên giòn rụm thơm hành tăm/hành tím quyện cùng sợi miến dong mềm tơi, giá đỗ và rau răm ấm bụng.','https://cdn.tgdd.vn/2021/11/CookRecipe/GalleryStep/thanh-pham-887.jpg','Món Việt',4,25,15,'Trung bình',NULL,487,21.20,53.90,20.70,5.50,4.80,6,554,0,0,'["nghệ an", "miến xào", "đặc sản"]','DB',1,'APPROVED',NULL,1),
(155,155,3,'Hến xúc bánh đa xào hành răm','hen-xuc-banh-da-xao-hanh-ram','Thịt hến tươi xào săn thơm lừng hành phi, đậu phộng rang và rau răm cay dịu, xúc cùng bánh đa nướng giòn rụm.','https://beptruong.edu.vn/wp-content/uploads/2021/01/hen-xao-chung-voi-hanh-tay-va-rau-ram.jpg','Món Việt',4,15,10,'Dễ',NULL,352,19.90,36.70,14.60,2.30,4.90,7,565,0,0,'["miền trung", "món xào", "hải sản"]','DB',1,'APPROVED',NULL,1),
(156,156,3,'Đậu hũ xào giá hẹ thịt băm','dau-hu-xao-gia-he-thit-bam','Đậu hũ trắng rán xém mềm mịn xào nhanh cùng thịt băm đậm vị, giá đỗ giòn và lá hẹ thơm lừng cho bữa tối 20 phút.','https://cdn2.fptshop.com.vn/unsafe/1240x0/filters:format(webp):quality(75)/2024_2_26_638445058941038709_canh-he-dau-hu.jpg','Món Việt',4,12,10,'Dễ',NULL,256,16.30,5.90,19.70,1.70,4.60,2,576,0,0,'["nhanh gọn", "bữa tối", "cơm gia đình"]','DB',1,'APPROVED',NULL,1),
(157,157,3,'Thịt bò xào đậu Hà Lan nấm hương','thit-bo-xao-dau-ha-lan-nam-huong','Đậu Hà Lan xanh giòn quyện nấm hương dày thịt mềm ngọt và lát bò áp chảo vừa chín tới, cân bằng đạm và chất xơ.','https://barona.vn/storage/meo-vat/64/thit-bo-xao-gi-ngon.jpg','Món Việt',4,15,10,'Dễ',NULL,317,23.70,17.50,16.60,4.50,4.70,3,587,0,0,'["eat clean", "món bò", "đủ chất"]','DB',1,'APPROVED',NULL,1),
(158,158,3,'Súp lơ xanh xào tôm tươi','sup-lo-xanh-xao-tom-tuoi','Tôm sú đỏ au giòn ngọt kết hợp bông cải xanh giòn sần sật và cà rốt bắt mắt, món xào ít béo cực hợp chế độ Eat Clean.','https://afamilycdn.com/Qalypm8xccccccccccccW2vZ1VroR/Image/2012/04/01/120429afamily-AN-suplo-xao-tom-12_51a15.jpg','Món Việt',4,15,8,'Dễ',NULL,157,18.30,11.10,5.50,3.10,4.80,4,598,0,0,'["eat clean", "tăng cơ", "hải sản"]','DB',1,'APPROVED',NULL,1),
(159,159,4,'Gà nướng lu mật ong ngũ vị','ga-nuong-lu-mat-ong-ngu-vi','Đùi gà nướng vàng ruộm da căng bóng thơm phức mật ong, ngũ vị hương và tỏi gừng, thịt bên trong vẫn mềm mọng ngọt nước.','https://cdn.tgdd.vn/2022/03/CookDish/cach-lam-ga-nuong-ngu-vi-mat-ong-gion-dai-thom-ngon-cho-ca-avt-1200x676-1.jpg','Món Việt',4,25,35,'Trung bình',NULL,455,40.80,13.20,25.70,0.70,4.90,5,609,1,0,'["món nướng", "gà nướng", "tiệc cuối tuần"]','DB',1,'APPROVED',NULL,1),
(160,160,4,'Sườn nướng BBQ ngũ vị nồi chiên','suon-nuong-bbq-ngu-vi-noi-chien','Dẻ sườn non mềm rục phủ sốt BBQ chua ngọt cay dịu quyện hương tỏi mật ong, nướng bằng nồi chiên không dầu cực gọn sạch.','https://cdn2.fptshop.com.vn/unsafe/2024_6_4_638531397582820590_cach-lam-suon-nuong-bbq-bang-noi-chien-khong-dau.jpg','Món Việt',4,25,25,'Dễ',NULL,626,37.90,17.40,44.40,0.80,4.60,6,180,1,0,'["nồi chiên không dầu", "sườn nướng", "BBQ"]','DB',1,'APPROVED',NULL,1),
(161,161,4,'Cá rô phi chiên xù giòn rụm','ca-ro-phi-chien-xu-gion-rum','Cá rô phi nguyên con khứa vảy chiên giòn tan vàng ươm cả vây đuôi, cuốn bánh tráng rau sống chấm nước mắm tỏi ớt.','https://cdn.tgdd.vn/2020/12/CookRecipe/GalleryStep/thanh-pham-1205.jpg','Món Việt',4,20,18,'Trung bình',NULL,714,47.40,54.30,34.70,2.10,4.70,7,191,0,0,'["cá chiên", "cuốn bánh tráng", "tiệc gia đình"]','DB',1,'APPROVED',NULL,1),
(162,162,4,'Tôm chiên xù giòn tan','tom-chien-xu-gion-tan','Từng con tôm sú thẳng tắp bên ngoài giòn tan xốp nhẹ, bên trong thịt tôm ngọt chắc, chấm tương cà mayonnaise trẻ em rất mê.','https://donghaifoodsaigon.com/wp-content/uploads/2025/05/tom-chien-xu.png','Món Việt',4,20,12,'Dễ',NULL,525,30.30,32.50,30.60,1.30,4.80,2,202,0,0,'["trẻ em thích", "chiên giòn", "khai vị"]','DB',1,'APPROVED',NULL,1),
(163,163,4,'Ba chỉ nướng riềng mẻ chuẩn vị','ba-chi-nuong-rieng-me-chuan-vi','Ba chỉ heo cắt lát dày vừa ướp riềng giã, mẻ chua, nghệ và chút mắm tôm nướng xém thơm nức mũi, ăn kèm rau sống bún tươi.','https://beptruong.edu.vn/wp-content/uploads/2016/06/cach-lam-thit-lon-uop-rieng-me-nuong.jpg','Món Việt',4,25,22,'Trung bình',NULL,656,26.00,7.00,58.00,0.70,4.90,3,213,0,0,'["món nướng", "bắc bộ", "bún nướng"]','DB',1,'APPROVED',NULL,1),
(164,164,4,'Cánh gà nướng sốt tiêu đen','canh-ga-nuong-sot-tieu-den','Cánh gà giữa đậm đà thơm cay mùi tiêu đen đập dập quyện vị mật ong và dầu hào bóng mượt hấp dẫn.','https://bepxua.vn/wp-content/uploads/2021/07/canh-ga.jpg','Món Việt',4,20,22,'Dễ',NULL,431,33.50,10.10,28.30,1.30,4.60,4,224,0,0,'["cánh gà", "nồi chiên không dầu", "tiệc cuối tuần"]','DB',1,'APPROVED',NULL,1),
(165,165,4,'Bạch tuộc nướng muối ớt xanh','bach-tuoc-nuong-muoi-ot-xanh','Râu bạch tuộc giòn sần sật ướp sa tế muối ớt cay nồng nướng vừa chín tới không bị khô, chấm kèm sốt muối ớt xanh Nha Trang.','https://www.nhahangquangon.com/wp-content/uploads/2014/12/bach-nuong-nuong-sa-te-cham-muoi-ot-xanh-2.jpg','Món Việt',4,20,14,'Dễ',NULL,237,23.60,12.50,10.00,0.30,4.70,5,235,0,0,'["hải sản", "món nướng", "cay nồng"]','DB',1,'APPROVED',NULL,1),
(166,166,4,'Chim cút quay bơ tỏi giòn da','chim-cut-quay-bo-toi-gion-da','Chim cút ướp ngũ vị mật ong chiên hoặc quay giòn rụm da, thơm nức hương bơ tỏi nóng hổi ăn kèm bánh mì và đồ chua.','https://www.huongnghiepaau.com/wp-content/uploads/2024/08/chim-cut-chien-bo-toi-bat-mat.jpg','Món Việt',4,25,25,'Trung bình',NULL,508,32.50,10.50,37.20,1.00,4.80,6,246,0,0,'["tiệc gia đình", "món quay", "giòn da"]','DB',1,'APPROVED',NULL,1),
(167,167,5,'Phở chay nấm hương thanh ngọt','pho-chay-nam-huong-thanh-ngot','Phở chay chuẩn vị với nước dùng ninh từ củ cải, bắp ngọt, táo và thảo quả quế hồi, ăn kèm nấm đùi gà, đậu hũ chiên và tàu hũ ky.','https://anchayhealthy.com/wp-content/uploads/2024/08/mnnhacht.jpg','Món Việt',4,25,40,'Trung bình',NULL,330,13.00,64.70,4.10,5.50,4.90,7,257,1,0,'["món chay", "thuần chay", "phở"]','DB',1,'APPROVED',NULL,1),
(168,168,5,'Bún bò Huế chay đậm đà','bun-bo-hue-chay-dam-da','Nồi bún bò Huế thuần chay dậy hương sả băm phi dầu điều, có chả lụa chay, nấm đùi gà, đậu hũ chiên và bắp chuối bào.','https://saigonesebaguette.vn/wp-content/uploads/2025/10/cach-nau-bun-ngon-tai-nha-2289b4.webp','Món Việt',4,25,35,'Trung bình',NULL,373,17.30,59.60,8.50,3.60,4.60,2,268,1,0,'["món chay", "thuần chay", "bún bò chay"]','DB',1,'APPROVED',NULL,1),
(169,169,5,'Lẩu nấm chay thập cẩm thanh ngọt','lau-nam-chay-thap-cam-thanh-ngot','Nồi lẩu nấm chay thanh khiết kết hợp táo đỏ, kỷ tử, bắp ngọt cùng nhiều loại nấm tươi, đậu hũ non và rau cải xanh giòn ngọt.','https://www.huongnghiepaau.com/wp-content/uploads/2024/06/thuong-thuc-lau-nam-thom-lung-nong-hoi.jpg','Món Việt',4,25,30,'Dễ','Ngày Rằm',273,21.70,34.90,8.20,6.90,4.70,3,279,0,0,'["món chay", "lẩu chay", "ngày rằm"]','DB',1,'APPROVED',NULL,1),
(170,170,5,'Đậu hũ non chiên xù sốt cam tươi','dau-hu-non-chien-xu-sot-cam-tuoi','Miếng đậu hũ non mềm mượt như tan bên trong lớp vỏ chiên vàng giòn rụm, áo sốt nước cam tươi chua ngọt thơm thanh.','https://cdn2.fptshop.com.vn/unsafe/1920x0/filters:quality(100)/2024_1_20_638413566767522706_cach-lam-dau-hu-non-chien-gion-ben-trong-mem-min-cuc-ky-de-lam-doi-vi-cho-bua-an.jpg','Món Việt',4,15,12,'Dễ',NULL,348,8.20,37.10,19.10,2.50,4.80,4,290,0,0,'["món chay", "thuần chay", "đậu hũ"]','DB',1,'APPROVED',NULL,1),
(171,171,5,'Canh bí đỏ hạt sen chay bổ dưỡng','canh-bi-do-hat-sen-chay-bo-duong','Bí đỏ dẻo bùi hòa quyện hạt sen tươi bùi ngọt và nấm hương trong nước canh vàng ấm thanh tịnh giúp an thần ngủ ngon.','https://cdn.hstatic.net/files/200000700229/file/canh-bi-do-chay-5.jpg','Món Việt',4,15,25,'Dễ',NULL,106,3.30,18.40,2.90,2.10,4.90,5,301,0,0,'["món chay", "thuần chay", "an thần"]','DB',1,'APPROVED',NULL,1),
(172,172,5,'Canh rong biển đậu hũ non chay','canh-rong-bien-dau-hu-non-chay','Món canh thanh mát giàu khoáng chất từ rong biển nấu cùng đậu hũ non mềm mượt, nấm kim châm và dầu mè thơm lừng.','https://cdn2.fptshop.com.vn/unsafe/1920x0/filters:format(webp):quality(75)/canh_rong_bien_tau_hu_non_1b767e2761.jpg','Món Việt',4,10,10,'Dễ',NULL,79,5.10,6.60,4.20,1.60,4.60,6,312,0,0,'["món chay", "thuần chay", "eat clean"]','DB',1,'APPROVED',NULL,1),
(173,173,5,'Chả lụa chay kho tiêu xanh','cha-lua-chay-kho-tieu-xanh','Từng lát chả lụa chay dai ngọt thấm đẫm sốt nước tương caramel thơm lừng tiêu xanh cay nồng và nước dừa thanh dịu.','https://storage.googleapis.com/onelife-public/blog.onelife.vn/2021/11/cach-lam-cha-lua-chay-kho-tieu-xanh-mon-chay-801719610189.jpg','Món Việt',4,10,18,'Dễ',NULL,212,13.20,16.80,10.70,2.50,4.70,7,323,0,0,'["món chay", "món kho", "nhanh gọn"]','DB',1,'APPROVED',NULL,1),
(174,174,5,'Nấm đùi gà nướng sả ớt chay','nam-dui-ga-nuong-sa-ot-chay','Nấm đùi gà khứa caro xé miếng dày mọng nước ướp sốt sả ớt dầu hào chay nướng xém thơm nức chẳng kém món nướng ngoài hàng.','https://cdn.tgdd.vn/2023/11/CookDish/tong-hop-cac-mon-chay-tu-nam-dui-ga-thom-ngon-hap-dan-cuc-hao-avt-1200x676.jpg','Món Việt',4,20,18,'Dễ',NULL,139,5.40,15.20,7.40,3.10,4.80,2,334,1,0,'["món chay", "thuần chay", "món nướng"]','DB',1,'APPROVED',NULL,1),
(175,175,5,'Miến xào thập cẩm chay giòn ngon','mien-xao-thap-cam-chay-gion-ngon','Sợi miến dong dai tơi không dính chùm xào cùng đậu hũ chiên sợi, nấm hương, cà rốt, bông cải và boaro thơm dịu.','https://cdn.tgdd.vn/Files/2021/08/27/1378221/cach-lam-mien-xao-chay-thap-cam-thom-ngon-khong-bi-dinh-202108271127168513.jpg','Món Việt',4,20,12,'Dễ','Ngày Rằm',321,6.30,56.30,8.70,5.90,4.90,3,345,0,0,'["món chay", "thuần chay", "miến xào"]','DB',1,'APPROVED',NULL,1)
INSERT INTO `recipes` (`recipe_id`,`dish_id`,`category_id`,`title`,`slug`,`description`,`image_url`,`cuisine`,`servings`,`prep_time`,`cook_time`,`difficulty`,`occasion`,`calories`,`protein`,`carbs`,`fat`,`fiber`,`rating`,`review_count`,`views`,`is_featured`,`is_new`,`tags_json`,`source_type`,`created_by`,`status`,`rejection_reason`,`reviewed_by`) VALUES
(176,176,5,'Bánh xèo chay nhân nấm đậu xanh','banh-xeo-chay-nhan-nam-dau-xanh','Vỏ bánh xèo vàng nghệ giòn rụm béo nhẹ nước cốt dừa, ôm trọn nhân đậu xanh hấp bở bùi, nấm bào ngư, cà rốt và giá đỗ.','https://bepxua.vn/wp-content/uploads/2021/07/banh-xeo.jpg','Món Việt',4,25,20,'Trung bình',NULL,417,15.90,68.40,10.40,8.40,4.60,4,356,1,0,'["món chay", "bánh xèo", "thuần chay"]','DB',1,'APPROVED',NULL,1),
(177,177,5,'Xôi vò hạt sen chay dẻo tơi','xoi-vo-hat-sen-chay-deo-toi','Hạt xôi nếp vàng ươm tơi mềm quyện áo đều lớp đậu xanh hấp tán nhuyễn và hạt sen bùi ngọt, cực hợp lễ cúng Rằm.','https://cdn2.fptshop.com.vn/unsafe/1920x0/filters:format(webp):quality(75)/2024_1_18_638412065848140954_xoi-vo-hat-sen-1.jpg','Món Việt',4,30,35,'Trung bình','Ngày Rằm',690,21.00,130.30,9.50,12.00,4.70,5,367,0,0,'["xôi", "món chay", "ngày rằm"]','DB',1,'APPROVED',NULL,1),
(178,178,5,'Gỏi xoài nấm bào ngư chay giòn mát','goi-xoai-nam-bao-ngu-chay-gion-mat','Xoài xanh bào sợi chua giòn kết hợp nấm bào ngư áp chảo xé sợi dai ngọt, rau răm và đậu phộng rang cực kỳ kích thích vị giác.','https://www.lorca.vn/wp-content/uploads/2023/06/tp1-4.jpg','Món Việt',4,15,8,'Dễ',NULL,166,6.30,25.50,6.00,4.90,4.80,6,378,0,0,'["món chay", "khai vị", "thuần chay"]','DB',1,'APPROVED',NULL,1),
(179,179,6,'Chè hạt sen long nhãn thanh mát','che-hat-sen-long-nhan-thanh-mat','Chè hạt sen bở bùi thơm dịu hương hoa bưởi/lá dứa quyện cùng nhãn nhục giòn ngọt tự nhiên giúp giải nhiệt an thần cực tốt.','https://bepmina.vn/wp-content/uploads/2021/08/che-hat-sen-long-nhankho-2048x1449.jpeg','Món Việt',4,20,25,'Dễ',NULL,221,3.60,53.50,0.40,2.20,4.90,7,389,1,0,'["chè", "thanh nhiệt", "giải nhiệt"]','DB',1,'APPROVED',NULL,1),
(180,180,6,'Chè trôi nước gừng ấm dẻo thơm','che-troi-nuoc-gung-am-deo-thom','Viên chè nếp mềm dẻo bọc nhân đậu xanh dừa bùi thơm trong nước đường gừng ấm nồng rưới nước cốt dừa béo mịn và mè rang.','https://giadinh.mediacdn.vn/296230595582509056/2025/12/14/che-troi-nuoc-6-1765700637460173618794.jpg','Món Việt',4,30,20,'Trung bình','Ngày Rằm',703,16.30,132.40,13.10,10.30,4.60,2,400,0,0,'["chè", "ngày rằm", "truyền thống"]','DB',1,'APPROVED',NULL,1),
(181,181,6,'Chè dưỡng nhan táo đỏ tuyết yến','che-duong-nhan-tao-do-tuyet-yen','Chè dưỡng nhan thanh mát hài hòa táo đỏ, kỷ tử, nhãn nhục, hạt chia và tuyết yến giòn mát rất tốt cho da và sức khỏe.','https://www.cet.edu.vn/wp-content/uploads/2019/08/che-duong-nhan-thom-ngon.jpg','Món Việt',5,30,25,'Dễ',NULL,171,2.20,41.30,1.10,4.00,4.70,3,411,0,0,'["chè", "làm đẹp", "giải nhiệt"]','DB',1,'APPROVED',NULL,1),
(182,182,6,'Tàu hũ trân châu đường đen','tau-hu-tran-chau-duong-den','Tàu hũ non làm tại nhà từ sữa đậu nành mịn tan, ăn kèm trân châu đen dai giòn thấm đẫm sốt đường đen thơm mùi lá dứa.','https://cdn.tgdd.vn/Files/2020/04/06/1247101/cach-lam-tau-hu-tran-chau-duong-den-mon-ngon-tuoi-mat-cho-ngay-he-202004061537197129.jpg','Món Việt',4,20,20,'Trung bình',NULL,327,6.60,56.20,9.20,2.00,4.80,4,422,0,0,'["tráng miệng", "tàu hũ", "giải nhiệt"]','DB',1,'APPROVED',NULL,1),
(183,183,6,'Bánh bò thốt nốt rễ tre thơm béo','banh-bo-thot-not-re-tre-thom-beo','Bánh bò thốt nốt vàng ươm thơm nức đường thốt nốt và nước cốt dừa, nở xốp nhiều rễ tre mềm dai ăn cực kỳ cuốn.','https://cdn.tgdd.vn/2021/06/CookProduct/1-1200x667.jpg','Món Việt',6,30,35,'Khó',NULL,420,6.30,69.30,13.40,2.50,4.90,5,433,0,0,'["bánh truyền thống", "miền tây", "bánh bò"]','DB',1,'APPROVED',NULL,1),
(184,184,6,'Kem chuối đậu phộng nước cốt dừa','kem-chuoi-dau-phong-nuoc-cot-dua','Món tráng miệng tuổi thơ mát lạnh với chuối sứ ngọt dẻo, nước cốt dừa béo thơm nấu bột năng, dừa bào và đậu phộng giòn tan.','https://eggyolk.vn/wp-content/uploads/2025/03/Cach-lam-kem-chuoi-dau-phong-nuoc-cot-dua.jpg','Món Việt',6,15,10,'Dễ',NULL,268,5.00,31.50,15.70,3.70,4.60,6,444,0,0,'["tráng miệng", "giải nhiệt", "tuổi thơ"]','DB',1,'APPROVED',NULL,1),
(185,185,6,'Bánh da lợn đậu xanh lá dứa','banh-da-lon-dau-xanh-la-dua','Bánh da lợn xếp lớp xen kẽ xanh mướt hương lá dứa và vàng ươm đậu xanh bùi béo, dẻo dai thơm nước cốt dừa.','https://cdn.tgdd.vn/Files/2019/03/08/1153592/cach-lam-banh-da-lon-deo-ngon-bui-bui-nhu-mua-ngoai-hang-202112031617559658.jpg','Món Việt',6,25,35,'Khó',NULL,448,6.60,80.10,12.30,5.20,4.70,7,455,0,0,'["bánh truyền thống", "lá dứa", "miền nam"]','DB',1,'APPROVED',NULL,1),
(186,186,6,'Chè khoai dẻo cốt dừa','che-khoai-deo-cot-dua','Viên khoai lang vàng, khoai môn tím dẻo dai tự nhiên hòa quyện nước cốt dừa lá dứa và chút trân châu mát ngọt.','https://cdn.tgdd.vn/2020/10/CookProduct/26-1200x676.jpg','Món Việt',4,25,20,'Dễ',NULL,452,3.00,85.60,12.10,5.50,4.80,2,466,0,0,'["chè", "khoai dẻo", "tráng miệng"]','DB',1,'APPROVED',NULL,1),
(187,187,6,'Sữa chua trân châu cốt dừa Hạ Long','sua-chua-tran-chau-cot-dua-ha-long','Sữa chua mát lạnh mịn dẻo ăn cùng trân châu trắng/đen dai giòn chan nước cốt dừa nấu ấm béo thơm tuyệt đỉnh.','https://www.huongnghiepaau.com/wp-content/uploads/2020/09/sua-chua-tran-chau-cot-dua.jpg','Món Việt',4,15,15,'Dễ',NULL,293,7.20,40.70,12.10,1.10,4.90,3,477,0,0,'["hạ long", "tráng miệng", "giải nhiệt"]','DB',1,'APPROVED',NULL,1),
(188,188,7,'Cà phê sữa đá Sài Gòn phin chuẩn','ca-phe-sua-da-sai-gon-phin-chuan','Ly cà phê phin đậm đặc nhỏ từng giọt hòa tan lớp sữa đặc ngọt béo và đá viên mát lạnh tỉnh táo buổi sáng.','https://eggyolk.vn/wp-content/uploads/2024/07/ca-phe-sua-da-1.jpg','Món Việt',4,10,5,'Dễ',NULL,81,1.70,14.90,1.80,0.20,4.60,4,488,1,0,'["đồ uống", "cà phê", "bữa sáng"]','DB',1,'APPROVED',NULL,1),
(189,189,7,'Cà phê muối Huế béo mặn hài hòa','ca-phe-muoi-hue-beo-man-hai-hoa','Lớp kem muối mịn mượt mặn dịu bồng bềnh trên nền cà phê phin đậm đà và sữa đặc tạo hương vị trứ danh cố đô Huế.','https://nld.mediacdn.vn/291774122806476800/2022/12/8/anh-1-1670513630936690813969.jpg','Món Việt',4,12,5,'Dễ',NULL,196,2.60,10.00,16.20,0.20,4.70,5,499,1,0,'["huế", "cà phê muối", "đặc sản"]','DB',1,'APPROVED',NULL,1),
(190,190,7,'Trà vải hạt chia thanh mát','tra-vai-hat-chia-thanh-mat','Trà đen ủ thanh không chát hòa quyện nước vải ngâm ngọt dịu, trái vải giòn mọng và hạt chia giàu chất xơ giải nhiệt ngày hè.','https://cdn.tgdd.vn/2022/06/CookDishThumb/tra-vai-hat-chia-thumb-620x620.jpg','Món Việt',4,15,5,'Dễ',NULL,112,1.10,25.20,1.30,2.10,4.80,6,510,0,0,'["giải nhiệt", "trà trái cây", "mùa hè"]','DB',1,'APPROVED',NULL,1),
(191,191,7,'Sinh tố dưa hấu bạc hà mát lạnh','sinh-to-dua-hau-bac-ha-mat-lanh','Dưa hấu đỏ mọng nước xay cùng lá bạc hà the mát và chút nước cốt chanh tạo ly sinh tố đỏ rực ít calo cực sảng khoái.','https://cdn2.fptshop.com.vn/unsafe/828x0/filters:format(webp):quality(75)/2023_8_13_638274846577642930_cach-lam-sinh-to-dua-hau.jpg','Món Việt',4,10,2,'Dễ',NULL,82,1.10,21.00,0.40,0.90,4.90,7,521,0,0,'["sinh tố", "eat clean", "mùa hè"]','DB',1,'APPROVED',NULL,1),
(192,192,7,'Nước ép cần tây táo xanh detox','nuoc-ep-can-tay-tao-xanh-detox','Công thức detox cân bằng vị với cần tây giòn thanh, táo xanh ngọt dịu, dưa leo và lát gừng giúp đẹp da và nhẹ bụng.','https://cdn2.fptshop.com.vn/unsafe/1920x0/filters:format(webp):quality(75)/small/Nuoc_ep_can_tay_tao_64377f15fd.jpg','Món Việt',4,10,0,'Dễ',NULL,64,1.10,16.50,0.40,3.40,4.60,2,532,0,0,'["detox", "eat clean", "nước ép"]','DB',1,'APPROVED',NULL,1),
(193,193,7,'Sữa hạt điều yến mạch thơm béo','sua-hat-dieu-yen-mach-thom-beo','Ly sữa thực vật sánh mịn tự nhiên từ hạt điều bùi béo và yến mạch cán dẹt thơm hương lá dứa, không lactose cực kỳ bổ dưỡng.','https://cdn2.fptshop.com.vn/unsafe/Uploads/images/tin-tuc/165179/Originals/sua-hat-dieu-43.jpg','Món Việt',4,20,15,'Dễ',NULL,278,8.50,31.50,14.40,3.00,4.70,3,543,0,0,'["sữa hạt", "thuần chay", "healthy"]','DB',1,'APPROVED',NULL,1),
(194,194,7,'Trà ô long kem cheese béo mặn','tra-o-long-kem-cheese-beo-man','Hương trà ô long thanh tao hậu ngọt quyện cùng lớp kem phô mai đánh bông mềm mịn mặn béo rất bắt miệng.','https://cdn.tgdd.vn/2021/09/CookDish/2-cach-lam-tra-sua-kem-cheese-kem-pho-mai-beo-ngay-cuc-don-avt-1200x676.jpg','Món Việt',4,15,5,'Dễ',NULL,273,2.90,16.90,21.90,0.20,4.80,4,554,0,0,'["trà sữa", "đồ uống", "giải nhiệt"]','DB',1,'APPROVED',NULL,1),
(195,195,8,'Gỏi bưởi tôm mực chua ngọt','goi-buoi-tom-muc-chua-ngot','Tép bưởi Năm Roi căng mọng chua ngọt hòa quyện cùng tôm sú giòn, mực luộc gừng và đậu phộng rang cực kỳ thanh mát khai tiệc.','https://cdn2.fptshop.com.vn/unsafe/goi_buoi_tom_muc_kho_9_a74f8b937d.jpg','Món Việt',4,25,10,'Trung bình',NULL,275,24.10,27.40,8.90,2.80,4.90,5,565,1,0,'["khai vị", "tiệc", "món gỏi"]','DB',1,'APPROVED',NULL,1),
(196,196,8,'Chân gà ngâm sả tắc giòn sần sật','chan-ga-ngam-sa-tac-gion-san-sat','Chân gà trắng giòn sần sật thấm trọn vị mắm đường chua ngọt thơm ngát mùi sả thái khoanh, tắc tươi và lá chanh cay nhẹ.','https://cooponline.vn/tin-tuc/wp-content/uploads/2025/12/cach-lam-chan-ga-ngam-sa-tac-gion-san-sat-chua-cay-man-ngot-4.png','Món Việt',4,25,15,'Dễ',NULL,516,37.00,32.60,25.80,0.60,4.60,6,576,1,0,'["ăn vặt", "khai vị", "chân gà"]','DB',1,'APPROVED',NULL,1),
(197,197,8,'Gỏi xoài xanh khô cá sặc trộn','goi-xoai-xanh-kho-ca-sac-tron','Vị chua giòn của xoài xanh cân bằng vị mặn thơm bùi của khô cá sặc nướng xé nhỏ, điểm xuyết hành phi đậu phộng cực bắt mồi.','https://cdn2.fptshop.com.vn/unsafe/1920x0/filters:format(webp):quality(75)/goi_xoai_kho_ca_sac_0_1_1_a3abc53c2f.jpg','Món Việt',4,15,10,'Dễ',NULL,270,22.70,26.10,9.30,3.80,4.70,7,587,0,0,'["miền tây", "món gỏi", "khai vị"]','DB',1,'APPROVED',NULL,1),
(198,198,8,'Bánh bột lọc Huế nhân tôm thịt','banh-bot-loc-hue-nhan-tom-thit','Vỏ bánh bột năng trong veo dai dẻo nhìn rõ nhân tôm rim đỏ au và thịt ba chỉ mặn ngọt chấm nước mắm ớt xanh Huế.','https://cdn.tgdd.vn/Files/2021/09/07/1380725/cach-lam-banh-bot-loc-goi-la-chuoi-dai-ngon-khong-can-khuay-202109301937549626.jpg','Món Việt',4,30,20,'Trung bình',NULL,567,18.80,71.00,23.20,1.10,4.80,2,598,0,0,'["huế", "bánh truyền thống", "khai vị"]','DB',1,'APPROVED',NULL,1),
(199,199,8,'Nem lụi Huế nướng sả thơm nức','nem-lui-hue-nuong-sa-thom-nuc','Chả giò sống trộn thịt heo bọc quanh cây sả thơm nồng nướng vàng ươm, cuốn bánh tráng rau sống chấm nước lèo đậu phộng.','https://www.lorca.vn/wp-content/uploads/2023/11/1-32.jpg','Món Việt',4,25,18,'Trung bình',NULL,515,26.40,40.40,28.70,2.70,4.90,3,609,1,0,'["huế", "cuốn bánh tráng", "khai vị"]','DB',1,'APPROVED',NULL,1),
(200,200,8,'Súp hoành thánh tôm thịt thanh nhẹ','sup-hoanh-thanh-tom-thit-thanh-nhe','Viên hoành thánh gói khéo ôm trọn nhân tôm băm thịt nạc giòn ngọt trong bát nước dùng thơm hành phi dầu mè ấm áp.','https://cdn.tgdd.vn/2021/05/CookRecipe/GalleryStep/tron-va-uop-tom-thit-2.jpg','Món Việt',4,25,18,'Trung bình',NULL,406,30.90,33.70,16.00,1.90,4.60,4,180,0,0,'["khai vị", "súp", "dễ ăn"]','DB',1,'APPROVED',NULL,1)
