(201,201,2,'Bún thang Hà Nội tinh hoa phố cổ','bun-thang-ha-noi-tinh-hoa-pho-co','Tuyệt phẩm bún nước Hà Thành thanh tao với sợi trứng tráng mỏng tang, ức gà xé phay, giò lụa thái chỉ trên nền nước dùng gà tôm khô trong vắt ngọt dịu.','https://afamilycdn.com/150157425591193600/2023/4/25/maxresdefault-2-10082224-1682395777333-16823957776251461769451.jpg','Món Việt',4,30,55,'Khó','Tết cổ truyền',490,49.60,44.60,11.60,2.10,4.70,8,493,1,1,'["hà nội", "bún thang", "miền bắc", "Hà Nội & ĐB Sông Hồng"]','DB',1,'APPROVED',NULL,1),
(202,202,8,'Phở cuốn thịt bò ngũ sắc Ngũ Xã','pho-cuon-thit-bo-ngu-sac-ngu-xa','Bánh phở bản to mềm mướt ôm trọn thịt bò xào tỏi lửa lớn, cà rốt, dưa leo và rau thơm tươi mát chấm nước mắm chua ngọt chuẩn vị hồ Trúc Bạch.','https://cdn.tgdd.vn/Files/2017/04/15/972358/cach-lam-pho-cuon-ngu-xa-sieu-ngon-9_760x570.jpg','Món Việt',4,20,15,'Dễ',NULL,365,24.60,39.10,11.80,1.90,4.80,9,506,0,1,'["hà nội", "phở cuốn", "ngũ xã", "khai vị", "Hà Nội & ĐB Sông Hồng"]','DB',1,'APPROVED',NULL,1),
(203,203,1,'Ốc om chuối đậu tía tô Hà Nội','oc-om-chuoi-dau-tia-to-ha-noi','Ốc bươu giòn sật om cùng chuối xanh bùi dẻo, đậu phụ rán vàng, thịt ba chỉ béo ngậy trên nền mẻ nghệ vàng ươm dậy hương tía tô lá lốt.','https://cdn2.fptshop.com.vn/unsafe/Uploads/images/tin-tuc/163435/Originals/oc-om-chuoi-dau_hinh-5.jpeg','Món Việt',4,25,30,'Trung bình',NULL,381,26.20,30.80,17.10,3.40,4.90,3,519,1,1,'["hà nội", "ốc chuối đậu", "miền bắc", "Hà Nội & ĐB Sông Hồng"]','DB',1,'APPROVED',NULL,1),
(204,204,2,'Bánh đa cua đồng Hải Phòng chuẩn vị','banh-da-cua-dong-hai-phong-chuan-vi','Sợi bánh đa đỏ dai mềm đất Cảng hòa quyện riêu cua đồng béo thơm, chả lá lốt, tôm tươi và rau muống chần giòn xanh.','https://cdn.hstatic.net/200000700229/file/cach-lam-banh-da-cua-04_d19d7aba5b18432189f1cf63119011a7.jpg','Món Việt',4,25,35,'Trung bình',NULL,604,34.70,84.80,14.10,3.90,4.70,4,532,1,1,'["hải phòng", "bánh đa cua", "miền bắc", "Hà Nội & ĐB Sông Hồng"]','DB',1,'APPROVED',NULL,1),
(205,205,4,'Nem cua bể vuông Hải Phòng chiên giòn','nem-cua-be-vuong-hai-phong-chien-gion','Chiếc nem gói vuông vức căng tròn nhân thịt cua bể tươi ngọt, tôm sú, thịt nạc vai, miến dong và mộc nhĩ, chiên hai lửa vàng giòn rụm.','https://bepxua.vn/wp-content/uploads/2021/05/26-3318.jpeg','Món Việt',4,30,20,'Trung bình','Tiệc gia đình & Cuối tuần',856,29.40,85.20,44.40,4.60,4.80,5,545,0,1,'["hải phòng", "nem cua bể", "nem rán", "Hà Nội & ĐB Sông Hồng"]','DB',1,'APPROVED',NULL,1),
(206,206,1,'Cá trắm kho riềng làng Vũ Đại Hà Nam','ca-tram-kho-rieng-lang-vu-dai-ha-nam','Khúc cá trắm đen chắc thịt kho rục xương cùng riềng giã, gừng, thịt ba chỉ, nước cốt cua/nước dừa và nước hàng sánh nâu đậm vị cổ truyền.','https://cdn.tgdd.vn/2021/09/CookDish/cach-kho-ca-tram-den-dung-vi-lang-vu-dai-cuc-dam-da-va-don-avt-1200x676.jpg','Món Việt',4,25,90,'Khó','Tết cổ truyền',540,47.80,16.10,30.80,1.80,4.90,6,558,1,1,'["hà nam", "cá kho vũ đại", "cá trắm kho", "Hà Nội & ĐB Sông Hồng"]','DB',1,'APPROVED',NULL,1),
(207,207,2,'Phở bò tái lăn Hà Nội dậy mùi tỏi','pho-bo-tai-lan-ha-noi-day-mui-toi','Thịt thăn bò ướp gừng tỏi áp chảo lửa lớn xém thơm trút thẳng lên bát bánh phở nóng hổi, chan nước dùng xương bò hoa hồi quế nướng đậm đà.','https://lh7-us.googleusercontent.com/WuLKMWMNqXBrD8PnJpoWyRJuxNv1R0jiX8m46TWFjx-A834BDWhUHnkHmzT5RRTXG9GndOR-I4MQEnzUJBWm3IfEeZnaOiSOll0EJ6S4gaGOTC3F4sn_AnIg74Iho7KFeFs49Cr5_aB_hC7wdymTMok','Món Việt',4,25,65,'Trung bình',NULL,564,38.90,44.90,24.60,1.60,4.70,7,571,1,1,'["hà nội", "phở tái lăn", "phở bò", "Hà Nội & ĐB Sông Hồng"]','DB',1,'APPROVED',NULL,1),
(208,208,4,'Chả mực giã tay Hạ Long Quảng Ninh','cha-muc-gia-tay-ha-long-quang-ninh','Mực ống tươi dày mình giã cối thủ công giữ nguyên hạt mực sần sật, quết cùng chút mỡ phần và tiêu sọ, chiên phồng vàng ươm thơm nức.','https://phucfood.vn/wp-content/uploads/2023/04/cha-muc-90.jpg','Món Việt',4,30,20,'Trung bình',NULL,464,30.60,8.10,34.10,0.60,4.80,8,584,0,1,'["quảng ninh", "chả mực hạ long", "hải sản", "Hà Nội & ĐB Sông Hồng"]','DB',1,'APPROVED',NULL,1),
(209,209,2,'Bún cá cay Hải Phòng dọc mùng giòn ngọt','bun-ca-cay-hai-phong-doc-mung-gion-ngot','Cá trắm chiên vàng giòn bên ngoài mềm ngọt bên trong cùng chả cá biển, dọc mùng bóp muối giòn sần sật trong làn nước dùng chua cay thanh thoát.','https://cdn2.fptshop.com.vn/unsafe/Uploads/images/tin-tuc/180931/Originals/bun-ca-cay-1.jpg','Món Việt',4,25,35,'Trung bình',NULL,423,32.70,47.80,11.30,2.60,4.90,9,597,0,1,'["hải phòng", "bún cá cay", "miền bắc", "Hà Nội & ĐB Sông Hồng"]','DB',1,'APPROVED',NULL,1),
(210,210,1,'Xôi xéo đậu xanh hành phi mỡ gà Hà Nội','xoi-xeo-dau-xanh-hanh-phi-mo-ga-ha-noi','Hạt nếp cái hoa vàng ngâm nghệ căng bóng dẻo thơm, phủ đậu xanh đồ chín nắm chặt thái lát mỏng mịn, rưới mỡ gà óng ả và hành phi giòn tan.','https://cdn-www.vinid.net/2020/04/66f7693d-cach-lam-xoi-xeo.jpg','Món Việt',4,35,35,'Trung bình',NULL,687,20.70,127.60,10.00,12.10,4.70,3,610,0,1,'["hà nội", "xôi xéo", "ăn sáng", "Hà Nội & ĐB Sông Hồng"]','DB',1,'APPROVED',NULL,1),
(211,211,8,'Bánh đúc nóng thịt băm mộc nhĩ Hà Nội','banh-duc-nong-thit-bam-moc-nhi-ha-noi','Bát bánh đúc bột gạo tẻ sánh dẻo nóng hổi, xúc kèm nhân thịt heo xay xào mộc nhĩ giòn sật, hành phi, rau mùi và nước mắm chua ngọt ấm bụng.','https://cookbeo.com/media/2023/10/banh-duc-nong/mon-banh-duc-nong-3.jpg','Món Việt',4,15,25,'Dễ',NULL,401,12.90,57.60,12.80,5.80,4.80,4,623,0,1,'["hà nội", "bánh đúc nóng", "quà chiều", "Hà Nội & ĐB Sông Hồng"]','DB',1,'APPROVED',NULL,1),
(212,212,4,'Bánh tôm Hồ Tây khoai lang giòn rụm','banh-tom-ho-tay-khoai-lang-gion-rum','Khoai lang thái sợi quyện bột chiên giòn vàng rực nâng đỡ con tôm đất tươi đỏ au trên mặt, ăn kèm xà lách rau thơm và nước chấm đu đủ xanh.','https://www.huongnghiepaau.com/wp-content/uploads/2019/10/banh-tom-ho-tay-hap-dan.jpg','Món Việt',4,20,20,'Dễ',NULL,694,23.20,60.00,40.60,4.40,4.90,5,636,0,1,'["hà nội", "bánh tôm hồ tây", "chiên giòn", "Hà Nội & ĐB Sông Hồng"]','DB',1,'APPROVED',NULL,1),
(213,213,7,'Cà phê trứng phố cổ Hà Nội béo mịn','ca-phe-trung-pho-co-ha-noi-beo-min','Lớp kem lòng đỏ trứng gà đánh bông mịn màng thơm mùi mật ong vani không hề tanh, bồng bềnh trên nền cà phê phin đậm đặc nóng hổi.','https://toplist.vn/images/800px/ca-phe-trung-440695.jpg','Món Việt',2,10,10,'Dễ',NULL,312,14.90,33.60,12.50,5.00,4.70,6,649,1,1,'["hà nội", "cà phê trứng", "đồ uống", "Hà Nội & ĐB Sông Hồng"]','DB',1,'APPROVED',NULL,1),
(214,214,7,'Nước sấu ngâm gừng đá Hà Nội giải nhiệt','nuoc-sau-ngam-gung-da-ha-noi-giai-nhiet','Quả sấu xanh cạo vỏ khía xoắn ốc ngâm nước đường phèn gừng tươi giòn chua thanh mát, giải nhiệt tức thì những trưa hè oi ả.','https://www.bartender.edu.vn/wp-content/uploads/2020/07/cach-bao-quan-sau.jpg','Món Việt',4,15,20,'Dễ',NULL,314,0.90,80.10,0.20,2.40,4.80,7,662,0,1,'["hà nội", "nước sấu", "giải nhiệt", "Hà Nội & ĐB Sông Hồng"]','DB',1,'APPROVED',NULL,1),
(215,215,6,'Chè cốm lá dứa làng Vòng thanh tao','che-com-la-dua-lang-vong-thanh-tao','Hạt cốm tươi xanh ngọc làng Vòng nở mềm quyện trong làn chè bột năng sánh trong thơm dịu lá dứa và nước cốt dừa béo thanh.','https://cdn2.fptshop.com.vn/unsafe/1920x0/filters:format(webp):quality(75)/che_buoi_com_la_dua_54685ce112.png','Món Việt',4,10,15,'Dễ',NULL,319,3.00,58.40,9.10,2.20,4.90,8,675,0,1,'["hà nội", "chè cốm", "mùa thu", "Hà Nội & ĐB Sông Hồng"]','DB',1,'APPROVED',NULL,1),
(216,216,6,'Tào phớ nước đường hoa nhài Hà Nội','tao-pho-nuoc-duong-hoa-nhai-ha-noi','Từng lát tào phớ trắng ngần mịn mướt như lụa hớt mỏng vào bát nước đường phèn ướp hoa nhài thơm ngát cùng trân châu trắng và thạch mát lành.','https://tauhutuoinamviet.com/wp-content/uploads/2024/01/nau-nuoc-duong-an-kem-voi-tao-pho.jpg','Món Việt',4,15,20,'Dễ',NULL,210,7.50,36.60,4.30,0.60,4.70,9,688,0,1,'["hà nội", "tào phớ", "tàu hũ nước đường", "Hà Nội & ĐB Sông Hồng"]','DB',1,'APPROVED',NULL,1),
(217,217,3,'Thịt trâu gác bếp xào măng chua Tây Bắc','thit-trau-gac-bep-xao-mang-chua-tay-bac','Thịt trâu gác bếp hấp mềm xé sợi xào lửa lớn cùng măng chua rừng giòn sật, dậy hương khói bếp hòa quyện hạt mắc khén và tỏi ớt vùng cao.','https://afamilycdn.com/150157425591193600/2022/7/25/thit-trau-gac-bep-son-la-4-16587060594302059937049.jpg','Món Việt',4,20,15,'Dễ',NULL,274,32.30,10.30,11.10,2.70,4.80,3,701,0,1,'["tây bắc", "trâu gác bếp", "măng chua", "Tây Bắc & Đông Bắc"]','DB',1,'APPROVED',NULL,1),
(218,218,4,'Cá chép nướng Pa Pỉnh Tộp mắc khén Sơn La','ca-chep-nuong-pa-pinh-top-mac-khen-son-la','Cá chép tươi mổ đằng lưng gập đôi nhồi đẫm sả, gừng, rau thơm, hạt dổi và mắc khén của người Thái vùng Tây Bắc, nướng than hồng thơm lừng.','https://cdn.tgdd.vn/2021/03/CookRecipe/GalleryStep/thanh-pham-1395.jpg','Món Việt',4,25,35,'Trung bình',NULL,317,41.10,6.50,13.10,1.10,4.90,4,714,1,1,'["sơn la", "pa pỉnh tộp", "tây bắc", "cá nướng", "Tây Bắc & Đông Bắc"]','DB',1,'APPROVED',NULL,1),
(219,219,4,'Thịt ba chỉ nướng lá mắc mật Lạng Sơn','thit-ba-chi-nuong-la-mac-mat-lang-son','Thịt ba chỉ thái con chì ướp mật ong ngũ vị kẹp xen kẽ lá mắc mật tươi xứ Lạng, nướng xém cạnh thơm nức tinh dầu rừng núi.','https://media.tripmap.vn/marketplace/recipes/2026/03/thit-ba-chi-nuong-la-mac-mat-featured-1773509122-0-z42h-full.webp','Món Việt',4,20,25,'Dễ',NULL,628,25.60,9.00,54.20,0.80,4.70,5,727,0,1,'["lạng sơn", "lá mắc mật", "thịt nướng", "Tây Bắc & Đông Bắc"]','DB',1,'APPROVED',NULL,1),
(220,220,1,'Khâu nhục Lạng Sơn khoai môn mềm rục','khau-nhuc-lang-son-khoai-mon-mem-ruc','Đặc sản cỗ tiệc xứ Lạng với miếng ba chỉ quay phồng bì hấp cách thủy hàng giờ úp trên khoai môn bùi dẻo, thấm đẫm sốt mộc nhĩ ngũ vị béo mềm tan ngay đầu lưỡi.','https://cdn2.fptshop.com.vn/unsafe/800x0/cach_lam_mon_khau_nhuc_lang_son_9_4f81a963a5.png','Món Việt',4,35,95,'Khó','Tết cổ truyền',837,32.10,35.00,63.50,8.50,4.80,6,740,1,1,'["lạng sơn", "khâu nhục", "đông bắc", "Tây Bắc & Đông Bắc"]','DB',1,'APPROVED',NULL,1),
(221,221,1,'Phở chua Lạng Sơn trộn sốt khoai lang giòn','pho-chua-lang-son-tron-sot-khoai-lang-gion','Bánh phở dai mát trộn nước sốt me đường sánh hồng, phủ thịt xá xíu, lạp xưởng, đậu phộng rang và khoai lang thái sợi chiên giòn rụm.','https://cdn.tgdd.vn/Files/2020/04/29/1252697/cach-lam-pho-chua-lang-son-thom-ngon-don-gian-ngay-tai-nha-2.jpg','Món Việt',4,25,25,'Trung bình',NULL,552,23.70,59.20,25.00,3.30,4.90,7,753,0,1,'["lạng sơn", "phở chua", "phở trộn", "Tây Bắc & Đông Bắc"]','DB',1,'APPROVED',NULL,1),
(222,222,4,'Vịt quay lá mắc mật Cao Bằng da giòn','vit-quay-la-mac-mat-cao-bang-da-gion','Vịt cỏ khâu kín bụng nhồi lá mắc mật, sả, gừng và sốt tương đặc trưng vùng Đông Bắc, tắm mật ong mạch nha trước khi quay da giòn bóng.','https://cdn2.fptshop.com.vn/unsafe/cach_lam_vit_nuong_la_mac_mat_bang_noi_chien_khong_dau_fd336cedc1.jpg','Món Việt',4,30,50,'Khó','Tiệc gia đình & Cuối tuần',764,58.40,12.20,51.90,0.90,4.70,8,766,0,1,'["cao bằng", "vịt quay mắc mật", "đông bắc", "Tây Bắc & Đông Bắc"]','DB',1,'APPROVED',NULL,1),
(223,223,4,'Gà bản nướng hạt dổi mắc khén Hòa Bình','ga-ban-nuong-hat-doi-mac-khen-hoa-binh','Đùi và mình gà thả đồi da mỏng thịt săn chắc ướp hạt dổi nướng, mắc khén và sả ớt Tây Bắc, nướng vàng óng chấm chẩm chéo thơm tê đầu lưỡi.','https://cdn.tgdd.vn/2022/08/CookDish/cach-lam-ga-nuong-mac-khen-chuan-vi-tay-bac-thom-ngon-de-lam-avt-1200x676.jpg','Món Việt',4,20,40,'Trung bình',NULL,391,40.00,8.70,20.80,0.80,4.80,9,779,0,1,'["hòa bình", "gà nướng mắc khén", "tây bắc", "Tây Bắc & Đông Bắc"]','DB',1,'APPROVED',NULL,1),
(224,224,5,'Xôi ngũ sắc Tây Bắc đồ lá cẩm nghệ gấc','xoi-ngu-sac-tay-bac-do-la-cam-nghe-gac','Mâm xôi chay rực rỡ 5 sắc màu tự nhiên từ lá cẩm tím, gấc đỏ, nghệ vàng, lá dứa xanh và nếp nương trắng ngần dẻo thơm thuần thực vật.','https://thittraugacbep.com.vn/wp-content/uploads/2025/08/xoi-ngu-sac-2.jpg','Món Việt',4,40,40,'Trung bình','Rằm & Lễ Vu Lan',683,13.50,130.50,11.10,6.80,4.90,3,792,0,1,'["tây bắc", "xôi ngũ sắc", "món chay", "Tây Bắc & Đông Bắc"]','DB',1,'APPROVED',NULL,1),
(225,225,3,'Măng trúc Yên Tử xào thịt bò tỏi thơm','mang-truc-yen-tu-xao-thit-bo-toi-thom','Búp măng trúc non mảnh giòn ngọt đặc sản vùng núi Yên Tử xào lửa lớn cùng thịt bò mềm mọng, dậy mùi tỏi đập dập và rau răm.','https://imagevietnam.vnanet.vn/Upload/2020/4/29/29042020104328543-3_resize.JPG','Món Việt',4,15,12,'Dễ',NULL,241,19.50,7.90,14.70,2.70,4.70,4,220,0,1,'["quảng ninh", "măng trúc yên tử", "bò xào", "Tây Bắc & Đông Bắc"]','DB',1,'APPROVED',NULL,1)
