INSERT INTO `recipe_steps` (`recipe_id`,`step_order`,`title`,`instruction`,`duration_mins`,`tip_note`) VALUES
(1,1,'Sơ chế & chần sạch nguyên liệu xương thịt, hải sản','Rửa sạch 400g thịt bò (thăn hoặc nạm) và 500g bánh phở tươi với muối hạt rồi chần nhanh trong nồi nước sôi có đập dập 1 nhánh gừng trong 2–3 phút trên lửa lớn để loại bỏ hoàn toàn bọt bẩn. Rửa lại dưới làn nước sạch cho thật trắng trẻo, đồng thời nhặt rửa sạch 150g hành tây để ráo nước. Rửa sạch xương và thịt bò, chần qua nước sôi cùng chút muối và gừng đập dập để khử mùi hôi.',21,'Bước chần sơ và rửa lại bằng nước ấm là bí quyết vàng giúp nồi nước dùng trong vắt, thơm thanh và không bao giờ bị đục hay hôi.'),
(1,2,'Nướng thơm thảo mộc & ninh nền nước dùng ngọt thanh','Cho phần nguyên liệu tạo ngọt từ 400g thịt bò (thăn hoặc nạm) và 500g bánh phở tươi cùng 40g gừng tươi nướng thơm đã nướng xém thơm vào nồi sâu lòng với khoảng 1.5–1.8 lít nước lọc. Đun sôi bùng trên lửa lớn rồi hạ ngay về lửa nhỏ liu riu, mở hé vung và hớt kỹ bọt nổi trên mặt để chiết xuất vị ngọt tự nhiên. Nướng thơm gừng, hành tây và các loại quả hoa hồi, thảo quả, quế thanh; sau đó cạo sạch lớp cháy đen bên ngoài.',48,'Luôn duy trì mặt nước lăn tăn nhẹ thay vì đun sôi sùng sục lửa to để protein không bị nhũ hóa gây đục nước lèo.'),
(1,3,'Xào tạo màu & dậy hương đặc trưng vùng miền','Bắc chảo nhỏ lên bếp với 15ml dầu ăn trên lửa vừa, phi thơm phần hành tỏi sả băm còn lại rồi xào săn 150g hành tây cùng 30ml nước mắm ngon, 15g đường phèn và 5g tiêu sọ xay trong 3–4 phút. Khi hỗn hợp dậy mùi thơm nồng nàn và lên sắc màu óng ả đặc trưng của món Phở bò Hà Nội truyền thống thì tắt bếp.',18,'Xào riêng phần nguyên liệu tạo màu và gia vị thơm trước khi trút vào nồi nước dùng giúp tầng hương dậy lên rõ nét gấp đôi.'),
(1,4,'Sơ chế & cắt thái phần nhân topping xếp tô','Vớt phần thịt hoặc hải sản chín tới từ 400g thịt bò (thăn hoặc nạm) và 500g bánh phở tươi ra ngâm ngay vào âu nước đun sôi để nguội giúp bề mặt săn giòn mọng nước, không bị thâm khô. Thái lát mỏng đều tay dày khoảng 3mm ngang thớ hoặc gỡ miếng vừa ăn, sắp riêng từng phần gọn gàng trên đĩa.',18,'Thái thịt ngang thớ với lưỡi dao thật sắc giúp lát thịt mềm mướt, khi chan nước dùng sôi lên sẽ phẳng đẹp không bị quăn cứng.'),
(1,5,'Hợp nhất nồi nước lèo & nêm chuẩn định lượng','Trút phần sốt màu thơm vào nồi nước dùng đang sôi lăn tăn, nêm chính xác lượng 30ml nước mắm ngon, 15g đường phèn và 5g tiêu sọ xay còn lại cho vừa miệng 4 người ăn. Đun nhẹ thêm 5 phút ở lửa vừa để các tầng vị mặn dịu, ngọt hậu từ xương thịt và thảo mộc hòa quyện tròn trịa. Cho xương vào nồi lớn cùng 2.5 lít nước, thả gừng và hành nướng vào hầm lửa nhỏ liu riu trong 2-3 tiếng, vớt bọt liên tục để nước trong.',18,'Nên nêm nước mắm ngon ở giai đoạn cuối trên lửa nhỏ để giữ trọn hậu vị ngọt đạm và hương thơm mà không làm nước dùng bị chua.'),
(1,6,'Chần nóng sợi bánh/bún & chuẩn bị rau ăn kèm','Đun sôi một nồi nước riêng, cho phần sợi bún/phở/bánh trong 400g thịt bò (thăn hoặc nạm) và 500g bánh phở tươi vào trụng nhanh 15–25 giây cho sợi mềm dẻo nóng hổi rồi vẩy thật ráo nước, chia đều vào 4 tô lớn. Chần sơ thêm rau ăn kèm (150g hành tây) nếu muốn dùng chín giòn.',15,'Trụng bún bánh ở nồi nước sôi riêng biệt giúp nước dùng chính không bị nhiễm tinh bột chua và tô bún luôn ráo sợi, thấm vị.'),
(1,7,'Xếp nhân hài hòa, chan nước dùng sôi & thưởng thức','Xếp đều các phần nhân thịt, hải sản lên mặt tô bún bánh, điểm xuyết 50g hành lá và rau mùi lên trên cùng. Dùng muôi múc nước dùng đang sôi thật già chan ngập xăm xắp mặt nguyên liệu để làm chín thơm hành ngò, dọn nóng ngay kèm chanh ớt tươi. Nêm nước mắm, đường phèn và muối cho vừa khẩu vị đậm đà thanh ngọt đặc trưng của nước dùng phở.',12,'Tráng nóng tô sứ bằng nước sôi trước khi xếp bún giúp tô món nước giữ nhiệt bốc khói nghi ngút suốt bữa ăn.'),
(2,1,'Sơ chế & chần sạch nguyên liệu xương thịt, hải sản','Rửa sạch 350g thịt ba chỉ rút sườn và 350g thịt nạc vai băm với muối hạt rồi chần nhanh trong nồi nước sôi có đập dập 1 nhánh gừng trong 2–3 phút trên lửa lớn để loại bỏ hoàn toàn bọt bẩn. Rửa lại dưới làn nước sạch cho thật trắng trẻo, đồng thời nhặt rửa sạch hành ngò và tiêu xay để ráo nước. Thịt ba chỉ thái lát mỏng vừa ăn. Thịt vai băm nhỏ để làm chả viên.',11,'Bước chần sơ và rửa lại bằng nước ấm là bí quyết vàng giúp nồi nước dùng trong vắt, thơm thanh và không bao giờ bị đục hay hôi.'),
(2,2,'Nướng thơm thảo mộc & ninh nền nước dùng ngọt thanh','Cho phần nguyên liệu tạo ngọt từ 350g thịt ba chỉ rút sườn và 350g thịt nạc vai băm cùng 20g tỏi băm nhuyễn đã nướng xém thơm vào nồi sâu lòng với khoảng 1.5–1.8 lít nước lọc. Đun sôi bùng trên lửa lớn rồi hạ ngay về lửa nhỏ liu riu, mở hé vung và hớt kỹ bọt nổi trên mặt để chiết xuất vị ngọt tự nhiên. Ướp riêng hai phần thịt với hành khô băm, tỏi băm, nước mắm ngon, hạt nêm, tiêu và nước hàng thắng màu trong ít nhất 45 phút.',23,'Luôn duy trì mặt nước lăn tăn nhẹ thay vì đun sôi sùng sục lửa to để protein không bị nhũ hóa gây đục nước lèo.'),
(2,3,'Xào tạo màu & dậy hương đặc trưng vùng miền','Bắc chảo nhỏ lên bếp với 15ml dầu ăn trên lửa vừa, phi thơm phần hành tỏi sả băm còn lại rồi xào săn 600g bún tươi sợi nhỏ và 100g cà rốt làm dưa góp cùng 10g ớt sừng băm, 50ml nước mắm truyền thống và 30g đường caramel thắng màu trong 3–4 phút. Khi hỗn hợp dậy mùi thơm nồng nàn và lên sắc màu óng ả đặc trưng của món Bún chả Hà Nội nướng than hoa thì tắt bếp.',9,'Xào riêng phần nguyên liệu tạo màu và gia vị thơm trước khi trút vào nồi nước dùng giúp tầng hương dậy lên rõ nét gấp đôi.'),
(2,4,'Sơ chế & cắt thái phần nhân topping xếp tô','Vớt phần thịt hoặc hải sản chín tới từ 350g thịt ba chỉ rút sườn và 350g thịt nạc vai băm ra ngâm ngay vào âu nước đun sôi để nguội giúp bề mặt săn giòn mọng nước, không bị thâm khô. Thái lát mỏng đều tay dày khoảng 3mm ngang thớ hoặc gỡ miếng vừa ăn, sắp riêng từng phần gọn gàng trên đĩa.',9,'Thái thịt ngang thớ với lưỡi dao thật sắc giúp lát thịt mềm mướt, khi chan nước dùng sôi lên sẽ phẳng đẹp không bị quăn cứng.'),
(2,5,'Hợp nhất nồi nước lèo & nêm chuẩn định lượng','Trút phần sốt màu thơm vào nồi nước dùng đang sôi lăn tăn, nêm chính xác lượng 10g ớt sừng băm, 50ml nước mắm truyền thống và 30g đường caramel thắng màu còn lại cho vừa miệng 4 người ăn. Đun nhẹ thêm 5 phút ở lửa vừa để các tầng vị mặn dịu, ngọt hậu từ xương thịt và thảo mộc hòa quyện tròn trịa. Viên thịt băm thành từng viên tròn dẹt, kẹp chả miếng vào vỉ nướng trên than hoa đỏ rực cho xém vàng thơm lừng hai mặt.',9,'Nên nêm nước mắm ngon ở giai đoạn cuối trên lửa nhỏ để giữ trọn hậu vị ngọt đạm và hương thơm mà không làm nước dùng bị chua.'),
(2,6,'Chần nóng sợi bánh/bún & chuẩn bị rau ăn kèm','Đun sôi một nồi nước riêng, cho phần sợi bún/phở/bánh trong 350g thịt ba chỉ rút sườn và 350g thịt nạc vai băm vào trụng nhanh 15–25 giây cho sợi mềm dẻo nóng hổi rồi vẩy thật ráo nước, chia đều vào 4 tô lớn. Chần sơ thêm rau ăn kèm (giá đỗ, rau xanh) nếu muốn dùng chín giòn.',8,'Trụng bún bánh ở nồi nước sôi riêng biệt giúp nước dùng chính không bị nhiễm tinh bột chua và tô bún luôn ráo sợi, thấm vị.'),
(2,7,'Xếp nhân hài hòa, chan nước dùng sôi & thưởng thức','Xếp đều các phần nhân thịt, hải sản lên mặt tô bún bánh, điểm xuyết hành ngò và tiêu xay lên trên cùng. Dùng muôi múc nước dùng đang sôi thật già chan ngập xăm xắp mặt nguyên liệu để làm chín thơm hành ngò, dọn nóng ngay kèm chanh ớt tươi. Pha nước mắm chấm theo tỷ lệ 1 mắm : 1 đường : 1 giấm : 5 nước ấm, thêm tỏi ớt băm và dưa góp cà rốt đu đủ giòn sần sật.',6,'Tráng nóng tô sứ bằng nước sôi trước khi xếp bún giúp tô món nước giữ nhiệt bốc khói nghi ngút suốt bữa ăn.'),
(3,1,'Sơ chế sạch & thấm thật khô bề mặt nguyên liệu','Rửa sạch 350g sườn cốt lết heo và 200g gạo tấm thơm cùng chút muối loãng để khử mùi tự nhiên, sau đó dùng khăn giấy bếp thấm thật khô ráo hoàn toàn bề mặt. Khứa nhẹ các đường chéo hoặc cắt miếng vừa ăn dày 2–3cm để nhiệt và gia vị thấm sâu đều khắp bên trong. Dùng sống dao dần mềm miếng sườn cốt lết để thịt mềm xốp và nhanh ngấm gia vị.',8,'Bề mặt nguyên liệu càng khô ráo thì khi chiên không bị văng dầu và khi nướng sẽ lên màu vàng ruộm giòn rụm cực đẹp.'),
(3,2,'Chuẩn bị hỗn hợp sốt ướp / bột áo chuẩn tỷ lệ','Phối trộn 30g sả băm thơm và 15g tỏi băm nhuyễn băm thật nhuyễn (hoặc vắt lấy nước cốt thơm) cùng 25ml nước mắm kẹo và 20g mật ong nguyên chất trong tô lớn cho quyện sánh đồng nhất. Nếu món có lớp vỏ bột hoặc bánh cuốn từ 350g sườn cốt lết heo và 200g gạo tấm thơm, trộn đều hỗn hợp theo đúng định lượng để đạt độ giòn xốp mỏng nhẹ chuẩn vị. Ướp sườn với sả băm, tỏi, mật ong, nước mắm, xì dầu, dầu hào và chút sữa đặc trong 1-2 tiếng.',8,'Vắt lấy nước cốt hành tỏi sả khi ướp đồ nướng giúp hương thơm thấm sâu mà không bị cháy đen phần xác băm trên lửa cao.'),
(3,3,'Ướp thấm thớ thịt / tạo hình cuốn khéo léo','Áo đều hỗn hợp gia vị hoặc lớp bột/vỏ cuốn quanh 350g sườn cốt lết heo và 200g gạo tấm thơm, massage nhẹ nhàng rồi để nghỉ 15–20 phút cho gia vị thẩm thấu trọn vẹn. Trường hợp cuốn chả/nem hoặc đổ khuôn bánh, thao tác đều tay vừa chặt để nhân kết dính nhưng không bị bục rách khi gặp nhiệt.',10,'Để nguyên liệu nghỉ đủ thời gian trước khi chiên nướng giúp lớp áo bột bám chắc và phần nhân bên trong mọng ngọt.'),
(3,4,'Pha nước chấm cân vị & sơ chế rau đồ chua ăn kèm','Nhặt rửa sạch rau củ ăn kèm ngâm nước mát cho giòn tươi, bào sợi hoặc thái lát gọn gàng bày sẵn bên cạnh. Pha chén nước chấm chua ngọt hoặc muối ớt chanh sả sánh thơm theo khẩu vị vùng miền của món Cơm tấm sườn nướng mật ong Sài Gòn để cân bằng độ béo giòn.',7,'Luôn chuẩn bị xong rau sống và bát nước chấm trước khi chiên/nướng mẻ cuối để món ăn vừa ra lò là thưởng thức nóng giòn ngay.'),
(3,5,'Làm nóng dầu / lò nướng chuẩn nhiệt & làm chín đều lần 1','Làm nóng chảo dầu hoặc vỉ nướng/nồi chiên ở mức nhiệt vừa khoảng 165–175°C, xếp 350g sườn cốt lết heo và 200g gạo tấm thơm vào với khoảng cách thoáng đều nhau. Chiên hoặc nướng trở mặt nhịp nhàng trên lửa vừa để nhiệt dẫn sâu làm chín mềm ngọt hoàn toàn phần nhân bên trong. Nấu chín gạo tấm với lượng nước vừa phải để hạt cơm tơi xốp, thơm dẻo.',12,'Kiểm tra nhiệt dầu bằng đầu đũa tre thấy sủi tăm nhỏ đều là đạt chuẩn 170°C, giúp vỏ không cháy sớm khi bên trong còn sống.'),
(3,6,'Tăng nhiệt khóa giòn rụm vàng ươm bề mặt lần 2','Ở 2–3 phút cuối, tăng lên lửa vừa lớn (khoảng 190°C) hoặc phết thêm lớp dầu điều/mật ong mỏng để vỏ ngoài của Cơm tấm sườn nướng mật ong Sài Gòn chuyển sắc vàng óng ánh và nổ giòn rụm. Lắng nghe tiếng xèo giòn rộn rã và hương thơm phức lan tỏa khắp bếp thì gắp ra vỉ thưa cho ráo dầu thừa.',6,'Đặt đồ chiên nướng lên giá inox thoáng khí thay vì giấy thấm dầu chồng khít để hơi nước thoát hết, giữ độ giòn lâu gấp 3 lần.'),
(3,7,'Trình bày bắt mắt kèm rau thơm & thưởng thức nóng','Xếp thành phẩm vàng giòn ra đĩa lớn có bày sẵn rau củ ăn kèm và điểm xuyết 40g hành lá làm mỡ hành tươi xanh hài hòa màu sắc. Dọn kèm chén nước chấm sánh đậm ngay chính giữa mâm ăn cho 2 người thưởng thức khi vỏ ngoài còn nóng giòn rụm. Nướng sườn trên vỉ hoặc nồi chiên không dầu ở nhiệt độ 180°C khoảng 15 phút, lật mặt quét sốt nướng thêm 7 phút cho xém vàng.',4,'Cắt miếng hoặc dọn ăn ngay trong vòng 10 phút sau khi rời bếp để cảm nhận trọn vẹn sự đối lập giòn ngoài - mềm ngọt bên trong.'),
(4,1,'Sơ chế tươi sạch & ngâm giòn rau củ thảo mộc','Nhặt rửa kỹ 100g giá đỗ sạch cùng 30g đậu phộng rang giã nhỏ và 50g hẹ tươi và rau thơm qua nước muối loãng rồi tráng nước đun sôi để nguội. Với các loại củ quả bào sợi hoặc thái lát mỏng, ngâm vào âu nước đá lạnh pha chút chanh đường trong 10 phút rồi vắt ráo để giữ độ trắng giòn sần sật. Luộc tôm với chút muối cho chín tới, vớt ra ngâm nước đá lạnh rồi bóc vỏ, chẻ đôi theo chiều dọc sống lưng.',8,'Rau củ làm gỏi và món cuốn phải quay rổ hoặc thấm thật ráo nước để khi trộn nước mắm không bị loãng nhạt.'),
(4,2,'Làm chín tới phần nhân đạm giữ trọn độ ngọt mọng','Xử lý phần nguyên liệu chính (300g tôm sú tươi và 250g thịt ba chỉ ngon): luộc hấp cùng lát gừng sả đập dập hoặc xào lửa lớn vừa chín tới, sau đó làm nguội nhanh rồi thái lát mỏng / xé sợi đều đặn. Nếu món có pha bột bánh gạo/bột năng, khuấy tan bột với nước đúng tỷ lệ và để bột nghỉ 15 phút cho nở mịn. Luộc chín thịt ba chỉ trong nước có đập nhánh hành củ, sau đó thái lát mỏng vừa ăn.',9,'Ngâm tôm hoặc thịt luộc qua bát nước sôi để nguội có vài viên đá giúp màu sắc tươi hồng và thớ thịt giòn ngọt không bị khô.'),
(4,3,'Rang vàng đậu phộng mè thơm & phi hành tỏi giòn','Bắc chảo nhỏ lên lửa nhỏ, rang chín vàng thơm đậu phộng/mè hoặc làm mỡ hành xanh mướt và phi vàng giòn hành tím và tỏi băm nhỏ. Vớt hành tỏi phi ra đĩa riêng để nguội giòn tan, giữ lại phần dầu thơm óng ánh để phết bánh hoặc rưới bóng mặt món ăn.',6,'Tắt bếp ngay khi hành phi chuyển vàng sáng vì nhiệt dư trong dầu nóng sẽ tiếp tục làm hành sẫm màu thêm một nấc hoàn hảo.'),
(4,4,'Pha nước mắm chấm / sốt trộn tỷ lệ vàng chua ngọt','Hòa tan hoàn toàn đường cùng gia vị chuẩn định lượng và nước ấm trong chén sâu lòng, khuấy đến khi hơi sánh nhẹ mới cho tỏi ớt băm nhuyễn và nước cốt chanh/tắc vào sau cùng. Công thức pha này giúp tỏi ớt nổi đều đẹp mắt trên bề mặt bát nước chấm chuẩn vị Gỏi cuốn tôm thịt thanh mát. Nhúng ướt nhẹ bánh tráng, trải phẳng lên mặt phẳng sạch, xếp rau xà lách, rau thơm, giá đỗ và một lọn bún tươi.',6,'Băm tỏi ớt thật ráo trên thớt khô và cho vào sau khi đường mắm đã nguội thì tỏi ớt sẽ nổi bồng bềnh 100% không bị chìm đáy.');
INSERT INTO `recipe_steps` (`recipe_id`,`step_order`,`title`,`instruction`,`duration_mins`,`tip_note`) VALUES
(4,5,'Phối trộn thấm vị / tráng hấp & cuốn đều tay','Tiến hành tráng hấp bánh mỏng mượt hoặc trải bánh cuốn gọn gàng 300g tôm sú tươi và 250g thịt ba chỉ ngon cùng 100g giá đỗ sạch; nếu là món gỏi trộn thì rưới từ từ 2/3 lượng sốt chua ngọt vào bóp nhẹ tay cho thấm đều trong 3 phút. Giữ lực tay nhẹ nhàng để rau củ không bị dập nát mà vẫn ngấm trọn vị mặn chua ngọt hài hòa.',7,'Chia nước sốt gỏi làm 2 lần trộn và chắt bỏ phần nước tiết ra ở lần đầu giúp đĩa gỏi khô ráo, đậm đà như ngoài hàng.'),
(4,6,'Bày biện ngũ sắc hài hòa & rắc topping giòn bùi','Xếp món Gỏi cuốn tôm thịt thanh mát ngay ngắn ra đĩa sứ trắng rộng, rải đều phần nhân tôm thịt sắc nét lên trên và rắc phủ 30g đậu phộng rang giã nhỏ và 50g hẹ tươi và rau thơm thơm giòn. Dọn kèm chén nước chấm đậm đà cho 3 người thưởng thức ngay khi rau bánh còn tươi giòn mướt mịn. Đặt thịt luộc, tiếp theo là tôm áp mặt đỏ xuống dưới bánh tráng, thêm cọng hẹ thò đầu ra ngoài rồi cuốn chặt tay.',4,'Chỉ rắc đậu phộng rang và hành phi ngay trước lúc mang ra bàn ăn để giữ nguyên độ giòn tan bùi béo.'),
(5,1,'Sơ chế sạch & cắt thái nguyên liệu nấu canh','Rửa sạch 450g cá basa cắt khúc và 150g cà chua chín đỏ, khử mùi tanh bằng chút muối hạt và gừng đập dập rồi rửa lại thật ráo, cắt miếng vừa ăn dày khoảng 2.5–3cm. Đồng thời gọt rửa sạch 100g giá đỗ tươi, cắt khúc hoặc bổ múi cau đồng đều để khi nấu chín đều không bị nát. Làm sạch cá basa với muối và chanh để hết nhớt, khứa nhẹ hai bên rồi để ráo nước.',7,'Phân loại riêng nhóm củ cứng nấu lâu và nhóm rau lá mềm nhanh chín để cho vào nồi theo đúng thứ tự chuẩn đầu bếp.'),
(5,2,'Ướp thấm gia vị nền cho nguyên liệu đạm','Cho phần đạm chính trong 450g cá basa cắt khúc và 150g cà chua chín đỏ vào tô, ướp nhẹ với một nửa lượng 15g tỏi phi vàng và 10g ớt sừng cay, 30ml nước mắm cá cơm và 20g đường cát trắng trong khoảng 10 phút. Đảo nhẹ tay cho gia vị áo đều bề mặt giúp miếng thịt, cá săn chắc và đậm đà từ bên trong khi thả vào nước canh. Dầm me chín trong bát nước ấm lấy nước cốt me chua thanh.',6,'Không ướp quá mặn ở bước này để giữ vị thanh mát tự nhiên của nước canh sau khi hoàn tất.'),
(5,3,'Phi thơm hành tỏi & xào săn khóa ngọt nguyên liệu','Đặt nồi canh lên bếp ở lửa vừa, làm nóng 15ml dầu ăn rồi phi thơm phần 15g tỏi phi vàng còn lại đến khi dậy mùi vàng óng. Trút nguyên liệu chính đã ướp vào đảo săn 2–3 phút cho bề mặt se lại, khóa trọn nước ngọt tự nhiên bên trong thớ thịt.',6,'Xào săn nguyên liệu đạm với hành tỏi phi trước khi đổ nước sôi giúp nước canh thơm ngọt đậm đà mà không hề tanh.'),
(5,4,'Đun sôi nước canh & hớt bọt giữ độ trong veo','Chế khoảng 1.1–1.3 lít nước (kết hợp lượng nước vừa ngập mặt nguyên liệu) vào nồi, bật lửa lớn đun đến khi sôi bùng rồi hạ ngay về lửa vừa. Dùng muôi hớt sạch lớp bọt đầu nổi lên trên mặt nước để nồi canh Canh chua cá basa bông điên điển đạt độ trong thanh đẹp mắt. Phi thơm tỏi băm, xào sơ cà chua và dứa cho lên màu vàng đỏ hấp dẫn.',9,'Sử dụng nước ấm hoặc nước sôi khi chế vào cá tươi sẽ giúp cá không bao giờ bị tanh nồng dù để nguội.'),
(5,5,'Thả rau củ theo độ chín & cân chỉnh định lượng vị','Lần lượt cho 100g giá đỗ tươi vào nồi canh đang sôi vừa (nhóm củ quả lâu chín cho trước 5–7 phút, nhóm rau mềm cho sau 1–2 phút). Nêm phần 10g ớt sừng cay, 30ml nước mắm cá cơm và 20g đường cát trắng còn lại, khuấy nhẹ và nếm thử thấy vị chua thanh hoặc ngọt dịu cân bằng đúng khẩu phần 4 người.',8,'Không đậy kín nắp vung sau khi đã thả các loại rau xanh vào nồi để giữ màu xanh ngọc tươi tắn hấp dẫn.'),
(5,6,'Điểm hương rau thơm & múc canh dọn nóng','Khi toàn bộ nguyên liệu vừa chín tới mềm ngọt, rắc ngay hành ngò và tiêu xay vào nồi rồi tắt bếp liền tay để giữ trọn tinh dầu thơm mát. Múc canh nóng hổi ra tô lớn, rắc thêm chút tiêu xay hoặc tỏi phi vàng và dùng ngay với cơm nóng. Đổ 1.2 lít nước vào đun sôi, thả cá basa vào nấu chín trong 7-8 phút, hớt bọt thường xuyên.',4,'Các loại rau thơm như thì là, ngò gai, rau om hay lá lốt chỉ nên thả ngay khoảnh khắc tắt bếp để hương thơm bùng nổ nhất.'),
(6,1,'Sơ chế sạch & cắt thái nguyên liệu đúng kích cỡ','Rửa sạch 600g thịt ba chỉ heo dày và 6 quả trứng gà hoặc vịt luộc cùng các nguyên liệu phối kèm dưới vòi nước mát rồi để thật ráo trên rổ thưa. Dùng dao sắc cắt thái nguyên liệu thành từng khúc hoặc khối vuông đều đặn khoảng 3.5–4cm để khi kho hầm giữ nguyên hình dáng đẹp mắt mà không bị vụn nát. Thịt ba chỉ rửa sạch, thái miếng vuông dày khoảng 4-5cm. Luộc sơ qua nước sôi rồi vớt ráo.',13,'Cắt miếng thịt/cá dày dặn đồng đều giúp quá trình kho lâu trên lửa nhỏ thớ thịt mềm rục mà vẫn giữ trọn độ mọng ngọt bên trong.'),
(6,2,'Khử mùi tự nhiên & làm săn sạch bề mặt nguyên liệu','Chà nhẹ phần đạm chính trong 600g thịt ba chỉ heo dày và 6 quả trứng gà hoặc vịt luộc với chút muối hạt, lát gừng đập dập hoặc chần sơ qua nước sôi 90 giây rồi rửa sạch lại bằng nước ấm, để ráo hoàn toàn. Công đoạn này loại bỏ triệt để tạp chất và mùi tanh hôi, giúp nước sốt món Thịt kho tàu nước dừa trứng vịt trong bóng thơm ngon.',10,'Sau khi chần hoặc rửa sạch, để nguyên liệu ráo nước ít nhất 5 phút trước khi ướp để gia vị rút sâu trực tiếp vào từng thớ thịt.'),
(6,3,'Pha hỗn hợp gia vị & ướp thấm chuẩn định lượng','Cho 600g thịt ba chỉ heo dày và 6 quả trứng gà hoặc vịt luộc vào tô lớn, ướp cùng một nửa 15g tỏi băm băm nhỏ và định lượng chuẩn 45ml nước mắm ngon loại 1, 25g đường thốt nốt và 5g ớt hiểm nguyên trái, đảo nhẹ tay cho gia vị phủ kín đều các mặt. Bọc kín tô và để nguyên liệu nghỉ thấm vị tối thiểu 20 phút ở nhiệt độ phòng (hoặc ngăn mát tủ lạnh). Ướp thịt với tỏi ớt băm nhuyễn, nước mắm ngon, hạt tiêu và chút đường trong 40 phút.',14,'Ướp đủ tối thiểu 20 phút trước khi bắc lên bếp là chìa khóa để tâm miếng thịt/cá đậm đà đồng nhất với lớp sốt bên ngoài.'),
(6,4,'Thắng nước màu cánh gián & phi dậy hương hành tỏi','Đặt nồi đáy dày lên bếp ở lửa vừa nhỏ, thắng nhẹ 15g đường với 15ml dầu ăn đến khi chuyển sắc nâu cánh gián óng ả thì cho ngay phần 15g tỏi băm còn lại vào phi thơm lừng. Hương caramel dịu ngọt quyện cùng tinh dầu hành tỏi sả tạo nền màu nâu hổ phách truyền thống đầy cuốn hút.',9,'Canh kỹ khoảnh khắc đường vừa chuyển màu cánh gián là hạ lửa nhỏ nhất ngay để nước màu bóng đẹp mà không bao giờ bị đắng.'),
(6,5,'Đảo săn hai mặt khóa ngọt nguyên liệu chính','Tăng lên lửa vừa lớn, gắp từng miếng trong 600g thịt ba chỉ heo dày và 6 quả trứng gà hoặc vịt luộc vào nồi đảo đều hoặc trở nhẹ hai mặt trong 4–5 phút cho săn chắc và bám đều lớp màu nâu óng. Khi bề mặt nguyên liệu se vàng thơm phức mới trút phần nước ướp còn lại trong tô vào đun sôi nhẹ. Thắng nước hàng màu cánh gián từ đường thốt nốt, trút thịt vào đảo săn cho thấm đều màu áo vàng óng.',13,'Đối với cá kho, chỉ lật cá một lần lúc cá vừa săn mặt trên lửa vừa để khúc cá nguyên vẹn không bị tróc da hay vỡ nát.'),
(6,6,'Kho/om liu riu lửa nhỏ thấm đẫm cùng nước dừa/nước dùng','Chế 400ml nước dừa tươi xâm xắp mặt nguyên liệu (xếp thêm rau củ ăn kèm nếu có), đun sôi bùng một dạo hớt sạch bọt rồi hạ ngay về mức lửa nhỏ liu riu nhất. Kho êm đềm không đậy kín nắp để từng thớ nguyên liệu chín mềm thấm đẫm gia vị và nước sốt rút dần sóng sánh. Đổ nước dừa xiêm ngập mặt thịt, đun sôi bùng rồi hạ lửa liu riu, không đậy vung để nước kho trong và thịt trong veo.',22,'Luôn dùng nước sôi hoặc nước dừa ấm khi châm thêm vào nồi kho đang nóng để thịt cá không bị sượng cứng trở lại.'),
(6,7,'Thu sánh nước sốt óng ả & trình bày thưởng thức nóng','Khi nước kho rút còn khoảng 1/3 sánh kẹo óng ánh áo đều quanh nguyên liệu và xiên đũa thấy mềm mọng vừa ý, rắc hành ngò và tiêu xay lên mặt rồi tắt bếp. Múc món Thịt kho tàu nước dừa trứng vịt ra đĩa sâu lòng hoặc niêu đất giữ nhiệt, dọn ăn nóng cùng cơm trắng dẻo thơm cho 4 người.',9,'Giữ lại một lượng nước sốt sánh kẹo vừa đủ dưới đáy nồi để chan cơm hoặc chấm kèm rau luộc sẽ tròn vị đưa cơm gấp bội.'),
(7,1,'Tuyển chọn, ngâm nở & sơ chế sạch nguyên liệu chè bánh','Đãi rửa sạch nhóm hạt, củ hoặc bột (150g bột năng áo cùi bưởi), ngâm nước ấm theo đúng đặc tính từng loại để hạt nở mềm đồng đều và loại bỏ nhựa chát. Rửa sạch nhóm tạo hương tự nhiên gồm 15g lá dứa để ráo nước. Cùi bưởi gọt sạch vỏ xanh và phần xơ trong, thái hạt lựu rồi bóp kỹ nhiều lần với muối hột, xả nước sạch cho hết đắng hoàn toàn.',15,'Thêm một nhúm muối nhỏ vào nước ngâm khoai và đậu giúp nguyên liệu giữ màu tươi sáng và khi nấu chín bùi hơn.'),
(7,2,'Ninh mềm bùi nguyên liệu chính giữ nguyên hạt/khối','Cho phần nguyên liệu nền trong 150g bột năng áo cùi bưởi vào nồi đáy dày cùng lượng nước vừa đủ, đun sôi rồi hạ lửa nhỏ ninh êm đến khi chín mềm bùi nhưng không bị vỡ nát đục nước. Nếu có trân châu, bột lọc hoặc hạt lựu, luộc riêng trong nồi nước sôi đến khi nổi trong veo rồi vớt ngâm ngay vào bát nước mát. Chần cùi bưởi qua nước sôi có pha chút đường, vớt ngay vào âu nước đá lạnh để giữ độ giòn sần sật.',20,'Tuyệt đối không cho đường ngay từ đầu khi đậu và khoai chưa chín mềm vì đường sẽ làm săn vỏ hạt khiến nấu mãi vẫn sượng.'),
(7,3,'Nấu nước đường phèn / mật mía thanh trong dậy hương','Kết hợp chính xác định lượng 120g đường phèn thanh ngọt và 15g đường vào nồi cùng bó lá dứa hoặc gừng thái chỉ, khuấy nhẹ trên lửa nhỏ cho tan trong vắt. Đun liu riu thêm 5–7 phút để vị ngọt thấm sâu vào từng viên nguyên liệu và tỏa hương thơm dịu tao nhã.',14,'Dùng đường phèn hoặc mật mía đun lửa nhỏ hớt bọt kỹ giúp hậu vị chè ngọt thanh mát họng, không bị khé cổ.'),
(7,4,'Thắng nước cốt dừa béo mịn / chuẩn bị lớp kem phủ','Cho 200ml nước cốt dừa thơm béo vào nồi nhỏ cùng 2g muối tinh và 5g bột năng/bột bắp hòa loãng, khuấy đều tay trên lửa nhỏ nhất đến khi vừa chớm sôi lăn tăn sánh mượt. Tắt bếp ngay để nước cốt dừa giữ màu trắng ngần béo ngậy mà không bị tách lớp dầu. Trộn cùi bưởi còn ẩm với bột năng cho bột áo đều từng miếng, thả vào nồi nước sôi luộc đến khi cùi trong veo thì vớt ra âu nước lạnh.',11,'Một chút xíu muối tinh trong nồi nước cốt dừa sẽ làm bật hẳn độ béo thơm tự nhiên và cân bằng vị ngọt của món tráng miệng.'),
(7,5,'Phối hợp độ sánh mượt & cân bằng hương vị tổng thể','Hợp nhất các thành phần của món Chè bưởi An Giang giòn sần sật, từ từ rưới nước bột năng hòa loãng (nếu là chè sánh) đồng thời khuấy nhẹ một chiều trên lửa nhỏ cho hỗn hợp bóng mượt như nhung. Kiểm tra độ mềm dẻo hài hòa và tắt bếp để ủ hương thảo mộc lan tỏa đều.',9,'Rót nước bột tạo sánh thành dòng mảnh vừa rót vừa khuấy đều tay giúp chè trong mượt, hoàn toàn không bị ốc trâu vón cục.'),
(7,6,'Múc ra chén sứ, điểm topping & thưởng thức ấm/lạnh','Múc chè hoặc bày bánh ra 4 chén nhỏ xinh, chan lớp nước cốt dừa trắng mịn lên mặt và rắc nhẹ 30g đậu phộng rang thơm. Thưởng thức ấm nóng dịu dàng hoặc thêm đá bào mát lạnh tùy sở thích đều trọn vị ngon truyền thống. Hấp chín đậu xanh đã cà vỏ. Đun nồi nước đường phèn, hòa chút bột năng cho sánh rồi trút đậu xanh và cùi bưởi vào khuấy đều.',6,'Để chè nguội bớt về khoảng 45°C hoặc ướp mát 30 phút trong ngăn mát tủ lạnh giúp các tầng hương vị kết tinh đậm đà hơn.'),
(8,1,'Sơ chế sạch & thấm thật khô bề mặt nguyên liệu','Rửa sạch 1200g thịt gà ta (nguyên con, ức gà hoặc đùi gà) cùng chút muối loãng để khử mùi tự nhiên, sau đó dùng khăn giấy bếp thấm thật khô ráo hoàn toàn bề mặt. Khứa nhẹ các đường chéo hoặc cắt miếng vừa ăn dày 2–3cm để nhiệt và gia vị thấm sâu đều khắp bên trong. Làm sạch gà bằng muối và rượu gừng để khử mùi, mổ phanh theo ức để trải phẳng cả con gà.',11,'Bề mặt nguyên liệu càng khô ráo thì khi chiên không bị văng dầu và khi nướng sẽ lên màu vàng ruộm giòn rụm cực đẹp.'),
(8,2,'Chuẩn bị hỗn hợp sốt ướp / bột áo chuẩn tỷ lệ','Phối trộn 60g sả tươi băm nhuyễn và 25g tỏi băm thơm băm thật nhuyễn (hoặc vắt lấy nước cốt thơm) cùng 20g ớt sừng và ớt cay, 30ml nước mắm đậm đà và 25g mật ong quét da trong tô lớn cho quyện sánh đồng nhất. Nếu món có lớp vỏ bột hoặc bánh cuốn từ 1200g thịt gà ta (nguyên con, ức gà hoặc đùi gà), trộn đều hỗn hợp theo đúng định lượng để đạt độ giòn xốp mỏng nhẹ chuẩn vị. Giã nhuyễn sả, ớt, tỏi, hạt nêm, tiêu, dầu màu điều và nước mắm thành hỗn hợp sốt ướp thơm lừng.',11,'Vắt lấy nước cốt hành tỏi sả khi ướp đồ nướng giúp hương thơm thấm sâu mà không bị cháy đen phần xác băm trên lửa cao.'),
(8,3,'Ướp thấm thớ thịt / tạo hình cuốn khéo léo','Áo đều hỗn hợp gia vị hoặc lớp bột/vỏ cuốn quanh 1200g thịt gà ta (nguyên con, ức gà hoặc đùi gà), massage nhẹ nhàng rồi để nghỉ 15–20 phút cho gia vị thẩm thấu trọn vẹn. Trường hợp cuốn chả/nem hoặc đổ khuôn bánh, thao tác đều tay vừa chặt để nhân kết dính nhưng không bị bục rách khi gặp nhiệt.',14,'Để nguyên liệu nghỉ đủ thời gian trước khi chiên nướng giúp lớp áo bột bám chắc và phần nhân bên trong mọng ngọt.'),
(8,4,'Pha nước chấm cân vị & sơ chế rau đồ chua ăn kèm','Nhặt rửa sạch rau củ ăn kèm ngâm nước mát cho giòn tươi, bào sợi hoặc thái lát gọn gàng bày sẵn bên cạnh. Pha chén nước chấm chua ngọt hoặc muối ớt chanh sả sánh thơm theo khẩu vị vùng miền của món Gà nướng sả ớt da giòn thơm lừng để cân bằng độ béo giòn.',9,'Luôn chuẩn bị xong rau sống và bát nước chấm trước khi chiên/nướng mẻ cuối để món ăn vừa ra lò là thưởng thức nóng giòn ngay.');
INSERT INTO `recipe_steps` (`recipe_id`,`step_order`,`title`,`instruction`,`duration_mins`,`tip_note`) VALUES
(8,5,'Làm nóng dầu / lò nướng chuẩn nhiệt & làm chín đều lần 1','Làm nóng chảo dầu hoặc vỉ nướng/nồi chiên ở mức nhiệt vừa khoảng 165–175°C, xếp 1200g thịt gà ta (nguyên con, ức gà hoặc đùi gà) vào với khoảng cách thoáng đều nhau. Chiên hoặc nướng trở mặt nhịp nhàng trên lửa vừa để nhiệt dẫn sâu làm chín mềm ngọt hoàn toàn phần nhân bên trong. Xoa đều sốt ướp vào bên trong mình gà và nhẹ nhàng lùa sốt dưới da để thịt ngấm đậm vị trong 60 phút.',16,'Kiểm tra nhiệt dầu bằng đầu đũa tre thấy sủi tăm nhỏ đều là đạt chuẩn 170°C, giúp vỏ không cháy sớm khi bên trong còn sống.'),
(8,6,'Tăng nhiệt khóa giòn rụm vàng ươm bề mặt lần 2','Ở 2–3 phút cuối, tăng lên lửa vừa lớn (khoảng 190°C) hoặc phết thêm lớp dầu điều/mật ong mỏng để vỏ ngoài của Gà nướng sả ớt da giòn thơm lừng chuyển sắc vàng óng ánh và nổ giòn rụm. Lắng nghe tiếng xèo giòn rộn rã và hương thơm phức lan tỏa khắp bếp thì gắp ra vỉ thưa cho ráo dầu thừa.',8,'Đặt đồ chiên nướng lên giá inox thoáng khí thay vì giấy thấm dầu chồng khít để hơi nước thoát hết, giữ độ giòn lâu gấp 3 lần.'),
(8,7,'Trình bày bắt mắt kèm rau thơm & thưởng thức nóng','Xếp thành phẩm vàng giòn ra đĩa lớn có bày sẵn rau củ ăn kèm và điểm xuyết hành ngò và tiêu xay tươi xanh hài hòa màu sắc. Dọn kèm chén nước chấm sánh đậm ngay chính giữa mâm ăn cho 4 người thưởng thức khi vỏ ngoài còn nóng giòn rụm. Nướng gà trên than hoa hoặc lò nướng 200°C trong 35 phút cho gà chín đều từ bên trong.',6,'Cắt miếng hoặc dọn ăn ngay trong vòng 10 phút sau khi rời bếp để cảm nhận trọn vẹn sự đối lập giòn ngoài - mềm ngọt bên trong.'),
(9,1,'Sơ chế & thái mỏng đồng đều nguyên liệu xào','Làm sạch và thấm ráo 400g rau muống non ngắt ngọn, dùng dao sắc thái lát mỏng vừa ăn khoảng 2–3mm ngang thớ để khi xào nhanh chín mềm không bị dai. Nhặt rửa sạch rau củ ăn kèm, cắt khúc xéo 4cm hoặc tách nhánh đồng đều giúp tiếp xúc nhiệt nhanh trên chảo. Nhặt ngọn rau muống non, rửa sạch ngâm nước muối loãng rồi vớt ra rổ để thật ráo nước.',4,'Nguyên liệu xào bắt buộc phải để thật ráo nước trước khi cho vào chảo để đạt hiệu ứng áp nhiệt thơm kiểu chảo gang.'),
(9,2,'Ướp mềm nguyên liệu đạm & pha sẵn chén sốt xào','Ướp phần đạm trong 400g rau muống non ngắt ngọn với 1/3 lượng 35g tỏi ta đập dập, 20g hành tím và 10g tỏi, chút dầu ăn và 1/3 lượng 15ml nước mắm ngon trong 10 phút để giữ độ ẩm mọng. Pha phần 15ml nước mắm ngon còn lại cùng 20ml nước lọc vào chén nhỏ khuấy tan hoàn toàn để thao tác xào lửa lớn diễn ra dứt khoát. Đun nồi nước sôi bùng với chút muối hột, chần nhanh rau muống trong 30 giây rồi vớt thả ngay vào âu nước đá lạnh.',4,'Thêm 1 muỗng cà phê dầu ăn vào bước ướp thịt bò/heo giúp khóa ẩm và các lát thịt tơi nhanh không bị dính chùm khi gặp chảo nóng.'),
(9,3,'Chần nhanh rau củ giữ sắc xanh ngọc & độ giòn','Đun sôi nồi nước nhỏ với một nhúm muối, thả rau củ ăn kèm vào chần nhanh 30–45 giây rồi vớt ngay ra tô nước đá lạnh cho sốc nhiệt, sau đó đổ ra rổ cho thật ráo. Bước tiền xử lý này giúp rau củ chín đều từ trong mà bên ngoài vẫn xanh mướt giòn sần sật.',3,'Thời gian chần dưới 1 phút kết hợp ngâm nước đá lạnh là bí quyết nhà hàng giúp đĩa rau xào không bị chảy nước đen đĩa.'),
(9,4,'Xào săn nguyên liệu chính trên lửa lớn nhanh tay','Làm nóng chảo rộng trên lửa lớn nhất với 15ml dầu ăn, phi dậy mùi một nửa 35g tỏi ta đập dập, 20g hành tím và 10g tỏi rồi trút phần đạm chính trong 400g rau muống non ngắt ngọn vào đảo cực nhanh tay trong 60–90 giây. Ngay khi thịt hoặc hải sản vừa chín tái hồng khoảng 85%, lập tức trút riêng ra đĩa sạch để không bị quá lửa khô xác. Đun nóng chảo với dầu ăn, phi một nửa lượng tỏi đập dập cho dậy mùi thơm nức.',3,'Tuyệt đối không xào thịt chung từ đầu đến cuối với rau củ vì thịt sẽ bị dai và tiết nước làm mất độ giòn.'),
(9,5,'Xào rau củ lửa lớn & rưới sốt định lượng khóa vị','Giữ nguyên chảo nóng trên lửa lớn, thêm chút dầu phi thơm nốt phần 35g tỏi ta đập dập, 20g hành tím và 10g tỏi còn lại rồi cho rau củ ăn kèm đã ráo nước vào đảo đều 1–2 phút. Trút ngược đĩa đạm vào chảo, rưới đều chén sốt gia vị đã pha và xóc nhanh tay 45 giây cho sốt sánh bóng áo quanh từng miếng nguyên liệu.',4,'Rưới sốt vòng quanh thành chảo nóng thay vì đổ thẳng giữa lòng chảo giúp sốt bốc hơi thơm lừng và sệt lại tức thì.'),
(9,6,'Dậy hương tiêu hành & trình bày nóng hổi','Cho hành ngò và tiêu xay vào đảo nhẹ đúng 1 lượt rồi tắt bếp ngay khi khói thơm bốc lên nghi ngút. Gắp món Rau muống xào tỏi xanh mướt giòn rụm ra đĩa rộng lòng để tản nhiệt đều, tránh đậy kín vung và thưởng thức nóng ngay cùng cơm dẻo cho 3 người. Mở lửa cực lớn, trút rau muống vào xào đảo nhanh tay, nêm hạt nêm và thìa nước mắm ngon.',2,'Bày món xào ra đĩa rộng không xếp chồng quá dày giúp hơi nóng thoát nhẹ, giữ rau củ giòn ngọt lâu đến miếng cuối cùng.'),
(10,1,'Sơ chế sạch & chuẩn bị nguyên liệu thuần chay','Rửa sạch toàn bộ nguyên liệu dưới vòi nước mát, để ráo tự nhiên trên rổ thưa gồm 300g đậu hũ non mơ và 200g cà chua chín mềm cùng các nguyên liệu phối kèm. Cắt thái đồng đều kích thước khoảng 3–4cm vừa gắp để khi chế biến chín cùng lúc và thấm đều gia vị thực vật. Đậu hũ thấm khô nước, thái miếng vuông vừa ăn kích cỡ 3x3cm.',4,'Thấm khô bề mặt đậu hũ và nấm bằng khăn giấy bếp trước khi chế biến giúp nguyên liệu săn chắc, không bị bắn dầu hay ra nước.'),
(10,2,'Xử lý độ giòn ngọt của nấm & rau củ','Đối với nhóm nấm và rau củ (300g đậu hũ non mơ và 200g cà chua chín mềm), ngâm nhanh qua nước muối loãng 3 phút rồi vắt nhẹ hoặc chần sơ 45 giây trong nước sôi, vớt ngay ra tô nước mát. Thao tác này giúp giữ trọn sắc màu tươi sáng tự nhiên, loại bỏ mùi ngái và tạo độ giòn ngọt thanh khiết cho món Đậu hũ sốt cà chua thanh đạm.',3,'Không ngâm nấm quá lâu trong nước lạnh vì nấm sẽ hút nước mạnh làm nhạt vị ngọt umami tự nhiên.'),
(10,3,'Pha chén sốt gia vị chay chuẩn định lượng','Chuẩn bị tô nhỏ, đong chính xác 15ml nước mắm chay và 10g đường làm dịu vị chua khuấy đều cùng 30ml nước ấm hoặc nước ngâm nấm hương cho tan hoàn toàn đường và hạt nêm nấm. Nếm thử thấy vị mặn ngọt hài hòa, thanh dịu đúng tinh thần ẩm thực chay cho khẩu phần 2 người. Chiên đậu trong chảo dầu nóng lửa vừa đến khi các mặt có lớp vỏ vàng giòn ruộm thì gắp ra ráo dầu.',2,'Pha sẵn chén sốt trước khi bật bếp giúp kiểm soát chính xác định lượng từng gam và không bị cháy khét gia vị trên chảo nóng.'),
(10,4,'Phi thơm hành boaro & tạo nền hương thảo mộc','Làm nóng nồi hoặc chảo đáy dày trên lửa vừa, cho 30ml dầu thực vật vào láng đều mặt chảo rồi trút 20g hành boaro thái lát mỏng vào phi thơm. Đảo nhẹ tay khoảng 1–2 phút đến khi hành boaro chuyển sắc vàng óng và dậy mùi thơm dịu thì hạ lửa vừa.',3,'Hành boaro cháy nhanh hơn hành tím nên chỉ phi trên lửa vừa đến khi vừa chớm vàng thơm là cho nguyên liệu chính vào ngay.'),
(10,5,'Chế biến săn thấm nguyên liệu chính thuần thực vật','Cho 300g đậu hũ non mơ và 200g cà chua chín mềm vào đảo đều hoặc áp chảo nhẹ hai mặt trên lửa vừa đến khi bề mặt săn vàng, sau đó rưới 2/3 chén sốt gia vị chay đã pha vào. Đảo nhẹ tay để sốt bám đều quanh từng thớ đậu và nấm mà không làm vỡ nát cấu trúc nguyên liệu. Cà chua băm nhuyễn xào nhừ trong chảo với chút dầu ăn và gia vị cho tan thành nước sốt sánh mịn.',7,'Dùng sạn gỗ đảo nhẹ từ dưới đáy chảo hất lên để miếng đậu hũ và nấm giữ nguyên hình khối vuông vắn đẹp mắt.'),
(10,6,'Phối hợp rau củ & cân chỉnh độ sánh thanh đạm','Tiếp tục cho các nguyên liệu phối kèm cùng phần sốt còn lại vào nồi, điều chỉnh lửa vừa nấu thêm cho nguyên liệu chín mềm tới nhưng vẫn giữ độ giòn ngọt. Quan sát thấy nước sốt chuyển màu nâu hổ phách sóng sánh hoặc nước dùng trong thanh, hương thơm quyện đều khắp gian bếp. Thả đậu hũ rán vào đun liu riu cùng sốt cà chua trong 5 phút để đậu hút đẫm vị đậm đà.',4,'Chỉ nấu rau củ xanh vừa chín tới để bảo toàn tối đa lượng chất xơ và vitamin tự nhiên trong khẩu phần chay.'),
(10,7,'Hoàn thiện hương thơm & trình bày món chay thanh tịnh','Tắt bếp ngay khi món ăn đạt độ chín chuẩn, rắc đều 30g hành hoa thái nhỏ lên bề mặt để dậy mùi thơm tươi mới. Múc món Đậu hũ sốt cà chua thanh đạm ra đĩa sứ hoặc tô sâu lòng, thưởng thức nóng cùng cơm trắng hoặc bún tươi cho trọn vẹn 2 khẩu phần.',2,'Rắc rau thơm và tiêu ngay lúc vừa tắt bếp giúp tinh dầu tỏa hương thơm ngát mà lá rau không bị thâm xỉn màu.'),
(11,1,'Sơ chế & chần sạch nguyên liệu xương thịt, hải sản','Rửa sạch 400g bắp bò hoa giòn và 400g giò heo khoanh tròn với muối hạt rồi chần nhanh trong nồi nước sôi có đập dập 1 nhánh gừng trong 2–3 phút trên lửa lớn để loại bỏ hoàn toàn bọt bẩn. Rửa lại dưới làn nước sạch cho thật trắng trẻo, đồng thời nhặt rửa sạch 100g hành hoa và hoa chuối để ráo nước. Chần bắp bò và giò heo qua nước sôi, rửa sạch lại rồi cuộn bắp bò bằng chỉ cho tròn đều.',18,'Bước chần sơ và rửa lại bằng nước ấm là bí quyết vàng giúp nồi nước dùng trong vắt, thơm thanh và không bao giờ bị đục hay hôi.'),
(11,2,'Nướng thơm thảo mộc & ninh nền nước dùng ngọt thanh','Cho phần nguyên liệu tạo ngọt từ 400g bắp bò hoa giòn và 400g giò heo khoanh tròn cùng 80g sả cây đập dập đã nướng xém thơm vào nồi sâu lòng với khoảng 1.5–1.8 lít nước lọc. Đun sôi bùng trên lửa lớn rồi hạ ngay về lửa nhỏ liu riu, mở hé vung và hớt kỹ bọt nổi trên mặt để chiết xuất vị ngọt tự nhiên. Hầm xương ống và giò heo cùng sả cây đập dập trong 1.5 giờ. Thả bắp bò vào luộc chín tới rồi vớt ra ngâm nước nguội thái lát mỏng.',41,'Luôn duy trì mặt nước lăn tăn nhẹ thay vì đun sôi sùng sục lửa to để protein không bị nhũ hóa gây đục nước lèo.'),
(11,3,'Xào tạo màu & dậy hương đặc trưng vùng miền','Bắc chảo nhỏ lên bếp với 15ml dầu ăn trên lửa vừa, phi thơm phần hành tỏi sả băm còn lại rồi xào săn 500g bún sợi to xứ huế cùng 35g mắm ruốc huế truyền thống và 25g sa tế ớt huế cay nồng trong 3–4 phút. Khi hỗn hợp dậy mùi thơm nồng nàn và lên sắc màu óng ả đặc trưng của món Bún bò Huế cay nồng chuẩn vị Cố đô thì tắt bếp.',16,'Xào riêng phần nguyên liệu tạo màu và gia vị thơm trước khi trút vào nồi nước dùng giúp tầng hương dậy lên rõ nét gấp đôi.'),
(11,4,'Sơ chế & cắt thái phần nhân topping xếp tô','Vớt phần thịt hoặc hải sản chín tới từ 400g bắp bò hoa giòn và 400g giò heo khoanh tròn ra ngâm ngay vào âu nước đun sôi để nguội giúp bề mặt săn giòn mọng nước, không bị thâm khô. Thái lát mỏng đều tay dày khoảng 3mm ngang thớ hoặc gỡ miếng vừa ăn, sắp riêng từng phần gọn gàng trên đĩa.',16,'Thái thịt ngang thớ với lưỡi dao thật sắc giúp lát thịt mềm mướt, khi chan nước dùng sôi lên sẽ phẳng đẹp không bị quăn cứng.'),
(11,5,'Hợp nhất nồi nước lèo & nêm chuẩn định lượng','Trút phần sốt màu thơm vào nồi nước dùng đang sôi lăn tăn, nêm chính xác lượng 35g mắm ruốc huế truyền thống và 25g sa tế ớt huế cay nồng còn lại cho vừa miệng 4 người ăn. Đun nhẹ thêm 5 phút ở lửa vừa để các tầng vị mặn dịu, ngọt hậu từ xương thịt và thảo mộc hòa quyện tròn trịa. Hòa mắm ruốc với nước lạnh, đun sôi để lắng cặn, chỉ lấy phần nước trong châm vào nồi nước dùng.',16,'Nên nêm nước mắm ngon ở giai đoạn cuối trên lửa nhỏ để giữ trọn hậu vị ngọt đạm và hương thơm mà không làm nước dùng bị chua.'),
(11,6,'Chần nóng sợi bánh/bún & chuẩn bị rau ăn kèm','Đun sôi một nồi nước riêng, cho phần sợi bún/phở/bánh trong 400g bắp bò hoa giòn và 400g giò heo khoanh tròn vào trụng nhanh 15–25 giây cho sợi mềm dẻo nóng hổi rồi vẩy thật ráo nước, chia đều vào 4 tô lớn. Chần sơ thêm rau ăn kèm (giá đỗ, rau xanh) nếu muốn dùng chín giòn.',13,'Trụng bún bánh ở nồi nước sôi riêng biệt giúp nước dùng chính không bị nhiễm tinh bột chua và tô bún luôn ráo sợi, thấm vị.'),
(11,7,'Xếp nhân hài hòa, chan nước dùng sôi & thưởng thức','Xếp đều các phần nhân thịt, hải sản lên mặt tô bún bánh, điểm xuyết 100g hành hoa và hoa chuối lên trên cùng. Dùng muôi múc nước dùng đang sôi thật già chan ngập xăm xắp mặt nguyên liệu để làm chín thơm hành ngò, dọn nóng ngay kèm chanh ớt tươi. Xào sa tế ớt màu điều đổ vào nồi nước dùng để tạo màu đỏ cam lóng lánh và vị cay ấm nồng đặc trưng.',10,'Tráng nóng tô sứ bằng nước sôi trước khi xếp bún giúp tô món nước giữ nhiệt bốc khói nghi ngút suốt bữa ăn.'),
(12,1,'Sơ chế sạch & thấm thật khô bề mặt nguyên liệu','Rửa sạch 250g bột gạo xay pha nghệ và 200g tôm đất nhỏ ngọt cùng chút muối loãng để khử mùi tự nhiên, sau đó dùng khăn giấy bếp thấm thật khô ráo hoàn toàn bề mặt. Khứa nhẹ các đường chéo hoặc cắt miếng vừa ăn dày 2–3cm để nhiệt và gia vị thấm sâu đều khắp bên trong. Khuấy đều bột gạo với nước, nước cốt dừa, bột nghệ, hành lá thái nhỏ và chút muối để bột nghỉ 30 phút.',8,'Bề mặt nguyên liệu càng khô ráo thì khi chiên không bị văng dầu và khi nướng sẽ lên màu vàng ruộm giòn rụm cực đẹp.'),
(12,2,'Chuẩn bị hỗn hợp sốt ướp / bột áo chuẩn tỷ lệ','Phối trộn hành tím và tỏi băm nhỏ băm thật nhuyễn (hoặc vắt lấy nước cốt thơm) cùng gia vị chuẩn định lượng trong tô lớn cho quyện sánh đồng nhất. Nếu món có lớp vỏ bột hoặc bánh cuốn từ 250g bột gạo xay pha nghệ và 200g tôm đất nhỏ ngọt, trộn đều hỗn hợp theo đúng định lượng để đạt độ giòn xốp mỏng nhẹ chuẩn vị. Xào sơ tôm và thịt ba rọi trong chảo gang cho săn và thơm.',8,'Vắt lấy nước cốt hành tỏi sả khi ướp đồ nướng giúp hương thơm thấm sâu mà không bị cháy đen phần xác băm trên lửa cao.');
INSERT INTO `recipe_steps` (`recipe_id`,`step_order`,`title`,`instruction`,`duration_mins`,`tip_note`) VALUES
(12,3,'Ướp thấm thớ thịt / tạo hình cuốn khéo léo','Áo đều hỗn hợp gia vị hoặc lớp bột/vỏ cuốn quanh 250g bột gạo xay pha nghệ và 200g tôm đất nhỏ ngọt, massage nhẹ nhàng rồi để nghỉ 15–20 phút cho gia vị thẩm thấu trọn vẹn. Trường hợp cuốn chả/nem hoặc đổ khuôn bánh, thao tác đều tay vừa chặt để nhân kết dính nhưng không bị bục rách khi gặp nhiệt.',10,'Để nguyên liệu nghỉ đủ thời gian trước khi chiên nướng giúp lớp áo bột bám chắc và phần nhân bên trong mọng ngọt.'),
(12,4,'Pha nước chấm cân vị & sơ chế rau đồ chua ăn kèm','Nhặt rửa sạch 150g giá đỗ sạch ngâm nước mát cho giòn tươi, bào sợi hoặc thái lát gọn gàng bày sẵn bên cạnh. Pha chén nước chấm chua ngọt hoặc muối ớt chanh sả sánh thơm theo khẩu vị vùng miền của món Bánh xèo miền Trung giòn rụm nhân tôm thịt để cân bằng độ béo giòn.',7,'Luôn chuẩn bị xong rau sống và bát nước chấm trước khi chiên/nướng mẻ cuối để món ăn vừa ra lò là thưởng thức nóng giòn ngay.'),
(12,5,'Làm nóng dầu / lò nướng chuẩn nhiệt & làm chín đều lần 1','Làm nóng chảo dầu hoặc vỉ nướng/nồi chiên ở mức nhiệt vừa khoảng 165–175°C, xếp 250g bột gạo xay pha nghệ và 200g tôm đất nhỏ ngọt vào với khoảng cách thoáng đều nhau. Chiên hoặc nướng trở mặt nhịp nhàng trên lửa vừa để nhiệt dẫn sâu làm chín mềm ngọt hoàn toàn phần nhân bên trong. Làm nóng chảo với chút dầu ăn, múc một muôi bột láng thật mỏng đều khắp lòng chảo.',12,'Kiểm tra nhiệt dầu bằng đầu đũa tre thấy sủi tăm nhỏ đều là đạt chuẩn 170°C, giúp vỏ không cháy sớm khi bên trong còn sống.'),
(12,6,'Tăng nhiệt khóa giòn rụm vàng ươm bề mặt lần 2','Ở 2–3 phút cuối, tăng lên lửa vừa lớn (khoảng 190°C) hoặc phết thêm lớp dầu điều/mật ong mỏng để vỏ ngoài của Bánh xèo miền Trung giòn rụm nhân tôm thịt chuyển sắc vàng óng ánh và nổ giòn rụm. Lắng nghe tiếng xèo giòn rộn rã và hương thơm phức lan tỏa khắp bếp thì gắp ra vỉ thưa cho ráo dầu thừa.',6,'Đặt đồ chiên nướng lên giá inox thoáng khí thay vì giấy thấm dầu chồng khít để hơi nước thoát hết, giữ độ giòn lâu gấp 3 lần.'),
(12,7,'Trình bày bắt mắt kèm rau thơm & thưởng thức nóng','Xếp thành phẩm vàng giòn ra đĩa lớn có bày sẵn 150g giá đỗ sạch và điểm xuyết 30g hành lá cắt khúc tươi xanh hài hòa màu sắc. Dọn kèm chén nước chấm sánh đậm ngay chính giữa mâm ăn cho 3 người thưởng thức khi vỏ ngoài còn nóng giòn rụm. Rải tôm, thịt và một nắm giá đỗ lên nửa mặt bánh, đậy nắp chảo trong 2 phút cho bánh chín giòn rụm viền ngoài.',4,'Cắt miếng hoặc dọn ăn ngay trong vòng 10 phút sau khi rời bếp để cảm nhận trọn vẹn sự đối lập giòn ngoài - mềm ngọt bên trong.'),
(13,1,'Tuyển chọn & sơ chế tươi sạch nguyên liệu pha chế','Rửa sạch kỹ các nguyên liệu tươi gồm 50ml nước cốt dừa hoặc sữa đặc và 15g đường phèn hoặc mật ong và 15g lá dứa, để ráo nước hoàn toàn trên khay sạch. Cắt lát, đập dập hoặc đong chuẩn xác từng gam/ml nguyên liệu cho khẩu phần 2 ly để hương vị đồng nhất tuyệt đối. Bơ sáp chín tới khía dọc, bỏ hạt, dùng thìa nạo lấy phần thịt bơ xanh vàng dẻo quánh.',4,'Loại bỏ kỹ hạt chanh, tắc trước khi vắt hoặc nấu giúp thức uống giữ hậu vị thanh ngọt mà không hề bị đắng vỏ.'),
(13,2,'Ủ chiết xuất nền trà, cà phê hoặc nấu cốt thảo mộc','Đun nước đạt nhiệt độ chuẩn 90–95°C (không dùng nước sôi sùng sục làm cháy hương), tiến hành ủ chiết xuất hoặc nấu nhỏ lửa 50ml nước cốt dừa hoặc sữa đặc và 15g đường phèn hoặc mật ong trong thời gian quy định. Lọc qua rây mịn hoặc túi vải sạch để thu được phần nước cốt trong trẻo, đậm hương tự nhiên không gợn cặn. Cho bơ, sữa tươi không đường, sữa đặc, nước cốt dừa và đường vào cối xay sinh tố.',5,'Ủ trà/cà phê đúng nhiệt độ 92°C và đậy nắp kín giúp thu trọn tinh dầu thơm quyến rũ mà không chiết xuất vị chát gắt.'),
(13,3,'Xử lý lớp kem bông mịn / hỗn hợp sữa & trái cây','Đánh bông mượt hoặc khuấy hòa quyện phần nguyên liệu bổ trợ (8g hạt chia) cùng 15g đường phèn hoặc mật ong và 15g đường đến khi sánh mịn đồng nhất. Kiểm soát tốc độ khuấy/đánh đều tay để tạo kết cấu bồng bềnh mượt mà hoặc hòa tan hoàn toàn đường phèn mật ong. Thêm đá viên đập nhỏ rồi bấm máy xay ở tốc độ cao trong 45 giây đến khi hỗn hợp nhuyễn mịn như kem tuyết.',4,'Nếu đánh kem trứng, nghiêng nhẹ âu 45 độ và đánh một chiều tốc độ cao cho tới khi nhấc que tạo chóp mềm bóng mượt không tanh.'),
(13,4,'Cân chỉnh định lượng độ ngọt & tầng hương tươi mát','Phối trộn phần nước cốt nền cùng hỗn hợp tạo vị theo đúng tỷ lệ vàng của món Sinh tố bơ sáp nước cốt dừa béo mịn, khuấy nhẹ để các tầng hương hòa quyện. Nếu có nước cốt chanh hoặc mật ong rừng, cho vào khi nền nước đã hạ xuống dưới 55°C để bảo toàn trọn vẹn vitamin và hương thơm.',3,'Nếm thử trước khi thêm đá viên sao cho vị đậm hơn khoảng 15% để khi đá tan nhẹ là vừa vặn hoàn hảo.'),
(13,5,'Phối tầng thẩm mỹ ra ly thủy tinh nóng hoặc đá mát','Tráng ấm ly gốm (nếu dùng nóng) hoặc cho lượng đá viên tinh khiết vừa đủ vào ly thủy tinh cao, rót từ từ cốt thức uống vào 2/3 ly. Nhẹ nhàng rót lớp kem/sữa hoặc xếp lát trái cây tươi áp sát thành ly tạo hiệu ứng phân tầng đẹp mắt như quán chuyên nghiệp.',2,'Rót lớp kem hoặc sữa nhẹ nhàng qua lưng muỗng inox giúp hai tầng màu tách bạch sắc nét cực kỳ cuốn hút.'),
(13,6,'Điểm xuyết lá thơm trang trí & thưởng thức ngay','Trang trí trên mặt ly bằng lát nguyên liệu tươi, nhánh bạc hà/lá dứa hoặc rắc nhẹ bột cacao/hạt chia cho món Sinh tố bơ sáp nước cốt dừa béo mịn thêm phần sinh động. Phục vụ ngay khi vừa pha chế xong cho 2 người để tận hưởng trọn vẹn hương thơm tươi mới sảng khoái nhất. Rót sinh tố bơ ra ly thủy tinh cao, rắc đậu phộng rang giòn hoặc dừa non nạo sợi lên mặt thưởng thức ngay.',2,'Vỗ nhẹ lá bạc hà trong lòng bàn tay trước khi đặt lên miệng ly sẽ đánh thức tinh dầu the mát lan tỏa ngay khi nâng ly.'),
(14,1,'Sơ chế sạch & cắt thái nguyên liệu đúng kích cỡ','Rửa sạch 500g thịt gà (ức gà hoặc đùi gà chặt miếng) cùng các nguyên liệu phối kèm dưới vòi nước mát rồi để thật ráo trên rổ thưa. Dùng dao sắc cắt thái nguyên liệu thành từng khúc hoặc khối vuông đều đặn khoảng 3.5–4cm để khi kho hầm giữ nguyên hình dáng đẹp mắt mà không bị vụn nát. Thịt gà chặt miếng vừa ăn, rửa sạch với nước muối loãng có pha chút rượu gừng cho hết mùi tanh.',6,'Cắt miếng thịt/cá dày dặn đồng đều giúp quá trình kho lâu trên lửa nhỏ thớ thịt mềm rục mà vẫn giữ trọn độ mọng ngọt bên trong.'),
(14,2,'Khử mùi tự nhiên & làm săn sạch bề mặt nguyên liệu','Chà nhẹ phần đạm chính trong 500g thịt gà (ức gà hoặc đùi gà chặt miếng) với chút muối hạt, lát gừng đập dập hoặc chần sơ qua nước sôi 90 giây rồi rửa sạch lại bằng nước ấm, để ráo hoàn toàn. Công đoạn này loại bỏ triệt để tạp chất và mùi tanh hôi, giúp nước sốt món Gà kho gừng ấm nồng ngày trở gió trong bóng thơm ngon.',4,'Sau khi chần hoặc rửa sạch, để nguyên liệu ráo nước ít nhất 5 phút trước khi ướp để gia vị rút sâu trực tiếp vào từng thớ thịt.'),
(14,3,'Pha hỗn hợp gia vị & ướp thấm chuẩn định lượng','Cho 500g thịt gà (ức gà hoặc đùi gà chặt miếng) vào tô lớn, ướp cùng một nửa 50g gừng non thái sợi dài và 15g tỏi băm nhỏ băm nhỏ và định lượng chuẩn 30ml nước mắm ngon, 15g đường caramel tạo màu và 5g tiêu đen xay thơm, đảo nhẹ tay cho gia vị phủ kín đều các mặt. Bọc kín tô và để nguyên liệu nghỉ thấm vị tối thiểu 20 phút ở nhiệt độ phòng (hoặc ngăn mát tủ lạnh). Ướp thịt gà với một nửa lượng gừng sợi, tỏi băm, nước mắm ngon, hạt tiêu và hạt nêm trong 20 phút.',6,'Ướp đủ tối thiểu 20 phút trước khi bắc lên bếp là chìa khóa để tâm miếng thịt/cá đậm đà đồng nhất với lớp sốt bên ngoài.'),
(14,4,'Thắng nước màu cánh gián & phi dậy hương hành tỏi','Đặt nồi đáy dày lên bếp ở lửa vừa nhỏ, thắng nhẹ 15g đường với 15ml dầu ăn đến khi chuyển sắc nâu cánh gián óng ả thì cho ngay phần 50g gừng non thái sợi dài và 15g tỏi băm nhỏ còn lại vào phi thơm lừng. Hương caramel dịu ngọt quyện cùng tinh dầu hành tỏi sả tạo nền màu nâu hổ phách truyền thống đầy cuốn hút.',4,'Canh kỹ khoảnh khắc đường vừa chuyển màu cánh gián là hạ lửa nhỏ nhất ngay để nước màu bóng đẹp mà không bao giờ bị đắng.'),
(14,5,'Đảo săn hai mặt khóa ngọt nguyên liệu chính','Tăng lên lửa vừa lớn, gắp từng miếng trong 500g thịt gà (ức gà hoặc đùi gà chặt miếng) vào nồi đảo đều hoặc trở nhẹ hai mặt trong 4–5 phút cho săn chắc và bám đều lớp màu nâu óng. Khi bề mặt nguyên liệu se vàng thơm phức mới trút phần nước ướp còn lại trong tô vào đun sôi nhẹ. Thắng nước hàng màu cánh gián từ đường, phi thơm phần gừng sợi còn lại cho dậy mùi thơm nức.',6,'Đối với cá kho, chỉ lật cá một lần lúc cá vừa săn mặt trên lửa vừa để khúc cá nguyên vẹn không bị tróc da hay vỡ nát.'),
(14,6,'Kho/om liu riu lửa nhỏ thấm đẫm cùng nước dừa/nước dùng','Chế lượng nước vừa ngập mặt nguyên liệu xâm xắp mặt nguyên liệu (xếp thêm rau củ ăn kèm nếu có), đun sôi bùng một dạo hớt sạch bọt rồi hạ ngay về mức lửa nhỏ liu riu nhất. Kho êm đềm không đậy kín nắp để từng thớ nguyên liệu chín mềm thấm đẫm gia vị và nước sốt rút dần sóng sánh. Cho thịt gà vào xào săn trên lửa lớn để miếng thịt chắc và ngấm màu vàng đều đẹp mắt.',10,'Luôn dùng nước sôi hoặc nước dừa ấm khi châm thêm vào nồi kho đang nóng để thịt cá không bị sượng cứng trở lại.'),
(14,7,'Thu sánh nước sốt óng ả & trình bày thưởng thức nóng','Khi nước kho rút còn khoảng 1/3 sánh kẹo óng ánh áo đều quanh nguyên liệu và xiên đũa thấy mềm mọng vừa ý, rắc hành ngò và tiêu xay lên mặt rồi tắt bếp. Múc món Gà kho gừng ấm nồng ngày trở gió ra đĩa sâu lòng hoặc niêu đất giữ nhiệt, dọn ăn nóng cùng cơm trắng dẻo thơm cho 3 người.',4,'Giữ lại một lượng nước sốt sánh kẹo vừa đủ dưới đáy nồi để chan cơm hoặc chấm kèm rau luộc sẽ tròn vị đưa cơm gấp bội.'),
(15,1,'Sơ chế sạch & cắt thái nguyên liệu đúng kích cỡ','Rửa sạch 300g thịt nạc vai băm nhỏ và 200g tôm tươi băm nhỏ cùng 80g cà rốt bào sợi và 40g nấm mèo ngâm nở thái nhỏ dưới vòi nước mát rồi để thật ráo trên rổ thưa. Dùng dao sắc cắt thái nguyên liệu thành từng khúc hoặc khối vuông đều đặn khoảng 3.5–4cm để khi kho hầm giữ nguyên hình dáng đẹp mắt mà không bị vụn nát. Trộn đều thịt băm, tôm băm, cà rốt, nấm mèo, hành hoa, trứng gà, hạt tiêu và chút hạt nêm làm nhân chả giò.',8,'Cắt miếng thịt/cá dày dặn đồng đều giúp quá trình kho lâu trên lửa nhỏ thớ thịt mềm rục mà vẫn giữ trọn độ mọng ngọt bên trong.'),
(15,2,'Khử mùi tự nhiên & làm săn sạch bề mặt nguyên liệu','Chà nhẹ phần đạm chính trong 300g thịt nạc vai băm nhỏ và 200g tôm tươi băm nhỏ với chút muối hạt, lát gừng đập dập hoặc chần sơ qua nước sôi 90 giây rồi rửa sạch lại bằng nước ấm, để ráo hoàn toàn. Công đoạn này loại bỏ triệt để tạp chất và mùi tanh hôi, giúp nước sốt món Chả giò rế tôm thịt giòn rụm cung đình trong bóng thơm ngon.',6,'Sau khi chần hoặc rửa sạch, để nguyên liệu ráo nước ít nhất 5 phút trước khi ướp để gia vị rút sâu trực tiếp vào từng thớ thịt.'),
(15,3,'Pha hỗn hợp gia vị & ướp thấm chuẩn định lượng','Cho 300g thịt nạc vai băm nhỏ và 200g tôm tươi băm nhỏ vào tô lớn, ướp cùng một nửa hành tím và tỏi băm nhỏ băm nhỏ và định lượng chuẩn 30ml nước mắm chấm nem, đảo nhẹ tay cho gia vị phủ kín đều các mặt. Bọc kín tô và để nguyên liệu nghỉ thấm vị tối thiểu 20 phút ở nhiệt độ phòng (hoặc ngăn mát tủ lạnh). Đặt bánh tráng rế lên thớt sạch, cho lượng nhân vừa phải vào cuộn tròn chặt tay hai đầu.',8,'Ướp đủ tối thiểu 20 phút trước khi bắc lên bếp là chìa khóa để tâm miếng thịt/cá đậm đà đồng nhất với lớp sốt bên ngoài.'),
(15,4,'Thắng nước màu cánh gián & phi dậy hương hành tỏi','Đặt nồi đáy dày lên bếp ở lửa vừa nhỏ, thắng nhẹ 15g đường với 15ml dầu ăn đến khi chuyển sắc nâu cánh gián óng ả thì cho ngay phần hành tím và tỏi băm nhỏ còn lại vào phi thơm lừng. Hương caramel dịu ngọt quyện cùng tinh dầu hành tỏi sả tạo nền màu nâu hổ phách truyền thống đầy cuốn hút.',6,'Canh kỹ khoảnh khắc đường vừa chuyển màu cánh gián là hạ lửa nhỏ nhất ngay để nước màu bóng đẹp mà không bao giờ bị đắng.'),
(15,5,'Đảo săn hai mặt khóa ngọt nguyên liệu chính','Tăng lên lửa vừa lớn, gắp từng miếng trong 300g thịt nạc vai băm nhỏ và 200g tôm tươi băm nhỏ vào nồi đảo đều hoặc trở nhẹ hai mặt trong 4–5 phút cho săn chắc và bám đều lớp màu nâu óng. Khi bề mặt nguyên liệu se vàng thơm phức mới trút phần nước ướp còn lại trong tô vào đun sôi nhẹ. Đun nóng chảo dầu ngập cuộn nem ở lửa vừa, thả chả giò vào chiên lần 1 cho chín tới và se mặt bánh.',8,'Đối với cá kho, chỉ lật cá một lần lúc cá vừa săn mặt trên lửa vừa để khúc cá nguyên vẹn không bị tróc da hay vỡ nát.'),
(15,6,'Kho/om liu riu lửa nhỏ thấm đẫm cùng nước dừa/nước dùng','Chế 300ml dầu ăn để chiên ngập xâm xắp mặt nguyên liệu (xếp thêm rau củ ăn kèm nếu có), đun sôi bùng một dạo hớt sạch bọt rồi hạ ngay về mức lửa nhỏ liu riu nhất. Kho êm đềm không đậy kín nắp để từng thớ nguyên liệu chín mềm thấm đẫm gia vị và nước sốt rút dần sóng sánh. Trước khi ăn chiên lại lần 2 với dầu nóng già để lớp vỏ bánh rế giòn rụm vàng ươm và không ngậm dầu.',13,'Luôn dùng nước sôi hoặc nước dừa ấm khi châm thêm vào nồi kho đang nóng để thịt cá không bị sượng cứng trở lại.'),
(15,7,'Thu sánh nước sốt óng ả & trình bày thưởng thức nóng','Khi nước kho rút còn khoảng 1/3 sánh kẹo óng ánh áo đều quanh nguyên liệu và xiên đũa thấy mềm mọng vừa ý, rắc hành ngò và tiêu xay lên mặt rồi tắt bếp. Múc món Chả giò rế tôm thịt giòn rụm cung đình ra đĩa sâu lòng hoặc niêu đất giữ nhiệt, dọn ăn nóng cùng cơm trắng dẻo thơm cho 4 người.',6,'Giữ lại một lượng nước sốt sánh kẹo vừa đủ dưới đáy nồi để chan cơm hoặc chấm kèm rau luộc sẽ tròn vị đưa cơm gấp bội.');
INSERT INTO `recipe_steps` (`recipe_id`,`step_order`,`title`,`instruction`,`duration_mins`,`tip_note`) VALUES
(16,1,'Sơ chế sạch & cắt thái nguyên liệu nấu canh','Rửa sạch 450g bí đỏ quả gọt vỏ cắt miếng và 200g tôm sú tươi lột vỏ, khử mùi tanh bằng chút muối hạt và gừng đập dập rồi rửa lại thật ráo, cắt miếng vừa ăn dày khoảng 2.5–3cm. Đồng thời gọt rửa sạch rau củ ăn kèm, cắt khúc hoặc bổ múi cau đồng đều để khi nấu chín đều không bị nát. Bí đỏ gọt vỏ, bỏ ruột, rửa sạch rồi thái miếng vuông dày khoảng 2cm.',6,'Phân loại riêng nhóm củ cứng nấu lâu và nhóm rau lá mềm nhanh chín để cho vào nồi theo đúng thứ tự chuẩn đầu bếp.'),
(16,2,'Ướp thấm gia vị nền cho nguyên liệu đạm','Cho phần đạm chính trong 450g bí đỏ quả gọt vỏ cắt miếng và 200g tôm sú tươi lột vỏ vào tô, ướp nhẹ với một nửa lượng 15g hành tỏi băm nhuyễn và 20ml nước mắm ngon trong khoảng 10 phút. Đảo nhẹ tay cho gia vị áo đều bề mặt giúp miếng thịt, cá săn chắc và đậm đà từ bên trong khi thả vào nước canh. Tôm tươi bóc vỏ, rút chỉ đen, giã dập nhẹ rồi ướp cùng chút hành băm, hạt nêm và tiêu trong 10 phút.',6,'Không ướp quá mặn ở bước này để giữ vị thanh mát tự nhiên của nước canh sau khi hoàn tất.'),
(16,3,'Phi thơm hành tỏi & xào săn khóa ngọt nguyên liệu','Đặt nồi canh lên bếp ở lửa vừa, làm nóng 15ml dầu ăn rồi phi thơm phần 15g hành tỏi băm nhuyễn còn lại đến khi dậy mùi vàng óng. Trút nguyên liệu chính đã ướp vào đảo săn 2–3 phút cho bề mặt se lại, khóa trọn nước ngọt tự nhiên bên trong thớ thịt.',5,'Xào săn nguyên liệu đạm với hành tỏi phi trước khi đổ nước sôi giúp nước canh thơm ngọt đậm đà mà không hề tanh.'),
(16,4,'Đun sôi nước canh & hớt bọt giữ độ trong veo','Chế khoảng 1.1–1.3 lít nước (kết hợp 15ml dầu ăn) vào nồi, bật lửa lớn đun đến khi sôi bùng rồi hạ ngay về lửa vừa. Dùng muôi hớt sạch lớp bọt đầu nổi lên trên mặt nước để nồi canh Canh bí đỏ hầm tôm tươi ngọt lịm đạt độ trong thanh đẹp mắt. Phi thơm hành tỏi băm trong nồi với dầu ăn, trút tôm vào xào săn chín hồng.',7,'Sử dụng nước ấm hoặc nước sôi khi chế vào cá tươi sẽ giúp cá không bao giờ bị tanh nồng dù để nguội.'),
(16,5,'Thả rau củ theo độ chín & cân chỉnh định lượng vị','Lần lượt cho rau củ ăn kèm vào nồi canh đang sôi vừa (nhóm củ quả lâu chín cho trước 5–7 phút, nhóm rau mềm cho sau 1–2 phút). Nêm phần 20ml nước mắm ngon còn lại, khuấy nhẹ và nếm thử thấy vị chua thanh hoặc ngọt dịu cân bằng đúng khẩu phần 4 người.',7,'Không đậy kín nắp vung sau khi đã thả các loại rau xanh vào nồi để giữ màu xanh ngọc tươi tắn hấp dẫn.'),
(16,6,'Điểm hương rau thơm & múc canh dọn nóng','Khi toàn bộ nguyên liệu vừa chín tới mềm ngọt, rắc ngay 30g ngò gai và rau ngổ vào nồi rồi tắt bếp liền tay để giữ trọn tinh dầu thơm mát. Múc canh nóng hổi ra tô lớn, rắc thêm chút tiêu xay hoặc tỏi phi vàng và dùng ngay với cơm nóng. Đổ 1 lít nước lọc vào đun sôi bùng, cho bí đỏ vào hầm lửa vừa khoảng 12 phút cho bí chín mềm bở.',4,'Các loại rau thơm như thì là, ngò gai, rau om hay lá lốt chỉ nên thả ngay khoảnh khắc tắt bếp để hương thơm bùng nổ nhất.'),
(17,1,'Vo đãi & ngâm nở hạt gạo/nếp đúng thời gian chuẩn','Đong chuẩn lượng gạo/nếp trong 320g gạo tẻ và 500g thịt gà (ức), vo nhẹ tay 2–3 nước cho sạch bụi cám mà không làm mất lớp dưỡng chất ngoài vỏ hạt, để ráo trên rổ. Nếu là nếp đồ xôi, ngâm trước trong nước ấm hoặc nước màu thảo mộc tự nhiên cùng 3g muối để hạt nếp ngậm đủ nước căng tròn. Rửa gà, để ráo; xát chút muối rồi tráng sạch. Vo gạo, để ráo; thái mỏng hành tây và rau răm.',11,'Xóc nhẹ một nhúm muối tinh vào gạo nếp sau khi để ráo giúp hạt xôi cơm khi chín có vị đậm dịu và bóng dẻo tự nhiên.'),
(17,2,'Sơ chế & tẩm ướp phần nhân thịt, đậu ăn kèm','Làm sạch và chuẩn bị phần nguyên liệu ăn kèm gồm 100g hành tây cùng 100g hành tây, cắt thái gọn gàng đúng quy cách món Cơm gà Hội An. Ướp thấm nhân với 25ml nước mắm, 1 quả chanh, 2g tiêu và 4g muối trong 15 phút để khi chế biến tạo điểm nhấn đậm đà quyện cùng hạt cơm xôi dẻo thơm. Cho gà vào nồi với 1 lít nước, một nửa hành tây và chút muối. Đun sôi rồi hạ lửa, luộc đến khi phần dày nhất đạt 74°C; vớt gà, giữ nước luộc.',10,'Chuẩn bị song song phần nhân topping trong lúc chờ nấu cơm/đồ xôi giúp tiết kiệm thời gian và mọi thành phần cùng nóng hổi.'),
(17,3,'Nấu cơm / đồ xôi canh chuẩn nhiệt & độ ẩm hạt','Cho gạo vào nấu với lượng nước luộc gà/nước dùng vừa khéo hoặc dàn đều nếp vào xửng hấp đã sôi sùng sục, chọc vài lỗ thoáng hơi trên bề mặt nếp. Duy trì lửa vừa ổn định để hơi nóng xuyên đều giúp hạt chín dẻo từ lõi mà bên ngoài vẫn ráo tơi óng ả.',15,'Lau khô nước đọng dưới nắp vung mỗi 10 phút khi đồ xôi giúp mặt xôi không bao giờ bị nhão ướt ở rìa xửng.'),
(17,4,'Chế biến chín vàng thơm phần nhân & mỡ hành phi','Bắc chảo lên lửa vừa, phi vàng giòn 4g nghệ lấy dầu thơm rồi chế biến chín tới phần nhân 100g hành tây cho lên màu bóng đẹp và dậy mùi đặc trưng. Trường hợp có đậu xanh hoặc trứng chả kèm theo, chế biến riêng từng phần để giữ trọn sắc màu và hương vị tinh tế. Trộn gạo với nghệ, cho vào nồi cùng khoảng 400 ml nước luộc gà đã lọc. Nấu đến khi hạt cơm chín tơi; nếu dùng nồi cơm điện, giảm nước theo loại gạo.',11,'Rưới một thìa mỡ gà hoặc dầu hành phi vào xới nhẹ lúc cơm/xôi vừa chín tới giúp từng hạt căng bóng mượt mà lâu khô.'),
(17,5,'Pha nước mắm sốt rưới / đồ chua cân bằng vị béo','Pha chén nước sốt chan từ 25ml nước mắm, 1 quả chanh, 2g tiêu và 4g muối khuấy tan sánh nhẹ hoặc trộn nhanh phần hành tím/dưa góp chua ngọt giòn mát đi kèm. Cân chỉnh hài hòa vị mặn ngọt chua thanh để tôn lên độ bùi dẻo của hạt gạo nếp Việt Nam.',7,'Nước mắm ăn kèm các món cơm gà, cơm tấm hay cơm trộn nên nấu sôi nhẹ với đường cho hơi sánh kẹo sẽ bám hạt cơm ngon hơn hẳn.'),
(17,6,'Đơm khuôn đầy đặn, xếp nhân & thưởng thức nóng','Đơm cơm hoặc xôi nóng vào chén ép nhẹ rồi úp tròn ra 4 đĩa, xếp đều các lớp nhân, đồ chua và rắc 20g rau răm và 15g hành lá lên trên cùng. Rưới nhẹ mỡ hành/nước sốt bóng bẩy và thưởng thức ngay khi hạt cơm xôi còn nóng dẻo thơm lừng. Xé gà khi còn ấm, trộn với hành tây, rau răm, nước mắm và nước cốt chanh. Nêm vừa miệng, rắc tiêu và ăn với cơm nóng.',6,'Tráng mỏng một lớp nước lọc hoặc dầu ăn vào lòng chén trước khi đơm cơm giúp úp ra đĩa tròn trịa sắc nét không dính hạt.'),
(18,1,'Vo đãi & ngâm nở hạt gạo/nếp đúng thời gian chuẩn','Đong chuẩn lượng gạo/nếp trong 600g cơm nguội và 250g thịt bò, vo nhẹ tay 2–3 nước cho sạch bụi cám mà không làm mất lớp dưỡng chất ngoài vỏ hạt, để ráo trên rổ. Nếu là nếp đồ xôi, ngâm trước trong nước ấm hoặc nước màu thảo mộc tự nhiên cùng 3g muối để hạt nếp ngậm đủ nước căng tròn. Tách cơm nguội cho tơi. Rửa dưa cải chua hai lần, vắt nhẹ và cắt khúc; thái bò mỏng, ướp một nửa nước mắm cùng tiêu.',6,'Xóc nhẹ một nhúm muối tinh vào gạo nếp sau khi để ráo giúp hạt xôi cơm khi chín có vị đậm dịu và bóng dẻo tự nhiên.'),
(18,2,'Sơ chế & tẩm ướp phần nhân thịt, đậu ăn kèm','Làm sạch và chuẩn bị phần nguyên liệu ăn kèm gồm 2 quả trứng gà cùng 180g dưa cải chua, cắt thái gọn gàng đúng quy cách món Cơm rang dưa bò. Ướp thấm nhân với 15ml nước mắm và 2g tiêu trong 15 phút để khi chế biến tạo điểm nhấn đậm đà quyện cùng hạt cơm xôi dẻo thơm. Làm nóng chảo với ít dầu, đảo bò trên lửa lớn vừa chín tới rồi trút ra. Phi tỏi, xào dưa 3–4 phút cho ráo nước.',6,'Chuẩn bị song song phần nhân topping trong lúc chờ nấu cơm/đồ xôi giúp tiết kiệm thời gian và mọi thành phần cùng nóng hổi.'),
(18,3,'Nấu cơm / đồ xôi canh chuẩn nhiệt & độ ẩm hạt','Cho gạo vào nấu với lượng nước luộc gà/nước dùng vừa khéo hoặc dàn đều nếp vào xửng hấp đã sôi sùng sục, chọc vài lỗ thoáng hơi trên bề mặt nếp. Duy trì lửa vừa ổn định để hơi nóng xuyên đều giúp hạt chín dẻo từ lõi mà bên ngoài vẫn ráo tơi óng ả.',9,'Lau khô nước đọng dưới nắp vung mỗi 10 phút khi đồ xôi giúp mặt xôi không bao giờ bị nhão ướt ở rìa xửng.'),
(18,4,'Chế biến chín vàng thơm phần nhân & mỡ hành phi','Bắc chảo lên lửa vừa, phi vàng giòn 10g tỏi lấy dầu thơm rồi chế biến chín tới phần nhân 2 quả trứng gà cho lên màu bóng đẹp và dậy mùi đặc trưng. Trường hợp có đậu xanh hoặc trứng chả kèm theo, chế biến riêng từng phần để giữ trọn sắc màu và hương vị tinh tế. Thêm dầu nếu chảo khô, cho cơm vào dàn đều và đảo đến khi nóng, hạt tơi. Gạt cơm sang bên, đánh trứng vào chảo rồi đảo chín.',6,'Rưới một thìa mỡ gà hoặc dầu hành phi vào xới nhẹ lúc cơm/xôi vừa chín tới giúp từng hạt căng bóng mượt mà lâu khô.'),
(18,5,'Pha nước mắm sốt rưới / đồ chua cân bằng vị béo','Pha chén nước sốt chan từ 15ml nước mắm và 2g tiêu khuấy tan sánh nhẹ hoặc trộn nhanh phần hành tím/dưa góp chua ngọt giòn mát đi kèm. Cân chỉnh hài hòa vị mặn ngọt chua thanh để tôn lên độ bùi dẻo của hạt gạo nếp Việt Nam.',4,'Nước mắm ăn kèm các món cơm gà, cơm tấm hay cơm trộn nên nấu sôi nhẹ với đường cho hơi sánh kẹo sẽ bám hạt cơm ngon hơn hẳn.'),
(18,6,'Đơm khuôn đầy đặn, xếp nhân & thưởng thức nóng','Đơm cơm hoặc xôi nóng vào chén ép nhẹ rồi úp tròn ra 4 đĩa, xếp đều các lớp nhân, đồ chua và rắc 15g hành lá lên trên cùng. Rưới nhẹ mỡ hành/nước sốt bóng bẩy và thưởng thức ngay khi hạt cơm xôi còn nóng dẻo thơm lừng. Cho bò trở lại cùng phần nước mắm còn lại, đảo nhanh 1–2 phút. Nếm độ mặn của dưa trước khi nêm thêm, rắc hành lá và tiêu.',4,'Tráng mỏng một lớp nước lọc hoặc dầu ăn vào lòng chén trước khi đơm cơm giúp úp ra đĩa tròn trịa sắc nét không dính hạt.'),
(19,1,'Sơ chế sạch & cắt thái nguyên liệu đúng kích cỡ','Rửa sạch 700g thịt bò bắp và 250g cà rốt cùng 4 ổ bánh mì và 250g cà chua dưới vòi nước mát rồi để thật ráo trên rổ thưa. Dùng dao sắc cắt thái nguyên liệu thành từng khúc hoặc khối vuông đều đặn khoảng 3.5–4cm để khi kho hầm giữ nguyên hình dáng đẹp mắt mà không bị vụn nát. Cắt bò khối 3–4 cm. Trộn với bột cà ri, nước mắm và hành tím băm; để ướp ít nhất 20 phút.',18,'Cắt miếng thịt/cá dày dặn đồng đều giúp quá trình kho lâu trên lửa nhỏ thớ thịt mềm rục mà vẫn giữ trọn độ mọng ngọt bên trong.'),
(19,2,'Khử mùi tự nhiên & làm săn sạch bề mặt nguyên liệu','Chà nhẹ phần đạm chính trong 700g thịt bò bắp và 250g cà rốt với chút muối hạt, lát gừng đập dập hoặc chần sơ qua nước sôi 90 giây rồi rửa sạch lại bằng nước ấm, để ráo hoàn toàn. Công đoạn này loại bỏ triệt để tạp chất và mùi tanh hôi, giúp nước sốt món Bò kho bánh mì trong bóng thơm ngon.',14,'Sau khi chần hoặc rửa sạch, để nguyên liệu ráo nước ít nhất 5 phút trước khi ướp để gia vị rút sâu trực tiếp vào từng thớ thịt.'),
(19,3,'Pha hỗn hợp gia vị & ướp thấm chuẩn định lượng','Cho 700g thịt bò bắp và 250g cà rốt vào tô lớn, ướp cùng một nửa 2 cây sả và 30g hành tím băm nhỏ và định lượng chuẩn 8g bột cà ri và 25ml nước mắm, đảo nhẹ tay cho gia vị phủ kín đều các mặt. Bọc kín tô và để nguyên liệu nghỉ thấm vị tối thiểu 20 phút ở nhiệt độ phòng (hoặc ngăn mát tủ lạnh). Đập dập sả, cắt khúc. Làm nóng nồi với chút dầu, áp chảo bò theo mẻ cho săn mặt; thêm cà chua và đảo đến khi mềm.',19,'Ướp đủ tối thiểu 20 phút trước khi bắc lên bếp là chìa khóa để tâm miếng thịt/cá đậm đà đồng nhất với lớp sốt bên ngoài.'),
(19,4,'Thắng nước màu cánh gián & phi dậy hương hành tỏi','Đặt nồi đáy dày lên bếp ở lửa vừa nhỏ, thắng nhẹ 15g đường với 15ml dầu ăn đến khi chuyển sắc nâu cánh gián óng ả thì cho ngay phần 2 cây sả và 30g hành tím còn lại vào phi thơm lừng. Hương caramel dịu ngọt quyện cùng tinh dầu hành tỏi sả tạo nền màu nâu hổ phách truyền thống đầy cuốn hút.',12,'Canh kỹ khoảnh khắc đường vừa chuyển màu cánh gián là hạ lửa nhỏ nhất ngay để nước màu bóng đẹp mà không bao giờ bị đắng.'),
(19,5,'Đảo săn hai mặt khóa ngọt nguyên liệu chính','Tăng lên lửa vừa lớn, gắp từng miếng trong 700g thịt bò bắp và 250g cà rốt vào nồi đảo đều hoặc trở nhẹ hai mặt trong 4–5 phút cho săn chắc và bám đều lớp màu nâu óng. Khi bề mặt nguyên liệu se vàng thơm phức mới trút phần nước ướp còn lại trong tô vào đun sôi nhẹ. Cho sả và nước dừa vào, thêm nước nóng vừa ngập thịt. Đậy hé nắp, hầm lửa nhỏ 70–80 phút; thêm cà rốt ở 25 phút cuối.',18,'Đối với cá kho, chỉ lật cá một lần lúc cá vừa săn mặt trên lửa vừa để khúc cá nguyên vẹn không bị tróc da hay vỡ nát.'),
(19,6,'Kho/om liu riu lửa nhỏ thấm đẫm cùng nước dừa/nước dùng','Chế 12ml dầu ăn và 500ml nước dừa tươi xâm xắp mặt nguyên liệu (xếp thêm rau củ ăn kèm nếu có), đun sôi bùng một dạo hớt sạch bọt rồi hạ ngay về mức lửa nhỏ liu riu nhất. Kho êm đềm không đậy kín nắp để từng thớ nguyên liệu chín mềm thấm đẫm gia vị và nước sốt rút dần sóng sánh. Khi bò mềm nhưng còn nguyên miếng, nếm lại nước kho, chỉnh mặn ngọt. Múc ra bát, ăn nóng với bánh mì.',32,'Luôn dùng nước sôi hoặc nước dừa ấm khi châm thêm vào nồi kho đang nóng để thịt cá không bị sượng cứng trở lại.'),
(19,7,'Thu sánh nước sốt óng ả & trình bày thưởng thức nóng','Khi nước kho rút còn khoảng 1/3 sánh kẹo óng ánh áo đều quanh nguyên liệu và xiên đũa thấy mềm mọng vừa ý, rắc hành ngò và tiêu xay lên mặt rồi tắt bếp. Múc món Bò kho bánh mì ra đĩa sâu lòng hoặc niêu đất giữ nhiệt, dọn ăn nóng cùng cơm trắng dẻo thơm cho 4 người.',12,'Giữ lại một lượng nước sốt sánh kẹo vừa đủ dưới đáy nồi để chan cơm hoặc chấm kèm rau luộc sẽ tròn vị đưa cơm gấp bội.');
INSERT INTO `recipe_steps` (`recipe_id`,`step_order`,`title`,`instruction`,`duration_mins`,`tip_note`) VALUES
(20,1,'Sơ chế sạch & cắt thái nguyên liệu đúng kích cỡ','Rửa sạch 650g thịt bò bắp và 200g cà rốt cùng 250g khoai tây, 120ml rượu vang đỏ và 120g hành tây dưới vòi nước mát rồi để thật ráo trên rổ thưa. Dùng dao sắc cắt thái nguyên liệu thành từng khúc hoặc khối vuông đều đặn khoảng 3.5–4cm để khi kho hầm giữ nguyên hình dáng đẹp mắt mà không bị vụn nát. Cắt bò khối vừa ăn, trộn với một nửa rượu vang, muối và tiêu; để 20 phút.',15,'Cắt miếng thịt/cá dày dặn đồng đều giúp quá trình kho lâu trên lửa nhỏ thớ thịt mềm rục mà vẫn giữ trọn độ mọng ngọt bên trong.'),
(20,2,'Khử mùi tự nhiên & làm săn sạch bề mặt nguyên liệu','Chà nhẹ phần đạm chính trong 650g thịt bò bắp và 200g cà rốt với chút muối hạt, lát gừng đập dập hoặc chần sơ qua nước sôi 90 giây rồi rửa sạch lại bằng nước ấm, để ráo hoàn toàn. Công đoạn này loại bỏ triệt để tạp chất và mùi tanh hôi, giúp nước sốt món Bò sốt vang trong bóng thơm ngon.',12,'Sau khi chần hoặc rửa sạch, để nguyên liệu ráo nước ít nhất 5 phút trước khi ướp để gia vị rút sâu trực tiếp vào từng thớ thịt.'),
(20,3,'Pha hỗn hợp gia vị & ướp thấm chuẩn định lượng','Cho 650g thịt bò bắp và 200g cà rốt vào tô lớn, ướp cùng một nửa hành tím và tỏi băm nhỏ băm nhỏ và định lượng chuẩn 3g muối và 2g tiêu, đảo nhẹ tay cho gia vị phủ kín đều các mặt. Bọc kín tô và để nguyên liệu nghỉ thấm vị tối thiểu 20 phút ở nhiệt độ phòng (hoặc ngăn mát tủ lạnh). Đun chảy bơ, xào hành tây và cà chua đến khi mềm. Rắc bột mì, đảo 1 phút rồi rót phần vang còn lại và 500 ml nước nóng.',16,'Ướp đủ tối thiểu 20 phút trước khi bắc lên bếp là chìa khóa để tâm miếng thịt/cá đậm đà đồng nhất với lớp sốt bên ngoài.'),
(20,4,'Thắng nước màu cánh gián & phi dậy hương hành tỏi','Đặt nồi đáy dày lên bếp ở lửa vừa nhỏ, thắng nhẹ 15g đường với 15ml dầu ăn đến khi chuyển sắc nâu cánh gián óng ả thì cho ngay phần hành tím và tỏi băm nhỏ còn lại vào phi thơm lừng. Hương caramel dịu ngọt quyện cùng tinh dầu hành tỏi sả tạo nền màu nâu hổ phách truyền thống đầy cuốn hút.',11,'Canh kỹ khoảnh khắc đường vừa chuyển màu cánh gián là hạ lửa nhỏ nhất ngay để nước màu bóng đẹp mà không bao giờ bị đắng.'),
(20,5,'Đảo săn hai mặt khóa ngọt nguyên liệu chính','Tăng lên lửa vừa lớn, gắp từng miếng trong 650g thịt bò bắp và 200g cà rốt vào nồi đảo đều hoặc trở nhẹ hai mặt trong 4–5 phút cho săn chắc và bám đều lớp màu nâu óng. Khi bề mặt nguyên liệu se vàng thơm phức mới trút phần nước ướp còn lại trong tô vào đun sôi nhẹ. Cho bò vào nồi, đun sôi rồi hạ nhỏ lửa, hầm khoảng 60 phút. Thêm cà rốt và khoai tây, nấu thêm 20–25 phút đến khi vừa mềm.',15,'Đối với cá kho, chỉ lật cá một lần lúc cá vừa săn mặt trên lửa vừa để khúc cá nguyên vẹn không bị tróc da hay vỡ nát.'),
(20,6,'Kho/om liu riu lửa nhỏ thấm đẫm cùng nước dừa/nước dùng','Chế 20g bơ lạt xâm xắp mặt nguyên liệu (xếp thêm 250g khoai tây, 120ml rượu vang đỏ và 120g hành tây nếu có), đun sôi bùng một dạo hớt sạch bọt rồi hạ ngay về mức lửa nhỏ liu riu nhất. Kho êm đềm không đậy kín nắp để từng thớ nguyên liệu chín mềm thấm đẫm gia vị và nước sốt rút dần sóng sánh. Nếm sốt và chỉnh gia vị. Nếu sốt quá loãng, mở nắp đun thêm vài phút; dùng nóng.',30,'Luôn dùng nước sôi hoặc nước dừa ấm khi châm thêm vào nồi kho đang nóng để thịt cá không bị sượng cứng trở lại.'),
(20,7,'Thu sánh nước sốt óng ả & trình bày thưởng thức nóng','Khi nước kho rút còn khoảng 1/3 sánh kẹo óng ánh áo đều quanh nguyên liệu và xiên đũa thấy mềm mọng vừa ý, rắc hành ngò và tiêu xay lên mặt rồi tắt bếp. Múc món Bò sốt vang ra đĩa sâu lòng hoặc niêu đất giữ nhiệt, dọn ăn nóng cùng cơm trắng dẻo thơm cho 4 người.',11,'Giữ lại một lượng nước sốt sánh kẹo vừa đủ dưới đáy nồi để chan cơm hoặc chấm kèm rau luộc sẽ tròn vị đưa cơm gấp bội.'),
(21,1,'Sơ chế sạch & cắt thái nguyên liệu đúng kích cỡ','Rửa sạch 500g thịt ba chỉ cùng các nguyên liệu phối kèm dưới vòi nước mát rồi để thật ráo trên rổ thưa. Dùng dao sắc cắt thái nguyên liệu thành từng khúc hoặc khối vuông đều đặn khoảng 3.5–4cm để khi kho hầm giữ nguyên hình dáng đẹp mắt mà không bị vụn nát. Rửa thịt, thấm khô rồi thái lát dày khoảng 5 mm. Băm hành tím; khuấy nước mắm, đường và nước thành hỗn hợp.',5,'Cắt miếng thịt/cá dày dặn đồng đều giúp quá trình kho lâu trên lửa nhỏ thớ thịt mềm rục mà vẫn giữ trọn độ mọng ngọt bên trong.'),
(21,2,'Khử mùi tự nhiên & làm săn sạch bề mặt nguyên liệu','Chà nhẹ phần đạm chính trong 500g thịt ba chỉ với chút muối hạt, lát gừng đập dập hoặc chần sơ qua nước sôi 90 giây rồi rửa sạch lại bằng nước ấm, để ráo hoàn toàn. Công đoạn này loại bỏ triệt để tạp chất và mùi tanh hôi, giúp nước sốt món Thịt rang cháy cạnh trong bóng thơm ngon.',4,'Sau khi chần hoặc rửa sạch, để nguyên liệu ráo nước ít nhất 5 phút trước khi ướp để gia vị rút sâu trực tiếp vào từng thớ thịt.'),
(21,3,'Pha hỗn hợp gia vị & ướp thấm chuẩn định lượng','Cho 500g thịt ba chỉ vào tô lớn, ướp cùng một nửa 25g hành tím băm nhỏ và định lượng chuẩn 25ml nước mắm, 12g đường, 2g tiêu và 3g muối, đảo nhẹ tay cho gia vị phủ kín đều các mặt. Bọc kín tô và để nguyên liệu nghỉ thấm vị tối thiểu 20 phút ở nhiệt độ phòng (hoặc ngăn mát tủ lạnh). Cho thịt vào chảo nguội, bật lửa vừa để mỡ tự tiết ra. Trở từng miếng đến khi hai mặt vàng xém; chắt bớt mỡ nếu quá nhiều.',5,'Ướp đủ tối thiểu 20 phút trước khi bắc lên bếp là chìa khóa để tâm miếng thịt/cá đậm đà đồng nhất với lớp sốt bên ngoài.'),
(21,4,'Thắng nước màu cánh gián & phi dậy hương hành tỏi','Đặt nồi đáy dày lên bếp ở lửa vừa nhỏ, thắng nhẹ 15g đường với 15ml dầu ăn đến khi chuyển sắc nâu cánh gián óng ả thì cho ngay phần 25g hành tím còn lại vào phi thơm lừng. Hương caramel dịu ngọt quyện cùng tinh dầu hành tỏi sả tạo nền màu nâu hổ phách truyền thống đầy cuốn hút.',4,'Canh kỹ khoảnh khắc đường vừa chuyển màu cánh gián là hạ lửa nhỏ nhất ngay để nước màu bóng đẹp mà không bao giờ bị đắng.'),
(21,5,'Đảo săn hai mặt khóa ngọt nguyên liệu chính','Tăng lên lửa vừa lớn, gắp từng miếng trong 500g thịt ba chỉ vào nồi đảo đều hoặc trở nhẹ hai mặt trong 4–5 phút cho săn chắc và bám đều lớp màu nâu óng. Khi bề mặt nguyên liệu se vàng thơm phức mới trút phần nước ướp còn lại trong tô vào đun sôi nhẹ. Thêm hành tím vào đảo thơm, rót hỗn hợp nước mắm. Hạ lửa nhỏ, đảo đều để sốt bám quanh thịt và cạn sánh.',5,'Đối với cá kho, chỉ lật cá một lần lúc cá vừa săn mặt trên lửa vừa để khúc cá nguyên vẹn không bị tróc da hay vỡ nát.'),
(21,6,'Kho/om liu riu lửa nhỏ thấm đẫm cùng nước dừa/nước dùng','Chế 40ml nước lọc xâm xắp mặt nguyên liệu (xếp thêm rau củ ăn kèm nếu có), đun sôi bùng một dạo hớt sạch bọt rồi hạ ngay về mức lửa nhỏ liu riu nhất. Kho êm đềm không đậy kín nắp để từng thớ nguyên liệu chín mềm thấm đẫm gia vị và nước sốt rút dần sóng sánh. Tắt bếp khi cạnh thịt nâu vàng, rắc tiêu và hành lá. Nếm trước khi thêm muối vì nước mắm đã mặn.',8,'Luôn dùng nước sôi hoặc nước dừa ấm khi châm thêm vào nồi kho đang nóng để thịt cá không bị sượng cứng trở lại.'),
(21,7,'Thu sánh nước sốt óng ả & trình bày thưởng thức nóng','Khi nước kho rút còn khoảng 1/3 sánh kẹo óng ánh áo đều quanh nguyên liệu và xiên đũa thấy mềm mọng vừa ý, rắc 15g hành lá lên mặt rồi tắt bếp. Múc món Thịt rang cháy cạnh ra đĩa sâu lòng hoặc niêu đất giữ nhiệt, dọn ăn nóng cùng cơm trắng dẻo thơm cho 4 người.',4,'Giữ lại một lượng nước sốt sánh kẹo vừa đủ dưới đáy nồi để chan cơm hoặc chấm kèm rau luộc sẽ tròn vị đưa cơm gấp bội.'),
(22,1,'Sơ chế sạch & cắt thái nguyên liệu đúng kích cỡ','Rửa sạch 700g sườn non cùng các nguyên liệu phối kèm dưới vòi nước mát rồi để thật ráo trên rổ thưa. Dùng dao sắc cắt thái nguyên liệu thành từng khúc hoặc khối vuông đều đặn khoảng 3.5–4cm để khi kho hầm giữ nguyên hình dáng đẹp mắt mà không bị vụn nát. Chặt sườn miếng vừa ăn, chần 2 phút rồi rửa sạch. Ướp với nước mắm, tiêu và một nửa hành tỏi trong 15 phút.',8,'Cắt miếng thịt/cá dày dặn đồng đều giúp quá trình kho lâu trên lửa nhỏ thớ thịt mềm rục mà vẫn giữ trọn độ mọng ngọt bên trong.'),
(22,2,'Khử mùi tự nhiên & làm săn sạch bề mặt nguyên liệu','Chà nhẹ phần đạm chính trong 700g sườn non với chút muối hạt, lát gừng đập dập hoặc chần sơ qua nước sôi 90 giây rồi rửa sạch lại bằng nước ấm, để ráo hoàn toàn. Công đoạn này loại bỏ triệt để tạp chất và mùi tanh hôi, giúp nước sốt món Sườn non ram mặn ngọt trong bóng thơm ngon.',6,'Sau khi chần hoặc rửa sạch, để nguyên liệu ráo nước ít nhất 5 phút trước khi ướp để gia vị rút sâu trực tiếp vào từng thớ thịt.'),
(22,3,'Pha hỗn hợp gia vị & ướp thấm chuẩn định lượng','Cho 700g sườn non vào tô lớn, ướp cùng một nửa 25g hành tím và 10g tỏi băm nhỏ và định lượng chuẩn 30ml nước mắm, 18g đường và 2g tiêu, đảo nhẹ tay cho gia vị phủ kín đều các mặt. Bọc kín tô và để nguyên liệu nghỉ thấm vị tối thiểu 20 phút ở nhiệt độ phòng (hoặc ngăn mát tủ lạnh). Làm nóng chút dầu, xếp sườn thành một lớp và áp chảo đến khi vàng nhạt hai mặt; làm theo mẻ để sườn không ra nước.',8,'Ướp đủ tối thiểu 20 phút trước khi bắc lên bếp là chìa khóa để tâm miếng thịt/cá đậm đà đồng nhất với lớp sốt bên ngoài.'),
(22,4,'Thắng nước màu cánh gián & phi dậy hương hành tỏi','Đặt nồi đáy dày lên bếp ở lửa vừa nhỏ, thắng nhẹ 15g đường với 15ml dầu ăn đến khi chuyển sắc nâu cánh gián óng ả thì cho ngay phần 25g hành tím và 10g tỏi còn lại vào phi thơm lừng. Hương caramel dịu ngọt quyện cùng tinh dầu hành tỏi sả tạo nền màu nâu hổ phách truyền thống đầy cuốn hút.',6,'Canh kỹ khoảnh khắc đường vừa chuyển màu cánh gián là hạ lửa nhỏ nhất ngay để nước màu bóng đẹp mà không bao giờ bị đắng.'),
(22,5,'Đảo săn hai mặt khóa ngọt nguyên liệu chính','Tăng lên lửa vừa lớn, gắp từng miếng trong 700g sườn non vào nồi đảo đều hoặc trở nhẹ hai mặt trong 4–5 phút cho săn chắc và bám đều lớp màu nâu óng. Khi bề mặt nguyên liệu se vàng thơm phức mới trút phần nước ướp còn lại trong tô vào đun sôi nhẹ. Thắng đường với 1 thìa nước đến màu hổ phách, cho phần hành tỏi còn lại vào đảo nhanh. Thêm sườn và nước dừa, đậy nắp ram nhỏ lửa 25 phút.',8,'Đối với cá kho, chỉ lật cá một lần lúc cá vừa săn mặt trên lửa vừa để khúc cá nguyên vẹn không bị tróc da hay vỡ nát.'),
(22,6,'Kho/om liu riu lửa nhỏ thấm đẫm cùng nước dừa/nước dùng','Chế 250ml nước dừa tươi và 10ml dầu ăn xâm xắp mặt nguyên liệu (xếp thêm rau củ ăn kèm nếu có), đun sôi bùng một dạo hớt sạch bọt rồi hạ ngay về mức lửa nhỏ liu riu nhất. Kho êm đềm không đậy kín nắp để từng thớ nguyên liệu chín mềm thấm đẫm gia vị và nước sốt rút dần sóng sánh. Mở nắp, đảo sườn đến khi nước sốt bám bóng. Nếm lại, tắt bếp và rắc tiêu; đảm bảo sườn mềm chín hoàn toàn.',13,'Luôn dùng nước sôi hoặc nước dừa ấm khi châm thêm vào nồi kho đang nóng để thịt cá không bị sượng cứng trở lại.'),
(22,7,'Thu sánh nước sốt óng ả & trình bày thưởng thức nóng','Khi nước kho rút còn khoảng 1/3 sánh kẹo óng ánh áo đều quanh nguyên liệu và xiên đũa thấy mềm mọng vừa ý, rắc hành ngò và tiêu xay lên mặt rồi tắt bếp. Múc món Sườn non ram mặn ngọt ra đĩa sâu lòng hoặc niêu đất giữ nhiệt, dọn ăn nóng cùng cơm trắng dẻo thơm cho 4 người.',6,'Giữ lại một lượng nước sốt sánh kẹo vừa đủ dưới đáy nồi để chan cơm hoặc chấm kèm rau luộc sẽ tròn vị đưa cơm gấp bội.'),
(23,1,'Sơ chế sạch & cắt thái nguyên liệu đúng kích cỡ','Rửa sạch 600g cá basa và 150g thịt ba chỉ cùng các nguyên liệu phối kèm dưới vòi nước mát rồi để thật ráo trên rổ thưa. Dùng dao sắc cắt thái nguyên liệu thành từng khúc hoặc khối vuông đều đặn khoảng 3.5–4cm để khi kho hầm giữ nguyên hình dáng đẹp mắt mà không bị vụn nát. Cắt cá khúc dày, thấm khô. Ướp cá với nước mắm, tiêu và hành tím băm trong 15 phút; thái ba chỉ lát mỏng.',8,'Cắt miếng thịt/cá dày dặn đồng đều giúp quá trình kho lâu trên lửa nhỏ thớ thịt mềm rục mà vẫn giữ trọn độ mọng ngọt bên trong.'),
(23,2,'Khử mùi tự nhiên & làm săn sạch bề mặt nguyên liệu','Chà nhẹ phần đạm chính trong 600g cá basa và 150g thịt ba chỉ với chút muối hạt, lát gừng đập dập hoặc chần sơ qua nước sôi 90 giây rồi rửa sạch lại bằng nước ấm, để ráo hoàn toàn. Công đoạn này loại bỏ triệt để tạp chất và mùi tanh hôi, giúp nước sốt món Cá kho tộ trong bóng thơm ngon.',6,'Sau khi chần hoặc rửa sạch, để nguyên liệu ráo nước ít nhất 5 phút trước khi ướp để gia vị rút sâu trực tiếp vào từng thớ thịt.'),
(23,3,'Pha hỗn hợp gia vị & ướp thấm chuẩn định lượng','Cho 600g cá basa và 150g thịt ba chỉ vào tô lớn, ướp cùng một nửa 25g hành tím băm nhỏ và định lượng chuẩn 35ml nước mắm, 15g đường, 3g tiêu và 1 quả ớt, đảo nhẹ tay cho gia vị phủ kín đều các mặt. Bọc kín tô và để nguyên liệu nghỉ thấm vị tối thiểu 20 phút ở nhiệt độ phòng (hoặc ngăn mát tủ lạnh). Thắng đường trong nồi đất ở lửa nhỏ đến màu hổ phách, thêm 2 thìa nước nóng cẩn thận để dừng caramel.',8,'Ướp đủ tối thiểu 20 phút trước khi bắc lên bếp là chìa khóa để tâm miếng thịt/cá đậm đà đồng nhất với lớp sốt bên ngoài.'),
(23,4,'Thắng nước màu cánh gián & phi dậy hương hành tỏi','Đặt nồi đáy dày lên bếp ở lửa vừa nhỏ, thắng nhẹ 15g đường với 15ml dầu ăn đến khi chuyển sắc nâu cánh gián óng ả thì cho ngay phần 25g hành tím còn lại vào phi thơm lừng. Hương caramel dịu ngọt quyện cùng tinh dầu hành tỏi sả tạo nền màu nâu hổ phách truyền thống đầy cuốn hút.',6,'Canh kỹ khoảnh khắc đường vừa chuyển màu cánh gián là hạ lửa nhỏ nhất ngay để nước màu bóng đẹp mà không bao giờ bị đắng.');
INSERT INTO `recipe_steps` (`recipe_id`,`step_order`,`title`,`instruction`,`duration_mins`,`tip_note`) VALUES
(23,5,'Đảo săn hai mặt khóa ngọt nguyên liệu chính','Tăng lên lửa vừa lớn, gắp từng miếng trong 600g cá basa và 150g thịt ba chỉ vào nồi đảo đều hoặc trở nhẹ hai mặt trong 4–5 phút cho săn chắc và bám đều lớp màu nâu óng. Khi bề mặt nguyên liệu se vàng thơm phức mới trút phần nước ướp còn lại trong tô vào đun sôi nhẹ. Xếp ba chỉ và cá vào nồi, rót nước dừa gần ngang mặt cá. Đun sôi nhẹ rồi kho hé nắp 25–30 phút, trở cá một lần thật nhẹ.',8,'Đối với cá kho, chỉ lật cá một lần lúc cá vừa săn mặt trên lửa vừa để khúc cá nguyên vẹn không bị tróc da hay vỡ nát.'),
(23,6,'Kho/om liu riu lửa nhỏ thấm đẫm cùng nước dừa/nước dùng','Chế 250ml nước dừa tươi xâm xắp mặt nguyên liệu (xếp thêm rau củ ăn kèm nếu có), đun sôi bùng một dạo hớt sạch bọt rồi hạ ngay về mức lửa nhỏ liu riu nhất. Kho êm đềm không đậy kín nắp để từng thớ nguyên liệu chín mềm thấm đẫm gia vị và nước sốt rút dần sóng sánh. Khi cá chín và nước kho sánh, nếm lại, thêm ớt nếu dùng. Rắc hành lá, tiêu; không đảo mạnh để cá không vỡ.',13,'Luôn dùng nước sôi hoặc nước dừa ấm khi châm thêm vào nồi kho đang nóng để thịt cá không bị sượng cứng trở lại.'),
(23,7,'Thu sánh nước sốt óng ả & trình bày thưởng thức nóng','Khi nước kho rút còn khoảng 1/3 sánh kẹo óng ánh áo đều quanh nguyên liệu và xiên đũa thấy mềm mọng vừa ý, rắc 15g hành lá lên mặt rồi tắt bếp. Múc món Cá kho tộ ra đĩa sâu lòng hoặc niêu đất giữ nhiệt, dọn ăn nóng cùng cơm trắng dẻo thơm cho 4 người.',6,'Giữ lại một lượng nước sốt sánh kẹo vừa đủ dưới đáy nồi để chan cơm hoặc chấm kèm rau luộc sẽ tròn vị đưa cơm gấp bội.'),
(24,1,'Sơ chế sạch & cắt thái nguyên liệu đúng kích cỡ','Rửa sạch 600g cá thu và 350g cà chua cùng các nguyên liệu phối kèm dưới vòi nước mát rồi để thật ráo trên rổ thưa. Dùng dao sắc cắt thái nguyên liệu thành từng khúc hoặc khối vuông đều đặn khoảng 3.5–4cm để khi kho hầm giữ nguyên hình dáng đẹp mắt mà không bị vụn nát. Rửa cá nhanh với nước muối loãng, thấm thật khô để giảm bắn dầu. Cắt cà chua múi nhỏ, băm hành tím và tỏi.',6,'Cắt miếng thịt/cá dày dặn đồng đều giúp quá trình kho lâu trên lửa nhỏ thớ thịt mềm rục mà vẫn giữ trọn độ mọng ngọt bên trong.'),
(24,2,'Khử mùi tự nhiên & làm săn sạch bề mặt nguyên liệu','Chà nhẹ phần đạm chính trong 600g cá thu và 350g cà chua với chút muối hạt, lát gừng đập dập hoặc chần sơ qua nước sôi 90 giây rồi rửa sạch lại bằng nước ấm, để ráo hoàn toàn. Công đoạn này loại bỏ triệt để tạp chất và mùi tanh hôi, giúp nước sốt món Cá thu sốt cà chua trong bóng thơm ngon.',4,'Sau khi chần hoặc rửa sạch, để nguyên liệu ráo nước ít nhất 5 phút trước khi ướp để gia vị rút sâu trực tiếp vào từng thớ thịt.'),
(24,3,'Pha hỗn hợp gia vị & ướp thấm chuẩn định lượng','Cho 600g cá thu và 350g cà chua vào tô lớn, ướp cùng một nửa 20g hành tím và 10g tỏi băm nhỏ và định lượng chuẩn 20ml nước mắm, 8g đường, 2g tiêu và 3g muối, đảo nhẹ tay cho gia vị phủ kín đều các mặt. Bọc kín tô và để nguyên liệu nghỉ thấm vị tối thiểu 20 phút ở nhiệt độ phòng (hoặc ngăn mát tủ lạnh). Làm nóng dầu, áp chảo cá 2–3 phút mỗi mặt đến khi vàng nhẹ và chín gần tới; gắp ra đĩa.',6,'Ướp đủ tối thiểu 20 phút trước khi bắc lên bếp là chìa khóa để tâm miếng thịt/cá đậm đà đồng nhất với lớp sốt bên ngoài.'),
(24,4,'Thắng nước màu cánh gián & phi dậy hương hành tỏi','Đặt nồi đáy dày lên bếp ở lửa vừa nhỏ, thắng nhẹ 15g đường với 15ml dầu ăn đến khi chuyển sắc nâu cánh gián óng ả thì cho ngay phần 20g hành tím và 10g tỏi còn lại vào phi thơm lừng. Hương caramel dịu ngọt quyện cùng tinh dầu hành tỏi sả tạo nền màu nâu hổ phách truyền thống đầy cuốn hút.',4,'Canh kỹ khoảnh khắc đường vừa chuyển màu cánh gián là hạ lửa nhỏ nhất ngay để nước màu bóng đẹp mà không bao giờ bị đắng.'),
(24,5,'Đảo săn hai mặt khóa ngọt nguyên liệu chính','Tăng lên lửa vừa lớn, gắp từng miếng trong 600g cá thu và 350g cà chua vào nồi đảo đều hoặc trở nhẹ hai mặt trong 4–5 phút cho săn chắc và bám đều lớp màu nâu óng. Khi bề mặt nguyên liệu se vàng thơm phức mới trút phần nước ướp còn lại trong tô vào đun sôi nhẹ. Dùng chảo đó phi thơm hành tỏi, cho cà chua và 60 ml nước vào đậy nắp 5 phút. Dằm nhẹ cà chua, nêm nước mắm và đường.',6,'Đối với cá kho, chỉ lật cá một lần lúc cá vừa săn mặt trên lửa vừa để khúc cá nguyên vẹn không bị tróc da hay vỡ nát.'),
(24,6,'Kho/om liu riu lửa nhỏ thấm đẫm cùng nước dừa/nước dùng','Chế 20ml dầu ăn xâm xắp mặt nguyên liệu (xếp thêm rau củ ăn kèm nếu có), đun sôi bùng một dạo hớt sạch bọt rồi hạ ngay về mức lửa nhỏ liu riu nhất. Kho êm đềm không đậy kín nắp để từng thớ nguyên liệu chín mềm thấm đẫm gia vị và nước sốt rút dần sóng sánh. Đặt cá lại vào sốt, om lửa nhỏ 7–10 phút đến khi thịt cá đục hoàn toàn và tách thớ. Rắc hành lá, tiêu rồi dùng nóng.',10,'Luôn dùng nước sôi hoặc nước dừa ấm khi châm thêm vào nồi kho đang nóng để thịt cá không bị sượng cứng trở lại.'),
(24,7,'Thu sánh nước sốt óng ả & trình bày thưởng thức nóng','Khi nước kho rút còn khoảng 1/3 sánh kẹo óng ánh áo đều quanh nguyên liệu và xiên đũa thấy mềm mọng vừa ý, rắc 15g hành lá lên mặt rồi tắt bếp. Múc món Cá thu sốt cà chua ra đĩa sâu lòng hoặc niêu đất giữ nhiệt, dọn ăn nóng cùng cơm trắng dẻo thơm cho 4 người.',4,'Giữ lại một lượng nước sốt sánh kẹo vừa đủ dưới đáy nồi để chan cơm hoặc chấm kèm rau luộc sẽ tròn vị đưa cơm gấp bội.'),
(25,1,'Sơ chế sạch & cắt thái nguyên liệu đúng kích cỡ','Rửa sạch 1 con cá diêu hồng cùng 80g hành tây dưới vòi nước mát rồi để thật ráo trên rổ thưa. Dùng dao sắc cắt thái nguyên liệu thành từng khúc hoặc khối vuông đều đặn khoảng 3.5–4cm để khi kho hầm giữ nguyên hình dáng đẹp mắt mà không bị vụn nát. Đánh vảy, bỏ mang và ruột, rửa sạch rồi khứa 2–3 đường mỗi bên. Xát ít muối, rửa lại; thái gừng và hành thành sợi.',6,'Cắt miếng thịt/cá dày dặn đồng đều giúp quá trình kho lâu trên lửa nhỏ thớ thịt mềm rục mà vẫn giữ trọn độ mọng ngọt bên trong.'),
(25,2,'Khử mùi tự nhiên & làm săn sạch bề mặt nguyên liệu','Chà nhẹ phần đạm chính trong 1 con cá diêu hồng với chút muối hạt, lát gừng đập dập hoặc chần sơ qua nước sôi 90 giây rồi rửa sạch lại bằng nước ấm, để ráo hoàn toàn. Công đoạn này loại bỏ triệt để tạp chất và mùi tanh hôi, giúp nước sốt món Cá diêu hồng hấp gừng trong bóng thơm ngon.',5,'Sau khi chần hoặc rửa sạch, để nguyên liệu ráo nước ít nhất 5 phút trước khi ướp để gia vị rút sâu trực tiếp vào từng thớ thịt.'),
(25,3,'Pha hỗn hợp gia vị & ướp thấm chuẩn định lượng','Cho 1 con cá diêu hồng vào tô lớn, ướp cùng một nửa 35g gừng băm nhỏ và định lượng chuẩn 20ml nước tương, 1 quả chanh, 2g tiêu và 3g muối, đảo nhẹ tay cho gia vị phủ kín đều các mặt. Bọc kín tô và để nguyên liệu nghỉ thấm vị tối thiểu 20 phút ở nhiệt độ phòng (hoặc ngăn mát tủ lạnh). Lót hành tây dưới đĩa sâu lòng, đặt cá lên, nhét một phần gừng vào bụng và rải phần còn lại lên cá.',7,'Ướp đủ tối thiểu 20 phút trước khi bắc lên bếp là chìa khóa để tâm miếng thịt/cá đậm đà đồng nhất với lớp sốt bên ngoài.'),
(25,4,'Thắng nước màu cánh gián & phi dậy hương hành tỏi','Đặt nồi đáy dày lên bếp ở lửa vừa nhỏ, thắng nhẹ 15g đường với 15ml dầu ăn đến khi chuyển sắc nâu cánh gián óng ả thì cho ngay phần 35g gừng còn lại vào phi thơm lừng. Hương caramel dịu ngọt quyện cùng tinh dầu hành tỏi sả tạo nền màu nâu hổ phách truyền thống đầy cuốn hút.',4,'Canh kỹ khoảnh khắc đường vừa chuyển màu cánh gián là hạ lửa nhỏ nhất ngay để nước màu bóng đẹp mà không bao giờ bị đắng.'),
(25,5,'Đảo săn hai mặt khóa ngọt nguyên liệu chính','Tăng lên lửa vừa lớn, gắp từng miếng trong 1 con cá diêu hồng vào nồi đảo đều hoặc trở nhẹ hai mặt trong 4–5 phút cho săn chắc và bám đều lớp màu nâu óng. Khi bề mặt nguyên liệu se vàng thơm phức mới trút phần nước ướp còn lại trong tô vào đun sôi nhẹ. Khi nước xửng sôi mạnh, đặt đĩa cá vào hấp 18–22 phút tùy kích thước. Cá chín khi phần thịt dày đục trắng và dễ tách bằng nĩa.',6,'Đối với cá kho, chỉ lật cá một lần lúc cá vừa săn mặt trên lửa vừa để khúc cá nguyên vẹn không bị tróc da hay vỡ nát.'),
(25,6,'Kho/om liu riu lửa nhỏ thấm đẫm cùng nước dừa/nước dùng','Chế 8ml dầu mè xâm xắp mặt nguyên liệu (xếp thêm 80g hành tây nếu có), đun sôi bùng một dạo hớt sạch bọt rồi hạ ngay về mức lửa nhỏ liu riu nhất. Kho êm đềm không đậy kín nắp để từng thớ nguyên liệu chín mềm thấm đẫm gia vị và nước sốt rút dần sóng sánh. Trộn nước tương, nước cốt chanh và dầu mè. Rưới lên cá, rắc hành lá, gừng; dùng ngay khi còn nóng.',13,'Luôn dùng nước sôi hoặc nước dừa ấm khi châm thêm vào nồi kho đang nóng để thịt cá không bị sượng cứng trở lại.'),
(25,7,'Thu sánh nước sốt óng ả & trình bày thưởng thức nóng','Khi nước kho rút còn khoảng 1/3 sánh kẹo óng ánh áo đều quanh nguyên liệu và xiên đũa thấy mềm mọng vừa ý, rắc 30g hành lá lên mặt rồi tắt bếp. Múc món Cá diêu hồng hấp gừng ra đĩa sâu lòng hoặc niêu đất giữ nhiệt, dọn ăn nóng cùng cơm trắng dẻo thơm cho 4 người.',4,'Giữ lại một lượng nước sốt sánh kẹo vừa đủ dưới đáy nồi để chan cơm hoặc chấm kèm rau luộc sẽ tròn vị đưa cơm gấp bội.'),
(26,1,'Sơ chế sạch & cắt thái nguyên liệu đúng kích cỡ','Rửa sạch 700g cá lóc cùng các nguyên liệu phối kèm dưới vòi nước mát rồi để thật ráo trên rổ thưa. Dùng dao sắc cắt thái nguyên liệu thành từng khúc hoặc khối vuông đều đặn khoảng 3.5–4cm để khi kho hầm giữ nguyên hình dáng đẹp mắt mà không bị vụn nát. Làm sạch cá, cắt khúc, thấm khô. Giã nghệ với sả và hành tím; đeo găng nếu muốn tránh nghệ bám tay.',7,'Cắt miếng thịt/cá dày dặn đồng đều giúp quá trình kho lâu trên lửa nhỏ thớ thịt mềm rục mà vẫn giữ trọn độ mọng ngọt bên trong.'),
(26,2,'Khử mùi tự nhiên & làm săn sạch bề mặt nguyên liệu','Chà nhẹ phần đạm chính trong 700g cá lóc với chút muối hạt, lát gừng đập dập hoặc chần sơ qua nước sôi 90 giây rồi rửa sạch lại bằng nước ấm, để ráo hoàn toàn. Công đoạn này loại bỏ triệt để tạp chất và mùi tanh hôi, giúp nước sốt món Cá lóc kho nghệ trong bóng thơm ngon.',6,'Sau khi chần hoặc rửa sạch, để nguyên liệu ráo nước ít nhất 5 phút trước khi ướp để gia vị rút sâu trực tiếp vào từng thớ thịt.'),
(26,3,'Pha hỗn hợp gia vị & ướp thấm chuẩn định lượng','Cho 700g cá lóc vào tô lớn, ướp cùng một nửa 15g nghệ, 2 cây sả và 20g hành tím băm nhỏ và định lượng chuẩn 30ml nước mắm, 10g đường, 2g tiêu và 1 quả ớt, đảo nhẹ tay cho gia vị phủ kín đều các mặt. Bọc kín tô và để nguyên liệu nghỉ thấm vị tối thiểu 20 phút ở nhiệt độ phòng (hoặc ngăn mát tủ lạnh). Trộn cá với hỗn hợp nghệ sả, nước mắm, đường và tiêu, để 15 phút. Xếp cá thành một lớp trong nồi.',8,'Ướp đủ tối thiểu 20 phút trước khi bắc lên bếp là chìa khóa để tâm miếng thịt/cá đậm đà đồng nhất với lớp sốt bên ngoài.'),
(26,4,'Thắng nước màu cánh gián & phi dậy hương hành tỏi','Đặt nồi đáy dày lên bếp ở lửa vừa nhỏ, thắng nhẹ 15g đường với 15ml dầu ăn đến khi chuyển sắc nâu cánh gián óng ả thì cho ngay phần 15g nghệ, 2 cây sả và 20g hành tím còn lại vào phi thơm lừng. Hương caramel dịu ngọt quyện cùng tinh dầu hành tỏi sả tạo nền màu nâu hổ phách truyền thống đầy cuốn hút.',5,'Canh kỹ khoảnh khắc đường vừa chuyển màu cánh gián là hạ lửa nhỏ nhất ngay để nước màu bóng đẹp mà không bao giờ bị đắng.'),
(26,5,'Đảo săn hai mặt khóa ngọt nguyên liệu chính','Tăng lên lửa vừa lớn, gắp từng miếng trong 700g cá lóc vào nồi đảo đều hoặc trở nhẹ hai mặt trong 4–5 phút cho săn chắc và bám đều lớp màu nâu óng. Khi bề mặt nguyên liệu se vàng thơm phức mới trút phần nước ướp còn lại trong tô vào đun sôi nhẹ. Rót nước dừa gần ngang mặt cá, đun sôi rồi hạ nhỏ lửa. Kho 20 phút, hé nắp và chỉ lắc nồi thay vì đảo cá.',7,'Đối với cá kho, chỉ lật cá một lần lúc cá vừa săn mặt trên lửa vừa để khúc cá nguyên vẹn không bị tróc da hay vỡ nát.'),
(26,6,'Kho/om liu riu lửa nhỏ thấm đẫm cùng nước dừa/nước dùng','Chế 200ml nước dừa tươi xâm xắp mặt nguyên liệu (xếp thêm rau củ ăn kèm nếu có), đun sôi bùng một dạo hớt sạch bọt rồi hạ ngay về mức lửa nhỏ liu riu nhất. Kho êm đềm không đậy kín nắp để từng thớ nguyên liệu chín mềm thấm đẫm gia vị và nước sốt rút dần sóng sánh. Khi thịt cá chín đục, săn và nước kho sánh, nếm lại độ mặn ngọt. Thêm ớt nếu thích, tắt bếp và dùng với cơm.',12,'Luôn dùng nước sôi hoặc nước dừa ấm khi châm thêm vào nồi kho đang nóng để thịt cá không bị sượng cứng trở lại.'),
(26,7,'Thu sánh nước sốt óng ả & trình bày thưởng thức nóng','Khi nước kho rút còn khoảng 1/3 sánh kẹo óng ánh áo đều quanh nguyên liệu và xiên đũa thấy mềm mọng vừa ý, rắc hành ngò và tiêu xay lên mặt rồi tắt bếp. Múc món Cá lóc kho nghệ ra đĩa sâu lòng hoặc niêu đất giữ nhiệt, dọn ăn nóng cùng cơm trắng dẻo thơm cho 4 người.',5,'Giữ lại một lượng nước sốt sánh kẹo vừa đủ dưới đáy nồi để chan cơm hoặc chấm kèm rau luộc sẽ tròn vị đưa cơm gấp bội.'),
(27,1,'Sơ chế sạch & cắt thái nguyên liệu đúng kích cỡ','Rửa sạch 400g tôm sú và 250g thịt ba chỉ cùng các nguyên liệu phối kèm dưới vòi nước mát rồi để thật ráo trên rổ thưa. Dùng dao sắc cắt thái nguyên liệu thành từng khúc hoặc khối vuông đều đặn khoảng 3.5–4cm để khi kho hầm giữ nguyên hình dáng đẹp mắt mà không bị vụn nát. Rút chỉ lưng tôm, rửa nhanh và để ráo. Thái ba chỉ miếng mỏng; băm hành tím.',6,'Cắt miếng thịt/cá dày dặn đồng đều giúp quá trình kho lâu trên lửa nhỏ thớ thịt mềm rục mà vẫn giữ trọn độ mọng ngọt bên trong.');
INSERT INTO `recipe_steps` (`recipe_id`,`step_order`,`title`,`instruction`,`duration_mins`,`tip_note`) VALUES
(27,2,'Khử mùi tự nhiên & làm săn sạch bề mặt nguyên liệu','Chà nhẹ phần đạm chính trong 400g tôm sú và 250g thịt ba chỉ với chút muối hạt, lát gừng đập dập hoặc chần sơ qua nước sôi 90 giây rồi rửa sạch lại bằng nước ấm, để ráo hoàn toàn. Công đoạn này loại bỏ triệt để tạp chất và mùi tanh hôi, giúp nước sốt món Tôm rim thịt ba chỉ trong bóng thơm ngon.',5,'Sau khi chần hoặc rửa sạch, để nguyên liệu ráo nước ít nhất 5 phút trước khi ướp để gia vị rút sâu trực tiếp vào từng thớ thịt.'),
(27,3,'Pha hỗn hợp gia vị & ướp thấm chuẩn định lượng','Cho 400g tôm sú và 250g thịt ba chỉ vào tô lớn, ướp cùng một nửa 20g hành tím băm nhỏ và định lượng chuẩn 25ml nước mắm, 12g đường và 2g tiêu, đảo nhẹ tay cho gia vị phủ kín đều các mặt. Bọc kín tô và để nguyên liệu nghỉ thấm vị tối thiểu 20 phút ở nhiệt độ phòng (hoặc ngăn mát tủ lạnh). Cho thịt vào chảo, rang lửa vừa đến khi mỡ tiết ra và cạnh thịt hơi vàng. Gạn bớt mỡ, chừa khoảng 1 thìa.',7,'Ướp đủ tối thiểu 20 phút trước khi bắc lên bếp là chìa khóa để tâm miếng thịt/cá đậm đà đồng nhất với lớp sốt bên ngoài.'),
(27,4,'Thắng nước màu cánh gián & phi dậy hương hành tỏi','Đặt nồi đáy dày lên bếp ở lửa vừa nhỏ, thắng nhẹ 15g đường với 15ml dầu ăn đến khi chuyển sắc nâu cánh gián óng ả thì cho ngay phần 20g hành tím còn lại vào phi thơm lừng. Hương caramel dịu ngọt quyện cùng tinh dầu hành tỏi sả tạo nền màu nâu hổ phách truyền thống đầy cuốn hút.',4,'Canh kỹ khoảnh khắc đường vừa chuyển màu cánh gián là hạ lửa nhỏ nhất ngay để nước màu bóng đẹp mà không bao giờ bị đắng.'),
(27,5,'Đảo săn hai mặt khóa ngọt nguyên liệu chính','Tăng lên lửa vừa lớn, gắp từng miếng trong 400g tôm sú và 250g thịt ba chỉ vào nồi đảo đều hoặc trở nhẹ hai mặt trong 4–5 phút cho săn chắc và bám đều lớp màu nâu óng. Khi bề mặt nguyên liệu se vàng thơm phức mới trút phần nước ướp còn lại trong tô vào đun sôi nhẹ. Thêm hành tím rồi tôm, đảo đến khi tôm vừa chuyển hồng. Nêm nước mắm, đường, tiêu và nước dừa; rim nhỏ lửa 8–10 phút.',6,'Đối với cá kho, chỉ lật cá một lần lúc cá vừa săn mặt trên lửa vừa để khúc cá nguyên vẹn không bị tróc da hay vỡ nát.'),
(27,6,'Kho/om liu riu lửa nhỏ thấm đẫm cùng nước dừa/nước dùng','Chế 100ml nước dừa tươi xâm xắp mặt nguyên liệu (xếp thêm rau củ ăn kèm nếu có), đun sôi bùng một dạo hớt sạch bọt rồi hạ ngay về mức lửa nhỏ liu riu nhất. Kho êm đềm không đậy kín nắp để từng thớ nguyên liệu chín mềm thấm đẫm gia vị và nước sốt rút dần sóng sánh. Đảo nhẹ đến khi tôm chín đục, ba chỉ mềm và sốt áo quanh nguyên liệu. Rắc hành lá, nếm lại rồi dọn với cơm.',13,'Luôn dùng nước sôi hoặc nước dừa ấm khi châm thêm vào nồi kho đang nóng để thịt cá không bị sượng cứng trở lại.'),
(27,7,'Thu sánh nước sốt óng ả & trình bày thưởng thức nóng','Khi nước kho rút còn khoảng 1/3 sánh kẹo óng ánh áo đều quanh nguyên liệu và xiên đũa thấy mềm mọng vừa ý, rắc 15g hành lá lên mặt rồi tắt bếp. Múc món Tôm rim thịt ba chỉ ra đĩa sâu lòng hoặc niêu đất giữ nhiệt, dọn ăn nóng cùng cơm trắng dẻo thơm cho 4 người.',4,'Giữ lại một lượng nước sốt sánh kẹo vừa đủ dưới đáy nồi để chan cơm hoặc chấm kèm rau luộc sẽ tròn vị đưa cơm gấp bội.'),
(28,1,'Sơ chế sạch & cắt thái nguyên liệu đúng kích cỡ','Rửa sạch 500g mực ống và 250g thịt heo xay cùng 300g cà chua và 15g nấm mèo dưới vòi nước mát rồi để thật ráo trên rổ thưa. Dùng dao sắc cắt thái nguyên liệu thành từng khúc hoặc khối vuông đều đặn khoảng 3.5–4cm để khi kho hầm giữ nguyên hình dáng đẹp mắt mà không bị vụn nát. Ngâm nấm mèo cho nở, băm nhỏ. Trộn thịt xay, nấm, trứng, tiêu và một ít nước mắm; để nhân nghỉ 10 phút.',8,'Cắt miếng thịt/cá dày dặn đồng đều giúp quá trình kho lâu trên lửa nhỏ thớ thịt mềm rục mà vẫn giữ trọn độ mọng ngọt bên trong.'),
(28,2,'Khử mùi tự nhiên & làm săn sạch bề mặt nguyên liệu','Chà nhẹ phần đạm chính trong 500g mực ống và 250g thịt heo xay với chút muối hạt, lát gừng đập dập hoặc chần sơ qua nước sôi 90 giây rồi rửa sạch lại bằng nước ấm, để ráo hoàn toàn. Công đoạn này loại bỏ triệt để tạp chất và mùi tanh hôi, giúp nước sốt món Mực nhồi thịt sốt cà chua trong bóng thơm ngon.',7,'Sau khi chần hoặc rửa sạch, để nguyên liệu ráo nước ít nhất 5 phút trước khi ướp để gia vị rút sâu trực tiếp vào từng thớ thịt.'),
(28,3,'Pha hỗn hợp gia vị & ướp thấm chuẩn định lượng','Cho 500g mực ống và 250g thịt heo xay vào tô lớn, ướp cùng một nửa 20g hành tím băm nhỏ và định lượng chuẩn 20ml nước mắm và 2g tiêu, đảo nhẹ tay cho gia vị phủ kín đều các mặt. Bọc kín tô và để nguyên liệu nghỉ thấm vị tối thiểu 20 phút ở nhiệt độ phòng (hoặc ngăn mát tủ lạnh). Rửa sạch mực, giữ nguyên thân và để ráo. Nhồi nhân khoảng hai phần ba thân mực, ghim miệng bằng tăm để chừa chỗ nở.',9,'Ướp đủ tối thiểu 20 phút trước khi bắc lên bếp là chìa khóa để tâm miếng thịt/cá đậm đà đồng nhất với lớp sốt bên ngoài.'),
(28,4,'Thắng nước màu cánh gián & phi dậy hương hành tỏi','Đặt nồi đáy dày lên bếp ở lửa vừa nhỏ, thắng nhẹ 15g đường với 15ml dầu ăn đến khi chuyển sắc nâu cánh gián óng ả thì cho ngay phần 20g hành tím còn lại vào phi thơm lừng. Hương caramel dịu ngọt quyện cùng tinh dầu hành tỏi sả tạo nền màu nâu hổ phách truyền thống đầy cuốn hút.',6,'Canh kỹ khoảnh khắc đường vừa chuyển màu cánh gián là hạ lửa nhỏ nhất ngay để nước màu bóng đẹp mà không bao giờ bị đắng.'),
(28,5,'Đảo săn hai mặt khóa ngọt nguyên liệu chính','Tăng lên lửa vừa lớn, gắp từng miếng trong 500g mực ống và 250g thịt heo xay vào nồi đảo đều hoặc trở nhẹ hai mặt trong 4–5 phút cho săn chắc và bám đều lớp màu nâu óng. Khi bề mặt nguyên liệu se vàng thơm phức mới trút phần nước ướp còn lại trong tô vào đun sôi nhẹ. Áp chảo mực với chút dầu đến khi săn các mặt, gắp ra. Phi hành tím, thêm cà chua cắt nhỏ và 80 ml nước, nấu mềm.',8,'Đối với cá kho, chỉ lật cá một lần lúc cá vừa săn mặt trên lửa vừa để khúc cá nguyên vẹn không bị tróc da hay vỡ nát.'),
(28,6,'Kho/om liu riu lửa nhỏ thấm đẫm cùng nước dừa/nước dùng','Chế 15ml dầu ăn xâm xắp mặt nguyên liệu (xếp thêm rau củ ăn kèm nếu có), đun sôi bùng một dạo hớt sạch bọt rồi hạ ngay về mức lửa nhỏ liu riu nhất. Kho êm đềm không đậy kín nắp để từng thớ nguyên liệu chín mềm thấm đẫm gia vị và nước sốt rút dần sóng sánh. Cho mực vào sốt, đậy nắp om nhỏ lửa 15 phút, trở một lần. Thịt nhân phải chín hoàn toàn; bỏ tăm, cắt khoanh và chan sốt.',16,'Luôn dùng nước sôi hoặc nước dừa ấm khi châm thêm vào nồi kho đang nóng để thịt cá không bị sượng cứng trở lại.'),
(28,7,'Thu sánh nước sốt óng ả & trình bày thưởng thức nóng','Khi nước kho rút còn khoảng 1/3 sánh kẹo óng ánh áo đều quanh nguyên liệu và xiên đũa thấy mềm mọng vừa ý, rắc hành ngò và tiêu xay lên mặt rồi tắt bếp. Múc món Mực nhồi thịt sốt cà chua ra đĩa sâu lòng hoặc niêu đất giữ nhiệt, dọn ăn nóng cùng cơm trắng dẻo thơm cho 4 người.',6,'Giữ lại một lượng nước sốt sánh kẹo vừa đủ dưới đáy nồi để chan cơm hoặc chấm kèm rau luộc sẽ tròn vị đưa cơm gấp bội.'),
(29,1,'Sơ chế sạch & cắt thái nguyên liệu đúng kích cỡ','Rửa sạch 800g thịt vịt và 6 quả quả sấu cùng 300g khoai môn dưới vòi nước mát rồi để thật ráo trên rổ thưa. Dùng dao sắc cắt thái nguyên liệu thành từng khúc hoặc khối vuông đều đặn khoảng 3.5–4cm để khi kho hầm giữ nguyên hình dáng đẹp mắt mà không bị vụn nát. Chà vịt với gừng giã và chút muối, rửa sạch, chặt miếng. Ướp với nước mắm, hành tím và sả đập dập trong 20 phút.',12,'Cắt miếng thịt/cá dày dặn đồng đều giúp quá trình kho lâu trên lửa nhỏ thớ thịt mềm rục mà vẫn giữ trọn độ mọng ngọt bên trong.'),
(29,2,'Khử mùi tự nhiên & làm săn sạch bề mặt nguyên liệu','Chà nhẹ phần đạm chính trong 800g thịt vịt và 6 quả quả sấu với chút muối hạt, lát gừng đập dập hoặc chần sơ qua nước sôi 90 giây rồi rửa sạch lại bằng nước ấm, để ráo hoàn toàn. Công đoạn này loại bỏ triệt để tạp chất và mùi tanh hôi, giúp nước sốt món Vịt om sấu trong bóng thơm ngon.',9,'Sau khi chần hoặc rửa sạch, để nguyên liệu ráo nước ít nhất 5 phút trước khi ướp để gia vị rút sâu trực tiếp vào từng thớ thịt.'),
(29,3,'Pha hỗn hợp gia vị & ướp thấm chuẩn định lượng','Cho 800g thịt vịt và 6 quả quả sấu vào tô lớn, ướp cùng một nửa 2 cây sả, 20g gừng và 20g hành tím băm nhỏ và định lượng chuẩn 25ml nước mắm và 4g muối, đảo nhẹ tay cho gia vị phủ kín đều các mặt. Bọc kín tô và để nguyên liệu nghỉ thấm vị tối thiểu 20 phút ở nhiệt độ phòng (hoặc ngăn mát tủ lạnh). Đặt vịt vào nồi nóng, áp mặt da cho ra bớt mỡ và vàng nhẹ; bỏ phần mỡ thừa nếu nhiều.',13,'Ướp đủ tối thiểu 20 phút trước khi bắc lên bếp là chìa khóa để tâm miếng thịt/cá đậm đà đồng nhất với lớp sốt bên ngoài.'),
(29,4,'Thắng nước màu cánh gián & phi dậy hương hành tỏi','Đặt nồi đáy dày lên bếp ở lửa vừa nhỏ, thắng nhẹ 15g đường với 15ml dầu ăn đến khi chuyển sắc nâu cánh gián óng ả thì cho ngay phần 2 cây sả, 20g gừng và 20g hành tím còn lại vào phi thơm lừng. Hương caramel dịu ngọt quyện cùng tinh dầu hành tỏi sả tạo nền màu nâu hổ phách truyền thống đầy cuốn hút.',8,'Canh kỹ khoảnh khắc đường vừa chuyển màu cánh gián là hạ lửa nhỏ nhất ngay để nước màu bóng đẹp mà không bao giờ bị đắng.'),
(29,5,'Đảo săn hai mặt khóa ngọt nguyên liệu chính','Tăng lên lửa vừa lớn, gắp từng miếng trong 800g thịt vịt và 6 quả quả sấu vào nồi đảo đều hoặc trở nhẹ hai mặt trong 4–5 phút cho săn chắc và bám đều lớp màu nâu óng. Khi bề mặt nguyên liệu se vàng thơm phức mới trút phần nước ướp còn lại trong tô vào đun sôi nhẹ. Thêm nước nóng và sấu, đun sôi rồi hạ lửa, om khoảng 40 phút đến khi vịt gần mềm. Cho khoai môn vào nấu thêm 15 phút.',12,'Đối với cá kho, chỉ lật cá một lần lúc cá vừa săn mặt trên lửa vừa để khúc cá nguyên vẹn không bị tróc da hay vỡ nát.'),
(29,6,'Kho/om liu riu lửa nhỏ thấm đẫm cùng nước dừa/nước dùng','Chế 700ml nước lọc xâm xắp mặt nguyên liệu (xếp thêm 300g khoai môn nếu có), đun sôi bùng một dạo hớt sạch bọt rồi hạ ngay về mức lửa nhỏ liu riu nhất. Kho êm đềm không đậy kín nắp để từng thớ nguyên liệu chín mềm thấm đẫm gia vị và nước sốt rút dần sóng sánh. Dằm 2–3 quả sấu vào nước om, nếm độ chua rồi thêm sấu nếu cần. Kiểm tra phần dày nhất của vịt đạt 74°C; rắc hành lá và dùng nóng.',23,'Luôn dùng nước sôi hoặc nước dừa ấm khi châm thêm vào nồi kho đang nóng để thịt cá không bị sượng cứng trở lại.'),
(29,7,'Thu sánh nước sốt óng ả & trình bày thưởng thức nóng','Khi nước kho rút còn khoảng 1/3 sánh kẹo óng ánh áo đều quanh nguyên liệu và xiên đũa thấy mềm mọng vừa ý, rắc 15g hành lá lên mặt rồi tắt bếp. Múc món Vịt om sấu ra đĩa sâu lòng hoặc niêu đất giữ nhiệt, dọn ăn nóng cùng cơm trắng dẻo thơm cho 4 người.',8,'Giữ lại một lượng nước sốt sánh kẹo vừa đủ dưới đáy nồi để chan cơm hoặc chấm kèm rau luộc sẽ tròn vị đưa cơm gấp bội.'),
(30,1,'Sơ chế sạch & cắt thái nguyên liệu đúng kích cỡ','Rửa sạch 600g thịt gà (đùi) cùng các nguyên liệu phối kèm dưới vòi nước mát rồi để thật ráo trên rổ thưa. Dùng dao sắc cắt thái nguyên liệu thành từng khúc hoặc khối vuông đều đặn khoảng 3.5–4cm để khi kho hầm giữ nguyên hình dáng đẹp mắt mà không bị vụn nát. Thấm khô gà, cắt miếng vừa ăn. Trộn mật ong, nước tương, tỏi băm, tiêu và một nửa nước cốt chanh.',6,'Cắt miếng thịt/cá dày dặn đồng đều giúp quá trình kho lâu trên lửa nhỏ thớ thịt mềm rục mà vẫn giữ trọn độ mọng ngọt bên trong.'),
(30,2,'Khử mùi tự nhiên & làm săn sạch bề mặt nguyên liệu','Chà nhẹ phần đạm chính trong 600g thịt gà (đùi) với chút muối hạt, lát gừng đập dập hoặc chần sơ qua nước sôi 90 giây rồi rửa sạch lại bằng nước ấm, để ráo hoàn toàn. Công đoạn này loại bỏ triệt để tạp chất và mùi tanh hôi, giúp nước sốt món Gà sốt mật ong trong bóng thơm ngon.',5,'Sau khi chần hoặc rửa sạch, để nguyên liệu ráo nước ít nhất 5 phút trước khi ướp để gia vị rút sâu trực tiếp vào từng thớ thịt.'),
(30,3,'Pha hỗn hợp gia vị & ướp thấm chuẩn định lượng','Cho 600g thịt gà (đùi) vào tô lớn, ướp cùng một nửa 15g tỏi băm nhỏ và định lượng chuẩn 30ml mật ong, 25ml nước tương, 1 quả chanh và 2g tiêu, đảo nhẹ tay cho gia vị phủ kín đều các mặt. Bọc kín tô và để nguyên liệu nghỉ thấm vị tối thiểu 20 phút ở nhiệt độ phòng (hoặc ngăn mát tủ lạnh). Làm nóng dầu, đặt gà một lớp và áp chảo mỗi mặt 4–5 phút đến khi vàng. Nấu theo mẻ để chảo không bị nguội.',7,'Ướp đủ tối thiểu 20 phút trước khi bắc lên bếp là chìa khóa để tâm miếng thịt/cá đậm đà đồng nhất với lớp sốt bên ngoài.'),
(30,4,'Thắng nước màu cánh gián & phi dậy hương hành tỏi','Đặt nồi đáy dày lên bếp ở lửa vừa nhỏ, thắng nhẹ 15g đường với 15ml dầu ăn đến khi chuyển sắc nâu cánh gián óng ả thì cho ngay phần 15g tỏi còn lại vào phi thơm lừng. Hương caramel dịu ngọt quyện cùng tinh dầu hành tỏi sả tạo nền màu nâu hổ phách truyền thống đầy cuốn hút.',4,'Canh kỹ khoảnh khắc đường vừa chuyển màu cánh gián là hạ lửa nhỏ nhất ngay để nước màu bóng đẹp mà không bao giờ bị đắng.'),
(30,5,'Đảo săn hai mặt khóa ngọt nguyên liệu chính','Tăng lên lửa vừa lớn, gắp từng miếng trong 600g thịt gà (đùi) vào nồi đảo đều hoặc trở nhẹ hai mặt trong 4–5 phút cho săn chắc và bám đều lớp màu nâu óng. Khi bề mặt nguyên liệu se vàng thơm phức mới trút phần nước ướp còn lại trong tô vào đun sôi nhẹ. Hạ lửa vừa, rót hỗn hợp mật ong vào chảo, đảo gà liên tục 3–4 phút để sốt sôi nhẹ và phủ đều.',6,'Đối với cá kho, chỉ lật cá một lần lúc cá vừa săn mặt trên lửa vừa để khúc cá nguyên vẹn không bị tróc da hay vỡ nát.');
INSERT INTO `recipe_steps` (`recipe_id`,`step_order`,`title`,`instruction`,`duration_mins`,`tip_note`) VALUES
(30,6,'Kho/om liu riu lửa nhỏ thấm đẫm cùng nước dừa/nước dùng','Chế 15ml dầu ăn xâm xắp mặt nguyên liệu (xếp thêm rau củ ăn kèm nếu có), đun sôi bùng một dạo hớt sạch bọt rồi hạ ngay về mức lửa nhỏ liu riu nhất. Kho êm đềm không đậy kín nắp để từng thớ nguyên liệu chín mềm thấm đẫm gia vị và nước sốt rút dần sóng sánh. Đo phần dày nhất của gà đạt 74°C; nếu chưa, đậy nắp nấu thêm vài phút. Vắt phần chanh còn lại, rắc mè nếu dùng.',13,'Luôn dùng nước sôi hoặc nước dừa ấm khi châm thêm vào nồi kho đang nóng để thịt cá không bị sượng cứng trở lại.'),
(30,7,'Thu sánh nước sốt óng ả & trình bày thưởng thức nóng','Khi nước kho rút còn khoảng 1/3 sánh kẹo óng ánh áo đều quanh nguyên liệu và xiên đũa thấy mềm mọng vừa ý, rắc 8g mè rang lên mặt rồi tắt bếp. Múc món Gà sốt mật ong ra đĩa sâu lòng hoặc niêu đất giữ nhiệt, dọn ăn nóng cùng cơm trắng dẻo thơm cho 4 người.',4,'Giữ lại một lượng nước sốt sánh kẹo vừa đủ dưới đáy nồi để chan cơm hoặc chấm kèm rau luộc sẽ tròn vị đưa cơm gấp bội.'),
(31,1,'Sơ chế sạch & cắt thái nguyên liệu đúng kích cỡ','Rửa sạch 800g thịt gà (đùi) cùng 100g hành tây dưới vòi nước mát rồi để thật ráo trên rổ thưa. Dùng dao sắc cắt thái nguyên liệu thành từng khúc hoặc khối vuông đều đặn khoảng 3.5–4cm để khi kho hầm giữ nguyên hình dáng đẹp mắt mà không bị vụn nát. Rửa gà, thấm khô. Thái gừng sợi, hành lá khúc dài và hành tây múi cau; xếp hành tây dưới đĩa hấp.',8,'Cắt miếng thịt/cá dày dặn đồng đều giúp quá trình kho lâu trên lửa nhỏ thớ thịt mềm rục mà vẫn giữ trọn độ mọng ngọt bên trong.'),
(31,2,'Khử mùi tự nhiên & làm săn sạch bề mặt nguyên liệu','Chà nhẹ phần đạm chính trong 800g thịt gà (đùi) với chút muối hạt, lát gừng đập dập hoặc chần sơ qua nước sôi 90 giây rồi rửa sạch lại bằng nước ấm, để ráo hoàn toàn. Công đoạn này loại bỏ triệt để tạp chất và mùi tanh hôi, giúp nước sốt món Gà hấp hành gừng trong bóng thơm ngon.',6,'Sau khi chần hoặc rửa sạch, để nguyên liệu ráo nước ít nhất 5 phút trước khi ướp để gia vị rút sâu trực tiếp vào từng thớ thịt.'),
(31,3,'Pha hỗn hợp gia vị & ướp thấm chuẩn định lượng','Cho 800g thịt gà (đùi) vào tô lớn, ướp cùng một nửa 40g gừng băm nhỏ và định lượng chuẩn 15ml nước mắm, 2g tiêu, 1 quả chanh và 4g muối, đảo nhẹ tay cho gia vị phủ kín đều các mặt. Bọc kín tô và để nguyên liệu nghỉ thấm vị tối thiểu 20 phút ở nhiệt độ phòng (hoặc ngăn mát tủ lạnh). Xoa gà với nước mắm và tiêu, đặt lên đĩa. Rải gừng và một nửa hành lá lên trên, để 10 phút.',8,'Ướp đủ tối thiểu 20 phút trước khi bắc lên bếp là chìa khóa để tâm miếng thịt/cá đậm đà đồng nhất với lớp sốt bên ngoài.'),
(31,4,'Thắng nước màu cánh gián & phi dậy hương hành tỏi','Đặt nồi đáy dày lên bếp ở lửa vừa nhỏ, thắng nhẹ 15g đường với 15ml dầu ăn đến khi chuyển sắc nâu cánh gián óng ả thì cho ngay phần 40g gừng còn lại vào phi thơm lừng. Hương caramel dịu ngọt quyện cùng tinh dầu hành tỏi sả tạo nền màu nâu hổ phách truyền thống đầy cuốn hút.',6,'Canh kỹ khoảnh khắc đường vừa chuyển màu cánh gián là hạ lửa nhỏ nhất ngay để nước màu bóng đẹp mà không bao giờ bị đắng.'),
(31,5,'Đảo săn hai mặt khóa ngọt nguyên liệu chính','Tăng lên lửa vừa lớn, gắp từng miếng trong 800g thịt gà (đùi) vào nồi đảo đều hoặc trở nhẹ hai mặt trong 4–5 phút cho săn chắc và bám đều lớp màu nâu óng. Khi bề mặt nguyên liệu se vàng thơm phức mới trút phần nước ướp còn lại trong tô vào đun sôi nhẹ. Khi xửng bốc hơi mạnh, hấp gà 25–30 phút tùy độ dày. Kiểm tra phần dày nhất đạt 74°C, không để nước trong xửng cạn.',8,'Đối với cá kho, chỉ lật cá một lần lúc cá vừa săn mặt trên lửa vừa để khúc cá nguyên vẹn không bị tróc da hay vỡ nát.'),
(31,6,'Kho/om liu riu lửa nhỏ thấm đẫm cùng nước dừa/nước dùng','Chế 10ml dầu mè xâm xắp mặt nguyên liệu (xếp thêm 100g hành tây nếu có), đun sôi bùng một dạo hớt sạch bọt rồi hạ ngay về mức lửa nhỏ liu riu nhất. Kho êm đềm không đậy kín nắp để từng thớ nguyên liệu chín mềm thấm đẫm gia vị và nước sốt rút dần sóng sánh. Trộn phần hành lá còn lại với dầu mè nóng vừa đủ làm hành xẹp, rưới lên gà. Chặt miếng, dùng nóng với chanh.',13,'Luôn dùng nước sôi hoặc nước dừa ấm khi châm thêm vào nồi kho đang nóng để thịt cá không bị sượng cứng trở lại.'),
(31,7,'Thu sánh nước sốt óng ả & trình bày thưởng thức nóng','Khi nước kho rút còn khoảng 1/3 sánh kẹo óng ánh áo đều quanh nguyên liệu và xiên đũa thấy mềm mọng vừa ý, rắc 60g hành lá lên mặt rồi tắt bếp. Múc món Gà hấp hành gừng ra đĩa sâu lòng hoặc niêu đất giữ nhiệt, dọn ăn nóng cùng cơm trắng dẻo thơm cho 4 người.',6,'Giữ lại một lượng nước sốt sánh kẹo vừa đủ dưới đáy nồi để chan cơm hoặc chấm kèm rau luộc sẽ tròn vị đưa cơm gấp bội.'),
(32,1,'Sơ chế & thái mỏng đồng đều nguyên liệu xào','Làm sạch và thấm ráo 650g sườn non và 180g dứa, dùng dao sắc thái lát mỏng vừa ăn khoảng 2–3mm ngang thớ để khi xào nhanh chín mềm không bị dai. Nhặt rửa sạch 120g ớt chuông, cắt khúc xéo 4cm hoặc tách nhánh đồng đều giúp tiếp xúc nhiệt nhanh trên chảo. Chặt sườn miếng nhỏ, chần 3 phút rồi rửa sạch. Ướp với một nửa nước mắm và tiêu 10 phút.',10,'Nguyên liệu xào bắt buộc phải để thật ráo nước trước khi cho vào chảo để đạt hiệu ứng áp nhiệt thơm kiểu chảo gang.'),
(32,2,'Ướp mềm nguyên liệu đạm & pha sẵn chén sốt xào','Ướp phần đạm trong 650g sườn non và 180g dứa với 1/3 lượng 12g tỏi, chút dầu ăn và 1/3 lượng 25ml giấm, 18g đường, 20ml nước mắm và 2g tiêu trong 10 phút để giữ độ ẩm mọng. Pha phần 25ml giấm, 18g đường, 20ml nước mắm và 2g tiêu còn lại cùng 20ml nước lọc vào chén nhỏ khuấy tan hoàn toàn để thao tác xào lửa lớn diễn ra dứt khoát. Làm nóng dầu, áp chảo sườn đến khi vàng các mặt và chín gần tới; gắp ra đĩa.',9,'Thêm 1 muỗng cà phê dầu ăn vào bước ướp thịt bò/heo giúp khóa ẩm và các lát thịt tơi nhanh không bị dính chùm khi gặp chảo nóng.'),
(32,3,'Chần nhanh rau củ giữ sắc xanh ngọc & độ giòn','Đun sôi nồi nước nhỏ với một nhúm muối, thả 120g ớt chuông vào chần nhanh 30–45 giây rồi vớt ngay ra tô nước đá lạnh cho sốc nhiệt, sau đó đổ ra rổ cho thật ráo. Bước tiền xử lý này giúp rau củ chín đều từ trong mà bên ngoài vẫn xanh mướt giòn sần sật.',8,'Thời gian chần dưới 1 phút kết hợp ngâm nước đá lạnh là bí quyết nhà hàng giúp đĩa rau xào không bị chảy nước đen đĩa.'),
(32,4,'Xào săn nguyên liệu chính trên lửa lớn nhanh tay','Làm nóng chảo rộng trên lửa lớn nhất với 15ml dầu ăn, phi dậy mùi một nửa 12g tỏi rồi trút phần đạm chính trong 650g sườn non và 180g dứa vào đảo cực nhanh tay trong 60–90 giây. Ngay khi thịt hoặc hải sản vừa chín tái hồng khoảng 85%, lập tức trút riêng ra đĩa sạch để không bị quá lửa khô xác. Khuấy giấm, đường, phần nước mắm còn lại và 40 ml nước. Phi tỏi, xào cà chua, dứa và ớt chuông 3 phút.',8,'Tuyệt đối không xào thịt chung từ đầu đến cuối với rau củ vì thịt sẽ bị dai và tiết nước làm mất độ giòn.'),
(32,5,'Xào rau củ lửa lớn & rưới sốt định lượng khóa vị','Giữ nguyên chảo nóng trên lửa lớn, thêm chút dầu phi thơm nốt phần 12g tỏi còn lại rồi cho 120g ớt chuông đã ráo nước vào đảo đều 1–2 phút. Trút ngược đĩa đạm vào chảo, rưới đều chén sốt gia vị đã pha và xóc nhanh tay 45 giây cho sốt sánh bóng áo quanh từng miếng nguyên liệu.',9,'Rưới sốt vòng quanh thành chảo nóng thay vì đổ thẳng giữa lòng chảo giúp sốt bốc hơi thơm lừng và sệt lại tức thì.'),
(32,6,'Dậy hương tiêu hành & trình bày nóng hổi','Cho hành ngò và tiêu xay vào đảo nhẹ đúng 1 lượt rồi tắt bếp ngay khi khói thơm bốc lên nghi ngút. Gắp món Sườn xào chua ngọt ra đĩa rộng lòng để tản nhiệt đều, tránh đậy kín vung và thưởng thức nóng ngay cùng cơm dẻo cho 4 người. Cho sườn và sốt vào chảo, đảo lửa vừa 8–10 phút đến khi sườn chín, sốt sệt bám mặt. Nếm lại vị chua ngọt.',6,'Bày món xào ra đĩa rộng không xếp chồng quá dày giúp hơi nóng thoát nhẹ, giữ rau củ giòn ngọt lâu đến miếng cuối cùng.'),
(33,1,'Sơ chế sạch & cắt thái nguyên liệu đúng kích cỡ','Rửa sạch 500g thịt gà (đùi) và 400g mì quảng cùng 120g rau sống dưới vòi nước mát rồi để thật ráo trên rổ thưa. Dùng dao sắc cắt thái nguyên liệu thành từng khúc hoặc khối vuông đều đặn khoảng 3.5–4cm để khi kho hầm giữ nguyên hình dáng đẹp mắt mà không bị vụn nát. Chặt gà miếng vừa, ướp với nghệ, hành tím băm và nước mắm trong 20 phút. Luộc trứng, bóc vỏ; rang đậu phộng.',10,'Cắt miếng thịt/cá dày dặn đồng đều giúp quá trình kho lâu trên lửa nhỏ thớ thịt mềm rục mà vẫn giữ trọn độ mọng ngọt bên trong.'),
(33,2,'Khử mùi tự nhiên & làm săn sạch bề mặt nguyên liệu','Chà nhẹ phần đạm chính trong 500g thịt gà (đùi) và 400g mì quảng với chút muối hạt, lát gừng đập dập hoặc chần sơ qua nước sôi 90 giây rồi rửa sạch lại bằng nước ấm, để ráo hoàn toàn. Công đoạn này loại bỏ triệt để tạp chất và mùi tanh hôi, giúp nước sốt món Mì Quảng gà trong bóng thơm ngon.',8,'Sau khi chần hoặc rửa sạch, để nguyên liệu ráo nước ít nhất 5 phút trước khi ướp để gia vị rút sâu trực tiếp vào từng thớ thịt.'),
(33,3,'Pha hỗn hợp gia vị & ướp thấm chuẩn định lượng','Cho 500g thịt gà (đùi) và 400g mì quảng vào tô lớn, ướp cùng một nửa 8g nghệ và 25g hành tím băm nhỏ và định lượng chuẩn 25ml nước mắm, đảo nhẹ tay cho gia vị phủ kín đều các mặt. Bọc kín tô và để nguyên liệu nghỉ thấm vị tối thiểu 20 phút ở nhiệt độ phòng (hoặc ngăn mát tủ lạnh). Phi thơm hành với dầu, cho gà vào đảo săn. Thêm cà chua, đảo đến khi mềm rồi châm 500 ml nước nóng.',10,'Ướp đủ tối thiểu 20 phút trước khi bắc lên bếp là chìa khóa để tâm miếng thịt/cá đậm đà đồng nhất với lớp sốt bên ngoài.'),
(33,4,'Thắng nước màu cánh gián & phi dậy hương hành tỏi','Đặt nồi đáy dày lên bếp ở lửa vừa nhỏ, thắng nhẹ 15g đường với 15ml dầu ăn đến khi chuyển sắc nâu cánh gián óng ả thì cho ngay phần 8g nghệ và 25g hành tím còn lại vào phi thơm lừng. Hương caramel dịu ngọt quyện cùng tinh dầu hành tỏi sả tạo nền màu nâu hổ phách truyền thống đầy cuốn hút.',7,'Canh kỹ khoảnh khắc đường vừa chuyển màu cánh gián là hạ lửa nhỏ nhất ngay để nước màu bóng đẹp mà không bao giờ bị đắng.'),
(33,5,'Đảo săn hai mặt khóa ngọt nguyên liệu chính','Tăng lên lửa vừa lớn, gắp từng miếng trong 500g thịt gà (đùi) và 400g mì quảng vào nồi đảo đều hoặc trở nhẹ hai mặt trong 4–5 phút cho săn chắc và bám đều lớp màu nâu óng. Khi bề mặt nguyên liệu se vàng thơm phức mới trút phần nước ướp còn lại trong tô vào đun sôi nhẹ. Đậy hé nắp, nấu gà 25–30 phút đến khi phần dày nhất đạt 74°C và chín mềm. Nếm nước dùng đậm hơn canh; thêm nước sôi nếu cạn quá nhanh.',10,'Đối với cá kho, chỉ lật cá một lần lúc cá vừa săn mặt trên lửa vừa để khúc cá nguyên vẹn không bị tróc da hay vỡ nát.'),
(33,6,'Kho/om liu riu lửa nhỏ thấm đẫm cùng nước dừa/nước dùng','Chế 15ml dầu ăn xâm xắp mặt nguyên liệu (xếp thêm 120g rau sống nếu có), đun sôi bùng một dạo hớt sạch bọt rồi hạ ngay về mức lửa nhỏ liu riu nhất. Kho êm đềm không đậy kín nắp để từng thớ nguyên liệu chín mềm thấm đẫm gia vị và nước sốt rút dần sóng sánh. Trụng mì theo hướng dẫn gói, chia vào bát, xếp gà và trứng, chan một lượng nước nhưn vừa đủ. Rắc đậu phộng, ăn cùng rau sống.',18,'Luôn dùng nước sôi hoặc nước dừa ấm khi châm thêm vào nồi kho đang nóng để thịt cá không bị sượng cứng trở lại.'),
(33,7,'Thu sánh nước sốt óng ả & trình bày thưởng thức nóng','Khi nước kho rút còn khoảng 1/3 sánh kẹo óng ánh áo đều quanh nguyên liệu và xiên đũa thấy mềm mọng vừa ý, rắc 40g đậu phộng lên mặt rồi tắt bếp. Múc món Mì Quảng gà ra đĩa sâu lòng hoặc niêu đất giữ nhiệt, dọn ăn nóng cùng cơm trắng dẻo thơm cho 4 người.',7,'Giữ lại một lượng nước sốt sánh kẹo vừa đủ dưới đáy nồi để chan cơm hoặc chấm kèm rau luộc sẽ tròn vị đưa cơm gấp bội.'),
(34,1,'Sơ chế sạch & thấm thật khô bề mặt nguyên liệu','Rửa sạch 600g cơm nguội và 200g tôm sú cùng chút muối loãng để khử mùi tự nhiên, sau đó dùng khăn giấy bếp thấm thật khô ráo hoàn toàn bề mặt. Khứa nhẹ các đường chéo hoặc cắt miếng vừa ăn dày 2–3cm để nhiệt và gia vị thấm sâu đều khắp bên trong. Tách cơm cho tơi. Rút chỉ tôm, cắt mực khoanh, thấm khô; thái cà rốt hạt lựu và chần đậu Hà Lan 2 phút.',5,'Bề mặt nguyên liệu càng khô ráo thì khi chiên không bị văng dầu và khi nướng sẽ lên màu vàng ruộm giòn rụm cực đẹp.'),
(34,2,'Chuẩn bị hỗn hợp sốt ướp / bột áo chuẩn tỷ lệ','Phối trộn 10g tỏi băm thật nhuyễn (hoặc vắt lấy nước cốt thơm) cùng 20ml nước tương trong tô lớn cho quyện sánh đồng nhất. Nếu món có lớp vỏ bột hoặc bánh cuốn từ 600g cơm nguội và 200g tôm sú, trộn đều hỗn hợp theo đúng định lượng để đạt độ giòn xốp mỏng nhẹ chuẩn vị. Chảo thật nóng với ít dầu, xào tôm và mực riêng từng mẻ đến khi vừa đục và chín; trút ra để không bị dai.',5,'Vắt lấy nước cốt hành tỏi sả khi ướp đồ nướng giúp hương thơm thấm sâu mà không bị cháy đen phần xác băm trên lửa cao.'),
(34,3,'Ướp thấm thớ thịt / tạo hình cuốn khéo léo','Áo đều hỗn hợp gia vị hoặc lớp bột/vỏ cuốn quanh 600g cơm nguội và 200g tôm sú, massage nhẹ nhàng rồi để nghỉ 15–20 phút cho gia vị thẩm thấu trọn vẹn. Trường hợp cuốn chả/nem hoặc đổ khuôn bánh, thao tác đều tay vừa chặt để nhân kết dính nhưng không bị bục rách khi gặp nhiệt.',6,'Để nguyên liệu nghỉ đủ thời gian trước khi chiên nướng giúp lớp áo bột bám chắc và phần nhân bên trong mọng ngọt.');
INSERT INTO `recipe_steps` (`recipe_id`,`step_order`,`title`,`instruction`,`duration_mins`,`tip_note`) VALUES
(34,4,'Pha nước chấm cân vị & sơ chế rau đồ chua ăn kèm','Nhặt rửa sạch 80g đậu hà lan ngâm nước mát cho giòn tươi, bào sợi hoặc thái lát gọn gàng bày sẵn bên cạnh. Pha chén nước chấm chua ngọt hoặc muối ớt chanh sả sánh thơm theo khẩu vị vùng miền của món Cơm chiên hải sản để cân bằng độ béo giòn.',4,'Luôn chuẩn bị xong rau sống và bát nước chấm trước khi chiên/nướng mẻ cuối để món ăn vừa ra lò là thưởng thức nóng giòn ngay.'),
(34,5,'Làm nóng dầu / lò nướng chuẩn nhiệt & làm chín đều lần 1','Làm nóng chảo dầu hoặc vỉ nướng/nồi chiên ở mức nhiệt vừa khoảng 165–175°C, xếp 600g cơm nguội và 200g tôm sú vào với khoảng cách thoáng đều nhau. Chiên hoặc nướng trở mặt nhịp nhàng trên lửa vừa để nhiệt dẫn sâu làm chín mềm ngọt hoàn toàn phần nhân bên trong. Phi tỏi, cho cà rốt và đậu vào đảo 2 phút. Thêm cơm, rang lửa lớn; gạt sang bên, cho trứng vào đảo chín.',8,'Kiểm tra nhiệt dầu bằng đầu đũa tre thấy sủi tăm nhỏ đều là đạt chuẩn 170°C, giúp vỏ không cháy sớm khi bên trong còn sống.'),
(34,6,'Tăng nhiệt khóa giòn rụm vàng ươm bề mặt lần 2','Ở 2–3 phút cuối, tăng lên lửa vừa lớn (khoảng 190°C) hoặc phết thêm lớp dầu điều/mật ong mỏng để vỏ ngoài của Cơm chiên hải sản chuyển sắc vàng óng ánh và nổ giòn rụm. Lắng nghe tiếng xèo giòn rộn rã và hương thơm phức lan tỏa khắp bếp thì gắp ra vỉ thưa cho ráo dầu thừa.',4,'Đặt đồ chiên nướng lên giá inox thoáng khí thay vì giấy thấm dầu chồng khít để hơi nước thoát hết, giữ độ giòn lâu gấp 3 lần.'),
(34,7,'Trình bày bắt mắt kèm rau thơm & thưởng thức nóng','Xếp thành phẩm vàng giòn ra đĩa lớn có bày sẵn 80g đậu hà lan và điểm xuyết 15g hành lá tươi xanh hài hòa màu sắc. Dọn kèm chén nước chấm sánh đậm ngay chính giữa mâm ăn cho 4 người thưởng thức khi vỏ ngoài còn nóng giòn rụm. Cho hải sản trở lại, rưới nước tương quanh mép chảo, đảo 1 phút. Nếm độ mặn rồi rắc hành lá và dùng nóng.',3,'Cắt miếng hoặc dọn ăn ngay trong vòng 10 phút sau khi rời bếp để cảm nhận trọn vẹn sự đối lập giòn ngoài - mềm ngọt bên trong.'),
(35,1,'Sơ chế sạch & cắt thái nguyên liệu đúng kích cỡ','Rửa sạch 320g mì ý và 300g thịt bò xay cùng 100g hành tây và 30g phô mai parmesan dưới vòi nước mát rồi để thật ráo trên rổ thưa. Dùng dao sắc cắt thái nguyên liệu thành từng khúc hoặc khối vuông đều đặn khoảng 3.5–4cm để khi kho hầm giữ nguyên hình dáng đẹp mắt mà không bị vụn nát. Băm nhỏ hành tây, tỏi và cà chua. Đun nồi nước lớn, thêm muối; chuẩn bị mì theo thời gian ghi trên bao bì.',6,'Cắt miếng thịt/cá dày dặn đồng đều giúp quá trình kho lâu trên lửa nhỏ thớ thịt mềm rục mà vẫn giữ trọn độ mọng ngọt bên trong.'),
(35,2,'Khử mùi tự nhiên & làm săn sạch bề mặt nguyên liệu','Chà nhẹ phần đạm chính trong 320g mì ý và 300g thịt bò xay với chút muối hạt, lát gừng đập dập hoặc chần sơ qua nước sôi 90 giây rồi rửa sạch lại bằng nước ấm, để ráo hoàn toàn. Công đoạn này loại bỏ triệt để tạp chất và mùi tanh hôi, giúp nước sốt món Mì Ý sốt bò bằm trong bóng thơm ngon.',5,'Sau khi chần hoặc rửa sạch, để nguyên liệu ráo nước ít nhất 5 phút trước khi ướp để gia vị rút sâu trực tiếp vào từng thớ thịt.'),
(35,3,'Pha hỗn hợp gia vị & ướp thấm chuẩn định lượng','Cho 320g mì ý và 300g thịt bò xay vào tô lớn, ướp cùng một nửa 12g tỏi băm nhỏ và định lượng chuẩn 5g muối, đảo nhẹ tay cho gia vị phủ kín đều các mặt. Bọc kín tô và để nguyên liệu nghỉ thấm vị tối thiểu 20 phút ở nhiệt độ phòng (hoặc ngăn mát tủ lạnh). Làm nóng dầu ô liu, xào hành đến trong rồi thêm tỏi. Cho bò xay vào, dằm tơi và đảo đến khi chuyển nâu.',7,'Ướp đủ tối thiểu 20 phút trước khi bắc lên bếp là chìa khóa để tâm miếng thịt/cá đậm đà đồng nhất với lớp sốt bên ngoài.'),
(35,4,'Thắng nước màu cánh gián & phi dậy hương hành tỏi','Đặt nồi đáy dày lên bếp ở lửa vừa nhỏ, thắng nhẹ 15g đường với 15ml dầu ăn đến khi chuyển sắc nâu cánh gián óng ả thì cho ngay phần 12g tỏi còn lại vào phi thơm lừng. Hương caramel dịu ngọt quyện cùng tinh dầu hành tỏi sả tạo nền màu nâu hổ phách truyền thống đầy cuốn hút.',4,'Canh kỹ khoảnh khắc đường vừa chuyển màu cánh gián là hạ lửa nhỏ nhất ngay để nước màu bóng đẹp mà không bao giờ bị đắng.'),
(35,5,'Đảo săn hai mặt khóa ngọt nguyên liệu chính','Tăng lên lửa vừa lớn, gắp từng miếng trong 320g mì ý và 300g thịt bò xay vào nồi đảo đều hoặc trở nhẹ hai mặt trong 4–5 phút cho săn chắc và bám đều lớp màu nâu óng. Khi bề mặt nguyên liệu se vàng thơm phức mới trút phần nước ướp còn lại trong tô vào đun sôi nhẹ. Thêm cà chua và cà chua cô đặc, hạ lửa nhỏ nấu 18–20 phút. Nếu sốt khô, thêm từng vá nước luộc mì.',6,'Đối với cá kho, chỉ lật cá một lần lúc cá vừa săn mặt trên lửa vừa để khúc cá nguyên vẹn không bị tróc da hay vỡ nát.'),
(35,6,'Kho/om liu riu lửa nhỏ thấm đẫm cùng nước dừa/nước dùng','Chế 15ml dầu ô liu xâm xắp mặt nguyên liệu (xếp thêm 100g hành tây và 30g phô mai parmesan nếu có), đun sôi bùng một dạo hớt sạch bọt rồi hạ ngay về mức lửa nhỏ liu riu nhất. Kho êm đềm không đậy kín nắp để từng thớ nguyên liệu chín mềm thấm đẫm gia vị và nước sốt rút dần sóng sánh. Vớt mì khi còn hơi dai, giữ lại ít nước luộc. Đảo mì vào sốt 1–2 phút; rắc Parmesan nếu dùng và dọn ngay.',13,'Luôn dùng nước sôi hoặc nước dừa ấm khi châm thêm vào nồi kho đang nóng để thịt cá không bị sượng cứng trở lại.'),
(35,7,'Thu sánh nước sốt óng ả & trình bày thưởng thức nóng','Khi nước kho rút còn khoảng 1/3 sánh kẹo óng ánh áo đều quanh nguyên liệu và xiên đũa thấy mềm mọng vừa ý, rắc hành ngò và tiêu xay lên mặt rồi tắt bếp. Múc món Mì Ý sốt bò bằm ra đĩa sâu lòng hoặc niêu đất giữ nhiệt, dọn ăn nóng cùng cơm trắng dẻo thơm cho 4 người.',4,'Giữ lại một lượng nước sốt sánh kẹo vừa đủ dưới đáy nồi để chan cơm hoặc chấm kèm rau luộc sẽ tròn vị đưa cơm gấp bội.'),
(36,1,'Sơ chế & chần sạch nguyên liệu xương thịt, hải sản','Rửa sạch 600g thịt heo (nạc vai) và 500g bún tươi với muối hạt rồi chần nhanh trong nồi nước sôi có đập dập 1 nhánh gừng trong 2–3 phút trên lửa lớn để loại bỏ hoàn toàn bọt bẩn. Rửa lại dưới làn nước sạch cho thật trắng trẻo, đồng thời nhặt rửa sạch 100g xà lách để ráo nước. Thái thịt lát mỏng. Trộn sả băm, một nửa nước mắm, đường và tỏi; ướp thịt ít nhất 30 phút.',6,'Bước chần sơ và rửa lại bằng nước ấm là bí quyết vàng giúp nồi nước dùng trong vắt, thơm thanh và không bao giờ bị đục hay hôi.'),
(36,2,'Nướng thơm thảo mộc & ninh nền nước dùng ngọt thanh','Cho phần nguyên liệu tạo ngọt từ 600g thịt heo (nạc vai) và 500g bún tươi cùng 3 cây sả và 12g tỏi đã nướng xém thơm vào nồi sâu lòng với khoảng 1.5–1.8 lít nước lọc. Đun sôi bùng trên lửa lớn rồi hạ ngay về lửa nhỏ liu riu, mở hé vung và hớt kỹ bọt nổi trên mặt để chiết xuất vị ngọt tự nhiên. Khuấy phần nước mắm còn lại với đường, giấm và 60 ml nước ấm; thêm tỏi băm, nếm chua ngọt vừa miệng.',12,'Luôn duy trì mặt nước lăn tăn nhẹ thay vì đun sôi sùng sục lửa to để protein không bị nhũ hóa gây đục nước lèo.'),
(36,3,'Xào tạo màu & dậy hương đặc trưng vùng miền','Bắc chảo nhỏ lên bếp với 15ml dầu ăn trên lửa vừa, phi thơm phần hành tỏi sả băm còn lại rồi xào săn 100g cà rốt cùng 35ml nước mắm, 25g đường và 20ml giấm trong 3–4 phút. Khi hỗn hợp dậy mùi thơm nồng nàn và lên sắc màu óng ả đặc trưng của món Bún thịt nướng thì tắt bếp.',5,'Xào riêng phần nguyên liệu tạo màu và gia vị thơm trước khi trút vào nồi nước dùng giúp tầng hương dậy lên rõ nét gấp đôi.'),
(36,4,'Sơ chế & cắt thái phần nhân topping xếp tô','Vớt phần thịt hoặc hải sản chín tới từ 600g thịt heo (nạc vai) và 500g bún tươi ra ngâm ngay vào âu nước đun sôi để nguội giúp bề mặt săn giòn mọng nước, không bị thâm khô. Thái lát mỏng đều tay dày khoảng 3mm ngang thớ hoặc gỡ miếng vừa ăn, sắp riêng từng phần gọn gàng trên đĩa.',5,'Thái thịt ngang thớ với lưỡi dao thật sắc giúp lát thịt mềm mướt, khi chan nước dùng sôi lên sẽ phẳng đẹp không bị quăn cứng.'),
(36,5,'Hợp nhất nồi nước lèo & nêm chuẩn định lượng','Trút phần sốt màu thơm vào nồi nước dùng đang sôi lăn tăn, nêm chính xác lượng 35ml nước mắm, 25g đường và 20ml giấm còn lại cho vừa miệng 4 người ăn. Đun nhẹ thêm 5 phút ở lửa vừa để các tầng vị mặn dịu, ngọt hậu từ xương thịt và thảo mộc hòa quyện tròn trịa. Xếp thịt thành lớp mỏng, nướng vỉ hoặc áp chảo lửa vừa cao 3–4 phút mỗi mặt đến chín và xém cạnh; tránh để sả cháy đắng.',5,'Nên nêm nước mắm ngon ở giai đoạn cuối trên lửa nhỏ để giữ trọn hậu vị ngọt đạm và hương thơm mà không làm nước dùng bị chua.'),
(36,6,'Chần nóng sợi bánh/bún & chuẩn bị rau ăn kèm','Đun sôi một nồi nước riêng, cho phần sợi bún/phở/bánh trong 600g thịt heo (nạc vai) và 500g bún tươi vào trụng nhanh 15–25 giây cho sợi mềm dẻo nóng hổi rồi vẩy thật ráo nước, chia đều vào 4 tô lớn. Chần sơ thêm rau ăn kèm (100g xà lách) nếu muốn dùng chín giòn.',4,'Trụng bún bánh ở nồi nước sôi riêng biệt giúp nước dùng chính không bị nhiễm tinh bột chua và tô bún luôn ráo sợi, thấm vị.'),
(36,7,'Xếp nhân hài hòa, chan nước dùng sôi & thưởng thức','Xếp đều các phần nhân thịt, hải sản lên mặt tô bún bánh, điểm xuyết 30g đậu phộng lên trên cùng. Dùng muôi múc nước dùng đang sôi thật già chan ngập xăm xắp mặt nguyên liệu để làm chín thơm hành ngò, dọn nóng ngay kèm chanh ớt tươi. Trụng bún nhanh, để ráo. Xếp xà lách, cà rốt ngâm giấm và thịt nướng lên trên; rắc đậu phộng nếu dùng, chan nước chấm.',3,'Tráng nóng tô sứ bằng nước sôi trước khi xếp bún giúp tô món nước giữ nhiệt bốc khói nghi ngút suốt bữa ăn.'),
(37,1,'Sơ chế sạch & cắt thái nguyên liệu đúng kích cỡ','Rửa sạch 400g thịt bò xay và 100g thịt heo xay cùng 300g bún tươi dưới vòi nước mát rồi để thật ráo trên rổ thưa. Dùng dao sắc cắt thái nguyên liệu thành từng khúc hoặc khối vuông đều đặn khoảng 3.5–4cm để khi kho hầm giữ nguyên hình dáng đẹp mắt mà không bị vụn nát. Trộn bò và heo xay với sả, hành tím băm, nước mắm, tiêu và dầu. Để lạnh 15 phút để nhân săn.',6,'Cắt miếng thịt/cá dày dặn đồng đều giúp quá trình kho lâu trên lửa nhỏ thớ thịt mềm rục mà vẫn giữ trọn độ mọng ngọt bên trong.'),
(37,2,'Khử mùi tự nhiên & làm săn sạch bề mặt nguyên liệu','Chà nhẹ phần đạm chính trong 400g thịt bò xay và 100g thịt heo xay với chút muối hạt, lát gừng đập dập hoặc chần sơ qua nước sôi 90 giây rồi rửa sạch lại bằng nước ấm, để ráo hoàn toàn. Công đoạn này loại bỏ triệt để tạp chất và mùi tanh hôi, giúp nước sốt món Bò cuốn lá lốt trong bóng thơm ngon.',4,'Sau khi chần hoặc rửa sạch, để nguyên liệu ráo nước ít nhất 5 phút trước khi ướp để gia vị rút sâu trực tiếp vào từng thớ thịt.'),
(37,3,'Pha hỗn hợp gia vị & ướp thấm chuẩn định lượng','Cho 400g thịt bò xay và 100g thịt heo xay vào tô lớn, ướp cùng một nửa 1 cây sả và 20g hành tím băm nhỏ và định lượng chuẩn 18ml nước mắm và 2g tiêu, đảo nhẹ tay cho gia vị phủ kín đều các mặt. Bọc kín tô và để nguyên liệu nghỉ thấm vị tối thiểu 20 phút ở nhiệt độ phòng (hoặc ngăn mát tủ lạnh). Rửa lá lốt, lau khô. Đặt mặt gân lên trên, cho ít nhân gần cuống rồi cuốn chặt, ghim bằng tăm nếu cần.',6,'Ướp đủ tối thiểu 20 phút trước khi bắc lên bếp là chìa khóa để tâm miếng thịt/cá đậm đà đồng nhất với lớp sốt bên ngoài.'),
(37,4,'Thắng nước màu cánh gián & phi dậy hương hành tỏi','Đặt nồi đáy dày lên bếp ở lửa vừa nhỏ, thắng nhẹ 15g đường với 15ml dầu ăn đến khi chuyển sắc nâu cánh gián óng ả thì cho ngay phần 1 cây sả và 20g hành tím còn lại vào phi thơm lừng. Hương caramel dịu ngọt quyện cùng tinh dầu hành tỏi sả tạo nền màu nâu hổ phách truyền thống đầy cuốn hút.',4,'Canh kỹ khoảnh khắc đường vừa chuyển màu cánh gián là hạ lửa nhỏ nhất ngay để nước màu bóng đẹp mà không bao giờ bị đắng.'),
(37,5,'Đảo săn hai mặt khóa ngọt nguyên liệu chính','Tăng lên lửa vừa lớn, gắp từng miếng trong 400g thịt bò xay và 100g thịt heo xay vào nồi đảo đều hoặc trở nhẹ hai mặt trong 4–5 phút cho săn chắc và bám đều lớp màu nâu óng. Khi bề mặt nguyên liệu se vàng thơm phức mới trút phần nước ướp còn lại trong tô vào đun sôi nhẹ. Phết dầu mỏng lên vỉ, nướng lửa vừa 3–4 phút mỗi mặt hoặc áp chảo có nắp. Trở nhẹ để lá không rách và nhân chín đều.',6,'Đối với cá kho, chỉ lật cá một lần lúc cá vừa săn mặt trên lửa vừa để khúc cá nguyên vẹn không bị tróc da hay vỡ nát.'),
(37,6,'Kho/om liu riu lửa nhỏ thấm đẫm cùng nước dừa/nước dùng','Chế 10ml dầu ăn xâm xắp mặt nguyên liệu (xếp thêm rau củ ăn kèm nếu có), đun sôi bùng một dạo hớt sạch bọt rồi hạ ngay về mức lửa nhỏ liu riu nhất. Kho êm đềm không đậy kín nắp để từng thớ nguyên liệu chín mềm thấm đẫm gia vị và nước sốt rút dần sóng sánh. Cắt thử cuốn dày nhất, thịt bên trong phải chín hoàn toàn. Ăn nóng với bún, đậu phộng rang và nước mắm chua ngọt.',10,'Luôn dùng nước sôi hoặc nước dừa ấm khi châm thêm vào nồi kho đang nóng để thịt cá không bị sượng cứng trở lại.'),
(37,7,'Thu sánh nước sốt óng ả & trình bày thưởng thức nóng','Khi nước kho rút còn khoảng 1/3 sánh kẹo óng ánh áo đều quanh nguyên liệu và xiên đũa thấy mềm mọng vừa ý, rắc 30 lá lá lốt và 25g đậu phộng lên mặt rồi tắt bếp. Múc món Bò cuốn lá lốt ra đĩa sâu lòng hoặc niêu đất giữ nhiệt, dọn ăn nóng cùng cơm trắng dẻo thơm cho 4 người.',4,'Giữ lại một lượng nước sốt sánh kẹo vừa đủ dưới đáy nồi để chan cơm hoặc chấm kèm rau luộc sẽ tròn vị đưa cơm gấp bội.');
INSERT INTO `recipe_steps` (`recipe_id`,`step_order`,`title`,`instruction`,`duration_mins`,`tip_note`) VALUES
(38,1,'Sơ chế sạch & thấm thật khô bề mặt nguyên liệu','Rửa sạch 500g thịt heo quay và 350g dưa cải chua cùng chút muối loãng để khử mùi tự nhiên, sau đó dùng khăn giấy bếp thấm thật khô ráo hoàn toàn bề mặt. Khứa nhẹ các đường chéo hoặc cắt miếng vừa ăn dày 2–3cm để nhiệt và gia vị thấm sâu đều khắp bên trong. Rửa cải chua, nếm thử; nếu mặn hoặc chua gắt, xả nhanh rồi vắt ráo. Cắt heo quay miếng vừa ăn.',7,'Bề mặt nguyên liệu càng khô ráo thì khi chiên không bị văng dầu và khi nướng sẽ lên màu vàng ruộm giòn rụm cực đẹp.'),
(38,2,'Chuẩn bị hỗn hợp sốt ướp / bột áo chuẩn tỷ lệ','Phối trộn 20g hành tím và 10g tỏi băm thật nhuyễn (hoặc vắt lấy nước cốt thơm) cùng 18ml nước mắm, 8g đường và 1 quả ớt trong tô lớn cho quyện sánh đồng nhất. Nếu món có lớp vỏ bột hoặc bánh cuốn từ 500g thịt heo quay và 350g dưa cải chua, trộn đều hỗn hợp theo đúng định lượng để đạt độ giòn xốp mỏng nhẹ chuẩn vị. Phi hành tím và tỏi, cho cải chua vào đảo 4 phút để ráo nước và dậy mùi.',6,'Vắt lấy nước cốt hành tỏi sả khi ướp đồ nướng giúp hương thơm thấm sâu mà không bị cháy đen phần xác băm trên lửa cao.'),
(38,3,'Ướp thấm thớ thịt / tạo hình cuốn khéo léo','Áo đều hỗn hợp gia vị hoặc lớp bột/vỏ cuốn quanh 500g thịt heo quay và 350g dưa cải chua, massage nhẹ nhàng rồi để nghỉ 15–20 phút cho gia vị thẩm thấu trọn vẹn. Trường hợp cuốn chả/nem hoặc đổ khuôn bánh, thao tác đều tay vừa chặt để nhân kết dính nhưng không bị bục rách khi gặp nhiệt.',8,'Để nguyên liệu nghỉ đủ thời gian trước khi chiên nướng giúp lớp áo bột bám chắc và phần nhân bên trong mọng ngọt.'),
(38,4,'Pha nước chấm cân vị & sơ chế rau đồ chua ăn kèm','Nhặt rửa sạch rau củ ăn kèm ngâm nước mát cho giòn tươi, bào sợi hoặc thái lát gọn gàng bày sẵn bên cạnh. Pha chén nước chấm chua ngọt hoặc muối ớt chanh sả sánh thơm theo khẩu vị vùng miền của món Heo quay kho cải chua để cân bằng độ béo giòn.',5,'Luôn chuẩn bị xong rau sống và bát nước chấm trước khi chiên/nướng mẻ cuối để món ăn vừa ra lò là thưởng thức nóng giòn ngay.'),
(38,5,'Làm nóng dầu / lò nướng chuẩn nhiệt & làm chín đều lần 1','Làm nóng chảo dầu hoặc vỉ nướng/nồi chiên ở mức nhiệt vừa khoảng 165–175°C, xếp 500g thịt heo quay và 350g dưa cải chua vào với khoảng cách thoáng đều nhau. Chiên hoặc nướng trở mặt nhịp nhàng trên lửa vừa để nhiệt dẫn sâu làm chín mềm ngọt hoàn toàn phần nhân bên trong. Thêm nước dừa, nước mắm và đường, đun sôi. Xếp heo quay phần thịt xuống nước kho, om lửa nhỏ 15 phút.',10,'Kiểm tra nhiệt dầu bằng đầu đũa tre thấy sủi tăm nhỏ đều là đạt chuẩn 170°C, giúp vỏ không cháy sớm khi bên trong còn sống.'),
(38,6,'Tăng nhiệt khóa giòn rụm vàng ươm bề mặt lần 2','Ở 2–3 phút cuối, tăng lên lửa vừa lớn (khoảng 190°C) hoặc phết thêm lớp dầu điều/mật ong mỏng để vỏ ngoài của Heo quay kho cải chua chuyển sắc vàng óng ánh và nổ giòn rụm. Lắng nghe tiếng xèo giòn rộn rã và hương thơm phức lan tỏa khắp bếp thì gắp ra vỉ thưa cho ráo dầu thừa.',5,'Đặt đồ chiên nướng lên giá inox thoáng khí thay vì giấy thấm dầu chồng khít để hơi nước thoát hết, giữ độ giòn lâu gấp 3 lần.'),
(38,7,'Trình bày bắt mắt kèm rau thơm & thưởng thức nóng','Xếp thành phẩm vàng giòn ra đĩa lớn có bày sẵn rau củ ăn kèm và điểm xuyết hành ngò và tiêu xay tươi xanh hài hòa màu sắc. Dọn kèm chén nước chấm sánh đậm ngay chính giữa mâm ăn cho 4 người thưởng thức khi vỏ ngoài còn nóng giòn rụm. Trở miếng thịt để thấm nhưng giữ phần bì trên mặt nếu muốn giòn. Nếm lại độ mặn, thêm ớt tùy thích và dùng nóng.',4,'Cắt miếng hoặc dọn ăn ngay trong vòng 10 phút sau khi rời bếp để cảm nhận trọn vẹn sự đối lập giòn ngoài - mềm ngọt bên trong.'),
(39,1,'Sơ chế & thái mỏng đồng đều nguyên liệu xào','Làm sạch và thấm ráo 250g miến dong và 220g thịt cua, dùng dao sắc thái lát mỏng vừa ăn khoảng 2–3mm ngang thớ để khi xào nhanh chín mềm không bị dai. Nhặt rửa sạch rau củ ăn kèm, cắt khúc xéo 4cm hoặc tách nhánh đồng đều giúp tiếp xúc nhiệt nhanh trên chảo. Ngâm miến trong nước mát 8–10 phút đến khi mềm dẻo nhưng chưa nhũn; để ráo và cắt ngắn. Ngâm nấm, thái lát.',8,'Nguyên liệu xào bắt buộc phải để thật ráo nước trước khi cho vào chảo để đạt hiệu ứng áp nhiệt thơm kiểu chảo gang.'),
(39,2,'Ướp mềm nguyên liệu đạm & pha sẵn chén sốt xào','Ướp phần đạm trong 250g miến dong và 220g thịt cua với 1/3 lượng hành tím và tỏi băm nhỏ, chút dầu ăn và 1/3 lượng 15ml nước mắm và 2g tiêu trong 10 phút để giữ độ ẩm mọng. Pha phần 15ml nước mắm và 2g tiêu còn lại cùng 20ml nước lọc vào chén nhỏ khuấy tan hoàn toàn để thao tác xào lửa lớn diễn ra dứt khoát. Đánh trứng, tráng mỏng rồi thái sợi. Bào cà rốt; kiểm tra thịt cua bỏ hết mảnh vỏ.',6,'Thêm 1 muỗng cà phê dầu ăn vào bước ướp thịt bò/heo giúp khóa ẩm và các lát thịt tơi nhanh không bị dính chùm khi gặp chảo nóng.'),
(39,3,'Chần nhanh rau củ giữ sắc xanh ngọc & độ giòn','Đun sôi nồi nước nhỏ với một nhúm muối, thả rau củ ăn kèm vào chần nhanh 30–45 giây rồi vớt ngay ra tô nước đá lạnh cho sốc nhiệt, sau đó đổ ra rổ cho thật ráo. Bước tiền xử lý này giúp rau củ chín đều từ trong mà bên ngoài vẫn xanh mướt giòn sần sật.',5,'Thời gian chần dưới 1 phút kết hợp ngâm nước đá lạnh là bí quyết nhà hàng giúp đĩa rau xào không bị chảy nước đen đĩa.'),
(39,4,'Xào săn nguyên liệu chính trên lửa lớn nhanh tay','Làm nóng chảo rộng trên lửa lớn nhất với 15ml dầu ăn, phi dậy mùi một nửa hành tím và tỏi băm nhỏ rồi trút phần đạm chính trong 250g miến dong và 220g thịt cua vào đảo cực nhanh tay trong 60–90 giây. Ngay khi thịt hoặc hải sản vừa chín tái hồng khoảng 85%, lập tức trút riêng ra đĩa sạch để không bị quá lửa khô xác. Phi thơm hành, xào nấm và cà rốt 3 phút. Thêm cua, đảo nhẹ đến nóng; không nghiền nát thớ cua.',6,'Tuyệt đối không xào thịt chung từ đầu đến cuối với rau củ vì thịt sẽ bị dai và tiết nước làm mất độ giòn.'),
(39,5,'Xào rau củ lửa lớn & rưới sốt định lượng khóa vị','Giữ nguyên chảo nóng trên lửa lớn, thêm chút dầu phi thơm nốt phần hành tím và tỏi băm nhỏ còn lại rồi cho rau củ ăn kèm đã ráo nước vào đảo đều 1–2 phút. Trút ngược đĩa đạm vào chảo, rưới đều chén sốt gia vị đã pha và xóc nhanh tay 45 giây cho sốt sánh bóng áo quanh từng miếng nguyên liệu.',6,'Rưới sốt vòng quanh thành chảo nóng thay vì đổ thẳng giữa lòng chảo giúp sốt bốc hơi thơm lừng và sệt lại tức thì.'),
(39,6,'Dậy hương tiêu hành & trình bày nóng hổi','Cho 20g hành lá vào đảo nhẹ đúng 1 lượt rồi tắt bếp ngay khi khói thơm bốc lên nghi ngút. Gắp món Miến xào cua ra đĩa rộng lòng để tản nhiệt đều, tránh đậy kín vung và thưởng thức nóng ngay cùng cơm dẻo cho 4 người. Cho miến và 60 ml nước vào chảo, đảo tơi đến khi miến trong mềm. Nêm nước mắm, thêm trứng và hành lá, rắc tiêu.',4,'Bày món xào ra đĩa rộng không xếp chồng quá dày giúp hơi nóng thoát nhẹ, giữ rau củ giòn ngọt lâu đến miếng cuối cùng.'),
(40,1,'Sơ chế sạch & cắt thái nguyên liệu đúng kích cỡ','Rửa sạch 500g cá bống cùng các nguyên liệu phối kèm dưới vòi nước mát rồi để thật ráo trên rổ thưa. Dùng dao sắc cắt thái nguyên liệu thành từng khúc hoặc khối vuông đều đặn khoảng 3.5–4cm để khi kho hầm giữ nguyên hình dáng đẹp mắt mà không bị vụn nát. Bỏ ruột cá, rửa nhanh rồi để thật ráo. Ướp cá với nước mắm, hành tím băm và một nửa tiêu trong 10 phút.',6,'Cắt miếng thịt/cá dày dặn đồng đều giúp quá trình kho lâu trên lửa nhỏ thớ thịt mềm rục mà vẫn giữ trọn độ mọng ngọt bên trong.'),
(40,2,'Khử mùi tự nhiên & làm săn sạch bề mặt nguyên liệu','Chà nhẹ phần đạm chính trong 500g cá bống với chút muối hạt, lát gừng đập dập hoặc chần sơ qua nước sôi 90 giây rồi rửa sạch lại bằng nước ấm, để ráo hoàn toàn. Công đoạn này loại bỏ triệt để tạp chất và mùi tanh hôi, giúp nước sốt món Cá bống kho tiêu trong bóng thơm ngon.',5,'Sau khi chần hoặc rửa sạch, để nguyên liệu ráo nước ít nhất 5 phút trước khi ướp để gia vị rút sâu trực tiếp vào từng thớ thịt.'),
(40,3,'Pha hỗn hợp gia vị & ướp thấm chuẩn định lượng','Cho 500g cá bống vào tô lớn, ướp cùng một nửa 20g hành tím băm nhỏ và định lượng chuẩn 30ml nước mắm, 12g đường, 4g tiêu và 1 quả ớt, đảo nhẹ tay cho gia vị phủ kín đều các mặt. Bọc kín tô và để nguyên liệu nghỉ thấm vị tối thiểu 20 phút ở nhiệt độ phòng (hoặc ngăn mát tủ lạnh). Đun đường trong nồi nhỏ đến màu cánh gián, thêm 2 thìa nước nóng; khuấy cẩn thận tránh bắn.',7,'Ướp đủ tối thiểu 20 phút trước khi bắc lên bếp là chìa khóa để tâm miếng thịt/cá đậm đà đồng nhất với lớp sốt bên ngoài.'),
(40,4,'Thắng nước màu cánh gián & phi dậy hương hành tỏi','Đặt nồi đáy dày lên bếp ở lửa vừa nhỏ, thắng nhẹ 15g đường với 15ml dầu ăn đến khi chuyển sắc nâu cánh gián óng ả thì cho ngay phần 20g hành tím còn lại vào phi thơm lừng. Hương caramel dịu ngọt quyện cùng tinh dầu hành tỏi sả tạo nền màu nâu hổ phách truyền thống đầy cuốn hút.',4,'Canh kỹ khoảnh khắc đường vừa chuyển màu cánh gián là hạ lửa nhỏ nhất ngay để nước màu bóng đẹp mà không bao giờ bị đắng.'),
(40,5,'Đảo săn hai mặt khóa ngọt nguyên liệu chính','Tăng lên lửa vừa lớn, gắp từng miếng trong 500g cá bống vào nồi đảo đều hoặc trở nhẹ hai mặt trong 4–5 phút cho săn chắc và bám đều lớp màu nâu óng. Khi bề mặt nguyên liệu se vàng thơm phức mới trút phần nước ướp còn lại trong tô vào đun sôi nhẹ. Xếp cá vào nồi, rót nước dừa gần ngập, đun sôi rồi kho nhỏ lửa 20–25 phút. Không khuấy; lắc nồi nhẹ nếu cần.',6,'Đối với cá kho, chỉ lật cá một lần lúc cá vừa săn mặt trên lửa vừa để khúc cá nguyên vẹn không bị tróc da hay vỡ nát.'),
(40,6,'Kho/om liu riu lửa nhỏ thấm đẫm cùng nước dừa/nước dùng','Chế 180ml nước dừa tươi xâm xắp mặt nguyên liệu (xếp thêm rau củ ăn kèm nếu có), đun sôi bùng một dạo hớt sạch bọt rồi hạ ngay về mức lửa nhỏ liu riu nhất. Kho êm đềm không đậy kín nắp để từng thớ nguyên liệu chín mềm thấm đẫm gia vị và nước sốt rút dần sóng sánh. Mở nắp, rắc phần tiêu còn lại và rim đến khi nước kho sánh. Cá chín khi thịt săn và dễ tách; thêm hành lá trước khi ăn.',13,'Luôn dùng nước sôi hoặc nước dừa ấm khi châm thêm vào nồi kho đang nóng để thịt cá không bị sượng cứng trở lại.'),
(40,7,'Thu sánh nước sốt óng ả & trình bày thưởng thức nóng','Khi nước kho rút còn khoảng 1/3 sánh kẹo óng ánh áo đều quanh nguyên liệu và xiên đũa thấy mềm mọng vừa ý, rắc 15g hành lá lên mặt rồi tắt bếp. Múc món Cá bống kho tiêu ra đĩa sâu lòng hoặc niêu đất giữ nhiệt, dọn ăn nóng cùng cơm trắng dẻo thơm cho 4 người.',4,'Giữ lại một lượng nước sốt sánh kẹo vừa đủ dưới đáy nồi để chan cơm hoặc chấm kèm rau luộc sẽ tròn vị đưa cơm gấp bội.'),
(41,1,'Sơ chế sạch & cắt thái nguyên liệu nấu canh','Rửa sạch 250g rau ngót và 180g thịt heo xay, khử mùi tanh bằng chút muối hạt và gừng đập dập rồi rửa lại thật ráo, cắt miếng vừa ăn dày khoảng 2.5–3cm. Đồng thời gọt rửa sạch rau củ ăn kèm, cắt khúc hoặc bổ múi cau đồng đều để khi nấu chín đều không bị nát. Tuốt lá rau ngót, bỏ cọng già, rửa sạch. Vò nhẹ một phần rau để khi nấu mềm và tiết vị ngọt.',4,'Phân loại riêng nhóm củ cứng nấu lâu và nhóm rau lá mềm nhanh chín để cho vào nồi theo đúng thứ tự chuẩn đầu bếp.'),
(41,2,'Ướp thấm gia vị nền cho nguyên liệu đạm','Cho phần đạm chính trong 250g rau ngót và 180g thịt heo xay vào tô, ướp nhẹ với một nửa lượng 15g hành tím và 15ml nước mắm, 3g muối và 1g tiêu trong khoảng 10 phút. Đảo nhẹ tay cho gia vị áo đều bề mặt giúp miếng thịt, cá săn chắc và đậm đà từ bên trong khi thả vào nước canh. Phi hành tím với ít dầu, cho thịt băm vào đảo tơi đến khi đổi màu; nêm một chút nước mắm.',4,'Không ướp quá mặn ở bước này để giữ vị thanh mát tự nhiên của nước canh sau khi hoàn tất.'),
(41,3,'Phi thơm hành tỏi & xào săn khóa ngọt nguyên liệu','Đặt nồi canh lên bếp ở lửa vừa, làm nóng 15ml dầu ăn rồi phi thơm phần 15g hành tím còn lại đến khi dậy mùi vàng óng. Trút nguyên liệu chính đã ướp vào đảo săn 2–3 phút cho bề mặt se lại, khóa trọn nước ngọt tự nhiên bên trong thớ thịt.',4,'Xào săn nguyên liệu đạm với hành tỏi phi trước khi đổ nước sôi giúp nước canh thơm ngọt đậm đà mà không hề tanh.'),
(41,4,'Đun sôi nước canh & hớt bọt giữ độ trong veo','Chế khoảng 1.1–1.3 lít nước (kết hợp 900ml nước lọc và 8ml dầu ăn) vào nồi, bật lửa lớn đun đến khi sôi bùng rồi hạ ngay về lửa vừa. Dùng muôi hớt sạch lớp bọt đầu nổi lên trên mặt nước để nồi canh Canh rau ngót thịt băm đạt độ trong thanh đẹp mắt. Châm nước, đun sôi và hớt bọt. Thả rau ngót vào, khuấy tách lá và nấu 5–7 phút.',6,'Sử dụng nước ấm hoặc nước sôi khi chế vào cá tươi sẽ giúp cá không bao giờ bị tanh nồng dù để nguội.'),
(41,5,'Thả rau củ theo độ chín & cân chỉnh định lượng vị','Lần lượt cho rau củ ăn kèm vào nồi canh đang sôi vừa (nhóm củ quả lâu chín cho trước 5–7 phút, nhóm rau mềm cho sau 1–2 phút). Nêm phần 15ml nước mắm, 3g muối và 1g tiêu còn lại, khuấy nhẹ và nếm thử thấy vị chua thanh hoặc ngọt dịu cân bằng đúng khẩu phần 4 người.',5,'Không đậy kín nắp vung sau khi đã thả các loại rau xanh vào nồi để giữ màu xanh ngọc tươi tắn hấp dẫn.');
INSERT INTO `recipe_steps` (`recipe_id`,`step_order`,`title`,`instruction`,`duration_mins`,`tip_note`) VALUES
(41,6,'Điểm hương rau thơm & múc canh dọn nóng','Khi toàn bộ nguyên liệu vừa chín tới mềm ngọt, rắc ngay hành ngò và tiêu xay vào nồi rồi tắt bếp liền tay để giữ trọn tinh dầu thơm mát. Múc canh nóng hổi ra tô lớn, rắc thêm chút tiêu xay hoặc tỏi phi vàng và dùng ngay với cơm nóng. Khi rau mềm nhưng còn xanh, nêm muối và nước mắm còn lại. Tắt bếp, rắc tiêu; không đun lâu làm rau xỉn màu.',2,'Các loại rau thơm như thì là, ngò gai, rau om hay lá lốt chỉ nên thả ngay khoảnh khắc tắt bếp để hương thơm bùng nổ nhất.'),
(42,1,'Sơ chế sạch & cắt thái nguyên liệu nấu canh','Rửa sạch 300g cải xanh và 180g thịt heo xay, khử mùi tanh bằng chút muối hạt và gừng đập dập rồi rửa lại thật ráo, cắt miếng vừa ăn dày khoảng 2.5–3cm. Đồng thời gọt rửa sạch rau củ ăn kèm, cắt khúc hoặc bổ múi cau đồng đều để khi nấu chín đều không bị nát. Nhặt cải, rửa kỹ từng bẹ và cắt khúc 3 cm. Thái gừng lát mỏng, băm hành tím.',4,'Phân loại riêng nhóm củ cứng nấu lâu và nhóm rau lá mềm nhanh chín để cho vào nồi theo đúng thứ tự chuẩn đầu bếp.'),
(42,2,'Ướp thấm gia vị nền cho nguyên liệu đạm','Cho phần đạm chính trong 300g cải xanh và 180g thịt heo xay vào tô, ướp nhẹ với một nửa lượng 12g gừng và 15g hành tím và 15ml nước mắm và 3g muối trong khoảng 10 phút. Đảo nhẹ tay cho gia vị áo đều bề mặt giúp miếng thịt, cá săn chắc và đậm đà từ bên trong khi thả vào nước canh. Phi hành, cho thịt băm vào đảo tơi đến khi săn; thêm một chút nước mắm và gừng.',4,'Không ướp quá mặn ở bước này để giữ vị thanh mát tự nhiên của nước canh sau khi hoàn tất.'),
(42,3,'Phi thơm hành tỏi & xào săn khóa ngọt nguyên liệu','Đặt nồi canh lên bếp ở lửa vừa, làm nóng 15ml dầu ăn rồi phi thơm phần 12g gừng và 15g hành tím còn lại đến khi dậy mùi vàng óng. Trút nguyên liệu chính đã ướp vào đảo săn 2–3 phút cho bề mặt se lại, khóa trọn nước ngọt tự nhiên bên trong thớ thịt.',4,'Xào săn nguyên liệu đạm với hành tỏi phi trước khi đổ nước sôi giúp nước canh thơm ngọt đậm đà mà không hề tanh.'),
(42,4,'Đun sôi nước canh & hớt bọt giữ độ trong veo','Chế khoảng 1.1–1.3 lít nước (kết hợp 900ml nước lọc và 8ml dầu ăn) vào nồi, bật lửa lớn đun đến khi sôi bùng rồi hạ ngay về lửa vừa. Dùng muôi hớt sạch lớp bọt đầu nổi lên trên mặt nước để nồi canh Canh cải xanh nấu thịt bằm đạt độ trong thanh đẹp mắt. Thêm nước, đun sôi và vớt bọt. Cho phần cọng cải vào trước 2 phút rồi mới thêm lá.',6,'Sử dụng nước ấm hoặc nước sôi khi chế vào cá tươi sẽ giúp cá không bao giờ bị tanh nồng dù để nguội.'),
(42,5,'Thả rau củ theo độ chín & cân chỉnh định lượng vị','Lần lượt cho rau củ ăn kèm vào nồi canh đang sôi vừa (nhóm củ quả lâu chín cho trước 5–7 phút, nhóm rau mềm cho sau 1–2 phút). Nêm phần 15ml nước mắm và 3g muối còn lại, khuấy nhẹ và nếm thử thấy vị chua thanh hoặc ngọt dịu cân bằng đúng khẩu phần 4 người.',5,'Không đậy kín nắp vung sau khi đã thả các loại rau xanh vào nồi để giữ màu xanh ngọc tươi tắn hấp dẫn.'),
(42,6,'Điểm hương rau thơm & múc canh dọn nóng','Khi toàn bộ nguyên liệu vừa chín tới mềm ngọt, rắc ngay hành ngò và tiêu xay vào nồi rồi tắt bếp liền tay để giữ trọn tinh dầu thơm mát. Múc canh nóng hổi ra tô lớn, rắc thêm chút tiêu xay hoặc tỏi phi vàng và dùng ngay với cơm nóng. Nấu đến khi cải vừa mềm, nêm muối và nước mắm còn lại. Tắt bếp, dùng nóng để cải không bị nhũn.',2,'Các loại rau thơm như thì là, ngò gai, rau om hay lá lốt chỉ nên thả ngay khoảnh khắc tắt bếp để hương thơm bùng nổ nhất.'),
(43,1,'Sơ chế sạch & cắt thái nguyên liệu nấu canh','Rửa sạch 300g mồng tơi và 220g tôm sú, khử mùi tanh bằng chút muối hạt và gừng đập dập rồi rửa lại thật ráo, cắt miếng vừa ăn dày khoảng 2.5–3cm. Đồng thời gọt rửa sạch rau củ ăn kèm, cắt khúc hoặc bổ múi cau đồng đều để khi nấu chín đều không bị nát. Nhặt mồng tơi, rửa sạch và vò nhẹ lá to. Bóc vỏ tôm, bỏ chỉ lưng, băm dập một nửa để nước canh ngọt hơn.',4,'Phân loại riêng nhóm củ cứng nấu lâu và nhóm rau lá mềm nhanh chín để cho vào nồi theo đúng thứ tự chuẩn đầu bếp.'),
(43,2,'Ướp thấm gia vị nền cho nguyên liệu đạm','Cho phần đạm chính trong 300g mồng tơi và 220g tôm sú vào tô, ướp nhẹ với một nửa lượng 15g hành tím và 15ml nước mắm, 3g muối và 1g tiêu trong khoảng 10 phút. Đảo nhẹ tay cho gia vị áo đều bề mặt giúp miếng thịt, cá săn chắc và đậm đà từ bên trong khi thả vào nước canh. Phi hành tím, cho tôm vào đảo đến khi chuyển hồng; nêm một ít nước mắm.',4,'Không ướp quá mặn ở bước này để giữ vị thanh mát tự nhiên của nước canh sau khi hoàn tất.'),
(43,3,'Phi thơm hành tỏi & xào săn khóa ngọt nguyên liệu','Đặt nồi canh lên bếp ở lửa vừa, làm nóng 15ml dầu ăn rồi phi thơm phần 15g hành tím còn lại đến khi dậy mùi vàng óng. Trút nguyên liệu chính đã ướp vào đảo săn 2–3 phút cho bề mặt se lại, khóa trọn nước ngọt tự nhiên bên trong thớ thịt.',3,'Xào săn nguyên liệu đạm với hành tỏi phi trước khi đổ nước sôi giúp nước canh thơm ngọt đậm đà mà không hề tanh.'),
(43,4,'Đun sôi nước canh & hớt bọt giữ độ trong veo','Chế khoảng 1.1–1.3 lít nước (kết hợp 900ml nước lọc và 8ml dầu ăn) vào nồi, bật lửa lớn đun đến khi sôi bùng rồi hạ ngay về lửa vừa. Dùng muôi hớt sạch lớp bọt đầu nổi lên trên mặt nước để nồi canh Canh mồng tơi nấu tôm đạt độ trong thanh đẹp mắt. Châm nước, đun sôi và hớt bọt. Nêm muối vừa nhạt trước khi cho rau.',6,'Sử dụng nước ấm hoặc nước sôi khi chế vào cá tươi sẽ giúp cá không bao giờ bị tanh nồng dù để nguội.'),
(43,5,'Thả rau củ theo độ chín & cân chỉnh định lượng vị','Lần lượt cho rau củ ăn kèm vào nồi canh đang sôi vừa (nhóm củ quả lâu chín cho trước 5–7 phút, nhóm rau mềm cho sau 1–2 phút). Nêm phần 15ml nước mắm, 3g muối và 1g tiêu còn lại, khuấy nhẹ và nếm thử thấy vị chua thanh hoặc ngọt dịu cân bằng đúng khẩu phần 4 người.',5,'Không đậy kín nắp vung sau khi đã thả các loại rau xanh vào nồi để giữ màu xanh ngọc tươi tắn hấp dẫn.'),
(43,6,'Điểm hương rau thơm & múc canh dọn nóng','Khi toàn bộ nguyên liệu vừa chín tới mềm ngọt, rắc ngay hành ngò và tiêu xay vào nồi rồi tắt bếp liền tay để giữ trọn tinh dầu thơm mát. Múc canh nóng hổi ra tô lớn, rắc thêm chút tiêu xay hoặc tỏi phi vàng và dùng ngay với cơm nóng. Thả mồng tơi, đảo nhẹ và nấu 2–3 phút đến khi lá mềm. Nếm lại nước mắm, tắt bếp và rắc tiêu.',2,'Các loại rau thơm như thì là, ngò gai, rau om hay lá lốt chỉ nên thả ngay khoảnh khắc tắt bếp để hương thơm bùng nổ nhất.'),
(44,1,'Sơ chế sạch & cắt thái nguyên liệu nấu canh','Rửa sạch 300g tôm sú và 180g dứa, khử mùi tanh bằng chút muối hạt và gừng đập dập rồi rửa lại thật ráo, cắt miếng vừa ăn dày khoảng 2.5–3cm. Đồng thời gọt rửa sạch 120g đậu bắp và 100g giá đỗ, cắt khúc hoặc bổ múi cau đồng đều để khi nấu chín đều không bị nát. Bóc vỏ, rút chỉ tôm. Cắt dứa, cà chua và đậu bắp; dầm me với 100 ml nước nóng, lọc lấy nước chua.',6,'Phân loại riêng nhóm củ cứng nấu lâu và nhóm rau lá mềm nhanh chín để cho vào nồi theo đúng thứ tự chuẩn đầu bếp.'),
(44,2,'Ướp thấm gia vị nền cho nguyên liệu đạm','Cho phần đạm chính trong 300g tôm sú và 180g dứa vào tô, ướp nhẹ với một nửa lượng hành tím và tỏi băm nhỏ và 30g me vắt và 25ml nước mắm trong khoảng 10 phút. Đảo nhẹ tay cho gia vị áo đều bề mặt giúp miếng thịt, cá săn chắc và đậm đà từ bên trong khi thả vào nước canh. Đun 1,2 lít nước với nước me, dứa và cà chua 5 phút. Hớt bọt, nêm nước mắm và nếm độ chua.',6,'Không ướp quá mặn ở bước này để giữ vị thanh mát tự nhiên của nước canh sau khi hoàn tất.'),
(44,3,'Phi thơm hành tỏi & xào săn khóa ngọt nguyên liệu','Đặt nồi canh lên bếp ở lửa vừa, làm nóng 15ml dầu ăn rồi phi thơm phần hành tím và tỏi băm nhỏ còn lại đến khi dậy mùi vàng óng. Trút nguyên liệu chính đã ướp vào đảo săn 2–3 phút cho bề mặt se lại, khóa trọn nước ngọt tự nhiên bên trong thớ thịt.',5,'Xào săn nguyên liệu đạm với hành tỏi phi trước khi đổ nước sôi giúp nước canh thơm ngọt đậm đà mà không hề tanh.'),
(44,4,'Đun sôi nước canh & hớt bọt giữ độ trong veo','Chế khoảng 1.1–1.3 lít nước (kết hợp 1.2l nước lọc) vào nồi, bật lửa lớn đun đến khi sôi bùng rồi hạ ngay về lửa vừa. Dùng muôi hớt sạch lớp bọt đầu nổi lên trên mặt nước để nồi canh Canh chua tôm đạt độ trong thanh đẹp mắt. Thả tôm vào nước đang sôi nhẹ; nấu đến khi tôm vừa hồng đục. Thêm đậu bắp, nấu thêm 3 phút.',8,'Sử dụng nước ấm hoặc nước sôi khi chế vào cá tươi sẽ giúp cá không bao giờ bị tanh nồng dù để nguội.'),
(44,5,'Thả rau củ theo độ chín & cân chỉnh định lượng vị','Lần lượt cho 120g đậu bắp và 100g giá đỗ vào nồi canh đang sôi vừa (nhóm củ quả lâu chín cho trước 5–7 phút, nhóm rau mềm cho sau 1–2 phút). Nêm phần 30g me vắt và 25ml nước mắm còn lại, khuấy nhẹ và nếm thử thấy vị chua thanh hoặc ngọt dịu cân bằng đúng khẩu phần 4 người.',7,'Không đậy kín nắp vung sau khi đã thả các loại rau xanh vào nồi để giữ màu xanh ngọc tươi tắn hấp dẫn.'),
(44,6,'Điểm hương rau thơm & múc canh dọn nóng','Khi toàn bộ nguyên liệu vừa chín tới mềm ngọt, rắc ngay 15g rau om vào nồi rồi tắt bếp liền tay để giữ trọn tinh dầu thơm mát. Múc canh nóng hổi ra tô lớn, rắc thêm chút tiêu xay hoặc tỏi phi vàng và dùng ngay với cơm nóng. Cho giá vào cuối, đun 30 giây rồi tắt bếp. Rắc rau om; điều chỉnh chua bằng nước me và mặn bằng nước mắm.',4,'Các loại rau thơm như thì là, ngò gai, rau om hay lá lốt chỉ nên thả ngay khoảnh khắc tắt bếp để hương thơm bùng nổ nhất.'),
(45,1,'Sơ chế sạch & cắt thái nguyên liệu nấu canh','Rửa sạch 250g cua đồng xay và 250g mồng tơi, khử mùi tanh bằng chút muối hạt và gừng đập dập rồi rửa lại thật ráo, cắt miếng vừa ăn dày khoảng 2.5–3cm. Đồng thời gọt rửa sạch 200g mướp hương, cắt khúc hoặc bổ múi cau đồng đều để khi nấu chín đều không bị nát. Hòa cua xay với 1,2 lít nước và chút muối, khuấy đều rồi lọc qua rây hai lần để bỏ bã cứng.',7,'Phân loại riêng nhóm củ cứng nấu lâu và nhóm rau lá mềm nhanh chín để cho vào nồi theo đúng thứ tự chuẩn đầu bếp.'),
(45,2,'Ướp thấm gia vị nền cho nguyên liệu đạm','Cho phần đạm chính trong 250g cua đồng xay và 250g mồng tơi vào tô, ướp nhẹ với một nửa lượng 15g hành tím và 15ml nước mắm và 4g muối trong khoảng 10 phút. Đảo nhẹ tay cho gia vị áo đều bề mặt giúp miếng thịt, cá săn chắc và đậm đà từ bên trong khi thả vào nước canh. Đặt nước cua lên lửa vừa, khuấy nhẹ đáy nồi lúc đầu. Khi riêu kết lại và nổi lên, hạ lửa, vớt riêu ra bát.',6,'Không ướp quá mặn ở bước này để giữ vị thanh mát tự nhiên của nước canh sau khi hoàn tất.'),
(45,3,'Phi thơm hành tỏi & xào săn khóa ngọt nguyên liệu','Đặt nồi canh lên bếp ở lửa vừa, làm nóng 15ml dầu ăn rồi phi thơm phần 15g hành tím còn lại đến khi dậy mùi vàng óng. Trút nguyên liệu chính đã ướp vào đảo săn 2–3 phút cho bề mặt se lại, khóa trọn nước ngọt tự nhiên bên trong thớ thịt.',6,'Xào săn nguyên liệu đạm với hành tỏi phi trước khi đổ nước sôi giúp nước canh thơm ngọt đậm đà mà không hề tanh.'),
(45,4,'Đun sôi nước canh & hớt bọt giữ độ trong veo','Chế khoảng 1.1–1.3 lít nước (kết hợp 1.2l nước lọc và 8ml dầu ăn) vào nồi, bật lửa lớn đun đến khi sôi bùng rồi hạ ngay về lửa vừa. Dùng muôi hớt sạch lớp bọt đầu nổi lên trên mặt nước để nồi canh Canh riêu cua mồng tơi đạt độ trong thanh đẹp mắt. Phi hành tím, xào cà chua 2 phút rồi cho vào nồi nước cua. Thêm mướp, nấu 3 phút; tiếp đó cho mồng tơi.',9,'Sử dụng nước ấm hoặc nước sôi khi chế vào cá tươi sẽ giúp cá không bao giờ bị tanh nồng dù để nguội.'),
(45,5,'Thả rau củ theo độ chín & cân chỉnh định lượng vị','Lần lượt cho 200g mướp hương vào nồi canh đang sôi vừa (nhóm củ quả lâu chín cho trước 5–7 phút, nhóm rau mềm cho sau 1–2 phút). Nêm phần 15ml nước mắm và 4g muối còn lại, khuấy nhẹ và nếm thử thấy vị chua thanh hoặc ngọt dịu cân bằng đúng khẩu phần 4 người.',8,'Không đậy kín nắp vung sau khi đã thả các loại rau xanh vào nồi để giữ màu xanh ngọc tươi tắn hấp dẫn.'),
(45,6,'Điểm hương rau thơm & múc canh dọn nóng','Khi toàn bộ nguyên liệu vừa chín tới mềm ngọt, rắc ngay hành ngò và tiêu xay vào nồi rồi tắt bếp liền tay để giữ trọn tinh dầu thơm mát. Múc canh nóng hổi ra tô lớn, rắc thêm chút tiêu xay hoặc tỏi phi vàng và dùng ngay với cơm nóng. Nêm nước mắm, đặt riêu cua trở lại nồi và đun sôi nhẹ 1 phút. Không khuấy mạnh để riêu giữ miếng.',4,'Các loại rau thơm như thì là, ngò gai, rau om hay lá lốt chỉ nên thả ngay khoảnh khắc tắt bếp để hương thơm bùng nổ nhất.');
INSERT INTO `recipe_steps` (`recipe_id`,`step_order`,`title`,`instruction`,`duration_mins`,`tip_note`) VALUES
(46,1,'Sơ chế sạch & cắt thái nguyên liệu nấu canh','Rửa sạch 400g khoai mỡ và 220g tôm sú, khử mùi tanh bằng chút muối hạt và gừng đập dập rồi rửa lại thật ráo, cắt miếng vừa ăn dày khoảng 2.5–3cm. Đồng thời gọt rửa sạch rau củ ăn kèm, cắt khúc hoặc bổ múi cau đồng đều để khi nấu chín đều không bị nát. Gọt khoai mỡ, rửa và bào sợi lớn hoặc giã dập. Bóc tôm, rút chỉ lưng, băm thô.',6,'Phân loại riêng nhóm củ cứng nấu lâu và nhóm rau lá mềm nhanh chín để cho vào nồi theo đúng thứ tự chuẩn đầu bếp.'),
(46,2,'Ướp thấm gia vị nền cho nguyên liệu đạm','Cho phần đạm chính trong 400g khoai mỡ và 220g tôm sú vào tô, ướp nhẹ với một nửa lượng 15g hành tím và 15ml nước mắm, 3g muối và 1g tiêu trong khoảng 10 phút. Đảo nhẹ tay cho gia vị áo đều bề mặt giúp miếng thịt, cá săn chắc và đậm đà từ bên trong khi thả vào nước canh. Phi hành tím, cho tôm vào xào đến khi đổi màu; nêm ít nước mắm và tiêu.',5,'Không ướp quá mặn ở bước này để giữ vị thanh mát tự nhiên của nước canh sau khi hoàn tất.'),
(46,3,'Phi thơm hành tỏi & xào săn khóa ngọt nguyên liệu','Đặt nồi canh lên bếp ở lửa vừa, làm nóng 15ml dầu ăn rồi phi thơm phần 15g hành tím còn lại đến khi dậy mùi vàng óng. Trút nguyên liệu chính đã ướp vào đảo săn 2–3 phút cho bề mặt se lại, khóa trọn nước ngọt tự nhiên bên trong thớ thịt.',5,'Xào săn nguyên liệu đạm với hành tỏi phi trước khi đổ nước sôi giúp nước canh thơm ngọt đậm đà mà không hề tanh.'),
(46,4,'Đun sôi nước canh & hớt bọt giữ độ trong veo','Chế khoảng 1.1–1.3 lít nước (kết hợp 900ml nước lọc và 8ml dầu ăn) vào nồi, bật lửa lớn đun đến khi sôi bùng rồi hạ ngay về lửa vừa. Dùng muôi hớt sạch lớp bọt đầu nổi lên trên mặt nước để nồi canh Canh khoai mỡ nấu tôm đạt độ trong thanh đẹp mắt. Châm nước, đun sôi, cho khoai vào từng ít một và khuấy để khoai không vón. Hạ lửa, nấu 10–12 phút.',7,'Sử dụng nước ấm hoặc nước sôi khi chế vào cá tươi sẽ giúp cá không bao giờ bị tanh nồng dù để nguội.'),
(46,5,'Thả rau củ theo độ chín & cân chỉnh định lượng vị','Lần lượt cho rau củ ăn kèm vào nồi canh đang sôi vừa (nhóm củ quả lâu chín cho trước 5–7 phút, nhóm rau mềm cho sau 1–2 phút). Nêm phần 15ml nước mắm, 3g muối và 1g tiêu còn lại, khuấy nhẹ và nếm thử thấy vị chua thanh hoặc ngọt dịu cân bằng đúng khẩu phần 4 người.',7,'Không đậy kín nắp vung sau khi đã thả các loại rau xanh vào nồi để giữ màu xanh ngọc tươi tắn hấp dẫn.'),
(46,6,'Điểm hương rau thơm & múc canh dọn nóng','Khi toàn bộ nguyên liệu vừa chín tới mềm ngọt, rắc ngay 15g hành lá vào nồi rồi tắt bếp liền tay để giữ trọn tinh dầu thơm mát. Múc canh nóng hổi ra tô lớn, rắc thêm chút tiêu xay hoặc tỏi phi vàng và dùng ngay với cơm nóng. Khi khoai mềm sánh, nếm muối và nước mắm. Tắt bếp, thêm hành lá và tiêu; nếu canh đặc, châm nước sôi.',3,'Các loại rau thơm như thì là, ngò gai, rau om hay lá lốt chỉ nên thả ngay khoảnh khắc tắt bếp để hương thơm bùng nổ nhất.'),
(47,1,'Sơ chế sạch & cắt thái nguyên liệu nấu canh','Rửa sạch 300g cà chua và 3 quả trứng gà, khử mùi tanh bằng chút muối hạt và gừng đập dập rồi rửa lại thật ráo, cắt miếng vừa ăn dày khoảng 2.5–3cm. Đồng thời gọt rửa sạch rau củ ăn kèm, cắt khúc hoặc bổ múi cau đồng đều để khi nấu chín đều không bị nát. Cắt cà chua múi cau, băm hành tím và thái hành lá. Đánh trứng vừa tan, không đánh nổi bọt.',4,'Phân loại riêng nhóm củ cứng nấu lâu và nhóm rau lá mềm nhanh chín để cho vào nồi theo đúng thứ tự chuẩn đầu bếp.'),
(47,2,'Ướp thấm gia vị nền cho nguyên liệu đạm','Cho phần đạm chính trong 300g cà chua và 3 quả trứng gà vào tô, ướp nhẹ với một nửa lượng 12g hành tím và 12ml nước mắm, 3g muối và 1g tiêu trong khoảng 10 phút. Đảo nhẹ tay cho gia vị áo đều bề mặt giúp miếng thịt, cá săn chắc và đậm đà từ bên trong khi thả vào nước canh. Phi hành tím, cho cà chua vào xào 3 phút đến khi mềm và ra nước. Châm nước, đun sôi nhẹ.',3,'Không ướp quá mặn ở bước này để giữ vị thanh mát tự nhiên của nước canh sau khi hoàn tất.'),
(47,3,'Phi thơm hành tỏi & xào săn khóa ngọt nguyên liệu','Đặt nồi canh lên bếp ở lửa vừa, làm nóng 15ml dầu ăn rồi phi thơm phần 12g hành tím còn lại đến khi dậy mùi vàng óng. Trút nguyên liệu chính đã ướp vào đảo săn 2–3 phút cho bề mặt se lại, khóa trọn nước ngọt tự nhiên bên trong thớ thịt.',3,'Xào săn nguyên liệu đạm với hành tỏi phi trước khi đổ nước sôi giúp nước canh thơm ngọt đậm đà mà không hề tanh.'),
(47,4,'Đun sôi nước canh & hớt bọt giữ độ trong veo','Chế khoảng 1.1–1.3 lít nước (kết hợp 800ml nước lọc và 8ml dầu ăn) vào nồi, bật lửa lớn đun đến khi sôi bùng rồi hạ ngay về lửa vừa. Dùng muôi hớt sạch lớp bọt đầu nổi lên trên mặt nước để nồi canh Canh cà chua trứng đạt độ trong thanh đẹp mắt. Hạ lửa để nước chỉ sôi lăn tăn. Rót trứng thành dòng mảnh quanh nồi, đợi 10 giây rồi khuấy nhẹ một vòng.',4,'Sử dụng nước ấm hoặc nước sôi khi chế vào cá tươi sẽ giúp cá không bao giờ bị tanh nồng dù để nguội.'),
(47,5,'Thả rau củ theo độ chín & cân chỉnh định lượng vị','Lần lượt cho rau củ ăn kèm vào nồi canh đang sôi vừa (nhóm củ quả lâu chín cho trước 5–7 phút, nhóm rau mềm cho sau 1–2 phút). Nêm phần 12ml nước mắm, 3g muối và 1g tiêu còn lại, khuấy nhẹ và nếm thử thấy vị chua thanh hoặc ngọt dịu cân bằng đúng khẩu phần 4 người.',4,'Không đậy kín nắp vung sau khi đã thả các loại rau xanh vào nồi để giữ màu xanh ngọc tươi tắn hấp dẫn.'),
(47,6,'Điểm hương rau thơm & múc canh dọn nóng','Khi toàn bộ nguyên liệu vừa chín tới mềm ngọt, rắc ngay 20g hành lá vào nồi rồi tắt bếp liền tay để giữ trọn tinh dầu thơm mát. Múc canh nóng hổi ra tô lớn, rắc thêm chút tiêu xay hoặc tỏi phi vàng và dùng ngay với cơm nóng. Nêm nước mắm, muối và tiêu. Khi trứng vừa đông, tắt bếp, thêm hành lá và dùng nóng.',2,'Các loại rau thơm như thì là, ngò gai, rau om hay lá lốt chỉ nên thả ngay khoảnh khắc tắt bếp để hương thơm bùng nổ nhất.'),
(48,1,'Sơ chế sạch & cắt thái nguyên liệu nấu canh','Rửa sạch 500g sườn non và 300g dưa cải chua, khử mùi tanh bằng chút muối hạt và gừng đập dập rồi rửa lại thật ráo, cắt miếng vừa ăn dày khoảng 2.5–3cm. Đồng thời gọt rửa sạch rau củ ăn kèm, cắt khúc hoặc bổ múi cau đồng đều để khi nấu chín đều không bị nát. Chặt sườn miếng vừa, chần 3 phút rồi rửa sạch bọt. Rửa dưa cải, nếm thử và xả nếu quá mặn.',13,'Phân loại riêng nhóm củ cứng nấu lâu và nhóm rau lá mềm nhanh chín để cho vào nồi theo đúng thứ tự chuẩn đầu bếp.'),
(48,2,'Ướp thấm gia vị nền cho nguyên liệu đạm','Cho phần đạm chính trong 500g sườn non và 300g dưa cải chua vào tô, ướp nhẹ với một nửa lượng 20g hành tím và 18ml nước mắm và 5g đường trong khoảng 10 phút. Đảo nhẹ tay cho gia vị áo đều bề mặt giúp miếng thịt, cá săn chắc và đậm đà từ bên trong khi thả vào nước canh. Cho sườn và 1,2 lít nước vào nồi, đun sôi rồi hạ nhỏ lửa hầm 35 phút, vớt bọt để nước trong.',11,'Không ướp quá mặn ở bước này để giữ vị thanh mát tự nhiên của nước canh sau khi hoàn tất.'),
(48,3,'Phi thơm hành tỏi & xào săn khóa ngọt nguyên liệu','Đặt nồi canh lên bếp ở lửa vừa, làm nóng 15ml dầu ăn rồi phi thơm phần 20g hành tím còn lại đến khi dậy mùi vàng óng. Trút nguyên liệu chính đã ướp vào đảo săn 2–3 phút cho bề mặt se lại, khóa trọn nước ngọt tự nhiên bên trong thớ thịt.',10,'Xào săn nguyên liệu đạm với hành tỏi phi trước khi đổ nước sôi giúp nước canh thơm ngọt đậm đà mà không hề tanh.'),
(48,4,'Đun sôi nước canh & hớt bọt giữ độ trong veo','Chế khoảng 1.1–1.3 lít nước (kết hợp 1.2l nước lọc và 8ml dầu ăn) vào nồi, bật lửa lớn đun đến khi sôi bùng rồi hạ ngay về lửa vừa. Dùng muôi hớt sạch lớp bọt đầu nổi lên trên mặt nước để nồi canh Canh sườn nấu dưa chua đạt độ trong thanh đẹp mắt. Phi hành, xào cà chua đến mềm rồi thêm dưa cải, đảo 4 phút. Trút hỗn hợp vào nồi sườn, nấu thêm 10 phút.',15,'Sử dụng nước ấm hoặc nước sôi khi chế vào cá tươi sẽ giúp cá không bao giờ bị tanh nồng dù để nguội.'),
(48,5,'Thả rau củ theo độ chín & cân chỉnh định lượng vị','Lần lượt cho rau củ ăn kèm vào nồi canh đang sôi vừa (nhóm củ quả lâu chín cho trước 5–7 phút, nhóm rau mềm cho sau 1–2 phút). Nêm phần 18ml nước mắm và 5g đường còn lại, khuấy nhẹ và nếm thử thấy vị chua thanh hoặc ngọt dịu cân bằng đúng khẩu phần 4 người.',14,'Không đậy kín nắp vung sau khi đã thả các loại rau xanh vào nồi để giữ màu xanh ngọc tươi tắn hấp dẫn.'),
(48,6,'Điểm hương rau thơm & múc canh dọn nóng','Khi toàn bộ nguyên liệu vừa chín tới mềm ngọt, rắc ngay 15g hành lá vào nồi rồi tắt bếp liền tay để giữ trọn tinh dầu thơm mát. Múc canh nóng hổi ra tô lớn, rắc thêm chút tiêu xay hoặc tỏi phi vàng và dùng ngay với cơm nóng. Nếm vị chua mặn của dưa trước khi thêm nước mắm; thêm chút đường nếu chua gắt. Rắc hành lá, dùng khi sườn mềm.',7,'Các loại rau thơm như thì là, ngò gai, rau om hay lá lốt chỉ nên thả ngay khoảnh khắc tắt bếp để hương thơm bùng nổ nhất.'),
(49,1,'Sơ chế sạch & cắt thái nguyên liệu nấu canh','Rửa sạch 250g kim chi và 300g đậu hũ, khử mùi tanh bằng chút muối hạt và gừng đập dập rồi rửa lại thật ráo, cắt miếng vừa ăn dày khoảng 2.5–3cm. Đồng thời gọt rửa sạch 80g hành tây, cắt khúc hoặc bổ múi cau đồng đều để khi nấu chín đều không bị nát. Cắt kim chi miếng vừa và giữ lại ít nước kim chi. Cắt đậu phụ khối, thái hành tây, tách gốc nấm.',4,'Phân loại riêng nhóm củ cứng nấu lâu và nhóm rau lá mềm nhanh chín để cho vào nồi theo đúng thứ tự chuẩn đầu bếp.'),
(49,2,'Ướp thấm gia vị nền cho nguyên liệu đạm','Cho phần đạm chính trong 250g kim chi và 300g đậu hũ vào tô, ướp nhẹ với một nửa lượng hành tím và tỏi băm nhỏ và 15ml nước tương trong khoảng 10 phút. Đảo nhẹ tay cho gia vị áo đều bề mặt giúp miếng thịt, cá săn chắc và đậm đà từ bên trong khi thả vào nước canh. Làm nóng dầu mè, xào hành tây và kim chi 3–4 phút để dậy mùi. Thêm tương ớt Hàn Quốc nếu muốn cay hơn.',4,'Không ướp quá mặn ở bước này để giữ vị thanh mát tự nhiên của nước canh sau khi hoàn tất.'),
(49,3,'Phi thơm hành tỏi & xào săn khóa ngọt nguyên liệu','Đặt nồi canh lên bếp ở lửa vừa, làm nóng 15ml dầu ăn rồi phi thơm phần hành tím và tỏi băm nhỏ còn lại đến khi dậy mùi vàng óng. Trút nguyên liệu chính đã ướp vào đảo săn 2–3 phút cho bề mặt se lại, khóa trọn nước ngọt tự nhiên bên trong thớ thịt.',4,'Xào săn nguyên liệu đạm với hành tỏi phi trước khi đổ nước sôi giúp nước canh thơm ngọt đậm đà mà không hề tanh.'),
(49,4,'Đun sôi nước canh & hớt bọt giữ độ trong veo','Chế khoảng 1.1–1.3 lít nước (kết hợp 10ml dầu mè và 800ml nước lọc) vào nồi, bật lửa lớn đun đến khi sôi bùng rồi hạ ngay về lửa vừa. Dùng muôi hớt sạch lớp bọt đầu nổi lên trên mặt nước để nồi canh Canh kim chi đậu phụ đạt độ trong thanh đẹp mắt. Châm nước và nước kim chi, đun sôi 5 phút. Thêm đậu phụ, nấu nhẹ để miếng không vỡ.',6,'Sử dụng nước ấm hoặc nước sôi khi chế vào cá tươi sẽ giúp cá không bao giờ bị tanh nồng dù để nguội.'),
(49,5,'Thả rau củ theo độ chín & cân chỉnh định lượng vị','Lần lượt cho 80g hành tây vào nồi canh đang sôi vừa (nhóm củ quả lâu chín cho trước 5–7 phút, nhóm rau mềm cho sau 1–2 phút). Nêm phần 15ml nước tương còn lại, khuấy nhẹ và nếm thử thấy vị chua thanh hoặc ngọt dịu cân bằng đúng khẩu phần 4 người.',5,'Không đậy kín nắp vung sau khi đã thả các loại rau xanh vào nồi để giữ màu xanh ngọc tươi tắn hấp dẫn.'),
(49,6,'Điểm hương rau thơm & múc canh dọn nóng','Khi toàn bộ nguyên liệu vừa chín tới mềm ngọt, rắc ngay hành ngò và tiêu xay vào nồi rồi tắt bếp liền tay để giữ trọn tinh dầu thơm mát. Múc canh nóng hổi ra tô lớn, rắc thêm chút tiêu xay hoặc tỏi phi vàng và dùng ngay với cơm nóng. Thêm nấm kim châm, nấu 2 phút. Nêm nước tương sau khi nếm vì kim chi đã mặn; dọn nóng.',2,'Các loại rau thơm như thì là, ngò gai, rau om hay lá lốt chỉ nên thả ngay khoảnh khắc tắt bếp để hương thơm bùng nổ nhất.'),
(50,1,'Sơ chế & chần sạch nguyên liệu xương thịt, hải sản','Rửa sạch 200g thịt cua và 8 quả trứng cút với muối hạt rồi chần nhanh trong nồi nước sôi có đập dập 1 nhánh gừng trong 2–3 phút trên lửa lớn để loại bỏ hoàn toàn bọt bẩn. Rửa lại dưới làn nước sạch cho thật trắng trẻo, đồng thời nhặt rửa sạch 120g ngô non để ráo nước. Luộc trứng cút 5 phút, bóc vỏ. Cắt ngô và cà rốt hạt lựu; hòa bột bắp với 50 ml nước lạnh.',6,'Bước chần sơ và rửa lại bằng nước ấm là bí quyết vàng giúp nồi nước dùng trong vắt, thơm thanh và không bao giờ bị đục hay hôi.');
INSERT INTO `recipe_steps` (`recipe_id`,`step_order`,`title`,`instruction`,`duration_mins`,`tip_note`) VALUES
(50,2,'Nướng thơm thảo mộc & ninh nền nước dùng ngọt thanh','Cho phần nguyên liệu tạo ngọt từ 200g thịt cua và 8 quả trứng cút cùng hành tím và tỏi băm nhỏ đã nướng xém thơm vào nồi sâu lòng với khoảng 1.5–1.8 lít nước lọc. Đun sôi bùng trên lửa lớn rồi hạ ngay về lửa nhỏ liu riu, mở hé vung và hớt kỹ bọt nổi trên mặt để chiết xuất vị ngọt tự nhiên. Đun nước dùng, cho cà rốt và ngô vào nấu 6–8 phút đến vừa mềm. Hớt bọt để súp trong.',12,'Luôn duy trì mặt nước lăn tăn nhẹ thay vì đun sôi sùng sục lửa to để protein không bị nhũ hóa gây đục nước lèo.'),
(50,3,'Xào tạo màu & dậy hương đặc trưng vùng miền','Bắc chảo nhỏ lên bếp với 15ml dầu ăn trên lửa vừa, phi thơm phần hành tỏi sả băm còn lại rồi xào săn 80g cà rốt và 1 quả trứng gà cùng 12ml nước mắm và 1g tiêu trong 3–4 phút. Khi hỗn hợp dậy mùi thơm nồng nàn và lên sắc màu óng ả đặc trưng của món Súp cua trứng cút thì tắt bếp.',5,'Xào riêng phần nguyên liệu tạo màu và gia vị thơm trước khi trút vào nồi nước dùng giúp tầng hương dậy lên rõ nét gấp đôi.'),
(50,4,'Sơ chế & cắt thái phần nhân topping xếp tô','Vớt phần thịt hoặc hải sản chín tới từ 200g thịt cua và 8 quả trứng cút ra ngâm ngay vào âu nước đun sôi để nguội giúp bề mặt săn giòn mọng nước, không bị thâm khô. Thái lát mỏng đều tay dày khoảng 3mm ngang thớ hoặc gỡ miếng vừa ăn, sắp riêng từng phần gọn gàng trên đĩa.',5,'Thái thịt ngang thớ với lưỡi dao thật sắc giúp lát thịt mềm mướt, khi chan nước dùng sôi lên sẽ phẳng đẹp không bị quăn cứng.'),
(50,5,'Hợp nhất nồi nước lèo & nêm chuẩn định lượng','Trút phần sốt màu thơm vào nồi nước dùng đang sôi lăn tăn, nêm chính xác lượng 12ml nước mắm và 1g tiêu còn lại cho vừa miệng 4 người ăn. Đun nhẹ thêm 5 phút ở lửa vừa để các tầng vị mặn dịu, ngọt hậu từ xương thịt và thảo mộc hòa quyện tròn trịa. Cho thịt cua vào, đun sôi nhẹ. Rót từ từ bột bắp đã hòa, khuấy liên tục đến độ sánh vừa.',5,'Nên nêm nước mắm ngon ở giai đoạn cuối trên lửa nhỏ để giữ trọn hậu vị ngọt đạm và hương thơm mà không làm nước dùng bị chua.'),
(50,6,'Chần nóng sợi bánh/bún & chuẩn bị rau ăn kèm','Đun sôi một nồi nước riêng, cho phần sợi bún/phở/bánh trong 200g thịt cua và 8 quả trứng cút vào trụng nhanh 15–25 giây cho sợi mềm dẻo nóng hổi rồi vẩy thật ráo nước, chia đều vào 4 tô lớn. Chần sơ thêm rau ăn kèm (120g ngô non) nếu muốn dùng chín giòn.',4,'Trụng bún bánh ở nồi nước sôi riêng biệt giúp nước dùng chính không bị nhiễm tinh bột chua và tô bún luôn ráo sợi, thấm vị.'),
(50,7,'Xếp nhân hài hòa, chan nước dùng sôi & thưởng thức','Xếp đều các phần nhân thịt, hải sản lên mặt tô bún bánh, điểm xuyết hành ngò và tiêu xay lên trên cùng. Dùng muôi múc nước dùng đang sôi thật già chan ngập xăm xắp mặt nguyên liệu để làm chín thơm hành ngò, dọn nóng ngay kèm chanh ớt tươi. Rót trứng gà đã đánh thành dòng mảnh, khuấy nhẹ tạo sợi. Thêm trứng cút, nêm nước mắm và tiêu; dùng nóng.',3,'Tráng nóng tô sứ bằng nước sôi trước khi xếp bún giúp tô món nước giữ nhiệt bốc khói nghi ngút suốt bữa ăn.'),
(51,1,'Sơ chế & chần sạch nguyên liệu xương thịt, hải sản','Rửa sạch 300g thịt gà (ức) và 180g ngô non với muối hạt rồi chần nhanh trong nồi nước sôi có đập dập 1 nhánh gừng trong 2–3 phút trên lửa lớn để loại bỏ hoàn toàn bọt bẩn. Rửa lại dưới làn nước sạch cho thật trắng trẻo, đồng thời nhặt rửa sạch hành ngò và tiêu xay để ráo nước. Cho gà vào nồi nước dùng, đun đến khi phần dày nhất đạt 74°C. Vớt ra để nguội bớt rồi xé sợi; giữ nước luộc.',6,'Bước chần sơ và rửa lại bằng nước ấm là bí quyết vàng giúp nồi nước dùng trong vắt, thơm thanh và không bao giờ bị đục hay hôi.'),
(51,2,'Nướng thơm thảo mộc & ninh nền nước dùng ngọt thanh','Cho phần nguyên liệu tạo ngọt từ 300g thịt gà (ức) và 180g ngô non cùng hành tím và tỏi băm nhỏ đã nướng xém thơm vào nồi sâu lòng với khoảng 1.5–1.8 lít nước lọc. Đun sôi bùng trên lửa lớn rồi hạ ngay về lửa nhỏ liu riu, mở hé vung và hớt kỹ bọt nổi trên mặt để chiết xuất vị ngọt tự nhiên. Ngâm nấm hương, thái sợi; cắt ngô và cà rốt hạt lựu. Hòa bột bắp với nước lạnh.',15,'Luôn duy trì mặt nước lăn tăn nhẹ thay vì đun sôi sùng sục lửa to để protein không bị nhũ hóa gây đục nước lèo.'),
(51,3,'Xào tạo màu & dậy hương đặc trưng vùng miền','Bắc chảo nhỏ lên bếp với 15ml dầu ăn trên lửa vừa, phi thơm phần hành tỏi sả băm còn lại rồi xào săn 80g nấm hương và 1 quả trứng gà cùng 12ml nước mắm trong 3–4 phút. Khi hỗn hợp dậy mùi thơm nồng nàn và lên sắc màu óng ả đặc trưng của món Súp gà ngô non thì tắt bếp.',5,'Xào riêng phần nguyên liệu tạo màu và gia vị thơm trước khi trút vào nồi nước dùng giúp tầng hương dậy lên rõ nét gấp đôi.'),
(51,4,'Sơ chế & cắt thái phần nhân topping xếp tô','Vớt phần thịt hoặc hải sản chín tới từ 300g thịt gà (ức) và 180g ngô non ra ngâm ngay vào âu nước đun sôi để nguội giúp bề mặt săn giòn mọng nước, không bị thâm khô. Thái lát mỏng đều tay dày khoảng 3mm ngang thớ hoặc gỡ miếng vừa ăn, sắp riêng từng phần gọn gàng trên đĩa.',5,'Thái thịt ngang thớ với lưỡi dao thật sắc giúp lát thịt mềm mướt, khi chan nước dùng sôi lên sẽ phẳng đẹp không bị quăn cứng.'),
(51,5,'Hợp nhất nồi nước lèo & nêm chuẩn định lượng','Trút phần sốt màu thơm vào nồi nước dùng đang sôi lăn tăn, nêm chính xác lượng 12ml nước mắm còn lại cho vừa miệng 4 người ăn. Đun nhẹ thêm 5 phút ở lửa vừa để các tầng vị mặn dịu, ngọt hậu từ xương thịt và thảo mộc hòa quyện tròn trịa. Đun nước luộc sôi nhẹ, cho cà rốt, ngô và nấm vào nấu 7 phút. Thêm gà xé và nêm nước mắm.',5,'Nên nêm nước mắm ngon ở giai đoạn cuối trên lửa nhỏ để giữ trọn hậu vị ngọt đạm và hương thơm mà không làm nước dùng bị chua.'),
(51,6,'Chần nóng sợi bánh/bún & chuẩn bị rau ăn kèm','Đun sôi một nồi nước riêng, cho phần sợi bún/phở/bánh trong 300g thịt gà (ức) và 180g ngô non vào trụng nhanh 15–25 giây cho sợi mềm dẻo nóng hổi rồi vẩy thật ráo nước, chia đều vào 4 tô lớn. Chần sơ thêm rau ăn kèm (giá đỗ, rau xanh) nếu muốn dùng chín giòn.',4,'Trụng bún bánh ở nồi nước sôi riêng biệt giúp nước dùng chính không bị nhiễm tinh bột chua và tô bún luôn ráo sợi, thấm vị.'),
(51,7,'Xếp nhân hài hòa, chan nước dùng sôi & thưởng thức','Xếp đều các phần nhân thịt, hải sản lên mặt tô bún bánh, điểm xuyết hành ngò và tiêu xay lên trên cùng. Dùng muôi múc nước dùng đang sôi thật già chan ngập xăm xắp mặt nguyên liệu để làm chín thơm hành ngò, dọn nóng ngay kèm chanh ớt tươi. Rót bột bắp từng ít, khuấy đến khi súp sánh nhẹ. Thêm trứng đánh mỏng thành sợi, nấu thêm 1 phút rồi tắt bếp.',3,'Tráng nóng tô sứ bằng nước sôi trước khi xếp bún giúp tô món nước giữ nhiệt bốc khói nghi ngút suốt bữa ăn.'),
(52,1,'Sơ chế sạch & cắt thái nguyên liệu nấu canh','Rửa sạch 300g đậu hũ và 100g nấm hương, khử mùi tanh bằng chút muối hạt và gừng đập dập rồi rửa lại thật ráo, cắt miếng vừa ăn dày khoảng 2.5–3cm. Đồng thời gọt rửa sạch rau củ ăn kèm, cắt khúc hoặc bổ múi cau đồng đều để khi nấu chín đều không bị nát. Ngâm nấm hương cho nở, bỏ chân cứng và thái lát. Cắt bỏ gốc nấm kim châm, tách thành cụm nhỏ.',4,'Phân loại riêng nhóm củ cứng nấu lâu và nhóm rau lá mềm nhanh chín để cho vào nồi theo đúng thứ tự chuẩn đầu bếp.'),
(52,2,'Ướp thấm gia vị nền cho nguyên liệu đạm','Cho phần đạm chính trong 300g đậu hũ và 100g nấm hương vào tô, ướp nhẹ với một nửa lượng hành tím và tỏi băm nhỏ và 18ml nước tương trong khoảng 10 phút. Đảo nhẹ tay cho gia vị áo đều bề mặt giúp miếng thịt, cá săn chắc và đậm đà từ bên trong khi thả vào nước canh. Đun sôi nước, cho cà chua và nấm hương vào nấu 5 phút để nước có vị ngọt.',4,'Không ướp quá mặn ở bước này để giữ vị thanh mát tự nhiên của nước canh sau khi hoàn tất.'),
(52,3,'Phi thơm hành tỏi & xào săn khóa ngọt nguyên liệu','Đặt nồi canh lên bếp ở lửa vừa, làm nóng 15ml dầu ăn rồi phi thơm phần hành tím và tỏi băm nhỏ còn lại đến khi dậy mùi vàng óng. Trút nguyên liệu chính đã ướp vào đảo săn 2–3 phút cho bề mặt se lại, khóa trọn nước ngọt tự nhiên bên trong thớ thịt.',3,'Xào săn nguyên liệu đạm với hành tỏi phi trước khi đổ nước sôi giúp nước canh thơm ngọt đậm đà mà không hề tanh.'),
(52,4,'Đun sôi nước canh & hớt bọt giữ độ trong veo','Chế khoảng 1.1–1.3 lít nước (kết hợp 5ml dầu mè và 900ml nước lọc) vào nồi, bật lửa lớn đun đến khi sôi bùng rồi hạ ngay về lửa vừa. Dùng muôi hớt sạch lớp bọt đầu nổi lên trên mặt nước để nồi canh Canh nấm đậu phụ đạt độ trong thanh đẹp mắt. Cắt đậu khối vuông, thả nhẹ vào nồi và nấu 3 phút. Thêm nấm kim châm ở 2 phút cuối.',6,'Sử dụng nước ấm hoặc nước sôi khi chế vào cá tươi sẽ giúp cá không bao giờ bị tanh nồng dù để nguội.'),
(52,5,'Thả rau củ theo độ chín & cân chỉnh định lượng vị','Lần lượt cho rau củ ăn kèm vào nồi canh đang sôi vừa (nhóm củ quả lâu chín cho trước 5–7 phút, nhóm rau mềm cho sau 1–2 phút). Nêm phần 18ml nước tương còn lại, khuấy nhẹ và nếm thử thấy vị chua thanh hoặc ngọt dịu cân bằng đúng khẩu phần 4 người.',5,'Không đậy kín nắp vung sau khi đã thả các loại rau xanh vào nồi để giữ màu xanh ngọc tươi tắn hấp dẫn.'),
(52,6,'Điểm hương rau thơm & múc canh dọn nóng','Khi toàn bộ nguyên liệu vừa chín tới mềm ngọt, rắc ngay 15g hành lá vào nồi rồi tắt bếp liền tay để giữ trọn tinh dầu thơm mát. Múc canh nóng hổi ra tô lớn, rắc thêm chút tiêu xay hoặc tỏi phi vàng và dùng ngay với cơm nóng. Nêm nước tương, tắt bếp rồi thêm dầu mè và hành lá. Không đảo mạnh để đậu phụ giữ nguyên miếng.',2,'Các loại rau thơm như thì là, ngò gai, rau om hay lá lốt chỉ nên thả ngay khoảnh khắc tắt bếp để hương thơm bùng nổ nhất.'),
(53,1,'Sơ chế sạch & cắt thái nguyên liệu nấu canh','Rửa sạch 450g cá basa và 250g dọc mùng, khử mùi tanh bằng chút muối hạt và gừng đập dập rồi rửa lại thật ráo, cắt miếng vừa ăn dày khoảng 2.5–3cm. Đồng thời gọt rửa sạch 150g dứa, cắt khúc hoặc bổ múi cau đồng đều để khi nấu chín đều không bị nát. Tước xơ, thái vát, bóp với muối rồi xả sạch và vắt khô; dùng găng nếu da nhạy cảm. Cắt cá khúc, cà chua và dứa.',8,'Phân loại riêng nhóm củ cứng nấu lâu và nhóm rau lá mềm nhanh chín để cho vào nồi theo đúng thứ tự chuẩn đầu bếp.'),
(53,2,'Ướp thấm gia vị nền cho nguyên liệu đạm','Cho phần đạm chính trong 450g cá basa và 250g dọc mùng vào tô, ướp nhẹ với một nửa lượng hành tím và tỏi băm nhỏ và 20g me vắt, 20ml nước mắm và 3g muối trong khoảng 10 phút. Đảo nhẹ tay cho gia vị áo đều bề mặt giúp miếng thịt, cá săn chắc và đậm đà từ bên trong khi thả vào nước canh. Đun nước với me đã dầm lọc, cà chua và dứa 5 phút. Nếm độ chua, thêm nước nóng nếu quá gắt.',7,'Không ướp quá mặn ở bước này để giữ vị thanh mát tự nhiên của nước canh sau khi hoàn tất.'),
(53,3,'Phi thơm hành tỏi & xào săn khóa ngọt nguyên liệu','Đặt nồi canh lên bếp ở lửa vừa, làm nóng 15ml dầu ăn rồi phi thơm phần hành tím và tỏi băm nhỏ còn lại đến khi dậy mùi vàng óng. Trút nguyên liệu chính đã ướp vào đảo săn 2–3 phút cho bề mặt se lại, khóa trọn nước ngọt tự nhiên bên trong thớ thịt.',6,'Xào săn nguyên liệu đạm với hành tỏi phi trước khi đổ nước sôi giúp nước canh thơm ngọt đậm đà mà không hề tanh.'),
(53,4,'Đun sôi nước canh & hớt bọt giữ độ trong veo','Chế khoảng 1.1–1.3 lít nước (kết hợp 1.1l nước lọc) vào nồi, bật lửa lớn đun đến khi sôi bùng rồi hạ ngay về lửa vừa. Dùng muôi hớt sạch lớp bọt đầu nổi lên trên mặt nước để nồi canh Canh cá nấu dọc mùng đạt độ trong thanh đẹp mắt. Thả cá vào nồi đang sôi nhẹ, nấu 7–9 phút đến khi thịt đục và tách thớ. Không đảo để miếng cá nguyên.',11,'Sử dụng nước ấm hoặc nước sôi khi chế vào cá tươi sẽ giúp cá không bao giờ bị tanh nồng dù để nguội.'),
(53,5,'Thả rau củ theo độ chín & cân chỉnh định lượng vị','Lần lượt cho 150g dứa vào nồi canh đang sôi vừa (nhóm củ quả lâu chín cho trước 5–7 phút, nhóm rau mềm cho sau 1–2 phút). Nêm phần 20g me vắt, 20ml nước mắm và 3g muối còn lại, khuấy nhẹ và nếm thử thấy vị chua thanh hoặc ngọt dịu cân bằng đúng khẩu phần 4 người.',9,'Không đậy kín nắp vung sau khi đã thả các loại rau xanh vào nồi để giữ màu xanh ngọc tươi tắn hấp dẫn.'),
(53,6,'Điểm hương rau thơm & múc canh dọn nóng','Khi toàn bộ nguyên liệu vừa chín tới mềm ngọt, rắc ngay 15g thì là vào nồi rồi tắt bếp liền tay để giữ trọn tinh dầu thơm mát. Múc canh nóng hổi ra tô lớn, rắc thêm chút tiêu xay hoặc tỏi phi vàng và dùng ngay với cơm nóng. Thêm dọc mùng, nấu 3 phút đến mềm giòn. Nêm nước mắm, rắc thì là và tắt bếp.',4,'Các loại rau thơm như thì là, ngò gai, rau om hay lá lốt chỉ nên thả ngay khoảnh khắc tắt bếp để hương thơm bùng nổ nhất.');
INSERT INTO `recipe_steps` (`recipe_id`,`step_order`,`title`,`instruction`,`duration_mins`,`tip_note`) VALUES
(54,1,'Sơ chế sạch & cắt thái nguyên liệu nấu canh','Rửa sạch 450g bí xanh và 180g thịt heo xay, khử mùi tanh bằng chút muối hạt và gừng đập dập rồi rửa lại thật ráo, cắt miếng vừa ăn dày khoảng 2.5–3cm. Đồng thời gọt rửa sạch rau củ ăn kèm, cắt khúc hoặc bổ múi cau đồng đều để khi nấu chín đều không bị nát. Gọt bí xanh, bỏ ruột già, rửa sạch và thái lát dày khoảng 5 mm. Băm hành tím, thái hành lá.',5,'Phân loại riêng nhóm củ cứng nấu lâu và nhóm rau lá mềm nhanh chín để cho vào nồi theo đúng thứ tự chuẩn đầu bếp.'),
(54,2,'Ướp thấm gia vị nền cho nguyên liệu đạm','Cho phần đạm chính trong 450g bí xanh và 180g thịt heo xay vào tô, ướp nhẹ với một nửa lượng 15g hành tím và 15ml nước mắm, 3g muối và 1g tiêu trong khoảng 10 phút. Đảo nhẹ tay cho gia vị áo đều bề mặt giúp miếng thịt, cá săn chắc và đậm đà từ bên trong khi thả vào nước canh. Phi hành tím, cho thịt băm vào đảo tơi đến khi săn. Nêm chút nước mắm và tiêu.',5,'Không ướp quá mặn ở bước này để giữ vị thanh mát tự nhiên của nước canh sau khi hoàn tất.'),
(54,3,'Phi thơm hành tỏi & xào săn khóa ngọt nguyên liệu','Đặt nồi canh lên bếp ở lửa vừa, làm nóng 15ml dầu ăn rồi phi thơm phần 15g hành tím còn lại đến khi dậy mùi vàng óng. Trút nguyên liệu chính đã ướp vào đảo săn 2–3 phút cho bề mặt se lại, khóa trọn nước ngọt tự nhiên bên trong thớ thịt.',4,'Xào săn nguyên liệu đạm với hành tỏi phi trước khi đổ nước sôi giúp nước canh thơm ngọt đậm đà mà không hề tanh.'),
(54,4,'Đun sôi nước canh & hớt bọt giữ độ trong veo','Chế khoảng 1.1–1.3 lít nước (kết hợp 1l nước lọc và 8ml dầu ăn) vào nồi, bật lửa lớn đun đến khi sôi bùng rồi hạ ngay về lửa vừa. Dùng muôi hớt sạch lớp bọt đầu nổi lên trên mặt nước để nồi canh Canh bí xanh thịt băm đạt độ trong thanh đẹp mắt. Châm nước, đun sôi và hớt bọt. Cho bí xanh vào, nấu lửa vừa 8–10 phút đến khi miếng bí trong nhưng chưa rã.',7,'Sử dụng nước ấm hoặc nước sôi khi chế vào cá tươi sẽ giúp cá không bao giờ bị tanh nồng dù để nguội.'),
(54,5,'Thả rau củ theo độ chín & cân chỉnh định lượng vị','Lần lượt cho rau củ ăn kèm vào nồi canh đang sôi vừa (nhóm củ quả lâu chín cho trước 5–7 phút, nhóm rau mềm cho sau 1–2 phút). Nêm phần 15ml nước mắm, 3g muối và 1g tiêu còn lại, khuấy nhẹ và nếm thử thấy vị chua thanh hoặc ngọt dịu cân bằng đúng khẩu phần 4 người.',6,'Không đậy kín nắp vung sau khi đã thả các loại rau xanh vào nồi để giữ màu xanh ngọc tươi tắn hấp dẫn.'),
(54,6,'Điểm hương rau thơm & múc canh dọn nóng','Khi toàn bộ nguyên liệu vừa chín tới mềm ngọt, rắc ngay 15g hành lá vào nồi rồi tắt bếp liền tay để giữ trọn tinh dầu thơm mát. Múc canh nóng hổi ra tô lớn, rắc thêm chút tiêu xay hoặc tỏi phi vàng và dùng ngay với cơm nóng. Nêm muối, nước mắm còn lại; tắt bếp khi bí vừa mềm. Thêm hành lá, tiêu và dùng nóng.',3,'Các loại rau thơm như thì là, ngò gai, rau om hay lá lốt chỉ nên thả ngay khoảnh khắc tắt bếp để hương thơm bùng nổ nhất.'),
(55,1,'Sơ chế & thái mỏng đồng đều nguyên liệu xào','Làm sạch và thấm ráo 350g thịt bò và 180g cần tây, dùng dao sắc thái lát mỏng vừa ăn khoảng 2–3mm ngang thớ để khi xào nhanh chín mềm không bị dai. Nhặt rửa sạch 100g hành tây, cắt khúc xéo 4cm hoặc tách nhánh đồng đều giúp tiếp xúc nhiệt nhanh trên chảo. Thái bò ngang thớ thật mỏng, trộn với nước tương, bột bắp và tiêu; để 10 phút. Cắt cần tây khúc, hành tây múi.',6,'Nguyên liệu xào bắt buộc phải để thật ráo nước trước khi cho vào chảo để đạt hiệu ứng áp nhiệt thơm kiểu chảo gang.'),
(55,2,'Ướp mềm nguyên liệu đạm & pha sẵn chén sốt xào','Ướp phần đạm trong 350g thịt bò và 180g cần tây với 1/3 lượng 12g tỏi, chút dầu ăn và 1/3 lượng 18ml nước tương và 2g tiêu trong 10 phút để giữ độ ẩm mọng. Pha phần 18ml nước tương và 2g tiêu còn lại cùng 20ml nước lọc vào chén nhỏ khuấy tan hoàn toàn để thao tác xào lửa lớn diễn ra dứt khoát. Làm nóng chảo đến khi bốc hơi nhẹ, thêm dầu và xào bò từng mẻ 1–2 phút đến vừa đổi màu; trút ra.',4,'Thêm 1 muỗng cà phê dầu ăn vào bước ướp thịt bò/heo giúp khóa ẩm và các lát thịt tơi nhanh không bị dính chùm khi gặp chảo nóng.'),
(55,3,'Chần nhanh rau củ giữ sắc xanh ngọc & độ giòn','Đun sôi nồi nước nhỏ với một nhúm muối, thả 100g hành tây vào chần nhanh 30–45 giây rồi vớt ngay ra tô nước đá lạnh cho sốc nhiệt, sau đó đổ ra rổ cho thật ráo. Bước tiền xử lý này giúp rau củ chín đều từ trong mà bên ngoài vẫn xanh mướt giòn sần sật.',4,'Thời gian chần dưới 1 phút kết hợp ngâm nước đá lạnh là bí quyết nhà hàng giúp đĩa rau xào không bị chảy nước đen đĩa.'),
(55,4,'Xào săn nguyên liệu chính trên lửa lớn nhanh tay','Làm nóng chảo rộng trên lửa lớn nhất với 15ml dầu ăn, phi dậy mùi một nửa 12g tỏi rồi trút phần đạm chính trong 350g thịt bò và 180g cần tây vào đảo cực nhanh tay trong 60–90 giây. Ngay khi thịt hoặc hải sản vừa chín tái hồng khoảng 85%, lập tức trút riêng ra đĩa sạch để không bị quá lửa khô xác. Phi tỏi, cho hành tây vào đảo 1 phút rồi thêm cần tây. Xào lửa lớn 2–3 phút để rau còn giòn.',4,'Tuyệt đối không xào thịt chung từ đầu đến cuối với rau củ vì thịt sẽ bị dai và tiết nước làm mất độ giòn.'),
(55,5,'Xào rau củ lửa lớn & rưới sốt định lượng khóa vị','Giữ nguyên chảo nóng trên lửa lớn, thêm chút dầu phi thơm nốt phần 12g tỏi còn lại rồi cho 100g hành tây đã ráo nước vào đảo đều 1–2 phút. Trút ngược đĩa đạm vào chảo, rưới đều chén sốt gia vị đã pha và xóc nhanh tay 45 giây cho sốt sánh bóng áo quanh từng miếng nguyên liệu.',4,'Rưới sốt vòng quanh thành chảo nóng thay vì đổ thẳng giữa lòng chảo giúp sốt bốc hơi thơm lừng và sệt lại tức thì.'),
(55,6,'Dậy hương tiêu hành & trình bày nóng hổi','Cho hành ngò và tiêu xay vào đảo nhẹ đúng 1 lượt rồi tắt bếp ngay khi khói thơm bốc lên nghi ngút. Gắp món Bò xào cần tây ra đĩa rộng lòng để tản nhiệt đều, tránh đậy kín vung và thưởng thức nóng ngay cùng cơm dẻo cho 4 người. Cho bò trở lại chảo, đảo nhanh 30–60 giây. Nếm nước tương, tắt bếp khi cần tây còn xanh.',3,'Bày món xào ra đĩa rộng không xếp chồng quá dày giúp hơi nóng thoát nhẹ, giữ rau củ giòn ngọt lâu đến miếng cuối cùng.'),
(56,1,'Sơ chế & thái mỏng đồng đều nguyên liệu xào','Làm sạch và thấm ráo 350g thịt bò và 350g bông cải xanh, dùng dao sắc thái lát mỏng vừa ăn khoảng 2–3mm ngang thớ để khi xào nhanh chín mềm không bị dai. Nhặt rửa sạch rau củ ăn kèm, cắt khúc xéo 4cm hoặc tách nhánh đồng đều giúp tiếp xúc nhiệt nhanh trên chảo. Tách bông cải thành miếng nhỏ, ngâm rửa kỹ. Chần trong nước sôi có chút muối 2 phút rồi vớt ra ngâm nước mát.',5,'Nguyên liệu xào bắt buộc phải để thật ráo nước trước khi cho vào chảo để đạt hiệu ứng áp nhiệt thơm kiểu chảo gang.'),
(56,2,'Ướp mềm nguyên liệu đạm & pha sẵn chén sốt xào','Ướp phần đạm trong 350g thịt bò và 350g bông cải xanh với 1/3 lượng 12g tỏi, chút dầu ăn và 1/3 lượng 18ml nước tương, 12ml dầu hào và 3g muối trong 10 phút để giữ độ ẩm mọng. Pha phần 18ml nước tương, 12ml dầu hào và 3g muối còn lại cùng 20ml nước lọc vào chén nhỏ khuấy tan hoàn toàn để thao tác xào lửa lớn diễn ra dứt khoát. Thái bò mỏng ngang thớ, trộn với một nửa nước tương và bột bắp trong 10 phút.',5,'Thêm 1 muỗng cà phê dầu ăn vào bước ướp thịt bò/heo giúp khóa ẩm và các lát thịt tơi nhanh không bị dính chùm khi gặp chảo nóng.'),
(56,3,'Chần nhanh rau củ giữ sắc xanh ngọc & độ giòn','Đun sôi nồi nước nhỏ với một nhúm muối, thả rau củ ăn kèm vào chần nhanh 30–45 giây rồi vớt ngay ra tô nước đá lạnh cho sốc nhiệt, sau đó đổ ra rổ cho thật ráo. Bước tiền xử lý này giúp rau củ chín đều từ trong mà bên ngoài vẫn xanh mướt giòn sần sật.',4,'Thời gian chần dưới 1 phút kết hợp ngâm nước đá lạnh là bí quyết nhà hàng giúp đĩa rau xào không bị chảy nước đen đĩa.'),
(56,4,'Xào săn nguyên liệu chính trên lửa lớn nhanh tay','Làm nóng chảo rộng trên lửa lớn nhất với 15ml dầu ăn, phi dậy mùi một nửa 12g tỏi rồi trút phần đạm chính trong 350g thịt bò và 350g bông cải xanh vào đảo cực nhanh tay trong 60–90 giây. Ngay khi thịt hoặc hải sản vừa chín tái hồng khoảng 85%, lập tức trút riêng ra đĩa sạch để không bị quá lửa khô xác. Xào bò trên chảo nóng với ít dầu đến vừa chín tái, gắp ra. Phi tỏi, thêm dầu hào, phần nước tương còn lại và nước.',5,'Tuyệt đối không xào thịt chung từ đầu đến cuối với rau củ vì thịt sẽ bị dai và tiết nước làm mất độ giòn.'),
(56,5,'Xào rau củ lửa lớn & rưới sốt định lượng khóa vị','Giữ nguyên chảo nóng trên lửa lớn, thêm chút dầu phi thơm nốt phần 12g tỏi còn lại rồi cho rau củ ăn kèm đã ráo nước vào đảo đều 1–2 phút. Trút ngược đĩa đạm vào chảo, rưới đều chén sốt gia vị đã pha và xóc nhanh tay 45 giây cho sốt sánh bóng áo quanh từng miếng nguyên liệu.',5,'Rưới sốt vòng quanh thành chảo nóng thay vì đổ thẳng giữa lòng chảo giúp sốt bốc hơi thơm lừng và sệt lại tức thì.'),
(56,6,'Dậy hương tiêu hành & trình bày nóng hổi','Cho hành ngò và tiêu xay vào đảo nhẹ đúng 1 lượt rồi tắt bếp ngay khi khói thơm bốc lên nghi ngút. Gắp món Bò xào bông cải xanh ra đĩa rộng lòng để tản nhiệt đều, tránh đậy kín vung và thưởng thức nóng ngay cùng cơm dẻo cho 4 người. Cho bông cải vào đảo 2 phút, thêm bò trở lại và đảo đến nóng đều. Sốt chỉ cần áo mỏng; nếm lại trước khi dọn.',3,'Bày món xào ra đĩa rộng không xếp chồng quá dày giúp hơi nóng thoát nhẹ, giữ rau củ giòn ngọt lâu đến miếng cuối cùng.'),
(57,1,'Sơ chế & thái mỏng đồng đều nguyên liệu xào','Làm sạch và thấm ráo 400g thịt gà (đùi) và 150g nấm hương, dùng dao sắc thái lát mỏng vừa ăn khoảng 2–3mm ngang thớ để khi xào nhanh chín mềm không bị dai. Nhặt rửa sạch 100g hành tây, cắt khúc xéo 4cm hoặc tách nhánh đồng đều giúp tiếp xúc nhiệt nhanh trên chảo. Thái gà miếng nhỏ vừa ăn. Ngâm nấm hương cho mềm, bỏ chân cứng, cắt đôi; thái hành tây và gừng sợi.',7,'Nguyên liệu xào bắt buộc phải để thật ráo nước trước khi cho vào chảo để đạt hiệu ứng áp nhiệt thơm kiểu chảo gang.'),
(57,2,'Ướp mềm nguyên liệu đạm & pha sẵn chén sốt xào','Ướp phần đạm trong 400g thịt gà (đùi) và 150g nấm hương với 1/3 lượng 15g gừng, chút dầu ăn và 1/3 lượng 20ml nước tương và 12ml dầu hào trong 10 phút để giữ độ ẩm mọng. Pha phần 20ml nước tương và 12ml dầu hào còn lại cùng 20ml nước lọc vào chén nhỏ khuấy tan hoàn toàn để thao tác xào lửa lớn diễn ra dứt khoát. Trộn gà với một nửa nước tương, dầu hào và gừng; để 10 phút trong khi làm nóng chảo.',5,'Thêm 1 muỗng cà phê dầu ăn vào bước ướp thịt bò/heo giúp khóa ẩm và các lát thịt tơi nhanh không bị dính chùm khi gặp chảo nóng.'),
(57,3,'Chần nhanh rau củ giữ sắc xanh ngọc & độ giòn','Đun sôi nồi nước nhỏ với một nhúm muối, thả 100g hành tây vào chần nhanh 30–45 giây rồi vớt ngay ra tô nước đá lạnh cho sốc nhiệt, sau đó đổ ra rổ cho thật ráo. Bước tiền xử lý này giúp rau củ chín đều từ trong mà bên ngoài vẫn xanh mướt giòn sần sật.',4,'Thời gian chần dưới 1 phút kết hợp ngâm nước đá lạnh là bí quyết nhà hàng giúp đĩa rau xào không bị chảy nước đen đĩa.'),
(57,4,'Xào săn nguyên liệu chính trên lửa lớn nhanh tay','Làm nóng chảo rộng trên lửa lớn nhất với 15ml dầu ăn, phi dậy mùi một nửa 15g gừng rồi trút phần đạm chính trong 400g thịt gà (đùi) và 150g nấm hương vào đảo cực nhanh tay trong 60–90 giây. Ngay khi thịt hoặc hải sản vừa chín tái hồng khoảng 85%, lập tức trút riêng ra đĩa sạch để không bị quá lửa khô xác. Phi gừng, cho gà vào xào lửa lớn đến khi các mặt săn và phần giữa gần chín. Thêm nấm, đảo 3 phút.',5,'Tuyệt đối không xào thịt chung từ đầu đến cuối với rau củ vì thịt sẽ bị dai và tiết nước làm mất độ giòn.'),
(57,5,'Xào rau củ lửa lớn & rưới sốt định lượng khóa vị','Giữ nguyên chảo nóng trên lửa lớn, thêm chút dầu phi thơm nốt phần 15g gừng còn lại rồi cho 100g hành tây đã ráo nước vào đảo đều 1–2 phút. Trút ngược đĩa đạm vào chảo, rưới đều chén sốt gia vị đã pha và xóc nhanh tay 45 giây cho sốt sánh bóng áo quanh từng miếng nguyên liệu.',5,'Rưới sốt vòng quanh thành chảo nóng thay vì đổ thẳng giữa lòng chảo giúp sốt bốc hơi thơm lừng và sệt lại tức thì.'),
(57,6,'Dậy hương tiêu hành & trình bày nóng hổi','Cho 15g hành lá vào đảo nhẹ đúng 1 lượt rồi tắt bếp ngay khi khói thơm bốc lên nghi ngút. Gắp món Gà xào nấm đông cô ra đĩa rộng lòng để tản nhiệt đều, tránh đậy kín vung và thưởng thức nóng ngay cùng cơm dẻo cho 4 người. Thêm hành tây và phần nước tương còn lại cùng 50 ml nước; đậy nắp 4–5 phút đến khi gà đạt 74°C. Rắc hành lá.',4,'Bày món xào ra đĩa rộng không xếp chồng quá dày giúp hơi nóng thoát nhẹ, giữ rau củ giòn ngọt lâu đến miếng cuối cùng.'),
(58,1,'Sơ chế & thái mỏng đồng đều nguyên liệu xào','Làm sạch và thấm ráo 400g mực ống và 200g dứa, dùng dao sắc thái lát mỏng vừa ăn khoảng 2–3mm ngang thớ để khi xào nhanh chín mềm không bị dai. Nhặt rửa sạch 100g cần tây, cắt khúc xéo 4cm hoặc tách nhánh đồng đều giúp tiếp xúc nhiệt nhanh trên chảo. Làm sạch mực, bỏ mai và túi mực, khứa vảy rồng rồi cắt miếng. Thấm khô để khi xào không ra nhiều nước.',6,'Nguyên liệu xào bắt buộc phải để thật ráo nước trước khi cho vào chảo để đạt hiệu ứng áp nhiệt thơm kiểu chảo gang.');
INSERT INTO `recipe_steps` (`recipe_id`,`step_order`,`title`,`instruction`,`duration_mins`,`tip_note`) VALUES
(58,2,'Ướp mềm nguyên liệu đạm & pha sẵn chén sốt xào','Ướp phần đạm trong 400g mực ống và 200g dứa với 1/3 lượng 10g tỏi, chút dầu ăn và 1/3 lượng 15ml nước mắm và 2g tiêu trong 10 phút để giữ độ ẩm mọng. Pha phần 15ml nước mắm và 2g tiêu còn lại cùng 20ml nước lọc vào chén nhỏ khuấy tan hoàn toàn để thao tác xào lửa lớn diễn ra dứt khoát. Cắt dứa miếng mỏng, cần tây khúc 4 cm, cà chua múi cau; pha nước mắm với 30 ml nước.',4,'Thêm 1 muỗng cà phê dầu ăn vào bước ướp thịt bò/heo giúp khóa ẩm và các lát thịt tơi nhanh không bị dính chùm khi gặp chảo nóng.'),
(58,3,'Chần nhanh rau củ giữ sắc xanh ngọc & độ giòn','Đun sôi nồi nước nhỏ với một nhúm muối, thả 100g cần tây vào chần nhanh 30–45 giây rồi vớt ngay ra tô nước đá lạnh cho sốc nhiệt, sau đó đổ ra rổ cho thật ráo. Bước tiền xử lý này giúp rau củ chín đều từ trong mà bên ngoài vẫn xanh mướt giòn sần sật.',4,'Thời gian chần dưới 1 phút kết hợp ngâm nước đá lạnh là bí quyết nhà hàng giúp đĩa rau xào không bị chảy nước đen đĩa.'),
(58,4,'Xào săn nguyên liệu chính trên lửa lớn nhanh tay','Làm nóng chảo rộng trên lửa lớn nhất với 15ml dầu ăn, phi dậy mùi một nửa 10g tỏi rồi trút phần đạm chính trong 400g mực ống và 200g dứa vào đảo cực nhanh tay trong 60–90 giây. Ngay khi thịt hoặc hải sản vừa chín tái hồng khoảng 85%, lập tức trút riêng ra đĩa sạch để không bị quá lửa khô xác. Chảo nóng, phi tỏi rồi xào mực lửa lớn 1–2 phút đến khi vừa đục. Trút mực ra để giữ độ giòn.',4,'Tuyệt đối không xào thịt chung từ đầu đến cuối với rau củ vì thịt sẽ bị dai và tiết nước làm mất độ giòn.'),
(58,5,'Xào rau củ lửa lớn & rưới sốt định lượng khóa vị','Giữ nguyên chảo nóng trên lửa lớn, thêm chút dầu phi thơm nốt phần 10g tỏi còn lại rồi cho 100g cần tây đã ráo nước vào đảo đều 1–2 phút. Trút ngược đĩa đạm vào chảo, rưới đều chén sốt gia vị đã pha và xóc nhanh tay 45 giây cho sốt sánh bóng áo quanh từng miếng nguyên liệu.',4,'Rưới sốt vòng quanh thành chảo nóng thay vì đổ thẳng giữa lòng chảo giúp sốt bốc hơi thơm lừng và sệt lại tức thì.'),
(58,6,'Dậy hương tiêu hành & trình bày nóng hổi','Cho hành ngò và tiêu xay vào đảo nhẹ đúng 1 lượt rồi tắt bếp ngay khi khói thơm bốc lên nghi ngút. Gắp món Mực xào dứa ra đĩa rộng lòng để tản nhiệt đều, tránh đậy kín vung và thưởng thức nóng ngay cùng cơm dẻo cho 4 người. Xào dứa và cà chua 2 phút, thêm cần tây và mực, rưới nước mắm, đảo thêm 1 phút. Tắt bếp, rắc tiêu.',3,'Bày món xào ra đĩa rộng không xếp chồng quá dày giúp hơi nóng thoát nhẹ, giữ rau củ giòn ngọt lâu đến miếng cuối cùng.'),
(59,1,'Sơ chế & thái mỏng đồng đều nguyên liệu xào','Làm sạch và thấm ráo 300g tôm sú và 300g bông cải xanh, dùng dao sắc thái lát mỏng vừa ăn khoảng 2–3mm ngang thớ để khi xào nhanh chín mềm không bị dai. Nhặt rửa sạch rau củ ăn kèm, cắt khúc xéo 4cm hoặc tách nhánh đồng đều giúp tiếp xúc nhiệt nhanh trên chảo. Tách bông cải, cắt cà rốt lát xéo. Chần bông cải và cà rốt trong nước sôi 2 phút, vớt ra để ráo.',6,'Nguyên liệu xào bắt buộc phải để thật ráo nước trước khi cho vào chảo để đạt hiệu ứng áp nhiệt thơm kiểu chảo gang.'),
(59,2,'Ướp mềm nguyên liệu đạm & pha sẵn chén sốt xào','Ướp phần đạm trong 300g tôm sú và 300g bông cải xanh với 1/3 lượng 12g tỏi, chút dầu ăn và 1/3 lượng 15ml dầu hào và 1g tiêu trong 10 phút để giữ độ ẩm mọng. Pha phần 15ml dầu hào và 1g tiêu còn lại cùng 20ml nước lọc vào chén nhỏ khuấy tan hoàn toàn để thao tác xào lửa lớn diễn ra dứt khoát. Bóc vỏ, bỏ chỉ lưng và thấm khô tôm. Pha dầu hào với nước lọc để dễ áo đều món xào.',4,'Thêm 1 muỗng cà phê dầu ăn vào bước ướp thịt bò/heo giúp khóa ẩm và các lát thịt tơi nhanh không bị dính chùm khi gặp chảo nóng.'),
(59,3,'Chần nhanh rau củ giữ sắc xanh ngọc & độ giòn','Đun sôi nồi nước nhỏ với một nhúm muối, thả rau củ ăn kèm vào chần nhanh 30–45 giây rồi vớt ngay ra tô nước đá lạnh cho sốc nhiệt, sau đó đổ ra rổ cho thật ráo. Bước tiền xử lý này giúp rau củ chín đều từ trong mà bên ngoài vẫn xanh mướt giòn sần sật.',4,'Thời gian chần dưới 1 phút kết hợp ngâm nước đá lạnh là bí quyết nhà hàng giúp đĩa rau xào không bị chảy nước đen đĩa.'),
(59,4,'Xào săn nguyên liệu chính trên lửa lớn nhanh tay','Làm nóng chảo rộng trên lửa lớn nhất với 15ml dầu ăn, phi dậy mùi một nửa 12g tỏi rồi trút phần đạm chính trong 300g tôm sú và 300g bông cải xanh vào đảo cực nhanh tay trong 60–90 giây. Ngay khi thịt hoặc hải sản vừa chín tái hồng khoảng 85%, lập tức trút riêng ra đĩa sạch để không bị quá lửa khô xác. Phi tỏi trên chảo nóng, cho tôm vào đảo 2 phút đến khi chuyển hồng đục; trút tạm ra đĩa.',4,'Tuyệt đối không xào thịt chung từ đầu đến cuối với rau củ vì thịt sẽ bị dai và tiết nước làm mất độ giòn.'),
(59,5,'Xào rau củ lửa lớn & rưới sốt định lượng khóa vị','Giữ nguyên chảo nóng trên lửa lớn, thêm chút dầu phi thơm nốt phần 12g tỏi còn lại rồi cho rau củ ăn kèm đã ráo nước vào đảo đều 1–2 phút. Trút ngược đĩa đạm vào chảo, rưới đều chén sốt gia vị đã pha và xóc nhanh tay 45 giây cho sốt sánh bóng áo quanh từng miếng nguyên liệu.',4,'Rưới sốt vòng quanh thành chảo nóng thay vì đổ thẳng giữa lòng chảo giúp sốt bốc hơi thơm lừng và sệt lại tức thì.'),
(59,6,'Dậy hương tiêu hành & trình bày nóng hổi','Cho hành ngò và tiêu xay vào đảo nhẹ đúng 1 lượt rồi tắt bếp ngay khi khói thơm bốc lên nghi ngút. Gắp món Tôm xào bông cải ra đĩa rộng lòng để tản nhiệt đều, tránh đậy kín vung và thưởng thức nóng ngay cùng cơm dẻo cho 4 người. Xào bông cải và cà rốt 2 phút, thêm hỗn hợp dầu hào và tôm. Đảo đến khi tôm chín hẳn, rắc tiêu và dọn.',3,'Bày món xào ra đĩa rộng không xếp chồng quá dày giúp hơi nóng thoát nhẹ, giữ rau củ giòn ngọt lâu đến miếng cuối cùng.'),
(60,1,'Sơ chế & thái mỏng đồng đều nguyên liệu xào','Làm sạch và thấm ráo 250g nui và 250g thịt bò, dùng dao sắc thái lát mỏng vừa ăn khoảng 2–3mm ngang thớ để khi xào nhanh chín mềm không bị dai. Nhặt rửa sạch 100g hành tây, cắt khúc xéo 4cm hoặc tách nhánh đồng đều giúp tiếp xúc nhiệt nhanh trên chảo. Luộc nui trong nước sôi theo thời gian trên gói, vớt khi vừa mềm, xả nhanh nước mát và trộn chút dầu để không dính.',7,'Nguyên liệu xào bắt buộc phải để thật ráo nước trước khi cho vào chảo để đạt hiệu ứng áp nhiệt thơm kiểu chảo gang.'),
(60,2,'Ướp mềm nguyên liệu đạm & pha sẵn chén sốt xào','Ướp phần đạm trong 250g nui và 250g thịt bò với 1/3 lượng 10g tỏi, chút dầu ăn và 1/3 lượng 15ml nước tương và 2g tiêu trong 10 phút để giữ độ ẩm mọng. Pha phần 15ml nước tương và 2g tiêu còn lại cùng 20ml nước lọc vào chén nhỏ khuấy tan hoàn toàn để thao tác xào lửa lớn diễn ra dứt khoát. Thái bò mỏng, trộn với một nửa nước tương và tiêu. Cắt cà chua, hành tây và cà rốt hạt lựu.',5,'Thêm 1 muỗng cà phê dầu ăn vào bước ướp thịt bò/heo giúp khóa ẩm và các lát thịt tơi nhanh không bị dính chùm khi gặp chảo nóng.'),
(60,3,'Chần nhanh rau củ giữ sắc xanh ngọc & độ giòn','Đun sôi nồi nước nhỏ với một nhúm muối, thả 100g hành tây vào chần nhanh 30–45 giây rồi vớt ngay ra tô nước đá lạnh cho sốc nhiệt, sau đó đổ ra rổ cho thật ráo. Bước tiền xử lý này giúp rau củ chín đều từ trong mà bên ngoài vẫn xanh mướt giòn sần sật.',4,'Thời gian chần dưới 1 phút kết hợp ngâm nước đá lạnh là bí quyết nhà hàng giúp đĩa rau xào không bị chảy nước đen đĩa.'),
(60,4,'Xào săn nguyên liệu chính trên lửa lớn nhanh tay','Làm nóng chảo rộng trên lửa lớn nhất với 15ml dầu ăn, phi dậy mùi một nửa 10g tỏi rồi trút phần đạm chính trong 250g nui và 250g thịt bò vào đảo cực nhanh tay trong 60–90 giây. Ngay khi thịt hoặc hải sản vừa chín tái hồng khoảng 85%, lập tức trút riêng ra đĩa sạch để không bị quá lửa khô xác. Phi tỏi, xào bò nhanh đến vừa đổi màu rồi gắp ra. Xào cà rốt và hành tây 3 phút, thêm cà chua đến mềm.',5,'Tuyệt đối không xào thịt chung từ đầu đến cuối với rau củ vì thịt sẽ bị dai và tiết nước làm mất độ giòn.'),
(60,5,'Xào rau củ lửa lớn & rưới sốt định lượng khóa vị','Giữ nguyên chảo nóng trên lửa lớn, thêm chút dầu phi thơm nốt phần 10g tỏi còn lại rồi cho 100g hành tây đã ráo nước vào đảo đều 1–2 phút. Trút ngược đĩa đạm vào chảo, rưới đều chén sốt gia vị đã pha và xóc nhanh tay 45 giây cho sốt sánh bóng áo quanh từng miếng nguyên liệu.',5,'Rưới sốt vòng quanh thành chảo nóng thay vì đổ thẳng giữa lòng chảo giúp sốt bốc hơi thơm lừng và sệt lại tức thì.'),
(60,6,'Dậy hương tiêu hành & trình bày nóng hổi','Cho 15g hành lá vào đảo nhẹ đúng 1 lượt rồi tắt bếp ngay khi khói thơm bốc lên nghi ngút. Gắp món Nui xào bò ra đĩa rộng lòng để tản nhiệt đều, tránh đậy kín vung và thưởng thức nóng ngay cùng cơm dẻo cho 4 người. Cho nui và phần nước tương còn lại vào chảo, đảo 2 phút. Thêm bò, đảo đến nóng đều, rắc hành lá.',4,'Bày món xào ra đĩa rộng không xếp chồng quá dày giúp hơi nóng thoát nhẹ, giữ rau củ giòn ngọt lâu đến miếng cuối cùng.'),
(61,1,'Sơ chế & thái mỏng đồng đều nguyên liệu xào','Làm sạch và thấm ráo 220g miến dong và 150g thịt heo xay, dùng dao sắc thái lát mỏng vừa ăn khoảng 2–3mm ngang thớ để khi xào nhanh chín mềm không bị dai. Nhặt rửa sạch 150g bắp cải, cắt khúc xéo 4cm hoặc tách nhánh đồng đều giúp tiếp xúc nhiệt nhanh trên chảo. Ngâm miến trong nước mát đến mềm dẻo, để ráo và cắt đoạn 10 cm. Ngâm nấm hương, thái sợi; bào cà rốt và bắp cải.',8,'Nguyên liệu xào bắt buộc phải để thật ráo nước trước khi cho vào chảo để đạt hiệu ứng áp nhiệt thơm kiểu chảo gang.'),
(61,2,'Ướp mềm nguyên liệu đạm & pha sẵn chén sốt xào','Ướp phần đạm trong 220g miến dong và 150g thịt heo xay với 1/3 lượng hành tím và tỏi băm nhỏ, chút dầu ăn và 1/3 lượng 18ml nước tương trong 10 phút để giữ độ ẩm mọng. Pha phần 18ml nước tương còn lại cùng 20ml nước lọc vào chén nhỏ khuấy tan hoàn toàn để thao tác xào lửa lớn diễn ra dứt khoát. Phi hành, xào thịt băm đến săn, thêm tôm bóc vỏ và nấm. Đảo đến khi tôm vừa hồng đục.',6,'Thêm 1 muỗng cà phê dầu ăn vào bước ướp thịt bò/heo giúp khóa ẩm và các lát thịt tơi nhanh không bị dính chùm khi gặp chảo nóng.'),
(61,3,'Chần nhanh rau củ giữ sắc xanh ngọc & độ giòn','Đun sôi nồi nước nhỏ với một nhúm muối, thả 150g bắp cải vào chần nhanh 30–45 giây rồi vớt ngay ra tô nước đá lạnh cho sốc nhiệt, sau đó đổ ra rổ cho thật ráo. Bước tiền xử lý này giúp rau củ chín đều từ trong mà bên ngoài vẫn xanh mướt giòn sần sật.',5,'Thời gian chần dưới 1 phút kết hợp ngâm nước đá lạnh là bí quyết nhà hàng giúp đĩa rau xào không bị chảy nước đen đĩa.'),
(61,4,'Xào săn nguyên liệu chính trên lửa lớn nhanh tay','Làm nóng chảo rộng trên lửa lớn nhất với 15ml dầu ăn, phi dậy mùi một nửa hành tím và tỏi băm nhỏ rồi trút phần đạm chính trong 220g miến dong và 150g thịt heo xay vào đảo cực nhanh tay trong 60–90 giây. Ngay khi thịt hoặc hải sản vừa chín tái hồng khoảng 85%, lập tức trút riêng ra đĩa sạch để không bị quá lửa khô xác. Cho cà rốt và bắp cải vào, đảo lửa lớn 2–3 phút để rau vừa mềm. Nêm một nửa nước tương.',6,'Tuyệt đối không xào thịt chung từ đầu đến cuối với rau củ vì thịt sẽ bị dai và tiết nước làm mất độ giòn.'),
(61,5,'Xào rau củ lửa lớn & rưới sốt định lượng khóa vị','Giữ nguyên chảo nóng trên lửa lớn, thêm chút dầu phi thơm nốt phần hành tím và tỏi băm nhỏ còn lại rồi cho 150g bắp cải đã ráo nước vào đảo đều 1–2 phút. Trút ngược đĩa đạm vào chảo, rưới đều chén sốt gia vị đã pha và xóc nhanh tay 45 giây cho sốt sánh bóng áo quanh từng miếng nguyên liệu.',6,'Rưới sốt vòng quanh thành chảo nóng thay vì đổ thẳng giữa lòng chảo giúp sốt bốc hơi thơm lừng và sệt lại tức thì.'),
(61,6,'Dậy hương tiêu hành & trình bày nóng hổi','Cho 15g hành lá vào đảo nhẹ đúng 1 lượt rồi tắt bếp ngay khi khói thơm bốc lên nghi ngút. Gắp món Miến xào thập cẩm ra đĩa rộng lòng để tản nhiệt đều, tránh đậy kín vung và thưởng thức nóng ngay cùng cơm dẻo cho 4 người. Thêm miến với 60 ml nước, đảo bằng đũa tách sợi đến khi trong mềm. Nêm phần nước tương còn lại, thêm hành lá.',4,'Bày món xào ra đĩa rộng không xếp chồng quá dày giúp hơi nóng thoát nhẹ, giữ rau củ giòn ngọt lâu đến miếng cuối cùng.'),
(62,1,'Sơ chế & thái mỏng đồng đều nguyên liệu xào','Làm sạch và thấm ráo 350g đậu que, dùng dao sắc thái lát mỏng vừa ăn khoảng 2–3mm ngang thớ để khi xào nhanh chín mềm không bị dai. Nhặt rửa sạch rau củ ăn kèm, cắt khúc xéo 4cm hoặc tách nhánh đồng đều giúp tiếp xúc nhiệt nhanh trên chảo. Bẻ bỏ hai đầu đậu que, tước xơ nếu có, rửa sạch và để ráo. Đập dập tỏi, băm thô.',4,'Nguyên liệu xào bắt buộc phải để thật ráo nước trước khi cho vào chảo để đạt hiệu ứng áp nhiệt thơm kiểu chảo gang.'),
(62,2,'Ướp mềm nguyên liệu đạm & pha sẵn chén sốt xào','Ướp phần đạm trong 350g đậu que với 1/3 lượng 15g tỏi, chút dầu ăn và 1/3 lượng 10ml nước mắm và 2g muối trong 10 phút để giữ độ ẩm mọng. Pha phần 10ml nước mắm và 2g muối còn lại cùng 20ml nước lọc vào chén nhỏ khuấy tan hoàn toàn để thao tác xào lửa lớn diễn ra dứt khoát. Chần đậu trong nước sôi có chút muối 2 phút, vớt ra ngâm nước mát rồi để ráo để giữ màu.',4,'Thêm 1 muỗng cà phê dầu ăn vào bước ướp thịt bò/heo giúp khóa ẩm và các lát thịt tơi nhanh không bị dính chùm khi gặp chảo nóng.');
INSERT INTO `recipe_steps` (`recipe_id`,`step_order`,`title`,`instruction`,`duration_mins`,`tip_note`) VALUES
(62,3,'Chần nhanh rau củ giữ sắc xanh ngọc & độ giòn','Đun sôi nồi nước nhỏ với một nhúm muối, thả rau củ ăn kèm vào chần nhanh 30–45 giây rồi vớt ngay ra tô nước đá lạnh cho sốc nhiệt, sau đó đổ ra rổ cho thật ráo. Bước tiền xử lý này giúp rau củ chín đều từ trong mà bên ngoài vẫn xanh mướt giòn sần sật.',3,'Thời gian chần dưới 1 phút kết hợp ngâm nước đá lạnh là bí quyết nhà hàng giúp đĩa rau xào không bị chảy nước đen đĩa.'),
(62,4,'Xào săn nguyên liệu chính trên lửa lớn nhanh tay','Làm nóng chảo rộng trên lửa lớn nhất với 15ml dầu ăn, phi dậy mùi một nửa 15g tỏi rồi trút phần đạm chính trong 350g đậu que vào đảo cực nhanh tay trong 60–90 giây. Ngay khi thịt hoặc hải sản vừa chín tái hồng khoảng 85%, lập tức trút riêng ra đĩa sạch để không bị quá lửa khô xác. Phi tỏi với dầu ở lửa vừa đến thơm nhưng chưa vàng sậm. Cho đậu vào đảo lửa lớn 2 phút.',3,'Tuyệt đối không xào thịt chung từ đầu đến cuối với rau củ vì thịt sẽ bị dai và tiết nước làm mất độ giòn.'),
(62,5,'Xào rau củ lửa lớn & rưới sốt định lượng khóa vị','Giữ nguyên chảo nóng trên lửa lớn, thêm chút dầu phi thơm nốt phần 15g tỏi còn lại rồi cho rau củ ăn kèm đã ráo nước vào đảo đều 1–2 phút. Trút ngược đĩa đạm vào chảo, rưới đều chén sốt gia vị đã pha và xóc nhanh tay 45 giây cho sốt sánh bóng áo quanh từng miếng nguyên liệu.',4,'Rưới sốt vòng quanh thành chảo nóng thay vì đổ thẳng giữa lòng chảo giúp sốt bốc hơi thơm lừng và sệt lại tức thì.'),
(62,6,'Dậy hương tiêu hành & trình bày nóng hổi','Cho hành ngò và tiêu xay vào đảo nhẹ đúng 1 lượt rồi tắt bếp ngay khi khói thơm bốc lên nghi ngút. Gắp món Đậu que xào tỏi ra đĩa rộng lòng để tản nhiệt đều, tránh đậy kín vung và thưởng thức nóng ngay cùng cơm dẻo cho 4 người. Rưới nước mắm và nước, đảo đến khi nước cạn và đậu vừa chín giòn. Nếm lại rồi tắt bếp.',2,'Bày món xào ra đĩa rộng không xếp chồng quá dày giúp hơi nóng thoát nhẹ, giữ rau củ giòn ngọt lâu đến miếng cuối cùng.'),
(63,1,'Sơ chế & thái mỏng đồng đều nguyên liệu xào','Làm sạch và thấm ráo 350g bắp cải và 3 quả trứng gà, dùng dao sắc thái lát mỏng vừa ăn khoảng 2–3mm ngang thớ để khi xào nhanh chín mềm không bị dai. Nhặt rửa sạch rau củ ăn kèm, cắt khúc xéo 4cm hoặc tách nhánh đồng đều giúp tiếp xúc nhiệt nhanh trên chảo. Thái bắp cải sợi dày, rửa và để ráo thật kỹ. Đánh trứng với chút tiêu; thái hành lá.',4,'Nguyên liệu xào bắt buộc phải để thật ráo nước trước khi cho vào chảo để đạt hiệu ứng áp nhiệt thơm kiểu chảo gang.'),
(63,2,'Ướp mềm nguyên liệu đạm & pha sẵn chén sốt xào','Ướp phần đạm trong 350g bắp cải và 3 quả trứng gà với 1/3 lượng 8g tỏi, chút dầu ăn và 1/3 lượng 12ml nước mắm và 1g tiêu trong 10 phút để giữ độ ẩm mọng. Pha phần 12ml nước mắm và 1g tiêu còn lại cùng 20ml nước lọc vào chén nhỏ khuấy tan hoàn toàn để thao tác xào lửa lớn diễn ra dứt khoát. Phi tỏi, cho bắp cải vào chảo nóng đảo 3–4 phút đến khi mềm ngoài nhưng còn độ giòn.',4,'Thêm 1 muỗng cà phê dầu ăn vào bước ướp thịt bò/heo giúp khóa ẩm và các lát thịt tơi nhanh không bị dính chùm khi gặp chảo nóng.'),
(63,3,'Chần nhanh rau củ giữ sắc xanh ngọc & độ giòn','Đun sôi nồi nước nhỏ với một nhúm muối, thả rau củ ăn kèm vào chần nhanh 30–45 giây rồi vớt ngay ra tô nước đá lạnh cho sốc nhiệt, sau đó đổ ra rổ cho thật ráo. Bước tiền xử lý này giúp rau củ chín đều từ trong mà bên ngoài vẫn xanh mướt giòn sần sật.',3,'Thời gian chần dưới 1 phút kết hợp ngâm nước đá lạnh là bí quyết nhà hàng giúp đĩa rau xào không bị chảy nước đen đĩa.'),
(63,4,'Xào săn nguyên liệu chính trên lửa lớn nhanh tay','Làm nóng chảo rộng trên lửa lớn nhất với 15ml dầu ăn, phi dậy mùi một nửa 8g tỏi rồi trút phần đạm chính trong 350g bắp cải và 3 quả trứng gà vào đảo cực nhanh tay trong 60–90 giây. Ngay khi thịt hoặc hải sản vừa chín tái hồng khoảng 85%, lập tức trút riêng ra đĩa sạch để không bị quá lửa khô xác. Gạt rau sang một bên, thêm ít dầu và đổ trứng vào. Đợi trứng se rồi đảo thành miếng nhỏ cùng bắp cải.',3,'Tuyệt đối không xào thịt chung từ đầu đến cuối với rau củ vì thịt sẽ bị dai và tiết nước làm mất độ giòn.'),
(63,5,'Xào rau củ lửa lớn & rưới sốt định lượng khóa vị','Giữ nguyên chảo nóng trên lửa lớn, thêm chút dầu phi thơm nốt phần 8g tỏi còn lại rồi cho rau củ ăn kèm đã ráo nước vào đảo đều 1–2 phút. Trút ngược đĩa đạm vào chảo, rưới đều chén sốt gia vị đã pha và xóc nhanh tay 45 giây cho sốt sánh bóng áo quanh từng miếng nguyên liệu.',4,'Rưới sốt vòng quanh thành chảo nóng thay vì đổ thẳng giữa lòng chảo giúp sốt bốc hơi thơm lừng và sệt lại tức thì.'),
(63,6,'Dậy hương tiêu hành & trình bày nóng hổi','Cho 20g hành lá vào đảo nhẹ đúng 1 lượt rồi tắt bếp ngay khi khói thơm bốc lên nghi ngút. Gắp món Bắp cải xào trứng ra đĩa rộng lòng để tản nhiệt đều, tránh đậy kín vung và thưởng thức nóng ngay cùng cơm dẻo cho 4 người. Rưới nước mắm quanh mép chảo, đảo nhanh; thêm hành lá và tắt bếp khi trứng vừa chín.',2,'Bày món xào ra đĩa rộng không xếp chồng quá dày giúp hơi nóng thoát nhẹ, giữ rau củ giòn ngọt lâu đến miếng cuối cùng.'),
(64,1,'Sơ chế & thái mỏng đồng đều nguyên liệu xào','Làm sạch và thấm ráo 300g cải thìa và 120g nấm hương, dùng dao sắc thái lát mỏng vừa ăn khoảng 2–3mm ngang thớ để khi xào nhanh chín mềm không bị dai. Nhặt rửa sạch rau củ ăn kèm, cắt khúc xéo 4cm hoặc tách nhánh đồng đều giúp tiếp xúc nhiệt nhanh trên chảo. Tách cải thìa thành bẹ, rửa kỹ phần gốc. Ngâm nấm hương cho mềm, cắt bỏ chân cứng và thái lát.',4,'Nguyên liệu xào bắt buộc phải để thật ráo nước trước khi cho vào chảo để đạt hiệu ứng áp nhiệt thơm kiểu chảo gang.'),
(64,2,'Ướp mềm nguyên liệu đạm & pha sẵn chén sốt xào','Ướp phần đạm trong 300g cải thìa và 120g nấm hương với 1/3 lượng 10g tỏi, chút dầu ăn và 1/3 lượng 15ml nước tương trong 10 phút để giữ độ ẩm mọng. Pha phần 15ml nước tương còn lại cùng 20ml nước lọc vào chén nhỏ khuấy tan hoàn toàn để thao tác xào lửa lớn diễn ra dứt khoát. Phi tỏi, cho nấm vào áp chảo 2 phút đến khi thơm và hơi vàng cạnh.',4,'Thêm 1 muỗng cà phê dầu ăn vào bước ướp thịt bò/heo giúp khóa ẩm và các lát thịt tơi nhanh không bị dính chùm khi gặp chảo nóng.'),
(64,3,'Chần nhanh rau củ giữ sắc xanh ngọc & độ giòn','Đun sôi nồi nước nhỏ với một nhúm muối, thả rau củ ăn kèm vào chần nhanh 30–45 giây rồi vớt ngay ra tô nước đá lạnh cho sốc nhiệt, sau đó đổ ra rổ cho thật ráo. Bước tiền xử lý này giúp rau củ chín đều từ trong mà bên ngoài vẫn xanh mướt giòn sần sật.',3,'Thời gian chần dưới 1 phút kết hợp ngâm nước đá lạnh là bí quyết nhà hàng giúp đĩa rau xào không bị chảy nước đen đĩa.'),
(64,4,'Xào săn nguyên liệu chính trên lửa lớn nhanh tay','Làm nóng chảo rộng trên lửa lớn nhất với 15ml dầu ăn, phi dậy mùi một nửa 10g tỏi rồi trút phần đạm chính trong 300g cải thìa và 120g nấm hương vào đảo cực nhanh tay trong 60–90 giây. Ngay khi thịt hoặc hải sản vừa chín tái hồng khoảng 85%, lập tức trút riêng ra đĩa sạch để không bị quá lửa khô xác. Cho phần thân cải vào trước, đảo 1 phút rồi thêm lá. Rót nước và đậy nắp 1 phút để rau vừa chín.',3,'Tuyệt đối không xào thịt chung từ đầu đến cuối với rau củ vì thịt sẽ bị dai và tiết nước làm mất độ giòn.'),
(64,5,'Xào rau củ lửa lớn & rưới sốt định lượng khóa vị','Giữ nguyên chảo nóng trên lửa lớn, thêm chút dầu phi thơm nốt phần 10g tỏi còn lại rồi cho rau củ ăn kèm đã ráo nước vào đảo đều 1–2 phút. Trút ngược đĩa đạm vào chảo, rưới đều chén sốt gia vị đã pha và xóc nhanh tay 45 giây cho sốt sánh bóng áo quanh từng miếng nguyên liệu.',4,'Rưới sốt vòng quanh thành chảo nóng thay vì đổ thẳng giữa lòng chảo giúp sốt bốc hơi thơm lừng và sệt lại tức thì.'),
(64,6,'Dậy hương tiêu hành & trình bày nóng hổi','Cho hành ngò và tiêu xay vào đảo nhẹ đúng 1 lượt rồi tắt bếp ngay khi khói thơm bốc lên nghi ngút. Gắp món Rau cải xào nấm ra đĩa rộng lòng để tản nhiệt đều, tránh đậy kín vung và thưởng thức nóng ngay cùng cơm dẻo cho 4 người. Thêm nước tương, đảo đều đến khi cạn nước. Nhỏ dầu mè nếu dùng, tắt bếp khi rau còn xanh.',2,'Bày món xào ra đĩa rộng không xếp chồng quá dày giúp hơi nóng thoát nhẹ, giữ rau củ giòn ngọt lâu đến miếng cuối cùng.'),
(65,1,'Sơ chế tươi sạch & ngâm giòn rau củ thảo mộc','Nhặt rửa kỹ rau củ ăn kèm cùng hành ngò và tiêu xay qua nước muối loãng rồi tráng nước đun sôi để nguội. Với các loại củ quả bào sợi hoặc thái lát mỏng, ngâm vào âu nước đá lạnh pha chút chanh đường trong 10 phút rồi vắt ráo để giữ độ trắng giòn sần sật. Rửa bí ngòi, cắt lát chéo dày khoảng 7 mm. Không cắt quá mỏng để bí không nhũn khi xào.',4,'Rau củ làm gỏi và món cuốn phải quay rổ hoặc thấm thật ráo nước để khi trộn nước mắm không bị loãng nhạt.'),
(65,2,'Làm chín tới phần nhân đạm giữ trọn độ ngọt mọng','Xử lý phần nguyên liệu chính (350g bí ngòi): luộc hấp cùng lát gừng sả đập dập hoặc xào lửa lớn vừa chín tới, sau đó làm nguội nhanh rồi thái lát mỏng / xé sợi đều đặn. Nếu món có pha bột bánh gạo/bột năng, khuấy tan bột với nước đúng tỷ lệ và để bột nghỉ 15 phút cho nở mịn. Làm nóng dầu ở lửa vừa, cho tỏi lát vào đảo đến thơm vàng nhạt, không để cháy.',4,'Ngâm tôm hoặc thịt luộc qua bát nước sôi để nguội có vài viên đá giúp màu sắc tươi hồng và thớ thịt giòn ngọt không bị khô.'),
(65,3,'Rang vàng đậu phộng mè thơm & phi hành tỏi giòn','Bắc chảo nhỏ lên lửa nhỏ, rang chín vàng thơm đậu phộng/mè hoặc làm mỡ hành xanh mướt và phi vàng giòn 12g tỏi. Vớt hành tỏi phi ra đĩa riêng để nguội giòn tan, giữ lại phần dầu thơm óng ánh để phết bánh hoặc rưới bóng mặt món ăn.',3,'Tắt bếp ngay khi hành phi chuyển vàng sáng vì nhiệt dư trong dầu nóng sẽ tiếp tục làm hành sẫm màu thêm một nấc hoàn hảo.'),
(65,4,'Pha nước mắm chấm / sốt trộn tỷ lệ vàng chua ngọt','Hòa tan hoàn toàn đường cùng 10ml nước tương, 2g muối và 1g tiêu và nước ấm trong chén sâu lòng, khuấy đến khi hơi sánh nhẹ mới cho tỏi ớt băm nhuyễn và nước cốt chanh/tắc vào sau cùng. Công thức pha này giúp tỏi ớt nổi đều đẹp mắt trên bề mặt bát nước chấm chuẩn vị Bí ngòi xào tỏi. Tăng lửa, cho bí ngòi vào dàn thành lớp và áp chảo 2 phút rồi đảo. Nấu thêm 3 phút đến khi viền hơi trong.',3,'Băm tỏi ớt thật ráo trên thớt khô và cho vào sau khi đường mắm đã nguội thì tỏi ớt sẽ nổi bồng bềnh 100% không bị chìm đáy.'),
(65,5,'Phối trộn thấm vị / tráng hấp & cuốn đều tay','Tiến hành tráng hấp bánh mỏng mượt hoặc trải bánh cuốn gọn gàng 350g bí ngòi cùng rau củ ăn kèm; nếu là món gỏi trộn thì rưới từ từ 2/3 lượng sốt chua ngọt vào bóp nhẹ tay cho thấm đều trong 3 phút. Giữ lực tay nhẹ nhàng để rau củ không bị dập nát mà vẫn ngấm trọn vị mặn chua ngọt hài hòa.',4,'Chia nước sốt gỏi làm 2 lần trộn và chắt bỏ phần nước tiết ra ở lần đầu giúp đĩa gỏi khô ráo, đậm đà như ngoài hàng.'),
(65,6,'Bày biện ngũ sắc hài hòa & rắc topping giòn bùi','Xếp món Bí ngòi xào tỏi ngay ngắn ra đĩa sứ trắng rộng, rải đều phần nhân tôm thịt sắc nét lên trên và rắc phủ hành ngò và tiêu xay thơm giòn. Dọn kèm chén nước chấm đậm đà cho 4 người thưởng thức ngay khi rau bánh còn tươi giòn mướt mịn. Rưới nước tương, nêm chút muối và đảo thêm 30 giây. Tắt bếp khi bí vừa mềm, rắc tiêu nếu thích.',2,'Chỉ rắc đậu phộng rang và hành phi ngay trước lúc mang ra bàn ăn để giữ nguyên độ giòn tan bùi béo.'),
(66,1,'Sơ chế & thái mỏng đồng đều nguyên liệu xào','Làm sạch và thấm ráo 250g mì trứng giòn và 150g tôm sú, dùng dao sắc thái lát mỏng vừa ăn khoảng 2–3mm ngang thớ để khi xào nhanh chín mềm không bị dai. Nhặt rửa sạch rau củ ăn kèm, cắt khúc xéo 4cm hoặc tách nhánh đồng đều giúp tiếp xúc nhiệt nhanh trên chảo. Bóc tôm, bỏ chỉ; ngâm nấm, thái lát. Cắt bông cải thành nhánh và cà rốt lát xéo; hòa bột bắp với 70 ml nước.',9,'Nguyên liệu xào bắt buộc phải để thật ráo nước trước khi cho vào chảo để đạt hiệu ứng áp nhiệt thơm kiểu chảo gang.'),
(66,2,'Ướp mềm nguyên liệu đạm & pha sẵn chén sốt xào','Ướp phần đạm trong 250g mì trứng giòn và 150g tôm sú với 1/3 lượng hành tím và tỏi băm nhỏ, chút dầu ăn và 1/3 lượng 18ml dầu hào trong 10 phút để giữ độ ẩm mọng. Pha phần 18ml dầu hào còn lại cùng 20ml nước lọc vào chén nhỏ khuấy tan hoàn toàn để thao tác xào lửa lớn diễn ra dứt khoát. Tách mì thành phần nhỏ. Đun dầu vừa nóng, chiên từng phần đến vàng giòn rồi để ráo trên giấy thấm dầu.',8,'Thêm 1 muỗng cà phê dầu ăn vào bước ướp thịt bò/heo giúp khóa ẩm và các lát thịt tơi nhanh không bị dính chùm khi gặp chảo nóng.'),
(66,3,'Chần nhanh rau củ giữ sắc xanh ngọc & độ giòn','Đun sôi nồi nước nhỏ với một nhúm muối, thả rau củ ăn kèm vào chần nhanh 30–45 giây rồi vớt ngay ra tô nước đá lạnh cho sốc nhiệt, sau đó đổ ra rổ cho thật ráo. Bước tiền xử lý này giúp rau củ chín đều từ trong mà bên ngoài vẫn xanh mướt giòn sần sật.',7,'Thời gian chần dưới 1 phút kết hợp ngâm nước đá lạnh là bí quyết nhà hàng giúp đĩa rau xào không bị chảy nước đen đĩa.');
INSERT INTO `recipe_steps` (`recipe_id`,`step_order`,`title`,`instruction`,`duration_mins`,`tip_note`) VALUES
(66,4,'Xào săn nguyên liệu chính trên lửa lớn nhanh tay','Làm nóng chảo rộng trên lửa lớn nhất với 15ml dầu ăn, phi dậy mùi một nửa hành tím và tỏi băm nhỏ rồi trút phần đạm chính trong 250g mì trứng giòn và 150g tôm sú vào đảo cực nhanh tay trong 60–90 giây. Ngay khi thịt hoặc hải sản vừa chín tái hồng khoảng 85%, lập tức trút riêng ra đĩa sạch để không bị quá lửa khô xác. Chắt bớt dầu, xào thịt đến săn rồi thêm tôm. Khi tôm chuyển hồng đục, cho nấm và rau củ, đảo 3 phút.',8,'Tuyệt đối không xào thịt chung từ đầu đến cuối với rau củ vì thịt sẽ bị dai và tiết nước làm mất độ giòn.'),
(66,5,'Xào rau củ lửa lớn & rưới sốt định lượng khóa vị','Giữ nguyên chảo nóng trên lửa lớn, thêm chút dầu phi thơm nốt phần hành tím và tỏi băm nhỏ còn lại rồi cho rau củ ăn kèm đã ráo nước vào đảo đều 1–2 phút. Trút ngược đĩa đạm vào chảo, rưới đều chén sốt gia vị đã pha và xóc nhanh tay 45 giây cho sốt sánh bóng áo quanh từng miếng nguyên liệu.',8,'Rưới sốt vòng quanh thành chảo nóng thay vì đổ thẳng giữa lòng chảo giúp sốt bốc hơi thơm lừng và sệt lại tức thì.'),
(66,6,'Dậy hương tiêu hành & trình bày nóng hổi','Cho hành ngò và tiêu xay vào đảo nhẹ đúng 1 lượt rồi tắt bếp ngay khi khói thơm bốc lên nghi ngút. Gắp món Mì xào giòn thập cẩm ra đĩa rộng lòng để tản nhiệt đều, tránh đậy kín vung và thưởng thức nóng ngay cùng cơm dẻo cho 4 người. Thêm dầu hào cùng 250 ml nước, nấu đến rau vừa chín. Rót bột bắp từ từ cho sốt sánh, chan lên mì ngay trước khi ăn.',5,'Bày món xào ra đĩa rộng không xếp chồng quá dày giúp hơi nóng thoát nhẹ, giữ rau củ giòn ngọt lâu đến miếng cuối cùng.'),
(67,1,'Sơ chế & chần sạch nguyên liệu xương thịt, hải sản','Rửa sạch 500g cá hồi với muối hạt rồi chần nhanh trong nồi nước sôi có đập dập 1 nhánh gừng trong 2–3 phút trên lửa lớn để loại bỏ hoàn toàn bọt bẩn. Rửa lại dưới làn nước sạch cho thật trắng trẻo, đồng thời nhặt rửa sạch 8g mùi tây để ráo nước. Thấm cá hồi thật khô, kiểm tra và gỡ xương dăm. Nêm muối, tiêu hai mặt và để ngoài 10 phút.',3,'Bước chần sơ và rửa lại bằng nước ấm là bí quyết vàng giúp nồi nước dùng trong vắt, thơm thanh và không bao giờ bị đục hay hôi.'),
(67,2,'Nướng thơm thảo mộc & ninh nền nước dùng ngọt thanh','Cho phần nguyên liệu tạo ngọt từ 500g cá hồi cùng 8g tỏi đã nướng xém thơm vào nồi sâu lòng với khoảng 1.5–1.8 lít nước lọc. Đun sôi bùng trên lửa lớn rồi hạ ngay về lửa nhỏ liu riu, mở hé vung và hớt kỹ bọt nổi trên mặt để chiết xuất vị ngọt tự nhiên. Làm nóng chảo, thêm dầu. Đặt cá phía da xuống, ép nhẹ 20 giây rồi áp chảo 4–5 phút; lật mặt thịt 2–3 phút.',6,'Luôn duy trì mặt nước lăn tăn nhẹ thay vì đun sôi sùng sục lửa to để protein không bị nhũ hóa gây đục nước lèo.'),
(67,3,'Xào tạo màu & dậy hương đặc trưng vùng miền','Bắc chảo nhỏ lên bếp với 15ml dầu ăn trên lửa vừa, phi thơm phần hành tỏi sả băm còn lại rồi xào săn các nguyên liệu phối kèm cùng 1 quả chanh, 3g muối và 2g tiêu trong 3–4 phút. Khi hỗn hợp dậy mùi thơm nồng nàn và lên sắc màu óng ả đặc trưng của món Cá hồi áp chảo sốt bơ chanh thì tắt bếp.',3,'Xào riêng phần nguyên liệu tạo màu và gia vị thơm trước khi trút vào nồi nước dùng giúp tầng hương dậy lên rõ nét gấp đôi.'),
(67,4,'Sơ chế & cắt thái phần nhân topping xếp tô','Vớt phần thịt hoặc hải sản chín tới từ 500g cá hồi ra ngâm ngay vào âu nước đun sôi để nguội giúp bề mặt săn giòn mọng nước, không bị thâm khô. Thái lát mỏng đều tay dày khoảng 3mm ngang thớ hoặc gỡ miếng vừa ăn, sắp riêng từng phần gọn gàng trên đĩa.',3,'Thái thịt ngang thớ với lưỡi dao thật sắc giúp lát thịt mềm mướt, khi chan nước dùng sôi lên sẽ phẳng đẹp không bị quăn cứng.'),
(67,5,'Hợp nhất nồi nước lèo & nêm chuẩn định lượng','Trút phần sốt màu thơm vào nồi nước dùng đang sôi lăn tăn, nêm chính xác lượng 1 quả chanh, 3g muối và 2g tiêu còn lại cho vừa miệng 4 người ăn. Đun nhẹ thêm 5 phút ở lửa vừa để các tầng vị mặn dịu, ngọt hậu từ xương thịt và thảo mộc hòa quyện tròn trịa. Hạ lửa, cho bơ và tỏi băm vào chảo, đảo thơm 30 giây. Thêm nước cốt chanh, khuấy thành sốt.',3,'Nên nêm nước mắm ngon ở giai đoạn cuối trên lửa nhỏ để giữ trọn hậu vị ngọt đạm và hương thơm mà không làm nước dùng bị chua.'),
(67,6,'Chần nóng sợi bánh/bún & chuẩn bị rau ăn kèm','Đun sôi một nồi nước riêng, cho phần sợi bún/phở/bánh trong 500g cá hồi vào trụng nhanh 15–25 giây cho sợi mềm dẻo nóng hổi rồi vẩy thật ráo nước, chia đều vào 4 tô lớn. Chần sơ thêm rau ăn kèm (giá đỗ, rau xanh) nếu muốn dùng chín giòn.',2,'Trụng bún bánh ở nồi nước sôi riêng biệt giúp nước dùng chính không bị nhiễm tinh bột chua và tô bún luôn ráo sợi, thấm vị.'),
(67,7,'Xếp nhân hài hòa, chan nước dùng sôi & thưởng thức','Xếp đều các phần nhân thịt, hải sản lên mặt tô bún bánh, điểm xuyết 8g mùi tây lên trên cùng. Dùng muôi múc nước dùng đang sôi thật già chan ngập xăm xắp mặt nguyên liệu để làm chín thơm hành ngò, dọn nóng ngay kèm chanh ớt tươi. Cá chín khi phần thịt đục và tách dễ bằng nĩa; dùng nhiệt kế đạt 63°C nếu có. Rưới sốt, thêm mùi tây nếu dùng.',2,'Tráng nóng tô sứ bằng nước sôi trước khi xếp bún giúp tô món nước giữ nhiệt bốc khói nghi ngút suốt bữa ăn.'),
(68,1,'Sơ chế sạch & thấm thật khô bề mặt nguyên liệu','Rửa sạch 700g cánh gà và 30g bột bắp cùng chút muối loãng để khử mùi tự nhiên, sau đó dùng khăn giấy bếp thấm thật khô ráo hoàn toàn bề mặt. Khứa nhẹ các đường chéo hoặc cắt miếng vừa ăn dày 2–3cm để nhiệt và gia vị thấm sâu đều khắp bên trong. Chặt cánh gà làm đôi, rửa sạch và thấm khô kỹ. Trộn nước mắm, đường, tiêu và 30 ml nước thành sốt.',6,'Bề mặt nguyên liệu càng khô ráo thì khi chiên không bị văng dầu và khi nướng sẽ lên màu vàng ruộm giòn rụm cực đẹp.'),
(68,2,'Chuẩn bị hỗn hợp sốt ướp / bột áo chuẩn tỷ lệ','Phối trộn 15g tỏi băm thật nhuyễn (hoặc vắt lấy nước cốt thơm) cùng 25ml nước mắm, 15g đường, 2g tiêu và 1 quả ớt trong tô lớn cho quyện sánh đồng nhất. Nếu món có lớp vỏ bột hoặc bánh cuốn từ 700g cánh gà và 30g bột bắp, trộn đều hỗn hợp theo đúng định lượng để đạt độ giòn xốp mỏng nhẹ chuẩn vị. Phủ cánh gà lớp bột bắp mỏng, giũ phần bột thừa để dầu không vón và lớp vỏ không quá dày.',6,'Vắt lấy nước cốt hành tỏi sả khi ướp đồ nướng giúp hương thơm thấm sâu mà không bị cháy đen phần xác băm trên lửa cao.'),
(68,3,'Ướp thấm thớ thịt / tạo hình cuốn khéo léo','Áo đều hỗn hợp gia vị hoặc lớp bột/vỏ cuốn quanh 700g cánh gà và 30g bột bắp, massage nhẹ nhàng rồi để nghỉ 15–20 phút cho gia vị thẩm thấu trọn vẹn. Trường hợp cuốn chả/nem hoặc đổ khuôn bánh, thao tác đều tay vừa chặt để nhân kết dính nhưng không bị bục rách khi gặp nhiệt.',7,'Để nguyên liệu nghỉ đủ thời gian trước khi chiên nướng giúp lớp áo bột bám chắc và phần nhân bên trong mọng ngọt.'),
(68,4,'Pha nước chấm cân vị & sơ chế rau đồ chua ăn kèm','Nhặt rửa sạch rau củ ăn kèm ngâm nước mát cho giòn tươi, bào sợi hoặc thái lát gọn gàng bày sẵn bên cạnh. Pha chén nước chấm chua ngọt hoặc muối ớt chanh sả sánh thơm theo khẩu vị vùng miền của món Cánh gà chiên nước mắm để cân bằng độ béo giòn.',5,'Luôn chuẩn bị xong rau sống và bát nước chấm trước khi chiên/nướng mẻ cuối để món ăn vừa ra lò là thưởng thức nóng giòn ngay.'),
(68,5,'Làm nóng dầu / lò nướng chuẩn nhiệt & làm chín đều lần 1','Làm nóng chảo dầu hoặc vỉ nướng/nồi chiên ở mức nhiệt vừa khoảng 165–175°C, xếp 700g cánh gà và 30g bột bắp vào với khoảng cách thoáng đều nhau. Chiên hoặc nướng trở mặt nhịp nhàng trên lửa vừa để nhiệt dẫn sâu làm chín mềm ngọt hoàn toàn phần nhân bên trong. Chiên từng mẻ trong dầu 170°C khoảng 10–12 phút, trở đều đến vàng. Phần dày nhất cần đạt 74°C; để ráo trên giá.',9,'Kiểm tra nhiệt dầu bằng đầu đũa tre thấy sủi tăm nhỏ đều là đạt chuẩn 170°C, giúp vỏ không cháy sớm khi bên trong còn sống.'),
(68,6,'Tăng nhiệt khóa giòn rụm vàng ươm bề mặt lần 2','Ở 2–3 phút cuối, tăng lên lửa vừa lớn (khoảng 190°C) hoặc phết thêm lớp dầu điều/mật ong mỏng để vỏ ngoài của Cánh gà chiên nước mắm chuyển sắc vàng óng ánh và nổ giòn rụm. Lắng nghe tiếng xèo giòn rộn rã và hương thơm phức lan tỏa khắp bếp thì gắp ra vỉ thưa cho ráo dầu thừa.',4,'Đặt đồ chiên nướng lên giá inox thoáng khí thay vì giấy thấm dầu chồng khít để hơi nước thoát hết, giữ độ giòn lâu gấp 3 lần.'),
(68,7,'Trình bày bắt mắt kèm rau thơm & thưởng thức nóng','Xếp thành phẩm vàng giòn ra đĩa lớn có bày sẵn rau củ ăn kèm và điểm xuyết hành ngò và tiêu xay tươi xanh hài hòa màu sắc. Dọn kèm chén nước chấm sánh đậm ngay chính giữa mâm ăn cho 4 người thưởng thức khi vỏ ngoài còn nóng giòn rụm. Phi tỏi, đổ sốt vào đun sôi nhẹ đến hơi sánh. Cho cánh gà vào đảo nhanh cho áo đều; thêm ớt nếu thích.',3,'Cắt miếng hoặc dọn ăn ngay trong vòng 10 phút sau khi rời bếp để cảm nhận trọn vẹn sự đối lập giòn ngoài - mềm ngọt bên trong.'),
(69,1,'Sơ chế sạch & thấm thật khô bề mặt nguyên liệu','Rửa sạch 500g thịt heo xay và 150g giò sống cùng chút muối loãng để khử mùi tự nhiên, sau đó dùng khăn giấy bếp thấm thật khô ráo hoàn toàn bề mặt. Khứa nhẹ các đường chéo hoặc cắt miếng vừa ăn dày 2–3cm để nhiệt và gia vị thấm sâu đều khắp bên trong. Trộn thịt heo xay và giò sống với sả, tỏi băm, nước mắm, đường và tiêu. Nhồi đều 2–3 phút rồi để lạnh 20 phút.',7,'Bề mặt nguyên liệu càng khô ráo thì khi chiên không bị văng dầu và khi nướng sẽ lên màu vàng ruộm giòn rụm cực đẹp.'),
(69,2,'Chuẩn bị hỗn hợp sốt ướp / bột áo chuẩn tỷ lệ','Phối trộn 3 cây sả và 12g tỏi băm thật nhuyễn (hoặc vắt lấy nước cốt thơm) cùng 20ml nước mắm, 12g đường và 2g tiêu trong tô lớn cho quyện sánh đồng nhất. Nếu món có lớp vỏ bột hoặc bánh cuốn từ 500g thịt heo xay và 150g giò sống, trộn đều hỗn hợp theo đúng định lượng để đạt độ giòn xốp mỏng nhẹ chuẩn vị. Chia nhân thành phần bằng nhau, nặn quanh que sả hoặc que xiên đã làm ẩm; ép vừa tay để nem không nứt.',6,'Vắt lấy nước cốt hành tỏi sả khi ướp đồ nướng giúp hương thơm thấm sâu mà không bị cháy đen phần xác băm trên lửa cao.'),
(69,3,'Ướp thấm thớ thịt / tạo hình cuốn khéo léo','Áo đều hỗn hợp gia vị hoặc lớp bột/vỏ cuốn quanh 500g thịt heo xay và 150g giò sống, massage nhẹ nhàng rồi để nghỉ 15–20 phút cho gia vị thẩm thấu trọn vẹn. Trường hợp cuốn chả/nem hoặc đổ khuôn bánh, thao tác đều tay vừa chặt để nhân kết dính nhưng không bị bục rách khi gặp nhiệt.',8,'Để nguyên liệu nghỉ đủ thời gian trước khi chiên nướng giúp lớp áo bột bám chắc và phần nhân bên trong mọng ngọt.'),
(69,4,'Pha nước chấm cân vị & sơ chế rau đồ chua ăn kèm','Nhặt rửa sạch 100g xà lách ngâm nước mát cho giòn tươi, bào sợi hoặc thái lát gọn gàng bày sẵn bên cạnh. Pha chén nước chấm chua ngọt hoặc muối ớt chanh sả sánh thơm theo khẩu vị vùng miền của món Nem nướng Nha Trang để cân bằng độ béo giòn.',5,'Luôn chuẩn bị xong rau sống và bát nước chấm trước khi chiên/nướng mẻ cuối để món ăn vừa ra lò là thưởng thức nóng giòn ngay.'),
(69,5,'Làm nóng dầu / lò nướng chuẩn nhiệt & làm chín đều lần 1','Làm nóng chảo dầu hoặc vỉ nướng/nồi chiên ở mức nhiệt vừa khoảng 165–175°C, xếp 500g thịt heo xay và 150g giò sống vào với khoảng cách thoáng đều nhau. Chiên hoặc nướng trở mặt nhịp nhàng trên lửa vừa để nhiệt dẫn sâu làm chín mềm ngọt hoàn toàn phần nhân bên trong. Nướng trên vỉ lửa vừa, trở đều 10–12 phút đến khi phần giữa đạt 71°C và mặt nem xém nhẹ. Có thể dùng nồi chiên 180°C.',10,'Kiểm tra nhiệt dầu bằng đầu đũa tre thấy sủi tăm nhỏ đều là đạt chuẩn 170°C, giúp vỏ không cháy sớm khi bên trong còn sống.'),
(69,6,'Tăng nhiệt khóa giòn rụm vàng ươm bề mặt lần 2','Ở 2–3 phút cuối, tăng lên lửa vừa lớn (khoảng 190°C) hoặc phết thêm lớp dầu điều/mật ong mỏng để vỏ ngoài của Nem nướng Nha Trang chuyển sắc vàng óng ánh và nổ giòn rụm. Lắng nghe tiếng xèo giòn rộn rã và hương thơm phức lan tỏa khắp bếp thì gắp ra vỉ thưa cho ráo dầu thừa.',5,'Đặt đồ chiên nướng lên giá inox thoáng khí thay vì giấy thấm dầu chồng khít để hơi nước thoát hết, giữ độ giòn lâu gấp 3 lần.'),
(69,7,'Trình bày bắt mắt kèm rau thơm & thưởng thức nóng','Xếp thành phẩm vàng giòn ra đĩa lớn có bày sẵn 100g xà lách và điểm xuyết hành ngò và tiêu xay tươi xanh hài hòa màu sắc. Dọn kèm chén nước chấm sánh đậm ngay chính giữa mâm ăn cho 4 người thưởng thức khi vỏ ngoài còn nóng giòn rụm. Để nem nghỉ 2 phút, ăn cuốn với bánh tráng và xà lách nếu dùng. Không đặt nem chín lên đĩa từng đựng thịt sống.',4,'Cắt miếng hoặc dọn ăn ngay trong vòng 10 phút sau khi rời bếp để cảm nhận trọn vẹn sự đối lập giòn ngoài - mềm ngọt bên trong.'),
(70,1,'Sơ chế sạch & thấm thật khô bề mặt nguyên liệu','Rửa sạch 600g thịt heo (nạc vai) cùng chút muối loãng để khử mùi tự nhiên, sau đó dùng khăn giấy bếp thấm thật khô ráo hoàn toàn bề mặt. Khứa nhẹ các đường chéo hoặc cắt miếng vừa ăn dày 2–3cm để nhiệt và gia vị thấm sâu đều khắp bên trong. Thái thịt lát dày 5–7 mm. Trộn sả và hành tím băm, nước mắm, mật ong, dầu và tiêu; ướp thịt 30 phút.',6,'Bề mặt nguyên liệu càng khô ráo thì khi chiên không bị văng dầu và khi nướng sẽ lên màu vàng ruộm giòn rụm cực đẹp.');
INSERT INTO `recipe_steps` (`recipe_id`,`step_order`,`title`,`instruction`,`duration_mins`,`tip_note`) VALUES
(70,2,'Chuẩn bị hỗn hợp sốt ướp / bột áo chuẩn tỷ lệ','Phối trộn 3 cây sả và 20g hành tím băm thật nhuyễn (hoặc vắt lấy nước cốt thơm) cùng 25ml nước mắm, 18ml mật ong và 2g tiêu trong tô lớn cho quyện sánh đồng nhất. Nếu món có lớp vỏ bột hoặc bánh cuốn từ 600g thịt heo (nạc vai), trộn đều hỗn hợp theo đúng định lượng để đạt độ giòn xốp mỏng nhẹ chuẩn vị. Ngâm que tre trong nước 20 phút. Xiên thịt lỏng tay để nhiệt đi qua, gập đôi miếng mỏng nếu cần.',6,'Vắt lấy nước cốt hành tỏi sả khi ướp đồ nướng giúp hương thơm thấm sâu mà không bị cháy đen phần xác băm trên lửa cao.'),
(70,3,'Ướp thấm thớ thịt / tạo hình cuốn khéo léo','Áo đều hỗn hợp gia vị hoặc lớp bột/vỏ cuốn quanh 600g thịt heo (nạc vai), massage nhẹ nhàng rồi để nghỉ 15–20 phút cho gia vị thẩm thấu trọn vẹn. Trường hợp cuốn chả/nem hoặc đổ khuôn bánh, thao tác đều tay vừa chặt để nhân kết dính nhưng không bị bục rách khi gặp nhiệt.',7,'Để nguyên liệu nghỉ đủ thời gian trước khi chiên nướng giúp lớp áo bột bám chắc và phần nhân bên trong mọng ngọt.'),
(70,4,'Pha nước chấm cân vị & sơ chế rau đồ chua ăn kèm','Nhặt rửa sạch rau củ ăn kèm ngâm nước mát cho giòn tươi, bào sợi hoặc thái lát gọn gàng bày sẵn bên cạnh. Pha chén nước chấm chua ngọt hoặc muối ớt chanh sả sánh thơm theo khẩu vị vùng miền của món Thịt xiên nướng sả để cân bằng độ béo giòn.',5,'Luôn chuẩn bị xong rau sống và bát nước chấm trước khi chiên/nướng mẻ cuối để món ăn vừa ra lò là thưởng thức nóng giòn ngay.'),
(70,5,'Làm nóng dầu / lò nướng chuẩn nhiệt & làm chín đều lần 1','Làm nóng chảo dầu hoặc vỉ nướng/nồi chiên ở mức nhiệt vừa khoảng 165–175°C, xếp 600g thịt heo (nạc vai) vào với khoảng cách thoáng đều nhau. Chiên hoặc nướng trở mặt nhịp nhàng trên lửa vừa để nhiệt dẫn sâu làm chín mềm ngọt hoàn toàn phần nhân bên trong. Nướng vỉ hoặc nồi chiên 190°C khoảng 10–14 phút, trở giữa chừng; không phết lại nước ướp đã chạm thịt sống.',9,'Kiểm tra nhiệt dầu bằng đầu đũa tre thấy sủi tăm nhỏ đều là đạt chuẩn 170°C, giúp vỏ không cháy sớm khi bên trong còn sống.'),
(70,6,'Tăng nhiệt khóa giòn rụm vàng ươm bề mặt lần 2','Ở 2–3 phút cuối, tăng lên lửa vừa lớn (khoảng 190°C) hoặc phết thêm lớp dầu điều/mật ong mỏng để vỏ ngoài của Thịt xiên nướng sả chuyển sắc vàng óng ánh và nổ giòn rụm. Lắng nghe tiếng xèo giòn rộn rã và hương thơm phức lan tỏa khắp bếp thì gắp ra vỉ thưa cho ráo dầu thừa.',4,'Đặt đồ chiên nướng lên giá inox thoáng khí thay vì giấy thấm dầu chồng khít để hơi nước thoát hết, giữ độ giòn lâu gấp 3 lần.'),
(70,7,'Trình bày bắt mắt kèm rau thơm & thưởng thức nóng','Xếp thành phẩm vàng giòn ra đĩa lớn có bày sẵn rau củ ăn kèm và điểm xuyết hành ngò và tiêu xay tươi xanh hài hòa màu sắc. Dọn kèm chén nước chấm sánh đậm ngay chính giữa mâm ăn cho 4 người thưởng thức khi vỏ ngoài còn nóng giòn rụm. Đo phần thịt dày nhất đạt 63°C, để nghỉ 3 phút rồi dùng. Dọn cùng rau hoặc bún.',3,'Cắt miếng hoặc dọn ăn ngay trong vòng 10 phút sau khi rời bếp để cảm nhận trọn vẹn sự đối lập giòn ngoài - mềm ngọt bên trong.'),
(71,1,'Sơ chế sạch & thấm thật khô bề mặt nguyên liệu','Rửa sạch 800g sườn non cùng chút muối loãng để khử mùi tự nhiên, sau đó dùng khăn giấy bếp thấm thật khô ráo hoàn toàn bề mặt. Khứa nhẹ các đường chéo hoặc cắt miếng vừa ăn dày 2–3cm để nhiệt và gia vị thấm sâu đều khắp bên trong. Chặt sườn thành dải, thấm khô. Trộn mật ong, tỏi, nước tương, dầu hào, dầu và tiêu; ướp ít nhất 1 giờ.',9,'Bề mặt nguyên liệu càng khô ráo thì khi chiên không bị văng dầu và khi nướng sẽ lên màu vàng ruộm giòn rụm cực đẹp.'),
(71,2,'Chuẩn bị hỗn hợp sốt ướp / bột áo chuẩn tỷ lệ','Phối trộn 15g tỏi băm thật nhuyễn (hoặc vắt lấy nước cốt thơm) cùng 30ml mật ong, 25ml nước tương, 15ml dầu hào và 2g tiêu trong tô lớn cho quyện sánh đồng nhất. Nếu món có lớp vỏ bột hoặc bánh cuốn từ 800g sườn non, trộn đều hỗn hợp theo đúng định lượng để đạt độ giòn xốp mỏng nhẹ chuẩn vị. Làm nóng lò ở 190°C. Xếp sườn lên khay có lót giấy bạc, chừa khoảng trống để nhiệt lưu thông.',8,'Vắt lấy nước cốt hành tỏi sả khi ướp đồ nướng giúp hương thơm thấm sâu mà không bị cháy đen phần xác băm trên lửa cao.'),
(71,3,'Ướp thấm thớ thịt / tạo hình cuốn khéo léo','Áo đều hỗn hợp gia vị hoặc lớp bột/vỏ cuốn quanh 800g sườn non, massage nhẹ nhàng rồi để nghỉ 15–20 phút cho gia vị thẩm thấu trọn vẹn. Trường hợp cuốn chả/nem hoặc đổ khuôn bánh, thao tác đều tay vừa chặt để nhân kết dính nhưng không bị bục rách khi gặp nhiệt.',11,'Để nguyên liệu nghỉ đủ thời gian trước khi chiên nướng giúp lớp áo bột bám chắc và phần nhân bên trong mọng ngọt.'),
(71,4,'Pha nước chấm cân vị & sơ chế rau đồ chua ăn kèm','Nhặt rửa sạch rau củ ăn kèm ngâm nước mát cho giòn tươi, bào sợi hoặc thái lát gọn gàng bày sẵn bên cạnh. Pha chén nước chấm chua ngọt hoặc muối ớt chanh sả sánh thơm theo khẩu vị vùng miền của món Sườn nướng mật ong để cân bằng độ béo giòn.',7,'Luôn chuẩn bị xong rau sống và bát nước chấm trước khi chiên/nướng mẻ cuối để món ăn vừa ra lò là thưởng thức nóng giòn ngay.'),
(71,5,'Làm nóng dầu / lò nướng chuẩn nhiệt & làm chín đều lần 1','Làm nóng chảo dầu hoặc vỉ nướng/nồi chiên ở mức nhiệt vừa khoảng 165–175°C, xếp 800g sườn non vào với khoảng cách thoáng đều nhau. Chiên hoặc nướng trở mặt nhịp nhàng trên lửa vừa để nhiệt dẫn sâu làm chín mềm ngọt hoàn toàn phần nhân bên trong. Bọc kín khay bằng giấy bạc, nướng 25 phút. Mở giấy, trở sườn và nướng thêm 10–15 phút đến chín mềm.',13,'Kiểm tra nhiệt dầu bằng đầu đũa tre thấy sủi tăm nhỏ đều là đạt chuẩn 170°C, giúp vỏ không cháy sớm khi bên trong còn sống.'),
(71,6,'Tăng nhiệt khóa giòn rụm vàng ươm bề mặt lần 2','Ở 2–3 phút cuối, tăng lên lửa vừa lớn (khoảng 190°C) hoặc phết thêm lớp dầu điều/mật ong mỏng để vỏ ngoài của Sườn nướng mật ong chuyển sắc vàng óng ánh và nổ giòn rụm. Lắng nghe tiếng xèo giòn rộn rã và hương thơm phức lan tỏa khắp bếp thì gắp ra vỉ thưa cho ráo dầu thừa.',7,'Đặt đồ chiên nướng lên giá inox thoáng khí thay vì giấy thấm dầu chồng khít để hơi nước thoát hết, giữ độ giòn lâu gấp 3 lần.'),
(71,7,'Trình bày bắt mắt kèm rau thơm & thưởng thức nóng','Xếp thành phẩm vàng giòn ra đĩa lớn có bày sẵn rau củ ăn kèm và điểm xuyết hành ngò và tiêu xay tươi xanh hài hòa màu sắc. Dọn kèm chén nước chấm sánh đậm ngay chính giữa mâm ăn cho 4 người thưởng thức khi vỏ ngoài còn nóng giòn rụm. Quét lớp sốt ướp đã đun sôi trong 3 phút cuối, theo dõi để mật ong không cháy. Để sườn nghỉ 5 phút rồi chặt.',5,'Cắt miếng hoặc dọn ăn ngay trong vòng 10 phút sau khi rời bếp để cảm nhận trọn vẹn sự đối lập giòn ngoài - mềm ngọt bên trong.'),
(72,1,'Sơ chế sạch & thấm thật khô bề mặt nguyên liệu','Rửa sạch 600g khoai tây và 15g bột bắp cùng chút muối loãng để khử mùi tự nhiên, sau đó dùng khăn giấy bếp thấm thật khô ráo hoàn toàn bề mặt. Khứa nhẹ các đường chéo hoặc cắt miếng vừa ăn dày 2–3cm để nhiệt và gia vị thấm sâu đều khắp bên trong. Gọt khoai, cắt thanh đều khoảng 1 cm. Ngâm nước lạnh 20 phút để bớt tinh bột rồi rửa và lau thật khô.',5,'Bề mặt nguyên liệu càng khô ráo thì khi chiên không bị văng dầu và khi nướng sẽ lên màu vàng ruộm giòn rụm cực đẹp.'),
(72,2,'Chuẩn bị hỗn hợp sốt ướp / bột áo chuẩn tỷ lệ','Phối trộn 20g hành tím băm thật nhuyễn (hoặc vắt lấy nước cốt thơm) cùng 5g muối và 50g tương cà trong tô lớn cho quyện sánh đồng nhất. Nếu món có lớp vỏ bột hoặc bánh cuốn từ 600g khoai tây và 15g bột bắp, trộn đều hỗn hợp theo đúng định lượng để đạt độ giòn xốp mỏng nhẹ chuẩn vị. Luộc khoai trong nước sôi 4–5 phút đến khi hơi mềm nhưng chưa vỡ. Vớt ra hong nguội hoàn toàn.',5,'Vắt lấy nước cốt hành tỏi sả khi ướp đồ nướng giúp hương thơm thấm sâu mà không bị cháy đen phần xác băm trên lửa cao.'),
(72,3,'Ướp thấm thớ thịt / tạo hình cuốn khéo léo','Áo đều hỗn hợp gia vị hoặc lớp bột/vỏ cuốn quanh 600g khoai tây và 15g bột bắp, massage nhẹ nhàng rồi để nghỉ 15–20 phút cho gia vị thẩm thấu trọn vẹn. Trường hợp cuốn chả/nem hoặc đổ khuôn bánh, thao tác đều tay vừa chặt để nhân kết dính nhưng không bị bục rách khi gặp nhiệt.',6,'Để nguyên liệu nghỉ đủ thời gian trước khi chiên nướng giúp lớp áo bột bám chắc và phần nhân bên trong mọng ngọt.'),
(72,4,'Pha nước chấm cân vị & sơ chế rau đồ chua ăn kèm','Nhặt rửa sạch rau củ ăn kèm ngâm nước mát cho giòn tươi, bào sợi hoặc thái lát gọn gàng bày sẵn bên cạnh. Pha chén nước chấm chua ngọt hoặc muối ớt chanh sả sánh thơm theo khẩu vị vùng miền của món Khoai tây chiên giòn để cân bằng độ béo giòn.',4,'Luôn chuẩn bị xong rau sống và bát nước chấm trước khi chiên/nướng mẻ cuối để món ăn vừa ra lò là thưởng thức nóng giòn ngay.'),
(72,5,'Làm nóng dầu / lò nướng chuẩn nhiệt & làm chín đều lần 1','Làm nóng chảo dầu hoặc vỉ nướng/nồi chiên ở mức nhiệt vừa khoảng 165–175°C, xếp 600g khoai tây và 15g bột bắp vào với khoảng cách thoáng đều nhau. Chiên hoặc nướng trở mặt nhịp nhàng trên lửa vừa để nhiệt dẫn sâu làm chín mềm ngọt hoàn toàn phần nhân bên trong. Chiên ở 150°C trong 5–6 phút để khoai chín bên trong nhưng chưa vàng. Vớt ra để nguội 10 phút.',8,'Kiểm tra nhiệt dầu bằng đầu đũa tre thấy sủi tăm nhỏ đều là đạt chuẩn 170°C, giúp vỏ không cháy sớm khi bên trong còn sống.'),
(72,6,'Tăng nhiệt khóa giòn rụm vàng ươm bề mặt lần 2','Ở 2–3 phút cuối, tăng lên lửa vừa lớn (khoảng 190°C) hoặc phết thêm lớp dầu điều/mật ong mỏng để vỏ ngoài của Khoai tây chiên giòn chuyển sắc vàng óng ánh và nổ giòn rụm. Lắng nghe tiếng xèo giòn rộn rã và hương thơm phức lan tỏa khắp bếp thì gắp ra vỉ thưa cho ráo dầu thừa.',4,'Đặt đồ chiên nướng lên giá inox thoáng khí thay vì giấy thấm dầu chồng khít để hơi nước thoát hết, giữ độ giòn lâu gấp 3 lần.'),
(72,7,'Trình bày bắt mắt kèm rau thơm & thưởng thức nóng','Xếp thành phẩm vàng giòn ra đĩa lớn có bày sẵn rau củ ăn kèm và điểm xuyết hành ngò và tiêu xay tươi xanh hài hòa màu sắc. Dọn kèm chén nước chấm sánh đậm ngay chính giữa mâm ăn cho 4 người thưởng thức khi vỏ ngoài còn nóng giòn rụm. Tăng dầu lên 180°C, chiên lại 2–3 phút đến vàng giòn. Để ráo, rắc muối ngay; dùng với tương cà nếu thích.',3,'Cắt miếng hoặc dọn ăn ngay trong vòng 10 phút sau khi rời bếp để cảm nhận trọn vẹn sự đối lập giòn ngoài - mềm ngọt bên trong.'),
(73,1,'Sơ chế sạch & thấm thật khô bề mặt nguyên liệu','Rửa sạch 500g đậu hũ cùng chút muối loãng để khử mùi tự nhiên, sau đó dùng khăn giấy bếp thấm thật khô ráo hoàn toàn bề mặt. Khứa nhẹ các đường chéo hoặc cắt miếng vừa ăn dày 2–3cm để nhiệt và gia vị thấm sâu đều khắp bên trong. Thấm đậu hũ và ép nhẹ 10 phút để ráo nước; cắt miếng vuông dày 2 cm.',4,'Bề mặt nguyên liệu càng khô ráo thì khi chiên không bị văng dầu và khi nướng sẽ lên màu vàng ruộm giòn rụm cực đẹp.'),
(73,2,'Chuẩn bị hỗn hợp sốt ướp / bột áo chuẩn tỷ lệ','Phối trộn 2 cây sả và 10g tỏi băm thật nhuyễn (hoặc vắt lấy nước cốt thơm) cùng 18ml nước tương, 5g đường và 1 quả ớt trong tô lớn cho quyện sánh đồng nhất. Nếu món có lớp vỏ bột hoặc bánh cuốn từ 500g đậu hũ, trộn đều hỗn hợp theo đúng định lượng để đạt độ giòn xốp mỏng nhẹ chuẩn vị. Đun dầu vừa nóng, thả đậu từng mẻ và chiên đến vàng các mặt. Vớt ra giấy thấm hoặc giá.',4,'Vắt lấy nước cốt hành tỏi sả khi ướp đồ nướng giúp hương thơm thấm sâu mà không bị cháy đen phần xác băm trên lửa cao.'),
(73,3,'Ướp thấm thớ thịt / tạo hình cuốn khéo léo','Áo đều hỗn hợp gia vị hoặc lớp bột/vỏ cuốn quanh 500g đậu hũ, massage nhẹ nhàng rồi để nghỉ 15–20 phút cho gia vị thẩm thấu trọn vẹn. Trường hợp cuốn chả/nem hoặc đổ khuôn bánh, thao tác đều tay vừa chặt để nhân kết dính nhưng không bị bục rách khi gặp nhiệt.',5,'Để nguyên liệu nghỉ đủ thời gian trước khi chiên nướng giúp lớp áo bột bám chắc và phần nhân bên trong mọng ngọt.'),
(73,4,'Pha nước chấm cân vị & sơ chế rau đồ chua ăn kèm','Nhặt rửa sạch rau củ ăn kèm ngâm nước mát cho giòn tươi, bào sợi hoặc thái lát gọn gàng bày sẵn bên cạnh. Pha chén nước chấm chua ngọt hoặc muối ớt chanh sả sánh thơm theo khẩu vị vùng miền của món Đậu hũ chiên sả để cân bằng độ béo giòn.',3,'Luôn chuẩn bị xong rau sống và bát nước chấm trước khi chiên/nướng mẻ cuối để món ăn vừa ra lò là thưởng thức nóng giòn ngay.'),
(73,5,'Làm nóng dầu / lò nướng chuẩn nhiệt & làm chín đều lần 1','Làm nóng chảo dầu hoặc vỉ nướng/nồi chiên ở mức nhiệt vừa khoảng 165–175°C, xếp 500g đậu hũ vào với khoảng cách thoáng đều nhau. Chiên hoặc nướng trở mặt nhịp nhàng trên lửa vừa để nhiệt dẫn sâu làm chín mềm ngọt hoàn toàn phần nhân bên trong. Chắt dầu, chừa 1 thìa. Phi sả và tỏi băm ở lửa nhỏ đến thơm vàng; thêm nước tương, đường và 20 ml nước.',6,'Kiểm tra nhiệt dầu bằng đầu đũa tre thấy sủi tăm nhỏ đều là đạt chuẩn 170°C, giúp vỏ không cháy sớm khi bên trong còn sống.');
INSERT INTO `recipe_steps` (`recipe_id`,`step_order`,`title`,`instruction`,`duration_mins`,`tip_note`) VALUES
(73,6,'Tăng nhiệt khóa giòn rụm vàng ươm bề mặt lần 2','Ở 2–3 phút cuối, tăng lên lửa vừa lớn (khoảng 190°C) hoặc phết thêm lớp dầu điều/mật ong mỏng để vỏ ngoài của Đậu hũ chiên sả chuyển sắc vàng óng ánh và nổ giòn rụm. Lắng nghe tiếng xèo giòn rộn rã và hương thơm phức lan tỏa khắp bếp thì gắp ra vỉ thưa cho ráo dầu thừa.',3,'Đặt đồ chiên nướng lên giá inox thoáng khí thay vì giấy thấm dầu chồng khít để hơi nước thoát hết, giữ độ giòn lâu gấp 3 lần.'),
(73,7,'Trình bày bắt mắt kèm rau thơm & thưởng thức nóng','Xếp thành phẩm vàng giòn ra đĩa lớn có bày sẵn rau củ ăn kèm và điểm xuyết hành ngò và tiêu xay tươi xanh hài hòa màu sắc. Dọn kèm chén nước chấm sánh đậm ngay chính giữa mâm ăn cho 4 người thưởng thức khi vỏ ngoài còn nóng giòn rụm. Cho đậu vào chảo, đảo nhẹ đến khi gia vị bám đều và cạn. Thêm ớt nếu dùng, dọn khi còn giòn.',2,'Cắt miếng hoặc dọn ăn ngay trong vòng 10 phút sau khi rời bếp để cảm nhận trọn vẹn sự đối lập giòn ngoài - mềm ngọt bên trong.'),
(74,1,'Sơ chế sạch & thấm thật khô bề mặt nguyên liệu','Rửa sạch 600g tôm sú cùng chút muối loãng để khử mùi tự nhiên, sau đó dùng khăn giấy bếp thấm thật khô ráo hoàn toàn bề mặt. Khứa nhẹ các đường chéo hoặc cắt miếng vừa ăn dày 2–3cm để nhiệt và gia vị thấm sâu đều khắp bên trong. Rửa tôm, cắt râu và rạch nhẹ lưng rút chỉ đen; để nguyên vỏ để tôm không khô khi nướng.',4,'Bề mặt nguyên liệu càng khô ráo thì khi chiên không bị văng dầu và khi nướng sẽ lên màu vàng ruộm giòn rụm cực đẹp.'),
(74,2,'Chuẩn bị hỗn hợp sốt ướp / bột áo chuẩn tỷ lệ','Phối trộn 10g tỏi băm thật nhuyễn (hoặc vắt lấy nước cốt thơm) cùng 5g muối, 2 quả ớt, 1 quả chanh và 4g đường trong tô lớn cho quyện sánh đồng nhất. Nếu món có lớp vỏ bột hoặc bánh cuốn từ 600g tôm sú, trộn đều hỗn hợp theo đúng định lượng để đạt độ giòn xốp mỏng nhẹ chuẩn vị. Giã muối, ớt, tỏi và đường; trộn với dầu ăn. Ướp tôm với hai phần ba hỗn hợp trong 10 phút.',4,'Vắt lấy nước cốt hành tỏi sả khi ướp đồ nướng giúp hương thơm thấm sâu mà không bị cháy đen phần xác băm trên lửa cao.'),
(74,3,'Ướp thấm thớ thịt / tạo hình cuốn khéo léo','Áo đều hỗn hợp gia vị hoặc lớp bột/vỏ cuốn quanh 600g tôm sú, massage nhẹ nhàng rồi để nghỉ 15–20 phút cho gia vị thẩm thấu trọn vẹn. Trường hợp cuốn chả/nem hoặc đổ khuôn bánh, thao tác đều tay vừa chặt để nhân kết dính nhưng không bị bục rách khi gặp nhiệt.',4,'Để nguyên liệu nghỉ đủ thời gian trước khi chiên nướng giúp lớp áo bột bám chắc và phần nhân bên trong mọng ngọt.'),
(74,4,'Pha nước chấm cân vị & sơ chế rau đồ chua ăn kèm','Nhặt rửa sạch rau củ ăn kèm ngâm nước mát cho giòn tươi, bào sợi hoặc thái lát gọn gàng bày sẵn bên cạnh. Pha chén nước chấm chua ngọt hoặc muối ớt chanh sả sánh thơm theo khẩu vị vùng miền của món Tôm nướng muối ớt để cân bằng độ béo giòn.',3,'Luôn chuẩn bị xong rau sống và bát nước chấm trước khi chiên/nướng mẻ cuối để món ăn vừa ra lò là thưởng thức nóng giòn ngay.'),
(74,5,'Làm nóng dầu / lò nướng chuẩn nhiệt & làm chín đều lần 1','Làm nóng chảo dầu hoặc vỉ nướng/nồi chiên ở mức nhiệt vừa khoảng 165–175°C, xếp 600g tôm sú vào với khoảng cách thoáng đều nhau. Chiên hoặc nướng trở mặt nhịp nhàng trên lửa vừa để nhiệt dẫn sâu làm chín mềm ngọt hoàn toàn phần nhân bên trong. Nướng vỉ than hoặc lò 200°C khoảng 5–7 phút, trở một lần và phết phần sốt còn lại. Không nướng lâu làm tôm dai.',5,'Kiểm tra nhiệt dầu bằng đầu đũa tre thấy sủi tăm nhỏ đều là đạt chuẩn 170°C, giúp vỏ không cháy sớm khi bên trong còn sống.'),
(74,6,'Tăng nhiệt khóa giòn rụm vàng ươm bề mặt lần 2','Ở 2–3 phút cuối, tăng lên lửa vừa lớn (khoảng 190°C) hoặc phết thêm lớp dầu điều/mật ong mỏng để vỏ ngoài của Tôm nướng muối ớt chuyển sắc vàng óng ánh và nổ giòn rụm. Lắng nghe tiếng xèo giòn rộn rã và hương thơm phức lan tỏa khắp bếp thì gắp ra vỉ thưa cho ráo dầu thừa.',3,'Đặt đồ chiên nướng lên giá inox thoáng khí thay vì giấy thấm dầu chồng khít để hơi nước thoát hết, giữ độ giòn lâu gấp 3 lần.'),
(74,7,'Trình bày bắt mắt kèm rau thơm & thưởng thức nóng','Xếp thành phẩm vàng giòn ra đĩa lớn có bày sẵn rau củ ăn kèm và điểm xuyết hành ngò và tiêu xay tươi xanh hài hòa màu sắc. Dọn kèm chén nước chấm sánh đậm ngay chính giữa mâm ăn cho 4 người thưởng thức khi vỏ ngoài còn nóng giòn rụm. Tôm chín khi thịt trắng đục, vỏ chuyển đỏ đều. Vắt chanh khi ăn; rửa sạch dụng cụ từng tiếp xúc tôm sống.',2,'Cắt miếng hoặc dọn ăn ngay trong vòng 10 phút sau khi rời bếp để cảm nhận trọn vẹn sự đối lập giòn ngoài - mềm ngọt bên trong.'),
(75,1,'Sơ chế sạch & thấm thật khô bề mặt nguyên liệu','Rửa sạch 600g mực ống cùng chút muối loãng để khử mùi tự nhiên, sau đó dùng khăn giấy bếp thấm thật khô ráo hoàn toàn bề mặt. Khứa nhẹ các đường chéo hoặc cắt miếng vừa ăn dày 2–3cm để nhiệt và gia vị thấm sâu đều khắp bên trong. Rửa mực, bỏ mai và nội tạng, để nguyên thân hoặc cắt miếng lớn. Khía nhẹ mặt trong để mực dễ thấm.',4,'Bề mặt nguyên liệu càng khô ráo thì khi chiên không bị văng dầu và khi nướng sẽ lên màu vàng ruộm giòn rụm cực đẹp.'),
(75,2,'Chuẩn bị hỗn hợp sốt ướp / bột áo chuẩn tỷ lệ','Phối trộn 1 cây sả và 10g tỏi băm thật nhuyễn (hoặc vắt lấy nước cốt thơm) cùng 25g sa tế, 12ml nước mắm, 10ml mật ong và 1 quả chanh trong tô lớn cho quyện sánh đồng nhất. Nếu món có lớp vỏ bột hoặc bánh cuốn từ 600g mực ống, trộn đều hỗn hợp theo đúng định lượng để đạt độ giòn xốp mỏng nhẹ chuẩn vị. Trộn sa tế, sả tỏi băm, nước mắm, mật ong và dầu. Chia sốt làm đôi, giữ riêng một nửa sạch; dùng phần còn lại ướp mực 15 phút.',4,'Vắt lấy nước cốt hành tỏi sả khi ướp đồ nướng giúp hương thơm thấm sâu mà không bị cháy đen phần xác băm trên lửa cao.'),
(75,3,'Ướp thấm thớ thịt / tạo hình cuốn khéo léo','Áo đều hỗn hợp gia vị hoặc lớp bột/vỏ cuốn quanh 600g mực ống, massage nhẹ nhàng rồi để nghỉ 15–20 phút cho gia vị thẩm thấu trọn vẹn. Trường hợp cuốn chả/nem hoặc đổ khuôn bánh, thao tác đều tay vừa chặt để nhân kết dính nhưng không bị bục rách khi gặp nhiệt.',5,'Để nguyên liệu nghỉ đủ thời gian trước khi chiên nướng giúp lớp áo bột bám chắc và phần nhân bên trong mọng ngọt.'),
(75,4,'Pha nước chấm cân vị & sơ chế rau đồ chua ăn kèm','Nhặt rửa sạch rau củ ăn kèm ngâm nước mát cho giòn tươi, bào sợi hoặc thái lát gọn gàng bày sẵn bên cạnh. Pha chén nước chấm chua ngọt hoặc muối ớt chanh sả sánh thơm theo khẩu vị vùng miền của món Mực nướng sa tế để cân bằng độ béo giòn.',3,'Luôn chuẩn bị xong rau sống và bát nước chấm trước khi chiên/nướng mẻ cuối để món ăn vừa ra lò là thưởng thức nóng giòn ngay.'),
(75,5,'Làm nóng dầu / lò nướng chuẩn nhiệt & làm chín đều lần 1','Làm nóng chảo dầu hoặc vỉ nướng/nồi chiên ở mức nhiệt vừa khoảng 165–175°C, xếp 600g mực ống vào với khoảng cách thoáng đều nhau. Chiên hoặc nướng trở mặt nhịp nhàng trên lửa vừa để nhiệt dẫn sâu làm chín mềm ngọt hoàn toàn phần nhân bên trong. Nướng vỉ nóng hoặc lò 220°C khoảng 8–10 phút, trở một lần; chỉ phết phần sốt để riêng, không dùng lại sốt đã chạm mực sống.',6,'Kiểm tra nhiệt dầu bằng đầu đũa tre thấy sủi tăm nhỏ đều là đạt chuẩn 170°C, giúp vỏ không cháy sớm khi bên trong còn sống.'),
(75,6,'Tăng nhiệt khóa giòn rụm vàng ươm bề mặt lần 2','Ở 2–3 phút cuối, tăng lên lửa vừa lớn (khoảng 190°C) hoặc phết thêm lớp dầu điều/mật ong mỏng để vỏ ngoài của Mực nướng sa tế chuyển sắc vàng óng ánh và nổ giòn rụm. Lắng nghe tiếng xèo giòn rộn rã và hương thơm phức lan tỏa khắp bếp thì gắp ra vỉ thưa cho ráo dầu thừa.',3,'Đặt đồ chiên nướng lên giá inox thoáng khí thay vì giấy thấm dầu chồng khít để hơi nước thoát hết, giữ độ giòn lâu gấp 3 lần.'),
(75,7,'Trình bày bắt mắt kèm rau thơm & thưởng thức nóng','Xếp thành phẩm vàng giòn ra đĩa lớn có bày sẵn rau củ ăn kèm và điểm xuyết hành ngò và tiêu xay tươi xanh hài hòa màu sắc. Dọn kèm chén nước chấm sánh đậm ngay chính giữa mâm ăn cho 4 người thưởng thức khi vỏ ngoài còn nóng giòn rụm. Mực vừa săn, chuyển đục và cong nhẹ là chín; tránh nướng kéo dài làm dai. Cắt khoanh, ăn với chanh nếu thích.',2,'Cắt miếng hoặc dọn ăn ngay trong vòng 10 phút sau khi rời bếp để cảm nhận trọn vẹn sự đối lập giòn ngoài - mềm ngọt bên trong.'),
(76,1,'Sơ chế sạch & thấm thật khô bề mặt nguyên liệu','Rửa sạch 1 con cá diêu hồng và 150g cà chua cùng chút muối loãng để khử mùi tự nhiên, sau đó dùng khăn giấy bếp thấm thật khô ráo hoàn toàn bề mặt. Khứa nhẹ các đường chéo hoặc cắt miếng vừa ăn dày 2–3cm để nhiệt và gia vị thấm sâu đều khắp bên trong. Làm sạch cá, khứa hai bên và thấm khô. Thái gừng sợi, hành khúc, cà chua lát; nêm cá với nước mắm và tiêu.',8,'Bề mặt nguyên liệu càng khô ráo thì khi chiên không bị văng dầu và khi nướng sẽ lên màu vàng ruộm giòn rụm cực đẹp.'),
(76,2,'Chuẩn bị hỗn hợp sốt ướp / bột áo chuẩn tỷ lệ','Phối trộn 25g gừng băm thật nhuyễn (hoặc vắt lấy nước cốt thơm) cùng 18ml nước mắm và 2g tiêu trong tô lớn cho quyện sánh đồng nhất. Nếu món có lớp vỏ bột hoặc bánh cuốn từ 1 con cá diêu hồng và 150g cà chua, trộn đều hỗn hợp theo đúng định lượng để đạt độ giòn xốp mỏng nhẹ chuẩn vị. Lót giấy bạc hai lớp, đặt cá cùng gừng, hành và cà chua lên giữa. Rưới dầu, gấp mép kín nhưng chừa khoảng phồng.',7,'Vắt lấy nước cốt hành tỏi sả khi ướp đồ nướng giúp hương thơm thấm sâu mà không bị cháy đen phần xác băm trên lửa cao.'),
(76,3,'Ướp thấm thớ thịt / tạo hình cuốn khéo léo','Áo đều hỗn hợp gia vị hoặc lớp bột/vỏ cuốn quanh 1 con cá diêu hồng và 150g cà chua, massage nhẹ nhàng rồi để nghỉ 15–20 phút cho gia vị thẩm thấu trọn vẹn. Trường hợp cuốn chả/nem hoặc đổ khuôn bánh, thao tác đều tay vừa chặt để nhân kết dính nhưng không bị bục rách khi gặp nhiệt.',9,'Để nguyên liệu nghỉ đủ thời gian trước khi chiên nướng giúp lớp áo bột bám chắc và phần nhân bên trong mọng ngọt.'),
(76,4,'Pha nước chấm cân vị & sơ chế rau đồ chua ăn kèm','Nhặt rửa sạch rau củ ăn kèm ngâm nước mát cho giòn tươi, bào sợi hoặc thái lát gọn gàng bày sẵn bên cạnh. Pha chén nước chấm chua ngọt hoặc muối ớt chanh sả sánh thơm theo khẩu vị vùng miền của món Cá nướng giấy bạc để cân bằng độ béo giòn.',6,'Luôn chuẩn bị xong rau sống và bát nước chấm trước khi chiên/nướng mẻ cuối để món ăn vừa ra lò là thưởng thức nóng giòn ngay.'),
(76,5,'Làm nóng dầu / lò nướng chuẩn nhiệt & làm chín đều lần 1','Làm nóng chảo dầu hoặc vỉ nướng/nồi chiên ở mức nhiệt vừa khoảng 165–175°C, xếp 1 con cá diêu hồng và 150g cà chua vào với khoảng cách thoáng đều nhau. Chiên hoặc nướng trở mặt nhịp nhàng trên lửa vừa để nhiệt dẫn sâu làm chín mềm ngọt hoàn toàn phần nhân bên trong. Làm nóng lò 200°C, nướng cá 25–30 phút tùy kích thước. Đặt gói cá lên khay để hứng nước rỉ.',10,'Kiểm tra nhiệt dầu bằng đầu đũa tre thấy sủi tăm nhỏ đều là đạt chuẩn 170°C, giúp vỏ không cháy sớm khi bên trong còn sống.'),
(76,6,'Tăng nhiệt khóa giòn rụm vàng ươm bề mặt lần 2','Ở 2–3 phút cuối, tăng lên lửa vừa lớn (khoảng 190°C) hoặc phết thêm lớp dầu điều/mật ong mỏng để vỏ ngoài của Cá nướng giấy bạc chuyển sắc vàng óng ánh và nổ giòn rụm. Lắng nghe tiếng xèo giòn rộn rã và hương thơm phức lan tỏa khắp bếp thì gắp ra vỉ thưa cho ráo dầu thừa.',6,'Đặt đồ chiên nướng lên giá inox thoáng khí thay vì giấy thấm dầu chồng khít để hơi nước thoát hết, giữ độ giòn lâu gấp 3 lần.'),
(76,7,'Trình bày bắt mắt kèm rau thơm & thưởng thức nóng','Xếp thành phẩm vàng giòn ra đĩa lớn có bày sẵn rau củ ăn kèm và điểm xuyết 30g hành lá tươi xanh hài hòa màu sắc. Dọn kèm chén nước chấm sánh đậm ngay chính giữa mâm ăn cho 4 người thưởng thức khi vỏ ngoài còn nóng giòn rụm. Mở gói cẩn thận tránh hơi nóng. Cá chín khi thịt đục trắng và tách dễ; nếu chưa, gói lại nướng thêm 5 phút.',4,'Cắt miếng hoặc dọn ăn ngay trong vòng 10 phút sau khi rời bếp để cảm nhận trọn vẹn sự đối lập giòn ngoài - mềm ngọt bên trong.'),
(77,1,'Sơ chế sạch & thấm thật khô bề mặt nguyên liệu','Rửa sạch 450g khoai lang và 100g bột mì cùng chút muối loãng để khử mùi tự nhiên, sau đó dùng khăn giấy bếp thấm thật khô ráo hoàn toàn bề mặt. Khứa nhẹ các đường chéo hoặc cắt miếng vừa ăn dày 2–3cm để nhiệt và gia vị thấm sâu đều khắp bên trong. Gọt khoai, rửa và bào sợi dài. Ngâm nước 5 phút rồi để ráo thật kỹ để bột bám tốt.',5,'Bề mặt nguyên liệu càng khô ráo thì khi chiên không bị văng dầu và khi nướng sẽ lên màu vàng ruộm giòn rụm cực đẹp.'),
(77,2,'Chuẩn bị hỗn hợp sốt ướp / bột áo chuẩn tỷ lệ','Phối trộn hành tím và tỏi băm nhỏ băm thật nhuyễn (hoặc vắt lấy nước cốt thơm) cùng 20g đường và 2g muối trong tô lớn cho quyện sánh đồng nhất. Nếu món có lớp vỏ bột hoặc bánh cuốn từ 450g khoai lang và 100g bột mì, trộn đều hỗn hợp theo đúng định lượng để đạt độ giòn xốp mỏng nhẹ chuẩn vị. Trộn bột mì, bột gạo, đường, muối và nước thành hỗn hợp sệt vừa phủ khoai; để bột nghỉ 10 phút.',5,'Vắt lấy nước cốt hành tỏi sả khi ướp đồ nướng giúp hương thơm thấm sâu mà không bị cháy đen phần xác băm trên lửa cao.');
INSERT INTO `recipe_steps` (`recipe_id`,`step_order`,`title`,`instruction`,`duration_mins`,`tip_note`) VALUES
(77,3,'Ướp thấm thớ thịt / tạo hình cuốn khéo léo','Áo đều hỗn hợp gia vị hoặc lớp bột/vỏ cuốn quanh 450g khoai lang và 100g bột mì, massage nhẹ nhàng rồi để nghỉ 15–20 phút cho gia vị thẩm thấu trọn vẹn. Trường hợp cuốn chả/nem hoặc đổ khuôn bánh, thao tác đều tay vừa chặt để nhân kết dính nhưng không bị bục rách khi gặp nhiệt.',6,'Để nguyên liệu nghỉ đủ thời gian trước khi chiên nướng giúp lớp áo bột bám chắc và phần nhân bên trong mọng ngọt.'),
(77,4,'Pha nước chấm cân vị & sơ chế rau đồ chua ăn kèm','Nhặt rửa sạch rau củ ăn kèm ngâm nước mát cho giòn tươi, bào sợi hoặc thái lát gọn gàng bày sẵn bên cạnh. Pha chén nước chấm chua ngọt hoặc muối ớt chanh sả sánh thơm theo khẩu vị vùng miền của món Bánh khoai lang chiên để cân bằng độ béo giòn.',4,'Luôn chuẩn bị xong rau sống và bát nước chấm trước khi chiên/nướng mẻ cuối để món ăn vừa ra lò là thưởng thức nóng giòn ngay.'),
(77,5,'Làm nóng dầu / lò nướng chuẩn nhiệt & làm chín đều lần 1','Làm nóng chảo dầu hoặc vỉ nướng/nồi chiên ở mức nhiệt vừa khoảng 165–175°C, xếp 450g khoai lang và 100g bột mì vào với khoảng cách thoáng đều nhau. Chiên hoặc nướng trở mặt nhịp nhàng trên lửa vừa để nhiệt dẫn sâu làm chín mềm ngọt hoàn toàn phần nhân bên trong. Trộn khoai vào bột, múc từng phần nhỏ lên muôi hoặc vá. Không nén quá chặt để bánh có khe thoát hơi.',8,'Kiểm tra nhiệt dầu bằng đầu đũa tre thấy sủi tăm nhỏ đều là đạt chuẩn 170°C, giúp vỏ không cháy sớm khi bên trong còn sống.'),
(77,6,'Tăng nhiệt khóa giòn rụm vàng ươm bề mặt lần 2','Ở 2–3 phút cuối, tăng lên lửa vừa lớn (khoảng 190°C) hoặc phết thêm lớp dầu điều/mật ong mỏng để vỏ ngoài của Bánh khoai lang chiên chuyển sắc vàng óng ánh và nổ giòn rụm. Lắng nghe tiếng xèo giòn rộn rã và hương thơm phức lan tỏa khắp bếp thì gắp ra vỉ thưa cho ráo dầu thừa.',4,'Đặt đồ chiên nướng lên giá inox thoáng khí thay vì giấy thấm dầu chồng khít để hơi nước thoát hết, giữ độ giòn lâu gấp 3 lần.'),
(77,7,'Trình bày bắt mắt kèm rau thơm & thưởng thức nóng','Xếp thành phẩm vàng giòn ra đĩa lớn có bày sẵn rau củ ăn kèm và điểm xuyết 10g mè rang tươi xanh hài hòa màu sắc. Dọn kèm chén nước chấm sánh đậm ngay chính giữa mâm ăn cho 4 người thưởng thức khi vỏ ngoài còn nóng giòn rụm. Chiên ở 170°C khoảng 3–4 phút mỗi mặt đến vàng đều; để ráo trên giá. Rắc mè nếu dùng và ăn khi còn nóng.',3,'Cắt miếng hoặc dọn ăn ngay trong vòng 10 phút sau khi rời bếp để cảm nhận trọn vẹn sự đối lập giòn ngoài - mềm ngọt bên trong.'),
(78,1,'Sơ chế sạch & thấm thật khô bề mặt nguyên liệu','Rửa sạch 500g chả cá thác lác và 10g bột bắp cùng chút muối loãng để khử mùi tự nhiên, sau đó dùng khăn giấy bếp thấm thật khô ráo hoàn toàn bề mặt. Khứa nhẹ các đường chéo hoặc cắt miếng vừa ăn dày 2–3cm để nhiệt và gia vị thấm sâu đều khắp bên trong. Thấm khô thì là, thái nhỏ. Trộn chả cá lạnh với thì là, hành tím băm, nước mắm và tiêu; quết một chiều 3 phút.',4,'Bề mặt nguyên liệu càng khô ráo thì khi chiên không bị văng dầu và khi nướng sẽ lên màu vàng ruộm giòn rụm cực đẹp.'),
(78,2,'Chuẩn bị hỗn hợp sốt ướp / bột áo chuẩn tỷ lệ','Phối trộn 15g hành tím băm thật nhuyễn (hoặc vắt lấy nước cốt thơm) cùng 12ml nước mắm và 2g tiêu trong tô lớn cho quyện sánh đồng nhất. Nếu món có lớp vỏ bột hoặc bánh cuốn từ 500g chả cá thác lác và 10g bột bắp, trộn đều hỗn hợp theo đúng định lượng để đạt độ giòn xốp mỏng nhẹ chuẩn vị. Thoa chút dầu lên tay, nặn chả thành miếng dẹt dày khoảng 1,5 cm. Rắc bột bắp mỏng nếu hỗn hợp quá ướt.',4,'Vắt lấy nước cốt hành tỏi sả khi ướp đồ nướng giúp hương thơm thấm sâu mà không bị cháy đen phần xác băm trên lửa cao.'),
(78,3,'Ướp thấm thớ thịt / tạo hình cuốn khéo léo','Áo đều hỗn hợp gia vị hoặc lớp bột/vỏ cuốn quanh 500g chả cá thác lác và 10g bột bắp, massage nhẹ nhàng rồi để nghỉ 15–20 phút cho gia vị thẩm thấu trọn vẹn. Trường hợp cuốn chả/nem hoặc đổ khuôn bánh, thao tác đều tay vừa chặt để nhân kết dính nhưng không bị bục rách khi gặp nhiệt.',5,'Để nguyên liệu nghỉ đủ thời gian trước khi chiên nướng giúp lớp áo bột bám chắc và phần nhân bên trong mọng ngọt.'),
(78,4,'Pha nước chấm cân vị & sơ chế rau đồ chua ăn kèm','Nhặt rửa sạch rau củ ăn kèm ngâm nước mát cho giòn tươi, bào sợi hoặc thái lát gọn gàng bày sẵn bên cạnh. Pha chén nước chấm chua ngọt hoặc muối ớt chanh sả sánh thơm theo khẩu vị vùng miền của món Chả cá thác lác chiên thì là để cân bằng độ béo giòn.',4,'Luôn chuẩn bị xong rau sống và bát nước chấm trước khi chiên/nướng mẻ cuối để món ăn vừa ra lò là thưởng thức nóng giòn ngay.'),
(78,5,'Làm nóng dầu / lò nướng chuẩn nhiệt & làm chín đều lần 1','Làm nóng chảo dầu hoặc vỉ nướng/nồi chiên ở mức nhiệt vừa khoảng 165–175°C, xếp 500g chả cá thác lác và 10g bột bắp vào với khoảng cách thoáng đều nhau. Chiên hoặc nướng trở mặt nhịp nhàng trên lửa vừa để nhiệt dẫn sâu làm chín mềm ngọt hoàn toàn phần nhân bên trong. Đun dầu ở lửa vừa, chiên từng mẻ 3–4 phút mỗi mặt đến vàng nâu. Giữ lửa vừa để phần giữa kịp chín.',8,'Kiểm tra nhiệt dầu bằng đầu đũa tre thấy sủi tăm nhỏ đều là đạt chuẩn 170°C, giúp vỏ không cháy sớm khi bên trong còn sống.'),
(78,6,'Tăng nhiệt khóa giòn rụm vàng ươm bề mặt lần 2','Ở 2–3 phút cuối, tăng lên lửa vừa lớn (khoảng 190°C) hoặc phết thêm lớp dầu điều/mật ong mỏng để vỏ ngoài của Chả cá thác lác chiên thì là chuyển sắc vàng óng ánh và nổ giòn rụm. Lắng nghe tiếng xèo giòn rộn rã và hương thơm phức lan tỏa khắp bếp thì gắp ra vỉ thưa cho ráo dầu thừa.',3,'Đặt đồ chiên nướng lên giá inox thoáng khí thay vì giấy thấm dầu chồng khít để hơi nước thoát hết, giữ độ giòn lâu gấp 3 lần.'),
(78,7,'Trình bày bắt mắt kèm rau thơm & thưởng thức nóng','Xếp thành phẩm vàng giòn ra đĩa lớn có bày sẵn rau củ ăn kèm và điểm xuyết 25g thì là tươi xanh hài hòa màu sắc. Dọn kèm chén nước chấm sánh đậm ngay chính giữa mâm ăn cho 4 người thưởng thức khi vỏ ngoài còn nóng giòn rụm. Bẻ thử một miếng dày nhất, ruột phải nóng và chín đều. Để ráo dầu, ăn với cơm hoặc rau sống.',2,'Cắt miếng hoặc dọn ăn ngay trong vòng 10 phút sau khi rời bếp để cảm nhận trọn vẹn sự đối lập giòn ngoài - mềm ngọt bên trong.'),
(79,1,'Sơ chế sạch & thấm thật khô bề mặt nguyên liệu','Rửa sạch 800g thịt gà (đùi) cùng chút muối loãng để khử mùi tự nhiên, sau đó dùng khăn giấy bếp thấm thật khô ráo hoàn toàn bề mặt. Khứa nhẹ các đường chéo hoặc cắt miếng vừa ăn dày 2–3cm để nhiệt và gia vị thấm sâu đều khắp bên trong. Khứa nhẹ phần đùi dày, thấm khô. Trộn mật ong, nước tương, tỏi băm, dầu, tiêu và chút muối; ướp 30 phút.',8,'Bề mặt nguyên liệu càng khô ráo thì khi chiên không bị văng dầu và khi nướng sẽ lên màu vàng ruộm giòn rụm cực đẹp.'),
(79,2,'Chuẩn bị hỗn hợp sốt ướp / bột áo chuẩn tỷ lệ','Phối trộn 15g tỏi băm thật nhuyễn (hoặc vắt lấy nước cốt thơm) cùng 30ml mật ong, 25ml nước tương, 1 quả chanh và 2g tiêu trong tô lớn cho quyện sánh đồng nhất. Nếu món có lớp vỏ bột hoặc bánh cuốn từ 800g thịt gà (đùi), trộn đều hỗn hợp theo đúng định lượng để đạt độ giòn xốp mỏng nhẹ chuẩn vị. Làm nóng lò ở 200°C. Xếp gà lên vỉ, đặt khay hứng phía dưới; giữ lại phần sốt chưa tiếp xúc thịt sống để phết.',8,'Vắt lấy nước cốt hành tỏi sả khi ướp đồ nướng giúp hương thơm thấm sâu mà không bị cháy đen phần xác băm trên lửa cao.'),
(79,3,'Ướp thấm thớ thịt / tạo hình cuốn khéo léo','Áo đều hỗn hợp gia vị hoặc lớp bột/vỏ cuốn quanh 800g thịt gà (đùi), massage nhẹ nhàng rồi để nghỉ 15–20 phút cho gia vị thẩm thấu trọn vẹn. Trường hợp cuốn chả/nem hoặc đổ khuôn bánh, thao tác đều tay vừa chặt để nhân kết dính nhưng không bị bục rách khi gặp nhiệt.',10,'Để nguyên liệu nghỉ đủ thời gian trước khi chiên nướng giúp lớp áo bột bám chắc và phần nhân bên trong mọng ngọt.'),
(79,4,'Pha nước chấm cân vị & sơ chế rau đồ chua ăn kèm','Nhặt rửa sạch rau củ ăn kèm ngâm nước mát cho giòn tươi, bào sợi hoặc thái lát gọn gàng bày sẵn bên cạnh. Pha chén nước chấm chua ngọt hoặc muối ớt chanh sả sánh thơm theo khẩu vị vùng miền của món Gà nướng mật ong để cân bằng độ béo giòn.',7,'Luôn chuẩn bị xong rau sống và bát nước chấm trước khi chiên/nướng mẻ cuối để món ăn vừa ra lò là thưởng thức nóng giòn ngay.'),
(79,5,'Làm nóng dầu / lò nướng chuẩn nhiệt & làm chín đều lần 1','Làm nóng chảo dầu hoặc vỉ nướng/nồi chiên ở mức nhiệt vừa khoảng 165–175°C, xếp 800g thịt gà (đùi) vào với khoảng cách thoáng đều nhau. Chiên hoặc nướng trở mặt nhịp nhàng trên lửa vừa để nhiệt dẫn sâu làm chín mềm ngọt hoàn toàn phần nhân bên trong. Nướng 25 phút, lật gà và phết sốt đã đun sôi; nướng thêm 10 phút hoặc đến khi phần dày nhất đạt 74°C.',12,'Kiểm tra nhiệt dầu bằng đầu đũa tre thấy sủi tăm nhỏ đều là đạt chuẩn 170°C, giúp vỏ không cháy sớm khi bên trong còn sống.'),
(79,6,'Tăng nhiệt khóa giòn rụm vàng ươm bề mặt lần 2','Ở 2–3 phút cuối, tăng lên lửa vừa lớn (khoảng 190°C) hoặc phết thêm lớp dầu điều/mật ong mỏng để vỏ ngoài của Gà nướng mật ong chuyển sắc vàng óng ánh và nổ giòn rụm. Lắng nghe tiếng xèo giòn rộn rã và hương thơm phức lan tỏa khắp bếp thì gắp ra vỉ thưa cho ráo dầu thừa.',6,'Đặt đồ chiên nướng lên giá inox thoáng khí thay vì giấy thấm dầu chồng khít để hơi nước thoát hết, giữ độ giòn lâu gấp 3 lần.'),
(79,7,'Trình bày bắt mắt kèm rau thơm & thưởng thức nóng','Xếp thành phẩm vàng giòn ra đĩa lớn có bày sẵn rau củ ăn kèm và điểm xuyết hành ngò và tiêu xay tươi xanh hài hòa màu sắc. Dọn kèm chén nước chấm sánh đậm ngay chính giữa mâm ăn cho 4 người thưởng thức khi vỏ ngoài còn nóng giòn rụm. Tăng nhiệt trên hoặc nướng thêm 2–3 phút để da vàng, canh sát vì mật ong dễ cháy. Để nghỉ 5 phút, dùng cùng chanh.',4,'Cắt miếng hoặc dọn ăn ngay trong vòng 10 phút sau khi rời bếp để cảm nhận trọn vẹn sự đối lập giòn ngoài - mềm ngọt bên trong.'),
(80,1,'Sơ chế sạch & thấm thật khô bề mặt nguyên liệu','Rửa sạch 700g đùi gà và 100g bột mì cùng chút muối loãng để khử mùi tự nhiên, sau đó dùng khăn giấy bếp thấm thật khô ráo hoàn toàn bề mặt. Khứa nhẹ các đường chéo hoặc cắt miếng vừa ăn dày 2–3cm để nhiệt và gia vị thấm sâu đều khắp bên trong. Khứa 2 đường ở phần dày của đùi, trộn với muối và tiêu. Để lạnh 20 phút; khuấy trứng với sữa.',6,'Bề mặt nguyên liệu càng khô ráo thì khi chiên không bị văng dầu và khi nướng sẽ lên màu vàng ruộm giòn rụm cực đẹp.'),
(80,2,'Chuẩn bị hỗn hợp sốt ướp / bột áo chuẩn tỷ lệ','Phối trộn hành tím và tỏi băm nhỏ băm thật nhuyễn (hoặc vắt lấy nước cốt thơm) cùng 5g muối và 2g tiêu trong tô lớn cho quyện sánh đồng nhất. Nếu món có lớp vỏ bột hoặc bánh cuốn từ 700g đùi gà và 100g bột mì, trộn đều hỗn hợp theo đúng định lượng để đạt độ giòn xốp mỏng nhẹ chuẩn vị. Trộn bột mì với bột bắp. Nhúng gà vào trứng sữa, phủ bột, nhúng lại rồi lăn bột lần nữa để tạo lớp áo sần.',6,'Vắt lấy nước cốt hành tỏi sả khi ướp đồ nướng giúp hương thơm thấm sâu mà không bị cháy đen phần xác băm trên lửa cao.'),
(80,3,'Ướp thấm thớ thịt / tạo hình cuốn khéo léo','Áo đều hỗn hợp gia vị hoặc lớp bột/vỏ cuốn quanh 700g đùi gà và 100g bột mì, massage nhẹ nhàng rồi để nghỉ 15–20 phút cho gia vị thẩm thấu trọn vẹn. Trường hợp cuốn chả/nem hoặc đổ khuôn bánh, thao tác đều tay vừa chặt để nhân kết dính nhưng không bị bục rách khi gặp nhiệt.',7,'Để nguyên liệu nghỉ đủ thời gian trước khi chiên nướng giúp lớp áo bột bám chắc và phần nhân bên trong mọng ngọt.'),
(80,4,'Pha nước chấm cân vị & sơ chế rau đồ chua ăn kèm','Nhặt rửa sạch rau củ ăn kèm ngâm nước mát cho giòn tươi, bào sợi hoặc thái lát gọn gàng bày sẵn bên cạnh. Pha chén nước chấm chua ngọt hoặc muối ớt chanh sả sánh thơm theo khẩu vị vùng miền của món Đùi gà chiên giòn để cân bằng độ béo giòn.',5,'Luôn chuẩn bị xong rau sống và bát nước chấm trước khi chiên/nướng mẻ cuối để món ăn vừa ra lò là thưởng thức nóng giòn ngay.'),
(80,5,'Làm nóng dầu / lò nướng chuẩn nhiệt & làm chín đều lần 1','Làm nóng chảo dầu hoặc vỉ nướng/nồi chiên ở mức nhiệt vừa khoảng 165–175°C, xếp 700g đùi gà và 100g bột mì vào với khoảng cách thoáng đều nhau. Chiên hoặc nướng trở mặt nhịp nhàng trên lửa vừa để nhiệt dẫn sâu làm chín mềm ngọt hoàn toàn phần nhân bên trong. Chiên ở 160–165°C khoảng 14–18 phút tùy kích thước, trở đều. Không xếp chật nồi để dầu không giảm nhiệt mạnh.',9,'Kiểm tra nhiệt dầu bằng đầu đũa tre thấy sủi tăm nhỏ đều là đạt chuẩn 170°C, giúp vỏ không cháy sớm khi bên trong còn sống.'),
(80,6,'Tăng nhiệt khóa giòn rụm vàng ươm bề mặt lần 2','Ở 2–3 phút cuối, tăng lên lửa vừa lớn (khoảng 190°C) hoặc phết thêm lớp dầu điều/mật ong mỏng để vỏ ngoài của Đùi gà chiên giòn chuyển sắc vàng óng ánh và nổ giòn rụm. Lắng nghe tiếng xèo giòn rộn rã và hương thơm phức lan tỏa khắp bếp thì gắp ra vỉ thưa cho ráo dầu thừa.',4,'Đặt đồ chiên nướng lên giá inox thoáng khí thay vì giấy thấm dầu chồng khít để hơi nước thoát hết, giữ độ giòn lâu gấp 3 lần.');
INSERT INTO `recipe_steps` (`recipe_id`,`step_order`,`title`,`instruction`,`duration_mins`,`tip_note`) VALUES
(80,7,'Trình bày bắt mắt kèm rau thơm & thưởng thức nóng','Xếp thành phẩm vàng giòn ra đĩa lớn có bày sẵn rau củ ăn kèm và điểm xuyết hành ngò và tiêu xay tươi xanh hài hòa màu sắc. Dọn kèm chén nước chấm sánh đậm ngay chính giữa mâm ăn cho 4 người thưởng thức khi vỏ ngoài còn nóng giòn rụm. Đo phần dày nhất gần xương đạt 74°C. Để gà nghỉ trên giá 5 phút cho ráo dầu rồi dùng nóng.',3,'Cắt miếng hoặc dọn ăn ngay trong vòng 10 phút sau khi rời bếp để cảm nhận trọn vẹn sự đối lập giòn ngoài - mềm ngọt bên trong.'),
(81,1,'Sơ chế sạch & chuẩn bị nguyên liệu thuần chay','Rửa sạch toàn bộ nguyên liệu dưới vòi nước mát, để ráo tự nhiên trên rổ thưa gồm 400g nấm rơm và 100g nấm hương cùng các nguyên liệu phối kèm. Cắt thái đồng đều kích thước khoảng 3–4cm vừa gắp để khi chế biến chín cùng lúc và thấm đều gia vị thực vật. Cắt bỏ chân nấm, rửa nhanh rồi để thật ráo; nấm to bổ đôi để chín đều.',4,'Thấm khô bề mặt đậu hũ và nấm bằng khăn giấy bếp trước khi chế biến giúp nguyên liệu săn chắc, không bị bắn dầu hay ra nước.'),
(81,2,'Xử lý độ giòn ngọt của nấm & rau củ','Đối với nhóm nấm và rau củ (400g nấm rơm và 100g nấm hương), ngâm nhanh qua nước muối loãng 3 phút rồi vắt nhẹ hoặc chần sơ 45 giây trong nước sôi, vớt ngay ra tô nước mát. Thao tác này giúp giữ trọn sắc màu tươi sáng tự nhiên, loại bỏ mùi ngái và tạo độ giòn ngọt thanh khiết cho món Nấm kho tiêu.',4,'Không ngâm nấm quá lâu trong nước lạnh vì nấm sẽ hút nước mạnh làm nhạt vị ngọt umami tự nhiên.'),
(81,3,'Pha chén sốt gia vị chay chuẩn định lượng','Chuẩn bị tô nhỏ, đong chính xác 25ml nước tương, 4g tiêu và 8g đường khuấy đều cùng 30ml nước ấm hoặc nước ngâm nấm hương cho tan hoàn toàn đường và hạt nêm nấm. Nếm thử thấy vị mặn ngọt hài hòa, thanh dịu đúng tinh thần ẩm thực chay cho khẩu phần 4 người. Phi hành tím với dầu, cho nấm vào đảo lửa lớn 3 phút đến khi hơi se mặt.',3,'Pha sẵn chén sốt trước khi bật bếp giúp kiểm soát chính xác định lượng từng gam và không bị cháy khét gia vị trên chảo nóng.'),
(81,4,'Phi thơm hành boaro & tạo nền hương thảo mộc','Làm nóng nồi hoặc chảo đáy dày trên lửa vừa, cho 180ml nước dừa tươi và 10ml dầu ăn vào láng đều mặt chảo rồi trút 20g hành tím vào phi thơm. Đảo nhẹ tay khoảng 1–2 phút đến khi hành boaro chuyển sắc vàng óng và dậy mùi thơm dịu thì hạ lửa vừa.',4,'Hành boaro cháy nhanh hơn hành tím nên chỉ phi trên lửa vừa đến khi vừa chớm vàng thơm là cho nguyên liệu chính vào ngay.'),
(81,5,'Chế biến săn thấm nguyên liệu chính thuần thực vật','Cho 400g nấm rơm và 100g nấm hương vào đảo đều hoặc áp chảo nhẹ hai mặt trên lửa vừa đến khi bề mặt săn vàng, sau đó rưới 2/3 chén sốt gia vị chay đã pha vào. Đảo nhẹ tay để sốt bám đều quanh từng thớ đậu và nấm mà không làm vỡ nát cấu trúc nguyên liệu. Thêm nước tương, đường và nước dừa. Đun sôi rồi hạ nhỏ lửa kho 12–15 phút, thỉnh thoảng lắc nồi.',7,'Dùng sạn gỗ đảo nhẹ từ dưới đáy chảo hất lên để miếng đậu hũ và nấm giữ nguyên hình khối vuông vắn đẹp mắt.'),
(81,6,'Phối hợp rau củ & cân chỉnh độ sánh thanh đạm','Tiếp tục cho các nguyên liệu phối kèm cùng phần sốt còn lại vào nồi, điều chỉnh lửa vừa nấu thêm cho nguyên liệu chín mềm tới nhưng vẫn giữ độ giòn ngọt. Quan sát thấy nước sốt chuyển màu nâu hổ phách sóng sánh hoặc nước dùng trong thanh, hương thơm quyện đều khắp gian bếp. Khi nước kho sánh nhẹ, nếm lại và rắc tiêu. Món này dùng nước tương, không dùng nước mắm chay.',5,'Chỉ nấu rau củ xanh vừa chín tới để bảo toàn tối đa lượng chất xơ và vitamin tự nhiên trong khẩu phần chay.'),
(81,7,'Hoàn thiện hương thơm & trình bày món chay thanh tịnh','Tắt bếp ngay khi món ăn đạt độ chín chuẩn, rắc đều hành boaro lá xanh và tiêu xay lên bề mặt để dậy mùi thơm tươi mới. Múc món Nấm kho tiêu ra đĩa sứ hoặc tô sâu lòng, thưởng thức nóng cùng cơm trắng hoặc bún tươi cho trọn vẹn 4 khẩu phần.',3,'Rắc rau thơm và tiêu ngay lúc vừa tắt bếp giúp tinh dầu tỏa hương thơm ngát mà lá rau không bị thâm xỉn màu.'),
(82,1,'Sơ chế sạch & chuẩn bị nguyên liệu thuần chay','Rửa sạch toàn bộ nguyên liệu dưới vòi nước mát, để ráo tự nhiên trên rổ thưa gồm 400g đậu hũ non và 120g nấm hương cùng 100g nấm rơm và 8g bột bắp. Cắt thái đồng đều kích thước khoảng 3–4cm vừa gắp để khi chế biến chín cùng lúc và thấm đều gia vị thực vật. Ngâm nấm hương, thái lát; cắt nấm rơm đôi. Hòa bột bắp với 2 thìa nước lạnh.',4,'Thấm khô bề mặt đậu hũ và nấm bằng khăn giấy bếp trước khi chế biến giúp nguyên liệu săn chắc, không bị bắn dầu hay ra nước.'),
(82,2,'Xử lý độ giòn ngọt của nấm & rau củ','Đối với nhóm nấm và rau củ (400g đậu hũ non và 120g nấm hương), ngâm nhanh qua nước muối loãng 3 phút rồi vắt nhẹ hoặc chần sơ 45 giây trong nước sôi, vớt ngay ra tô nước mát. Thao tác này giúp giữ trọn sắc màu tươi sáng tự nhiên, loại bỏ mùi ngái và tạo độ giòn ngọt thanh khiết cho món Đậu hũ non sốt nấm.',3,'Không ngâm nấm quá lâu trong nước lạnh vì nấm sẽ hút nước mạnh làm nhạt vị ngọt umami tự nhiên.'),
(82,3,'Pha chén sốt gia vị chay chuẩn định lượng','Chuẩn bị tô nhỏ, đong chính xác 18ml nước tương khuấy đều cùng 30ml nước ấm hoặc nước ngâm nấm hương cho tan hoàn toàn đường và hạt nêm nấm. Nếm thử thấy vị mặn ngọt hài hòa, thanh dịu đúng tinh thần ẩm thực chay cho khẩu phần 4 người. Cắt đậu hũ non thành khối lớn, hấp 5–6 phút cho nóng; giữ nguyên miếng để đậu không vỡ.',2,'Pha sẵn chén sốt trước khi bật bếp giúp kiểm soát chính xác định lượng từng gam và không bị cháy khét gia vị trên chảo nóng.'),
(82,4,'Phi thơm hành boaro & tạo nền hương thảo mộc','Làm nóng nồi hoặc chảo đáy dày trên lửa vừa, cho 5ml dầu mè và 120ml nước lọc vào láng đều mặt chảo rồi trút 20g hành boaro thái lát mỏng vào phi thơm. Đảo nhẹ tay khoảng 1–2 phút đến khi hành boaro chuyển sắc vàng óng và dậy mùi thơm dịu thì hạ lửa vừa.',3,'Hành boaro cháy nhanh hơn hành tím nên chỉ phi trên lửa vừa đến khi vừa chớm vàng thơm là cho nguyên liệu chính vào ngay.'),
(82,5,'Chế biến săn thấm nguyên liệu chính thuần thực vật','Cho 400g đậu hũ non và 120g nấm hương vào đảo đều hoặc áp chảo nhẹ hai mặt trên lửa vừa đến khi bề mặt săn vàng, sau đó rưới 2/3 chén sốt gia vị chay đã pha vào. Đảo nhẹ tay để sốt bám đều quanh từng thớ đậu và nấm mà không làm vỡ nát cấu trúc nguyên liệu. Xào nấm với chút dầu đến thơm, thêm nước tương và nước lọc, đun 4 phút. Rót bột bắp từ từ để sốt sánh.',6,'Dùng sạn gỗ đảo nhẹ từ dưới đáy chảo hất lên để miếng đậu hũ và nấm giữ nguyên hình khối vuông vắn đẹp mắt.'),
(82,6,'Phối hợp rau củ & cân chỉnh độ sánh thanh đạm','Tiếp tục cho 100g nấm rơm và 8g bột bắp cùng phần sốt còn lại vào nồi, điều chỉnh lửa vừa nấu thêm cho nguyên liệu chín mềm tới nhưng vẫn giữ độ giòn ngọt. Quan sát thấy nước sốt chuyển màu nâu hổ phách sóng sánh hoặc nước dùng trong thanh, hương thơm quyện đều khắp gian bếp. Nhấc đậu ra đĩa, chắt bớt nước đọng. Rưới sốt nấm, thêm dầu mè và hành lá; dùng nóng.',4,'Chỉ nấu rau củ xanh vừa chín tới để bảo toàn tối đa lượng chất xơ và vitamin tự nhiên trong khẩu phần chay.'),
(82,7,'Hoàn thiện hương thơm & trình bày món chay thanh tịnh','Tắt bếp ngay khi món ăn đạt độ chín chuẩn, rắc đều 10g hành lá lên bề mặt để dậy mùi thơm tươi mới. Múc món Đậu hũ non sốt nấm ra đĩa sứ hoặc tô sâu lòng, thưởng thức nóng cùng cơm trắng hoặc bún tươi cho trọn vẹn 4 khẩu phần.',2,'Rắc rau thơm và tiêu ngay lúc vừa tắt bếp giúp tinh dầu tỏa hương thơm ngát mà lá rau không bị thâm xỉn màu.'),
(83,1,'Sơ chế sạch & chuẩn bị nguyên liệu thuần chay','Rửa sạch toàn bộ nguyên liệu dưới vòi nước mát, để ráo tự nhiên trên rổ thưa gồm 400g cà tím và 250g đậu hũ cùng 200g cà chua. Cắt thái đồng đều kích thước khoảng 3–4cm vừa gắp để khi chế biến chín cùng lúc và thấm đều gia vị thực vật. Cắt cà tím khúc vừa, ngâm nước muối loãng 10 phút rồi rửa và để ráo. Cắt đậu hũ khối, cà chua múi cau.',5,'Thấm khô bề mặt đậu hũ và nấm bằng khăn giấy bếp trước khi chế biến giúp nguyên liệu săn chắc, không bị bắn dầu hay ra nước.'),
(83,2,'Xử lý độ giòn ngọt của nấm & rau củ','Đối với nhóm nấm và rau củ (400g cà tím và 250g đậu hũ), ngâm nhanh qua nước muối loãng 3 phút rồi vắt nhẹ hoặc chần sơ 45 giây trong nước sôi, vớt ngay ra tô nước mát. Thao tác này giúp giữ trọn sắc màu tươi sáng tự nhiên, loại bỏ mùi ngái và tạo độ giòn ngọt thanh khiết cho món Cà tím om đậu.',5,'Không ngâm nấm quá lâu trong nước lạnh vì nấm sẽ hút nước mạnh làm nhạt vị ngọt umami tự nhiên.'),
(83,3,'Pha chén sốt gia vị chay chuẩn định lượng','Chuẩn bị tô nhỏ, đong chính xác 18ml nước tương và 3g muối khuấy đều cùng 30ml nước ấm hoặc nước ngâm nấm hương cho tan hoàn toàn đường và hạt nêm nấm. Nếm thử thấy vị mặn ngọt hài hòa, thanh dịu đúng tinh thần ẩm thực chay cho khẩu phần 4 người. Áp chảo đậu hũ hai mặt vàng nhẹ, gắp ra. Xào cà tím với ít dầu đến khi se mặt.',4,'Pha sẵn chén sốt trước khi bật bếp giúp kiểm soát chính xác định lượng từng gam và không bị cháy khét gia vị trên chảo nóng.'),
(83,4,'Phi thơm hành boaro & tạo nền hương thảo mộc','Làm nóng nồi hoặc chảo đáy dày trên lửa vừa, cho 180ml nước lọc và 15ml dầu ăn vào láng đều mặt chảo rồi trút 15g hành tím vào phi thơm. Đảo nhẹ tay khoảng 1–2 phút đến khi hành boaro chuyển sắc vàng óng và dậy mùi thơm dịu thì hạ lửa vừa.',4,'Hành boaro cháy nhanh hơn hành tím nên chỉ phi trên lửa vừa đến khi vừa chớm vàng thơm là cho nguyên liệu chính vào ngay.'),
(83,5,'Chế biến săn thấm nguyên liệu chính thuần thực vật','Cho 400g cà tím và 250g đậu hũ vào đảo đều hoặc áp chảo nhẹ hai mặt trên lửa vừa đến khi bề mặt săn vàng, sau đó rưới 2/3 chén sốt gia vị chay đã pha vào. Đảo nhẹ tay để sốt bám đều quanh từng thớ đậu và nấm mà không làm vỡ nát cấu trúc nguyên liệu. Thêm cà chua, nước tương và nước lọc, đậy nắp om nhỏ lửa 10 phút. Cho đậu hũ vào nấu thêm 5 phút.',7,'Dùng sạn gỗ đảo nhẹ từ dưới đáy chảo hất lên để miếng đậu hũ và nấm giữ nguyên hình khối vuông vắn đẹp mắt.'),
(83,6,'Phối hợp rau củ & cân chỉnh độ sánh thanh đạm','Tiếp tục cho 200g cà chua cùng phần sốt còn lại vào nồi, điều chỉnh lửa vừa nấu thêm cho nguyên liệu chín mềm tới nhưng vẫn giữ độ giòn ngọt. Quan sát thấy nước sốt chuyển màu nâu hổ phách sóng sánh hoặc nước dùng trong thanh, hương thơm quyện đều khắp gian bếp. Khi cà tím mềm nhưng còn nguyên miếng, nếm sốt và tắt bếp. Thái tía tô rắc lên trên; không thêm nước mắm chay.',6,'Chỉ nấu rau củ xanh vừa chín tới để bảo toàn tối đa lượng chất xơ và vitamin tự nhiên trong khẩu phần chay.'),
(83,7,'Hoàn thiện hương thơm & trình bày món chay thanh tịnh','Tắt bếp ngay khi món ăn đạt độ chín chuẩn, rắc đều 15g tía tô lên bề mặt để dậy mùi thơm tươi mới. Múc món Cà tím om đậu ra đĩa sứ hoặc tô sâu lòng, thưởng thức nóng cùng cơm trắng hoặc bún tươi cho trọn vẹn 4 khẩu phần.',4,'Rắc rau thơm và tiêu ngay lúc vừa tắt bếp giúp tinh dầu tỏa hương thơm ngát mà lá rau không bị thâm xỉn màu.'),
(84,1,'Sơ chế sạch & chuẩn bị nguyên liệu thuần chay','Rửa sạch toàn bộ nguyên liệu dưới vòi nước mát, để ráo tự nhiên trên rổ thưa gồm 400g nấm đùi gà cùng các nguyên liệu phối kèm. Cắt thái đồng đều kích thước khoảng 3–4cm vừa gắp để khi chế biến chín cùng lúc và thấm đều gia vị thực vật. Lau sạch nấm, cắt lát dày 1 cm rồi khía nhẹ mặt nấm để thấm sốt. Thái gừng sợi.',5,'Thấm khô bề mặt đậu hũ và nấm bằng khăn giấy bếp trước khi chế biến giúp nguyên liệu săn chắc, không bị bắn dầu hay ra nước.'),
(84,2,'Xử lý độ giòn ngọt của nấm & rau củ','Đối với nhóm nấm và rau củ (400g nấm đùi gà), ngâm nhanh qua nước muối loãng 3 phút rồi vắt nhẹ hoặc chần sơ 45 giây trong nước sôi, vớt ngay ra tô nước mát. Thao tác này giúp giữ trọn sắc màu tươi sáng tự nhiên, loại bỏ mùi ngái và tạo độ giòn ngọt thanh khiết cho món Nấm đùi gà kho gừng.',4,'Không ngâm nấm quá lâu trong nước lạnh vì nấm sẽ hút nước mạnh làm nhạt vị ngọt umami tự nhiên.'),
(84,3,'Pha chén sốt gia vị chay chuẩn định lượng','Chuẩn bị tô nhỏ, đong chính xác 25ml nước tương, 2g tiêu và 8g đường khuấy đều cùng 30ml nước ấm hoặc nước ngâm nấm hương cho tan hoàn toàn đường và hạt nêm nấm. Nếm thử thấy vị mặn ngọt hài hòa, thanh dịu đúng tinh thần ẩm thực chay cho khẩu phần 4 người. Làm nóng dầu, xếp nấm một lớp và áp mỗi mặt 2 phút đến hơi vàng; gắp ra.',3,'Pha sẵn chén sốt trước khi bật bếp giúp kiểm soát chính xác định lượng từng gam và không bị cháy khét gia vị trên chảo nóng.');
INSERT INTO `recipe_steps` (`recipe_id`,`step_order`,`title`,`instruction`,`duration_mins`,`tip_note`) VALUES
(84,4,'Phi thơm hành boaro & tạo nền hương thảo mộc','Làm nóng nồi hoặc chảo đáy dày trên lửa vừa, cho 160ml nước dừa tươi và 10ml dầu ăn vào láng đều mặt chảo rồi trút 25g gừng và 15g hành tím vào phi thơm. Đảo nhẹ tay khoảng 1–2 phút đến khi hành boaro chuyển sắc vàng óng và dậy mùi thơm dịu thì hạ lửa vừa.',4,'Hành boaro cháy nhanh hơn hành tím nên chỉ phi trên lửa vừa đến khi vừa chớm vàng thơm là cho nguyên liệu chính vào ngay.'),
(84,5,'Chế biến săn thấm nguyên liệu chính thuần thực vật','Cho 400g nấm đùi gà vào đảo đều hoặc áp chảo nhẹ hai mặt trên lửa vừa đến khi bề mặt săn vàng, sau đó rưới 2/3 chén sốt gia vị chay đã pha vào. Đảo nhẹ tay để sốt bám đều quanh từng thớ đậu và nấm mà không làm vỡ nát cấu trúc nguyên liệu. Phi hành tím và gừng, thêm nước tương, đường, nước dừa và nấm. Đun sôi rồi hạ nhỏ lửa 12 phút.',7,'Dùng sạn gỗ đảo nhẹ từ dưới đáy chảo hất lên để miếng đậu hũ và nấm giữ nguyên hình khối vuông vắn đẹp mắt.'),
(84,6,'Phối hợp rau củ & cân chỉnh độ sánh thanh đạm','Tiếp tục cho các nguyên liệu phối kèm cùng phần sốt còn lại vào nồi, điều chỉnh lửa vừa nấu thêm cho nguyên liệu chín mềm tới nhưng vẫn giữ độ giòn ngọt. Quan sát thấy nước sốt chuyển màu nâu hổ phách sóng sánh hoặc nước dùng trong thanh, hương thơm quyện đều khắp gian bếp. Mở nắp, đảo nấm đến khi sốt bám bóng. Nêm tiêu, tắt bếp; dùng nước tương thay cho nước mắm chay.',6,'Chỉ nấu rau củ xanh vừa chín tới để bảo toàn tối đa lượng chất xơ và vitamin tự nhiên trong khẩu phần chay.'),
(84,7,'Hoàn thiện hương thơm & trình bày món chay thanh tịnh','Tắt bếp ngay khi món ăn đạt độ chín chuẩn, rắc đều hành boaro lá xanh và tiêu xay lên bề mặt để dậy mùi thơm tươi mới. Múc món Nấm đùi gà kho gừng ra đĩa sứ hoặc tô sâu lòng, thưởng thức nóng cùng cơm trắng hoặc bún tươi cho trọn vẹn 4 khẩu phần.',3,'Rắc rau thơm và tiêu ngay lúc vừa tắt bếp giúp tinh dầu tỏa hương thơm ngát mà lá rau không bị thâm xỉn màu.'),
(85,1,'Sơ chế sạch & chuẩn bị nguyên liệu thuần chay','Rửa sạch toàn bộ nguyên liệu dưới vòi nước mát, để ráo tự nhiên trên rổ thưa gồm 200g đậu hũ và 100g cà rốt cùng 20g nấm mèo và 80g miến dong. Cắt thái đồng đều kích thước khoảng 3–4cm vừa gắp để khi chế biến chín cùng lúc và thấm đều gia vị thực vật. Ngâm nấm mèo và miến cho mềm, để ráo rồi cắt nhỏ. Bào cà rốt, bóp nhẹ đậu hũ cho bớt nước.',7,'Thấm khô bề mặt đậu hũ và nấm bằng khăn giấy bếp trước khi chế biến giúp nguyên liệu săn chắc, không bị bắn dầu hay ra nước.'),
(85,2,'Xử lý độ giòn ngọt của nấm & rau củ','Đối với nhóm nấm và rau củ (200g đậu hũ và 100g cà rốt), ngâm nhanh qua nước muối loãng 3 phút rồi vắt nhẹ hoặc chần sơ 45 giây trong nước sôi, vớt ngay ra tô nước mát. Thao tác này giúp giữ trọn sắc màu tươi sáng tự nhiên, loại bỏ mùi ngái và tạo độ giòn ngọt thanh khiết cho món Chả giò chay.',6,'Không ngâm nấm quá lâu trong nước lạnh vì nấm sẽ hút nước mạnh làm nhạt vị ngọt umami tự nhiên.'),
(85,3,'Pha chén sốt gia vị chay chuẩn định lượng','Chuẩn bị tô nhỏ, đong chính xác 15ml nước tương, 2g tiêu và 1 quả chanh khuấy đều cùng 30ml nước ấm hoặc nước ngâm nấm hương cho tan hoàn toàn đường và hạt nêm nấm. Nếm thử thấy vị mặn ngọt hài hòa, thanh dịu đúng tinh thần ẩm thực chay cho khẩu phần 4 người. Trộn đậu, cà rốt, nấm, miến, nước tương và tiêu. Nhúng bánh tráng cho mềm vừa, đặt nhân rồi cuốn kín hai đầu.',4,'Pha sẵn chén sốt trước khi bật bếp giúp kiểm soát chính xác định lượng từng gam và không bị cháy khét gia vị trên chảo nóng.'),
(85,4,'Phi thơm hành boaro & tạo nền hương thảo mộc','Làm nóng nồi hoặc chảo đáy dày trên lửa vừa, cho 500ml dầu ăn vào láng đều mặt chảo rồi trút 20g hành boaro thái lát mỏng vào phi thơm. Đảo nhẹ tay khoảng 1–2 phút đến khi hành boaro chuyển sắc vàng óng và dậy mùi thơm dịu thì hạ lửa vừa.',5,'Hành boaro cháy nhanh hơn hành tím nên chỉ phi trên lửa vừa đến khi vừa chớm vàng thơm là cho nguyên liệu chính vào ngay.'),
(85,5,'Chế biến săn thấm nguyên liệu chính thuần thực vật','Cho 200g đậu hũ và 100g cà rốt vào đảo đều hoặc áp chảo nhẹ hai mặt trên lửa vừa đến khi bề mặt săn vàng, sau đó rưới 2/3 chén sốt gia vị chay đã pha vào. Đảo nhẹ tay để sốt bám đều quanh từng thớ đậu và nấm mà không làm vỡ nát cấu trúc nguyên liệu. Chiên ở 160°C từng mẻ 5–6 phút đến khi cuốn se và hơi vàng; vớt ra để nguội vài phút.',11,'Dùng sạn gỗ đảo nhẹ từ dưới đáy chảo hất lên để miếng đậu hũ và nấm giữ nguyên hình khối vuông vắn đẹp mắt.'),
(85,6,'Phối hợp rau củ & cân chỉnh độ sánh thanh đạm','Tiếp tục cho 20g nấm mèo và 80g miến dong cùng phần sốt còn lại vào nồi, điều chỉnh lửa vừa nấu thêm cho nguyên liệu chín mềm tới nhưng vẫn giữ độ giòn ngọt. Quan sát thấy nước sốt chuyển màu nâu hổ phách sóng sánh hoặc nước dùng trong thanh, hương thơm quyện đều khắp gian bếp. Tăng dầu lên 175°C, chiên lại 2–3 phút đến vàng giòn. Để ráo trên giá; chấm nước tương pha chanh.',8,'Chỉ nấu rau củ xanh vừa chín tới để bảo toàn tối đa lượng chất xơ và vitamin tự nhiên trong khẩu phần chay.'),
(85,7,'Hoàn thiện hương thơm & trình bày món chay thanh tịnh','Tắt bếp ngay khi món ăn đạt độ chín chuẩn, rắc đều hành boaro lá xanh và tiêu xay lên bề mặt để dậy mùi thơm tươi mới. Múc món Chả giò chay ra đĩa sứ hoặc tô sâu lòng, thưởng thức nóng cùng cơm trắng hoặc bún tươi cho trọn vẹn 4 khẩu phần.',4,'Rắc rau thơm và tiêu ngay lúc vừa tắt bếp giúp tinh dầu tỏa hương thơm ngát mà lá rau không bị thâm xỉn màu.'),
(86,1,'Sơ chế sạch & chuẩn bị nguyên liệu thuần chay','Rửa sạch toàn bộ nguyên liệu dưới vòi nước mát, để ráo tự nhiên trên rổ thưa gồm 300g ngó sen và 100g cà rốt cùng 120g dưa leo. Cắt thái đồng đều kích thước khoảng 3–4cm vừa gắp để khi chế biến chín cùng lúc và thấm đều gia vị thực vật. Rửa ngó sen, cắt khúc xéo và ngâm nước có chanh 10 phút để giữ màu; vớt ra, để ráo thật kỹ.',6,'Thấm khô bề mặt đậu hũ và nấm bằng khăn giấy bếp trước khi chế biến giúp nguyên liệu săn chắc, không bị bắn dầu hay ra nước.'),
(86,2,'Xử lý độ giòn ngọt của nấm & rau củ','Đối với nhóm nấm và rau củ (120g dưa leo), ngâm nhanh qua nước muối loãng 3 phút rồi vắt nhẹ hoặc chần sơ 45 giây trong nước sôi, vớt ngay ra tô nước mát. Thao tác này giúp giữ trọn sắc màu tươi sáng tự nhiên, loại bỏ mùi ngái và tạo độ giòn ngọt thanh khiết cho món Gỏi ngó sen chay.',5,'Không ngâm nấm quá lâu trong nước lạnh vì nấm sẽ hút nước mạnh làm nhạt vị ngọt umami tự nhiên.'),
(86,3,'Pha chén sốt gia vị chay chuẩn định lượng','Chuẩn bị tô nhỏ, đong chính xác 2 quả chanh, 18ml nước tương, 12g đường và 3g muối khuấy đều cùng 30ml nước ấm hoặc nước ngâm nấm hương cho tan hoàn toàn đường và hạt nêm nấm. Nếm thử thấy vị mặn ngọt hài hòa, thanh dịu đúng tinh thần ẩm thực chay cho khẩu phần 4 người. Bào cà rốt sợi, bỏ ruột dưa leo rồi thái sợi. Rang đậu phộng, để nguội và giã dập.',4,'Pha sẵn chén sốt trước khi bật bếp giúp kiểm soát chính xác định lượng từng gam và không bị cháy khét gia vị trên chảo nóng.'),
(86,4,'Phi thơm hành boaro & tạo nền hương thảo mộc','Làm nóng nồi hoặc chảo đáy dày trên lửa vừa, cho 15ml dầu thực vật vào láng đều mặt chảo rồi trút 20g hành boaro thái lát mỏng vào phi thơm. Đảo nhẹ tay khoảng 1–2 phút đến khi hành boaro chuyển sắc vàng óng và dậy mùi thơm dịu thì hạ lửa vừa.',5,'Hành boaro cháy nhanh hơn hành tím nên chỉ phi trên lửa vừa đến khi vừa chớm vàng thơm là cho nguyên liệu chính vào ngay.'),
(86,5,'Chế biến săn thấm nguyên liệu chính thuần thực vật','Cho 300g ngó sen và 100g cà rốt vào đảo đều hoặc áp chảo nhẹ hai mặt trên lửa vừa đến khi bề mặt săn vàng, sau đó rưới 2/3 chén sốt gia vị chay đã pha vào. Đảo nhẹ tay để sốt bám đều quanh từng thớ đậu và nấm mà không làm vỡ nát cấu trúc nguyên liệu. Khuấy nước cốt chanh, nước tương, đường và muối đến tan. Nếm vị chua ngọt mặn cân bằng.',9,'Dùng sạn gỗ đảo nhẹ từ dưới đáy chảo hất lên để miếng đậu hũ và nấm giữ nguyên hình khối vuông vắn đẹp mắt.'),
(86,6,'Phối hợp rau củ & cân chỉnh độ sánh thanh đạm','Tiếp tục cho 120g dưa leo cùng phần sốt còn lại vào nồi, điều chỉnh lửa vừa nấu thêm cho nguyên liệu chín mềm tới nhưng vẫn giữ độ giòn ngọt. Quan sát thấy nước sốt chuyển màu nâu hổ phách sóng sánh hoặc nước dùng trong thanh, hương thơm quyện đều khắp gian bếp. Trộn ngó sen, cà rốt và dưa leo với nước sốt, để 5 phút rồi chắt bớt nước. Thêm rau răm, đậu phộng; không dùng nước mắm chay.',7,'Chỉ nấu rau củ xanh vừa chín tới để bảo toàn tối đa lượng chất xơ và vitamin tự nhiên trong khẩu phần chay.'),
(86,7,'Hoàn thiện hương thơm & trình bày món chay thanh tịnh','Tắt bếp ngay khi món ăn đạt độ chín chuẩn, rắc đều 35g đậu phộng và 15g rau răm lên bề mặt để dậy mùi thơm tươi mới. Múc món Gỏi ngó sen chay ra đĩa sứ hoặc tô sâu lòng, thưởng thức nóng cùng cơm trắng hoặc bún tươi cho trọn vẹn 4 khẩu phần.',4,'Rắc rau thơm và tiêu ngay lúc vừa tắt bếp giúp tinh dầu tỏa hương thơm ngát mà lá rau không bị thâm xỉn màu.'),
(87,1,'Sơ chế sạch & chuẩn bị nguyên liệu thuần chay','Rửa sạch toàn bộ nguyên liệu dưới vòi nước mát, để ráo tự nhiên trên rổ thưa gồm 400g bún tươi và 250g đậu hũ cùng 150g cải thìa. Cắt thái đồng đều kích thước khoảng 3–4cm vừa gắp để khi chế biến chín cùng lúc và thấm đều gia vị thực vật. Tách bún cho tơi; nếu bún lạnh cứng, trụng nhanh rồi để ráo. Thái đậu phụ, cải thìa, cà rốt và nấm.',4,'Thấm khô bề mặt đậu hũ và nấm bằng khăn giấy bếp trước khi chế biến giúp nguyên liệu săn chắc, không bị bắn dầu hay ra nước.'),
(87,2,'Xử lý độ giòn ngọt của nấm & rau củ','Đối với nhóm nấm và rau củ (150g cải thìa), ngâm nhanh qua nước muối loãng 3 phút rồi vắt nhẹ hoặc chần sơ 45 giây trong nước sôi, vớt ngay ra tô nước mát. Thao tác này giúp giữ trọn sắc màu tươi sáng tự nhiên, loại bỏ mùi ngái và tạo độ giòn ngọt thanh khiết cho món Bún xào chay.',4,'Không ngâm nấm quá lâu trong nước lạnh vì nấm sẽ hút nước mạnh làm nhạt vị ngọt umami tự nhiên.'),
(87,3,'Pha chén sốt gia vị chay chuẩn định lượng','Chuẩn bị tô nhỏ, đong chính xác 20ml nước tương khuấy đều cùng 30ml nước ấm hoặc nước ngâm nấm hương cho tan hoàn toàn đường và hạt nêm nấm. Nếm thử thấy vị mặn ngọt hài hòa, thanh dịu đúng tinh thần ẩm thực chay cho khẩu phần 4 người. Áp đậu phụ với ít dầu đến vàng các mặt, gắp riêng. Xào nấm và cà rốt 3 phút.',3,'Pha sẵn chén sốt trước khi bật bếp giúp kiểm soát chính xác định lượng từng gam và không bị cháy khét gia vị trên chảo nóng.'),
(87,4,'Phi thơm hành boaro & tạo nền hương thảo mộc','Làm nóng nồi hoặc chảo đáy dày trên lửa vừa, cho 15ml dầu ăn vào láng đều mặt chảo rồi trút 20g hành boaro thái lát mỏng vào phi thơm. Đảo nhẹ tay khoảng 1–2 phút đến khi hành boaro chuyển sắc vàng óng và dậy mùi thơm dịu thì hạ lửa vừa.',4,'Hành boaro cháy nhanh hơn hành tím nên chỉ phi trên lửa vừa đến khi vừa chớm vàng thơm là cho nguyên liệu chính vào ngay.'),
(87,5,'Chế biến săn thấm nguyên liệu chính thuần thực vật','Cho 400g bún tươi và 250g đậu hũ vào đảo đều hoặc áp chảo nhẹ hai mặt trên lửa vừa đến khi bề mặt săn vàng, sau đó rưới 2/3 chén sốt gia vị chay đã pha vào. Đảo nhẹ tay để sốt bám đều quanh từng thớ đậu và nấm mà không làm vỡ nát cấu trúc nguyên liệu. Thêm cải thìa và bún, đảo lửa vừa. Rưới nước tương pha 40 ml nước, dùng đũa tách sợi.',7,'Dùng sạn gỗ đảo nhẹ từ dưới đáy chảo hất lên để miếng đậu hũ và nấm giữ nguyên hình khối vuông vắn đẹp mắt.'),
(87,6,'Phối hợp rau củ & cân chỉnh độ sánh thanh đạm','Tiếp tục cho 150g cải thìa cùng phần sốt còn lại vào nồi, điều chỉnh lửa vừa nấu thêm cho nguyên liệu chín mềm tới nhưng vẫn giữ độ giòn ngọt. Quan sát thấy nước sốt chuyển màu nâu hổ phách sóng sánh hoặc nước dùng trong thanh, hương thơm quyện đều khắp gian bếp. Cho đậu phụ trở lại, đảo đến nóng đều và rau vừa chín. Rắc mè rang nếu dùng; không nêm nước mắm chay.',5,'Chỉ nấu rau củ xanh vừa chín tới để bảo toàn tối đa lượng chất xơ và vitamin tự nhiên trong khẩu phần chay.'),
(87,7,'Hoàn thiện hương thơm & trình bày món chay thanh tịnh','Tắt bếp ngay khi món ăn đạt độ chín chuẩn, rắc đều 10g mè rang lên bề mặt để dậy mùi thơm tươi mới. Múc món Bún xào chay ra đĩa sứ hoặc tô sâu lòng, thưởng thức nóng cùng cơm trắng hoặc bún tươi cho trọn vẹn 4 khẩu phần.',3,'Rắc rau thơm và tiêu ngay lúc vừa tắt bếp giúp tinh dầu tỏa hương thơm ngát mà lá rau không bị thâm xỉn màu.');
INSERT INTO `recipe_steps` (`recipe_id`,`step_order`,`title`,`instruction`,`duration_mins`,`tip_note`) VALUES
(88,1,'Sơ chế sạch & chuẩn bị nguyên liệu thuần chay','Rửa sạch toàn bộ nguyên liệu dưới vòi nước mát, để ráo tự nhiên trên rổ thưa gồm 600g cơm nguội và 100g cà rốt cùng 100g đậu hà lan và 100g bắp ngọt. Cắt thái đồng đều kích thước khoảng 3–4cm vừa gắp để khi chế biến chín cùng lúc và thấm đều gia vị thực vật. Dùng tay sạch hoặc muỗng tách cơm nguội thành hạt rời. Cắt cà rốt hạt lựu; chần đậu Hà Lan 2 phút.',4,'Thấm khô bề mặt đậu hũ và nấm bằng khăn giấy bếp trước khi chế biến giúp nguyên liệu săn chắc, không bị bắn dầu hay ra nước.'),
(88,2,'Xử lý độ giòn ngọt của nấm & rau củ','Đối với nhóm nấm và rau củ (100g đậu hà lan và 100g bắp ngọt), ngâm nhanh qua nước muối loãng 3 phút rồi vắt nhẹ hoặc chần sơ 45 giây trong nước sôi, vớt ngay ra tô nước mát. Thao tác này giúp giữ trọn sắc màu tươi sáng tự nhiên, loại bỏ mùi ngái và tạo độ giòn ngọt thanh khiết cho món Cơm chiên rau củ.',4,'Không ngâm nấm quá lâu trong nước lạnh vì nấm sẽ hút nước mạnh làm nhạt vị ngọt umami tự nhiên.'),
(88,3,'Pha chén sốt gia vị chay chuẩn định lượng','Chuẩn bị tô nhỏ, đong chính xác 20ml nước tương khuấy đều cùng 30ml nước ấm hoặc nước ngâm nấm hương cho tan hoàn toàn đường và hạt nêm nấm. Nếm thử thấy vị mặn ngọt hài hòa, thanh dịu đúng tinh thần ẩm thực chay cho khẩu phần 4 người. Phi tỏi trong chảo nóng, cho cà rốt và bắp vào xào 3 phút. Thêm đậu Hà Lan, đảo đến nóng.',3,'Pha sẵn chén sốt trước khi bật bếp giúp kiểm soát chính xác định lượng từng gam và không bị cháy khét gia vị trên chảo nóng.'),
(88,4,'Phi thơm hành boaro & tạo nền hương thảo mộc','Làm nóng nồi hoặc chảo đáy dày trên lửa vừa, cho 18ml dầu ăn vào láng đều mặt chảo rồi trút 8g tỏi vào phi thơm. Đảo nhẹ tay khoảng 1–2 phút đến khi hành boaro chuyển sắc vàng óng và dậy mùi thơm dịu thì hạ lửa vừa.',3,'Hành boaro cháy nhanh hơn hành tím nên chỉ phi trên lửa vừa đến khi vừa chớm vàng thơm là cho nguyên liệu chính vào ngay.'),
(88,5,'Chế biến săn thấm nguyên liệu chính thuần thực vật','Cho 600g cơm nguội và 100g cà rốt vào đảo đều hoặc áp chảo nhẹ hai mặt trên lửa vừa đến khi bề mặt săn vàng, sau đó rưới 2/3 chén sốt gia vị chay đã pha vào. Đảo nhẹ tay để sốt bám đều quanh từng thớ đậu và nấm mà không làm vỡ nát cấu trúc nguyên liệu. Thêm cơm, dàn đều và rang lửa lớn 4–5 phút. Đảo từ dưới lên để hạt cơm nóng đều mà không nát.',5,'Dùng sạn gỗ đảo nhẹ từ dưới đáy chảo hất lên để miếng đậu hũ và nấm giữ nguyên hình khối vuông vắn đẹp mắt.'),
(88,6,'Phối hợp rau củ & cân chỉnh độ sánh thanh đạm','Tiếp tục cho 100g đậu hà lan và 100g bắp ngọt cùng phần sốt còn lại vào nồi, điều chỉnh lửa vừa nấu thêm cho nguyên liệu chín mềm tới nhưng vẫn giữ độ giòn ngọt. Quan sát thấy nước sốt chuyển màu nâu hổ phách sóng sánh hoặc nước dùng trong thanh, hương thơm quyện đều khắp gian bếp. Rưới nước tương quanh thành chảo, đảo nhanh. Nếm lại, rắc hành lá và tắt bếp; món hoàn toàn không dùng trứng.',5,'Chỉ nấu rau củ xanh vừa chín tới để bảo toàn tối đa lượng chất xơ và vitamin tự nhiên trong khẩu phần chay.'),
(88,7,'Hoàn thiện hương thơm & trình bày món chay thanh tịnh','Tắt bếp ngay khi món ăn đạt độ chín chuẩn, rắc đều 15g hành lá lên bề mặt để dậy mùi thơm tươi mới. Múc món Cơm chiên rau củ ra đĩa sứ hoặc tô sâu lòng, thưởng thức nóng cùng cơm trắng hoặc bún tươi cho trọn vẹn 4 khẩu phần.',3,'Rắc rau thơm và tiêu ngay lúc vừa tắt bếp giúp tinh dầu tỏa hương thơm ngát mà lá rau không bị thâm xỉn màu.'),
(89,1,'Sơ chế sạch & chuẩn bị nguyên liệu thuần chay','Rửa sạch toàn bộ nguyên liệu dưới vòi nước mát, để ráo tự nhiên trên rổ thưa gồm 350g đậu hũ và 250g nấm rơm cùng các nguyên liệu phối kèm. Cắt thái đồng đều kích thước khoảng 3–4cm vừa gắp để khi chế biến chín cùng lúc và thấm đều gia vị thực vật. Cắt đậu hũ miếng vuông, thấm khô. Rửa nấm nhanh, cắt đôi nấm lớn; băm hành tím.',5,'Thấm khô bề mặt đậu hũ và nấm bằng khăn giấy bếp trước khi chế biến giúp nguyên liệu săn chắc, không bị bắn dầu hay ra nước.'),
(89,2,'Xử lý độ giòn ngọt của nấm & rau củ','Đối với nhóm nấm và rau củ (350g đậu hũ và 250g nấm rơm), ngâm nhanh qua nước muối loãng 3 phút rồi vắt nhẹ hoặc chần sơ 45 giây trong nước sôi, vớt ngay ra tô nước mát. Thao tác này giúp giữ trọn sắc màu tươi sáng tự nhiên, loại bỏ mùi ngái và tạo độ giòn ngọt thanh khiết cho món Đậu hũ kho nấm.',5,'Không ngâm nấm quá lâu trong nước lạnh vì nấm sẽ hút nước mạnh làm nhạt vị ngọt umami tự nhiên.'),
(89,3,'Pha chén sốt gia vị chay chuẩn định lượng','Chuẩn bị tô nhỏ, đong chính xác 25ml nước tương, 2g tiêu và 8g đường khuấy đều cùng 30ml nước ấm hoặc nước ngâm nấm hương cho tan hoàn toàn đường và hạt nêm nấm. Nếm thử thấy vị mặn ngọt hài hòa, thanh dịu đúng tinh thần ẩm thực chay cho khẩu phần 4 người. Chiên áp chảo đậu với ít dầu đến vàng nhẹ các mặt, gắp ra để giữ miếng khi kho.',4,'Pha sẵn chén sốt trước khi bật bếp giúp kiểm soát chính xác định lượng từng gam và không bị cháy khét gia vị trên chảo nóng.'),
(89,4,'Phi thơm hành boaro & tạo nền hương thảo mộc','Làm nóng nồi hoặc chảo đáy dày trên lửa vừa, cho 200ml nước dừa tươi và 12ml dầu ăn vào láng đều mặt chảo rồi trút 15g hành tím vào phi thơm. Đảo nhẹ tay khoảng 1–2 phút đến khi hành boaro chuyển sắc vàng óng và dậy mùi thơm dịu thì hạ lửa vừa.',4,'Hành boaro cháy nhanh hơn hành tím nên chỉ phi trên lửa vừa đến khi vừa chớm vàng thơm là cho nguyên liệu chính vào ngay.'),
(89,5,'Chế biến săn thấm nguyên liệu chính thuần thực vật','Cho 350g đậu hũ và 250g nấm rơm vào đảo đều hoặc áp chảo nhẹ hai mặt trên lửa vừa đến khi bề mặt săn vàng, sau đó rưới 2/3 chén sốt gia vị chay đã pha vào. Đảo nhẹ tay để sốt bám đều quanh từng thớ đậu và nấm mà không làm vỡ nát cấu trúc nguyên liệu. Phi hành, cho nấm vào xào 2 phút. Thêm nước tương, đường, nước dừa và đậu; kho lửa nhỏ 12 phút.',7,'Dùng sạn gỗ đảo nhẹ từ dưới đáy chảo hất lên để miếng đậu hũ và nấm giữ nguyên hình khối vuông vắn đẹp mắt.'),
(89,6,'Phối hợp rau củ & cân chỉnh độ sánh thanh đạm','Tiếp tục cho các nguyên liệu phối kèm cùng phần sốt còn lại vào nồi, điều chỉnh lửa vừa nấu thêm cho nguyên liệu chín mềm tới nhưng vẫn giữ độ giòn ngọt. Quan sát thấy nước sốt chuyển màu nâu hổ phách sóng sánh hoặc nước dùng trong thanh, hương thơm quyện đều khắp gian bếp. Lắc nồi nhẹ để sốt phủ đậu, mở nắp rim thêm đến sánh. Rắc tiêu; món dùng nước tương, không dùng nước mắm chay.',6,'Chỉ nấu rau củ xanh vừa chín tới để bảo toàn tối đa lượng chất xơ và vitamin tự nhiên trong khẩu phần chay.'),
(89,7,'Hoàn thiện hương thơm & trình bày món chay thanh tịnh','Tắt bếp ngay khi món ăn đạt độ chín chuẩn, rắc đều hành boaro lá xanh và tiêu xay lên bề mặt để dậy mùi thơm tươi mới. Múc món Đậu hũ kho nấm ra đĩa sứ hoặc tô sâu lòng, thưởng thức nóng cùng cơm trắng hoặc bún tươi cho trọn vẹn 4 khẩu phần.',4,'Rắc rau thơm và tiêu ngay lúc vừa tắt bếp giúp tinh dầu tỏa hương thơm ngát mà lá rau không bị thâm xỉn màu.'),
(90,1,'Sơ chế sạch & chuẩn bị nguyên liệu thuần chay','Rửa sạch toàn bộ nguyên liệu dưới vòi nước mát, để ráo tự nhiên trên rổ thưa gồm 300g mì căn cùng 100g hành tây. Cắt thái đồng đều kích thước khoảng 3–4cm vừa gắp để khi chế biến chín cùng lúc và thấm đều gia vị thực vật. Xé mì căn thành miếng vừa ăn, bóp nhẹ cho ráo nước. Băm sả, thái ớt và hành tây.',4,'Thấm khô bề mặt đậu hũ và nấm bằng khăn giấy bếp trước khi chế biến giúp nguyên liệu săn chắc, không bị bắn dầu hay ra nước.'),
(90,2,'Xử lý độ giòn ngọt của nấm & rau củ','Đối với nhóm nấm và rau củ (100g hành tây), ngâm nhanh qua nước muối loãng 3 phút rồi vắt nhẹ hoặc chần sơ 45 giây trong nước sôi, vớt ngay ra tô nước mát. Thao tác này giúp giữ trọn sắc màu tươi sáng tự nhiên, loại bỏ mùi ngái và tạo độ giòn ngọt thanh khiết cho món Mì căn xào sả ớt.',3,'Không ngâm nấm quá lâu trong nước lạnh vì nấm sẽ hút nước mạnh làm nhạt vị ngọt umami tự nhiên.'),
(90,3,'Pha chén sốt gia vị chay chuẩn định lượng','Chuẩn bị tô nhỏ, đong chính xác 1 quả ớt, 20ml nước tương, 5g đường và 1g tiêu khuấy đều cùng 30ml nước ấm hoặc nước ngâm nấm hương cho tan hoàn toàn đường và hạt nêm nấm. Nếm thử thấy vị mặn ngọt hài hòa, thanh dịu đúng tinh thần ẩm thực chay cho khẩu phần 4 người. Làm nóng dầu, áp chảo mì căn đến vàng cạnh để mặt ngoài săn và không hút quá nhiều sốt.',2,'Pha sẵn chén sốt trước khi bật bếp giúp kiểm soát chính xác định lượng từng gam và không bị cháy khét gia vị trên chảo nóng.'),
(90,4,'Phi thơm hành boaro & tạo nền hương thảo mộc','Làm nóng nồi hoặc chảo đáy dày trên lửa vừa, cho 15ml dầu ăn vào láng đều mặt chảo rồi trút 2 cây sả vào phi thơm. Đảo nhẹ tay khoảng 1–2 phút đến khi hành boaro chuyển sắc vàng óng và dậy mùi thơm dịu thì hạ lửa vừa.',3,'Hành boaro cháy nhanh hơn hành tím nên chỉ phi trên lửa vừa đến khi vừa chớm vàng thơm là cho nguyên liệu chính vào ngay.'),
(90,5,'Chế biến săn thấm nguyên liệu chính thuần thực vật','Cho 300g mì căn vào đảo đều hoặc áp chảo nhẹ hai mặt trên lửa vừa đến khi bề mặt săn vàng, sau đó rưới 2/3 chén sốt gia vị chay đã pha vào. Đảo nhẹ tay để sốt bám đều quanh từng thớ đậu và nấm mà không làm vỡ nát cấu trúc nguyên liệu. Đẩy mì căn sang mép, phi sả và ớt ở lửa vừa đến thơm. Thêm hành tây, đảo đến trong.',6,'Dùng sạn gỗ đảo nhẹ từ dưới đáy chảo hất lên để miếng đậu hũ và nấm giữ nguyên hình khối vuông vắn đẹp mắt.'),
(90,6,'Phối hợp rau củ & cân chỉnh độ sánh thanh đạm','Tiếp tục cho 100g hành tây cùng phần sốt còn lại vào nồi, điều chỉnh lửa vừa nấu thêm cho nguyên liệu chín mềm tới nhưng vẫn giữ độ giòn ngọt. Quan sát thấy nước sốt chuyển màu nâu hổ phách sóng sánh hoặc nước dùng trong thanh, hương thơm quyện đều khắp gian bếp. Rưới nước tương và đường, đảo đều 2 phút cho gia vị bám. Nếm độ cay, rắc tiêu và dùng nóng.',4,'Chỉ nấu rau củ xanh vừa chín tới để bảo toàn tối đa lượng chất xơ và vitamin tự nhiên trong khẩu phần chay.'),
(90,7,'Hoàn thiện hương thơm & trình bày món chay thanh tịnh','Tắt bếp ngay khi món ăn đạt độ chín chuẩn, rắc đều hành boaro lá xanh và tiêu xay lên bề mặt để dậy mùi thơm tươi mới. Múc món Mì căn xào sả ớt ra đĩa sứ hoặc tô sâu lòng, thưởng thức nóng cùng cơm trắng hoặc bún tươi cho trọn vẹn 4 khẩu phần.',2,'Rắc rau thơm và tiêu ngay lúc vừa tắt bếp giúp tinh dầu tỏa hương thơm ngát mà lá rau không bị thâm xỉn màu.'),
(91,1,'Sơ chế sạch & chuẩn bị nguyên liệu thuần chay','Rửa sạch toàn bộ nguyên liệu dưới vòi nước mát, để ráo tự nhiên trên rổ thưa gồm 12 cái bánh tráng và 250g bún tươi cùng 100g xà lách và 120g dưa leo. Cắt thái đồng đều kích thước khoảng 3–4cm vừa gắp để khi chế biến chín cùng lúc và thấm đều gia vị thực vật. Áp chảo đậu phụ đến vàng, cắt thanh. Trụng bún nếu cần, để ráo; rửa xà lách, húng quế và thái dưa leo.',7,'Thấm khô bề mặt đậu hũ và nấm bằng khăn giấy bếp trước khi chế biến giúp nguyên liệu săn chắc, không bị bắn dầu hay ra nước.'),
(91,2,'Xử lý độ giòn ngọt của nấm & rau củ','Đối với nhóm nấm và rau củ (100g xà lách và 120g dưa leo), ngâm nhanh qua nước muối loãng 3 phút rồi vắt nhẹ hoặc chần sơ 45 giây trong nước sôi, vớt ngay ra tô nước mát. Thao tác này giúp giữ trọn sắc màu tươi sáng tự nhiên, loại bỏ mùi ngái và tạo độ giòn ngọt thanh khiết cho món Gỏi cuốn chay.',6,'Không ngâm nấm quá lâu trong nước lạnh vì nấm sẽ hút nước mạnh làm nhạt vị ngọt umami tự nhiên.'),
(91,3,'Pha chén sốt gia vị chay chuẩn định lượng','Chuẩn bị tô nhỏ, đong chính xác 20ml nước tương và 1 quả chanh khuấy đều cùng 30ml nước ấm hoặc nước ngâm nấm hương cho tan hoàn toàn đường và hạt nêm nấm. Nếm thử thấy vị mặn ngọt hài hòa, thanh dịu đúng tinh thần ẩm thực chay cho khẩu phần 4 người. Giã đậu phộng, khuấy với nước tương, nước cốt chanh và 2 thìa nước ấm đến sánh; nếm vừa mặn chua.',4,'Pha sẵn chén sốt trước khi bật bếp giúp kiểm soát chính xác định lượng từng gam và không bị cháy khét gia vị trên chảo nóng.'),
(91,4,'Phi thơm hành boaro & tạo nền hương thảo mộc','Làm nóng nồi hoặc chảo đáy dày trên lửa vừa, cho 15ml dầu thực vật vào láng đều mặt chảo rồi trút 20g hành boaro thái lát mỏng vào phi thơm. Đảo nhẹ tay khoảng 1–2 phút đến khi hành boaro chuyển sắc vàng óng và dậy mùi thơm dịu thì hạ lửa vừa.',5,'Hành boaro cháy nhanh hơn hành tím nên chỉ phi trên lửa vừa đến khi vừa chớm vàng thơm là cho nguyên liệu chính vào ngay.');
INSERT INTO `recipe_steps` (`recipe_id`,`step_order`,`title`,`instruction`,`duration_mins`,`tip_note`) VALUES
(91,5,'Chế biến săn thấm nguyên liệu chính thuần thực vật','Cho 12 cái bánh tráng và 250g bún tươi vào đảo đều hoặc áp chảo nhẹ hai mặt trên lửa vừa đến khi bề mặt săn vàng, sau đó rưới 2/3 chén sốt gia vị chay đã pha vào. Đảo nhẹ tay để sốt bám đều quanh từng thớ đậu và nấm mà không làm vỡ nát cấu trúc nguyên liệu. Nhúng bánh tráng qua nước vừa đủ ẩm. Đặt xà lách, bún, dưa leo, đậu phụ và húng quế ở một mép.',11,'Dùng sạn gỗ đảo nhẹ từ dưới đáy chảo hất lên để miếng đậu hũ và nấm giữ nguyên hình khối vuông vắn đẹp mắt.'),
(91,6,'Phối hợp rau củ & cân chỉnh độ sánh thanh đạm','Tiếp tục cho 100g xà lách và 120g dưa leo cùng phần sốt còn lại vào nồi, điều chỉnh lửa vừa nấu thêm cho nguyên liệu chín mềm tới nhưng vẫn giữ độ giòn ngọt. Quan sát thấy nước sốt chuyển màu nâu hổ phách sóng sánh hoặc nước dùng trong thanh, hương thơm quyện đều khắp gian bếp. Gập hai cạnh vào, cuốn chặt vừa tay để bánh không rách. Dùng ngay với sốt đậu phộng; không dùng nước mắm chay.',8,'Chỉ nấu rau củ xanh vừa chín tới để bảo toàn tối đa lượng chất xơ và vitamin tự nhiên trong khẩu phần chay.'),
(91,7,'Hoàn thiện hương thơm & trình bày món chay thanh tịnh','Tắt bếp ngay khi món ăn đạt độ chín chuẩn, rắc đều 20g húng quế và 35g đậu phộng lên bề mặt để dậy mùi thơm tươi mới. Múc món Gỏi cuốn chay ra đĩa sứ hoặc tô sâu lòng, thưởng thức nóng cùng cơm trắng hoặc bún tươi cho trọn vẹn 4 khẩu phần.',4,'Rắc rau thơm và tiêu ngay lúc vừa tắt bếp giúp tinh dầu tỏa hương thơm ngát mà lá rau không bị thâm xỉn màu.'),
(92,1,'Sơ chế sạch & chuẩn bị nguyên liệu thuần chay','Rửa sạch toàn bộ nguyên liệu dưới vòi nước mát, để ráo tự nhiên trên rổ thưa gồm 250g đậu hũ và 250g khoai tây cùng 180g cà rốt và 150g nấm rơm. Cắt thái đồng đều kích thước khoảng 3–4cm vừa gắp để khi chế biến chín cùng lúc và thấm đều gia vị thực vật. Cắt đậu phụ, khoai tây và cà rốt khối vừa; rửa nấm. Đập dập sả, phần gốc băm nhỏ.',8,'Thấm khô bề mặt đậu hũ và nấm bằng khăn giấy bếp trước khi chế biến giúp nguyên liệu săn chắc, không bị bắn dầu hay ra nước.'),
(92,2,'Xử lý độ giòn ngọt của nấm & rau củ','Đối với nhóm nấm và rau củ (250g đậu hũ và 250g khoai tây), ngâm nhanh qua nước muối loãng 3 phút rồi vắt nhẹ hoặc chần sơ 45 giây trong nước sôi, vớt ngay ra tô nước mát. Thao tác này giúp giữ trọn sắc màu tươi sáng tự nhiên, loại bỏ mùi ngái và tạo độ giòn ngọt thanh khiết cho món Cà ri chay.',7,'Không ngâm nấm quá lâu trong nước lạnh vì nấm sẽ hút nước mạnh làm nhạt vị ngọt umami tự nhiên.'),
(92,3,'Pha chén sốt gia vị chay chuẩn định lượng','Chuẩn bị tô nhỏ, đong chính xác 15g bột cà ri và 4g muối khuấy đều cùng 30ml nước ấm hoặc nước ngâm nấm hương cho tan hoàn toàn đường và hạt nêm nấm. Nếm thử thấy vị mặn ngọt hài hòa, thanh dịu đúng tinh thần ẩm thực chay cho khẩu phần 4 người. Áp chảo đậu phụ vàng nhẹ, gắp ra. Xào khoai tây và cà rốt với bột cà ri, sả băm 2 phút.',6,'Pha sẵn chén sốt trước khi bật bếp giúp kiểm soát chính xác định lượng từng gam và không bị cháy khét gia vị trên chảo nóng.'),
(92,4,'Phi thơm hành boaro & tạo nền hương thảo mộc','Làm nóng nồi hoặc chảo đáy dày trên lửa vừa, cho 300ml nước cốt dừa và 300ml nước lọc vào láng đều mặt chảo rồi trút 2 cây sả vào phi thơm. Đảo nhẹ tay khoảng 1–2 phút đến khi hành boaro chuyển sắc vàng óng và dậy mùi thơm dịu thì hạ lửa vừa.',7,'Hành boaro cháy nhanh hơn hành tím nên chỉ phi trên lửa vừa đến khi vừa chớm vàng thơm là cho nguyên liệu chính vào ngay.'),
(92,5,'Chế biến săn thấm nguyên liệu chính thuần thực vật','Cho 250g đậu hũ và 250g khoai tây vào đảo đều hoặc áp chảo nhẹ hai mặt trên lửa vừa đến khi bề mặt săn vàng, sau đó rưới 2/3 chén sốt gia vị chay đã pha vào. Đảo nhẹ tay để sốt bám đều quanh từng thớ đậu và nấm mà không làm vỡ nát cấu trúc nguyên liệu. Thêm nước lọc và sả cây, đun nhỏ lửa 18 phút đến khi khoai gần mềm. Cho nấm và đậu phụ vào.',11,'Dùng sạn gỗ đảo nhẹ từ dưới đáy chảo hất lên để miếng đậu hũ và nấm giữ nguyên hình khối vuông vắn đẹp mắt.'),
(92,6,'Phối hợp rau củ & cân chỉnh độ sánh thanh đạm','Tiếp tục cho 180g cà rốt và 150g nấm rơm cùng phần sốt còn lại vào nồi, điều chỉnh lửa vừa nấu thêm cho nguyên liệu chín mềm tới nhưng vẫn giữ độ giòn ngọt. Quan sát thấy nước sốt chuyển màu nâu hổ phách sóng sánh hoặc nước dùng trong thanh, hương thơm quyện đều khắp gian bếp. Rót nước cốt dừa, nấu lăn tăn 8 phút; không để sôi mạnh làm tách dầu. Nêm muối, dùng với cơm hoặc bánh mì.',10,'Chỉ nấu rau củ xanh vừa chín tới để bảo toàn tối đa lượng chất xơ và vitamin tự nhiên trong khẩu phần chay.'),
(92,7,'Hoàn thiện hương thơm & trình bày món chay thanh tịnh','Tắt bếp ngay khi món ăn đạt độ chín chuẩn, rắc đều hành boaro lá xanh và tiêu xay lên bề mặt để dậy mùi thơm tươi mới. Múc món Cà ri chay ra đĩa sứ hoặc tô sâu lòng, thưởng thức nóng cùng cơm trắng hoặc bún tươi cho trọn vẹn 4 khẩu phần.',6,'Rắc rau thơm và tiêu ngay lúc vừa tắt bếp giúp tinh dầu tỏa hương thơm ngát mà lá rau không bị thâm xỉn màu.'),
(93,1,'Tuyển chọn, ngâm nở & sơ chế sạch nguyên liệu chè bánh','Đãi rửa sạch nhóm hạt, củ hoặc bột (200g đậu xanh cà vỏ và 15g bột năng), ngâm nước ấm theo đúng đặc tính từng loại để hạt nở mềm đồng đều và loại bỏ nhựa chát. Rửa sạch nhóm tạo hương tự nhiên gồm 2 lá lá dứa để ráo nước. Vo đậu xanh vài lần, ngâm nước ấm 1 giờ rồi để ráo. Buộc lá dứa thành bó.',10,'Thêm một nhúm muối nhỏ vào nước ngâm khoai và đậu giúp nguyên liệu giữ màu tươi sáng và khi nấu chín bùi hơn.'),
(93,2,'Ninh mềm bùi nguyên liệu chính giữ nguyên hạt/khối','Cho phần nguyên liệu nền trong 200g đậu xanh cà vỏ và 15g bột năng vào nồi đáy dày cùng lượng nước vừa đủ, đun sôi rồi hạ lửa nhỏ ninh êm đến khi chín mềm bùi nhưng không bị vỡ nát đục nước. Nếu có trân châu, bột lọc hoặc hạt lựu, luộc riêng trong nồi nước sôi đến khi nổi trong veo rồi vớt ngâm ngay vào bát nước mát. Cho đậu vào nồi với 800 ml nước và lá dứa, nấu lửa nhỏ 25 phút đến mềm nhưng hạt chưa nát.',14,'Tuyệt đối không cho đường ngay từ đầu khi đậu và khoai chưa chín mềm vì đường sẽ làm săn vỏ hạt khiến nấu mãi vẫn sượng.'),
(93,3,'Nấu nước đường phèn / mật mía thanh trong dậy hương','Kết hợp chính xác định lượng 100g đường và 2g muối vào nồi cùng bó lá dứa hoặc gừng thái chỉ, khuấy nhẹ trên lửa nhỏ cho tan trong vắt. Đun liu riu thêm 5–7 phút để vị ngọt thấm sâu vào từng viên nguyên liệu và tỏa hương thơm dịu tao nhã.',9,'Dùng đường phèn hoặc mật mía đun lửa nhỏ hớt bọt kỹ giúp hậu vị chè ngọt thanh mát họng, không bị khé cổ.'),
(93,4,'Thắng nước cốt dừa béo mịn / chuẩn bị lớp kem phủ','Cho 180ml nước cốt dừa và 1l nước lọc vào nồi nhỏ cùng 2g muối tinh và 5g bột năng/bột bắp hòa loãng, khuấy đều tay trên lửa nhỏ nhất đến khi vừa chớm sôi lăn tăn sánh mượt. Tắt bếp ngay để nước cốt dừa giữ màu trắng ngần béo ngậy mà không bị tách lớp dầu. Hòa bột năng với 50 ml nước lạnh, rót từ từ vào nồi, khuấy nhẹ. Thêm đường và muối, nấu tan.',7,'Một chút xíu muối tinh trong nồi nước cốt dừa sẽ làm bật hẳn độ béo thơm tự nhiên và cân bằng vị ngọt của món tráng miệng.'),
(93,5,'Phối hợp độ sánh mượt & cân bằng hương vị tổng thể','Hợp nhất các thành phần của món Chè đậu xanh nước cốt dừa, từ từ rưới nước bột năng hòa loãng (nếu là chè sánh) đồng thời khuấy nhẹ một chiều trên lửa nhỏ cho hỗn hợp bóng mượt như nhung. Kiểm tra độ mềm dẻo hài hòa và tắt bếp để ủ hương thảo mộc lan tỏa đều.',6,'Rót nước bột tạo sánh thành dòng mảnh vừa rót vừa khuấy đều tay giúp chè trong mượt, hoàn toàn không bị ốc trâu vón cục.'),
(93,6,'Múc ra chén sứ, điểm topping & thưởng thức ấm/lạnh','Múc chè hoặc bày bánh ra 4 chén nhỏ xinh, chan lớp nước cốt dừa trắng mịn lên mặt và rắc nhẹ mè rang, đậu phộng hoặc dừa non bào sợi. Thưởng thức ấm nóng dịu dàng hoặc thêm đá bào mát lạnh tùy sở thích đều trọn vị ngon truyền thống. Đun riêng nước cốt dừa với chút muối 3–4 phút, không để sôi mạnh. Múc chè ra bát, chan cốt dừa.',4,'Để chè nguội bớt về khoảng 45°C hoặc ướp mát 30 phút trong ngăn mát tủ lạnh giúp các tầng hương vị kết tinh đậm đà hơn.'),
(94,1,'Tuyển chọn, ngâm nở & sơ chế sạch nguyên liệu chè bánh','Đãi rửa sạch nhóm hạt, củ hoặc bột (200ml kem tươi và 150g vải ngâm), ngâm nước ấm theo đúng đặc tính từng loại để hạt nở mềm đồng đều và loại bỏ nhựa chát. Rửa sạch nhóm tạo hương tự nhiên gồm lá dứa, gừng tươi để ráo nước. Rắc gelatin lên 50 ml nước lạnh, để nở 10 phút. Đun sữa, kem và đường ở lửa nhỏ đến ấm nóng, không đun sôi.',7,'Thêm một nhúm muối nhỏ vào nước ngâm khoai và đậu giúp nguyên liệu giữ màu tươi sáng và khi nấu chín bùi hơn.'),
(94,2,'Ninh mềm bùi nguyên liệu chính giữ nguyên hạt/khối','Cho phần nguyên liệu nền trong 200ml kem tươi và 150g vải ngâm vào nồi đáy dày cùng lượng nước vừa đủ, đun sôi rồi hạ lửa nhỏ ninh êm đến khi chín mềm bùi nhưng không bị vỡ nát đục nước. Nếu có trân châu, bột lọc hoặc hạt lựu, luộc riêng trong nồi nước sôi đến khi nổi trong veo rồi vớt ngâm ngay vào bát nước mát. Tắt bếp, cho gelatin đã nở vào sữa nóng, khuấy đến tan hoàn toàn rồi thêm vani.',10,'Tuyệt đối không cho đường ngay từ đầu khi đậu và khoai chưa chín mềm vì đường sẽ làm săn vỏ hạt khiến nấu mãi vẫn sượng.'),
(94,3,'Nấu nước đường phèn / mật mía thanh trong dậy hương','Kết hợp chính xác định lượng 60g đường vào nồi cùng bó lá dứa hoặc gừng thái chỉ, khuấy nhẹ trên lửa nhỏ cho tan trong vắt. Đun liu riu thêm 5–7 phút để vị ngọt thấm sâu vào từng viên nguyên liệu và tỏa hương thơm dịu tao nhã.',6,'Dùng đường phèn hoặc mật mía đun lửa nhỏ hớt bọt kỹ giúp hậu vị chè ngọt thanh mát họng, không bị khé cổ.'),
(94,4,'Thắng nước cốt dừa béo mịn / chuẩn bị lớp kem phủ','Cho 300ml sữa tươi và 80ml nước lọc vào nồi nhỏ cùng 2g muối tinh và 5g bột năng/bột bắp hòa loãng, khuấy đều tay trên lửa nhỏ nhất đến khi vừa chớm sôi lăn tăn sánh mượt. Tắt bếp ngay để nước cốt dừa giữ màu trắng ngần béo ngậy mà không bị tách lớp dầu. Lọc hỗn hợp qua rây, đổ khuôn và làm nguội. Bọc kín, để tủ lạnh ít nhất 4 giờ đến khi đông mềm.',5,'Một chút xíu muối tinh trong nồi nước cốt dừa sẽ làm bật hẳn độ béo thơm tự nhiên và cân bằng vị ngọt của món tráng miệng.'),
(94,5,'Phối hợp độ sánh mượt & cân bằng hương vị tổng thể','Hợp nhất các thành phần của món Chè khúc bạch, từ từ rưới nước bột năng hòa loãng (nếu là chè sánh) đồng thời khuấy nhẹ một chiều trên lửa nhỏ cho hỗn hợp bóng mượt như nhung. Kiểm tra độ mềm dẻo hài hòa và tắt bếp để ủ hương thảo mộc lan tỏa đều.',4,'Rót nước bột tạo sánh thành dòng mảnh vừa rót vừa khuấy đều tay giúp chè trong mượt, hoàn toàn không bị ốc trâu vón cục.'),
(94,6,'Múc ra chén sứ, điểm topping & thưởng thức ấm/lạnh','Múc chè hoặc bày bánh ra 4 chén nhỏ xinh, chan lớp nước cốt dừa trắng mịn lên mặt và rắc nhẹ mè rang, đậu phộng hoặc dừa non bào sợi. Thưởng thức ấm nóng dịu dàng hoặc thêm đá bào mát lạnh tùy sở thích đều trọn vị ngon truyền thống. Rang hạnh nhân lát đến vàng thơm. Cắt khúc bạch, dùng với vải và nước vải pha thêm nước lạnh; ăn lạnh.',3,'Để chè nguội bớt về khoảng 45°C hoặc ướp mát 30 phút trong ngăn mát tủ lạnh giúp các tầng hương vị kết tinh đậm đà hơn.'),
(95,1,'Tuyển chọn, ngâm nở & sơ chế sạch nguyên liệu chè bánh','Đãi rửa sạch nhóm hạt, củ hoặc bột (500g chuối sứ và 40g bột báng), ngâm nước ấm theo đúng đặc tính từng loại để hạt nở mềm đồng đều và loại bỏ nhựa chát. Rửa sạch nhóm tạo hương tự nhiên gồm 2 lá lá dứa để ráo nước. Ngâm bột báng trong nước 15 phút rồi để ráo. Bóc chuối, cắt khúc dày 2 cm; rang và giã đậu phộng.',8,'Thêm một nhúm muối nhỏ vào nước ngâm khoai và đậu giúp nguyên liệu giữ màu tươi sáng và khi nấu chín bùi hơn.'),
(95,2,'Ninh mềm bùi nguyên liệu chính giữ nguyên hạt/khối','Cho phần nguyên liệu nền trong 500g chuối sứ và 40g bột báng vào nồi đáy dày cùng lượng nước vừa đủ, đun sôi rồi hạ lửa nhỏ ninh êm đến khi chín mềm bùi nhưng không bị vỡ nát đục nước. Nếu có trân châu, bột lọc hoặc hạt lựu, luộc riêng trong nồi nước sôi đến khi nổi trong veo rồi vớt ngâm ngay vào bát nước mát. Đun nước với lá dứa và đường, cho chuối vào nấu lửa nhỏ 8–10 phút đến mềm nhưng còn nguyên miếng.',11,'Tuyệt đối không cho đường ngay từ đầu khi đậu và khoai chưa chín mềm vì đường sẽ làm săn vỏ hạt khiến nấu mãi vẫn sượng.'),
(95,3,'Nấu nước đường phèn / mật mía thanh trong dậy hương','Kết hợp chính xác định lượng 70g đường và 2g muối vào nồi cùng bó lá dứa hoặc gừng thái chỉ, khuấy nhẹ trên lửa nhỏ cho tan trong vắt. Đun liu riu thêm 5–7 phút để vị ngọt thấm sâu vào từng viên nguyên liệu và tỏa hương thơm dịu tao nhã.',7,'Dùng đường phèn hoặc mật mía đun lửa nhỏ hớt bọt kỹ giúp hậu vị chè ngọt thanh mát họng, không bị khé cổ.');
INSERT INTO `recipe_steps` (`recipe_id`,`step_order`,`title`,`instruction`,`duration_mins`,`tip_note`) VALUES
(95,4,'Thắng nước cốt dừa béo mịn / chuẩn bị lớp kem phủ','Cho 250ml nước cốt dừa và 600ml nước lọc vào nồi nhỏ cùng 2g muối tinh và 5g bột năng/bột bắp hòa loãng, khuấy đều tay trên lửa nhỏ nhất đến khi vừa chớm sôi lăn tăn sánh mượt. Tắt bếp ngay để nước cốt dừa giữ màu trắng ngần béo ngậy mà không bị tách lớp dầu. Thêm bột báng, khuấy nhẹ để không dính đáy; nấu đến khi hạt trong gần hết.',6,'Một chút xíu muối tinh trong nồi nước cốt dừa sẽ làm bật hẳn độ béo thơm tự nhiên và cân bằng vị ngọt của món tráng miệng.'),
(95,5,'Phối hợp độ sánh mượt & cân bằng hương vị tổng thể','Hợp nhất các thành phần của món Chè chuối, từ từ rưới nước bột năng hòa loãng (nếu là chè sánh) đồng thời khuấy nhẹ một chiều trên lửa nhỏ cho hỗn hợp bóng mượt như nhung. Kiểm tra độ mềm dẻo hài hòa và tắt bếp để ủ hương thảo mộc lan tỏa đều.',5,'Rót nước bột tạo sánh thành dòng mảnh vừa rót vừa khuấy đều tay giúp chè trong mượt, hoàn toàn không bị ốc trâu vón cục.'),
(95,6,'Múc ra chén sứ, điểm topping & thưởng thức ấm/lạnh','Múc chè hoặc bày bánh ra 4 chén nhỏ xinh, chan lớp nước cốt dừa trắng mịn lên mặt và rắc nhẹ 30g đậu phộng. Thưởng thức ấm nóng dịu dàng hoặc thêm đá bào mát lạnh tùy sở thích đều trọn vị ngon truyền thống. Rót nước cốt dừa và chút muối, đun lăn tăn 3 phút rồi tắt bếp. Bỏ lá dứa, rắc đậu phộng khi ăn.',3,'Để chè nguội bớt về khoảng 45°C hoặc ướp mát 30 phút trong ngăn mát tủ lạnh giúp các tầng hương vị kết tinh đậm đà hơn.'),
(96,1,'Tuyển chọn, ngâm nở & sơ chế sạch nguyên liệu chè bánh','Đãi rửa sạch nhóm hạt, củ hoặc bột (250g đậu đen), ngâm nước ấm theo đúng đặc tính từng loại để hạt nở mềm đồng đều và loại bỏ nhựa chát. Rửa sạch nhóm tạo hương tự nhiên gồm 2 lá lá dứa và 10g gừng để ráo nước. Nhặt bỏ hạt lép, vo sạch và ngâm đậu đen qua đêm hoặc ít nhất 6 giờ; chắt bỏ nước ngâm.',13,'Thêm một nhúm muối nhỏ vào nước ngâm khoai và đậu giúp nguyên liệu giữ màu tươi sáng và khi nấu chín bùi hơn.'),
(96,2,'Ninh mềm bùi nguyên liệu chính giữ nguyên hạt/khối','Cho phần nguyên liệu nền trong 250g đậu đen vào nồi đáy dày cùng lượng nước vừa đủ, đun sôi rồi hạ lửa nhỏ ninh êm đến khi chín mềm bùi nhưng không bị vỡ nát đục nước. Nếu có trân châu, bột lọc hoặc hạt lựu, luộc riêng trong nồi nước sôi đến khi nổi trong veo rồi vớt ngâm ngay vào bát nước mát. Cho đậu vào nồi với nước mới, lá dứa và gừng nếu dùng. Ninh nhỏ lửa 45–55 phút đến khi hạt mềm.',18,'Tuyệt đối không cho đường ngay từ đầu khi đậu và khoai chưa chín mềm vì đường sẽ làm săn vỏ hạt khiến nấu mãi vẫn sượng.'),
(96,3,'Nấu nước đường phèn / mật mía thanh trong dậy hương','Kết hợp chính xác định lượng 120g đường và 2g muối vào nồi cùng bó lá dứa hoặc gừng thái chỉ, khuấy nhẹ trên lửa nhỏ cho tan trong vắt. Đun liu riu thêm 5–7 phút để vị ngọt thấm sâu vào từng viên nguyên liệu và tỏa hương thơm dịu tao nhã.',12,'Dùng đường phèn hoặc mật mía đun lửa nhỏ hớt bọt kỹ giúp hậu vị chè ngọt thanh mát họng, không bị khé cổ.'),
(96,4,'Thắng nước cốt dừa béo mịn / chuẩn bị lớp kem phủ','Cho 150ml nước cốt dừa và 1.5l nước lọc vào nồi nhỏ cùng 2g muối tinh và 5g bột năng/bột bắp hòa loãng, khuấy đều tay trên lửa nhỏ nhất đến khi vừa chớm sôi lăn tăn sánh mượt. Tắt bếp ngay để nước cốt dừa giữ màu trắng ngần béo ngậy mà không bị tách lớp dầu. Vớt đậu ra chảo, trộn đường và chút muối, đun lửa nhỏ 5 phút để đường bám hạt; đổ lại vào nồi nước.',9,'Một chút xíu muối tinh trong nồi nước cốt dừa sẽ làm bật hẳn độ béo thơm tự nhiên và cân bằng vị ngọt của món tráng miệng.'),
(96,5,'Phối hợp độ sánh mượt & cân bằng hương vị tổng thể','Hợp nhất các thành phần của món Chè đậu đen, từ từ rưới nước bột năng hòa loãng (nếu là chè sánh) đồng thời khuấy nhẹ một chiều trên lửa nhỏ cho hỗn hợp bóng mượt như nhung. Kiểm tra độ mềm dẻo hài hòa và tắt bếp để ủ hương thảo mộc lan tỏa đều.',8,'Rót nước bột tạo sánh thành dòng mảnh vừa rót vừa khuấy đều tay giúp chè trong mượt, hoàn toàn không bị ốc trâu vón cục.'),
(96,6,'Múc ra chén sứ, điểm topping & thưởng thức ấm/lạnh','Múc chè hoặc bày bánh ra 4 chén nhỏ xinh, chan lớp nước cốt dừa trắng mịn lên mặt và rắc nhẹ mè rang, đậu phộng hoặc dừa non bào sợi. Thưởng thức ấm nóng dịu dàng hoặc thêm đá bào mát lạnh tùy sở thích đều trọn vị ngon truyền thống. Đun sôi nhẹ chè 3 phút rồi nếm độ ngọt. Múc ra bát, chan cốt dừa; có thể làm lạnh trước khi dùng.',5,'Để chè nguội bớt về khoảng 45°C hoặc ướp mát 30 phút trong ngăn mát tủ lạnh giúp các tầng hương vị kết tinh đậm đà hơn.'),
(97,1,'Tuyển chọn, ngâm nở & sơ chế sạch nguyên liệu chè bánh','Đãi rửa sạch nhóm hạt, củ hoặc bột (200g nếp cẩm và 400g sữa chua), ngâm nước ấm theo đúng đặc tính từng loại để hạt nở mềm đồng đều và loại bỏ nhựa chát. Rửa sạch nhóm tạo hương tự nhiên gồm 2 lá lá dứa để ráo nước. Vo nếp cẩm đến nước bớt đục, ngâm 4–6 giờ rồi để ráo. Buộc lá dứa thành bó.',12,'Thêm một nhúm muối nhỏ vào nước ngâm khoai và đậu giúp nguyên liệu giữ màu tươi sáng và khi nấu chín bùi hơn.'),
(97,2,'Ninh mềm bùi nguyên liệu chính giữ nguyên hạt/khối','Cho phần nguyên liệu nền trong 200g nếp cẩm và 400g sữa chua vào nồi đáy dày cùng lượng nước vừa đủ, đun sôi rồi hạ lửa nhỏ ninh êm đến khi chín mềm bùi nhưng không bị vỡ nát đục nước. Nếu có trân châu, bột lọc hoặc hạt lựu, luộc riêng trong nồi nước sôi đến khi nổi trong veo rồi vớt ngâm ngay vào bát nước mát. Cho nếp vào nồi với 700 ml nước và lá dứa, nấu nhỏ lửa 35–40 phút; khuấy đáy nồi thỉnh thoảng.',17,'Tuyệt đối không cho đường ngay từ đầu khi đậu và khoai chưa chín mềm vì đường sẽ làm săn vỏ hạt khiến nấu mãi vẫn sượng.'),
(97,3,'Nấu nước đường phèn / mật mía thanh trong dậy hương','Kết hợp chính xác định lượng 80g đường và 2g muối vào nồi cùng bó lá dứa hoặc gừng thái chỉ, khuấy nhẹ trên lửa nhỏ cho tan trong vắt. Đun liu riu thêm 5–7 phút để vị ngọt thấm sâu vào từng viên nguyên liệu và tỏa hương thơm dịu tao nhã.',11,'Dùng đường phèn hoặc mật mía đun lửa nhỏ hớt bọt kỹ giúp hậu vị chè ngọt thanh mát họng, không bị khé cổ.'),
(97,4,'Thắng nước cốt dừa béo mịn / chuẩn bị lớp kem phủ','Cho 100ml nước cốt dừa và 900ml nước lọc vào nồi nhỏ cùng 2g muối tinh và 5g bột năng/bột bắp hòa loãng, khuấy đều tay trên lửa nhỏ nhất đến khi vừa chớm sôi lăn tăn sánh mượt. Tắt bếp ngay để nước cốt dừa giữ màu trắng ngần béo ngậy mà không bị tách lớp dầu. Khi hạt nếp mềm dẻo, thêm đường và muối, nấu 5 phút cho tan. Để nguội hoàn toàn trước khi ghép với sữa chua.',8,'Một chút xíu muối tinh trong nồi nước cốt dừa sẽ làm bật hẳn độ béo thơm tự nhiên và cân bằng vị ngọt của món tráng miệng.'),
(97,5,'Phối hợp độ sánh mượt & cân bằng hương vị tổng thể','Hợp nhất các thành phần của món Sữa chua nếp cẩm, từ từ rưới nước bột năng hòa loãng (nếu là chè sánh) đồng thời khuấy nhẹ một chiều trên lửa nhỏ cho hỗn hợp bóng mượt như nhung. Kiểm tra độ mềm dẻo hài hòa và tắt bếp để ủ hương thảo mộc lan tỏa đều.',7,'Rót nước bột tạo sánh thành dòng mảnh vừa rót vừa khuấy đều tay giúp chè trong mượt, hoàn toàn không bị ốc trâu vón cục.'),
(97,6,'Múc ra chén sứ, điểm topping & thưởng thức ấm/lạnh','Múc chè hoặc bày bánh ra 4 chén nhỏ xinh, chan lớp nước cốt dừa trắng mịn lên mặt và rắc nhẹ mè rang, đậu phộng hoặc dừa non bào sợi. Thưởng thức ấm nóng dịu dàng hoặc thêm đá bào mát lạnh tùy sở thích đều trọn vị ngon truyền thống. Múc nếp cẩm vào cốc, thêm sữa chua lạnh và một ít nước cốt dừa. Bảo quản phần còn lại trong hộp kín ở ngăn mát.',5,'Để chè nguội bớt về khoảng 45°C hoặc ướp mát 30 phút trong ngăn mát tủ lạnh giúp các tầng hương vị kết tinh đậm đà hơn.'),
(98,1,'Tuyển chọn, ngâm nở & sơ chế sạch nguyên liệu chè bánh','Đãi rửa sạch nhóm hạt, củ hoặc bột (10g bột rau câu), ngâm nước ấm theo đúng đặc tính từng loại để hạt nở mềm đồng đều và loại bỏ nhựa chát. Rửa sạch nhóm tạo hương tự nhiên gồm 2 lá lá dứa để ráo nước. Chia bột rau câu và đường làm hai phần. Trộn khô từng phần để bột không vón khi cho vào chất lỏng.',6,'Thêm một nhúm muối nhỏ vào nước ngâm khoai và đậu giúp nguyên liệu giữ màu tươi sáng và khi nấu chín bùi hơn.'),
(98,2,'Ninh mềm bùi nguyên liệu chính giữ nguyên hạt/khối','Cho phần nguyên liệu nền trong 10g bột rau câu vào nồi đáy dày cùng lượng nước vừa đủ, đun sôi rồi hạ lửa nhỏ ninh êm đến khi chín mềm bùi nhưng không bị vỡ nát đục nước. Nếu có trân châu, bột lọc hoặc hạt lựu, luộc riêng trong nồi nước sôi đến khi nổi trong veo rồi vớt ngâm ngay vào bát nước mát. Đun nước dừa với lá dứa, rắc một phần bột đường vào từ từ và khuấy liên tục. Sôi nhẹ 2 phút thì bỏ lá.',9,'Tuyệt đối không cho đường ngay từ đầu khi đậu và khoai chưa chín mềm vì đường sẽ làm săn vỏ hạt khiến nấu mãi vẫn sượng.'),
(98,3,'Nấu nước đường phèn / mật mía thanh trong dậy hương','Kết hợp chính xác định lượng 100g đường và 2g muối vào nồi cùng bó lá dứa hoặc gừng thái chỉ, khuấy nhẹ trên lửa nhỏ cho tan trong vắt. Đun liu riu thêm 5–7 phút để vị ngọt thấm sâu vào từng viên nguyên liệu và tỏa hương thơm dịu tao nhã.',5,'Dùng đường phèn hoặc mật mía đun lửa nhỏ hớt bọt kỹ giúp hậu vị chè ngọt thanh mát họng, không bị khé cổ.'),
(98,4,'Thắng nước cốt dừa béo mịn / chuẩn bị lớp kem phủ','Cho 700ml nước dừa tươi và 250ml nước cốt dừa vào nồi nhỏ cùng 2g muối tinh và 5g bột năng/bột bắp hòa loãng, khuấy đều tay trên lửa nhỏ nhất đến khi vừa chớm sôi lăn tăn sánh mượt. Tắt bếp ngay để nước cốt dừa giữ màu trắng ngần béo ngậy mà không bị tách lớp dầu. Đun nước cốt dừa cùng phần bột đường còn lại và chút muối, khuấy đến sôi nhẹ 2 phút.',4,'Một chút xíu muối tinh trong nồi nước cốt dừa sẽ làm bật hẳn độ béo thơm tự nhiên và cân bằng vị ngọt của món tráng miệng.'),
(98,5,'Phối hợp độ sánh mượt & cân bằng hương vị tổng thể','Hợp nhất các thành phần của món Rau câu dừa, từ từ rưới nước bột năng hòa loãng (nếu là chè sánh) đồng thời khuấy nhẹ một chiều trên lửa nhỏ cho hỗn hợp bóng mượt như nhung. Kiểm tra độ mềm dẻo hài hòa và tắt bếp để ủ hương thảo mộc lan tỏa đều.',4,'Rót nước bột tạo sánh thành dòng mảnh vừa rót vừa khuấy đều tay giúp chè trong mượt, hoàn toàn không bị ốc trâu vón cục.'),
(98,6,'Múc ra chén sứ, điểm topping & thưởng thức ấm/lạnh','Múc chè hoặc bày bánh ra 4 chén nhỏ xinh, chan lớp nước cốt dừa trắng mịn lên mặt và rắc nhẹ mè rang, đậu phộng hoặc dừa non bào sợi. Thưởng thức ấm nóng dịu dàng hoặc thêm đá bào mát lạnh tùy sở thích đều trọn vị ngon truyền thống. Rót lớp nước dừa vào khuôn, chờ se mặt nhưng còn ấm rồi rót lớp cốt dừa. Để nguội, làm lạnh 2 giờ trước khi cắt.',2,'Để chè nguội bớt về khoảng 45°C hoặc ướp mát 30 phút trong ngăn mát tủ lạnh giúp các tầng hương vị kết tinh đậm đà hơn.'),
(99,1,'Tuyển chọn, ngâm nở & sơ chế sạch nguyên liệu chè bánh','Đãi rửa sạch nhóm hạt, củ hoặc bột (4 quả trứng gà), ngâm nước ấm theo đúng đặc tính từng loại để hạt nở mềm đồng đều và loại bỏ nhựa chát. Rửa sạch nhóm tạo hương tự nhiên gồm lá dứa, gừng tươi để ráo nước. Đun đường với nước ở lửa vừa, không khuấy; lắc nhẹ nồi đến màu hổ phách. Rót ngay một lớp mỏng vào khuôn.',11,'Thêm một nhúm muối nhỏ vào nước ngâm khoai và đậu giúp nguyên liệu giữ màu tươi sáng và khi nấu chín bùi hơn.'),
(99,2,'Ninh mềm bùi nguyên liệu chính giữ nguyên hạt/khối','Cho phần nguyên liệu nền trong 4 quả trứng gà vào nồi đáy dày cùng lượng nước vừa đủ, đun sôi rồi hạ lửa nhỏ ninh êm đến khi chín mềm bùi nhưng không bị vỡ nát đục nước. Nếu có trân châu, bột lọc hoặc hạt lựu, luộc riêng trong nồi nước sôi đến khi nổi trong veo rồi vớt ngâm ngay vào bát nước mát. Làm ấm sữa tươi với sữa đặc và muối, không đun sôi. Đánh trứng nhẹ tay rồi rót sữa ấm vào từ từ, thêm vani.',15,'Tuyệt đối không cho đường ngay từ đầu khi đậu và khoai chưa chín mềm vì đường sẽ làm săn vỏ hạt khiến nấu mãi vẫn sượng.'),
(99,3,'Nấu nước đường phèn / mật mía thanh trong dậy hương','Kết hợp chính xác định lượng 80g đường và 1g muối vào nồi cùng bó lá dứa hoặc gừng thái chỉ, khuấy nhẹ trên lửa nhỏ cho tan trong vắt. Đun liu riu thêm 5–7 phút để vị ngọt thấm sâu vào từng viên nguyên liệu và tỏa hương thơm dịu tao nhã.',10,'Dùng đường phèn hoặc mật mía đun lửa nhỏ hớt bọt kỹ giúp hậu vị chè ngọt thanh mát họng, không bị khé cổ.'),
(99,4,'Thắng nước cốt dừa béo mịn / chuẩn bị lớp kem phủ','Cho 400ml sữa tươi và 100ml sữa đặc vào nồi nhỏ cùng 2g muối tinh và 5g bột năng/bột bắp hòa loãng, khuấy đều tay trên lửa nhỏ nhất đến khi vừa chớm sôi lăn tăn sánh mượt. Tắt bếp ngay để nước cốt dừa giữ màu trắng ngần béo ngậy mà không bị tách lớp dầu. Lọc hỗn hợp qua rây, rót vào khuôn. Đặt khuôn vào nồi hấp nước sôi lăn tăn, phủ khăn dưới nắp và hấp 25–30 phút.',8,'Một chút xíu muối tinh trong nồi nước cốt dừa sẽ làm bật hẳn độ béo thơm tự nhiên và cân bằng vị ngọt của món tráng miệng.');
INSERT INTO `recipe_steps` (`recipe_id`,`step_order`,`title`,`instruction`,`duration_mins`,`tip_note`) VALUES
(99,5,'Phối hợp độ sánh mượt & cân bằng hương vị tổng thể','Hợp nhất các thành phần của món Bánh flan caramel, từ từ rưới nước bột năng hòa loãng (nếu là chè sánh) đồng thời khuấy nhẹ một chiều trên lửa nhỏ cho hỗn hợp bóng mượt như nhung. Kiểm tra độ mềm dẻo hài hòa và tắt bếp để ủ hương thảo mộc lan tỏa đều.',7,'Rót nước bột tạo sánh thành dòng mảnh vừa rót vừa khuấy đều tay giúp chè trong mượt, hoàn toàn không bị ốc trâu vón cục.'),
(99,6,'Múc ra chén sứ, điểm topping & thưởng thức ấm/lạnh','Múc chè hoặc bày bánh ra 4 chén nhỏ xinh, chan lớp nước cốt dừa trắng mịn lên mặt và rắc nhẹ mè rang, đậu phộng hoặc dừa non bào sợi. Thưởng thức ấm nóng dịu dàng hoặc thêm đá bào mát lạnh tùy sở thích đều trọn vị ngon truyền thống. Bánh đạt khi tâm vừa đông, còn rung nhẹ; để nguội rồi làm lạnh ít nhất 3 giờ. Úp khuôn khi dùng để caramel phủ mặt.',4,'Để chè nguội bớt về khoảng 45°C hoặc ướp mát 30 phút trong ngăn mát tủ lạnh giúp các tầng hương vị kết tinh đậm đà hơn.'),
(100,1,'Tuyển chọn, ngâm nở & sơ chế sạch nguyên liệu chè bánh','Đãi rửa sạch nhóm hạt, củ hoặc bột (500g chuối sứ và 120g bột gạo), ngâm nước ấm theo đúng đặc tính từng loại để hạt nở mềm đồng đều và loại bỏ nhựa chát. Rửa sạch nhóm tạo hương tự nhiên gồm lá dứa, gừng tươi để ráo nước. Bóc chuối, cắt lát dày 5 mm. Giữ lại vài lát đẹp để xếp mặt khuôn.',11,'Thêm một nhúm muối nhỏ vào nước ngâm khoai và đậu giúp nguyên liệu giữ màu tươi sáng và khi nấu chín bùi hơn.'),
(100,2,'Ninh mềm bùi nguyên liệu chính giữ nguyên hạt/khối','Cho phần nguyên liệu nền trong 500g chuối sứ và 120g bột gạo vào nồi đáy dày cùng lượng nước vừa đủ, đun sôi rồi hạ lửa nhỏ ninh êm đến khi chín mềm bùi nhưng không bị vỡ nát đục nước. Nếu có trân châu, bột lọc hoặc hạt lựu, luộc riêng trong nồi nước sôi đến khi nổi trong veo rồi vớt ngâm ngay vào bát nước mát. Trộn bột gạo, bột năng, đường, muối và 150 ml nước cốt dừa thành hỗn hợp sệt. Gập phần chuối vào nhẹ tay.',15,'Tuyệt đối không cho đường ngay từ đầu khi đậu và khoai chưa chín mềm vì đường sẽ làm săn vỏ hạt khiến nấu mãi vẫn sượng.'),
(100,3,'Nấu nước đường phèn / mật mía thanh trong dậy hương','Kết hợp chính xác định lượng 70g đường và 2g muối vào nồi cùng bó lá dứa hoặc gừng thái chỉ, khuấy nhẹ trên lửa nhỏ cho tan trong vắt. Đun liu riu thêm 5–7 phút để vị ngọt thấm sâu vào từng viên nguyên liệu và tỏa hương thơm dịu tao nhã.',10,'Dùng đường phèn hoặc mật mía đun lửa nhỏ hớt bọt kỹ giúp hậu vị chè ngọt thanh mát họng, không bị khé cổ.'),
(100,4,'Thắng nước cốt dừa béo mịn / chuẩn bị lớp kem phủ','Cho 250ml nước cốt dừa và 5ml dầu ăn vào nồi nhỏ cùng 2g muối tinh và 5g bột năng/bột bắp hòa loãng, khuấy đều tay trên lửa nhỏ nhất đến khi vừa chớm sôi lăn tăn sánh mượt. Tắt bếp ngay để nước cốt dừa giữ màu trắng ngần béo ngậy mà không bị tách lớp dầu. Quét dầu mỏng khuôn, đổ bột dày khoảng 3 cm, xếp lát chuối lên mặt. Hấp 30–35 phút đến khi bánh trong và xiên tăm sạch.',8,'Một chút xíu muối tinh trong nồi nước cốt dừa sẽ làm bật hẳn độ béo thơm tự nhiên và cân bằng vị ngọt của món tráng miệng.'),
(100,5,'Phối hợp độ sánh mượt & cân bằng hương vị tổng thể','Hợp nhất các thành phần của món Bánh chuối hấp nước cốt dừa, từ từ rưới nước bột năng hòa loãng (nếu là chè sánh) đồng thời khuấy nhẹ một chiều trên lửa nhỏ cho hỗn hợp bóng mượt như nhung. Kiểm tra độ mềm dẻo hài hòa và tắt bếp để ủ hương thảo mộc lan tỏa đều.',7,'Rót nước bột tạo sánh thành dòng mảnh vừa rót vừa khuấy đều tay giúp chè trong mượt, hoàn toàn không bị ốc trâu vón cục.'),
(100,6,'Múc ra chén sứ, điểm topping & thưởng thức ấm/lạnh','Múc chè hoặc bày bánh ra 4 chén nhỏ xinh, chan lớp nước cốt dừa trắng mịn lên mặt và rắc nhẹ 10g mè rang. Thưởng thức ấm nóng dịu dàng hoặc thêm đá bào mát lạnh tùy sở thích đều trọn vị ngon truyền thống. Đun phần cốt dừa còn lại với chút muối đến sôi lăn tăn. Để bánh nguội bớt, cắt miếng, rưới cốt dừa và rắc mè.',4,'Để chè nguội bớt về khoảng 45°C hoặc ướp mát 30 phút trong ngăn mát tủ lạnh giúp các tầng hương vị kết tinh đậm đà hơn.'),
(101,1,'Tuyển chọn & sơ chế tươi sạch nguyên liệu pha chế','Rửa sạch kỹ các nguyên liệu tươi gồm 2 quả chanh và 30ml mật ong và rau củ ăn kèm, để ráo nước hoàn toàn trên khay sạch. Cắt lát, đập dập hoặc đong chuẩn xác từng gam/ml nguyên liệu cho khẩu phần 2 ly để hương vị đồng nhất tuyệt đối. Rửa chanh, lăn nhẹ trên bàn để dễ ra nước rồi vắt lấy nước cốt; lọc bỏ hạt.',6,'Loại bỏ kỹ hạt chanh, tắc trước khi vắt hoặc nấu giúp thức uống giữ hậu vị thanh ngọt mà không hề bị đắng vỏ.'),
(101,2,'Ủ chiết xuất nền trà, cà phê hoặc nấu cốt thảo mộc','Đun nước đạt nhiệt độ chuẩn 90–95°C (không dùng nước sôi sùng sục làm cháy hương), tiến hành ủ chiết xuất hoặc nấu nhỏ lửa 2 quả chanh và 30ml mật ong trong thời gian quy định. Lọc qua rây mịn hoặc túi vải sạch để thu được phần nước cốt trong trẻo, đậm hương tự nhiên không gợn cặn. Khuấy mật ong với 100 ml nước ấm vừa, thêm chút muối cho vị chanh dịu hơn.',9,'Ủ trà/cà phê đúng nhiệt độ 92°C và đậy nắp kín giúp thu trọn tinh dầu thơm quyến rũ mà không chiết xuất vị chát gắt.'),
(101,3,'Xử lý lớp kem bông mịn / hỗn hợp sữa & trái cây','Đánh bông mượt hoặc khuấy hòa quyện phần nguyên liệu bổ trợ (600ml nước lọc và 200g đá viên) cùng 2 quả chanh, 30ml mật ong, 1g muối và 15g đường đến khi sánh mịn đồng nhất. Kiểm soát tốc độ khuấy/đánh đều tay để tạo kết cấu bồng bềnh mượt mà hoặc hòa tan hoàn toàn đường phèn mật ong. Rót phần nước còn lại và nước cốt chanh vào, khuấy đều. Nếm rồi điều chỉnh thêm nước nếu chua gắt.',6,'Nếu đánh kem trứng, nghiêng nhẹ âu 45 độ và đánh một chiều tốc độ cao cho tới khi nhấc que tạo chóp mềm bóng mượt không tanh.'),
(101,4,'Cân chỉnh định lượng độ ngọt & tầng hương tươi mát','Phối trộn phần nước cốt nền cùng hỗn hợp tạo vị theo đúng tỷ lệ vàng của món Nước chanh mật ong, khuấy nhẹ để các tầng hương hòa quyện. Nếu có nước cốt chanh hoặc mật ong rừng, cho vào khi nền nước đã hạ xuống dưới 55°C để bảo toàn trọn vẹn vitamin và hương thơm.',4,'Nếm thử trước khi thêm đá viên sao cho vị đậm hơn khoảng 15% để khi đá tan nhẹ là vừa vặn hoàn hảo.'),
(101,5,'Phối tầng thẩm mỹ ra ly thủy tinh nóng hoặc đá mát','Tráng ấm ly gốm (nếu dùng nóng) hoặc cho lượng đá viên tinh khiết vừa đủ vào ly thủy tinh cao, rót từ từ cốt thức uống vào 2/3 ly. Nhẹ nhàng rót lớp kem/sữa hoặc xếp lát trái cây tươi áp sát thành ly tạo hiệu ứng phân tầng đẹp mắt như quán chuyên nghiệp.',3,'Rót lớp kem hoặc sữa nhẹ nhàng qua lưng muỗng inox giúp hai tầng màu tách bạch sắc nét cực kỳ cuốn hút.'),
(101,6,'Điểm xuyết lá thơm trang trí & thưởng thức ngay','Trang trí trên mặt ly bằng lát nguyên liệu tươi, nhánh bạc hà/lá dứa hoặc rắc nhẹ bột cacao/hạt chia cho món Nước chanh mật ong thêm phần sinh động. Phục vụ ngay khi vừa pha chế xong cho 2 người để tận hưởng trọn vẹn hương thơm tươi mới sảng khoái nhất. Thêm đá ngay trước khi uống. Không rót mật ong vào nước quá nóng để giữ hương thơm tự nhiên.',2,'Vỗ nhẹ lá bạc hà trong lòng bàn tay trước khi đặt lên miệng ly sẽ đánh thức tinh dầu the mát lan tỏa ngay khi nâng ly.'),
(102,1,'Tuyển chọn & sơ chế tươi sạch nguyên liệu pha chế','Rửa sạch kỹ các nguyên liệu tươi gồm 8g trà đen và 180g đào ngâm và 2 cây sả, để ráo nước hoàn toàn trên khay sạch. Cắt lát, đập dập hoặc đong chuẩn xác từng gam/ml nguyên liệu cho khẩu phần 4 ly để hương vị đồng nhất tuyệt đối. Đun nước đến khoảng 90–95°C, rót lên trà đen và ủ 4 phút rồi lọc bã để trà không bị chát.',4,'Loại bỏ kỹ hạt chanh, tắc trước khi vắt hoặc nấu giúp thức uống giữ hậu vị thanh ngọt mà không hề bị đắng vỏ.'),
(102,2,'Ủ chiết xuất nền trà, cà phê hoặc nấu cốt thảo mộc','Đun nước đạt nhiệt độ chuẩn 90–95°C (không dùng nước sôi sùng sục làm cháy hương), tiến hành ủ chiết xuất hoặc nấu nhỏ lửa 8g trà đen và 180g đào ngâm trong thời gian quy định. Lọc qua rây mịn hoặc túi vải sạch để thu được phần nước cốt trong trẻo, đậm hương tự nhiên không gợn cặn. Đập dập sả, cho vào nồi với 150 ml nước và đường, đun nhỏ lửa 5 phút; để nguội rồi lọc.',7,'Ủ trà/cà phê đúng nhiệt độ 92°C và đậy nắp kín giúp thu trọn tinh dầu thơm quyến rũ mà không chiết xuất vị chát gắt.'),
(102,3,'Xử lý lớp kem bông mịn / hỗn hợp sữa & trái cây','Đánh bông mượt hoặc khuấy hòa quyện phần nguyên liệu bổ trợ (1 quả cam) cùng 25g đường đến khi sánh mịn đồng nhất. Kiểm soát tốc độ khuấy/đánh đều tay để tạo kết cấu bồng bềnh mượt mà hoặc hòa tan hoàn toàn đường phèn mật ong. Trộn trà với nước sả và một ít nước đào ngâm. Nếm vị ngọt, để lạnh 30 phút.',4,'Nếu đánh kem trứng, nghiêng nhẹ âu 45 độ và đánh một chiều tốc độ cao cho tới khi nhấc que tạo chóp mềm bóng mượt không tanh.'),
(102,4,'Cân chỉnh định lượng độ ngọt & tầng hương tươi mát','Phối trộn phần nước cốt nền cùng hỗn hợp tạo vị theo đúng tỷ lệ vàng của món Trà đào cam sả, khuấy nhẹ để các tầng hương hòa quyện. Nếu có nước cốt chanh hoặc mật ong rừng, cho vào khi nền nước đã hạ xuống dưới 55°C để bảo toàn trọn vẹn vitamin và hương thơm.',3,'Nếm thử trước khi thêm đá viên sao cho vị đậm hơn khoảng 15% để khi đá tan nhẹ là vừa vặn hoàn hảo.'),
(102,5,'Phối tầng thẩm mỹ ra ly thủy tinh nóng hoặc đá mát','Tráng ấm ly gốm (nếu dùng nóng) hoặc cho lượng đá viên tinh khiết vừa đủ vào ly thủy tinh cao, rót từ từ cốt thức uống vào 2/3 ly. Nhẹ nhàng rót lớp kem/sữa hoặc xếp lát trái cây tươi áp sát thành ly tạo hiệu ứng phân tầng đẹp mắt như quán chuyên nghiệp.',2,'Rót lớp kem hoặc sữa nhẹ nhàng qua lưng muỗng inox giúp hai tầng màu tách bạch sắc nét cực kỳ cuốn hút.'),
(102,6,'Điểm xuyết lá thơm trang trí & thưởng thức ngay','Trang trí trên mặt ly bằng lát nguyên liệu tươi, nhánh bạc hà/lá dứa hoặc rắc nhẹ bột cacao/hạt chia cho món Trà đào cam sả thêm phần sinh động. Phục vụ ngay khi vừa pha chế xong cho 4 người để tận hưởng trọn vẹn hương thơm tươi mới sảng khoái nhất. Thêm đào cắt miếng và cam thái lát mỏng; cho đá ngay trước khi uống để trà không loãng.',2,'Vỗ nhẹ lá bạc hà trong lòng bàn tay trước khi đặt lên miệng ly sẽ đánh thức tinh dầu the mát lan tỏa ngay khi nâng ly.'),
(103,1,'Tuyển chọn & sơ chế tươi sạch nguyên liệu pha chế','Rửa sạch kỹ các nguyên liệu tươi gồm 3 quả cam và 2 củ cà rốt và rau củ ăn kèm, để ráo nước hoàn toàn trên khay sạch. Cắt lát, đập dập hoặc đong chuẩn xác từng gam/ml nguyên liệu cho khẩu phần 2 ly để hương vị đồng nhất tuyệt đối. Rửa cam và cà rốt dưới vòi nước. Gọt cà rốt, cắt khúc; gọt bỏ vỏ cam và hạt.',6,'Loại bỏ kỹ hạt chanh, tắc trước khi vắt hoặc nấu giúp thức uống giữ hậu vị thanh ngọt mà không hề bị đắng vỏ.'),
(103,2,'Ủ chiết xuất nền trà, cà phê hoặc nấu cốt thảo mộc','Đun nước đạt nhiệt độ chuẩn 90–95°C (không dùng nước sôi sùng sục làm cháy hương), tiến hành ủ chiết xuất hoặc nấu nhỏ lửa 3 quả cam và 2 củ cà rốt trong thời gian quy định. Lọc qua rây mịn hoặc túi vải sạch để thu được phần nước cốt trong trẻo, đậm hương tự nhiên không gợn cặn. Cho cà rốt vào máy ép. Nếu dùng máy xay, thêm ít nước rồi lọc qua rây mịn.',10,'Ủ trà/cà phê đúng nhiệt độ 92°C và đậy nắp kín giúp thu trọn tinh dầu thơm quyến rũ mà không chiết xuất vị chát gắt.'),
(103,3,'Xử lý lớp kem bông mịn / hỗn hợp sữa & trái cây','Đánh bông mượt hoặc khuấy hòa quyện phần nguyên liệu bổ trợ (100ml nước lọc và 200g đá viên) cùng 1/2 quả chanh và 15g đường đến khi sánh mịn đồng nhất. Kiểm soát tốc độ khuấy/đánh đều tay để tạo kết cấu bồng bềnh mượt mà hoặc hòa tan hoàn toàn đường phèn mật ong. Vắt cam riêng, lọc hạt rồi trộn với nước ép cà rốt và nước cốt nửa quả chanh.',6,'Nếu đánh kem trứng, nghiêng nhẹ âu 45 độ và đánh một chiều tốc độ cao cho tới khi nhấc que tạo chóp mềm bóng mượt không tanh.'),
(103,4,'Cân chỉnh định lượng độ ngọt & tầng hương tươi mát','Phối trộn phần nước cốt nền cùng hỗn hợp tạo vị theo đúng tỷ lệ vàng của món Nước ép cam cà rốt, khuấy nhẹ để các tầng hương hòa quyện. Nếu có nước cốt chanh hoặc mật ong rừng, cho vào khi nền nước đã hạ xuống dưới 55°C để bảo toàn trọn vẹn vitamin và hương thơm.',4,'Nếm thử trước khi thêm đá viên sao cho vị đậm hơn khoảng 15% để khi đá tan nhẹ là vừa vặn hoàn hảo.'),
(103,5,'Phối tầng thẩm mỹ ra ly thủy tinh nóng hoặc đá mát','Tráng ấm ly gốm (nếu dùng nóng) hoặc cho lượng đá viên tinh khiết vừa đủ vào ly thủy tinh cao, rót từ từ cốt thức uống vào 2/3 ly. Nhẹ nhàng rót lớp kem/sữa hoặc xếp lát trái cây tươi áp sát thành ly tạo hiệu ứng phân tầng đẹp mắt như quán chuyên nghiệp.',3,'Rót lớp kem hoặc sữa nhẹ nhàng qua lưng muỗng inox giúp hai tầng màu tách bạch sắc nét cực kỳ cuốn hút.');
INSERT INTO `recipe_steps` (`recipe_id`,`step_order`,`title`,`instruction`,`duration_mins`,`tip_note`) VALUES
(103,6,'Điểm xuyết lá thơm trang trí & thưởng thức ngay','Trang trí trên mặt ly bằng lát nguyên liệu tươi, nhánh bạc hà/lá dứa hoặc rắc nhẹ bột cacao/hạt chia cho món Nước ép cam cà rốt thêm phần sinh động. Phục vụ ngay khi vừa pha chế xong cho 2 người để tận hưởng trọn vẹn hương thơm tươi mới sảng khoái nhất. Nếm trước khi pha thêm nước; rót ra ly và dùng ngay để giữ hương tươi. Thêm đá nếu thích.',3,'Vỗ nhẹ lá bạc hà trong lòng bàn tay trước khi đặt lên miệng ly sẽ đánh thức tinh dầu the mát lan tỏa ngay khi nâng ly.'),
(104,1,'Tuyển chọn & sơ chế tươi sạch nguyên liệu pha chế','Rửa sạch kỹ các nguyên liệu tươi gồm 300g xoài chín và 100g sữa chua và rau củ ăn kèm, để ráo nước hoàn toàn trên khay sạch. Cắt lát, đập dập hoặc đong chuẩn xác từng gam/ml nguyên liệu cho khẩu phần 2 ly để hương vị đồng nhất tuyệt đối. Gọt vỏ xoài, cắt lấy phần thịt và bỏ hạt. Ướp lạnh xoài 20 phút nếu muốn sinh tố đặc mát.',6,'Loại bỏ kỹ hạt chanh, tắc trước khi vắt hoặc nấu giúp thức uống giữ hậu vị thanh ngọt mà không hề bị đắng vỏ.'),
(104,2,'Ủ chiết xuất nền trà, cà phê hoặc nấu cốt thảo mộc','Đun nước đạt nhiệt độ chuẩn 90–95°C (không dùng nước sôi sùng sục làm cháy hương), tiến hành ủ chiết xuất hoặc nấu nhỏ lửa 300g xoài chín và 100g sữa chua trong thời gian quy định. Lọc qua rây mịn hoặc túi vải sạch để thu được phần nước cốt trong trẻo, đậm hương tự nhiên không gợn cặn. Cho xoài, sữa chua và sữa tươi vào cối trước; thêm sữa đặc sau để dễ điều chỉnh độ ngọt.',9,'Ủ trà/cà phê đúng nhiệt độ 92°C và đậy nắp kín giúp thu trọn tinh dầu thơm quyến rũ mà không chiết xuất vị chát gắt.'),
(104,3,'Xử lý lớp kem bông mịn / hỗn hợp sữa & trái cây','Đánh bông mượt hoặc khuấy hòa quyện phần nguyên liệu bổ trợ (120ml sữa tươi và 20ml sữa đặc) cùng 15g đường đến khi sánh mịn đồng nhất. Kiểm soát tốc độ khuấy/đánh đều tay để tạo kết cấu bồng bềnh mượt mà hoặc hòa tan hoàn toàn đường phèn mật ong. Xay 30–45 giây đến khi hỗn hợp mịn. Thêm đá và xay ngắn thêm nếu muốn uống lạnh sệt.',6,'Nếu đánh kem trứng, nghiêng nhẹ âu 45 độ và đánh một chiều tốc độ cao cho tới khi nhấc que tạo chóp mềm bóng mượt không tanh.'),
(104,4,'Cân chỉnh định lượng độ ngọt & tầng hương tươi mát','Phối trộn phần nước cốt nền cùng hỗn hợp tạo vị theo đúng tỷ lệ vàng của món Sinh tố xoài, khuấy nhẹ để các tầng hương hòa quyện. Nếu có nước cốt chanh hoặc mật ong rừng, cho vào khi nền nước đã hạ xuống dưới 55°C để bảo toàn trọn vẹn vitamin và hương thơm.',4,'Nếm thử trước khi thêm đá viên sao cho vị đậm hơn khoảng 15% để khi đá tan nhẹ là vừa vặn hoàn hảo.'),
(104,5,'Phối tầng thẩm mỹ ra ly thủy tinh nóng hoặc đá mát','Tráng ấm ly gốm (nếu dùng nóng) hoặc cho lượng đá viên tinh khiết vừa đủ vào ly thủy tinh cao, rót từ từ cốt thức uống vào 2/3 ly. Nhẹ nhàng rót lớp kem/sữa hoặc xếp lát trái cây tươi áp sát thành ly tạo hiệu ứng phân tầng đẹp mắt như quán chuyên nghiệp.',3,'Rót lớp kem hoặc sữa nhẹ nhàng qua lưng muỗng inox giúp hai tầng màu tách bạch sắc nét cực kỳ cuốn hút.'),
(104,6,'Điểm xuyết lá thơm trang trí & thưởng thức ngay','Trang trí trên mặt ly bằng lát nguyên liệu tươi, nhánh bạc hà/lá dứa hoặc rắc nhẹ bột cacao/hạt chia cho món Sinh tố xoài thêm phần sinh động. Phục vụ ngay khi vừa pha chế xong cho 2 người để tận hưởng trọn vẹn hương thơm tươi mới sảng khoái nhất. Nếm độ chua ngọt; nếu xoài chua, thêm ít sữa đặc, nếu quá đặc thêm sữa tươi. Rót ra dùng ngay.',2,'Vỗ nhẹ lá bạc hà trong lòng bàn tay trước khi đặt lên miệng ly sẽ đánh thức tinh dầu the mát lan tỏa ngay khi nâng ly.'),
(105,1,'Tuyển chọn & sơ chế tươi sạch nguyên liệu pha chế','Rửa sạch kỹ các nguyên liệu tươi gồm 200g đậu nành khô và 2 lá lá dứa, để ráo nước hoàn toàn trên khay sạch. Cắt lát, đập dập hoặc đong chuẩn xác từng gam/ml nguyên liệu cho khẩu phần 4 ly để hương vị đồng nhất tuyệt đối. Rửa đậu nành, ngâm 8 giờ hoặc qua đêm; bỏ hạt hỏng và xả sạch. Không dùng nước ngâm để xay.',10,'Loại bỏ kỹ hạt chanh, tắc trước khi vắt hoặc nấu giúp thức uống giữ hậu vị thanh ngọt mà không hề bị đắng vỏ.'),
(105,2,'Ủ chiết xuất nền trà, cà phê hoặc nấu cốt thảo mộc','Đun nước đạt nhiệt độ chuẩn 90–95°C (không dùng nước sôi sùng sục làm cháy hương), tiến hành ủ chiết xuất hoặc nấu nhỏ lửa 200g đậu nành khô trong thời gian quy định. Lọc qua rây mịn hoặc túi vải sạch để thu được phần nước cốt trong trẻo, đậm hương tự nhiên không gợn cặn. Chia đậu và nước thành nhiều mẻ, xay mịn. Lọc qua túi vải sạch, vắt bã; lọc lại lần nữa để sữa mịn.',14,'Ủ trà/cà phê đúng nhiệt độ 92°C và đậy nắp kín giúp thu trọn tinh dầu thơm quyến rũ mà không chiết xuất vị chát gắt.'),
(105,3,'Xử lý lớp kem bông mịn / hỗn hợp sữa & trái cây','Đánh bông mượt hoặc khuấy hòa quyện phần nguyên liệu bổ trợ (8g hạt chia) cùng 50g đường và 1g muối đến khi sánh mịn đồng nhất. Kiểm soát tốc độ khuấy/đánh đều tay để tạo kết cấu bồng bềnh mượt mà hoặc hòa tan hoàn toàn đường phèn mật ong. Đun sữa với lá dứa ở lửa vừa, khuấy đáy nồi thường xuyên. Khi sôi, hạ lửa và nấu thêm 15 phút để đậu chín.',10,'Nếu đánh kem trứng, nghiêng nhẹ âu 45 độ và đánh một chiều tốc độ cao cho tới khi nhấc que tạo chóp mềm bóng mượt không tanh.'),
(105,4,'Cân chỉnh định lượng độ ngọt & tầng hương tươi mát','Phối trộn phần nước cốt nền cùng hỗn hợp tạo vị theo đúng tỷ lệ vàng của món Sữa đậu nành, khuấy nhẹ để các tầng hương hòa quyện. Nếu có nước cốt chanh hoặc mật ong rừng, cho vào khi nền nước đã hạ xuống dưới 55°C để bảo toàn trọn vẹn vitamin và hương thơm.',7,'Nếm thử trước khi thêm đá viên sao cho vị đậm hơn khoảng 15% để khi đá tan nhẹ là vừa vặn hoàn hảo.'),
(105,5,'Phối tầng thẩm mỹ ra ly thủy tinh nóng hoặc đá mát','Tráng ấm ly gốm (nếu dùng nóng) hoặc cho lượng đá viên tinh khiết vừa đủ vào ly thủy tinh cao, rót từ từ cốt thức uống vào 2/3 ly. Nhẹ nhàng rót lớp kem/sữa hoặc xếp lát trái cây tươi áp sát thành ly tạo hiệu ứng phân tầng đẹp mắt như quán chuyên nghiệp.',5,'Rót lớp kem hoặc sữa nhẹ nhàng qua lưng muỗng inox giúp hai tầng màu tách bạch sắc nét cực kỳ cuốn hút.'),
(105,6,'Điểm xuyết lá thơm trang trí & thưởng thức ngay','Trang trí trên mặt ly bằng lát nguyên liệu tươi, nhánh bạc hà/lá dứa hoặc rắc nhẹ bột cacao/hạt chia cho món Sữa đậu nành thêm phần sinh động. Phục vụ ngay khi vừa pha chế xong cho 4 người để tận hưởng trọn vẹn hương thơm tươi mới sảng khoái nhất. Thêm đường, muối rồi khuấy tan. Để nguội nhanh, rót chai sạch và bảo quản lạnh; dùng trong 2–3 ngày.',4,'Vỗ nhẹ lá bạc hà trong lòng bàn tay trước khi đặt lên miệng ly sẽ đánh thức tinh dầu the mát lan tỏa ngay khi nâng ly.'),
(106,1,'Tuyển chọn & sơ chế tươi sạch nguyên liệu pha chế','Rửa sạch kỹ các nguyên liệu tươi gồm 6g trà đen và rau củ ăn kèm, để ráo nước hoàn toàn trên khay sạch. Cắt lát, đập dập hoặc đong chuẩn xác từng gam/ml nguyên liệu cho khẩu phần 2 ly để hương vị đồng nhất tuyệt đối. Rót nước nóng khoảng 90°C lên trà đen, ủ 4 phút rồi lọc bã. Để trà nguội bớt.',4,'Loại bỏ kỹ hạt chanh, tắc trước khi vắt hoặc nấu giúp thức uống giữ hậu vị thanh ngọt mà không hề bị đắng vỏ.'),
(106,2,'Ủ chiết xuất nền trà, cà phê hoặc nấu cốt thảo mộc','Đun nước đạt nhiệt độ chuẩn 90–95°C (không dùng nước sôi sùng sục làm cháy hương), tiến hành ủ chiết xuất hoặc nấu nhỏ lửa 6g trà đen trong thời gian quy định. Lọc qua rây mịn hoặc túi vải sạch để thu được phần nước cốt trong trẻo, đậm hương tự nhiên không gợn cặn. Rửa tắc, cắt đôi và vắt nhẹ lấy nước; lọc hạt. Giữ một lát tắc để trang trí.',5,'Ủ trà/cà phê đúng nhiệt độ 92°C và đậy nắp kín giúp thu trọn tinh dầu thơm quyến rũ mà không chiết xuất vị chát gắt.'),
(106,3,'Xử lý lớp kem bông mịn / hỗn hợp sữa & trái cây','Đánh bông mượt hoặc khuấy hòa quyện phần nguyên liệu bổ trợ (600ml nước lọc và 200g đá viên) cùng 6 quả tắc, 30ml mật ong và 10g đường đến khi sánh mịn đồng nhất. Kiểm soát tốc độ khuấy/đánh đều tay để tạo kết cấu bồng bềnh mượt mà hoặc hòa tan hoàn toàn đường phèn mật ong. Hòa mật ong với trà ấm, thêm nước tắc và khuấy. Nếm vị chua trước khi thêm đường.',4,'Nếu đánh kem trứng, nghiêng nhẹ âu 45 độ và đánh một chiều tốc độ cao cho tới khi nhấc que tạo chóp mềm bóng mượt không tanh.'),
(106,4,'Cân chỉnh định lượng độ ngọt & tầng hương tươi mát','Phối trộn phần nước cốt nền cùng hỗn hợp tạo vị theo đúng tỷ lệ vàng của món Trà tắc mật ong, khuấy nhẹ để các tầng hương hòa quyện. Nếu có nước cốt chanh hoặc mật ong rừng, cho vào khi nền nước đã hạ xuống dưới 55°C để bảo toàn trọn vẹn vitamin và hương thơm.',3,'Nếm thử trước khi thêm đá viên sao cho vị đậm hơn khoảng 15% để khi đá tan nhẹ là vừa vặn hoàn hảo.'),
(106,5,'Phối tầng thẩm mỹ ra ly thủy tinh nóng hoặc đá mát','Tráng ấm ly gốm (nếu dùng nóng) hoặc cho lượng đá viên tinh khiết vừa đủ vào ly thủy tinh cao, rót từ từ cốt thức uống vào 2/3 ly. Nhẹ nhàng rót lớp kem/sữa hoặc xếp lát trái cây tươi áp sát thành ly tạo hiệu ứng phân tầng đẹp mắt như quán chuyên nghiệp.',2,'Rót lớp kem hoặc sữa nhẹ nhàng qua lưng muỗng inox giúp hai tầng màu tách bạch sắc nét cực kỳ cuốn hút.'),
(106,6,'Điểm xuyết lá thơm trang trí & thưởng thức ngay','Trang trí trên mặt ly bằng lát nguyên liệu tươi, nhánh bạc hà/lá dứa hoặc rắc nhẹ bột cacao/hạt chia cho món Trà tắc mật ong thêm phần sinh động. Phục vụ ngay khi vừa pha chế xong cho 2 người để tận hưởng trọn vẹn hương thơm tươi mới sảng khoái nhất. Để trà nguội hoàn toàn, rót vào ly có đá. Thả lát tắc vào sau cùng để hương vỏ không bị đắng.',2,'Vỗ nhẹ lá bạc hà trong lòng bàn tay trước khi đặt lên miệng ly sẽ đánh thức tinh dầu the mát lan tỏa ngay khi nâng ly.'),
(107,1,'Sơ chế tươi sạch & ngâm giòn rau củ thảo mộc','Nhặt rửa kỹ 80g hành tây cùng 20g rau răm và 25g đậu phộng qua nước muối loãng rồi tráng nước đun sôi để nguội. Với các loại củ quả bào sợi hoặc thái lát mỏng, ngâm vào âu nước đá lạnh pha chút chanh đường trong 10 phút rồi vắt ráo để giữ độ trắng giòn sần sật. Luộc gà trong nước vừa ngập đến khi phần dày nhất đạt 74°C. Vớt ra để nguội, giữ lại một ít nước luộc.',8,'Rau củ làm gỏi và món cuốn phải quay rổ hoặc thấm thật ráo nước để khi trộn nước mắm không bị loãng nhạt.'),
(107,2,'Làm chín tới phần nhân đạm giữ trọn độ ngọt mọng','Xử lý phần nguyên liệu chính (350g thịt gà (ức) và 200g bắp cải): luộc hấp cùng lát gừng sả đập dập hoặc xào lửa lớn vừa chín tới, sau đó làm nguội nhanh rồi thái lát mỏng / xé sợi đều đặn. Nếu món có pha bột bánh gạo/bột năng, khuấy tan bột với nước đúng tỷ lệ và để bột nghỉ 15 phút cho nở mịn. Thái bắp cải và cà rốt sợi. Thái hành tây mỏng, ngâm nước đá 10 phút rồi để ráo; xé gà dọc thớ.',9,'Ngâm tôm hoặc thịt luộc qua bát nước sôi để nguội có vài viên đá giúp màu sắc tươi hồng và thớ thịt giòn ngọt không bị khô.'),
(107,3,'Rang vàng đậu phộng mè thơm & phi hành tỏi giòn','Bắc chảo nhỏ lên lửa nhỏ, rang chín vàng thơm đậu phộng/mè hoặc làm mỡ hành xanh mướt và phi vàng giòn hành tím và tỏi băm nhỏ. Vớt hành tỏi phi ra đĩa riêng để nguội giòn tan, giữ lại phần dầu thơm óng ánh để phết bánh hoặc rưới bóng mặt món ăn.',6,'Tắt bếp ngay khi hành phi chuyển vàng sáng vì nhiệt dư trong dầu nóng sẽ tiếp tục làm hành sẫm màu thêm một nấc hoàn hảo.'),
(107,4,'Pha nước mắm chấm / sốt trộn tỷ lệ vàng chua ngọt','Hòa tan hoàn toàn đường cùng 2 quả chanh, 20ml nước mắm và 12g đường và nước ấm trong chén sâu lòng, khuấy đến khi hơi sánh nhẹ mới cho tỏi ớt băm nhuyễn và nước cốt chanh/tắc vào sau cùng. Công thức pha này giúp tỏi ớt nổi đều đẹp mắt trên bề mặt bát nước chấm chuẩn vị Nộm gà xé phay. Khuấy nước mắm, nước cốt chanh, đường và 2 thìa nước luộc gà. Nếm vị chua ngọt mặn cân bằng.',6,'Băm tỏi ớt thật ráo trên thớt khô và cho vào sau khi đường mắm đã nguội thì tỏi ớt sẽ nổi bồng bềnh 100% không bị chìm đáy.'),
(107,5,'Phối trộn thấm vị / tráng hấp & cuốn đều tay','Tiến hành tráng hấp bánh mỏng mượt hoặc trải bánh cuốn gọn gàng 350g thịt gà (ức) và 200g bắp cải cùng 80g hành tây; nếu là món gỏi trộn thì rưới từ từ 2/3 lượng sốt chua ngọt vào bóp nhẹ tay cho thấm đều trong 3 phút. Giữ lực tay nhẹ nhàng để rau củ không bị dập nát mà vẫn ngấm trọn vị mặn chua ngọt hài hòa.',7,'Chia nước sốt gỏi làm 2 lần trộn và chắt bỏ phần nước tiết ra ở lần đầu giúp đĩa gỏi khô ráo, đậm đà như ngoài hàng.'),
(107,6,'Bày biện ngũ sắc hài hòa & rắc topping giòn bùi','Xếp món Nộm gà xé phay ngay ngắn ra đĩa sứ trắng rộng, rải đều phần nhân tôm thịt sắc nét lên trên và rắc phủ 20g rau răm và 25g đậu phộng thơm giòn. Dọn kèm chén nước chấm đậm đà cho 4 người thưởng thức ngay khi rau bánh còn tươi giòn mướt mịn. Trộn gà với rau và nước sốt trước khi ăn 5 phút. Thêm rau răm, đậu phộng rang nếu dùng; không để lâu làm rau ra nước.',4,'Chỉ rắc đậu phộng rang và hành phi ngay trước lúc mang ra bàn ăn để giữ nguyên độ giòn tan bùi béo.');
INSERT INTO `recipe_steps` (`recipe_id`,`step_order`,`title`,`instruction`,`duration_mins`,`tip_note`) VALUES
(108,1,'Sơ chế tươi sạch & ngâm giòn rau củ thảo mộc','Nhặt rửa kỹ rau củ ăn kèm cùng 15g rau răm và 30g đậu phộng qua nước muối loãng rồi tráng nước đun sôi để nguội. Với các loại củ quả bào sợi hoặc thái lát mỏng, ngâm vào âu nước đá lạnh pha chút chanh đường trong 10 phút rồi vắt ráo để giữ độ trắng giòn sần sật. Cắt ngó sen khúc xéo, ngâm nước chanh 10 phút rồi rửa và để thật ráo. Bào cà rốt sợi.',9,'Rau củ làm gỏi và món cuốn phải quay rổ hoặc thấm thật ráo nước để khi trộn nước mắm không bị loãng nhạt.'),
(108,2,'Làm chín tới phần nhân đạm giữ trọn độ ngọt mọng','Xử lý phần nguyên liệu chính (250g ngó sen và 200g tôm sú): luộc hấp cùng lát gừng sả đập dập hoặc xào lửa lớn vừa chín tới, sau đó làm nguội nhanh rồi thái lát mỏng / xé sợi đều đặn. Nếu món có pha bột bánh gạo/bột năng, khuấy tan bột với nước đúng tỷ lệ và để bột nghỉ 15 phút cho nở mịn. Luộc ba chỉ đến chín, để nguội rồi thái lát mỏng. Luộc tôm đến khi thịt đục, bóc vỏ và bỏ chỉ.',10,'Ngâm tôm hoặc thịt luộc qua bát nước sôi để nguội có vài viên đá giúp màu sắc tươi hồng và thớ thịt giòn ngọt không bị khô.'),
(108,3,'Rang vàng đậu phộng mè thơm & phi hành tỏi giòn','Bắc chảo nhỏ lên lửa nhỏ, rang chín vàng thơm đậu phộng/mè hoặc làm mỡ hành xanh mướt và phi vàng giòn hành tím và tỏi băm nhỏ. Vớt hành tỏi phi ra đĩa riêng để nguội giòn tan, giữ lại phần dầu thơm óng ánh để phết bánh hoặc rưới bóng mặt món ăn.',6,'Tắt bếp ngay khi hành phi chuyển vàng sáng vì nhiệt dư trong dầu nóng sẽ tiếp tục làm hành sẫm màu thêm một nấc hoàn hảo.'),
(108,4,'Pha nước mắm chấm / sốt trộn tỷ lệ vàng chua ngọt','Hòa tan hoàn toàn đường cùng 25ml nước mắm, 2 quả chanh và 15g đường và nước ấm trong chén sâu lòng, khuấy đến khi hơi sánh nhẹ mới cho tỏi ớt băm nhuyễn và nước cốt chanh/tắc vào sau cùng. Công thức pha này giúp tỏi ớt nổi đều đẹp mắt trên bề mặt bát nước chấm chuẩn vị Gỏi ngó sen tôm thịt. Khuấy nước mắm, chanh, đường và 30 ml nước luộc tôm; nếm vị chua ngọt vừa miệng.',6,'Băm tỏi ớt thật ráo trên thớt khô và cho vào sau khi đường mắm đã nguội thì tỏi ớt sẽ nổi bồng bềnh 100% không bị chìm đáy.'),
(108,5,'Phối trộn thấm vị / tráng hấp & cuốn đều tay','Tiến hành tráng hấp bánh mỏng mượt hoặc trải bánh cuốn gọn gàng 250g ngó sen và 200g tôm sú cùng rau củ ăn kèm; nếu là món gỏi trộn thì rưới từ từ 2/3 lượng sốt chua ngọt vào bóp nhẹ tay cho thấm đều trong 3 phút. Giữ lực tay nhẹ nhàng để rau củ không bị dập nát mà vẫn ngấm trọn vị mặn chua ngọt hài hòa.',8,'Chia nước sốt gỏi làm 2 lần trộn và chắt bỏ phần nước tiết ra ở lần đầu giúp đĩa gỏi khô ráo, đậm đà như ngoài hàng.'),
(108,6,'Bày biện ngũ sắc hài hòa & rắc topping giòn bùi','Xếp món Gỏi ngó sen tôm thịt ngay ngắn ra đĩa sứ trắng rộng, rải đều phần nhân tôm thịt sắc nét lên trên và rắc phủ 15g rau răm và 30g đậu phộng thơm giòn. Dọn kèm chén nước chấm đậm đà cho 4 người thưởng thức ngay khi rau bánh còn tươi giòn mướt mịn. Trộn ngó sen, cà rốt, tôm và thịt với nước sốt, để 5 phút rồi chắt bớt nước. Thêm rau răm, đậu phộng và dùng ngay.',4,'Chỉ rắc đậu phộng rang và hành phi ngay trước lúc mang ra bàn ăn để giữ nguyên độ giòn tan bùi béo.'),
(109,1,'Sơ chế sạch & cắt thái nguyên liệu đúng kích cỡ','Rửa sạch 150g xà lách và 150g dưa leo cùng 150g cà chua và 80g cà rốt dưới vòi nước mát rồi để thật ráo trên rổ thưa. Dùng dao sắc cắt thái nguyên liệu thành từng khúc hoặc khối vuông đều đặn khoảng 3.5–4cm để khi kho hầm giữ nguyên hình dáng đẹp mắt mà không bị vụn nát. Rửa xà lách, dưa leo, cà chua và cà rốt dưới vòi nước, để ráo hoàn toàn. Ngâm rau lá trong nước sạch nếu cần.',5,'Cắt miếng thịt/cá dày dặn đồng đều giúp quá trình kho lâu trên lửa nhỏ thớ thịt mềm rục mà vẫn giữ trọn độ mọng ngọt bên trong.'),
(109,2,'Khử mùi tự nhiên & làm săn sạch bề mặt nguyên liệu','Chà nhẹ phần đạm chính trong 150g xà lách và 150g dưa leo với chút muối hạt, lát gừng đập dập hoặc chần sơ qua nước sôi 90 giây rồi rửa sạch lại bằng nước ấm, để ráo hoàn toàn. Công đoạn này loại bỏ triệt để tạp chất và mùi tanh hôi, giúp nước sốt món Salad rau củ sốt mè trong bóng thơm ngon.',4,'Sau khi chần hoặc rửa sạch, để nguyên liệu ráo nước ít nhất 5 phút trước khi ướp để gia vị rút sâu trực tiếp vào từng thớ thịt.'),
(109,3,'Pha hỗn hợp gia vị & ướp thấm chuẩn định lượng','Cho 150g xà lách và 150g dưa leo vào tô lớn, ướp cùng một nửa hành tím và tỏi băm nhỏ băm nhỏ và định lượng chuẩn 15ml nước tương, 15ml giấm và 10ml mật ong, đảo nhẹ tay cho gia vị phủ kín đều các mặt. Bọc kín tô và để nguyên liệu nghỉ thấm vị tối thiểu 20 phút ở nhiệt độ phòng (hoặc ngăn mát tủ lạnh). Xé xà lách miếng vừa, thái dưa leo và cà chua, bào cà rốt sợi; giữ các miếng có kích thước gần nhau.',5,'Ướp đủ tối thiểu 20 phút trước khi bắc lên bếp là chìa khóa để tâm miếng thịt/cá đậm đà đồng nhất với lớp sốt bên ngoài.'),
(109,4,'Thắng nước màu cánh gián & phi dậy hương hành tỏi','Đặt nồi đáy dày lên bếp ở lửa vừa nhỏ, thắng nhẹ 15g đường với 15ml dầu ăn đến khi chuyển sắc nâu cánh gián óng ả thì cho ngay phần hành tím và tỏi băm nhỏ còn lại vào phi thơm lừng. Hương caramel dịu ngọt quyện cùng tinh dầu hành tỏi sả tạo nền màu nâu hổ phách truyền thống đầy cuốn hút.',4,'Canh kỹ khoảnh khắc đường vừa chuyển màu cánh gián là hạ lửa nhỏ nhất ngay để nước màu bóng đẹp mà không bao giờ bị đắng.'),
(109,5,'Đảo săn hai mặt khóa ngọt nguyên liệu chính','Tăng lên lửa vừa lớn, gắp từng miếng trong 150g xà lách và 150g dưa leo vào nồi đảo đều hoặc trở nhẹ hai mặt trong 4–5 phút cho săn chắc và bám đều lớp màu nâu óng. Khi bề mặt nguyên liệu se vàng thơm phức mới trút phần nước ướp còn lại trong tô vào đun sôi nhẹ. Giã một nửa mè rang, khuấy với nước tương, giấm, dầu mè và mật ong đến hòa quyện.',5,'Đối với cá kho, chỉ lật cá một lần lúc cá vừa săn mặt trên lửa vừa để khúc cá nguyên vẹn không bị tróc da hay vỡ nát.'),
(109,6,'Kho/om liu riu lửa nhỏ thấm đẫm cùng nước dừa/nước dùng','Chế 10ml dầu mè xâm xắp mặt nguyên liệu (xếp thêm rau củ ăn kèm nếu có), đun sôi bùng một dạo hớt sạch bọt rồi hạ ngay về mức lửa nhỏ liu riu nhất. Kho êm đềm không đậy kín nắp để từng thớ nguyên liệu chín mềm thấm đẫm gia vị và nước sốt rút dần sóng sánh. Rưới sốt ngay trước khi ăn, đảo nhẹ để không dập rau. Rắc phần mè còn lại; không trộn quá sớm làm salad ra nước.',8,'Luôn dùng nước sôi hoặc nước dừa ấm khi châm thêm vào nồi kho đang nóng để thịt cá không bị sượng cứng trở lại.'),
(109,7,'Thu sánh nước sốt óng ả & trình bày thưởng thức nóng','Khi nước kho rút còn khoảng 1/3 sánh kẹo óng ánh áo đều quanh nguyên liệu và xiên đũa thấy mềm mọng vừa ý, rắc 20g mè rang lên mặt rồi tắt bếp. Múc món Salad rau củ sốt mè ra đĩa sâu lòng hoặc niêu đất giữ nhiệt, dọn ăn nóng cùng cơm trắng dẻo thơm cho 4 người.',4,'Giữ lại một lượng nước sốt sánh kẹo vừa đủ dưới đáy nồi để chan cơm hoặc chấm kèm rau luộc sẽ tròn vị đưa cơm gấp bội.'),
(110,1,'Sơ chế tươi sạch & ngâm giòn rau củ thảo mộc','Nhặt rửa kỹ rau củ ăn kèm cùng 15g rau răm và 25g đậu phộng qua nước muối loãng rồi tráng nước đun sôi để nguội. Với các loại củ quả bào sợi hoặc thái lát mỏng, ngâm vào âu nước đá lạnh pha chút chanh đường trong 10 phút rồi vắt ráo để giữ độ trắng giòn sần sật. Gọt đu đủ, bỏ hạt, bào sợi rồi ngâm nước đá 10 phút để giòn. Rửa lại, vắt ráo và bào cà rốt.',8,'Rau củ làm gỏi và món cuốn phải quay rổ hoặc thấm thật ráo nước để khi trộn nước mắm không bị loãng nhạt.'),
(110,2,'Làm chín tới phần nhân đạm giữ trọn độ ngọt mọng','Xử lý phần nguyên liệu chính (350g đu đủ xanh và 100g bò khô): luộc hấp cùng lát gừng sả đập dập hoặc xào lửa lớn vừa chín tới, sau đó làm nguội nhanh rồi thái lát mỏng / xé sợi đều đặn. Nếu món có pha bột bánh gạo/bột năng, khuấy tan bột với nước đúng tỷ lệ và để bột nghỉ 15 phút cho nở mịn. Khuấy nước mắm, nước cốt chanh, đường và ớt băm; nếm chua ngọt mặn rõ vị.',9,'Ngâm tôm hoặc thịt luộc qua bát nước sôi để nguội có vài viên đá giúp màu sắc tươi hồng và thớ thịt giòn ngọt không bị khô.'),
(110,3,'Rang vàng đậu phộng mè thơm & phi hành tỏi giòn','Bắc chảo nhỏ lên lửa nhỏ, rang chín vàng thơm đậu phộng/mè hoặc làm mỡ hành xanh mướt và phi vàng giòn hành tím và tỏi băm nhỏ. Vớt hành tỏi phi ra đĩa riêng để nguội giòn tan, giữ lại phần dầu thơm óng ánh để phết bánh hoặc rưới bóng mặt món ăn.',6,'Tắt bếp ngay khi hành phi chuyển vàng sáng vì nhiệt dư trong dầu nóng sẽ tiếp tục làm hành sẫm màu thêm một nấc hoàn hảo.'),
(110,4,'Pha nước mắm chấm / sốt trộn tỷ lệ vàng chua ngọt','Hòa tan hoàn toàn đường cùng 18ml nước mắm, 2 quả chanh, 12g đường và 1 quả ớt và nước ấm trong chén sâu lòng, khuấy đến khi hơi sánh nhẹ mới cho tỏi ớt băm nhuyễn và nước cốt chanh/tắc vào sau cùng. Công thức pha này giúp tỏi ớt nổi đều đẹp mắt trên bề mặt bát nước chấm chuẩn vị Nộm đu đủ bò khô. Trộn đu đủ và cà rốt với hai phần ba nước sốt, để 5 phút rồi chắt phần nước đọng.',6,'Băm tỏi ớt thật ráo trên thớt khô và cho vào sau khi đường mắm đã nguội thì tỏi ớt sẽ nổi bồng bềnh 100% không bị chìm đáy.'),
(110,5,'Phối trộn thấm vị / tráng hấp & cuốn đều tay','Tiến hành tráng hấp bánh mỏng mượt hoặc trải bánh cuốn gọn gàng 350g đu đủ xanh và 100g bò khô cùng rau củ ăn kèm; nếu là món gỏi trộn thì rưới từ từ 2/3 lượng sốt chua ngọt vào bóp nhẹ tay cho thấm đều trong 3 phút. Giữ lực tay nhẹ nhàng để rau củ không bị dập nát mà vẫn ngấm trọn vị mặn chua ngọt hài hòa.',7,'Chia nước sốt gỏi làm 2 lần trộn và chắt bỏ phần nước tiết ra ở lần đầu giúp đĩa gỏi khô ráo, đậm đà như ngoài hàng.'),
(110,6,'Bày biện ngũ sắc hài hòa & rắc topping giòn bùi','Xếp món Nộm đu đủ bò khô ngay ngắn ra đĩa sứ trắng rộng, rải đều phần nhân tôm thịt sắc nét lên trên và rắc phủ 15g rau răm và 25g đậu phộng thơm giòn. Dọn kèm chén nước chấm đậm đà cho 4 người thưởng thức ngay khi rau bánh còn tươi giòn mướt mịn. Xé bò khô sợi, trộn nhẹ với rau răm và nước sốt còn lại. Rắc đậu phộng trước khi dọn để giữ độ giòn.',4,'Chỉ rắc đậu phộng rang và hành phi ngay trước lúc mang ra bàn ăn để giữ nguyên độ giòn tan bùi béo.'),
(111,1,'Sơ chế & thái mỏng đồng đều nguyên liệu xào','Làm sạch và thấm ráo 350g bắp ngọt và 50g tép khô, dùng dao sắc thái lát mỏng vừa ăn khoảng 2–3mm ngang thớ để khi xào nhanh chín mềm không bị dai. Nhặt rửa sạch rau củ ăn kèm, cắt khúc xéo 4cm hoặc tách nhánh đồng đều giúp tiếp xúc nhiệt nhanh trên chảo. Ngâm tép khô trong nước ấm 10 phút rồi để ráo. Tách hạt bắp hoặc dùng bắp hạt đã rã đông.',4,'Nguyên liệu xào bắt buộc phải để thật ráo nước trước khi cho vào chảo để đạt hiệu ứng áp nhiệt thơm kiểu chảo gang.'),
(111,2,'Ướp mềm nguyên liệu đạm & pha sẵn chén sốt xào','Ướp phần đạm trong 350g bắp ngọt và 50g tép khô với 1/3 lượng hành tím và tỏi băm nhỏ, chút dầu ăn và 1/3 lượng 8ml nước mắm, 4g đường và 1 quả ớt trong 10 phút để giữ độ ẩm mọng. Pha phần 8ml nước mắm, 4g đường và 1 quả ớt còn lại cùng 20ml nước lọc vào chén nhỏ khuấy tan hoàn toàn để thao tác xào lửa lớn diễn ra dứt khoát. Đun chảy bơ, cho tép vào đảo 2 phút đến thơm và khô ráo.',4,'Thêm 1 muỗng cà phê dầu ăn vào bước ướp thịt bò/heo giúp khóa ẩm và các lát thịt tơi nhanh không bị dính chùm khi gặp chảo nóng.'),
(111,3,'Chần nhanh rau củ giữ sắc xanh ngọc & độ giòn','Đun sôi nồi nước nhỏ với một nhúm muối, thả rau củ ăn kèm vào chần nhanh 30–45 giây rồi vớt ngay ra tô nước đá lạnh cho sốc nhiệt, sau đó đổ ra rổ cho thật ráo. Bước tiền xử lý này giúp rau củ chín đều từ trong mà bên ngoài vẫn xanh mướt giòn sần sật.',3,'Thời gian chần dưới 1 phút kết hợp ngâm nước đá lạnh là bí quyết nhà hàng giúp đĩa rau xào không bị chảy nước đen đĩa.'),
(111,4,'Xào săn nguyên liệu chính trên lửa lớn nhanh tay','Làm nóng chảo rộng trên lửa lớn nhất với 15ml dầu ăn, phi dậy mùi một nửa hành tím và tỏi băm nhỏ rồi trút phần đạm chính trong 350g bắp ngọt và 50g tép khô vào đảo cực nhanh tay trong 60–90 giây. Ngay khi thịt hoặc hải sản vừa chín tái hồng khoảng 85%, lập tức trút riêng ra đĩa sạch để không bị quá lửa khô xác. Thêm hạt bắp, đường và 2 thìa nước, đảo lửa vừa 6–8 phút đến bắp chín giòn ngọt.',4,'Tuyệt đối không xào thịt chung từ đầu đến cuối với rau củ vì thịt sẽ bị dai và tiết nước làm mất độ giòn.'),
(111,5,'Xào rau củ lửa lớn & rưới sốt định lượng khóa vị','Giữ nguyên chảo nóng trên lửa lớn, thêm chút dầu phi thơm nốt phần hành tím và tỏi băm nhỏ còn lại rồi cho rau củ ăn kèm đã ráo nước vào đảo đều 1–2 phút. Trút ngược đĩa đạm vào chảo, rưới đều chén sốt gia vị đã pha và xóc nhanh tay 45 giây cho sốt sánh bóng áo quanh từng miếng nguyên liệu.',4,'Rưới sốt vòng quanh thành chảo nóng thay vì đổ thẳng giữa lòng chảo giúp sốt bốc hơi thơm lừng và sệt lại tức thì.'),
(111,6,'Dậy hương tiêu hành & trình bày nóng hổi','Cho 20g hành lá vào đảo nhẹ đúng 1 lượt rồi tắt bếp ngay khi khói thơm bốc lên nghi ngút. Gắp món Bắp xào tép ra đĩa rộng lòng để tản nhiệt đều, tránh đậy kín vung và thưởng thức nóng ngay cùng cơm dẻo cho 4 người. Nêm chút nước mắm, thêm hành lá và ớt nếu thích. Đảo 30 giây rồi tắt bếp, dùng khi còn nóng.',3,'Bày món xào ra đĩa rộng không xếp chồng quá dày giúp hơi nóng thoát nhẹ, giữ rau củ giòn ngọt lâu đến miếng cuối cùng.');
INSERT INTO `recipe_steps` (`recipe_id`,`step_order`,`title`,`instruction`,`duration_mins`,`tip_note`) VALUES
(112,1,'Sơ chế sạch & cắt thái nguyên liệu đúng kích cỡ','Rửa sạch 150g bánh tráng và 6 quả trứng cút cùng 120g xoài xanh và 25g tép khô dưới vòi nước mát rồi để thật ráo trên rổ thưa. Dùng dao sắc cắt thái nguyên liệu thành từng khúc hoặc khối vuông đều đặn khoảng 3.5–4cm để khi kho hầm giữ nguyên hình dáng đẹp mắt mà không bị vụn nát. Luộc trứng cút 5 phút, ngâm nước lạnh rồi bóc vỏ. Ngâm tép khô cho mềm và để ráo.',6,'Cắt miếng thịt/cá dày dặn đồng đều giúp quá trình kho lâu trên lửa nhỏ thớ thịt mềm rục mà vẫn giữ trọn độ mọng ngọt bên trong.'),
(112,2,'Khử mùi tự nhiên & làm săn sạch bề mặt nguyên liệu','Chà nhẹ phần đạm chính trong 150g bánh tráng và 6 quả trứng cút với chút muối hạt, lát gừng đập dập hoặc chần sơ qua nước sôi 90 giây rồi rửa sạch lại bằng nước ấm, để ráo hoàn toàn. Công đoạn này loại bỏ triệt để tạp chất và mùi tanh hôi, giúp nước sốt món Bánh tráng trộn trong bóng thơm ngon.',4,'Sau khi chần hoặc rửa sạch, để nguyên liệu ráo nước ít nhất 5 phút trước khi ướp để gia vị rút sâu trực tiếp vào từng thớ thịt.'),
(112,3,'Pha hỗn hợp gia vị & ướp thấm chuẩn định lượng','Cho 150g bánh tráng và 6 quả trứng cút vào tô lớn, ướp cùng một nửa hành tím và tỏi băm nhỏ băm nhỏ và định lượng chuẩn 30g me vắt và 8g sa tế, đảo nhẹ tay cho gia vị phủ kín đều các mặt. Bọc kín tô và để nguyên liệu nghỉ thấm vị tối thiểu 20 phút ở nhiệt độ phòng (hoặc ngăn mát tủ lạnh). Cắt bánh tráng thành sợi, bào xoài xanh sợi, xé bò khô và thái rau răm.',6,'Ướp đủ tối thiểu 20 phút trước khi bắc lên bếp là chìa khóa để tâm miếng thịt/cá đậm đà đồng nhất với lớp sốt bên ngoài.'),
(112,4,'Thắng nước màu cánh gián & phi dậy hương hành tỏi','Đặt nồi đáy dày lên bếp ở lửa vừa nhỏ, thắng nhẹ 15g đường với 15ml dầu ăn đến khi chuyển sắc nâu cánh gián óng ả thì cho ngay phần hành tím và tỏi băm nhỏ còn lại vào phi thơm lừng. Hương caramel dịu ngọt quyện cùng tinh dầu hành tỏi sả tạo nền màu nâu hổ phách truyền thống đầy cuốn hút.',4,'Canh kỹ khoảnh khắc đường vừa chuyển màu cánh gián là hạ lửa nhỏ nhất ngay để nước màu bóng đẹp mà không bao giờ bị đắng.'),
(112,5,'Đảo săn hai mặt khóa ngọt nguyên liệu chính','Tăng lên lửa vừa lớn, gắp từng miếng trong 150g bánh tráng và 6 quả trứng cút vào nồi đảo đều hoặc trở nhẹ hai mặt trong 4–5 phút cho săn chắc và bám đều lớp màu nâu óng. Khi bề mặt nguyên liệu se vàng thơm phức mới trút phần nước ướp còn lại trong tô vào đun sôi nhẹ. Dầm me vắt với nước ấm, lọc lấy nước chua; thêm sa tế nếu muốn cay. Nếm trước vì bò khô và tép đã mặn.',6,'Đối với cá kho, chỉ lật cá một lần lúc cá vừa săn mặt trên lửa vừa để khúc cá nguyên vẹn không bị tróc da hay vỡ nát.'),
(112,6,'Kho/om liu riu lửa nhỏ thấm đẫm cùng nước dừa/nước dùng','Chế 30ml nước lọc xâm xắp mặt nguyên liệu (xếp thêm 120g xoài xanh và 25g tép khô nếu có), đun sôi bùng một dạo hớt sạch bọt rồi hạ ngay về mức lửa nhỏ liu riu nhất. Kho êm đềm không đậy kín nắp để từng thớ nguyên liệu chín mềm thấm đẫm gia vị và nước sốt rút dần sóng sánh. Trộn bánh tráng với sốt từng ít một cho mềm vừa, thêm xoài, bò khô, tép và rau răm. Cắt trứng lên trên, rắc đậu phộng.',10,'Luôn dùng nước sôi hoặc nước dừa ấm khi châm thêm vào nồi kho đang nóng để thịt cá không bị sượng cứng trở lại.'),
(112,7,'Thu sánh nước sốt óng ả & trình bày thưởng thức nóng','Khi nước kho rút còn khoảng 1/3 sánh kẹo óng ánh áo đều quanh nguyên liệu và xiên đũa thấy mềm mọng vừa ý, rắc 15g rau răm và 20g đậu phộng lên mặt rồi tắt bếp. Múc món Bánh tráng trộn ra đĩa sâu lòng hoặc niêu đất giữ nhiệt, dọn ăn nóng cùng cơm trắng dẻo thơm cho 4 người.',4,'Giữ lại một lượng nước sốt sánh kẹo vừa đủ dưới đáy nồi để chan cơm hoặc chấm kèm rau luộc sẽ tròn vị đưa cơm gấp bội.'),
(113,1,'Sơ chế sạch & cắt thái nguyên liệu đúng kích cỡ','Rửa sạch 12 cái bánh tráng và 250g củ sắn cùng 120g lạp xưởng và 80g xà lách dưới vòi nước mát rồi để thật ráo trên rổ thưa. Dùng dao sắc cắt thái nguyên liệu thành từng khúc hoặc khối vuông đều đặn khoảng 3.5–4cm để khi kho hầm giữ nguyên hình dáng đẹp mắt mà không bị vụn nát. Bào củ sắn và cà rốt sợi, xào với dầu đến mềm và cạn nước. Ngâm tôm khô, để ráo.',6,'Cắt miếng thịt/cá dày dặn đồng đều giúp quá trình kho lâu trên lửa nhỏ thớ thịt mềm rục mà vẫn giữ trọn độ mọng ngọt bên trong.'),
(113,2,'Khử mùi tự nhiên & làm săn sạch bề mặt nguyên liệu','Chà nhẹ phần đạm chính trong 12 cái bánh tráng và 250g củ sắn với chút muối hạt, lát gừng đập dập hoặc chần sơ qua nước sôi 90 giây rồi rửa sạch lại bằng nước ấm, để ráo hoàn toàn. Công đoạn này loại bỏ triệt để tạp chất và mùi tanh hôi, giúp nước sốt món Bò bía mặn trong bóng thơm ngon.',4,'Sau khi chần hoặc rửa sạch, để nguyên liệu ráo nước ít nhất 5 phút trước khi ướp để gia vị rút sâu trực tiếp vào từng thớ thịt.'),
(113,3,'Pha hỗn hợp gia vị & ướp thấm chuẩn định lượng','Cho 12 cái bánh tráng và 250g củ sắn vào tô lớn, ướp cùng một nửa hành tím và tỏi băm nhỏ băm nhỏ và định lượng chuẩn 20ml nước tương và 5g đường, đảo nhẹ tay cho gia vị phủ kín đều các mặt. Bọc kín tô và để nguyên liệu nghỉ thấm vị tối thiểu 20 phút ở nhiệt độ phòng (hoặc ngăn mát tủ lạnh). Chiên trứng thành lớp mỏng rồi thái sợi. Áp chảo lạp xưởng chín, thái lát; rang tôm khô đến thơm.',6,'Ướp đủ tối thiểu 20 phút trước khi bắc lên bếp là chìa khóa để tâm miếng thịt/cá đậm đà đồng nhất với lớp sốt bên ngoài.'),
(113,4,'Thắng nước màu cánh gián & phi dậy hương hành tỏi','Đặt nồi đáy dày lên bếp ở lửa vừa nhỏ, thắng nhẹ 15g đường với 15ml dầu ăn đến khi chuyển sắc nâu cánh gián óng ả thì cho ngay phần hành tím và tỏi băm nhỏ còn lại vào phi thơm lừng. Hương caramel dịu ngọt quyện cùng tinh dầu hành tỏi sả tạo nền màu nâu hổ phách truyền thống đầy cuốn hút.',4,'Canh kỹ khoảnh khắc đường vừa chuyển màu cánh gián là hạ lửa nhỏ nhất ngay để nước màu bóng đẹp mà không bao giờ bị đắng.'),
(113,5,'Đảo săn hai mặt khóa ngọt nguyên liệu chính','Tăng lên lửa vừa lớn, gắp từng miếng trong 12 cái bánh tráng và 250g củ sắn vào nồi đảo đều hoặc trở nhẹ hai mặt trong 4–5 phút cho săn chắc và bám đều lớp màu nâu óng. Khi bề mặt nguyên liệu se vàng thơm phức mới trút phần nước ướp còn lại trong tô vào đun sôi nhẹ. Đun nước tương, đường và 60 ml nước đến sánh nhẹ. Nếm mặn ngọt vừa.',6,'Đối với cá kho, chỉ lật cá một lần lúc cá vừa săn mặt trên lửa vừa để khúc cá nguyên vẹn không bị tróc da hay vỡ nát.'),
(113,6,'Kho/om liu riu lửa nhỏ thấm đẫm cùng nước dừa/nước dùng','Chế 10ml dầu ăn xâm xắp mặt nguyên liệu (xếp thêm 120g lạp xưởng và 80g xà lách nếu có), đun sôi bùng một dạo hớt sạch bọt rồi hạ ngay về mức lửa nhỏ liu riu nhất. Kho êm đềm không đậy kín nắp để từng thớ nguyên liệu chín mềm thấm đẫm gia vị và nước sốt rút dần sóng sánh. Làm ẩm bánh tráng, đặt xà lách, củ sắn, trứng, lạp xưởng và tôm khô lên một mép. Cuốn chặt vừa, ăn với sốt.',10,'Luôn dùng nước sôi hoặc nước dừa ấm khi châm thêm vào nồi kho đang nóng để thịt cá không bị sượng cứng trở lại.'),
(113,7,'Thu sánh nước sốt óng ả & trình bày thưởng thức nóng','Khi nước kho rút còn khoảng 1/3 sánh kẹo óng ánh áo đều quanh nguyên liệu và xiên đũa thấy mềm mọng vừa ý, rắc hành ngò và tiêu xay lên mặt rồi tắt bếp. Múc món Bò bía mặn ra đĩa sâu lòng hoặc niêu đất giữ nhiệt, dọn ăn nóng cùng cơm trắng dẻo thơm cho 4 người.',4,'Giữ lại một lượng nước sốt sánh kẹo vừa đủ dưới đáy nồi để chan cơm hoặc chấm kèm rau luộc sẽ tròn vị đưa cơm gấp bội.'),
(114,1,'Sơ chế tươi sạch & ngâm giòn rau củ thảo mộc','Nhặt rửa kỹ 150g giá đỗ cùng 20g hành phi qua nước muối loãng rồi tráng nước đun sôi để nguội. Với các loại củ quả bào sợi hoặc thái lát mỏng, ngâm vào âu nước đá lạnh pha chút chanh đường trong 10 phút rồi vắt ráo để giữ độ trắng giòn sần sật. Hòa bột gạo, bột năng với nước, để nghỉ 20 phút. Ngâm nấm mèo, băm nhỏ; xào thịt với hành tím và nước mắm.',11,'Rau củ làm gỏi và món cuốn phải quay rổ hoặc thấm thật ráo nước để khi trộn nước mắm không bị loãng nhạt.'),
(114,2,'Làm chín tới phần nhân đạm giữ trọn độ ngọt mọng','Xử lý phần nguyên liệu chính (200g bột gạo và 50g bột năng): luộc hấp cùng lát gừng sả đập dập hoặc xào lửa lớn vừa chín tới, sau đó làm nguội nhanh rồi thái lát mỏng / xé sợi đều đặn. Nếu món có pha bột bánh gạo/bột năng, khuấy tan bột với nước đúng tỷ lệ và để bột nghỉ 15 phút cho nở mịn. Căng vải mỏng sạch trên miệng nồi nước sôi, giữ hơi nước ổn định. Thoa lớp dầu rất mỏng lên vải.',12,'Ngâm tôm hoặc thịt luộc qua bát nước sôi để nguội có vài viên đá giúp màu sắc tươi hồng và thớ thịt giòn ngọt không bị khô.'),
(114,3,'Rang vàng đậu phộng mè thơm & phi hành tỏi giòn','Bắc chảo nhỏ lên lửa nhỏ, rang chín vàng thơm đậu phộng/mè hoặc làm mỡ hành xanh mướt và phi vàng giòn 30g hành tím. Vớt hành tỏi phi ra đĩa riêng để nguội giòn tan, giữ lại phần dầu thơm óng ánh để phết bánh hoặc rưới bóng mặt món ăn.',8,'Tắt bếp ngay khi hành phi chuyển vàng sáng vì nhiệt dư trong dầu nóng sẽ tiếp tục làm hành sẫm màu thêm một nấc hoàn hảo.'),
(114,4,'Pha nước mắm chấm / sốt trộn tỷ lệ vàng chua ngọt','Hòa tan hoàn toàn đường cùng 18ml nước mắm và nước ấm trong chén sâu lòng, khuấy đến khi hơi sánh nhẹ mới cho tỏi ớt băm nhuyễn và nước cốt chanh/tắc vào sau cùng. Công thức pha này giúp tỏi ớt nổi đều đẹp mắt trên bề mặt bát nước chấm chuẩn vị Bánh cuốn nhân thịt. Múc lớp bột mỏng lên vải, đậy nắp 30–45 giây đến khi bánh trong. Dùng que tre lấy bánh, đặt lên đĩa phẳng.',8,'Băm tỏi ớt thật ráo trên thớt khô và cho vào sau khi đường mắm đã nguội thì tỏi ớt sẽ nổi bồng bềnh 100% không bị chìm đáy.'),
(114,5,'Phối trộn thấm vị / tráng hấp & cuốn đều tay','Tiến hành tráng hấp bánh mỏng mượt hoặc trải bánh cuốn gọn gàng 200g bột gạo và 50g bột năng cùng 150g giá đỗ; nếu là món gỏi trộn thì rưới từ từ 2/3 lượng sốt chua ngọt vào bóp nhẹ tay cho thấm đều trong 3 phút. Giữ lực tay nhẹ nhàng để rau củ không bị dập nát mà vẫn ngấm trọn vị mặn chua ngọt hài hòa.',10,'Chia nước sốt gỏi làm 2 lần trộn và chắt bỏ phần nước tiết ra ở lần đầu giúp đĩa gỏi khô ráo, đậm đà như ngoài hàng.'),
(114,6,'Bày biện ngũ sắc hài hòa & rắc topping giòn bùi','Xếp món Bánh cuốn nhân thịt ngay ngắn ra đĩa sứ trắng rộng, rải đều phần nhân tôm thịt sắc nét lên trên và rắc phủ 20g hành phi thơm giòn. Dọn kèm chén nước chấm đậm đà cho 4 người thưởng thức ngay khi rau bánh còn tươi giòn mướt mịn. Cho nhân thịt vào giữa, cuốn gọn. Lặp lại đến hết bột; ăn với giá chần, hành phi và nước mắm pha.',6,'Chỉ rắc đậu phộng rang và hành phi ngay trước lúc mang ra bàn ăn để giữ nguyên độ giòn tan bùi béo.'),
(115,1,'Sơ chế sạch & cắt thái nguyên liệu đúng kích cỡ','Rửa sạch 150g cốm tươi và 250g giò sống cùng 2 lá lá sen dưới vòi nước mát rồi để thật ráo trên rổ thưa. Dùng dao sắc cắt thái nguyên liệu thành từng khúc hoặc khối vuông đều đặn khoảng 3.5–4cm để khi kho hầm giữ nguyên hình dáng đẹp mắt mà không bị vụn nát. Nếu dùng cốm khô, vẩy ít nước ấm cho mềm; cốm tươi chỉ nhặt sạch và để ráo.',5,'Cắt miếng thịt/cá dày dặn đồng đều giúp quá trình kho lâu trên lửa nhỏ thớ thịt mềm rục mà vẫn giữ trọn độ mọng ngọt bên trong.'),
(115,2,'Khử mùi tự nhiên & làm săn sạch bề mặt nguyên liệu','Chà nhẹ phần đạm chính trong 150g cốm tươi và 250g giò sống với chút muối hạt, lát gừng đập dập hoặc chần sơ qua nước sôi 90 giây rồi rửa sạch lại bằng nước ấm, để ráo hoàn toàn. Công đoạn này loại bỏ triệt để tạp chất và mùi tanh hôi, giúp nước sốt món Chả cốm trong bóng thơm ngon.',4,'Sau khi chần hoặc rửa sạch, để nguyên liệu ráo nước ít nhất 5 phút trước khi ướp để gia vị rút sâu trực tiếp vào từng thớ thịt.'),
(115,3,'Pha hỗn hợp gia vị & ướp thấm chuẩn định lượng','Cho 150g cốm tươi và 250g giò sống vào tô lớn, ướp cùng một nửa hành tím và tỏi băm nhỏ băm nhỏ và định lượng chuẩn 10ml nước mắm và 2g tiêu, đảo nhẹ tay cho gia vị phủ kín đều các mặt. Bọc kín tô và để nguyên liệu nghỉ thấm vị tối thiểu 20 phút ở nhiệt độ phòng (hoặc ngăn mát tủ lạnh). Trộn cốm với giò sống, thịt xay, trứng, nước mắm và tiêu. Quết nhẹ đến kết dính, không bóp nát hạt cốm.',5,'Ướp đủ tối thiểu 20 phút trước khi bắc lên bếp là chìa khóa để tâm miếng thịt/cá đậm đà đồng nhất với lớp sốt bên ngoài.'),
(115,4,'Thắng nước màu cánh gián & phi dậy hương hành tỏi','Đặt nồi đáy dày lên bếp ở lửa vừa nhỏ, thắng nhẹ 15g đường với 15ml dầu ăn đến khi chuyển sắc nâu cánh gián óng ả thì cho ngay phần hành tím và tỏi băm nhỏ còn lại vào phi thơm lừng. Hương caramel dịu ngọt quyện cùng tinh dầu hành tỏi sả tạo nền màu nâu hổ phách truyền thống đầy cuốn hút.',4,'Canh kỹ khoảnh khắc đường vừa chuyển màu cánh gián là hạ lửa nhỏ nhất ngay để nước màu bóng đẹp mà không bao giờ bị đắng.'),
(115,5,'Đảo săn hai mặt khóa ngọt nguyên liệu chính','Tăng lên lửa vừa lớn, gắp từng miếng trong 150g cốm tươi và 250g giò sống vào nồi đảo đều hoặc trở nhẹ hai mặt trong 4–5 phút cho săn chắc và bám đều lớp màu nâu óng. Khi bề mặt nguyên liệu se vàng thơm phức mới trút phần nước ướp còn lại trong tô vào đun sôi nhẹ. Nặn thành miếng dẹt, lót lá sen nếu có và hấp 8–10 phút đến khi chả se mặt, chín sơ.',5,'Đối với cá kho, chỉ lật cá một lần lúc cá vừa săn mặt trên lửa vừa để khúc cá nguyên vẹn không bị tróc da hay vỡ nát.');
INSERT INTO `recipe_steps` (`recipe_id`,`step_order`,`title`,`instruction`,`duration_mins`,`tip_note`) VALUES
(115,6,'Kho/om liu riu lửa nhỏ thấm đẫm cùng nước dừa/nước dùng','Chế 15ml dầu ăn xâm xắp mặt nguyên liệu (xếp thêm 2 lá lá sen nếu có), đun sôi bùng một dạo hớt sạch bọt rồi hạ ngay về mức lửa nhỏ liu riu nhất. Kho êm đềm không đậy kín nắp để từng thớ nguyên liệu chín mềm thấm đẫm gia vị và nước sốt rút dần sóng sánh. Làm nóng dầu vừa đủ, chiên chả lửa vừa 3–4 phút mỗi mặt đến vàng và phần thịt chín hẳn. Để ráo trước khi dùng.',8,'Luôn dùng nước sôi hoặc nước dừa ấm khi châm thêm vào nồi kho đang nóng để thịt cá không bị sượng cứng trở lại.'),
(115,7,'Thu sánh nước sốt óng ả & trình bày thưởng thức nóng','Khi nước kho rút còn khoảng 1/3 sánh kẹo óng ánh áo đều quanh nguyên liệu và xiên đũa thấy mềm mọng vừa ý, rắc hành ngò và tiêu xay lên mặt rồi tắt bếp. Múc món Chả cốm ra đĩa sâu lòng hoặc niêu đất giữ nhiệt, dọn ăn nóng cùng cơm trắng dẻo thơm cho 4 người.',4,'Giữ lại một lượng nước sốt sánh kẹo vừa đủ dưới đáy nồi để chan cơm hoặc chấm kèm rau luộc sẽ tròn vị đưa cơm gấp bội.'),
(116,1,'Sơ chế sạch & cắt thái nguyên liệu đúng kích cỡ','Rửa sạch 500g khoai lang và 90g bột năng cùng 50g bột mì dưới vòi nước mát rồi để thật ráo trên rổ thưa. Dùng dao sắc cắt thái nguyên liệu thành từng khúc hoặc khối vuông đều đặn khoảng 3.5–4cm để khi kho hầm giữ nguyên hình dáng đẹp mắt mà không bị vụn nát. Gọt khoai, cắt khúc và hấp 15–18 phút đến mềm. Tán nhuyễn khi còn nóng, bỏ xơ cứng nếu có.',6,'Cắt miếng thịt/cá dày dặn đồng đều giúp quá trình kho lâu trên lửa nhỏ thớ thịt mềm rục mà vẫn giữ trọn độ mọng ngọt bên trong.'),
(116,2,'Khử mùi tự nhiên & làm săn sạch bề mặt nguyên liệu','Chà nhẹ phần đạm chính trong 500g khoai lang và 90g bột năng với chút muối hạt, lát gừng đập dập hoặc chần sơ qua nước sôi 90 giây rồi rửa sạch lại bằng nước ấm, để ráo hoàn toàn. Công đoạn này loại bỏ triệt để tạp chất và mùi tanh hôi, giúp nước sốt món Khoai lang kén trong bóng thơm ngon.',4,'Sau khi chần hoặc rửa sạch, để nguyên liệu ráo nước ít nhất 5 phút trước khi ướp để gia vị rút sâu trực tiếp vào từng thớ thịt.'),
(116,3,'Pha hỗn hợp gia vị & ướp thấm chuẩn định lượng','Cho 500g khoai lang và 90g bột năng vào tô lớn, ướp cùng một nửa hành tím và tỏi băm nhỏ băm nhỏ và định lượng chuẩn 25g đường và 2g muối, đảo nhẹ tay cho gia vị phủ kín đều các mặt. Bọc kín tô và để nguyên liệu nghỉ thấm vị tối thiểu 20 phút ở nhiệt độ phòng (hoặc ngăn mát tủ lạnh). Trộn khoai với bột năng, bột mì, nước cốt dừa, đường và muối đến thành khối dẻo không dính tay.',6,'Ướp đủ tối thiểu 20 phút trước khi bắc lên bếp là chìa khóa để tâm miếng thịt/cá đậm đà đồng nhất với lớp sốt bên ngoài.'),
(116,4,'Thắng nước màu cánh gián & phi dậy hương hành tỏi','Đặt nồi đáy dày lên bếp ở lửa vừa nhỏ, thắng nhẹ 15g đường với 15ml dầu ăn đến khi chuyển sắc nâu cánh gián óng ả thì cho ngay phần hành tím và tỏi băm nhỏ còn lại vào phi thơm lừng. Hương caramel dịu ngọt quyện cùng tinh dầu hành tỏi sả tạo nền màu nâu hổ phách truyền thống đầy cuốn hút.',4,'Canh kỹ khoảnh khắc đường vừa chuyển màu cánh gián là hạ lửa nhỏ nhất ngay để nước màu bóng đẹp mà không bao giờ bị đắng.'),
(116,5,'Đảo săn hai mặt khóa ngọt nguyên liệu chính','Tăng lên lửa vừa lớn, gắp từng miếng trong 500g khoai lang và 90g bột năng vào nồi đảo đều hoặc trở nhẹ hai mặt trong 4–5 phút cho săn chắc và bám đều lớp màu nâu óng. Khi bề mặt nguyên liệu se vàng thơm phức mới trút phần nước ướp còn lại trong tô vào đun sôi nhẹ. Nặn thành miếng thuôn nhỏ cỡ ngón tay, lăn nhẹ qua mè trắng. Nếu bột mềm, để lạnh 15 phút cho dễ tạo hình.',6,'Đối với cá kho, chỉ lật cá một lần lúc cá vừa săn mặt trên lửa vừa để khúc cá nguyên vẹn không bị tróc da hay vỡ nát.'),
(116,6,'Kho/om liu riu lửa nhỏ thấm đẫm cùng nước dừa/nước dùng','Chế 60ml nước cốt dừa và 500ml dầu ăn xâm xắp mặt nguyên liệu (xếp thêm rau củ ăn kèm nếu có), đun sôi bùng một dạo hớt sạch bọt rồi hạ ngay về mức lửa nhỏ liu riu nhất. Kho êm đềm không đậy kín nắp để từng thớ nguyên liệu chín mềm thấm đẫm gia vị và nước sốt rút dần sóng sánh. Chiên ở 165–170°C từng mẻ 4–5 phút đến vàng đều. Vớt ra giá cho ráo, để nguội bớt trước khi ăn.',10,'Luôn dùng nước sôi hoặc nước dừa ấm khi châm thêm vào nồi kho đang nóng để thịt cá không bị sượng cứng trở lại.'),
(116,7,'Thu sánh nước sốt óng ả & trình bày thưởng thức nóng','Khi nước kho rút còn khoảng 1/3 sánh kẹo óng ánh áo đều quanh nguyên liệu và xiên đũa thấy mềm mọng vừa ý, rắc 20g mè trắng lên mặt rồi tắt bếp. Múc món Khoai lang kén ra đĩa sâu lòng hoặc niêu đất giữ nhiệt, dọn ăn nóng cùng cơm trắng dẻo thơm cho 4 người.',4,'Giữ lại một lượng nước sốt sánh kẹo vừa đủ dưới đáy nồi để chan cơm hoặc chấm kèm rau luộc sẽ tròn vị đưa cơm gấp bội.'),
(117,1,'Sơ chế sạch & cắt thái nguyên liệu đúng kích cỡ','Rửa sạch 600g cá hú cùng các nguyên liệu phối kèm dưới vòi nước mát rồi để thật ráo trên rổ thưa. Dùng dao sắc cắt thái nguyên liệu thành từng khúc hoặc khối vuông đều đặn khoảng 3.5–4cm để khi kho hầm giữ nguyên hình dáng đẹp mắt mà không bị vụn nát. Chần nhanh khứa cá hú với nước ấm pha muối loãng và chanh rồi rửa sạch, thấm khô.',6,'Cắt miếng thịt/cá dày dặn đồng đều giúp quá trình kho lâu trên lửa nhỏ thớ thịt mềm rục mà vẫn giữ trọn độ mọng ngọt bên trong.'),
(117,2,'Khử mùi tự nhiên & làm săn sạch bề mặt nguyên liệu','Chà nhẹ phần đạm chính trong 600g cá hú với chút muối hạt, lát gừng đập dập hoặc chần sơ qua nước sôi 90 giây rồi rửa sạch lại bằng nước ấm, để ráo hoàn toàn. Công đoạn này loại bỏ triệt để tạp chất và mùi tanh hôi, giúp nước sốt món Cá hú kho tộ nước dừa trong bóng thơm ngon.',4,'Sau khi chần hoặc rửa sạch, để nguyên liệu ráo nước ít nhất 5 phút trước khi ướp để gia vị rút sâu trực tiếp vào từng thớ thịt.'),
(117,3,'Pha hỗn hợp gia vị & ướp thấm chuẩn định lượng','Cho 600g cá hú vào tô lớn, ướp cùng một nửa 30g hành tím và 15g tỏi băm nhỏ và định lượng chuẩn 45ml nước mắm, 25g đường, 10g ớt và 5g tiêu, đảo nhẹ tay cho gia vị phủ kín đều các mặt. Bọc kín tô và để nguyên liệu nghỉ thấm vị tối thiểu 20 phút ở nhiệt độ phòng (hoặc ngăn mát tủ lạnh). Ướp cá với nước mắm, 15g đường, hành tím, tỏi băm và 1/2 phần tiêu trong 20 phút.',6,'Ướp đủ tối thiểu 20 phút trước khi bắc lên bếp là chìa khóa để tâm miếng thịt/cá đậm đà đồng nhất với lớp sốt bên ngoài.'),
(117,4,'Thắng nước màu cánh gián & phi dậy hương hành tỏi','Đặt nồi đáy dày lên bếp ở lửa vừa nhỏ, thắng nhẹ 15g đường với 15ml dầu ăn đến khi chuyển sắc nâu cánh gián óng ả thì cho ngay phần 30g hành tím và 15g tỏi còn lại vào phi thơm lừng. Hương caramel dịu ngọt quyện cùng tinh dầu hành tỏi sả tạo nền màu nâu hổ phách truyền thống đầy cuốn hút.',4,'Canh kỹ khoảnh khắc đường vừa chuyển màu cánh gián là hạ lửa nhỏ nhất ngay để nước màu bóng đẹp mà không bao giờ bị đắng.'),
(117,5,'Đảo săn hai mặt khóa ngọt nguyên liệu chính','Tăng lên lửa vừa lớn, gắp từng miếng trong 600g cá hú vào nồi đảo đều hoặc trở nhẹ hai mặt trong 4–5 phút cho săn chắc và bám đều lớp màu nâu óng. Khi bề mặt nguyên liệu se vàng thơm phức mới trút phần nước ướp còn lại trong tô vào đun sôi nhẹ. Thắng 10g đường còn lại lên màu cánh gián, xếp cá vào tộ đất nấu lửa vừa 3 phút cho săn thịt.',6,'Đối với cá kho, chỉ lật cá một lần lúc cá vừa săn mặt trên lửa vừa để khúc cá nguyên vẹn không bị tróc da hay vỡ nát.'),
(117,6,'Kho/om liu riu lửa nhỏ thấm đẫm cùng nước dừa/nước dùng','Chế 200ml nước dừa tươi xâm xắp mặt nguyên liệu (xếp thêm rau củ ăn kèm nếu có), đun sôi bùng một dạo hớt sạch bọt rồi hạ ngay về mức lửa nhỏ liu riu nhất. Kho êm đềm không đậy kín nắp để từng thớ nguyên liệu chín mềm thấm đẫm gia vị và nước sốt rút dần sóng sánh. Chế nước dừa tươi xăm xắp mặt cá, kho nhỏ lửa 15 phút đến khi nước sốt sánh kẹo; rắc hành lá, tiêu và ớt.',10,'Luôn dùng nước sôi hoặc nước dừa ấm khi châm thêm vào nồi kho đang nóng để thịt cá không bị sượng cứng trở lại.'),
(117,7,'Thu sánh nước sốt óng ả & trình bày thưởng thức nóng','Khi nước kho rút còn khoảng 1/3 sánh kẹo óng ánh áo đều quanh nguyên liệu và xiên đũa thấy mềm mọng vừa ý, rắc 25g hành lá lên mặt rồi tắt bếp. Múc món Cá hú kho tộ nước dừa ra đĩa sâu lòng hoặc niêu đất giữ nhiệt, dọn ăn nóng cùng cơm trắng dẻo thơm cho 4 người.',4,'Giữ lại một lượng nước sốt sánh kẹo vừa đủ dưới đáy nồi để chan cơm hoặc chấm kèm rau luộc sẽ tròn vị đưa cơm gấp bội.'),
(118,1,'Sơ chế sạch & cắt thái nguyên liệu đúng kích cỡ','Rửa sạch 700g đùi gà và 60g bột năng cùng 50g trứng gà và 50g gạo tẻ dưới vòi nước mát rồi để thật ráo trên rổ thưa. Dùng dao sắc cắt thái nguyên liệu thành từng khúc hoặc khối vuông đều đặn khoảng 3.5–4cm để khi kho hầm giữ nguyên hình dáng đẹp mắt mà không bị vụn nát. Ngâm gạo tẻ và đậu xanh 15 phút, để ráo rồi rang vàng khô trên chảo nhỏ; thêm muối rang tiếp 2 phút và xay mịn.',6,'Cắt miếng thịt/cá dày dặn đồng đều giúp quá trình kho lâu trên lửa nhỏ thớ thịt mềm rục mà vẫn giữ trọn độ mọng ngọt bên trong.'),
(118,2,'Khử mùi tự nhiên & làm săn sạch bề mặt nguyên liệu','Chà nhẹ phần đạm chính trong 700g đùi gà và 60g bột năng với chút muối hạt, lát gừng đập dập hoặc chần sơ qua nước sôi 90 giây rồi rửa sạch lại bằng nước ấm, để ráo hoàn toàn. Công đoạn này loại bỏ triệt để tạp chất và mùi tanh hôi, giúp nước sốt món Gà rang muối sả lá chanh trong bóng thơm ngon.',4,'Sau khi chần hoặc rửa sạch, để nguyên liệu ráo nước ít nhất 5 phút trước khi ướp để gia vị rút sâu trực tiếp vào từng thớ thịt.'),
(118,3,'Pha hỗn hợp gia vị & ướp thấm chuẩn định lượng','Cho 700g đùi gà và 60g bột năng vào tô lớn, ướp cùng một nửa 60g sả băm nhỏ và định lượng chuẩn 8g muối, đảo nhẹ tay cho gia vị phủ kín đều các mặt. Bọc kín tô và để nguyên liệu nghỉ thấm vị tối thiểu 20 phút ở nhiệt độ phòng (hoặc ngăn mát tủ lạnh). Ướp đùi gà với chút muối, tiêu và 1 thìa nước tương 15 phút; nhúng qua trứng gà đánh tan rồi lăn đều bột năng.',6,'Ướp đủ tối thiểu 20 phút trước khi bắc lên bếp là chìa khóa để tâm miếng thịt/cá đậm đà đồng nhất với lớp sốt bên ngoài.'),
(118,4,'Thắng nước màu cánh gián & phi dậy hương hành tỏi','Đặt nồi đáy dày lên bếp ở lửa vừa nhỏ, thắng nhẹ 15g đường với 15ml dầu ăn đến khi chuyển sắc nâu cánh gián óng ả thì cho ngay phần 60g sả còn lại vào phi thơm lừng. Hương caramel dịu ngọt quyện cùng tinh dầu hành tỏi sả tạo nền màu nâu hổ phách truyền thống đầy cuốn hút.',4,'Canh kỹ khoảnh khắc đường vừa chuyển màu cánh gián là hạ lửa nhỏ nhất ngay để nước màu bóng đẹp mà không bao giờ bị đắng.'),
(118,5,'Đảo săn hai mặt khóa ngọt nguyên liệu chính','Tăng lên lửa vừa lớn, gắp từng miếng trong 700g đùi gà và 60g bột năng vào nồi đảo đều hoặc trở nhẹ hai mặt trong 4–5 phút cho săn chắc và bám đều lớp màu nâu óng. Khi bề mặt nguyên liệu se vàng thơm phức mới trút phần nước ướp còn lại trong tô vào đun sôi nhẹ. Chiên ngập hoặc áp dầu vừa đến khi gà chín vàng giòn; vớt ra giấy thấm dầu. Chiên nhanh sợi sả và lá chanh 30 giây cho giòn.',6,'Đối với cá kho, chỉ lật cá một lần lúc cá vừa săn mặt trên lửa vừa để khúc cá nguyên vẹn không bị tróc da hay vỡ nát.'),
(118,6,'Kho/om liu riu lửa nhỏ thấm đẫm cùng nước dừa/nước dùng','Chế 60ml dầu ăn xâm xắp mặt nguyên liệu (xếp thêm rau củ ăn kèm nếu có), đun sôi bùng một dạo hớt sạch bọt rồi hạ ngay về mức lửa nhỏ liu riu nhất. Kho êm đềm không đậy kín nắp để từng thớ nguyên liệu chín mềm thấm đẫm gia vị và nước sốt rút dần sóng sánh. Cho gà vào chảo sạch, tắt bếp rồi rắc hỗn hợp muối rang cùng sả, lá chanh vào xóc đều tay và dọn nóng.',10,'Luôn dùng nước sôi hoặc nước dừa ấm khi châm thêm vào nồi kho đang nóng để thịt cá không bị sượng cứng trở lại.'),
(118,7,'Thu sánh nước sốt óng ả & trình bày thưởng thức nóng','Khi nước kho rút còn khoảng 1/3 sánh kẹo óng ánh áo đều quanh nguyên liệu và xiên đũa thấy mềm mọng vừa ý, rắc 15g lá chanh lên mặt rồi tắt bếp. Múc món Gà rang muối sả lá chanh ra đĩa sâu lòng hoặc niêu đất giữ nhiệt, dọn ăn nóng cùng cơm trắng dẻo thơm cho 4 người.',4,'Giữ lại một lượng nước sốt sánh kẹo vừa đủ dưới đáy nồi để chan cơm hoặc chấm kèm rau luộc sẽ tròn vị đưa cơm gấp bội.'),
(119,1,'Sơ chế sạch & cắt thái nguyên liệu đúng kích cỡ','Rửa sạch 500g thịt ba chỉ và 200g măng khô cùng các nguyên liệu phối kèm dưới vòi nước mát rồi để thật ráo trên rổ thưa. Dùng dao sắc cắt thái nguyên liệu thành từng khúc hoặc khối vuông đều đặn khoảng 3.5–4cm để khi kho hầm giữ nguyên hình dáng đẹp mắt mà không bị vụn nát. Luộc măng khô đã ngâm mềm 2 lần nước với nhúm muối đến khi nước trong, xé sợi to và cắt khúc 5 cm.',11,'Cắt miếng thịt/cá dày dặn đồng đều giúp quá trình kho lâu trên lửa nhỏ thớ thịt mềm rục mà vẫn giữ trọn độ mọng ngọt bên trong.'),
(119,2,'Khử mùi tự nhiên & làm săn sạch bề mặt nguyên liệu','Chà nhẹ phần đạm chính trong 500g thịt ba chỉ và 200g măng khô với chút muối hạt, lát gừng đập dập hoặc chần sơ qua nước sôi 90 giây rồi rửa sạch lại bằng nước ấm, để ráo hoàn toàn. Công đoạn này loại bỏ triệt để tạp chất và mùi tanh hôi, giúp nước sốt món Thịt ba chỉ kho măng khô trong bóng thơm ngon.',8,'Sau khi chần hoặc rửa sạch, để nguyên liệu ráo nước ít nhất 5 phút trước khi ướp để gia vị rút sâu trực tiếp vào từng thớ thịt.');
INSERT INTO `recipe_steps` (`recipe_id`,`step_order`,`title`,`instruction`,`duration_mins`,`tip_note`) VALUES
(119,3,'Pha hỗn hợp gia vị & ướp thấm chuẩn định lượng','Cho 500g thịt ba chỉ và 200g măng khô vào tô lớn, ướp cùng một nửa 30g hành tím băm nhỏ và định lượng chuẩn 40ml nước mắm, 25g đường và 4g tiêu, đảo nhẹ tay cho gia vị phủ kín đều các mặt. Bọc kín tô và để nguyên liệu nghỉ thấm vị tối thiểu 20 phút ở nhiệt độ phòng (hoặc ngăn mát tủ lạnh). Chần thịt ba chỉ 2 phút với nước sôi gừng hành, rửa sạch rồi ướp nước mắm, hành tím băm, tiêu và 15g đường.',11,'Ướp đủ tối thiểu 20 phút trước khi bắc lên bếp là chìa khóa để tâm miếng thịt/cá đậm đà đồng nhất với lớp sốt bên ngoài.'),
(119,4,'Thắng nước màu cánh gián & phi dậy hương hành tỏi','Đặt nồi đáy dày lên bếp ở lửa vừa nhỏ, thắng nhẹ 15g đường với 15ml dầu ăn đến khi chuyển sắc nâu cánh gián óng ả thì cho ngay phần 30g hành tím còn lại vào phi thơm lừng. Hương caramel dịu ngọt quyện cùng tinh dầu hành tỏi sả tạo nền màu nâu hổ phách truyền thống đầy cuốn hút.',8,'Canh kỹ khoảnh khắc đường vừa chuyển màu cánh gián là hạ lửa nhỏ nhất ngay để nước màu bóng đẹp mà không bao giờ bị đắng.'),
(119,5,'Đảo săn hai mặt khóa ngọt nguyên liệu chính','Tăng lên lửa vừa lớn, gắp từng miếng trong 500g thịt ba chỉ và 200g măng khô vào nồi đảo đều hoặc trở nhẹ hai mặt trong 4–5 phút cho săn chắc và bám đều lớp màu nâu óng. Khi bề mặt nguyên liệu se vàng thơm phức mới trút phần nước ướp còn lại trong tô vào đun sôi nhẹ. Thắng 10g đường thành nước màu, cho thịt vào đảo săn rồi thêm măng khô đảo đều cho măng thấm mỡ béo.',11,'Đối với cá kho, chỉ lật cá một lần lúc cá vừa săn mặt trên lửa vừa để khúc cá nguyên vẹn không bị tróc da hay vỡ nát.'),
(119,6,'Kho/om liu riu lửa nhỏ thấm đẫm cùng nước dừa/nước dùng','Chế 400ml nước lọc xâm xắp mặt nguyên liệu (xếp thêm rau củ ăn kèm nếu có), đun sôi bùng một dạo hớt sạch bọt rồi hạ ngay về mức lửa nhỏ liu riu nhất. Kho êm đềm không đậy kín nắp để từng thớ nguyên liệu chín mềm thấm đẫm gia vị và nước sốt rút dần sóng sánh. Đổ 400ml nước nóng xăm xắp nồi, kho lửa nhỏ 35 phút đến khi thịt mềm rục và nước kho còn 1/3; rắc hành lá.',18,'Luôn dùng nước sôi hoặc nước dừa ấm khi châm thêm vào nồi kho đang nóng để thịt cá không bị sượng cứng trở lại.'),
(119,7,'Thu sánh nước sốt óng ả & trình bày thưởng thức nóng','Khi nước kho rút còn khoảng 1/3 sánh kẹo óng ánh áo đều quanh nguyên liệu và xiên đũa thấy mềm mọng vừa ý, rắc 25g hành lá lên mặt rồi tắt bếp. Múc món Thịt ba chỉ kho măng khô ra đĩa sâu lòng hoặc niêu đất giữ nhiệt, dọn ăn nóng cùng cơm trắng dẻo thơm cho 4 người.',8,'Giữ lại một lượng nước sốt sánh kẹo vừa đủ dưới đáy nồi để chan cơm hoặc chấm kèm rau luộc sẽ tròn vị đưa cơm gấp bội.'),
(120,1,'Sơ chế & chần sạch nguyên liệu xương thịt, hải sản','Rửa sạch 500g bún tươi và 300g đậu hũ với muối hạt rồi chần nhanh trong nồi nước sôi có đập dập 1 nhánh gừng trong 2–3 phút trên lửa lớn để loại bỏ hoàn toàn bọt bẩn. Rửa lại dưới làn nước sạch cho thật trắng trẻo, đồng thời nhặt rửa sạch 150g dưa leo để ráo nước. Cuộn chặt thịt chân giò hoặc nạc vai bằng chỉ, luộc ngập nước với hành tím đập dập 25 phút rồi ngâm nước lạnh trước khi thái mỏng.',6,'Bước chần sơ và rửa lại bằng nước ấm là bí quyết vàng giúp nồi nước dùng trong vắt, thơm thanh và không bao giờ bị đục hay hôi.'),
(120,2,'Nướng thơm thảo mộc & ninh nền nước dùng ngọt thanh','Cho phần nguyên liệu tạo ngọt từ 500g bún tươi và 300g đậu hũ cùng hành tím và tỏi băm nhỏ đã nướng xém thơm vào nồi sâu lòng với khoảng 1.5–1.8 lít nước lọc. Đun sôi bùng trên lửa lớn rồi hạ ngay về lửa nhỏ liu riu, mở hé vung và hớt kỹ bọt nổi trên mặt để chiết xuất vị ngọt tự nhiên. Rán đậu hũ ngập dầu vừa vàng phồng bốn mặt giòn rụm; tiếp tục rán chả cốm chín vàng hai mặt, đặt ráo dầu.',12,'Luôn duy trì mặt nước lăn tăn nhẹ thay vì đun sôi sùng sục lửa to để protein không bị nhũ hóa gây đục nước lèo.'),
(120,3,'Xào tạo màu & dậy hương đặc trưng vùng miền','Bắc chảo nhỏ lên bếp với 15ml dầu ăn trên lửa vừa, phi thơm phần hành tỏi sả băm còn lại rồi xào săn 350g thịt heo (nạc vai) và 200g chả cốm cùng 50g mắm tôm, 30ml tắc và 20g đường trong 3–4 phút. Khi hỗn hợp dậy mùi thơm nồng nàn và lên sắc màu óng ả đặc trưng của món Bún đậu mắm tôm đầy đủ thì tắt bếp.',5,'Xào riêng phần nguyên liệu tạo màu và gia vị thơm trước khi trút vào nồi nước dùng giúp tầng hương dậy lên rõ nét gấp đôi.'),
(120,4,'Sơ chế & cắt thái phần nhân topping xếp tô','Vớt phần thịt hoặc hải sản chín tới từ 500g bún tươi và 300g đậu hũ ra ngâm ngay vào âu nước đun sôi để nguội giúp bề mặt săn giòn mọng nước, không bị thâm khô. Thái lát mỏng đều tay dày khoảng 3mm ngang thớ hoặc gỡ miếng vừa ăn, sắp riêng từng phần gọn gàng trên đĩa.',5,'Thái thịt ngang thớ với lưỡi dao thật sắc giúp lát thịt mềm mướt, khi chan nước dùng sôi lên sẽ phẳng đẹp không bị quăn cứng.'),
(120,5,'Hợp nhất nồi nước lèo & nêm chuẩn định lượng','Trút phần sốt màu thơm vào nồi nước dùng đang sôi lăn tăn, nêm chính xác lượng 50g mắm tôm, 30ml tắc và 20g đường còn lại cho vừa miệng 4 người ăn. Đun nhẹ thêm 5 phút ở lửa vừa để các tầng vị mặn dịu, ngọt hậu từ xương thịt và thảo mộc hòa quyện tròn trịa. Hòa mắm tôm cùng đường, nước cốt tắc, ớt tươi và 1 thìa dầu nóng vừa rán đậu rồi đánh bông sủi bọt.',5,'Nên nêm nước mắm ngon ở giai đoạn cuối trên lửa nhỏ để giữ trọn hậu vị ngọt đạm và hương thơm mà không làm nước dùng bị chua.'),
(120,6,'Chần nóng sợi bánh/bún & chuẩn bị rau ăn kèm','Đun sôi một nồi nước riêng, cho phần sợi bún/phở/bánh trong 500g bún tươi và 300g đậu hũ vào trụng nhanh 15–25 giây cho sợi mềm dẻo nóng hổi rồi vẩy thật ráo nước, chia đều vào 4 tô lớn. Chần sơ thêm rau ăn kèm (150g dưa leo) nếu muốn dùng chín giòn.',4,'Trụng bún bánh ở nồi nước sôi riêng biệt giúp nước dùng chính không bị nhiễm tinh bột chua và tô bún luôn ráo sợi, thấm vị.'),
(120,7,'Xếp nhân hài hòa, chan nước dùng sôi & thưởng thức','Xếp đều các phần nhân thịt, hải sản lên mặt tô bún bánh, điểm xuyết 50g tía tô lên trên cùng. Dùng muôi múc nước dùng đang sôi thật già chan ngập xăm xắp mặt nguyên liệu để làm chín thơm hành ngò, dọn nóng ngay kèm chanh ớt tươi. Xếp bún cắt miếng, thịt luộc, đậu hũ nóng giòn, chả cốm cùng dưa leo và rau tía tô kinh giới quanh chén mắm tôm.',3,'Tráng nóng tô sứ bằng nước sôi trước khi xếp bún giúp tô món nước giữ nhiệt bốc khói nghi ngút suốt bữa ăn.'),
(121,1,'Sơ chế & chần sạch nguyên liệu xương thịt, hải sản','Rửa sạch 450g thịt bò và 200g trứng gà với muối hạt rồi chần nhanh trong nồi nước sôi có đập dập 1 nhánh gừng trong 2–3 phút trên lửa lớn để loại bỏ hoàn toàn bọt bẩn. Rửa lại dưới làn nước sạch cho thật trắng trẻo, đồng thời nhặt rửa sạch 120g hành tây để ráo nước. Dần nhẹ miếng bò rồi ướp dầu hào, tỏi băm, tiêu và 1 thìa dầu ăn trong 15 phút.',4,'Bước chần sơ và rửa lại bằng nước ấm là bí quyết vàng giúp nồi nước dùng trong vắt, thơm thanh và không bao giờ bị đục hay hôi.'),
(121,2,'Nướng thơm thảo mộc & ninh nền nước dùng ngọt thanh','Cho phần nguyên liệu tạo ngọt từ 450g thịt bò và 200g trứng gà cùng 15g tỏi đã nướng xém thơm vào nồi sâu lòng với khoảng 1.5–1.8 lít nước lọc. Đun sôi bùng trên lửa lớn rồi hạ ngay về lửa nhỏ liu riu, mở hé vung và hớt kỹ bọt nổi trên mặt để chiết xuất vị ngọt tự nhiên. Đặt chảo gang lên bếp đến khi thật nóng, thả bơ lạt vào tan chảy rồi xếp hành tây xuống đáy.',9,'Luôn duy trì mặt nước lăn tăn nhẹ thay vì đun sôi sùng sục lửa to để protein không bị nhũ hóa gây đục nước lèo.'),
(121,3,'Xào tạo màu & dậy hương đặc trưng vùng miền','Bắc chảo nhỏ lên bếp với 15ml dầu ăn trên lửa vừa, phi thơm phần hành tỏi sả băm còn lại rồi xào săn 240g bánh mì và 150g cà chua cùng 25ml dầu hào và 30g tương cà trong 3–4 phút. Khi hỗn hợp dậy mùi thơm nồng nàn và lên sắc màu óng ả đặc trưng của món Bò né chảo gang ốp la thì tắt bếp.',3,'Xào riêng phần nguyên liệu tạo màu và gia vị thơm trước khi trút vào nồi nước dùng giúp tầng hương dậy lên rõ nét gấp đôi.'),
(121,4,'Sơ chế & cắt thái phần nhân topping xếp tô','Vớt phần thịt hoặc hải sản chín tới từ 450g thịt bò và 200g trứng gà ra ngâm ngay vào âu nước đun sôi để nguội giúp bề mặt săn giòn mọng nước, không bị thâm khô. Thái lát mỏng đều tay dày khoảng 3mm ngang thớ hoặc gỡ miếng vừa ăn, sắp riêng từng phần gọn gàng trên đĩa.',3,'Thái thịt ngang thớ với lưỡi dao thật sắc giúp lát thịt mềm mướt, khi chan nước dùng sôi lên sẽ phẳng đẹp không bị quăn cứng.'),
(121,5,'Hợp nhất nồi nước lèo & nêm chuẩn định lượng','Trút phần sốt màu thơm vào nồi nước dùng đang sôi lăn tăn, nêm chính xác lượng 25ml dầu hào và 30g tương cà còn lại cho vừa miệng 4 người ăn. Đun nhẹ thêm 5 phút ở lửa vừa để các tầng vị mặn dịu, ngọt hậu từ xương thịt và thảo mộc hòa quyện tròn trịa. Đặt bò vào áp chảo 1.5 phút mỗi mặt cho chín tái vừa; đập trứng gà và xếp khoanh cà chua vào góc chảo 2 phút.',3,'Nên nêm nước mắm ngon ở giai đoạn cuối trên lửa nhỏ để giữ trọn hậu vị ngọt đạm và hương thơm mà không làm nước dùng bị chua.'),
(121,6,'Chần nóng sợi bánh/bún & chuẩn bị rau ăn kèm','Đun sôi một nồi nước riêng, cho phần sợi bún/phở/bánh trong 450g thịt bò và 200g trứng gà vào trụng nhanh 15–25 giây cho sợi mềm dẻo nóng hổi rồi vẩy thật ráo nước, chia đều vào 4 tô lớn. Chần sơ thêm rau ăn kèm (120g hành tây) nếu muốn dùng chín giòn.',3,'Trụng bún bánh ở nồi nước sôi riêng biệt giúp nước dùng chính không bị nhiễm tinh bột chua và tô bún luôn ráo sợi, thấm vị.'),
(121,7,'Xếp nhân hài hòa, chan nước dùng sôi & thưởng thức','Xếp đều các phần nhân thịt, hải sản lên mặt tô bún bánh, điểm xuyết hành ngò và tiêu xay lên trên cùng. Dùng muôi múc nước dùng đang sôi thật già chan ngập xăm xắp mặt nguyên liệu để làm chín thơm hành ngò, dọn nóng ngay kèm chanh ớt tươi. Rắc tiêu xay và chút hành lá lên mặt chảo còn xèo xèo, rưới tương cà tương ớt ăn nóng cùng bánh mì.',2,'Tráng nóng tô sứ bằng nước sôi trước khi xếp bún giúp tô món nước giữ nhiệt bốc khói nghi ngút suốt bữa ăn.'),
(122,1,'Sơ chế sạch & cắt thái nguyên liệu đúng kích cỡ','Rửa sạch 700g thịt vịt cùng các nguyên liệu phối kèm dưới vòi nước mát rồi để thật ráo trên rổ thưa. Dùng dao sắc cắt thái nguyên liệu thành từng khúc hoặc khối vuông đều đặn khoảng 3.5–4cm để khi kho hầm giữ nguyên hình dáng đẹp mắt mà không bị vụn nát. Chà xát thịt vịt kỹ với gừng đập dập và muối hột trong 5 phút rồi xả sạch bằng nước lạnh, để ráo.',7,'Cắt miếng thịt/cá dày dặn đồng đều giúp quá trình kho lâu trên lửa nhỏ thớ thịt mềm rục mà vẫn giữ trọn độ mọng ngọt bên trong.'),
(122,2,'Khử mùi tự nhiên & làm săn sạch bề mặt nguyên liệu','Chà nhẹ phần đạm chính trong 700g thịt vịt với chút muối hạt, lát gừng đập dập hoặc chần sơ qua nước sôi 90 giây rồi rửa sạch lại bằng nước ấm, để ráo hoàn toàn. Công đoạn này loại bỏ triệt để tạp chất và mùi tanh hôi, giúp nước sốt món Vịt kho gừng thơm nồng trong bóng thơm ngon.',6,'Sau khi chần hoặc rửa sạch, để nguyên liệu ráo nước ít nhất 5 phút trước khi ướp để gia vị rút sâu trực tiếp vào từng thớ thịt.'),
(122,3,'Pha hỗn hợp gia vị & ướp thấm chuẩn định lượng','Cho 700g thịt vịt vào tô lớn, ướp cùng một nửa 60g gừng, 25g hành tím và 15g tỏi băm nhỏ và định lượng chuẩn 40ml nước mắm, 20g đường và 8g ớt, đảo nhẹ tay cho gia vị phủ kín đều các mặt. Bọc kín tô và để nguyên liệu nghỉ thấm vị tối thiểu 20 phút ở nhiệt độ phòng (hoặc ngăn mát tủ lạnh). Ướp thịt vịt cùng gừng băm, hành tím, tỏi, nước mắm, đường và tiêu trong 20 phút.',8,'Ướp đủ tối thiểu 20 phút trước khi bắc lên bếp là chìa khóa để tâm miếng thịt/cá đậm đà đồng nhất với lớp sốt bên ngoài.'),
(122,4,'Thắng nước màu cánh gián & phi dậy hương hành tỏi','Đặt nồi đáy dày lên bếp ở lửa vừa nhỏ, thắng nhẹ 15g đường với 15ml dầu ăn đến khi chuyển sắc nâu cánh gián óng ả thì cho ngay phần 60g gừng, 25g hành tím và 15g tỏi còn lại vào phi thơm lừng. Hương caramel dịu ngọt quyện cùng tinh dầu hành tỏi sả tạo nền màu nâu hổ phách truyền thống đầy cuốn hút.',5,'Canh kỹ khoảnh khắc đường vừa chuyển màu cánh gián là hạ lửa nhỏ nhất ngay để nước màu bóng đẹp mà không bao giờ bị đắng.'),
(122,5,'Đảo săn hai mặt khóa ngọt nguyên liệu chính','Tăng lên lửa vừa lớn, gắp từng miếng trong 700g thịt vịt vào nồi đảo đều hoặc trở nhẹ hai mặt trong 4–5 phút cho săn chắc và bám đều lớp màu nâu óng. Khi bề mặt nguyên liệu se vàng thơm phức mới trút phần nước ướp còn lại trong tô vào đun sôi nhẹ. Phi thơm phần tỏi hành còn lại, cho vịt vào đảo lửa lớn 6-8 phút đến khi thịt săn và ra bớt mỡ thừa; chắt bớt mỡ.',7,'Đối với cá kho, chỉ lật cá một lần lúc cá vừa săn mặt trên lửa vừa để khúc cá nguyên vẹn không bị tróc da hay vỡ nát.'),
(122,6,'Kho/om liu riu lửa nhỏ thấm đẫm cùng nước dừa/nước dùng','Chế 20ml dầu ăn xâm xắp mặt nguyên liệu (xếp thêm rau củ ăn kèm nếu có), đun sôi bùng một dạo hớt sạch bọt rồi hạ ngay về mức lửa nhỏ liu riu nhất. Kho êm đềm không đậy kín nắp để từng thớ nguyên liệu chín mềm thấm đẫm gia vị và nước sốt rút dần sóng sánh. Thêm 150ml nước sôi kho nhỏ lửa 20 phút đến khi nước cạn sền sệt; rắc gừng thái sợi và ớt đảo đều 2 phút rồi tắt bếp.',12,'Luôn dùng nước sôi hoặc nước dừa ấm khi châm thêm vào nồi kho đang nóng để thịt cá không bị sượng cứng trở lại.');
INSERT INTO `recipe_steps` (`recipe_id`,`step_order`,`title`,`instruction`,`duration_mins`,`tip_note`) VALUES
(122,7,'Thu sánh nước sốt óng ả & trình bày thưởng thức nóng','Khi nước kho rút còn khoảng 1/3 sánh kẹo óng ánh áo đều quanh nguyên liệu và xiên đũa thấy mềm mọng vừa ý, rắc hành ngò và tiêu xay lên mặt rồi tắt bếp. Múc món Vịt kho gừng thơm nồng ra đĩa sâu lòng hoặc niêu đất giữ nhiệt, dọn ăn nóng cùng cơm trắng dẻo thơm cho 4 người.',5,'Giữ lại một lượng nước sốt sánh kẹo vừa đủ dưới đáy nồi để chan cơm hoặc chấm kèm rau luộc sẽ tròn vị đưa cơm gấp bội.'),
(123,1,'Sơ chế sạch & cắt thái nguyên liệu đúng kích cỡ','Rửa sạch 800g cá chép và 350g dưa cải chua cùng 200g cà chua dưới vòi nước mát rồi để thật ráo trên rổ thưa. Dùng dao sắc cắt thái nguyên liệu thành từng khúc hoặc khối vuông đều đặn khoảng 3.5–4cm để khi kho hầm giữ nguyên hình dáng đẹp mắt mà không bị vụn nát. Rửa cá sạch màng đen bụng bằng muối chanh, thấm thật khô rồi rán sơ hai mặt cho da cá săn vàng nhẹ.',6,'Cắt miếng thịt/cá dày dặn đồng đều giúp quá trình kho lâu trên lửa nhỏ thớ thịt mềm rục mà vẫn giữ trọn độ mọng ngọt bên trong.'),
(123,2,'Khử mùi tự nhiên & làm săn sạch bề mặt nguyên liệu','Chà nhẹ phần đạm chính trong 800g cá chép và 350g dưa cải chua với chút muối hạt, lát gừng đập dập hoặc chần sơ qua nước sôi 90 giây rồi rửa sạch lại bằng nước ấm, để ráo hoàn toàn. Công đoạn này loại bỏ triệt để tạp chất và mùi tanh hôi, giúp nước sốt món Cá chép om dưa cải chua trong bóng thơm ngon.',5,'Sau khi chần hoặc rửa sạch, để nguyên liệu ráo nước ít nhất 5 phút trước khi ướp để gia vị rút sâu trực tiếp vào từng thớ thịt.'),
(123,3,'Pha hỗn hợp gia vị & ướp thấm chuẩn định lượng','Cho 800g cá chép và 350g dưa cải chua vào tô lớn, ướp cùng một nửa 15g nghệ băm nhỏ và định lượng chuẩn 30ml nước mắm, đảo nhẹ tay cho gia vị phủ kín đều các mặt. Bọc kín tô và để nguyên liệu nghỉ thấm vị tối thiểu 20 phút ở nhiệt độ phòng (hoặc ngăn mát tủ lạnh). Phi thơm hành tím, xào cà chua nhừ tạo màu rồi cho dưa cải chua vào xào săn 4 phút với chút nước mắm.',7,'Ướp đủ tối thiểu 20 phút trước khi bắc lên bếp là chìa khóa để tâm miếng thịt/cá đậm đà đồng nhất với lớp sốt bên ngoài.'),
(123,4,'Thắng nước màu cánh gián & phi dậy hương hành tỏi','Đặt nồi đáy dày lên bếp ở lửa vừa nhỏ, thắng nhẹ 15g đường với 15ml dầu ăn đến khi chuyển sắc nâu cánh gián óng ả thì cho ngay phần 15g nghệ còn lại vào phi thơm lừng. Hương caramel dịu ngọt quyện cùng tinh dầu hành tỏi sả tạo nền màu nâu hổ phách truyền thống đầy cuốn hút.',4,'Canh kỹ khoảnh khắc đường vừa chuyển màu cánh gián là hạ lửa nhỏ nhất ngay để nước màu bóng đẹp mà không bao giờ bị đắng.'),
(123,5,'Đảo săn hai mặt khóa ngọt nguyên liệu chính','Tăng lên lửa vừa lớn, gắp từng miếng trong 800g cá chép và 350g dưa cải chua vào nồi đảo đều hoặc trở nhẹ hai mặt trong 4–5 phút cho săn chắc và bám đều lớp màu nâu óng. Khi bề mặt nguyên liệu se vàng thơm phức mới trút phần nước ướp còn lại trong tô vào đun sôi nhẹ. Đặt cá lên lớp dưa chua cà chua, chế 500ml nước sôi ngập nửa thân cá, om nhỏ lửa 15 phút và trở nhẹ mặt cá một lần.',6,'Đối với cá kho, chỉ lật cá một lần lúc cá vừa săn mặt trên lửa vừa để khúc cá nguyên vẹn không bị tróc da hay vỡ nát.'),
(123,6,'Kho/om liu riu lửa nhỏ thấm đẫm cùng nước dừa/nước dùng','Chế 35ml dầu ăn xâm xắp mặt nguyên liệu (xếp thêm rau củ ăn kèm nếu có), đun sôi bùng một dạo hớt sạch bọt rồi hạ ngay về mức lửa nhỏ liu riu nhất. Kho êm đềm không đậy kín nắp để từng thớ nguyên liệu chín mềm thấm đẫm gia vị và nước sốt rút dần sóng sánh. Thả thì là và hành lá cắt khúc vào ngập mặt nước om 1 phút cuối rồi dọn nóng cùng bún hoặc cơm.',13,'Luôn dùng nước sôi hoặc nước dừa ấm khi châm thêm vào nồi kho đang nóng để thịt cá không bị sượng cứng trở lại.'),
(123,7,'Thu sánh nước sốt óng ả & trình bày thưởng thức nóng','Khi nước kho rút còn khoảng 1/3 sánh kẹo óng ánh áo đều quanh nguyên liệu và xiên đũa thấy mềm mọng vừa ý, rắc 40g thì là và 30g hành lá lên mặt rồi tắt bếp. Múc món Cá chép om dưa cải chua ra đĩa sâu lòng hoặc niêu đất giữ nhiệt, dọn ăn nóng cùng cơm trắng dẻo thơm cho 4 người.',4,'Giữ lại một lượng nước sốt sánh kẹo vừa đủ dưới đáy nồi để chan cơm hoặc chấm kèm rau luộc sẽ tròn vị đưa cơm gấp bội.'),
(124,1,'Sơ chế sạch & cắt thái nguyên liệu đúng kích cỡ','Rửa sạch 600g sườn cốt lết cùng các nguyên liệu phối kèm dưới vòi nước mát rồi để thật ráo trên rổ thưa. Dùng dao sắc cắt thái nguyên liệu thành từng khúc hoặc khối vuông đều đặn khoảng 3.5–4cm để khi kho hầm giữ nguyên hình dáng đẹp mắt mà không bị vụn nát. Khứa nhẹ viền mỡ sườn để khi áp chảo không bị cong, dần nhẹ mặt thịt rồi ướp 1/2 tỏi, dầu hào, nước mắm và tiêu 15 phút.',5,'Cắt miếng thịt/cá dày dặn đồng đều giúp quá trình kho lâu trên lửa nhỏ thớ thịt mềm rục mà vẫn giữ trọn độ mọng ngọt bên trong.'),
(124,2,'Khử mùi tự nhiên & làm săn sạch bề mặt nguyên liệu','Chà nhẹ phần đạm chính trong 600g sườn cốt lết với chút muối hạt, lát gừng đập dập hoặc chần sơ qua nước sôi 90 giây rồi rửa sạch lại bằng nước ấm, để ráo hoàn toàn. Công đoạn này loại bỏ triệt để tạp chất và mùi tanh hôi, giúp nước sốt món Sườn cốt lết rim tỏi ớt trong bóng thơm ngon.',4,'Sau khi chần hoặc rửa sạch, để nguyên liệu ráo nước ít nhất 5 phút trước khi ướp để gia vị rút sâu trực tiếp vào từng thớ thịt.'),
(124,3,'Pha hỗn hợp gia vị & ướp thấm chuẩn định lượng','Cho 600g sườn cốt lết vào tô lớn, ướp cùng một nửa 30g tỏi băm nhỏ và định lượng chuẩn 35ml nước mắm, 25g đường, 20ml dầu hào và 10g ớt, đảo nhẹ tay cho gia vị phủ kín đều các mặt. Bọc kín tô và để nguyên liệu nghỉ thấm vị tối thiểu 20 phút ở nhiệt độ phòng (hoặc ngăn mát tủ lạnh). Làm nóng chảo với dầu ăn, áp chảo sườn ở lửa vừa 3 phút mỗi mặt cho vàng thơm rồi gắp ra đĩa.',5,'Ướp đủ tối thiểu 20 phút trước khi bắc lên bếp là chìa khóa để tâm miếng thịt/cá đậm đà đồng nhất với lớp sốt bên ngoài.'),
(124,4,'Thắng nước màu cánh gián & phi dậy hương hành tỏi','Đặt nồi đáy dày lên bếp ở lửa vừa nhỏ, thắng nhẹ 15g đường với 15ml dầu ăn đến khi chuyển sắc nâu cánh gián óng ả thì cho ngay phần 30g tỏi còn lại vào phi thơm lừng. Hương caramel dịu ngọt quyện cùng tinh dầu hành tỏi sả tạo nền màu nâu hổ phách truyền thống đầy cuốn hút.',4,'Canh kỹ khoảnh khắc đường vừa chuyển màu cánh gián là hạ lửa nhỏ nhất ngay để nước màu bóng đẹp mà không bao giờ bị đắng.'),
(124,5,'Đảo săn hai mặt khóa ngọt nguyên liệu chính','Tăng lên lửa vừa lớn, gắp từng miếng trong 600g sườn cốt lết vào nồi đảo đều hoặc trở nhẹ hai mặt trong 4–5 phút cho săn chắc và bám đều lớp màu nâu óng. Khi bề mặt nguyên liệu se vàng thơm phức mới trút phần nước ướp còn lại trong tô vào đun sôi nhẹ. Phi thơm phần tỏi băm còn lại và ớt băm, hòa nước mắm, đường và 40ml nước lọc khuấy sôi sánh nhẹ.',5,'Đối với cá kho, chỉ lật cá một lần lúc cá vừa săn mặt trên lửa vừa để khúc cá nguyên vẹn không bị tróc da hay vỡ nát.'),
(124,6,'Kho/om liu riu lửa nhỏ thấm đẫm cùng nước dừa/nước dùng','Chế 30ml dầu ăn xâm xắp mặt nguyên liệu (xếp thêm rau củ ăn kèm nếu có), đun sôi bùng một dạo hớt sạch bọt rồi hạ ngay về mức lửa nhỏ liu riu nhất. Kho êm đềm không đậy kín nắp để từng thớ nguyên liệu chín mềm thấm đẫm gia vị và nước sốt rút dần sóng sánh. Cho sườn trở lại chảo đảo lật 2-3 phút đến khi nước sốt keo bóng áo đều hai mặt thịt.',8,'Luôn dùng nước sôi hoặc nước dừa ấm khi châm thêm vào nồi kho đang nóng để thịt cá không bị sượng cứng trở lại.'),
(124,7,'Thu sánh nước sốt óng ả & trình bày thưởng thức nóng','Khi nước kho rút còn khoảng 1/3 sánh kẹo óng ánh áo đều quanh nguyên liệu và xiên đũa thấy mềm mọng vừa ý, rắc hành ngò và tiêu xay lên mặt rồi tắt bếp. Múc món Sườn cốt lết rim tỏi ớt ra đĩa sâu lòng hoặc niêu đất giữ nhiệt, dọn ăn nóng cùng cơm trắng dẻo thơm cho 4 người.',4,'Giữ lại một lượng nước sốt sánh kẹo vừa đủ dưới đáy nồi để chan cơm hoặc chấm kèm rau luộc sẽ tròn vị đưa cơm gấp bội.'),
(125,1,'Sơ chế sạch & cắt thái nguyên liệu đúng kích cỡ','Rửa sạch 700g cá lóc và 500g bún tươi cùng các nguyên liệu phối kèm dưới vòi nước mát rồi để thật ráo trên rổ thưa. Dùng dao sắc cắt thái nguyên liệu thành từng khúc hoặc khối vuông đều đặn khoảng 3.5–4cm để khi kho hầm giữ nguyên hình dáng đẹp mắt mà không bị vụn nát. Trộn nước cốt riềng, nước cốt nghệ, mẻ lọc mịn, 1 thìa mắm tôm (hoặc nước mắm) và chút dầu ăn ướp vào cá 30 phút.',6,'Cắt miếng thịt/cá dày dặn đồng đều giúp quá trình kho lâu trên lửa nhỏ thớ thịt mềm rục mà vẫn giữ trọn độ mọng ngọt bên trong.'),
(125,2,'Khử mùi tự nhiên & làm săn sạch bề mặt nguyên liệu','Chà nhẹ phần đạm chính trong 700g cá lóc và 500g bún tươi với chút muối hạt, lát gừng đập dập hoặc chần sơ qua nước sôi 90 giây rồi rửa sạch lại bằng nước ấm, để ráo hoàn toàn. Công đoạn này loại bỏ triệt để tạp chất và mùi tanh hôi, giúp nước sốt món Chả cá Lã Vọng Hà Nội trong bóng thơm ngon.',5,'Sau khi chần hoặc rửa sạch, để nguyên liệu ráo nước ít nhất 5 phút trước khi ướp để gia vị rút sâu trực tiếp vào từng thớ thịt.'),
(125,3,'Pha hỗn hợp gia vị & ướp thấm chuẩn định lượng','Cho 700g cá lóc và 500g bún tươi vào tô lớn, ướp cùng một nửa 40g riềng tươi và 20g nghệ băm nhỏ và định lượng chuẩn 35g mẻ chua và 45g mắm tôm, đảo nhẹ tay cho gia vị phủ kín đều các mặt. Bọc kín tô và để nguyên liệu nghỉ thấm vị tối thiểu 20 phút ở nhiệt độ phòng (hoặc ngăn mát tủ lạnh). Xếp cá lên khay nướng 190°C khoảng 10 phút cho vàng săn hai mặt (hoặc áp chảo ít dầu).',6,'Ướp đủ tối thiểu 20 phút trước khi bắc lên bếp là chìa khóa để tâm miếng thịt/cá đậm đà đồng nhất với lớp sốt bên ngoài.'),
(125,4,'Thắng nước màu cánh gián & phi dậy hương hành tỏi','Đặt nồi đáy dày lên bếp ở lửa vừa nhỏ, thắng nhẹ 15g đường với 15ml dầu ăn đến khi chuyển sắc nâu cánh gián óng ả thì cho ngay phần 40g riềng tươi và 20g nghệ còn lại vào phi thơm lừng. Hương caramel dịu ngọt quyện cùng tinh dầu hành tỏi sả tạo nền màu nâu hổ phách truyền thống đầy cuốn hút.',4,'Canh kỹ khoảnh khắc đường vừa chuyển màu cánh gián là hạ lửa nhỏ nhất ngay để nước màu bóng đẹp mà không bao giờ bị đắng.'),
(125,5,'Đảo săn hai mặt khóa ngọt nguyên liệu chính','Tăng lên lửa vừa lớn, gắp từng miếng trong 700g cá lóc và 500g bún tươi vào nồi đảo đều hoặc trở nhẹ hai mặt trong 4–5 phút cho săn chắc và bám đều lớp màu nâu óng. Khi bề mặt nguyên liệu se vàng thơm phức mới trút phần nước ướp còn lại trong tô vào đun sôi nhẹ. Làm nóng chảo với dầu ăn, thả cá đã nướng cùng lượng lớn hành lá và thì là đảo đều 2 phút cho rau vừa chín tới.',6,'Đối với cá kho, chỉ lật cá một lần lúc cá vừa săn mặt trên lửa vừa để khúc cá nguyên vẹn không bị tróc da hay vỡ nát.'),
(125,6,'Kho/om liu riu lửa nhỏ thấm đẫm cùng nước dừa/nước dùng','Chế 45ml dầu ăn xâm xắp mặt nguyên liệu (xếp thêm rau củ ăn kèm nếu có), đun sôi bùng một dạo hớt sạch bọt rồi hạ ngay về mức lửa nhỏ liu riu nhất. Kho êm đềm không đậy kín nắp để từng thớ nguyên liệu chín mềm thấm đẫm gia vị và nước sốt rút dần sóng sánh. Gắp cá nóng, thì là vào chén bún tươi, rắc đậu phộng rang và chan mắm tôm đánh bông vị tắc.',12,'Luôn dùng nước sôi hoặc nước dừa ấm khi châm thêm vào nồi kho đang nóng để thịt cá không bị sượng cứng trở lại.'),
(125,7,'Thu sánh nước sốt óng ả & trình bày thưởng thức nóng','Khi nước kho rút còn khoảng 1/3 sánh kẹo óng ánh áo đều quanh nguyên liệu và xiên đũa thấy mềm mọng vừa ý, rắc 100g thì là, 100g hành lá và 50g đậu phộng lên mặt rồi tắt bếp. Múc món Chả cá Lã Vọng Hà Nội ra đĩa sâu lòng hoặc niêu đất giữ nhiệt, dọn ăn nóng cùng cơm trắng dẻo thơm cho 4 người.',4,'Giữ lại một lượng nước sốt sánh kẹo vừa đủ dưới đáy nồi để chan cơm hoặc chấm kèm rau luộc sẽ tròn vị đưa cơm gấp bội.'),
(126,1,'Sơ chế & chần sạch nguyên liệu xương thịt, hải sản','Rửa sạch 350g chả cá thác lác và 600g bún tươi với muối hạt rồi chần nhanh trong nồi nước sôi có đập dập 1 nhánh gừng trong 2–3 phút trên lửa lớn để loại bỏ hoàn toàn bọt bẩn. Rửa lại dưới làn nước sạch cho thật trắng trẻo, đồng thời nhặt rửa sạch 180g bí đỏ, 150g bắp cải và 120g măng tươi để ráo nước. Phi thơm hành tím với dầu điều cho đẹp màu, xào cà chua và dứa rồi chế 1.6 lít nước dùng nấu cùng bí đỏ, bắp cải và măng.',8,'Bước chần sơ và rửa lại bằng nước ấm là bí quyết vàng giúp nồi nước dùng trong vắt, thơm thanh và không bao giờ bị đục hay hôi.'),
(126,2,'Nướng thơm thảo mộc & ninh nền nước dùng ngọt thanh','Cho phần nguyên liệu tạo ngọt từ 350g chả cá thác lác và 600g bún tươi cùng hành tím và tỏi băm nhỏ đã nướng xém thơm vào nồi sâu lòng với khoảng 1.5–1.8 lít nước lọc. Đun sôi bùng trên lửa lớn rồi hạ ngay về lửa nhỏ liu riu, mở hé vung và hớt kỹ bọt nổi trên mặt để chiết xuất vị ngọt tự nhiên. Quết chả cá thác lác với tiêu và hành băm, nặn miếng dẹt chiên vàng đều hai mặt rồi cắt lát xéo.',20,'Luôn duy trì mặt nước lăn tăn nhẹ thay vì đun sôi sùng sục lửa to để protein không bị nhũ hóa gây đục nước lèo.'),
(126,3,'Xào tạo màu & dậy hương đặc trưng vùng miền','Bắc chảo nhỏ lên bếp với 15ml dầu ăn trên lửa vừa, phi thơm phần hành tỏi sả băm còn lại rồi xào săn 180g cà chua cùng 40ml nước mắm trong 3–4 phút. Khi hỗn hợp dậy mùi thơm nồng nàn và lên sắc màu óng ả đặc trưng của món Bún chả cá Đà Nẵng thì tắt bếp.',7,'Xào riêng phần nguyên liệu tạo màu và gia vị thơm trước khi trút vào nồi nước dùng giúp tầng hương dậy lên rõ nét gấp đôi.');
INSERT INTO `recipe_steps` (`recipe_id`,`step_order`,`title`,`instruction`,`duration_mins`,`tip_note`) VALUES
(126,4,'Sơ chế & cắt thái phần nhân topping xếp tô','Vớt phần thịt hoặc hải sản chín tới từ 350g chả cá thác lác và 600g bún tươi ra ngâm ngay vào âu nước đun sôi để nguội giúp bề mặt săn giòn mọng nước, không bị thâm khô. Thái lát mỏng đều tay dày khoảng 3mm ngang thớ hoặc gỡ miếng vừa ăn, sắp riêng từng phần gọn gàng trên đĩa.',7,'Thái thịt ngang thớ với lưỡi dao thật sắc giúp lát thịt mềm mướt, khi chan nước dùng sôi lên sẽ phẳng đẹp không bị quăn cứng.'),
(126,5,'Hợp nhất nồi nước lèo & nêm chuẩn định lượng','Trút phần sốt màu thơm vào nồi nước dùng đang sôi lăn tăn, nêm chính xác lượng 40ml nước mắm còn lại cho vừa miệng 4 người ăn. Đun nhẹ thêm 5 phút ở lửa vừa để các tầng vị mặn dịu, ngọt hậu từ xương thịt và thảo mộc hòa quyện tròn trịa. Khi bí đỏ mềm, nêm nước mắm ngon, hạt nêm cho vừa ăn và thả chả cá vào đun sôi nhẹ 3 phút.',7,'Nên nêm nước mắm ngon ở giai đoạn cuối trên lửa nhỏ để giữ trọn hậu vị ngọt đạm và hương thơm mà không làm nước dùng bị chua.'),
(126,6,'Chần nóng sợi bánh/bún & chuẩn bị rau ăn kèm','Đun sôi một nồi nước riêng, cho phần sợi bún/phở/bánh trong 350g chả cá thác lác và 600g bún tươi vào trụng nhanh 15–25 giây cho sợi mềm dẻo nóng hổi rồi vẩy thật ráo nước, chia đều vào 4 tô lớn. Chần sơ thêm rau ăn kèm (180g bí đỏ, 150g bắp cải và 120g măng tươi) nếu muốn dùng chín giòn.',6,'Trụng bún bánh ở nồi nước sôi riêng biệt giúp nước dùng chính không bị nhiễm tinh bột chua và tô bún luôn ráo sợi, thấm vị.'),
(126,7,'Xếp nhân hài hòa, chan nước dùng sôi & thưởng thức','Xếp đều các phần nhân thịt, hải sản lên mặt tô bún bánh, điểm xuyết 30g hành lá lên trên cùng. Dùng muôi múc nước dùng đang sôi thật già chan ngập xăm xắp mặt nguyên liệu để làm chín thơm hành ngò, dọn nóng ngay kèm chanh ớt tươi. Trụng bún tươi, xếp chả cá, cà chua, bí đỏ và rau thơm lên trên rồi chan nước dùng nóng, ăn kèm rau sống và mắm ruốc/sa tế.',5,'Tráng nóng tô sứ bằng nước sôi trước khi xếp bún giúp tô món nước giữ nhiệt bốc khói nghi ngút suốt bữa ăn.'),
(127,1,'Sơ chế & chần sạch nguyên liệu xương thịt, hải sản','Rửa sạch 320g hủ tiếu dai và 200g thịt heo xay với muối hạt rồi chần nhanh trong nồi nước sôi có đập dập 1 nhánh gừng trong 2–3 phút trên lửa lớn để loại bỏ hoàn toàn bọt bẩn. Rửa lại dưới làn nước sạch cho thật trắng trẻo, đồng thời nhặt rửa sạch 120g giá đỗ để ráo nước. Rang sơ tôm khô và hành tây nướng rồi thả vào nồi ninh với 1.8 lít nước dùng (hoặc xương heo) 40 phút cho nước ngọt trong.',11,'Bước chần sơ và rửa lại bằng nước ấm là bí quyết vàng giúp nồi nước dùng trong vắt, thơm thanh và không bao giờ bị đục hay hôi.'),
(127,2,'Nướng thơm thảo mộc & ninh nền nước dùng ngọt thanh','Cho phần nguyên liệu tạo ngọt từ 320g hủ tiếu dai và 200g thịt heo xay cùng hành tím và tỏi băm nhỏ đã nướng xém thơm vào nồi sâu lòng với khoảng 1.5–1.8 lít nước lọc. Đun sôi bùng trên lửa lớn rồi hạ ngay về lửa nhỏ liu riu, mở hé vung và hớt kỹ bọt nổi trên mặt để chiết xuất vị ngọt tự nhiên. Phi thơm tỏi, xào thịt heo xay chín tơi với chút nước tương và tiêu xay.',25,'Luôn duy trì mặt nước lăn tăn nhẹ thay vì đun sôi sùng sục lửa to để protein không bị nhũ hóa gây đục nước lèo.'),
(127,3,'Xào tạo màu & dậy hương đặc trưng vùng miền','Bắc chảo nhỏ lên bếp với 15ml dầu ăn trên lửa vừa, phi thơm phần hành tỏi sả băm còn lại rồi xào săn 200g thịt heo (nạc) và 200g tôm sú cùng 30ml nước tương trong 3–4 phút. Khi hỗn hợp dậy mùi thơm nồng nàn và lên sắc màu óng ả đặc trưng của món Hủ tiếu Nam Vang thanh ngọt thì tắt bếp.',10,'Xào riêng phần nguyên liệu tạo màu và gia vị thơm trước khi trút vào nồi nước dùng giúp tầng hương dậy lên rõ nét gấp đôi.'),
(127,4,'Sơ chế & cắt thái phần nhân topping xếp tô','Vớt phần thịt hoặc hải sản chín tới từ 320g hủ tiếu dai và 200g thịt heo xay ra ngâm ngay vào âu nước đun sôi để nguội giúp bề mặt săn giòn mọng nước, không bị thâm khô. Thái lát mỏng đều tay dày khoảng 3mm ngang thớ hoặc gỡ miếng vừa ăn, sắp riêng từng phần gọn gàng trên đĩa.',10,'Thái thịt ngang thớ với lưỡi dao thật sắc giúp lát thịt mềm mướt, khi chan nước dùng sôi lên sẽ phẳng đẹp không bị quăn cứng.'),
(127,5,'Hợp nhất nồi nước lèo & nêm chuẩn định lượng','Trút phần sốt màu thơm vào nồi nước dùng đang sôi lăn tăn, nêm chính xác lượng 30ml nước tương còn lại cho vừa miệng 4 người ăn. Đun nhẹ thêm 5 phút ở lửa vừa để các tầng vị mặn dịu, ngọt hậu từ xương thịt và thảo mộc hòa quyện tròn trịa. Luộc tôm sú vừa chín tới bóc vỏ chừa đuôi; luộc trứng cút bóc vỏ và chần sơ hẹ, giá đỗ.',10,'Nên nêm nước mắm ngon ở giai đoạn cuối trên lửa nhỏ để giữ trọn hậu vị ngọt đạm và hương thơm mà không làm nước dùng bị chua.'),
(127,6,'Chần nóng sợi bánh/bún & chuẩn bị rau ăn kèm','Đun sôi một nồi nước riêng, cho phần sợi bún/phở/bánh trong 320g hủ tiếu dai và 200g thịt heo xay vào trụng nhanh 15–25 giây cho sợi mềm dẻo nóng hổi rồi vẩy thật ráo nước, chia đều vào 4 tô lớn. Chần sơ thêm rau ăn kèm (120g giá đỗ) nếu muốn dùng chín giòn.',8,'Trụng bún bánh ở nồi nước sôi riêng biệt giúp nước dùng chính không bị nhiễm tinh bột chua và tô bún luôn ráo sợi, thấm vị.'),
(127,7,'Xếp nhân hài hòa, chan nước dùng sôi & thưởng thức','Xếp đều các phần nhân thịt, hải sản lên mặt tô bún bánh, điểm xuyết 35g hành lá và 20g hành phi lên trên cùng. Dùng muôi múc nước dùng đang sôi thật già chan ngập xăm xắp mặt nguyên liệu để làm chín thơm hành ngò, dọn nóng ngay kèm chanh ớt tươi. Trụng sợi hủ tiếu 45 giây cho dai vừa, xếp thịt thái, thịt băm, tôm, trứng cút, rắc hành phi, hẹ rồi chan nước dùng sôi.',6,'Tráng nóng tô sứ bằng nước sôi trước khi xếp bún giúp tô món nước giữ nhiệt bốc khói nghi ngút suốt bữa ăn.'),
(128,1,'Sơ chế sạch & thấm thật khô bề mặt nguyên liệu','Rửa sạch 600g cơm nguội và 150g trứng gà cùng chút muối loãng để khử mùi tự nhiên, sau đó dùng khăn giấy bếp thấm thật khô ráo hoàn toàn bề mặt. Khứa nhẹ các đường chéo hoặc cắt miếng vừa ăn dày 2–3cm để nhiệt và gia vị thấm sâu đều khắp bên trong. Đánh tan 2 lòng đỏ trứng (giữ 1 quả cho phần sau) trộn đều vào bát cơm nguội trước để từng hạt cơm tách rời và có màu vàng đẹp.',4,'Bề mặt nguyên liệu càng khô ráo thì khi chiên không bị văng dầu và khi nướng sẽ lên màu vàng ruộm giòn rụm cực đẹp.'),
(128,2,'Chuẩn bị hỗn hợp sốt ướp / bột áo chuẩn tỷ lệ','Phối trộn hành tím và tỏi băm nhỏ băm thật nhuyễn (hoặc vắt lấy nước cốt thơm) cùng 25ml nước tương trong tô lớn cho quyện sánh đồng nhất. Nếu món có lớp vỏ bột hoặc bánh cuốn từ 600g cơm nguội và 150g trứng gà, trộn đều hỗn hợp theo đúng định lượng để đạt độ giòn xốp mỏng nhẹ chuẩn vị. Luộc lạp xưởng 5 phút rồi cắt hạt lựu; chần nhanh cà rốt, đậu Hà Lan và bắp ngọt 2 phút cho chín đều; xào sơ tôm với chút tỏi.',4,'Vắt lấy nước cốt hành tỏi sả khi ướp đồ nướng giúp hương thơm thấm sâu mà không bị cháy đen phần xác băm trên lửa cao.'),
(128,3,'Ướp thấm thớ thịt / tạo hình cuốn khéo léo','Áo đều hỗn hợp gia vị hoặc lớp bột/vỏ cuốn quanh 600g cơm nguội và 150g trứng gà, massage nhẹ nhàng rồi để nghỉ 15–20 phút cho gia vị thẩm thấu trọn vẹn. Trường hợp cuốn chả/nem hoặc đổ khuôn bánh, thao tác đều tay vừa chặt để nhân kết dính nhưng không bị bục rách khi gặp nhiệt.',5,'Để nguyên liệu nghỉ đủ thời gian trước khi chiên nướng giúp lớp áo bột bám chắc và phần nhân bên trong mọng ngọt.'),
(128,4,'Pha nước chấm cân vị & sơ chế rau đồ chua ăn kèm','Nhặt rửa sạch 100g lạp xưởng, 60g đậu hà lan và 60g bắp ngọt ngâm nước mát cho giòn tươi, bào sợi hoặc thái lát gọn gàng bày sẵn bên cạnh. Pha chén nước chấm chua ngọt hoặc muối ớt chanh sả sánh thơm theo khẩu vị vùng miền của món Cơm chiên Dương Châu hạt tơi để cân bằng độ béo giòn.',4,'Luôn chuẩn bị xong rau sống và bát nước chấm trước khi chiên/nướng mẻ cuối để món ăn vừa ra lò là thưởng thức nóng giòn ngay.'),
(128,5,'Làm nóng dầu / lò nướng chuẩn nhiệt & làm chín đều lần 1','Làm nóng chảo dầu hoặc vỉ nướng/nồi chiên ở mức nhiệt vừa khoảng 165–175°C, xếp 600g cơm nguội và 150g trứng gà vào với khoảng cách thoáng đều nhau. Chiên hoặc nướng trở mặt nhịp nhàng trên lửa vừa để nhiệt dẫn sâu làm chín mềm ngọt hoàn toàn phần nhân bên trong. Đảo phần trứng còn lại tơi nhanh trong chảo dầu, trút cơm đã áo vàng vào đảo đều 5-6 phút đến khi hạt cơm săn nhảy lách tách.',8,'Kiểm tra nhiệt dầu bằng đầu đũa tre thấy sủi tăm nhỏ đều là đạt chuẩn 170°C, giúp vỏ không cháy sớm khi bên trong còn sống.'),
(128,6,'Tăng nhiệt khóa giòn rụm vàng ươm bề mặt lần 2','Ở 2–3 phút cuối, tăng lên lửa vừa lớn (khoảng 190°C) hoặc phết thêm lớp dầu điều/mật ong mỏng để vỏ ngoài của Cơm chiên Dương Châu hạt tơi chuyển sắc vàng óng ánh và nổ giòn rụm. Lắng nghe tiếng xèo giòn rộn rã và hương thơm phức lan tỏa khắp bếp thì gắp ra vỉ thưa cho ráo dầu thừa.',3,'Đặt đồ chiên nướng lên giá inox thoáng khí thay vì giấy thấm dầu chồng khít để hơi nước thoát hết, giữ độ giòn lâu gấp 3 lần.'),
(128,7,'Trình bày bắt mắt kèm rau thơm & thưởng thức nóng','Xếp thành phẩm vàng giòn ra đĩa lớn có bày sẵn 100g lạp xưởng, 60g đậu hà lan và 60g bắp ngọt và điểm xuyết 25g hành lá tươi xanh hài hòa màu sắc. Dọn kèm chén nước chấm sánh đậm ngay chính giữa mâm ăn cho 4 người thưởng thức khi vỏ ngoài còn nóng giòn rụm. Cho lạp xưởng, tôm và rau củ vào đảo đều tay, nêm nước tương, hạt nêm và rắc hành lá tiêu xay rồi tắt bếp.',2,'Cắt miếng hoặc dọn ăn ngay trong vòng 10 phút sau khi rời bếp để cảm nhận trọn vẹn sự đối lập giòn ngoài - mềm ngọt bên trong.'),
(129,1,'Sơ chế sạch & thấm thật khô bề mặt nguyên liệu','Rửa sạch 500g thịt bò và 300g khoai tây cùng chút muối loãng để khử mùi tự nhiên, sau đó dùng khăn giấy bếp thấm thật khô ráo hoàn toàn bề mặt. Khứa nhẹ các đường chéo hoặc cắt miếng vừa ăn dày 2–3cm để nhiệt và gia vị thấm sâu đều khắp bên trong. Ướp bò với dầu hào, 1 thìa nước tương, đường, tiêu, tỏi băm và 1 thìa dầu ăn trong 20 phút cho thấm.',5,'Bề mặt nguyên liệu càng khô ráo thì khi chiên không bị văng dầu và khi nướng sẽ lên màu vàng ruộm giòn rụm cực đẹp.'),
(129,2,'Chuẩn bị hỗn hợp sốt ướp / bột áo chuẩn tỷ lệ','Phối trộn 20g tỏi băm thật nhuyễn (hoặc vắt lấy nước cốt thơm) cùng 30ml dầu hào trong tô lớn cho quyện sánh đồng nhất. Nếu món có lớp vỏ bột hoặc bánh cuốn từ 500g thịt bò và 300g khoai tây, trộn đều hỗn hợp theo đúng định lượng để đạt độ giòn xốp mỏng nhẹ chuẩn vị. Ngâm khoai tây nước muối loãng rồi thấm thật khô, chiên chín vàng giòn trên chảo dầu hoặc nồi chiên không dầu 195°C.',5,'Vắt lấy nước cốt hành tỏi sả khi ướp đồ nướng giúp hương thơm thấm sâu mà không bị cháy đen phần xác băm trên lửa cao.'),
(129,3,'Ướp thấm thớ thịt / tạo hình cuốn khéo léo','Áo đều hỗn hợp gia vị hoặc lớp bột/vỏ cuốn quanh 500g thịt bò và 300g khoai tây, massage nhẹ nhàng rồi để nghỉ 15–20 phút cho gia vị thẩm thấu trọn vẹn. Trường hợp cuốn chả/nem hoặc đổ khuôn bánh, thao tác đều tay vừa chặt để nhân kết dính nhưng không bị bục rách khi gặp nhiệt.',6,'Để nguyên liệu nghỉ đủ thời gian trước khi chiên nướng giúp lớp áo bột bám chắc và phần nhân bên trong mọng ngọt.'),
(129,4,'Pha nước chấm cân vị & sơ chế rau đồ chua ăn kèm','Nhặt rửa sạch 150g ớt chuông, 100g hành tây và 100g xà lách ngâm nước mát cho giòn tươi, bào sợi hoặc thái lát gọn gàng bày sẵn bên cạnh. Pha chén nước chấm chua ngọt hoặc muối ớt chanh sả sánh thơm theo khẩu vị vùng miền của món Bò lúc lắc khoai tây chiên để cân bằng độ béo giòn.',4,'Luôn chuẩn bị xong rau sống và bát nước chấm trước khi chiên/nướng mẻ cuối để món ăn vừa ra lò là thưởng thức nóng giòn ngay.'),
(129,5,'Làm nóng dầu / lò nướng chuẩn nhiệt & làm chín đều lần 1','Làm nóng chảo dầu hoặc vỉ nướng/nồi chiên ở mức nhiệt vừa khoảng 165–175°C, xếp 500g thịt bò và 300g khoai tây vào với khoảng cách thoáng đều nhau. Chiên hoặc nướng trở mặt nhịp nhàng trên lửa vừa để nhiệt dẫn sâu làm chín mềm ngọt hoàn toàn phần nhân bên trong. Xào nhanh ớt chuông và hành tây trên lửa lớn 1 phút với chút gia vị cho chín giòn rồi trút ra riêng.',8,'Kiểm tra nhiệt dầu bằng đầu đũa tre thấy sủi tăm nhỏ đều là đạt chuẩn 170°C, giúp vỏ không cháy sớm khi bên trong còn sống.'),
(129,6,'Tăng nhiệt khóa giòn rụm vàng ươm bề mặt lần 2','Ở 2–3 phút cuối, tăng lên lửa vừa lớn (khoảng 190°C) hoặc phết thêm lớp dầu điều/mật ong mỏng để vỏ ngoài của Bò lúc lắc khoai tây chiên chuyển sắc vàng óng ánh và nổ giòn rụm. Lắng nghe tiếng xèo giòn rộn rã và hương thơm phức lan tỏa khắp bếp thì gắp ra vỉ thưa cho ráo dầu thừa.',4,'Đặt đồ chiên nướng lên giá inox thoáng khí thay vì giấy thấm dầu chồng khít để hơi nước thoát hết, giữ độ giòn lâu gấp 3 lần.'),
(129,7,'Trình bày bắt mắt kèm rau thơm & thưởng thức nóng','Xếp thành phẩm vàng giòn ra đĩa lớn có bày sẵn 150g ớt chuông, 100g hành tây và 100g xà lách và điểm xuyết hành ngò và tiêu xay tươi xanh hài hòa màu sắc. Dọn kèm chén nước chấm sánh đậm ngay chính giữa mâm ăn cho 4 người thưởng thức khi vỏ ngoài còn nóng giòn rụm. Đun nóng chảo dầu với tỏi đập dập và bơ lạt, trút bò vào đảo nhanh trên lửa cao nhất 2 phút vừa chín tới thì cho ớt chuông vào lắc đều; xếp lên đĩa xà lách cạnh khoai tây.',3,'Cắt miếng hoặc dọn ăn ngay trong vòng 10 phút sau khi rời bếp để cảm nhận trọn vẹn sự đối lập giòn ngoài - mềm ngọt bên trong.');
INSERT INTO `recipe_steps` (`recipe_id`,`step_order`,`title`,`instruction`,`duration_mins`,`tip_note`) VALUES
(130,1,'Sơ chế sạch & cắt thái nguyên liệu đúng kích cỡ','Rửa sạch 500g lươn đồng và 300g chuối xanh cùng 200g đậu hũ và 120g thịt ba chỉ dưới vòi nước mát rồi để thật ráo trên rổ thưa. Dùng dao sắc cắt thái nguyên liệu thành từng khúc hoặc khối vuông đều đặn khoảng 3.5–4cm để khi kho hầm giữ nguyên hình dáng đẹp mắt mà không bị vụn nát. Tuốt sạch nhớt lươn bằng muối và chanh, rửa nước ấm để ráo. Chuối xanh thái vát ngâm nước muối chanh tránh thâm rồi luộc sơ 3 phút.',8,'Cắt miếng thịt/cá dày dặn đồng đều giúp quá trình kho lâu trên lửa nhỏ thớ thịt mềm rục mà vẫn giữ trọn độ mọng ngọt bên trong.'),
(130,2,'Khử mùi tự nhiên & làm săn sạch bề mặt nguyên liệu','Chà nhẹ phần đạm chính trong 500g lươn đồng và 300g chuối xanh với chút muối hạt, lát gừng đập dập hoặc chần sơ qua nước sôi 90 giây rồi rửa sạch lại bằng nước ấm, để ráo hoàn toàn. Công đoạn này loại bỏ triệt để tạp chất và mùi tanh hôi, giúp nước sốt món Lươn om chuối đậu nghệ vàng trong bóng thơm ngon.',6,'Sau khi chần hoặc rửa sạch, để nguyên liệu ráo nước ít nhất 5 phút trước khi ướp để gia vị rút sâu trực tiếp vào từng thớ thịt.'),
(130,3,'Pha hỗn hợp gia vị & ướp thấm chuẩn định lượng','Cho 500g lươn đồng và 300g chuối xanh vào tô lớn, ướp cùng một nửa 25g nghệ băm nhỏ và định lượng chuẩn 30g mẻ chua, đảo nhẹ tay cho gia vị phủ kín đều các mặt. Bọc kín tô và để nguyên liệu nghỉ thấm vị tối thiểu 20 phút ở nhiệt độ phòng (hoặc ngăn mát tủ lạnh). Ướp lươn cùng nước cốt nghệ, hành tím băm, 1 thìa nước mắm và chút tiêu 15 phút.',8,'Ướp đủ tối thiểu 20 phút trước khi bắc lên bếp là chìa khóa để tâm miếng thịt/cá đậm đà đồng nhất với lớp sốt bên ngoài.'),
(130,4,'Thắng nước màu cánh gián & phi dậy hương hành tỏi','Đặt nồi đáy dày lên bếp ở lửa vừa nhỏ, thắng nhẹ 15g đường với 15ml dầu ăn đến khi chuyển sắc nâu cánh gián óng ả thì cho ngay phần 25g nghệ còn lại vào phi thơm lừng. Hương caramel dịu ngọt quyện cùng tinh dầu hành tỏi sả tạo nền màu nâu hổ phách truyền thống đầy cuốn hút.',6,'Canh kỹ khoảnh khắc đường vừa chuyển màu cánh gián là hạ lửa nhỏ nhất ngay để nước màu bóng đẹp mà không bao giờ bị đắng.'),
(130,5,'Đảo săn hai mặt khóa ngọt nguyên liệu chính','Tăng lên lửa vừa lớn, gắp từng miếng trong 500g lươn đồng và 300g chuối xanh vào nồi đảo đều hoặc trở nhẹ hai mặt trong 4–5 phút cho săn chắc và bám đều lớp màu nâu óng. Khi bề mặt nguyên liệu se vàng thơm phức mới trút phần nước ướp còn lại trong tô vào đun sôi nhẹ. Áp chảo thịt ba chỉ cho xém vàng, trút chuối xanh vào đảo cùng 1/2 phần nước mẻ và chút mắm cho thấm.',8,'Đối với cá kho, chỉ lật cá một lần lúc cá vừa săn mặt trên lửa vừa để khúc cá nguyên vẹn không bị tróc da hay vỡ nát.'),
(130,6,'Kho/om liu riu lửa nhỏ thấm đẫm cùng nước dừa/nước dùng','Chế 25ml dầu ăn xâm xắp mặt nguyên liệu (xếp thêm rau củ ăn kèm nếu có), đun sôi bùng một dạo hớt sạch bọt rồi hạ ngay về mức lửa nhỏ liu riu nhất. Kho êm đềm không đậy kín nắp để từng thớ nguyên liệu chín mềm thấm đẫm gia vị và nước sốt rút dần sóng sánh. Chế 400ml nước sôi đun liu riu 15 phút cho chuối bùi, thả đậu hũ chiên và lươn vào om tiếp 8 phút đến sánh nhẹ rồi rắc lá lốt, tía tô.',13,'Luôn dùng nước sôi hoặc nước dừa ấm khi châm thêm vào nồi kho đang nóng để thịt cá không bị sượng cứng trở lại.'),
(130,7,'Thu sánh nước sốt óng ả & trình bày thưởng thức nóng','Khi nước kho rút còn khoảng 1/3 sánh kẹo óng ánh áo đều quanh nguyên liệu và xiên đũa thấy mềm mọng vừa ý, rắc 35g tía tô và 25g lá lốt lên mặt rồi tắt bếp. Múc món Lươn om chuối đậu nghệ vàng ra đĩa sâu lòng hoặc niêu đất giữ nhiệt, dọn ăn nóng cùng cơm trắng dẻo thơm cho 4 người.',6,'Giữ lại một lượng nước sốt sánh kẹo vừa đủ dưới đáy nồi để chan cơm hoặc chấm kèm rau luộc sẽ tròn vị đưa cơm gấp bội.'),
(131,1,'Sơ chế sạch & cắt thái nguyên liệu đúng kích cỡ','Rửa sạch 650g đùi gà và 120g đậu hà lan cùng 250g khoai tây dưới vòi nước mát rồi để thật ráo trên rổ thưa. Dùng dao sắc cắt thái nguyên liệu thành từng khúc hoặc khối vuông đều đặn khoảng 3.5–4cm để khi kho hầm giữ nguyên hình dáng đẹp mắt mà không bị vụn nát. Ướp đùi gà với tỏi hành băm, muối, tiêu và 1 thìa dầu ăn; áp chảo nhanh hai mặt cho săn da vàng nhẹ.',8,'Cắt miếng thịt/cá dày dặn đồng đều giúp quá trình kho lâu trên lửa nhỏ thớ thịt mềm rục mà vẫn giữ trọn độ mọng ngọt bên trong.'),
(131,2,'Khử mùi tự nhiên & làm săn sạch bề mặt nguyên liệu','Chà nhẹ phần đạm chính trong 650g đùi gà và 120g đậu hà lan với chút muối hạt, lát gừng đập dập hoặc chần sơ qua nước sôi 90 giây rồi rửa sạch lại bằng nước ấm, để ráo hoàn toàn. Công đoạn này loại bỏ triệt để tạp chất và mùi tanh hôi, giúp nước sốt món Gà nấu đậu Hà Lan bánh mì trong bóng thơm ngon.',6,'Sau khi chần hoặc rửa sạch, để nguyên liệu ráo nước ít nhất 5 phút trước khi ướp để gia vị rút sâu trực tiếp vào từng thớ thịt.'),
(131,3,'Pha hỗn hợp gia vị & ướp thấm chuẩn định lượng','Cho 650g đùi gà và 120g đậu hà lan vào tô lớn, ướp cùng một nửa 25g hành tím băm nhỏ và định lượng chuẩn gia vị chuẩn định lượng, đảo nhẹ tay cho gia vị phủ kín đều các mặt. Bọc kín tô và để nguyên liệu nghỉ thấm vị tối thiểu 20 phút ở nhiệt độ phòng (hoặc ngăn mát tủ lạnh). Áp chảo sơ khoai tây và cà rốt 3 phút để khi hầm không bị vỡ bở.',8,'Ướp đủ tối thiểu 20 phút trước khi bắc lên bếp là chìa khóa để tâm miếng thịt/cá đậm đà đồng nhất với lớp sốt bên ngoài.'),
(131,4,'Thắng nước màu cánh gián & phi dậy hương hành tỏi','Đặt nồi đáy dày lên bếp ở lửa vừa nhỏ, thắng nhẹ 15g đường với 15ml dầu ăn đến khi chuyển sắc nâu cánh gián óng ả thì cho ngay phần 25g hành tím còn lại vào phi thơm lừng. Hương caramel dịu ngọt quyện cùng tinh dầu hành tỏi sả tạo nền màu nâu hổ phách truyền thống đầy cuốn hút.',6,'Canh kỹ khoảnh khắc đường vừa chuyển màu cánh gián là hạ lửa nhỏ nhất ngay để nước màu bóng đẹp mà không bao giờ bị đắng.'),
(131,5,'Đảo săn hai mặt khóa ngọt nguyên liệu chính','Tăng lên lửa vừa lớn, gắp từng miếng trong 650g đùi gà và 120g đậu hà lan vào nồi đảo đều hoặc trở nhẹ hai mặt trong 4–5 phút cho săn chắc và bám đều lớp màu nâu óng. Khi bề mặt nguyên liệu se vàng thơm phức mới trút phần nước ướp còn lại trong tô vào đun sôi nhẹ. Phi thơm hành tím với cà chua cô đặc, thả gà vào đảo đều rồi chế nước dừa tươi + 300ml nước lọc hầm nhỏ lửa 20 phút.',8,'Đối với cá kho, chỉ lật cá một lần lúc cá vừa săn mặt trên lửa vừa để khúc cá nguyên vẹn không bị tróc da hay vỡ nát.'),
(131,6,'Kho/om liu riu lửa nhỏ thấm đẫm cùng nước dừa/nước dùng','Chế 300ml nước dừa tươi xâm xắp mặt nguyên liệu (xếp thêm 250g khoai tây nếu có), đun sôi bùng một dạo hớt sạch bọt rồi hạ ngay về mức lửa nhỏ liu riu nhất. Kho êm đềm không đậy kín nắp để từng thớ nguyên liệu chín mềm thấm đẫm gia vị và nước sốt rút dần sóng sánh. Cho khoai tây, cà rốt và đậu Hà Lan vào đun tiếp 8 phút; hòa bột năng rót nhẹ tạo độ sánh mượt rồi dọn nóng cùng bánh mì.',13,'Luôn dùng nước sôi hoặc nước dừa ấm khi châm thêm vào nồi kho đang nóng để thịt cá không bị sượng cứng trở lại.'),
(131,7,'Thu sánh nước sốt óng ả & trình bày thưởng thức nóng','Khi nước kho rút còn khoảng 1/3 sánh kẹo óng ánh áo đều quanh nguyên liệu và xiên đũa thấy mềm mọng vừa ý, rắc hành ngò và tiêu xay lên mặt rồi tắt bếp. Múc món Gà nấu đậu Hà Lan bánh mì ra đĩa sâu lòng hoặc niêu đất giữ nhiệt, dọn ăn nóng cùng cơm trắng dẻo thơm cho 4 người.',6,'Giữ lại một lượng nước sốt sánh kẹo vừa đủ dưới đáy nồi để chan cơm hoặc chấm kèm rau luộc sẽ tròn vị đưa cơm gấp bội.'),
(132,1,'Sơ chế sạch & cắt thái nguyên liệu đúng kích cỡ','Rửa sạch 600g cá nục và 250g cà chua cùng các nguyên liệu phối kèm dưới vòi nước mát rồi để thật ráo trên rổ thưa. Dùng dao sắc cắt thái nguyên liệu thành từng khúc hoặc khối vuông đều đặn khoảng 3.5–4cm để khi kho hầm giữ nguyên hình dáng đẹp mắt mà không bị vụn nát. Moi sạch mang và ruột cá nục, rửa nước muối chanh cho hết tanh rồi rán sơ hai mặt cho chắc thịt.',8,'Cắt miếng thịt/cá dày dặn đồng đều giúp quá trình kho lâu trên lửa nhỏ thớ thịt mềm rục mà vẫn giữ trọn độ mọng ngọt bên trong.'),
(132,2,'Khử mùi tự nhiên & làm săn sạch bề mặt nguyên liệu','Chà nhẹ phần đạm chính trong 600g cá nục và 250g cà chua với chút muối hạt, lát gừng đập dập hoặc chần sơ qua nước sôi 90 giây rồi rửa sạch lại bằng nước ấm, để ráo hoàn toàn. Công đoạn này loại bỏ triệt để tạp chất và mùi tanh hôi, giúp nước sốt món Cá nục kho cà chua mía trong bóng thơm ngon.',7,'Sau khi chần hoặc rửa sạch, để nguyên liệu ráo nước ít nhất 5 phút trước khi ướp để gia vị rút sâu trực tiếp vào từng thớ thịt.'),
(132,3,'Pha hỗn hợp gia vị & ướp thấm chuẩn định lượng','Cho 600g cá nục và 250g cà chua vào tô lớn, ướp cùng một nửa 25g hành tím băm nhỏ và định lượng chuẩn 45ml nước mắm, 20g đường, 10g ớt và 4g tiêu, đảo nhẹ tay cho gia vị phủ kín đều các mặt. Bọc kín tô và để nguyên liệu nghỉ thấm vị tối thiểu 20 phút ở nhiệt độ phòng (hoặc ngăn mát tủ lạnh). Phi thơm hành tím, xào nhừ cà chua băm cùng nước mắm, đường và chút tiêu đến khi thành sốt sánh đỏ.',9,'Ướp đủ tối thiểu 20 phút trước khi bắc lên bếp là chìa khóa để tâm miếng thịt/cá đậm đà đồng nhất với lớp sốt bên ngoài.'),
(132,4,'Thắng nước màu cánh gián & phi dậy hương hành tỏi','Đặt nồi đáy dày lên bếp ở lửa vừa nhỏ, thắng nhẹ 15g đường với 15ml dầu ăn đến khi chuyển sắc nâu cánh gián óng ả thì cho ngay phần 25g hành tím còn lại vào phi thơm lừng. Hương caramel dịu ngọt quyện cùng tinh dầu hành tỏi sả tạo nền màu nâu hổ phách truyền thống đầy cuốn hút.',6,'Canh kỹ khoảnh khắc đường vừa chuyển màu cánh gián là hạ lửa nhỏ nhất ngay để nước màu bóng đẹp mà không bao giờ bị đắng.'),
(132,5,'Đảo săn hai mặt khóa ngọt nguyên liệu chính','Tăng lên lửa vừa lớn, gắp từng miếng trong 600g cá nục và 250g cà chua vào nồi đảo đều hoặc trở nhẹ hai mặt trong 4–5 phút cho săn chắc và bám đều lớp màu nâu óng. Khi bề mặt nguyên liệu se vàng thơm phức mới trút phần nước ướp còn lại trong tô vào đun sôi nhẹ. Xếp cá vào nồi sốt cà chua, châm 250ml nước sôi cùng vài trái ớt hiểm, kho lửa liu riu 30 phút cho sốt rút vào thân cá.',8,'Đối với cá kho, chỉ lật cá một lần lúc cá vừa săn mặt trên lửa vừa để khúc cá nguyên vẹn không bị tróc da hay vỡ nát.'),
(132,6,'Kho/om liu riu lửa nhỏ thấm đẫm cùng nước dừa/nước dùng','Chế 25ml dầu ăn xâm xắp mặt nguyên liệu (xếp thêm rau củ ăn kèm nếu có), đun sôi bùng một dạo hớt sạch bọt rồi hạ ngay về mức lửa nhỏ liu riu nhất. Kho êm đềm không đậy kín nắp để từng thớ nguyên liệu chín mềm thấm đẫm gia vị và nước sốt rút dần sóng sánh. Khi nước kho sánh keo, rắc hành lá thái nhỏ và tiêu xay rồi bắc bếp dọn cùng cơm nóng.',16,'Luôn dùng nước sôi hoặc nước dừa ấm khi châm thêm vào nồi kho đang nóng để thịt cá không bị sượng cứng trở lại.'),
(132,7,'Thu sánh nước sốt óng ả & trình bày thưởng thức nóng','Khi nước kho rút còn khoảng 1/3 sánh kẹo óng ánh áo đều quanh nguyên liệu và xiên đũa thấy mềm mọng vừa ý, rắc hành ngò và tiêu xay lên mặt rồi tắt bếp. Múc món Cá nục kho cà chua mía ra đĩa sâu lòng hoặc niêu đất giữ nhiệt, dọn ăn nóng cùng cơm trắng dẻo thơm cho 4 người.',6,'Giữ lại một lượng nước sốt sánh kẹo vừa đủ dưới đáy nồi để chan cơm hoặc chấm kèm rau luộc sẽ tròn vị đưa cơm gấp bội.'),
(133,1,'Sơ chế sạch & cắt thái nguyên liệu đúng kích cỡ','Rửa sạch 550g giò heo và 30g nấm mèo cùng 200g dưa cải chua dưới vòi nước mát rồi để thật ráo trên rổ thưa. Dùng dao sắc cắt thái nguyên liệu thành từng khúc hoặc khối vuông đều đặn khoảng 3.5–4cm để khi kho hầm giữ nguyên hình dáng đẹp mắt mà không bị vụn nát. Chần kỹ thịt giò heo trong nước sôi có hành gừng 4 phút rồi rửa sạch hết bọt cặn, ướp nước mắm, hành tím và tiêu.',11,'Cắt miếng thịt/cá dày dặn đồng đều giúp quá trình kho lâu trên lửa nhỏ thớ thịt mềm rục mà vẫn giữ trọn độ mọng ngọt bên trong.'),
(133,2,'Khử mùi tự nhiên & làm săn sạch bề mặt nguyên liệu','Chà nhẹ phần đạm chính trong 550g giò heo và 30g nấm mèo với chút muối hạt, lát gừng đập dập hoặc chần sơ qua nước sôi 90 giây rồi rửa sạch lại bằng nước ấm, để ráo hoàn toàn. Công đoạn này loại bỏ triệt để tạp chất và mùi tanh hôi, giúp nước sốt món Thịt đông dưa hành miền Bắc trong bóng thơm ngon.',8,'Sau khi chần hoặc rửa sạch, để nguyên liệu ráo nước ít nhất 5 phút trước khi ướp để gia vị rút sâu trực tiếp vào từng thớ thịt.'),
(133,3,'Pha hỗn hợp gia vị & ướp thấm chuẩn định lượng','Cho 550g giò heo và 30g nấm mèo vào tô lớn, ướp cùng một nửa 25g hành tím băm nhỏ và định lượng chuẩn 35ml nước mắm và 6g tiêu, đảo nhẹ tay cho gia vị phủ kín đều các mặt. Bọc kín tô và để nguyên liệu nghỉ thấm vị tối thiểu 20 phút ở nhiệt độ phòng (hoặc ngăn mát tủ lạnh). Phi thơm hành tím, xào thịt săn lại rồi cho nấm hương, nấm mèo vào đảo 3 phút cho dậy mùi thơm.',11,'Ướp đủ tối thiểu 20 phút trước khi bắc lên bếp là chìa khóa để tâm miếng thịt/cá đậm đà đồng nhất với lớp sốt bên ngoài.'),
(133,4,'Thắng nước màu cánh gián & phi dậy hương hành tỏi','Đặt nồi đáy dày lên bếp ở lửa vừa nhỏ, thắng nhẹ 15g đường với 15ml dầu ăn đến khi chuyển sắc nâu cánh gián óng ả thì cho ngay phần 25g hành tím còn lại vào phi thơm lừng. Hương caramel dịu ngọt quyện cùng tinh dầu hành tỏi sả tạo nền màu nâu hổ phách truyền thống đầy cuốn hút.',8,'Canh kỹ khoảnh khắc đường vừa chuyển màu cánh gián là hạ lửa nhỏ nhất ngay để nước màu bóng đẹp mà không bao giờ bị đắng.');
INSERT INTO `recipe_steps` (`recipe_id`,`step_order`,`title`,`instruction`,`duration_mins`,`tip_note`) VALUES
(133,5,'Đảo săn hai mặt khóa ngọt nguyên liệu chính','Tăng lên lửa vừa lớn, gắp từng miếng trong 550g giò heo và 30g nấm mèo vào nồi đảo đều hoặc trở nhẹ hai mặt trong 4–5 phút cho săn chắc và bám đều lớp màu nâu óng. Khi bề mặt nguyên liệu se vàng thơm phức mới trút phần nước ướp còn lại trong tô vào đun sôi nhẹ. Đổ 900ml nước sôi ngập thịt, ninh nhỏ lửa 40 phút và liên tục hớt sạch lớp váng bọt mỡ để nước dùng thật trong.',11,'Đối với cá kho, chỉ lật cá một lần lúc cá vừa săn mặt trên lửa vừa để khúc cá nguyên vẹn không bị tróc da hay vỡ nát.'),
(133,6,'Kho/om liu riu lửa nhỏ thấm đẫm cùng nước dừa/nước dùng','Chế lượng nước vừa ngập mặt nguyên liệu xâm xắp mặt nguyên liệu (xếp thêm 200g dưa cải chua nếu có), đun sôi bùng một dạo hớt sạch bọt rồi hạ ngay về mức lửa nhỏ liu riu nhất. Kho êm đềm không đậy kín nắp để từng thớ nguyên liệu chín mềm thấm đẫm gia vị và nước sốt rút dần sóng sánh. Xếp cà rốt tỉa hoa xuống đáy bát, rắc tiêu đập dập rồi múc thịt và nước hầm vào để nguội hoàn toàn và cho vào ngăn mát 5-6 giờ; úp đĩa ăn kèm dưa cải chua.',18,'Luôn dùng nước sôi hoặc nước dừa ấm khi châm thêm vào nồi kho đang nóng để thịt cá không bị sượng cứng trở lại.'),
(133,7,'Thu sánh nước sốt óng ả & trình bày thưởng thức nóng','Khi nước kho rút còn khoảng 1/3 sánh kẹo óng ánh áo đều quanh nguyên liệu và xiên đũa thấy mềm mọng vừa ý, rắc hành ngò và tiêu xay lên mặt rồi tắt bếp. Múc món Thịt đông dưa hành miền Bắc ra đĩa sâu lòng hoặc niêu đất giữ nhiệt, dọn ăn nóng cùng cơm trắng dẻo thơm cho 6 người.',8,'Giữ lại một lượng nước sốt sánh kẹo vừa đủ dưới đáy nồi để chan cơm hoặc chấm kèm rau luộc sẽ tròn vị đưa cơm gấp bội.'),
(134,1,'Sơ chế sạch & cắt thái nguyên liệu đúng kích cỡ','Rửa sạch 500g thịt gà (ức) và 350g cà chua cùng 80g hành tây dưới vòi nước mát rồi để thật ráo trên rổ thưa. Dùng dao sắc cắt thái nguyên liệu thành từng khúc hoặc khối vuông đều đặn khoảng 3.5–4cm để khi kho hầm giữ nguyên hình dáng đẹp mắt mà không bị vụn nát. Thấm khô ức gà, ướp cùng 10ml nước mắm, nửa phần hành tím băm, tiêu xay và 5ml dầu ăn trong 15 phút để thớ thịt ngấm vị và không bị khô bã.',5,'Cắt miếng thịt/cá dày dặn đồng đều giúp quá trình kho lâu trên lửa nhỏ thớ thịt mềm rục mà vẫn giữ trọn độ mọng ngọt bên trong.'),
(134,2,'Khử mùi tự nhiên & làm săn sạch bề mặt nguyên liệu','Chà nhẹ phần đạm chính trong 500g thịt gà (ức) và 350g cà chua với chút muối hạt, lát gừng đập dập hoặc chần sơ qua nước sôi 90 giây rồi rửa sạch lại bằng nước ấm, để ráo hoàn toàn. Công đoạn này loại bỏ triệt để tạp chất và mùi tanh hôi, giúp nước sốt món Ức gà sốt cà chua đậm đà trong bóng thơm ngon.',4,'Sau khi chần hoặc rửa sạch, để nguyên liệu ráo nước ít nhất 5 phút trước khi ướp để gia vị rút sâu trực tiếp vào từng thớ thịt.'),
(134,3,'Pha hỗn hợp gia vị & ướp thấm chuẩn định lượng','Cho 500g thịt gà (ức) và 350g cà chua vào tô lớn, ướp cùng một nửa 20g hành tím và 15g tỏi băm nhỏ và định lượng chuẩn 25ml nước mắm, 10g đường và 3g tiêu, đảo nhẹ tay cho gia vị phủ kín đều các mặt. Bọc kín tô và để nguyên liệu nghỉ thấm vị tối thiểu 20 phút ở nhiệt độ phòng (hoặc ngăn mát tủ lạnh). Đun nóng chảo với 10ml dầu ăn, cho ức gà vào áp chảo lửa vừa mỗi mặt 2.5 phút đến khi xém vàng nhẹ bên ngoài rồi gắp ra đĩa.',5,'Ướp đủ tối thiểu 20 phút trước khi bắc lên bếp là chìa khóa để tâm miếng thịt/cá đậm đà đồng nhất với lớp sốt bên ngoài.'),
(134,4,'Thắng nước màu cánh gián & phi dậy hương hành tỏi','Đặt nồi đáy dày lên bếp ở lửa vừa nhỏ, thắng nhẹ 15g đường với 15ml dầu ăn đến khi chuyển sắc nâu cánh gián óng ả thì cho ngay phần 20g hành tím và 15g tỏi còn lại vào phi thơm lừng. Hương caramel dịu ngọt quyện cùng tinh dầu hành tỏi sả tạo nền màu nâu hổ phách truyền thống đầy cuốn hút.',4,'Canh kỹ khoảnh khắc đường vừa chuyển màu cánh gián là hạ lửa nhỏ nhất ngay để nước màu bóng đẹp mà không bao giờ bị đắng.'),
(134,5,'Đảo săn hai mặt khóa ngọt nguyên liệu chính','Tăng lên lửa vừa lớn, gắp từng miếng trong 500g thịt gà (ức) và 350g cà chua vào nồi đảo đều hoặc trở nhẹ hai mặt trong 4–5 phút cho săn chắc và bám đều lớp màu nâu óng. Khi bề mặt nguyên liệu se vàng thơm phức mới trút phần nước ướp còn lại trong tô vào đun sôi nhẹ. Phi thơm hành tím và tỏi băm còn lại, cho cà chua chín cùng 50ml nước lọc vào dầm nhuyễn trên lửa vừa 6 phút; nêm 15ml nước mắm và 10g đường.',5,'Đối với cá kho, chỉ lật cá một lần lúc cá vừa săn mặt trên lửa vừa để khúc cá nguyên vẹn không bị tróc da hay vỡ nát.'),
(134,6,'Kho/om liu riu lửa nhỏ thấm đẫm cùng nước dừa/nước dùng','Chế 15ml dầu ăn xâm xắp mặt nguyên liệu (xếp thêm 80g hành tây nếu có), đun sôi bùng một dạo hớt sạch bọt rồi hạ ngay về mức lửa nhỏ liu riu nhất. Kho êm đềm không đậy kín nắp để từng thớ nguyên liệu chín mềm thấm đẫm gia vị và nước sốt rút dần sóng sánh. Trút ức gà và hành tây vào chảo sốt cà chua, đảo đều trên lửa nhỏ 4-5 phút cho sốt áo bóng quanh từng miếng gà; rắc hành lá và tiêu xay dọn nóng.',8,'Luôn dùng nước sôi hoặc nước dừa ấm khi châm thêm vào nồi kho đang nóng để thịt cá không bị sượng cứng trở lại.'),
(134,7,'Thu sánh nước sốt óng ả & trình bày thưởng thức nóng','Khi nước kho rút còn khoảng 1/3 sánh kẹo óng ánh áo đều quanh nguyên liệu và xiên đũa thấy mềm mọng vừa ý, rắc 20g hành lá lên mặt rồi tắt bếp. Múc món Ức gà sốt cà chua đậm đà ra đĩa sâu lòng hoặc niêu đất giữ nhiệt, dọn ăn nóng cùng cơm trắng dẻo thơm cho 4 người.',4,'Giữ lại một lượng nước sốt sánh kẹo vừa đủ dưới đáy nồi để chan cơm hoặc chấm kèm rau luộc sẽ tròn vị đưa cơm gấp bội.'),
(135,1,'Sơ chế & chần sạch nguyên liệu xương thịt, hải sản','Rửa sạch 650g thịt gà (đùi) và 600g bánh phở tươi với muối hạt rồi chần nhanh trong nồi nước sôi có đập dập 1 nhánh gừng trong 2–3 phút trên lửa lớn để loại bỏ hoàn toàn bọt bẩn. Rửa lại dưới làn nước sạch cho thật trắng trẻo, đồng thời nhặt rửa sạch 120g hành tây để ráo nước. Đặt thịt gà ngập trong 2 lít nước lạnh cùng gừng, hành tây nướng và nhúm muối; sôi lăn tăn hạ nhỏ lửa luộc 18 phút rồi tắt bếp ủ 15 phút.',10,'Bước chần sơ và rửa lại bằng nước ấm là bí quyết vàng giúp nồi nước dùng trong vắt, thơm thanh và không bao giờ bị đục hay hôi.'),
(135,2,'Nướng thơm thảo mộc & ninh nền nước dùng ngọt thanh','Cho phần nguyên liệu tạo ngọt từ 650g thịt gà (đùi) và 600g bánh phở tươi cùng 30g gừng và 5g hoa hồi đã nướng xém thơm vào nồi sâu lòng với khoảng 1.5–1.8 lít nước lọc. Đun sôi bùng trên lửa lớn rồi hạ ngay về lửa nhỏ liu riu, mở hé vung và hớt kỹ bọt nổi trên mặt để chiết xuất vị ngọt tự nhiên. Rang sơ hoa hồi, thảo quả (hoặc hạt mùi) thả túi vải vào nước luộc gà hầm tiếp 15 phút, hớt bọt kỹ và nêm nước mắm đường phèn.',23,'Luôn duy trì mặt nước lăn tăn nhẹ thay vì đun sôi sùng sục lửa to để protein không bị nhũ hóa gây đục nước lèo.'),
(135,3,'Xào tạo màu & dậy hương đặc trưng vùng miền','Bắc chảo nhỏ lên bếp với 15ml dầu ăn trên lửa vừa, phi thơm phần hành tỏi sả băm còn lại rồi xào săn 120g hành tây cùng 35ml nước mắm và 30ml chanh trong 3–4 phút. Khi hỗn hợp dậy mùi thơm nồng nàn và lên sắc màu óng ả đặc trưng của món Phở gà ta lá chanh Hà Nội thì tắt bếp.',8,'Xào riêng phần nguyên liệu tạo màu và gia vị thơm trước khi trút vào nồi nước dùng giúp tầng hương dậy lên rõ nét gấp đôi.'),
(135,4,'Sơ chế & cắt thái phần nhân topping xếp tô','Vớt phần thịt hoặc hải sản chín tới từ 650g thịt gà (đùi) và 600g bánh phở tươi ra ngâm ngay vào âu nước đun sôi để nguội giúp bề mặt săn giòn mọng nước, không bị thâm khô. Thái lát mỏng đều tay dày khoảng 3mm ngang thớ hoặc gỡ miếng vừa ăn, sắp riêng từng phần gọn gàng trên đĩa.',8,'Thái thịt ngang thớ với lưỡi dao thật sắc giúp lát thịt mềm mướt, khi chan nước dùng sôi lên sẽ phẳng đẹp không bị quăn cứng.'),
(135,5,'Hợp nhất nồi nước lèo & nêm chuẩn định lượng','Trút phần sốt màu thơm vào nồi nước dùng đang sôi lăn tăn, nêm chính xác lượng 35ml nước mắm và 30ml chanh còn lại cho vừa miệng 4 người ăn. Đun nhẹ thêm 5 phút ở lửa vừa để các tầng vị mặn dịu, ngọt hậu từ xương thịt và thảo mộc hòa quyện tròn trịa. Xé hoặc thái lát thịt gà vừa ăn; trụng bánh phở qua nước sôi 10 giây cho mềm dẻo rồi xếp vào tô sứ.',8,'Nên nêm nước mắm ngon ở giai đoạn cuối trên lửa nhỏ để giữ trọn hậu vị ngọt đạm và hương thơm mà không làm nước dùng bị chua.'),
(135,6,'Chần nóng sợi bánh/bún & chuẩn bị rau ăn kèm','Đun sôi một nồi nước riêng, cho phần sợi bún/phở/bánh trong 650g thịt gà (đùi) và 600g bánh phở tươi vào trụng nhanh 15–25 giây cho sợi mềm dẻo nóng hổi rồi vẩy thật ráo nước, chia đều vào 4 tô lớn. Chần sơ thêm rau ăn kèm (120g hành tây) nếu muốn dùng chín giòn.',7,'Trụng bún bánh ở nồi nước sôi riêng biệt giúp nước dùng chính không bị nhiễm tinh bột chua và tô bún luôn ráo sợi, thấm vị.'),
(135,7,'Xếp nhân hài hòa, chan nước dùng sôi & thưởng thức','Xếp đều các phần nhân thịt, hải sản lên mặt tô bún bánh, điểm xuyết 10g lá chanh và 45g hành lá lên trên cùng. Dùng muôi múc nước dùng đang sôi thật già chan ngập xăm xắp mặt nguyên liệu để làm chín thơm hành ngò, dọn nóng ngay kèm chanh ớt tươi. Xếp thịt gà, hành lá, ngò lên mặt bánh phở, chan nước dùng sôi bùng và rắc lá chanh thái chỉ kèm chanh ớt.',6,'Tráng nóng tô sứ bằng nước sôi trước khi xếp bún giúp tô món nước giữ nhiệt bốc khói nghi ngút suốt bữa ăn.'),
(136,1,'Sơ chế & chần sạch nguyên liệu xương thịt, hải sản','Rửa sạch 350g cua đồng xay và 250g ốc bươu với muối hạt rồi chần nhanh trong nồi nước sôi có đập dập 1 nhánh gừng trong 2–3 phút trên lửa lớn để loại bỏ hoàn toàn bọt bẩn. Rửa lại dưới làn nước sạch cho thật trắng trẻo, đồng thời nhặt rửa sạch 200g rau sống để ráo nước. Hòa cua xay với 1.5 lít nước lọc, gạn sạch vỏ qua rây; khuấy chút muối rồi đun lửa vừa không khuấy nữa khi nước ấm để thịt cua tự nổi kết tảng, vớt riêng phần gạch riêu.',10,'Bước chần sơ và rửa lại bằng nước ấm là bí quyết vàng giúp nồi nước dùng trong vắt, thơm thanh và không bao giờ bị đục hay hôi.'),
(136,2,'Nướng thơm thảo mộc & ninh nền nước dùng ngọt thanh','Cho phần nguyên liệu tạo ngọt từ 350g cua đồng xay và 250g ốc bươu cùng 30g hành tím đã nướng xém thơm vào nồi sâu lòng với khoảng 1.5–1.8 lít nước lọc. Đun sôi bùng trên lửa lớn rồi hạ ngay về lửa nhỏ liu riu, mở hé vung và hớt kỹ bọt nổi trên mặt để chiết xuất vị ngọt tự nhiên. Bóp thịt ốc với muối chanh rửa sạch, phi thơm hành tím tỏi xào nhanh ốc lửa lớn 2 phút với chút mắm gừng cho giòn.',23,'Luôn duy trì mặt nước lăn tăn nhẹ thay vì đun sôi sùng sục lửa to để protein không bị nhũ hóa gây đục nước lèo.'),
(136,3,'Xào tạo màu & dậy hương đặc trưng vùng miền','Bắc chảo nhỏ lên bếp với 15ml dầu ăn trên lửa vừa, phi thơm phần hành tỏi sả băm còn lại rồi xào săn 600g bún tươi và 200g đậu hũ cùng 35ml giấm và 35ml nước mắm trong 3–4 phút. Khi hỗn hợp dậy mùi thơm nồng nàn và lên sắc màu óng ả đặc trưng của món Bún riêu cua đồng ốc bươu thì tắt bếp.',8,'Xào riêng phần nguyên liệu tạo màu và gia vị thơm trước khi trút vào nồi nước dùng giúp tầng hương dậy lên rõ nét gấp đôi.'),
(136,4,'Sơ chế & cắt thái phần nhân topping xếp tô','Vớt phần thịt hoặc hải sản chín tới từ 350g cua đồng xay và 250g ốc bươu ra ngâm ngay vào âu nước đun sôi để nguội giúp bề mặt săn giòn mọng nước, không bị thâm khô. Thái lát mỏng đều tay dày khoảng 3mm ngang thớ hoặc gỡ miếng vừa ăn, sắp riêng từng phần gọn gàng trên đĩa.',8,'Thái thịt ngang thớ với lưỡi dao thật sắc giúp lát thịt mềm mướt, khi chan nước dùng sôi lên sẽ phẳng đẹp không bị quăn cứng.'),
(136,5,'Hợp nhất nồi nước lèo & nêm chuẩn định lượng','Trút phần sốt màu thơm vào nồi nước dùng đang sôi lăn tăn, nêm chính xác lượng 35ml giấm và 35ml nước mắm còn lại cho vừa miệng 4 người ăn. Đun nhẹ thêm 5 phút ở lửa vừa để các tầng vị mặn dịu, ngọt hậu từ xương thịt và thảo mộc hòa quyện tròn trịa. Chưng phần gạch cua vàng với dầu điều hành tím, cho cà chua vào xào mềm rồi trút vào nồi nước cua; nêm giấm bỗng và nước mắm vừa thanh chua.',8,'Nên nêm nước mắm ngon ở giai đoạn cuối trên lửa nhỏ để giữ trọn hậu vị ngọt đạm và hương thơm mà không làm nước dùng bị chua.'),
(136,6,'Chần nóng sợi bánh/bún & chuẩn bị rau ăn kèm','Đun sôi một nồi nước riêng, cho phần sợi bún/phở/bánh trong 350g cua đồng xay và 250g ốc bươu vào trụng nhanh 15–25 giây cho sợi mềm dẻo nóng hổi rồi vẩy thật ráo nước, chia đều vào 4 tô lớn. Chần sơ thêm rau ăn kèm (200g rau sống) nếu muốn dùng chín giòn.',7,'Trụng bún bánh ở nồi nước sôi riêng biệt giúp nước dùng chính không bị nhiễm tinh bột chua và tô bún luôn ráo sợi, thấm vị.'),
(136,7,'Xếp nhân hài hòa, chan nước dùng sôi & thưởng thức','Xếp đều các phần nhân thịt, hải sản lên mặt tô bún bánh, điểm xuyết hành ngò và tiêu xay lên trên cùng. Dùng muôi múc nước dùng đang sôi thật già chan ngập xăm xắp mặt nguyên liệu để làm chín thơm hành ngò, dọn nóng ngay kèm chanh ớt tươi. Cho bún, riêu cua, ốc xào, đậu hũ rán vào tô, chan nước dùng cà chua và dùng kèm mắm tôm, rau sống thái nhỏ.',6,'Tráng nóng tô sứ bằng nước sôi trước khi xếp bún giúp tô món nước giữ nhiệt bốc khói nghi ngút suốt bữa ăn.'),
(137,1,'Sơ chế sạch & cắt thái nguyên liệu nấu canh','Rửa sạch 450g khổ qua và 220g thịt heo xay, khử mùi tanh bằng chút muối hạt và gừng đập dập rồi rửa lại thật ráo, cắt miếng vừa ăn dày khoảng 2.5–3cm. Đồng thời gọt rửa sạch rau củ ăn kèm, cắt khúc hoặc bổ múi cau đồng đều để khi nấu chín đều không bị nát. Cắt khúc khổ qua 5 cm, nạo sạch thật kỹ lớp màng trắng bên trong; chần nhanh nước sôi pha xíu muối 1 phút rồi ngâm nước lạnh giữ màu xanh.',9,'Phân loại riêng nhóm củ cứng nấu lâu và nhóm rau lá mềm nhanh chín để cho vào nồi theo đúng thứ tự chuẩn đầu bếp.');
INSERT INTO `recipe_steps` (`recipe_id`,`step_order`,`title`,`instruction`,`duration_mins`,`tip_note`) VALUES
(137,2,'Ướp thấm gia vị nền cho nguyên liệu đạm','Cho phần đạm chính trong 450g khổ qua và 220g thịt heo xay vào tô, ướp nhẹ với một nửa lượng hành tím và tỏi băm nhỏ và 4g tiêu và 25ml nước mắm trong khoảng 10 phút. Đảo nhẹ tay cho gia vị áo đều bề mặt giúp miếng thịt, cá săn chắc và đậm đà từ bên trong khi thả vào nước canh. Trộn thịt heo xay, giò sống, nấm mèo, miến cắt vụn, đầu hành băm, nước mắm và tiêu xay cho dẻo quánh.',8,'Không ướp quá mặn ở bước này để giữ vị thanh mát tự nhiên của nước canh sau khi hoàn tất.'),
(137,3,'Phi thơm hành tỏi & xào săn khóa ngọt nguyên liệu','Đặt nồi canh lên bếp ở lửa vừa, làm nóng 15ml dầu ăn rồi phi thơm phần hành tím và tỏi băm nhỏ còn lại đến khi dậy mùi vàng óng. Trút nguyên liệu chính đã ướp vào đảo săn 2–3 phút cho bề mặt se lại, khóa trọn nước ngọt tự nhiên bên trong thớ thịt.',7,'Xào săn nguyên liệu đạm với hành tỏi phi trước khi đổ nước sôi giúp nước canh thơm ngọt đậm đà mà không hề tanh.'),
(137,4,'Đun sôi nước canh & hớt bọt giữ độ trong veo','Chế khoảng 1.1–1.3 lít nước (kết hợp lượng nước vừa ngập mặt nguyên liệu) vào nồi, bật lửa lớn đun đến khi sôi bùng rồi hạ ngay về lửa vừa. Dùng muôi hớt sạch lớp bọt đầu nổi lên trên mặt nước để nồi canh Canh khổ qua nhồi thịt thanh nhiệt đạt độ trong thanh đẹp mắt. Nhồi đầy nhân vừa tay vào từng khúc khổ qua, đặt vào 1.2 lít nước sôi nhẹ có đầu hành lá và nấu nhỏ lửa 20 phút.',11,'Sử dụng nước ấm hoặc nước sôi khi chế vào cá tươi sẽ giúp cá không bao giờ bị tanh nồng dù để nguội.'),
(137,5,'Thả rau củ theo độ chín & cân chỉnh định lượng vị','Lần lượt cho rau củ ăn kèm vào nồi canh đang sôi vừa (nhóm củ quả lâu chín cho trước 5–7 phút, nhóm rau mềm cho sau 1–2 phút). Nêm phần 4g tiêu và 25ml nước mắm còn lại, khuấy nhẹ và nếm thử thấy vị chua thanh hoặc ngọt dịu cân bằng đúng khẩu phần 4 người.',10,'Không đậy kín nắp vung sau khi đã thả các loại rau xanh vào nồi để giữ màu xanh ngọc tươi tắn hấp dẫn.'),
(137,6,'Điểm hương rau thơm & múc canh dọn nóng','Khi toàn bộ nguyên liệu vừa chín tới mềm ngọt, rắc ngay 30g hành lá vào nồi rồi tắt bếp liền tay để giữ trọn tinh dầu thơm mát. Múc canh nóng hổi ra tô lớn, rắc thêm chút tiêu xay hoặc tỏi phi vàng và dùng ngay với cơm nóng. Khi khổ qua chín mềm vừa xiên đũa, nêm lại muối nước mắm rồi rắc hành lá tiêu xay trước khi múc ra tô.',5,'Các loại rau thơm như thì là, ngò gai, rau om hay lá lốt chỉ nên thả ngay khoảnh khắc tắt bếp để hương thơm bùng nổ nhất.'),
(138,1,'Sơ chế sạch & cắt thái nguyên liệu nấu canh','Rửa sạch 450g bầu sao và 45g tôm khô, khử mùi tanh bằng chút muối hạt và gừng đập dập rồi rửa lại thật ráo, cắt miếng vừa ăn dày khoảng 2.5–3cm. Đồng thời gọt rửa sạch rau củ ăn kèm, cắt khúc hoặc bổ múi cau đồng đều để khi nấu chín đều không bị nát. Ngâm tôm khô trong nước ấm cho mềm, vớt ra giã hơi dập để nhanh tiết vị ngọt khi nấu.',4,'Phân loại riêng nhóm củ cứng nấu lâu và nhóm rau lá mềm nhanh chín để cho vào nồi theo đúng thứ tự chuẩn đầu bếp.'),
(138,2,'Ướp thấm gia vị nền cho nguyên liệu đạm','Cho phần đạm chính trong 450g bầu sao và 45g tôm khô vào tô, ướp nhẹ với một nửa lượng 15g hành tím và 20ml nước mắm và 3g tiêu trong khoảng 10 phút. Đảo nhẹ tay cho gia vị áo đều bề mặt giúp miếng thịt, cá săn chắc và đậm đà từ bên trong khi thả vào nước canh. Phi thơm hành tím với 1 thìa dầu ăn, cho tôm khô vào đảo đều 1 phút với xíu nước mắm.',4,'Không ướp quá mặn ở bước này để giữ vị thanh mát tự nhiên của nước canh sau khi hoàn tất.'),
(138,3,'Phi thơm hành tỏi & xào săn khóa ngọt nguyên liệu','Đặt nồi canh lên bếp ở lửa vừa, làm nóng 15ml dầu ăn rồi phi thơm phần 15g hành tím còn lại đến khi dậy mùi vàng óng. Trút nguyên liệu chính đã ướp vào đảo săn 2–3 phút cho bề mặt se lại, khóa trọn nước ngọt tự nhiên bên trong thớ thịt.',3,'Xào săn nguyên liệu đạm với hành tỏi phi trước khi đổ nước sôi giúp nước canh thơm ngọt đậm đà mà không hề tanh.'),
(138,4,'Đun sôi nước canh & hớt bọt giữ độ trong veo','Chế khoảng 1.1–1.3 lít nước (kết hợp 10ml dầu ăn) vào nồi, bật lửa lớn đun đến khi sôi bùng rồi hạ ngay về lửa vừa. Dùng muôi hớt sạch lớp bọt đầu nổi lên trên mặt nước để nồi canh Canh bầu nấu tôm khô ngọt thanh đạt độ trong thanh đẹp mắt. Đổ 1 lít nước lọc đun sôi 5 phút cho tôm ra ngọt rồi thả bầu thái lát vào nấu lửa vừa 4-5 phút đến khi bầu trong mềm vừa tới.',6,'Sử dụng nước ấm hoặc nước sôi khi chế vào cá tươi sẽ giúp cá không bao giờ bị tanh nồng dù để nguội.'),
(138,5,'Thả rau củ theo độ chín & cân chỉnh định lượng vị','Lần lượt cho rau củ ăn kèm vào nồi canh đang sôi vừa (nhóm củ quả lâu chín cho trước 5–7 phút, nhóm rau mềm cho sau 1–2 phút). Nêm phần 20ml nước mắm và 3g tiêu còn lại, khuấy nhẹ và nếm thử thấy vị chua thanh hoặc ngọt dịu cân bằng đúng khẩu phần 4 người.',5,'Không đậy kín nắp vung sau khi đã thả các loại rau xanh vào nồi để giữ màu xanh ngọc tươi tắn hấp dẫn.'),
(138,6,'Điểm hương rau thơm & múc canh dọn nóng','Khi toàn bộ nguyên liệu vừa chín tới mềm ngọt, rắc ngay 25g hành lá vào nồi rồi tắt bếp liền tay để giữ trọn tinh dầu thơm mát. Múc canh nóng hổi ra tô lớn, rắc thêm chút tiêu xay hoặc tỏi phi vàng và dùng ngay với cơm nóng. Nêm lại muối vừa miệng, tắt bếp rồi thả hành lá cắt nhỏ và tiêu xay.',2,'Các loại rau thơm như thì là, ngò gai, rau om hay lá lốt chỉ nên thả ngay khoảnh khắc tắt bếp để hương thơm bùng nổ nhất.'),
(139,1,'Sơ chế sạch & cắt thái nguyên liệu nấu canh','Rửa sạch 250g mướp hương và 200g mồng tơi, khử mùi tanh bằng chút muối hạt và gừng đập dập rồi rửa lại thật ráo, cắt miếng vừa ăn dày khoảng 2.5–3cm. Đồng thời gọt rửa sạch rau củ ăn kèm, cắt khúc hoặc bổ múi cau đồng đều để khi nấu chín đều không bị nát. Ướp thịt băm chút nước mắm tiêu, phi thơm hành tím rồi xào tơi thịt 2 phút.',4,'Phân loại riêng nhóm củ cứng nấu lâu và nhóm rau lá mềm nhanh chín để cho vào nồi theo đúng thứ tự chuẩn đầu bếp.'),
(139,2,'Ướp thấm gia vị nền cho nguyên liệu đạm','Cho phần đạm chính trong 250g mướp hương và 200g mồng tơi vào tô, ướp nhẹ với một nửa lượng 15g hành tím và 20ml nước mắm trong khoảng 10 phút. Đảo nhẹ tay cho gia vị áo đều bề mặt giúp miếng thịt, cá săn chắc và đậm đà từ bên trong khi thả vào nước canh. Khi nước thịt sôi, thả mướp hương thái vát vào nấu lửa vừa 3 phút.',3,'Không ướp quá mặn ở bước này để giữ vị thanh mát tự nhiên của nước canh sau khi hoàn tất.'),
(139,3,'Phi thơm hành tỏi & xào săn khóa ngọt nguyên liệu','Đặt nồi canh lên bếp ở lửa vừa, làm nóng 15ml dầu ăn rồi phi thơm phần 15g hành tím còn lại đến khi dậy mùi vàng óng. Trút nguyên liệu chính đã ướp vào đảo săn 2–3 phút cho bề mặt se lại, khóa trọn nước ngọt tự nhiên bên trong thớ thịt.',3,'Xào săn nguyên liệu đạm với hành tỏi phi trước khi đổ nước sôi giúp nước canh thơm ngọt đậm đà mà không hề tanh.'),
(139,4,'Đun sôi nước canh & hớt bọt giữ độ trong veo','Chế khoảng 1.1–1.3 lít nước (kết hợp 10ml dầu ăn) vào nồi, bật lửa lớn đun đến khi sôi bùng rồi hạ ngay về lửa vừa. Dùng muôi hớt sạch lớp bọt đầu nổi lên trên mặt nước để nồi canh Canh mướp hương mồng tơi thịt băm đạt độ trong thanh đẹp mắt. Cho rau mồng tơi vào nhấn chìm nước sôi 2 phút cho vừa chín tới rồi tắt bếp ngay.',4,'Sử dụng nước ấm hoặc nước sôi khi chế vào cá tươi sẽ giúp cá không bao giờ bị tanh nồng dù để nguội.'),
(139,5,'Thả rau củ theo độ chín & cân chỉnh định lượng vị','Lần lượt cho rau củ ăn kèm vào nồi canh đang sôi vừa (nhóm củ quả lâu chín cho trước 5–7 phút, nhóm rau mềm cho sau 1–2 phút). Nêm phần 20ml nước mắm còn lại, khuấy nhẹ và nếm thử thấy vị chua thanh hoặc ngọt dịu cân bằng đúng khẩu phần 4 người.',4,'Không đậy kín nắp vung sau khi đã thả các loại rau xanh vào nồi để giữ màu xanh ngọc tươi tắn hấp dẫn.'),
(139,6,'Điểm hương rau thơm & múc canh dọn nóng','Khi toàn bộ nguyên liệu vừa chín tới mềm ngọt, rắc ngay hành ngò và tiêu xay vào nồi rồi tắt bếp liền tay để giữ trọn tinh dầu thơm mát. Múc canh nóng hổi ra tô lớn, rắc thêm chút tiêu xay hoặc tỏi phi vàng và dùng ngay với cơm nóng. Nêm lại nước mắm muối vừa ăn và múc ra tô lớn.',2,'Các loại rau thơm như thì là, ngò gai, rau om hay lá lốt chỉ nên thả ngay khoảnh khắc tắt bếp để hương thơm bùng nổ nhất.'),
(140,1,'Sơ chế sạch & cắt thái nguyên liệu nấu canh','Rửa sạch 650g giò heo và 250g măng khô, khử mùi tanh bằng chút muối hạt và gừng đập dập rồi rửa lại thật ráo, cắt miếng vừa ăn dày khoảng 2.5–3cm. Đồng thời gọt rửa sạch rau củ ăn kèm, cắt khúc hoặc bổ múi cau đồng đều để khi nấu chín đều không bị nát. Ngâm măng khô qua đêm, luộc sôi mở nắp 2-3 lần nước đến khi nước trong hoàn toàn, xé sợi bản to vừa.',15,'Phân loại riêng nhóm củ cứng nấu lâu và nhóm rau lá mềm nhanh chín để cho vào nồi theo đúng thứ tự chuẩn đầu bếp.'),
(140,2,'Ướp thấm gia vị nền cho nguyên liệu đạm','Cho phần đạm chính trong 650g giò heo và 250g măng khô vào tô, ướp nhẹ với một nửa lượng 25g hành tím và 35ml nước mắm và 4g tiêu trong khoảng 10 phút. Đảo nhẹ tay cho gia vị áo đều bề mặt giúp miếng thịt, cá săn chắc và đậm đà từ bên trong khi thả vào nước canh. Chần khoanh giò heo qua nước sôi gừng muối 4 phút rồi rửa sạch hết bọt cặn bẩn.',14,'Không ướp quá mặn ở bước này để giữ vị thanh mát tự nhiên của nước canh sau khi hoàn tất.'),
(140,3,'Phi thơm hành tỏi & xào săn khóa ngọt nguyên liệu','Đặt nồi canh lên bếp ở lửa vừa, làm nóng 15ml dầu ăn rồi phi thơm phần 25g hành tím còn lại đến khi dậy mùi vàng óng. Trút nguyên liệu chính đã ướp vào đảo săn 2–3 phút cho bề mặt se lại, khóa trọn nước ngọt tự nhiên bên trong thớ thịt.',12,'Xào săn nguyên liệu đạm với hành tỏi phi trước khi đổ nước sôi giúp nước canh thơm ngọt đậm đà mà không hề tanh.'),
(140,4,'Đun sôi nước canh & hớt bọt giữ độ trong veo','Chế khoảng 1.1–1.3 lít nước (kết hợp 15ml dầu ăn) vào nồi, bật lửa lớn đun đến khi sôi bùng rồi hạ ngay về lửa vừa. Dùng muôi hớt sạch lớp bọt đầu nổi lên trên mặt nước để nồi canh Canh măng giò heo ngày Tết đạt độ trong thanh đẹp mắt. Phi thơm hành tím, xào măng với nước mắm 4 phút cho măng săn đậm đà.',19,'Sử dụng nước ấm hoặc nước sôi khi chế vào cá tươi sẽ giúp cá không bao giờ bị tanh nồng dù để nguội.'),
(140,5,'Thả rau củ theo độ chín & cân chỉnh định lượng vị','Lần lượt cho rau củ ăn kèm vào nồi canh đang sôi vừa (nhóm củ quả lâu chín cho trước 5–7 phút, nhóm rau mềm cho sau 1–2 phút). Nêm phần 35ml nước mắm và 4g tiêu còn lại, khuấy nhẹ và nếm thử thấy vị chua thanh hoặc ngọt dịu cân bằng đúng khẩu phần 4 người.',17,'Không đậy kín nắp vung sau khi đã thả các loại rau xanh vào nồi để giữ màu xanh ngọc tươi tắn hấp dẫn.'),
(140,6,'Điểm hương rau thơm & múc canh dọn nóng','Khi toàn bộ nguyên liệu vừa chín tới mềm ngọt, rắc ngay 35g hành lá vào nồi rồi tắt bếp liền tay để giữ trọn tinh dầu thơm mát. Múc canh nóng hổi ra tô lớn, rắc thêm chút tiêu xay hoặc tỏi phi vàng và dùng ngay với cơm nóng. Đổ 1.6 lít nước sôi hầm lửa nhỏ 45 phút đến khi giò mềm và măng ngấm ngọt béo; nêm nếm lại rồi rắc hành lá tiêu.',8,'Các loại rau thơm như thì là, ngò gai, rau om hay lá lốt chỉ nên thả ngay khoảnh khắc tắt bếp để hương thơm bùng nổ nhất.'),
(141,1,'Sơ chế sạch & cắt thái nguyên liệu nấu canh','Rửa sạch 300g cua đồng xay và 150g rau đay, khử mùi tanh bằng chút muối hạt và gừng đập dập rồi rửa lại thật ráo, cắt miếng vừa ăn dày khoảng 2.5–3cm. Đồng thời gọt rửa sạch 150g mồng tơi và 180g mướp hương, cắt khúc hoặc bổ múi cau đồng đều để khi nấu chín đều không bị nát. Hòa cua xay cùng 1.2 lít nước và 6g muối, bóp tan rồi lọc qua rây bỏ xác vỏ.',6,'Phân loại riêng nhóm củ cứng nấu lâu và nhóm rau lá mềm nhanh chín để cho vào nồi theo đúng thứ tự chuẩn đầu bếp.'),
(141,2,'Ướp thấm gia vị nền cho nguyên liệu đạm','Cho phần đạm chính trong 300g cua đồng xay và 150g rau đay vào tô, ướp nhẹ với một nửa lượng 15g hành tím và 20ml nước mắm và 6g muối trong khoảng 10 phút. Đảo nhẹ tay cho gia vị áo đều bề mặt giúp miếng thịt, cá săn chắc và đậm đà từ bên trong khi thả vào nước canh. Đặt nồi nước cua lên bếp lửa vừa, không khuấy khi nước nóng già để thịt cua kết mảng nổi lên; gạt nhẹ riêu sang một bên.',6,'Không ướp quá mặn ở bước này để giữ vị thanh mát tự nhiên của nước canh sau khi hoàn tất.');
INSERT INTO `recipe_steps` (`recipe_id`,`step_order`,`title`,`instruction`,`duration_mins`,`tip_note`) VALUES
(141,3,'Phi thơm hành tỏi & xào săn khóa ngọt nguyên liệu','Đặt nồi canh lên bếp ở lửa vừa, làm nóng 15ml dầu ăn rồi phi thơm phần 15g hành tím còn lại đến khi dậy mùi vàng óng. Trút nguyên liệu chính đã ướp vào đảo săn 2–3 phút cho bề mặt se lại, khóa trọn nước ngọt tự nhiên bên trong thớ thịt.',5,'Xào săn nguyên liệu đạm với hành tỏi phi trước khi đổ nước sôi giúp nước canh thơm ngọt đậm đà mà không hề tanh.'),
(141,4,'Đun sôi nước canh & hớt bọt giữ độ trong veo','Chế khoảng 1.1–1.3 lít nước (kết hợp lượng nước vừa ngập mặt nguyên liệu) vào nồi, bật lửa lớn đun đến khi sôi bùng rồi hạ ngay về lửa vừa. Dùng muôi hớt sạch lớp bọt đầu nổi lên trên mặt nước để nồi canh Canh cua nấu rau đay mồng tơi đạt độ trong thanh đẹp mắt. Thả mướp hương nấu 2 phút rồi cho rau đay, mồng tơi thái vừa vào nhấn nhẹ chìm dưới nước sôi.',7,'Sử dụng nước ấm hoặc nước sôi khi chế vào cá tươi sẽ giúp cá không bao giờ bị tanh nồng dù để nguội.'),
(141,5,'Thả rau củ theo độ chín & cân chỉnh định lượng vị','Lần lượt cho 150g mồng tơi và 180g mướp hương vào nồi canh đang sôi vừa (nhóm củ quả lâu chín cho trước 5–7 phút, nhóm rau mềm cho sau 1–2 phút). Nêm phần 20ml nước mắm và 6g muối còn lại, khuấy nhẹ và nếm thử thấy vị chua thanh hoặc ngọt dịu cân bằng đúng khẩu phần 4 người.',7,'Không đậy kín nắp vung sau khi đã thả các loại rau xanh vào nồi để giữ màu xanh ngọc tươi tắn hấp dẫn.'),
(141,6,'Điểm hương rau thơm & múc canh dọn nóng','Khi toàn bộ nguyên liệu vừa chín tới mềm ngọt, rắc ngay hành ngò và tiêu xay vào nồi rồi tắt bếp liền tay để giữ trọn tinh dầu thơm mát. Múc canh nóng hổi ra tô lớn, rắc thêm chút tiêu xay hoặc tỏi phi vàng và dùng ngay với cơm nóng. Nêm chút nước mắm ngon, múc rau vào tô trước rồi đặt gạch riêu lên mặt.',4,'Các loại rau thơm như thì là, ngò gai, rau om hay lá lốt chỉ nên thả ngay khoảnh khắc tắt bếp để hương thơm bùng nổ nhất.'),
(142,1,'Sơ chế sạch & cắt thái nguyên liệu nấu canh','Rửa sạch 550g cá lóc và 180g cà chua, khử mùi tanh bằng chút muối hạt và gừng đập dập rồi rửa lại thật ráo, cắt miếng vừa ăn dày khoảng 2.5–3cm. Đồng thời gọt rửa sạch 150g dứa, 120g đậu bắp và 100g giá đỗ, cắt khúc hoặc bổ múi cau đồng đều để khi nấu chín đều không bị nát. Chà sạch nhớt cá với muối chanh để ráo; bóp dọc mùng với muối rồi xả sạch vắt ráo để không bị ngứa.',7,'Phân loại riêng nhóm củ cứng nấu lâu và nhóm rau lá mềm nhanh chín để cho vào nồi theo đúng thứ tự chuẩn đầu bếp.'),
(142,2,'Ướp thấm gia vị nền cho nguyên liệu đạm','Cho phần đạm chính trong 550g cá lóc và 180g cà chua vào tô, ướp nhẹ với một nửa lượng 15g tỏi và 45g me vắt và 35ml nước mắm trong khoảng 10 phút. Đảo nhẹ tay cho gia vị áo đều bề mặt giúp miếng thịt, cá săn chắc và đậm đà từ bên trong khi thả vào nước canh. Dầm me với nước sôi lọc bỏ hạt, đun sôi 1.4 lít nước cùng nước me, dứa, 1/2 cà chua, nước mắm và đường.',6,'Không ướp quá mặn ở bước này để giữ vị thanh mát tự nhiên của nước canh sau khi hoàn tất.'),
(142,3,'Phi thơm hành tỏi & xào săn khóa ngọt nguyên liệu','Đặt nồi canh lên bếp ở lửa vừa, làm nóng 15ml dầu ăn rồi phi thơm phần 15g tỏi còn lại đến khi dậy mùi vàng óng. Trút nguyên liệu chính đã ướp vào đảo săn 2–3 phút cho bề mặt se lại, khóa trọn nước ngọt tự nhiên bên trong thớ thịt.',6,'Xào săn nguyên liệu đạm với hành tỏi phi trước khi đổ nước sôi giúp nước canh thơm ngọt đậm đà mà không hề tanh.'),
(142,4,'Đun sôi nước canh & hớt bọt giữ độ trong veo','Chế khoảng 1.1–1.3 lít nước (kết hợp lượng nước vừa ngập mặt nguyên liệu) vào nồi, bật lửa lớn đun đến khi sôi bùng rồi hạ ngay về lửa vừa. Dùng muôi hớt sạch lớp bọt đầu nổi lên trên mặt nước để nồi canh Canh chua cá lóc miền Tây đạt độ trong thanh đẹp mắt. Thả cá lóc vào nồi nước đang sôi giữ lửa vừa 8 phút đến khi cá chín tới thì vớt cá ra đĩa riêng hoặc gạt gọn tránh nát.',9,'Sử dụng nước ấm hoặc nước sôi khi chế vào cá tươi sẽ giúp cá không bao giờ bị tanh nồng dù để nguội.'),
(142,5,'Thả rau củ theo độ chín & cân chỉnh định lượng vị','Lần lượt cho 150g dứa, 120g đậu bắp và 100g giá đỗ vào nồi canh đang sôi vừa (nhóm củ quả lâu chín cho trước 5–7 phút, nhóm rau mềm cho sau 1–2 phút). Nêm phần 45g me vắt và 35ml nước mắm còn lại, khuấy nhẹ và nếm thử thấy vị chua thanh hoặc ngọt dịu cân bằng đúng khẩu phần 4 người.',8,'Không đậy kín nắp vung sau khi đã thả các loại rau xanh vào nồi để giữ màu xanh ngọc tươi tắn hấp dẫn.'),
(142,6,'Điểm hương rau thơm & múc canh dọn nóng','Khi toàn bộ nguyên liệu vừa chín tới mềm ngọt, rắc ngay 25g rau om vào nồi rồi tắt bếp liền tay để giữ trọn tinh dầu thơm mát. Múc canh nóng hổi ra tô lớn, rắc thêm chút tiêu xay hoặc tỏi phi vàng và dùng ngay với cơm nóng. Cho đậu bắp, cà chua còn lại và dọc mùng vào 2 phút, thả giá đỗ tắt bếp rồi rắc rau om ngò gai, ớt lát và tỏi phi.',4,'Các loại rau thơm như thì là, ngò gai, rau om hay lá lốt chỉ nên thả ngay khoảnh khắc tắt bếp để hương thơm bùng nổ nhất.'),
(143,1,'Sơ chế & chần sạch nguyên liệu xương thịt, hải sản','Rửa sạch 250g thịt gà (ức) và 180g bắp ngọt với muối hạt rồi chần nhanh trong nồi nước sôi có đập dập 1 nhánh gừng trong 2–3 phút trên lửa lớn để loại bỏ hoàn toàn bọt bẩn. Rửa lại dưới làn nước sạch cho thật trắng trẻo, đồng thời nhặt rửa sạch 25g hành lá để ráo nước. Luộc ức gà chín vớt ra xé sợi; đun sôi nước dùng gà với hạt bắp ngọt và nấm hương thái nhỏ 8 phút.',6,'Bước chần sơ và rửa lại bằng nước ấm là bí quyết vàng giúp nồi nước dùng trong vắt, thơm thanh và không bao giờ bị đục hay hôi.'),
(143,2,'Nướng thơm thảo mộc & ninh nền nước dùng ngọt thanh','Cho phần nguyên liệu tạo ngọt từ 250g thịt gà (ức) và 180g bắp ngọt cùng hành tím và tỏi băm nhỏ đã nướng xém thơm vào nồi sâu lòng với khoảng 1.5–1.8 lít nước lọc. Đun sôi bùng trên lửa lớn rồi hạ ngay về lửa nhỏ liu riu, mở hé vung và hớt kỹ bọt nổi trên mặt để chiết xuất vị ngọt tự nhiên. Cho phần ức gà xé sợi vào nồi súp, nêm chút muối và hạt nêm vừa thanh.',12,'Luôn duy trì mặt nước lăn tăn nhẹ thay vì đun sôi sùng sục lửa to để protein không bị nhũ hóa gây đục nước lèo.'),
(143,3,'Xào tạo màu & dậy hương đặc trưng vùng miền','Bắc chảo nhỏ lên bếp với 15ml dầu ăn trên lửa vừa, phi thơm phần hành tỏi sả băm còn lại rồi xào săn 20g nấm hương và 100g trứng gà cùng 3g tiêu trong 3–4 phút. Khi hỗn hợp dậy mùi thơm nồng nàn và lên sắc màu óng ả đặc trưng của món Súp gà kem bắp ngọt sánh mịn thì tắt bếp.',5,'Xào riêng phần nguyên liệu tạo màu và gia vị thơm trước khi trút vào nồi nước dùng giúp tầng hương dậy lên rõ nét gấp đôi.'),
(143,4,'Sơ chế & cắt thái phần nhân topping xếp tô','Vớt phần thịt hoặc hải sản chín tới từ 250g thịt gà (ức) và 180g bắp ngọt ra ngâm ngay vào âu nước đun sôi để nguội giúp bề mặt săn giòn mọng nước, không bị thâm khô. Thái lát mỏng đều tay dày khoảng 3mm ngang thớ hoặc gỡ miếng vừa ăn, sắp riêng từng phần gọn gàng trên đĩa.',5,'Thái thịt ngang thớ với lưỡi dao thật sắc giúp lát thịt mềm mướt, khi chan nước dùng sôi lên sẽ phẳng đẹp không bị quăn cứng.'),
(143,5,'Hợp nhất nồi nước lèo & nêm chuẩn định lượng','Trút phần sốt màu thơm vào nồi nước dùng đang sôi lăn tăn, nêm chính xác lượng 3g tiêu còn lại cho vừa miệng 4 người ăn. Đun nhẹ thêm 5 phút ở lửa vừa để các tầng vị mặn dịu, ngọt hậu từ xương thịt và thảo mộc hòa quyện tròn trịa. Rót từ từ hỗn hợp bột năng khuấy đều theo vòng tròn cho súp sánh mượt, rồi rây nhẹ trứng đánh tan vào tạo sợi vân mây đẹp.',5,'Nên nêm nước mắm ngon ở giai đoạn cuối trên lửa nhỏ để giữ trọn hậu vị ngọt đạm và hương thơm mà không làm nước dùng bị chua.'),
(143,6,'Chần nóng sợi bánh/bún & chuẩn bị rau ăn kèm','Đun sôi một nồi nước riêng, cho phần sợi bún/phở/bánh trong 250g thịt gà (ức) và 180g bắp ngọt vào trụng nhanh 15–25 giây cho sợi mềm dẻo nóng hổi rồi vẩy thật ráo nước, chia đều vào 4 tô lớn. Chần sơ thêm rau ăn kèm (giá đỗ, rau xanh) nếu muốn dùng chín giòn.',4,'Trụng bún bánh ở nồi nước sôi riêng biệt giúp nước dùng chính không bị nhiễm tinh bột chua và tô bún luôn ráo sợi, thấm vị.'),
(143,7,'Xếp nhân hài hòa, chan nước dùng sôi & thưởng thức','Xếp đều các phần nhân thịt, hải sản lên mặt tô bún bánh, điểm xuyết 25g hành lá lên trên cùng. Dùng muôi múc nước dùng đang sôi thật già chan ngập xăm xắp mặt nguyên liệu để làm chín thơm hành ngò, dọn nóng ngay kèm chanh ớt tươi. Múc súp ra chén sâu lòng, rắc hành ngò thái nhuyễn, tiêu xay và rưới 2 giọt dầu mè thơm.',3,'Tráng nóng tô sứ bằng nước sôi trước khi xếp bún giúp tô món nước giữ nhiệt bốc khói nghi ngút suốt bữa ăn.'),
(144,1,'Sơ chế sạch & cắt thái nguyên liệu nấu canh','Rửa sạch 500g sườn non và 120g lá giang, khử mùi tanh bằng chút muối hạt và gừng đập dập rồi rửa lại thật ráo, cắt miếng vừa ăn dày khoảng 2.5–3cm. Đồng thời gọt rửa sạch rau củ ăn kèm, cắt khúc hoặc bổ múi cau đồng đều để khi nấu chín đều không bị nát. Chần sườn qua nước sôi muối gừng rồi rửa sạch; hầm cùng 1.4 lít nước lửa nhỏ 25 phút cho sườn mềm và nước dùng ngọt thanh.',9,'Phân loại riêng nhóm củ cứng nấu lâu và nhóm rau lá mềm nhanh chín để cho vào nồi theo đúng thứ tự chuẩn đầu bếp.'),
(144,2,'Ướp thấm gia vị nền cho nguyên liệu đạm','Cho phần đạm chính trong 500g sườn non và 120g lá giang vào tô, ướp nhẹ với một nửa lượng 15g tỏi và 8g ớt, 30ml nước mắm và 12g đường trong khoảng 10 phút. Đảo nhẹ tay cho gia vị áo đều bề mặt giúp miếng thịt, cá săn chắc và đậm đà từ bên trong khi thả vào nước canh. Dùng tay vò hơi nát phần lá giang đã rửa sạch (giúp lá tiết axit chua đều mà không cần đun lâu).',8,'Không ướp quá mặn ở bước này để giữ vị thanh mát tự nhiên của nước canh sau khi hoàn tất.'),
(144,3,'Phi thơm hành tỏi & xào săn khóa ngọt nguyên liệu','Đặt nồi canh lên bếp ở lửa vừa, làm nóng 15ml dầu ăn rồi phi thơm phần 15g tỏi còn lại đến khi dậy mùi vàng óng. Trút nguyên liệu chính đã ướp vào đảo săn 2–3 phút cho bề mặt se lại, khóa trọn nước ngọt tự nhiên bên trong thớ thịt.',7,'Xào săn nguyên liệu đạm với hành tỏi phi trước khi đổ nước sôi giúp nước canh thơm ngọt đậm đà mà không hề tanh.'),
(144,4,'Đun sôi nước canh & hớt bọt giữ độ trong veo','Chế khoảng 1.1–1.3 lít nước (kết hợp lượng nước vừa ngập mặt nguyên liệu) vào nồi, bật lửa lớn đun đến khi sôi bùng rồi hạ ngay về lửa vừa. Dùng muôi hớt sạch lớp bọt đầu nổi lên trên mặt nước để nồi canh Canh chua sườn non lá giang đạt độ trong thanh đẹp mắt. Nêm nước mắm và đường vào nồi sườn, thả lá giang vào đảo đều 2 phút rồi tắt bếp ngay khi lá chuyển màu vàng xanh.',11,'Sử dụng nước ấm hoặc nước sôi khi chế vào cá tươi sẽ giúp cá không bao giờ bị tanh nồng dù để nguội.'),
(144,5,'Thả rau củ theo độ chín & cân chỉnh định lượng vị','Lần lượt cho rau củ ăn kèm vào nồi canh đang sôi vừa (nhóm củ quả lâu chín cho trước 5–7 phút, nhóm rau mềm cho sau 1–2 phút). Nêm phần 8g ớt, 30ml nước mắm và 12g đường còn lại, khuấy nhẹ và nếm thử thấy vị chua thanh hoặc ngọt dịu cân bằng đúng khẩu phần 4 người.',10,'Không đậy kín nắp vung sau khi đã thả các loại rau xanh vào nồi để giữ màu xanh ngọc tươi tắn hấp dẫn.'),
(144,6,'Điểm hương rau thơm & múc canh dọn nóng','Khi toàn bộ nguyên liệu vừa chín tới mềm ngọt, rắc ngay 25g rau om vào nồi rồi tắt bếp liền tay để giữ trọn tinh dầu thơm mát. Múc canh nóng hổi ra tô lớn, rắc thêm chút tiêu xay hoặc tỏi phi vàng và dùng ngay với cơm nóng. Múc canh ra tô, rắc rau om thái nhỏ, ớt lát và tỏi phi vàng.',5,'Các loại rau thơm như thì là, ngò gai, rau om hay lá lốt chỉ nên thả ngay khoảnh khắc tắt bếp để hương thơm bùng nổ nhất.'),
(145,1,'Sơ chế sạch & cắt thái nguyên liệu nấu canh','Rửa sạch 350g thịt gà (ức) và 250g cà chua, khử mùi tanh bằng chút muối hạt và gừng đập dập rồi rửa lại thật ráo, cắt miếng vừa ăn dày khoảng 2.5–3cm. Đồng thời gọt rửa sạch 150g dứa, cắt khúc hoặc bổ múi cau đồng đều để khi nấu chín đều không bị nát. Thái lát thịt ức gà vừa ăn, ướp cùng gừng thái sợi, nửa phần hành tím băm, 2g muối và 10ml nước mắm trong 10 phút.',6,'Phân loại riêng nhóm củ cứng nấu lâu và nhóm rau lá mềm nhanh chín để cho vào nồi theo đúng thứ tự chuẩn đầu bếp.'),
(145,2,'Ướp thấm gia vị nền cho nguyên liệu đạm','Cho phần đạm chính trong 350g thịt gà (ức) và 250g cà chua vào tô, ướp nhẹ với một nửa lượng 20g hành tím và 10g gừng và 20ml nước mắm và 4g muối trong khoảng 10 phút. Đảo nhẹ tay cho gia vị áo đều bề mặt giúp miếng thịt, cá săn chắc và đậm đà từ bên trong khi thả vào nước canh. Phi thơm hành tím còn lại, cho 1/2 lượng cà chua và dứa vào xào 3 phút cho ra màu đỏ cam đẹp mắt và tiết vị chua ngọt thanh.',6,'Không ướp quá mặn ở bước này để giữ vị thanh mát tự nhiên của nước canh sau khi hoàn tất.');
INSERT INTO `recipe_steps` (`recipe_id`,`step_order`,`title`,`instruction`,`duration_mins`,`tip_note`) VALUES
(145,3,'Phi thơm hành tỏi & xào săn khóa ngọt nguyên liệu','Đặt nồi canh lên bếp ở lửa vừa, làm nóng 15ml dầu ăn rồi phi thơm phần 20g hành tím và 10g gừng còn lại đến khi dậy mùi vàng óng. Trút nguyên liệu chính đã ướp vào đảo săn 2–3 phút cho bề mặt se lại, khóa trọn nước ngọt tự nhiên bên trong thớ thịt.',5,'Xào săn nguyên liệu đạm với hành tỏi phi trước khi đổ nước sôi giúp nước canh thơm ngọt đậm đà mà không hề tanh.'),
(145,4,'Đun sôi nước canh & hớt bọt giữ độ trong veo','Chế khoảng 1.1–1.3 lít nước (kết hợp 1200ml nước lọc) vào nồi, bật lửa lớn đun đến khi sôi bùng rồi hạ ngay về lửa vừa. Dùng muôi hớt sạch lớp bọt đầu nổi lên trên mặt nước để nồi canh Canh gà nấu cà chua dứa đạt độ trong thanh đẹp mắt. Châm 1200ml nước sôi vào nồi, đun sôi nhẹ 5 phút rồi thả thịt ức gà và phần cà chua còn lại vào nấu lửa vừa 6 phút, hớt sạch bọt.',7,'Sử dụng nước ấm hoặc nước sôi khi chế vào cá tươi sẽ giúp cá không bao giờ bị tanh nồng dù để nguội.'),
(145,5,'Thả rau củ theo độ chín & cân chỉnh định lượng vị','Lần lượt cho 150g dứa vào nồi canh đang sôi vừa (nhóm củ quả lâu chín cho trước 5–7 phút, nhóm rau mềm cho sau 1–2 phút). Nêm phần 20ml nước mắm và 4g muối còn lại, khuấy nhẹ và nếm thử thấy vị chua thanh hoặc ngọt dịu cân bằng đúng khẩu phần 4 người.',7,'Không đậy kín nắp vung sau khi đã thả các loại rau xanh vào nồi để giữ màu xanh ngọc tươi tắn hấp dẫn.'),
(145,6,'Điểm hương rau thơm & múc canh dọn nóng','Khi toàn bộ nguyên liệu vừa chín tới mềm ngọt, rắc ngay 20g hành lá và 15g rau om vào nồi rồi tắt bếp liền tay để giữ trọn tinh dầu thơm mát. Múc canh nóng hổi ra tô lớn, rắc thêm chút tiêu xay hoặc tỏi phi vàng và dùng ngay với cơm nóng. Nêm nốt 10ml nước mắm và 2g muối vừa miệng, tắt bếp rồi rắc hành lá cùng rau om thái nhỏ trước khi múc ra tô.',4,'Các loại rau thơm như thì là, ngò gai, rau om hay lá lốt chỉ nên thả ngay khoảnh khắc tắt bếp để hương thơm bùng nổ nhất.'),
(146,1,'Sơ chế sạch & cắt thái nguyên liệu nấu canh','Rửa sạch 500g thịt gà (đùi) và 200g miến dong, khử mùi tanh bằng chút muối hạt và gừng đập dập rồi rửa lại thật ráo, cắt miếng vừa ăn dày khoảng 2.5–3cm. Đồng thời gọt rửa sạch 150g măng khô, cắt khúc hoặc bổ múi cau đồng đều để khi nấu chín đều không bị nát. Luộc đùi gà cùng gừng và hành tím nướng trong 1.6 lít nước khoảng 22 phút, vớt gà ra để nguội xé sợi vừa ăn.',11,'Phân loại riêng nhóm củ cứng nấu lâu và nhóm rau lá mềm nhanh chín để cho vào nồi theo đúng thứ tự chuẩn đầu bếp.'),
(146,2,'Ướp thấm gia vị nền cho nguyên liệu đạm','Cho phần đạm chính trong 500g thịt gà (đùi) và 200g miến dong vào tô, ướp nhẹ với một nửa lượng 30g hành tím và 15g gừng và 30ml nước mắm trong khoảng 10 phút. Đảo nhẹ tay cho gia vị áo đều bề mặt giúp miếng thịt, cá săn chắc và đậm đà từ bên trong khi thả vào nước canh. Luộc măng khô sạch nước hăng, xé sợi rồi xào cùng hành tím phi, nấm hương và 1 thìa nước mắm cho thơm.',10,'Không ướp quá mặn ở bước này để giữ vị thanh mát tự nhiên của nước canh sau khi hoàn tất.'),
(146,3,'Phi thơm hành tỏi & xào săn khóa ngọt nguyên liệu','Đặt nồi canh lên bếp ở lửa vừa, làm nóng 15ml dầu ăn rồi phi thơm phần 30g hành tím và 15g gừng còn lại đến khi dậy mùi vàng óng. Trút nguyên liệu chính đã ướp vào đảo săn 2–3 phút cho bề mặt se lại, khóa trọn nước ngọt tự nhiên bên trong thớ thịt.',8,'Xào săn nguyên liệu đạm với hành tỏi phi trước khi đổ nước sôi giúp nước canh thơm ngọt đậm đà mà không hề tanh.'),
(146,4,'Đun sôi nước canh & hớt bọt giữ độ trong veo','Chế khoảng 1.1–1.3 lít nước (kết hợp lượng nước vừa ngập mặt nguyên liệu) vào nồi, bật lửa lớn đun đến khi sôi bùng rồi hạ ngay về lửa vừa. Dùng muôi hớt sạch lớp bọt đầu nổi lên trên mặt nước để nồi canh Miến măng gà thanh ngọt đạt độ trong thanh đẹp mắt. Ngâm miến dong nước mát 10 phút cho mềm, chần nhanh qua nước sôi 20 giây rồi trút vào tô.',13,'Sử dụng nước ấm hoặc nước sôi khi chế vào cá tươi sẽ giúp cá không bao giờ bị tanh nồng dù để nguội.'),
(146,5,'Thả rau củ theo độ chín & cân chỉnh định lượng vị','Lần lượt cho 150g măng khô vào nồi canh đang sôi vừa (nhóm củ quả lâu chín cho trước 5–7 phút, nhóm rau mềm cho sau 1–2 phút). Nêm phần 30ml nước mắm còn lại, khuấy nhẹ và nếm thử thấy vị chua thanh hoặc ngọt dịu cân bằng đúng khẩu phần 4 người.',12,'Không đậy kín nắp vung sau khi đã thả các loại rau xanh vào nồi để giữ màu xanh ngọc tươi tắn hấp dẫn.'),
(146,6,'Điểm hương rau thơm & múc canh dọn nóng','Khi toàn bộ nguyên liệu vừa chín tới mềm ngọt, rắc ngay 35g hành lá vào nồi rồi tắt bếp liền tay để giữ trọn tinh dầu thơm mát. Múc canh nóng hổi ra tô lớn, rắc thêm chút tiêu xay hoặc tỏi phi vàng và dùng ngay với cơm nóng. Xếp thịt gà xé, măng nấm, hành lá rau mùi và hành phi vàng lên mặt miến, chan ngập nước dùng gà nóng hổi.',6,'Các loại rau thơm như thì là, ngò gai, rau om hay lá lốt chỉ nên thả ngay khoảnh khắc tắt bếp để hương thơm bùng nổ nhất.'),
(147,1,'Sơ chế & thái mỏng đồng đều nguyên liệu xào','Làm sạch và thấm ráo 350g lòng gà và 300g mướp hương, dùng dao sắc thái lát mỏng vừa ăn khoảng 2–3mm ngang thớ để khi xào nhanh chín mềm không bị dai. Nhặt rửa sạch 150g giá đỗ, cắt khúc xéo 4cm hoặc tách nhánh đồng đều giúp tiếp xúc nhiệt nhanh trên chảo. Bóp mề tim với muối chanh rửa sạch, khứa hoa mề gà, gan để riêng; ướp lòng gà với dầu hào, hành tím và tiêu.',7,'Nguyên liệu xào bắt buộc phải để thật ráo nước trước khi cho vào chảo để đạt hiệu ứng áp nhiệt thơm kiểu chảo gang.'),
(147,2,'Ướp mềm nguyên liệu đạm & pha sẵn chén sốt xào','Ướp phần đạm trong 350g lòng gà và 300g mướp hương với 1/3 lượng 20g hành tím và 15g tỏi, chút dầu ăn và 1/3 lượng 20ml dầu hào trong 10 phút để giữ độ ẩm mọng. Pha phần 20ml dầu hào còn lại cùng 20ml nước lọc vào chén nhỏ khuấy tan hoàn toàn để thao tác xào lửa lớn diễn ra dứt khoát. Phi thơm tỏi với dầu ăn, cho mề tim vào đảo lửa lớn 3 phút rồi cho gan vào đảo thêm 1.5 phút trút ra đĩa.',5,'Thêm 1 muỗng cà phê dầu ăn vào bước ướp thịt bò/heo giúp khóa ẩm và các lát thịt tơi nhanh không bị dính chùm khi gặp chảo nóng.'),
(147,3,'Chần nhanh rau củ giữ sắc xanh ngọc & độ giòn','Đun sôi nồi nước nhỏ với một nhúm muối, thả 150g giá đỗ vào chần nhanh 30–45 giây rồi vớt ngay ra tô nước đá lạnh cho sốc nhiệt, sau đó đổ ra rổ cho thật ráo. Bước tiền xử lý này giúp rau củ chín đều từ trong mà bên ngoài vẫn xanh mướt giòn sần sật.',4,'Thời gian chần dưới 1 phút kết hợp ngâm nước đá lạnh là bí quyết nhà hàng giúp đĩa rau xào không bị chảy nước đen đĩa.'),
(147,4,'Xào săn nguyên liệu chính trên lửa lớn nhanh tay','Làm nóng chảo rộng trên lửa lớn nhất với 15ml dầu ăn, phi dậy mùi một nửa 20g hành tím và 15g tỏi rồi trút phần đạm chính trong 350g lòng gà và 300g mướp hương vào đảo cực nhanh tay trong 60–90 giây. Ngay khi thịt hoặc hải sản vừa chín tái hồng khoảng 85%, lập tức trút riêng ra đĩa sạch để không bị quá lửa khô xác. Tận dụng chảo nóng cho mướp vào đảo nhanh 2 phút với nhúm muối nhỏ rồi trút giá đỗ đảo thêm 30 giây.',5,'Tuyệt đối không xào thịt chung từ đầu đến cuối với rau củ vì thịt sẽ bị dai và tiết nước làm mất độ giòn.'),
(147,5,'Xào rau củ lửa lớn & rưới sốt định lượng khóa vị','Giữ nguyên chảo nóng trên lửa lớn, thêm chút dầu phi thơm nốt phần 20g hành tím và 15g tỏi còn lại rồi cho 150g giá đỗ đã ráo nước vào đảo đều 1–2 phút. Trút ngược đĩa đạm vào chảo, rưới đều chén sốt gia vị đã pha và xóc nhanh tay 45 giây cho sốt sánh bóng áo quanh từng miếng nguyên liệu.',5,'Rưới sốt vòng quanh thành chảo nóng thay vì đổ thẳng giữa lòng chảo giúp sốt bốc hơi thơm lừng và sệt lại tức thì.'),
(147,6,'Dậy hương tiêu hành & trình bày nóng hổi','Cho 30g hành lá vào đảo nhẹ đúng 1 lượt rồi tắt bếp ngay khi khói thơm bốc lên nghi ngút. Gắp món Lòng gà xào mướp giá thơm lừng ra đĩa rộng lòng để tản nhiệt đều, tránh đậy kín vung và thưởng thức nóng ngay cùng cơm dẻo cho 4 người. Trút lòng gà trở lại chảo cùng hành lá cắt khúc đảo đều 30 giây, rắc tiêu rồi bắc xuống ăn nóng.',4,'Bày món xào ra đĩa rộng không xếp chồng quá dày giúp hơi nóng thoát nhẹ, giữ rau củ giòn ngọt lâu đến miếng cuối cùng.'),
(148,1,'Sơ chế & thái mỏng đồng đều nguyên liệu xào','Làm sạch và thấm ráo 300g thịt bò và 300g hoa thiên lý, dùng dao sắc thái lát mỏng vừa ăn khoảng 2–3mm ngang thớ để khi xào nhanh chín mềm không bị dai. Nhặt rửa sạch rau củ ăn kèm, cắt khúc xéo 4cm hoặc tách nhánh đồng đều giúp tiếp xúc nhiệt nhanh trên chảo. Ướp thịt bò với dầu hào, 1/2 tỏi băm, tiêu, 1 thìa dầu ăn và 5g bột bắp trong 15 phút.',6,'Nguyên liệu xào bắt buộc phải để thật ráo nước trước khi cho vào chảo để đạt hiệu ứng áp nhiệt thơm kiểu chảo gang.'),
(148,2,'Ướp mềm nguyên liệu đạm & pha sẵn chén sốt xào','Ướp phần đạm trong 300g thịt bò và 300g hoa thiên lý với 1/3 lượng 20g tỏi, chút dầu ăn và 1/3 lượng 20ml dầu hào và 3g tiêu trong 10 phút để giữ độ ẩm mọng. Pha phần 20ml dầu hào và 3g tiêu còn lại cùng 20ml nước lọc vào chén nhỏ khuấy tan hoàn toàn để thao tác xào lửa lớn diễn ra dứt khoát. Làm chảo thật nóng bốc khói nhẹ với dầu ăn, phi thơm 1/2 số tỏi rồi trút bò vào đảo nhanh 60 giây cho chín tái 80%, trút ra đĩa.',4,'Thêm 1 muỗng cà phê dầu ăn vào bước ướp thịt bò/heo giúp khóa ẩm và các lát thịt tơi nhanh không bị dính chùm khi gặp chảo nóng.'),
(148,3,'Chần nhanh rau củ giữ sắc xanh ngọc & độ giòn','Đun sôi nồi nước nhỏ với một nhúm muối, thả rau củ ăn kèm vào chần nhanh 30–45 giây rồi vớt ngay ra tô nước đá lạnh cho sốc nhiệt, sau đó đổ ra rổ cho thật ráo. Bước tiền xử lý này giúp rau củ chín đều từ trong mà bên ngoài vẫn xanh mướt giòn sần sật.',4,'Thời gian chần dưới 1 phút kết hợp ngâm nước đá lạnh là bí quyết nhà hàng giúp đĩa rau xào không bị chảy nước đen đĩa.'),
(148,4,'Xào săn nguyên liệu chính trên lửa lớn nhanh tay','Làm nóng chảo rộng trên lửa lớn nhất với 15ml dầu ăn, phi dậy mùi một nửa 20g tỏi rồi trút phần đạm chính trong 300g thịt bò và 300g hoa thiên lý vào đảo cực nhanh tay trong 60–90 giây. Ngay khi thịt hoặc hải sản vừa chín tái hồng khoảng 85%, lập tức trút riêng ra đĩa sạch để không bị quá lửa khô xác. Cho nốt tỏi phi vào chảo, trút hoa thiên lý cùng 2 thìa nước lọc xào lửa lớn 1.5 phút vừa chín xanh tới.',4,'Tuyệt đối không xào thịt chung từ đầu đến cuối với rau củ vì thịt sẽ bị dai và tiết nước làm mất độ giòn.'),
(148,5,'Xào rau củ lửa lớn & rưới sốt định lượng khóa vị','Giữ nguyên chảo nóng trên lửa lớn, thêm chút dầu phi thơm nốt phần 20g tỏi còn lại rồi cho rau củ ăn kèm đã ráo nước vào đảo đều 1–2 phút. Trút ngược đĩa đạm vào chảo, rưới đều chén sốt gia vị đã pha và xóc nhanh tay 45 giây cho sốt sánh bóng áo quanh từng miếng nguyên liệu.',4,'Rưới sốt vòng quanh thành chảo nóng thay vì đổ thẳng giữa lòng chảo giúp sốt bốc hơi thơm lừng và sệt lại tức thì.'),
(148,6,'Dậy hương tiêu hành & trình bày nóng hổi','Cho hành ngò và tiêu xay vào đảo nhẹ đúng 1 lượt rồi tắt bếp ngay khi khói thơm bốc lên nghi ngút. Gắp món Thịt bò xào hoa thiên lý ra đĩa rộng lòng để tản nhiệt đều, tránh đậy kín vung và thưởng thức nóng ngay cùng cơm dẻo cho 4 người. Đổ đĩa bò vào đảo đều cùng hoa thiên lý 20 giây, rắc tiêu và trút ra đĩa thưởng thức ngay.',3,'Bày món xào ra đĩa rộng không xếp chồng quá dày giúp hơi nóng thoát nhẹ, giữ rau củ giòn ngọt lâu đến miếng cuối cùng.'),
(149,1,'Sơ chế & thái mỏng đồng đều nguyên liệu xào','Làm sạch và thấm ráo 450g mực ống và 120g cần tây, dùng dao sắc thái lát mỏng vừa ăn khoảng 2–3mm ngang thớ để khi xào nhanh chín mềm không bị dai. Nhặt rửa sạch 120g hành tây, cắt khúc xéo 4cm hoặc tách nhánh đồng đều giúp tiếp xúc nhiệt nhanh trên chảo. Bóp nhanh mực với gừng đập dập và chút muối rồi rửa sạch; chần nước sôi có gừng 20 giây cho mực săn ráo nước.',6,'Nguyên liệu xào bắt buộc phải để thật ráo nước trước khi cho vào chảo để đạt hiệu ứng áp nhiệt thơm kiểu chảo gang.'),
(149,2,'Ướp mềm nguyên liệu đạm & pha sẵn chén sốt xào','Ướp phần đạm trong 450g mực ống và 120g cần tây với 1/3 lượng 20g tỏi và 15g gừng, chút dầu ăn và 1/3 lượng 20ml dầu hào trong 10 phút để giữ độ ẩm mọng. Pha phần 20ml dầu hào còn lại cùng 20ml nước lọc vào chén nhỏ khuấy tan hoàn toàn để thao tác xào lửa lớn diễn ra dứt khoát. Phi thơm tỏi, cho mực vào đảo nhanh 1.5 phút cùng dầu hào rồi trút riêng ra bát.',4,'Thêm 1 muỗng cà phê dầu ăn vào bước ướp thịt bò/heo giúp khóa ẩm và các lát thịt tơi nhanh không bị dính chùm khi gặp chảo nóng.'),
(149,3,'Chần nhanh rau củ giữ sắc xanh ngọc & độ giòn','Đun sôi nồi nước nhỏ với một nhúm muối, thả 120g hành tây vào chần nhanh 30–45 giây rồi vớt ngay ra tô nước đá lạnh cho sốc nhiệt, sau đó đổ ra rổ cho thật ráo. Bước tiền xử lý này giúp rau củ chín đều từ trong mà bên ngoài vẫn xanh mướt giòn sần sật.',4,'Thời gian chần dưới 1 phút kết hợp ngâm nước đá lạnh là bí quyết nhà hàng giúp đĩa rau xào không bị chảy nước đen đĩa.');
INSERT INTO `recipe_steps` (`recipe_id`,`step_order`,`title`,`instruction`,`duration_mins`,`tip_note`) VALUES
(149,4,'Xào săn nguyên liệu chính trên lửa lớn nhanh tay','Làm nóng chảo rộng trên lửa lớn nhất với 15ml dầu ăn, phi dậy mùi một nửa 20g tỏi và 15g gừng rồi trút phần đạm chính trong 450g mực ống và 120g cần tây vào đảo cực nhanh tay trong 60–90 giây. Ngay khi thịt hoặc hải sản vừa chín tái hồng khoảng 85%, lập tức trút riêng ra đĩa sạch để không bị quá lửa khô xác. Đảo nhanh cà chua và hành tây 1.5 phút rồi thả cần tây và hành lá cắt khúc vào xào tiếp 45 giây.',4,'Tuyệt đối không xào thịt chung từ đầu đến cuối với rau củ vì thịt sẽ bị dai và tiết nước làm mất độ giòn.'),
(149,5,'Xào rau củ lửa lớn & rưới sốt định lượng khóa vị','Giữ nguyên chảo nóng trên lửa lớn, thêm chút dầu phi thơm nốt phần 20g tỏi và 15g gừng còn lại rồi cho 120g hành tây đã ráo nước vào đảo đều 1–2 phút. Trút ngược đĩa đạm vào chảo, rưới đều chén sốt gia vị đã pha và xóc nhanh tay 45 giây cho sốt sánh bóng áo quanh từng miếng nguyên liệu.',4,'Rưới sốt vòng quanh thành chảo nóng thay vì đổ thẳng giữa lòng chảo giúp sốt bốc hơi thơm lừng và sệt lại tức thì.'),
(149,6,'Dậy hương tiêu hành & trình bày nóng hổi','Cho hành ngò và tiêu xay vào đảo nhẹ đúng 1 lượt rồi tắt bếp ngay khi khói thơm bốc lên nghi ngút. Gắp món Mực xào cần tỏi hành tây ra đĩa rộng lòng để tản nhiệt đều, tránh đậy kín vung và thưởng thức nóng ngay cùng cơm dẻo cho 4 người. Trút mực trở lại chảo đảo đều 30 giây trên lửa cao rồi tắt bếp, rắc tiêu và dùng nóng.',3,'Bày món xào ra đĩa rộng không xếp chồng quá dày giúp hơi nóng thoát nhẹ, giữ rau củ giòn ngọt lâu đến miếng cuối cùng.'),
(150,1,'Sơ chế & thái mỏng đồng đều nguyên liệu xào','Làm sạch và thấm ráo 500g ếch đồng, dùng dao sắc thái lát mỏng vừa ăn khoảng 2–3mm ngang thớ để khi xào nhanh chín mềm không bị dai. Nhặt rửa sạch 100g hành tây, cắt khúc xéo 4cm hoặc tách nhánh đồng đều giúp tiếp xúc nhiệt nhanh trên chảo. Rửa sạch thịt ếch bằng muối hạt và rượu trắng gừng, chặt miếng rồi ướp với nước mắm, nghệ, 1/2 sả băm và đường 15 phút.',8,'Nguyên liệu xào bắt buộc phải để thật ráo nước trước khi cho vào chảo để đạt hiệu ứng áp nhiệt thơm kiểu chảo gang.'),
(150,2,'Ướp mềm nguyên liệu đạm & pha sẵn chén sốt xào','Ướp phần đạm trong 500g ếch đồng với 1/3 lượng 60g sả và 15g nghệ, chút dầu ăn và 1/3 lượng 15g ớt, 30ml nước mắm và 12g đường trong 10 phút để giữ độ ẩm mọng. Pha phần 15g ớt, 30ml nước mắm và 12g đường còn lại cùng 20ml nước lọc vào chén nhỏ khuấy tan hoàn toàn để thao tác xào lửa lớn diễn ra dứt khoát. Làm nóng chảo dầu, phi thơm sả băm và sả cắt lát cùng tỏi cho đến khi dậy mùi vàng nhẹ.',6,'Thêm 1 muỗng cà phê dầu ăn vào bước ướp thịt bò/heo giúp khóa ẩm và các lát thịt tơi nhanh không bị dính chùm khi gặp chảo nóng.'),
(150,3,'Chần nhanh rau củ giữ sắc xanh ngọc & độ giòn','Đun sôi nồi nước nhỏ với một nhúm muối, thả 100g hành tây vào chần nhanh 30–45 giây rồi vớt ngay ra tô nước đá lạnh cho sốc nhiệt, sau đó đổ ra rổ cho thật ráo. Bước tiền xử lý này giúp rau củ chín đều từ trong mà bên ngoài vẫn xanh mướt giòn sần sật.',5,'Thời gian chần dưới 1 phút kết hợp ngâm nước đá lạnh là bí quyết nhà hàng giúp đĩa rau xào không bị chảy nước đen đĩa.'),
(150,4,'Xào săn nguyên liệu chính trên lửa lớn nhanh tay','Làm nóng chảo rộng trên lửa lớn nhất với 15ml dầu ăn, phi dậy mùi một nửa 60g sả và 15g nghệ rồi trút phần đạm chính trong 500g ếch đồng vào đảo cực nhanh tay trong 60–90 giây. Ngay khi thịt hoặc hải sản vừa chín tái hồng khoảng 85%, lập tức trút riêng ra đĩa sạch để không bị quá lửa khô xác. Trút thịt ếch vào đảo lửa lớn 5 phút, hạ lửa vừa đậy nắp 4 phút cho thịt chín ngọt bên trong.',6,'Tuyệt đối không xào thịt chung từ đầu đến cuối với rau củ vì thịt sẽ bị dai và tiết nước làm mất độ giòn.'),
(150,5,'Xào rau củ lửa lớn & rưới sốt định lượng khóa vị','Giữ nguyên chảo nóng trên lửa lớn, thêm chút dầu phi thơm nốt phần 60g sả và 15g nghệ còn lại rồi cho 100g hành tây đã ráo nước vào đảo đều 1–2 phút. Trút ngược đĩa đạm vào chảo, rưới đều chén sốt gia vị đã pha và xóc nhanh tay 45 giây cho sốt sánh bóng áo quanh từng miếng nguyên liệu.',6,'Rưới sốt vòng quanh thành chảo nóng thay vì đổ thẳng giữa lòng chảo giúp sốt bốc hơi thơm lừng và sệt lại tức thì.'),
(150,6,'Dậy hương tiêu hành & trình bày nóng hổi','Cho hành ngò và tiêu xay vào đảo nhẹ đúng 1 lượt rồi tắt bếp ngay khi khói thơm bốc lên nghi ngút. Gắp món Ếch xào sả ớt đậm đà ra đĩa rộng lòng để tản nhiệt đều, tránh đậy kín vung và thưởng thức nóng ngay cùng cơm dẻo cho 4 người. Cho hành tây và ớt thái lát vào đảo tiếp 2 phút đến khi hành tây vừa chín tới, nêm lại vị mặn ngọt rồi dọn đĩa.',4,'Bày món xào ra đĩa rộng không xếp chồng quá dày giúp hơi nóng thoát nhẹ, giữ rau củ giòn ngọt lâu đến miếng cuối cùng.'),
(151,1,'Sơ chế & thái mỏng đồng đều nguyên liệu xào','Làm sạch và thấm ráo 400g su su và 100g cà rốt, dùng dao sắc thái lát mỏng vừa ăn khoảng 2–3mm ngang thớ để khi xào nhanh chín mềm không bị dai. Nhặt rửa sạch rau củ ăn kèm, cắt khúc xéo 4cm hoặc tách nhánh đồng đều giúp tiếp xúc nhiệt nhanh trên chảo. Gọt su su dưới vòi nước chảy nhẹ hoặc đeo găng tay sạch rồi rửa ráo, bỏ hạt lõi và thái miếng mỏng đều.',4,'Nguyên liệu xào bắt buộc phải để thật ráo nước trước khi cho vào chảo để đạt hiệu ứng áp nhiệt thơm kiểu chảo gang.'),
(151,2,'Ướp mềm nguyên liệu đạm & pha sẵn chén sốt xào','Ướp phần đạm trong 400g su su và 100g cà rốt với 1/3 lượng 20g tỏi, chút dầu ăn và 1/3 lượng 4g muối trong 10 phút để giữ độ ẩm mọng. Pha phần 4g muối còn lại cùng 20ml nước lọc vào chén nhỏ khuấy tan hoàn toàn để thao tác xào lửa lớn diễn ra dứt khoát. Đun nóng 1 thìa canh dầu ăn, phi 1/2 phần tỏi cho vàng thơm.',4,'Thêm 1 muỗng cà phê dầu ăn vào bước ướp thịt bò/heo giúp khóa ẩm và các lát thịt tơi nhanh không bị dính chùm khi gặp chảo nóng.'),
(151,3,'Chần nhanh rau củ giữ sắc xanh ngọc & độ giòn','Đun sôi nồi nước nhỏ với một nhúm muối, thả rau củ ăn kèm vào chần nhanh 30–45 giây rồi vớt ngay ra tô nước đá lạnh cho sốc nhiệt, sau đó đổ ra rổ cho thật ráo. Bước tiền xử lý này giúp rau củ chín đều từ trong mà bên ngoài vẫn xanh mướt giòn sần sật.',3,'Thời gian chần dưới 1 phút kết hợp ngâm nước đá lạnh là bí quyết nhà hàng giúp đĩa rau xào không bị chảy nước đen đĩa.'),
(151,4,'Xào săn nguyên liệu chính trên lửa lớn nhanh tay','Làm nóng chảo rộng trên lửa lớn nhất với 15ml dầu ăn, phi dậy mùi một nửa 20g tỏi rồi trút phần đạm chính trong 400g su su và 100g cà rốt vào đảo cực nhanh tay trong 60–90 giây. Ngay khi thịt hoặc hải sản vừa chín tái hồng khoảng 85%, lập tức trút riêng ra đĩa sạch để không bị quá lửa khô xác. Cho cà rốt vào đảo 1 phút trước rồi trút su su + 30ml nước lọc + muối vào đảo đều 4 phút đến khi su su trong giòn.',4,'Tuyệt đối không xào thịt chung từ đầu đến cuối với rau củ vì thịt sẽ bị dai và tiết nước làm mất độ giòn.'),
(151,5,'Xào rau củ lửa lớn & rưới sốt định lượng khóa vị','Giữ nguyên chảo nóng trên lửa lớn, thêm chút dầu phi thơm nốt phần 20g tỏi còn lại rồi cho rau củ ăn kèm đã ráo nước vào đảo đều 1–2 phút. Trút ngược đĩa đạm vào chảo, rưới đều chén sốt gia vị đã pha và xóc nhanh tay 45 giây cho sốt sánh bóng áo quanh từng miếng nguyên liệu.',4,'Rưới sốt vòng quanh thành chảo nóng thay vì đổ thẳng giữa lòng chảo giúp sốt bốc hơi thơm lừng và sệt lại tức thì.'),
(151,6,'Dậy hương tiêu hành & trình bày nóng hổi','Cho 20g hành lá vào đảo nhẹ đúng 1 lượt rồi tắt bếp ngay khi khói thơm bốc lên nghi ngút. Gắp món Su su xào tỏi cà rốt thanh mát ra đĩa rộng lòng để tản nhiệt đều, tránh đậy kín vung và thưởng thức nóng ngay cùng cơm dẻo cho 4 người. Thả phần tỏi băm còn lại và hành lá cắt khúc vào đảo 30 giây rồi tắt bếp.',3,'Bày món xào ra đĩa rộng không xếp chồng quá dày giúp hơi nóng thoát nhẹ, giữ rau củ giòn ngọt lâu đến miếng cuối cùng.'),
(152,1,'Sơ chế & thái mỏng đồng đều nguyên liệu xào','Làm sạch và thấm ráo 450g cải thìa và 5g bột bắp, dùng dao sắc thái lát mỏng vừa ăn khoảng 2–3mm ngang thớ để khi xào nhanh chín mềm không bị dai. Nhặt rửa sạch rau củ ăn kèm, cắt khúc xéo 4cm hoặc tách nhánh đồng đều giúp tiếp xúc nhiệt nhanh trên chảo. Đun sôi nồi nước có xíu muối và 2 giọt dầu ăn, chần cải thìa 45 giây rồi vớt ra tô nước đá lạnh 1 phút, để thật ráo.',4,'Nguyên liệu xào bắt buộc phải để thật ráo nước trước khi cho vào chảo để đạt hiệu ứng áp nhiệt thơm kiểu chảo gang.'),
(152,2,'Ướp mềm nguyên liệu đạm & pha sẵn chén sốt xào','Ướp phần đạm trong 450g cải thìa và 5g bột bắp với 1/3 lượng 25g tỏi, chút dầu ăn và 1/3 lượng 25ml dầu hào và 10ml nước tương trong 10 phút để giữ độ ẩm mọng. Pha phần 25ml dầu hào và 10ml nước tương còn lại cùng 20ml nước lọc vào chén nhỏ khuấy tan hoàn toàn để thao tác xào lửa lớn diễn ra dứt khoát. Phi thơm vàng 2/3 số tỏi băm; hòa dầu hào, nước tương, 40ml nước lọc và 5g bột bắp rót vào đun sôi sệt nhẹ.',4,'Thêm 1 muỗng cà phê dầu ăn vào bước ướp thịt bò/heo giúp khóa ẩm và các lát thịt tơi nhanh không bị dính chùm khi gặp chảo nóng.'),
(152,3,'Chần nhanh rau củ giữ sắc xanh ngọc & độ giòn','Đun sôi nồi nước nhỏ với một nhúm muối, thả rau củ ăn kèm vào chần nhanh 30–45 giây rồi vớt ngay ra tô nước đá lạnh cho sốc nhiệt, sau đó đổ ra rổ cho thật ráo. Bước tiền xử lý này giúp rau củ chín đều từ trong mà bên ngoài vẫn xanh mướt giòn sần sật.',3,'Thời gian chần dưới 1 phút kết hợp ngâm nước đá lạnh là bí quyết nhà hàng giúp đĩa rau xào không bị chảy nước đen đĩa.'),
(152,4,'Xào săn nguyên liệu chính trên lửa lớn nhanh tay','Làm nóng chảo rộng trên lửa lớn nhất với 15ml dầu ăn, phi dậy mùi một nửa 25g tỏi rồi trút phần đạm chính trong 450g cải thìa và 5g bột bắp vào đảo cực nhanh tay trong 60–90 giây. Ngay khi thịt hoặc hải sản vừa chín tái hồng khoảng 85%, lập tức trút riêng ra đĩa sạch để không bị quá lửa khô xác. Đảo cải thìa nhanh tay trong chảo nóng với 1/3 tỏi còn lại 45 giây rồi xếp ngay ngắn ra đĩa.',3,'Tuyệt đối không xào thịt chung từ đầu đến cuối với rau củ vì thịt sẽ bị dai và tiết nước làm mất độ giòn.'),
(152,5,'Xào rau củ lửa lớn & rưới sốt định lượng khóa vị','Giữ nguyên chảo nóng trên lửa lớn, thêm chút dầu phi thơm nốt phần 25g tỏi còn lại rồi cho rau củ ăn kèm đã ráo nước vào đảo đều 1–2 phút. Trút ngược đĩa đạm vào chảo, rưới đều chén sốt gia vị đã pha và xóc nhanh tay 45 giây cho sốt sánh bóng áo quanh từng miếng nguyên liệu.',4,'Rưới sốt vòng quanh thành chảo nóng thay vì đổ thẳng giữa lòng chảo giúp sốt bốc hơi thơm lừng và sệt lại tức thì.'),
(152,6,'Dậy hương tiêu hành & trình bày nóng hổi','Cho hành ngò và tiêu xay vào đảo nhẹ đúng 1 lượt rồi tắt bếp ngay khi khói thơm bốc lên nghi ngút. Gắp món Cải thìa xào tỏi dầu hào xanh mướt ra đĩa rộng lòng để tản nhiệt đều, tránh đậy kín vung và thưởng thức nóng ngay cùng cơm dẻo cho 4 người. Chan đều sốt dầu hào sánh bóng lên mặt cải thìa, rắc tỏi phi giòn rồi dùng ngay.',2,'Bày món xào ra đĩa rộng không xếp chồng quá dày giúp hơi nóng thoát nhẹ, giữ rau củ giòn ngọt lâu đến miếng cuối cùng.'),
(153,1,'Sơ chế & thái mỏng đồng đều nguyên liệu xào','Làm sạch và thấm ráo 500g bạch tuộc, dùng dao sắc thái lát mỏng vừa ăn khoảng 2–3mm ngang thớ để khi xào nhanh chín mềm không bị dai. Nhặt rửa sạch 120g hành tây và 100g ớt chuông, cắt khúc xéo 4cm hoặc tách nhánh đồng đều giúp tiếp xúc nhiệt nhanh trên chảo. Bóp bạch tuộc với muối và gừng xả sạch, chần nước sôi 30 giây với lát gừng rồi ngâm ngay nước đá giúp bạch tuộc giòn sần sật.',6,'Nguyên liệu xào bắt buộc phải để thật ráo nước trước khi cho vào chảo để đạt hiệu ứng áp nhiệt thơm kiểu chảo gang.'),
(153,2,'Ướp mềm nguyên liệu đạm & pha sẵn chén sốt xào','Ướp phần đạm trong 500g bạch tuộc với 1/3 lượng 40g sả, chút dầu ăn và 1/3 lượng 30g sa tế và 20ml nước mắm trong 10 phút để giữ độ ẩm mọng. Pha phần 30g sa tế và 20ml nước mắm còn lại cùng 20ml nước lọc vào chén nhỏ khuấy tan hoàn toàn để thao tác xào lửa lớn diễn ra dứt khoát. Làm nóng chảo dầu ăn, phi thơm sả băm và tỏi rồi cho sa tế vào đảo nhẹ ở lửa vừa.',4,'Thêm 1 muỗng cà phê dầu ăn vào bước ướp thịt bò/heo giúp khóa ẩm và các lát thịt tơi nhanh không bị dính chùm khi gặp chảo nóng.'),
(153,3,'Chần nhanh rau củ giữ sắc xanh ngọc & độ giòn','Đun sôi nồi nước nhỏ với một nhúm muối, thả 120g hành tây và 100g ớt chuông vào chần nhanh 30–45 giây rồi vớt ngay ra tô nước đá lạnh cho sốc nhiệt, sau đó đổ ra rổ cho thật ráo. Bước tiền xử lý này giúp rau củ chín đều từ trong mà bên ngoài vẫn xanh mướt giòn sần sật.',4,'Thời gian chần dưới 1 phút kết hợp ngâm nước đá lạnh là bí quyết nhà hàng giúp đĩa rau xào không bị chảy nước đen đĩa.'),
(153,4,'Xào săn nguyên liệu chính trên lửa lớn nhanh tay','Làm nóng chảo rộng trên lửa lớn nhất với 15ml dầu ăn, phi dậy mùi một nửa 40g sả rồi trút phần đạm chính trong 500g bạch tuộc vào đảo cực nhanh tay trong 60–90 giây. Ngay khi thịt hoặc hải sản vừa chín tái hồng khoảng 85%, lập tức trút riêng ra đĩa sạch để không bị quá lửa khô xác. Trút bạch tuộc vào đảo lửa lớn 2 phút với nước mắm và chút đường cho thấm sốt cay.',4,'Tuyệt đối không xào thịt chung từ đầu đến cuối với rau củ vì thịt sẽ bị dai và tiết nước làm mất độ giòn.');
INSERT INTO `recipe_steps` (`recipe_id`,`step_order`,`title`,`instruction`,`duration_mins`,`tip_note`) VALUES
(153,5,'Xào rau củ lửa lớn & rưới sốt định lượng khóa vị','Giữ nguyên chảo nóng trên lửa lớn, thêm chút dầu phi thơm nốt phần 40g sả còn lại rồi cho 120g hành tây và 100g ớt chuông đã ráo nước vào đảo đều 1–2 phút. Trút ngược đĩa đạm vào chảo, rưới đều chén sốt gia vị đã pha và xóc nhanh tay 45 giây cho sốt sánh bóng áo quanh từng miếng nguyên liệu.',4,'Rưới sốt vòng quanh thành chảo nóng thay vì đổ thẳng giữa lòng chảo giúp sốt bốc hơi thơm lừng và sệt lại tức thì.'),
(153,6,'Dậy hương tiêu hành & trình bày nóng hổi','Cho 25g rau răm vào đảo nhẹ đúng 1 lượt rồi tắt bếp ngay khi khói thơm bốc lên nghi ngút. Gắp món Bạch tuộc xào sa tế sả ớt ra đĩa rộng lòng để tản nhiệt đều, tránh đậy kín vung và thưởng thức nóng ngay cùng cơm dẻo cho 4 người. Cho hành tây và ớt chuông vào đảo thêm 1 phút, tắt bếp trộn rau răm thái nhỏ và rắc tiêu.',3,'Bày món xào ra đĩa rộng không xếp chồng quá dày giúp hơi nóng thoát nhẹ, giữ rau củ giòn ngọt lâu đến miếng cuối cùng.'),
(154,1,'Sơ chế & thái mỏng đồng đều nguyên liệu xào','Làm sạch và thấm ráo 400g lươn đồng và 200g miến dong, dùng dao sắc thái lát mỏng vừa ăn khoảng 2–3mm ngang thớ để khi xào nhanh chín mềm không bị dai. Nhặt rửa sạch 100g giá đỗ, cắt khúc xéo 4cm hoặc tách nhánh đồng đều giúp tiếp xúc nhiệt nhanh trên chảo. Lươn lọc bỏ xương, thái dải vừa ướp chút nghệ, tiêu, nước mắm rồi chiên vàng giòn ráo dầu.',8,'Nguyên liệu xào bắt buộc phải để thật ráo nước trước khi cho vào chảo để đạt hiệu ứng áp nhiệt thơm kiểu chảo gang.'),
(154,2,'Ướp mềm nguyên liệu đạm & pha sẵn chén sốt xào','Ướp phần đạm trong 400g lươn đồng và 200g miến dong với 1/3 lượng hành tím và tỏi băm nhỏ, chút dầu ăn và 1/3 lượng 25ml nước mắm trong 10 phút để giữ độ ẩm mọng. Pha phần 25ml nước mắm còn lại cùng 20ml nước lọc vào chén nhỏ khuấy tan hoàn toàn để thao tác xào lửa lớn diễn ra dứt khoát. Ngâm miến nước nguội 10 phút, vớt ra trộn nhẹ 1/2 thìa dầu ăn và 1/2 thìa nước tương để miến không vón.',7,'Thêm 1 muỗng cà phê dầu ăn vào bước ướp thịt bò/heo giúp khóa ẩm và các lát thịt tơi nhanh không bị dính chùm khi gặp chảo nóng.'),
(154,3,'Chần nhanh rau củ giữ sắc xanh ngọc & độ giòn','Đun sôi nồi nước nhỏ với một nhúm muối, thả 100g giá đỗ vào chần nhanh 30–45 giây rồi vớt ngay ra tô nước đá lạnh cho sốc nhiệt, sau đó đổ ra rổ cho thật ráo. Bước tiền xử lý này giúp rau củ chín đều từ trong mà bên ngoài vẫn xanh mướt giòn sần sật.',6,'Thời gian chần dưới 1 phút kết hợp ngâm nước đá lạnh là bí quyết nhà hàng giúp đĩa rau xào không bị chảy nước đen đĩa.'),
(154,4,'Xào săn nguyên liệu chính trên lửa lớn nhanh tay','Làm nóng chảo rộng trên lửa lớn nhất với 15ml dầu ăn, phi dậy mùi một nửa hành tím và tỏi băm nhỏ rồi trút phần đạm chính trong 400g lươn đồng và 200g miến dong vào đảo cực nhanh tay trong 60–90 giây. Ngay khi thịt hoặc hải sản vừa chín tái hồng khoảng 85%, lập tức trút riêng ra đĩa sạch để không bị quá lửa khô xác. Phi thơm hành tím, xào nấm hương, nấm mèo, cà rốt trong 2 phút với gia vị vừa thanh rồi trút riêng.',7,'Tuyệt đối không xào thịt chung từ đầu đến cuối với rau củ vì thịt sẽ bị dai và tiết nước làm mất độ giòn.'),
(154,5,'Xào rau củ lửa lớn & rưới sốt định lượng khóa vị','Giữ nguyên chảo nóng trên lửa lớn, thêm chút dầu phi thơm nốt phần hành tím và tỏi băm nhỏ còn lại rồi cho 100g giá đỗ đã ráo nước vào đảo đều 1–2 phút. Trút ngược đĩa đạm vào chảo, rưới đều chén sốt gia vị đã pha và xóc nhanh tay 45 giây cho sốt sánh bóng áo quanh từng miếng nguyên liệu.',7,'Rưới sốt vòng quanh thành chảo nóng thay vì đổ thẳng giữa lòng chảo giúp sốt bốc hơi thơm lừng và sệt lại tức thì.'),
(154,6,'Dậy hương tiêu hành & trình bày nóng hổi','Cho 25g rau răm vào đảo nhẹ đúng 1 lượt rồi tắt bếp ngay khi khói thơm bốc lên nghi ngút. Gắp món Miến xào lươn giòn Nghệ An ra đĩa rộng lòng để tản nhiệt đều, tránh đậy kín vung và thưởng thức nóng ngay cùng cơm dẻo cho 4 người. Đảo miến trong chảo nóng 3 phút đến khi mềm dẻo, cho nấm rau, giá đỗ và 1/2 lượng lươn giòn vào đảo nhanh rồi bày đĩa, xếp phần lươn giòn còn lại cùng rau răm lên trên.',5,'Bày món xào ra đĩa rộng không xếp chồng quá dày giúp hơi nóng thoát nhẹ, giữ rau củ giòn ngọt lâu đến miếng cuối cùng.'),
(155,1,'Sơ chế & thái mỏng đồng đều nguyên liệu xào','Làm sạch và thấm ráo 400g hến tươi và 150g bánh đa nướng, dùng dao sắc thái lát mỏng vừa ăn khoảng 2–3mm ngang thớ để khi xào nhanh chín mềm không bị dai. Nhặt rửa sạch rau củ ăn kèm, cắt khúc xéo 4cm hoặc tách nhánh đồng đều giúp tiếp xúc nhiệt nhanh trên chảo. Rửa thịt hến nhẹ nhàng trong tô nước muối loãng nhiều lần cho sạch hết sạn cát rồi vắt cực ráo.',6,'Nguyên liệu xào bắt buộc phải để thật ráo nước trước khi cho vào chảo để đạt hiệu ứng áp nhiệt thơm kiểu chảo gang.'),
(155,2,'Ướp mềm nguyên liệu đạm & pha sẵn chén sốt xào','Ướp phần đạm trong 400g hến tươi và 150g bánh đa nướng với 1/3 lượng 40g hành tím, chút dầu ăn và 1/3 lượng 25ml nước mắm và 8g ớt trong 10 phút để giữ độ ẩm mọng. Pha phần 25ml nước mắm và 8g ớt còn lại cùng 20ml nước lọc vào chén nhỏ khuấy tan hoàn toàn để thao tác xào lửa lớn diễn ra dứt khoát. Làm nóng chảo dầu ăn, phi vàng 1/2 phần hành tím băm cho giòn thơm rồi vớt riêng làm hành phi.',4,'Thêm 1 muỗng cà phê dầu ăn vào bước ướp thịt bò/heo giúp khóa ẩm và các lát thịt tơi nhanh không bị dính chùm khi gặp chảo nóng.'),
(155,3,'Chần nhanh rau củ giữ sắc xanh ngọc & độ giòn','Đun sôi nồi nước nhỏ với một nhúm muối, thả rau củ ăn kèm vào chần nhanh 30–45 giây rồi vớt ngay ra tô nước đá lạnh cho sốc nhiệt, sau đó đổ ra rổ cho thật ráo. Bước tiền xử lý này giúp rau củ chín đều từ trong mà bên ngoài vẫn xanh mướt giòn sần sật.',4,'Thời gian chần dưới 1 phút kết hợp ngâm nước đá lạnh là bí quyết nhà hàng giúp đĩa rau xào không bị chảy nước đen đĩa.'),
(155,4,'Xào săn nguyên liệu chính trên lửa lớn nhanh tay','Làm nóng chảo rộng trên lửa lớn nhất với 15ml dầu ăn, phi dậy mùi một nửa 40g hành tím rồi trút phần đạm chính trong 400g hến tươi và 150g bánh đa nướng vào đảo cực nhanh tay trong 60–90 giây. Ngay khi thịt hoặc hải sản vừa chín tái hồng khoảng 85%, lập tức trút riêng ra đĩa sạch để không bị quá lửa khô xác. Đảo phần hành tím còn lại với sả/ớt băm, trút hến vào xào nhanh 3 phút với nước mắm, chút đường và tiêu.',4,'Tuyệt đối không xào thịt chung từ đầu đến cuối với rau củ vì thịt sẽ bị dai và tiết nước làm mất độ giòn.'),
(155,5,'Xào rau củ lửa lớn & rưới sốt định lượng khóa vị','Giữ nguyên chảo nóng trên lửa lớn, thêm chút dầu phi thơm nốt phần 40g hành tím còn lại rồi cho rau củ ăn kèm đã ráo nước vào đảo đều 1–2 phút. Trút ngược đĩa đạm vào chảo, rưới đều chén sốt gia vị đã pha và xóc nhanh tay 45 giây cho sốt sánh bóng áo quanh từng miếng nguyên liệu.',4,'Rưới sốt vòng quanh thành chảo nóng thay vì đổ thẳng giữa lòng chảo giúp sốt bốc hơi thơm lừng và sệt lại tức thì.'),
(155,6,'Dậy hương tiêu hành & trình bày nóng hổi','Cho 50g đậu phộng và 40g rau răm vào đảo nhẹ đúng 1 lượt rồi tắt bếp ngay khi khói thơm bốc lên nghi ngút. Gắp món Hến xúc bánh đa xào hành răm ra đĩa rộng lòng để tản nhiệt đều, tránh đậy kín vung và thưởng thức nóng ngay cùng cơm dẻo cho 4 người. Tắt bếp cho rau răm thái nhỏ và đậu phộng rang vào đảo đều; rắc hành phi lên trên và dọn kèm đĩa bánh đa nướng giòn.',3,'Bày món xào ra đĩa rộng không xếp chồng quá dày giúp hơi nóng thoát nhẹ, giữ rau củ giòn ngọt lâu đến miếng cuối cùng.'),
(156,1,'Sơ chế & thái mỏng đồng đều nguyên liệu xào','Làm sạch và thấm ráo 300g đậu hũ và 180g thịt heo xay, dùng dao sắc thái lát mỏng vừa ăn khoảng 2–3mm ngang thớ để khi xào nhanh chín mềm không bị dai. Nhặt rửa sạch 180g giá đỗ, cắt khúc xéo 4cm hoặc tách nhánh đồng đều giúp tiếp xúc nhiệt nhanh trên chảo. Thấm khô đậu hũ, cắt miếng mỏng rồi áp chảo ít dầu 2 mặt cho hơi vàng cạnh, gắp ra đĩa.',4,'Nguyên liệu xào bắt buộc phải để thật ráo nước trước khi cho vào chảo để đạt hiệu ứng áp nhiệt thơm kiểu chảo gang.'),
(156,2,'Ướp mềm nguyên liệu đạm & pha sẵn chén sốt xào','Ướp phần đạm trong 300g đậu hũ và 180g thịt heo xay với 1/3 lượng 15g hành tím, chút dầu ăn và 1/3 lượng 25ml nước tương trong 10 phút để giữ độ ẩm mọng. Pha phần 25ml nước tương còn lại cùng 20ml nước lọc vào chén nhỏ khuấy tan hoàn toàn để thao tác xào lửa lớn diễn ra dứt khoát. Phi thơm hành tím, cho thịt heo xay vào đảo chín tơi cùng 1 thìa nước tương và tiêu.',4,'Thêm 1 muỗng cà phê dầu ăn vào bước ướp thịt bò/heo giúp khóa ẩm và các lát thịt tơi nhanh không bị dính chùm khi gặp chảo nóng.'),
(156,3,'Chần nhanh rau củ giữ sắc xanh ngọc & độ giòn','Đun sôi nồi nước nhỏ với một nhúm muối, thả 180g giá đỗ vào chần nhanh 30–45 giây rồi vớt ngay ra tô nước đá lạnh cho sốc nhiệt, sau đó đổ ra rổ cho thật ráo. Bước tiền xử lý này giúp rau củ chín đều từ trong mà bên ngoài vẫn xanh mướt giòn sần sật.',3,'Thời gian chần dưới 1 phút kết hợp ngâm nước đá lạnh là bí quyết nhà hàng giúp đĩa rau xào không bị chảy nước đen đĩa.'),
(156,4,'Xào săn nguyên liệu chính trên lửa lớn nhanh tay','Làm nóng chảo rộng trên lửa lớn nhất với 15ml dầu ăn, phi dậy mùi một nửa 15g hành tím rồi trút phần đạm chính trong 300g đậu hũ và 180g thịt heo xay vào đảo cực nhanh tay trong 60–90 giây. Ngay khi thịt hoặc hải sản vừa chín tái hồng khoảng 85%, lập tức trút riêng ra đĩa sạch để không bị quá lửa khô xác. Trút đậu hũ vào nhẹ tay, thả giá đỗ và rau hẹ cắt khúc lên trên đảo nhanh 1 phút trên lửa lớn.',4,'Tuyệt đối không xào thịt chung từ đầu đến cuối với rau củ vì thịt sẽ bị dai và tiết nước làm mất độ giòn.'),
(156,5,'Xào rau củ lửa lớn & rưới sốt định lượng khóa vị','Giữ nguyên chảo nóng trên lửa lớn, thêm chút dầu phi thơm nốt phần 15g hành tím còn lại rồi cho 180g giá đỗ đã ráo nước vào đảo đều 1–2 phút. Trút ngược đĩa đạm vào chảo, rưới đều chén sốt gia vị đã pha và xóc nhanh tay 45 giây cho sốt sánh bóng áo quanh từng miếng nguyên liệu.',4,'Rưới sốt vòng quanh thành chảo nóng thay vì đổ thẳng giữa lòng chảo giúp sốt bốc hơi thơm lừng và sệt lại tức thì.'),
(156,6,'Dậy hương tiêu hành & trình bày nóng hổi','Cho 80g rau hẹ vào đảo nhẹ đúng 1 lượt rồi tắt bếp ngay khi khói thơm bốc lên nghi ngút. Gắp món Đậu hũ xào giá hẹ thịt băm ra đĩa rộng lòng để tản nhiệt đều, tránh đậy kín vung và thưởng thức nóng ngay cùng cơm dẻo cho 4 người. Rưới phần nước tương còn lại đảo nhẹ 20 giây rồi tắt bếp trút ra đĩa.',3,'Bày món xào ra đĩa rộng không xếp chồng quá dày giúp hơi nóng thoát nhẹ, giữ rau củ giòn ngọt lâu đến miếng cuối cùng.'),
(157,1,'Sơ chế & thái mỏng đồng đều nguyên liệu xào','Làm sạch và thấm ráo 300g thịt bò và 200g đậu hà lan, dùng dao sắc thái lát mỏng vừa ăn khoảng 2–3mm ngang thớ để khi xào nhanh chín mềm không bị dai. Nhặt rửa sạch rau củ ăn kèm, cắt khúc xéo 4cm hoặc tách nhánh đồng đều giúp tiếp xúc nhiệt nhanh trên chảo. Ướp thịt bò với dầu hào, chút dầu ăn, tỏi băm và tiêu trong 15 phút.',6,'Nguyên liệu xào bắt buộc phải để thật ráo nước trước khi cho vào chảo để đạt hiệu ứng áp nhiệt thơm kiểu chảo gang.'),
(157,2,'Ướp mềm nguyên liệu đạm & pha sẵn chén sốt xào','Ướp phần đạm trong 300g thịt bò và 200g đậu hà lan với 1/3 lượng 20g tỏi, chút dầu ăn và 1/3 lượng 25ml dầu hào trong 10 phút để giữ độ ẩm mọng. Pha phần 25ml dầu hào còn lại cùng 20ml nước lọc vào chén nhỏ khuấy tan hoàn toàn để thao tác xào lửa lớn diễn ra dứt khoát. Xào nhanh bò trong chảo thật nóng khoảng 1.5 phút cho vừa chín tái, trút ra đĩa.',4,'Thêm 1 muỗng cà phê dầu ăn vào bước ướp thịt bò/heo giúp khóa ẩm và các lát thịt tơi nhanh không bị dính chùm khi gặp chảo nóng.'),
(157,3,'Chần nhanh rau củ giữ sắc xanh ngọc & độ giòn','Đun sôi nồi nước nhỏ với một nhúm muối, thả rau củ ăn kèm vào chần nhanh 30–45 giây rồi vớt ngay ra tô nước đá lạnh cho sốc nhiệt, sau đó đổ ra rổ cho thật ráo. Bước tiền xử lý này giúp rau củ chín đều từ trong mà bên ngoài vẫn xanh mướt giòn sần sật.',4,'Thời gian chần dưới 1 phút kết hợp ngâm nước đá lạnh là bí quyết nhà hàng giúp đĩa rau xào không bị chảy nước đen đĩa.'),
(157,4,'Xào săn nguyên liệu chính trên lửa lớn nhanh tay','Làm nóng chảo rộng trên lửa lớn nhất với 15ml dầu ăn, phi dậy mùi một nửa 20g tỏi rồi trút phần đạm chính trong 300g thịt bò và 200g đậu hà lan vào đảo cực nhanh tay trong 60–90 giây. Ngay khi thịt hoặc hải sản vừa chín tái hồng khoảng 85%, lập tức trút riêng ra đĩa sạch để không bị quá lửa khô xác. Phi thơm tỏi còn lại, đảo cà rốt và nấm hương 2 phút với 2 thìa nước rồi thả đậu Hà Lan vào xào thêm 2 phút.',4,'Tuyệt đối không xào thịt chung từ đầu đến cuối với rau củ vì thịt sẽ bị dai và tiết nước làm mất độ giòn.'),
(157,5,'Xào rau củ lửa lớn & rưới sốt định lượng khóa vị','Giữ nguyên chảo nóng trên lửa lớn, thêm chút dầu phi thơm nốt phần 20g tỏi còn lại rồi cho rau củ ăn kèm đã ráo nước vào đảo đều 1–2 phút. Trút ngược đĩa đạm vào chảo, rưới đều chén sốt gia vị đã pha và xóc nhanh tay 45 giây cho sốt sánh bóng áo quanh từng miếng nguyên liệu.',4,'Rưới sốt vòng quanh thành chảo nóng thay vì đổ thẳng giữa lòng chảo giúp sốt bốc hơi thơm lừng và sệt lại tức thì.');
INSERT INTO `recipe_steps` (`recipe_id`,`step_order`,`title`,`instruction`,`duration_mins`,`tip_note`) VALUES
(157,6,'Dậy hương tiêu hành & trình bày nóng hổi','Cho hành ngò và tiêu xay vào đảo nhẹ đúng 1 lượt rồi tắt bếp ngay khi khói thơm bốc lên nghi ngút. Gắp món Thịt bò xào đậu Hà Lan nấm hương ra đĩa rộng lòng để tản nhiệt đều, tránh đậy kín vung và thưởng thức nóng ngay cùng cơm dẻo cho 4 người. Trút đĩa thịt bò vào đảo hòa quyện 30 giây rồi bắc bếp, rắc thêm chút tiêu xay.',3,'Bày món xào ra đĩa rộng không xếp chồng quá dày giúp hơi nóng thoát nhẹ, giữ rau củ giòn ngọt lâu đến miếng cuối cùng.'),
(158,1,'Sơ chế & thái mỏng đồng đều nguyên liệu xào','Làm sạch và thấm ráo 300g tôm sú và 350g bông cải xanh, dùng dao sắc thái lát mỏng vừa ăn khoảng 2–3mm ngang thớ để khi xào nhanh chín mềm không bị dai. Nhặt rửa sạch rau củ ăn kèm, cắt khúc xéo 4cm hoặc tách nhánh đồng đều giúp tiếp xúc nhiệt nhanh trên chảo. Chần bông cải xanh và cà rốt trong nước sôi pha xíu muối 45 giây rồi ngâm nước lạnh giúp giữ màu xanh cam rực rỡ.',6,'Nguyên liệu xào bắt buộc phải để thật ráo nước trước khi cho vào chảo để đạt hiệu ứng áp nhiệt thơm kiểu chảo gang.'),
(158,2,'Ướp mềm nguyên liệu đạm & pha sẵn chén sốt xào','Ướp phần đạm trong 300g tôm sú và 350g bông cải xanh với 1/3 lượng 20g tỏi, chút dầu ăn và 1/3 lượng 20ml dầu hào và 3g tiêu trong 10 phút để giữ độ ẩm mọng. Pha phần 20ml dầu hào và 3g tiêu còn lại cùng 20ml nước lọc vào chén nhỏ khuấy tan hoàn toàn để thao tác xào lửa lớn diễn ra dứt khoát. Ướp tôm với 1/2 tỏi băm và chút tiêu; đảo nhanh trên chảo nóng 2 phút đến khi tôm cong đỏ săn chắc.',4,'Thêm 1 muỗng cà phê dầu ăn vào bước ướp thịt bò/heo giúp khóa ẩm và các lát thịt tơi nhanh không bị dính chùm khi gặp chảo nóng.'),
(158,3,'Chần nhanh rau củ giữ sắc xanh ngọc & độ giòn','Đun sôi nồi nước nhỏ với một nhúm muối, thả rau củ ăn kèm vào chần nhanh 30–45 giây rồi vớt ngay ra tô nước đá lạnh cho sốc nhiệt, sau đó đổ ra rổ cho thật ráo. Bước tiền xử lý này giúp rau củ chín đều từ trong mà bên ngoài vẫn xanh mướt giòn sần sật.',4,'Thời gian chần dưới 1 phút kết hợp ngâm nước đá lạnh là bí quyết nhà hàng giúp đĩa rau xào không bị chảy nước đen đĩa.'),
(158,4,'Xào săn nguyên liệu chính trên lửa lớn nhanh tay','Làm nóng chảo rộng trên lửa lớn nhất với 15ml dầu ăn, phi dậy mùi một nửa 20g tỏi rồi trút phần đạm chính trong 300g tôm sú và 350g bông cải xanh vào đảo cực nhanh tay trong 60–90 giây. Ngay khi thịt hoặc hải sản vừa chín tái hồng khoảng 85%, lập tức trút riêng ra đĩa sạch để không bị quá lửa khô xác. Cho nốt tỏi băm vào chảo, trút bông cải xanh và cà rốt cùng dầu hào đảo nhanh tay lửa lớn 1.5 phút.',4,'Tuyệt đối không xào thịt chung từ đầu đến cuối với rau củ vì thịt sẽ bị dai và tiết nước làm mất độ giòn.'),
(158,5,'Xào rau củ lửa lớn & rưới sốt định lượng khóa vị','Giữ nguyên chảo nóng trên lửa lớn, thêm chút dầu phi thơm nốt phần 20g tỏi còn lại rồi cho rau củ ăn kèm đã ráo nước vào đảo đều 1–2 phút. Trút ngược đĩa đạm vào chảo, rưới đều chén sốt gia vị đã pha và xóc nhanh tay 45 giây cho sốt sánh bóng áo quanh từng miếng nguyên liệu.',4,'Rưới sốt vòng quanh thành chảo nóng thay vì đổ thẳng giữa lòng chảo giúp sốt bốc hơi thơm lừng và sệt lại tức thì.'),
(158,6,'Dậy hương tiêu hành & trình bày nóng hổi','Cho hành ngò và tiêu xay vào đảo nhẹ đúng 1 lượt rồi tắt bếp ngay khi khói thơm bốc lên nghi ngút. Gắp món Súp lơ xanh xào tôm tươi ra đĩa rộng lòng để tản nhiệt đều, tránh đậy kín vung và thưởng thức nóng ngay cùng cơm dẻo cho 4 người. Đổ tôm vào xóc đều 30 giây, rắc tiêu xay và trình bày ra đĩa ngay.',3,'Bày món xào ra đĩa rộng không xếp chồng quá dày giúp hơi nóng thoát nhẹ, giữ rau củ giòn ngọt lâu đến miếng cuối cùng.'),
(159,1,'Sơ chế sạch & thấm thật khô bề mặt nguyên liệu','Rửa sạch 800g đùi gà cùng chút muối loãng để khử mùi tự nhiên, sau đó dùng khăn giấy bếp thấm thật khô ráo hoàn toàn bề mặt. Khứa nhẹ các đường chéo hoặc cắt miếng vừa ăn dày 2–3cm để nhiệt và gia vị thấm sâu đều khắp bên trong. Rửa sạch đùi gà thấm thật khô, khứa vài đường mặt trong xương; vắt nước cốt tỏi hành băm trộn nước tương, dầu hào, ngũ vị hương ướp 2 tiếng.',9,'Bề mặt nguyên liệu càng khô ráo thì khi chiên không bị văng dầu và khi nướng sẽ lên màu vàng ruộm giòn rụm cực đẹp.'),
(159,2,'Chuẩn bị hỗn hợp sốt ướp / bột áo chuẩn tỷ lệ','Phối trộn 25g tỏi và 25g hành tím băm thật nhuyễn (hoặc vắt lấy nước cốt thơm) cùng 40g mật ong, 6g ngũ vị hương, 30ml nước tương và 25ml dầu hào trong tô lớn cho quyện sánh đồng nhất. Nếu món có lớp vỏ bột hoặc bánh cuốn từ 800g đùi gà, trộn đều hỗn hợp theo đúng định lượng để đạt độ giòn xốp mỏng nhẹ chuẩn vị. Bật trước lò nướng ở 190°C (hoặc nồi chiên không dầu 180°C) 5 phút; lót giấy nến có khay hứng mỡ.',8,'Vắt lấy nước cốt hành tỏi sả khi ướp đồ nướng giúp hương thơm thấm sâu mà không bị cháy đen phần xác băm trên lửa cao.'),
(159,3,'Ướp thấm thớ thịt / tạo hình cuốn khéo léo','Áo đều hỗn hợp gia vị hoặc lớp bột/vỏ cuốn quanh 800g đùi gà, massage nhẹ nhàng rồi để nghỉ 15–20 phút cho gia vị thẩm thấu trọn vẹn. Trường hợp cuốn chả/nem hoặc đổ khuôn bánh, thao tác đều tay vừa chặt để nhân kết dính nhưng không bị bục rách khi gặp nhiệt.',11,'Để nguyên liệu nghỉ đủ thời gian trước khi chiên nướng giúp lớp áo bột bám chắc và phần nhân bên trong mọng ngọt.'),
(159,4,'Pha nước chấm cân vị & sơ chế rau đồ chua ăn kèm','Nhặt rửa sạch rau củ ăn kèm ngâm nước mát cho giòn tươi, bào sợi hoặc thái lát gọn gàng bày sẵn bên cạnh. Pha chén nước chấm chua ngọt hoặc muối ớt chanh sả sánh thơm theo khẩu vị vùng miền của món Gà nướng lu mật ong ngũ vị để cân bằng độ béo giòn.',7,'Luôn chuẩn bị xong rau sống và bát nước chấm trước khi chiên/nướng mẻ cuối để món ăn vừa ra lò là thưởng thức nóng giòn ngay.'),
(159,5,'Làm nóng dầu / lò nướng chuẩn nhiệt & làm chín đều lần 1','Làm nóng chảo dầu hoặc vỉ nướng/nồi chiên ở mức nhiệt vừa khoảng 165–175°C, xếp 800g đùi gà vào với khoảng cách thoáng đều nhau. Chiên hoặc nướng trở mặt nhịp nhàng trên lửa vừa để nhiệt dẫn sâu làm chín mềm ngọt hoàn toàn phần nhân bên trong. Nướng 180°C trong 15 phút mặt trong, sau đó lật mặt da lên nướng thêm 10 phút cho da săn ráo mỡ.',13,'Kiểm tra nhiệt dầu bằng đầu đũa tre thấy sủi tăm nhỏ đều là đạt chuẩn 170°C, giúp vỏ không cháy sớm khi bên trong còn sống.'),
(159,6,'Tăng nhiệt khóa giòn rụm vàng ươm bề mặt lần 2','Ở 2–3 phút cuối, tăng lên lửa vừa lớn (khoảng 190°C) hoặc phết thêm lớp dầu điều/mật ong mỏng để vỏ ngoài của Gà nướng lu mật ong ngũ vị chuyển sắc vàng óng ánh và nổ giòn rụm. Lắng nghe tiếng xèo giòn rộn rã và hương thơm phức lan tỏa khắp bếp thì gắp ra vỉ thưa cho ráo dầu thừa.',7,'Đặt đồ chiên nướng lên giá inox thoáng khí thay vì giấy thấm dầu chồng khít để hơi nước thoát hết, giữ độ giòn lâu gấp 3 lần.'),
(159,7,'Trình bày bắt mắt kèm rau thơm & thưởng thức nóng','Xếp thành phẩm vàng giòn ra đĩa lớn có bày sẵn rau củ ăn kèm và điểm xuyết hành ngò và tiêu xay tươi xanh hài hòa màu sắc. Dọn kèm chén nước chấm sánh đậm ngay chính giữa mâm ăn cho 4 người thưởng thức khi vỏ ngoài còn nóng giòn rụm. Trộn mật ong với chút dầu ăn phết đều mặt da, nướng tiếp ở 200°C trong 4 phút cho da gà vàng cánh gián óng ả.',5,'Cắt miếng hoặc dọn ăn ngay trong vòng 10 phút sau khi rời bếp để cảm nhận trọn vẹn sự đối lập giòn ngoài - mềm ngọt bên trong.'),
(160,1,'Sơ chế sạch & thấm thật khô bề mặt nguyên liệu','Rửa sạch 750g sườn non cùng chút muối loãng để khử mùi tự nhiên, sau đó dùng khăn giấy bếp thấm thật khô ráo hoàn toàn bề mặt. Khứa nhẹ các đường chéo hoặc cắt miếng vừa ăn dày 2–3cm để nhiệt và gia vị thấm sâu đều khắp bên trong. Chần và luộc sườn non cùng lát gừng hành 12 phút cho thịt mềm bớt mỡ rồi vớt ráo.',8,'Bề mặt nguyên liệu càng khô ráo thì khi chiên không bị văng dầu và khi nướng sẽ lên màu vàng ruộm giòn rụm cực đẹp.'),
(160,2,'Chuẩn bị hỗn hợp sốt ướp / bột áo chuẩn tỷ lệ','Phối trộn 20g tỏi băm thật nhuyễn (hoặc vắt lấy nước cốt thơm) cùng 90g sốt bbq, 25g mật ong, 4g ngũ vị hương và 20ml nước tương trong tô lớn cho quyện sánh đồng nhất. Nếu món có lớp vỏ bột hoặc bánh cuốn từ 750g sườn non, trộn đều hỗn hợp theo đúng định lượng để đạt độ giòn xốp mỏng nhẹ chuẩn vị. Trộn sốt BBQ, nước tương, ngũ vị hương, tỏi băm và 1/2 phần mật ong xoa đều hai mặt sườn ướp 30 phút.',7,'Vắt lấy nước cốt hành tỏi sả khi ướp đồ nướng giúp hương thơm thấm sâu mà không bị cháy đen phần xác băm trên lửa cao.'),
(160,3,'Ướp thấm thớ thịt / tạo hình cuốn khéo léo','Áo đều hỗn hợp gia vị hoặc lớp bột/vỏ cuốn quanh 750g sườn non, massage nhẹ nhàng rồi để nghỉ 15–20 phút cho gia vị thẩm thấu trọn vẹn. Trường hợp cuốn chả/nem hoặc đổ khuôn bánh, thao tác đều tay vừa chặt để nhân kết dính nhưng không bị bục rách khi gặp nhiệt.',9,'Để nguyên liệu nghỉ đủ thời gian trước khi chiên nướng giúp lớp áo bột bám chắc và phần nhân bên trong mọng ngọt.'),
(160,4,'Pha nước chấm cân vị & sơ chế rau đồ chua ăn kèm','Nhặt rửa sạch rau củ ăn kèm ngâm nước mát cho giòn tươi, bào sợi hoặc thái lát gọn gàng bày sẵn bên cạnh. Pha chén nước chấm chua ngọt hoặc muối ớt chanh sả sánh thơm theo khẩu vị vùng miền của món Sườn nướng BBQ ngũ vị nồi chiên để cân bằng độ béo giòn.',6,'Luôn chuẩn bị xong rau sống và bát nước chấm trước khi chiên/nướng mẻ cuối để món ăn vừa ra lò là thưởng thức nóng giòn ngay.'),
(160,5,'Làm nóng dầu / lò nướng chuẩn nhiệt & làm chín đều lần 1','Làm nóng chảo dầu hoặc vỉ nướng/nồi chiên ở mức nhiệt vừa khoảng 165–175°C, xếp 750g sườn non vào với khoảng cách thoáng đều nhau. Chiên hoặc nướng trở mặt nhịp nhàng trên lửa vừa để nhiệt dẫn sâu làm chín mềm ngọt hoàn toàn phần nhân bên trong. Bọc giấy bạc lót đáy, nướng sườn 180°C trong 15 phút, lật mặt phết thêm sốt BBQ mật ong nướng tiếp 8 phút ở 190°C.',10,'Kiểm tra nhiệt dầu bằng đầu đũa tre thấy sủi tăm nhỏ đều là đạt chuẩn 170°C, giúp vỏ không cháy sớm khi bên trong còn sống.'),
(160,6,'Tăng nhiệt khóa giòn rụm vàng ươm bề mặt lần 2','Ở 2–3 phút cuối, tăng lên lửa vừa lớn (khoảng 190°C) hoặc phết thêm lớp dầu điều/mật ong mỏng để vỏ ngoài của Sườn nướng BBQ ngũ vị nồi chiên chuyển sắc vàng óng ánh và nổ giòn rụm. Lắng nghe tiếng xèo giòn rộn rã và hương thơm phức lan tỏa khắp bếp thì gắp ra vỉ thưa cho ráo dầu thừa.',6,'Đặt đồ chiên nướng lên giá inox thoáng khí thay vì giấy thấm dầu chồng khít để hơi nước thoát hết, giữ độ giòn lâu gấp 3 lần.'),
(160,7,'Trình bày bắt mắt kèm rau thơm & thưởng thức nóng','Xếp thành phẩm vàng giòn ra đĩa lớn có bày sẵn rau củ ăn kèm và điểm xuyết hành ngò và tiêu xay tươi xanh hài hòa màu sắc. Dọn kèm chén nước chấm sánh đậm ngay chính giữa mâm ăn cho 4 người thưởng thức khi vỏ ngoài còn nóng giòn rụm. Cho sườn nghỉ trên thớt 5 phút giúp giữ nước ngọt bên trong trước khi cắt thành từng dẻ và dùng nóng với salad.',4,'Cắt miếng hoặc dọn ăn ngay trong vòng 10 phút sau khi rời bếp để cảm nhận trọn vẹn sự đối lập giòn ngoài - mềm ngọt bên trong.'),
(161,1,'Sơ chế sạch & thấm thật khô bề mặt nguyên liệu','Rửa sạch 850g cá rô phi và 60g bột chiên xù cùng chút muối loãng để khử mùi tự nhiên, sau đó dùng khăn giấy bếp thấm thật khô ráo hoàn toàn bề mặt. Khứa nhẹ các đường chéo hoặc cắt miếng vừa ăn dày 2–3cm để nhiệt và gia vị thấm sâu đều khắp bên trong. Làm sạch mang, màng đen bụng cá rồi khứa 3-4 đường chéo mỗi bên thân cá; xoa chút muối gừng rượu rồi dùng khăn giấy thấm thật khô.',6,'Bề mặt nguyên liệu càng khô ráo thì khi chiên không bị văng dầu và khi nướng sẽ lên màu vàng ruộm giòn rụm cực đẹp.'),
(161,2,'Chuẩn bị hỗn hợp sốt ướp / bột áo chuẩn tỷ lệ','Phối trộn 15g tỏi băm thật nhuyễn (hoặc vắt lấy nước cốt thơm) cùng 40ml nước mắm và 30ml chanh trong tô lớn cho quyện sánh đồng nhất. Nếu món có lớp vỏ bột hoặc bánh cuốn từ 850g cá rô phi và 60g bột chiên xù, trộn đều hỗn hợp theo đúng định lượng để đạt độ giòn xốp mỏng nhẹ chuẩn vị. Rắc đều bột bắp và bột chiên xù mịn vào các khe khứa thân cá rồi giũ bỏ bột dư.',5,'Vắt lấy nước cốt hành tỏi sả khi ướp đồ nướng giúp hương thơm thấm sâu mà không bị cháy đen phần xác băm trên lửa cao.'),
(161,3,'Ướp thấm thớ thịt / tạo hình cuốn khéo léo','Áo đều hỗn hợp gia vị hoặc lớp bột/vỏ cuốn quanh 850g cá rô phi và 60g bột chiên xù, massage nhẹ nhàng rồi để nghỉ 15–20 phút cho gia vị thẩm thấu trọn vẹn. Trường hợp cuốn chả/nem hoặc đổ khuôn bánh, thao tác đều tay vừa chặt để nhân kết dính nhưng không bị bục rách khi gặp nhiệt.',7,'Để nguyên liệu nghỉ đủ thời gian trước khi chiên nướng giúp lớp áo bột bám chắc và phần nhân bên trong mọng ngọt.'),
(161,4,'Pha nước chấm cân vị & sơ chế rau đồ chua ăn kèm','Nhặt rửa sạch 200g rau sống ngâm nước mát cho giòn tươi, bào sợi hoặc thái lát gọn gàng bày sẵn bên cạnh. Pha chén nước chấm chua ngọt hoặc muối ớt chanh sả sánh thơm theo khẩu vị vùng miền của món Cá rô phi chiên xù giòn rụm để cân bằng độ béo giòn.',5,'Luôn chuẩn bị xong rau sống và bát nước chấm trước khi chiên/nướng mẻ cuối để món ăn vừa ra lò là thưởng thức nóng giòn ngay.');
INSERT INTO `recipe_steps` (`recipe_id`,`step_order`,`title`,`instruction`,`duration_mins`,`tip_note`) VALUES
(161,5,'Làm nóng dầu / lò nướng chuẩn nhiệt & làm chín đều lần 1','Làm nóng chảo dầu hoặc vỉ nướng/nồi chiên ở mức nhiệt vừa khoảng 165–175°C, xếp 850g cá rô phi và 60g bột chiên xù vào với khoảng cách thoáng đều nhau. Chiên hoặc nướng trở mặt nhịp nhàng trên lửa vừa để nhiệt dẫn sâu làm chín mềm ngọt hoàn toàn phần nhân bên trong. Đun nóng dầu thử đũa sủi tăm mạnh, thả cá nhẹ nhàng chiên mỗi mặt 7-8 phút đến khi vàng ruộm dựng đứng vây giòn rụm.',8,'Kiểm tra nhiệt dầu bằng đầu đũa tre thấy sủi tăm nhỏ đều là đạt chuẩn 170°C, giúp vỏ không cháy sớm khi bên trong còn sống.'),
(161,6,'Tăng nhiệt khóa giòn rụm vàng ươm bề mặt lần 2','Ở 2–3 phút cuối, tăng lên lửa vừa lớn (khoảng 190°C) hoặc phết thêm lớp dầu điều/mật ong mỏng để vỏ ngoài của Cá rô phi chiên xù giòn rụm chuyển sắc vàng óng ánh và nổ giòn rụm. Lắng nghe tiếng xèo giòn rộn rã và hương thơm phức lan tỏa khắp bếp thì gắp ra vỉ thưa cho ráo dầu thừa.',4,'Đặt đồ chiên nướng lên giá inox thoáng khí thay vì giấy thấm dầu chồng khít để hơi nước thoát hết, giữ độ giòn lâu gấp 3 lần.'),
(161,7,'Trình bày bắt mắt kèm rau thơm & thưởng thức nóng','Xếp thành phẩm vàng giòn ra đĩa lớn có bày sẵn 200g rau sống và điểm xuyết hành ngò và tiêu xay tươi xanh hài hòa màu sắc. Dọn kèm chén nước chấm sánh đậm ngay chính giữa mâm ăn cho 4 người thưởng thức khi vỏ ngoài còn nóng giòn rụm. Đặt cá lên giấy thấm dầu, bày ra đĩa cùng rau sống, bún, bánh tráng và chén nước mắm tỏi ớt chua ngọt.',3,'Cắt miếng hoặc dọn ăn ngay trong vòng 10 phút sau khi rời bếp để cảm nhận trọn vẹn sự đối lập giòn ngoài - mềm ngọt bên trong.'),
(162,1,'Sơ chế sạch & thấm thật khô bề mặt nguyên liệu','Rửa sạch 450g tôm sú và 60g bột mì cùng chút muối loãng để khử mùi tự nhiên, sau đó dùng khăn giấy bếp thấm thật khô ráo hoàn toàn bề mặt. Khứa nhẹ các đường chéo hoặc cắt miếng vừa ăn dày 2–3cm để nhiệt và gia vị thấm sâu đều khắp bên trong. Bóc vỏ bỏ đầu chừa đốt đuôi, rút chỉ đen lưng; khứa 3-4 khía nông dưới bụng tôm rồi ấn nhẹ sống lưng cho tôm thẳng đều.',5,'Bề mặt nguyên liệu càng khô ráo thì khi chiên không bị văng dầu và khi nướng sẽ lên màu vàng ruộm giòn rụm cực đẹp.'),
(162,2,'Chuẩn bị hỗn hợp sốt ướp / bột áo chuẩn tỷ lệ','Phối trộn hành tím và tỏi băm nhỏ băm thật nhuyễn (hoặc vắt lấy nước cốt thơm) cùng 3g tiêu, 4g muối và 40g tương cà trong tô lớn cho quyện sánh đồng nhất. Nếu món có lớp vỏ bột hoặc bánh cuốn từ 450g tôm sú và 60g bột mì, trộn đều hỗn hợp theo đúng định lượng để đạt độ giòn xốp mỏng nhẹ chuẩn vị. Ướp tôm với xíu muối tiêu 10 phút; chuẩn bị 3 tô riêng: bột mì, trứng đánh tan, và bột chiên xù.',4,'Vắt lấy nước cốt hành tỏi sả khi ướp đồ nướng giúp hương thơm thấm sâu mà không bị cháy đen phần xác băm trên lửa cao.'),
(162,3,'Ướp thấm thớ thịt / tạo hình cuốn khéo léo','Áo đều hỗn hợp gia vị hoặc lớp bột/vỏ cuốn quanh 450g tôm sú và 60g bột mì, massage nhẹ nhàng rồi để nghỉ 15–20 phút cho gia vị thẩm thấu trọn vẹn. Trường hợp cuốn chả/nem hoặc đổ khuôn bánh, thao tác đều tay vừa chặt để nhân kết dính nhưng không bị bục rách khi gặp nhiệt.',6,'Để nguyên liệu nghỉ đủ thời gian trước khi chiên nướng giúp lớp áo bột bám chắc và phần nhân bên trong mọng ngọt.'),
(162,4,'Pha nước chấm cân vị & sơ chế rau đồ chua ăn kèm','Nhặt rửa sạch rau củ ăn kèm ngâm nước mát cho giòn tươi, bào sợi hoặc thái lát gọn gàng bày sẵn bên cạnh. Pha chén nước chấm chua ngọt hoặc muối ớt chanh sả sánh thơm theo khẩu vị vùng miền của món Tôm chiên xù giòn tan để cân bằng độ béo giòn.',4,'Luôn chuẩn bị xong rau sống và bát nước chấm trước khi chiên/nướng mẻ cuối để món ăn vừa ra lò là thưởng thức nóng giòn ngay.'),
(162,5,'Làm nóng dầu / lò nướng chuẩn nhiệt & làm chín đều lần 1','Làm nóng chảo dầu hoặc vỉ nướng/nồi chiên ở mức nhiệt vừa khoảng 165–175°C, xếp 450g tôm sú và 60g bột mì vào với khoảng cách thoáng đều nhau. Chiên hoặc nướng trở mặt nhịp nhàng trên lửa vừa để nhiệt dẫn sâu làm chín mềm ngọt hoàn toàn phần nhân bên trong. Lần lượt lăn tôm qua lớp bột mì mỏng -> nhúng vào trứng gà -> áo kín đều bột chiên xù, ấn nhẹ tay.',6,'Kiểm tra nhiệt dầu bằng đầu đũa tre thấy sủi tăm nhỏ đều là đạt chuẩn 170°C, giúp vỏ không cháy sớm khi bên trong còn sống.'),
(162,6,'Tăng nhiệt khóa giòn rụm vàng ươm bề mặt lần 2','Ở 2–3 phút cuối, tăng lên lửa vừa lớn (khoảng 190°C) hoặc phết thêm lớp dầu điều/mật ong mỏng để vỏ ngoài của Tôm chiên xù giòn tan chuyển sắc vàng óng ánh và nổ giòn rụm. Lắng nghe tiếng xèo giòn rộn rã và hương thơm phức lan tỏa khắp bếp thì gắp ra vỉ thưa cho ráo dầu thừa.',4,'Đặt đồ chiên nướng lên giá inox thoáng khí thay vì giấy thấm dầu chồng khít để hơi nước thoát hết, giữ độ giòn lâu gấp 3 lần.'),
(162,7,'Trình bày bắt mắt kèm rau thơm & thưởng thức nóng','Xếp thành phẩm vàng giòn ra đĩa lớn có bày sẵn rau củ ăn kèm và điểm xuyết hành ngò và tiêu xay tươi xanh hài hòa màu sắc. Dọn kèm chén nước chấm sánh đậm ngay chính giữa mâm ăn cho 4 người thưởng thức khi vỏ ngoài còn nóng giòn rụm. Chiên tôm trong dầu nóng 170°C khoảng 2.5-3 phút đến khi vàng ruộm rồi vớt ra giá lưới ráo dầu.',3,'Cắt miếng hoặc dọn ăn ngay trong vòng 10 phút sau khi rời bếp để cảm nhận trọn vẹn sự đối lập giòn ngoài - mềm ngọt bên trong.'),
(163,1,'Sơ chế sạch & thấm thật khô bề mặt nguyên liệu','Rửa sạch 600g thịt ba chỉ cùng chút muối loãng để khử mùi tự nhiên, sau đó dùng khăn giấy bếp thấm thật khô ráo hoàn toàn bề mặt. Khứa nhẹ các đường chéo hoặc cắt miếng vừa ăn dày 2–3cm để nhiệt và gia vị thấm sâu đều khắp bên trong. Trộn nước mẻ lọc, nước cốt nghệ, riềng sả băm mịn, mắm tôm (hoặc nước mắm) và dầu ăn xoa đều hai mặt thịt ướp ít nhất 1 giờ.',7,'Bề mặt nguyên liệu càng khô ráo thì khi chiên không bị văng dầu và khi nướng sẽ lên màu vàng ruộm giòn rụm cực đẹp.'),
(163,2,'Chuẩn bị hỗn hợp sốt ướp / bột áo chuẩn tỷ lệ','Phối trộn 45g riềng tươi, 35g sả và 15g nghệ băm thật nhuyễn (hoặc vắt lấy nước cốt thơm) cùng 40g mẻ chua và 15g mắm tôm trong tô lớn cho quyện sánh đồng nhất. Nếu món có lớp vỏ bột hoặc bánh cuốn từ 600g thịt ba chỉ, trộn đều hỗn hợp theo đúng định lượng để đạt độ giòn xốp mỏng nhẹ chuẩn vị. Gạt bớt phần xác riềng sả dính ngoài mặt để tránh bị cháy khét sớm khi nướng.',7,'Vắt lấy nước cốt hành tỏi sả khi ướp đồ nướng giúp hương thơm thấm sâu mà không bị cháy đen phần xác băm trên lửa cao.'),
(163,3,'Ướp thấm thớ thịt / tạo hình cuốn khéo léo','Áo đều hỗn hợp gia vị hoặc lớp bột/vỏ cuốn quanh 600g thịt ba chỉ, massage nhẹ nhàng rồi để nghỉ 15–20 phút cho gia vị thẩm thấu trọn vẹn. Trường hợp cuốn chả/nem hoặc đổ khuôn bánh, thao tác đều tay vừa chặt để nhân kết dính nhưng không bị bục rách khi gặp nhiệt.',8,'Để nguyên liệu nghỉ đủ thời gian trước khi chiên nướng giúp lớp áo bột bám chắc và phần nhân bên trong mọng ngọt.'),
(163,4,'Pha nước chấm cân vị & sơ chế rau đồ chua ăn kèm','Nhặt rửa sạch rau củ ăn kèm ngâm nước mát cho giòn tươi, bào sợi hoặc thái lát gọn gàng bày sẵn bên cạnh. Pha chén nước chấm chua ngọt hoặc muối ớt chanh sả sánh thơm theo khẩu vị vùng miền của món Ba chỉ nướng riềng mẻ chuẩn vị để cân bằng độ béo giòn.',6,'Luôn chuẩn bị xong rau sống và bát nước chấm trước khi chiên/nướng mẻ cuối để món ăn vừa ra lò là thưởng thức nóng giòn ngay.'),
(163,5,'Làm nóng dầu / lò nướng chuẩn nhiệt & làm chín đều lần 1','Làm nóng chảo dầu hoặc vỉ nướng/nồi chiên ở mức nhiệt vừa khoảng 165–175°C, xếp 600g thịt ba chỉ vào với khoảng cách thoáng đều nhau. Chiên hoặc nướng trở mặt nhịp nhàng trên lửa vừa để nhiệt dẫn sâu làm chín mềm ngọt hoàn toàn phần nhân bên trong. Nướng 185°C trong 12 phút rồi lật mặt nướng tiếp 8-10 phút ở 195°C cho ba chỉ chín vàng cạnh thơm nức.',10,'Kiểm tra nhiệt dầu bằng đầu đũa tre thấy sủi tăm nhỏ đều là đạt chuẩn 170°C, giúp vỏ không cháy sớm khi bên trong còn sống.'),
(163,6,'Tăng nhiệt khóa giòn rụm vàng ươm bề mặt lần 2','Ở 2–3 phút cuối, tăng lên lửa vừa lớn (khoảng 190°C) hoặc phết thêm lớp dầu điều/mật ong mỏng để vỏ ngoài của Ba chỉ nướng riềng mẻ chuẩn vị chuyển sắc vàng óng ánh và nổ giòn rụm. Lắng nghe tiếng xèo giòn rộn rã và hương thơm phức lan tỏa khắp bếp thì gắp ra vỉ thưa cho ráo dầu thừa.',5,'Đặt đồ chiên nướng lên giá inox thoáng khí thay vì giấy thấm dầu chồng khít để hơi nước thoát hết, giữ độ giòn lâu gấp 3 lần.'),
(163,7,'Trình bày bắt mắt kèm rau thơm & thưởng thức nóng','Xếp thành phẩm vàng giòn ra đĩa lớn có bày sẵn rau củ ăn kèm và điểm xuyết hành ngò và tiêu xay tươi xanh hài hòa màu sắc. Dọn kèm chén nước chấm sánh đậm ngay chính giữa mâm ăn cho 4 người thưởng thức khi vỏ ngoài còn nóng giòn rụm. Thái lát vừa ăn, rắc thêm chút mè rang và dùng kèm bún, xà lách, dưa leo chấm mắm nêm hoặc nước mắm chua ngọt.',4,'Cắt miếng hoặc dọn ăn ngay trong vòng 10 phút sau khi rời bếp để cảm nhận trọn vẹn sự đối lập giòn ngoài - mềm ngọt bên trong.'),
(164,1,'Sơ chế sạch & thấm thật khô bề mặt nguyên liệu','Rửa sạch 700g cánh gà cùng chút muối loãng để khử mùi tự nhiên, sau đó dùng khăn giấy bếp thấm thật khô ráo hoàn toàn bề mặt. Khứa nhẹ các đường chéo hoặc cắt miếng vừa ăn dày 2–3cm để nhiệt và gia vị thấm sâu đều khắp bên trong. Bóp cánh gà với muối gừng rửa sạch, thấm thật khô rồi khứa 2 đường mặt dưới giúp gia vị ngấm nhanh.',6,'Bề mặt nguyên liệu càng khô ráo thì khi chiên không bị văng dầu và khi nướng sẽ lên màu vàng ruộm giòn rụm cực đẹp.'),
(164,2,'Chuẩn bị hỗn hợp sốt ướp / bột áo chuẩn tỷ lệ','Phối trộn 20g tỏi và 20g hành tím băm thật nhuyễn (hoặc vắt lấy nước cốt thơm) cùng 15g tiêu, 30ml dầu hào, 25ml nước tương và 20g mật ong trong tô lớn cho quyện sánh đồng nhất. Nếu món có lớp vỏ bột hoặc bánh cuốn từ 700g cánh gà, trộn đều hỗn hợp theo đúng định lượng để đạt độ giòn xốp mỏng nhẹ chuẩn vị. Trộn tỏi hành băm, dầu hào, nước tương, đường/mật ong, dầu ăn và 2/3 tiêu đen đập dập ướp cánh gà 30 phút.',6,'Vắt lấy nước cốt hành tỏi sả khi ướp đồ nướng giúp hương thơm thấm sâu mà không bị cháy đen phần xác băm trên lửa cao.'),
(164,3,'Ướp thấm thớ thịt / tạo hình cuốn khéo léo','Áo đều hỗn hợp gia vị hoặc lớp bột/vỏ cuốn quanh 700g cánh gà, massage nhẹ nhàng rồi để nghỉ 15–20 phút cho gia vị thẩm thấu trọn vẹn. Trường hợp cuốn chả/nem hoặc đổ khuôn bánh, thao tác đều tay vừa chặt để nhân kết dính nhưng không bị bục rách khi gặp nhiệt.',8,'Để nguyên liệu nghỉ đủ thời gian trước khi chiên nướng giúp lớp áo bột bám chắc và phần nhân bên trong mọng ngọt.'),
(164,4,'Pha nước chấm cân vị & sơ chế rau đồ chua ăn kèm','Nhặt rửa sạch rau củ ăn kèm ngâm nước mát cho giòn tươi, bào sợi hoặc thái lát gọn gàng bày sẵn bên cạnh. Pha chén nước chấm chua ngọt hoặc muối ớt chanh sả sánh thơm theo khẩu vị vùng miền của món Cánh gà nướng sốt tiêu đen để cân bằng độ béo giòn.',5,'Luôn chuẩn bị xong rau sống và bát nước chấm trước khi chiên/nướng mẻ cuối để món ăn vừa ra lò là thưởng thức nóng giòn ngay.'),
(164,5,'Làm nóng dầu / lò nướng chuẩn nhiệt & làm chín đều lần 1','Làm nóng chảo dầu hoặc vỉ nướng/nồi chiên ở mức nhiệt vừa khoảng 165–175°C, xếp 700g cánh gà vào với khoảng cách thoáng đều nhau. Chiên hoặc nướng trở mặt nhịp nhàng trên lửa vừa để nhiệt dẫn sâu làm chín mềm ngọt hoàn toàn phần nhân bên trong. Nướng ở 180°C trong 12 phút, lật mặt rồi quét thêm nước sốt ướp nướng tiếp 8-10 phút ở 195°C.',9,'Kiểm tra nhiệt dầu bằng đầu đũa tre thấy sủi tăm nhỏ đều là đạt chuẩn 170°C, giúp vỏ không cháy sớm khi bên trong còn sống.'),
(164,6,'Tăng nhiệt khóa giòn rụm vàng ươm bề mặt lần 2','Ở 2–3 phút cuối, tăng lên lửa vừa lớn (khoảng 190°C) hoặc phết thêm lớp dầu điều/mật ong mỏng để vỏ ngoài của Cánh gà nướng sốt tiêu đen chuyển sắc vàng óng ánh và nổ giòn rụm. Lắng nghe tiếng xèo giòn rộn rã và hương thơm phức lan tỏa khắp bếp thì gắp ra vỉ thưa cho ráo dầu thừa.',5,'Đặt đồ chiên nướng lên giá inox thoáng khí thay vì giấy thấm dầu chồng khít để hơi nước thoát hết, giữ độ giòn lâu gấp 3 lần.'),
(164,7,'Trình bày bắt mắt kèm rau thơm & thưởng thức nóng','Xếp thành phẩm vàng giòn ra đĩa lớn có bày sẵn rau củ ăn kèm và điểm xuyết hành ngò và tiêu xay tươi xanh hài hòa màu sắc. Dọn kèm chén nước chấm sánh đậm ngay chính giữa mâm ăn cho 4 người thưởng thức khi vỏ ngoài còn nóng giòn rụm. Xếp cánh gà ra đĩa lót xà lách, rắc nốt phần tiêu đen thơm và dùng nóng.',3,'Cắt miếng hoặc dọn ăn ngay trong vòng 10 phút sau khi rời bếp để cảm nhận trọn vẹn sự đối lập giòn ngoài - mềm ngọt bên trong.'),
(165,1,'Sơ chế sạch & thấm thật khô bề mặt nguyên liệu','Rửa sạch 600g bạch tuộc cùng chút muối loãng để khử mùi tự nhiên, sau đó dùng khăn giấy bếp thấm thật khô ráo hoàn toàn bề mặt. Khứa nhẹ các đường chéo hoặc cắt miếng vừa ăn dày 2–3cm để nhiệt và gia vị thấm sâu đều khắp bên trong. Làm sạch túi mực răng bạch tuộc với muối chanh; nhúng nhanh vào nước sôi gừng 30 giây giúp râu cuộn đẹp và không ra nước lúc nướng.',5,'Bề mặt nguyên liệu càng khô ráo thì khi chiên không bị văng dầu và khi nướng sẽ lên màu vàng ruộm giòn rụm cực đẹp.');
INSERT INTO `recipe_steps` (`recipe_id`,`step_order`,`title`,`instruction`,`duration_mins`,`tip_note`) VALUES
(165,2,'Chuẩn bị hỗn hợp sốt ướp / bột áo chuẩn tỷ lệ','Phối trộn 30g sả và 20g tỏi băm thật nhuyễn (hoặc vắt lấy nước cốt thơm) cùng 25g sa tế, 20g ớt, 35ml chanh và 6g muối trong tô lớn cho quyện sánh đồng nhất. Nếu món có lớp vỏ bột hoặc bánh cuốn từ 600g bạch tuộc, trộn đều hỗn hợp theo đúng định lượng để đạt độ giòn xốp mỏng nhẹ chuẩn vị. Ướp bạch tuộc với sa tế, tỏi sả băm và dầu ăn 15 phút (phết ít nước tương cho lên màu đỏ cánh gián).',5,'Vắt lấy nước cốt hành tỏi sả khi ướp đồ nướng giúp hương thơm thấm sâu mà không bị cháy đen phần xác băm trên lửa cao.'),
(165,3,'Ướp thấm thớ thịt / tạo hình cuốn khéo léo','Áo đều hỗn hợp gia vị hoặc lớp bột/vỏ cuốn quanh 600g bạch tuộc, massage nhẹ nhàng rồi để nghỉ 15–20 phút cho gia vị thẩm thấu trọn vẹn. Trường hợp cuốn chả/nem hoặc đổ khuôn bánh, thao tác đều tay vừa chặt để nhân kết dính nhưng không bị bục rách khi gặp nhiệt.',6,'Để nguyên liệu nghỉ đủ thời gian trước khi chiên nướng giúp lớp áo bột bám chắc và phần nhân bên trong mọng ngọt.'),
(165,4,'Pha nước chấm cân vị & sơ chế rau đồ chua ăn kèm','Nhặt rửa sạch rau củ ăn kèm ngâm nước mát cho giòn tươi, bào sợi hoặc thái lát gọn gàng bày sẵn bên cạnh. Pha chén nước chấm chua ngọt hoặc muối ớt chanh sả sánh thơm theo khẩu vị vùng miền của món Bạch tuộc nướng muối ớt xanh để cân bằng độ béo giòn.',4,'Luôn chuẩn bị xong rau sống và bát nước chấm trước khi chiên/nướng mẻ cuối để món ăn vừa ra lò là thưởng thức nóng giòn ngay.'),
(165,5,'Làm nóng dầu / lò nướng chuẩn nhiệt & làm chín đều lần 1','Làm nóng chảo dầu hoặc vỉ nướng/nồi chiên ở mức nhiệt vừa khoảng 165–175°C, xếp 600g bạch tuộc vào với khoảng cách thoáng đều nhau. Chiên hoặc nướng trở mặt nhịp nhàng trên lửa vừa để nhiệt dẫn sâu làm chín mềm ngọt hoàn toàn phần nhân bên trong. Xay nhuyễn ớt xiêm xanh, muối, đường, sữa đặc, lá chanh non và nước cốt chanh thành sốt sánh xanh ngọc.',7,'Kiểm tra nhiệt dầu bằng đầu đũa tre thấy sủi tăm nhỏ đều là đạt chuẩn 170°C, giúp vỏ không cháy sớm khi bên trong còn sống.'),
(165,6,'Tăng nhiệt khóa giòn rụm vàng ươm bề mặt lần 2','Ở 2–3 phút cuối, tăng lên lửa vừa lớn (khoảng 190°C) hoặc phết thêm lớp dầu điều/mật ong mỏng để vỏ ngoài của Bạch tuộc nướng muối ớt xanh chuyển sắc vàng óng ánh và nổ giòn rụm. Lắng nghe tiếng xèo giòn rộn rã và hương thơm phức lan tỏa khắp bếp thì gắp ra vỉ thưa cho ráo dầu thừa.',4,'Đặt đồ chiên nướng lên giá inox thoáng khí thay vì giấy thấm dầu chồng khít để hơi nước thoát hết, giữ độ giòn lâu gấp 3 lần.'),
(165,7,'Trình bày bắt mắt kèm rau thơm & thưởng thức nóng','Xếp thành phẩm vàng giòn ra đĩa lớn có bày sẵn rau củ ăn kèm và điểm xuyết hành ngò và tiêu xay tươi xanh hài hòa màu sắc. Dọn kèm chén nước chấm sánh đậm ngay chính giữa mâm ăn cho 4 người thưởng thức khi vỏ ngoài còn nóng giòn rụm. Nướng bạch tuộc ở 200°C trong 8-10 phút (hoặc trên than hoa trở đều tay) đến khi se mặt thơm phức, cắt khúc chấm muối ớt xanh.',3,'Cắt miếng hoặc dọn ăn ngay trong vòng 10 phút sau khi rời bếp để cảm nhận trọn vẹn sự đối lập giòn ngoài - mềm ngọt bên trong.'),
(166,1,'Sơ chế sạch & thấm thật khô bề mặt nguyên liệu','Rửa sạch 600g chim cút cùng chút muối loãng để khử mùi tự nhiên, sau đó dùng khăn giấy bếp thấm thật khô ráo hoàn toàn bề mặt. Khứa nhẹ các đường chéo hoặc cắt miếng vừa ăn dày 2–3cm để nhiệt và gia vị thấm sâu đều khắp bên trong. Rửa sạch chim cút bằng muối gừng; chần hoặc rim sơ chim cút trong 200ml nước dừa tươi cùng chút ngũ vị hương và nước tương 10 phút rồi vớt ráo.',8,'Bề mặt nguyên liệu càng khô ráo thì khi chiên không bị văng dầu và khi nướng sẽ lên màu vàng ruộm giòn rụm cực đẹp.'),
(166,2,'Chuẩn bị hỗn hợp sốt ướp / bột áo chuẩn tỷ lệ','Phối trộn 30g tỏi băm thật nhuyễn (hoặc vắt lấy nước cốt thơm) cùng 5g ngũ vị hương, 25g mật ong và 25ml nước tương trong tô lớn cho quyện sánh đồng nhất. Nếu món có lớp vỏ bột hoặc bánh cuốn từ 600g chim cút, trộn đều hỗn hợp theo đúng định lượng để đạt độ giòn xốp mỏng nhẹ chuẩn vị. Để chim cút nguội bớt thấm khô, phết lớp mật ong pha nước chanh loãng lên mặt da để da giòn bóng.',7,'Vắt lấy nước cốt hành tỏi sả khi ướp đồ nướng giúp hương thơm thấm sâu mà không bị cháy đen phần xác băm trên lửa cao.'),
(166,3,'Ướp thấm thớ thịt / tạo hình cuốn khéo léo','Áo đều hỗn hợp gia vị hoặc lớp bột/vỏ cuốn quanh 600g chim cút, massage nhẹ nhàng rồi để nghỉ 15–20 phút cho gia vị thẩm thấu trọn vẹn. Trường hợp cuốn chả/nem hoặc đổ khuôn bánh, thao tác đều tay vừa chặt để nhân kết dính nhưng không bị bục rách khi gặp nhiệt.',9,'Để nguyên liệu nghỉ đủ thời gian trước khi chiên nướng giúp lớp áo bột bám chắc và phần nhân bên trong mọng ngọt.'),
(166,4,'Pha nước chấm cân vị & sơ chế rau đồ chua ăn kèm','Nhặt rửa sạch rau củ ăn kèm ngâm nước mát cho giòn tươi, bào sợi hoặc thái lát gọn gàng bày sẵn bên cạnh. Pha chén nước chấm chua ngọt hoặc muối ớt chanh sả sánh thơm theo khẩu vị vùng miền của món Chim cút quay bơ tỏi giòn da để cân bằng độ béo giòn.',6,'Luôn chuẩn bị xong rau sống và bát nước chấm trước khi chiên/nướng mẻ cuối để món ăn vừa ra lò là thưởng thức nóng giòn ngay.'),
(166,5,'Làm nóng dầu / lò nướng chuẩn nhiệt & làm chín đều lần 1','Làm nóng chảo dầu hoặc vỉ nướng/nồi chiên ở mức nhiệt vừa khoảng 165–175°C, xếp 600g chim cút vào với khoảng cách thoáng đều nhau. Chiên hoặc nướng trở mặt nhịp nhàng trên lửa vừa để nhiệt dẫn sâu làm chín mềm ngọt hoàn toàn phần nhân bên trong. Chiên dầu sôi vừa 5 phút (hoặc nướng nồi chiên 195°C trong 12 phút) đến khi chim cút vàng rụm.',10,'Kiểm tra nhiệt dầu bằng đầu đũa tre thấy sủi tăm nhỏ đều là đạt chuẩn 170°C, giúp vỏ không cháy sớm khi bên trong còn sống.'),
(166,6,'Tăng nhiệt khóa giòn rụm vàng ươm bề mặt lần 2','Ở 2–3 phút cuối, tăng lên lửa vừa lớn (khoảng 190°C) hoặc phết thêm lớp dầu điều/mật ong mỏng để vỏ ngoài của Chim cút quay bơ tỏi giòn da chuyển sắc vàng óng ánh và nổ giòn rụm. Lắng nghe tiếng xèo giòn rộn rã và hương thơm phức lan tỏa khắp bếp thì gắp ra vỉ thưa cho ráo dầu thừa.',6,'Đặt đồ chiên nướng lên giá inox thoáng khí thay vì giấy thấm dầu chồng khít để hơi nước thoát hết, giữ độ giòn lâu gấp 3 lần.'),
(166,7,'Trình bày bắt mắt kèm rau thơm & thưởng thức nóng','Xếp thành phẩm vàng giòn ra đĩa lớn có bày sẵn rau củ ăn kèm và điểm xuyết hành ngò và tiêu xay tươi xanh hài hòa màu sắc. Dọn kèm chén nước chấm sánh đậm ngay chính giữa mâm ăn cho 4 người thưởng thức khi vỏ ngoài còn nóng giòn rụm. Làm chảy bơ lạt với tỏi phi thơm, cho chim cút vào đảo nhanh tay 30 giây cho áo đều hương bơ tỏi; dùng nóng kèm muối tiêu chanh.',4,'Cắt miếng hoặc dọn ăn ngay trong vòng 10 phút sau khi rời bếp để cảm nhận trọn vẹn sự đối lập giòn ngoài - mềm ngọt bên trong.'),
(167,1,'Sơ chế sạch & chuẩn bị nguyên liệu thuần chay','Rửa sạch toàn bộ nguyên liệu dưới vòi nước mát, để ráo tự nhiên trên rổ thưa gồm 600g bánh phở tươi và 35g nấm hương cùng 150g bắp ngọt. Cắt thái đồng đều kích thước khoảng 3–4cm vừa gắp để khi chế biến chín cùng lúc và thấm đều gia vị thực vật. Nướng sơ 1 củ gừng, rang thơm hoa hồi và quế thanh; nấu 1.8 lít nước cùng cà rốt, bắp ngọt, chân nấm hương trong 35 phút rồi vớt bã lọc lấy nước trong.',10,'Thấm khô bề mặt đậu hũ và nấm bằng khăn giấy bếp trước khi chế biến giúp nguyên liệu săn chắc, không bị bắn dầu hay ra nước.'),
(167,2,'Xử lý độ giòn ngọt của nấm & rau củ','Đối với nhóm nấm và rau củ (150g bắp ngọt), ngâm nhanh qua nước muối loãng 3 phút rồi vắt nhẹ hoặc chần sơ 45 giây trong nước sôi, vớt ngay ra tô nước mát. Thao tác này giúp giữ trọn sắc màu tươi sáng tự nhiên, loại bỏ mùi ngái và tạo độ giòn ngọt thanh khiết cho món Phở chay nấm hương thanh ngọt.',8,'Không ngâm nấm quá lâu trong nước lạnh vì nấm sẽ hút nước mạnh làm nhạt vị ngọt umami tự nhiên.'),
(167,3,'Pha chén sốt gia vị chay chuẩn định lượng','Chuẩn bị tô nhỏ, đong chính xác 30ml nước tương và 18g hạt nêm nấm hương khuấy đều cùng 30ml nước ấm hoặc nước ngâm nấm hương cho tan hoàn toàn đường và hạt nêm nấm. Nếm thử thấy vị mặn ngọt hài hòa, thanh dịu đúng tinh thần ẩm thực chay cho khẩu phần 4 người. Áp chảo nấm đùi gà cắt lát mỏng với chút dầu và nước tương cho cháy cạnh thơm; chiên đậu hũ vàng giòn cắt lát.',6,'Pha sẵn chén sốt trước khi bật bếp giúp kiểm soát chính xác định lượng từng gam và không bị cháy khét gia vị trên chảo nóng.'),
(167,4,'Phi thơm hành boaro & tạo nền hương thảo mộc','Làm nóng nồi hoặc chảo đáy dày trên lửa vừa, cho 15ml dầu thực vật vào láng đều mặt chảo rồi trút 45g hành boaro và 5g hoa hồi vào phi thơm. Đảo nhẹ tay khoảng 1–2 phút đến khi hành boaro chuyển sắc vàng óng và dậy mùi thơm dịu thì hạ lửa vừa.',8,'Hành boaro cháy nhanh hơn hành tím nên chỉ phi trên lửa vừa đến khi vừa chớm vàng thơm là cho nguyên liệu chính vào ngay.'),
(167,5,'Chế biến săn thấm nguyên liệu chính thuần thực vật','Cho 600g bánh phở tươi và 35g nấm hương vào đảo đều hoặc áp chảo nhẹ hai mặt trên lửa vừa đến khi bề mặt săn vàng, sau đó rưới 2/3 chén sốt gia vị chay đã pha vào. Đảo nhẹ tay để sốt bám đều quanh từng thớ đậu và nấm mà không làm vỡ nát cấu trúc nguyên liệu. Nêm nước dùng chay bằng hạt nêm nấm hương, nước tương và nhúm muối hầm cho thanh dịu.',15,'Dùng sạn gỗ đảo nhẹ từ dưới đáy chảo hất lên để miếng đậu hũ và nấm giữ nguyên hình khối vuông vắn đẹp mắt.'),
(167,6,'Phối hợp rau củ & cân chỉnh độ sánh thanh đạm','Tiếp tục cho 150g bắp ngọt cùng phần sốt còn lại vào nồi, điều chỉnh lửa vừa nấu thêm cho nguyên liệu chín mềm tới nhưng vẫn giữ độ giòn ngọt. Quan sát thấy nước sốt chuyển màu nâu hổ phách sóng sánh hoặc nước dùng trong thanh, hương thơm quyện đều khắp gian bếp. Trụng bánh phở, xếp nấm hương, nấm đùi gà, đậu hũ, hành boaro thái mỏng, ngò gai húng quế rồi chan nước dùng sôi ngập tô.',12,'Chỉ nấu rau củ xanh vừa chín tới để bảo toàn tối đa lượng chất xơ và vitamin tự nhiên trong khẩu phần chay.'),
(167,7,'Hoàn thiện hương thơm & trình bày món chay thanh tịnh','Tắt bếp ngay khi món ăn đạt độ chín chuẩn, rắc đều hành boaro lá xanh và tiêu xay lên bề mặt để dậy mùi thơm tươi mới. Múc món Phở chay nấm hương thanh ngọt ra đĩa sứ hoặc tô sâu lòng, thưởng thức nóng cùng cơm trắng hoặc bún tươi cho trọn vẹn 4 khẩu phần.',6,'Rắc rau thơm và tiêu ngay lúc vừa tắt bếp giúp tinh dầu tỏa hương thơm ngát mà lá rau không bị thâm xỉn màu.'),
(168,1,'Sơ chế sạch & chuẩn bị nguyên liệu thuần chay','Rửa sạch toàn bộ nguyên liệu dưới vòi nước mát, để ráo tự nhiên trên rổ thưa gồm 600g bún tươi và 200g đậu hũ cùng 150g dứa. Cắt thái đồng đều kích thước khoảng 3–4cm vừa gắp để khi chế biến chín cùng lúc và thấm đều gia vị thực vật. Ninh 1.8 lít nước với dứa, cà rốt, nấm hương và 3 cây sả đập dập trong 30 phút cho thơm ngọt.',9,'Thấm khô bề mặt đậu hũ và nấm bằng khăn giấy bếp trước khi chế biến giúp nguyên liệu săn chắc, không bị bắn dầu hay ra nước.'),
(168,2,'Xử lý độ giòn ngọt của nấm & rau củ','Đối với nhóm nấm và rau củ (150g dứa), ngâm nhanh qua nước muối loãng 3 phút rồi vắt nhẹ hoặc chần sơ 45 giây trong nước sôi, vớt ngay ra tô nước mát. Thao tác này giúp giữ trọn sắc màu tươi sáng tự nhiên, loại bỏ mùi ngái và tạo độ giòn ngọt thanh khiết cho món Bún bò Huế chay đậm đà.',8,'Không ngâm nấm quá lâu trong nước lạnh vì nấm sẽ hút nước mạnh làm nhạt vị ngọt umami tự nhiên.'),
(168,3,'Pha chén sốt gia vị chay chuẩn định lượng','Chuẩn bị tô nhỏ, đong chính xác 30ml nước tương, 20g sa tế và 20g hạt nêm nấm hương khuấy đều cùng 30ml nước ấm hoặc nước ngâm nấm hương cho tan hoàn toàn đường và hạt nêm nấm. Nếm thử thấy vị mặn ngọt hài hòa, thanh dịu đúng tinh thần ẩm thực chay cho khẩu phần 4 người. Phi thơm hành boaro và sả băm với dầu ăn (thêm chút dầu điều/sa tế chay), cho nấm đùi gà vào đảo săn với nước tương.',6,'Pha sẵn chén sốt trước khi bật bếp giúp kiểm soát chính xác định lượng từng gam và không bị cháy khét gia vị trên chảo nóng.'),
(168,4,'Phi thơm hành boaro & tạo nền hương thảo mộc','Làm nóng nồi hoặc chảo đáy dày trên lửa vừa, cho 15ml dầu thực vật vào láng đều mặt chảo rồi trút 70g sả và 40g hành boaro vào phi thơm. Đảo nhẹ tay khoảng 1–2 phút đến khi hành boaro chuyển sắc vàng óng và dậy mùi thơm dịu thì hạ lửa vừa.',7,'Hành boaro cháy nhanh hơn hành tím nên chỉ phi trên lửa vừa đến khi vừa chớm vàng thơm là cho nguyên liệu chính vào ngay.'),
(168,5,'Chế biến săn thấm nguyên liệu chính thuần thực vật','Cho 600g bún tươi và 200g đậu hũ vào đảo đều hoặc áp chảo nhẹ hai mặt trên lửa vừa đến khi bề mặt săn vàng, sau đó rưới 2/3 chén sốt gia vị chay đã pha vào. Đảo nhẹ tay để sốt bám đều quanh từng thớ đậu và nấm mà không làm vỡ nát cấu trúc nguyên liệu. Thả nấm xào và đậu hũ chiên vào nồi nước dùng, nêm hạt nêm nấm hương, chút tương bần/nước tương và đường phèn.',13,'Dùng sạn gỗ đảo nhẹ từ dưới đáy chảo hất lên để miếng đậu hũ và nấm giữ nguyên hình khối vuông vắn đẹp mắt.');
INSERT INTO `recipe_steps` (`recipe_id`,`step_order`,`title`,`instruction`,`duration_mins`,`tip_note`) VALUES
(168,6,'Phối hợp rau củ & cân chỉnh độ sánh thanh đạm','Tiếp tục cho 150g dứa cùng phần sốt còn lại vào nồi, điều chỉnh lửa vừa nấu thêm cho nguyên liệu chín mềm tới nhưng vẫn giữ độ giòn ngọt. Quan sát thấy nước sốt chuyển màu nâu hổ phách sóng sánh hoặc nước dùng trong thanh, hương thơm quyện đều khắp gian bếp. Trụng bún sợi to, xếp chả lụa chay, nấm, đậu hũ, rắc hành boaro ngò gai rồi chan nước dùng sôi; ăn kèm rau sống giá đỗ.',11,'Chỉ nấu rau củ xanh vừa chín tới để bảo toàn tối đa lượng chất xơ và vitamin tự nhiên trong khẩu phần chay.'),
(168,7,'Hoàn thiện hương thơm & trình bày món chay thanh tịnh','Tắt bếp ngay khi món ăn đạt độ chín chuẩn, rắc đều hành boaro lá xanh và tiêu xay lên bề mặt để dậy mùi thơm tươi mới. Múc món Bún bò Huế chay đậm đà ra đĩa sứ hoặc tô sâu lòng, thưởng thức nóng cùng cơm trắng hoặc bún tươi cho trọn vẹn 4 khẩu phần.',6,'Rắc rau thơm và tiêu ngay lúc vừa tắt bếp giúp tinh dầu tỏa hương thơm ngát mà lá rau không bị thâm xỉn màu.'),
(169,1,'Sơ chế sạch & chuẩn bị nguyên liệu thuần chay','Rửa sạch toàn bộ nguyên liệu dưới vòi nước mát, để ráo tự nhiên trên rổ thưa gồm 180g nấm đùi gà và 150g nấm kim châm cùng 80g tàu hũ ky, 200g bắp ngọt và 250g cải thìa. Cắt thái đồng đều kích thước khoảng 3–4cm vừa gắp để khi chế biến chín cùng lúc và thấm đều gia vị thực vật. Đun 1.8 lít nước với bắp ngọt cắt khoanh, cà rốt, táo đỏ khô, kỷ tử và chân nấm hương trong 25 phút cho ngọt nước tự nhiên.',8,'Thấm khô bề mặt đậu hũ và nấm bằng khăn giấy bếp trước khi chế biến giúp nguyên liệu săn chắc, không bị bắn dầu hay ra nước.'),
(169,2,'Xử lý độ giòn ngọt của nấm & rau củ','Đối với nhóm nấm và rau củ (80g tàu hũ ky, 200g bắp ngọt và 250g cải thìa), ngâm nhanh qua nước muối loãng 3 phút rồi vắt nhẹ hoặc chần sơ 45 giây trong nước sôi, vớt ngay ra tô nước mát. Thao tác này giúp giữ trọn sắc màu tươi sáng tự nhiên, loại bỏ mùi ngái và tạo độ giòn ngọt thanh khiết cho món Lẩu nấm chay thập cẩm thanh ngọt.',7,'Không ngâm nấm quá lâu trong nước lạnh vì nấm sẽ hút nước mạnh làm nhạt vị ngọt umami tự nhiên.'),
(169,3,'Pha chén sốt gia vị chay chuẩn định lượng','Chuẩn bị tô nhỏ, đong chính xác 22g hạt nêm nấm hương khuấy đều cùng 30ml nước ấm hoặc nước ngâm nấm hương cho tan hoàn toàn đường và hạt nêm nấm. Nếm thử thấy vị mặn ngọt hài hòa, thanh dịu đúng tinh thần ẩm thực chay cho khẩu phần 4 người. Rửa nhanh nấm đùi gà, nấm rơm, nấm kim châm, cải thìa rồi bày gọn ra đĩa lớn cùng đậu hũ non và tàu hũ ky.',6,'Pha sẵn chén sốt trước khi bật bếp giúp kiểm soát chính xác định lượng từng gam và không bị cháy khét gia vị trên chảo nóng.'),
(169,4,'Phi thơm hành boaro & tạo nền hương thảo mộc','Làm nóng nồi hoặc chảo đáy dày trên lửa vừa, cho 15ml dầu thực vật vào láng đều mặt chảo rồi trút 20g hành boaro thái lát mỏng vào phi thơm. Đảo nhẹ tay khoảng 1–2 phút đến khi hành boaro chuyển sắc vàng óng và dậy mùi thơm dịu thì hạ lửa vừa.',7,'Hành boaro cháy nhanh hơn hành tím nên chỉ phi trên lửa vừa đến khi vừa chớm vàng thơm là cho nguyên liệu chính vào ngay.'),
(169,5,'Chế biến săn thấm nguyên liệu chính thuần thực vật','Cho 180g nấm đùi gà và 150g nấm kim châm vào đảo đều hoặc áp chảo nhẹ hai mặt trên lửa vừa đến khi bề mặt săn vàng, sau đó rưới 2/3 chén sốt gia vị chay đã pha vào. Đảo nhẹ tay để sốt bám đều quanh từng thớ đậu và nấm mà không làm vỡ nát cấu trúc nguyên liệu. Nêm nước lẩu với hạt nêm nấm hương, muối hầm và 1 thìa nước tương cho vị thanh ngọt nhẹ.',11,'Dùng sạn gỗ đảo nhẹ từ dưới đáy chảo hất lên để miếng đậu hũ và nấm giữ nguyên hình khối vuông vắn đẹp mắt.'),
(169,6,'Phối hợp rau củ & cân chỉnh độ sánh thanh đạm','Tiếp tục cho 80g tàu hũ ky, 200g bắp ngọt và 250g cải thìa cùng phần sốt còn lại vào nồi, điều chỉnh lửa vừa nấu thêm cho nguyên liệu chín mềm tới nhưng vẫn giữ độ giòn ngọt. Quan sát thấy nước sốt chuyển màu nâu hổ phách sóng sánh hoặc nước dùng trong thanh, hương thơm quyện đều khắp gian bếp. Thả bắp, nấm đùi gà vào trước rồi nhúng nấm kim châm, đậu hũ non và cải thìa ăn kèm mì hoặc bún tươi.',10,'Chỉ nấu rau củ xanh vừa chín tới để bảo toàn tối đa lượng chất xơ và vitamin tự nhiên trong khẩu phần chay.'),
(169,7,'Hoàn thiện hương thơm & trình bày món chay thanh tịnh','Tắt bếp ngay khi món ăn đạt độ chín chuẩn, rắc đều hành boaro lá xanh và tiêu xay lên bề mặt để dậy mùi thơm tươi mới. Múc món Lẩu nấm chay thập cẩm thanh ngọt ra đĩa sứ hoặc tô sâu lòng, thưởng thức nóng cùng cơm trắng hoặc bún tươi cho trọn vẹn 4 khẩu phần.',6,'Rắc rau thơm và tiêu ngay lúc vừa tắt bếp giúp tinh dầu tỏa hương thơm ngát mà lá rau không bị thâm xỉn màu.'),
(170,1,'Sơ chế sạch & chuẩn bị nguyên liệu thuần chay','Rửa sạch toàn bộ nguyên liệu dưới vòi nước mát, để ráo tự nhiên trên rổ thưa gồm 400g đậu hũ non và 250g cam cùng 70g bột chiên xù và 45g bột năng. Cắt thái đồng đều kích thước khoảng 3–4cm vừa gắp để khi chế biến chín cùng lúc và thấm đều gia vị thực vật. Dùng khăn giấy thấm nhẹ mặt đậu hũ non cắt miếng, nhúng qua hỗn hợp bột năng pha sệt với nước lọc rồi lăn bột chiên xù.',4,'Thấm khô bề mặt đậu hũ và nấm bằng khăn giấy bếp trước khi chế biến giúp nguyên liệu săn chắc, không bị bắn dầu hay ra nước.'),
(170,2,'Xử lý độ giòn ngọt của nấm & rau củ','Đối với nhóm nấm và rau củ (400g đậu hũ non và 250g cam), ngâm nhanh qua nước muối loãng 3 phút rồi vắt nhẹ hoặc chần sơ 45 giây trong nước sôi, vớt ngay ra tô nước mát. Thao tác này giúp giữ trọn sắc màu tươi sáng tự nhiên, loại bỏ mùi ngái và tạo độ giòn ngọt thanh khiết cho món Đậu hũ non chiên xù sốt cam tươi.',4,'Không ngâm nấm quá lâu trong nước lạnh vì nấm sẽ hút nước mạnh làm nhạt vị ngọt umami tự nhiên.'),
(170,3,'Pha chén sốt gia vị chay chuẩn định lượng','Chuẩn bị tô nhỏ, đong chính xác 15ml nước tương và 18g đường thốt nốt khuấy đều cùng 30ml nước ấm hoặc nước ngâm nấm hương cho tan hoàn toàn đường và hạt nêm nấm. Nếm thử thấy vị mặn ngọt hài hòa, thanh dịu đúng tinh thần ẩm thực chay cho khẩu phần 4 người. Chiên đậu ở dầu nóng vừa khoảng 3 phút cho lớp vỏ xù phồng vàng giòn nhẹ rồi vớt ra giấy thấm dầu.',3,'Pha sẵn chén sốt trước khi bật bếp giúp kiểm soát chính xác định lượng từng gam và không bị cháy khét gia vị trên chảo nóng.'),
(170,4,'Phi thơm hành boaro & tạo nền hương thảo mộc','Làm nóng nồi hoặc chảo đáy dày trên lửa vừa, cho 60ml dầu ăn vào láng đều mặt chảo rồi trút 15g hành boaro vào phi thơm. Đảo nhẹ tay khoảng 1–2 phút đến khi hành boaro chuyển sắc vàng óng và dậy mùi thơm dịu thì hạ lửa vừa.',3,'Hành boaro cháy nhanh hơn hành tím nên chỉ phi trên lửa vừa đến khi vừa chớm vàng thơm là cho nguyên liệu chính vào ngay.'),
(170,5,'Chế biến săn thấm nguyên liệu chính thuần thực vật','Cho 400g đậu hũ non và 250g cam vào đảo đều hoặc áp chảo nhẹ hai mặt trên lửa vừa đến khi bề mặt săn vàng, sau đó rưới 2/3 chén sốt gia vị chay đã pha vào. Đảo nhẹ tay để sốt bám đều quanh từng thớ đậu và nấm mà không làm vỡ nát cấu trúc nguyên liệu. Phi chút boaro cho thơm, đổ nước cam tươi, nước tương, đường và bột năng pha loãng vào khuấy nhỏ lửa 3 phút cho sốt sánh mượt.',5,'Dùng sạn gỗ đảo nhẹ từ dưới đáy chảo hất lên để miếng đậu hũ và nấm giữ nguyên hình khối vuông vắn đẹp mắt.'),
(170,6,'Phối hợp rau củ & cân chỉnh độ sánh thanh đạm','Tiếp tục cho 70g bột chiên xù và 45g bột năng cùng phần sốt còn lại vào nồi, điều chỉnh lửa vừa nấu thêm cho nguyên liệu chín mềm tới nhưng vẫn giữ độ giòn ngọt. Quan sát thấy nước sốt chuyển màu nâu hổ phách sóng sánh hoặc nước dùng trong thanh, hương thơm quyện đều khắp gian bếp. Xếp đậu hũ chiên xù ra đĩa, chan sốt cam sánh óng lên trên hoặc để chấm kèm nhằm giữ vỏ giòn.',5,'Chỉ nấu rau củ xanh vừa chín tới để bảo toàn tối đa lượng chất xơ và vitamin tự nhiên trong khẩu phần chay.'),
(170,7,'Hoàn thiện hương thơm & trình bày món chay thanh tịnh','Tắt bếp ngay khi món ăn đạt độ chín chuẩn, rắc đều hành boaro lá xanh và tiêu xay lên bề mặt để dậy mùi thơm tươi mới. Múc món Đậu hũ non chiên xù sốt cam tươi ra đĩa sứ hoặc tô sâu lòng, thưởng thức nóng cùng cơm trắng hoặc bún tươi cho trọn vẹn 4 khẩu phần.',3,'Rắc rau thơm và tiêu ngay lúc vừa tắt bếp giúp tinh dầu tỏa hương thơm ngát mà lá rau không bị thâm xỉn màu.'),
(171,1,'Sơ chế sạch & chuẩn bị nguyên liệu thuần chay','Rửa sạch toàn bộ nguyên liệu dưới vòi nước mát, để ráo tự nhiên trên rổ thưa gồm 400g bí đỏ và 150g hạt sen tươi cùng 20g nấm hương. Cắt thái đồng đều kích thước khoảng 3–4cm vừa gắp để khi chế biến chín cùng lúc và thấm đều gia vị thực vật. Tách đôi hoặc thông tim xanh giữa hạt sen tươi rửa sạch (nếu dùng hạt sen khô thì ngâm nước ấm 2 giờ).',6,'Thấm khô bề mặt đậu hũ và nấm bằng khăn giấy bếp trước khi chế biến giúp nguyên liệu săn chắc, không bị bắn dầu hay ra nước.'),
(171,2,'Xử lý độ giòn ngọt của nấm & rau củ','Đối với nhóm nấm và rau củ (400g bí đỏ và 150g hạt sen tươi), ngâm nhanh qua nước muối loãng 3 phút rồi vắt nhẹ hoặc chần sơ 45 giây trong nước sôi, vớt ngay ra tô nước mát. Thao tác này giúp giữ trọn sắc màu tươi sáng tự nhiên, loại bỏ mùi ngái và tạo độ giòn ngọt thanh khiết cho món Canh bí đỏ hạt sen chay bổ dưỡng.',5,'Không ngâm nấm quá lâu trong nước lạnh vì nấm sẽ hút nước mạnh làm nhạt vị ngọt umami tự nhiên.'),
(171,3,'Pha chén sốt gia vị chay chuẩn định lượng','Chuẩn bị tô nhỏ, đong chính xác 12g hạt nêm nấm hương và 4g muối khuấy đều cùng 30ml nước ấm hoặc nước ngâm nấm hương cho tan hoàn toàn đường và hạt nêm nấm. Nếm thử thấy vị mặn ngọt hài hòa, thanh dịu đúng tinh thần ẩm thực chay cho khẩu phần 4 người. Cho hạt sen vào 1.1 lít nước đun lửa vừa nhỏ 15 phút cho hạt sen mềm bở 80%.',4,'Pha sẵn chén sốt trước khi bật bếp giúp kiểm soát chính xác định lượng từng gam và không bị cháy khét gia vị trên chảo nóng.'),
(171,4,'Phi thơm hành boaro & tạo nền hương thảo mộc','Làm nóng nồi hoặc chảo đáy dày trên lửa vừa, cho 10ml dầu ăn vào láng đều mặt chảo rồi trút 20g hành boaro vào phi thơm. Đảo nhẹ tay khoảng 1–2 phút đến khi hành boaro chuyển sắc vàng óng và dậy mùi thơm dịu thì hạ lửa vừa.',5,'Hành boaro cháy nhanh hơn hành tím nên chỉ phi trên lửa vừa đến khi vừa chớm vàng thơm là cho nguyên liệu chính vào ngay.'),
(171,5,'Chế biến săn thấm nguyên liệu chính thuần thực vật','Cho 400g bí đỏ và 150g hạt sen tươi vào đảo đều hoặc áp chảo nhẹ hai mặt trên lửa vừa đến khi bề mặt săn vàng, sau đó rưới 2/3 chén sốt gia vị chay đã pha vào. Đảo nhẹ tay để sốt bám đều quanh từng thớ đậu và nấm mà không làm vỡ nát cấu trúc nguyên liệu. Phi thơm boaro, đảo sơ bí đỏ và nấm hương 2 phút cho thơm rồi trút vào nồi hạt sen hầm tiếp 8-10 phút.',9,'Dùng sạn gỗ đảo nhẹ từ dưới đáy chảo hất lên để miếng đậu hũ và nấm giữ nguyên hình khối vuông vắn đẹp mắt.'),
(171,6,'Phối hợp rau củ & cân chỉnh độ sánh thanh đạm','Tiếp tục cho 20g nấm hương cùng phần sốt còn lại vào nồi, điều chỉnh lửa vừa nấu thêm cho nguyên liệu chín mềm tới nhưng vẫn giữ độ giòn ngọt. Quan sát thấy nước sốt chuyển màu nâu hổ phách sóng sánh hoặc nước dùng trong thanh, hương thơm quyện đều khắp gian bếp. Nêm hạt nêm nấm hương và nhúm muối hầm, rắc hành boaro lá/ngò rí rồi tắt bếp.',7,'Chỉ nấu rau củ xanh vừa chín tới để bảo toàn tối đa lượng chất xơ và vitamin tự nhiên trong khẩu phần chay.'),
(171,7,'Hoàn thiện hương thơm & trình bày món chay thanh tịnh','Tắt bếp ngay khi món ăn đạt độ chín chuẩn, rắc đều 15g rau om lên bề mặt để dậy mùi thơm tươi mới. Múc món Canh bí đỏ hạt sen chay bổ dưỡng ra đĩa sứ hoặc tô sâu lòng, thưởng thức nóng cùng cơm trắng hoặc bún tươi cho trọn vẹn 4 khẩu phần.',4,'Rắc rau thơm và tiêu ngay lúc vừa tắt bếp giúp tinh dầu tỏa hương thơm ngát mà lá rau không bị thâm xỉn màu.'),
(172,1,'Sơ chế sạch & chuẩn bị nguyên liệu thuần chay','Rửa sạch toàn bộ nguyên liệu dưới vòi nước mát, để ráo tự nhiên trên rổ thưa gồm 20g rong biển khô và 250g đậu hũ non cùng 100g nấm kim châm. Cắt thái đồng đều kích thước khoảng 3–4cm vừa gắp để khi chế biến chín cùng lúc và thấm đều gia vị thực vật. Ngâm rong biển khô trong nước mát 5 phút cho nở, vắt nhẹ và bóp với chút gừng thái lát khử vị tanh biển rồi cắt khúc.',3,'Thấm khô bề mặt đậu hũ và nấm bằng khăn giấy bếp trước khi chế biến giúp nguyên liệu săn chắc, không bị bắn dầu hay ra nước.'),
(172,2,'Xử lý độ giòn ngọt của nấm & rau củ','Đối với nhóm nấm và rau củ (20g rong biển khô và 250g đậu hũ non), ngâm nhanh qua nước muối loãng 3 phút rồi vắt nhẹ hoặc chần sơ 45 giây trong nước sôi, vớt ngay ra tô nước mát. Thao tác này giúp giữ trọn sắc màu tươi sáng tự nhiên, loại bỏ mùi ngái và tạo độ giòn ngọt thanh khiết cho món Canh rong biển đậu hũ non chay.',3,'Không ngâm nấm quá lâu trong nước lạnh vì nấm sẽ hút nước mạnh làm nhạt vị ngọt umami tự nhiên.');
INSERT INTO `recipe_steps` (`recipe_id`,`step_order`,`title`,`instruction`,`duration_mins`,`tip_note`) VALUES
(172,3,'Pha chén sốt gia vị chay chuẩn định lượng','Chuẩn bị tô nhỏ, đong chính xác 12ml nước tương và 10g hạt nêm nấm hương khuấy đều cùng 30ml nước ấm hoặc nước ngâm nấm hương cho tan hoàn toàn đường và hạt nêm nấm. Nếm thử thấy vị mặn ngọt hài hòa, thanh dịu đúng tinh thần ẩm thực chay cho khẩu phần 4 người. Đun nóng 1 thìa dầu mè với gừng thái chỉ, cho rong biển vào đảo đều 1 phút với chút nước tương.',2,'Pha sẵn chén sốt trước khi bật bếp giúp kiểm soát chính xác định lượng từng gam và không bị cháy khét gia vị trên chảo nóng.'),
(172,4,'Phi thơm hành boaro & tạo nền hương thảo mộc','Làm nóng nồi hoặc chảo đáy dày trên lửa vừa, cho 8ml dầu mè vào láng đều mặt chảo rồi trút 12g gừng vào phi thơm. Đảo nhẹ tay khoảng 1–2 phút đến khi hành boaro chuyển sắc vàng óng và dậy mùi thơm dịu thì hạ lửa vừa.',3,'Hành boaro cháy nhanh hơn hành tím nên chỉ phi trên lửa vừa đến khi vừa chớm vàng thơm là cho nguyên liệu chính vào ngay.'),
(172,5,'Chế biến săn thấm nguyên liệu chính thuần thực vật','Cho 20g rong biển khô và 250g đậu hũ non vào đảo đều hoặc áp chảo nhẹ hai mặt trên lửa vừa đến khi bề mặt săn vàng, sau đó rưới 2/3 chén sốt gia vị chay đã pha vào. Đảo nhẹ tay để sốt bám đều quanh từng thớ đậu và nấm mà không làm vỡ nát cấu trúc nguyên liệu. Chế 1 lít nước sôi vào nồi nấu 4 phút, thả nhẹ đậu hũ non và nấm kim châm đun thêm 2 phút.',4,'Dùng sạn gỗ đảo nhẹ từ dưới đáy chảo hất lên để miếng đậu hũ và nấm giữ nguyên hình khối vuông vắn đẹp mắt.'),
(172,6,'Phối hợp rau củ & cân chỉnh độ sánh thanh đạm','Tiếp tục cho 100g nấm kim châm cùng phần sốt còn lại vào nồi, điều chỉnh lửa vừa nấu thêm cho nguyên liệu chín mềm tới nhưng vẫn giữ độ giòn ngọt. Quan sát thấy nước sốt chuyển màu nâu hổ phách sóng sánh hoặc nước dùng trong thanh, hương thơm quyện đều khắp gian bếp. Nêm hạt nêm nấm hương vừa thanh, tắt bếp rồi rưới thêm 1/2 thìa dầu mè và tiêu xay.',4,'Chỉ nấu rau củ xanh vừa chín tới để bảo toàn tối đa lượng chất xơ và vitamin tự nhiên trong khẩu phần chay.'),
(172,7,'Hoàn thiện hương thơm & trình bày món chay thanh tịnh','Tắt bếp ngay khi món ăn đạt độ chín chuẩn, rắc đều hành boaro lá xanh và tiêu xay lên bề mặt để dậy mùi thơm tươi mới. Múc món Canh rong biển đậu hũ non chay ra đĩa sứ hoặc tô sâu lòng, thưởng thức nóng cùng cơm trắng hoặc bún tươi cho trọn vẹn 4 khẩu phần.',2,'Rắc rau thơm và tiêu ngay lúc vừa tắt bếp giúp tinh dầu tỏa hương thơm ngát mà lá rau không bị thâm xỉn màu.'),
(173,1,'Sơ chế sạch & chuẩn bị nguyên liệu thuần chay','Rửa sạch toàn bộ nguyên liệu dưới vòi nước mát, để ráo tự nhiên trên rổ thưa gồm 350g chả lụa chay cùng các nguyên liệu phối kèm. Cắt thái đồng đều kích thước khoảng 3–4cm vừa gắp để khi chế biến chín cùng lúc và thấm đều gia vị thực vật. Áp chảo chả lụa chay cắt miếng với ít dầu ăn cho se vàng hai mặt để khi kho chả săn đậm không nhũn.',4,'Thấm khô bề mặt đậu hũ và nấm bằng khăn giấy bếp trước khi chế biến giúp nguyên liệu săn chắc, không bị bắn dầu hay ra nước.'),
(173,2,'Xử lý độ giòn ngọt của nấm & rau củ','Đối với nhóm nấm và rau củ (350g chả lụa chay), ngâm nhanh qua nước muối loãng 3 phút rồi vắt nhẹ hoặc chần sơ 45 giây trong nước sôi, vớt ngay ra tô nước mát. Thao tác này giúp giữ trọn sắc màu tươi sáng tự nhiên, loại bỏ mùi ngái và tạo độ giòn ngọt thanh khiết cho món Chả lụa chay kho tiêu xanh.',4,'Không ngâm nấm quá lâu trong nước lạnh vì nấm sẽ hút nước mạnh làm nhạt vị ngọt umami tự nhiên.'),
(173,3,'Pha chén sốt gia vị chay chuẩn định lượng','Chuẩn bị tô nhỏ, đong chính xác 35ml nước tương, 10g tiêu và 18g đường thốt nốt khuấy đều cùng 30ml nước ấm hoặc nước ngâm nấm hương cho tan hoàn toàn đường và hạt nêm nấm. Nếm thử thấy vị mặn ngọt hài hòa, thanh dịu đúng tinh thần ẩm thực chay cho khẩu phần 4 người. Thắng nhẹ 1 thìa đường thốt nốt cho lên màu cánh gián, thêm boaro băm phi thơm rồi hòa nước tương và nước dừa tươi.',3,'Pha sẵn chén sốt trước khi bật bếp giúp kiểm soát chính xác định lượng từng gam và không bị cháy khét gia vị trên chảo nóng.'),
(173,4,'Phi thơm hành boaro & tạo nền hương thảo mộc','Làm nóng nồi hoặc chảo đáy dày trên lửa vừa, cho 150ml nước dừa tươi và 20ml dầu ăn vào láng đều mặt chảo rồi trút 25g hành boaro vào phi thơm. Đảo nhẹ tay khoảng 1–2 phút đến khi hành boaro chuyển sắc vàng óng và dậy mùi thơm dịu thì hạ lửa vừa.',3,'Hành boaro cháy nhanh hơn hành tím nên chỉ phi trên lửa vừa đến khi vừa chớm vàng thơm là cho nguyên liệu chính vào ngay.'),
(173,5,'Chế biến săn thấm nguyên liệu chính thuần thực vật','Cho 350g chả lụa chay vào đảo đều hoặc áp chảo nhẹ hai mặt trên lửa vừa đến khi bề mặt săn vàng, sau đó rưới 2/3 chén sốt gia vị chay đã pha vào. Đảo nhẹ tay để sốt bám đều quanh từng thớ đậu và nấm mà không làm vỡ nát cấu trúc nguyên liệu. Thả chả lụa chay và tiêu hạt đập dập vào đảo đều trên lửa nhỏ 10-12 phút đến khi sốt kẹo bám mặt chả.',6,'Dùng sạn gỗ đảo nhẹ từ dưới đáy chảo hất lên để miếng đậu hũ và nấm giữ nguyên hình khối vuông vắn đẹp mắt.'),
(173,6,'Phối hợp rau củ & cân chỉnh độ sánh thanh đạm','Tiếp tục cho các nguyên liệu phối kèm cùng phần sốt còn lại vào nồi, điều chỉnh lửa vừa nấu thêm cho nguyên liệu chín mềm tới nhưng vẫn giữ độ giòn ngọt. Quan sát thấy nước sốt chuyển màu nâu hổ phách sóng sánh hoặc nước dùng trong thanh, hương thơm quyện đều khắp gian bếp. Tắt bếp rắc boaro cắt lát, tiêu xay và ớt tươi dùng nóng với cơm dẻo hoặc cháo trắng.',5,'Chỉ nấu rau củ xanh vừa chín tới để bảo toàn tối đa lượng chất xơ và vitamin tự nhiên trong khẩu phần chay.'),
(173,7,'Hoàn thiện hương thơm & trình bày món chay thanh tịnh','Tắt bếp ngay khi món ăn đạt độ chín chuẩn, rắc đều hành boaro lá xanh và tiêu xay lên bề mặt để dậy mùi thơm tươi mới. Múc món Chả lụa chay kho tiêu xanh ra đĩa sứ hoặc tô sâu lòng, thưởng thức nóng cùng cơm trắng hoặc bún tươi cho trọn vẹn 4 khẩu phần.',3,'Rắc rau thơm và tiêu ngay lúc vừa tắt bếp giúp tinh dầu tỏa hương thơm ngát mà lá rau không bị thâm xỉn màu.'),
(174,1,'Sơ chế sạch & chuẩn bị nguyên liệu thuần chay','Rửa sạch toàn bộ nguyên liệu dưới vòi nước mát, để ráo tự nhiên trên rổ thưa gồm 450g nấm đùi gà cùng các nguyên liệu phối kèm. Cắt thái đồng đều kích thước khoảng 3–4cm vừa gắp để khi chế biến chín cùng lúc và thấm đều gia vị thực vật. Cắt dọc nấm đùi gà dày 1.2 cm, khứa đường chéo mặt trong rồi chần nước sôi có chút muối 2 phút, vắt ráo nhẹ.',6,'Thấm khô bề mặt đậu hũ và nấm bằng khăn giấy bếp trước khi chế biến giúp nguyên liệu săn chắc, không bị bắn dầu hay ra nước.'),
(174,2,'Xử lý độ giòn ngọt của nấm & rau củ','Đối với nhóm nấm và rau củ (450g nấm đùi gà), ngâm nhanh qua nước muối loãng 3 phút rồi vắt nhẹ hoặc chần sơ 45 giây trong nước sôi, vớt ngay ra tô nước mát. Thao tác này giúp giữ trọn sắc màu tươi sáng tự nhiên, loại bỏ mùi ngái và tạo độ giòn ngọt thanh khiết cho món Nấm đùi gà nướng sả ớt chay.',5,'Không ngâm nấm quá lâu trong nước lạnh vì nấm sẽ hút nước mạnh làm nhạt vị ngọt umami tự nhiên.'),
(174,3,'Pha chén sốt gia vị chay chuẩn định lượng','Chuẩn bị tô nhỏ, đong chính xác 12g ớt, 25ml nước tương, 20ml dầu hào chay và 15ml nước mắm chay khuấy đều cùng 30ml nước ấm hoặc nước ngâm nấm hương cho tan hoàn toàn đường và hạt nêm nấm. Nếm thử thấy vị mặn ngọt hài hòa, thanh dịu đúng tinh thần ẩm thực chay cho khẩu phần 4 người. Trộn sả băm, ớt, nước tương, nước mắm chay, đường thốt nốt và dầu ăn ướp nấm 20 phút.',4,'Pha sẵn chén sốt trước khi bật bếp giúp kiểm soát chính xác định lượng từng gam và không bị cháy khét gia vị trên chảo nóng.'),
(174,4,'Phi thơm hành boaro & tạo nền hương thảo mộc','Làm nóng nồi hoặc chảo đáy dày trên lửa vừa, cho 20ml dầu ăn vào láng đều mặt chảo rồi trút 45g sả vào phi thơm. Đảo nhẹ tay khoảng 1–2 phút đến khi hành boaro chuyển sắc vàng óng và dậy mùi thơm dịu thì hạ lửa vừa.',5,'Hành boaro cháy nhanh hơn hành tím nên chỉ phi trên lửa vừa đến khi vừa chớm vàng thơm là cho nguyên liệu chính vào ngay.'),
(174,5,'Chế biến săn thấm nguyên liệu chính thuần thực vật','Cho 450g nấm đùi gà vào đảo đều hoặc áp chảo nhẹ hai mặt trên lửa vừa đến khi bề mặt săn vàng, sau đó rưới 2/3 chén sốt gia vị chay đã pha vào. Đảo nhẹ tay để sốt bám đều quanh từng thớ đậu và nấm mà không làm vỡ nát cấu trúc nguyên liệu. Xếp nấm lên khay nồi chiên không dầu nướng 190°C khoảng 12 phút (lật mặt giữa giờ và quét phần sốt còn lại) đến khi cạnh nấm cháy vàng.',7,'Dùng sạn gỗ đảo nhẹ từ dưới đáy chảo hất lên để miếng đậu hũ và nấm giữ nguyên hình khối vuông vắn đẹp mắt.'),
(174,6,'Phối hợp rau củ & cân chỉnh độ sánh thanh đạm','Tiếp tục cho các nguyên liệu phối kèm cùng phần sốt còn lại vào nồi, điều chỉnh lửa vừa nấu thêm cho nguyên liệu chín mềm tới nhưng vẫn giữ độ giòn ngọt. Quan sát thấy nước sốt chuyển màu nâu hổ phách sóng sánh hoặc nước dùng trong thanh, hương thơm quyện đều khắp gian bếp. Bày nấm nướng ra đĩa, rắc mè rang vàng thơm và chấm kèm nước tương tỏi ớt hoặc muối tiêu chanh.',7,'Chỉ nấu rau củ xanh vừa chín tới để bảo toàn tối đa lượng chất xơ và vitamin tự nhiên trong khẩu phần chay.'),
(174,7,'Hoàn thiện hương thơm & trình bày món chay thanh tịnh','Tắt bếp ngay khi món ăn đạt độ chín chuẩn, rắc đều 15g mè rang lên bề mặt để dậy mùi thơm tươi mới. Múc món Nấm đùi gà nướng sả ớt chay ra đĩa sứ hoặc tô sâu lòng, thưởng thức nóng cùng cơm trắng hoặc bún tươi cho trọn vẹn 4 khẩu phần.',4,'Rắc rau thơm và tiêu ngay lúc vừa tắt bếp giúp tinh dầu tỏa hương thơm ngát mà lá rau không bị thâm xỉn màu.'),
(175,1,'Sơ chế sạch & chuẩn bị nguyên liệu thuần chay','Rửa sạch toàn bộ nguyên liệu dưới vòi nước mát, để ráo tự nhiên trên rổ thưa gồm 200g miến dong và 180g đậu hũ cùng 150g cải thìa. Cắt thái đồng đều kích thước khoảng 3–4cm vừa gắp để khi chế biến chín cùng lúc và thấm đều gia vị thực vật. Ngâm miến nước mát 10 phút cho vừa mềm dẻo, vớt để ráo rồi trộn 1 thìa dầu ăn + 1 thìa nước tương.',5,'Thấm khô bề mặt đậu hũ và nấm bằng khăn giấy bếp trước khi chế biến giúp nguyên liệu săn chắc, không bị bắn dầu hay ra nước.'),
(175,2,'Xử lý độ giòn ngọt của nấm & rau củ','Đối với nhóm nấm và rau củ (150g cải thìa), ngâm nhanh qua nước muối loãng 3 phút rồi vắt nhẹ hoặc chần sơ 45 giây trong nước sôi, vớt ngay ra tô nước mát. Thao tác này giúp giữ trọn sắc màu tươi sáng tự nhiên, loại bỏ mùi ngái và tạo độ giòn ngọt thanh khiết cho món Miến xào thập cẩm chay giòn ngon.',4,'Không ngâm nấm quá lâu trong nước lạnh vì nấm sẽ hút nước mạnh làm nhạt vị ngọt umami tự nhiên.'),
(175,3,'Pha chén sốt gia vị chay chuẩn định lượng','Chuẩn bị tô nhỏ, đong chính xác 30ml nước tương khuấy đều cùng 30ml nước ấm hoặc nước ngâm nấm hương cho tan hoàn toàn đường và hạt nêm nấm. Nếm thử thấy vị mặn ngọt hài hòa, thanh dịu đúng tinh thần ẩm thực chay cho khẩu phần 4 người. Phi thơm boaro, xào cà rốt, nấm hương, nấm mèo, đậu hũ thái sợi và cải thìa 3 phút với chút hạt nêm nấm hương rồi trút riêng.',3,'Pha sẵn chén sốt trước khi bật bếp giúp kiểm soát chính xác định lượng từng gam và không bị cháy khét gia vị trên chảo nóng.'),
(175,4,'Phi thơm hành boaro & tạo nền hương thảo mộc','Làm nóng nồi hoặc chảo đáy dày trên lửa vừa, cho 25ml dầu ăn vào láng đều mặt chảo rồi trút 25g hành boaro vào phi thơm. Đảo nhẹ tay khoảng 1–2 phút đến khi hành boaro chuyển sắc vàng óng và dậy mùi thơm dịu thì hạ lửa vừa.',4,'Hành boaro cháy nhanh hơn hành tím nên chỉ phi trên lửa vừa đến khi vừa chớm vàng thơm là cho nguyên liệu chính vào ngay.'),
(175,5,'Chế biến săn thấm nguyên liệu chính thuần thực vật','Cho 200g miến dong và 180g đậu hũ vào đảo đều hoặc áp chảo nhẹ hai mặt trên lửa vừa đến khi bề mặt săn vàng, sau đó rưới 2/3 chén sốt gia vị chay đã pha vào. Đảo nhẹ tay để sốt bám đều quanh từng thớ đậu và nấm mà không làm vỡ nát cấu trúc nguyên liệu. Xào miến trên chảo lửa vừa-cao 3 phút đến khi sợi miến săn dẻo nóng đều, rưới phần nước tương còn lại.',7,'Dùng sạn gỗ đảo nhẹ từ dưới đáy chảo hất lên để miếng đậu hũ và nấm giữ nguyên hình khối vuông vắn đẹp mắt.'),
(175,6,'Phối hợp rau củ & cân chỉnh độ sánh thanh đạm','Tiếp tục cho 150g cải thìa cùng phần sốt còn lại vào nồi, điều chỉnh lửa vừa nấu thêm cho nguyên liệu chín mềm tới nhưng vẫn giữ độ giòn ngọt. Quan sát thấy nước sốt chuyển màu nâu hổ phách sóng sánh hoặc nước dùng trong thanh, hương thơm quyện đều khắp gian bếp. Đổ đĩa rau nấm đậu hũ vào đảo đều tay 1 phút trên lửa lớn, rắc tiêu xay và ngò rí rồi tắt bếp.',6,'Chỉ nấu rau củ xanh vừa chín tới để bảo toàn tối đa lượng chất xơ và vitamin tự nhiên trong khẩu phần chay.');
INSERT INTO `recipe_steps` (`recipe_id`,`step_order`,`title`,`instruction`,`duration_mins`,`tip_note`) VALUES
(175,7,'Hoàn thiện hương thơm & trình bày món chay thanh tịnh','Tắt bếp ngay khi món ăn đạt độ chín chuẩn, rắc đều hành boaro lá xanh và tiêu xay lên bề mặt để dậy mùi thơm tươi mới. Múc món Miến xào thập cẩm chay giòn ngon ra đĩa sứ hoặc tô sâu lòng, thưởng thức nóng cùng cơm trắng hoặc bún tươi cho trọn vẹn 4 khẩu phần.',3,'Rắc rau thơm và tiêu ngay lúc vừa tắt bếp giúp tinh dầu tỏa hương thơm ngát mà lá rau không bị thâm xỉn màu.'),
(176,1,'Sơ chế sạch & chuẩn bị nguyên liệu thuần chay','Rửa sạch toàn bộ nguyên liệu dưới vòi nước mát, để ráo tự nhiên trên rổ thưa gồm 220g bột gạo và 80g đậu xanh cà vỏ cùng 150g giá đỗ và 180g xà lách. Cắt thái đồng đều kích thước khoảng 3–4cm vừa gắp để khi chế biến chín cùng lúc và thấm đều gia vị thực vật. Hòa bột gạo với nước cốt dừa, 380ml nước lọc, chút bột nghệ/nước cốt nghệ, nhúm muối và boaro lá thái nhỏ rồi để bột nghỉ 30 phút.',7,'Thấm khô bề mặt đậu hũ và nấm bằng khăn giấy bếp trước khi chế biến giúp nguyên liệu săn chắc, không bị bắn dầu hay ra nước.'),
(176,2,'Xử lý độ giòn ngọt của nấm & rau củ','Đối với nhóm nấm và rau củ (150g giá đỗ và 180g xà lách), ngâm nhanh qua nước muối loãng 3 phút rồi vắt nhẹ hoặc chần sơ 45 giây trong nước sôi, vớt ngay ra tô nước mát. Thao tác này giúp giữ trọn sắc màu tươi sáng tự nhiên, loại bỏ mùi ngái và tạo độ giòn ngọt thanh khiết cho món Bánh xèo chay nhân nấm đậu xanh.',6,'Không ngâm nấm quá lâu trong nước lạnh vì nấm sẽ hút nước mạnh làm nhạt vị ngọt umami tự nhiên.'),
(176,3,'Pha chén sốt gia vị chay chuẩn định lượng','Chuẩn bị tô nhỏ, đong chính xác 40ml nước mắm chay khuấy đều cùng 30ml nước ấm hoặc nước ngâm nấm hương cho tan hoàn toàn đường và hạt nêm nấm. Nếm thử thấy vị mặn ngọt hài hòa, thanh dịu đúng tinh thần ẩm thực chay cho khẩu phần 4 người. Hấp chín bở đậu xanh cà vỏ; phi thơm boaro xào nấm bào ngư xé sợi, đậu hũ và cà rốt với hạt nêm nấm hương cho đậm đà.',4,'Pha sẵn chén sốt trước khi bật bếp giúp kiểm soát chính xác định lượng từng gam và không bị cháy khét gia vị trên chảo nóng.'),
(176,4,'Phi thơm hành boaro & tạo nền hương thảo mộc','Làm nóng nồi hoặc chảo đáy dày trên lửa vừa, cho 120ml nước cốt dừa vào láng đều mặt chảo rồi trút 10g nghệ vào phi thơm. Đảo nhẹ tay khoảng 1–2 phút đến khi hành boaro chuyển sắc vàng óng và dậy mùi thơm dịu thì hạ lửa vừa.',5,'Hành boaro cháy nhanh hơn hành tím nên chỉ phi trên lửa vừa đến khi vừa chớm vàng thơm là cho nguyên liệu chính vào ngay.'),
(176,5,'Chế biến săn thấm nguyên liệu chính thuần thực vật','Cho 220g bột gạo và 80g đậu xanh cà vỏ vào đảo đều hoặc áp chảo nhẹ hai mặt trên lửa vừa đến khi bề mặt săn vàng, sau đó rưới 2/3 chén sốt gia vị chay đã pha vào. Đảo nhẹ tay để sốt bám đều quanh từng thớ đậu và nấm mà không làm vỡ nát cấu trúc nguyên liệu. Làm nóng chảo chống dính thoa chút dầu ăn, múc 1 vá bột láng thật mỏng mặt chảo, đặt nhân đậu xanh nấm và giá đỗ lên nửa mặt bánh rồi đậy nắp 2 phút; mở nắp gập đôi chiên thêm 1.5 phút cho rìa giòn tan.',11,'Dùng sạn gỗ đảo nhẹ từ dưới đáy chảo hất lên để miếng đậu hũ và nấm giữ nguyên hình khối vuông vắn đẹp mắt.'),
(176,6,'Phối hợp rau củ & cân chỉnh độ sánh thanh đạm','Tiếp tục cho 150g giá đỗ và 180g xà lách cùng phần sốt còn lại vào nồi, điều chỉnh lửa vừa nấu thêm cho nguyên liệu chín mềm tới nhưng vẫn giữ độ giòn ngọt. Quan sát thấy nước sốt chuyển màu nâu hổ phách sóng sánh hoặc nước dùng trong thanh, hương thơm quyện đều khắp gian bếp. Dọn bánh nóng kèm cải xanh, xà lách, rau thơm và nước mắm chay pha chanh đường ớt tỏi/băm.',8,'Chỉ nấu rau củ xanh vừa chín tới để bảo toàn tối đa lượng chất xơ và vitamin tự nhiên trong khẩu phần chay.'),
(176,7,'Hoàn thiện hương thơm & trình bày món chay thanh tịnh','Tắt bếp ngay khi món ăn đạt độ chín chuẩn, rắc đều hành boaro lá xanh và tiêu xay lên bề mặt để dậy mùi thơm tươi mới. Múc món Bánh xèo chay nhân nấm đậu xanh ra đĩa sứ hoặc tô sâu lòng, thưởng thức nóng cùng cơm trắng hoặc bún tươi cho trọn vẹn 4 khẩu phần.',4,'Rắc rau thơm và tiêu ngay lúc vừa tắt bếp giúp tinh dầu tỏa hương thơm ngát mà lá rau không bị thâm xỉn màu.'),
(177,1,'Sơ chế sạch & chuẩn bị nguyên liệu thuần chay','Rửa sạch toàn bộ nguyên liệu dưới vòi nước mát, để ráo tự nhiên trên rổ thưa gồm 400g gạo nếp và 200g đậu xanh cà vỏ cùng 120g hạt sen tươi. Cắt thái đồng đều kích thước khoảng 3–4cm vừa gắp để khi chế biến chín cùng lúc và thấm đều gia vị thực vật. Ngâm gạo nếp với nước nghệ loãng và nhúm muối 6 tiếng rồi xả sạch; hấp chín bở đậu xanh cà vỏ, giã hoặc xay tơi mịn khi còn nóng.',10,'Thấm khô bề mặt đậu hũ và nấm bằng khăn giấy bếp trước khi chế biến giúp nguyên liệu săn chắc, không bị bắn dầu hay ra nước.'),
(177,2,'Xử lý độ giòn ngọt của nấm & rau củ','Đối với nhóm nấm và rau củ (120g hạt sen tươi), ngâm nhanh qua nước muối loãng 3 phút rồi vắt nhẹ hoặc chần sơ 45 giây trong nước sôi, vớt ngay ra tô nước mát. Thao tác này giúp giữ trọn sắc màu tươi sáng tự nhiên, loại bỏ mùi ngái và tạo độ giòn ngọt thanh khiết cho món Xôi vò hạt sen chay dẻo tơi.',8,'Không ngâm nấm quá lâu trong nước lạnh vì nấm sẽ hút nước mạnh làm nhạt vị ngọt umami tự nhiên.'),
(177,3,'Pha chén sốt gia vị chay chuẩn định lượng','Chuẩn bị tô nhỏ, đong chính xác 45g đường và 4g muối khuấy đều cùng 30ml nước ấm hoặc nước ngâm nấm hương cho tan hoàn toàn đường và hạt nêm nấm. Nếm thử thấy vị mặn ngọt hài hòa, thanh dịu đúng tinh thần ẩm thực chay cho khẩu phần 4 người. Trộn đều gạo nếp ráo nước với 1/2 phần đậu xanh tán nhuyễn và 1 thìa dầu ăn cho hạt gạo áo tơi không dính.',6,'Pha sẵn chén sốt trước khi bật bếp giúp kiểm soát chính xác định lượng từng gam và không bị cháy khét gia vị trên chảo nóng.'),
(177,4,'Phi thơm hành boaro & tạo nền hương thảo mộc','Làm nóng nồi hoặc chảo đáy dày trên lửa vừa, cho 25ml dầu ăn vào láng đều mặt chảo rồi trút 20g hành boaro thái lát mỏng vào phi thơm. Đảo nhẹ tay khoảng 1–2 phút đến khi hành boaro chuyển sắc vàng óng và dậy mùi thơm dịu thì hạ lửa vừa.',8,'Hành boaro cháy nhanh hơn hành tím nên chỉ phi trên lửa vừa đến khi vừa chớm vàng thơm là cho nguyên liệu chính vào ngay.'),
(177,5,'Chế biến săn thấm nguyên liệu chính thuần thực vật','Cho 400g gạo nếp và 200g đậu xanh cà vỏ vào đảo đều hoặc áp chảo nhẹ hai mặt trên lửa vừa đến khi bề mặt săn vàng, sau đó rưới 2/3 chén sốt gia vị chay đã pha vào. Đảo nhẹ tay để sốt bám đều quanh từng thớ đậu và nấm mà không làm vỡ nát cấu trúc nguyên liệu. Cho gạo vào xửng hấp lửa vừa 20 phút, trút ra mâm xới tơi rồi rưới 1 thìa dầu ăn, hạt sen chín và đường trộn đều; đem hấp lại thêm 10 phút.',15,'Dùng sạn gỗ đảo nhẹ từ dưới đáy chảo hất lên để miếng đậu hũ và nấm giữ nguyên hình khối vuông vắn đẹp mắt.'),
(177,6,'Phối hợp rau củ & cân chỉnh độ sánh thanh đạm','Tiếp tục cho 120g hạt sen tươi cùng phần sốt còn lại vào nồi, điều chỉnh lửa vừa nấu thêm cho nguyên liệu chín mềm tới nhưng vẫn giữ độ giòn ngọt. Quan sát thấy nước sốt chuyển màu nâu hổ phách sóng sánh hoặc nước dùng trong thanh, hương thơm quyện đều khắp gian bếp. Khi xôi nguội bớt còn ấm tay, trộn nốt 1/2 phần đậu xanh tơi còn lại cho từng hạt nếp tơi bóng áo vàng đẹp mắt.',12,'Chỉ nấu rau củ xanh vừa chín tới để bảo toàn tối đa lượng chất xơ và vitamin tự nhiên trong khẩu phần chay.'),
(177,7,'Hoàn thiện hương thơm & trình bày món chay thanh tịnh','Tắt bếp ngay khi món ăn đạt độ chín chuẩn, rắc đều 15g mè rang lên bề mặt để dậy mùi thơm tươi mới. Múc món Xôi vò hạt sen chay dẻo tơi ra đĩa sứ hoặc tô sâu lòng, thưởng thức nóng cùng cơm trắng hoặc bún tươi cho trọn vẹn 4 khẩu phần.',6,'Rắc rau thơm và tiêu ngay lúc vừa tắt bếp giúp tinh dầu tỏa hương thơm ngát mà lá rau không bị thâm xỉn màu.'),
(178,1,'Sơ chế sạch & chuẩn bị nguyên liệu thuần chay','Rửa sạch toàn bộ nguyên liệu dưới vòi nước mát, để ráo tự nhiên trên rổ thưa gồm 350g xoài xanh và 250g nấm bào ngư cùng 80g cà rốt. Cắt thái đồng đều kích thước khoảng 3–4cm vừa gắp để khi chế biến chín cùng lúc và thấm đều gia vị thực vật. Ngâm xoài xanh và cà rốt bào sợi trong nước đá lạnh 10 phút rồi vắt nhẹ cho ráo nước và thật giòn.',4,'Thấm khô bề mặt đậu hũ và nấm bằng khăn giấy bếp trước khi chế biến giúp nguyên liệu săn chắc, không bị bắn dầu hay ra nước.'),
(178,2,'Xử lý độ giòn ngọt của nấm & rau củ','Đối với nhóm nấm và rau củ (350g xoài xanh và 250g nấm bào ngư), ngâm nhanh qua nước muối loãng 3 phút rồi vắt nhẹ hoặc chần sơ 45 giây trong nước sôi, vớt ngay ra tô nước mát. Thao tác này giúp giữ trọn sắc màu tươi sáng tự nhiên, loại bỏ mùi ngái và tạo độ giòn ngọt thanh khiết cho món Gỏi xoài nấm bào ngư chay giòn mát.',3,'Không ngâm nấm quá lâu trong nước lạnh vì nấm sẽ hút nước mạnh làm nhạt vị ngọt umami tự nhiên.'),
(178,3,'Pha chén sốt gia vị chay chuẩn định lượng','Chuẩn bị tô nhỏ, đong chính xác 35ml nước mắm chay, 25g đường, 20ml chanh và 8g ớt khuấy đều cùng 30ml nước ấm hoặc nước ngâm nấm hương cho tan hoàn toàn đường và hạt nêm nấm. Nếm thử thấy vị mặn ngọt hài hòa, thanh dịu đúng tinh thần ẩm thực chay cho khẩu phần 4 người. Xé sợi nấm bào ngư, áp chảo ít dầu ăn lửa vừa 5 phút đến khi nấm ráo nước vàng cạnh và có độ dai ngọt; nêm xíu nước tương.',2,'Pha sẵn chén sốt trước khi bật bếp giúp kiểm soát chính xác định lượng từng gam và không bị cháy khét gia vị trên chảo nóng.'),
(178,4,'Phi thơm hành boaro & tạo nền hương thảo mộc','Làm nóng nồi hoặc chảo đáy dày trên lửa vừa, cho 15ml dầu thực vật vào láng đều mặt chảo rồi trút 20g hành boaro thái lát mỏng vào phi thơm. Đảo nhẹ tay khoảng 1–2 phút đến khi hành boaro chuyển sắc vàng óng và dậy mùi thơm dịu thì hạ lửa vừa.',3,'Hành boaro cháy nhanh hơn hành tím nên chỉ phi trên lửa vừa đến khi vừa chớm vàng thơm là cho nguyên liệu chính vào ngay.'),
(178,5,'Chế biến săn thấm nguyên liệu chính thuần thực vật','Cho 350g xoài xanh và 250g nấm bào ngư vào đảo đều hoặc áp chảo nhẹ hai mặt trên lửa vừa đến khi bề mặt săn vàng, sau đó rưới 2/3 chén sốt gia vị chay đã pha vào. Đảo nhẹ tay để sốt bám đều quanh từng thớ đậu và nấm mà không làm vỡ nát cấu trúc nguyên liệu. Hòa tan nước mắm chay, đường, nước cốt chanh và ớt băm khuấy đều đến khi tan đường sánh nhẹ.',7,'Dùng sạn gỗ đảo nhẹ từ dưới đáy chảo hất lên để miếng đậu hũ và nấm giữ nguyên hình khối vuông vắn đẹp mắt.'),
(178,6,'Phối hợp rau củ & cân chỉnh độ sánh thanh đạm','Tiếp tục cho 80g cà rốt cùng phần sốt còn lại vào nồi, điều chỉnh lửa vừa nấu thêm cho nguyên liệu chín mềm tới nhưng vẫn giữ độ giòn ngọt. Quan sát thấy nước sốt chuyển màu nâu hổ phách sóng sánh hoặc nước dùng trong thanh, hương thơm quyện đều khắp gian bếp. Trộn nhẹ nhàng xoài, cà rốt, nấm bào ngư với 2/3 sốt và rau răm cắt nhỏ ngay trước khi ăn; rắc đậu phộng rang lên trên.',4,'Chỉ nấu rau củ xanh vừa chín tới để bảo toàn tối đa lượng chất xơ và vitamin tự nhiên trong khẩu phần chay.'),
(178,7,'Hoàn thiện hương thơm & trình bày món chay thanh tịnh','Tắt bếp ngay khi món ăn đạt độ chín chuẩn, rắc đều 45g đậu phộng và 30g rau răm lên bề mặt để dậy mùi thơm tươi mới. Múc món Gỏi xoài nấm bào ngư chay giòn mát ra đĩa sứ hoặc tô sâu lòng, thưởng thức nóng cùng cơm trắng hoặc bún tươi cho trọn vẹn 4 khẩu phần.',2,'Rắc rau thơm và tiêu ngay lúc vừa tắt bếp giúp tinh dầu tỏa hương thơm ngát mà lá rau không bị thâm xỉn màu.'),
(179,1,'Tuyển chọn, ngâm nở & sơ chế sạch nguyên liệu chè bánh','Đãi rửa sạch nhóm hạt, củ hoặc bột (250g hạt sen tươi và 80g nhãn nhục), ngâm nước ấm theo đúng đặc tính từng loại để hạt nở mềm đồng đều và loại bỏ nhựa chát. Rửa sạch nhóm tạo hương tự nhiên gồm 25g lá dứa để ráo nước. Cho hạt sen tươi vào 1.2 lít nước nấu lửa vừa 18-20 phút đến khi hạt sen mềm bùi vừa tới mà không nát vỡ.',9,'Thêm một nhúm muối nhỏ vào nước ngâm khoai và đậu giúp nguyên liệu giữ màu tươi sáng và khi nấu chín bùi hơn.'),
(179,2,'Ninh mềm bùi nguyên liệu chính giữ nguyên hạt/khối','Cho phần nguyên liệu nền trong 250g hạt sen tươi và 80g nhãn nhục vào nồi đáy dày cùng lượng nước vừa đủ, đun sôi rồi hạ lửa nhỏ ninh êm đến khi chín mềm bùi nhưng không bị vỡ nát đục nước. Nếu có trân châu, bột lọc hoặc hạt lựu, luộc riêng trong nồi nước sôi đến khi nổi trong veo rồi vớt ngâm ngay vào bát nước mát. Rửa sạch nhãn nhục, ngâm nước ấm 10 phút rồi vớt ra (nước ngâm để lắng dùng nấu chung nếu sạch).',13,'Tuyệt đối không cho đường ngay từ đầu khi đậu và khoai chưa chín mềm vì đường sẽ làm săn vỏ hạt khiến nấu mãi vẫn sượng.'),
(179,3,'Nấu nước đường phèn / mật mía thanh trong dậy hương','Kết hợp chính xác định lượng 110g đường vào nồi cùng bó lá dứa hoặc gừng thái chỉ, khuấy nhẹ trên lửa nhỏ cho tan trong vắt. Đun liu riu thêm 5–7 phút để vị ngọt thấm sâu vào từng viên nguyên liệu và tỏa hương thơm dịu tao nhã.',8,'Dùng đường phèn hoặc mật mía đun lửa nhỏ hớt bọt kỹ giúp hậu vị chè ngọt thanh mát họng, không bị khé cổ.');
INSERT INTO `recipe_steps` (`recipe_id`,`step_order`,`title`,`instruction`,`duration_mins`,`tip_note`) VALUES
(179,4,'Thắng nước cốt dừa béo mịn / chuẩn bị lớp kem phủ','Cho 1200ml nước lọc và 200g đá viên vào nồi nhỏ cùng 2g muối tinh và 5g bột năng/bột bắp hòa loãng, khuấy đều tay trên lửa nhỏ nhất đến khi vừa chớm sôi lăn tăn sánh mượt. Tắt bếp ngay để nước cốt dừa giữ màu trắng ngần béo ngậy mà không bị tách lớp dầu. Cho đường phèn và bó lá dứa vào nồi hạt sen nấu lửa nhỏ 5 phút cho hạt sen thấm ngọt thanh.',6,'Một chút xíu muối tinh trong nồi nước cốt dừa sẽ làm bật hẳn độ béo thơm tự nhiên và cân bằng vị ngọt của món tráng miệng.'),
(179,5,'Phối hợp độ sánh mượt & cân bằng hương vị tổng thể','Hợp nhất các thành phần của món Chè hạt sen long nhãn thanh mát, từ từ rưới nước bột năng hòa loãng (nếu là chè sánh) đồng thời khuấy nhẹ một chiều trên lửa nhỏ cho hỗn hợp bóng mượt như nhung. Kiểm tra độ mềm dẻo hài hòa và tắt bếp để ủ hương thảo mộc lan tỏa đều.',5,'Rót nước bột tạo sánh thành dòng mảnh vừa rót vừa khuấy đều tay giúp chè trong mượt, hoàn toàn không bị ốc trâu vón cục.'),
(179,6,'Múc ra chén sứ, điểm topping & thưởng thức ấm/lạnh','Múc chè hoặc bày bánh ra 4 chén nhỏ xinh, chan lớp nước cốt dừa trắng mịn lên mặt và rắc nhẹ mè rang, đậu phộng hoặc dừa non bào sợi. Thưởng thức ấm nóng dịu dàng hoặc thêm đá bào mát lạnh tùy sở thích đều trọn vị ngon truyền thống. Cho nhãn nhục vào nồi nấu thêm 2 phút rồi tắt bếp để giữ độ giòn của nhãn; để nguội dùng lạnh với đá bào.',4,'Để chè nguội bớt về khoảng 45°C hoặc ướp mát 30 phút trong ngăn mát tủ lạnh giúp các tầng hương vị kết tinh đậm đà hơn.'),
(180,1,'Tuyển chọn, ngâm nở & sơ chế sạch nguyên liệu chè bánh','Đãi rửa sạch nhóm hạt, củ hoặc bột (300g bột nếp và 150g đậu xanh cà vỏ), ngâm nước ấm theo đúng đặc tính từng loại để hạt nở mềm đồng đều và loại bỏ nhựa chát. Rửa sạch nhóm tạo hương tự nhiên gồm 45g gừng để ráo nước. Hấp chín bở đậu xanh cà vỏ, sên nhỏ lửa với 40g đường, chút dầu ăn và nhúm muối 5 phút rồi vo thành viên tròn đều.',10,'Thêm một nhúm muối nhỏ vào nước ngâm khoai và đậu giúp nguyên liệu giữ màu tươi sáng và khi nấu chín bùi hơn.'),
(180,2,'Ninh mềm bùi nguyên liệu chính giữ nguyên hạt/khối','Cho phần nguyên liệu nền trong 300g bột nếp và 150g đậu xanh cà vỏ vào nồi đáy dày cùng lượng nước vừa đủ, đun sôi rồi hạ lửa nhỏ ninh êm đến khi chín mềm bùi nhưng không bị vỡ nát đục nước. Nếu có trân châu, bột lọc hoặc hạt lựu, luộc riêng trong nồi nước sôi đến khi nổi trong veo rồi vớt ngâm ngay vào bát nước mát. Trộn bột nếp với khoai lang nghiền (hoặc 180ml nước ấm) nhồi kỹ đến khi khối bột mịn dẻo không dính tay; bọc kín từng viên nhân đậu xanh.',14,'Tuyệt đối không cho đường ngay từ đầu khi đậu và khoai chưa chín mềm vì đường sẽ làm săn vỏ hạt khiến nấu mãi vẫn sượng.'),
(180,3,'Nấu nước đường phèn / mật mía thanh trong dậy hương','Kết hợp chính xác định lượng 160g đường thốt nốt vào nồi cùng bó lá dứa hoặc gừng thái chỉ, khuấy nhẹ trên lửa nhỏ cho tan trong vắt. Đun liu riu thêm 5–7 phút để vị ngọt thấm sâu vào từng viên nguyên liệu và tỏa hương thơm dịu tao nhã.',9,'Dùng đường phèn hoặc mật mía đun lửa nhỏ hớt bọt kỹ giúp hậu vị chè ngọt thanh mát họng, không bị khé cổ.'),
(180,4,'Thắng nước cốt dừa béo mịn / chuẩn bị lớp kem phủ','Cho 150ml nước cốt dừa vào nồi nhỏ cùng 2g muối tinh và 5g bột năng/bột bắp hòa loãng, khuấy đều tay trên lửa nhỏ nhất đến khi vừa chớm sôi lăn tăn sánh mượt. Tắt bếp ngay để nước cốt dừa giữ màu trắng ngần béo ngậy mà không bị tách lớp dầu. Thả viên chè vào nước sôi luộc 5 phút đến khi nổi căng lên mặt nước rồi vớt ngay vào tô nước lạnh; nấu tan đường thốt nốt với 700ml nước và gừng thái sợi 6 phút rồi thả viên chè vào rim thấm 4 phút.',7,'Một chút xíu muối tinh trong nồi nước cốt dừa sẽ làm bật hẳn độ béo thơm tự nhiên và cân bằng vị ngọt của món tráng miệng.'),
(180,5,'Phối hợp độ sánh mượt & cân bằng hương vị tổng thể','Hợp nhất các thành phần của món Chè trôi nước gừng ấm dẻo thơm, từ từ rưới nước bột năng hòa loãng (nếu là chè sánh) đồng thời khuấy nhẹ một chiều trên lửa nhỏ cho hỗn hợp bóng mượt như nhung. Kiểm tra độ mềm dẻo hài hòa và tắt bếp để ủ hương thảo mộc lan tỏa đều.',6,'Rót nước bột tạo sánh thành dòng mảnh vừa rót vừa khuấy đều tay giúp chè trong mượt, hoàn toàn không bị ốc trâu vón cục.'),
(180,6,'Múc ra chén sứ, điểm topping & thưởng thức ấm/lạnh','Múc chè hoặc bày bánh ra 4 chén nhỏ xinh, chan lớp nước cốt dừa trắng mịn lên mặt và rắc nhẹ 20g mè rang. Thưởng thức ấm nóng dịu dàng hoặc thêm đá bào mát lạnh tùy sở thích đều trọn vị ngon truyền thống. Nấu sôi nhẹ nước cốt dừa với xíu muối và bột năng pha loãng; múc chè ra chén chan cốt dừa và rắc mè rang vàng.',4,'Để chè nguội bớt về khoảng 45°C hoặc ướp mát 30 phút trong ngăn mát tủ lạnh giúp các tầng hương vị kết tinh đậm đà hơn.'),
(181,1,'Tuyển chọn, ngâm nở & sơ chế sạch nguyên liệu chè bánh','Đãi rửa sạch nhóm hạt, củ hoặc bột (15g tuyết yến khô và 60g táo đỏ khô), ngâm nước ấm theo đúng đặc tính từng loại để hạt nở mềm đồng đều và loại bỏ nhựa chát. Rửa sạch nhóm tạo hương tự nhiên gồm 20g lá dứa để ráo nước. Ngâm tuyết yến khô với thật nhiều nước sạch qua đêm (tuyết yến nở rất lớn) rồi lọc bỏ tạp chất qua rây; ngâm nở nhãn nhục và hạt chia riêng.',11,'Thêm một nhúm muối nhỏ vào nước ngâm khoai và đậu giúp nguyên liệu giữ màu tươi sáng và khi nấu chín bùi hơn.'),
(181,2,'Ninh mềm bùi nguyên liệu chính giữ nguyên hạt/khối','Cho phần nguyên liệu nền trong 15g tuyết yến khô và 60g táo đỏ khô vào nồi đáy dày cùng lượng nước vừa đủ, đun sôi rồi hạ lửa nhỏ ninh êm đến khi chín mềm bùi nhưng không bị vỡ nát đục nước. Nếu có trân châu, bột lọc hoặc hạt lựu, luộc riêng trong nồi nước sôi đến khi nổi trong veo rồi vớt ngâm ngay vào bát nước mát. Đun 1.3 lít nước với táo đỏ cắt lát và bó lá dứa 12 phút cho nước thơm ngọt màu hổ phách.',15,'Tuyệt đối không cho đường ngay từ đầu khi đậu và khoai chưa chín mềm vì đường sẽ làm săn vỏ hạt khiến nấu mãi vẫn sượng.'),
(181,3,'Nấu nước đường phèn / mật mía thanh trong dậy hương','Kết hợp chính xác định lượng 95g đường vào nồi cùng bó lá dứa hoặc gừng thái chỉ, khuấy nhẹ trên lửa nhỏ cho tan trong vắt. Đun liu riu thêm 5–7 phút để vị ngọt thấm sâu vào từng viên nguyên liệu và tỏa hương thơm dịu tao nhã.',10,'Dùng đường phèn hoặc mật mía đun lửa nhỏ hớt bọt kỹ giúp hậu vị chè ngọt thanh mát họng, không bị khé cổ.'),
(181,4,'Thắng nước cốt dừa béo mịn / chuẩn bị lớp kem phủ','Cho 1300ml nước lọc vào nồi nhỏ cùng 2g muối tinh và 5g bột năng/bột bắp hòa loãng, khuấy đều tay trên lửa nhỏ nhất đến khi vừa chớm sôi lăn tăn sánh mượt. Tắt bếp ngay để nước cốt dừa giữ màu trắng ngần béo ngậy mà không bị tách lớp dầu. Vớt lá dứa ra, cho nhãn nhục và đường phèn vào đun tan nhỏ lửa 5 phút.',8,'Một chút xíu muối tinh trong nồi nước cốt dừa sẽ làm bật hẳn độ béo thơm tự nhiên và cân bằng vị ngọt của món tráng miệng.'),
(181,5,'Phối hợp độ sánh mượt & cân bằng hương vị tổng thể','Hợp nhất các thành phần của món Chè dưỡng nhan táo đỏ tuyết yến, từ từ rưới nước bột năng hòa loãng (nếu là chè sánh) đồng thời khuấy nhẹ một chiều trên lửa nhỏ cho hỗn hợp bóng mượt như nhung. Kiểm tra độ mềm dẻo hài hòa và tắt bếp để ủ hương thảo mộc lan tỏa đều.',7,'Rót nước bột tạo sánh thành dòng mảnh vừa rót vừa khuấy đều tay giúp chè trong mượt, hoàn toàn không bị ốc trâu vón cục.'),
(181,6,'Múc ra chén sứ, điểm topping & thưởng thức ấm/lạnh','Múc chè hoặc bày bánh ra 5 chén nhỏ xinh, chan lớp nước cốt dừa trắng mịn lên mặt và rắc nhẹ mè rang, đậu phộng hoặc dừa non bào sợi. Thưởng thức ấm nóng dịu dàng hoặc thêm đá bào mát lạnh tùy sở thích đều trọn vị ngon truyền thống. Cho tuyết yến và kỷ tử vào nấu đúng 3 phút (tránh nấu lâu làm tuyết yến tan mất sợi), tắt bếp để nguội mới khuấy hạt chia rồi ướp lạnh.',4,'Để chè nguội bớt về khoảng 45°C hoặc ướp mát 30 phút trong ngăn mát tủ lạnh giúp các tầng hương vị kết tinh đậm đà hơn.'),
(182,1,'Tuyển chọn, ngâm nở & sơ chế sạch nguyên liệu chè bánh','Đãi rửa sạch nhóm hạt, củ hoặc bột (5g bột rau câu), ngâm nước ấm theo đúng đặc tính từng loại để hạt nở mềm đồng đều và loại bỏ nhựa chát. Rửa sạch nhóm tạo hương tự nhiên gồm 15g gừng để ráo nước. Ngâm bột rau câu (loại dẻo) trong 700ml sữa đậu nành 10 phút rồi bật lửa nhỏ khuấy tan đều đến khi sôi nhẹ 2 phút thì tắt bếp, hớt sạch bọt đổ khuôn để nguội vào ngăn mát 2 giờ.',8,'Thêm một nhúm muối nhỏ vào nước ngâm khoai và đậu giúp nguyên liệu giữ màu tươi sáng và khi nấu chín bùi hơn.'),
(182,2,'Ninh mềm bùi nguyên liệu chính giữ nguyên hạt/khối','Cho phần nguyên liệu nền trong 5g bột rau câu vào nồi đáy dày cùng lượng nước vừa đủ, đun sôi rồi hạ lửa nhỏ ninh êm đến khi chín mềm bùi nhưng không bị vỡ nát đục nước. Nếu có trân châu, bột lọc hoặc hạt lựu, luộc riêng trong nồi nước sôi đến khi nổi trong veo rồi vớt ngâm ngay vào bát nước mát. Đun sôi nhiều nước thả trân châu đen khuấy đều luộc 15 phút, tắt bếp đậy nắp ủ tiếp 15 phút rồi xả nước lạnh.',11,'Tuyệt đối không cho đường ngay từ đầu khi đậu và khoai chưa chín mềm vì đường sẽ làm săn vỏ hạt khiến nấu mãi vẫn sượng.'),
(182,3,'Nấu nước đường phèn / mật mía thanh trong dậy hương','Kết hợp chính xác định lượng 100g đường đen vào nồi cùng bó lá dứa hoặc gừng thái chỉ, khuấy nhẹ trên lửa nhỏ cho tan trong vắt. Đun liu riu thêm 5–7 phút để vị ngọt thấm sâu vào từng viên nguyên liệu và tỏa hương thơm dịu tao nhã.',7,'Dùng đường phèn hoặc mật mía đun lửa nhỏ hớt bọt kỹ giúp hậu vị chè ngọt thanh mát họng, không bị khé cổ.'),
(182,4,'Thắng nước cốt dừa béo mịn / chuẩn bị lớp kem phủ','Cho 700ml sữa đậu nành và 100ml nước cốt dừa vào nồi nhỏ cùng 2g muối tinh và 5g bột năng/bột bắp hòa loãng, khuấy đều tay trên lửa nhỏ nhất đến khi vừa chớm sôi lăn tăn sánh mượt. Tắt bếp ngay để nước cốt dừa giữ màu trắng ngần béo ngậy mà không bị tách lớp dầu. Đun tan 100g đường đen với 80ml nước và vài lát gừng đập dập đến khi sôi sệt nhẹ rồi thả trân châu vào đảo 3 phút cho ngấm.',6,'Một chút xíu muối tinh trong nồi nước cốt dừa sẽ làm bật hẳn độ béo thơm tự nhiên và cân bằng vị ngọt của món tráng miệng.'),
(182,5,'Phối hợp độ sánh mượt & cân bằng hương vị tổng thể','Hợp nhất các thành phần của món Tàu hũ trân châu đường đen, từ từ rưới nước bột năng hòa loãng (nếu là chè sánh) đồng thời khuấy nhẹ một chiều trên lửa nhỏ cho hỗn hợp bóng mượt như nhung. Kiểm tra độ mềm dẻo hài hòa và tắt bếp để ủ hương thảo mộc lan tỏa đều.',5,'Rót nước bột tạo sánh thành dòng mảnh vừa rót vừa khuấy đều tay giúp chè trong mượt, hoàn toàn không bị ốc trâu vón cục.'),
(182,6,'Múc ra chén sứ, điểm topping & thưởng thức ấm/lạnh','Múc chè hoặc bày bánh ra 4 chén nhỏ xinh, chan lớp nước cốt dừa trắng mịn lên mặt và rắc nhẹ mè rang, đậu phộng hoặc dừa non bào sợi. Thưởng thức ấm nóng dịu dàng hoặc thêm đá bào mát lạnh tùy sở thích đều trọn vị ngon truyền thống. Hớt từng lát tàu hũ mỏng mịn vào chén, chan trân châu sốt đường đen và chút nước cốt dừa béo nhẹ.',3,'Để chè nguội bớt về khoảng 45°C hoặc ướp mát 30 phút trong ngăn mát tủ lạnh giúp các tầng hương vị kết tinh đậm đà hơn.'),
(183,1,'Tuyển chọn, ngâm nở & sơ chế sạch nguyên liệu chè bánh','Đãi rửa sạch nhóm hạt, củ hoặc bột (250g bột gạo và 50g bột năng), ngâm nước ấm theo đúng đặc tính từng loại để hạt nở mềm đồng đều và loại bỏ nhựa chát. Rửa sạch nhóm tạo hương tự nhiên gồm lá dứa, gừng tươi để ráo nước. Nấu tan đường thốt nốt với 120ml nước dừa tươi và nước cốt dừa trên lửa nhỏ đến khi vừa tan đều, để nguội hoàn toàn.',13,'Thêm một nhúm muối nhỏ vào nước ngâm khoai và đậu giúp nguyên liệu giữ màu tươi sáng và khi nấu chín bùi hơn.'),
(183,2,'Ninh mềm bùi nguyên liệu chính giữ nguyên hạt/khối','Cho phần nguyên liệu nền trong 250g bột gạo và 50g bột năng vào nồi đáy dày cùng lượng nước vừa đủ, đun sôi rồi hạ lửa nhỏ ninh êm đến khi chín mềm bùi nhưng không bị vỡ nát đục nước. Nếu có trân châu, bột lọc hoặc hạt lựu, luộc riêng trong nồi nước sôi đến khi nổi trong veo rồi vớt ngâm ngay vào bát nước mát. Trộn bột gạo, bột năng với 1 thìa nhỏ men nở/bột nở (hoặc nước cốt dừa ấm) và nước đường thốt nốt khuấy đều, lọc qua rây cho thật mịn rồi ủ ấm 1-2 giờ đến khi nổi bọt tăm.',18,'Tuyệt đối không cho đường ngay từ đầu khi đậu và khoai chưa chín mềm vì đường sẽ làm săn vỏ hạt khiến nấu mãi vẫn sượng.'),
(183,3,'Nấu nước đường phèn / mật mía thanh trong dậy hương','Kết hợp chính xác định lượng 160g đường thốt nốt vào nồi cùng bó lá dứa hoặc gừng thái chỉ, khuấy nhẹ trên lửa nhỏ cho tan trong vắt. Đun liu riu thêm 5–7 phút để vị ngọt thấm sâu vào từng viên nguyên liệu và tỏa hương thơm dịu tao nhã.',12,'Dùng đường phèn hoặc mật mía đun lửa nhỏ hớt bọt kỹ giúp hậu vị chè ngọt thanh mát họng, không bị khé cổ.'),
(183,4,'Thắng nước cốt dừa béo mịn / chuẩn bị lớp kem phủ','Cho 250ml nước cốt dừa và 120ml nước dừa tươi vào nồi nhỏ cùng 2g muối tinh và 5g bột năng/bột bắp hòa loãng, khuấy đều tay trên lửa nhỏ nhất đến khi vừa chớm sôi lăn tăn sánh mượt. Tắt bếp ngay để nước cốt dừa giữ màu trắng ngần béo ngậy mà không bị tách lớp dầu. Thoa lớp dầu mỏng vào khuôn hấp và làm nóng khuôn trong xửng nước sôi 3 phút rồi mới đổ bột đầy 80% khuôn.',9,'Một chút xíu muối tinh trong nồi nước cốt dừa sẽ làm bật hẳn độ béo thơm tự nhiên và cân bằng vị ngọt của món tráng miệng.');
INSERT INTO `recipe_steps` (`recipe_id`,`step_order`,`title`,`instruction`,`duration_mins`,`tip_note`) VALUES
(183,5,'Phối hợp độ sánh mượt & cân bằng hương vị tổng thể','Hợp nhất các thành phần của món Bánh bò thốt nốt rễ tre thơm béo, từ từ rưới nước bột năng hòa loãng (nếu là chè sánh) đồng thời khuấy nhẹ một chiều trên lửa nhỏ cho hỗn hợp bóng mượt như nhung. Kiểm tra độ mềm dẻo hài hòa và tắt bếp để ủ hương thảo mộc lan tỏa đều.',8,'Rót nước bột tạo sánh thành dòng mảnh vừa rót vừa khuấy đều tay giúp chè trong mượt, hoàn toàn không bị ốc trâu vón cục.'),
(183,6,'Múc ra chén sứ, điểm topping & thưởng thức ấm/lạnh','Múc chè hoặc bày bánh ra 6 chén nhỏ xinh, chan lớp nước cốt dừa trắng mịn lên mặt và rắc nhẹ 15g mè rang. Thưởng thức ấm nóng dịu dàng hoặc thêm đá bào mát lạnh tùy sở thích đều trọn vị ngon truyền thống. Hấp lửa lớn ổn định 18-20 phút (lót khăn nắp nồi tránh đọng nước), thử tăm rút ra khô là bánh chín; rắc mè rang ăn cùng nước cốt dừa.',5,'Để chè nguội bớt về khoảng 45°C hoặc ướp mát 30 phút trong ngăn mát tủ lạnh giúp các tầng hương vị kết tinh đậm đà hơn.'),
(184,1,'Tuyển chọn, ngâm nở & sơ chế sạch nguyên liệu chè bánh','Đãi rửa sạch nhóm hạt, củ hoặc bột (450g chuối sứ và 15g bột năng), ngâm nước ấm theo đúng đặc tính từng loại để hạt nở mềm đồng đều và loại bỏ nhựa chát. Rửa sạch nhóm tạo hương tự nhiên gồm lá dứa, gừng tươi để ráo nước. Hòa tan nước cốt dừa, sữa đặc, đường, nhúm muối và bột năng khuấy trên lửa nhỏ đến khi sánh sệt mịn màng rồi để nguội hoàn toàn.',5,'Thêm một nhúm muối nhỏ vào nước ngâm khoai và đậu giúp nguyên liệu giữ màu tươi sáng và khi nấu chín bùi hơn.'),
(184,2,'Ninh mềm bùi nguyên liệu chính giữ nguyên hạt/khối','Cho phần nguyên liệu nền trong 450g chuối sứ và 15g bột năng vào nồi đáy dày cùng lượng nước vừa đủ, đun sôi rồi hạ lửa nhỏ ninh êm đến khi chín mềm bùi nhưng không bị vỡ nát đục nước. Nếu có trân châu, bột lọc hoặc hạt lựu, luộc riêng trong nồi nước sôi đến khi nổi trong veo rồi vớt ngâm ngay vào bát nước mát. Lột vỏ chuối sứ, đặt giữa hai miếng màng bọc/túi sạch và ép nhẹ dẹt dày khoảng 0.8 cm.',7,'Tuyệt đối không cho đường ngay từ đầu khi đậu và khoai chưa chín mềm vì đường sẽ làm săn vỏ hạt khiến nấu mãi vẫn sượng.'),
(184,3,'Nấu nước đường phèn / mật mía thanh trong dậy hương','Kết hợp chính xác định lượng 25g đường và 2g muối vào nồi cùng bó lá dứa hoặc gừng thái chỉ, khuấy nhẹ trên lửa nhỏ cho tan trong vắt. Đun liu riu thêm 5–7 phút để vị ngọt thấm sâu vào từng viên nguyên liệu và tỏa hương thơm dịu tao nhã.',4,'Dùng đường phèn hoặc mật mía đun lửa nhỏ hớt bọt kỹ giúp hậu vị chè ngọt thanh mát họng, không bị khé cổ.'),
(184,4,'Thắng nước cốt dừa béo mịn / chuẩn bị lớp kem phủ','Cho 250ml nước cốt dừa và 45g sữa đặc vào nồi nhỏ cùng 2g muối tinh và 5g bột năng/bột bắp hòa loãng, khuấy đều tay trên lửa nhỏ nhất đến khi vừa chớm sôi lăn tăn sánh mượt. Tắt bếp ngay để nước cốt dừa giữ màu trắng ngần béo ngậy mà không bị tách lớp dầu. Trải lớp sốt nước cốt dừa vào hộp/khay, đặt chuối ép lên rồi rưới phủ sốt cốt dừa, rắc kín đậu phộng rang (làm 2-3 lớp).',4,'Một chút xíu muối tinh trong nồi nước cốt dừa sẽ làm bật hẳn độ béo thơm tự nhiên và cân bằng vị ngọt của món tráng miệng.'),
(184,5,'Phối hợp độ sánh mượt & cân bằng hương vị tổng thể','Hợp nhất các thành phần của món Kem chuối đậu phộng nước cốt dừa, từ từ rưới nước bột năng hòa loãng (nếu là chè sánh) đồng thời khuấy nhẹ một chiều trên lửa nhỏ cho hỗn hợp bóng mượt như nhung. Kiểm tra độ mềm dẻo hài hòa và tắt bếp để ủ hương thảo mộc lan tỏa đều.',3,'Rót nước bột tạo sánh thành dòng mảnh vừa rót vừa khuấy đều tay giúp chè trong mượt, hoàn toàn không bị ốc trâu vón cục.'),
(184,6,'Múc ra chén sứ, điểm topping & thưởng thức ấm/lạnh','Múc chè hoặc bày bánh ra 6 chén nhỏ xinh, chan lớp nước cốt dừa trắng mịn lên mặt và rắc nhẹ 60g đậu phộng. Thưởng thức ấm nóng dịu dàng hoặc thêm đá bào mát lạnh tùy sở thích đều trọn vị ngon truyền thống. Đậy kín hộp cho vào ngăn đá 6-8 giờ đến khi đông cứng vừa dẻo, cắt miếng vuông vừa ăn.',2,'Để chè nguội bớt về khoảng 45°C hoặc ướp mát 30 phút trong ngăn mát tủ lạnh giúp các tầng hương vị kết tinh đậm đà hơn.'),
(185,1,'Tuyển chọn, ngâm nở & sơ chế sạch nguyên liệu chè bánh','Đãi rửa sạch nhóm hạt, củ hoặc bột (220g bột năng và 50g bột gạo), ngâm nước ấm theo đúng đặc tính từng loại để hạt nở mềm đồng đều và loại bỏ nhựa chát. Rửa sạch nhóm tạo hương tự nhiên gồm 50g lá dứa để ráo nước. Xay lá dứa với 250ml nước vắt lấy cốt xanh; trộn 1/2 bột năng, bột gạo, 1/2 nước cốt dừa và 1/2 đường thành hỗn hợp lá dứa mịn rồi rây lọc.',12,'Thêm một nhúm muối nhỏ vào nước ngâm khoai và đậu giúp nguyên liệu giữ màu tươi sáng và khi nấu chín bùi hơn.'),
(185,2,'Ninh mềm bùi nguyên liệu chính giữ nguyên hạt/khối','Cho phần nguyên liệu nền trong 220g bột năng và 50g bột gạo vào nồi đáy dày cùng lượng nước vừa đủ, đun sôi rồi hạ lửa nhỏ ninh êm đến khi chín mềm bùi nhưng không bị vỡ nát đục nước. Nếu có trân châu, bột lọc hoặc hạt lựu, luộc riêng trong nồi nước sôi đến khi nổi trong veo rồi vớt ngâm ngay vào bát nước mát. Xay nhuyễn đậu xanh hấp chín với 1/2 nước cốt dừa, đường, 1/2 phần bột năng gạo còn lại và vani đến khi sánh mịn.',17,'Tuyệt đối không cho đường ngay từ đầu khi đậu và khoai chưa chín mềm vì đường sẽ làm săn vỏ hạt khiến nấu mãi vẫn sượng.'),
(185,3,'Nấu nước đường phèn / mật mía thanh trong dậy hương','Kết hợp chính xác định lượng 150g đường vào nồi cùng bó lá dứa hoặc gừng thái chỉ, khuấy nhẹ trên lửa nhỏ cho tan trong vắt. Đun liu riu thêm 5–7 phút để vị ngọt thấm sâu vào từng viên nguyên liệu và tỏa hương thơm dịu tao nhã.',11,'Dùng đường phèn hoặc mật mía đun lửa nhỏ hớt bọt kỹ giúp hậu vị chè ngọt thanh mát họng, không bị khé cổ.'),
(185,4,'Thắng nước cốt dừa béo mịn / chuẩn bị lớp kem phủ','Cho 300ml nước cốt dừa vào nồi nhỏ cùng 2g muối tinh và 5g bột năng/bột bắp hòa loãng, khuấy đều tay trên lửa nhỏ nhất đến khi vừa chớm sôi lăn tăn sánh mượt. Tắt bếp ngay để nước cốt dừa giữ màu trắng ngần béo ngậy mà không bị tách lớp dầu. Thoa dầu khuôn, làm nóng xửng hấp; đổ 1 lớp bột lá dứa dày 0.5 cm hấp 5 phút cho se mặt, tiếp theo đổ lớp đậu xanh hấp 6 phút rồi lặp lại 4-6 lớp.',8,'Một chút xíu muối tinh trong nồi nước cốt dừa sẽ làm bật hẳn độ béo thơm tự nhiên và cân bằng vị ngọt của món tráng miệng.'),
(185,5,'Phối hợp độ sánh mượt & cân bằng hương vị tổng thể','Hợp nhất các thành phần của món Bánh da lợn đậu xanh lá dứa, từ từ rưới nước bột năng hòa loãng (nếu là chè sánh) đồng thời khuấy nhẹ một chiều trên lửa nhỏ cho hỗn hợp bóng mượt như nhung. Kiểm tra độ mềm dẻo hài hòa và tắt bếp để ủ hương thảo mộc lan tỏa đều.',7,'Rót nước bột tạo sánh thành dòng mảnh vừa rót vừa khuấy đều tay giúp chè trong mượt, hoàn toàn không bị ốc trâu vón cục.'),
(185,6,'Múc ra chén sứ, điểm topping & thưởng thức ấm/lạnh','Múc chè hoặc bày bánh ra 6 chén nhỏ xinh, chan lớp nước cốt dừa trắng mịn lên mặt và rắc nhẹ mè rang, đậu phộng hoặc dừa non bào sợi. Thưởng thức ấm nóng dịu dàng hoặc thêm đá bào mát lạnh tùy sở thích đều trọn vị ngon truyền thống. Lấy khuôn bánh ra để nguội hẳn 2 giờ rồi mới dùng dao phết dầu ăn cắt thành miếng tam giác hoặc hình thoi đẹp mắt.',5,'Để chè nguội bớt về khoảng 45°C hoặc ướp mát 30 phút trong ngăn mát tủ lạnh giúp các tầng hương vị kết tinh đậm đà hơn.'),
(186,1,'Tuyển chọn, ngâm nở & sơ chế sạch nguyên liệu chè bánh','Đãi rửa sạch nhóm hạt, củ hoặc bột (250g khoai lang và 200g khoai môn), ngâm nước ấm theo đúng đặc tính từng loại để hạt nở mềm đồng đều và loại bỏ nhựa chát. Rửa sạch nhóm tạo hương tự nhiên gồm 20g lá dứa để ráo nước. Hấp chín khoai lang và khoai môn rồi nghiền thật mịn thành hai tô riêng biệt.',9,'Thêm một nhúm muối nhỏ vào nước ngâm khoai và đậu giúp nguyên liệu giữ màu tươi sáng và khi nấu chín bùi hơn.'),
(186,2,'Ninh mềm bùi nguyên liệu chính giữ nguyên hạt/khối','Cho phần nguyên liệu nền trong 250g khoai lang và 200g khoai môn vào nồi đáy dày cùng lượng nước vừa đủ, đun sôi rồi hạ lửa nhỏ ninh êm đến khi chín mềm bùi nhưng không bị vỡ nát đục nước. Nếu có trân châu, bột lọc hoặc hạt lựu, luộc riêng trong nồi nước sôi đến khi nổi trong veo rồi vớt ngâm ngay vào bát nước mát. Trộn mỗi tô khoai với khoảng 80g bột năng và chút nước nóng vừa đủ nhồi thành khối dẻo, se thành cuộn dài và cắt khúc nhỏ 1.5 cm.',13,'Tuyệt đối không cho đường ngay từ đầu khi đậu và khoai chưa chín mềm vì đường sẽ làm săn vỏ hạt khiến nấu mãi vẫn sượng.'),
(186,3,'Nấu nước đường phèn / mật mía thanh trong dậy hương','Kết hợp chính xác định lượng 85g đường vào nồi cùng bó lá dứa hoặc gừng thái chỉ, khuấy nhẹ trên lửa nhỏ cho tan trong vắt. Đun liu riu thêm 5–7 phút để vị ngọt thấm sâu vào từng viên nguyên liệu và tỏa hương thơm dịu tao nhã.',8,'Dùng đường phèn hoặc mật mía đun lửa nhỏ hớt bọt kỹ giúp hậu vị chè ngọt thanh mát họng, không bị khé cổ.'),
(186,4,'Thắng nước cốt dừa béo mịn / chuẩn bị lớp kem phủ','Cho 200ml nước cốt dừa và 200g đá viên vào nồi nhỏ cùng 2g muối tinh và 5g bột năng/bột bắp hòa loãng, khuấy đều tay trên lửa nhỏ nhất đến khi vừa chớm sôi lăn tăn sánh mượt. Tắt bếp ngay để nước cốt dừa giữ màu trắng ngần béo ngậy mà không bị tách lớp dầu. Thả viên khoai vào nước sôi luộc đến khi nổi lên thì đun thêm 2 phút rồi vớt vào tô nước đường lạnh.',6,'Một chút xíu muối tinh trong nồi nước cốt dừa sẽ làm bật hẳn độ béo thơm tự nhiên và cân bằng vị ngọt của món tráng miệng.'),
(186,5,'Phối hợp độ sánh mượt & cân bằng hương vị tổng thể','Hợp nhất các thành phần của món Chè khoai dẻo cốt dừa, từ từ rưới nước bột năng hòa loãng (nếu là chè sánh) đồng thời khuấy nhẹ một chiều trên lửa nhỏ cho hỗn hợp bóng mượt như nhung. Kiểm tra độ mềm dẻo hài hòa và tắt bếp để ủ hương thảo mộc lan tỏa đều.',5,'Rót nước bột tạo sánh thành dòng mảnh vừa rót vừa khuấy đều tay giúp chè trong mượt, hoàn toàn không bị ốc trâu vón cục.'),
(186,6,'Múc ra chén sứ, điểm topping & thưởng thức ấm/lạnh','Múc chè hoặc bày bánh ra 4 chén nhỏ xinh, chan lớp nước cốt dừa trắng mịn lên mặt và rắc nhẹ mè rang, đậu phộng hoặc dừa non bào sợi. Thưởng thức ấm nóng dịu dàng hoặc thêm đá bào mát lạnh tùy sở thích đều trọn vị ngon truyền thống. Đun nước cốt dừa với 200ml nước, lá dứa và đường 5 phút; múc khoai dẻo ra chén chan cốt dừa thêm đá viên.',4,'Để chè nguội bớt về khoảng 45°C hoặc ướp mát 30 phút trong ngăn mát tủ lạnh giúp các tầng hương vị kết tinh đậm đà hơn.'),
(187,1,'Tuyển chọn, ngâm nở & sơ chế sạch nguyên liệu chè bánh','Đãi rửa sạch nhóm hạt, củ hoặc bột (400g sữa chua và 100g trân châu đen), ngâm nước ấm theo đúng đặc tính từng loại để hạt nở mềm đồng đều và loại bỏ nhựa chát. Rửa sạch nhóm tạo hương tự nhiên gồm lá dứa, gừng tươi để ráo nước. Luộc trân châu chín dẻo 15 phút, ủ 15 phút xả nước mát rồi trộn đường đen sên 3 phút trên bếp.',6,'Thêm một nhúm muối nhỏ vào nước ngâm khoai và đậu giúp nguyên liệu giữ màu tươi sáng và khi nấu chín bùi hơn.'),
(187,2,'Ninh mềm bùi nguyên liệu chính giữ nguyên hạt/khối','Cho phần nguyên liệu nền trong 400g sữa chua và 100g trân châu đen vào nồi đáy dày cùng lượng nước vừa đủ, đun sôi rồi hạ lửa nhỏ ninh êm đến khi chín mềm bùi nhưng không bị vỡ nát đục nước. Nếu có trân châu, bột lọc hoặc hạt lựu, luộc riêng trong nồi nước sôi đến khi nổi trong veo rồi vớt ngâm ngay vào bát nước mát. Đun nóng nước cốt dừa cùng sữa đặc, nhúm muối siêu nhỏ và bột năng pha loãng đến khi sánh mịn vừa thì tắt bếp.',9,'Tuyệt đối không cho đường ngay từ đầu khi đậu và khoai chưa chín mềm vì đường sẽ làm săn vỏ hạt khiến nấu mãi vẫn sượng.'),
(187,3,'Nấu nước đường phèn / mật mía thanh trong dậy hương','Kết hợp chính xác định lượng 35g đường đen vào nồi cùng bó lá dứa hoặc gừng thái chỉ, khuấy nhẹ trên lửa nhỏ cho tan trong vắt. Đun liu riu thêm 5–7 phút để vị ngọt thấm sâu vào từng viên nguyên liệu và tỏa hương thơm dịu tao nhã.',5,'Dùng đường phèn hoặc mật mía đun lửa nhỏ hớt bọt kỹ giúp hậu vị chè ngọt thanh mát họng, không bị khé cổ.'),
(187,4,'Thắng nước cốt dừa béo mịn / chuẩn bị lớp kem phủ','Cho 160ml nước cốt dừa và 45g sữa đặc vào nồi nhỏ cùng 2g muối tinh và 5g bột năng/bột bắp hòa loãng, khuấy đều tay trên lửa nhỏ nhất đến khi vừa chớm sôi lăn tăn sánh mượt. Tắt bếp ngay để nước cốt dừa giữ màu trắng ngần béo ngậy mà không bị tách lớp dầu. Cho sữa chua đã làm lạnh (có thể cấp đông nhẹ 1 giờ kiểu sữa chua dẻo) vào ly/tô kèm chút đá bào mịn.',4,'Một chút xíu muối tinh trong nồi nước cốt dừa sẽ làm bật hẳn độ béo thơm tự nhiên và cân bằng vị ngọt của món tráng miệng.'),
(187,5,'Phối hợp độ sánh mượt & cân bằng hương vị tổng thể','Hợp nhất các thành phần của món Sữa chua trân châu cốt dừa Hạ Long, từ từ rưới nước bột năng hòa loãng (nếu là chè sánh) đồng thời khuấy nhẹ một chiều trên lửa nhỏ cho hỗn hợp bóng mượt như nhung. Kiểm tra độ mềm dẻo hài hòa và tắt bếp để ủ hương thảo mộc lan tỏa đều.',4,'Rót nước bột tạo sánh thành dòng mảnh vừa rót vừa khuấy đều tay giúp chè trong mượt, hoàn toàn không bị ốc trâu vón cục.');
INSERT INTO `recipe_steps` (`recipe_id`,`step_order`,`title`,`instruction`,`duration_mins`,`tip_note`) VALUES
(187,6,'Múc ra chén sứ, điểm topping & thưởng thức ấm/lạnh','Múc chè hoặc bày bánh ra 4 chén nhỏ xinh, chan lớp nước cốt dừa trắng mịn lên mặt và rắc nhẹ mè rang, đậu phộng hoặc dừa non bào sợi. Thưởng thức ấm nóng dịu dàng hoặc thêm đá bào mát lạnh tùy sở thích đều trọn vị ngon truyền thống. Múc trân châu ấm vào chén nhỏ chan ngập cốt dừa đặt bên cạnh tô sữa chua để rưới ăn từng muỗng.',2,'Để chè nguội bớt về khoảng 45°C hoặc ướp mát 30 phút trong ngăn mát tủ lạnh giúp các tầng hương vị kết tinh đậm đà hơn.'),
(188,1,'Tuyển chọn & sơ chế tươi sạch nguyên liệu pha chế','Rửa sạch kỹ các nguyên liệu tươi gồm 120ml cà phê đen và 15g lá dứa, để ráo nước hoàn toàn trên khay sạch. Cắt lát, đập dập hoặc đong chuẩn xác từng gam/ml nguyên liệu cho khẩu phần 4 ly để hương vị đồng nhất tuyệt đối. Tráng phin bằng nước sôi; cho 25g bột cà phê rang xay mỗi phin (tổng ~80-100g cho 4 ly), nén vừa gài nắp chặn và rót 20ml nước sôi 92°C ủ 1 phút.',4,'Loại bỏ kỹ hạt chanh, tắc trước khi vắt hoặc nấu giúp thức uống giữ hậu vị thanh ngọt mà không hề bị đắng vỏ.'),
(188,2,'Ủ chiết xuất nền trà, cà phê hoặc nấu cốt thảo mộc','Đun nước đạt nhiệt độ chuẩn 90–95°C (không dùng nước sôi sùng sục làm cháy hương), tiến hành ủ chiết xuất hoặc nấu nhỏ lửa 120ml cà phê đen trong thời gian quy định. Lọc qua rây mịn hoặc túi vải sạch để thu được phần nước cốt trong trẻo, đậm hương tự nhiên không gợn cặn. Rót thêm 40-50ml nước sôi vào phin đậy nắp cho cà phê nhỏ từng giọt đậm đà trong 5-6 phút.',5,'Ủ trà/cà phê đúng nhiệt độ 92°C và đậy nắp kín giúp thu trọn tinh dầu thơm quyến rũ mà không chiết xuất vị chát gắt.'),
(188,3,'Xử lý lớp kem bông mịn / hỗn hợp sữa & trái cây','Đánh bông mượt hoặc khuấy hòa quyện phần nguyên liệu bổ trợ (80g sữa đặc và 300g đá viên) cùng 15g đường đến khi sánh mịn đồng nhất. Kiểm soát tốc độ khuấy/đánh đều tay để tạo kết cấu bồng bềnh mượt mà hoặc hòa tan hoàn toàn đường phèn mật ong. Rót khoảng 20-25g sữa đặc vào đáy mỗi ly thủy tinh, trút cà phê nóng lên khuấy mạnh cho tan đều sủi bọt mịn.',4,'Nếu đánh kem trứng, nghiêng nhẹ âu 45 độ và đánh một chiều tốc độ cao cho tới khi nhấc que tạo chóp mềm bóng mượt không tanh.'),
(188,4,'Cân chỉnh định lượng độ ngọt & tầng hương tươi mát','Phối trộn phần nước cốt nền cùng hỗn hợp tạo vị theo đúng tỷ lệ vàng của món Cà phê sữa đá Sài Gòn phin chuẩn, khuấy nhẹ để các tầng hương hòa quyện. Nếu có nước cốt chanh hoặc mật ong rừng, cho vào khi nền nước đã hạ xuống dưới 55°C để bảo toàn trọn vẹn vitamin và hương thơm.',3,'Nếm thử trước khi thêm đá viên sao cho vị đậm hơn khoảng 15% để khi đá tan nhẹ là vừa vặn hoàn hảo.'),
(188,5,'Phối tầng thẩm mỹ ra ly thủy tinh nóng hoặc đá mát','Tráng ấm ly gốm (nếu dùng nóng) hoặc cho lượng đá viên tinh khiết vừa đủ vào ly thủy tinh cao, rót từ từ cốt thức uống vào 2/3 ly. Nhẹ nhàng rót lớp kem/sữa hoặc xếp lát trái cây tươi áp sát thành ly tạo hiệu ứng phân tầng đẹp mắt như quán chuyên nghiệp.',2,'Rót lớp kem hoặc sữa nhẹ nhàng qua lưng muỗng inox giúp hai tầng màu tách bạch sắc nét cực kỳ cuốn hút.'),
(188,6,'Điểm xuyết lá thơm trang trí & thưởng thức ngay','Trang trí trên mặt ly bằng lát nguyên liệu tươi, nhánh bạc hà/lá dứa hoặc rắc nhẹ bột cacao/hạt chia cho món Cà phê sữa đá Sài Gòn phin chuẩn thêm phần sinh động. Phục vụ ngay khi vừa pha chế xong cho 4 người để tận hưởng trọn vẹn hương thơm tươi mới sảng khoái nhất. Cho đầy đá viên già lạnh vào ly khuấy nhẹ 2 vòng là hoàn thiện ly cà phê sữa đá Sài Gòn.',2,'Vỗ nhẹ lá bạc hà trong lòng bàn tay trước khi đặt lên miệng ly sẽ đánh thức tinh dầu the mát lan tỏa ngay khi nâng ly.'),
(189,1,'Tuyển chọn & sơ chế tươi sạch nguyên liệu pha chế','Rửa sạch kỹ các nguyên liệu tươi gồm 160ml cà phê đen và 160ml kem tươi và rau củ ăn kèm, để ráo nước hoàn toàn trên khay sạch. Cắt lát, đập dập hoặc đong chuẩn xác từng gam/ml nguyên liệu cho khẩu phần 4 ly để hương vị đồng nhất tuyệt đối. Pha 4 phần nước cốt cà phê phin đậm vị và để nguội bớt.',4,'Loại bỏ kỹ hạt chanh, tắc trước khi vắt hoặc nấu giúp thức uống giữ hậu vị thanh ngọt mà không hề bị đắng vỏ.'),
(189,2,'Ủ chiết xuất nền trà, cà phê hoặc nấu cốt thảo mộc','Đun nước đạt nhiệt độ chuẩn 90–95°C (không dùng nước sôi sùng sục làm cháy hương), tiến hành ủ chiết xuất hoặc nấu nhỏ lửa 160ml cà phê đen và 160ml kem tươi trong thời gian quy định. Lọc qua rây mịn hoặc túi vải sạch để thu được phần nước cốt trong trẻo, đậm hương tự nhiên không gợn cặn. Cho kem tươi lạnh, 40ml sữa tươi và 3g muối tinh vào tô đánh đều bằng máy đánh trứng (hoặc bình lắc) 2 phút đến khi đặc sánh mịn bóng như kem sữa.',7,'Ủ trà/cà phê đúng nhiệt độ 92°C và đậy nắp kín giúp thu trọn tinh dầu thơm quyến rũ mà không chiết xuất vị chát gắt.'),
(189,3,'Xử lý lớp kem bông mịn / hỗn hợp sữa & trái cây','Đánh bông mượt hoặc khuấy hòa quyện phần nguyên liệu bổ trợ (60g sữa đặc và 60ml sữa tươi) cùng 3g muối đến khi sánh mịn đồng nhất. Kiểm soát tốc độ khuấy/đánh đều tay để tạo kết cấu bồng bềnh mượt mà hoặc hòa tan hoàn toàn đường phèn mật ong. Hòa sữa đặc vào ly rồi rót cà phê phin khuấy đều, thêm đá viên đầy 2/3 ly.',4,'Nếu đánh kem trứng, nghiêng nhẹ âu 45 độ và đánh một chiều tốc độ cao cho tới khi nhấc que tạo chóp mềm bóng mượt không tanh.'),
(189,4,'Cân chỉnh định lượng độ ngọt & tầng hương tươi mát','Phối trộn phần nước cốt nền cùng hỗn hợp tạo vị theo đúng tỷ lệ vàng của món Cà phê muối Huế béo mặn hài hòa, khuấy nhẹ để các tầng hương hòa quyện. Nếu có nước cốt chanh hoặc mật ong rừng, cho vào khi nền nước đã hạ xuống dưới 55°C để bảo toàn trọn vẹn vitamin và hương thơm.',3,'Nếm thử trước khi thêm đá viên sao cho vị đậm hơn khoảng 15% để khi đá tan nhẹ là vừa vặn hoàn hảo.'),
(189,5,'Phối tầng thẩm mỹ ra ly thủy tinh nóng hoặc đá mát','Tráng ấm ly gốm (nếu dùng nóng) hoặc cho lượng đá viên tinh khiết vừa đủ vào ly thủy tinh cao, rót từ từ cốt thức uống vào 2/3 ly. Nhẹ nhàng rót lớp kem/sữa hoặc xếp lát trái cây tươi áp sát thành ly tạo hiệu ứng phân tầng đẹp mắt như quán chuyên nghiệp.',2,'Rót lớp kem hoặc sữa nhẹ nhàng qua lưng muỗng inox giúp hai tầng màu tách bạch sắc nét cực kỳ cuốn hút.'),
(189,6,'Điểm xuyết lá thơm trang trí & thưởng thức ngay','Trang trí trên mặt ly bằng lát nguyên liệu tươi, nhánh bạc hà/lá dứa hoặc rắc nhẹ bột cacao/hạt chia cho món Cà phê muối Huế béo mặn hài hòa thêm phần sinh động. Phục vụ ngay khi vừa pha chế xong cho 4 người để tận hưởng trọn vẹn hương thơm tươi mới sảng khoái nhất. Rót nhẹ lớp kem muối béo mặn lên trên cùng tạo hai tầng đẹp mắt và thưởng thức không cần ống hút.',2,'Vỗ nhẹ lá bạc hà trong lòng bàn tay trước khi đặt lên miệng ly sẽ đánh thức tinh dầu the mát lan tỏa ngay khi nâng ly.'),
(190,1,'Tuyển chọn & sơ chế tươi sạch nguyên liệu pha chế','Rửa sạch kỹ các nguyên liệu tươi gồm 15g trà đen và 240g vải ngâm và 16g hạt chia, để ráo nước hoàn toàn trên khay sạch. Cắt lát, đập dập hoặc đong chuẩn xác từng gam/ml nguyên liệu cho khẩu phần 4 ly để hương vị đồng nhất tuyệt đối. Hãm trà đen trong 700ml nước nóng 88°C đúng 3-4 phút rồi lọc bỏ xác trà ngay và để nguội nhanh.',5,'Loại bỏ kỹ hạt chanh, tắc trước khi vắt hoặc nấu giúp thức uống giữ hậu vị thanh ngọt mà không hề bị đắng vỏ.'),
(190,2,'Ủ chiết xuất nền trà, cà phê hoặc nấu cốt thảo mộc','Đun nước đạt nhiệt độ chuẩn 90–95°C (không dùng nước sôi sùng sục làm cháy hương), tiến hành ủ chiết xuất hoặc nấu nhỏ lửa 15g trà đen và 240g vải ngâm trong thời gian quy định. Lọc qua rây mịn hoặc túi vải sạch để thu được phần nước cốt trong trẻo, đậm hương tự nhiên không gợn cặn. Ngâm 16g hạt chia trong 100ml nước lọc 10 phút cho hạt nở đều thành lớp gel trong; tách quả vải ngâm để riêng.',7,'Ủ trà/cà phê đúng nhiệt độ 92°C và đậy nắp kín giúp thu trọn tinh dầu thơm quyến rũ mà không chiết xuất vị chát gắt.'),
(190,3,'Xử lý lớp kem bông mịn / hỗn hợp sữa & trái cây','Đánh bông mượt hoặc khuấy hòa quyện phần nguyên liệu bổ trợ (16g hạt chia) cùng 45g đường và 30ml tắc đến khi sánh mịn đồng nhất. Kiểm soát tốc độ khuấy/đánh đều tay để tạo kết cấu bồng bềnh mượt mà hoặc hòa tan hoàn toàn đường phèn mật ong. Hòa nước trà đã nguội với 100ml nước ngâm vải (thêm chút nước đường nếu muốn ngọt hơn) và nước cốt tắc thơm.',5,'Nếu đánh kem trứng, nghiêng nhẹ âu 45 độ và đánh một chiều tốc độ cao cho tới khi nhấc que tạo chóp mềm bóng mượt không tanh.'),
(190,4,'Cân chỉnh định lượng độ ngọt & tầng hương tươi mát','Phối trộn phần nước cốt nền cùng hỗn hợp tạo vị theo đúng tỷ lệ vàng của món Trà vải hạt chia thanh mát, khuấy nhẹ để các tầng hương hòa quyện. Nếu có nước cốt chanh hoặc mật ong rừng, cho vào khi nền nước đã hạ xuống dưới 55°C để bảo toàn trọn vẹn vitamin và hương thơm.',4,'Nếm thử trước khi thêm đá viên sao cho vị đậm hơn khoảng 15% để khi đá tan nhẹ là vừa vặn hoàn hảo.'),
(190,5,'Phối tầng thẩm mỹ ra ly thủy tinh nóng hoặc đá mát','Tráng ấm ly gốm (nếu dùng nóng) hoặc cho lượng đá viên tinh khiết vừa đủ vào ly thủy tinh cao, rót từ từ cốt thức uống vào 2/3 ly. Nhẹ nhàng rót lớp kem/sữa hoặc xếp lát trái cây tươi áp sát thành ly tạo hiệu ứng phân tầng đẹp mắt như quán chuyên nghiệp.',2,'Rót lớp kem hoặc sữa nhẹ nhàng qua lưng muỗng inox giúp hai tầng màu tách bạch sắc nét cực kỳ cuốn hút.'),
(190,6,'Điểm xuyết lá thơm trang trí & thưởng thức ngay','Trang trí trên mặt ly bằng lát nguyên liệu tươi, nhánh bạc hà/lá dứa hoặc rắc nhẹ bột cacao/hạt chia cho món Trà vải hạt chia thanh mát thêm phần sinh động. Phục vụ ngay khi vừa pha chế xong cho 4 người để tận hưởng trọn vẹn hương thơm tươi mới sảng khoái nhất. Rót trà ra 4 ly đá, múc hạt chia đã nở cùng 3 trái vải ngâm lên mặt mỗi ly và trang trí lá bạc hà.',2,'Vỗ nhẹ lá bạc hà trong lòng bàn tay trước khi đặt lên miệng ly sẽ đánh thức tinh dầu the mát lan tỏa ngay khi nâng ly.'),
(191,1,'Tuyển chọn & sơ chế tươi sạch nguyên liệu pha chế','Rửa sạch kỹ các nguyên liệu tươi gồm 650g dưa hấu và rau củ ăn kèm, để ráo nước hoàn toàn trên khay sạch. Cắt lát, đập dập hoặc đong chuẩn xác từng gam/ml nguyên liệu cho khẩu phần 4 ly để hương vị đồng nhất tuyệt đối. Cắt thịt dưa hấu đỏ thành khối vuông và gạn bỏ hạt, có thể ướp lạnh trước 30 phút.',4,'Loại bỏ kỹ hạt chanh, tắc trước khi vắt hoặc nấu giúp thức uống giữ hậu vị thanh ngọt mà không hề bị đắng vỏ.'),
(191,2,'Ủ chiết xuất nền trà, cà phê hoặc nấu cốt thảo mộc','Đun nước đạt nhiệt độ chuẩn 90–95°C (không dùng nước sôi sùng sục làm cháy hương), tiến hành ủ chiết xuất hoặc nấu nhỏ lửa 650g dưa hấu trong thời gian quy định. Lọc qua rây mịn hoặc túi vải sạch để thu được phần nước cốt trong trẻo, đậm hương tự nhiên không gợn cặn. Ngắt lá bạc hà rửa sạch để ráo (chừa 4 ngọn đẹp trang trí miệng ly).',5,'Ủ trà/cà phê đúng nhiệt độ 92°C và đậy nắp kín giúp thu trọn tinh dầu thơm quyến rũ mà không chiết xuất vị chát gắt.'),
(191,3,'Xử lý lớp kem bông mịn / hỗn hợp sữa & trái cây','Đánh bông mượt hoặc khuấy hòa quyện phần nguyên liệu bổ trợ (300g đá viên) cùng 20ml chanh, 20g mật ong và 15g đường đến khi sánh mịn đồng nhất. Kiểm soát tốc độ khuấy/đánh đều tay để tạo kết cấu bồng bềnh mượt mà hoặc hòa tan hoàn toàn đường phèn mật ong. Cho dưa hấu, 2/3 lá bạc hà, nước cốt chanh, mật ong và đá viên vào máy xay nhuyễn 30 giây.',4,'Nếu đánh kem trứng, nghiêng nhẹ âu 45 độ và đánh một chiều tốc độ cao cho tới khi nhấc que tạo chóp mềm bóng mượt không tanh.'),
(191,4,'Cân chỉnh định lượng độ ngọt & tầng hương tươi mát','Phối trộn phần nước cốt nền cùng hỗn hợp tạo vị theo đúng tỷ lệ vàng của món Sinh tố dưa hấu bạc hà mát lạnh, khuấy nhẹ để các tầng hương hòa quyện. Nếu có nước cốt chanh hoặc mật ong rừng, cho vào khi nền nước đã hạ xuống dưới 55°C để bảo toàn trọn vẹn vitamin và hương thơm.',3,'Nếm thử trước khi thêm đá viên sao cho vị đậm hơn khoảng 15% để khi đá tan nhẹ là vừa vặn hoàn hảo.'),
(191,5,'Phối tầng thẩm mỹ ra ly thủy tinh nóng hoặc đá mát','Tráng ấm ly gốm (nếu dùng nóng) hoặc cho lượng đá viên tinh khiết vừa đủ vào ly thủy tinh cao, rót từ từ cốt thức uống vào 2/3 ly. Nhẹ nhàng rót lớp kem/sữa hoặc xếp lát trái cây tươi áp sát thành ly tạo hiệu ứng phân tầng đẹp mắt như quán chuyên nghiệp.',2,'Rót lớp kem hoặc sữa nhẹ nhàng qua lưng muỗng inox giúp hai tầng màu tách bạch sắc nét cực kỳ cuốn hút.'),
(191,6,'Điểm xuyết lá thơm trang trí & thưởng thức ngay','Trang trí trên mặt ly bằng lát nguyên liệu tươi, nhánh bạc hà/lá dứa hoặc rắc nhẹ bột cacao/hạt chia cho món Sinh tố dưa hấu bạc hà mát lạnh thêm phần sinh động. Phục vụ ngay khi vừa pha chế xong cho 4 người để tận hưởng trọn vẹn hương thơm tươi mới sảng khoái nhất. Rót ra 4 ly cao, cắm ngọn bạc hà và lát dưa hấu nhỏ trên vành ly rồi uống ngay khi lạnh.',2,'Vỗ nhẹ lá bạc hà trong lòng bàn tay trước khi đặt lên miệng ly sẽ đánh thức tinh dầu the mát lan tỏa ngay khi nâng ly.');
INSERT INTO `recipe_steps` (`recipe_id`,`step_order`,`title`,`instruction`,`duration_mins`,`tip_note`) VALUES
(192,1,'Tuyển chọn & sơ chế tươi sạch nguyên liệu pha chế','Rửa sạch kỹ các nguyên liệu tươi gồm 250g cần tây và 350g táo xanh và 8g gừng, để ráo nước hoàn toàn trên khay sạch. Cắt lát, đập dập hoặc đong chuẩn xác từng gam/ml nguyên liệu cho khẩu phần 4 ly để hương vị đồng nhất tuyệt đối. Rửa cần tây (chọn cọng xanh non ít xơ già) và táo xanh bằng nước muối loãng rồi tráng lại nước đun sôi để nguội.',6,'Loại bỏ kỹ hạt chanh, tắc trước khi vắt hoặc nấu giúp thức uống giữ hậu vị thanh ngọt mà không hề bị đắng vỏ.'),
(192,2,'Ủ chiết xuất nền trà, cà phê hoặc nấu cốt thảo mộc','Đun nước đạt nhiệt độ chuẩn 90–95°C (không dùng nước sôi sùng sục làm cháy hương), tiến hành ủ chiết xuất hoặc nấu nhỏ lửa 250g cần tây và 350g táo xanh trong thời gian quy định. Lọc qua rây mịn hoặc túi vải sạch để thu được phần nước cốt trong trẻo, đậm hương tự nhiên không gợn cặn. Cắt khúc cần tây 3 cm, cắt múi táo bỏ hạt (giữ vỏ để nhiều chất chống oxy hóa), thái khúc dưa leo và gừng.',9,'Ủ trà/cà phê đúng nhiệt độ 92°C và đậy nắp kín giúp thu trọn tinh dầu thơm quyến rũ mà không chiết xuất vị chát gắt.'),
(192,3,'Xử lý lớp kem bông mịn / hỗn hợp sữa & trái cây','Đánh bông mượt hoặc khuấy hòa quyện phần nguyên liệu bổ trợ (200g dưa leo) cùng 15ml chanh đến khi sánh mịn đồng nhất. Kiểm soát tốc độ khuấy/đánh đều tay để tạo kết cấu bồng bềnh mượt mà hoặc hòa tan hoàn toàn đường phèn mật ong. Đưa lần lượt cần tây, táo xanh, dưa leo và lát gừng qua máy ép chậm lấy nước nguyên chất.',6,'Nếu đánh kem trứng, nghiêng nhẹ âu 45 độ và đánh một chiều tốc độ cao cho tới khi nhấc que tạo chóp mềm bóng mượt không tanh.'),
(192,4,'Cân chỉnh định lượng độ ngọt & tầng hương tươi mát','Phối trộn phần nước cốt nền cùng hỗn hợp tạo vị theo đúng tỷ lệ vàng của món Nước ép cần tây táo xanh detox, khuấy nhẹ để các tầng hương hòa quyện. Nếu có nước cốt chanh hoặc mật ong rừng, cho vào khi nền nước đã hạ xuống dưới 55°C để bảo toàn trọn vẹn vitamin và hương thơm.',4,'Nếm thử trước khi thêm đá viên sao cho vị đậm hơn khoảng 15% để khi đá tan nhẹ là vừa vặn hoàn hảo.'),
(192,5,'Phối tầng thẩm mỹ ra ly thủy tinh nóng hoặc đá mát','Tráng ấm ly gốm (nếu dùng nóng) hoặc cho lượng đá viên tinh khiết vừa đủ vào ly thủy tinh cao, rót từ từ cốt thức uống vào 2/3 ly. Nhẹ nhàng rót lớp kem/sữa hoặc xếp lát trái cây tươi áp sát thành ly tạo hiệu ứng phân tầng đẹp mắt như quán chuyên nghiệp.',3,'Rót lớp kem hoặc sữa nhẹ nhàng qua lưng muỗng inox giúp hai tầng màu tách bạch sắc nét cực kỳ cuốn hút.'),
(192,6,'Điểm xuyết lá thơm trang trí & thưởng thức ngay','Trang trí trên mặt ly bằng lát nguyên liệu tươi, nhánh bạc hà/lá dứa hoặc rắc nhẹ bột cacao/hạt chia cho món Nước ép cần tây táo xanh detox thêm phần sinh động. Phục vụ ngay khi vừa pha chế xong cho 4 người để tận hưởng trọn vẹn hương thơm tươi mới sảng khoái nhất. Rót ra ly thủy tinh thêm chút đá nếu thích lạnh và dùng hết trong vòng 30 phút sau khi ép.',2,'Vỗ nhẹ lá bạc hà trong lòng bàn tay trước khi đặt lên miệng ly sẽ đánh thức tinh dầu the mát lan tỏa ngay khi nâng ly.'),
(193,1,'Tuyển chọn & sơ chế tươi sạch nguyên liệu pha chế','Rửa sạch kỹ các nguyên liệu tươi gồm 120g hạt điều và 70g yến mạch và 20g lá dứa, để ráo nước hoàn toàn trên khay sạch. Cắt lát, đập dập hoặc đong chuẩn xác từng gam/ml nguyên liệu cho khẩu phần 4 ly để hương vị đồng nhất tuyệt đối. Ngâm hạt điều tươi với chút muối trong 2 giờ rồi xả sạch; ngâm yến mạch 20 phút và rửa nhẹ qua rây cho hết nước nhớt để sữa không bị lợn cợn.',7,'Loại bỏ kỹ hạt chanh, tắc trước khi vắt hoặc nấu giúp thức uống giữ hậu vị thanh ngọt mà không hề bị đắng vỏ.'),
(193,2,'Ủ chiết xuất nền trà, cà phê hoặc nấu cốt thảo mộc','Đun nước đạt nhiệt độ chuẩn 90–95°C (không dùng nước sôi sùng sục làm cháy hương), tiến hành ủ chiết xuất hoặc nấu nhỏ lửa 120g hạt điều và 70g yến mạch trong thời gian quy định. Lọc qua rây mịn hoặc túi vải sạch để thu được phần nước cốt trong trẻo, đậm hương tự nhiên không gợn cặn. Đun hạt điều với 600ml nước và lá dứa trên lửa nhỏ 10 phút cho hạt chín mềm (hoặc dùng máy nấu sữa hạt trực tiếp).',9,'Ủ trà/cà phê đúng nhiệt độ 92°C và đậy nắp kín giúp thu trọn tinh dầu thơm quyến rũ mà không chiết xuất vị chát gắt.'),
(193,3,'Xử lý lớp kem bông mịn / hỗn hợp sữa & trái cây','Đánh bông mượt hoặc khuấy hòa quyện phần nguyên liệu bổ trợ (1100ml nước lọc) cùng 45g đường thốt nốt và 2g muối đến khi sánh mịn đồng nhất. Kiểm soát tốc độ khuấy/đánh đều tay để tạo kết cấu bồng bềnh mượt mà hoặc hòa tan hoàn toàn đường phèn mật ong. Cho hạt điều đã nấu, yến mạch ráo nước, 500ml nước ấm còn lại, nhúm muối và đường thốt nốt vào máy xay công suất cao xay 2 phút thật mịn.',7,'Nếu đánh kem trứng, nghiêng nhẹ âu 45 độ và đánh một chiều tốc độ cao cho tới khi nhấc que tạo chóp mềm bóng mượt không tanh.'),
(193,4,'Cân chỉnh định lượng độ ngọt & tầng hương tươi mát','Phối trộn phần nước cốt nền cùng hỗn hợp tạo vị theo đúng tỷ lệ vàng của món Sữa hạt điều yến mạch thơm béo, khuấy nhẹ để các tầng hương hòa quyện. Nếu có nước cốt chanh hoặc mật ong rừng, cho vào khi nền nước đã hạ xuống dưới 55°C để bảo toàn trọn vẹn vitamin và hương thơm.',5,'Nếm thử trước khi thêm đá viên sao cho vị đậm hơn khoảng 15% để khi đá tan nhẹ là vừa vặn hoàn hảo.'),
(193,5,'Phối tầng thẩm mỹ ra ly thủy tinh nóng hoặc đá mát','Tráng ấm ly gốm (nếu dùng nóng) hoặc cho lượng đá viên tinh khiết vừa đủ vào ly thủy tinh cao, rót từ từ cốt thức uống vào 2/3 ly. Nhẹ nhàng rót lớp kem/sữa hoặc xếp lát trái cây tươi áp sát thành ly tạo hiệu ứng phân tầng đẹp mắt như quán chuyên nghiệp.',4,'Rót lớp kem hoặc sữa nhẹ nhàng qua lưng muỗng inox giúp hai tầng màu tách bạch sắc nét cực kỳ cuốn hút.'),
(193,6,'Điểm xuyết lá thơm trang trí & thưởng thức ngay','Trang trí trên mặt ly bằng lát nguyên liệu tươi, nhánh bạc hà/lá dứa hoặc rắc nhẹ bột cacao/hạt chia cho món Sữa hạt điều yến mạch thơm béo thêm phần sinh động. Phục vụ ngay khi vừa pha chế xong cho 4 người để tận hưởng trọn vẹn hương thơm tươi mới sảng khoái nhất. Có thể đun ấm lại ở 75°C khoảng 3 phút (khuấy liên tục tránh khê đáy), để nguội rót chai thủy tinh dùng dần trong 2-3 ngày ngăn mát.',3,'Vỗ nhẹ lá bạc hà trong lòng bàn tay trước khi đặt lên miệng ly sẽ đánh thức tinh dầu the mát lan tỏa ngay khi nâng ly.'),
(194,1,'Tuyển chọn & sơ chế tươi sạch nguyên liệu pha chế','Rửa sạch kỹ các nguyên liệu tươi gồm 20g trà ô long và 90g kem phô mai và 150ml kem tươi, để ráo nước hoàn toàn trên khay sạch. Cắt lát, đập dập hoặc đong chuẩn xác từng gam/ml nguyên liệu cho khẩu phần 4 ly để hương vị đồng nhất tuyệt đối. Tráng ấm, hãm 20g trà ô long với 800ml nước 90°C trong 4-5 phút rồi lọc bỏ lá trà, hòa tan 30g đường để nguội và làm lạnh.',5,'Loại bỏ kỹ hạt chanh, tắc trước khi vắt hoặc nấu giúp thức uống giữ hậu vị thanh ngọt mà không hề bị đắng vỏ.'),
(194,2,'Ủ chiết xuất nền trà, cà phê hoặc nấu cốt thảo mộc','Đun nước đạt nhiệt độ chuẩn 90–95°C (không dùng nước sôi sùng sục làm cháy hương), tiến hành ủ chiết xuất hoặc nấu nhỏ lửa 20g trà ô long và 90g kem phô mai trong thời gian quy định. Lọc qua rây mịn hoặc túi vải sạch để thu được phần nước cốt trong trẻo, đậm hương tự nhiên không gợn cặn. Tán nhuyễn cream cheese cùng 25g đường trước rồi đổ kem tươi lạnh, sữa tươi và muối vào đánh bông 60% đến khi sệt chảy ruy băng.',7,'Ủ trà/cà phê đúng nhiệt độ 92°C và đậy nắp kín giúp thu trọn tinh dầu thơm quyến rũ mà không chiết xuất vị chát gắt.'),
(194,3,'Xử lý lớp kem bông mịn / hỗn hợp sữa & trái cây','Đánh bông mượt hoặc khuấy hòa quyện phần nguyên liệu bổ trợ (150ml kem tươi) cùng 55g đường và 2g muối đến khi sánh mịn đồng nhất. Kiểm soát tốc độ khuấy/đánh đều tay để tạo kết cấu bồng bềnh mượt mà hoặc hòa tan hoàn toàn đường phèn mật ong. Cho đá viên vào 4 ly thủy tinh, rót trà ô long đầy khoảng 3/4 ly.',5,'Nếu đánh kem trứng, nghiêng nhẹ âu 45 độ và đánh một chiều tốc độ cao cho tới khi nhấc que tạo chóp mềm bóng mượt không tanh.'),
(194,4,'Cân chỉnh định lượng độ ngọt & tầng hương tươi mát','Phối trộn phần nước cốt nền cùng hỗn hợp tạo vị theo đúng tỷ lệ vàng của món Trà ô long kem cheese béo mặn, khuấy nhẹ để các tầng hương hòa quyện. Nếu có nước cốt chanh hoặc mật ong rừng, cho vào khi nền nước đã hạ xuống dưới 55°C để bảo toàn trọn vẹn vitamin và hương thơm.',4,'Nếm thử trước khi thêm đá viên sao cho vị đậm hơn khoảng 15% để khi đá tan nhẹ là vừa vặn hoàn hảo.'),
(194,5,'Phối tầng thẩm mỹ ra ly thủy tinh nóng hoặc đá mát','Tráng ấm ly gốm (nếu dùng nóng) hoặc cho lượng đá viên tinh khiết vừa đủ vào ly thủy tinh cao, rót từ từ cốt thức uống vào 2/3 ly. Nhẹ nhàng rót lớp kem/sữa hoặc xếp lát trái cây tươi áp sát thành ly tạo hiệu ứng phân tầng đẹp mắt như quán chuyên nghiệp.',2,'Rót lớp kem hoặc sữa nhẹ nhàng qua lưng muỗng inox giúp hai tầng màu tách bạch sắc nét cực kỳ cuốn hút.'),
(194,6,'Điểm xuyết lá thơm trang trí & thưởng thức ngay','Trang trí trên mặt ly bằng lát nguyên liệu tươi, nhánh bạc hà/lá dứa hoặc rắc nhẹ bột cacao/hạt chia cho món Trà ô long kem cheese béo mặn thêm phần sinh động. Phục vụ ngay khi vừa pha chế xong cho 4 người để tận hưởng trọn vẹn hương thơm tươi mới sảng khoái nhất. Rót từ từ lớp kem cheese béo mịn lên trên cùng tạo tầng bồng bềnh đẹp mắt rồi thưởng thức.',2,'Vỗ nhẹ lá bạc hà trong lòng bàn tay trước khi đặt lên miệng ly sẽ đánh thức tinh dầu the mát lan tỏa ngay khi nâng ly.'),
(195,1,'Sơ chế tươi sạch & ngâm giòn rau củ thảo mộc','Nhặt rửa kỹ rau củ ăn kèm cùng 45g đậu phộng và 25g hành phi qua nước muối loãng rồi tráng nước đun sôi để nguội. Với các loại củ quả bào sợi hoặc thái lát mỏng, ngâm vào âu nước đá lạnh pha chút chanh đường trong 10 phút rồi vắt ráo để giữ độ trắng giòn sần sật. Bóc sạch hoàn toàn phần cùi trắng và màng vỏ múi bưởi, tách tép thành từng cụm vừa ăn không để dập nát ra nước.',7,'Rau củ làm gỏi và món cuốn phải quay rổ hoặc thấm thật ráo nước để khi trộn nước mắm không bị loãng nhạt.'),
(195,2,'Làm chín tới phần nhân đạm giữ trọn độ ngọt mọng','Xử lý phần nguyên liệu chính (450g bưởi năm roi và 220g tôm sú): luộc hấp cùng lát gừng sả đập dập hoặc xào lửa lớn vừa chín tới, sau đó làm nguội nhanh rồi thái lát mỏng / xé sợi đều đặn. Nếu món có pha bột bánh gạo/bột năng, khuấy tan bột với nước đúng tỷ lệ và để bột nghỉ 15 phút cho nở mịn. Luộc tôm với chút rượu gừng rồi bóc vỏ chẻ dọc; chần mực trong nước sôi gừng 2 phút vớt ngâm nước đá cho giòn trắng.',8,'Ngâm tôm hoặc thịt luộc qua bát nước sôi để nguội có vài viên đá giúp màu sắc tươi hồng và thớ thịt giòn ngọt không bị khô.'),
(195,3,'Rang vàng đậu phộng mè thơm & phi hành tỏi giòn','Bắc chảo nhỏ lên lửa nhỏ, rang chín vàng thơm đậu phộng/mè hoặc làm mỡ hành xanh mướt và phi vàng giòn hành tím và tỏi băm nhỏ. Vớt hành tỏi phi ra đĩa riêng để nguội giòn tan, giữ lại phần dầu thơm óng ánh để phết bánh hoặc rưới bóng mặt món ăn.',5,'Tắt bếp ngay khi hành phi chuyển vàng sáng vì nhiệt dư trong dầu nóng sẽ tiếp tục làm hành sẫm màu thêm một nấc hoàn hảo.'),
(195,4,'Pha nước mắm chấm / sốt trộn tỷ lệ vàng chua ngọt','Hòa tan hoàn toàn đường cùng 35ml nước mắm, 30g đường và 20ml chanh và nước ấm trong chén sâu lòng, khuấy đến khi hơi sánh nhẹ mới cho tỏi ớt băm nhuyễn và nước cốt chanh/tắc vào sau cùng. Công thức pha này giúp tỏi ớt nổi đều đẹp mắt trên bề mặt bát nước chấm chuẩn vị Gỏi bưởi tôm mực chua ngọt. Hòa tan nước mắm ngon, đường, chanh, tỏi ớt băm nhuyễn cho vị sánh chua ngọt đậm vừa.',5,'Băm tỏi ớt thật ráo trên thớt khô và cho vào sau khi đường mắm đã nguội thì tỏi ớt sẽ nổi bồng bềnh 100% không bị chìm đáy.'),
(195,5,'Phối trộn thấm vị / tráng hấp & cuốn đều tay','Tiến hành tráng hấp bánh mỏng mượt hoặc trải bánh cuốn gọn gàng 450g bưởi năm roi và 220g tôm sú cùng rau củ ăn kèm; nếu là món gỏi trộn thì rưới từ từ 2/3 lượng sốt chua ngọt vào bóp nhẹ tay cho thấm đều trong 3 phút. Giữ lực tay nhẹ nhàng để rau củ không bị dập nát mà vẫn ngấm trọn vị mặn chua ngọt hài hòa.',6,'Chia nước sốt gỏi làm 2 lần trộn và chắt bỏ phần nước tiết ra ở lần đầu giúp đĩa gỏi khô ráo, đậm đà như ngoài hàng.'),
(195,6,'Bày biện ngũ sắc hài hòa & rắc topping giòn bùi','Xếp món Gỏi bưởi tôm mực chua ngọt ngay ngắn ra đĩa sứ trắng rộng, rải đều phần nhân tôm thịt sắc nét lên trên và rắc phủ 45g đậu phộng và 25g hành phi thơm giòn. Dọn kèm chén nước chấm đậm đà cho 4 người thưởng thức ngay khi rau bánh còn tươi giòn mướt mịn. Trộn tôm mực cà rốt trước với 1/2 nước sốt, sau đó nhẹ tay đảo cùng tép bưởi, rau răm và rưới phần sốt còn lại; rắc đậu phộng, hành phi và dọn ngay.',4,'Chỉ rắc đậu phộng rang và hành phi ngay trước lúc mang ra bàn ăn để giữ nguyên độ giòn tan bùi béo.'),
(196,1,'Sơ chế sạch & cắt thái nguyên liệu đúng kích cỡ','Rửa sạch 700g chân gà cùng các nguyên liệu phối kèm dưới vòi nước mát rồi để thật ráo trên rổ thưa. Dùng dao sắc cắt thái nguyên liệu thành từng khúc hoặc khối vuông đều đặn khoảng 3.5–4cm để khi kho hầm giữ nguyên hình dáng đẹp mắt mà không bị vụn nát. Rửa sạch chân gà cắt móng với muối giấm; luộc cùng gừng đập dập đúng 8 phút tính từ lúc nước sôi rồi vớt ngâm ngay vào thau nước đá lạnh 20 phút, để thật ráo.',6,'Cắt miếng thịt/cá dày dặn đồng đều giúp quá trình kho lâu trên lửa nhỏ thớ thịt mềm rục mà vẫn giữ trọn độ mọng ngọt bên trong.');
INSERT INTO `recipe_steps` (`recipe_id`,`step_order`,`title`,`instruction`,`duration_mins`,`tip_note`) VALUES
(196,2,'Khử mùi tự nhiên & làm săn sạch bề mặt nguyên liệu','Chà nhẹ phần đạm chính trong 700g chân gà với chút muối hạt, lát gừng đập dập hoặc chần sơ qua nước sôi 90 giây rồi rửa sạch lại bằng nước ấm, để ráo hoàn toàn. Công đoạn này loại bỏ triệt để tạp chất và mùi tanh hôi, giúp nước sốt món Chân gà ngâm sả tắc giòn sần sật trong bóng thơm ngon.',4,'Sau khi chần hoặc rửa sạch, để nguyên liệu ráo nước ít nhất 5 phút trước khi ướp để gia vị rút sâu trực tiếp vào từng thớ thịt.'),
(196,3,'Pha hỗn hợp gia vị & ướp thấm chuẩn định lượng','Cho 700g chân gà vào tô lớn, ướp cùng một nửa 80g sả và 25g gừng băm nhỏ và định lượng chuẩn 120g tắc, 20g ớt, 90ml nước mắm và 90g đường, đảo nhẹ tay cho gia vị phủ kín đều các mặt. Bọc kín tô và để nguyên liệu nghỉ thấm vị tối thiểu 20 phút ở nhiệt độ phòng (hoặc ngăn mát tủ lạnh). Nấu sôi tan hỗn hợp 90ml nước mắm, 90g đường, 70ml giấm và 200ml nước lọc trong 4 phút rồi ĐỂ NGUỘI HOÀN TOÀN.',6,'Ướp đủ tối thiểu 20 phút trước khi bắc lên bếp là chìa khóa để tâm miếng thịt/cá đậm đà đồng nhất với lớp sốt bên ngoài.'),
(196,4,'Thắng nước màu cánh gián & phi dậy hương hành tỏi','Đặt nồi đáy dày lên bếp ở lửa vừa nhỏ, thắng nhẹ 15g đường với 15ml dầu ăn đến khi chuyển sắc nâu cánh gián óng ả thì cho ngay phần 80g sả và 25g gừng còn lại vào phi thơm lừng. Hương caramel dịu ngọt quyện cùng tinh dầu hành tỏi sả tạo nền màu nâu hổ phách truyền thống đầy cuốn hút.',4,'Canh kỹ khoảnh khắc đường vừa chuyển màu cánh gián là hạ lửa nhỏ nhất ngay để nước màu bóng đẹp mà không bao giờ bị đắng.'),
(196,5,'Đảo săn hai mặt khóa ngọt nguyên liệu chính','Tăng lên lửa vừa lớn, gắp từng miếng trong 700g chân gà vào nồi đảo đều hoặc trở nhẹ hai mặt trong 4–5 phút cho săn chắc và bám đều lớp màu nâu óng. Khi bề mặt nguyên liệu se vàng thơm phức mới trút phần nước ướp còn lại trong tô vào đun sôi nhẹ. Rửa sạch trái tắc, thái lát mỏng bỏ sạch 100% hạt tắc; sả thái xéo mỏng, ớt cắt lát.',6,'Đối với cá kho, chỉ lật cá một lần lúc cá vừa săn mặt trên lửa vừa để khúc cá nguyên vẹn không bị tróc da hay vỡ nát.'),
(196,6,'Kho/om liu riu lửa nhỏ thấm đẫm cùng nước dừa/nước dùng','Chế lượng nước vừa ngập mặt nguyên liệu xâm xắp mặt nguyên liệu (xếp thêm rau củ ăn kèm nếu có), đun sôi bùng một dạo hớt sạch bọt rồi hạ ngay về mức lửa nhỏ liu riu nhất. Kho êm đềm không đậy kín nắp để từng thớ nguyên liệu chín mềm thấm đẫm gia vị và nước sốt rút dần sóng sánh. Xếp chân gà vào hũ thủy tinh xen kẽ sả, ớt, tắc và lá chanh, đổ ngập nước mắm đã nguội hoàn toàn và đậy kín cất ngăn mát 4-6 giờ.',10,'Luôn dùng nước sôi hoặc nước dừa ấm khi châm thêm vào nồi kho đang nóng để thịt cá không bị sượng cứng trở lại.'),
(196,7,'Thu sánh nước sốt óng ả & trình bày thưởng thức nóng','Khi nước kho rút còn khoảng 1/3 sánh kẹo óng ánh áo đều quanh nguyên liệu và xiên đũa thấy mềm mọng vừa ý, rắc 12g lá chanh lên mặt rồi tắt bếp. Múc món Chân gà ngâm sả tắc giòn sần sật ra đĩa sâu lòng hoặc niêu đất giữ nhiệt, dọn ăn nóng cùng cơm trắng dẻo thơm cho 4 người.',4,'Giữ lại một lượng nước sốt sánh kẹo vừa đủ dưới đáy nồi để chan cơm hoặc chấm kèm rau luộc sẽ tròn vị đưa cơm gấp bội.'),
(197,1,'Sơ chế tươi sạch & ngâm giòn rau củ thảo mộc','Nhặt rửa kỹ rau củ ăn kèm cùng 25g hành phi, 45g đậu phộng và 25g rau răm qua nước muối loãng rồi tráng nước đun sôi để nguội. Với các loại củ quả bào sợi hoặc thái lát mỏng, ngâm vào âu nước đá lạnh pha chút chanh đường trong 10 phút rồi vắt ráo để giữ độ trắng giòn sần sật. Ngâm sơ khô cá sặc nước ấm 5 phút cho dịu bớt vị mặn nếu cần, lau khô rồi nướng nồi chiên 180°C 7 phút (hoặc áp chảo) đến khi vàng thơm, xé miếng vừa bỏ xương.',5,'Rau củ làm gỏi và món cuốn phải quay rổ hoặc thấm thật ráo nước để khi trộn nước mắm không bị loãng nhạt.'),
(197,2,'Làm chín tới phần nhân đạm giữ trọn độ ngọt mọng','Xử lý phần nguyên liệu chính (400g xoài xanh và 150g cá sặc khô): luộc hấp cùng lát gừng sả đập dập hoặc xào lửa lớn vừa chín tới, sau đó làm nguội nhanh rồi thái lát mỏng / xé sợi đều đặn. Nếu món có pha bột bánh gạo/bột năng, khuấy tan bột với nước đúng tỷ lệ và để bột nghỉ 15 phút cho nở mịn. Ngâm xoài xanh cà rốt bào sợi với nước đá lạnh 5 phút rồi vắt nhẹ cho ráo.',6,'Ngâm tôm hoặc thịt luộc qua bát nước sôi để nguội có vài viên đá giúp màu sắc tươi hồng và thớ thịt giòn ngọt không bị khô.'),
(197,3,'Rang vàng đậu phộng mè thơm & phi hành tỏi giòn','Bắc chảo nhỏ lên lửa nhỏ, rang chín vàng thơm đậu phộng/mè hoặc làm mỡ hành xanh mướt và phi vàng giòn hành tím và tỏi băm nhỏ. Vớt hành tỏi phi ra đĩa riêng để nguội giòn tan, giữ lại phần dầu thơm óng ánh để phết bánh hoặc rưới bóng mặt món ăn.',4,'Tắt bếp ngay khi hành phi chuyển vàng sáng vì nhiệt dư trong dầu nóng sẽ tiếp tục làm hành sẫm màu thêm một nấc hoàn hảo.'),
(197,4,'Pha nước mắm chấm / sốt trộn tỷ lệ vàng chua ngọt','Hòa tan hoàn toàn đường cùng 30g đường và 25ml nước mắm và nước ấm trong chén sâu lòng, khuấy đến khi hơi sánh nhẹ mới cho tỏi ớt băm nhuyễn và nước cốt chanh/tắc vào sau cùng. Công thức pha này giúp tỏi ớt nổi đều đẹp mắt trên bề mặt bát nước chấm chuẩn vị Gỏi xoài xanh khô cá sặc trộn. Khuấy tan 30g đường với 25ml nước mắm (hoặc ít hơn tùy độ mặn của khô cá), tỏi ớt băm và chút nước lọc.',4,'Băm tỏi ớt thật ráo trên thớt khô và cho vào sau khi đường mắm đã nguội thì tỏi ớt sẽ nổi bồng bềnh 100% không bị chìm đáy.'),
(197,5,'Phối trộn thấm vị / tráng hấp & cuốn đều tay','Tiến hành tráng hấp bánh mỏng mượt hoặc trải bánh cuốn gọn gàng 400g xoài xanh và 150g cá sặc khô cùng rau củ ăn kèm; nếu là món gỏi trộn thì rưới từ từ 2/3 lượng sốt chua ngọt vào bóp nhẹ tay cho thấm đều trong 3 phút. Giữ lực tay nhẹ nhàng để rau củ không bị dập nát mà vẫn ngấm trọn vị mặn chua ngọt hài hòa.',4,'Chia nước sốt gỏi làm 2 lần trộn và chắt bỏ phần nước tiết ra ở lần đầu giúp đĩa gỏi khô ráo, đậm đà như ngoài hàng.'),
(197,6,'Bày biện ngũ sắc hài hòa & rắc topping giòn bùi','Xếp món Gỏi xoài xanh khô cá sặc trộn ngay ngắn ra đĩa sứ trắng rộng, rải đều phần nhân tôm thịt sắc nét lên trên và rắc phủ 25g hành phi, 45g đậu phộng và 25g rau răm thơm giòn. Dọn kèm chén nước chấm đậm đà cho 4 người thưởng thức ngay khi rau bánh còn tươi giòn mướt mịn. Trộn xoài, cà rốt với nước sốt và rau răm thái nhỏ, rắc khô cá sặc xé, hành phi và đậu phộng rang lên mặt.',2,'Chỉ rắc đậu phộng rang và hành phi ngay trước lúc mang ra bàn ăn để giữ nguyên độ giòn tan bùi béo.'),
(198,1,'Sơ chế sạch & cắt thái nguyên liệu đúng kích cỡ','Rửa sạch 280g bột năng và 220g tôm sú cùng 150g thịt ba chỉ dưới vòi nước mát rồi để thật ráo trên rổ thưa. Dùng dao sắc cắt thái nguyên liệu thành từng khúc hoặc khối vuông đều đặn khoảng 3.5–4cm để khi kho hầm giữ nguyên hình dáng đẹp mắt mà không bị vụn nát. Xào ba chỉ cắt hạt lựu cho xém cạnh ra mỡ, thêm hành tím và tôm vào rim cùng nước mắm, đường, tiêu đến khi tôm đỏ au sánh sệt.',7,'Cắt miếng thịt/cá dày dặn đồng đều giúp quá trình kho lâu trên lửa nhỏ thớ thịt mềm rục mà vẫn giữ trọn độ mọng ngọt bên trong.'),
(198,2,'Khử mùi tự nhiên & làm săn sạch bề mặt nguyên liệu','Chà nhẹ phần đạm chính trong 280g bột năng và 220g tôm sú với chút muối hạt, lát gừng đập dập hoặc chần sơ qua nước sôi 90 giây rồi rửa sạch lại bằng nước ấm, để ráo hoàn toàn. Công đoạn này loại bỏ triệt để tạp chất và mùi tanh hôi, giúp nước sốt món Bánh bột lọc Huế nhân tôm thịt trong bóng thơm ngon.',6,'Sau khi chần hoặc rửa sạch, để nguyên liệu ráo nước ít nhất 5 phút trước khi ướp để gia vị rút sâu trực tiếp vào từng thớ thịt.'),
(198,3,'Pha hỗn hợp gia vị & ướp thấm chuẩn định lượng','Cho 280g bột năng và 220g tôm sú vào tô lớn, ướp cùng một nửa 30g hành tím băm nhỏ và định lượng chuẩn 40ml nước mắm và 25g đường, đảo nhẹ tay cho gia vị phủ kín đều các mặt. Bọc kín tô và để nguyên liệu nghỉ thấm vị tối thiểu 20 phút ở nhiệt độ phòng (hoặc ngăn mát tủ lạnh). Đun sôi 220ml nước có 1 thìa dầu ăn và xíu muối, rót từ từ vào tô bột năng khuấy đều rồi nhồi nhanh tay đến khi khối bột dẻo mịn không dính tay.',8,'Ướp đủ tối thiểu 20 phút trước khi bắc lên bếp là chìa khóa để tâm miếng thịt/cá đậm đà đồng nhất với lớp sốt bên ngoài.'),
(198,4,'Thắng nước màu cánh gián & phi dậy hương hành tỏi','Đặt nồi đáy dày lên bếp ở lửa vừa nhỏ, thắng nhẹ 15g đường với 15ml dầu ăn đến khi chuyển sắc nâu cánh gián óng ả thì cho ngay phần 30g hành tím còn lại vào phi thơm lừng. Hương caramel dịu ngọt quyện cùng tinh dầu hành tỏi sả tạo nền màu nâu hổ phách truyền thống đầy cuốn hút.',5,'Canh kỹ khoảnh khắc đường vừa chuyển màu cánh gián là hạ lửa nhỏ nhất ngay để nước màu bóng đẹp mà không bao giờ bị đắng.'),
(198,5,'Đảo săn hai mặt khóa ngọt nguyên liệu chính','Tăng lên lửa vừa lớn, gắp từng miếng trong 280g bột năng và 220g tôm sú vào nồi đảo đều hoặc trở nhẹ hai mặt trong 4–5 phút cho săn chắc và bám đều lớp màu nâu óng. Khi bề mặt nguyên liệu se vàng thơm phức mới trút phần nước ướp còn lại trong tô vào đun sôi nhẹ. Chia bột thành từng viên nhỏ, ấn dẹt mỏng đặt 1 con tôm + 1 miếng thịt vào giữa rồi gập mí ép chặt thành hình bán nguyệt.',7,'Đối với cá kho, chỉ lật cá một lần lúc cá vừa săn mặt trên lửa vừa để khúc cá nguyên vẹn không bị tróc da hay vỡ nát.'),
(198,6,'Kho/om liu riu lửa nhỏ thấm đẫm cùng nước dừa/nước dùng','Chế 35ml dầu ăn xâm xắp mặt nguyên liệu (xếp thêm rau củ ăn kèm nếu có), đun sôi bùng một dạo hớt sạch bọt rồi hạ ngay về mức lửa nhỏ liu riu nhất. Kho êm đềm không đậy kín nắp để từng thớ nguyên liệu chín mềm thấm đẫm gia vị và nước sốt rút dần sóng sánh. Thả bánh vào nồi nước sôi luộc 5-6 phút đến khi bánh nổi và vỏ chuyển trong suốt nhìn rõ nhân, vớt ngâm nước nguội 30 giây rồi trộn mỡ hành; chấm nước mắm ớt tỏi.',12,'Luôn dùng nước sôi hoặc nước dừa ấm khi châm thêm vào nồi kho đang nóng để thịt cá không bị sượng cứng trở lại.'),
(198,7,'Thu sánh nước sốt óng ả & trình bày thưởng thức nóng','Khi nước kho rút còn khoảng 1/3 sánh kẹo óng ánh áo đều quanh nguyên liệu và xiên đũa thấy mềm mọng vừa ý, rắc 35g hành lá lên mặt rồi tắt bếp. Múc món Bánh bột lọc Huế nhân tôm thịt ra đĩa sâu lòng hoặc niêu đất giữ nhiệt, dọn ăn nóng cùng cơm trắng dẻo thơm cho 4 người.',5,'Giữ lại một lượng nước sốt sánh kẹo vừa đủ dưới đáy nồi để chan cơm hoặc chấm kèm rau luộc sẽ tròn vị đưa cơm gấp bội.'),
(199,1,'Sơ chế sạch & thấm thật khô bề mặt nguyên liệu','Rửa sạch 220g giò sống và 220g thịt heo xay cùng chút muối loãng để khử mùi tự nhiên, sau đó dùng khăn giấy bếp thấm thật khô ráo hoàn toàn bề mặt. Khứa nhẹ các đường chéo hoặc cắt miếng vừa ăn dày 2–3cm để nhiệt và gia vị thấm sâu đều khắp bên trong. Quết đều thịt heo xay, giò sống, hành tím tỏi băm, nước mắm, hạt tiêu và 1 thìa dầu ăn rồi giữ lạnh ngăn mát 30 phút cho dai.',6,'Bề mặt nguyên liệu càng khô ráo thì khi chiên không bị văng dầu và khi nướng sẽ lên màu vàng ruộm giòn rụm cực đẹp.'),
(199,2,'Chuẩn bị hỗn hợp sốt ướp / bột áo chuẩn tỷ lệ','Phối trộn 80g sả và 20g tỏi băm thật nhuyễn (hoặc vắt lấy nước cốt thơm) cùng 25ml nước tương trong tô lớn cho quyện sánh đồng nhất. Nếu món có lớp vỏ bột hoặc bánh cuốn từ 220g giò sống và 220g thịt heo xay, trộn đều hỗn hợp theo đúng định lượng để đạt độ giòn xốp mỏng nhẹ chuẩn vị. Thoa chút dầu ăn vào tay, lấy nắm thịt bọc ôm quanh đầu củ sả đập dập nhẹ tạo hình thuôn dài.',6,'Vắt lấy nước cốt hành tỏi sả khi ướp đồ nướng giúp hương thơm thấm sâu mà không bị cháy đen phần xác băm trên lửa cao.'),
(199,3,'Ướp thấm thớ thịt / tạo hình cuốn khéo léo','Áo đều hỗn hợp gia vị hoặc lớp bột/vỏ cuốn quanh 220g giò sống và 220g thịt heo xay, massage nhẹ nhàng rồi để nghỉ 15–20 phút cho gia vị thẩm thấu trọn vẹn. Trường hợp cuốn chả/nem hoặc đổ khuôn bánh, thao tác đều tay vừa chặt để nhân kết dính nhưng không bị bục rách khi gặp nhiệt.',8,'Để nguyên liệu nghỉ đủ thời gian trước khi chiên nướng giúp lớp áo bột bám chắc và phần nhân bên trong mọng ngọt.'),
(199,4,'Pha nước chấm cân vị & sơ chế rau đồ chua ăn kèm','Nhặt rửa sạch 180g rau sống ngâm nước mát cho giòn tươi, bào sợi hoặc thái lát gọn gàng bày sẵn bên cạnh. Pha chén nước chấm chua ngọt hoặc muối ớt chanh sả sánh thơm theo khẩu vị vùng miền của món Nem lụi Huế nướng sả thơm nức để cân bằng độ béo giòn.',5,'Luôn chuẩn bị xong rau sống và bát nước chấm trước khi chiên/nướng mẻ cuối để món ăn vừa ra lò là thưởng thức nóng giòn ngay.'),
(199,5,'Làm nóng dầu / lò nướng chuẩn nhiệt & làm chín đều lần 1','Làm nóng chảo dầu hoặc vỉ nướng/nồi chiên ở mức nhiệt vừa khoảng 165–175°C, xếp 220g giò sống và 220g thịt heo xay vào với khoảng cách thoáng đều nhau. Chiên hoặc nướng trở mặt nhịp nhàng trên lửa vừa để nhiệt dẫn sâu làm chín mềm ngọt hoàn toàn phần nhân bên trong. Nướng nem lụi ở 190°C khoảng 15 phút (lật phết dầu hành giữa giờ). Song song phi tỏi băm nấu tương đen/tương đậu với nước lọc, đậu phộng giã nhuyễn và chút bột năng cho sệt bóng.',10,'Kiểm tra nhiệt dầu bằng đầu đũa tre thấy sủi tăm nhỏ đều là đạt chuẩn 170°C, giúp vỏ không cháy sớm khi bên trong còn sống.'),
(199,6,'Tăng nhiệt khóa giòn rụm vàng ươm bề mặt lần 2','Ở 2–3 phút cuối, tăng lên lửa vừa lớn (khoảng 190°C) hoặc phết thêm lớp dầu điều/mật ong mỏng để vỏ ngoài của Nem lụi Huế nướng sả thơm nức chuyển sắc vàng óng ánh và nổ giòn rụm. Lắng nghe tiếng xèo giòn rộn rã và hương thơm phức lan tỏa khắp bếp thì gắp ra vỉ thưa cho ráo dầu thừa.',5,'Đặt đồ chiên nướng lên giá inox thoáng khí thay vì giấy thấm dầu chồng khít để hơi nước thoát hết, giữ độ giòn lâu gấp 3 lần.');
INSERT INTO `recipe_steps` (`recipe_id`,`step_order`,`title`,`instruction`,`duration_mins`,`tip_note`) VALUES
(199,7,'Trình bày bắt mắt kèm rau thơm & thưởng thức nóng','Xếp thành phẩm vàng giòn ra đĩa lớn có bày sẵn 180g rau sống và điểm xuyết 60g đậu phộng tươi xanh hài hòa màu sắc. Dọn kèm chén nước chấm sánh đậm ngay chính giữa mâm ăn cho 4 người thưởng thức khi vỏ ngoài còn nóng giòn rụm. Cuốn nem lụi cùng rau sống, xoài xanh dưa leo trong bánh tráng mỏng, rút cây sả ra và chấm ngập nước lèo.',3,'Cắt miếng hoặc dọn ăn ngay trong vòng 10 phút sau khi rời bếp để cảm nhận trọn vẹn sự đối lập giòn ngoài - mềm ngọt bên trong.'),
(200,1,'Sơ chế & chần sạch nguyên liệu xương thịt, hải sản','Rửa sạch 200g thịt heo xay và 200g tôm sú với muối hạt rồi chần nhanh trong nồi nước sôi có đập dập 1 nhánh gừng trong 2–3 phút trên lửa lớn để loại bỏ hoàn toàn bọt bẩn. Rửa lại dưới làn nước sạch cho thật trắng trẻo, đồng thời nhặt rửa sạch 150g cải thìa để ráo nước. Tôm bóc vỏ băm dối (không xay nát để còn độ giòn), trộn đều với thịt heo xay, đầu hành băm, dầu mè, nước tương và tiêu xay.',6,'Bước chần sơ và rửa lại bằng nước ấm là bí quyết vàng giúp nồi nước dùng trong vắt, thơm thanh và không bao giờ bị đục hay hôi.'),
(200,2,'Nướng thơm thảo mộc & ninh nền nước dùng ngọt thanh','Cho phần nguyên liệu tạo ngọt từ 200g thịt heo xay và 200g tôm sú cùng hành tím và tỏi băm nhỏ đã nướng xém thơm vào nồi sâu lòng với khoảng 1.5–1.8 lít nước lọc. Đun sôi bùng trên lửa lớn rồi hạ ngay về lửa nhỏ liu riu, mở hé vung và hớt kỹ bọt nổi trên mặt để chiết xuất vị ngọt tự nhiên. Đặt 1 thìa cà phê nhân vào giữa lá hoành thánh mỏng (cán từ bột mì dẻo), phết nước lọc ở viền rồi túm gọn mép.',15,'Luôn duy trì mặt nước lăn tăn nhẹ thay vì đun sôi sùng sục lửa to để protein không bị nhũ hóa gây đục nước lèo.'),
(200,3,'Xào tạo màu & dậy hương đặc trưng vùng miền','Bắc chảo nhỏ lên bếp với 15ml dầu ăn trên lửa vừa, phi thơm phần hành tỏi sả băm còn lại rồi xào săn 150g bột mì cùng 20ml nước tương và 4g tiêu trong 3–4 phút. Khi hỗn hợp dậy mùi thơm nồng nàn và lên sắc màu óng ả đặc trưng của món Súp hoành thánh tôm thịt thanh nhẹ thì tắt bếp.',5,'Xào riêng phần nguyên liệu tạo màu và gia vị thơm trước khi trút vào nồi nước dùng giúp tầng hương dậy lên rõ nét gấp đôi.'),
(200,4,'Sơ chế & cắt thái phần nhân topping xếp tô','Vớt phần thịt hoặc hải sản chín tới từ 200g thịt heo xay và 200g tôm sú ra ngâm ngay vào âu nước đun sôi để nguội giúp bề mặt săn giòn mọng nước, không bị thâm khô. Thái lát mỏng đều tay dày khoảng 3mm ngang thớ hoặc gỡ miếng vừa ăn, sắp riêng từng phần gọn gàng trên đĩa.',5,'Thái thịt ngang thớ với lưỡi dao thật sắc giúp lát thịt mềm mướt, khi chan nước dùng sôi lên sẽ phẳng đẹp không bị quăn cứng.'),
(200,5,'Hợp nhất nồi nước lèo & nêm chuẩn định lượng','Trút phần sốt màu thơm vào nồi nước dùng đang sôi lăn tăn, nêm chính xác lượng 20ml nước tương và 4g tiêu còn lại cho vừa miệng 4 người ăn. Đun nhẹ thêm 5 phút ở lửa vừa để các tầng vị mặn dịu, ngọt hậu từ xương thịt và thảo mộc hòa quyện tròn trịa. Luộc từng đợt hoành thánh trong nước sôi vừa 3-4 phút đến khi nổi lên vỏ trong mềm thì vớt ra xếp vào tô; chần sơ cải thìa.',5,'Nên nêm nước mắm ngon ở giai đoạn cuối trên lửa nhỏ để giữ trọn hậu vị ngọt đạm và hương thơm mà không làm nước dùng bị chua.'),
(200,6,'Chần nóng sợi bánh/bún & chuẩn bị rau ăn kèm','Đun sôi một nồi nước riêng, cho phần sợi bún/phở/bánh trong 200g thịt heo xay và 200g tôm sú vào trụng nhanh 15–25 giây cho sợi mềm dẻo nóng hổi rồi vẩy thật ráo nước, chia đều vào 4 tô lớn. Chần sơ thêm rau ăn kèm (150g cải thìa) nếu muốn dùng chín giòn.',4,'Trụng bún bánh ở nồi nước sôi riêng biệt giúp nước dùng chính không bị nhiễm tinh bột chua và tô bún luôn ráo sợi, thấm vị.'),
(200,7,'Xếp nhân hài hòa, chan nước dùng sôi & thưởng thức','Xếp đều các phần nhân thịt, hải sản lên mặt tô bún bánh, điểm xuyết 30g hành lá lên trên cùng. Dùng muôi múc nước dùng đang sôi thật già chan ngập xăm xắp mặt nguyên liệu để làm chín thơm hành ngò, dọn nóng ngay kèm chanh ớt tươi. Nấu sôi nước dùng gà nêm thanh vừa ăn, chan ngập tô hoành thánh có cải thìa, rắc hành phi, hành lá, ngò và chút tiêu.',3,'Tráng nóng tô sứ bằng nước sôi trước khi xếp bún giúp tô món nước giữ nhiệt bốc khói nghi ngút suốt bữa ăn.'),
(201,1,'Sơ chế & chần sạch nguyên liệu xương thịt, hải sản','Rửa sạch 350g thịt gà (ức) và 600g bún tươi với muối hạt rồi chần nhanh trong nồi nước sôi có đập dập 1 nhánh gừng trong 2–3 phút trên lửa lớn để loại bỏ hoàn toàn bọt bẩn. Rửa lại dưới làn nước sạch cho thật trắng trẻo, đồng thời nhặt rửa sạch 120g củ cải trắng để ráo nước.',12,'Bước chần sơ và rửa lại bằng nước ấm là bí quyết vàng giúp nồi nước dùng trong vắt, thơm thanh và không bao giờ bị đục hay hôi.'),
(201,2,'Nướng thơm thảo mộc & ninh nền nước dùng ngọt thanh','Cho phần nguyên liệu tạo ngọt từ 350g thịt gà (ức) và 600g bún tươi cùng hành tím và tỏi băm nhỏ đã nướng xém thơm vào nồi sâu lòng với khoảng 1.5–1.8 lít nước lọc. Đun sôi bùng trên lửa lớn rồi hạ ngay về lửa nhỏ liu riu, mở hé vung và hớt kỹ bọt nổi trên mặt để chiết xuất vị ngọt tự nhiên.',28,'Luôn duy trì mặt nước lăn tăn nhẹ thay vì đun sôi sùng sục lửa to để protein không bị nhũ hóa gây đục nước lèo.'),
(201,3,'Xào tạo màu & dậy hương đặc trưng vùng miền','Bắc chảo nhỏ lên bếp với 15ml dầu ăn trên lửa vừa, phi thơm phần hành tỏi sả băm còn lại rồi xào săn 3 quả trứng gà và 150g chả lụa cùng 25ml nước mắm trong 3–4 phút. Khi hỗn hợp dậy mùi thơm nồng nàn và lên sắc màu óng ả đặc trưng của món Bún thang Hà Nội tinh hoa phố cổ thì tắt bếp.',10,'Xào riêng phần nguyên liệu tạo màu và gia vị thơm trước khi trút vào nồi nước dùng giúp tầng hương dậy lên rõ nét gấp đôi.'),
(201,4,'Sơ chế & cắt thái phần nhân topping xếp tô','Vớt phần thịt hoặc hải sản chín tới từ 350g thịt gà (ức) và 600g bún tươi ra ngâm ngay vào âu nước đun sôi để nguội giúp bề mặt săn giòn mọng nước, không bị thâm khô. Thái lát mỏng đều tay dày khoảng 3mm ngang thớ hoặc gỡ miếng vừa ăn, sắp riêng từng phần gọn gàng trên đĩa.',10,'Thái thịt ngang thớ với lưỡi dao thật sắc giúp lát thịt mềm mướt, khi chan nước dùng sôi lên sẽ phẳng đẹp không bị quăn cứng.'),
(201,5,'Hợp nhất nồi nước lèo & nêm chuẩn định lượng','Trút phần sốt màu thơm vào nồi nước dùng đang sôi lăn tăn, nêm chính xác lượng 25ml nước mắm còn lại cho vừa miệng 4 người ăn. Đun nhẹ thêm 5 phút ở lửa vừa để các tầng vị mặn dịu, ngọt hậu từ xương thịt và thảo mộc hòa quyện tròn trịa.',10,'Nên nêm nước mắm ngon ở giai đoạn cuối trên lửa nhỏ để giữ trọn hậu vị ngọt đạm và hương thơm mà không làm nước dùng bị chua.'),
(201,6,'Chần nóng sợi bánh/bún & chuẩn bị rau ăn kèm','Đun sôi một nồi nước riêng, cho phần sợi bún/phở/bánh trong 350g thịt gà (ức) và 600g bún tươi vào trụng nhanh 15–25 giây cho sợi mềm dẻo nóng hổi rồi vẩy thật ráo nước, chia đều vào 4 tô lớn. Chần sơ thêm rau ăn kèm (120g củ cải trắng) nếu muốn dùng chín giòn.',8,'Trụng bún bánh ở nồi nước sôi riêng biệt giúp nước dùng chính không bị nhiễm tinh bột chua và tô bún luôn ráo sợi, thấm vị.'),
(201,7,'Xếp nhân hài hòa, chan nước dùng sôi & thưởng thức','Xếp đều các phần nhân thịt, hải sản lên mặt tô bún bánh, điểm xuyết 25g rau răm lên trên cùng. Dùng muôi múc nước dùng đang sôi thật già chan ngập xăm xắp mặt nguyên liệu để làm chín thơm hành ngò, dọn nóng ngay kèm chanh ớt tươi.',7,'Tráng nóng tô sứ bằng nước sôi trước khi xếp bún giúp tô món nước giữ nhiệt bốc khói nghi ngút suốt bữa ăn.'),
(202,1,'Sơ chế tươi sạch & ngâm giòn rau củ thảo mộc','Nhặt rửa kỹ 120g xà lách và 100g dưa leo cùng hành ngò và tiêu xay qua nước muối loãng rồi tráng nước đun sôi để nguội. Với các loại củ quả bào sợi hoặc thái lát mỏng, ngâm vào âu nước đá lạnh pha chút chanh đường trong 10 phút rồi vắt ráo để giữ độ trắng giòn sần sật.',7,'Rau củ làm gỏi và món cuốn phải quay rổ hoặc thấm thật ráo nước để khi trộn nước mắm không bị loãng nhạt.'),
(202,2,'Làm chín tới phần nhân đạm giữ trọn độ ngọt mọng','Xử lý phần nguyên liệu chính (500g bánh phở tươi và 300g thịt bò): luộc hấp cùng lát gừng sả đập dập hoặc xào lửa lớn vừa chín tới, sau đó làm nguội nhanh rồi thái lát mỏng / xé sợi đều đặn. Nếu món có pha bột bánh gạo/bột năng, khuấy tan bột với nước đúng tỷ lệ và để bột nghỉ 15 phút cho nở mịn.',8,'Ngâm tôm hoặc thịt luộc qua bát nước sôi để nguội có vài viên đá giúp màu sắc tươi hồng và thớ thịt giòn ngọt không bị khô.'),
(202,3,'Rang vàng đậu phộng mè thơm & phi hành tỏi giòn','Bắc chảo nhỏ lên lửa nhỏ, rang chín vàng thơm đậu phộng/mè hoặc làm mỡ hành xanh mướt và phi vàng giòn 20g tỏi. Vớt hành tỏi phi ra đĩa riêng để nguội giòn tan, giữ lại phần dầu thơm óng ánh để phết bánh hoặc rưới bóng mặt món ăn.',5,'Tắt bếp ngay khi hành phi chuyển vàng sáng vì nhiệt dư trong dầu nóng sẽ tiếp tục làm hành sẫm màu thêm một nấc hoàn hảo.'),
(202,4,'Pha nước mắm chấm / sốt trộn tỷ lệ vàng chua ngọt','Hòa tan hoàn toàn đường cùng 35ml nước mắm và 15ml chanh và nước ấm trong chén sâu lòng, khuấy đến khi hơi sánh nhẹ mới cho tỏi ớt băm nhuyễn và nước cốt chanh/tắc vào sau cùng. Công thức pha này giúp tỏi ớt nổi đều đẹp mắt trên bề mặt bát nước chấm chuẩn vị Phở cuốn thịt bò ngũ sắc Ngũ Xã.',5,'Băm tỏi ớt thật ráo trên thớt khô và cho vào sau khi đường mắm đã nguội thì tỏi ớt sẽ nổi bồng bềnh 100% không bị chìm đáy.'),
(202,5,'Phối trộn thấm vị / tráng hấp & cuốn đều tay','Tiến hành tráng hấp bánh mỏng mượt hoặc trải bánh cuốn gọn gàng 500g bánh phở tươi và 300g thịt bò cùng 120g xà lách và 100g dưa leo; nếu là món gỏi trộn thì rưới từ từ 2/3 lượng sốt chua ngọt vào bóp nhẹ tay cho thấm đều trong 3 phút. Giữ lực tay nhẹ nhàng để rau củ không bị dập nát mà vẫn ngấm trọn vị mặn chua ngọt hài hòa.',6,'Chia nước sốt gỏi làm 2 lần trộn và chắt bỏ phần nước tiết ra ở lần đầu giúp đĩa gỏi khô ráo, đậm đà như ngoài hàng.'),
(202,6,'Bày biện ngũ sắc hài hòa & rắc topping giòn bùi','Xếp món Phở cuốn thịt bò ngũ sắc Ngũ Xã ngay ngắn ra đĩa sứ trắng rộng, rải đều phần nhân tôm thịt sắc nét lên trên và rắc phủ hành ngò và tiêu xay thơm giòn. Dọn kèm chén nước chấm đậm đà cho 4 người thưởng thức ngay khi rau bánh còn tươi giòn mướt mịn.',4,'Chỉ rắc đậu phộng rang và hành phi ngay trước lúc mang ra bàn ăn để giữ nguyên độ giòn tan bùi béo.'),
(203,1,'Sơ chế sạch & cắt thái nguyên liệu đúng kích cỡ','Rửa sạch 500g ốc bươu và 300g chuối xanh cùng 200g đậu hũ và 150g thịt ba chỉ dưới vòi nước mát rồi để thật ráo trên rổ thưa. Dùng dao sắc cắt thái nguyên liệu thành từng khúc hoặc khối vuông đều đặn khoảng 3.5–4cm để khi kho hầm giữ nguyên hình dáng đẹp mắt mà không bị vụn nát.',8,'Cắt miếng thịt/cá dày dặn đồng đều giúp quá trình kho lâu trên lửa nhỏ thớ thịt mềm rục mà vẫn giữ trọn độ mọng ngọt bên trong.'),
(203,2,'Khử mùi tự nhiên & làm săn sạch bề mặt nguyên liệu','Chà nhẹ phần đạm chính trong 500g ốc bươu và 300g chuối xanh với chút muối hạt, lát gừng đập dập hoặc chần sơ qua nước sôi 90 giây rồi rửa sạch lại bằng nước ấm, để ráo hoàn toàn. Công đoạn này loại bỏ triệt để tạp chất và mùi tanh hôi, giúp nước sốt món Ốc om chuối đậu tía tô Hà Nội trong bóng thơm ngon.',6,'Sau khi chần hoặc rửa sạch, để nguyên liệu ráo nước ít nhất 5 phút trước khi ướp để gia vị rút sâu trực tiếp vào từng thớ thịt.'),
(203,3,'Pha hỗn hợp gia vị & ướp thấm chuẩn định lượng','Cho 500g ốc bươu và 300g chuối xanh vào tô lớn, ướp cùng một nửa 25g nghệ băm nhỏ và định lượng chuẩn 50g mẻ chua, đảo nhẹ tay cho gia vị phủ kín đều các mặt. Bọc kín tô và để nguyên liệu nghỉ thấm vị tối thiểu 20 phút ở nhiệt độ phòng (hoặc ngăn mát tủ lạnh).',8,'Ướp đủ tối thiểu 20 phút trước khi bắc lên bếp là chìa khóa để tâm miếng thịt/cá đậm đà đồng nhất với lớp sốt bên ngoài.'),
(203,4,'Thắng nước màu cánh gián & phi dậy hương hành tỏi','Đặt nồi đáy dày lên bếp ở lửa vừa nhỏ, thắng nhẹ 15g đường với 15ml dầu ăn đến khi chuyển sắc nâu cánh gián óng ả thì cho ngay phần 25g nghệ còn lại vào phi thơm lừng. Hương caramel dịu ngọt quyện cùng tinh dầu hành tỏi sả tạo nền màu nâu hổ phách truyền thống đầy cuốn hút.',6,'Canh kỹ khoảnh khắc đường vừa chuyển màu cánh gián là hạ lửa nhỏ nhất ngay để nước màu bóng đẹp mà không bao giờ bị đắng.');
INSERT INTO `recipe_steps` (`recipe_id`,`step_order`,`title`,`instruction`,`duration_mins`,`tip_note`) VALUES
(203,5,'Đảo săn hai mặt khóa ngọt nguyên liệu chính','Tăng lên lửa vừa lớn, gắp từng miếng trong 500g ốc bươu và 300g chuối xanh vào nồi đảo đều hoặc trở nhẹ hai mặt trong 4–5 phút cho săn chắc và bám đều lớp màu nâu óng. Khi bề mặt nguyên liệu se vàng thơm phức mới trút phần nước ướp còn lại trong tô vào đun sôi nhẹ.',8,'Đối với cá kho, chỉ lật cá một lần lúc cá vừa săn mặt trên lửa vừa để khúc cá nguyên vẹn không bị tróc da hay vỡ nát.'),
(203,6,'Kho/om liu riu lửa nhỏ thấm đẫm cùng nước dừa/nước dùng','Chế lượng nước vừa ngập mặt nguyên liệu xâm xắp mặt nguyên liệu (xếp thêm rau củ ăn kèm nếu có), đun sôi bùng một dạo hớt sạch bọt rồi hạ ngay về mức lửa nhỏ liu riu nhất. Kho êm đềm không đậy kín nắp để từng thớ nguyên liệu chín mềm thấm đẫm gia vị và nước sốt rút dần sóng sánh.',13,'Luôn dùng nước sôi hoặc nước dừa ấm khi châm thêm vào nồi kho đang nóng để thịt cá không bị sượng cứng trở lại.'),
(203,7,'Thu sánh nước sốt óng ả & trình bày thưởng thức nóng','Khi nước kho rút còn khoảng 1/3 sánh kẹo óng ánh áo đều quanh nguyên liệu và xiên đũa thấy mềm mọng vừa ý, rắc 35g tía tô và 25g lá lốt lên mặt rồi tắt bếp. Múc món Ốc om chuối đậu tía tô Hà Nội ra đĩa sâu lòng hoặc niêu đất giữ nhiệt, dọn ăn nóng cùng cơm trắng dẻo thơm cho 4 người.',6,'Giữ lại một lượng nước sốt sánh kẹo vừa đủ dưới đáy nồi để chan cơm hoặc chấm kèm rau luộc sẽ tròn vị đưa cơm gấp bội.'),
(204,1,'Sơ chế & chần sạch nguyên liệu xương thịt, hải sản','Rửa sạch 400g bánh đa đỏ và 400g cua đồng xay với muối hạt rồi chần nhanh trong nồi nước sôi có đập dập 1 nhánh gừng trong 2–3 phút trên lửa lớn để loại bỏ hoàn toàn bọt bẩn. Rửa lại dưới làn nước sạch cho thật trắng trẻo, đồng thời nhặt rửa sạch 200g rau muống để ráo nước.',8,'Bước chần sơ và rửa lại bằng nước ấm là bí quyết vàng giúp nồi nước dùng trong vắt, thơm thanh và không bao giờ bị đục hay hôi.'),
(204,2,'Nướng thơm thảo mộc & ninh nền nước dùng ngọt thanh','Cho phần nguyên liệu tạo ngọt từ 400g bánh đa đỏ và 400g cua đồng xay cùng hành tím và tỏi băm nhỏ đã nướng xém thơm vào nồi sâu lòng với khoảng 1.5–1.8 lít nước lọc. Đun sôi bùng trên lửa lớn rồi hạ ngay về lửa nhỏ liu riu, mở hé vung và hớt kỹ bọt nổi trên mặt để chiết xuất vị ngọt tự nhiên.',20,'Luôn duy trì mặt nước lăn tăn nhẹ thay vì đun sôi sùng sục lửa to để protein không bị nhũ hóa gây đục nước lèo.'),
(204,3,'Xào tạo màu & dậy hương đặc trưng vùng miền','Bắc chảo nhỏ lên bếp với 15ml dầu ăn trên lửa vừa, phi thơm phần hành tỏi sả băm còn lại rồi xào săn 150g thịt heo xay và 150g tôm sú cùng gia vị chuẩn định lượng trong 3–4 phút. Khi hỗn hợp dậy mùi thơm nồng nàn và lên sắc màu óng ả đặc trưng của món Bánh đa cua đồng Hải Phòng chuẩn vị thì tắt bếp.',7,'Xào riêng phần nguyên liệu tạo màu và gia vị thơm trước khi trút vào nồi nước dùng giúp tầng hương dậy lên rõ nét gấp đôi.'),
(204,4,'Sơ chế & cắt thái phần nhân topping xếp tô','Vớt phần thịt hoặc hải sản chín tới từ 400g bánh đa đỏ và 400g cua đồng xay ra ngâm ngay vào âu nước đun sôi để nguội giúp bề mặt săn giòn mọng nước, không bị thâm khô. Thái lát mỏng đều tay dày khoảng 3mm ngang thớ hoặc gỡ miếng vừa ăn, sắp riêng từng phần gọn gàng trên đĩa.',7,'Thái thịt ngang thớ với lưỡi dao thật sắc giúp lát thịt mềm mướt, khi chan nước dùng sôi lên sẽ phẳng đẹp không bị quăn cứng.'),
(204,5,'Hợp nhất nồi nước lèo & nêm chuẩn định lượng','Trút phần sốt màu thơm vào nồi nước dùng đang sôi lăn tăn, nêm chính xác lượng gia vị chuẩn định lượng còn lại cho vừa miệng 4 người ăn. Đun nhẹ thêm 5 phút ở lửa vừa để các tầng vị mặn dịu, ngọt hậu từ xương thịt và thảo mộc hòa quyện tròn trịa.',7,'Nên nêm nước mắm ngon ở giai đoạn cuối trên lửa nhỏ để giữ trọn hậu vị ngọt đạm và hương thơm mà không làm nước dùng bị chua.'),
(204,6,'Chần nóng sợi bánh/bún & chuẩn bị rau ăn kèm','Đun sôi một nồi nước riêng, cho phần sợi bún/phở/bánh trong 400g bánh đa đỏ và 400g cua đồng xay vào trụng nhanh 15–25 giây cho sợi mềm dẻo nóng hổi rồi vẩy thật ráo nước, chia đều vào 4 tô lớn. Chần sơ thêm rau ăn kèm (200g rau muống) nếu muốn dùng chín giòn.',6,'Trụng bún bánh ở nồi nước sôi riêng biệt giúp nước dùng chính không bị nhiễm tinh bột chua và tô bún luôn ráo sợi, thấm vị.'),
(204,7,'Xếp nhân hài hòa, chan nước dùng sôi & thưởng thức','Xếp đều các phần nhân thịt, hải sản lên mặt tô bún bánh, điểm xuyết 30g lá lốt và 20g hành phi lên trên cùng. Dùng muôi múc nước dùng đang sôi thật già chan ngập xăm xắp mặt nguyên liệu để làm chín thơm hành ngò, dọn nóng ngay kèm chanh ớt tươi.',5,'Tráng nóng tô sứ bằng nước sôi trước khi xếp bún giúp tô món nước giữ nhiệt bốc khói nghi ngút suốt bữa ăn.'),
(205,1,'Sơ chế sạch & thấm thật khô bề mặt nguyên liệu','Rửa sạch 200g thịt cua và 200g thịt heo xay cùng chút muối loãng để khử mùi tự nhiên, sau đó dùng khăn giấy bếp thấm thật khô ráo hoàn toàn bề mặt. Khứa nhẹ các đường chéo hoặc cắt miếng vừa ăn dày 2–3cm để nhiệt và gia vị thấm sâu đều khắp bên trong.',8,'Bề mặt nguyên liệu càng khô ráo thì khi chiên không bị văng dầu và khi nướng sẽ lên màu vàng ruộm giòn rụm cực đẹp.'),
(205,2,'Chuẩn bị hỗn hợp sốt ướp / bột áo chuẩn tỷ lệ','Phối trộn hành tím và tỏi băm nhỏ băm thật nhuyễn (hoặc vắt lấy nước cốt thơm) cùng gia vị chuẩn định lượng trong tô lớn cho quyện sánh đồng nhất. Nếu món có lớp vỏ bột hoặc bánh cuốn từ 200g thịt cua và 200g thịt heo xay, trộn đều hỗn hợp theo đúng định lượng để đạt độ giòn xốp mỏng nhẹ chuẩn vị.',7,'Vắt lấy nước cốt hành tỏi sả khi ướp đồ nướng giúp hương thơm thấm sâu mà không bị cháy đen phần xác băm trên lửa cao.'),
(205,3,'Ướp thấm thớ thịt / tạo hình cuốn khéo léo','Áo đều hỗn hợp gia vị hoặc lớp bột/vỏ cuốn quanh 200g thịt cua và 200g thịt heo xay, massage nhẹ nhàng rồi để nghỉ 15–20 phút cho gia vị thẩm thấu trọn vẹn. Trường hợp cuốn chả/nem hoặc đổ khuôn bánh, thao tác đều tay vừa chặt để nhân kết dính nhưng không bị bục rách khi gặp nhiệt.',9,'Để nguyên liệu nghỉ đủ thời gian trước khi chiên nướng giúp lớp áo bột bám chắc và phần nhân bên trong mọng ngọt.'),
(205,4,'Pha nước chấm cân vị & sơ chế rau đồ chua ăn kèm','Nhặt rửa sạch rau củ ăn kèm ngâm nước mát cho giòn tươi, bào sợi hoặc thái lát gọn gàng bày sẵn bên cạnh. Pha chén nước chấm chua ngọt hoặc muối ớt chanh sả sánh thơm theo khẩu vị vùng miền của món Nem cua bể vuông Hải Phòng chiên giòn để cân bằng độ béo giòn.',6,'Luôn chuẩn bị xong rau sống và bát nước chấm trước khi chiên/nướng mẻ cuối để món ăn vừa ra lò là thưởng thức nóng giòn ngay.'),
(205,5,'Làm nóng dầu / lò nướng chuẩn nhiệt & làm chín đều lần 1','Làm nóng chảo dầu hoặc vỉ nướng/nồi chiên ở mức nhiệt vừa khoảng 165–175°C, xếp 200g thịt cua và 200g thịt heo xay vào với khoảng cách thoáng đều nhau. Chiên hoặc nướng trở mặt nhịp nhàng trên lửa vừa để nhiệt dẫn sâu làm chín mềm ngọt hoàn toàn phần nhân bên trong.',10,'Kiểm tra nhiệt dầu bằng đầu đũa tre thấy sủi tăm nhỏ đều là đạt chuẩn 170°C, giúp vỏ không cháy sớm khi bên trong còn sống.'),
(205,6,'Tăng nhiệt khóa giòn rụm vàng ươm bề mặt lần 2','Ở 2–3 phút cuối, tăng lên lửa vừa lớn (khoảng 190°C) hoặc phết thêm lớp dầu điều/mật ong mỏng để vỏ ngoài của Nem cua bể vuông Hải Phòng chiên giòn chuyển sắc vàng óng ánh và nổ giòn rụm. Lắng nghe tiếng xèo giòn rộn rã và hương thơm phức lan tỏa khắp bếp thì gắp ra vỉ thưa cho ráo dầu thừa.',6,'Đặt đồ chiên nướng lên giá inox thoáng khí thay vì giấy thấm dầu chồng khít để hơi nước thoát hết, giữ độ giòn lâu gấp 3 lần.'),
(205,7,'Trình bày bắt mắt kèm rau thơm & thưởng thức nóng','Xếp thành phẩm vàng giòn ra đĩa lớn có bày sẵn rau củ ăn kèm và điểm xuyết hành ngò và tiêu xay tươi xanh hài hòa màu sắc. Dọn kèm chén nước chấm sánh đậm ngay chính giữa mâm ăn cho 4 người thưởng thức khi vỏ ngoài còn nóng giòn rụm.',4,'Cắt miếng hoặc dọn ăn ngay trong vòng 10 phút sau khi rời bếp để cảm nhận trọn vẹn sự đối lập giòn ngoài - mềm ngọt bên trong.'),
(206,1,'Sơ chế sạch & cắt thái nguyên liệu đúng kích cỡ','Rửa sạch 800g cá trắm và 200g thịt ba chỉ cùng các nguyên liệu phối kèm dưới vòi nước mát rồi để thật ráo trên rổ thưa. Dùng dao sắc cắt thái nguyên liệu thành từng khúc hoặc khối vuông đều đặn khoảng 3.5–4cm để khi kho hầm giữ nguyên hình dáng đẹp mắt mà không bị vụn nát.',16,'Cắt miếng thịt/cá dày dặn đồng đều giúp quá trình kho lâu trên lửa nhỏ thớ thịt mềm rục mà vẫn giữ trọn độ mọng ngọt bên trong.'),
(206,2,'Khử mùi tự nhiên & làm săn sạch bề mặt nguyên liệu','Chà nhẹ phần đạm chính trong 800g cá trắm và 200g thịt ba chỉ với chút muối hạt, lát gừng đập dập hoặc chần sơ qua nước sôi 90 giây rồi rửa sạch lại bằng nước ấm, để ráo hoàn toàn. Công đoạn này loại bỏ triệt để tạp chất và mùi tanh hôi, giúp nước sốt món Cá trắm kho riềng làng Vũ Đại Hà Nam trong bóng thơm ngon.',13,'Sau khi chần hoặc rửa sạch, để nguyên liệu ráo nước ít nhất 5 phút trước khi ướp để gia vị rút sâu trực tiếp vào từng thớ thịt.'),
(206,3,'Pha hỗn hợp gia vị & ướp thấm chuẩn định lượng','Cho 800g cá trắm và 200g thịt ba chỉ vào tô lớn, ướp cùng một nửa 120g riềng tươi và 40g gừng băm nhỏ và định lượng chuẩn 50ml nước mắm, 25g đường và 10g ớt, đảo nhẹ tay cho gia vị phủ kín đều các mặt. Bọc kín tô và để nguyên liệu nghỉ thấm vị tối thiểu 20 phút ở nhiệt độ phòng (hoặc ngăn mát tủ lạnh).',17,'Ướp đủ tối thiểu 20 phút trước khi bắc lên bếp là chìa khóa để tâm miếng thịt/cá đậm đà đồng nhất với lớp sốt bên ngoài.'),
(206,4,'Thắng nước màu cánh gián & phi dậy hương hành tỏi','Đặt nồi đáy dày lên bếp ở lửa vừa nhỏ, thắng nhẹ 15g đường với 15ml dầu ăn đến khi chuyển sắc nâu cánh gián óng ả thì cho ngay phần 120g riềng tươi và 40g gừng còn lại vào phi thơm lừng. Hương caramel dịu ngọt quyện cùng tinh dầu hành tỏi sả tạo nền màu nâu hổ phách truyền thống đầy cuốn hút.',12,'Canh kỹ khoảnh khắc đường vừa chuyển màu cánh gián là hạ lửa nhỏ nhất ngay để nước màu bóng đẹp mà không bao giờ bị đắng.'),
(206,5,'Đảo săn hai mặt khóa ngọt nguyên liệu chính','Tăng lên lửa vừa lớn, gắp từng miếng trong 800g cá trắm và 200g thịt ba chỉ vào nồi đảo đều hoặc trở nhẹ hai mặt trong 4–5 phút cho săn chắc và bám đều lớp màu nâu óng. Khi bề mặt nguyên liệu se vàng thơm phức mới trút phần nước ướp còn lại trong tô vào đun sôi nhẹ.',16,'Đối với cá kho, chỉ lật cá một lần lúc cá vừa săn mặt trên lửa vừa để khúc cá nguyên vẹn không bị tróc da hay vỡ nát.'),
(206,6,'Kho/om liu riu lửa nhỏ thấm đẫm cùng nước dừa/nước dùng','Chế 300ml nước dừa tươi xâm xắp mặt nguyên liệu (xếp thêm rau củ ăn kèm nếu có), đun sôi bùng một dạo hớt sạch bọt rồi hạ ngay về mức lửa nhỏ liu riu nhất. Kho êm đềm không đậy kín nắp để từng thớ nguyên liệu chín mềm thấm đẫm gia vị và nước sốt rút dần sóng sánh.',29,'Luôn dùng nước sôi hoặc nước dừa ấm khi châm thêm vào nồi kho đang nóng để thịt cá không bị sượng cứng trở lại.'),
(206,7,'Thu sánh nước sốt óng ả & trình bày thưởng thức nóng','Khi nước kho rút còn khoảng 1/3 sánh kẹo óng ánh áo đều quanh nguyên liệu và xiên đũa thấy mềm mọng vừa ý, rắc hành ngò và tiêu xay lên mặt rồi tắt bếp. Múc món Cá trắm kho riềng làng Vũ Đại Hà Nam ra đĩa sâu lòng hoặc niêu đất giữ nhiệt, dọn ăn nóng cùng cơm trắng dẻo thơm cho 4 người.',12,'Giữ lại một lượng nước sốt sánh kẹo vừa đủ dưới đáy nồi để chan cơm hoặc chấm kèm rau luộc sẽ tròn vị đưa cơm gấp bội.'),
(207,1,'Sơ chế & chần sạch nguyên liệu xương thịt, hải sản','Rửa sạch 350g thịt bò và 600g bánh phở tươi với muối hạt rồi chần nhanh trong nồi nước sôi có đập dập 1 nhánh gừng trong 2–3 phút trên lửa lớn để loại bỏ hoàn toàn bọt bẩn. Rửa lại dưới làn nước sạch cho thật trắng trẻo, đồng thời nhặt rửa sạch 40g hành lá để ráo nước.',13,'Bước chần sơ và rửa lại bằng nước ấm là bí quyết vàng giúp nồi nước dùng trong vắt, thơm thanh và không bao giờ bị đục hay hôi.');
INSERT INTO `recipe_steps` (`recipe_id`,`step_order`,`title`,`instruction`,`duration_mins`,`tip_note`) VALUES
(207,2,'Nướng thơm thảo mộc & ninh nền nước dùng ngọt thanh','Cho phần nguyên liệu tạo ngọt từ 350g thịt bò và 600g bánh phở tươi cùng 30g tỏi, 30g gừng và 5g hoa hồi đã nướng xém thơm vào nồi sâu lòng với khoảng 1.5–1.8 lít nước lọc. Đun sôi bùng trên lửa lớn rồi hạ ngay về lửa nhỏ liu riu, mở hé vung và hớt kỹ bọt nổi trên mặt để chiết xuất vị ngọt tự nhiên.',28,'Luôn duy trì mặt nước lăn tăn nhẹ thay vì đun sôi sùng sục lửa to để protein không bị nhũ hóa gây đục nước lèo.'),
(207,3,'Xào tạo màu & dậy hương đặc trưng vùng miền','Bắc chảo nhỏ lên bếp với 15ml dầu ăn trên lửa vừa, phi thơm phần hành tỏi sả băm còn lại rồi xào săn 200g thịt bò bắp cùng gia vị chuẩn định lượng trong 3–4 phút. Khi hỗn hợp dậy mùi thơm nồng nàn và lên sắc màu óng ả đặc trưng của món Phở bò tái lăn Hà Nội dậy mùi tỏi thì tắt bếp.',11,'Xào riêng phần nguyên liệu tạo màu và gia vị thơm trước khi trút vào nồi nước dùng giúp tầng hương dậy lên rõ nét gấp đôi.'),
(207,4,'Sơ chế & cắt thái phần nhân topping xếp tô','Vớt phần thịt hoặc hải sản chín tới từ 350g thịt bò và 600g bánh phở tươi ra ngâm ngay vào âu nước đun sôi để nguội giúp bề mặt săn giòn mọng nước, không bị thâm khô. Thái lát mỏng đều tay dày khoảng 3mm ngang thớ hoặc gỡ miếng vừa ăn, sắp riêng từng phần gọn gàng trên đĩa.',11,'Thái thịt ngang thớ với lưỡi dao thật sắc giúp lát thịt mềm mướt, khi chan nước dùng sôi lên sẽ phẳng đẹp không bị quăn cứng.'),
(207,5,'Hợp nhất nồi nước lèo & nêm chuẩn định lượng','Trút phần sốt màu thơm vào nồi nước dùng đang sôi lăn tăn, nêm chính xác lượng gia vị chuẩn định lượng còn lại cho vừa miệng 4 người ăn. Đun nhẹ thêm 5 phút ở lửa vừa để các tầng vị mặn dịu, ngọt hậu từ xương thịt và thảo mộc hòa quyện tròn trịa.',11,'Nên nêm nước mắm ngon ở giai đoạn cuối trên lửa nhỏ để giữ trọn hậu vị ngọt đạm và hương thơm mà không làm nước dùng bị chua.'),
(207,6,'Chần nóng sợi bánh/bún & chuẩn bị rau ăn kèm','Đun sôi một nồi nước riêng, cho phần sợi bún/phở/bánh trong 350g thịt bò và 600g bánh phở tươi vào trụng nhanh 15–25 giây cho sợi mềm dẻo nóng hổi rồi vẩy thật ráo nước, chia đều vào 4 tô lớn. Chần sơ thêm rau ăn kèm (giá đỗ, rau xanh) nếu muốn dùng chín giòn.',9,'Trụng bún bánh ở nồi nước sôi riêng biệt giúp nước dùng chính không bị nhiễm tinh bột chua và tô bún luôn ráo sợi, thấm vị.'),
(207,7,'Xếp nhân hài hòa, chan nước dùng sôi & thưởng thức','Xếp đều các phần nhân thịt, hải sản lên mặt tô bún bánh, điểm xuyết 40g hành lá lên trên cùng. Dùng muôi múc nước dùng đang sôi thật già chan ngập xăm xắp mặt nguyên liệu để làm chín thơm hành ngò, dọn nóng ngay kèm chanh ớt tươi.',7,'Tráng nóng tô sứ bằng nước sôi trước khi xếp bún giúp tô món nước giữ nhiệt bốc khói nghi ngút suốt bữa ăn.'),
(208,1,'Sơ chế sạch & thấm thật khô bề mặt nguyên liệu','Rửa sạch 600g mực ống và 80g giò sống cùng chút muối loãng để khử mùi tự nhiên, sau đó dùng khăn giấy bếp thấm thật khô ráo hoàn toàn bề mặt. Khứa nhẹ các đường chéo hoặc cắt miếng vừa ăn dày 2–3cm để nhiệt và gia vị thấm sâu đều khắp bên trong.',8,'Bề mặt nguyên liệu càng khô ráo thì khi chiên không bị văng dầu và khi nướng sẽ lên màu vàng ruộm giòn rụm cực đẹp.'),
(208,2,'Chuẩn bị hỗn hợp sốt ướp / bột áo chuẩn tỷ lệ','Phối trộn 15g tỏi và 20g hành tím băm thật nhuyễn (hoặc vắt lấy nước cốt thơm) cùng 18ml nước mắm và 5g tiêu trong tô lớn cho quyện sánh đồng nhất. Nếu món có lớp vỏ bột hoặc bánh cuốn từ 600g mực ống và 80g giò sống, trộn đều hỗn hợp theo đúng định lượng để đạt độ giòn xốp mỏng nhẹ chuẩn vị.',7,'Vắt lấy nước cốt hành tỏi sả khi ướp đồ nướng giúp hương thơm thấm sâu mà không bị cháy đen phần xác băm trên lửa cao.'),
(208,3,'Ướp thấm thớ thịt / tạo hình cuốn khéo léo','Áo đều hỗn hợp gia vị hoặc lớp bột/vỏ cuốn quanh 600g mực ống và 80g giò sống, massage nhẹ nhàng rồi để nghỉ 15–20 phút cho gia vị thẩm thấu trọn vẹn. Trường hợp cuốn chả/nem hoặc đổ khuôn bánh, thao tác đều tay vừa chặt để nhân kết dính nhưng không bị bục rách khi gặp nhiệt.',9,'Để nguyên liệu nghỉ đủ thời gian trước khi chiên nướng giúp lớp áo bột bám chắc và phần nhân bên trong mọng ngọt.'),
(208,4,'Pha nước chấm cân vị & sơ chế rau đồ chua ăn kèm','Nhặt rửa sạch rau củ ăn kèm ngâm nước mát cho giòn tươi, bào sợi hoặc thái lát gọn gàng bày sẵn bên cạnh. Pha chén nước chấm chua ngọt hoặc muối ớt chanh sả sánh thơm theo khẩu vị vùng miền của món Chả mực giã tay Hạ Long Quảng Ninh để cân bằng độ béo giòn.',6,'Luôn chuẩn bị xong rau sống và bát nước chấm trước khi chiên/nướng mẻ cuối để món ăn vừa ra lò là thưởng thức nóng giòn ngay.'),
(208,5,'Làm nóng dầu / lò nướng chuẩn nhiệt & làm chín đều lần 1','Làm nóng chảo dầu hoặc vỉ nướng/nồi chiên ở mức nhiệt vừa khoảng 165–175°C, xếp 600g mực ống và 80g giò sống vào với khoảng cách thoáng đều nhau. Chiên hoặc nướng trở mặt nhịp nhàng trên lửa vừa để nhiệt dẫn sâu làm chín mềm ngọt hoàn toàn phần nhân bên trong.',10,'Kiểm tra nhiệt dầu bằng đầu đũa tre thấy sủi tăm nhỏ đều là đạt chuẩn 170°C, giúp vỏ không cháy sớm khi bên trong còn sống.'),
(208,6,'Tăng nhiệt khóa giòn rụm vàng ươm bề mặt lần 2','Ở 2–3 phút cuối, tăng lên lửa vừa lớn (khoảng 190°C) hoặc phết thêm lớp dầu điều/mật ong mỏng để vỏ ngoài của Chả mực giã tay Hạ Long Quảng Ninh chuyển sắc vàng óng ánh và nổ giòn rụm. Lắng nghe tiếng xèo giòn rộn rã và hương thơm phức lan tỏa khắp bếp thì gắp ra vỉ thưa cho ráo dầu thừa.',6,'Đặt đồ chiên nướng lên giá inox thoáng khí thay vì giấy thấm dầu chồng khít để hơi nước thoát hết, giữ độ giòn lâu gấp 3 lần.'),
(208,7,'Trình bày bắt mắt kèm rau thơm & thưởng thức nóng','Xếp thành phẩm vàng giòn ra đĩa lớn có bày sẵn rau củ ăn kèm và điểm xuyết hành ngò và tiêu xay tươi xanh hài hòa màu sắc. Dọn kèm chén nước chấm sánh đậm ngay chính giữa mâm ăn cho 4 người thưởng thức khi vỏ ngoài còn nóng giòn rụm.',4,'Cắt miếng hoặc dọn ăn ngay trong vòng 10 phút sau khi rời bếp để cảm nhận trọn vẹn sự đối lập giòn ngoài - mềm ngọt bên trong.'),
(209,1,'Sơ chế & chần sạch nguyên liệu xương thịt, hải sản','Rửa sạch 400g cá trắm và 200g chả cá biển với muối hạt rồi chần nhanh trong nồi nước sôi có đập dập 1 nhánh gừng trong 2–3 phút trên lửa lớn để loại bỏ hoàn toàn bọt bẩn. Rửa lại dưới làn nước sạch cho thật trắng trẻo, đồng thời nhặt rửa sạch 25g thì là để ráo nước.',8,'Bước chần sơ và rửa lại bằng nước ấm là bí quyết vàng giúp nồi nước dùng trong vắt, thơm thanh và không bao giờ bị đục hay hôi.'),
(209,2,'Nướng thơm thảo mộc & ninh nền nước dùng ngọt thanh','Cho phần nguyên liệu tạo ngọt từ 400g cá trắm và 200g chả cá biển cùng hành tím và tỏi băm nhỏ đã nướng xém thơm vào nồi sâu lòng với khoảng 1.5–1.8 lít nước lọc. Đun sôi bùng trên lửa lớn rồi hạ ngay về lửa nhỏ liu riu, mở hé vung và hớt kỹ bọt nổi trên mặt để chiết xuất vị ngọt tự nhiên.',20,'Luôn duy trì mặt nước lăn tăn nhẹ thay vì đun sôi sùng sục lửa to để protein không bị nhũ hóa gây đục nước lèo.'),
(209,3,'Xào tạo màu & dậy hương đặc trưng vùng miền','Bắc chảo nhỏ lên bếp với 15ml dầu ăn trên lửa vừa, phi thơm phần hành tỏi sả băm còn lại rồi xào săn 600g bún tươi và 200g dọc mùng cùng 25g me vắt và 15g sa tế trong 3–4 phút. Khi hỗn hợp dậy mùi thơm nồng nàn và lên sắc màu óng ả đặc trưng của món Bún cá cay Hải Phòng dọc mùng giòn ngọt thì tắt bếp.',7,'Xào riêng phần nguyên liệu tạo màu và gia vị thơm trước khi trút vào nồi nước dùng giúp tầng hương dậy lên rõ nét gấp đôi.'),
(209,4,'Sơ chế & cắt thái phần nhân topping xếp tô','Vớt phần thịt hoặc hải sản chín tới từ 400g cá trắm và 200g chả cá biển ra ngâm ngay vào âu nước đun sôi để nguội giúp bề mặt săn giòn mọng nước, không bị thâm khô. Thái lát mỏng đều tay dày khoảng 3mm ngang thớ hoặc gỡ miếng vừa ăn, sắp riêng từng phần gọn gàng trên đĩa.',7,'Thái thịt ngang thớ với lưỡi dao thật sắc giúp lát thịt mềm mướt, khi chan nước dùng sôi lên sẽ phẳng đẹp không bị quăn cứng.'),
(209,5,'Hợp nhất nồi nước lèo & nêm chuẩn định lượng','Trút phần sốt màu thơm vào nồi nước dùng đang sôi lăn tăn, nêm chính xác lượng 25g me vắt và 15g sa tế còn lại cho vừa miệng 4 người ăn. Đun nhẹ thêm 5 phút ở lửa vừa để các tầng vị mặn dịu, ngọt hậu từ xương thịt và thảo mộc hòa quyện tròn trịa.',7,'Nên nêm nước mắm ngon ở giai đoạn cuối trên lửa nhỏ để giữ trọn hậu vị ngọt đạm và hương thơm mà không làm nước dùng bị chua.'),
(209,6,'Chần nóng sợi bánh/bún & chuẩn bị rau ăn kèm','Đun sôi một nồi nước riêng, cho phần sợi bún/phở/bánh trong 400g cá trắm và 200g chả cá biển vào trụng nhanh 15–25 giây cho sợi mềm dẻo nóng hổi rồi vẩy thật ráo nước, chia đều vào 4 tô lớn. Chần sơ thêm rau ăn kèm (giá đỗ, rau xanh) nếu muốn dùng chín giòn.',6,'Trụng bún bánh ở nồi nước sôi riêng biệt giúp nước dùng chính không bị nhiễm tinh bột chua và tô bún luôn ráo sợi, thấm vị.'),
(209,7,'Xếp nhân hài hòa, chan nước dùng sôi & thưởng thức','Xếp đều các phần nhân thịt, hải sản lên mặt tô bún bánh, điểm xuyết 25g thì là lên trên cùng. Dùng muôi múc nước dùng đang sôi thật già chan ngập xăm xắp mặt nguyên liệu để làm chín thơm hành ngò, dọn nóng ngay kèm chanh ớt tươi.',5,'Tráng nóng tô sứ bằng nước sôi trước khi xếp bún giúp tô món nước giữ nhiệt bốc khói nghi ngút suốt bữa ăn.'),
(210,1,'Vo đãi & ngâm nở hạt gạo/nếp đúng thời gian chuẩn','Đong chuẩn lượng gạo/nếp trong 450g gạo nếp và 200g đậu xanh cà vỏ, vo nhẹ tay 2–3 nước cho sạch bụi cám mà không làm mất lớp dưỡng chất ngoài vỏ hạt, để ráo trên rổ. Nếu là nếp đồ xôi, ngâm trước trong nước ấm hoặc nước màu thảo mộc tự nhiên cùng 3g muối để hạt nếp ngậm đủ nước căng tròn.',13,'Xóc nhẹ một nhúm muối tinh vào gạo nếp sau khi để ráo giúp hạt xôi cơm khi chín có vị đậm dịu và bóng dẻo tự nhiên.'),
(210,2,'Sơ chế & tẩm ướp phần nhân thịt, đậu ăn kèm','Làm sạch và chuẩn bị phần nguyên liệu ăn kèm gồm các nguyên liệu phối kèm cùng 80g hành tím và 20g nghệ, cắt thái gọn gàng đúng quy cách món Xôi xéo đậu xanh hành phi mỡ gà Hà Nội. Ướp thấm nhân với 5g muối trong 15 phút để khi chế biến tạo điểm nhấn đậm đà quyện cùng hạt cơm xôi dẻo thơm.',11,'Chuẩn bị song song phần nhân topping trong lúc chờ nấu cơm/đồ xôi giúp tiết kiệm thời gian và mọi thành phần cùng nóng hổi.'),
(210,3,'Nấu cơm / đồ xôi canh chuẩn nhiệt & độ ẩm hạt','Cho gạo vào nấu với lượng nước luộc gà/nước dùng vừa khéo hoặc dàn đều nếp vào xửng hấp đã sôi sùng sục, chọc vài lỗ thoáng hơi trên bề mặt nếp. Duy trì lửa vừa ổn định để hơi nóng xuyên đều giúp hạt chín dẻo từ lõi mà bên ngoài vẫn ráo tơi óng ả.',18,'Lau khô nước đọng dưới nắp vung mỗi 10 phút khi đồ xôi giúp mặt xôi không bao giờ bị nhão ướt ở rìa xửng.'),
(210,4,'Chế biến chín vàng thơm phần nhân & mỡ hành phi','Bắc chảo lên lửa vừa, phi vàng giòn 80g hành tím và 20g nghệ lấy dầu thơm rồi chế biến chín tới phần nhân các nguyên liệu phối kèm cho lên màu bóng đẹp và dậy mùi đặc trưng. Trường hợp có đậu xanh hoặc trứng chả kèm theo, chế biến riêng từng phần để giữ trọn sắc màu và hương vị tinh tế.',13,'Rưới một thìa mỡ gà hoặc dầu hành phi vào xới nhẹ lúc cơm/xôi vừa chín tới giúp từng hạt căng bóng mượt mà lâu khô.'),
(210,5,'Pha nước mắm sốt rưới / đồ chua cân bằng vị béo','Pha chén nước sốt chan từ 5g muối khuấy tan sánh nhẹ hoặc trộn nhanh phần hành tím/dưa góp chua ngọt giòn mát đi kèm. Cân chỉnh hài hòa vị mặn ngọt chua thanh để tôn lên độ bùi dẻo của hạt gạo nếp Việt Nam.',8,'Nước mắm ăn kèm các món cơm gà, cơm tấm hay cơm trộn nên nấu sôi nhẹ với đường cho hơi sánh kẹo sẽ bám hạt cơm ngon hơn hẳn.');
INSERT INTO `recipe_steps` (`recipe_id`,`step_order`,`title`,`instruction`,`duration_mins`,`tip_note`) VALUES
(210,6,'Đơm khuôn đầy đặn, xếp nhân & thưởng thức nóng','Đơm cơm hoặc xôi nóng vào chén ép nhẹ rồi úp tròn ra 4 đĩa, xếp đều các lớp nhân, đồ chua và rắc hành ngò và tiêu xay lên trên cùng. Rưới nhẹ mỡ hành/nước sốt bóng bẩy và thưởng thức ngay khi hạt cơm xôi còn nóng dẻo thơm lừng.',7,'Tráng mỏng một lớp nước lọc hoặc dầu ăn vào lòng chén trước khi đơm cơm giúp úp ra đĩa tròn trịa sắc nét không dính hạt.'),
(211,1,'Sơ chế tươi sạch & ngâm giòn rau củ thảo mộc','Nhặt rửa kỹ rau củ ăn kèm cùng 25g hành phi qua nước muối loãng rồi tráng nước đun sôi để nguội. Với các loại củ quả bào sợi hoặc thái lát mỏng, ngâm vào âu nước đá lạnh pha chút chanh đường trong 10 phút rồi vắt ráo để giữ độ trắng giòn sần sật.',8,'Rau củ làm gỏi và món cuốn phải quay rổ hoặc thấm thật ráo nước để khi trộn nước mắm không bị loãng nhạt.'),
(211,2,'Làm chín tới phần nhân đạm giữ trọn độ ngọt mọng','Xử lý phần nguyên liệu chính (180g bột gạo và 40g bột năng): luộc hấp cùng lát gừng sả đập dập hoặc xào lửa lớn vừa chín tới, sau đó làm nguội nhanh rồi thái lát mỏng / xé sợi đều đặn. Nếu món có pha bột bánh gạo/bột năng, khuấy tan bột với nước đúng tỷ lệ và để bột nghỉ 15 phút cho nở mịn.',9,'Ngâm tôm hoặc thịt luộc qua bát nước sôi để nguội có vài viên đá giúp màu sắc tươi hồng và thớ thịt giòn ngọt không bị khô.'),
(211,3,'Rang vàng đậu phộng mè thơm & phi hành tỏi giòn','Bắc chảo nhỏ lên lửa nhỏ, rang chín vàng thơm đậu phộng/mè hoặc làm mỡ hành xanh mướt và phi vàng giòn hành tím và tỏi băm nhỏ. Vớt hành tỏi phi ra đĩa riêng để nguội giòn tan, giữ lại phần dầu thơm óng ánh để phết bánh hoặc rưới bóng mặt món ăn.',6,'Tắt bếp ngay khi hành phi chuyển vàng sáng vì nhiệt dư trong dầu nóng sẽ tiếp tục làm hành sẫm màu thêm một nấc hoàn hảo.'),
(211,4,'Pha nước mắm chấm / sốt trộn tỷ lệ vàng chua ngọt','Hòa tan hoàn toàn đường cùng 35ml nước mắm, 20g đường và 15ml giấm và nước ấm trong chén sâu lòng, khuấy đến khi hơi sánh nhẹ mới cho tỏi ớt băm nhuyễn và nước cốt chanh/tắc vào sau cùng. Công thức pha này giúp tỏi ớt nổi đều đẹp mắt trên bề mặt bát nước chấm chuẩn vị Bánh đúc nóng thịt băm mộc nhĩ Hà Nội.',6,'Băm tỏi ớt thật ráo trên thớt khô và cho vào sau khi đường mắm đã nguội thì tỏi ớt sẽ nổi bồng bềnh 100% không bị chìm đáy.'),
(211,5,'Phối trộn thấm vị / tráng hấp & cuốn đều tay','Tiến hành tráng hấp bánh mỏng mượt hoặc trải bánh cuốn gọn gàng 180g bột gạo và 40g bột năng cùng rau củ ăn kèm; nếu là món gỏi trộn thì rưới từ từ 2/3 lượng sốt chua ngọt vào bóp nhẹ tay cho thấm đều trong 3 phút. Giữ lực tay nhẹ nhàng để rau củ không bị dập nát mà vẫn ngấm trọn vị mặn chua ngọt hài hòa.',7,'Chia nước sốt gỏi làm 2 lần trộn và chắt bỏ phần nước tiết ra ở lần đầu giúp đĩa gỏi khô ráo, đậm đà như ngoài hàng.'),
(211,6,'Bày biện ngũ sắc hài hòa & rắc topping giòn bùi','Xếp món Bánh đúc nóng thịt băm mộc nhĩ Hà Nội ngay ngắn ra đĩa sứ trắng rộng, rải đều phần nhân tôm thịt sắc nét lên trên và rắc phủ 25g hành phi thơm giòn. Dọn kèm chén nước chấm đậm đà cho 4 người thưởng thức ngay khi rau bánh còn tươi giòn mướt mịn.',4,'Chỉ rắc đậu phộng rang và hành phi ngay trước lúc mang ra bàn ăn để giữ nguyên độ giòn tan bùi béo.'),
(212,1,'Sơ chế sạch & thấm thật khô bề mặt nguyên liệu','Rửa sạch 300g tôm đất và 300g khoai lang cùng chút muối loãng để khử mùi tự nhiên, sau đó dùng khăn giấy bếp thấm thật khô ráo hoàn toàn bề mặt. Khứa nhẹ các đường chéo hoặc cắt miếng vừa ăn dày 2–3cm để nhiệt và gia vị thấm sâu đều khắp bên trong.',6,'Bề mặt nguyên liệu càng khô ráo thì khi chiên không bị văng dầu và khi nướng sẽ lên màu vàng ruộm giòn rụm cực đẹp.'),
(212,2,'Chuẩn bị hỗn hợp sốt ướp / bột áo chuẩn tỷ lệ','Phối trộn hành tím và tỏi băm nhỏ băm thật nhuyễn (hoặc vắt lấy nước cốt thơm) cùng gia vị chuẩn định lượng trong tô lớn cho quyện sánh đồng nhất. Nếu món có lớp vỏ bột hoặc bánh cuốn từ 300g tôm đất và 300g khoai lang, trộn đều hỗn hợp theo đúng định lượng để đạt độ giòn xốp mỏng nhẹ chuẩn vị.',6,'Vắt lấy nước cốt hành tỏi sả khi ướp đồ nướng giúp hương thơm thấm sâu mà không bị cháy đen phần xác băm trên lửa cao.'),
(212,3,'Ướp thấm thớ thịt / tạo hình cuốn khéo léo','Áo đều hỗn hợp gia vị hoặc lớp bột/vỏ cuốn quanh 300g tôm đất và 300g khoai lang, massage nhẹ nhàng rồi để nghỉ 15–20 phút cho gia vị thẩm thấu trọn vẹn. Trường hợp cuốn chả/nem hoặc đổ khuôn bánh, thao tác đều tay vừa chặt để nhân kết dính nhưng không bị bục rách khi gặp nhiệt.',7,'Để nguyên liệu nghỉ đủ thời gian trước khi chiên nướng giúp lớp áo bột bám chắc và phần nhân bên trong mọng ngọt.'),
(212,4,'Pha nước chấm cân vị & sơ chế rau đồ chua ăn kèm','Nhặt rửa sạch 100g đu đủ xanh và 120g xà lách ngâm nước mát cho giòn tươi, bào sợi hoặc thái lát gọn gàng bày sẵn bên cạnh. Pha chén nước chấm chua ngọt hoặc muối ớt chanh sả sánh thơm theo khẩu vị vùng miền của món Bánh tôm Hồ Tây khoai lang giòn rụm để cân bằng độ béo giòn.',5,'Luôn chuẩn bị xong rau sống và bát nước chấm trước khi chiên/nướng mẻ cuối để món ăn vừa ra lò là thưởng thức nóng giòn ngay.'),
(212,5,'Làm nóng dầu / lò nướng chuẩn nhiệt & làm chín đều lần 1','Làm nóng chảo dầu hoặc vỉ nướng/nồi chiên ở mức nhiệt vừa khoảng 165–175°C, xếp 300g tôm đất và 300g khoai lang vào với khoảng cách thoáng đều nhau. Chiên hoặc nướng trở mặt nhịp nhàng trên lửa vừa để nhiệt dẫn sâu làm chín mềm ngọt hoàn toàn phần nhân bên trong.',9,'Kiểm tra nhiệt dầu bằng đầu đũa tre thấy sủi tăm nhỏ đều là đạt chuẩn 170°C, giúp vỏ không cháy sớm khi bên trong còn sống.'),
(212,6,'Tăng nhiệt khóa giòn rụm vàng ươm bề mặt lần 2','Ở 2–3 phút cuối, tăng lên lửa vừa lớn (khoảng 190°C) hoặc phết thêm lớp dầu điều/mật ong mỏng để vỏ ngoài của Bánh tôm Hồ Tây khoai lang giòn rụm chuyển sắc vàng óng ánh và nổ giòn rụm. Lắng nghe tiếng xèo giòn rộn rã và hương thơm phức lan tỏa khắp bếp thì gắp ra vỉ thưa cho ráo dầu thừa.',4,'Đặt đồ chiên nướng lên giá inox thoáng khí thay vì giấy thấm dầu chồng khít để hơi nước thoát hết, giữ độ giòn lâu gấp 3 lần.'),
(212,7,'Trình bày bắt mắt kèm rau thơm & thưởng thức nóng','Xếp thành phẩm vàng giòn ra đĩa lớn có bày sẵn 100g đu đủ xanh và 120g xà lách và điểm xuyết hành ngò và tiêu xay tươi xanh hài hòa màu sắc. Dọn kèm chén nước chấm sánh đậm ngay chính giữa mâm ăn cho 4 người thưởng thức khi vỏ ngoài còn nóng giòn rụm.',3,'Cắt miếng hoặc dọn ăn ngay trong vòng 10 phút sau khi rời bếp để cảm nhận trọn vẹn sự đối lập giòn ngoài - mềm ngọt bên trong.'),
(213,1,'Tuyển chọn & sơ chế tươi sạch nguyên liệu pha chế','Rửa sạch kỹ các nguyên liệu tươi gồm 50g cà phê bột và 3 quả trứng gà và 5ml tinh chất vani, để ráo nước hoàn toàn trên khay sạch. Cắt lát, đập dập hoặc đong chuẩn xác từng gam/ml nguyên liệu cho khẩu phần 2 ly để hương vị đồng nhất tuyệt đối.',4,'Loại bỏ kỹ hạt chanh, tắc trước khi vắt hoặc nấu giúp thức uống giữ hậu vị thanh ngọt mà không hề bị đắng vỏ.'),
(213,2,'Ủ chiết xuất nền trà, cà phê hoặc nấu cốt thảo mộc','Đun nước đạt nhiệt độ chuẩn 90–95°C (không dùng nước sôi sùng sục làm cháy hương), tiến hành ủ chiết xuất hoặc nấu nhỏ lửa 50g cà phê bột và 3 quả trứng gà trong thời gian quy định. Lọc qua rây mịn hoặc túi vải sạch để thu được phần nước cốt trong trẻo, đậm hương tự nhiên không gợn cặn.',5,'Ủ trà/cà phê đúng nhiệt độ 92°C và đậy nắp kín giúp thu trọn tinh dầu thơm quyến rũ mà không chiết xuất vị chát gắt.'),
(213,3,'Xử lý lớp kem bông mịn / hỗn hợp sữa & trái cây','Đánh bông mượt hoặc khuấy hòa quyện phần nguyên liệu bổ trợ (5ml tinh chất vani) cùng 15g mật ong đến khi sánh mịn đồng nhất. Kiểm soát tốc độ khuấy/đánh đều tay để tạo kết cấu bồng bềnh mượt mà hoặc hòa tan hoàn toàn đường phèn mật ong.',4,'Nếu đánh kem trứng, nghiêng nhẹ âu 45 độ và đánh một chiều tốc độ cao cho tới khi nhấc que tạo chóp mềm bóng mượt không tanh.'),
(213,4,'Cân chỉnh định lượng độ ngọt & tầng hương tươi mát','Phối trộn phần nước cốt nền cùng hỗn hợp tạo vị theo đúng tỷ lệ vàng của món Cà phê trứng phố cổ Hà Nội béo mịn, khuấy nhẹ để các tầng hương hòa quyện. Nếu có nước cốt chanh hoặc mật ong rừng, cho vào khi nền nước đã hạ xuống dưới 55°C để bảo toàn trọn vẹn vitamin và hương thơm.',3,'Nếm thử trước khi thêm đá viên sao cho vị đậm hơn khoảng 15% để khi đá tan nhẹ là vừa vặn hoàn hảo.'),
(213,5,'Phối tầng thẩm mỹ ra ly thủy tinh nóng hoặc đá mát','Tráng ấm ly gốm (nếu dùng nóng) hoặc cho lượng đá viên tinh khiết vừa đủ vào ly thủy tinh cao, rót từ từ cốt thức uống vào 2/3 ly. Nhẹ nhàng rót lớp kem/sữa hoặc xếp lát trái cây tươi áp sát thành ly tạo hiệu ứng phân tầng đẹp mắt như quán chuyên nghiệp.',2,'Rót lớp kem hoặc sữa nhẹ nhàng qua lưng muỗng inox giúp hai tầng màu tách bạch sắc nét cực kỳ cuốn hút.'),
(213,6,'Điểm xuyết lá thơm trang trí & thưởng thức ngay','Trang trí trên mặt ly bằng lát nguyên liệu tươi, nhánh bạc hà/lá dứa hoặc rắc nhẹ bột cacao/hạt chia cho món Cà phê trứng phố cổ Hà Nội béo mịn thêm phần sinh động. Phục vụ ngay khi vừa pha chế xong cho 2 người để tận hưởng trọn vẹn hương thơm tươi mới sảng khoái nhất.',2,'Vỗ nhẹ lá bạc hà trong lòng bàn tay trước khi đặt lên miệng ly sẽ đánh thức tinh dầu the mát lan tỏa ngay khi nâng ly.'),
(214,1,'Tuyển chọn & sơ chế tươi sạch nguyên liệu pha chế','Rửa sạch kỹ các nguyên liệu tươi gồm 400g quả sấu và 30g gừng, để ráo nước hoàn toàn trên khay sạch. Cắt lát, đập dập hoặc đong chuẩn xác từng gam/ml nguyên liệu cho khẩu phần 4 ly để hương vị đồng nhất tuyệt đối.',7,'Loại bỏ kỹ hạt chanh, tắc trước khi vắt hoặc nấu giúp thức uống giữ hậu vị thanh ngọt mà không hề bị đắng vỏ.'),
(214,2,'Ủ chiết xuất nền trà, cà phê hoặc nấu cốt thảo mộc','Đun nước đạt nhiệt độ chuẩn 90–95°C (không dùng nước sôi sùng sục làm cháy hương), tiến hành ủ chiết xuất hoặc nấu nhỏ lửa 400g quả sấu trong thời gian quy định. Lọc qua rây mịn hoặc túi vải sạch để thu được phần nước cốt trong trẻo, đậm hương tự nhiên không gợn cặn.',9,'Ủ trà/cà phê đúng nhiệt độ 92°C và đậy nắp kín giúp thu trọn tinh dầu thơm quyến rũ mà không chiết xuất vị chát gắt.'),
(214,3,'Xử lý lớp kem bông mịn / hỗn hợp sữa & trái cây','Đánh bông mượt hoặc khuấy hòa quyện phần nguyên liệu bổ trợ (500ml nước lọc và 250g đá viên) cùng 280g đường phèn và 5g muối đến khi sánh mịn đồng nhất. Kiểm soát tốc độ khuấy/đánh đều tay để tạo kết cấu bồng bềnh mượt mà hoặc hòa tan hoàn toàn đường phèn mật ong.',7,'Nếu đánh kem trứng, nghiêng nhẹ âu 45 độ và đánh một chiều tốc độ cao cho tới khi nhấc que tạo chóp mềm bóng mượt không tanh.'),
(214,4,'Cân chỉnh định lượng độ ngọt & tầng hương tươi mát','Phối trộn phần nước cốt nền cùng hỗn hợp tạo vị theo đúng tỷ lệ vàng của món Nước sấu ngâm gừng đá Hà Nội giải nhiệt, khuấy nhẹ để các tầng hương hòa quyện. Nếu có nước cốt chanh hoặc mật ong rừng, cho vào khi nền nước đã hạ xuống dưới 55°C để bảo toàn trọn vẹn vitamin và hương thơm.',5,'Nếm thử trước khi thêm đá viên sao cho vị đậm hơn khoảng 15% để khi đá tan nhẹ là vừa vặn hoàn hảo.'),
(214,5,'Phối tầng thẩm mỹ ra ly thủy tinh nóng hoặc đá mát','Tráng ấm ly gốm (nếu dùng nóng) hoặc cho lượng đá viên tinh khiết vừa đủ vào ly thủy tinh cao, rót từ từ cốt thức uống vào 2/3 ly. Nhẹ nhàng rót lớp kem/sữa hoặc xếp lát trái cây tươi áp sát thành ly tạo hiệu ứng phân tầng đẹp mắt như quán chuyên nghiệp.',4,'Rót lớp kem hoặc sữa nhẹ nhàng qua lưng muỗng inox giúp hai tầng màu tách bạch sắc nét cực kỳ cuốn hút.');
INSERT INTO `recipe_steps` (`recipe_id`,`step_order`,`title`,`instruction`,`duration_mins`,`tip_note`) VALUES
(214,6,'Điểm xuyết lá thơm trang trí & thưởng thức ngay','Trang trí trên mặt ly bằng lát nguyên liệu tươi, nhánh bạc hà/lá dứa hoặc rắc nhẹ bột cacao/hạt chia cho món Nước sấu ngâm gừng đá Hà Nội giải nhiệt thêm phần sinh động. Phục vụ ngay khi vừa pha chế xong cho 4 người để tận hưởng trọn vẹn hương thơm tươi mới sảng khoái nhất.',3,'Vỗ nhẹ lá bạc hà trong lòng bàn tay trước khi đặt lên miệng ly sẽ đánh thức tinh dầu the mát lan tỏa ngay khi nâng ly.'),
(215,1,'Tuyển chọn, ngâm nở & sơ chế sạch nguyên liệu chè bánh','Đãi rửa sạch nhóm hạt, củ hoặc bột (200g cốm tươi và 35g bột năng), ngâm nước ấm theo đúng đặc tính từng loại để hạt nở mềm đồng đều và loại bỏ nhựa chát. Rửa sạch nhóm tạo hương tự nhiên gồm 30g lá dứa để ráo nước.',5,'Thêm một nhúm muối nhỏ vào nước ngâm khoai và đậu giúp nguyên liệu giữ màu tươi sáng và khi nấu chín bùi hơn.'),
(215,2,'Ninh mềm bùi nguyên liệu chính giữ nguyên hạt/khối','Cho phần nguyên liệu nền trong 200g cốm tươi và 35g bột năng vào nồi đáy dày cùng lượng nước vừa đủ, đun sôi rồi hạ lửa nhỏ ninh êm đến khi chín mềm bùi nhưng không bị vỡ nát đục nước. Nếu có trân châu, bột lọc hoặc hạt lựu, luộc riêng trong nồi nước sôi đến khi nổi trong veo rồi vớt ngâm ngay vào bát nước mát.',7,'Tuyệt đối không cho đường ngay từ đầu khi đậu và khoai chưa chín mềm vì đường sẽ làm săn vỏ hạt khiến nấu mãi vẫn sượng.'),
(215,3,'Nấu nước đường phèn / mật mía thanh trong dậy hương','Kết hợp chính xác định lượng 120g đường phèn vào nồi cùng bó lá dứa hoặc gừng thái chỉ, khuấy nhẹ trên lửa nhỏ cho tan trong vắt. Đun liu riu thêm 5–7 phút để vị ngọt thấm sâu vào từng viên nguyên liệu và tỏa hương thơm dịu tao nhã.',4,'Dùng đường phèn hoặc mật mía đun lửa nhỏ hớt bọt kỹ giúp hậu vị chè ngọt thanh mát họng, không bị khé cổ.'),
(215,4,'Thắng nước cốt dừa béo mịn / chuẩn bị lớp kem phủ','Cho 100ml nước cốt dừa vào nồi nhỏ cùng 2g muối tinh và 5g bột năng/bột bắp hòa loãng, khuấy đều tay trên lửa nhỏ nhất đến khi vừa chớm sôi lăn tăn sánh mượt. Tắt bếp ngay để nước cốt dừa giữ màu trắng ngần béo ngậy mà không bị tách lớp dầu.',4,'Một chút xíu muối tinh trong nồi nước cốt dừa sẽ làm bật hẳn độ béo thơm tự nhiên và cân bằng vị ngọt của món tráng miệng.'),
(215,5,'Phối hợp độ sánh mượt & cân bằng hương vị tổng thể','Hợp nhất các thành phần của món Chè cốm lá dứa làng Vòng thanh tao, từ từ rưới nước bột năng hòa loãng (nếu là chè sánh) đồng thời khuấy nhẹ một chiều trên lửa nhỏ cho hỗn hợp bóng mượt như nhung. Kiểm tra độ mềm dẻo hài hòa và tắt bếp để ủ hương thảo mộc lan tỏa đều.',3,'Rót nước bột tạo sánh thành dòng mảnh vừa rót vừa khuấy đều tay giúp chè trong mượt, hoàn toàn không bị ốc trâu vón cục.'),
(215,6,'Múc ra chén sứ, điểm topping & thưởng thức ấm/lạnh','Múc chè hoặc bày bánh ra 4 chén nhỏ xinh, chan lớp nước cốt dừa trắng mịn lên mặt và rắc nhẹ mè rang, đậu phộng hoặc dừa non bào sợi. Thưởng thức ấm nóng dịu dàng hoặc thêm đá bào mát lạnh tùy sở thích đều trọn vị ngon truyền thống.',2,'Để chè nguội bớt về khoảng 45°C hoặc ướp mát 30 phút trong ngăn mát tủ lạnh giúp các tầng hương vị kết tinh đậm đà hơn.'),
(216,1,'Tuyển chọn, ngâm nở & sơ chế sạch nguyên liệu chè bánh','Đãi rửa sạch nhóm hạt, củ hoặc bột (600g tào phớ), ngâm nước ấm theo đúng đặc tính từng loại để hạt nở mềm đồng đều và loại bỏ nhựa chát. Rửa sạch nhóm tạo hương tự nhiên gồm 8g hoa nhài khô, 20g gừng và 15g lá dứa để ráo nước.',7,'Thêm một nhúm muối nhỏ vào nước ngâm khoai và đậu giúp nguyên liệu giữ màu tươi sáng và khi nấu chín bùi hơn.'),
(216,2,'Ninh mềm bùi nguyên liệu chính giữ nguyên hạt/khối','Cho phần nguyên liệu nền trong 600g tào phớ vào nồi đáy dày cùng lượng nước vừa đủ, đun sôi rồi hạ lửa nhỏ ninh êm đến khi chín mềm bùi nhưng không bị vỡ nát đục nước. Nếu có trân châu, bột lọc hoặc hạt lựu, luộc riêng trong nồi nước sôi đến khi nổi trong veo rồi vớt ngâm ngay vào bát nước mát.',10,'Tuyệt đối không cho đường ngay từ đầu khi đậu và khoai chưa chín mềm vì đường sẽ làm săn vỏ hạt khiến nấu mãi vẫn sượng.'),
(216,3,'Nấu nước đường phèn / mật mía thanh trong dậy hương','Kết hợp chính xác định lượng 130g đường phèn vào nồi cùng bó lá dứa hoặc gừng thái chỉ, khuấy nhẹ trên lửa nhỏ cho tan trong vắt. Đun liu riu thêm 5–7 phút để vị ngọt thấm sâu vào từng viên nguyên liệu và tỏa hương thơm dịu tao nhã.',6,'Dùng đường phèn hoặc mật mía đun lửa nhỏ hớt bọt kỹ giúp hậu vị chè ngọt thanh mát họng, không bị khé cổ.'),
(216,4,'Thắng nước cốt dừa béo mịn / chuẩn bị lớp kem phủ','Cho 200g đá viên vào nồi nhỏ cùng 2g muối tinh và 5g bột năng/bột bắp hòa loãng, khuấy đều tay trên lửa nhỏ nhất đến khi vừa chớm sôi lăn tăn sánh mượt. Tắt bếp ngay để nước cốt dừa giữ màu trắng ngần béo ngậy mà không bị tách lớp dầu.',5,'Một chút xíu muối tinh trong nồi nước cốt dừa sẽ làm bật hẳn độ béo thơm tự nhiên và cân bằng vị ngọt của món tráng miệng.'),
(216,5,'Phối hợp độ sánh mượt & cân bằng hương vị tổng thể','Hợp nhất các thành phần của món Tào phớ nước đường hoa nhài Hà Nội, từ từ rưới nước bột năng hòa loãng (nếu là chè sánh) đồng thời khuấy nhẹ một chiều trên lửa nhỏ cho hỗn hợp bóng mượt như nhung. Kiểm tra độ mềm dẻo hài hòa và tắt bếp để ủ hương thảo mộc lan tỏa đều.',4,'Rót nước bột tạo sánh thành dòng mảnh vừa rót vừa khuấy đều tay giúp chè trong mượt, hoàn toàn không bị ốc trâu vón cục.'),
(216,6,'Múc ra chén sứ, điểm topping & thưởng thức ấm/lạnh','Múc chè hoặc bày bánh ra 4 chén nhỏ xinh, chan lớp nước cốt dừa trắng mịn lên mặt và rắc nhẹ mè rang, đậu phộng hoặc dừa non bào sợi. Thưởng thức ấm nóng dịu dàng hoặc thêm đá bào mát lạnh tùy sở thích đều trọn vị ngon truyền thống.',3,'Để chè nguội bớt về khoảng 45°C hoặc ướp mát 30 phút trong ngăn mát tủ lạnh giúp các tầng hương vị kết tinh đậm đà hơn.'),
(217,1,'Sơ chế & thái mỏng đồng đều nguyên liệu xào','Làm sạch và thấm ráo 250g thịt trâu gác bếp và 300g măng chua, dùng dao sắc thái lát mỏng vừa ăn khoảng 2–3mm ngang thớ để khi xào nhanh chín mềm không bị dai. Nhặt rửa sạch rau củ ăn kèm, cắt khúc xéo 4cm hoặc tách nhánh đồng đều giúp tiếp xúc nhiệt nhanh trên chảo.',8,'Nguyên liệu xào bắt buộc phải để thật ráo nước trước khi cho vào chảo để đạt hiệu ứng áp nhiệt thơm kiểu chảo gang.'),
(217,2,'Ướp mềm nguyên liệu đạm & pha sẵn chén sốt xào','Ướp phần đạm trong 250g thịt trâu gác bếp và 300g măng chua với 1/3 lượng 20g tỏi, chút dầu ăn và 1/3 lượng 5g mắc khén và 10g ớt trong 10 phút để giữ độ ẩm mọng. Pha phần 5g mắc khén và 10g ớt còn lại cùng 20ml nước lọc vào chén nhỏ khuấy tan hoàn toàn để thao tác xào lửa lớn diễn ra dứt khoát.',6,'Thêm 1 muỗng cà phê dầu ăn vào bước ướp thịt bò/heo giúp khóa ẩm và các lát thịt tơi nhanh không bị dính chùm khi gặp chảo nóng.'),
(217,3,'Chần nhanh rau củ giữ sắc xanh ngọc & độ giòn','Đun sôi nồi nước nhỏ với một nhúm muối, thả rau củ ăn kèm vào chần nhanh 30–45 giây rồi vớt ngay ra tô nước đá lạnh cho sốc nhiệt, sau đó đổ ra rổ cho thật ráo. Bước tiền xử lý này giúp rau củ chín đều từ trong mà bên ngoài vẫn xanh mướt giòn sần sật.',5,'Thời gian chần dưới 1 phút kết hợp ngâm nước đá lạnh là bí quyết nhà hàng giúp đĩa rau xào không bị chảy nước đen đĩa.'),
(217,4,'Xào săn nguyên liệu chính trên lửa lớn nhanh tay','Làm nóng chảo rộng trên lửa lớn nhất với 15ml dầu ăn, phi dậy mùi một nửa 20g tỏi rồi trút phần đạm chính trong 250g thịt trâu gác bếp và 300g măng chua vào đảo cực nhanh tay trong 60–90 giây. Ngay khi thịt hoặc hải sản vừa chín tái hồng khoảng 85%, lập tức trút riêng ra đĩa sạch để không bị quá lửa khô xác.',6,'Tuyệt đối không xào thịt chung từ đầu đến cuối với rau củ vì thịt sẽ bị dai và tiết nước làm mất độ giòn.'),
(217,5,'Xào rau củ lửa lớn & rưới sốt định lượng khóa vị','Giữ nguyên chảo nóng trên lửa lớn, thêm chút dầu phi thơm nốt phần 20g tỏi còn lại rồi cho rau củ ăn kèm đã ráo nước vào đảo đều 1–2 phút. Trút ngược đĩa đạm vào chảo, rưới đều chén sốt gia vị đã pha và xóc nhanh tay 45 giây cho sốt sánh bóng áo quanh từng miếng nguyên liệu.',6,'Rưới sốt vòng quanh thành chảo nóng thay vì đổ thẳng giữa lòng chảo giúp sốt bốc hơi thơm lừng và sệt lại tức thì.'),
(217,6,'Dậy hương tiêu hành & trình bày nóng hổi','Cho 25g hành lá vào đảo nhẹ đúng 1 lượt rồi tắt bếp ngay khi khói thơm bốc lên nghi ngút. Gắp món Thịt trâu gác bếp xào măng chua Tây Bắc ra đĩa rộng lòng để tản nhiệt đều, tránh đậy kín vung và thưởng thức nóng ngay cùng cơm dẻo cho 4 người.',4,'Bày món xào ra đĩa rộng không xếp chồng quá dày giúp hơi nóng thoát nhẹ, giữ rau củ giòn ngọt lâu đến miếng cuối cùng.'),
(218,1,'Sơ chế sạch & thấm thật khô bề mặt nguyên liệu','Rửa sạch 900g cá chép cùng chút muối loãng để khử mùi tự nhiên, sau đó dùng khăn giấy bếp thấm thật khô ráo hoàn toàn bề mặt. Khứa nhẹ các đường chéo hoặc cắt miếng vừa ăn dày 2–3cm để nhiệt và gia vị thấm sâu đều khắp bên trong.',9,'Bề mặt nguyên liệu càng khô ráo thì khi chiên không bị văng dầu và khi nướng sẽ lên màu vàng ruộm giòn rụm cực đẹp.'),
(218,2,'Chuẩn bị hỗn hợp sốt ướp / bột áo chuẩn tỷ lệ','Phối trộn 50g sả và 25g gừng băm thật nhuyễn (hoặc vắt lấy nước cốt thơm) cùng 8g mắc khén, 4g hạt dổi và 8g muối trong tô lớn cho quyện sánh đồng nhất. Nếu món có lớp vỏ bột hoặc bánh cuốn từ 900g cá chép, trộn đều hỗn hợp theo đúng định lượng để đạt độ giòn xốp mỏng nhẹ chuẩn vị.',8,'Vắt lấy nước cốt hành tỏi sả khi ướp đồ nướng giúp hương thơm thấm sâu mà không bị cháy đen phần xác băm trên lửa cao.'),
(218,3,'Ướp thấm thớ thịt / tạo hình cuốn khéo léo','Áo đều hỗn hợp gia vị hoặc lớp bột/vỏ cuốn quanh 900g cá chép, massage nhẹ nhàng rồi để nghỉ 15–20 phút cho gia vị thẩm thấu trọn vẹn. Trường hợp cuốn chả/nem hoặc đổ khuôn bánh, thao tác đều tay vừa chặt để nhân kết dính nhưng không bị bục rách khi gặp nhiệt.',11,'Để nguyên liệu nghỉ đủ thời gian trước khi chiên nướng giúp lớp áo bột bám chắc và phần nhân bên trong mọng ngọt.'),
(218,4,'Pha nước chấm cân vị & sơ chế rau đồ chua ăn kèm','Nhặt rửa sạch rau củ ăn kèm ngâm nước mát cho giòn tươi, bào sợi hoặc thái lát gọn gàng bày sẵn bên cạnh. Pha chén nước chấm chua ngọt hoặc muối ớt chanh sả sánh thơm theo khẩu vị vùng miền của món Cá chép nướng Pa Pỉnh Tộp mắc khén Sơn La để cân bằng độ béo giòn.',7,'Luôn chuẩn bị xong rau sống và bát nước chấm trước khi chiên/nướng mẻ cuối để món ăn vừa ra lò là thưởng thức nóng giòn ngay.'),
(218,5,'Làm nóng dầu / lò nướng chuẩn nhiệt & làm chín đều lần 1','Làm nóng chảo dầu hoặc vỉ nướng/nồi chiên ở mức nhiệt vừa khoảng 165–175°C, xếp 900g cá chép vào với khoảng cách thoáng đều nhau. Chiên hoặc nướng trở mặt nhịp nhàng trên lửa vừa để nhiệt dẫn sâu làm chín mềm ngọt hoàn toàn phần nhân bên trong.',13,'Kiểm tra nhiệt dầu bằng đầu đũa tre thấy sủi tăm nhỏ đều là đạt chuẩn 170°C, giúp vỏ không cháy sớm khi bên trong còn sống.'),
(218,6,'Tăng nhiệt khóa giòn rụm vàng ươm bề mặt lần 2','Ở 2–3 phút cuối, tăng lên lửa vừa lớn (khoảng 190°C) hoặc phết thêm lớp dầu điều/mật ong mỏng để vỏ ngoài của Cá chép nướng Pa Pỉnh Tộp mắc khén Sơn La chuyển sắc vàng óng ánh và nổ giòn rụm. Lắng nghe tiếng xèo giòn rộn rã và hương thơm phức lan tỏa khắp bếp thì gắp ra vỉ thưa cho ráo dầu thừa.',7,'Đặt đồ chiên nướng lên giá inox thoáng khí thay vì giấy thấm dầu chồng khít để hơi nước thoát hết, giữ độ giòn lâu gấp 3 lần.');
INSERT INTO `recipe_steps` (`recipe_id`,`step_order`,`title`,`instruction`,`duration_mins`,`tip_note`) VALUES
(218,7,'Trình bày bắt mắt kèm rau thơm & thưởng thức nóng','Xếp thành phẩm vàng giòn ra đĩa lớn có bày sẵn rau củ ăn kèm và điểm xuyết 30g rau răm và 25g thì là tươi xanh hài hòa màu sắc. Dọn kèm chén nước chấm sánh đậm ngay chính giữa mâm ăn cho 4 người thưởng thức khi vỏ ngoài còn nóng giòn rụm.',5,'Cắt miếng hoặc dọn ăn ngay trong vòng 10 phút sau khi rời bếp để cảm nhận trọn vẹn sự đối lập giòn ngoài - mềm ngọt bên trong.'),
(219,1,'Sơ chế sạch & thấm thật khô bề mặt nguyên liệu','Rửa sạch 600g thịt ba chỉ cùng chút muối loãng để khử mùi tự nhiên, sau đó dùng khăn giấy bếp thấm thật khô ráo hoàn toàn bề mặt. Khứa nhẹ các đường chéo hoặc cắt miếng vừa ăn dày 2–3cm để nhiệt và gia vị thấm sâu đều khắp bên trong.',7,'Bề mặt nguyên liệu càng khô ráo thì khi chiên không bị văng dầu và khi nướng sẽ lên màu vàng ruộm giòn rụm cực đẹp.'),
(219,2,'Chuẩn bị hỗn hợp sốt ướp / bột áo chuẩn tỷ lệ','Phối trộn 40g lá mắc mật, 15g tỏi và 20g hành tím băm thật nhuyễn (hoặc vắt lấy nước cốt thơm) cùng 25g mật ong, 20ml dầu hào và 4g ngũ vị hương trong tô lớn cho quyện sánh đồng nhất. Nếu món có lớp vỏ bột hoặc bánh cuốn từ 600g thịt ba chỉ, trộn đều hỗn hợp theo đúng định lượng để đạt độ giòn xốp mỏng nhẹ chuẩn vị.',6,'Vắt lấy nước cốt hành tỏi sả khi ướp đồ nướng giúp hương thơm thấm sâu mà không bị cháy đen phần xác băm trên lửa cao.'),
(219,3,'Ướp thấm thớ thịt / tạo hình cuốn khéo léo','Áo đều hỗn hợp gia vị hoặc lớp bột/vỏ cuốn quanh 600g thịt ba chỉ, massage nhẹ nhàng rồi để nghỉ 15–20 phút cho gia vị thẩm thấu trọn vẹn. Trường hợp cuốn chả/nem hoặc đổ khuôn bánh, thao tác đều tay vừa chặt để nhân kết dính nhưng không bị bục rách khi gặp nhiệt.',8,'Để nguyên liệu nghỉ đủ thời gian trước khi chiên nướng giúp lớp áo bột bám chắc và phần nhân bên trong mọng ngọt.'),
(219,4,'Pha nước chấm cân vị & sơ chế rau đồ chua ăn kèm','Nhặt rửa sạch rau củ ăn kèm ngâm nước mát cho giòn tươi, bào sợi hoặc thái lát gọn gàng bày sẵn bên cạnh. Pha chén nước chấm chua ngọt hoặc muối ớt chanh sả sánh thơm theo khẩu vị vùng miền của món Thịt ba chỉ nướng lá mắc mật Lạng Sơn để cân bằng độ béo giòn.',5,'Luôn chuẩn bị xong rau sống và bát nước chấm trước khi chiên/nướng mẻ cuối để món ăn vừa ra lò là thưởng thức nóng giòn ngay.'),
(219,5,'Làm nóng dầu / lò nướng chuẩn nhiệt & làm chín đều lần 1','Làm nóng chảo dầu hoặc vỉ nướng/nồi chiên ở mức nhiệt vừa khoảng 165–175°C, xếp 600g thịt ba chỉ vào với khoảng cách thoáng đều nhau. Chiên hoặc nướng trở mặt nhịp nhàng trên lửa vừa để nhiệt dẫn sâu làm chín mềm ngọt hoàn toàn phần nhân bên trong.',10,'Kiểm tra nhiệt dầu bằng đầu đũa tre thấy sủi tăm nhỏ đều là đạt chuẩn 170°C, giúp vỏ không cháy sớm khi bên trong còn sống.'),
(219,6,'Tăng nhiệt khóa giòn rụm vàng ươm bề mặt lần 2','Ở 2–3 phút cuối, tăng lên lửa vừa lớn (khoảng 190°C) hoặc phết thêm lớp dầu điều/mật ong mỏng để vỏ ngoài của Thịt ba chỉ nướng lá mắc mật Lạng Sơn chuyển sắc vàng óng ánh và nổ giòn rụm. Lắng nghe tiếng xèo giòn rộn rã và hương thơm phức lan tỏa khắp bếp thì gắp ra vỉ thưa cho ráo dầu thừa.',5,'Đặt đồ chiên nướng lên giá inox thoáng khí thay vì giấy thấm dầu chồng khít để hơi nước thoát hết, giữ độ giòn lâu gấp 3 lần.'),
(219,7,'Trình bày bắt mắt kèm rau thơm & thưởng thức nóng','Xếp thành phẩm vàng giòn ra đĩa lớn có bày sẵn rau củ ăn kèm và điểm xuyết hành ngò và tiêu xay tươi xanh hài hòa màu sắc. Dọn kèm chén nước chấm sánh đậm ngay chính giữa mâm ăn cho 4 người thưởng thức khi vỏ ngoài còn nóng giòn rụm.',4,'Cắt miếng hoặc dọn ăn ngay trong vòng 10 phút sau khi rời bếp để cảm nhận trọn vẹn sự đối lập giòn ngoài - mềm ngọt bên trong.'),
(220,1,'Sơ chế sạch & cắt thái nguyên liệu đúng kích cỡ','Rửa sạch 700g thịt ba chỉ và 350g khoai môn cùng 25g nấm mèo dưới vòi nước mát rồi để thật ráo trên rổ thưa. Dùng dao sắc cắt thái nguyên liệu thành từng khúc hoặc khối vuông đều đặn khoảng 3.5–4cm để khi kho hầm giữ nguyên hình dáng đẹp mắt mà không bị vụn nát.',18,'Cắt miếng thịt/cá dày dặn đồng đều giúp quá trình kho lâu trên lửa nhỏ thớ thịt mềm rục mà vẫn giữ trọn độ mọng ngọt bên trong.'),
(220,2,'Khử mùi tự nhiên & làm săn sạch bề mặt nguyên liệu','Chà nhẹ phần đạm chính trong 700g thịt ba chỉ và 350g khoai môn với chút muối hạt, lát gừng đập dập hoặc chần sơ qua nước sôi 90 giây rồi rửa sạch lại bằng nước ấm, để ráo hoàn toàn. Công đoạn này loại bỏ triệt để tạp chất và mùi tanh hôi, giúp nước sốt món Khâu nhục Lạng Sơn khoai môn mềm rục trong bóng thơm ngon.',14,'Sau khi chần hoặc rửa sạch, để nguyên liệu ráo nước ít nhất 5 phút trước khi ướp để gia vị rút sâu trực tiếp vào từng thớ thịt.'),
(220,3,'Pha hỗn hợp gia vị & ướp thấm chuẩn định lượng','Cho 700g thịt ba chỉ và 350g khoai môn vào tô lớn, ướp cùng một nửa 20g lá mắc mật và 20g tỏi băm nhỏ và định lượng chuẩn 35ml nước tương, 20g mật ong và 5g ngũ vị hương, đảo nhẹ tay cho gia vị phủ kín đều các mặt. Bọc kín tô và để nguyên liệu nghỉ thấm vị tối thiểu 20 phút ở nhiệt độ phòng (hoặc ngăn mát tủ lạnh).',20,'Ướp đủ tối thiểu 20 phút trước khi bắc lên bếp là chìa khóa để tâm miếng thịt/cá đậm đà đồng nhất với lớp sốt bên ngoài.'),
(220,4,'Thắng nước màu cánh gián & phi dậy hương hành tỏi','Đặt nồi đáy dày lên bếp ở lửa vừa nhỏ, thắng nhẹ 15g đường với 15ml dầu ăn đến khi chuyển sắc nâu cánh gián óng ả thì cho ngay phần 20g lá mắc mật và 20g tỏi còn lại vào phi thơm lừng. Hương caramel dịu ngọt quyện cùng tinh dầu hành tỏi sả tạo nền màu nâu hổ phách truyền thống đầy cuốn hút.',13,'Canh kỹ khoảnh khắc đường vừa chuyển màu cánh gián là hạ lửa nhỏ nhất ngay để nước màu bóng đẹp mà không bao giờ bị đắng.'),
(220,5,'Đảo săn hai mặt khóa ngọt nguyên liệu chính','Tăng lên lửa vừa lớn, gắp từng miếng trong 700g thịt ba chỉ và 350g khoai môn vào nồi đảo đều hoặc trở nhẹ hai mặt trong 4–5 phút cho săn chắc và bám đều lớp màu nâu óng. Khi bề mặt nguyên liệu se vàng thơm phức mới trút phần nước ướp còn lại trong tô vào đun sôi nhẹ.',18,'Đối với cá kho, chỉ lật cá một lần lúc cá vừa săn mặt trên lửa vừa để khúc cá nguyên vẹn không bị tróc da hay vỡ nát.'),
(220,6,'Kho/om liu riu lửa nhỏ thấm đẫm cùng nước dừa/nước dùng','Chế lượng nước vừa ngập mặt nguyên liệu xâm xắp mặt nguyên liệu (xếp thêm rau củ ăn kèm nếu có), đun sôi bùng một dạo hớt sạch bọt rồi hạ ngay về mức lửa nhỏ liu riu nhất. Kho êm đềm không đậy kín nắp để từng thớ nguyên liệu chín mềm thấm đẫm gia vị và nước sốt rút dần sóng sánh.',34,'Luôn dùng nước sôi hoặc nước dừa ấm khi châm thêm vào nồi kho đang nóng để thịt cá không bị sượng cứng trở lại.'),
(220,7,'Thu sánh nước sốt óng ả & trình bày thưởng thức nóng','Khi nước kho rút còn khoảng 1/3 sánh kẹo óng ánh áo đều quanh nguyên liệu và xiên đũa thấy mềm mọng vừa ý, rắc hành ngò và tiêu xay lên mặt rồi tắt bếp. Múc món Khâu nhục Lạng Sơn khoai môn mềm rục ra đĩa sâu lòng hoặc niêu đất giữ nhiệt, dọn ăn nóng cùng cơm trắng dẻo thơm cho 4 người.',13,'Giữ lại một lượng nước sốt sánh kẹo vừa đủ dưới đáy nồi để chan cơm hoặc chấm kèm rau luộc sẽ tròn vị đưa cơm gấp bội.'),
(221,1,'Sơ chế sạch & cắt thái nguyên liệu đúng kích cỡ','Rửa sạch 500g bánh phở tươi và 250g thịt heo (nạc vai) cùng 200g khoai lang và 100g lạp xưởng dưới vòi nước mát rồi để thật ráo trên rổ thưa. Dùng dao sắc cắt thái nguyên liệu thành từng khúc hoặc khối vuông đều đặn khoảng 3.5–4cm để khi kho hầm giữ nguyên hình dáng đẹp mắt mà không bị vụn nát.',7,'Cắt miếng thịt/cá dày dặn đồng đều giúp quá trình kho lâu trên lửa nhỏ thớ thịt mềm rục mà vẫn giữ trọn độ mọng ngọt bên trong.'),
(221,2,'Khử mùi tự nhiên & làm săn sạch bề mặt nguyên liệu','Chà nhẹ phần đạm chính trong 500g bánh phở tươi và 250g thịt heo (nạc vai) với chút muối hạt, lát gừng đập dập hoặc chần sơ qua nước sôi 90 giây rồi rửa sạch lại bằng nước ấm, để ráo hoàn toàn. Công đoạn này loại bỏ triệt để tạp chất và mùi tanh hôi, giúp nước sốt món Phở chua Lạng Sơn trộn sốt khoai lang giòn trong bóng thơm ngon.',6,'Sau khi chần hoặc rửa sạch, để nguyên liệu ráo nước ít nhất 5 phút trước khi ướp để gia vị rút sâu trực tiếp vào từng thớ thịt.'),
(221,3,'Pha hỗn hợp gia vị & ướp thấm chuẩn định lượng','Cho 500g bánh phở tươi và 250g thịt heo (nạc vai) vào tô lớn, ướp cùng một nửa hành tím và tỏi băm nhỏ băm nhỏ và định lượng chuẩn 30ml giấm và 30g đường, đảo nhẹ tay cho gia vị phủ kín đều các mặt. Bọc kín tô và để nguyên liệu nghỉ thấm vị tối thiểu 20 phút ở nhiệt độ phòng (hoặc ngăn mát tủ lạnh).',8,'Ướp đủ tối thiểu 20 phút trước khi bắc lên bếp là chìa khóa để tâm miếng thịt/cá đậm đà đồng nhất với lớp sốt bên ngoài.'),
(221,4,'Thắng nước màu cánh gián & phi dậy hương hành tỏi','Đặt nồi đáy dày lên bếp ở lửa vừa nhỏ, thắng nhẹ 15g đường với 15ml dầu ăn đến khi chuyển sắc nâu cánh gián óng ả thì cho ngay phần hành tím và tỏi băm nhỏ còn lại vào phi thơm lừng. Hương caramel dịu ngọt quyện cùng tinh dầu hành tỏi sả tạo nền màu nâu hổ phách truyền thống đầy cuốn hút.',5,'Canh kỹ khoảnh khắc đường vừa chuyển màu cánh gián là hạ lửa nhỏ nhất ngay để nước màu bóng đẹp mà không bao giờ bị đắng.'),
(221,5,'Đảo săn hai mặt khóa ngọt nguyên liệu chính','Tăng lên lửa vừa lớn, gắp từng miếng trong 500g bánh phở tươi và 250g thịt heo (nạc vai) vào nồi đảo đều hoặc trở nhẹ hai mặt trong 4–5 phút cho săn chắc và bám đều lớp màu nâu óng. Khi bề mặt nguyên liệu se vàng thơm phức mới trút phần nước ướp còn lại trong tô vào đun sôi nhẹ.',7,'Đối với cá kho, chỉ lật cá một lần lúc cá vừa săn mặt trên lửa vừa để khúc cá nguyên vẹn không bị tróc da hay vỡ nát.'),
(221,6,'Kho/om liu riu lửa nhỏ thấm đẫm cùng nước dừa/nước dùng','Chế lượng nước vừa ngập mặt nguyên liệu xâm xắp mặt nguyên liệu (xếp thêm 200g khoai lang và 100g lạp xưởng nếu có), đun sôi bùng một dạo hớt sạch bọt rồi hạ ngay về mức lửa nhỏ liu riu nhất. Kho êm đềm không đậy kín nắp để từng thớ nguyên liệu chín mềm thấm đẫm gia vị và nước sốt rút dần sóng sánh.',12,'Luôn dùng nước sôi hoặc nước dừa ấm khi châm thêm vào nồi kho đang nóng để thịt cá không bị sượng cứng trở lại.'),
(221,7,'Thu sánh nước sốt óng ả & trình bày thưởng thức nóng','Khi nước kho rút còn khoảng 1/3 sánh kẹo óng ánh áo đều quanh nguyên liệu và xiên đũa thấy mềm mọng vừa ý, rắc 50g đậu phộng lên mặt rồi tắt bếp. Múc món Phở chua Lạng Sơn trộn sốt khoai lang giòn ra đĩa sâu lòng hoặc niêu đất giữ nhiệt, dọn ăn nóng cùng cơm trắng dẻo thơm cho 4 người.',5,'Giữ lại một lượng nước sốt sánh kẹo vừa đủ dưới đáy nồi để chan cơm hoặc chấm kèm rau luộc sẽ tròn vị đưa cơm gấp bội.'),
(222,1,'Sơ chế sạch & thấm thật khô bề mặt nguyên liệu','Rửa sạch 1200g thịt vịt cùng chút muối loãng để khử mùi tự nhiên, sau đó dùng khăn giấy bếp thấm thật khô ráo hoàn toàn bề mặt. Khứa nhẹ các đường chéo hoặc cắt miếng vừa ăn dày 2–3cm để nhiệt và gia vị thấm sâu đều khắp bên trong.',12,'Bề mặt nguyên liệu càng khô ráo thì khi chiên không bị văng dầu và khi nướng sẽ lên màu vàng ruộm giòn rụm cực đẹp.'),
(222,2,'Chuẩn bị hỗn hợp sốt ướp / bột áo chuẩn tỷ lệ','Phối trộn 50g lá mắc mật, 30g sả và 25g gừng băm thật nhuyễn (hoặc vắt lấy nước cốt thơm) cùng 35g mật ong, 30ml nước tương, 5g ngũ vị hương và 20ml giấm trong tô lớn cho quyện sánh đồng nhất. Nếu món có lớp vỏ bột hoặc bánh cuốn từ 1200g thịt vịt, trộn đều hỗn hợp theo đúng định lượng để đạt độ giòn xốp mỏng nhẹ chuẩn vị.',11,'Vắt lấy nước cốt hành tỏi sả khi ướp đồ nướng giúp hương thơm thấm sâu mà không bị cháy đen phần xác băm trên lửa cao.'),
(222,3,'Ướp thấm thớ thịt / tạo hình cuốn khéo léo','Áo đều hỗn hợp gia vị hoặc lớp bột/vỏ cuốn quanh 1200g thịt vịt, massage nhẹ nhàng rồi để nghỉ 15–20 phút cho gia vị thẩm thấu trọn vẹn. Trường hợp cuốn chả/nem hoặc đổ khuôn bánh, thao tác đều tay vừa chặt để nhân kết dính nhưng không bị bục rách khi gặp nhiệt.',14,'Để nguyên liệu nghỉ đủ thời gian trước khi chiên nướng giúp lớp áo bột bám chắc và phần nhân bên trong mọng ngọt.');
INSERT INTO `recipe_steps` (`recipe_id`,`step_order`,`title`,`instruction`,`duration_mins`,`tip_note`) VALUES
(222,4,'Pha nước chấm cân vị & sơ chế rau đồ chua ăn kèm','Nhặt rửa sạch rau củ ăn kèm ngâm nước mát cho giòn tươi, bào sợi hoặc thái lát gọn gàng bày sẵn bên cạnh. Pha chén nước chấm chua ngọt hoặc muối ớt chanh sả sánh thơm theo khẩu vị vùng miền của món Vịt quay lá mắc mật Cao Bằng da giòn để cân bằng độ béo giòn.',10,'Luôn chuẩn bị xong rau sống và bát nước chấm trước khi chiên/nướng mẻ cuối để món ăn vừa ra lò là thưởng thức nóng giòn ngay.'),
(222,5,'Làm nóng dầu / lò nướng chuẩn nhiệt & làm chín đều lần 1','Làm nóng chảo dầu hoặc vỉ nướng/nồi chiên ở mức nhiệt vừa khoảng 165–175°C, xếp 1200g thịt vịt vào với khoảng cách thoáng đều nhau. Chiên hoặc nướng trở mặt nhịp nhàng trên lửa vừa để nhiệt dẫn sâu làm chín mềm ngọt hoàn toàn phần nhân bên trong.',18,'Kiểm tra nhiệt dầu bằng đầu đũa tre thấy sủi tăm nhỏ đều là đạt chuẩn 170°C, giúp vỏ không cháy sớm khi bên trong còn sống.'),
(222,6,'Tăng nhiệt khóa giòn rụm vàng ươm bề mặt lần 2','Ở 2–3 phút cuối, tăng lên lửa vừa lớn (khoảng 190°C) hoặc phết thêm lớp dầu điều/mật ong mỏng để vỏ ngoài của Vịt quay lá mắc mật Cao Bằng da giòn chuyển sắc vàng óng ánh và nổ giòn rụm. Lắng nghe tiếng xèo giòn rộn rã và hương thơm phức lan tỏa khắp bếp thì gắp ra vỉ thưa cho ráo dầu thừa.',9,'Đặt đồ chiên nướng lên giá inox thoáng khí thay vì giấy thấm dầu chồng khít để hơi nước thoát hết, giữ độ giòn lâu gấp 3 lần.'),
(222,7,'Trình bày bắt mắt kèm rau thơm & thưởng thức nóng','Xếp thành phẩm vàng giòn ra đĩa lớn có bày sẵn rau củ ăn kèm và điểm xuyết hành ngò và tiêu xay tươi xanh hài hòa màu sắc. Dọn kèm chén nước chấm sánh đậm ngay chính giữa mâm ăn cho 4 người thưởng thức khi vỏ ngoài còn nóng giòn rụm.',6,'Cắt miếng hoặc dọn ăn ngay trong vòng 10 phút sau khi rời bếp để cảm nhận trọn vẹn sự đối lập giòn ngoài - mềm ngọt bên trong.'),
(223,1,'Sơ chế sạch & thấm thật khô bề mặt nguyên liệu','Rửa sạch 800g thịt gà (đùi) cùng chút muối loãng để khử mùi tự nhiên, sau đó dùng khăn giấy bếp thấm thật khô ráo hoàn toàn bề mặt. Khứa nhẹ các đường chéo hoặc cắt miếng vừa ăn dày 2–3cm để nhiệt và gia vị thấm sâu đều khắp bên trong.',9,'Bề mặt nguyên liệu càng khô ráo thì khi chiên không bị văng dầu và khi nướng sẽ lên màu vàng ruộm giòn rụm cực đẹp.'),
(223,2,'Chuẩn bị hỗn hợp sốt ướp / bột áo chuẩn tỷ lệ','Phối trộn 40g sả băm thật nhuyễn (hoặc vắt lấy nước cốt thơm) cùng 8g mắc khén, 4g hạt dổi, 10g ớt và 8g muối trong tô lớn cho quyện sánh đồng nhất. Nếu món có lớp vỏ bột hoặc bánh cuốn từ 800g thịt gà (đùi), trộn đều hỗn hợp theo đúng định lượng để đạt độ giòn xốp mỏng nhẹ chuẩn vị.',8,'Vắt lấy nước cốt hành tỏi sả khi ướp đồ nướng giúp hương thơm thấm sâu mà không bị cháy đen phần xác băm trên lửa cao.'),
(223,3,'Ướp thấm thớ thịt / tạo hình cuốn khéo léo','Áo đều hỗn hợp gia vị hoặc lớp bột/vỏ cuốn quanh 800g thịt gà (đùi), massage nhẹ nhàng rồi để nghỉ 15–20 phút cho gia vị thẩm thấu trọn vẹn. Trường hợp cuốn chả/nem hoặc đổ khuôn bánh, thao tác đều tay vừa chặt để nhân kết dính nhưng không bị bục rách khi gặp nhiệt.',11,'Để nguyên liệu nghỉ đủ thời gian trước khi chiên nướng giúp lớp áo bột bám chắc và phần nhân bên trong mọng ngọt.'),
(223,4,'Pha nước chấm cân vị & sơ chế rau đồ chua ăn kèm','Nhặt rửa sạch rau củ ăn kèm ngâm nước mát cho giòn tươi, bào sợi hoặc thái lát gọn gàng bày sẵn bên cạnh. Pha chén nước chấm chua ngọt hoặc muối ớt chanh sả sánh thơm theo khẩu vị vùng miền của món Gà bản nướng hạt dổi mắc khén Hòa Bình để cân bằng độ béo giòn.',7,'Luôn chuẩn bị xong rau sống và bát nước chấm trước khi chiên/nướng mẻ cuối để món ăn vừa ra lò là thưởng thức nóng giòn ngay.'),
(223,5,'Làm nóng dầu / lò nướng chuẩn nhiệt & làm chín đều lần 1','Làm nóng chảo dầu hoặc vỉ nướng/nồi chiên ở mức nhiệt vừa khoảng 165–175°C, xếp 800g thịt gà (đùi) vào với khoảng cách thoáng đều nhau. Chiên hoặc nướng trở mặt nhịp nhàng trên lửa vừa để nhiệt dẫn sâu làm chín mềm ngọt hoàn toàn phần nhân bên trong.',13,'Kiểm tra nhiệt dầu bằng đầu đũa tre thấy sủi tăm nhỏ đều là đạt chuẩn 170°C, giúp vỏ không cháy sớm khi bên trong còn sống.'),
(223,6,'Tăng nhiệt khóa giòn rụm vàng ươm bề mặt lần 2','Ở 2–3 phút cuối, tăng lên lửa vừa lớn (khoảng 190°C) hoặc phết thêm lớp dầu điều/mật ong mỏng để vỏ ngoài của Gà bản nướng hạt dổi mắc khén Hòa Bình chuyển sắc vàng óng ánh và nổ giòn rụm. Lắng nghe tiếng xèo giòn rộn rã và hương thơm phức lan tỏa khắp bếp thì gắp ra vỉ thưa cho ráo dầu thừa.',7,'Đặt đồ chiên nướng lên giá inox thoáng khí thay vì giấy thấm dầu chồng khít để hơi nước thoát hết, giữ độ giòn lâu gấp 3 lần.'),
(223,7,'Trình bày bắt mắt kèm rau thơm & thưởng thức nóng','Xếp thành phẩm vàng giòn ra đĩa lớn có bày sẵn rau củ ăn kèm và điểm xuyết 15g lá chanh tươi xanh hài hòa màu sắc. Dọn kèm chén nước chấm sánh đậm ngay chính giữa mâm ăn cho 4 người thưởng thức khi vỏ ngoài còn nóng giòn rụm.',5,'Cắt miếng hoặc dọn ăn ngay trong vòng 10 phút sau khi rời bếp để cảm nhận trọn vẹn sự đối lập giòn ngoài - mềm ngọt bên trong.'),
(224,1,'Sơ chế sạch & chuẩn bị nguyên liệu thuần chay','Rửa sạch toàn bộ nguyên liệu dưới vòi nước mát, để ráo tự nhiên trên rổ thưa gồm 600g gạo nếp và 50g lá cẩm cùng 80g thịt gấc. Cắt thái đồng đều kích thước khoảng 3–4cm vừa gắp để khi chế biến chín cùng lúc và thấm đều gia vị thực vật.',12,'Thấm khô bề mặt đậu hũ và nấm bằng khăn giấy bếp trước khi chế biến giúp nguyên liệu săn chắc, không bị bắn dầu hay ra nước.'),
(224,2,'Xử lý độ giòn ngọt của nấm & rau củ','Đối với nhóm nấm và rau củ (600g gạo nếp và 50g lá cẩm), ngâm nhanh qua nước muối loãng 3 phút rồi vắt nhẹ hoặc chần sơ 45 giây trong nước sôi, vớt ngay ra tô nước mát. Thao tác này giúp giữ trọn sắc màu tươi sáng tự nhiên, loại bỏ mùi ngái và tạo độ giòn ngọt thanh khiết cho món Xôi ngũ sắc Tây Bắc đồ lá cẩm nghệ gấc.',10,'Không ngâm nấm quá lâu trong nước lạnh vì nấm sẽ hút nước mạnh làm nhạt vị ngọt umami tự nhiên.'),
(224,3,'Pha chén sốt gia vị chay chuẩn định lượng','Chuẩn bị tô nhỏ, đong chính xác 5g muối khuấy đều cùng 30ml nước ấm hoặc nước ngâm nấm hương cho tan hoàn toàn đường và hạt nêm nấm. Nếm thử thấy vị mặn ngọt hài hòa, thanh dịu đúng tinh thần ẩm thực chay cho khẩu phần 4 người.',8,'Pha sẵn chén sốt trước khi bật bếp giúp kiểm soát chính xác định lượng từng gam và không bị cháy khét gia vị trên chảo nóng.'),
(224,4,'Phi thơm hành boaro & tạo nền hương thảo mộc','Làm nóng nồi hoặc chảo đáy dày trên lửa vừa, cho 80ml nước cốt dừa vào láng đều mặt chảo rồi trút 25g nghệ và 50g lá dứa vào phi thơm. Đảo nhẹ tay khoảng 1–2 phút đến khi hành boaro chuyển sắc vàng óng và dậy mùi thơm dịu thì hạ lửa vừa.',10,'Hành boaro cháy nhanh hơn hành tím nên chỉ phi trên lửa vừa đến khi vừa chớm vàng thơm là cho nguyên liệu chính vào ngay.'),
(224,5,'Chế biến săn thấm nguyên liệu chính thuần thực vật','Cho 600g gạo nếp và 50g lá cẩm vào đảo đều hoặc áp chảo nhẹ hai mặt trên lửa vừa đến khi bề mặt săn vàng, sau đó rưới 2/3 chén sốt gia vị chay đã pha vào. Đảo nhẹ tay để sốt bám đều quanh từng thớ đậu và nấm mà không làm vỡ nát cấu trúc nguyên liệu.',18,'Dùng sạn gỗ đảo nhẹ từ dưới đáy chảo hất lên để miếng đậu hũ và nấm giữ nguyên hình khối vuông vắn đẹp mắt.'),
(224,6,'Phối hợp rau củ & cân chỉnh độ sánh thanh đạm','Tiếp tục cho 80g thịt gấc cùng phần sốt còn lại vào nồi, điều chỉnh lửa vừa nấu thêm cho nguyên liệu chín mềm tới nhưng vẫn giữ độ giòn ngọt. Quan sát thấy nước sốt chuyển màu nâu hổ phách sóng sánh hoặc nước dùng trong thanh, hương thơm quyện đều khắp gian bếp.',14,'Chỉ nấu rau củ xanh vừa chín tới để bảo toàn tối đa lượng chất xơ và vitamin tự nhiên trong khẩu phần chay.'),
(224,7,'Hoàn thiện hương thơm & trình bày món chay thanh tịnh','Tắt bếp ngay khi món ăn đạt độ chín chuẩn, rắc đều 30g mè rang lên bề mặt để dậy mùi thơm tươi mới. Múc món Xôi ngũ sắc Tây Bắc đồ lá cẩm nghệ gấc ra đĩa sứ hoặc tô sâu lòng, thưởng thức nóng cùng cơm trắng hoặc bún tươi cho trọn vẹn 4 khẩu phần.',8,'Rắc rau thơm và tiêu ngay lúc vừa tắt bếp giúp tinh dầu tỏa hương thơm ngát mà lá rau không bị thâm xỉn màu.'),
(225,1,'Sơ chế & thái mỏng đồng đều nguyên liệu xào','Làm sạch và thấm ráo 350g măng trúc và 250g thịt bò, dùng dao sắc thái lát mỏng vừa ăn khoảng 2–3mm ngang thớ để khi xào nhanh chín mềm không bị dai. Nhặt rửa sạch rau củ ăn kèm, cắt khúc xéo 4cm hoặc tách nhánh đồng đều giúp tiếp xúc nhiệt nhanh trên chảo.',5,'Nguyên liệu xào bắt buộc phải để thật ráo nước trước khi cho vào chảo để đạt hiệu ứng áp nhiệt thơm kiểu chảo gang.'),
(225,2,'Ướp mềm nguyên liệu đạm & pha sẵn chén sốt xào','Ướp phần đạm trong 350g măng trúc và 250g thịt bò với 1/3 lượng 25g tỏi, chút dầu ăn và 1/3 lượng 20ml dầu hào trong 10 phút để giữ độ ẩm mọng. Pha phần 20ml dầu hào còn lại cùng 20ml nước lọc vào chén nhỏ khuấy tan hoàn toàn để thao tác xào lửa lớn diễn ra dứt khoát.',5,'Thêm 1 muỗng cà phê dầu ăn vào bước ướp thịt bò/heo giúp khóa ẩm và các lát thịt tơi nhanh không bị dính chùm khi gặp chảo nóng.'),
(225,3,'Chần nhanh rau củ giữ sắc xanh ngọc & độ giòn','Đun sôi nồi nước nhỏ với một nhúm muối, thả rau củ ăn kèm vào chần nhanh 30–45 giây rồi vớt ngay ra tô nước đá lạnh cho sốc nhiệt, sau đó đổ ra rổ cho thật ráo. Bước tiền xử lý này giúp rau củ chín đều từ trong mà bên ngoài vẫn xanh mướt giòn sần sật.',4,'Thời gian chần dưới 1 phút kết hợp ngâm nước đá lạnh là bí quyết nhà hàng giúp đĩa rau xào không bị chảy nước đen đĩa.'),
(225,4,'Xào săn nguyên liệu chính trên lửa lớn nhanh tay','Làm nóng chảo rộng trên lửa lớn nhất với 15ml dầu ăn, phi dậy mùi một nửa 25g tỏi rồi trút phần đạm chính trong 350g măng trúc và 250g thịt bò vào đảo cực nhanh tay trong 60–90 giây. Ngay khi thịt hoặc hải sản vừa chín tái hồng khoảng 85%, lập tức trút riêng ra đĩa sạch để không bị quá lửa khô xác.',5,'Tuyệt đối không xào thịt chung từ đầu đến cuối với rau củ vì thịt sẽ bị dai và tiết nước làm mất độ giòn.'),
(225,5,'Xào rau củ lửa lớn & rưới sốt định lượng khóa vị','Giữ nguyên chảo nóng trên lửa lớn, thêm chút dầu phi thơm nốt phần 25g tỏi còn lại rồi cho rau củ ăn kèm đã ráo nước vào đảo đều 1–2 phút. Trút ngược đĩa đạm vào chảo, rưới đều chén sốt gia vị đã pha và xóc nhanh tay 45 giây cho sốt sánh bóng áo quanh từng miếng nguyên liệu.',5,'Rưới sốt vòng quanh thành chảo nóng thay vì đổ thẳng giữa lòng chảo giúp sốt bốc hơi thơm lừng và sệt lại tức thì.'),
(225,6,'Dậy hương tiêu hành & trình bày nóng hổi','Cho 20g rau răm và 20g hành lá vào đảo nhẹ đúng 1 lượt rồi tắt bếp ngay khi khói thơm bốc lên nghi ngút. Gắp món Măng trúc Yên Tử xào thịt bò tỏi thơm ra đĩa rộng lòng để tản nhiệt đều, tránh đậy kín vung và thưởng thức nóng ngay cùng cơm dẻo cho 4 người.',3,'Bày món xào ra đĩa rộng không xếp chồng quá dày giúp hơi nóng thoát nhẹ, giữ rau củ giòn ngọt lâu đến miếng cuối cùng.'),
(226,1,'Sơ chế tươi sạch & ngâm giòn rau củ thảo mộc','Nhặt rửa kỹ rau củ ăn kèm cùng 60g đậu phộng và 20g mè rang qua nước muối loãng rồi tráng nước đun sôi để nguội. Với các loại củ quả bào sợi hoặc thái lát mỏng, ngâm vào âu nước đá lạnh pha chút chanh đường trong 10 phút rồi vắt ráo để giữ độ trắng giòn sần sật.',6,'Rau củ làm gỏi và món cuốn phải quay rổ hoặc thấm thật ráo nước để khi trộn nước mắm không bị loãng nhạt.');
INSERT INTO `recipe_steps` (`recipe_id`,`step_order`,`title`,`instruction`,`duration_mins`,`tip_note`) VALUES
(226,2,'Làm chín tới phần nhân đạm giữ trọn độ ngọt mọng','Xử lý phần nguyên liệu chính (300g rau dớn và 200g măng tươi): luộc hấp cùng lát gừng sả đập dập hoặc xào lửa lớn vừa chín tới, sau đó làm nguội nhanh rồi thái lát mỏng / xé sợi đều đặn. Nếu món có pha bột bánh gạo/bột năng, khuấy tan bột với nước đúng tỷ lệ và để bột nghỉ 15 phút cho nở mịn.',8,'Ngâm tôm hoặc thịt luộc qua bát nước sôi để nguội có vài viên đá giúp màu sắc tươi hồng và thớ thịt giòn ngọt không bị khô.'),
(226,3,'Rang vàng đậu phộng mè thơm & phi hành tỏi giòn','Bắc chảo nhỏ lên lửa nhỏ, rang chín vàng thơm đậu phộng/mè hoặc làm mỡ hành xanh mướt và phi vàng giòn 15g tỏi. Vớt hành tỏi phi ra đĩa riêng để nguội giòn tan, giữ lại phần dầu thơm óng ánh để phết bánh hoặc rưới bóng mặt món ăn.',4,'Tắt bếp ngay khi hành phi chuyển vàng sáng vì nhiệt dư trong dầu nóng sẽ tiếp tục làm hành sẫm màu thêm một nấc hoàn hảo.'),
(226,4,'Pha nước mắm chấm / sốt trộn tỷ lệ vàng chua ngọt','Hòa tan hoàn toàn đường cùng 25ml chanh, 25ml nước mắm và 25g đường và nước ấm trong chén sâu lòng, khuấy đến khi hơi sánh nhẹ mới cho tỏi ớt băm nhuyễn và nước cốt chanh/tắc vào sau cùng. Công thức pha này giúp tỏi ớt nổi đều đẹp mắt trên bề mặt bát nước chấm chuẩn vị Nộm măng rừng rau dớn đậu phộng Tây Bắc.',4,'Băm tỏi ớt thật ráo trên thớt khô và cho vào sau khi đường mắm đã nguội thì tỏi ớt sẽ nổi bồng bềnh 100% không bị chìm đáy.'),
(226,5,'Phối trộn thấm vị / tráng hấp & cuốn đều tay','Tiến hành tráng hấp bánh mỏng mượt hoặc trải bánh cuốn gọn gàng 300g rau dớn và 200g măng tươi cùng rau củ ăn kèm; nếu là món gỏi trộn thì rưới từ từ 2/3 lượng sốt chua ngọt vào bóp nhẹ tay cho thấm đều trong 3 phút. Giữ lực tay nhẹ nhàng để rau củ không bị dập nát mà vẫn ngấm trọn vị mặn chua ngọt hài hòa.',5,'Chia nước sốt gỏi làm 2 lần trộn và chắt bỏ phần nước tiết ra ở lần đầu giúp đĩa gỏi khô ráo, đậm đà như ngoài hàng.'),
(226,6,'Bày biện ngũ sắc hài hòa & rắc topping giòn bùi','Xếp món Nộm măng rừng rau dớn đậu phộng Tây Bắc ngay ngắn ra đĩa sứ trắng rộng, rải đều phần nhân tôm thịt sắc nét lên trên và rắc phủ 60g đậu phộng và 20g mè rang thơm giòn. Dọn kèm chén nước chấm đậm đà cho 4 người thưởng thức ngay khi rau bánh còn tươi giòn mướt mịn.',3,'Chỉ rắc đậu phộng rang và hành phi ngay trước lúc mang ra bàn ăn để giữ nguyên độ giòn tan bùi béo.'),
(227,1,'Sơ chế tươi sạch & ngâm giòn rau củ thảo mộc','Nhặt rửa kỹ rau củ ăn kèm cùng 20g hành phi và 25g hành lá qua nước muối loãng rồi tráng nước đun sôi để nguội. Với các loại củ quả bào sợi hoặc thái lát mỏng, ngâm vào âu nước đá lạnh pha chút chanh đường trong 10 phút rồi vắt ráo để giữ độ trắng giòn sần sật.',9,'Rau củ làm gỏi và món cuốn phải quay rổ hoặc thấm thật ráo nước để khi trộn nước mắm không bị loãng nhạt.'),
(227,2,'Làm chín tới phần nhân đạm giữ trọn độ ngọt mọng','Xử lý phần nguyên liệu chính (220g bột gạo và 40g bột năng): luộc hấp cùng lát gừng sả đập dập hoặc xào lửa lớn vừa chín tới, sau đó làm nguội nhanh rồi thái lát mỏng / xé sợi đều đặn. Nếu món có pha bột bánh gạo/bột năng, khuấy tan bột với nước đúng tỷ lệ và để bột nghỉ 15 phút cho nở mịn.',12,'Ngâm tôm hoặc thịt luộc qua bát nước sôi để nguội có vài viên đá giúp màu sắc tươi hồng và thớ thịt giòn ngọt không bị khô.'),
(227,3,'Rang vàng đậu phộng mè thơm & phi hành tỏi giòn','Bắc chảo nhỏ lên lửa nhỏ, rang chín vàng thơm đậu phộng/mè hoặc làm mỡ hành xanh mướt và phi vàng giòn hành tím và tỏi băm nhỏ. Vớt hành tỏi phi ra đĩa riêng để nguội giòn tan, giữ lại phần dầu thơm óng ánh để phết bánh hoặc rưới bóng mặt món ăn.',6,'Tắt bếp ngay khi hành phi chuyển vàng sáng vì nhiệt dư trong dầu nóng sẽ tiếp tục làm hành sẫm màu thêm một nấc hoàn hảo.'),
(227,4,'Pha nước mắm chấm / sốt trộn tỷ lệ vàng chua ngọt','Hòa tan hoàn toàn đường cùng gia vị chuẩn định lượng và nước ấm trong chén sâu lòng, khuấy đến khi hơi sánh nhẹ mới cho tỏi ớt băm nhuyễn và nước cốt chanh/tắc vào sau cùng. Công thức pha này giúp tỏi ớt nổi đều đẹp mắt trên bề mặt bát nước chấm chuẩn vị Bánh cuốn trứng nóng Cao Bằng nước hầm xương.',6,'Băm tỏi ớt thật ráo trên thớt khô và cho vào sau khi đường mắm đã nguội thì tỏi ớt sẽ nổi bồng bềnh 100% không bị chìm đáy.'),
(227,5,'Phối trộn thấm vị / tráng hấp & cuốn đều tay','Tiến hành tráng hấp bánh mỏng mượt hoặc trải bánh cuốn gọn gàng 220g bột gạo và 40g bột năng cùng rau củ ăn kèm; nếu là món gỏi trộn thì rưới từ từ 2/3 lượng sốt chua ngọt vào bóp nhẹ tay cho thấm đều trong 3 phút. Giữ lực tay nhẹ nhàng để rau củ không bị dập nát mà vẫn ngấm trọn vị mặn chua ngọt hài hòa.',8,'Chia nước sốt gỏi làm 2 lần trộn và chắt bỏ phần nước tiết ra ở lần đầu giúp đĩa gỏi khô ráo, đậm đà như ngoài hàng.'),
(227,6,'Bày biện ngũ sắc hài hòa & rắc topping giòn bùi','Xếp món Bánh cuốn trứng nóng Cao Bằng nước hầm xương ngay ngắn ra đĩa sứ trắng rộng, rải đều phần nhân tôm thịt sắc nét lên trên và rắc phủ 20g hành phi và 25g hành lá thơm giòn. Dọn kèm chén nước chấm đậm đà cho 4 người thưởng thức ngay khi rau bánh còn tươi giòn mướt mịn.',4,'Chỉ rắc đậu phộng rang và hành phi ngay trước lúc mang ra bàn ăn để giữ nguyên độ giòn tan bùi béo.'),
(228,1,'Tuyển chọn, ngâm nở & sơ chế sạch nguyên liệu chè bánh','Đãi rửa sạch nhóm hạt, củ hoặc bột (250g bột nếp), ngâm nước ấm theo đúng đặc tính từng loại để hạt nở mềm đồng đều và loại bỏ nhựa chát. Rửa sạch nhóm tạo hương tự nhiên gồm 45g gừng để ráo nước.',8,'Thêm một nhúm muối nhỏ vào nước ngâm khoai và đậu giúp nguyên liệu giữ màu tươi sáng và khi nấu chín bùi hơn.'),
(228,2,'Ninh mềm bùi nguyên liệu chính giữ nguyên hạt/khối','Cho phần nguyên liệu nền trong 250g bột nếp vào nồi đáy dày cùng lượng nước vừa đủ, đun sôi rồi hạ lửa nhỏ ninh êm đến khi chín mềm bùi nhưng không bị vỡ nát đục nước. Nếu có trân châu, bột lọc hoặc hạt lựu, luộc riêng trong nồi nước sôi đến khi nổi trong veo rồi vớt ngâm ngay vào bát nước mát.',11,'Tuyệt đối không cho đường ngay từ đầu khi đậu và khoai chưa chín mềm vì đường sẽ làm săn vỏ hạt khiến nấu mãi vẫn sượng.'),
(228,3,'Nấu nước đường phèn / mật mía thanh trong dậy hương','Kết hợp chính xác định lượng 200ml mật mía và 60g đường vào nồi cùng bó lá dứa hoặc gừng thái chỉ, khuấy nhẹ trên lửa nhỏ cho tan trong vắt. Đun liu riu thêm 5–7 phút để vị ngọt thấm sâu vào từng viên nguyên liệu và tỏa hương thơm dịu tao nhã.',7,'Dùng đường phèn hoặc mật mía đun lửa nhỏ hớt bọt kỹ giúp hậu vị chè ngọt thanh mát họng, không bị khé cổ.'),
(228,4,'Thắng nước cốt dừa béo mịn / chuẩn bị lớp kem phủ','Cho nước cốt dừa vào nồi nhỏ cùng 2g muối tinh và 5g bột năng/bột bắp hòa loãng, khuấy đều tay trên lửa nhỏ nhất đến khi vừa chớm sôi lăn tăn sánh mượt. Tắt bếp ngay để nước cốt dừa giữ màu trắng ngần béo ngậy mà không bị tách lớp dầu.',6,'Một chút xíu muối tinh trong nồi nước cốt dừa sẽ làm bật hẳn độ béo thơm tự nhiên và cân bằng vị ngọt của món tráng miệng.'),
(228,5,'Phối hợp độ sánh mượt & cân bằng hương vị tổng thể','Hợp nhất các thành phần của món Chè lam gừng đậu phộng Bắc Giang dẻo ấm, từ từ rưới nước bột năng hòa loãng (nếu là chè sánh) đồng thời khuấy nhẹ một chiều trên lửa nhỏ cho hỗn hợp bóng mượt như nhung. Kiểm tra độ mềm dẻo hài hòa và tắt bếp để ủ hương thảo mộc lan tỏa đều.',5,'Rót nước bột tạo sánh thành dòng mảnh vừa rót vừa khuấy đều tay giúp chè trong mượt, hoàn toàn không bị ốc trâu vón cục.'),
(228,6,'Múc ra chén sứ, điểm topping & thưởng thức ấm/lạnh','Múc chè hoặc bày bánh ra 4 chén nhỏ xinh, chan lớp nước cốt dừa trắng mịn lên mặt và rắc nhẹ 100g đậu phộng và 25g mè trắng. Thưởng thức ấm nóng dịu dàng hoặc thêm đá bào mát lạnh tùy sở thích đều trọn vị ngon truyền thống.',3,'Để chè nguội bớt về khoảng 45°C hoặc ướp mát 30 phút trong ngăn mát tủ lạnh giúp các tầng hương vị kết tinh đậm đà hơn.'),
(229,1,'Sơ chế & chần sạch nguyên liệu xương thịt, hải sản','Rửa sạch 450g lươn đồng và 200g bánh mì với muối hạt rồi chần nhanh trong nồi nước sôi có đập dập 1 nhánh gừng trong 2–3 phút trên lửa lớn để loại bỏ hoàn toàn bọt bẩn. Rửa lại dưới làn nước sạch cho thật trắng trẻo, đồng thời nhặt rửa sạch 30g rau răm để ráo nước.',7,'Bước chần sơ và rửa lại bằng nước ấm là bí quyết vàng giúp nồi nước dùng trong vắt, thơm thanh và không bao giờ bị đục hay hôi.'),
(229,2,'Nướng thơm thảo mộc & ninh nền nước dùng ngọt thanh','Cho phần nguyên liệu tạo ngọt từ 450g lươn đồng và 200g bánh mì cùng 40g hành tăm và 30g nghệ đã nướng xém thơm vào nồi sâu lòng với khoảng 1.5–1.8 lít nước lọc. Đun sôi bùng trên lửa lớn rồi hạ ngay về lửa nhỏ liu riu, mở hé vung và hớt kỹ bọt nổi trên mặt để chiết xuất vị ngọt tự nhiên.',16,'Luôn duy trì mặt nước lăn tăn nhẹ thay vì đun sôi sùng sục lửa to để protein không bị nhũ hóa gây đục nước lèo.'),
(229,3,'Xào tạo màu & dậy hương đặc trưng vùng miền','Bắc chảo nhỏ lên bếp với 15ml dầu ăn trên lửa vừa, phi thơm phần hành tỏi sả băm còn lại rồi xào săn 15g bột năng cùng 15g sa tế và 20ml nước mắm trong 3–4 phút. Khi hỗn hợp dậy mùi thơm nồng nàn và lên sắc màu óng ả đặc trưng của món Súp lươn cay Nghệ An ăn kèm bánh mì thì tắt bếp.',6,'Xào riêng phần nguyên liệu tạo màu và gia vị thơm trước khi trút vào nồi nước dùng giúp tầng hương dậy lên rõ nét gấp đôi.'),
(229,4,'Sơ chế & cắt thái phần nhân topping xếp tô','Vớt phần thịt hoặc hải sản chín tới từ 450g lươn đồng và 200g bánh mì ra ngâm ngay vào âu nước đun sôi để nguội giúp bề mặt săn giòn mọng nước, không bị thâm khô. Thái lát mỏng đều tay dày khoảng 3mm ngang thớ hoặc gỡ miếng vừa ăn, sắp riêng từng phần gọn gàng trên đĩa.',6,'Thái thịt ngang thớ với lưỡi dao thật sắc giúp lát thịt mềm mướt, khi chan nước dùng sôi lên sẽ phẳng đẹp không bị quăn cứng.'),
(229,5,'Hợp nhất nồi nước lèo & nêm chuẩn định lượng','Trút phần sốt màu thơm vào nồi nước dùng đang sôi lăn tăn, nêm chính xác lượng 15g sa tế và 20ml nước mắm còn lại cho vừa miệng 4 người ăn. Đun nhẹ thêm 5 phút ở lửa vừa để các tầng vị mặn dịu, ngọt hậu từ xương thịt và thảo mộc hòa quyện tròn trịa.',6,'Nên nêm nước mắm ngon ở giai đoạn cuối trên lửa nhỏ để giữ trọn hậu vị ngọt đạm và hương thơm mà không làm nước dùng bị chua.'),
(229,6,'Chần nóng sợi bánh/bún & chuẩn bị rau ăn kèm','Đun sôi một nồi nước riêng, cho phần sợi bún/phở/bánh trong 450g lươn đồng và 200g bánh mì vào trụng nhanh 15–25 giây cho sợi mềm dẻo nóng hổi rồi vẩy thật ráo nước, chia đều vào 4 tô lớn. Chần sơ thêm rau ăn kèm (giá đỗ, rau xanh) nếu muốn dùng chín giòn.',5,'Trụng bún bánh ở nồi nước sôi riêng biệt giúp nước dùng chính không bị nhiễm tinh bột chua và tô bún luôn ráo sợi, thấm vị.'),
(229,7,'Xếp nhân hài hòa, chan nước dùng sôi & thưởng thức','Xếp đều các phần nhân thịt, hải sản lên mặt tô bún bánh, điểm xuyết 30g rau răm lên trên cùng. Dùng muôi múc nước dùng đang sôi thật già chan ngập xăm xắp mặt nguyên liệu để làm chín thơm hành ngò, dọn nóng ngay kèm chanh ớt tươi.',4,'Tráng nóng tô sứ bằng nước sôi trước khi xếp bún giúp tô món nước giữ nhiệt bốc khói nghi ngút suốt bữa ăn.'),
(230,1,'Sơ chế & chần sạch nguyên liệu xương thịt, hải sản','Rửa sạch 400g lươn đồng và 160g gạo tẻ với muối hạt rồi chần nhanh trong nồi nước sôi có đập dập 1 nhánh gừng trong 2–3 phút trên lửa lớn để loại bỏ hoàn toàn bọt bẩn. Rửa lại dưới làn nước sạch cho thật trắng trẻo, đồng thời nhặt rửa sạch 30g rau răm để ráo nước.',8,'Bước chần sơ và rửa lại bằng nước ấm là bí quyết vàng giúp nồi nước dùng trong vắt, thơm thanh và không bao giờ bị đục hay hôi.');
INSERT INTO `recipe_steps` (`recipe_id`,`step_order`,`title`,`instruction`,`duration_mins`,`tip_note`) VALUES
(230,2,'Nướng thơm thảo mộc & ninh nền nước dùng ngọt thanh','Cho phần nguyên liệu tạo ngọt từ 400g lươn đồng và 160g gạo tẻ cùng 35g hành tăm và 25g nghệ đã nướng xém thơm vào nồi sâu lòng với khoảng 1.5–1.8 lít nước lọc. Đun sôi bùng trên lửa lớn rồi hạ ngay về lửa nhỏ liu riu, mở hé vung và hớt kỹ bọt nổi trên mặt để chiết xuất vị ngọt tự nhiên.',20,'Luôn duy trì mặt nước lăn tăn nhẹ thay vì đun sôi sùng sục lửa to để protein không bị nhũ hóa gây đục nước lèo.'),
(230,3,'Xào tạo màu & dậy hương đặc trưng vùng miền','Bắc chảo nhỏ lên bếp với 15ml dầu ăn trên lửa vừa, phi thơm phần hành tỏi sả băm còn lại rồi xào săn 30g gạo nếp cùng 20ml nước mắm và 4g tiêu trong 3–4 phút. Khi hỗn hợp dậy mùi thơm nồng nàn và lên sắc màu óng ả đặc trưng của món Cháo lươn đồng xứ Nghệ nghệ tươi rau răm thì tắt bếp.',7,'Xào riêng phần nguyên liệu tạo màu và gia vị thơm trước khi trút vào nồi nước dùng giúp tầng hương dậy lên rõ nét gấp đôi.'),
(230,4,'Sơ chế & cắt thái phần nhân topping xếp tô','Vớt phần thịt hoặc hải sản chín tới từ 400g lươn đồng và 160g gạo tẻ ra ngâm ngay vào âu nước đun sôi để nguội giúp bề mặt săn giòn mọng nước, không bị thâm khô. Thái lát mỏng đều tay dày khoảng 3mm ngang thớ hoặc gỡ miếng vừa ăn, sắp riêng từng phần gọn gàng trên đĩa.',7,'Thái thịt ngang thớ với lưỡi dao thật sắc giúp lát thịt mềm mướt, khi chan nước dùng sôi lên sẽ phẳng đẹp không bị quăn cứng.'),
(230,5,'Hợp nhất nồi nước lèo & nêm chuẩn định lượng','Trút phần sốt màu thơm vào nồi nước dùng đang sôi lăn tăn, nêm chính xác lượng 20ml nước mắm và 4g tiêu còn lại cho vừa miệng 4 người ăn. Đun nhẹ thêm 5 phút ở lửa vừa để các tầng vị mặn dịu, ngọt hậu từ xương thịt và thảo mộc hòa quyện tròn trịa.',7,'Nên nêm nước mắm ngon ở giai đoạn cuối trên lửa nhỏ để giữ trọn hậu vị ngọt đạm và hương thơm mà không làm nước dùng bị chua.'),
(230,6,'Chần nóng sợi bánh/bún & chuẩn bị rau ăn kèm','Đun sôi một nồi nước riêng, cho phần sợi bún/phở/bánh trong 400g lươn đồng và 160g gạo tẻ vào trụng nhanh 15–25 giây cho sợi mềm dẻo nóng hổi rồi vẩy thật ráo nước, chia đều vào 4 tô lớn. Chần sơ thêm rau ăn kèm (giá đỗ, rau xanh) nếu muốn dùng chín giòn.',6,'Trụng bún bánh ở nồi nước sôi riêng biệt giúp nước dùng chính không bị nhiễm tinh bột chua và tô bún luôn ráo sợi, thấm vị.'),
(230,7,'Xếp nhân hài hòa, chan nước dùng sôi & thưởng thức','Xếp đều các phần nhân thịt, hải sản lên mặt tô bún bánh, điểm xuyết 30g rau răm lên trên cùng. Dùng muôi múc nước dùng đang sôi thật già chan ngập xăm xắp mặt nguyên liệu để làm chín thơm hành ngò, dọn nóng ngay kèm chanh ớt tươi.',5,'Tráng nóng tô sứ bằng nước sôi trước khi xếp bún giúp tô món nước giữ nhiệt bốc khói nghi ngút suốt bữa ăn.'),
(231,1,'Sơ chế sạch & thấm thật khô bề mặt nguyên liệu','Rửa sạch 350g tôm sú và 150g thịt ba chỉ cùng chút muối loãng để khử mùi tự nhiên, sau đó dùng khăn giấy bếp thấm thật khô ráo hoàn toàn bề mặt. Khứa nhẹ các đường chéo hoặc cắt miếng vừa ăn dày 2–3cm để nhiệt và gia vị thấm sâu đều khắp bên trong.',7,'Bề mặt nguyên liệu càng khô ráo thì khi chiên không bị văng dầu và khi nướng sẽ lên màu vàng ruộm giòn rụm cực đẹp.'),
(231,2,'Chuẩn bị hỗn hợp sốt ướp / bột áo chuẩn tỷ lệ','Phối trộn 20g hành tím băm thật nhuyễn (hoặc vắt lấy nước cốt thơm) cùng 30ml nước mắm trong tô lớn cho quyện sánh đồng nhất. Nếu món có lớp vỏ bột hoặc bánh cuốn từ 350g tôm sú và 150g thịt ba chỉ, trộn đều hỗn hợp theo đúng định lượng để đạt độ giòn xốp mỏng nhẹ chuẩn vị.',6,'Vắt lấy nước cốt hành tỏi sả khi ướp đồ nướng giúp hương thơm thấm sâu mà không bị cháy đen phần xác băm trên lửa cao.'),
(231,3,'Ướp thấm thớ thịt / tạo hình cuốn khéo léo','Áo đều hỗn hợp gia vị hoặc lớp bột/vỏ cuốn quanh 350g tôm sú và 150g thịt ba chỉ, massage nhẹ nhàng rồi để nghỉ 15–20 phút cho gia vị thẩm thấu trọn vẹn. Trường hợp cuốn chả/nem hoặc đổ khuôn bánh, thao tác đều tay vừa chặt để nhân kết dính nhưng không bị bục rách khi gặp nhiệt.',8,'Để nguyên liệu nghỉ đủ thời gian trước khi chiên nướng giúp lớp áo bột bám chắc và phần nhân bên trong mọng ngọt.'),
(231,4,'Pha nước chấm cân vị & sơ chế rau đồ chua ăn kèm','Nhặt rửa sạch 120g đu đủ xanh và 150g rau sống ngâm nước mát cho giòn tươi, bào sợi hoặc thái lát gọn gàng bày sẵn bên cạnh. Pha chén nước chấm chua ngọt hoặc muối ớt chanh sả sánh thơm theo khẩu vị vùng miền của món Chả tôm nướng Thanh Hóa cuốn rau sống để cân bằng độ béo giòn.',5,'Luôn chuẩn bị xong rau sống và bát nước chấm trước khi chiên/nướng mẻ cuối để món ăn vừa ra lò là thưởng thức nóng giòn ngay.'),
(231,5,'Làm nóng dầu / lò nướng chuẩn nhiệt & làm chín đều lần 1','Làm nóng chảo dầu hoặc vỉ nướng/nồi chiên ở mức nhiệt vừa khoảng 165–175°C, xếp 350g tôm sú và 150g thịt ba chỉ vào với khoảng cách thoáng đều nhau. Chiên hoặc nướng trở mặt nhịp nhàng trên lửa vừa để nhiệt dẫn sâu làm chín mềm ngọt hoàn toàn phần nhân bên trong.',10,'Kiểm tra nhiệt dầu bằng đầu đũa tre thấy sủi tăm nhỏ đều là đạt chuẩn 170°C, giúp vỏ không cháy sớm khi bên trong còn sống.'),
(231,6,'Tăng nhiệt khóa giòn rụm vàng ươm bề mặt lần 2','Ở 2–3 phút cuối, tăng lên lửa vừa lớn (khoảng 190°C) hoặc phết thêm lớp dầu điều/mật ong mỏng để vỏ ngoài của Chả tôm nướng Thanh Hóa cuốn rau sống chuyển sắc vàng óng ánh và nổ giòn rụm. Lắng nghe tiếng xèo giòn rộn rã và hương thơm phức lan tỏa khắp bếp thì gắp ra vỉ thưa cho ráo dầu thừa.',5,'Đặt đồ chiên nướng lên giá inox thoáng khí thay vì giấy thấm dầu chồng khít để hơi nước thoát hết, giữ độ giòn lâu gấp 3 lần.'),
(231,7,'Trình bày bắt mắt kèm rau thơm & thưởng thức nóng','Xếp thành phẩm vàng giòn ra đĩa lớn có bày sẵn 120g đu đủ xanh và 150g rau sống và điểm xuyết hành ngò và tiêu xay tươi xanh hài hòa màu sắc. Dọn kèm chén nước chấm sánh đậm ngay chính giữa mâm ăn cho 4 người thưởng thức khi vỏ ngoài còn nóng giòn rụm.',4,'Cắt miếng hoặc dọn ăn ngay trong vòng 10 phút sau khi rời bếp để cảm nhận trọn vẹn sự đối lập giòn ngoài - mềm ngọt bên trong.'),
(232,1,'Sơ chế & chần sạch nguyên liệu xương thịt, hải sản','Rửa sạch 400g nem chua và 100g bột chiên xù với muối hạt rồi chần nhanh trong nồi nước sôi có đập dập 1 nhánh gừng trong 2–3 phút trên lửa lớn để loại bỏ hoàn toàn bọt bẩn. Rửa lại dưới làn nước sạch cho thật trắng trẻo, đồng thời nhặt rửa sạch 150g dưa leo và 100g xoài xanh để ráo nước.',4,'Bước chần sơ và rửa lại bằng nước ấm là bí quyết vàng giúp nồi nước dùng trong vắt, thơm thanh và không bao giờ bị đục hay hôi.'),
(232,2,'Nướng thơm thảo mộc & ninh nền nước dùng ngọt thanh','Cho phần nguyên liệu tạo ngọt từ 400g nem chua và 100g bột chiên xù cùng hành tím và tỏi băm nhỏ đã nướng xém thơm vào nồi sâu lòng với khoảng 1.5–1.8 lít nước lọc. Đun sôi bùng trên lửa lớn rồi hạ ngay về lửa nhỏ liu riu, mở hé vung và hớt kỹ bọt nổi trên mặt để chiết xuất vị ngọt tự nhiên.',9,'Luôn duy trì mặt nước lăn tăn nhẹ thay vì đun sôi sùng sục lửa to để protein không bị nhũ hóa gây đục nước lèo.'),
(232,3,'Xào tạo màu & dậy hương đặc trưng vùng miền','Bắc chảo nhỏ lên bếp với 15ml dầu ăn trên lửa vừa, phi thơm phần hành tỏi sả băm còn lại rồi xào săn 60g bột mì và 2 quả trứng gà cùng 50g tương ớt trong 3–4 phút. Khi hỗn hợp dậy mùi thơm nồng nàn và lên sắc màu óng ả đặc trưng của món Nem chua rán giòn phố cổ chấm tương ớt thì tắt bếp.',4,'Xào riêng phần nguyên liệu tạo màu và gia vị thơm trước khi trút vào nồi nước dùng giúp tầng hương dậy lên rõ nét gấp đôi.'),
(232,4,'Sơ chế & cắt thái phần nhân topping xếp tô','Vớt phần thịt hoặc hải sản chín tới từ 400g nem chua và 100g bột chiên xù ra ngâm ngay vào âu nước đun sôi để nguội giúp bề mặt săn giòn mọng nước, không bị thâm khô. Thái lát mỏng đều tay dày khoảng 3mm ngang thớ hoặc gỡ miếng vừa ăn, sắp riêng từng phần gọn gàng trên đĩa.',4,'Thái thịt ngang thớ với lưỡi dao thật sắc giúp lát thịt mềm mướt, khi chan nước dùng sôi lên sẽ phẳng đẹp không bị quăn cứng.'),
(232,5,'Hợp nhất nồi nước lèo & nêm chuẩn định lượng','Trút phần sốt màu thơm vào nồi nước dùng đang sôi lăn tăn, nêm chính xác lượng 50g tương ớt còn lại cho vừa miệng 4 người ăn. Đun nhẹ thêm 5 phút ở lửa vừa để các tầng vị mặn dịu, ngọt hậu từ xương thịt và thảo mộc hòa quyện tròn trịa.',4,'Nên nêm nước mắm ngon ở giai đoạn cuối trên lửa nhỏ để giữ trọn hậu vị ngọt đạm và hương thơm mà không làm nước dùng bị chua.'),
(232,6,'Chần nóng sợi bánh/bún & chuẩn bị rau ăn kèm','Đun sôi một nồi nước riêng, cho phần sợi bún/phở/bánh trong 400g nem chua và 100g bột chiên xù vào trụng nhanh 15–25 giây cho sợi mềm dẻo nóng hổi rồi vẩy thật ráo nước, chia đều vào 4 tô lớn. Chần sơ thêm rau ăn kèm (150g dưa leo và 100g xoài xanh) nếu muốn dùng chín giòn.',3,'Trụng bún bánh ở nồi nước sôi riêng biệt giúp nước dùng chính không bị nhiễm tinh bột chua và tô bún luôn ráo sợi, thấm vị.'),
(232,7,'Xếp nhân hài hòa, chan nước dùng sôi & thưởng thức','Xếp đều các phần nhân thịt, hải sản lên mặt tô bún bánh, điểm xuyết hành ngò và tiêu xay lên trên cùng. Dùng muôi múc nước dùng đang sôi thật già chan ngập xăm xắp mặt nguyên liệu để làm chín thơm hành ngò, dọn nóng ngay kèm chanh ớt tươi.',2,'Tráng nóng tô sứ bằng nước sôi trước khi xếp bún giúp tô món nước giữ nhiệt bốc khói nghi ngút suốt bữa ăn.'),
(233,1,'Sơ chế sạch & cắt thái nguyên liệu đúng kích cỡ','Rửa sạch 650g mực ống cùng các nguyên liệu phối kèm dưới vòi nước mát rồi để thật ráo trên rổ thưa. Dùng dao sắc cắt thái nguyên liệu thành từng khúc hoặc khối vuông đều đặn khoảng 3.5–4cm để khi kho hầm giữ nguyên hình dáng đẹp mắt mà không bị vụn nát.',4,'Cắt miếng thịt/cá dày dặn đồng đều giúp quá trình kho lâu trên lửa nhỏ thớ thịt mềm rục mà vẫn giữ trọn độ mọng ngọt bên trong.'),
(233,2,'Khử mùi tự nhiên & làm săn sạch bề mặt nguyên liệu','Chà nhẹ phần đạm chính trong 650g mực ống với chút muối hạt, lát gừng đập dập hoặc chần sơ qua nước sôi 90 giây rồi rửa sạch lại bằng nước ấm, để ráo hoàn toàn. Công đoạn này loại bỏ triệt để tạp chất và mùi tanh hôi, giúp nước sốt món Mực ống tươi hấp gừng sả Cửa Lò trong bóng thơm ngon.',3,'Sau khi chần hoặc rửa sạch, để nguyên liệu ráo nước ít nhất 5 phút trước khi ướp để gia vị rút sâu trực tiếp vào từng thớ thịt.'),
(233,3,'Pha hỗn hợp gia vị & ướp thấm chuẩn định lượng','Cho 650g mực ống vào tô lớn, ướp cùng một nửa 40g gừng và 60g sả băm nhỏ và định lượng chuẩn 12g ớt, 35ml nước mắm, 20ml chanh và 18g đường, đảo nhẹ tay cho gia vị phủ kín đều các mặt. Bọc kín tô và để nguyên liệu nghỉ thấm vị tối thiểu 20 phút ở nhiệt độ phòng (hoặc ngăn mát tủ lạnh).',4,'Ướp đủ tối thiểu 20 phút trước khi bắc lên bếp là chìa khóa để tâm miếng thịt/cá đậm đà đồng nhất với lớp sốt bên ngoài.'),
(233,4,'Thắng nước màu cánh gián & phi dậy hương hành tỏi','Đặt nồi đáy dày lên bếp ở lửa vừa nhỏ, thắng nhẹ 15g đường với 15ml dầu ăn đến khi chuyển sắc nâu cánh gián óng ả thì cho ngay phần 40g gừng và 60g sả còn lại vào phi thơm lừng. Hương caramel dịu ngọt quyện cùng tinh dầu hành tỏi sả tạo nền màu nâu hổ phách truyền thống đầy cuốn hút.',3,'Canh kỹ khoảnh khắc đường vừa chuyển màu cánh gián là hạ lửa nhỏ nhất ngay để nước màu bóng đẹp mà không bao giờ bị đắng.'),
(233,5,'Đảo săn hai mặt khóa ngọt nguyên liệu chính','Tăng lên lửa vừa lớn, gắp từng miếng trong 650g mực ống vào nồi đảo đều hoặc trở nhẹ hai mặt trong 4–5 phút cho săn chắc và bám đều lớp màu nâu óng. Khi bề mặt nguyên liệu se vàng thơm phức mới trút phần nước ướp còn lại trong tô vào đun sôi nhẹ.',4,'Đối với cá kho, chỉ lật cá một lần lúc cá vừa săn mặt trên lửa vừa để khúc cá nguyên vẹn không bị tróc da hay vỡ nát.');
INSERT INTO `recipe_steps` (`recipe_id`,`step_order`,`title`,`instruction`,`duration_mins`,`tip_note`) VALUES
(233,6,'Kho/om liu riu lửa nhỏ thấm đẫm cùng nước dừa/nước dùng','Chế lượng nước vừa ngập mặt nguyên liệu xâm xắp mặt nguyên liệu (xếp thêm rau củ ăn kèm nếu có), đun sôi bùng một dạo hớt sạch bọt rồi hạ ngay về mức lửa nhỏ liu riu nhất. Kho êm đềm không đậy kín nắp để từng thớ nguyên liệu chín mềm thấm đẫm gia vị và nước sốt rút dần sóng sánh.',6,'Luôn dùng nước sôi hoặc nước dừa ấm khi châm thêm vào nồi kho đang nóng để thịt cá không bị sượng cứng trở lại.'),
(233,7,'Thu sánh nước sốt óng ả & trình bày thưởng thức nóng','Khi nước kho rút còn khoảng 1/3 sánh kẹo óng ánh áo đều quanh nguyên liệu và xiên đũa thấy mềm mọng vừa ý, rắc 35g hành lá lên mặt rồi tắt bếp. Múc món Mực ống tươi hấp gừng sả Cửa Lò ra đĩa sâu lòng hoặc niêu đất giữ nhiệt, dọn ăn nóng cùng cơm trắng dẻo thơm cho 4 người.',3,'Giữ lại một lượng nước sốt sánh kẹo vừa đủ dưới đáy nồi để chan cơm hoặc chấm kèm rau luộc sẽ tròn vị đưa cơm gấp bội.'),
(234,1,'Sơ chế tươi sạch & ngâm giòn rau củ thảo mộc','Nhặt rửa kỹ 100g rau sống cùng 25g hành lá qua nước muối loãng rồi tráng nước đun sôi để nguội. Với các loại củ quả bào sợi hoặc thái lát mỏng, ngâm vào âu nước đá lạnh pha chút chanh đường trong 10 phút rồi vắt ráo để giữ độ trắng giòn sần sật.',6,'Rau củ làm gỏi và món cuốn phải quay rổ hoặc thấm thật ráo nước để khi trộn nước mắm không bị loãng nhạt.'),
(234,2,'Làm chín tới phần nhân đạm giữ trọn độ ngọt mọng','Xử lý phần nguyên liệu chính (500g bánh ướt và 250g chả lụa): luộc hấp cùng lát gừng sả đập dập hoặc xào lửa lớn vừa chín tới, sau đó làm nguội nhanh rồi thái lát mỏng / xé sợi đều đặn. Nếu món có pha bột bánh gạo/bột năng, khuấy tan bột với nước đúng tỷ lệ và để bột nghỉ 15 phút cho nở mịn.',8,'Ngâm tôm hoặc thịt luộc qua bát nước sôi để nguội có vài viên đá giúp màu sắc tươi hồng và thớ thịt giòn ngọt không bị khô.'),
(234,3,'Rang vàng đậu phộng mè thơm & phi hành tỏi giòn','Bắc chảo nhỏ lên lửa nhỏ, rang chín vàng thơm đậu phộng/mè hoặc làm mỡ hành xanh mướt và phi vàng giòn 35g hành tăm. Vớt hành tỏi phi ra đĩa riêng để nguội giòn tan, giữ lại phần dầu thơm óng ánh để phết bánh hoặc rưới bóng mặt món ăn.',4,'Tắt bếp ngay khi hành phi chuyển vàng sáng vì nhiệt dư trong dầu nóng sẽ tiếp tục làm hành sẫm màu thêm một nấc hoàn hảo.'),
(234,4,'Pha nước mắm chấm / sốt trộn tỷ lệ vàng chua ngọt','Hòa tan hoàn toàn đường cùng 35ml nước mắm và 15ml chanh và nước ấm trong chén sâu lòng, khuấy đến khi hơi sánh nhẹ mới cho tỏi ớt băm nhuyễn và nước cốt chanh/tắc vào sau cùng. Công thức pha này giúp tỏi ớt nổi đều đẹp mắt trên bề mặt bát nước chấm chuẩn vị Bánh mướt Nghệ An cuốn chả lụa hành phi.',4,'Băm tỏi ớt thật ráo trên thớt khô và cho vào sau khi đường mắm đã nguội thì tỏi ớt sẽ nổi bồng bềnh 100% không bị chìm đáy.'),
(234,5,'Phối trộn thấm vị / tráng hấp & cuốn đều tay','Tiến hành tráng hấp bánh mỏng mượt hoặc trải bánh cuốn gọn gàng 500g bánh ướt và 250g chả lụa cùng 100g rau sống; nếu là món gỏi trộn thì rưới từ từ 2/3 lượng sốt chua ngọt vào bóp nhẹ tay cho thấm đều trong 3 phút. Giữ lực tay nhẹ nhàng để rau củ không bị dập nát mà vẫn ngấm trọn vị mặn chua ngọt hài hòa.',5,'Chia nước sốt gỏi làm 2 lần trộn và chắt bỏ phần nước tiết ra ở lần đầu giúp đĩa gỏi khô ráo, đậm đà như ngoài hàng.'),
(234,6,'Bày biện ngũ sắc hài hòa & rắc topping giòn bùi','Xếp món Bánh mướt Nghệ An cuốn chả lụa hành phi ngay ngắn ra đĩa sứ trắng rộng, rải đều phần nhân tôm thịt sắc nét lên trên và rắc phủ 25g hành lá thơm giòn. Dọn kèm chén nước chấm đậm đà cho 4 người thưởng thức ngay khi rau bánh còn tươi giòn mướt mịn.',3,'Chỉ rắc đậu phộng rang và hành phi ngay trước lúc mang ra bàn ăn để giữ nguyên độ giòn tan bùi béo.'),
(235,1,'Sơ chế sạch & cắt thái nguyên liệu đúng kích cỡ','Rửa sạch 800g giò heo cùng 150g măng tươi dưới vòi nước mát rồi để thật ráo trên rổ thưa. Dùng dao sắc cắt thái nguyên liệu thành từng khúc hoặc khối vuông đều đặn khoảng 3.5–4cm để khi kho hầm giữ nguyên hình dáng đẹp mắt mà không bị vụn nát.',11,'Cắt miếng thịt/cá dày dặn đồng đều giúp quá trình kho lâu trên lửa nhỏ thớ thịt mềm rục mà vẫn giữ trọn độ mọng ngọt bên trong.'),
(235,2,'Khử mùi tự nhiên & làm săn sạch bề mặt nguyên liệu','Chà nhẹ phần đạm chính trong 800g giò heo với chút muối hạt, lát gừng đập dập hoặc chần sơ qua nước sôi 90 giây rồi rửa sạch lại bằng nước ấm, để ráo hoàn toàn. Công đoạn này loại bỏ triệt để tạp chất và mùi tanh hôi, giúp nước sốt món Giò heo nấu giả cầy riềng mẻ mắm tôm trong bóng thơm ngon.',8,'Sau khi chần hoặc rửa sạch, để nguyên liệu ráo nước ít nhất 5 phút trước khi ướp để gia vị rút sâu trực tiếp vào từng thớ thịt.'),
(235,3,'Pha hỗn hợp gia vị & ướp thấm chuẩn định lượng','Cho 800g giò heo vào tô lớn, ướp cùng một nửa 120g riềng tươi, 30g nghệ và 40g sả băm nhỏ và định lượng chuẩn 60g mẻ chua và 25g mắm tôm, đảo nhẹ tay cho gia vị phủ kín đều các mặt. Bọc kín tô và để nguyên liệu nghỉ thấm vị tối thiểu 20 phút ở nhiệt độ phòng (hoặc ngăn mát tủ lạnh).',11,'Ướp đủ tối thiểu 20 phút trước khi bắc lên bếp là chìa khóa để tâm miếng thịt/cá đậm đà đồng nhất với lớp sốt bên ngoài.'),
(235,4,'Thắng nước màu cánh gián & phi dậy hương hành tỏi','Đặt nồi đáy dày lên bếp ở lửa vừa nhỏ, thắng nhẹ 15g đường với 15ml dầu ăn đến khi chuyển sắc nâu cánh gián óng ả thì cho ngay phần 120g riềng tươi, 30g nghệ và 40g sả còn lại vào phi thơm lừng. Hương caramel dịu ngọt quyện cùng tinh dầu hành tỏi sả tạo nền màu nâu hổ phách truyền thống đầy cuốn hút.',8,'Canh kỹ khoảnh khắc đường vừa chuyển màu cánh gián là hạ lửa nhỏ nhất ngay để nước màu bóng đẹp mà không bao giờ bị đắng.'),
(235,5,'Đảo săn hai mặt khóa ngọt nguyên liệu chính','Tăng lên lửa vừa lớn, gắp từng miếng trong 800g giò heo vào nồi đảo đều hoặc trở nhẹ hai mặt trong 4–5 phút cho săn chắc và bám đều lớp màu nâu óng. Khi bề mặt nguyên liệu se vàng thơm phức mới trút phần nước ướp còn lại trong tô vào đun sôi nhẹ.',11,'Đối với cá kho, chỉ lật cá một lần lúc cá vừa săn mặt trên lửa vừa để khúc cá nguyên vẹn không bị tróc da hay vỡ nát.'),
(235,6,'Kho/om liu riu lửa nhỏ thấm đẫm cùng nước dừa/nước dùng','Chế lượng nước vừa ngập mặt nguyên liệu xâm xắp mặt nguyên liệu (xếp thêm 150g măng tươi nếu có), đun sôi bùng một dạo hớt sạch bọt rồi hạ ngay về mức lửa nhỏ liu riu nhất. Kho êm đềm không đậy kín nắp để từng thớ nguyên liệu chín mềm thấm đẫm gia vị và nước sốt rút dần sóng sánh.',18,'Luôn dùng nước sôi hoặc nước dừa ấm khi châm thêm vào nồi kho đang nóng để thịt cá không bị sượng cứng trở lại.'),
(235,7,'Thu sánh nước sốt óng ả & trình bày thưởng thức nóng','Khi nước kho rút còn khoảng 1/3 sánh kẹo óng ánh áo đều quanh nguyên liệu và xiên đũa thấy mềm mọng vừa ý, rắc 25g rau răm lên mặt rồi tắt bếp. Múc món Giò heo nấu giả cầy riềng mẻ mắm tôm ra đĩa sâu lòng hoặc niêu đất giữ nhiệt, dọn ăn nóng cùng cơm trắng dẻo thơm cho 4 người.',8,'Giữ lại một lượng nước sốt sánh kẹo vừa đủ dưới đáy nồi để chan cơm hoặc chấm kèm rau luộc sẽ tròn vị đưa cơm gấp bội.'),
(236,1,'Sơ chế sạch & cắt thái nguyên liệu nấu canh','Rửa sạch 500g cá lăng và 250g măng chua, khử mùi tanh bằng chút muối hạt và gừng đập dập rồi rửa lại thật ráo, cắt miếng vừa ăn dày khoảng 2.5–3cm. Đồng thời gọt rửa sạch 120g dứa, cắt khúc hoặc bổ múi cau đồng đều để khi nấu chín đều không bị nát.',8,'Phân loại riêng nhóm củ cứng nấu lâu và nhóm rau lá mềm nhanh chín để cho vào nồi theo đúng thứ tự chuẩn đầu bếp.'),
(236,2,'Ướp thấm gia vị nền cho nguyên liệu đạm','Cho phần đạm chính trong 500g cá lăng và 250g măng chua vào tô, ướp nhẹ với một nửa lượng 20g hành tím và 25ml nước mắm trong khoảng 10 phút. Đảo nhẹ tay cho gia vị áo đều bề mặt giúp miếng thịt, cá săn chắc và đậm đà từ bên trong khi thả vào nước canh.',7,'Không ướp quá mặn ở bước này để giữ vị thanh mát tự nhiên của nước canh sau khi hoàn tất.'),
(236,3,'Phi thơm hành tỏi & xào săn khóa ngọt nguyên liệu','Đặt nồi canh lên bếp ở lửa vừa, làm nóng 15ml dầu ăn rồi phi thơm phần 20g hành tím còn lại đến khi dậy mùi vàng óng. Trút nguyên liệu chính đã ướp vào đảo săn 2–3 phút cho bề mặt se lại, khóa trọn nước ngọt tự nhiên bên trong thớ thịt.',6,'Xào săn nguyên liệu đạm với hành tỏi phi trước khi đổ nước sôi giúp nước canh thơm ngọt đậm đà mà không hề tanh.'),
(236,4,'Đun sôi nước canh & hớt bọt giữ độ trong veo','Chế khoảng 1.1–1.3 lít nước (kết hợp lượng nước vừa ngập mặt nguyên liệu) vào nồi, bật lửa lớn đun đến khi sôi bùng rồi hạ ngay về lửa vừa. Dùng muôi hớt sạch lớp bọt đầu nổi lên trên mặt nước để nồi canh Canh cá lăng nấu măng chua lá lốt đạt độ trong thanh đẹp mắt.',11,'Sử dụng nước ấm hoặc nước sôi khi chế vào cá tươi sẽ giúp cá không bao giờ bị tanh nồng dù để nguội.'),
(236,5,'Thả rau củ theo độ chín & cân chỉnh định lượng vị','Lần lượt cho 120g dứa vào nồi canh đang sôi vừa (nhóm củ quả lâu chín cho trước 5–7 phút, nhóm rau mềm cho sau 1–2 phút). Nêm phần 25ml nước mắm còn lại, khuấy nhẹ và nếm thử thấy vị chua thanh hoặc ngọt dịu cân bằng đúng khẩu phần 4 người.',9,'Không đậy kín nắp vung sau khi đã thả các loại rau xanh vào nồi để giữ màu xanh ngọc tươi tắn hấp dẫn.'),
(236,6,'Điểm hương rau thơm & múc canh dọn nóng','Khi toàn bộ nguyên liệu vừa chín tới mềm ngọt, rắc ngay 25g lá lốt và 20g thì là vào nồi rồi tắt bếp liền tay để giữ trọn tinh dầu thơm mát. Múc canh nóng hổi ra tô lớn, rắc thêm chút tiêu xay hoặc tỏi phi vàng và dùng ngay với cơm nóng.',4,'Các loại rau thơm như thì là, ngò gai, rau om hay lá lốt chỉ nên thả ngay khoảnh khắc tắt bếp để hương thơm bùng nổ nhất.'),
(237,1,'Tuyển chọn, ngâm nở & sơ chế sạch nguyên liệu chè bánh','Đãi rửa sạch nhóm hạt, củ hoặc bột (300g bột nếp và 100g đậu xanh cà vỏ), ngâm nước ấm theo đúng đặc tính từng loại để hạt nở mềm đồng đều và loại bỏ nhựa chát. Rửa sạch nhóm tạo hương tự nhiên gồm 50g gừng để ráo nước.',8,'Thêm một nhúm muối nhỏ vào nước ngâm khoai và đậu giúp nguyên liệu giữ màu tươi sáng và khi nấu chín bùi hơn.'),
(237,2,'Ninh mềm bùi nguyên liệu chính giữ nguyên hạt/khối','Cho phần nguyên liệu nền trong 300g bột nếp và 100g đậu xanh cà vỏ vào nồi đáy dày cùng lượng nước vừa đủ, đun sôi rồi hạ lửa nhỏ ninh êm đến khi chín mềm bùi nhưng không bị vỡ nát đục nước. Nếu có trân châu, bột lọc hoặc hạt lựu, luộc riêng trong nồi nước sôi đến khi nổi trong veo rồi vớt ngâm ngay vào bát nước mát.',11,'Tuyệt đối không cho đường ngay từ đầu khi đậu và khoai chưa chín mềm vì đường sẽ làm săn vỏ hạt khiến nấu mãi vẫn sượng.'),
(237,3,'Nấu nước đường phèn / mật mía thanh trong dậy hương','Kết hợp chính xác định lượng 220ml mật mía vào nồi cùng bó lá dứa hoặc gừng thái chỉ, khuấy nhẹ trên lửa nhỏ cho tan trong vắt. Đun liu riu thêm 5–7 phút để vị ngọt thấm sâu vào từng viên nguyên liệu và tỏa hương thơm dịu tao nhã.',7,'Dùng đường phèn hoặc mật mía đun lửa nhỏ hớt bọt kỹ giúp hậu vị chè ngọt thanh mát họng, không bị khé cổ.'),
(237,4,'Thắng nước cốt dừa béo mịn / chuẩn bị lớp kem phủ','Cho nước cốt dừa vào nồi nhỏ cùng 2g muối tinh và 5g bột năng/bột bắp hòa loãng, khuấy đều tay trên lửa nhỏ nhất đến khi vừa chớm sôi lăn tăn sánh mượt. Tắt bếp ngay để nước cốt dừa giữ màu trắng ngần béo ngậy mà không bị tách lớp dầu.',6,'Một chút xíu muối tinh trong nồi nước cốt dừa sẽ làm bật hẳn độ béo thơm tự nhiên và cân bằng vị ngọt của món tráng miệng.');
INSERT INTO `recipe_steps` (`recipe_id`,`step_order`,`title`,`instruction`,`duration_mins`,`tip_note`) VALUES
(237,5,'Phối hợp độ sánh mượt & cân bằng hương vị tổng thể','Hợp nhất các thành phần của món Bánh ngào mật mía gừng ấm Hà Tĩnh, từ từ rưới nước bột năng hòa loãng (nếu là chè sánh) đồng thời khuấy nhẹ một chiều trên lửa nhỏ cho hỗn hợp bóng mượt như nhung. Kiểm tra độ mềm dẻo hài hòa và tắt bếp để ủ hương thảo mộc lan tỏa đều.',5,'Rót nước bột tạo sánh thành dòng mảnh vừa rót vừa khuấy đều tay giúp chè trong mượt, hoàn toàn không bị ốc trâu vón cục.'),
(237,6,'Múc ra chén sứ, điểm topping & thưởng thức ấm/lạnh','Múc chè hoặc bày bánh ra 4 chén nhỏ xinh, chan lớp nước cốt dừa trắng mịn lên mặt và rắc nhẹ 50g đậu phộng và 15g mè trắng. Thưởng thức ấm nóng dịu dàng hoặc thêm đá bào mát lạnh tùy sở thích đều trọn vị ngon truyền thống.',3,'Để chè nguội bớt về khoảng 45°C hoặc ướp mát 30 phút trong ngăn mát tủ lạnh giúp các tầng hương vị kết tinh đậm đà hơn.'),
(238,1,'Tuyển chọn & sơ chế tươi sạch nguyên liệu pha chế','Rửa sạch kỹ các nguyên liệu tươi gồm 120g lá chè xanh và 25g gừng, để ráo nước hoàn toàn trên khay sạch. Cắt lát, đập dập hoặc đong chuẩn xác từng gam/ml nguyên liệu cho khẩu phần 4 ly để hương vị đồng nhất tuyệt đối.',4,'Loại bỏ kỹ hạt chanh, tắc trước khi vắt hoặc nấu giúp thức uống giữ hậu vị thanh ngọt mà không hề bị đắng vỏ.'),
(238,2,'Ủ chiết xuất nền trà, cà phê hoặc nấu cốt thảo mộc','Đun nước đạt nhiệt độ chuẩn 90–95°C (không dùng nước sôi sùng sục làm cháy hương), tiến hành ủ chiết xuất hoặc nấu nhỏ lửa 120g lá chè xanh trong thời gian quy định. Lọc qua rây mịn hoặc túi vải sạch để thu được phần nước cốt trong trẻo, đậm hương tự nhiên không gợn cặn.',7,'Ủ trà/cà phê đúng nhiệt độ 92°C và đậy nắp kín giúp thu trọn tinh dầu thơm quyến rũ mà không chiết xuất vị chát gắt.'),
(238,3,'Xử lý lớp kem bông mịn / hỗn hợp sữa & trái cây','Đánh bông mượt hoặc khuấy hòa quyện phần nguyên liệu bổ trợ (900ml nước lọc) cùng 35g mật ong, 10ml chanh và 15g đường phèn đến khi sánh mịn đồng nhất. Kiểm soát tốc độ khuấy/đánh đều tay để tạo kết cấu bồng bềnh mượt mà hoặc hòa tan hoàn toàn đường phèn mật ong.',4,'Nếu đánh kem trứng, nghiêng nhẹ âu 45 độ và đánh một chiều tốc độ cao cho tới khi nhấc que tạo chóp mềm bóng mượt không tanh.'),
(238,4,'Cân chỉnh định lượng độ ngọt & tầng hương tươi mát','Phối trộn phần nước cốt nền cùng hỗn hợp tạo vị theo đúng tỷ lệ vàng của món Nước chè xanh gừng tươi mật ong xứ Nghệ, khuấy nhẹ để các tầng hương hòa quyện. Nếu có nước cốt chanh hoặc mật ong rừng, cho vào khi nền nước đã hạ xuống dưới 55°C để bảo toàn trọn vẹn vitamin và hương thơm.',3,'Nếm thử trước khi thêm đá viên sao cho vị đậm hơn khoảng 15% để khi đá tan nhẹ là vừa vặn hoàn hảo.'),
(238,5,'Phối tầng thẩm mỹ ra ly thủy tinh nóng hoặc đá mát','Tráng ấm ly gốm (nếu dùng nóng) hoặc cho lượng đá viên tinh khiết vừa đủ vào ly thủy tinh cao, rót từ từ cốt thức uống vào 2/3 ly. Nhẹ nhàng rót lớp kem/sữa hoặc xếp lát trái cây tươi áp sát thành ly tạo hiệu ứng phân tầng đẹp mắt như quán chuyên nghiệp.',2,'Rót lớp kem hoặc sữa nhẹ nhàng qua lưng muỗng inox giúp hai tầng màu tách bạch sắc nét cực kỳ cuốn hút.'),
(238,6,'Điểm xuyết lá thơm trang trí & thưởng thức ngay','Trang trí trên mặt ly bằng lát nguyên liệu tươi, nhánh bạc hà/lá dứa hoặc rắc nhẹ bột cacao/hạt chia cho món Nước chè xanh gừng tươi mật ong xứ Nghệ thêm phần sinh động. Phục vụ ngay khi vừa pha chế xong cho 4 người để tận hưởng trọn vẹn hương thơm tươi mới sảng khoái nhất.',2,'Vỗ nhẹ lá bạc hà trong lòng bàn tay trước khi đặt lên miệng ly sẽ đánh thức tinh dầu the mát lan tỏa ngay khi nâng ly.'),
(239,1,'Vo đãi & ngâm nở hạt gạo/nếp đúng thời gian chuẩn','Đong chuẩn lượng gạo/nếp trong 300g hến tươi và 500g cơm nguội, vo nhẹ tay 2–3 nước cho sạch bụi cám mà không làm mất lớp dưỡng chất ngoài vỏ hạt, để ráo trên rổ. Nếu là nếp đồ xôi, ngâm trước trong nước ấm hoặc nước màu thảo mộc tự nhiên cùng 3g muối để hạt nếp ngậm đủ nước căng tròn.',8,'Xóc nhẹ một nhúm muối tinh vào gạo nếp sau khi để ráo giúp hạt xôi cơm khi chín có vị đậm dịu và bóng dẻo tự nhiên.'),
(239,2,'Sơ chế & tẩm ướp phần nhân thịt, đậu ăn kèm','Làm sạch và chuẩn bị phần nguyên liệu ăn kèm gồm 150g dọc mùng cùng 80g xoài xanh và 150g rau sống, cắt thái gọn gàng đúng quy cách món Cơm hến Cồn Hến xứ Huế cay thơm mắm ruốc. Ướp thấm nhân với 25g mắm ruốc huế và 18g sa tế trong 15 phút để khi chế biến tạo điểm nhấn đậm đà quyện cùng hạt cơm xôi dẻo thơm.',7,'Chuẩn bị song song phần nhân topping trong lúc chờ nấu cơm/đồ xôi giúp tiết kiệm thời gian và mọi thành phần cùng nóng hổi.'),
(239,3,'Nấu cơm / đồ xôi canh chuẩn nhiệt & độ ẩm hạt','Cho gạo vào nấu với lượng nước luộc gà/nước dùng vừa khéo hoặc dàn đều nếp vào xửng hấp đã sôi sùng sục, chọc vài lỗ thoáng hơi trên bề mặt nếp. Duy trì lửa vừa ổn định để hơi nóng xuyên đều giúp hạt chín dẻo từ lõi mà bên ngoài vẫn ráo tơi óng ả.',13,'Lau khô nước đọng dưới nắp vung mỗi 10 phút khi đồ xôi giúp mặt xôi không bao giờ bị nhão ướt ở rìa xửng.'),
(239,4,'Chế biến chín vàng thơm phần nhân & mỡ hành phi','Bắc chảo lên lửa vừa, phi vàng giòn hành tím và tỏi băm nhỏ lấy dầu thơm rồi chế biến chín tới phần nhân 150g dọc mùng cho lên màu bóng đẹp và dậy mùi đặc trưng. Trường hợp có đậu xanh hoặc trứng chả kèm theo, chế biến riêng từng phần để giữ trọn sắc màu và hương vị tinh tế.',8,'Rưới một thìa mỡ gà hoặc dầu hành phi vào xới nhẹ lúc cơm/xôi vừa chín tới giúp từng hạt căng bóng mượt mà lâu khô.'),
(239,5,'Pha nước mắm sốt rưới / đồ chua cân bằng vị béo','Pha chén nước sốt chan từ 25g mắm ruốc huế và 18g sa tế khuấy tan sánh nhẹ hoặc trộn nhanh phần hành tím/dưa góp chua ngọt giòn mát đi kèm. Cân chỉnh hài hòa vị mặn ngọt chua thanh để tôn lên độ bùi dẻo của hạt gạo nếp Việt Nam.',5,'Nước mắm ăn kèm các món cơm gà, cơm tấm hay cơm trộn nên nấu sôi nhẹ với đường cho hơi sánh kẹo sẽ bám hạt cơm ngon hơn hẳn.'),
(239,6,'Đơm khuôn đầy đặn, xếp nhân & thưởng thức nóng','Đơm cơm hoặc xôi nóng vào chén ép nhẹ rồi úp tròn ra 4 đĩa, xếp đều các lớp nhân, đồ chua và rắc 60g đậu phộng lên trên cùng. Rưới nhẹ mỡ hành/nước sốt bóng bẩy và thưởng thức ngay khi hạt cơm xôi còn nóng dẻo thơm lừng.',4,'Tráng mỏng một lớp nước lọc hoặc dầu ăn vào lòng chén trước khi đơm cơm giúp úp ra đĩa tròn trịa sắc nét không dính hạt.'),
(240,1,'Sơ chế tươi sạch & ngâm giòn rau củ thảo mộc','Nhặt rửa kỹ rau củ ăn kèm cùng 40g hành lá qua nước muối loãng rồi tráng nước đun sôi để nguội. Với các loại củ quả bào sợi hoặc thái lát mỏng, ngâm vào âu nước đá lạnh pha chút chanh đường trong 10 phút rồi vắt ráo để giữ độ trắng giòn sần sật.',9,'Rau củ làm gỏi và món cuốn phải quay rổ hoặc thấm thật ráo nước để khi trộn nước mắm không bị loãng nhạt.'),
(240,2,'Làm chín tới phần nhân đạm giữ trọn độ ngọt mọng','Xử lý phần nguyên liệu chính (220g bột gạo và 25g bột năng): luộc hấp cùng lát gừng sả đập dập hoặc xào lửa lớn vừa chín tới, sau đó làm nguội nhanh rồi thái lát mỏng / xé sợi đều đặn. Nếu món có pha bột bánh gạo/bột năng, khuấy tan bột với nước đúng tỷ lệ và để bột nghỉ 15 phút cho nở mịn.',12,'Ngâm tôm hoặc thịt luộc qua bát nước sôi để nguội có vài viên đá giúp màu sắc tươi hồng và thớ thịt giòn ngọt không bị khô.'),
(240,3,'Rang vàng đậu phộng mè thơm & phi hành tỏi giòn','Bắc chảo nhỏ lên lửa nhỏ, rang chín vàng thơm đậu phộng/mè hoặc làm mỡ hành xanh mướt và phi vàng giòn hành tím và tỏi băm nhỏ. Vớt hành tỏi phi ra đĩa riêng để nguội giòn tan, giữ lại phần dầu thơm óng ánh để phết bánh hoặc rưới bóng mặt món ăn.',6,'Tắt bếp ngay khi hành phi chuyển vàng sáng vì nhiệt dư trong dầu nóng sẽ tiếp tục làm hành sẫm màu thêm một nấc hoàn hảo.'),
(240,4,'Pha nước mắm chấm / sốt trộn tỷ lệ vàng chua ngọt','Hòa tan hoàn toàn đường cùng 35ml nước mắm, 25g đường và 10g ớt và nước ấm trong chén sâu lòng, khuấy đến khi hơi sánh nhẹ mới cho tỏi ớt băm nhuyễn và nước cốt chanh/tắc vào sau cùng. Công thức pha này giúp tỏi ớt nổi đều đẹp mắt trên bề mặt bát nước chấm chuẩn vị Bánh bèo chén tôm cháy mỡ hành Huế.',6,'Băm tỏi ớt thật ráo trên thớt khô và cho vào sau khi đường mắm đã nguội thì tỏi ớt sẽ nổi bồng bềnh 100% không bị chìm đáy.'),
(240,5,'Phối trộn thấm vị / tráng hấp & cuốn đều tay','Tiến hành tráng hấp bánh mỏng mượt hoặc trải bánh cuốn gọn gàng 220g bột gạo và 25g bột năng cùng rau củ ăn kèm; nếu là món gỏi trộn thì rưới từ từ 2/3 lượng sốt chua ngọt vào bóp nhẹ tay cho thấm đều trong 3 phút. Giữ lực tay nhẹ nhàng để rau củ không bị dập nát mà vẫn ngấm trọn vị mặn chua ngọt hài hòa.',8,'Chia nước sốt gỏi làm 2 lần trộn và chắt bỏ phần nước tiết ra ở lần đầu giúp đĩa gỏi khô ráo, đậm đà như ngoài hàng.'),
(240,6,'Bày biện ngũ sắc hài hòa & rắc topping giòn bùi','Xếp món Bánh bèo chén tôm cháy mỡ hành Huế ngay ngắn ra đĩa sứ trắng rộng, rải đều phần nhân tôm thịt sắc nét lên trên và rắc phủ 40g hành lá thơm giòn. Dọn kèm chén nước chấm đậm đà cho 4 người thưởng thức ngay khi rau bánh còn tươi giòn mướt mịn.',4,'Chỉ rắc đậu phộng rang và hành phi ngay trước lúc mang ra bàn ăn để giữ nguyên độ giòn tan bùi béo.'),
(241,1,'Sơ chế tươi sạch & ngâm giòn rau củ thảo mộc','Nhặt rửa kỹ rau củ ăn kèm cùng 30g hành lá qua nước muối loãng rồi tráng nước đun sôi để nguội. Với các loại củ quả bào sợi hoặc thái lát mỏng, ngâm vào âu nước đá lạnh pha chút chanh đường trong 10 phút rồi vắt ráo để giữ độ trắng giòn sần sật.',11,'Rau củ làm gỏi và món cuốn phải quay rổ hoặc thấm thật ráo nước để khi trộn nước mắm không bị loãng nhạt.'),
(241,2,'Làm chín tới phần nhân đạm giữ trọn độ ngọt mọng','Xử lý phần nguyên liệu chính (240g bột gạo và 30g bột năng): luộc hấp cùng lát gừng sả đập dập hoặc xào lửa lớn vừa chín tới, sau đó làm nguội nhanh rồi thái lát mỏng / xé sợi đều đặn. Nếu món có pha bột bánh gạo/bột năng, khuấy tan bột với nước đúng tỷ lệ và để bột nghỉ 15 phút cho nở mịn.',12,'Ngâm tôm hoặc thịt luộc qua bát nước sôi để nguội có vài viên đá giúp màu sắc tươi hồng và thớ thịt giòn ngọt không bị khô.'),
(241,3,'Rang vàng đậu phộng mè thơm & phi hành tỏi giòn','Bắc chảo nhỏ lên lửa nhỏ, rang chín vàng thơm đậu phộng/mè hoặc làm mỡ hành xanh mướt và phi vàng giòn hành tím và tỏi băm nhỏ. Vớt hành tỏi phi ra đĩa riêng để nguội giòn tan, giữ lại phần dầu thơm óng ánh để phết bánh hoặc rưới bóng mặt món ăn.',8,'Tắt bếp ngay khi hành phi chuyển vàng sáng vì nhiệt dư trong dầu nóng sẽ tiếp tục làm hành sẫm màu thêm một nấc hoàn hảo.'),
(241,4,'Pha nước mắm chấm / sốt trộn tỷ lệ vàng chua ngọt','Hòa tan hoàn toàn đường cùng 35ml nước mắm và 20g đường và nước ấm trong chén sâu lòng, khuấy đến khi hơi sánh nhẹ mới cho tỏi ớt băm nhuyễn và nước cốt chanh/tắc vào sau cùng. Công thức pha này giúp tỏi ớt nổi đều đẹp mắt trên bề mặt bát nước chấm chuẩn vị Bánh nậm Huế gói lá nhân tôm thịt mềm mịn.',8,'Băm tỏi ớt thật ráo trên thớt khô và cho vào sau khi đường mắm đã nguội thì tỏi ớt sẽ nổi bồng bềnh 100% không bị chìm đáy.'),
(241,5,'Phối trộn thấm vị / tráng hấp & cuốn đều tay','Tiến hành tráng hấp bánh mỏng mượt hoặc trải bánh cuốn gọn gàng 240g bột gạo và 30g bột năng cùng rau củ ăn kèm; nếu là món gỏi trộn thì rưới từ từ 2/3 lượng sốt chua ngọt vào bóp nhẹ tay cho thấm đều trong 3 phút. Giữ lực tay nhẹ nhàng để rau củ không bị dập nát mà vẫn ngấm trọn vị mặn chua ngọt hài hòa.',10,'Chia nước sốt gỏi làm 2 lần trộn và chắt bỏ phần nước tiết ra ở lần đầu giúp đĩa gỏi khô ráo, đậm đà như ngoài hàng.');
INSERT INTO `recipe_steps` (`recipe_id`,`step_order`,`title`,`instruction`,`duration_mins`,`tip_note`) VALUES
(241,6,'Bày biện ngũ sắc hài hòa & rắc topping giòn bùi','Xếp món Bánh nậm Huế gói lá nhân tôm thịt mềm mịn ngay ngắn ra đĩa sứ trắng rộng, rải đều phần nhân tôm thịt sắc nét lên trên và rắc phủ 30g hành lá thơm giòn. Dọn kèm chén nước chấm đậm đà cho 4 người thưởng thức ngay khi rau bánh còn tươi giòn mướt mịn.',6,'Chỉ rắc đậu phộng rang và hành phi ngay trước lúc mang ra bàn ăn để giữ nguyên độ giòn tan bùi béo.'),
(242,1,'Sơ chế sạch & thấm thật khô bề mặt nguyên liệu','Rửa sạch 220g bột gạo và 250g tôm đất cùng chút muối loãng để khử mùi tự nhiên, sau đó dùng khăn giấy bếp thấm thật khô ráo hoàn toàn bề mặt. Khứa nhẹ các đường chéo hoặc cắt miếng vừa ăn dày 2–3cm để nhiệt và gia vị thấm sâu đều khắp bên trong.',8,'Bề mặt nguyên liệu càng khô ráo thì khi chiên không bị văng dầu và khi nướng sẽ lên màu vàng ruộm giòn rụm cực đẹp.'),
(242,2,'Chuẩn bị hỗn hợp sốt ướp / bột áo chuẩn tỷ lệ','Phối trộn hành tím và tỏi băm nhỏ băm thật nhuyễn (hoặc vắt lấy nước cốt thơm) cùng gia vị chuẩn định lượng trong tô lớn cho quyện sánh đồng nhất. Nếu món có lớp vỏ bột hoặc bánh cuốn từ 220g bột gạo và 250g tôm đất, trộn đều hỗn hợp theo đúng định lượng để đạt độ giòn xốp mỏng nhẹ chuẩn vị.',7,'Vắt lấy nước cốt hành tỏi sả khi ướp đồ nướng giúp hương thơm thấm sâu mà không bị cháy đen phần xác băm trên lửa cao.'),
(242,3,'Ướp thấm thớ thịt / tạo hình cuốn khéo léo','Áo đều hỗn hợp gia vị hoặc lớp bột/vỏ cuốn quanh 220g bột gạo và 250g tôm đất, massage nhẹ nhàng rồi để nghỉ 15–20 phút cho gia vị thẩm thấu trọn vẹn. Trường hợp cuốn chả/nem hoặc đổ khuôn bánh, thao tác đều tay vừa chặt để nhân kết dính nhưng không bị bục rách khi gặp nhiệt.',9,'Để nguyên liệu nghỉ đủ thời gian trước khi chiên nướng giúp lớp áo bột bám chắc và phần nhân bên trong mọng ngọt.'),
(242,4,'Pha nước chấm cân vị & sơ chế rau đồ chua ăn kèm','Nhặt rửa sạch 150g giá đỗ và 100g quả vả ngâm nước mát cho giòn tươi, bào sợi hoặc thái lát gọn gàng bày sẵn bên cạnh. Pha chén nước chấm chua ngọt hoặc muối ớt chanh sả sánh thơm theo khẩu vị vùng miền của món Bánh khoái Huế giòn rụm chấm nước lèo đậu phộng để cân bằng độ béo giòn.',6,'Luôn chuẩn bị xong rau sống và bát nước chấm trước khi chiên/nướng mẻ cuối để món ăn vừa ra lò là thưởng thức nóng giòn ngay.'),
(242,5,'Làm nóng dầu / lò nướng chuẩn nhiệt & làm chín đều lần 1','Làm nóng chảo dầu hoặc vỉ nướng/nồi chiên ở mức nhiệt vừa khoảng 165–175°C, xếp 220g bột gạo và 250g tôm đất vào với khoảng cách thoáng đều nhau. Chiên hoặc nướng trở mặt nhịp nhàng trên lửa vừa để nhiệt dẫn sâu làm chín mềm ngọt hoàn toàn phần nhân bên trong.',10,'Kiểm tra nhiệt dầu bằng đầu đũa tre thấy sủi tăm nhỏ đều là đạt chuẩn 170°C, giúp vỏ không cháy sớm khi bên trong còn sống.'),
(242,6,'Tăng nhiệt khóa giòn rụm vàng ươm bề mặt lần 2','Ở 2–3 phút cuối, tăng lên lửa vừa lớn (khoảng 190°C) hoặc phết thêm lớp dầu điều/mật ong mỏng để vỏ ngoài của Bánh khoái Huế giòn rụm chấm nước lèo đậu phộng chuyển sắc vàng óng ánh và nổ giòn rụm. Lắng nghe tiếng xèo giòn rộn rã và hương thơm phức lan tỏa khắp bếp thì gắp ra vỉ thưa cho ráo dầu thừa.',6,'Đặt đồ chiên nướng lên giá inox thoáng khí thay vì giấy thấm dầu chồng khít để hơi nước thoát hết, giữ độ giòn lâu gấp 3 lần.'),
(242,7,'Trình bày bắt mắt kèm rau thơm & thưởng thức nóng','Xếp thành phẩm vàng giòn ra đĩa lớn có bày sẵn 150g giá đỗ và 100g quả vả và điểm xuyết 70g đậu phộng tươi xanh hài hòa màu sắc. Dọn kèm chén nước chấm sánh đậm ngay chính giữa mâm ăn cho 4 người thưởng thức khi vỏ ngoài còn nóng giòn rụm.',4,'Cắt miếng hoặc dọn ăn ngay trong vòng 10 phút sau khi rời bếp để cảm nhận trọn vẹn sự đối lập giòn ngoài - mềm ngọt bên trong.'),
(243,1,'Sơ chế & chần sạch nguyên liệu xương thịt, hải sản','Rửa sạch 650g cá lóc và 500g sợi bánh canh với muối hạt rồi chần nhanh trong nồi nước sôi có đập dập 1 nhánh gừng trong 2–3 phút trên lửa lớn để loại bỏ hoàn toàn bọt bẩn. Rửa lại dưới làn nước sạch cho thật trắng trẻo, đồng thời nhặt rửa sạch 40g hành lá để ráo nước.',8,'Bước chần sơ và rửa lại bằng nước ấm là bí quyết vàng giúp nồi nước dùng trong vắt, thơm thanh và không bao giờ bị đục hay hôi.'),
(243,2,'Nướng thơm thảo mộc & ninh nền nước dùng ngọt thanh','Cho phần nguyên liệu tạo ngọt từ 650g cá lóc và 500g sợi bánh canh cùng 45g hành tăm và 20g nghệ đã nướng xém thơm vào nồi sâu lòng với khoảng 1.5–1.8 lít nước lọc. Đun sôi bùng trên lửa lớn rồi hạ ngay về lửa nhỏ liu riu, mở hé vung và hớt kỹ bọt nổi trên mặt để chiết xuất vị ngọt tự nhiên.',16,'Luôn duy trì mặt nước lăn tăn nhẹ thay vì đun sôi sùng sục lửa to để protein không bị nhũ hóa gây đục nước lèo.'),
(243,3,'Xào tạo màu & dậy hương đặc trưng vùng miền','Bắc chảo nhỏ lên bếp với 15ml dầu ăn trên lửa vừa, phi thơm phần hành tỏi sả băm còn lại rồi xào săn các nguyên liệu phối kèm cùng 15g ớt và 25ml nước mắm trong 3–4 phút. Khi hỗn hợp dậy mùi thơm nồng nàn và lên sắc màu óng ả đặc trưng của món Bánh canh cá lóc Quảng Trị cay nồng hành tăm thì tắt bếp.',7,'Xào riêng phần nguyên liệu tạo màu và gia vị thơm trước khi trút vào nồi nước dùng giúp tầng hương dậy lên rõ nét gấp đôi.'),
(243,4,'Sơ chế & cắt thái phần nhân topping xếp tô','Vớt phần thịt hoặc hải sản chín tới từ 650g cá lóc và 500g sợi bánh canh ra ngâm ngay vào âu nước đun sôi để nguội giúp bề mặt săn giòn mọng nước, không bị thâm khô. Thái lát mỏng đều tay dày khoảng 3mm ngang thớ hoặc gỡ miếng vừa ăn, sắp riêng từng phần gọn gàng trên đĩa.',7,'Thái thịt ngang thớ với lưỡi dao thật sắc giúp lát thịt mềm mướt, khi chan nước dùng sôi lên sẽ phẳng đẹp không bị quăn cứng.'),
(243,5,'Hợp nhất nồi nước lèo & nêm chuẩn định lượng','Trút phần sốt màu thơm vào nồi nước dùng đang sôi lăn tăn, nêm chính xác lượng 15g ớt và 25ml nước mắm còn lại cho vừa miệng 4 người ăn. Đun nhẹ thêm 5 phút ở lửa vừa để các tầng vị mặn dịu, ngọt hậu từ xương thịt và thảo mộc hòa quyện tròn trịa.',7,'Nên nêm nước mắm ngon ở giai đoạn cuối trên lửa nhỏ để giữ trọn hậu vị ngọt đạm và hương thơm mà không làm nước dùng bị chua.'),
(243,6,'Chần nóng sợi bánh/bún & chuẩn bị rau ăn kèm','Đun sôi một nồi nước riêng, cho phần sợi bún/phở/bánh trong 650g cá lóc và 500g sợi bánh canh vào trụng nhanh 15–25 giây cho sợi mềm dẻo nóng hổi rồi vẩy thật ráo nước, chia đều vào 4 tô lớn. Chần sơ thêm rau ăn kèm (giá đỗ, rau xanh) nếu muốn dùng chín giòn.',6,'Trụng bún bánh ở nồi nước sôi riêng biệt giúp nước dùng chính không bị nhiễm tinh bột chua và tô bún luôn ráo sợi, thấm vị.'),
(243,7,'Xếp nhân hài hòa, chan nước dùng sôi & thưởng thức','Xếp đều các phần nhân thịt, hải sản lên mặt tô bún bánh, điểm xuyết 40g hành lá lên trên cùng. Dùng muôi múc nước dùng đang sôi thật già chan ngập xăm xắp mặt nguyên liệu để làm chín thơm hành ngò, dọn nóng ngay kèm chanh ớt tươi.',4,'Tráng nóng tô sứ bằng nước sôi trước khi xếp bún giúp tô món nước giữ nhiệt bốc khói nghi ngút suốt bữa ăn.'),
(244,1,'Sơ chế & chần sạch nguyên liệu xương thịt, hải sản','Rửa sạch 500g sợi bánh canh và 350g cá lóc với muối hạt rồi chần nhanh trong nồi nước sôi có đập dập 1 nhánh gừng trong 2–3 phút trên lửa lớn để loại bỏ hoàn toàn bọt bẩn. Rửa lại dưới làn nước sạch cho thật trắng trẻo, đồng thời nhặt rửa sạch 150g cải xanh để ráo nước.',8,'Bước chần sơ và rửa lại bằng nước ấm là bí quyết vàng giúp nồi nước dùng trong vắt, thơm thanh và không bao giờ bị đục hay hôi.'),
(244,2,'Nướng thơm thảo mộc & ninh nền nước dùng ngọt thanh','Cho phần nguyên liệu tạo ngọt từ 500g sợi bánh canh và 350g cá lóc cùng 25g hành tím đã nướng xém thơm vào nồi sâu lòng với khoảng 1.5–1.8 lít nước lọc. Đun sôi bùng trên lửa lớn rồi hạ ngay về lửa nhỏ liu riu, mở hé vung và hớt kỹ bọt nổi trên mặt để chiết xuất vị ngọt tự nhiên.',16,'Luôn duy trì mặt nước lăn tăn nhẹ thay vì đun sôi sùng sục lửa to để protein không bị nhũ hóa gây đục nước lèo.'),
(244,3,'Xào tạo màu & dậy hương đặc trưng vùng miền','Bắc chảo nhỏ lên bếp với 15ml dầu ăn trên lửa vừa, phi thơm phần hành tỏi sả băm còn lại rồi xào săn 200g tôm sú và 250g sườn non cùng 25ml nước mắm và 4g tiêu trong 3–4 phút. Khi hỗn hợp dậy mùi thơm nồng nàn và lên sắc màu óng ả đặc trưng của món Cháo canh Quảng Bình cá lóc tôm tươi thì tắt bếp.',7,'Xào riêng phần nguyên liệu tạo màu và gia vị thơm trước khi trút vào nồi nước dùng giúp tầng hương dậy lên rõ nét gấp đôi.'),
(244,4,'Sơ chế & cắt thái phần nhân topping xếp tô','Vớt phần thịt hoặc hải sản chín tới từ 500g sợi bánh canh và 350g cá lóc ra ngâm ngay vào âu nước đun sôi để nguội giúp bề mặt săn giòn mọng nước, không bị thâm khô. Thái lát mỏng đều tay dày khoảng 3mm ngang thớ hoặc gỡ miếng vừa ăn, sắp riêng từng phần gọn gàng trên đĩa.',7,'Thái thịt ngang thớ với lưỡi dao thật sắc giúp lát thịt mềm mướt, khi chan nước dùng sôi lên sẽ phẳng đẹp không bị quăn cứng.'),
(244,5,'Hợp nhất nồi nước lèo & nêm chuẩn định lượng','Trút phần sốt màu thơm vào nồi nước dùng đang sôi lăn tăn, nêm chính xác lượng 25ml nước mắm và 4g tiêu còn lại cho vừa miệng 4 người ăn. Đun nhẹ thêm 5 phút ở lửa vừa để các tầng vị mặn dịu, ngọt hậu từ xương thịt và thảo mộc hòa quyện tròn trịa.',7,'Nên nêm nước mắm ngon ở giai đoạn cuối trên lửa nhỏ để giữ trọn hậu vị ngọt đạm và hương thơm mà không làm nước dùng bị chua.'),
(244,6,'Chần nóng sợi bánh/bún & chuẩn bị rau ăn kèm','Đun sôi một nồi nước riêng, cho phần sợi bún/phở/bánh trong 500g sợi bánh canh và 350g cá lóc vào trụng nhanh 15–25 giây cho sợi mềm dẻo nóng hổi rồi vẩy thật ráo nước, chia đều vào 4 tô lớn. Chần sơ thêm rau ăn kèm (150g cải xanh) nếu muốn dùng chín giòn.',6,'Trụng bún bánh ở nồi nước sôi riêng biệt giúp nước dùng chính không bị nhiễm tinh bột chua và tô bún luôn ráo sợi, thấm vị.'),
(244,7,'Xếp nhân hài hòa, chan nước dùng sôi & thưởng thức','Xếp đều các phần nhân thịt, hải sản lên mặt tô bún bánh, điểm xuyết hành ngò và tiêu xay lên trên cùng. Dùng muôi múc nước dùng đang sôi thật già chan ngập xăm xắp mặt nguyên liệu để làm chín thơm hành ngò, dọn nóng ngay kèm chanh ớt tươi.',4,'Tráng nóng tô sứ bằng nước sôi trước khi xếp bún giúp tô món nước giữ nhiệt bốc khói nghi ngút suốt bữa ăn.'),
(245,1,'Sơ chế tươi sạch & ngâm giòn rau củ thảo mộc','Nhặt rửa kỹ 120g quả vả, 120g dưa leo và 150g rau sống cùng hành ngò và tiêu xay qua nước muối loãng rồi tráng nước đun sôi để nguội. Với các loại củ quả bào sợi hoặc thái lát mỏng, ngâm vào âu nước đá lạnh pha chút chanh đường trong 10 phút rồi vắt ráo để giữ độ trắng giòn sần sật.',10,'Rau củ làm gỏi và món cuốn phải quay rổ hoặc thấm thật ráo nước để khi trộn nước mắm không bị loãng nhạt.'),
(245,2,'Làm chín tới phần nhân đạm giữ trọn độ ngọt mọng','Xử lý phần nguyên liệu chính (550g thịt ba chỉ và 400g bánh ướt): luộc hấp cùng lát gừng sả đập dập hoặc xào lửa lớn vừa chín tới, sau đó làm nguội nhanh rồi thái lát mỏng / xé sợi đều đặn. Nếu món có pha bột bánh gạo/bột năng, khuấy tan bột với nước đúng tỷ lệ và để bột nghỉ 15 phút cho nở mịn.',12,'Ngâm tôm hoặc thịt luộc qua bát nước sôi để nguội có vài viên đá giúp màu sắc tươi hồng và thớ thịt giòn ngọt không bị khô.'),
(245,3,'Rang vàng đậu phộng mè thơm & phi hành tỏi giòn','Bắc chảo nhỏ lên lửa nhỏ, rang chín vàng thơm đậu phộng/mè hoặc làm mỡ hành xanh mướt và phi vàng giòn 15g tỏi và 20g gừng. Vớt hành tỏi phi ra đĩa riêng để nguội giòn tan, giữ lại phần dầu thơm óng ánh để phết bánh hoặc rưới bóng mặt món ăn.',7,'Tắt bếp ngay khi hành phi chuyển vàng sáng vì nhiệt dư trong dầu nóng sẽ tiếp tục làm hành sẫm màu thêm một nấc hoàn hảo.');
INSERT INTO `recipe_steps` (`recipe_id`,`step_order`,`title`,`instruction`,`duration_mins`,`tip_note`) VALUES
(245,4,'Pha nước mắm chấm / sốt trộn tỷ lệ vàng chua ngọt','Hòa tan hoàn toàn đường cùng gia vị chuẩn định lượng và nước ấm trong chén sâu lòng, khuấy đến khi hơi sánh nhẹ mới cho tỏi ớt băm nhuyễn và nước cốt chanh/tắc vào sau cùng. Công thức pha này giúp tỏi ớt nổi đều đẹp mắt trên bề mặt bát nước chấm chuẩn vị Thịt heo hai đầu da cuốn bánh ướt tôm chua Huế.',7,'Băm tỏi ớt thật ráo trên thớt khô và cho vào sau khi đường mắm đã nguội thì tỏi ớt sẽ nổi bồng bềnh 100% không bị chìm đáy.'),
(245,5,'Phối trộn thấm vị / tráng hấp & cuốn đều tay','Tiến hành tráng hấp bánh mỏng mượt hoặc trải bánh cuốn gọn gàng 550g thịt ba chỉ và 400g bánh ướt cùng 120g quả vả, 120g dưa leo và 150g rau sống; nếu là món gỏi trộn thì rưới từ từ 2/3 lượng sốt chua ngọt vào bóp nhẹ tay cho thấm đều trong 3 phút. Giữ lực tay nhẹ nhàng để rau củ không bị dập nát mà vẫn ngấm trọn vị mặn chua ngọt hài hòa.',9,'Chia nước sốt gỏi làm 2 lần trộn và chắt bỏ phần nước tiết ra ở lần đầu giúp đĩa gỏi khô ráo, đậm đà như ngoài hàng.'),
(245,6,'Bày biện ngũ sắc hài hòa & rắc topping giòn bùi','Xếp món Thịt heo hai đầu da cuốn bánh ướt tôm chua Huế ngay ngắn ra đĩa sứ trắng rộng, rải đều phần nhân tôm thịt sắc nét lên trên và rắc phủ hành ngò và tiêu xay thơm giòn. Dọn kèm chén nước chấm đậm đà cho 4 người thưởng thức ngay khi rau bánh còn tươi giòn mướt mịn.',5,'Chỉ rắc đậu phộng rang và hành phi ngay trước lúc mang ra bàn ăn để giữ nguyên độ giòn tan bùi béo.'),
(246,1,'Sơ chế tươi sạch & ngâm giòn rau củ thảo mộc','Nhặt rửa kỹ rau củ ăn kèm cùng 30g mè rang, 40g đậu phộng và 25g rau răm qua nước muối loãng rồi tráng nước đun sôi để nguội. Với các loại củ quả bào sợi hoặc thái lát mỏng, ngâm vào âu nước đá lạnh pha chút chanh đường trong 10 phút rồi vắt ráo để giữ độ trắng giòn sần sật.',7,'Rau củ làm gỏi và món cuốn phải quay rổ hoặc thấm thật ráo nước để khi trộn nước mắm không bị loãng nhạt.'),
(246,2,'Làm chín tới phần nhân đạm giữ trọn độ ngọt mọng','Xử lý phần nguyên liệu chính (400g quả vả và 200g tôm sú): luộc hấp cùng lát gừng sả đập dập hoặc xào lửa lớn vừa chín tới, sau đó làm nguội nhanh rồi thái lát mỏng / xé sợi đều đặn. Nếu món có pha bột bánh gạo/bột năng, khuấy tan bột với nước đúng tỷ lệ và để bột nghỉ 15 phút cho nở mịn.',8,'Ngâm tôm hoặc thịt luộc qua bát nước sôi để nguội có vài viên đá giúp màu sắc tươi hồng và thớ thịt giòn ngọt không bị khô.'),
(246,3,'Rang vàng đậu phộng mè thơm & phi hành tỏi giòn','Bắc chảo nhỏ lên lửa nhỏ, rang chín vàng thơm đậu phộng/mè hoặc làm mỡ hành xanh mướt và phi vàng giòn hành tím và tỏi băm nhỏ. Vớt hành tỏi phi ra đĩa riêng để nguội giòn tan, giữ lại phần dầu thơm óng ánh để phết bánh hoặc rưới bóng mặt món ăn.',5,'Tắt bếp ngay khi hành phi chuyển vàng sáng vì nhiệt dư trong dầu nóng sẽ tiếp tục làm hành sẫm màu thêm một nấc hoàn hảo.'),
(246,4,'Pha nước mắm chấm / sốt trộn tỷ lệ vàng chua ngọt','Hòa tan hoàn toàn đường cùng 25ml nước mắm và nước ấm trong chén sâu lòng, khuấy đến khi hơi sánh nhẹ mới cho tỏi ớt băm nhuyễn và nước cốt chanh/tắc vào sau cùng. Công thức pha này giúp tỏi ớt nổi đều đẹp mắt trên bề mặt bát nước chấm chuẩn vị Vả trộn tôm thịt mè rang cố đô Huế.',5,'Băm tỏi ớt thật ráo trên thớt khô và cho vào sau khi đường mắm đã nguội thì tỏi ớt sẽ nổi bồng bềnh 100% không bị chìm đáy.'),
(246,5,'Phối trộn thấm vị / tráng hấp & cuốn đều tay','Tiến hành tráng hấp bánh mỏng mượt hoặc trải bánh cuốn gọn gàng 400g quả vả và 200g tôm sú cùng rau củ ăn kèm; nếu là món gỏi trộn thì rưới từ từ 2/3 lượng sốt chua ngọt vào bóp nhẹ tay cho thấm đều trong 3 phút. Giữ lực tay nhẹ nhàng để rau củ không bị dập nát mà vẫn ngấm trọn vị mặn chua ngọt hài hòa.',6,'Chia nước sốt gỏi làm 2 lần trộn và chắt bỏ phần nước tiết ra ở lần đầu giúp đĩa gỏi khô ráo, đậm đà như ngoài hàng.'),
(246,6,'Bày biện ngũ sắc hài hòa & rắc topping giòn bùi','Xếp món Vả trộn tôm thịt mè rang cố đô Huế ngay ngắn ra đĩa sứ trắng rộng, rải đều phần nhân tôm thịt sắc nét lên trên và rắc phủ 30g mè rang, 40g đậu phộng và 25g rau răm thơm giòn. Dọn kèm chén nước chấm đậm đà cho 4 người thưởng thức ngay khi rau bánh còn tươi giòn mướt mịn.',4,'Chỉ rắc đậu phộng rang và hành phi ngay trước lúc mang ra bàn ăn để giữ nguyên độ giòn tan bùi béo.'),
(247,1,'Vo đãi & ngâm nở hạt gạo/nếp đúng thời gian chuẩn','Đong chuẩn lượng gạo/nếp trong 320g gạo tẻ và 200g thịt ba chỉ, vo nhẹ tay 2–3 nước cho sạch bụi cám mà không làm mất lớp dưỡng chất ngoài vỏ hạt, để ráo trên rổ. Nếu là nếp đồ xôi, ngâm trước trong nước ấm hoặc nước màu thảo mộc tự nhiên cùng 3g muối để hạt nếp ngậm đủ nước căng tròn.',10,'Xóc nhẹ một nhúm muối tinh vào gạo nếp sau khi để ráo giúp hạt xôi cơm khi chín có vị đậm dịu và bóng dẻo tự nhiên.'),
(247,2,'Sơ chế & tẩm ướp phần nhân thịt, đậu ăn kèm','Làm sạch và chuẩn bị phần nguyên liệu ăn kèm gồm 200g tôm sú và 3 quả trứng gà cùng 120g dưa leo, cắt thái gọn gàng đúng quy cách món Cơm âm phủ cung đình Huế bảy sắc hài hòa. Ướp thấm nhân với 35ml nước mắm trong 15 phút để khi chế biến tạo điểm nhấn đậm đà quyện cùng hạt cơm xôi dẻo thơm.',9,'Chuẩn bị song song phần nhân topping trong lúc chờ nấu cơm/đồ xôi giúp tiết kiệm thời gian và mọi thành phần cùng nóng hổi.'),
(247,3,'Nấu cơm / đồ xôi canh chuẩn nhiệt & độ ẩm hạt','Cho gạo vào nấu với lượng nước luộc gà/nước dùng vừa khéo hoặc dàn đều nếp vào xửng hấp đã sôi sùng sục, chọc vài lỗ thoáng hơi trên bề mặt nếp. Duy trì lửa vừa ổn định để hơi nóng xuyên đều giúp hạt chín dẻo từ lõi mà bên ngoài vẫn ráo tơi óng ả.',13,'Lau khô nước đọng dưới nắp vung mỗi 10 phút khi đồ xôi giúp mặt xôi không bao giờ bị nhão ướt ở rìa xửng.'),
(247,4,'Chế biến chín vàng thơm phần nhân & mỡ hành phi','Bắc chảo lên lửa vừa, phi vàng giòn hành tím và tỏi băm nhỏ lấy dầu thơm rồi chế biến chín tới phần nhân 200g tôm sú và 3 quả trứng gà cho lên màu bóng đẹp và dậy mùi đặc trưng. Trường hợp có đậu xanh hoặc trứng chả kèm theo, chế biến riêng từng phần để giữ trọn sắc màu và hương vị tinh tế.',10,'Rưới một thìa mỡ gà hoặc dầu hành phi vào xới nhẹ lúc cơm/xôi vừa chín tới giúp từng hạt căng bóng mượt mà lâu khô.'),
(247,5,'Pha nước mắm sốt rưới / đồ chua cân bằng vị béo','Pha chén nước sốt chan từ 35ml nước mắm khuấy tan sánh nhẹ hoặc trộn nhanh phần hành tím/dưa góp chua ngọt giòn mát đi kèm. Cân chỉnh hài hòa vị mặn ngọt chua thanh để tôn lên độ bùi dẻo của hạt gạo nếp Việt Nam.',7,'Nước mắm ăn kèm các món cơm gà, cơm tấm hay cơm trộn nên nấu sôi nhẹ với đường cho hơi sánh kẹo sẽ bám hạt cơm ngon hơn hẳn.'),
(247,6,'Đơm khuôn đầy đặn, xếp nhân & thưởng thức nóng','Đơm cơm hoặc xôi nóng vào chén ép nhẹ rồi úp tròn ra 4 đĩa, xếp đều các lớp nhân, đồ chua và rắc hành ngò và tiêu xay lên trên cùng. Rưới nhẹ mỡ hành/nước sốt bóng bẩy và thưởng thức ngay khi hạt cơm xôi còn nóng dẻo thơm lừng.',6,'Tráng mỏng một lớp nước lọc hoặc dầu ăn vào lòng chén trước khi đơm cơm giúp úp ra đĩa tròn trịa sắc nét không dính hạt.'),
(248,1,'Sơ chế & thái mỏng đồng đều nguyên liệu xào','Làm sạch và thấm ráo 500g bún tươi và 300g lòng gà, dùng dao sắc thái lát mỏng vừa ăn khoảng 2–3mm ngang thớ để khi xào nhanh chín mềm không bị dai. Nhặt rửa sạch 100g hành tây, cắt khúc xéo 4cm hoặc tách nhánh đồng đều giúp tiếp xúc nhiệt nhanh trên chảo.',8,'Nguyên liệu xào bắt buộc phải để thật ráo nước trước khi cho vào chảo để đạt hiệu ứng áp nhiệt thơm kiểu chảo gang.'),
(248,2,'Ướp mềm nguyên liệu đạm & pha sẵn chén sốt xào','Ướp phần đạm trong 500g bún tươi và 300g lòng gà với 1/3 lượng 50g nghệ và 25g hành tím, chút dầu ăn và 1/3 lượng 20ml nước mắm trong 10 phút để giữ độ ẩm mọng. Pha phần 20ml nước mắm còn lại cùng 20ml nước lọc vào chén nhỏ khuấy tan hoàn toàn để thao tác xào lửa lớn diễn ra dứt khoát.',6,'Thêm 1 muỗng cà phê dầu ăn vào bước ướp thịt bò/heo giúp khóa ẩm và các lát thịt tơi nhanh không bị dính chùm khi gặp chảo nóng.'),
(248,3,'Chần nhanh rau củ giữ sắc xanh ngọc & độ giòn','Đun sôi nồi nước nhỏ với một nhúm muối, thả 100g hành tây vào chần nhanh 30–45 giây rồi vớt ngay ra tô nước đá lạnh cho sốc nhiệt, sau đó đổ ra rổ cho thật ráo. Bước tiền xử lý này giúp rau củ chín đều từ trong mà bên ngoài vẫn xanh mướt giòn sần sật.',5,'Thời gian chần dưới 1 phút kết hợp ngâm nước đá lạnh là bí quyết nhà hàng giúp đĩa rau xào không bị chảy nước đen đĩa.'),
(248,4,'Xào săn nguyên liệu chính trên lửa lớn nhanh tay','Làm nóng chảo rộng trên lửa lớn nhất với 15ml dầu ăn, phi dậy mùi một nửa 50g nghệ và 25g hành tím rồi trút phần đạm chính trong 500g bún tươi và 300g lòng gà vào đảo cực nhanh tay trong 60–90 giây. Ngay khi thịt hoặc hải sản vừa chín tái hồng khoảng 85%, lập tức trút riêng ra đĩa sạch để không bị quá lửa khô xác.',6,'Tuyệt đối không xào thịt chung từ đầu đến cuối với rau củ vì thịt sẽ bị dai và tiết nước làm mất độ giòn.'),
(248,5,'Xào rau củ lửa lớn & rưới sốt định lượng khóa vị','Giữ nguyên chảo nóng trên lửa lớn, thêm chút dầu phi thơm nốt phần 50g nghệ và 25g hành tím còn lại rồi cho 100g hành tây đã ráo nước vào đảo đều 1–2 phút. Trút ngược đĩa đạm vào chảo, rưới đều chén sốt gia vị đã pha và xóc nhanh tay 45 giây cho sốt sánh bóng áo quanh từng miếng nguyên liệu.',6,'Rưới sốt vòng quanh thành chảo nóng thay vì đổ thẳng giữa lòng chảo giúp sốt bốc hơi thơm lừng và sệt lại tức thì.'),
(248,6,'Dậy hương tiêu hành & trình bày nóng hổi','Cho 40g rau răm vào đảo nhẹ đúng 1 lượt rồi tắt bếp ngay khi khói thơm bốc lên nghi ngút. Gắp món Bún nghệ xào lòng gà rau răm xứ Huế ra đĩa rộng lòng để tản nhiệt đều, tránh đậy kín vung và thưởng thức nóng ngay cùng cơm dẻo cho 4 người.',4,'Bày món xào ra đĩa rộng không xếp chồng quá dày giúp hơi nóng thoát nhẹ, giữ rau củ giòn ngọt lâu đến miếng cuối cùng.'),
(249,1,'Sơ chế sạch & chuẩn bị nguyên liệu thuần chay','Rửa sạch toàn bộ nguyên liệu dưới vòi nước mát, để ráo tự nhiên trên rổ thưa gồm 320g gạo tẻ và 180g hạt sen tươi cùng 2 lá lá sen và 80g đậu hà lan. Cắt thái đồng đều kích thước khoảng 3–4cm vừa gắp để khi chế biến chín cùng lúc và thấm đều gia vị thực vật.',8,'Thấm khô bề mặt đậu hũ và nấm bằng khăn giấy bếp trước khi chế biến giúp nguyên liệu săn chắc, không bị bắn dầu hay ra nước.'),
(249,2,'Xử lý độ giòn ngọt của nấm & rau củ','Đối với nhóm nấm và rau củ (2 lá lá sen và 80g đậu hà lan), ngâm nhanh qua nước muối loãng 3 phút rồi vắt nhẹ hoặc chần sơ 45 giây trong nước sôi, vớt ngay ra tô nước mát. Thao tác này giúp giữ trọn sắc màu tươi sáng tự nhiên, loại bỏ mùi ngái và tạo độ giòn ngọt thanh khiết cho món Cơm sen chay gói lá sen tịnh tâm xứ Huế.',7,'Không ngâm nấm quá lâu trong nước lạnh vì nấm sẽ hút nước mạnh làm nhạt vị ngọt umami tự nhiên.'),
(249,3,'Pha chén sốt gia vị chay chuẩn định lượng','Chuẩn bị tô nhỏ, đong chính xác 25ml nước tương khuấy đều cùng 30ml nước ấm hoặc nước ngâm nấm hương cho tan hoàn toàn đường và hạt nêm nấm. Nếm thử thấy vị mặn ngọt hài hòa, thanh dịu đúng tinh thần ẩm thực chay cho khẩu phần 4 người.',6,'Pha sẵn chén sốt trước khi bật bếp giúp kiểm soát chính xác định lượng từng gam và không bị cháy khét gia vị trên chảo nóng.'),
(249,4,'Phi thơm hành boaro & tạo nền hương thảo mộc','Làm nóng nồi hoặc chảo đáy dày trên lửa vừa, cho 15ml dầu thực vật vào láng đều mặt chảo rồi trút 20g hành boaro thái lát mỏng vào phi thơm. Đảo nhẹ tay khoảng 1–2 phút đến khi hành boaro chuyển sắc vàng óng và dậy mùi thơm dịu thì hạ lửa vừa.',7,'Hành boaro cháy nhanh hơn hành tím nên chỉ phi trên lửa vừa đến khi vừa chớm vàng thơm là cho nguyên liệu chính vào ngay.');
INSERT INTO `recipe_steps` (`recipe_id`,`step_order`,`title`,`instruction`,`duration_mins`,`tip_note`) VALUES
(249,5,'Chế biến săn thấm nguyên liệu chính thuần thực vật','Cho 320g gạo tẻ và 180g hạt sen tươi vào đảo đều hoặc áp chảo nhẹ hai mặt trên lửa vừa đến khi bề mặt săn vàng, sau đó rưới 2/3 chén sốt gia vị chay đã pha vào. Đảo nhẹ tay để sốt bám đều quanh từng thớ đậu và nấm mà không làm vỡ nát cấu trúc nguyên liệu.',11,'Dùng sạn gỗ đảo nhẹ từ dưới đáy chảo hất lên để miếng đậu hũ và nấm giữ nguyên hình khối vuông vắn đẹp mắt.'),
(249,6,'Phối hợp rau củ & cân chỉnh độ sánh thanh đạm','Tiếp tục cho 2 lá lá sen và 80g đậu hà lan cùng phần sốt còn lại vào nồi, điều chỉnh lửa vừa nấu thêm cho nguyên liệu chín mềm tới nhưng vẫn giữ độ giòn ngọt. Quan sát thấy nước sốt chuyển màu nâu hổ phách sóng sánh hoặc nước dùng trong thanh, hương thơm quyện đều khắp gian bếp.',10,'Chỉ nấu rau củ xanh vừa chín tới để bảo toàn tối đa lượng chất xơ và vitamin tự nhiên trong khẩu phần chay.'),
(249,7,'Hoàn thiện hương thơm & trình bày món chay thanh tịnh','Tắt bếp ngay khi món ăn đạt độ chín chuẩn, rắc đều hành boaro lá xanh và tiêu xay lên bề mặt để dậy mùi thơm tươi mới. Múc món Cơm sen chay gói lá sen tịnh tâm xứ Huế ra đĩa sứ hoặc tô sâu lòng, thưởng thức nóng cùng cơm trắng hoặc bún tươi cho trọn vẹn 4 khẩu phần.',6,'Rắc rau thơm và tiêu ngay lúc vừa tắt bếp giúp tinh dầu tỏa hương thơm ngát mà lá rau không bị thâm xỉn màu.'),
(250,1,'Sơ chế sạch & chuẩn bị nguyên liệu thuần chay','Rửa sạch toàn bộ nguyên liệu dưới vòi nước mát, để ráo tự nhiên trên rổ thưa gồm 400g đậu hũ và 250g nấm rơm cùng các nguyên liệu phối kèm. Cắt thái đồng đều kích thước khoảng 3–4cm vừa gắp để khi chế biến chín cùng lúc và thấm đều gia vị thực vật.',5,'Thấm khô bề mặt đậu hũ và nấm bằng khăn giấy bếp trước khi chế biến giúp nguyên liệu săn chắc, không bị bắn dầu hay ra nước.'),
(250,2,'Xử lý độ giòn ngọt của nấm & rau củ','Đối với nhóm nấm và rau củ (400g đậu hũ và 250g nấm rơm), ngâm nhanh qua nước muối loãng 3 phút rồi vắt nhẹ hoặc chần sơ 45 giây trong nước sôi, vớt ngay ra tô nước mát. Thao tác này giúp giữ trọn sắc màu tươi sáng tự nhiên, loại bỏ mùi ngái và tạo độ giòn ngọt thanh khiết cho món Đậu hũ kho nấm rơm lá lốt thuần chay Huế.',5,'Không ngâm nấm quá lâu trong nước lạnh vì nấm sẽ hút nước mạnh làm nhạt vị ngọt umami tự nhiên.'),
(250,3,'Pha chén sốt gia vị chay chuẩn định lượng','Chuẩn bị tô nhỏ, đong chính xác 35ml nước tương, 20ml dầu hào chay, 12g đường và 4g tiêu khuấy đều cùng 30ml nước ấm hoặc nước ngâm nấm hương cho tan hoàn toàn đường và hạt nêm nấm. Nếm thử thấy vị mặn ngọt hài hòa, thanh dịu đúng tinh thần ẩm thực chay cho khẩu phần 4 người.',4,'Pha sẵn chén sốt trước khi bật bếp giúp kiểm soát chính xác định lượng từng gam và không bị cháy khét gia vị trên chảo nóng.'),
(250,4,'Phi thơm hành boaro & tạo nền hương thảo mộc','Làm nóng nồi hoặc chảo đáy dày trên lửa vừa, cho 15ml dầu thực vật vào láng đều mặt chảo rồi trút 30g hành boaro vào phi thơm. Đảo nhẹ tay khoảng 1–2 phút đến khi hành boaro chuyển sắc vàng óng và dậy mùi thơm dịu thì hạ lửa vừa.',4,'Hành boaro cháy nhanh hơn hành tím nên chỉ phi trên lửa vừa đến khi vừa chớm vàng thơm là cho nguyên liệu chính vào ngay.'),
(250,5,'Chế biến săn thấm nguyên liệu chính thuần thực vật','Cho 400g đậu hũ và 250g nấm rơm vào đảo đều hoặc áp chảo nhẹ hai mặt trên lửa vừa đến khi bề mặt săn vàng, sau đó rưới 2/3 chén sốt gia vị chay đã pha vào. Đảo nhẹ tay để sốt bám đều quanh từng thớ đậu và nấm mà không làm vỡ nát cấu trúc nguyên liệu.',7,'Dùng sạn gỗ đảo nhẹ từ dưới đáy chảo hất lên để miếng đậu hũ và nấm giữ nguyên hình khối vuông vắn đẹp mắt.'),
(250,6,'Phối hợp rau củ & cân chỉnh độ sánh thanh đạm','Tiếp tục cho các nguyên liệu phối kèm cùng phần sốt còn lại vào nồi, điều chỉnh lửa vừa nấu thêm cho nguyên liệu chín mềm tới nhưng vẫn giữ độ giòn ngọt. Quan sát thấy nước sốt chuyển màu nâu hổ phách sóng sánh hoặc nước dùng trong thanh, hương thơm quyện đều khắp gian bếp.',6,'Chỉ nấu rau củ xanh vừa chín tới để bảo toàn tối đa lượng chất xơ và vitamin tự nhiên trong khẩu phần chay.'),
(250,7,'Hoàn thiện hương thơm & trình bày món chay thanh tịnh','Tắt bếp ngay khi món ăn đạt độ chín chuẩn, rắc đều 30g lá lốt lên bề mặt để dậy mùi thơm tươi mới. Múc món Đậu hũ kho nấm rơm lá lốt thuần chay Huế ra đĩa sứ hoặc tô sâu lòng, thưởng thức nóng cùng cơm trắng hoặc bún tươi cho trọn vẹn 4 khẩu phần.',4,'Rắc rau thơm và tiêu ngay lúc vừa tắt bếp giúp tinh dầu tỏa hương thơm ngát mà lá rau không bị thâm xỉn màu.'),
(251,1,'Tuyển chọn, ngâm nở & sơ chế sạch nguyên liệu chè bánh','Đãi rửa sạch nhóm hạt, củ hoặc bột (220g bột năng và 180g dừa non), ngâm nước ấm theo đúng đặc tính từng loại để hạt nở mềm đồng đều và loại bỏ nhựa chát. Rửa sạch nhóm tạo hương tự nhiên gồm 25g gừng và 20g lá dứa để ráo nước.',10,'Thêm một nhúm muối nhỏ vào nước ngâm khoai và đậu giúp nguyên liệu giữ màu tươi sáng và khi nấu chín bùi hơn.'),
(251,2,'Ninh mềm bùi nguyên liệu chính giữ nguyên hạt/khối','Cho phần nguyên liệu nền trong 220g bột năng và 180g dừa non vào nồi đáy dày cùng lượng nước vừa đủ, đun sôi rồi hạ lửa nhỏ ninh êm đến khi chín mềm bùi nhưng không bị vỡ nát đục nước. Nếu có trân châu, bột lọc hoặc hạt lựu, luộc riêng trong nồi nước sôi đến khi nổi trong veo rồi vớt ngâm ngay vào bát nước mát.',14,'Tuyệt đối không cho đường ngay từ đầu khi đậu và khoai chưa chín mềm vì đường sẽ làm săn vỏ hạt khiến nấu mãi vẫn sượng.'),
(251,3,'Nấu nước đường phèn / mật mía thanh trong dậy hương','Kết hợp chính xác định lượng 140g đường phèn vào nồi cùng bó lá dứa hoặc gừng thái chỉ, khuấy nhẹ trên lửa nhỏ cho tan trong vắt. Đun liu riu thêm 5–7 phút để vị ngọt thấm sâu vào từng viên nguyên liệu và tỏa hương thơm dịu tao nhã.',9,'Dùng đường phèn hoặc mật mía đun lửa nhỏ hớt bọt kỹ giúp hậu vị chè ngọt thanh mát họng, không bị khé cổ.'),
(251,4,'Thắng nước cốt dừa béo mịn / chuẩn bị lớp kem phủ','Cho nước cốt dừa vào nồi nhỏ cùng 2g muối tinh và 5g bột năng/bột bắp hòa loãng, khuấy đều tay trên lửa nhỏ nhất đến khi vừa chớm sôi lăn tăn sánh mượt. Tắt bếp ngay để nước cốt dừa giữ màu trắng ngần béo ngậy mà không bị tách lớp dầu.',7,'Một chút xíu muối tinh trong nồi nước cốt dừa sẽ làm bật hẳn độ béo thơm tự nhiên và cân bằng vị ngọt của món tráng miệng.'),
(251,5,'Phối hợp độ sánh mượt & cân bằng hương vị tổng thể','Hợp nhất các thành phần của món Chè bột lọc bọc dừa non thanh ngọt xứ Huế, từ từ rưới nước bột năng hòa loãng (nếu là chè sánh) đồng thời khuấy nhẹ một chiều trên lửa nhỏ cho hỗn hợp bóng mượt như nhung. Kiểm tra độ mềm dẻo hài hòa và tắt bếp để ủ hương thảo mộc lan tỏa đều.',6,'Rót nước bột tạo sánh thành dòng mảnh vừa rót vừa khuấy đều tay giúp chè trong mượt, hoàn toàn không bị ốc trâu vón cục.'),
(251,6,'Múc ra chén sứ, điểm topping & thưởng thức ấm/lạnh','Múc chè hoặc bày bánh ra 4 chén nhỏ xinh, chan lớp nước cốt dừa trắng mịn lên mặt và rắc nhẹ 15g mè rang. Thưởng thức ấm nóng dịu dàng hoặc thêm đá bào mát lạnh tùy sở thích đều trọn vị ngon truyền thống.',4,'Để chè nguội bớt về khoảng 45°C hoặc ướp mát 30 phút trong ngăn mát tủ lạnh giúp các tầng hương vị kết tinh đậm đà hơn.'),
(252,1,'Tuyển chọn, ngâm nở & sơ chế sạch nguyên liệu chè bánh','Đãi rửa sạch nhóm hạt, củ hoặc bột (500g bắp ngọt và 30g bột năng), ngâm nước ấm theo đúng đặc tính từng loại để hạt nở mềm đồng đều và loại bỏ nhựa chát. Rửa sạch nhóm tạo hương tự nhiên gồm 25g lá dứa để ráo nước.',8,'Thêm một nhúm muối nhỏ vào nước ngâm khoai và đậu giúp nguyên liệu giữ màu tươi sáng và khi nấu chín bùi hơn.'),
(252,2,'Ninh mềm bùi nguyên liệu chính giữ nguyên hạt/khối','Cho phần nguyên liệu nền trong 500g bắp ngọt và 30g bột năng vào nồi đáy dày cùng lượng nước vừa đủ, đun sôi rồi hạ lửa nhỏ ninh êm đến khi chín mềm bùi nhưng không bị vỡ nát đục nước. Nếu có trân châu, bột lọc hoặc hạt lựu, luộc riêng trong nồi nước sôi đến khi nổi trong veo rồi vớt ngâm ngay vào bát nước mát.',11,'Tuyệt đối không cho đường ngay từ đầu khi đậu và khoai chưa chín mềm vì đường sẽ làm săn vỏ hạt khiến nấu mãi vẫn sượng.'),
(252,3,'Nấu nước đường phèn / mật mía thanh trong dậy hương','Kết hợp chính xác định lượng 120g đường phèn và 3g muối vào nồi cùng bó lá dứa hoặc gừng thái chỉ, khuấy nhẹ trên lửa nhỏ cho tan trong vắt. Đun liu riu thêm 5–7 phút để vị ngọt thấm sâu vào từng viên nguyên liệu và tỏa hương thơm dịu tao nhã.',7,'Dùng đường phèn hoặc mật mía đun lửa nhỏ hớt bọt kỹ giúp hậu vị chè ngọt thanh mát họng, không bị khé cổ.'),
(252,4,'Thắng nước cốt dừa béo mịn / chuẩn bị lớp kem phủ','Cho 150ml nước cốt dừa vào nồi nhỏ cùng 2g muối tinh và 5g bột năng/bột bắp hòa loãng, khuấy đều tay trên lửa nhỏ nhất đến khi vừa chớm sôi lăn tăn sánh mượt. Tắt bếp ngay để nước cốt dừa giữ màu trắng ngần béo ngậy mà không bị tách lớp dầu.',6,'Một chút xíu muối tinh trong nồi nước cốt dừa sẽ làm bật hẳn độ béo thơm tự nhiên và cân bằng vị ngọt của món tráng miệng.'),
(252,5,'Phối hợp độ sánh mượt & cân bằng hương vị tổng thể','Hợp nhất các thành phần của món Chè bắp Cồn Hến Huế sánh mịn cốt dừa, từ từ rưới nước bột năng hòa loãng (nếu là chè sánh) đồng thời khuấy nhẹ một chiều trên lửa nhỏ cho hỗn hợp bóng mượt như nhung. Kiểm tra độ mềm dẻo hài hòa và tắt bếp để ủ hương thảo mộc lan tỏa đều.',5,'Rót nước bột tạo sánh thành dòng mảnh vừa rót vừa khuấy đều tay giúp chè trong mượt, hoàn toàn không bị ốc trâu vón cục.'),
(252,6,'Múc ra chén sứ, điểm topping & thưởng thức ấm/lạnh','Múc chè hoặc bày bánh ra 4 chén nhỏ xinh, chan lớp nước cốt dừa trắng mịn lên mặt và rắc nhẹ mè rang, đậu phộng hoặc dừa non bào sợi. Thưởng thức ấm nóng dịu dàng hoặc thêm đá bào mát lạnh tùy sở thích đều trọn vị ngon truyền thống.',3,'Để chè nguội bớt về khoảng 45°C hoặc ướp mát 30 phút trong ngăn mát tủ lạnh giúp các tầng hương vị kết tinh đậm đà hơn.'),
(253,1,'Sơ chế & chần sạch nguyên liệu xương thịt, hải sản','Rửa sạch 500g sợi cao lầu và 400g thịt heo (nạc vai) với muối hạt rồi chần nhanh trong nồi nước sôi có đập dập 1 nhánh gừng trong 2–3 phút trên lửa lớn để loại bỏ hoàn toàn bọt bẩn. Rửa lại dưới làn nước sạch cho thật trắng trẻo, đồng thời nhặt rửa sạch 150g giá đỗ và 180g rau sống để ráo nước.',11,'Bước chần sơ và rửa lại bằng nước ấm là bí quyết vàng giúp nồi nước dùng trong vắt, thơm thanh và không bao giờ bị đục hay hôi.'),
(253,2,'Nướng thơm thảo mộc & ninh nền nước dùng ngọt thanh','Cho phần nguyên liệu tạo ngọt từ 500g sợi cao lầu và 400g thịt heo (nạc vai) cùng 20g tỏi đã nướng xém thơm vào nồi sâu lòng với khoảng 1.5–1.8 lít nước lọc. Đun sôi bùng trên lửa lớn rồi hạ ngay về lửa nhỏ liu riu, mở hé vung và hớt kỹ bọt nổi trên mặt để chiết xuất vị ngọt tự nhiên.',23,'Luôn duy trì mặt nước lăn tăn nhẹ thay vì đun sôi sùng sục lửa to để protein không bị nhũ hóa gây đục nước lèo.'),
(253,3,'Xào tạo màu & dậy hương đặc trưng vùng miền','Bắc chảo nhỏ lên bếp với 15ml dầu ăn trên lửa vừa, phi thơm phần hành tỏi sả băm còn lại rồi xào săn 60g bánh đa nướng cùng 40ml nước tương và 5g ngũ vị hương trong 3–4 phút. Khi hỗn hợp dậy mùi thơm nồng nàn và lên sắc màu óng ả đặc trưng của món Cao lầu phố cổ Hội An thịt xá xíu giòn thơm thì tắt bếp.',9,'Xào riêng phần nguyên liệu tạo màu và gia vị thơm trước khi trút vào nồi nước dùng giúp tầng hương dậy lên rõ nét gấp đôi.');
INSERT INTO `recipe_steps` (`recipe_id`,`step_order`,`title`,`instruction`,`duration_mins`,`tip_note`) VALUES
(253,4,'Sơ chế & cắt thái phần nhân topping xếp tô','Vớt phần thịt hoặc hải sản chín tới từ 500g sợi cao lầu và 400g thịt heo (nạc vai) ra ngâm ngay vào âu nước đun sôi để nguội giúp bề mặt săn giòn mọng nước, không bị thâm khô. Thái lát mỏng đều tay dày khoảng 3mm ngang thớ hoặc gỡ miếng vừa ăn, sắp riêng từng phần gọn gàng trên đĩa.',9,'Thái thịt ngang thớ với lưỡi dao thật sắc giúp lát thịt mềm mướt, khi chan nước dùng sôi lên sẽ phẳng đẹp không bị quăn cứng.'),
(253,5,'Hợp nhất nồi nước lèo & nêm chuẩn định lượng','Trút phần sốt màu thơm vào nồi nước dùng đang sôi lăn tăn, nêm chính xác lượng 40ml nước tương và 5g ngũ vị hương còn lại cho vừa miệng 4 người ăn. Đun nhẹ thêm 5 phút ở lửa vừa để các tầng vị mặn dịu, ngọt hậu từ xương thịt và thảo mộc hòa quyện tròn trịa.',9,'Nên nêm nước mắm ngon ở giai đoạn cuối trên lửa nhỏ để giữ trọn hậu vị ngọt đạm và hương thơm mà không làm nước dùng bị chua.'),
(253,6,'Chần nóng sợi bánh/bún & chuẩn bị rau ăn kèm','Đun sôi một nồi nước riêng, cho phần sợi bún/phở/bánh trong 500g sợi cao lầu và 400g thịt heo (nạc vai) vào trụng nhanh 15–25 giây cho sợi mềm dẻo nóng hổi rồi vẩy thật ráo nước, chia đều vào 4 tô lớn. Chần sơ thêm rau ăn kèm (150g giá đỗ và 180g rau sống) nếu muốn dùng chín giòn.',8,'Trụng bún bánh ở nồi nước sôi riêng biệt giúp nước dùng chính không bị nhiễm tinh bột chua và tô bún luôn ráo sợi, thấm vị.'),
(253,7,'Xếp nhân hài hòa, chan nước dùng sôi & thưởng thức','Xếp đều các phần nhân thịt, hải sản lên mặt tô bún bánh, điểm xuyết hành ngò và tiêu xay lên trên cùng. Dùng muôi múc nước dùng đang sôi thật già chan ngập xăm xắp mặt nguyên liệu để làm chín thơm hành ngò, dọn nóng ngay kèm chanh ớt tươi.',6,'Tráng nóng tô sứ bằng nước sôi trước khi xếp bún giúp tô món nước giữ nhiệt bốc khói nghi ngút suốt bữa ăn.'),
(254,1,'Sơ chế tươi sạch & ngâm giòn rau củ thảo mộc','Nhặt rửa kỹ 120g dứa, 150g dưa leo và 100g xoài xanh cùng hành ngò và tiêu xay qua nước muối loãng rồi tráng nước đun sôi để nguội. Với các loại củ quả bào sợi hoặc thái lát mỏng, ngâm vào âu nước đá lạnh pha chút chanh đường trong 10 phút rồi vắt ráo để giữ độ trắng giòn sần sật.',10,'Rau củ làm gỏi và món cuốn phải quay rổ hoặc thấm thật ráo nước để khi trộn nước mắm không bị loãng nhạt.'),
(254,2,'Làm chín tới phần nhân đạm giữ trọn độ ngọt mọng','Xử lý phần nguyên liệu chính (550g thịt ba chỉ và 20 lá bánh tráng): luộc hấp cùng lát gừng sả đập dập hoặc xào lửa lớn vừa chín tới, sau đó làm nguội nhanh rồi thái lát mỏng / xé sợi đều đặn. Nếu món có pha bột bánh gạo/bột năng, khuấy tan bột với nước đúng tỷ lệ và để bột nghỉ 15 phút cho nở mịn.',12,'Ngâm tôm hoặc thịt luộc qua bát nước sôi để nguội có vài viên đá giúp màu sắc tươi hồng và thớ thịt giòn ngọt không bị khô.'),
(254,3,'Rang vàng đậu phộng mè thơm & phi hành tỏi giòn','Bắc chảo nhỏ lên lửa nhỏ, rang chín vàng thơm đậu phộng/mè hoặc làm mỡ hành xanh mướt và phi vàng giòn hành tím và tỏi băm nhỏ. Vớt hành tỏi phi ra đĩa riêng để nguội giòn tan, giữ lại phần dầu thơm óng ánh để phết bánh hoặc rưới bóng mặt món ăn.',7,'Tắt bếp ngay khi hành phi chuyển vàng sáng vì nhiệt dư trong dầu nóng sẽ tiếp tục làm hành sẫm màu thêm một nấc hoàn hảo.'),
(254,4,'Pha nước mắm chấm / sốt trộn tỷ lệ vàng chua ngọt','Hòa tan hoàn toàn đường cùng 120ml mắm nêm và nước ấm trong chén sâu lòng, khuấy đến khi hơi sánh nhẹ mới cho tỏi ớt băm nhuyễn và nước cốt chanh/tắc vào sau cùng. Công thức pha này giúp tỏi ớt nổi đều đẹp mắt trên bề mặt bát nước chấm chuẩn vị Bánh tráng cuốn thịt heo luộc Đà Nẵng mắm nêm.',7,'Băm tỏi ớt thật ráo trên thớt khô và cho vào sau khi đường mắm đã nguội thì tỏi ớt sẽ nổi bồng bềnh 100% không bị chìm đáy.'),
(254,5,'Phối trộn thấm vị / tráng hấp & cuốn đều tay','Tiến hành tráng hấp bánh mỏng mượt hoặc trải bánh cuốn gọn gàng 550g thịt ba chỉ và 20 lá bánh tráng cùng 120g dứa, 150g dưa leo và 100g xoài xanh; nếu là món gỏi trộn thì rưới từ từ 2/3 lượng sốt chua ngọt vào bóp nhẹ tay cho thấm đều trong 3 phút. Giữ lực tay nhẹ nhàng để rau củ không bị dập nát mà vẫn ngấm trọn vị mặn chua ngọt hài hòa.',9,'Chia nước sốt gỏi làm 2 lần trộn và chắt bỏ phần nước tiết ra ở lần đầu giúp đĩa gỏi khô ráo, đậm đà như ngoài hàng.'),
(254,6,'Bày biện ngũ sắc hài hòa & rắc topping giòn bùi','Xếp món Bánh tráng cuốn thịt heo luộc Đà Nẵng mắm nêm ngay ngắn ra đĩa sứ trắng rộng, rải đều phần nhân tôm thịt sắc nét lên trên và rắc phủ hành ngò và tiêu xay thơm giòn. Dọn kèm chén nước chấm đậm đà cho 4 người thưởng thức ngay khi rau bánh còn tươi giòn mướt mịn.',5,'Chỉ rắc đậu phộng rang và hành phi ngay trước lúc mang ra bàn ăn để giữ nguyên độ giòn tan bùi béo.'),
(255,1,'Sơ chế sạch & thấm thật khô bề mặt nguyên liệu','Rửa sạch 500g bún tươi và 350g thịt heo quay cùng chút muối loãng để khử mùi tự nhiên, sau đó dùng khăn giấy bếp thấm thật khô ráo hoàn toàn bề mặt. Khứa nhẹ các đường chéo hoặc cắt miếng vừa ăn dày 2–3cm để nhiệt và gia vị thấm sâu đều khắp bên trong.',5,'Bề mặt nguyên liệu càng khô ráo thì khi chiên không bị văng dầu và khi nướng sẽ lên màu vàng ruộm giòn rụm cực đẹp.'),
(255,2,'Chuẩn bị hỗn hợp sốt ướp / bột áo chuẩn tỷ lệ','Phối trộn hành tím và tỏi băm nhỏ băm thật nhuyễn (hoặc vắt lấy nước cốt thơm) cùng 100ml mắm nêm và 25g đường trong tô lớn cho quyện sánh đồng nhất. Nếu món có lớp vỏ bột hoặc bánh cuốn từ 500g bún tươi và 350g thịt heo quay, trộn đều hỗn hợp theo đúng định lượng để đạt độ giòn xốp mỏng nhẹ chuẩn vị.',5,'Vắt lấy nước cốt hành tỏi sả khi ướp đồ nướng giúp hương thơm thấm sâu mà không bị cháy đen phần xác băm trên lửa cao.'),
(255,3,'Ướp thấm thớ thịt / tạo hình cuốn khéo léo','Áo đều hỗn hợp gia vị hoặc lớp bột/vỏ cuốn quanh 500g bún tươi và 350g thịt heo quay, massage nhẹ nhàng rồi để nghỉ 15–20 phút cho gia vị thẩm thấu trọn vẹn. Trường hợp cuốn chả/nem hoặc đổ khuôn bánh, thao tác đều tay vừa chặt để nhân kết dính nhưng không bị bục rách khi gặp nhiệt.',6,'Để nguyên liệu nghỉ đủ thời gian trước khi chiên nướng giúp lớp áo bột bám chắc và phần nhân bên trong mọng ngọt.'),
(255,4,'Pha nước chấm cân vị & sơ chế rau đồ chua ăn kèm','Nhặt rửa sạch 150g mít non, 120g dứa và 150g rau sống ngâm nước mát cho giòn tươi, bào sợi hoặc thái lát gọn gàng bày sẵn bên cạnh. Pha chén nước chấm chua ngọt hoặc muối ớt chanh sả sánh thơm theo khẩu vị vùng miền của món Bún mắm nêm thịt heo quay giòn bì Đà Nẵng để cân bằng độ béo giòn.',4,'Luôn chuẩn bị xong rau sống và bát nước chấm trước khi chiên/nướng mẻ cuối để món ăn vừa ra lò là thưởng thức nóng giòn ngay.'),
(255,5,'Làm nóng dầu / lò nướng chuẩn nhiệt & làm chín đều lần 1','Làm nóng chảo dầu hoặc vỉ nướng/nồi chiên ở mức nhiệt vừa khoảng 165–175°C, xếp 500g bún tươi và 350g thịt heo quay vào với khoảng cách thoáng đều nhau. Chiên hoặc nướng trở mặt nhịp nhàng trên lửa vừa để nhiệt dẫn sâu làm chín mềm ngọt hoàn toàn phần nhân bên trong.',8,'Kiểm tra nhiệt dầu bằng đầu đũa tre thấy sủi tăm nhỏ đều là đạt chuẩn 170°C, giúp vỏ không cháy sớm khi bên trong còn sống.'),
(255,6,'Tăng nhiệt khóa giòn rụm vàng ươm bề mặt lần 2','Ở 2–3 phút cuối, tăng lên lửa vừa lớn (khoảng 190°C) hoặc phết thêm lớp dầu điều/mật ong mỏng để vỏ ngoài của Bún mắm nêm thịt heo quay giòn bì Đà Nẵng chuyển sắc vàng óng ánh và nổ giòn rụm. Lắng nghe tiếng xèo giòn rộn rã và hương thơm phức lan tỏa khắp bếp thì gắp ra vỉ thưa cho ráo dầu thừa.',4,'Đặt đồ chiên nướng lên giá inox thoáng khí thay vì giấy thấm dầu chồng khít để hơi nước thoát hết, giữ độ giòn lâu gấp 3 lần.'),
(255,7,'Trình bày bắt mắt kèm rau thơm & thưởng thức nóng','Xếp thành phẩm vàng giòn ra đĩa lớn có bày sẵn 150g mít non, 120g dứa và 150g rau sống và điểm xuyết 50g đậu phộng tươi xanh hài hòa màu sắc. Dọn kèm chén nước chấm sánh đậm ngay chính giữa mâm ăn cho 4 người thưởng thức khi vỏ ngoài còn nóng giòn rụm.',3,'Cắt miếng hoặc dọn ăn ngay trong vòng 10 phút sau khi rời bếp để cảm nhận trọn vẹn sự đối lập giòn ngoài - mềm ngọt bên trong.'),
(256,1,'Sơ chế tươi sạch & ngâm giòn rau củ thảo mộc','Nhặt rửa kỹ 250g rau muống cùng 35g hành lá qua nước muối loãng rồi tráng nước đun sôi để nguội. Với các loại củ quả bào sợi hoặc thái lát mỏng, ngâm vào âu nước đá lạnh pha chút chanh đường trong 10 phút rồi vắt ráo để giữ độ trắng giòn sần sật.',7,'Rau củ làm gỏi và món cuốn phải quay rổ hoặc thấm thật ráo nước để khi trộn nước mắm không bị loãng nhạt.'),
(256,2,'Làm chín tới phần nhân đạm giữ trọn độ ngọt mọng','Xử lý phần nguyên liệu chính (600g cá nục và 20 lá bánh tráng): luộc hấp cùng lát gừng sả đập dập hoặc xào lửa lớn vừa chín tới, sau đó làm nguội nhanh rồi thái lát mỏng / xé sợi đều đặn. Nếu món có pha bột bánh gạo/bột năng, khuấy tan bột với nước đúng tỷ lệ và để bột nghỉ 15 phút cho nở mịn.',8,'Ngâm tôm hoặc thịt luộc qua bát nước sôi để nguội có vài viên đá giúp màu sắc tươi hồng và thớ thịt giòn ngọt không bị khô.'),
(256,3,'Rang vàng đậu phộng mè thơm & phi hành tỏi giòn','Bắc chảo nhỏ lên lửa nhỏ, rang chín vàng thơm đậu phộng/mè hoặc làm mỡ hành xanh mướt và phi vàng giòn 40g hành tím. Vớt hành tỏi phi ra đĩa riêng để nguội giòn tan, giữ lại phần dầu thơm óng ánh để phết bánh hoặc rưới bóng mặt món ăn.',5,'Tắt bếp ngay khi hành phi chuyển vàng sáng vì nhiệt dư trong dầu nóng sẽ tiếp tục làm hành sẫm màu thêm một nấc hoàn hảo.'),
(256,4,'Pha nước mắm chấm / sốt trộn tỷ lệ vàng chua ngọt','Hòa tan hoàn toàn đường cùng 40ml nước mắm, 12g ớt và 15ml chanh và nước ấm trong chén sâu lòng, khuấy đến khi hơi sánh nhẹ mới cho tỏi ớt băm nhuyễn và nước cốt chanh/tắc vào sau cùng. Công thức pha này giúp tỏi ớt nổi đều đẹp mắt trên bề mặt bát nước chấm chuẩn vị Cá nục hấp cuốn bánh tráng rau muống Đà Nẵng.',5,'Băm tỏi ớt thật ráo trên thớt khô và cho vào sau khi đường mắm đã nguội thì tỏi ớt sẽ nổi bồng bềnh 100% không bị chìm đáy.'),
(256,5,'Phối trộn thấm vị / tráng hấp & cuốn đều tay','Tiến hành tráng hấp bánh mỏng mượt hoặc trải bánh cuốn gọn gàng 600g cá nục và 20 lá bánh tráng cùng 250g rau muống; nếu là món gỏi trộn thì rưới từ từ 2/3 lượng sốt chua ngọt vào bóp nhẹ tay cho thấm đều trong 3 phút. Giữ lực tay nhẹ nhàng để rau củ không bị dập nát mà vẫn ngấm trọn vị mặn chua ngọt hài hòa.',6,'Chia nước sốt gỏi làm 2 lần trộn và chắt bỏ phần nước tiết ra ở lần đầu giúp đĩa gỏi khô ráo, đậm đà như ngoài hàng.'),
(256,6,'Bày biện ngũ sắc hài hòa & rắc topping giòn bùi','Xếp món Cá nục hấp cuốn bánh tráng rau muống Đà Nẵng ngay ngắn ra đĩa sứ trắng rộng, rải đều phần nhân tôm thịt sắc nét lên trên và rắc phủ 35g hành lá thơm giòn. Dọn kèm chén nước chấm đậm đà cho 4 người thưởng thức ngay khi rau bánh còn tươi giòn mướt mịn.',4,'Chỉ rắc đậu phộng rang và hành phi ngay trước lúc mang ra bàn ăn để giữ nguyên độ giòn tan bùi béo.'),
(257,1,'Sơ chế & chần sạch nguyên liệu xương thịt, hải sản','Rửa sạch 350g con don và 4 chiếc bánh đa nướng với muối hạt rồi chần nhanh trong nồi nước sôi có đập dập 1 nhánh gừng trong 2–3 phút trên lửa lớn để loại bỏ hoàn toàn bọt bẩn. Rửa lại dưới làn nước sạch cho thật trắng trẻo, đồng thời nhặt rửa sạch 80g hành tây để ráo nước.',6,'Bước chần sơ và rửa lại bằng nước ấm là bí quyết vàng giúp nồi nước dùng trong vắt, thơm thanh và không bao giờ bị đục hay hôi.'),
(257,2,'Nướng thơm thảo mộc & ninh nền nước dùng ngọt thanh','Cho phần nguyên liệu tạo ngọt từ 350g con don và 4 chiếc bánh đa nướng cùng 20g hành tím đã nướng xém thơm vào nồi sâu lòng với khoảng 1.5–1.8 lít nước lọc. Đun sôi bùng trên lửa lớn rồi hạ ngay về lửa nhỏ liu riu, mở hé vung và hớt kỹ bọt nổi trên mặt để chiết xuất vị ngọt tự nhiên.',16,'Luôn duy trì mặt nước lăn tăn nhẹ thay vì đun sôi sùng sục lửa to để protein không bị nhũ hóa gây đục nước lèo.');
INSERT INTO `recipe_steps` (`recipe_id`,`step_order`,`title`,`instruction`,`duration_mins`,`tip_note`) VALUES
(257,3,'Xào tạo màu & dậy hương đặc trưng vùng miền','Bắc chảo nhỏ lên bếp với 15ml dầu ăn trên lửa vừa, phi thơm phần hành tỏi sả băm còn lại rồi xào săn 80g hành tây cùng 20ml nước mắm và 10g ớt trong 3–4 phút. Khi hỗn hợp dậy mùi thơm nồng nàn và lên sắc màu óng ả đặc trưng của món Don Quảng Ngãi nước dùng thanh ngọt bánh đa nướng thì tắt bếp.',5,'Xào riêng phần nguyên liệu tạo màu và gia vị thơm trước khi trút vào nồi nước dùng giúp tầng hương dậy lên rõ nét gấp đôi.'),
(257,4,'Sơ chế & cắt thái phần nhân topping xếp tô','Vớt phần thịt hoặc hải sản chín tới từ 350g con don và 4 chiếc bánh đa nướng ra ngâm ngay vào âu nước đun sôi để nguội giúp bề mặt săn giòn mọng nước, không bị thâm khô. Thái lát mỏng đều tay dày khoảng 3mm ngang thớ hoặc gỡ miếng vừa ăn, sắp riêng từng phần gọn gàng trên đĩa.',5,'Thái thịt ngang thớ với lưỡi dao thật sắc giúp lát thịt mềm mướt, khi chan nước dùng sôi lên sẽ phẳng đẹp không bị quăn cứng.'),
(257,5,'Hợp nhất nồi nước lèo & nêm chuẩn định lượng','Trút phần sốt màu thơm vào nồi nước dùng đang sôi lăn tăn, nêm chính xác lượng 20ml nước mắm và 10g ớt còn lại cho vừa miệng 4 người ăn. Đun nhẹ thêm 5 phút ở lửa vừa để các tầng vị mặn dịu, ngọt hậu từ xương thịt và thảo mộc hòa quyện tròn trịa.',5,'Nên nêm nước mắm ngon ở giai đoạn cuối trên lửa nhỏ để giữ trọn hậu vị ngọt đạm và hương thơm mà không làm nước dùng bị chua.'),
(257,6,'Chần nóng sợi bánh/bún & chuẩn bị rau ăn kèm','Đun sôi một nồi nước riêng, cho phần sợi bún/phở/bánh trong 350g con don và 4 chiếc bánh đa nướng vào trụng nhanh 15–25 giây cho sợi mềm dẻo nóng hổi rồi vẩy thật ráo nước, chia đều vào 4 tô lớn. Chần sơ thêm rau ăn kèm (80g hành tây) nếu muốn dùng chín giòn.',4,'Trụng bún bánh ở nồi nước sôi riêng biệt giúp nước dùng chính không bị nhiễm tinh bột chua và tô bún luôn ráo sợi, thấm vị.'),
(257,7,'Xếp nhân hài hòa, chan nước dùng sôi & thưởng thức','Xếp đều các phần nhân thịt, hải sản lên mặt tô bún bánh, điểm xuyết 35g hành lá và 20g rau răm lên trên cùng. Dùng muôi múc nước dùng đang sôi thật già chan ngập xăm xắp mặt nguyên liệu để làm chín thơm hành ngò, dọn nóng ngay kèm chanh ớt tươi.',4,'Tráng nóng tô sứ bằng nước sôi trước khi xếp bún giúp tô món nước giữ nhiệt bốc khói nghi ngút suốt bữa ăn.'),
(258,1,'Sơ chế sạch & thấm thật khô bề mặt nguyên liệu','Rửa sạch 450g bắp ngọt và 120g tôm đất cùng chút muối loãng để khử mùi tự nhiên, sau đó dùng khăn giấy bếp thấm thật khô ráo hoàn toàn bề mặt. Khứa nhẹ các đường chéo hoặc cắt miếng vừa ăn dày 2–3cm để nhiệt và gia vị thấm sâu đều khắp bên trong.',7,'Bề mặt nguyên liệu càng khô ráo thì khi chiên không bị văng dầu và khi nướng sẽ lên màu vàng ruộm giòn rụm cực đẹp.'),
(258,2,'Chuẩn bị hỗn hợp sốt ướp / bột áo chuẩn tỷ lệ','Phối trộn hành tím và tỏi băm nhỏ băm thật nhuyễn (hoặc vắt lấy nước cốt thơm) cùng 4g tiêu trong tô lớn cho quyện sánh đồng nhất. Nếu món có lớp vỏ bột hoặc bánh cuốn từ 450g bắp ngọt và 120g tôm đất, trộn đều hỗn hợp theo đúng định lượng để đạt độ giòn xốp mỏng nhẹ chuẩn vị.',6,'Vắt lấy nước cốt hành tỏi sả khi ướp đồ nướng giúp hương thơm thấm sâu mà không bị cháy đen phần xác băm trên lửa cao.'),
(258,3,'Ướp thấm thớ thịt / tạo hình cuốn khéo léo','Áo đều hỗn hợp gia vị hoặc lớp bột/vỏ cuốn quanh 450g bắp ngọt và 120g tôm đất, massage nhẹ nhàng rồi để nghỉ 15–20 phút cho gia vị thẩm thấu trọn vẹn. Trường hợp cuốn chả/nem hoặc đổ khuôn bánh, thao tác đều tay vừa chặt để nhân kết dính nhưng không bị bục rách khi gặp nhiệt.',8,'Để nguyên liệu nghỉ đủ thời gian trước khi chiên nướng giúp lớp áo bột bám chắc và phần nhân bên trong mọng ngọt.'),
(258,4,'Pha nước chấm cân vị & sơ chế rau đồ chua ăn kèm','Nhặt rửa sạch 150g rau sống ngâm nước mát cho giòn tươi, bào sợi hoặc thái lát gọn gàng bày sẵn bên cạnh. Pha chén nước chấm chua ngọt hoặc muối ớt chanh sả sánh thơm theo khẩu vị vùng miền của món Ram bắp non Quảng Ngãi cuốn giòn rụm để cân bằng độ béo giòn.',5,'Luôn chuẩn bị xong rau sống và bát nước chấm trước khi chiên/nướng mẻ cuối để món ăn vừa ra lò là thưởng thức nóng giòn ngay.'),
(258,5,'Làm nóng dầu / lò nướng chuẩn nhiệt & làm chín đều lần 1','Làm nóng chảo dầu hoặc vỉ nướng/nồi chiên ở mức nhiệt vừa khoảng 165–175°C, xếp 450g bắp ngọt và 120g tôm đất vào với khoảng cách thoáng đều nhau. Chiên hoặc nướng trở mặt nhịp nhàng trên lửa vừa để nhiệt dẫn sâu làm chín mềm ngọt hoàn toàn phần nhân bên trong.',10,'Kiểm tra nhiệt dầu bằng đầu đũa tre thấy sủi tăm nhỏ đều là đạt chuẩn 170°C, giúp vỏ không cháy sớm khi bên trong còn sống.'),
(258,6,'Tăng nhiệt khóa giòn rụm vàng ươm bề mặt lần 2','Ở 2–3 phút cuối, tăng lên lửa vừa lớn (khoảng 190°C) hoặc phết thêm lớp dầu điều/mật ong mỏng để vỏ ngoài của Ram bắp non Quảng Ngãi cuốn giòn rụm chuyển sắc vàng óng ánh và nổ giòn rụm. Lắng nghe tiếng xèo giòn rộn rã và hương thơm phức lan tỏa khắp bếp thì gắp ra vỉ thưa cho ráo dầu thừa.',5,'Đặt đồ chiên nướng lên giá inox thoáng khí thay vì giấy thấm dầu chồng khít để hơi nước thoát hết, giữ độ giòn lâu gấp 3 lần.'),
(258,7,'Trình bày bắt mắt kèm rau thơm & thưởng thức nóng','Xếp thành phẩm vàng giòn ra đĩa lớn có bày sẵn 150g rau sống và điểm xuyết 30g hành lá tươi xanh hài hòa màu sắc. Dọn kèm chén nước chấm sánh đậm ngay chính giữa mâm ăn cho 4 người thưởng thức khi vỏ ngoài còn nóng giòn rụm.',4,'Cắt miếng hoặc dọn ăn ngay trong vòng 10 phút sau khi rời bếp để cảm nhận trọn vẹn sự đối lập giòn ngoài - mềm ngọt bên trong.'),
(259,1,'Sơ chế tươi sạch & ngâm giòn rau củ thảo mộc','Nhặt rửa kỹ rau củ ăn kèm cùng 25g rau răm và 40g đậu phộng qua nước muối loãng rồi tráng nước đun sôi để nguội. Với các loại củ quả bào sợi hoặc thái lát mỏng, ngâm vào âu nước đá lạnh pha chút chanh đường trong 10 phút rồi vắt ráo để giữ độ trắng giòn sần sật.',6,'Rau củ làm gỏi và món cuốn phải quay rổ hoặc thấm thật ráo nước để khi trộn nước mắm không bị loãng nhạt.'),
(259,2,'Làm chín tới phần nhân đạm giữ trọn độ ngọt mọng','Xử lý phần nguyên liệu chính (400g bò tơ và 120g hành tây): luộc hấp cùng lát gừng sả đập dập hoặc xào lửa lớn vừa chín tới, sau đó làm nguội nhanh rồi thái lát mỏng / xé sợi đều đặn. Nếu món có pha bột bánh gạo/bột năng, khuấy tan bột với nước đúng tỷ lệ và để bột nghỉ 15 phút cho nở mịn.',8,'Ngâm tôm hoặc thịt luộc qua bát nước sôi để nguội có vài viên đá giúp màu sắc tươi hồng và thớ thịt giòn ngọt không bị khô.'),
(259,3,'Rang vàng đậu phộng mè thơm & phi hành tỏi giòn','Bắc chảo nhỏ lên lửa nhỏ, rang chín vàng thơm đậu phộng/mè hoặc làm mỡ hành xanh mướt và phi vàng giòn 40g sả. Vớt hành tỏi phi ra đĩa riêng để nguội giòn tan, giữ lại phần dầu thơm óng ánh để phết bánh hoặc rưới bóng mặt món ăn.',4,'Tắt bếp ngay khi hành phi chuyển vàng sáng vì nhiệt dư trong dầu nóng sẽ tiếp tục làm hành sẫm màu thêm một nấc hoàn hảo.'),
(259,4,'Pha nước mắm chấm / sốt trộn tỷ lệ vàng chua ngọt','Hòa tan hoàn toàn đường cùng 35ml chanh, 80ml mắm nêm và 20g đường và nước ấm trong chén sâu lòng, khuấy đến khi hơi sánh nhẹ mới cho tỏi ớt băm nhuyễn và nước cốt chanh/tắc vào sau cùng. Công thức pha này giúp tỏi ớt nổi đều đẹp mắt trên bề mặt bát nước chấm chuẩn vị Bò tái chanh kiểu Cầu Mống chấm mắm nêm Quảng Nam.',4,'Băm tỏi ớt thật ráo trên thớt khô và cho vào sau khi đường mắm đã nguội thì tỏi ớt sẽ nổi bồng bềnh 100% không bị chìm đáy.'),
(259,5,'Phối trộn thấm vị / tráng hấp & cuốn đều tay','Tiến hành tráng hấp bánh mỏng mượt hoặc trải bánh cuốn gọn gàng 400g bò tơ và 120g hành tây cùng rau củ ăn kèm; nếu là món gỏi trộn thì rưới từ từ 2/3 lượng sốt chua ngọt vào bóp nhẹ tay cho thấm đều trong 3 phút. Giữ lực tay nhẹ nhàng để rau củ không bị dập nát mà vẫn ngấm trọn vị mặn chua ngọt hài hòa.',5,'Chia nước sốt gỏi làm 2 lần trộn và chắt bỏ phần nước tiết ra ở lần đầu giúp đĩa gỏi khô ráo, đậm đà như ngoài hàng.'),
(259,6,'Bày biện ngũ sắc hài hòa & rắc topping giòn bùi','Xếp món Bò tái chanh kiểu Cầu Mống chấm mắm nêm Quảng Nam ngay ngắn ra đĩa sứ trắng rộng, rải đều phần nhân tôm thịt sắc nét lên trên và rắc phủ 25g rau răm và 40g đậu phộng thơm giòn. Dọn kèm chén nước chấm đậm đà cho 4 người thưởng thức ngay khi rau bánh còn tươi giòn mướt mịn.',3,'Chỉ rắc đậu phộng rang và hành phi ngay trước lúc mang ra bàn ăn để giữ nguyên độ giòn tan bùi béo.'),
(260,1,'Sơ chế tươi sạch & ngâm giòn rau củ thảo mộc','Nhặt rửa kỹ rau củ ăn kèm cùng 60g đậu phộng và 30g rau răm qua nước muối loãng rồi tráng nước đun sôi để nguội. Với các loại củ quả bào sợi hoặc thái lát mỏng, ngâm vào âu nước đá lạnh pha chút chanh đường trong 10 phút rồi vắt ráo để giữ độ trắng giòn sần sật.',9,'Rau củ làm gỏi và món cuốn phải quay rổ hoặc thấm thật ráo nước để khi trộn nước mắm không bị loãng nhạt.'),
(260,2,'Làm chín tới phần nhân đạm giữ trọn độ ngọt mọng','Xử lý phần nguyên liệu chính (450g mít non và 180g tôm sú): luộc hấp cùng lát gừng sả đập dập hoặc xào lửa lớn vừa chín tới, sau đó làm nguội nhanh rồi thái lát mỏng / xé sợi đều đặn. Nếu món có pha bột bánh gạo/bột năng, khuấy tan bột với nước đúng tỷ lệ và để bột nghỉ 15 phút cho nở mịn.',12,'Ngâm tôm hoặc thịt luộc qua bát nước sôi để nguội có vài viên đá giúp màu sắc tươi hồng và thớ thịt giòn ngọt không bị khô.'),
(260,3,'Rang vàng đậu phộng mè thơm & phi hành tỏi giòn','Bắc chảo nhỏ lên lửa nhỏ, rang chín vàng thơm đậu phộng/mè hoặc làm mỡ hành xanh mướt và phi vàng giòn 30g hành tím. Vớt hành tỏi phi ra đĩa riêng để nguội giòn tan, giữ lại phần dầu thơm óng ánh để phết bánh hoặc rưới bóng mặt món ăn.',6,'Tắt bếp ngay khi hành phi chuyển vàng sáng vì nhiệt dư trong dầu nóng sẽ tiếp tục làm hành sẫm màu thêm một nấc hoàn hảo.'),
(260,4,'Pha nước mắm chấm / sốt trộn tỷ lệ vàng chua ngọt','Hòa tan hoàn toàn đường cùng 25ml nước mắm và nước ấm trong chén sâu lòng, khuấy đến khi hơi sánh nhẹ mới cho tỏi ớt băm nhuyễn và nước cốt chanh/tắc vào sau cùng. Công thức pha này giúp tỏi ớt nổi đều đẹp mắt trên bề mặt bát nước chấm chuẩn vị Mít non trộn tôm thịt đậu phộng xứ Quảng.',6,'Băm tỏi ớt thật ráo trên thớt khô và cho vào sau khi đường mắm đã nguội thì tỏi ớt sẽ nổi bồng bềnh 100% không bị chìm đáy.'),
(260,5,'Phối trộn thấm vị / tráng hấp & cuốn đều tay','Tiến hành tráng hấp bánh mỏng mượt hoặc trải bánh cuốn gọn gàng 450g mít non và 180g tôm sú cùng rau củ ăn kèm; nếu là món gỏi trộn thì rưới từ từ 2/3 lượng sốt chua ngọt vào bóp nhẹ tay cho thấm đều trong 3 phút. Giữ lực tay nhẹ nhàng để rau củ không bị dập nát mà vẫn ngấm trọn vị mặn chua ngọt hài hòa.',8,'Chia nước sốt gỏi làm 2 lần trộn và chắt bỏ phần nước tiết ra ở lần đầu giúp đĩa gỏi khô ráo, đậm đà như ngoài hàng.'),
(260,6,'Bày biện ngũ sắc hài hòa & rắc topping giòn bùi','Xếp món Mít non trộn tôm thịt đậu phộng xứ Quảng ngay ngắn ra đĩa sứ trắng rộng, rải đều phần nhân tôm thịt sắc nét lên trên và rắc phủ 60g đậu phộng và 30g rau răm thơm giòn. Dọn kèm chén nước chấm đậm đà cho 4 người thưởng thức ngay khi rau bánh còn tươi giòn mướt mịn.',4,'Chỉ rắc đậu phộng rang và hành phi ngay trước lúc mang ra bàn ăn để giữ nguyên độ giòn tan bùi béo.'),
(261,1,'Sơ chế sạch & chuẩn bị nguyên liệu thuần chay','Rửa sạch toàn bộ nguyên liệu dưới vòi nước mát, để ráo tự nhiên trên rổ thưa gồm 400g mít non và 250g đậu hũ cùng các nguyên liệu phối kèm. Cắt thái đồng đều kích thước khoảng 3–4cm vừa gắp để khi chế biến chín cùng lúc và thấm đều gia vị thực vật.',8,'Thấm khô bề mặt đậu hũ và nấm bằng khăn giấy bếp trước khi chế biến giúp nguyên liệu săn chắc, không bị bắn dầu hay ra nước.');
INSERT INTO `recipe_steps` (`recipe_id`,`step_order`,`title`,`instruction`,`duration_mins`,`tip_note`) VALUES
(261,2,'Xử lý độ giòn ngọt của nấm & rau củ','Đối với nhóm nấm và rau củ (400g mít non và 250g đậu hũ), ngâm nhanh qua nước muối loãng 3 phút rồi vắt nhẹ hoặc chần sơ 45 giây trong nước sôi, vớt ngay ra tô nước mát. Thao tác này giúp giữ trọn sắc màu tươi sáng tự nhiên, loại bỏ mùi ngái và tạo độ giòn ngọt thanh khiết cho món Mít non kho đậu hũ sả ớt chay xứ Quảng.',6,'Không ngâm nấm quá lâu trong nước lạnh vì nấm sẽ hút nước mạnh làm nhạt vị ngọt umami tự nhiên.'),
(261,3,'Pha chén sốt gia vị chay chuẩn định lượng','Chuẩn bị tô nhỏ, đong chính xác 40ml nước tương, 20ml dầu hào chay và 10g ớt khuấy đều cùng 30ml nước ấm hoặc nước ngâm nấm hương cho tan hoàn toàn đường và hạt nêm nấm. Nếm thử thấy vị mặn ngọt hài hòa, thanh dịu đúng tinh thần ẩm thực chay cho khẩu phần 4 người.',5,'Pha sẵn chén sốt trước khi bật bếp giúp kiểm soát chính xác định lượng từng gam và không bị cháy khét gia vị trên chảo nóng.'),
(261,4,'Phi thơm hành boaro & tạo nền hương thảo mộc','Làm nóng nồi hoặc chảo đáy dày trên lửa vừa, cho 200ml nước dừa tươi và 20ml dầu ăn vào láng đều mặt chảo rồi trút 40g sả vào phi thơm. Đảo nhẹ tay khoảng 1–2 phút đến khi hành boaro chuyển sắc vàng óng và dậy mùi thơm dịu thì hạ lửa vừa.',6,'Hành boaro cháy nhanh hơn hành tím nên chỉ phi trên lửa vừa đến khi vừa chớm vàng thơm là cho nguyên liệu chính vào ngay.'),
(261,5,'Chế biến săn thấm nguyên liệu chính thuần thực vật','Cho 400g mít non và 250g đậu hũ vào đảo đều hoặc áp chảo nhẹ hai mặt trên lửa vừa đến khi bề mặt săn vàng, sau đó rưới 2/3 chén sốt gia vị chay đã pha vào. Đảo nhẹ tay để sốt bám đều quanh từng thớ đậu và nấm mà không làm vỡ nát cấu trúc nguyên liệu.',11,'Dùng sạn gỗ đảo nhẹ từ dưới đáy chảo hất lên để miếng đậu hũ và nấm giữ nguyên hình khối vuông vắn đẹp mắt.'),
(261,6,'Phối hợp rau củ & cân chỉnh độ sánh thanh đạm','Tiếp tục cho các nguyên liệu phối kèm cùng phần sốt còn lại vào nồi, điều chỉnh lửa vừa nấu thêm cho nguyên liệu chín mềm tới nhưng vẫn giữ độ giòn ngọt. Quan sát thấy nước sốt chuyển màu nâu hổ phách sóng sánh hoặc nước dùng trong thanh, hương thơm quyện đều khắp gian bếp.',9,'Chỉ nấu rau củ xanh vừa chín tới để bảo toàn tối đa lượng chất xơ và vitamin tự nhiên trong khẩu phần chay.'),
(261,7,'Hoàn thiện hương thơm & trình bày món chay thanh tịnh','Tắt bếp ngay khi món ăn đạt độ chín chuẩn, rắc đều hành boaro lá xanh và tiêu xay lên bề mặt để dậy mùi thơm tươi mới. Múc món Mít non kho đậu hũ sả ớt chay xứ Quảng ra đĩa sứ hoặc tô sâu lòng, thưởng thức nóng cùng cơm trắng hoặc bún tươi cho trọn vẹn 4 khẩu phần.',5,'Rắc rau thơm và tiêu ngay lúc vừa tắt bếp giúp tinh dầu tỏa hương thơm ngát mà lá rau không bị thâm xỉn màu.'),
(262,1,'Sơ chế sạch & chuẩn bị nguyên liệu thuần chay','Rửa sạch toàn bộ nguyên liệu dưới vòi nước mát, để ráo tự nhiên trên rổ thưa gồm 500g mì quảng và 250g nấm đùi gà cùng 50g tàu hũ ky và 200g củ sắn. Cắt thái đồng đều kích thước khoảng 3–4cm vừa gắp để khi chế biến chín cùng lúc và thấm đều gia vị thực vật.',8,'Thấm khô bề mặt đậu hũ và nấm bằng khăn giấy bếp trước khi chế biến giúp nguyên liệu săn chắc, không bị bắn dầu hay ra nước.'),
(262,2,'Xử lý độ giòn ngọt của nấm & rau củ','Đối với nhóm nấm và rau củ (50g tàu hũ ky và 200g củ sắn), ngâm nhanh qua nước muối loãng 3 phút rồi vắt nhẹ hoặc chần sơ 45 giây trong nước sôi, vớt ngay ra tô nước mát. Thao tác này giúp giữ trọn sắc màu tươi sáng tự nhiên, loại bỏ mùi ngái và tạo độ giòn ngọt thanh khiết cho món Mì Quảng chay nấm đùi gà đậu phộng Hội An.',7,'Không ngâm nấm quá lâu trong nước lạnh vì nấm sẽ hút nước mạnh làm nhạt vị ngọt umami tự nhiên.'),
(262,3,'Pha chén sốt gia vị chay chuẩn định lượng','Chuẩn bị tô nhỏ, đong chính xác 30ml nước mắm chay khuấy đều cùng 30ml nước ấm hoặc nước ngâm nấm hương cho tan hoàn toàn đường và hạt nêm nấm. Nếm thử thấy vị mặn ngọt hài hòa, thanh dịu đúng tinh thần ẩm thực chay cho khẩu phần 4 người.',6,'Pha sẵn chén sốt trước khi bật bếp giúp kiểm soát chính xác định lượng từng gam và không bị cháy khét gia vị trên chảo nóng.'),
(262,4,'Phi thơm hành boaro & tạo nền hương thảo mộc','Làm nóng nồi hoặc chảo đáy dày trên lửa vừa, cho 15ml dầu thực vật vào láng đều mặt chảo rồi trút 20g hành boaro thái lát mỏng vào phi thơm. Đảo nhẹ tay khoảng 1–2 phút đến khi hành boaro chuyển sắc vàng óng và dậy mùi thơm dịu thì hạ lửa vừa.',7,'Hành boaro cháy nhanh hơn hành tím nên chỉ phi trên lửa vừa đến khi vừa chớm vàng thơm là cho nguyên liệu chính vào ngay.'),
(262,5,'Chế biến săn thấm nguyên liệu chính thuần thực vật','Cho 500g mì quảng và 250g nấm đùi gà vào đảo đều hoặc áp chảo nhẹ hai mặt trên lửa vừa đến khi bề mặt săn vàng, sau đó rưới 2/3 chén sốt gia vị chay đã pha vào. Đảo nhẹ tay để sốt bám đều quanh từng thớ đậu và nấm mà không làm vỡ nát cấu trúc nguyên liệu.',11,'Dùng sạn gỗ đảo nhẹ từ dưới đáy chảo hất lên để miếng đậu hũ và nấm giữ nguyên hình khối vuông vắn đẹp mắt.'),
(262,6,'Phối hợp rau củ & cân chỉnh độ sánh thanh đạm','Tiếp tục cho 50g tàu hũ ky và 200g củ sắn cùng phần sốt còn lại vào nồi, điều chỉnh lửa vừa nấu thêm cho nguyên liệu chín mềm tới nhưng vẫn giữ độ giòn ngọt. Quan sát thấy nước sốt chuyển màu nâu hổ phách sóng sánh hoặc nước dùng trong thanh, hương thơm quyện đều khắp gian bếp.',10,'Chỉ nấu rau củ xanh vừa chín tới để bảo toàn tối đa lượng chất xơ và vitamin tự nhiên trong khẩu phần chay.'),
(262,7,'Hoàn thiện hương thơm & trình bày món chay thanh tịnh','Tắt bếp ngay khi món ăn đạt độ chín chuẩn, rắc đều 50g đậu phộng lên bề mặt để dậy mùi thơm tươi mới. Múc món Mì Quảng chay nấm đùi gà đậu phộng Hội An ra đĩa sứ hoặc tô sâu lòng, thưởng thức nóng cùng cơm trắng hoặc bún tươi cho trọn vẹn 4 khẩu phần.',6,'Rắc rau thơm và tiêu ngay lúc vừa tắt bếp giúp tinh dầu tỏa hương thơm ngát mà lá rau không bị thâm xỉn màu.'),
(263,1,'Tuyển chọn, ngâm nở & sơ chế sạch nguyên liệu chè bánh','Đãi rửa sạch nhóm hạt, củ hoặc bột (15g bột rau câu và 150g củ sắn), ngâm nước ấm theo đúng đặc tính từng loại để hạt nở mềm đồng đều và loại bỏ nhựa chát. Rửa sạch nhóm tạo hương tự nhiên gồm lá dứa, gừng tươi để ráo nước.',10,'Thêm một nhúm muối nhỏ vào nước ngâm khoai và đậu giúp nguyên liệu giữ màu tươi sáng và khi nấu chín bùi hơn.'),
(263,2,'Ninh mềm bùi nguyên liệu chính giữ nguyên hạt/khối','Cho phần nguyên liệu nền trong 15g bột rau câu và 150g củ sắn vào nồi đáy dày cùng lượng nước vừa đủ, đun sôi rồi hạ lửa nhỏ ninh êm đến khi chín mềm bùi nhưng không bị vỡ nát đục nước. Nếu có trân châu, bột lọc hoặc hạt lựu, luộc riêng trong nồi nước sôi đến khi nổi trong veo rồi vớt ngâm ngay vào bát nước mát.',14,'Tuyệt đối không cho đường ngay từ đầu khi đậu và khoai chưa chín mềm vì đường sẽ làm săn vỏ hạt khiến nấu mãi vẫn sượng.'),
(263,3,'Nấu nước đường phèn / mật mía thanh trong dậy hương','Kết hợp chính xác định lượng 130g đường vào nồi cùng bó lá dứa hoặc gừng thái chỉ, khuấy nhẹ trên lửa nhỏ cho tan trong vắt. Đun liu riu thêm 5–7 phút để vị ngọt thấm sâu vào từng viên nguyên liệu và tỏa hương thơm dịu tao nhã.',9,'Dùng đường phèn hoặc mật mía đun lửa nhỏ hớt bọt kỹ giúp hậu vị chè ngọt thanh mát họng, không bị khé cổ.'),
(263,4,'Thắng nước cốt dừa béo mịn / chuẩn bị lớp kem phủ','Cho 160ml nước cốt dừa và 250g đá viên vào nồi nhỏ cùng 2g muối tinh và 5g bột năng/bột bắp hòa loãng, khuấy đều tay trên lửa nhỏ nhất đến khi vừa chớm sôi lăn tăn sánh mượt. Tắt bếp ngay để nước cốt dừa giữ màu trắng ngần béo ngậy mà không bị tách lớp dầu.',7,'Một chút xíu muối tinh trong nồi nước cốt dừa sẽ làm bật hẳn độ béo thơm tự nhiên và cân bằng vị ngọt của món tráng miệng.'),
(263,5,'Phối hợp độ sánh mượt & cân bằng hương vị tổng thể','Hợp nhất các thành phần của món Chè xoa xoa hạt lựu cốt dừa Đà Nẵng, từ từ rưới nước bột năng hòa loãng (nếu là chè sánh) đồng thời khuấy nhẹ một chiều trên lửa nhỏ cho hỗn hợp bóng mượt như nhung. Kiểm tra độ mềm dẻo hài hòa và tắt bếp để ủ hương thảo mộc lan tỏa đều.',6,'Rót nước bột tạo sánh thành dòng mảnh vừa rót vừa khuấy đều tay giúp chè trong mượt, hoàn toàn không bị ốc trâu vón cục.'),
(263,6,'Múc ra chén sứ, điểm topping & thưởng thức ấm/lạnh','Múc chè hoặc bày bánh ra 4 chén nhỏ xinh, chan lớp nước cốt dừa trắng mịn lên mặt và rắc nhẹ mè rang, đậu phộng hoặc dừa non bào sợi. Thưởng thức ấm nóng dịu dàng hoặc thêm đá bào mát lạnh tùy sở thích đều trọn vị ngon truyền thống.',4,'Để chè nguội bớt về khoảng 45°C hoặc ướp mát 30 phút trong ngăn mát tủ lạnh giúp các tầng hương vị kết tinh đậm đà hơn.'),
(264,1,'Tuyển chọn & sơ chế tươi sạch nguyên liệu pha chế','Rửa sạch kỹ các nguyên liệu tươi gồm 120g sả và 35g gừng và 120g sả, 35g gừng và 25g lá dứa, để ráo nước hoàn toàn trên khay sạch. Cắt lát, đập dập hoặc đong chuẩn xác từng gam/ml nguyên liệu cho khẩu phần 4 ly để hương vị đồng nhất tuyệt đối.',7,'Loại bỏ kỹ hạt chanh, tắc trước khi vắt hoặc nấu giúp thức uống giữ hậu vị thanh ngọt mà không hề bị đắng vỏ.'),
(264,2,'Ủ chiết xuất nền trà, cà phê hoặc nấu cốt thảo mộc','Đun nước đạt nhiệt độ chuẩn 90–95°C (không dùng nước sôi sùng sục làm cháy hương), tiến hành ủ chiết xuất hoặc nấu nhỏ lửa 120g sả và 35g gừng trong thời gian quy định. Lọc qua rây mịn hoặc túi vải sạch để thu được phần nước cốt trong trẻo, đậm hương tự nhiên không gợn cặn.',9,'Ủ trà/cà phê đúng nhiệt độ 92°C và đậy nắp kín giúp thu trọn tinh dầu thơm quyến rũ mà không chiết xuất vị chát gắt.'),
(264,3,'Xử lý lớp kem bông mịn / hỗn hợp sữa & trái cây','Đánh bông mượt hoặc khuấy hòa quyện phần nguyên liệu bổ trợ (1000ml nước lọc và 250g đá viên) cùng 140g đường phèn và 45ml chanh đến khi sánh mịn đồng nhất. Kiểm soát tốc độ khuấy/đánh đều tay để tạo kết cấu bồng bềnh mượt mà hoặc hòa tan hoàn toàn đường phèn mật ong.',7,'Nếu đánh kem trứng, nghiêng nhẹ âu 45 độ và đánh một chiều tốc độ cao cho tới khi nhấc que tạo chóp mềm bóng mượt không tanh.'),
(264,4,'Cân chỉnh định lượng độ ngọt & tầng hương tươi mát','Phối trộn phần nước cốt nền cùng hỗn hợp tạo vị theo đúng tỷ lệ vàng của món Nước thảo mộc sả chanh gừng kiểu Hội An, khuấy nhẹ để các tầng hương hòa quyện. Nếu có nước cốt chanh hoặc mật ong rừng, cho vào khi nền nước đã hạ xuống dưới 55°C để bảo toàn trọn vẹn vitamin và hương thơm.',5,'Nếm thử trước khi thêm đá viên sao cho vị đậm hơn khoảng 15% để khi đá tan nhẹ là vừa vặn hoàn hảo.'),
(264,5,'Phối tầng thẩm mỹ ra ly thủy tinh nóng hoặc đá mát','Tráng ấm ly gốm (nếu dùng nóng) hoặc cho lượng đá viên tinh khiết vừa đủ vào ly thủy tinh cao, rót từ từ cốt thức uống vào 2/3 ly. Nhẹ nhàng rót lớp kem/sữa hoặc xếp lát trái cây tươi áp sát thành ly tạo hiệu ứng phân tầng đẹp mắt như quán chuyên nghiệp.',4,'Rót lớp kem hoặc sữa nhẹ nhàng qua lưng muỗng inox giúp hai tầng màu tách bạch sắc nét cực kỳ cuốn hút.'),
(264,6,'Điểm xuyết lá thơm trang trí & thưởng thức ngay','Trang trí trên mặt ly bằng lát nguyên liệu tươi, nhánh bạc hà/lá dứa hoặc rắc nhẹ bột cacao/hạt chia cho món Nước thảo mộc sả chanh gừng kiểu Hội An thêm phần sinh động. Phục vụ ngay khi vừa pha chế xong cho 4 người để tận hưởng trọn vẹn hương thơm tươi mới sảng khoái nhất.',3,'Vỗ nhẹ lá bạc hà trong lòng bàn tay trước khi đặt lên miệng ly sẽ đánh thức tinh dầu the mát lan tỏa ngay khi nâng ly.');
INSERT INTO `recipe_steps` (`recipe_id`,`step_order`,`title`,`instruction`,`duration_mins`,`tip_note`) VALUES
(265,1,'Sơ chế sạch & cắt thái nguyên liệu nấu canh','Rửa sạch 300g chả cá biển và 250g sứa biển tươi, khử mùi tanh bằng chút muối hạt và gừng đập dập rồi rửa lại thật ráo, cắt miếng vừa ăn dày khoảng 2.5–3cm. Đồng thời gọt rửa sạch 150g dứa, cắt khúc hoặc bổ múi cau đồng đều để khi nấu chín đều không bị nát.',11,'Phân loại riêng nhóm củ cứng nấu lâu và nhóm rau lá mềm nhanh chín để cho vào nồi theo đúng thứ tự chuẩn đầu bếp.'),
(265,2,'Ướp thấm gia vị nền cho nguyên liệu đạm','Cho phần đạm chính trong 300g chả cá biển và 250g sứa biển tươi vào tô, ướp nhẹ với một nửa lượng hành tím và tỏi băm nhỏ và 25ml nước mắm trong khoảng 10 phút. Đảo nhẹ tay cho gia vị áo đều bề mặt giúp miếng thịt, cá săn chắc và đậm đà từ bên trong khi thả vào nước canh.',10,'Không ướp quá mặn ở bước này để giữ vị thanh mát tự nhiên của nước canh sau khi hoàn tất.'),
(265,3,'Phi thơm hành tỏi & xào săn khóa ngọt nguyên liệu','Đặt nồi canh lên bếp ở lửa vừa, làm nóng 15ml dầu ăn rồi phi thơm phần hành tím và tỏi băm nhỏ còn lại đến khi dậy mùi vàng óng. Trút nguyên liệu chính đã ướp vào đảo săn 2–3 phút cho bề mặt se lại, khóa trọn nước ngọt tự nhiên bên trong thớ thịt.',8,'Xào săn nguyên liệu đạm với hành tỏi phi trước khi đổ nước sôi giúp nước canh thơm ngọt đậm đà mà không hề tanh.'),
(265,4,'Đun sôi nước canh & hớt bọt giữ độ trong veo','Chế khoảng 1.1–1.3 lít nước (kết hợp lượng nước vừa ngập mặt nguyên liệu) vào nồi, bật lửa lớn đun đến khi sôi bùng rồi hạ ngay về lửa vừa. Dùng muôi hớt sạch lớp bọt đầu nổi lên trên mặt nước để nồi canh Bún chả cá sứa Nha Trang nước dùng trong ngọt đạt độ trong thanh đẹp mắt.',13,'Sử dụng nước ấm hoặc nước sôi khi chế vào cá tươi sẽ giúp cá không bao giờ bị tanh nồng dù để nguội.'),
(265,5,'Thả rau củ theo độ chín & cân chỉnh định lượng vị','Lần lượt cho 150g dứa vào nồi canh đang sôi vừa (nhóm củ quả lâu chín cho trước 5–7 phút, nhóm rau mềm cho sau 1–2 phút). Nêm phần 25ml nước mắm còn lại, khuấy nhẹ và nếm thử thấy vị chua thanh hoặc ngọt dịu cân bằng đúng khẩu phần 4 người.',12,'Không đậy kín nắp vung sau khi đã thả các loại rau xanh vào nồi để giữ màu xanh ngọc tươi tắn hấp dẫn.'),
(265,6,'Điểm hương rau thơm & múc canh dọn nóng','Khi toàn bộ nguyên liệu vừa chín tới mềm ngọt, rắc ngay 35g hành lá vào nồi rồi tắt bếp liền tay để giữ trọn tinh dầu thơm mát. Múc canh nóng hổi ra tô lớn, rắc thêm chút tiêu xay hoặc tỏi phi vàng và dùng ngay với cơm nóng.',6,'Các loại rau thơm như thì là, ngò gai, rau om hay lá lốt chỉ nên thả ngay khoảnh khắc tắt bếp để hương thơm bùng nổ nhất.'),
(266,1,'Sơ chế sạch & thấm thật khô bề mặt nguyên liệu','Rửa sạch 250g bột gạo và 200g tôm sú cùng chút muối loãng để khử mùi tự nhiên, sau đó dùng khăn giấy bếp thấm thật khô ráo hoàn toàn bề mặt. Khứa nhẹ các đường chéo hoặc cắt miếng vừa ăn dày 2–3cm để nhiệt và gia vị thấm sâu đều khắp bên trong.',8,'Bề mặt nguyên liệu càng khô ráo thì khi chiên không bị văng dầu và khi nướng sẽ lên màu vàng ruộm giòn rụm cực đẹp.'),
(266,2,'Chuẩn bị hỗn hợp sốt ướp / bột áo chuẩn tỷ lệ','Phối trộn hành tím và tỏi băm nhỏ băm thật nhuyễn (hoặc vắt lấy nước cốt thơm) cùng 40ml nước mắm trong tô lớn cho quyện sánh đồng nhất. Nếu món có lớp vỏ bột hoặc bánh cuốn từ 250g bột gạo và 200g tôm sú, trộn đều hỗn hợp theo đúng định lượng để đạt độ giòn xốp mỏng nhẹ chuẩn vị.',7,'Vắt lấy nước cốt hành tỏi sả khi ướp đồ nướng giúp hương thơm thấm sâu mà không bị cháy đen phần xác băm trên lửa cao.'),
(266,3,'Ướp thấm thớ thịt / tạo hình cuốn khéo léo','Áo đều hỗn hợp gia vị hoặc lớp bột/vỏ cuốn quanh 250g bột gạo và 200g tôm sú, massage nhẹ nhàng rồi để nghỉ 15–20 phút cho gia vị thẩm thấu trọn vẹn. Trường hợp cuốn chả/nem hoặc đổ khuôn bánh, thao tác đều tay vừa chặt để nhân kết dính nhưng không bị bục rách khi gặp nhiệt.',9,'Để nguyên liệu nghỉ đủ thời gian trước khi chiên nướng giúp lớp áo bột bám chắc và phần nhân bên trong mọng ngọt.'),
(266,4,'Pha nước chấm cân vị & sơ chế rau đồ chua ăn kèm','Nhặt rửa sạch 120g xoài xanh ngâm nước mát cho giòn tươi, bào sợi hoặc thái lát gọn gàng bày sẵn bên cạnh. Pha chén nước chấm chua ngọt hoặc muối ớt chanh sả sánh thơm theo khẩu vị vùng miền của món Bánh căn hải sản tôm mực Phan Thiết xíu mại để cân bằng độ béo giòn.',6,'Luôn chuẩn bị xong rau sống và bát nước chấm trước khi chiên/nướng mẻ cuối để món ăn vừa ra lò là thưởng thức nóng giòn ngay.'),
(266,5,'Làm nóng dầu / lò nướng chuẩn nhiệt & làm chín đều lần 1','Làm nóng chảo dầu hoặc vỉ nướng/nồi chiên ở mức nhiệt vừa khoảng 165–175°C, xếp 250g bột gạo và 200g tôm sú vào với khoảng cách thoáng đều nhau. Chiên hoặc nướng trở mặt nhịp nhàng trên lửa vừa để nhiệt dẫn sâu làm chín mềm ngọt hoàn toàn phần nhân bên trong.',10,'Kiểm tra nhiệt dầu bằng đầu đũa tre thấy sủi tăm nhỏ đều là đạt chuẩn 170°C, giúp vỏ không cháy sớm khi bên trong còn sống.'),
(266,6,'Tăng nhiệt khóa giòn rụm vàng ươm bề mặt lần 2','Ở 2–3 phút cuối, tăng lên lửa vừa lớn (khoảng 190°C) hoặc phết thêm lớp dầu điều/mật ong mỏng để vỏ ngoài của Bánh căn hải sản tôm mực Phan Thiết xíu mại chuyển sắc vàng óng ánh và nổ giòn rụm. Lắng nghe tiếng xèo giòn rộn rã và hương thơm phức lan tỏa khắp bếp thì gắp ra vỉ thưa cho ráo dầu thừa.',6,'Đặt đồ chiên nướng lên giá inox thoáng khí thay vì giấy thấm dầu chồng khít để hơi nước thoát hết, giữ độ giòn lâu gấp 3 lần.'),
(266,7,'Trình bày bắt mắt kèm rau thơm & thưởng thức nóng','Xếp thành phẩm vàng giòn ra đĩa lớn có bày sẵn 120g xoài xanh và điểm xuyết 40g hành lá tươi xanh hài hòa màu sắc. Dọn kèm chén nước chấm sánh đậm ngay chính giữa mâm ăn cho 4 người thưởng thức khi vỏ ngoài còn nóng giòn rụm.',4,'Cắt miếng hoặc dọn ăn ngay trong vòng 10 phút sau khi rời bếp để cảm nhận trọn vẹn sự đối lập giòn ngoài - mềm ngọt bên trong.'),
(267,1,'Sơ chế tươi sạch & ngâm giòn rau củ thảo mộc','Nhặt rửa kỹ 150g rau sống cùng 50g rau hẹ và 20g mè trắng qua nước muối loãng rồi tráng nước đun sôi để nguội. Với các loại củ quả bào sợi hoặc thái lát mỏng, ngâm vào âu nước đá lạnh pha chút chanh đường trong 10 phút rồi vắt ráo để giữ độ trắng giòn sần sật.',10,'Rau củ làm gỏi và món cuốn phải quay rổ hoặc thấm thật ráo nước để khi trộn nước mắm không bị loãng nhạt.'),
(267,2,'Làm chín tới phần nhân đạm giữ trọn độ ngọt mọng','Xử lý phần nguyên liệu chính (500g bánh hỏi và 450g thịt heo (nạc vai)): luộc hấp cùng lát gừng sả đập dập hoặc xào lửa lớn vừa chín tới, sau đó làm nguội nhanh rồi thái lát mỏng / xé sợi đều đặn. Nếu món có pha bột bánh gạo/bột năng, khuấy tan bột với nước đúng tỷ lệ và để bột nghỉ 15 phút cho nở mịn.',12,'Ngâm tôm hoặc thịt luộc qua bát nước sôi để nguội có vài viên đá giúp màu sắc tươi hồng và thớ thịt giòn ngọt không bị khô.'),
(267,3,'Rang vàng đậu phộng mè thơm & phi hành tỏi giòn','Bắc chảo nhỏ lên lửa nhỏ, rang chín vàng thơm đậu phộng/mè hoặc làm mỡ hành xanh mướt và phi vàng giòn 35g sả. Vớt hành tỏi phi ra đĩa riêng để nguội giòn tan, giữ lại phần dầu thơm óng ánh để phết bánh hoặc rưới bóng mặt món ăn.',7,'Tắt bếp ngay khi hành phi chuyển vàng sáng vì nhiệt dư trong dầu nóng sẽ tiếp tục làm hành sẫm màu thêm một nấc hoàn hảo.'),
(267,4,'Pha nước mắm chấm / sốt trộn tỷ lệ vàng chua ngọt','Hòa tan hoàn toàn đường cùng 40ml nước mắm và nước ấm trong chén sâu lòng, khuấy đến khi hơi sánh nhẹ mới cho tỏi ớt băm nhuyễn và nước cốt chanh/tắc vào sau cùng. Công thức pha này giúp tỏi ớt nổi đều đẹp mắt trên bề mặt bát nước chấm chuẩn vị Bánh hỏi thịt nướng mỡ hành Bình Định.',7,'Băm tỏi ớt thật ráo trên thớt khô và cho vào sau khi đường mắm đã nguội thì tỏi ớt sẽ nổi bồng bềnh 100% không bị chìm đáy.'),
(267,5,'Phối trộn thấm vị / tráng hấp & cuốn đều tay','Tiến hành tráng hấp bánh mỏng mượt hoặc trải bánh cuốn gọn gàng 500g bánh hỏi và 450g thịt heo (nạc vai) cùng 150g rau sống; nếu là món gỏi trộn thì rưới từ từ 2/3 lượng sốt chua ngọt vào bóp nhẹ tay cho thấm đều trong 3 phút. Giữ lực tay nhẹ nhàng để rau củ không bị dập nát mà vẫn ngấm trọn vị mặn chua ngọt hài hòa.',9,'Chia nước sốt gỏi làm 2 lần trộn và chắt bỏ phần nước tiết ra ở lần đầu giúp đĩa gỏi khô ráo, đậm đà như ngoài hàng.'),
(267,6,'Bày biện ngũ sắc hài hòa & rắc topping giòn bùi','Xếp món Bánh hỏi thịt nướng mỡ hành Bình Định ngay ngắn ra đĩa sứ trắng rộng, rải đều phần nhân tôm thịt sắc nét lên trên và rắc phủ 50g rau hẹ và 20g mè trắng thơm giòn. Dọn kèm chén nước chấm đậm đà cho 4 người thưởng thức ngay khi rau bánh còn tươi giòn mướt mịn.',5,'Chỉ rắc đậu phộng rang và hành phi ngay trước lúc mang ra bàn ăn để giữ nguyên độ giòn tan bùi béo.'),
(268,1,'Sơ chế sạch & thấm thật khô bề mặt nguyên liệu','Rửa sạch 350g tôm đất và 180g thịt ba chỉ cùng chút muối loãng để khử mùi tự nhiên, sau đó dùng khăn giấy bếp thấm thật khô ráo hoàn toàn bề mặt. Khứa nhẹ các đường chéo hoặc cắt miếng vừa ăn dày 2–3cm để nhiệt và gia vị thấm sâu đều khắp bên trong.',7,'Bề mặt nguyên liệu càng khô ráo thì khi chiên không bị văng dầu và khi nướng sẽ lên màu vàng ruộm giòn rụm cực đẹp.'),
(268,2,'Chuẩn bị hỗn hợp sốt ướp / bột áo chuẩn tỷ lệ','Phối trộn 40g hành tím băm thật nhuyễn (hoặc vắt lấy nước cốt thơm) cùng gia vị chuẩn định lượng trong tô lớn cho quyện sánh đồng nhất. Nếu món có lớp vỏ bột hoặc bánh cuốn từ 350g tôm đất và 180g thịt ba chỉ, trộn đều hỗn hợp theo đúng định lượng để đạt độ giòn xốp mỏng nhẹ chuẩn vị.',6,'Vắt lấy nước cốt hành tỏi sả khi ướp đồ nướng giúp hương thơm thấm sâu mà không bị cháy đen phần xác băm trên lửa cao.'),
(268,3,'Ướp thấm thớ thịt / tạo hình cuốn khéo léo','Áo đều hỗn hợp gia vị hoặc lớp bột/vỏ cuốn quanh 350g tôm đất và 180g thịt ba chỉ, massage nhẹ nhàng rồi để nghỉ 15–20 phút cho gia vị thẩm thấu trọn vẹn. Trường hợp cuốn chả/nem hoặc đổ khuôn bánh, thao tác đều tay vừa chặt để nhân kết dính nhưng không bị bục rách khi gặp nhiệt.',8,'Để nguyên liệu nghỉ đủ thời gian trước khi chiên nướng giúp lớp áo bột bám chắc và phần nhân bên trong mọng ngọt.'),
(268,4,'Pha nước chấm cân vị & sơ chế rau đồ chua ăn kèm','Nhặt rửa sạch 150g xà lách và 120g dưa leo ngâm nước mát cho giòn tươi, bào sợi hoặc thái lát gọn gàng bày sẵn bên cạnh. Pha chén nước chấm chua ngọt hoặc muối ớt chanh sả sánh thơm theo khẩu vị vùng miền của món Chả ram tôm đất Bình Định cuốn nhỏ giòn tan để cân bằng độ béo giòn.',5,'Luôn chuẩn bị xong rau sống và bát nước chấm trước khi chiên/nướng mẻ cuối để món ăn vừa ra lò là thưởng thức nóng giòn ngay.'),
(268,5,'Làm nóng dầu / lò nướng chuẩn nhiệt & làm chín đều lần 1','Làm nóng chảo dầu hoặc vỉ nướng/nồi chiên ở mức nhiệt vừa khoảng 165–175°C, xếp 350g tôm đất và 180g thịt ba chỉ vào với khoảng cách thoáng đều nhau. Chiên hoặc nướng trở mặt nhịp nhàng trên lửa vừa để nhiệt dẫn sâu làm chín mềm ngọt hoàn toàn phần nhân bên trong.',10,'Kiểm tra nhiệt dầu bằng đầu đũa tre thấy sủi tăm nhỏ đều là đạt chuẩn 170°C, giúp vỏ không cháy sớm khi bên trong còn sống.'),
(268,6,'Tăng nhiệt khóa giòn rụm vàng ươm bề mặt lần 2','Ở 2–3 phút cuối, tăng lên lửa vừa lớn (khoảng 190°C) hoặc phết thêm lớp dầu điều/mật ong mỏng để vỏ ngoài của Chả ram tôm đất Bình Định cuốn nhỏ giòn tan chuyển sắc vàng óng ánh và nổ giòn rụm. Lắng nghe tiếng xèo giòn rộn rã và hương thơm phức lan tỏa khắp bếp thì gắp ra vỉ thưa cho ráo dầu thừa.',5,'Đặt đồ chiên nướng lên giá inox thoáng khí thay vì giấy thấm dầu chồng khít để hơi nước thoát hết, giữ độ giòn lâu gấp 3 lần.');
INSERT INTO `recipe_steps` (`recipe_id`,`step_order`,`title`,`instruction`,`duration_mins`,`tip_note`) VALUES
(268,7,'Trình bày bắt mắt kèm rau thơm & thưởng thức nóng','Xếp thành phẩm vàng giòn ra đĩa lớn có bày sẵn 150g xà lách và 120g dưa leo và điểm xuyết 30g đậu phộng tươi xanh hài hòa màu sắc. Dọn kèm chén nước chấm sánh đậm ngay chính giữa mâm ăn cho 4 người thưởng thức khi vỏ ngoài còn nóng giòn rụm.',4,'Cắt miếng hoặc dọn ăn ngay trong vòng 10 phút sau khi rời bếp để cảm nhận trọn vẹn sự đối lập giòn ngoài - mềm ngọt bên trong.'),
(269,1,'Sơ chế sạch & cắt thái nguyên liệu đúng kích cỡ','Rửa sạch 600g cá ngừ đại dương và 220g dứa cùng 180g cà chua dưới vòi nước mát rồi để thật ráo trên rổ thưa. Dùng dao sắc cắt thái nguyên liệu thành từng khúc hoặc khối vuông đều đặn khoảng 3.5–4cm để khi kho hầm giữ nguyên hình dáng đẹp mắt mà không bị vụn nát.',7,'Cắt miếng thịt/cá dày dặn đồng đều giúp quá trình kho lâu trên lửa nhỏ thớ thịt mềm rục mà vẫn giữ trọn độ mọng ngọt bên trong.'),
(269,2,'Khử mùi tự nhiên & làm săn sạch bề mặt nguyên liệu','Chà nhẹ phần đạm chính trong 600g cá ngừ đại dương và 220g dứa với chút muối hạt, lát gừng đập dập hoặc chần sơ qua nước sôi 90 giây rồi rửa sạch lại bằng nước ấm, để ráo hoàn toàn. Công đoạn này loại bỏ triệt để tạp chất và mùi tanh hôi, giúp nước sốt món Cá ngừ đại dương kho thơm cà chua Phú Yên trong bóng thơm ngon.',6,'Sau khi chần hoặc rửa sạch, để nguyên liệu ráo nước ít nhất 5 phút trước khi ướp để gia vị rút sâu trực tiếp vào từng thớ thịt.'),
(269,3,'Pha hỗn hợp gia vị & ướp thấm chuẩn định lượng','Cho 600g cá ngừ đại dương và 220g dứa vào tô lớn, ướp cùng một nửa 25g hành tím và 15g tỏi băm nhỏ và định lượng chuẩn 35ml nước mắm, đảo nhẹ tay cho gia vị phủ kín đều các mặt. Bọc kín tô và để nguyên liệu nghỉ thấm vị tối thiểu 20 phút ở nhiệt độ phòng (hoặc ngăn mát tủ lạnh).',8,'Ướp đủ tối thiểu 20 phút trước khi bắc lên bếp là chìa khóa để tâm miếng thịt/cá đậm đà đồng nhất với lớp sốt bên ngoài.'),
(269,4,'Thắng nước màu cánh gián & phi dậy hương hành tỏi','Đặt nồi đáy dày lên bếp ở lửa vừa nhỏ, thắng nhẹ 15g đường với 15ml dầu ăn đến khi chuyển sắc nâu cánh gián óng ả thì cho ngay phần 25g hành tím và 15g tỏi còn lại vào phi thơm lừng. Hương caramel dịu ngọt quyện cùng tinh dầu hành tỏi sả tạo nền màu nâu hổ phách truyền thống đầy cuốn hút.',5,'Canh kỹ khoảnh khắc đường vừa chuyển màu cánh gián là hạ lửa nhỏ nhất ngay để nước màu bóng đẹp mà không bao giờ bị đắng.'),
(269,5,'Đảo săn hai mặt khóa ngọt nguyên liệu chính','Tăng lên lửa vừa lớn, gắp từng miếng trong 600g cá ngừ đại dương và 220g dứa vào nồi đảo đều hoặc trở nhẹ hai mặt trong 4–5 phút cho săn chắc và bám đều lớp màu nâu óng. Khi bề mặt nguyên liệu se vàng thơm phức mới trút phần nước ướp còn lại trong tô vào đun sôi nhẹ.',7,'Đối với cá kho, chỉ lật cá một lần lúc cá vừa săn mặt trên lửa vừa để khúc cá nguyên vẹn không bị tróc da hay vỡ nát.'),
(269,6,'Kho/om liu riu lửa nhỏ thấm đẫm cùng nước dừa/nước dùng','Chế 200ml nước dừa tươi xâm xắp mặt nguyên liệu (xếp thêm rau củ ăn kèm nếu có), đun sôi bùng một dạo hớt sạch bọt rồi hạ ngay về mức lửa nhỏ liu riu nhất. Kho êm đềm không đậy kín nắp để từng thớ nguyên liệu chín mềm thấm đẫm gia vị và nước sốt rút dần sóng sánh.',12,'Luôn dùng nước sôi hoặc nước dừa ấm khi châm thêm vào nồi kho đang nóng để thịt cá không bị sượng cứng trở lại.'),
(269,7,'Thu sánh nước sốt óng ả & trình bày thưởng thức nóng','Khi nước kho rút còn khoảng 1/3 sánh kẹo óng ánh áo đều quanh nguyên liệu và xiên đũa thấy mềm mọng vừa ý, rắc 25g hành lá lên mặt rồi tắt bếp. Múc món Cá ngừ đại dương kho thơm cà chua Phú Yên ra đĩa sâu lòng hoặc niêu đất giữ nhiệt, dọn ăn nóng cùng cơm trắng dẻo thơm cho 4 người.',5,'Giữ lại một lượng nước sốt sánh kẹo vừa đủ dưới đáy nồi để chan cơm hoặc chấm kèm rau luộc sẽ tròn vị đưa cơm gấp bội.'),
(270,1,'Vo đãi & ngâm nở hạt gạo/nếp đúng thời gian chuẩn','Đong chuẩn lượng gạo/nếp trong 700g đùi gà và 380g gạo tẻ, vo nhẹ tay 2–3 nước cho sạch bụi cám mà không làm mất lớp dưỡng chất ngoài vỏ hạt, để ráo trên rổ. Nếu là nếp đồ xôi, ngâm trước trong nước ấm hoặc nước màu thảo mộc tự nhiên cùng 3g muối để hạt nếp ngậm đủ nước căng tròn.',11,'Xóc nhẹ một nhúm muối tinh vào gạo nếp sau khi để ráo giúp hạt xôi cơm khi chín có vị đậm dịu và bóng dẻo tự nhiên.'),
(270,2,'Sơ chế & tẩm ướp phần nhân thịt, đậu ăn kèm','Làm sạch và chuẩn bị phần nguyên liệu ăn kèm gồm 120g dưa leo cùng 120g dưa leo, cắt thái gọn gàng đúng quy cách món Cơm gà Phú Yên da vàng óng hành tím ngâm. Ướp thấm nhân với 35ml nước mắm và 20ml chanh trong 15 phút để khi chế biến tạo điểm nhấn đậm đà quyện cùng hạt cơm xôi dẻo thơm.',10,'Chuẩn bị song song phần nhân topping trong lúc chờ nấu cơm/đồ xôi giúp tiết kiệm thời gian và mọi thành phần cùng nóng hổi.'),
(270,3,'Nấu cơm / đồ xôi canh chuẩn nhiệt & độ ẩm hạt','Cho gạo vào nấu với lượng nước luộc gà/nước dùng vừa khéo hoặc dàn đều nếp vào xửng hấp đã sôi sùng sục, chọc vài lỗ thoáng hơi trên bề mặt nếp. Duy trì lửa vừa ổn định để hơi nóng xuyên đều giúp hạt chín dẻo từ lõi mà bên ngoài vẫn ráo tơi óng ả.',15,'Lau khô nước đọng dưới nắp vung mỗi 10 phút khi đồ xôi giúp mặt xôi không bao giờ bị nhão ướt ở rìa xửng.'),
(270,4,'Chế biến chín vàng thơm phần nhân & mỡ hành phi','Bắc chảo lên lửa vừa, phi vàng giòn 80g hành tím và 15g nghệ lấy dầu thơm rồi chế biến chín tới phần nhân 120g dưa leo cho lên màu bóng đẹp và dậy mùi đặc trưng. Trường hợp có đậu xanh hoặc trứng chả kèm theo, chế biến riêng từng phần để giữ trọn sắc màu và hương vị tinh tế.',11,'Rưới một thìa mỡ gà hoặc dầu hành phi vào xới nhẹ lúc cơm/xôi vừa chín tới giúp từng hạt căng bóng mượt mà lâu khô.'),
(270,5,'Pha nước mắm sốt rưới / đồ chua cân bằng vị béo','Pha chén nước sốt chan từ 35ml nước mắm và 20ml chanh khuấy tan sánh nhẹ hoặc trộn nhanh phần hành tím/dưa góp chua ngọt giòn mát đi kèm. Cân chỉnh hài hòa vị mặn ngọt chua thanh để tôn lên độ bùi dẻo của hạt gạo nếp Việt Nam.',7,'Nước mắm ăn kèm các món cơm gà, cơm tấm hay cơm trộn nên nấu sôi nhẹ với đường cho hơi sánh kẹo sẽ bám hạt cơm ngon hơn hẳn.'),
(270,6,'Đơm khuôn đầy đặn, xếp nhân & thưởng thức nóng','Đơm cơm hoặc xôi nóng vào chén ép nhẹ rồi úp tròn ra 4 đĩa, xếp đều các lớp nhân, đồ chua và rắc 30g rau răm lên trên cùng. Rưới nhẹ mỡ hành/nước sốt bóng bẩy và thưởng thức ngay khi hạt cơm xôi còn nóng dẻo thơm lừng.',6,'Tráng mỏng một lớp nước lọc hoặc dầu ăn vào lòng chén trước khi đơm cơm giúp úp ra đĩa tròn trịa sắc nét không dính hạt.'),
(271,1,'Sơ chế sạch & thấm thật khô bề mặt nguyên liệu','Rửa sạch 550g cá basa và 90g bột bắp cùng chút muối loãng để khử mùi tự nhiên, sau đó dùng khăn giấy bếp thấm thật khô ráo hoàn toàn bề mặt. Khứa nhẹ các đường chéo hoặc cắt miếng vừa ăn dày 2–3cm để nhiệt và gia vị thấm sâu đều khắp bên trong.',6,'Bề mặt nguyên liệu càng khô ráo thì khi chiên không bị văng dầu và khi nướng sẽ lên màu vàng ruộm giòn rụm cực đẹp.'),
(271,2,'Chuẩn bị hỗn hợp sốt ướp / bột áo chuẩn tỷ lệ','Phối trộn 20g tỏi băm thật nhuyễn (hoặc vắt lấy nước cốt thơm) cùng 45g me vắt, 35g đường, 25ml nước mắm và 10g ớt trong tô lớn cho quyện sánh đồng nhất. Nếu món có lớp vỏ bột hoặc bánh cuốn từ 550g cá basa và 90g bột bắp, trộn đều hỗn hợp theo đúng định lượng để đạt độ giòn xốp mỏng nhẹ chuẩn vị.',6,'Vắt lấy nước cốt hành tỏi sả khi ướp đồ nướng giúp hương thơm thấm sâu mà không bị cháy đen phần xác băm trên lửa cao.'),
(271,3,'Ướp thấm thớ thịt / tạo hình cuốn khéo léo','Áo đều hỗn hợp gia vị hoặc lớp bột/vỏ cuốn quanh 550g cá basa và 90g bột bắp, massage nhẹ nhàng rồi để nghỉ 15–20 phút cho gia vị thẩm thấu trọn vẹn. Trường hợp cuốn chả/nem hoặc đổ khuôn bánh, thao tác đều tay vừa chặt để nhân kết dính nhưng không bị bục rách khi gặp nhiệt.',7,'Để nguyên liệu nghỉ đủ thời gian trước khi chiên nướng giúp lớp áo bột bám chắc và phần nhân bên trong mọng ngọt.'),
(271,4,'Pha nước chấm cân vị & sơ chế rau đồ chua ăn kèm','Nhặt rửa sạch rau củ ăn kèm ngâm nước mát cho giòn tươi, bào sợi hoặc thái lát gọn gàng bày sẵn bên cạnh. Pha chén nước chấm chua ngọt hoặc muối ớt chanh sả sánh thơm theo khẩu vị vùng miền của món Cá basa phi lê tẩm bột bắp chiên giòn sốt me để cân bằng độ béo giòn.',5,'Luôn chuẩn bị xong rau sống và bát nước chấm trước khi chiên/nướng mẻ cuối để món ăn vừa ra lò là thưởng thức nóng giòn ngay.'),
(271,5,'Làm nóng dầu / lò nướng chuẩn nhiệt & làm chín đều lần 1','Làm nóng chảo dầu hoặc vỉ nướng/nồi chiên ở mức nhiệt vừa khoảng 165–175°C, xếp 550g cá basa và 90g bột bắp vào với khoảng cách thoáng đều nhau. Chiên hoặc nướng trở mặt nhịp nhàng trên lửa vừa để nhiệt dẫn sâu làm chín mềm ngọt hoàn toàn phần nhân bên trong.',9,'Kiểm tra nhiệt dầu bằng đầu đũa tre thấy sủi tăm nhỏ đều là đạt chuẩn 170°C, giúp vỏ không cháy sớm khi bên trong còn sống.'),
(271,6,'Tăng nhiệt khóa giòn rụm vàng ươm bề mặt lần 2','Ở 2–3 phút cuối, tăng lên lửa vừa lớn (khoảng 190°C) hoặc phết thêm lớp dầu điều/mật ong mỏng để vỏ ngoài của Cá basa phi lê tẩm bột bắp chiên giòn sốt me chuyển sắc vàng óng ánh và nổ giòn rụm. Lắng nghe tiếng xèo giòn rộn rã và hương thơm phức lan tỏa khắp bếp thì gắp ra vỉ thưa cho ráo dầu thừa.',4,'Đặt đồ chiên nướng lên giá inox thoáng khí thay vì giấy thấm dầu chồng khít để hơi nước thoát hết, giữ độ giòn lâu gấp 3 lần.'),
(271,7,'Trình bày bắt mắt kèm rau thơm & thưởng thức nóng','Xếp thành phẩm vàng giòn ra đĩa lớn có bày sẵn rau củ ăn kèm và điểm xuyết hành ngò và tiêu xay tươi xanh hài hòa màu sắc. Dọn kèm chén nước chấm sánh đậm ngay chính giữa mâm ăn cho 4 người thưởng thức khi vỏ ngoài còn nóng giòn rụm.',3,'Cắt miếng hoặc dọn ăn ngay trong vòng 10 phút sau khi rời bếp để cảm nhận trọn vẹn sự đối lập giòn ngoài - mềm ngọt bên trong.'),
(272,1,'Sơ chế & chần sạch nguyên liệu xương thịt, hải sản','Rửa sạch 500g sợi bánh canh và 300g chả cá biển với muối hạt rồi chần nhanh trong nồi nước sôi có đập dập 1 nhánh gừng trong 2–3 phút trên lửa lớn để loại bỏ hoàn toàn bọt bẩn. Rửa lại dưới làn nước sạch cho thật trắng trẻo, đồng thời nhặt rửa sạch 120g rau hẹ để ráo nước.',6,'Bước chần sơ và rửa lại bằng nước ấm là bí quyết vàng giúp nồi nước dùng trong vắt, thơm thanh và không bao giờ bị đục hay hôi.'),
(272,2,'Nướng thơm thảo mộc & ninh nền nước dùng ngọt thanh','Cho phần nguyên liệu tạo ngọt từ 500g sợi bánh canh và 300g chả cá biển cùng 20g hành tím đã nướng xém thơm vào nồi sâu lòng với khoảng 1.5–1.8 lít nước lọc. Đun sôi bùng trên lửa lớn rồi hạ ngay về lửa nhỏ liu riu, mở hé vung và hớt kỹ bọt nổi trên mặt để chiết xuất vị ngọt tự nhiên.',16,'Luôn duy trì mặt nước lăn tăn nhẹ thay vì đun sôi sùng sục lửa to để protein không bị nhũ hóa gây đục nước lèo.'),
(272,3,'Xào tạo màu & dậy hương đặc trưng vùng miền','Bắc chảo nhỏ lên bếp với 15ml dầu ăn trên lửa vừa, phi thơm phần hành tỏi sả băm còn lại rồi xào săn 250g cá nục và 12 quả trứng cút cùng 25ml nước mắm và 4g tiêu trong 3–4 phút. Khi hỗn hợp dậy mùi thơm nồng nàn và lên sắc màu óng ả đặc trưng của món Bánh canh hẹ chả cá Phú Yên xanh mướt thì tắt bếp.',5,'Xào riêng phần nguyên liệu tạo màu và gia vị thơm trước khi trút vào nồi nước dùng giúp tầng hương dậy lên rõ nét gấp đôi.'),
(272,4,'Sơ chế & cắt thái phần nhân topping xếp tô','Vớt phần thịt hoặc hải sản chín tới từ 500g sợi bánh canh và 300g chả cá biển ra ngâm ngay vào âu nước đun sôi để nguội giúp bề mặt săn giòn mọng nước, không bị thâm khô. Thái lát mỏng đều tay dày khoảng 3mm ngang thớ hoặc gỡ miếng vừa ăn, sắp riêng từng phần gọn gàng trên đĩa.',5,'Thái thịt ngang thớ với lưỡi dao thật sắc giúp lát thịt mềm mướt, khi chan nước dùng sôi lên sẽ phẳng đẹp không bị quăn cứng.');
INSERT INTO `recipe_steps` (`recipe_id`,`step_order`,`title`,`instruction`,`duration_mins`,`tip_note`) VALUES
(272,5,'Hợp nhất nồi nước lèo & nêm chuẩn định lượng','Trút phần sốt màu thơm vào nồi nước dùng đang sôi lăn tăn, nêm chính xác lượng 25ml nước mắm và 4g tiêu còn lại cho vừa miệng 4 người ăn. Đun nhẹ thêm 5 phút ở lửa vừa để các tầng vị mặn dịu, ngọt hậu từ xương thịt và thảo mộc hòa quyện tròn trịa.',5,'Nên nêm nước mắm ngon ở giai đoạn cuối trên lửa nhỏ để giữ trọn hậu vị ngọt đạm và hương thơm mà không làm nước dùng bị chua.'),
(272,6,'Chần nóng sợi bánh/bún & chuẩn bị rau ăn kèm','Đun sôi một nồi nước riêng, cho phần sợi bún/phở/bánh trong 500g sợi bánh canh và 300g chả cá biển vào trụng nhanh 15–25 giây cho sợi mềm dẻo nóng hổi rồi vẩy thật ráo nước, chia đều vào 4 tô lớn. Chần sơ thêm rau ăn kèm (giá đỗ, rau xanh) nếu muốn dùng chín giòn.',4,'Trụng bún bánh ở nồi nước sôi riêng biệt giúp nước dùng chính không bị nhiễm tinh bột chua và tô bún luôn ráo sợi, thấm vị.'),
(272,7,'Xếp nhân hài hòa, chan nước dùng sôi & thưởng thức','Xếp đều các phần nhân thịt, hải sản lên mặt tô bún bánh, điểm xuyết 120g rau hẹ lên trên cùng. Dùng muôi múc nước dùng đang sôi thật già chan ngập xăm xắp mặt nguyên liệu để làm chín thơm hành ngò, dọn nóng ngay kèm chanh ớt tươi.',4,'Tráng nóng tô sứ bằng nước sôi trước khi xếp bún giúp tô món nước giữ nhiệt bốc khói nghi ngút suốt bữa ăn.'),
(273,1,'Sơ chế tươi sạch & ngâm giòn rau củ thảo mộc','Nhặt rửa kỹ 300g xoài xanh và 80g hành tây cùng 50g đậu phộng và 25g rau răm qua nước muối loãng rồi tráng nước đun sôi để nguội. Với các loại củ quả bào sợi hoặc thái lát mỏng, ngâm vào âu nước đá lạnh pha chút chanh đường trong 10 phút rồi vắt ráo để giữ độ trắng giòn sần sật.',7,'Rau củ làm gỏi và món cuốn phải quay rổ hoặc thấm thật ráo nước để khi trộn nước mắm không bị loãng nhạt.'),
(273,2,'Làm chín tới phần nhân đạm giữ trọn độ ngọt mọng','Xử lý phần nguyên liệu chính (250g tôm sú và 250g mực ống): luộc hấp cùng lát gừng sả đập dập hoặc xào lửa lớn vừa chín tới, sau đó làm nguội nhanh rồi thái lát mỏng / xé sợi đều đặn. Nếu món có pha bột bánh gạo/bột năng, khuấy tan bột với nước đúng tỷ lệ và để bột nghỉ 15 phút cho nở mịn.',8,'Ngâm tôm hoặc thịt luộc qua bát nước sôi để nguội có vài viên đá giúp màu sắc tươi hồng và thớ thịt giòn ngọt không bị khô.'),
(273,3,'Rang vàng đậu phộng mè thơm & phi hành tỏi giòn','Bắc chảo nhỏ lên lửa nhỏ, rang chín vàng thơm đậu phộng/mè hoặc làm mỡ hành xanh mướt và phi vàng giòn hành tím và tỏi băm nhỏ. Vớt hành tỏi phi ra đĩa riêng để nguội giòn tan, giữ lại phần dầu thơm óng ánh để phết bánh hoặc rưới bóng mặt món ăn.',5,'Tắt bếp ngay khi hành phi chuyển vàng sáng vì nhiệt dư trong dầu nóng sẽ tiếp tục làm hành sẫm màu thêm một nấc hoàn hảo.'),
(273,4,'Pha nước mắm chấm / sốt trộn tỷ lệ vàng chua ngọt','Hòa tan hoàn toàn đường cùng 35ml nước mắm và nước ấm trong chén sâu lòng, khuấy đến khi hơi sánh nhẹ mới cho tỏi ớt băm nhuyễn và nước cốt chanh/tắc vào sau cùng. Công thức pha này giúp tỏi ớt nổi đều đẹp mắt trên bề mặt bát nước chấm chuẩn vị Gỏi hải sản xoài xanh Nha Trang giòn mát.',5,'Băm tỏi ớt thật ráo trên thớt khô và cho vào sau khi đường mắm đã nguội thì tỏi ớt sẽ nổi bồng bềnh 100% không bị chìm đáy.'),
(273,5,'Phối trộn thấm vị / tráng hấp & cuốn đều tay','Tiến hành tráng hấp bánh mỏng mượt hoặc trải bánh cuốn gọn gàng 250g tôm sú và 250g mực ống cùng 300g xoài xanh và 80g hành tây; nếu là món gỏi trộn thì rưới từ từ 2/3 lượng sốt chua ngọt vào bóp nhẹ tay cho thấm đều trong 3 phút. Giữ lực tay nhẹ nhàng để rau củ không bị dập nát mà vẫn ngấm trọn vị mặn chua ngọt hài hòa.',6,'Chia nước sốt gỏi làm 2 lần trộn và chắt bỏ phần nước tiết ra ở lần đầu giúp đĩa gỏi khô ráo, đậm đà như ngoài hàng.'),
(273,6,'Bày biện ngũ sắc hài hòa & rắc topping giòn bùi','Xếp món Gỏi hải sản xoài xanh Nha Trang giòn mát ngay ngắn ra đĩa sứ trắng rộng, rải đều phần nhân tôm thịt sắc nét lên trên và rắc phủ 50g đậu phộng và 25g rau răm thơm giòn. Dọn kèm chén nước chấm đậm đà cho 4 người thưởng thức ngay khi rau bánh còn tươi giòn mướt mịn.',4,'Chỉ rắc đậu phộng rang và hành phi ngay trước lúc mang ra bàn ăn để giữ nguyên độ giòn tan bùi béo.'),
(274,1,'Sơ chế sạch & thấm thật khô bề mặt nguyên liệu','Rửa sạch 500g mực một nắng cùng chút muối loãng để khử mùi tự nhiên, sau đó dùng khăn giấy bếp thấm thật khô ráo hoàn toàn bề mặt. Khứa nhẹ các đường chéo hoặc cắt miếng vừa ăn dày 2–3cm để nhiệt và gia vị thấm sâu đều khắp bên trong.',4,'Bề mặt nguyên liệu càng khô ráo thì khi chiên không bị văng dầu và khi nướng sẽ lên màu vàng ruộm giòn rụm cực đẹp.'),
(274,2,'Chuẩn bị hỗn hợp sốt ướp / bột áo chuẩn tỷ lệ','Phối trộn 15g tỏi và 25g sả băm thật nhuyễn (hoặc vắt lấy nước cốt thơm) cùng 20g ớt và 20ml chanh trong tô lớn cho quyện sánh đồng nhất. Nếu món có lớp vỏ bột hoặc bánh cuốn từ 500g mực một nắng, trộn đều hỗn hợp theo đúng định lượng để đạt độ giòn xốp mỏng nhẹ chuẩn vị.',4,'Vắt lấy nước cốt hành tỏi sả khi ướp đồ nướng giúp hương thơm thấm sâu mà không bị cháy đen phần xác băm trên lửa cao.'),
(274,3,'Ướp thấm thớ thịt / tạo hình cuốn khéo léo','Áo đều hỗn hợp gia vị hoặc lớp bột/vỏ cuốn quanh 500g mực một nắng, massage nhẹ nhàng rồi để nghỉ 15–20 phút cho gia vị thẩm thấu trọn vẹn. Trường hợp cuốn chả/nem hoặc đổ khuôn bánh, thao tác đều tay vừa chặt để nhân kết dính nhưng không bị bục rách khi gặp nhiệt.',5,'Để nguyên liệu nghỉ đủ thời gian trước khi chiên nướng giúp lớp áo bột bám chắc và phần nhân bên trong mọng ngọt.'),
(274,4,'Pha nước chấm cân vị & sơ chế rau đồ chua ăn kèm','Nhặt rửa sạch 150g dưa leo ngâm nước mát cho giòn tươi, bào sợi hoặc thái lát gọn gàng bày sẵn bên cạnh. Pha chén nước chấm chua ngọt hoặc muối ớt chanh sả sánh thơm theo khẩu vị vùng miền của món Mực một nắng nướng muối ớt Phan Thiết để cân bằng độ béo giòn.',4,'Luôn chuẩn bị xong rau sống và bát nước chấm trước khi chiên/nướng mẻ cuối để món ăn vừa ra lò là thưởng thức nóng giòn ngay.'),
(274,5,'Làm nóng dầu / lò nướng chuẩn nhiệt & làm chín đều lần 1','Làm nóng chảo dầu hoặc vỉ nướng/nồi chiên ở mức nhiệt vừa khoảng 165–175°C, xếp 500g mực một nắng vào với khoảng cách thoáng đều nhau. Chiên hoặc nướng trở mặt nhịp nhàng trên lửa vừa để nhiệt dẫn sâu làm chín mềm ngọt hoàn toàn phần nhân bên trong.',8,'Kiểm tra nhiệt dầu bằng đầu đũa tre thấy sủi tăm nhỏ đều là đạt chuẩn 170°C, giúp vỏ không cháy sớm khi bên trong còn sống.'),
(274,6,'Tăng nhiệt khóa giòn rụm vàng ươm bề mặt lần 2','Ở 2–3 phút cuối, tăng lên lửa vừa lớn (khoảng 190°C) hoặc phết thêm lớp dầu điều/mật ong mỏng để vỏ ngoài của Mực một nắng nướng muối ớt Phan Thiết chuyển sắc vàng óng ánh và nổ giòn rụm. Lắng nghe tiếng xèo giòn rộn rã và hương thơm phức lan tỏa khắp bếp thì gắp ra vỉ thưa cho ráo dầu thừa.',3,'Đặt đồ chiên nướng lên giá inox thoáng khí thay vì giấy thấm dầu chồng khít để hơi nước thoát hết, giữ độ giòn lâu gấp 3 lần.'),
(274,7,'Trình bày bắt mắt kèm rau thơm & thưởng thức nóng','Xếp thành phẩm vàng giòn ra đĩa lớn có bày sẵn 150g dưa leo và điểm xuyết 20g rau răm tươi xanh hài hòa màu sắc. Dọn kèm chén nước chấm sánh đậm ngay chính giữa mâm ăn cho 4 người thưởng thức khi vỏ ngoài còn nóng giòn rụm.',2,'Cắt miếng hoặc dọn ăn ngay trong vòng 10 phút sau khi rời bếp để cảm nhận trọn vẹn sự đối lập giòn ngoài - mềm ngọt bên trong.'),
(275,1,'Sơ chế sạch & thấm thật khô bề mặt nguyên liệu','Rửa sạch 8 lá bánh tráng và 16 quả trứng cút cùng chút muối loãng để khử mùi tự nhiên, sau đó dùng khăn giấy bếp thấm thật khô ráo hoàn toàn bề mặt. Khứa nhẹ các đường chéo hoặc cắt miếng vừa ăn dày 2–3cm để nhiệt và gia vị thấm sâu đều khắp bên trong.',4,'Bề mặt nguyên liệu càng khô ráo thì khi chiên không bị văng dầu và khi nướng sẽ lên màu vàng ruộm giòn rụm cực đẹp.'),
(275,2,'Chuẩn bị hỗn hợp sốt ướp / bột áo chuẩn tỷ lệ','Phối trộn hành tím và tỏi băm nhỏ băm thật nhuyễn (hoặc vắt lấy nước cốt thơm) cùng 20g mắm ruốc huế và 40g tương ớt trong tô lớn cho quyện sánh đồng nhất. Nếu món có lớp vỏ bột hoặc bánh cuốn từ 8 lá bánh tráng và 16 quả trứng cút, trộn đều hỗn hợp theo đúng định lượng để đạt độ giòn xốp mỏng nhẹ chuẩn vị.',4,'Vắt lấy nước cốt hành tỏi sả khi ướp đồ nướng giúp hương thơm thấm sâu mà không bị cháy đen phần xác băm trên lửa cao.'),
(275,3,'Ướp thấm thớ thịt / tạo hình cuốn khéo léo','Áo đều hỗn hợp gia vị hoặc lớp bột/vỏ cuốn quanh 8 lá bánh tráng và 16 quả trứng cút, massage nhẹ nhàng rồi để nghỉ 15–20 phút cho gia vị thẩm thấu trọn vẹn. Trường hợp cuốn chả/nem hoặc đổ khuôn bánh, thao tác đều tay vừa chặt để nhân kết dính nhưng không bị bục rách khi gặp nhiệt.',5,'Để nguyên liệu nghỉ đủ thời gian trước khi chiên nướng giúp lớp áo bột bám chắc và phần nhân bên trong mọng ngọt.'),
(275,4,'Pha nước chấm cân vị & sơ chế rau đồ chua ăn kèm','Nhặt rửa sạch 40g tép khô ngâm nước mát cho giòn tươi, bào sợi hoặc thái lát gọn gàng bày sẵn bên cạnh. Pha chén nước chấm chua ngọt hoặc muối ớt chanh sả sánh thơm theo khẩu vị vùng miền của món Bánh tráng nướng trứng cút hành phi Phan Rang để cân bằng độ béo giòn.',4,'Luôn chuẩn bị xong rau sống và bát nước chấm trước khi chiên/nướng mẻ cuối để món ăn vừa ra lò là thưởng thức nóng giòn ngay.'),
(275,5,'Làm nóng dầu / lò nướng chuẩn nhiệt & làm chín đều lần 1','Làm nóng chảo dầu hoặc vỉ nướng/nồi chiên ở mức nhiệt vừa khoảng 165–175°C, xếp 8 lá bánh tráng và 16 quả trứng cút vào với khoảng cách thoáng đều nhau. Chiên hoặc nướng trở mặt nhịp nhàng trên lửa vừa để nhiệt dẫn sâu làm chín mềm ngọt hoàn toàn phần nhân bên trong.',8,'Kiểm tra nhiệt dầu bằng đầu đũa tre thấy sủi tăm nhỏ đều là đạt chuẩn 170°C, giúp vỏ không cháy sớm khi bên trong còn sống.'),
(275,6,'Tăng nhiệt khóa giòn rụm vàng ươm bề mặt lần 2','Ở 2–3 phút cuối, tăng lên lửa vừa lớn (khoảng 190°C) hoặc phết thêm lớp dầu điều/mật ong mỏng để vỏ ngoài của Bánh tráng nướng trứng cút hành phi Phan Rang chuyển sắc vàng óng ánh và nổ giòn rụm. Lắng nghe tiếng xèo giòn rộn rã và hương thơm phức lan tỏa khắp bếp thì gắp ra vỉ thưa cho ráo dầu thừa.',3,'Đặt đồ chiên nướng lên giá inox thoáng khí thay vì giấy thấm dầu chồng khít để hơi nước thoát hết, giữ độ giòn lâu gấp 3 lần.'),
(275,7,'Trình bày bắt mắt kèm rau thơm & thưởng thức nóng','Xếp thành phẩm vàng giòn ra đĩa lớn có bày sẵn 40g tép khô và điểm xuyết 50g hành lá và 30g hành phi tươi xanh hài hòa màu sắc. Dọn kèm chén nước chấm sánh đậm ngay chính giữa mâm ăn cho 4 người thưởng thức khi vỏ ngoài còn nóng giòn rụm.',2,'Cắt miếng hoặc dọn ăn ngay trong vòng 10 phút sau khi rời bếp để cảm nhận trọn vẹn sự đối lập giòn ngoài - mềm ngọt bên trong.'),
(276,1,'Tuyển chọn & sơ chế tươi sạch nguyên liệu pha chế','Rửa sạch kỹ các nguyên liệu tươi gồm 35g rong biển khô và 50g táo đỏ khô và 30g lá dứa, để ráo nước hoàn toàn trên khay sạch. Cắt lát, đập dập hoặc đong chuẩn xác từng gam/ml nguyên liệu cho khẩu phần 4 ly để hương vị đồng nhất tuyệt đối.',8,'Loại bỏ kỹ hạt chanh, tắc trước khi vắt hoặc nấu giúp thức uống giữ hậu vị thanh ngọt mà không hề bị đắng vỏ.'),
(276,2,'Ủ chiết xuất nền trà, cà phê hoặc nấu cốt thảo mộc','Đun nước đạt nhiệt độ chuẩn 90–95°C (không dùng nước sôi sùng sục làm cháy hương), tiến hành ủ chiết xuất hoặc nấu nhỏ lửa 35g rong biển khô và 50g táo đỏ khô trong thời gian quy định. Lọc qua rây mịn hoặc túi vải sạch để thu được phần nước cốt trong trẻo, đậm hương tự nhiên không gợn cặn.',11,'Ủ trà/cà phê đúng nhiệt độ 92°C và đậy nắp kín giúp thu trọn tinh dầu thơm quyến rũ mà không chiết xuất vị chát gắt.');
INSERT INTO `recipe_steps` (`recipe_id`,`step_order`,`title`,`instruction`,`duration_mins`,`tip_note`) VALUES
(276,3,'Xử lý lớp kem bông mịn / hỗn hợp sữa & trái cây','Đánh bông mượt hoặc khuấy hòa quyện phần nguyên liệu bổ trợ (40g nhãn nhục và 15g hạt chia) cùng 110g đường phèn đến khi sánh mịn đồng nhất. Kiểm soát tốc độ khuấy/đánh đều tay để tạo kết cấu bồng bềnh mượt mà hoặc hòa tan hoàn toàn đường phèn mật ong.',8,'Nếu đánh kem trứng, nghiêng nhẹ âu 45 độ và đánh một chiều tốc độ cao cho tới khi nhấc que tạo chóp mềm bóng mượt không tanh.'),
(276,4,'Cân chỉnh định lượng độ ngọt & tầng hương tươi mát','Phối trộn phần nước cốt nền cùng hỗn hợp tạo vị theo đúng tỷ lệ vàng của món Nước mát rong biển táo đỏ đường phèn Nha Trang, khuấy nhẹ để các tầng hương hòa quyện. Nếu có nước cốt chanh hoặc mật ong rừng, cho vào khi nền nước đã hạ xuống dưới 55°C để bảo toàn trọn vẹn vitamin và hương thơm.',6,'Nếm thử trước khi thêm đá viên sao cho vị đậm hơn khoảng 15% để khi đá tan nhẹ là vừa vặn hoàn hảo.'),
(276,5,'Phối tầng thẩm mỹ ra ly thủy tinh nóng hoặc đá mát','Tráng ấm ly gốm (nếu dùng nóng) hoặc cho lượng đá viên tinh khiết vừa đủ vào ly thủy tinh cao, rót từ từ cốt thức uống vào 2/3 ly. Nhẹ nhàng rót lớp kem/sữa hoặc xếp lát trái cây tươi áp sát thành ly tạo hiệu ứng phân tầng đẹp mắt như quán chuyên nghiệp.',4,'Rót lớp kem hoặc sữa nhẹ nhàng qua lưng muỗng inox giúp hai tầng màu tách bạch sắc nét cực kỳ cuốn hút.'),
(276,6,'Điểm xuyết lá thơm trang trí & thưởng thức ngay','Trang trí trên mặt ly bằng lát nguyên liệu tươi, nhánh bạc hà/lá dứa hoặc rắc nhẹ bột cacao/hạt chia cho món Nước mát rong biển táo đỏ đường phèn Nha Trang thêm phần sinh động. Phục vụ ngay khi vừa pha chế xong cho 4 người để tận hưởng trọn vẹn hương thơm tươi mới sảng khoái nhất.',3,'Vỗ nhẹ lá bạc hà trong lòng bàn tay trước khi đặt lên miệng ly sẽ đánh thức tinh dầu the mát lan tỏa ngay khi nâng ly.'),
(277,1,'Sơ chế sạch & thấm thật khô bề mặt nguyên liệu','Rửa sạch 900g thịt gà (đùi) cùng chút muối loãng để khử mùi tự nhiên, sau đó dùng khăn giấy bếp thấm thật khô ráo hoàn toàn bề mặt. Khứa nhẹ các đường chéo hoặc cắt miếng vừa ăn dày 2–3cm để nhiệt và gia vị thấm sâu đều khắp bên trong.',10,'Bề mặt nguyên liệu càng khô ráo thì khi chiên không bị văng dầu và khi nướng sẽ lên màu vàng ruộm giòn rụm cực đẹp.'),
(277,2,'Chuẩn bị hỗn hợp sốt ướp / bột áo chuẩn tỷ lệ','Phối trộn 70g sả và 30g hành tím băm thật nhuyễn (hoặc vắt lấy nước cốt thơm) cùng 30g mật ong, 15g ớt, 25ml nước mắm và 20ml chanh trong tô lớn cho quyện sánh đồng nhất. Nếu món có lớp vỏ bột hoặc bánh cuốn từ 900g thịt gà (đùi), trộn đều hỗn hợp theo đúng định lượng để đạt độ giòn xốp mỏng nhẹ chuẩn vị.',10,'Vắt lấy nước cốt hành tỏi sả khi ướp đồ nướng giúp hương thơm thấm sâu mà không bị cháy đen phần xác băm trên lửa cao.'),
(277,3,'Ướp thấm thớ thịt / tạo hình cuốn khéo léo','Áo đều hỗn hợp gia vị hoặc lớp bột/vỏ cuốn quanh 900g thịt gà (đùi), massage nhẹ nhàng rồi để nghỉ 15–20 phút cho gia vị thẩm thấu trọn vẹn. Trường hợp cuốn chả/nem hoặc đổ khuôn bánh, thao tác đều tay vừa chặt để nhân kết dính nhưng không bị bục rách khi gặp nhiệt.',13,'Để nguyên liệu nghỉ đủ thời gian trước khi chiên nướng giúp lớp áo bột bám chắc và phần nhân bên trong mọng ngọt.'),
(277,4,'Pha nước chấm cân vị & sơ chế rau đồ chua ăn kèm','Nhặt rửa sạch rau củ ăn kèm ngâm nước mát cho giòn tươi, bào sợi hoặc thái lát gọn gàng bày sẵn bên cạnh. Pha chén nước chấm chua ngọt hoặc muối ớt chanh sả sánh thơm theo khẩu vị vùng miền của món Gà nướng Bản Đôn Đắk Lắk chấm muối sả ớt để cân bằng độ béo giòn.',8,'Luôn chuẩn bị xong rau sống và bát nước chấm trước khi chiên/nướng mẻ cuối để món ăn vừa ra lò là thưởng thức nóng giòn ngay.'),
(277,5,'Làm nóng dầu / lò nướng chuẩn nhiệt & làm chín đều lần 1','Làm nóng chảo dầu hoặc vỉ nướng/nồi chiên ở mức nhiệt vừa khoảng 165–175°C, xếp 900g thịt gà (đùi) vào với khoảng cách thoáng đều nhau. Chiên hoặc nướng trở mặt nhịp nhàng trên lửa vừa để nhiệt dẫn sâu làm chín mềm ngọt hoàn toàn phần nhân bên trong.',15,'Kiểm tra nhiệt dầu bằng đầu đũa tre thấy sủi tăm nhỏ đều là đạt chuẩn 170°C, giúp vỏ không cháy sớm khi bên trong còn sống.'),
(277,6,'Tăng nhiệt khóa giòn rụm vàng ươm bề mặt lần 2','Ở 2–3 phút cuối, tăng lên lửa vừa lớn (khoảng 190°C) hoặc phết thêm lớp dầu điều/mật ong mỏng để vỏ ngoài của Gà nướng Bản Đôn Đắk Lắk chấm muối sả ớt chuyển sắc vàng óng ánh và nổ giòn rụm. Lắng nghe tiếng xèo giòn rộn rã và hương thơm phức lan tỏa khắp bếp thì gắp ra vỉ thưa cho ráo dầu thừa.',8,'Đặt đồ chiên nướng lên giá inox thoáng khí thay vì giấy thấm dầu chồng khít để hơi nước thoát hết, giữ độ giòn lâu gấp 3 lần.'),
(277,7,'Trình bày bắt mắt kèm rau thơm & thưởng thức nóng','Xếp thành phẩm vàng giòn ra đĩa lớn có bày sẵn rau củ ăn kèm và điểm xuyết 20g lá chanh tươi xanh hài hòa màu sắc. Dọn kèm chén nước chấm sánh đậm ngay chính giữa mâm ăn cho 4 người thưởng thức khi vỏ ngoài còn nóng giòn rụm.',6,'Cắt miếng hoặc dọn ăn ngay trong vòng 10 phút sau khi rời bếp để cảm nhận trọn vẹn sự đối lập giòn ngoài - mềm ngọt bên trong.'),
(278,1,'Sơ chế & chần sạch nguyên liệu xương thịt, hải sản','Rửa sạch 750g thịt gà (đùi) và 180g lá giang với muối hạt rồi chần nhanh trong nồi nước sôi có đập dập 1 nhánh gừng trong 2–3 phút trên lửa lớn để loại bỏ hoàn toàn bọt bẩn. Rửa lại dưới làn nước sạch cho thật trắng trẻo, đồng thời nhặt rửa sạch 200g măng tươi để ráo nước.',8,'Bước chần sơ và rửa lại bằng nước ấm là bí quyết vàng giúp nồi nước dùng trong vắt, thơm thanh và không bao giờ bị đục hay hôi.'),
(278,2,'Nướng thơm thảo mộc & ninh nền nước dùng ngọt thanh','Cho phần nguyên liệu tạo ngọt từ 750g thịt gà (đùi) và 180g lá giang cùng 40g sả và 20g tỏi đã nướng xém thơm vào nồi sâu lòng với khoảng 1.5–1.8 lít nước lọc. Đun sôi bùng trên lửa lớn rồi hạ ngay về lửa nhỏ liu riu, mở hé vung và hớt kỹ bọt nổi trên mặt để chiết xuất vị ngọt tự nhiên.',16,'Luôn duy trì mặt nước lăn tăn nhẹ thay vì đun sôi sùng sục lửa to để protein không bị nhũ hóa gây đục nước lèo.'),
(278,3,'Xào tạo màu & dậy hương đặc trưng vùng miền','Bắc chảo nhỏ lên bếp với 15ml dầu ăn trên lửa vừa, phi thơm phần hành tỏi sả băm còn lại rồi xào săn 400g bún tươi cùng 30ml nước mắm trong 3–4 phút. Khi hỗn hợp dậy mùi thơm nồng nàn và lên sắc màu óng ả đặc trưng của món Lẩu gà lá giang măng tươi kiểu cao nguyên thì tắt bếp.',7,'Xào riêng phần nguyên liệu tạo màu và gia vị thơm trước khi trút vào nồi nước dùng giúp tầng hương dậy lên rõ nét gấp đôi.'),
(278,4,'Sơ chế & cắt thái phần nhân topping xếp tô','Vớt phần thịt hoặc hải sản chín tới từ 750g thịt gà (đùi) và 180g lá giang ra ngâm ngay vào âu nước đun sôi để nguội giúp bề mặt săn giòn mọng nước, không bị thâm khô. Thái lát mỏng đều tay dày khoảng 3mm ngang thớ hoặc gỡ miếng vừa ăn, sắp riêng từng phần gọn gàng trên đĩa.',7,'Thái thịt ngang thớ với lưỡi dao thật sắc giúp lát thịt mềm mướt, khi chan nước dùng sôi lên sẽ phẳng đẹp không bị quăn cứng.'),
(278,5,'Hợp nhất nồi nước lèo & nêm chuẩn định lượng','Trút phần sốt màu thơm vào nồi nước dùng đang sôi lăn tăn, nêm chính xác lượng 30ml nước mắm còn lại cho vừa miệng 4 người ăn. Đun nhẹ thêm 5 phút ở lửa vừa để các tầng vị mặn dịu, ngọt hậu từ xương thịt và thảo mộc hòa quyện tròn trịa.',7,'Nên nêm nước mắm ngon ở giai đoạn cuối trên lửa nhỏ để giữ trọn hậu vị ngọt đạm và hương thơm mà không làm nước dùng bị chua.'),
(278,6,'Chần nóng sợi bánh/bún & chuẩn bị rau ăn kèm','Đun sôi một nồi nước riêng, cho phần sợi bún/phở/bánh trong 750g thịt gà (đùi) và 180g lá giang vào trụng nhanh 15–25 giây cho sợi mềm dẻo nóng hổi rồi vẩy thật ráo nước, chia đều vào 4 tô lớn. Chần sơ thêm rau ăn kèm (200g măng tươi) nếu muốn dùng chín giòn.',6,'Trụng bún bánh ở nồi nước sôi riêng biệt giúp nước dùng chính không bị nhiễm tinh bột chua và tô bún luôn ráo sợi, thấm vị.'),
(278,7,'Xếp nhân hài hòa, chan nước dùng sôi & thưởng thức','Xếp đều các phần nhân thịt, hải sản lên mặt tô bún bánh, điểm xuyết 25g lá ngò gai lên trên cùng. Dùng muôi múc nước dùng đang sôi thật già chan ngập xăm xắp mặt nguyên liệu để làm chín thơm hành ngò, dọn nóng ngay kèm chanh ớt tươi.',4,'Tráng nóng tô sứ bằng nước sôi trước khi xếp bún giúp tô món nước giữ nhiệt bốc khói nghi ngút suốt bữa ăn.'),
(279,1,'Sơ chế & chần sạch nguyên liệu xương thịt, hải sản','Rửa sạch 500g bánh phở tươi và 250g thịt bò với muối hạt rồi chần nhanh trong nồi nước sôi có đập dập 1 nhánh gừng trong 2–3 phút trên lửa lớn để loại bỏ hoàn toàn bọt bẩn. Rửa lại dưới làn nước sạch cho thật trắng trẻo, đồng thời nhặt rửa sạch 150g giá đỗ để ráo nước.',10,'Bước chần sơ và rửa lại bằng nước ấm là bí quyết vàng giúp nồi nước dùng trong vắt, thơm thanh và không bao giờ bị đục hay hôi.'),
(279,2,'Nướng thơm thảo mộc & ninh nền nước dùng ngọt thanh','Cho phần nguyên liệu tạo ngọt từ 500g bánh phở tươi và 250g thịt bò cùng hành tím và tỏi băm nhỏ đã nướng xém thơm vào nồi sâu lòng với khoảng 1.5–1.8 lít nước lọc. Đun sôi bùng trên lửa lớn rồi hạ ngay về lửa nhỏ liu riu, mở hé vung và hớt kỹ bọt nổi trên mặt để chiết xuất vị ngọt tự nhiên.',23,'Luôn duy trì mặt nước lăn tăn nhẹ thay vì đun sôi sùng sục lửa to để protein không bị nhũ hóa gây đục nước lèo.'),
(279,3,'Xào tạo màu & dậy hương đặc trưng vùng miền','Bắc chảo nhỏ lên bếp với 15ml dầu ăn trên lửa vừa, phi thơm phần hành tỏi sả băm còn lại rồi xào săn 200g thịt heo xay và 250g sườn non cùng 45g tương đen trong 3–4 phút. Khi hỗn hợp dậy mùi thơm nồng nàn và lên sắc màu óng ả đặc trưng của món Phở khô Gia Lai hai tô thịt bằm hành phi thì tắt bếp.',8,'Xào riêng phần nguyên liệu tạo màu và gia vị thơm trước khi trút vào nồi nước dùng giúp tầng hương dậy lên rõ nét gấp đôi.'),
(279,4,'Sơ chế & cắt thái phần nhân topping xếp tô','Vớt phần thịt hoặc hải sản chín tới từ 500g bánh phở tươi và 250g thịt bò ra ngâm ngay vào âu nước đun sôi để nguội giúp bề mặt săn giòn mọng nước, không bị thâm khô. Thái lát mỏng đều tay dày khoảng 3mm ngang thớ hoặc gỡ miếng vừa ăn, sắp riêng từng phần gọn gàng trên đĩa.',8,'Thái thịt ngang thớ với lưỡi dao thật sắc giúp lát thịt mềm mướt, khi chan nước dùng sôi lên sẽ phẳng đẹp không bị quăn cứng.'),
(279,5,'Hợp nhất nồi nước lèo & nêm chuẩn định lượng','Trút phần sốt màu thơm vào nồi nước dùng đang sôi lăn tăn, nêm chính xác lượng 45g tương đen còn lại cho vừa miệng 4 người ăn. Đun nhẹ thêm 5 phút ở lửa vừa để các tầng vị mặn dịu, ngọt hậu từ xương thịt và thảo mộc hòa quyện tròn trịa.',8,'Nên nêm nước mắm ngon ở giai đoạn cuối trên lửa nhỏ để giữ trọn hậu vị ngọt đạm và hương thơm mà không làm nước dùng bị chua.'),
(279,6,'Chần nóng sợi bánh/bún & chuẩn bị rau ăn kèm','Đun sôi một nồi nước riêng, cho phần sợi bún/phở/bánh trong 500g bánh phở tươi và 250g thịt bò vào trụng nhanh 15–25 giây cho sợi mềm dẻo nóng hổi rồi vẩy thật ráo nước, chia đều vào 4 tô lớn. Chần sơ thêm rau ăn kèm (150g giá đỗ) nếu muốn dùng chín giòn.',7,'Trụng bún bánh ở nồi nước sôi riêng biệt giúp nước dùng chính không bị nhiễm tinh bột chua và tô bún luôn ráo sợi, thấm vị.'),
(279,7,'Xếp nhân hài hòa, chan nước dùng sôi & thưởng thức','Xếp đều các phần nhân thịt, hải sản lên mặt tô bún bánh, điểm xuyết 35g hành phi và 30g hành lá lên trên cùng. Dùng muôi múc nước dùng đang sôi thật già chan ngập xăm xắp mặt nguyên liệu để làm chín thơm hành ngò, dọn nóng ngay kèm chanh ớt tươi.',6,'Tráng nóng tô sứ bằng nước sôi trước khi xếp bún giúp tô món nước giữ nhiệt bốc khói nghi ngút suốt bữa ăn.');
INSERT INTO `recipe_steps` (`recipe_id`,`step_order`,`title`,`instruction`,`duration_mins`,`tip_note`) VALUES
(280,1,'Sơ chế & chần sạch nguyên liệu xương thịt, hải sản','Rửa sạch 600g bún tươi và 350g cua đồng xay với muối hạt rồi chần nhanh trong nồi nước sôi có đập dập 1 nhánh gừng trong 2–3 phút trên lửa lớn để loại bỏ hoàn toàn bọt bẩn. Rửa lại dưới làn nước sạch cho thật trắng trẻo, đồng thời nhặt rửa sạch 200g cải xanh và 30g tép khô để ráo nước.',9,'Bước chần sơ và rửa lại bằng nước ấm là bí quyết vàng giúp nồi nước dùng trong vắt, thơm thanh và không bao giờ bị đục hay hôi.'),
(280,2,'Nướng thơm thảo mộc & ninh nền nước dùng ngọt thanh','Cho phần nguyên liệu tạo ngọt từ 600g bún tươi và 350g cua đồng xay cùng hành tím và tỏi băm nhỏ đã nướng xém thơm vào nồi sâu lòng với khoảng 1.5–1.8 lít nước lọc. Đun sôi bùng trên lửa lớn rồi hạ ngay về lửa nhỏ liu riu, mở hé vung và hớt kỹ bọt nổi trên mặt để chiết xuất vị ngọt tự nhiên.',21,'Luôn duy trì mặt nước lăn tăn nhẹ thay vì đun sôi sùng sục lửa to để protein không bị nhũ hóa gây đục nước lèo.'),
(280,3,'Xào tạo màu & dậy hương đặc trưng vùng miền','Bắc chảo nhỏ lên bếp với 15ml dầu ăn trên lửa vừa, phi thơm phần hành tỏi sả băm còn lại rồi xào săn 200g thịt heo xay và 16 quả trứng cút cùng 30ml nước mắm trong 3–4 phút. Khi hỗn hợp dậy mùi thơm nồng nàn và lên sắc màu óng ả đặc trưng của món Bún đỏ Buôn Ma Thuột gạch cua trứng cút thì tắt bếp.',8,'Xào riêng phần nguyên liệu tạo màu và gia vị thơm trước khi trút vào nồi nước dùng giúp tầng hương dậy lên rõ nét gấp đôi.'),
(280,4,'Sơ chế & cắt thái phần nhân topping xếp tô','Vớt phần thịt hoặc hải sản chín tới từ 600g bún tươi và 350g cua đồng xay ra ngâm ngay vào âu nước đun sôi để nguội giúp bề mặt săn giòn mọng nước, không bị thâm khô. Thái lát mỏng đều tay dày khoảng 3mm ngang thớ hoặc gỡ miếng vừa ăn, sắp riêng từng phần gọn gàng trên đĩa.',8,'Thái thịt ngang thớ với lưỡi dao thật sắc giúp lát thịt mềm mướt, khi chan nước dùng sôi lên sẽ phẳng đẹp không bị quăn cứng.'),
(280,5,'Hợp nhất nồi nước lèo & nêm chuẩn định lượng','Trút phần sốt màu thơm vào nồi nước dùng đang sôi lăn tăn, nêm chính xác lượng 30ml nước mắm còn lại cho vừa miệng 4 người ăn. Đun nhẹ thêm 5 phút ở lửa vừa để các tầng vị mặn dịu, ngọt hậu từ xương thịt và thảo mộc hòa quyện tròn trịa.',8,'Nên nêm nước mắm ngon ở giai đoạn cuối trên lửa nhỏ để giữ trọn hậu vị ngọt đạm và hương thơm mà không làm nước dùng bị chua.'),
(280,6,'Chần nóng sợi bánh/bún & chuẩn bị rau ăn kèm','Đun sôi một nồi nước riêng, cho phần sợi bún/phở/bánh trong 600g bún tươi và 350g cua đồng xay vào trụng nhanh 15–25 giây cho sợi mềm dẻo nóng hổi rồi vẩy thật ráo nước, chia đều vào 4 tô lớn. Chần sơ thêm rau ăn kèm (200g cải xanh và 30g tép khô) nếu muốn dùng chín giòn.',6,'Trụng bún bánh ở nồi nước sôi riêng biệt giúp nước dùng chính không bị nhiễm tinh bột chua và tô bún luôn ráo sợi, thấm vị.'),
(280,7,'Xếp nhân hài hòa, chan nước dùng sôi & thưởng thức','Xếp đều các phần nhân thịt, hải sản lên mặt tô bún bánh, điểm xuyết hành ngò và tiêu xay lên trên cùng. Dùng muôi múc nước dùng đang sôi thật già chan ngập xăm xắp mặt nguyên liệu để làm chín thơm hành ngò, dọn nóng ngay kèm chanh ớt tươi.',5,'Tráng nóng tô sứ bằng nước sôi trước khi xếp bún giúp tô món nước giữ nhiệt bốc khói nghi ngút suốt bữa ăn.'),
(281,1,'Sơ chế tươi sạch & ngâm giòn rau củ thảo mộc','Nhặt rửa kỹ 120g hành tây cùng 35g rau răm và 25g hành phi qua nước muối loãng rồi tráng nước đun sôi để nguội. Với các loại củ quả bào sợi hoặc thái lát mỏng, ngâm vào âu nước đá lạnh pha chút chanh đường trong 10 phút rồi vắt ráo để giữ độ trắng giòn sần sật.',9,'Rau củ làm gỏi và món cuốn phải quay rổ hoặc thấm thật ráo nước để khi trộn nước mắm không bị loãng nhạt.'),
(281,2,'Làm chín tới phần nhân đạm giữ trọn độ ngọt mọng','Xử lý phần nguyên liệu chính (500g bánh ướt và 250g thịt gà (ức)): luộc hấp cùng lát gừng sả đập dập hoặc xào lửa lớn vừa chín tới, sau đó làm nguội nhanh rồi thái lát mỏng / xé sợi đều đặn. Nếu món có pha bột bánh gạo/bột năng, khuấy tan bột với nước đúng tỷ lệ và để bột nghỉ 15 phút cho nở mịn.',12,'Ngâm tôm hoặc thịt luộc qua bát nước sôi để nguội có vài viên đá giúp màu sắc tươi hồng và thớ thịt giòn ngọt không bị khô.'),
(281,3,'Rang vàng đậu phộng mè thơm & phi hành tỏi giòn','Bắc chảo nhỏ lên lửa nhỏ, rang chín vàng thơm đậu phộng/mè hoặc làm mỡ hành xanh mướt và phi vàng giòn hành tím và tỏi băm nhỏ. Vớt hành tỏi phi ra đĩa riêng để nguội giòn tan, giữ lại phần dầu thơm óng ánh để phết bánh hoặc rưới bóng mặt món ăn.',6,'Tắt bếp ngay khi hành phi chuyển vàng sáng vì nhiệt dư trong dầu nóng sẽ tiếp tục làm hành sẫm màu thêm một nấc hoàn hảo.'),
(281,4,'Pha nước mắm chấm / sốt trộn tỷ lệ vàng chua ngọt','Hòa tan hoàn toàn đường cùng 35ml nước mắm và 20ml chanh và nước ấm trong chén sâu lòng, khuấy đến khi hơi sánh nhẹ mới cho tỏi ớt băm nhuyễn và nước cốt chanh/tắc vào sau cùng. Công thức pha này giúp tỏi ớt nổi đều đẹp mắt trên bề mặt bát nước chấm chuẩn vị Bánh ướt gà xé hành tây rau răm Đà Lạt.',6,'Băm tỏi ớt thật ráo trên thớt khô và cho vào sau khi đường mắm đã nguội thì tỏi ớt sẽ nổi bồng bềnh 100% không bị chìm đáy.'),
(281,5,'Phối trộn thấm vị / tráng hấp & cuốn đều tay','Tiến hành tráng hấp bánh mỏng mượt hoặc trải bánh cuốn gọn gàng 500g bánh ướt và 250g thịt gà (ức) cùng 120g hành tây; nếu là món gỏi trộn thì rưới từ từ 2/3 lượng sốt chua ngọt vào bóp nhẹ tay cho thấm đều trong 3 phút. Giữ lực tay nhẹ nhàng để rau củ không bị dập nát mà vẫn ngấm trọn vị mặn chua ngọt hài hòa.',8,'Chia nước sốt gỏi làm 2 lần trộn và chắt bỏ phần nước tiết ra ở lần đầu giúp đĩa gỏi khô ráo, đậm đà như ngoài hàng.'),
(281,6,'Bày biện ngũ sắc hài hòa & rắc topping giòn bùi','Xếp món Bánh ướt gà xé hành tây rau răm Đà Lạt ngay ngắn ra đĩa sứ trắng rộng, rải đều phần nhân tôm thịt sắc nét lên trên và rắc phủ 35g rau răm và 25g hành phi thơm giòn. Dọn kèm chén nước chấm đậm đà cho 4 người thưởng thức ngay khi rau bánh còn tươi giòn mướt mịn.',4,'Chỉ rắc đậu phộng rang và hành phi ngay trước lúc mang ra bàn ăn để giữ nguyên độ giòn tan bùi béo.'),
(282,1,'Sơ chế sạch & thấm thật khô bề mặt nguyên liệu','Rửa sạch 240g bột gạo và 20 quả trứng cút cùng chút muối loãng để khử mùi tự nhiên, sau đó dùng khăn giấy bếp thấm thật khô ráo hoàn toàn bề mặt. Khứa nhẹ các đường chéo hoặc cắt miếng vừa ăn dày 2–3cm để nhiệt và gia vị thấm sâu đều khắp bên trong.',7,'Bề mặt nguyên liệu càng khô ráo thì khi chiên không bị văng dầu và khi nướng sẽ lên màu vàng ruộm giòn rụm cực đẹp.'),
(282,2,'Chuẩn bị hỗn hợp sốt ướp / bột áo chuẩn tỷ lệ','Phối trộn hành tím và tỏi băm nhỏ băm thật nhuyễn (hoặc vắt lấy nước cốt thơm) cùng 30ml nước mắm trong tô lớn cho quyện sánh đồng nhất. Nếu món có lớp vỏ bột hoặc bánh cuốn từ 240g bột gạo và 20 quả trứng cút, trộn đều hỗn hợp theo đúng định lượng để đạt độ giòn xốp mỏng nhẹ chuẩn vị.',6,'Vắt lấy nước cốt hành tỏi sả khi ướp đồ nướng giúp hương thơm thấm sâu mà không bị cháy đen phần xác băm trên lửa cao.'),
(282,3,'Ướp thấm thớ thịt / tạo hình cuốn khéo léo','Áo đều hỗn hợp gia vị hoặc lớp bột/vỏ cuốn quanh 240g bột gạo và 20 quả trứng cút, massage nhẹ nhàng rồi để nghỉ 15–20 phút cho gia vị thẩm thấu trọn vẹn. Trường hợp cuốn chả/nem hoặc đổ khuôn bánh, thao tác đều tay vừa chặt để nhân kết dính nhưng không bị bục rách khi gặp nhiệt.',8,'Để nguyên liệu nghỉ đủ thời gian trước khi chiên nướng giúp lớp áo bột bám chắc và phần nhân bên trong mọng ngọt.'),
(282,4,'Pha nước chấm cân vị & sơ chế rau đồ chua ăn kèm','Nhặt rửa sạch 80g củ sắn và 100g xoài xanh ngâm nước mát cho giòn tươi, bào sợi hoặc thái lát gọn gàng bày sẵn bên cạnh. Pha chén nước chấm chua ngọt hoặc muối ớt chanh sả sánh thơm theo khẩu vị vùng miền của món Bánh căn trứng cút xíu mại mỡ hành Đà Lạt để cân bằng độ béo giòn.',5,'Luôn chuẩn bị xong rau sống và bát nước chấm trước khi chiên/nướng mẻ cuối để món ăn vừa ra lò là thưởng thức nóng giòn ngay.'),
(282,5,'Làm nóng dầu / lò nướng chuẩn nhiệt & làm chín đều lần 1','Làm nóng chảo dầu hoặc vỉ nướng/nồi chiên ở mức nhiệt vừa khoảng 165–175°C, xếp 240g bột gạo và 20 quả trứng cút vào với khoảng cách thoáng đều nhau. Chiên hoặc nướng trở mặt nhịp nhàng trên lửa vừa để nhiệt dẫn sâu làm chín mềm ngọt hoàn toàn phần nhân bên trong.',10,'Kiểm tra nhiệt dầu bằng đầu đũa tre thấy sủi tăm nhỏ đều là đạt chuẩn 170°C, giúp vỏ không cháy sớm khi bên trong còn sống.'),
(282,6,'Tăng nhiệt khóa giòn rụm vàng ươm bề mặt lần 2','Ở 2–3 phút cuối, tăng lên lửa vừa lớn (khoảng 190°C) hoặc phết thêm lớp dầu điều/mật ong mỏng để vỏ ngoài của Bánh căn trứng cút xíu mại mỡ hành Đà Lạt chuyển sắc vàng óng ánh và nổ giòn rụm. Lắng nghe tiếng xèo giòn rộn rã và hương thơm phức lan tỏa khắp bếp thì gắp ra vỉ thưa cho ráo dầu thừa.',5,'Đặt đồ chiên nướng lên giá inox thoáng khí thay vì giấy thấm dầu chồng khít để hơi nước thoát hết, giữ độ giòn lâu gấp 3 lần.'),
(282,7,'Trình bày bắt mắt kèm rau thơm & thưởng thức nóng','Xếp thành phẩm vàng giòn ra đĩa lớn có bày sẵn 80g củ sắn và 100g xoài xanh và điểm xuyết 60g hành lá tươi xanh hài hòa màu sắc. Dọn kèm chén nước chấm sánh đậm ngay chính giữa mâm ăn cho 4 người thưởng thức khi vỏ ngoài còn nóng giòn rụm.',4,'Cắt miếng hoặc dọn ăn ngay trong vòng 10 phút sau khi rời bếp để cảm nhận trọn vẹn sự đối lập giòn ngoài - mềm ngọt bên trong.'),
(283,1,'Sơ chế sạch & thấm thật khô bề mặt nguyên liệu','Rửa sạch 500g thịt bò và 180g ớt chuông cùng chút muối loãng để khử mùi tự nhiên, sau đó dùng khăn giấy bếp thấm thật khô ráo hoàn toàn bề mặt. Khứa nhẹ các đường chéo hoặc cắt miếng vừa ăn dày 2–3cm để nhiệt và gia vị thấm sâu đều khắp bên trong.',6,'Bề mặt nguyên liệu càng khô ráo thì khi chiên không bị văng dầu và khi nướng sẽ lên màu vàng ruộm giòn rụm cực đẹp.'),
(283,2,'Chuẩn bị hỗn hợp sốt ướp / bột áo chuẩn tỷ lệ','Phối trộn 45g sả và 20g tỏi băm thật nhuyễn (hoặc vắt lấy nước cốt thơm) cùng 25ml dầu hào trong tô lớn cho quyện sánh đồng nhất. Nếu món có lớp vỏ bột hoặc bánh cuốn từ 500g thịt bò và 180g ớt chuông, trộn đều hỗn hợp theo đúng định lượng để đạt độ giòn xốp mỏng nhẹ chuẩn vị.',6,'Vắt lấy nước cốt hành tỏi sả khi ướp đồ nướng giúp hương thơm thấm sâu mà không bị cháy đen phần xác băm trên lửa cao.'),
(283,3,'Ướp thấm thớ thịt / tạo hình cuốn khéo léo','Áo đều hỗn hợp gia vị hoặc lớp bột/vỏ cuốn quanh 500g thịt bò và 180g ớt chuông, massage nhẹ nhàng rồi để nghỉ 15–20 phút cho gia vị thẩm thấu trọn vẹn. Trường hợp cuốn chả/nem hoặc đổ khuôn bánh, thao tác đều tay vừa chặt để nhân kết dính nhưng không bị bục rách khi gặp nhiệt.',7,'Để nguyên liệu nghỉ đủ thời gian trước khi chiên nướng giúp lớp áo bột bám chắc và phần nhân bên trong mọng ngọt.'),
(283,4,'Pha nước chấm cân vị & sơ chế rau đồ chua ăn kèm','Nhặt rửa sạch 100g hành tây ngâm nước mát cho giòn tươi, bào sợi hoặc thái lát gọn gàng bày sẵn bên cạnh. Pha chén nước chấm chua ngọt hoặc muối ớt chanh sả sánh thơm theo khẩu vị vùng miền của món Bò nướng ống tre / vỉ sả ớt Tây Nguyên để cân bằng độ béo giòn.',5,'Luôn chuẩn bị xong rau sống và bát nước chấm trước khi chiên/nướng mẻ cuối để món ăn vừa ra lò là thưởng thức nóng giòn ngay.'),
(283,5,'Làm nóng dầu / lò nướng chuẩn nhiệt & làm chín đều lần 1','Làm nóng chảo dầu hoặc vỉ nướng/nồi chiên ở mức nhiệt vừa khoảng 165–175°C, xếp 500g thịt bò và 180g ớt chuông vào với khoảng cách thoáng đều nhau. Chiên hoặc nướng trở mặt nhịp nhàng trên lửa vừa để nhiệt dẫn sâu làm chín mềm ngọt hoàn toàn phần nhân bên trong.',9,'Kiểm tra nhiệt dầu bằng đầu đũa tre thấy sủi tăm nhỏ đều là đạt chuẩn 170°C, giúp vỏ không cháy sớm khi bên trong còn sống.');
INSERT INTO `recipe_steps` (`recipe_id`,`step_order`,`title`,`instruction`,`duration_mins`,`tip_note`) VALUES
(283,6,'Tăng nhiệt khóa giòn rụm vàng ươm bề mặt lần 2','Ở 2–3 phút cuối, tăng lên lửa vừa lớn (khoảng 190°C) hoặc phết thêm lớp dầu điều/mật ong mỏng để vỏ ngoài của Bò nướng ống tre / vỉ sả ớt Tây Nguyên chuyển sắc vàng óng ánh và nổ giòn rụm. Lắng nghe tiếng xèo giòn rộn rã và hương thơm phức lan tỏa khắp bếp thì gắp ra vỉ thưa cho ráo dầu thừa.',4,'Đặt đồ chiên nướng lên giá inox thoáng khí thay vì giấy thấm dầu chồng khít để hơi nước thoát hết, giữ độ giòn lâu gấp 3 lần.'),
(283,7,'Trình bày bắt mắt kèm rau thơm & thưởng thức nóng','Xếp thành phẩm vàng giòn ra đĩa lớn có bày sẵn 100g hành tây và điểm xuyết 15g mè trắng tươi xanh hài hòa màu sắc. Dọn kèm chén nước chấm sánh đậm ngay chính giữa mâm ăn cho 4 người thưởng thức khi vỏ ngoài còn nóng giòn rụm.',3,'Cắt miếng hoặc dọn ăn ngay trong vòng 10 phút sau khi rời bếp để cảm nhận trọn vẹn sự đối lập giòn ngoài - mềm ngọt bên trong.'),
(284,1,'Sơ chế sạch & cắt thái nguyên liệu nấu canh','Rửa sạch 450g sườn non và 180g bông cải xanh, khử mùi tanh bằng chút muối hạt và gừng đập dập rồi rửa lại thật ráo, cắt miếng vừa ăn dày khoảng 2.5–3cm. Đồng thời gọt rửa sạch 180g khoai tây và 150g su su, cắt khúc hoặc bổ múi cau đồng đều để khi nấu chín đều không bị nát.',10,'Phân loại riêng nhóm củ cứng nấu lâu và nhóm rau lá mềm nhanh chín để cho vào nồi theo đúng thứ tự chuẩn đầu bếp.'),
(284,2,'Ướp thấm gia vị nền cho nguyên liệu đạm','Cho phần đạm chính trong 450g sườn non và 180g bông cải xanh vào tô, ướp nhẹ với một nửa lượng 20g hành tím và 6g muối trong khoảng 10 phút. Đảo nhẹ tay cho gia vị áo đều bề mặt giúp miếng thịt, cá săn chắc và đậm đà từ bên trong khi thả vào nước canh.',9,'Không ướp quá mặn ở bước này để giữ vị thanh mát tự nhiên của nước canh sau khi hoàn tất.'),
(284,3,'Phi thơm hành tỏi & xào săn khóa ngọt nguyên liệu','Đặt nồi canh lên bếp ở lửa vừa, làm nóng 15ml dầu ăn rồi phi thơm phần 20g hành tím còn lại đến khi dậy mùi vàng óng. Trút nguyên liệu chính đã ướp vào đảo săn 2–3 phút cho bề mặt se lại, khóa trọn nước ngọt tự nhiên bên trong thớ thịt.',8,'Xào săn nguyên liệu đạm với hành tỏi phi trước khi đổ nước sôi giúp nước canh thơm ngọt đậm đà mà không hề tanh.'),
(284,4,'Đun sôi nước canh & hớt bọt giữ độ trong veo','Chế khoảng 1.1–1.3 lít nước (kết hợp lượng nước vừa ngập mặt nguyên liệu) vào nồi, bật lửa lớn đun đến khi sôi bùng rồi hạ ngay về lửa vừa. Dùng muôi hớt sạch lớp bọt đầu nổi lên trên mặt nước để nồi canh Canh sườn non hầm rau củ thập cẩm Đà Lạt đạt độ trong thanh đẹp mắt.',11,'Sử dụng nước ấm hoặc nước sôi khi chế vào cá tươi sẽ giúp cá không bao giờ bị tanh nồng dù để nguội.'),
(284,5,'Thả rau củ theo độ chín & cân chỉnh định lượng vị','Lần lượt cho 180g khoai tây và 150g su su vào nồi canh đang sôi vừa (nhóm củ quả lâu chín cho trước 5–7 phút, nhóm rau mềm cho sau 1–2 phút). Nêm phần 6g muối còn lại, khuấy nhẹ và nếm thử thấy vị chua thanh hoặc ngọt dịu cân bằng đúng khẩu phần 4 người.',11,'Không đậy kín nắp vung sau khi đã thả các loại rau xanh vào nồi để giữ màu xanh ngọc tươi tắn hấp dẫn.'),
(284,6,'Điểm hương rau thơm & múc canh dọn nóng','Khi toàn bộ nguyên liệu vừa chín tới mềm ngọt, rắc ngay 25g hành lá vào nồi rồi tắt bếp liền tay để giữ trọn tinh dầu thơm mát. Múc canh nóng hổi ra tô lớn, rắc thêm chút tiêu xay hoặc tỏi phi vàng và dùng ngay với cơm nóng.',6,'Các loại rau thơm như thì là, ngò gai, rau om hay lá lốt chỉ nên thả ngay khoảnh khắc tắt bếp để hương thơm bùng nổ nhất.'),
(285,1,'Sơ chế sạch & chuẩn bị nguyên liệu thuần chay','Rửa sạch toàn bộ nguyên liệu dưới vòi nước mát, để ráo tự nhiên trên rổ thưa gồm 200g bông cải xanh và 40g nấm hương cùng 120g ngô non, 100g đậu hà lan và 100g ớt chuông. Cắt thái đồng đều kích thước khoảng 3–4cm vừa gắp để khi chế biến chín cùng lúc và thấm đều gia vị thực vật.',4,'Thấm khô bề mặt đậu hũ và nấm bằng khăn giấy bếp trước khi chế biến giúp nguyên liệu săn chắc, không bị bắn dầu hay ra nước.'),
(285,2,'Xử lý độ giòn ngọt của nấm & rau củ','Đối với nhóm nấm và rau củ (120g ngô non, 100g đậu hà lan và 100g ớt chuông), ngâm nhanh qua nước muối loãng 3 phút rồi vắt nhẹ hoặc chần sơ 45 giây trong nước sôi, vớt ngay ra tô nước mát. Thao tác này giúp giữ trọn sắc màu tươi sáng tự nhiên, loại bỏ mùi ngái và tạo độ giòn ngọt thanh khiết cho món Rau củ thập cẩm Đà Lạt xào nấm hương dầu hào chay.',4,'Không ngâm nấm quá lâu trong nước lạnh vì nấm sẽ hút nước mạnh làm nhạt vị ngọt umami tự nhiên.'),
(285,3,'Pha chén sốt gia vị chay chuẩn định lượng','Chuẩn bị tô nhỏ, đong chính xác 30ml dầu hào chay khuấy đều cùng 30ml nước ấm hoặc nước ngâm nấm hương cho tan hoàn toàn đường và hạt nêm nấm. Nếm thử thấy vị mặn ngọt hài hòa, thanh dịu đúng tinh thần ẩm thực chay cho khẩu phần 4 người.',3,'Pha sẵn chén sốt trước khi bật bếp giúp kiểm soát chính xác định lượng từng gam và không bị cháy khét gia vị trên chảo nóng.'),
(285,4,'Phi thơm hành boaro & tạo nền hương thảo mộc','Làm nóng nồi hoặc chảo đáy dày trên lửa vừa, cho 15ml dầu thực vật vào láng đều mặt chảo rồi trút 25g hành boaro vào phi thơm. Đảo nhẹ tay khoảng 1–2 phút đến khi hành boaro chuyển sắc vàng óng và dậy mùi thơm dịu thì hạ lửa vừa.',3,'Hành boaro cháy nhanh hơn hành tím nên chỉ phi trên lửa vừa đến khi vừa chớm vàng thơm là cho nguyên liệu chính vào ngay.'),
(285,5,'Chế biến săn thấm nguyên liệu chính thuần thực vật','Cho 200g bông cải xanh và 40g nấm hương vào đảo đều hoặc áp chảo nhẹ hai mặt trên lửa vừa đến khi bề mặt săn vàng, sau đó rưới 2/3 chén sốt gia vị chay đã pha vào. Đảo nhẹ tay để sốt bám đều quanh từng thớ đậu và nấm mà không làm vỡ nát cấu trúc nguyên liệu.',5,'Dùng sạn gỗ đảo nhẹ từ dưới đáy chảo hất lên để miếng đậu hũ và nấm giữ nguyên hình khối vuông vắn đẹp mắt.'),
(285,6,'Phối hợp rau củ & cân chỉnh độ sánh thanh đạm','Tiếp tục cho 120g ngô non, 100g đậu hà lan và 100g ớt chuông cùng phần sốt còn lại vào nồi, điều chỉnh lửa vừa nấu thêm cho nguyên liệu chín mềm tới nhưng vẫn giữ độ giòn ngọt. Quan sát thấy nước sốt chuyển màu nâu hổ phách sóng sánh hoặc nước dùng trong thanh, hương thơm quyện đều khắp gian bếp.',5,'Chỉ nấu rau củ xanh vừa chín tới để bảo toàn tối đa lượng chất xơ và vitamin tự nhiên trong khẩu phần chay.'),
(285,7,'Hoàn thiện hương thơm & trình bày món chay thanh tịnh','Tắt bếp ngay khi món ăn đạt độ chín chuẩn, rắc đều hành boaro lá xanh và tiêu xay lên bề mặt để dậy mùi thơm tươi mới. Múc món Rau củ thập cẩm Đà Lạt xào nấm hương dầu hào chay ra đĩa sứ hoặc tô sâu lòng, thưởng thức nóng cùng cơm trắng hoặc bún tươi cho trọn vẹn 4 khẩu phần.',3,'Rắc rau thơm và tiêu ngay lúc vừa tắt bếp giúp tinh dầu tỏa hương thơm ngát mà lá rau không bị thâm xỉn màu.'),
(286,1,'Tuyển chọn & sơ chế tươi sạch nguyên liệu pha chế','Rửa sạch kỹ các nguyên liệu tươi gồm 200g đậu nành khô và 40g lá dứa, để ráo nước hoàn toàn trên khay sạch. Cắt lát, đập dập hoặc đong chuẩn xác từng gam/ml nguyên liệu cho khẩu phần 4 ly để hương vị đồng nhất tuyệt đối.',9,'Loại bỏ kỹ hạt chanh, tắc trước khi vắt hoặc nấu giúp thức uống giữ hậu vị thanh ngọt mà không hề bị đắng vỏ.'),
(286,2,'Ủ chiết xuất nền trà, cà phê hoặc nấu cốt thảo mộc','Đun nước đạt nhiệt độ chuẩn 90–95°C (không dùng nước sôi sùng sục làm cháy hương), tiến hành ủ chiết xuất hoặc nấu nhỏ lửa 200g đậu nành khô trong thời gian quy định. Lọc qua rây mịn hoặc túi vải sạch để thu được phần nước cốt trong trẻo, đậm hương tự nhiên không gợn cặn.',13,'Ủ trà/cà phê đúng nhiệt độ 92°C và đậy nắp kín giúp thu trọn tinh dầu thơm quyến rũ mà không chiết xuất vị chát gắt.'),
(286,3,'Xử lý lớp kem bông mịn / hỗn hợp sữa & trái cây','Đánh bông mượt hoặc khuấy hòa quyện phần nguyên liệu bổ trợ (30g sữa đặc và 1300ml nước lọc) cùng 70g đường phèn đến khi sánh mịn đồng nhất. Kiểm soát tốc độ khuấy/đánh đều tay để tạo kết cấu bồng bềnh mượt mà hoặc hòa tan hoàn toàn đường phèn mật ong.',9,'Nếu đánh kem trứng, nghiêng nhẹ âu 45 độ và đánh một chiều tốc độ cao cho tới khi nhấc que tạo chóp mềm bóng mượt không tanh.'),
(286,4,'Cân chỉnh định lượng độ ngọt & tầng hương tươi mát','Phối trộn phần nước cốt nền cùng hỗn hợp tạo vị theo đúng tỷ lệ vàng của món Sữa đậu nành lá dứa nóng kiểu chợ đêm Đà Lạt, khuấy nhẹ để các tầng hương hòa quyện. Nếu có nước cốt chanh hoặc mật ong rừng, cho vào khi nền nước đã hạ xuống dưới 55°C để bảo toàn trọn vẹn vitamin và hương thơm.',6,'Nếm thử trước khi thêm đá viên sao cho vị đậm hơn khoảng 15% để khi đá tan nhẹ là vừa vặn hoàn hảo.'),
(286,5,'Phối tầng thẩm mỹ ra ly thủy tinh nóng hoặc đá mát','Tráng ấm ly gốm (nếu dùng nóng) hoặc cho lượng đá viên tinh khiết vừa đủ vào ly thủy tinh cao, rót từ từ cốt thức uống vào 2/3 ly. Nhẹ nhàng rót lớp kem/sữa hoặc xếp lát trái cây tươi áp sát thành ly tạo hiệu ứng phân tầng đẹp mắt như quán chuyên nghiệp.',4,'Rót lớp kem hoặc sữa nhẹ nhàng qua lưng muỗng inox giúp hai tầng màu tách bạch sắc nét cực kỳ cuốn hút.'),
(286,6,'Điểm xuyết lá thơm trang trí & thưởng thức ngay','Trang trí trên mặt ly bằng lát nguyên liệu tươi, nhánh bạc hà/lá dứa hoặc rắc nhẹ bột cacao/hạt chia cho món Sữa đậu nành lá dứa nóng kiểu chợ đêm Đà Lạt thêm phần sinh động. Phục vụ ngay khi vừa pha chế xong cho 4 người để tận hưởng trọn vẹn hương thơm tươi mới sảng khoái nhất.',4,'Vỗ nhẹ lá bạc hà trong lòng bàn tay trước khi đặt lên miệng ly sẽ đánh thức tinh dầu the mát lan tỏa ngay khi nâng ly.'),
(287,1,'Sơ chế & chần sạch nguyên liệu xương thịt, hải sản','Rửa sạch 600g bún tươi và 200g tôm sú với muối hạt rồi chần nhanh trong nồi nước sôi có đập dập 1 nhánh gừng trong 2–3 phút trên lửa lớn để loại bỏ hoàn toàn bọt bẩn. Rửa lại dưới làn nước sạch cho thật trắng trẻo, đồng thời nhặt rửa sạch hành ngò và tiêu xay để ráo nước.',10,'Bước chần sơ và rửa lại bằng nước ấm là bí quyết vàng giúp nồi nước dùng trong vắt, thơm thanh và không bao giờ bị đục hay hôi.'),
(287,2,'Nướng thơm thảo mộc & ninh nền nước dùng ngọt thanh','Cho phần nguyên liệu tạo ngọt từ 600g bún tươi và 200g tôm sú cùng 60g sả đã nướng xém thơm vào nồi sâu lòng với khoảng 1.5–1.8 lít nước lọc. Đun sôi bùng trên lửa lớn rồi hạ ngay về lửa nhỏ liu riu, mở hé vung và hớt kỹ bọt nổi trên mặt để chiết xuất vị ngọt tự nhiên.',23,'Luôn duy trì mặt nước lăn tăn nhẹ thay vì đun sôi sùng sục lửa to để protein không bị nhũ hóa gây đục nước lèo.'),
(287,3,'Xào tạo màu & dậy hương đặc trưng vùng miền','Bắc chảo nhỏ lên bếp với 15ml dầu ăn trên lửa vừa, phi thơm phần hành tỏi sả băm còn lại rồi xào săn 200g mực ống và 200g thịt heo quay cùng 120g mắm cá linh trong 3–4 phút. Khi hỗn hợp dậy mùi thơm nồng nàn và lên sắc màu óng ả đặc trưng của món Bún mắm miền Tây tôm mực heo quay đậm đà thì tắt bếp.',8,'Xào riêng phần nguyên liệu tạo màu và gia vị thơm trước khi trút vào nồi nước dùng giúp tầng hương dậy lên rõ nét gấp đôi.'),
(287,4,'Sơ chế & cắt thái phần nhân topping xếp tô','Vớt phần thịt hoặc hải sản chín tới từ 600g bún tươi và 200g tôm sú ra ngâm ngay vào âu nước đun sôi để nguội giúp bề mặt săn giòn mọng nước, không bị thâm khô. Thái lát mỏng đều tay dày khoảng 3mm ngang thớ hoặc gỡ miếng vừa ăn, sắp riêng từng phần gọn gàng trên đĩa.',8,'Thái thịt ngang thớ với lưỡi dao thật sắc giúp lát thịt mềm mướt, khi chan nước dùng sôi lên sẽ phẳng đẹp không bị quăn cứng.');
INSERT INTO `recipe_steps` (`recipe_id`,`step_order`,`title`,`instruction`,`duration_mins`,`tip_note`) VALUES
(287,5,'Hợp nhất nồi nước lèo & nêm chuẩn định lượng','Trút phần sốt màu thơm vào nồi nước dùng đang sôi lăn tăn, nêm chính xác lượng 120g mắm cá linh còn lại cho vừa miệng 4 người ăn. Đun nhẹ thêm 5 phút ở lửa vừa để các tầng vị mặn dịu, ngọt hậu từ xương thịt và thảo mộc hòa quyện tròn trịa.',8,'Nên nêm nước mắm ngon ở giai đoạn cuối trên lửa nhỏ để giữ trọn hậu vị ngọt đạm và hương thơm mà không làm nước dùng bị chua.'),
(287,6,'Chần nóng sợi bánh/bún & chuẩn bị rau ăn kèm','Đun sôi một nồi nước riêng, cho phần sợi bún/phở/bánh trong 600g bún tươi và 200g tôm sú vào trụng nhanh 15–25 giây cho sợi mềm dẻo nóng hổi rồi vẩy thật ráo nước, chia đều vào 4 tô lớn. Chần sơ thêm rau ăn kèm (giá đỗ, rau xanh) nếu muốn dùng chín giòn.',7,'Trụng bún bánh ở nồi nước sôi riêng biệt giúp nước dùng chính không bị nhiễm tinh bột chua và tô bún luôn ráo sợi, thấm vị.'),
(287,7,'Xếp nhân hài hòa, chan nước dùng sôi & thưởng thức','Xếp đều các phần nhân thịt, hải sản lên mặt tô bún bánh, điểm xuyết hành ngò và tiêu xay lên trên cùng. Dùng muôi múc nước dùng đang sôi thật già chan ngập xăm xắp mặt nguyên liệu để làm chín thơm hành ngò, dọn nóng ngay kèm chanh ớt tươi.',6,'Tráng nóng tô sứ bằng nước sôi trước khi xếp bún giúp tô món nước giữ nhiệt bốc khói nghi ngút suốt bữa ăn.'),
(288,1,'Sơ chế & chần sạch nguyên liệu xương thịt, hải sản','Rửa sạch 450g hủ tiếu dai và 350g sườn non với muối hạt rồi chần nhanh trong nồi nước sôi có đập dập 1 nhánh gừng trong 2–3 phút trên lửa lớn để loại bỏ hoàn toàn bọt bẩn. Rửa lại dưới làn nước sạch cho thật trắng trẻo, đồng thời nhặt rửa sạch 180g củ cải trắng để ráo nước.',11,'Bước chần sơ và rửa lại bằng nước ấm là bí quyết vàng giúp nồi nước dùng trong vắt, thơm thanh và không bao giờ bị đục hay hôi.'),
(288,2,'Nướng thơm thảo mộc & ninh nền nước dùng ngọt thanh','Cho phần nguyên liệu tạo ngọt từ 450g hủ tiếu dai và 350g sườn non cùng 25g tỏi đã nướng xém thơm vào nồi sâu lòng với khoảng 1.5–1.8 lít nước lọc. Đun sôi bùng trên lửa lớn rồi hạ ngay về lửa nhỏ liu riu, mở hé vung và hớt kỹ bọt nổi trên mặt để chiết xuất vị ngọt tự nhiên.',25,'Luôn duy trì mặt nước lăn tăn nhẹ thay vì đun sôi sùng sục lửa to để protein không bị nhũ hóa gây đục nước lèo.'),
(288,3,'Xào tạo màu & dậy hương đặc trưng vùng miền','Bắc chảo nhỏ lên bếp với 15ml dầu ăn trên lửa vừa, phi thơm phần hành tỏi sả băm còn lại rồi xào săn 200g thịt heo (nạc vai) và 200g tôm sú cùng gia vị chuẩn định lượng trong 3–4 phút. Khi hỗn hợp dậy mùi thơm nồng nàn và lên sắc màu óng ả đặc trưng của món Hủ tiếu Mỹ Tho Tiền Giang tôm thịt sườn non thì tắt bếp.',10,'Xào riêng phần nguyên liệu tạo màu và gia vị thơm trước khi trút vào nồi nước dùng giúp tầng hương dậy lên rõ nét gấp đôi.'),
(288,4,'Sơ chế & cắt thái phần nhân topping xếp tô','Vớt phần thịt hoặc hải sản chín tới từ 450g hủ tiếu dai và 350g sườn non ra ngâm ngay vào âu nước đun sôi để nguội giúp bề mặt săn giòn mọng nước, không bị thâm khô. Thái lát mỏng đều tay dày khoảng 3mm ngang thớ hoặc gỡ miếng vừa ăn, sắp riêng từng phần gọn gàng trên đĩa.',10,'Thái thịt ngang thớ với lưỡi dao thật sắc giúp lát thịt mềm mướt, khi chan nước dùng sôi lên sẽ phẳng đẹp không bị quăn cứng.'),
(288,5,'Hợp nhất nồi nước lèo & nêm chuẩn định lượng','Trút phần sốt màu thơm vào nồi nước dùng đang sôi lăn tăn, nêm chính xác lượng gia vị chuẩn định lượng còn lại cho vừa miệng 4 người ăn. Đun nhẹ thêm 5 phút ở lửa vừa để các tầng vị mặn dịu, ngọt hậu từ xương thịt và thảo mộc hòa quyện tròn trịa.',10,'Nên nêm nước mắm ngon ở giai đoạn cuối trên lửa nhỏ để giữ trọn hậu vị ngọt đạm và hương thơm mà không làm nước dùng bị chua.'),
(288,6,'Chần nóng sợi bánh/bún & chuẩn bị rau ăn kèm','Đun sôi một nồi nước riêng, cho phần sợi bún/phở/bánh trong 450g hủ tiếu dai và 350g sườn non vào trụng nhanh 15–25 giây cho sợi mềm dẻo nóng hổi rồi vẩy thật ráo nước, chia đều vào 4 tô lớn. Chần sơ thêm rau ăn kèm (180g củ cải trắng) nếu muốn dùng chín giòn.',8,'Trụng bún bánh ở nồi nước sôi riêng biệt giúp nước dùng chính không bị nhiễm tinh bột chua và tô bún luôn ráo sợi, thấm vị.'),
(288,7,'Xếp nhân hài hòa, chan nước dùng sôi & thưởng thức','Xếp đều các phần nhân thịt, hải sản lên mặt tô bún bánh, điểm xuyết 50g rau hẹ lên trên cùng. Dùng muôi múc nước dùng đang sôi thật già chan ngập xăm xắp mặt nguyên liệu để làm chín thơm hành ngò, dọn nóng ngay kèm chanh ớt tươi.',6,'Tráng nóng tô sứ bằng nước sôi trước khi xếp bún giúp tô món nước giữ nhiệt bốc khói nghi ngút suốt bữa ăn.'),
(289,1,'Sơ chế & chần sạch nguyên liệu xương thịt, hải sản','Rửa sạch 550g sợi bánh canh và 750g giò heo với muối hạt rồi chần nhanh trong nồi nước sôi có đập dập 1 nhánh gừng trong 2–3 phút trên lửa lớn để loại bỏ hoàn toàn bọt bẩn. Rửa lại dưới làn nước sạch cho thật trắng trẻo, đồng thời nhặt rửa sạch 200g củ cải trắng để ráo nước.',12,'Bước chần sơ và rửa lại bằng nước ấm là bí quyết vàng giúp nồi nước dùng trong vắt, thơm thanh và không bao giờ bị đục hay hôi.'),
(289,2,'Nướng thơm thảo mộc & ninh nền nước dùng ngọt thanh','Cho phần nguyên liệu tạo ngọt từ 550g sợi bánh canh và 750g giò heo cùng hành tím và tỏi băm nhỏ đã nướng xém thơm vào nồi sâu lòng với khoảng 1.5–1.8 lít nước lọc. Đun sôi bùng trên lửa lớn rồi hạ ngay về lửa nhỏ liu riu, mở hé vung và hớt kỹ bọt nổi trên mặt để chiết xuất vị ngọt tự nhiên.',28,'Luôn duy trì mặt nước lăn tăn nhẹ thay vì đun sôi sùng sục lửa to để protein không bị nhũ hóa gây đục nước lèo.'),
(289,3,'Xào tạo màu & dậy hương đặc trưng vùng miền','Bắc chảo nhỏ lên bếp với 15ml dầu ăn trên lửa vừa, phi thơm phần hành tỏi sả băm còn lại rồi xào săn 200g thịt heo (nạc) và 100g cà rốt cùng 35ml nước mắm trong 3–4 phút. Khi hỗn hợp dậy mùi thơm nồng nàn và lên sắc màu óng ả đặc trưng của món Bánh canh giò heo Trảng Bàng Tây Ninh thì tắt bếp.',10,'Xào riêng phần nguyên liệu tạo màu và gia vị thơm trước khi trút vào nồi nước dùng giúp tầng hương dậy lên rõ nét gấp đôi.'),
(289,4,'Sơ chế & cắt thái phần nhân topping xếp tô','Vớt phần thịt hoặc hải sản chín tới từ 550g sợi bánh canh và 750g giò heo ra ngâm ngay vào âu nước đun sôi để nguội giúp bề mặt săn giòn mọng nước, không bị thâm khô. Thái lát mỏng đều tay dày khoảng 3mm ngang thớ hoặc gỡ miếng vừa ăn, sắp riêng từng phần gọn gàng trên đĩa.',10,'Thái thịt ngang thớ với lưỡi dao thật sắc giúp lát thịt mềm mướt, khi chan nước dùng sôi lên sẽ phẳng đẹp không bị quăn cứng.'),
(289,5,'Hợp nhất nồi nước lèo & nêm chuẩn định lượng','Trút phần sốt màu thơm vào nồi nước dùng đang sôi lăn tăn, nêm chính xác lượng 35ml nước mắm còn lại cho vừa miệng 4 người ăn. Đun nhẹ thêm 5 phút ở lửa vừa để các tầng vị mặn dịu, ngọt hậu từ xương thịt và thảo mộc hòa quyện tròn trịa.',10,'Nên nêm nước mắm ngon ở giai đoạn cuối trên lửa nhỏ để giữ trọn hậu vị ngọt đạm và hương thơm mà không làm nước dùng bị chua.'),
(289,6,'Chần nóng sợi bánh/bún & chuẩn bị rau ăn kèm','Đun sôi một nồi nước riêng, cho phần sợi bún/phở/bánh trong 550g sợi bánh canh và 750g giò heo vào trụng nhanh 15–25 giây cho sợi mềm dẻo nóng hổi rồi vẩy thật ráo nước, chia đều vào 4 tô lớn. Chần sơ thêm rau ăn kèm (200g củ cải trắng) nếu muốn dùng chín giòn.',8,'Trụng bún bánh ở nồi nước sôi riêng biệt giúp nước dùng chính không bị nhiễm tinh bột chua và tô bún luôn ráo sợi, thấm vị.'),
(289,7,'Xếp nhân hài hòa, chan nước dùng sôi & thưởng thức','Xếp đều các phần nhân thịt, hải sản lên mặt tô bún bánh, điểm xuyết 25g hành phi và 35g hành lá lên trên cùng. Dùng muôi múc nước dùng đang sôi thật già chan ngập xăm xắp mặt nguyên liệu để làm chín thơm hành ngò, dọn nóng ngay kèm chanh ớt tươi.',7,'Tráng nóng tô sứ bằng nước sôi trước khi xếp bún giúp tô món nước giữ nhiệt bốc khói nghi ngút suốt bữa ăn.'),
(290,1,'Sơ chế & chần sạch nguyên liệu xương thịt, hải sản','Rửa sạch 500g cá lóc và 200g tôm sú với muối hạt rồi chần nhanh trong nồi nước sôi có đập dập 1 nhánh gừng trong 2–3 phút trên lửa lớn để loại bỏ hoàn toàn bọt bẩn. Rửa lại dưới làn nước sạch cho thật trắng trẻo, đồng thời nhặt rửa sạch 60g rau hẹ để ráo nước.',9,'Bước chần sơ và rửa lại bằng nước ấm là bí quyết vàng giúp nồi nước dùng trong vắt, thơm thanh và không bao giờ bị đục hay hôi.'),
(290,2,'Nướng thơm thảo mộc & ninh nền nước dùng ngọt thanh','Cho phần nguyên liệu tạo ngọt từ 500g cá lóc và 200g tôm sú cùng 50g sả đã nướng xém thơm vào nồi sâu lòng với khoảng 1.5–1.8 lít nước lọc. Đun sôi bùng trên lửa lớn rồi hạ ngay về lửa nhỏ liu riu, mở hé vung và hớt kỹ bọt nổi trên mặt để chiết xuất vị ngọt tự nhiên.',21,'Luôn duy trì mặt nước lăn tăn nhẹ thay vì đun sôi sùng sục lửa to để protein không bị nhũ hóa gây đục nước lèo.'),
(290,3,'Xào tạo màu & dậy hương đặc trưng vùng miền','Bắc chảo nhỏ lên bếp với 15ml dầu ăn trên lửa vừa, phi thơm phần hành tỏi sả băm còn lại rồi xào săn 180g thịt heo quay và 600g bún tươi cùng 80g mắm cá linh trong 3–4 phút. Khi hỗn hợp dậy mùi thơm nồng nàn và lên sắc màu óng ả đặc trưng của món Bún nước lèo Sóc Trăng cá lóc tôm tươi thì tắt bếp.',8,'Xào riêng phần nguyên liệu tạo màu và gia vị thơm trước khi trút vào nồi nước dùng giúp tầng hương dậy lên rõ nét gấp đôi.'),
(290,4,'Sơ chế & cắt thái phần nhân topping xếp tô','Vớt phần thịt hoặc hải sản chín tới từ 500g cá lóc và 200g tôm sú ra ngâm ngay vào âu nước đun sôi để nguội giúp bề mặt săn giòn mọng nước, không bị thâm khô. Thái lát mỏng đều tay dày khoảng 3mm ngang thớ hoặc gỡ miếng vừa ăn, sắp riêng từng phần gọn gàng trên đĩa.',8,'Thái thịt ngang thớ với lưỡi dao thật sắc giúp lát thịt mềm mướt, khi chan nước dùng sôi lên sẽ phẳng đẹp không bị quăn cứng.'),
(290,5,'Hợp nhất nồi nước lèo & nêm chuẩn định lượng','Trút phần sốt màu thơm vào nồi nước dùng đang sôi lăn tăn, nêm chính xác lượng 80g mắm cá linh còn lại cho vừa miệng 4 người ăn. Đun nhẹ thêm 5 phút ở lửa vừa để các tầng vị mặn dịu, ngọt hậu từ xương thịt và thảo mộc hòa quyện tròn trịa.',8,'Nên nêm nước mắm ngon ở giai đoạn cuối trên lửa nhỏ để giữ trọn hậu vị ngọt đạm và hương thơm mà không làm nước dùng bị chua.'),
(290,6,'Chần nóng sợi bánh/bún & chuẩn bị rau ăn kèm','Đun sôi một nồi nước riêng, cho phần sợi bún/phở/bánh trong 500g cá lóc và 200g tôm sú vào trụng nhanh 15–25 giây cho sợi mềm dẻo nóng hổi rồi vẩy thật ráo nước, chia đều vào 4 tô lớn. Chần sơ thêm rau ăn kèm (giá đỗ, rau xanh) nếu muốn dùng chín giòn.',6,'Trụng bún bánh ở nồi nước sôi riêng biệt giúp nước dùng chính không bị nhiễm tinh bột chua và tô bún luôn ráo sợi, thấm vị.'),
(290,7,'Xếp nhân hài hòa, chan nước dùng sôi & thưởng thức','Xếp đều các phần nhân thịt, hải sản lên mặt tô bún bánh, điểm xuyết 60g rau hẹ lên trên cùng. Dùng muôi múc nước dùng đang sôi thật già chan ngập xăm xắp mặt nguyên liệu để làm chín thơm hành ngò, dọn nóng ngay kèm chanh ớt tươi.',5,'Tráng nóng tô sứ bằng nước sôi trước khi xếp bún giúp tô món nước giữ nhiệt bốc khói nghi ngút suốt bữa ăn.'),
(291,1,'Sơ chế & chần sạch nguyên liệu xương thịt, hải sản','Rửa sạch 650g cá basa và 250g măng chua với muối hạt rồi chần nhanh trong nồi nước sôi có đập dập 1 nhánh gừng trong 2–3 phút trên lửa lớn để loại bỏ hoàn toàn bọt bẩn. Rửa lại dưới làn nước sạch cho thật trắng trẻo, đồng thời nhặt rửa sạch 150g dứa để ráo nước.',7,'Bước chần sơ và rửa lại bằng nước ấm là bí quyết vàng giúp nồi nước dùng trong vắt, thơm thanh và không bao giờ bị đục hay hôi.');
INSERT INTO `recipe_steps` (`recipe_id`,`step_order`,`title`,`instruction`,`duration_mins`,`tip_note`) VALUES
(291,2,'Nướng thơm thảo mộc & ninh nền nước dùng ngọt thanh','Cho phần nguyên liệu tạo ngọt từ 650g cá basa và 250g măng chua cùng 25g tỏi đã nướng xém thơm vào nồi sâu lòng với khoảng 1.5–1.8 lít nước lọc. Đun sôi bùng trên lửa lớn rồi hạ ngay về lửa nhỏ liu riu, mở hé vung và hớt kỹ bọt nổi trên mặt để chiết xuất vị ngọt tự nhiên.',16,'Luôn duy trì mặt nước lăn tăn nhẹ thay vì đun sôi sùng sục lửa to để protein không bị nhũ hóa gây đục nước lèo.'),
(291,3,'Xào tạo màu & dậy hương đặc trưng vùng miền','Bắc chảo nhỏ lên bếp với 15ml dầu ăn trên lửa vừa, phi thơm phần hành tỏi sả băm còn lại rồi xào săn 180g cà chua và 150g bông điên điển cùng 40g me vắt trong 3–4 phút. Khi hỗn hợp dậy mùi thơm nồng nàn và lên sắc màu óng ả đặc trưng của món Lẩu cá basa măng chua rau đồng miền Tây thì tắt bếp.',6,'Xào riêng phần nguyên liệu tạo màu và gia vị thơm trước khi trút vào nồi nước dùng giúp tầng hương dậy lên rõ nét gấp đôi.'),
(291,4,'Sơ chế & cắt thái phần nhân topping xếp tô','Vớt phần thịt hoặc hải sản chín tới từ 650g cá basa và 250g măng chua ra ngâm ngay vào âu nước đun sôi để nguội giúp bề mặt săn giòn mọng nước, không bị thâm khô. Thái lát mỏng đều tay dày khoảng 3mm ngang thớ hoặc gỡ miếng vừa ăn, sắp riêng từng phần gọn gàng trên đĩa.',6,'Thái thịt ngang thớ với lưỡi dao thật sắc giúp lát thịt mềm mướt, khi chan nước dùng sôi lên sẽ phẳng đẹp không bị quăn cứng.'),
(291,5,'Hợp nhất nồi nước lèo & nêm chuẩn định lượng','Trút phần sốt màu thơm vào nồi nước dùng đang sôi lăn tăn, nêm chính xác lượng 40g me vắt còn lại cho vừa miệng 4 người ăn. Đun nhẹ thêm 5 phút ở lửa vừa để các tầng vị mặn dịu, ngọt hậu từ xương thịt và thảo mộc hòa quyện tròn trịa.',6,'Nên nêm nước mắm ngon ở giai đoạn cuối trên lửa nhỏ để giữ trọn hậu vị ngọt đạm và hương thơm mà không làm nước dùng bị chua.'),
(291,6,'Chần nóng sợi bánh/bún & chuẩn bị rau ăn kèm','Đun sôi một nồi nước riêng, cho phần sợi bún/phở/bánh trong 650g cá basa và 250g măng chua vào trụng nhanh 15–25 giây cho sợi mềm dẻo nóng hổi rồi vẩy thật ráo nước, chia đều vào 4 tô lớn. Chần sơ thêm rau ăn kèm (150g dứa) nếu muốn dùng chín giòn.',5,'Trụng bún bánh ở nồi nước sôi riêng biệt giúp nước dùng chính không bị nhiễm tinh bột chua và tô bún luôn ráo sợi, thấm vị.'),
(291,7,'Xếp nhân hài hòa, chan nước dùng sôi & thưởng thức','Xếp đều các phần nhân thịt, hải sản lên mặt tô bún bánh, điểm xuyết 25g rau om lên trên cùng. Dùng muôi múc nước dùng đang sôi thật già chan ngập xăm xắp mặt nguyên liệu để làm chín thơm hành ngò, dọn nóng ngay kèm chanh ớt tươi.',4,'Tráng nóng tô sứ bằng nước sôi trước khi xếp bún giúp tô món nước giữ nhiệt bốc khói nghi ngút suốt bữa ăn.'),
(292,1,'Sơ chế sạch & cắt thái nguyên liệu đúng kích cỡ','Rửa sạch 900g thịt vịt và 400g khoai môn cùng 250g rau muống dưới vòi nước mát rồi để thật ráo trên rổ thưa. Dùng dao sắc cắt thái nguyên liệu thành từng khúc hoặc khối vuông đều đặn khoảng 3.5–4cm để khi kho hầm giữ nguyên hình dáng đẹp mắt mà không bị vụn nát.',10,'Cắt miếng thịt/cá dày dặn đồng đều giúp quá trình kho lâu trên lửa nhỏ thớ thịt mềm rục mà vẫn giữ trọn độ mọng ngọt bên trong.'),
(292,2,'Khử mùi tự nhiên & làm săn sạch bề mặt nguyên liệu','Chà nhẹ phần đạm chính trong 900g thịt vịt và 400g khoai môn với chút muối hạt, lát gừng đập dập hoặc chần sơ qua nước sôi 90 giây rồi rửa sạch lại bằng nước ấm, để ráo hoàn toàn. Công đoạn này loại bỏ triệt để tạp chất và mùi tanh hôi, giúp nước sốt món Vịt nấu khoai môn nước cốt dừa miền Tây trong bóng thơm ngon.',8,'Sau khi chần hoặc rửa sạch, để nguyên liệu ráo nước ít nhất 5 phút trước khi ướp để gia vị rút sâu trực tiếp vào từng thớ thịt.'),
(292,3,'Pha hỗn hợp gia vị & ướp thấm chuẩn định lượng','Cho 900g thịt vịt và 400g khoai môn vào tô lớn, ướp cùng một nửa 35g gừng và 20g tỏi băm nhỏ và định lượng chuẩn gia vị chuẩn định lượng, đảo nhẹ tay cho gia vị phủ kín đều các mặt. Bọc kín tô và để nguyên liệu nghỉ thấm vị tối thiểu 20 phút ở nhiệt độ phòng (hoặc ngăn mát tủ lạnh).',10,'Ướp đủ tối thiểu 20 phút trước khi bắc lên bếp là chìa khóa để tâm miếng thịt/cá đậm đà đồng nhất với lớp sốt bên ngoài.'),
(292,4,'Thắng nước màu cánh gián & phi dậy hương hành tỏi','Đặt nồi đáy dày lên bếp ở lửa vừa nhỏ, thắng nhẹ 15g đường với 15ml dầu ăn đến khi chuyển sắc nâu cánh gián óng ả thì cho ngay phần 35g gừng và 20g tỏi còn lại vào phi thơm lừng. Hương caramel dịu ngọt quyện cùng tinh dầu hành tỏi sả tạo nền màu nâu hổ phách truyền thống đầy cuốn hút.',7,'Canh kỹ khoảnh khắc đường vừa chuyển màu cánh gián là hạ lửa nhỏ nhất ngay để nước màu bóng đẹp mà không bao giờ bị đắng.'),
(292,5,'Đảo săn hai mặt khóa ngọt nguyên liệu chính','Tăng lên lửa vừa lớn, gắp từng miếng trong 900g thịt vịt và 400g khoai môn vào nồi đảo đều hoặc trở nhẹ hai mặt trong 4–5 phút cho săn chắc và bám đều lớp màu nâu óng. Khi bề mặt nguyên liệu se vàng thơm phức mới trút phần nước ướp còn lại trong tô vào đun sôi nhẹ.',10,'Đối với cá kho, chỉ lật cá một lần lúc cá vừa săn mặt trên lửa vừa để khúc cá nguyên vẹn không bị tróc da hay vỡ nát.'),
(292,6,'Kho/om liu riu lửa nhỏ thấm đẫm cùng nước dừa/nước dùng','Chế 500ml nước dừa tươi và 120ml nước cốt dừa xâm xắp mặt nguyên liệu (xếp thêm 250g rau muống nếu có), đun sôi bùng một dạo hớt sạch bọt rồi hạ ngay về mức lửa nhỏ liu riu nhất. Kho êm đềm không đậy kín nắp để từng thớ nguyên liệu chín mềm thấm đẫm gia vị và nước sốt rút dần sóng sánh.',18,'Luôn dùng nước sôi hoặc nước dừa ấm khi châm thêm vào nồi kho đang nóng để thịt cá không bị sượng cứng trở lại.'),
(292,7,'Thu sánh nước sốt óng ả & trình bày thưởng thức nóng','Khi nước kho rút còn khoảng 1/3 sánh kẹo óng ánh áo đều quanh nguyên liệu và xiên đũa thấy mềm mọng vừa ý, rắc hành ngò và tiêu xay lên mặt rồi tắt bếp. Múc món Vịt nấu khoai môn nước cốt dừa miền Tây ra đĩa sâu lòng hoặc niêu đất giữ nhiệt, dọn ăn nóng cùng cơm trắng dẻo thơm cho 4 người.',7,'Giữ lại một lượng nước sốt sánh kẹo vừa đủ dưới đáy nồi để chan cơm hoặc chấm kèm rau luộc sẽ tròn vị đưa cơm gấp bội.'),
(293,1,'Sơ chế tươi sạch & ngâm giòn rau củ thảo mộc','Nhặt rửa kỹ 120g dứa và 200g rau sống cùng 70g hành lá và 60g đậu phộng qua nước muối loãng rồi tráng nước đun sôi để nguội. Với các loại củ quả bào sợi hoặc thái lát mỏng, ngâm vào âu nước đá lạnh pha chút chanh đường trong 10 phút rồi vắt ráo để giữ độ trắng giòn sần sật.',12,'Rau củ làm gỏi và món cuốn phải quay rổ hoặc thấm thật ráo nước để khi trộn nước mắm không bị loãng nhạt.'),
(293,2,'Làm chín tới phần nhân đạm giữ trọn độ ngọt mọng','Xử lý phần nguyên liệu chính (850g cá lóc và 20 lá bánh tráng): luộc hấp cùng lát gừng sả đập dập hoặc xào lửa lớn vừa chín tới, sau đó làm nguội nhanh rồi thái lát mỏng / xé sợi đều đặn. Nếu món có pha bột bánh gạo/bột năng, khuấy tan bột với nước đúng tỷ lệ và để bột nghỉ 15 phút cho nở mịn.',15,'Ngâm tôm hoặc thịt luộc qua bát nước sôi để nguội có vài viên đá giúp màu sắc tươi hồng và thớ thịt giòn ngọt không bị khô.'),
(293,3,'Rang vàng đậu phộng mè thơm & phi hành tỏi giòn','Bắc chảo nhỏ lên lửa nhỏ, rang chín vàng thơm đậu phộng/mè hoặc làm mỡ hành xanh mướt và phi vàng giòn hành tím và tỏi băm nhỏ. Vớt hành tỏi phi ra đĩa riêng để nguội giòn tan, giữ lại phần dầu thơm óng ánh để phết bánh hoặc rưới bóng mặt món ăn.',8,'Tắt bếp ngay khi hành phi chuyển vàng sáng vì nhiệt dư trong dầu nóng sẽ tiếp tục làm hành sẫm màu thêm một nấc hoàn hảo.'),
(293,4,'Pha nước mắm chấm / sốt trộn tỷ lệ vàng chua ngọt','Hòa tan hoàn toàn đường cùng 35g me vắt và nước ấm trong chén sâu lòng, khuấy đến khi hơi sánh nhẹ mới cho tỏi ớt băm nhuyễn và nước cốt chanh/tắc vào sau cùng. Công thức pha này giúp tỏi ớt nổi đều đẹp mắt trên bề mặt bát nước chấm chuẩn vị Cá lóc nướng mỡ hành đậu phộng cuốn bánh tráng.',8,'Băm tỏi ớt thật ráo trên thớt khô và cho vào sau khi đường mắm đã nguội thì tỏi ớt sẽ nổi bồng bềnh 100% không bị chìm đáy.'),
(293,5,'Phối trộn thấm vị / tráng hấp & cuốn đều tay','Tiến hành tráng hấp bánh mỏng mượt hoặc trải bánh cuốn gọn gàng 850g cá lóc và 20 lá bánh tráng cùng 120g dứa và 200g rau sống; nếu là món gỏi trộn thì rưới từ từ 2/3 lượng sốt chua ngọt vào bóp nhẹ tay cho thấm đều trong 3 phút. Giữ lực tay nhẹ nhàng để rau củ không bị dập nát mà vẫn ngấm trọn vị mặn chua ngọt hài hòa.',11,'Chia nước sốt gỏi làm 2 lần trộn và chắt bỏ phần nước tiết ra ở lần đầu giúp đĩa gỏi khô ráo, đậm đà như ngoài hàng.'),
(293,6,'Bày biện ngũ sắc hài hòa & rắc topping giòn bùi','Xếp món Cá lóc nướng mỡ hành đậu phộng cuốn bánh tráng ngay ngắn ra đĩa sứ trắng rộng, rải đều phần nhân tôm thịt sắc nét lên trên và rắc phủ 70g hành lá và 60g đậu phộng thơm giòn. Dọn kèm chén nước chấm đậm đà cho 4 người thưởng thức ngay khi rau bánh còn tươi giòn mướt mịn.',6,'Chỉ rắc đậu phộng rang và hành phi ngay trước lúc mang ra bàn ăn để giữ nguyên độ giòn tan bùi béo.'),
(294,1,'Sơ chế tươi sạch & ngâm giòn rau củ thảo mộc','Nhặt rửa kỹ 120g dưa leo và 100g rau sống cùng hành ngò và tiêu xay qua nước muối loãng rồi tráng nước đun sôi để nguội. Với các loại củ quả bào sợi hoặc thái lát mỏng, ngâm vào âu nước đá lạnh pha chút chanh đường trong 10 phút rồi vắt ráo để giữ độ trắng giòn sần sật.',13,'Rau củ làm gỏi và món cuốn phải quay rổ hoặc thấm thật ráo nước để khi trộn nước mắm không bị loãng nhạt.'),
(294,2,'Làm chín tới phần nhân đạm giữ trọn độ ngọt mọng','Xử lý phần nguyên liệu chính (500g bánh tằm và 250g thịt heo (nạc vai)): luộc hấp cùng lát gừng sả đập dập hoặc xào lửa lớn vừa chín tới, sau đó làm nguội nhanh rồi thái lát mỏng / xé sợi đều đặn. Nếu món có pha bột bánh gạo/bột năng, khuấy tan bột với nước đúng tỷ lệ và để bột nghỉ 15 phút cho nở mịn.',16,'Ngâm tôm hoặc thịt luộc qua bát nước sôi để nguội có vài viên đá giúp màu sắc tươi hồng và thớ thịt giòn ngọt không bị khô.'),
(294,3,'Rang vàng đậu phộng mè thơm & phi hành tỏi giòn','Bắc chảo nhỏ lên lửa nhỏ, rang chín vàng thơm đậu phộng/mè hoặc làm mỡ hành xanh mướt và phi vàng giòn hành tím và tỏi băm nhỏ. Vớt hành tỏi phi ra đĩa riêng để nguội giòn tan, giữ lại phần dầu thơm óng ánh để phết bánh hoặc rưới bóng mặt món ăn.',9,'Tắt bếp ngay khi hành phi chuyển vàng sáng vì nhiệt dư trong dầu nóng sẽ tiếp tục làm hành sẫm màu thêm một nấc hoàn hảo.'),
(294,4,'Pha nước mắm chấm / sốt trộn tỷ lệ vàng chua ngọt','Hòa tan hoàn toàn đường cùng 35ml nước mắm và 25g đường và nước ấm trong chén sâu lòng, khuấy đến khi hơi sánh nhẹ mới cho tỏi ớt băm nhuyễn và nước cốt chanh/tắc vào sau cùng. Công thức pha này giúp tỏi ớt nổi đều đẹp mắt trên bề mặt bát nước chấm chuẩn vị Bánh tằm bì thịt xíu mại cốt dừa miền Tây.',9,'Băm tỏi ớt thật ráo trên thớt khô và cho vào sau khi đường mắm đã nguội thì tỏi ớt sẽ nổi bồng bềnh 100% không bị chìm đáy.'),
(294,5,'Phối trộn thấm vị / tráng hấp & cuốn đều tay','Tiến hành tráng hấp bánh mỏng mượt hoặc trải bánh cuốn gọn gàng 500g bánh tằm và 250g thịt heo (nạc vai) cùng 120g dưa leo và 100g rau sống; nếu là món gỏi trộn thì rưới từ từ 2/3 lượng sốt chua ngọt vào bóp nhẹ tay cho thấm đều trong 3 phút. Giữ lực tay nhẹ nhàng để rau củ không bị dập nát mà vẫn ngấm trọn vị mặn chua ngọt hài hòa.',12,'Chia nước sốt gỏi làm 2 lần trộn và chắt bỏ phần nước tiết ra ở lần đầu giúp đĩa gỏi khô ráo, đậm đà như ngoài hàng.'),
(294,6,'Bày biện ngũ sắc hài hòa & rắc topping giòn bùi','Xếp món Bánh tằm bì thịt xíu mại cốt dừa miền Tây ngay ngắn ra đĩa sứ trắng rộng, rải đều phần nhân tôm thịt sắc nét lên trên và rắc phủ hành ngò và tiêu xay thơm giòn. Dọn kèm chén nước chấm đậm đà cho 4 người thưởng thức ngay khi rau bánh còn tươi giòn mướt mịn.',6,'Chỉ rắc đậu phộng rang và hành phi ngay trước lúc mang ra bàn ăn để giữ nguyên độ giòn tan bùi béo.');
INSERT INTO `recipe_steps` (`recipe_id`,`step_order`,`title`,`instruction`,`duration_mins`,`tip_note`) VALUES
(295,1,'Sơ chế tươi sạch & ngâm giòn rau củ thảo mộc','Nhặt rửa kỹ 120g chuối xanh, 120g dứa và 150g dưa leo cùng hành ngò và tiêu xay qua nước muối loãng rồi tráng nước đun sôi để nguội. Với các loại củ quả bào sợi hoặc thái lát mỏng, ngâm vào âu nước đá lạnh pha chút chanh đường trong 10 phút rồi vắt ráo để giữ độ trắng giòn sần sật.',11,'Rau củ làm gỏi và món cuốn phải quay rổ hoặc thấm thật ráo nước để khi trộn nước mắm không bị loãng nhạt.'),
(295,2,'Làm chín tới phần nhân đạm giữ trọn độ ngọt mọng','Xử lý phần nguyên liệu chính (600g bò tơ và 20 lá bánh tráng): luộc hấp cùng lát gừng sả đập dập hoặc xào lửa lớn vừa chín tới, sau đó làm nguội nhanh rồi thái lát mỏng / xé sợi đều đặn. Nếu món có pha bột bánh gạo/bột năng, khuấy tan bột với nước đúng tỷ lệ và để bột nghỉ 15 phút cho nở mịn.',12,'Ngâm tôm hoặc thịt luộc qua bát nước sôi để nguội có vài viên đá giúp màu sắc tươi hồng và thớ thịt giòn ngọt không bị khô.'),
(295,3,'Rang vàng đậu phộng mè thơm & phi hành tỏi giòn','Bắc chảo nhỏ lên lửa nhỏ, rang chín vàng thơm đậu phộng/mè hoặc làm mỡ hành xanh mướt và phi vàng giòn 40g sả. Vớt hành tỏi phi ra đĩa riêng để nguội giòn tan, giữ lại phần dầu thơm óng ánh để phết bánh hoặc rưới bóng mặt món ăn.',8,'Tắt bếp ngay khi hành phi chuyển vàng sáng vì nhiệt dư trong dầu nóng sẽ tiếp tục làm hành sẫm màu thêm một nấc hoàn hảo.'),
(295,4,'Pha nước mắm chấm / sốt trộn tỷ lệ vàng chua ngọt','Hòa tan hoàn toàn đường cùng 100ml mắm nêm và nước ấm trong chén sâu lòng, khuấy đến khi hơi sánh nhẹ mới cho tỏi ớt băm nhuyễn và nước cốt chanh/tắc vào sau cùng. Công thức pha này giúp tỏi ớt nổi đều đẹp mắt trên bề mặt bát nước chấm chuẩn vị Bò tơ Củ Chi cuốn bánh tráng rau sống mắm nêm.',8,'Băm tỏi ớt thật ráo trên thớt khô và cho vào sau khi đường mắm đã nguội thì tỏi ớt sẽ nổi bồng bềnh 100% không bị chìm đáy.'),
(295,5,'Phối trộn thấm vị / tráng hấp & cuốn đều tay','Tiến hành tráng hấp bánh mỏng mượt hoặc trải bánh cuốn gọn gàng 600g bò tơ và 20 lá bánh tráng cùng 120g chuối xanh, 120g dứa và 150g dưa leo; nếu là món gỏi trộn thì rưới từ từ 2/3 lượng sốt chua ngọt vào bóp nhẹ tay cho thấm đều trong 3 phút. Giữ lực tay nhẹ nhàng để rau củ không bị dập nát mà vẫn ngấm trọn vị mặn chua ngọt hài hòa.',10,'Chia nước sốt gỏi làm 2 lần trộn và chắt bỏ phần nước tiết ra ở lần đầu giúp đĩa gỏi khô ráo, đậm đà như ngoài hàng.'),
(295,6,'Bày biện ngũ sắc hài hòa & rắc topping giòn bùi','Xếp món Bò tơ Củ Chi cuốn bánh tráng rau sống mắm nêm ngay ngắn ra đĩa sứ trắng rộng, rải đều phần nhân tôm thịt sắc nét lên trên và rắc phủ hành ngò và tiêu xay thơm giòn. Dọn kèm chén nước chấm đậm đà cho 4 người thưởng thức ngay khi rau bánh còn tươi giòn mướt mịn.',6,'Chỉ rắc đậu phộng rang và hành phi ngay trước lúc mang ra bàn ăn để giữ nguyên độ giòn tan bùi béo.'),
(296,1,'Sơ chế sạch & thấm thật khô bề mặt nguyên liệu','Rửa sạch 220g bột gạo và 35g bột năng cùng chút muối loãng để khử mùi tự nhiên, sau đó dùng khăn giấy bếp thấm thật khô ráo hoàn toàn bề mặt. Khứa nhẹ các đường chéo hoặc cắt miếng vừa ăn dày 2–3cm để nhiệt và gia vị thấm sâu đều khắp bên trong.',7,'Bề mặt nguyên liệu càng khô ráo thì khi chiên không bị văng dầu và khi nướng sẽ lên màu vàng ruộm giòn rụm cực đẹp.'),
(296,2,'Chuẩn bị hỗn hợp sốt ướp / bột áo chuẩn tỷ lệ','Phối trộn hành tím và tỏi băm nhỏ băm thật nhuyễn (hoặc vắt lấy nước cốt thơm) cùng 45ml nước tương trong tô lớn cho quyện sánh đồng nhất. Nếu món có lớp vỏ bột hoặc bánh cuốn từ 220g bột gạo và 35g bột năng, trộn đều hỗn hợp theo đúng định lượng để đạt độ giòn xốp mỏng nhẹ chuẩn vị.',6,'Vắt lấy nước cốt hành tỏi sả khi ướp đồ nướng giúp hương thơm thấm sâu mà không bị cháy đen phần xác băm trên lửa cao.'),
(296,3,'Ướp thấm thớ thịt / tạo hình cuốn khéo léo','Áo đều hỗn hợp gia vị hoặc lớp bột/vỏ cuốn quanh 220g bột gạo và 35g bột năng, massage nhẹ nhàng rồi để nghỉ 15–20 phút cho gia vị thẩm thấu trọn vẹn. Trường hợp cuốn chả/nem hoặc đổ khuôn bánh, thao tác đều tay vừa chặt để nhân kết dính nhưng không bị bục rách khi gặp nhiệt.',8,'Để nguyên liệu nghỉ đủ thời gian trước khi chiên nướng giúp lớp áo bột bám chắc và phần nhân bên trong mọng ngọt.'),
(296,4,'Pha nước chấm cân vị & sơ chế rau đồ chua ăn kèm','Nhặt rửa sạch 200g đu đủ xanh ngâm nước mát cho giòn tươi, bào sợi hoặc thái lát gọn gàng bày sẵn bên cạnh. Pha chén nước chấm chua ngọt hoặc muối ớt chanh sả sánh thơm theo khẩu vị vùng miền của món Bột chiên trứng giòn đu đủ bào Sài Gòn để cân bằng độ béo giòn.',5,'Luôn chuẩn bị xong rau sống và bát nước chấm trước khi chiên/nướng mẻ cuối để món ăn vừa ra lò là thưởng thức nóng giòn ngay.'),
(296,5,'Làm nóng dầu / lò nướng chuẩn nhiệt & làm chín đều lần 1','Làm nóng chảo dầu hoặc vỉ nướng/nồi chiên ở mức nhiệt vừa khoảng 165–175°C, xếp 220g bột gạo và 35g bột năng vào với khoảng cách thoáng đều nhau. Chiên hoặc nướng trở mặt nhịp nhàng trên lửa vừa để nhiệt dẫn sâu làm chín mềm ngọt hoàn toàn phần nhân bên trong.',10,'Kiểm tra nhiệt dầu bằng đầu đũa tre thấy sủi tăm nhỏ đều là đạt chuẩn 170°C, giúp vỏ không cháy sớm khi bên trong còn sống.'),
(296,6,'Tăng nhiệt khóa giòn rụm vàng ươm bề mặt lần 2','Ở 2–3 phút cuối, tăng lên lửa vừa lớn (khoảng 190°C) hoặc phết thêm lớp dầu điều/mật ong mỏng để vỏ ngoài của Bột chiên trứng giòn đu đủ bào Sài Gòn chuyển sắc vàng óng ánh và nổ giòn rụm. Lắng nghe tiếng xèo giòn rộn rã và hương thơm phức lan tỏa khắp bếp thì gắp ra vỉ thưa cho ráo dầu thừa.',5,'Đặt đồ chiên nướng lên giá inox thoáng khí thay vì giấy thấm dầu chồng khít để hơi nước thoát hết, giữ độ giòn lâu gấp 3 lần.'),
(296,7,'Trình bày bắt mắt kèm rau thơm & thưởng thức nóng','Xếp thành phẩm vàng giòn ra đĩa lớn có bày sẵn 200g đu đủ xanh và điểm xuyết 45g hành lá tươi xanh hài hòa màu sắc. Dọn kèm chén nước chấm sánh đậm ngay chính giữa mâm ăn cho 4 người thưởng thức khi vỏ ngoài còn nóng giòn rụm.',4,'Cắt miếng hoặc dọn ăn ngay trong vòng 10 phút sau khi rời bếp để cảm nhận trọn vẹn sự đối lập giòn ngoài - mềm ngọt bên trong.'),
(297,1,'Sơ chế sạch & cắt thái nguyên liệu đúng kích cỡ','Rửa sạch 600g thịt bò bắp và 200g cà rốt cùng 260g bánh mì và 30g cà chua cô đặc dưới vòi nước mát rồi để thật ráo trên rổ thưa. Dùng dao sắc cắt thái nguyên liệu thành từng khúc hoặc khối vuông đều đặn khoảng 3.5–4cm để khi kho hầm giữ nguyên hình dáng đẹp mắt mà không bị vụn nát.',13,'Cắt miếng thịt/cá dày dặn đồng đều giúp quá trình kho lâu trên lửa nhỏ thớ thịt mềm rục mà vẫn giữ trọn độ mọng ngọt bên trong.'),
(297,2,'Khử mùi tự nhiên & làm săn sạch bề mặt nguyên liệu','Chà nhẹ phần đạm chính trong 600g thịt bò bắp và 200g cà rốt với chút muối hạt, lát gừng đập dập hoặc chần sơ qua nước sôi 90 giây rồi rửa sạch lại bằng nước ấm, để ráo hoàn toàn. Công đoạn này loại bỏ triệt để tạp chất và mùi tanh hôi, giúp nước sốt món Bò hầm nước cốt dừa ngũ vị bánh mì Sài Gòn trong bóng thơm ngon.',10,'Sau khi chần hoặc rửa sạch, để nguyên liệu ráo nước ít nhất 5 phút trước khi ướp để gia vị rút sâu trực tiếp vào từng thớ thịt.'),
(297,3,'Pha hỗn hợp gia vị & ướp thấm chuẩn định lượng','Cho 600g thịt bò bắp và 200g cà rốt vào tô lớn, ướp cùng một nửa 45g sả băm nhỏ và định lượng chuẩn 5g ngũ vị hương, đảo nhẹ tay cho gia vị phủ kín đều các mặt. Bọc kín tô và để nguyên liệu nghỉ thấm vị tối thiểu 20 phút ở nhiệt độ phòng (hoặc ngăn mát tủ lạnh).',14,'Ướp đủ tối thiểu 20 phút trước khi bắc lên bếp là chìa khóa để tâm miếng thịt/cá đậm đà đồng nhất với lớp sốt bên ngoài.'),
(297,4,'Thắng nước màu cánh gián & phi dậy hương hành tỏi','Đặt nồi đáy dày lên bếp ở lửa vừa nhỏ, thắng nhẹ 15g đường với 15ml dầu ăn đến khi chuyển sắc nâu cánh gián óng ả thì cho ngay phần 45g sả còn lại vào phi thơm lừng. Hương caramel dịu ngọt quyện cùng tinh dầu hành tỏi sả tạo nền màu nâu hổ phách truyền thống đầy cuốn hút.',9,'Canh kỹ khoảnh khắc đường vừa chuyển màu cánh gián là hạ lửa nhỏ nhất ngay để nước màu bóng đẹp mà không bao giờ bị đắng.'),
(297,5,'Đảo săn hai mặt khóa ngọt nguyên liệu chính','Tăng lên lửa vừa lớn, gắp từng miếng trong 600g thịt bò bắp và 200g cà rốt vào nồi đảo đều hoặc trở nhẹ hai mặt trong 4–5 phút cho săn chắc và bám đều lớp màu nâu óng. Khi bề mặt nguyên liệu se vàng thơm phức mới trút phần nước ướp còn lại trong tô vào đun sôi nhẹ.',13,'Đối với cá kho, chỉ lật cá một lần lúc cá vừa săn mặt trên lửa vừa để khúc cá nguyên vẹn không bị tróc da hay vỡ nát.'),
(297,6,'Kho/om liu riu lửa nhỏ thấm đẫm cùng nước dừa/nước dùng','Chế 450ml nước dừa tươi và 80ml nước cốt dừa xâm xắp mặt nguyên liệu (xếp thêm rau củ ăn kèm nếu có), đun sôi bùng một dạo hớt sạch bọt rồi hạ ngay về mức lửa nhỏ liu riu nhất. Kho êm đềm không đậy kín nắp để từng thớ nguyên liệu chín mềm thấm đẫm gia vị và nước sốt rút dần sóng sánh.',22,'Luôn dùng nước sôi hoặc nước dừa ấm khi châm thêm vào nồi kho đang nóng để thịt cá không bị sượng cứng trở lại.'),
(297,7,'Thu sánh nước sốt óng ả & trình bày thưởng thức nóng','Khi nước kho rút còn khoảng 1/3 sánh kẹo óng ánh áo đều quanh nguyên liệu và xiên đũa thấy mềm mọng vừa ý, rắc hành ngò và tiêu xay lên mặt rồi tắt bếp. Múc món Bò hầm nước cốt dừa ngũ vị bánh mì Sài Gòn ra đĩa sâu lòng hoặc niêu đất giữ nhiệt, dọn ăn nóng cùng cơm trắng dẻo thơm cho 4 người.',9,'Giữ lại một lượng nước sốt sánh kẹo vừa đủ dưới đáy nồi để chan cơm hoặc chấm kèm rau luộc sẽ tròn vị đưa cơm gấp bội.'),
(298,1,'Sơ chế tươi sạch & ngâm giòn rau củ thảo mộc','Nhặt rửa kỹ 300g bắp cải và 80g hành tây cùng 40g rau răm và 50g đậu phộng qua nước muối loãng rồi tráng nước đun sôi để nguội. Với các loại củ quả bào sợi hoặc thái lát mỏng, ngâm vào âu nước đá lạnh pha chút chanh đường trong 10 phút rồi vắt ráo để giữ độ trắng giòn sần sật.',8,'Rau củ làm gỏi và món cuốn phải quay rổ hoặc thấm thật ráo nước để khi trộn nước mắm không bị loãng nhạt.'),
(298,2,'Làm chín tới phần nhân đạm giữ trọn độ ngọt mọng','Xử lý phần nguyên liệu chính (450g thịt gà (đùi) và 200g thịt gà (ức)): luộc hấp cùng lát gừng sả đập dập hoặc xào lửa lớn vừa chín tới, sau đó làm nguội nhanh rồi thái lát mỏng / xé sợi đều đặn. Nếu món có pha bột bánh gạo/bột năng, khuấy tan bột với nước đúng tỷ lệ và để bột nghỉ 15 phút cho nở mịn.',9,'Ngâm tôm hoặc thịt luộc qua bát nước sôi để nguội có vài viên đá giúp màu sắc tươi hồng và thớ thịt giòn ngọt không bị khô.'),
(298,3,'Rang vàng đậu phộng mè thơm & phi hành tỏi giòn','Bắc chảo nhỏ lên lửa nhỏ, rang chín vàng thơm đậu phộng/mè hoặc làm mỡ hành xanh mướt và phi vàng giòn hành tím và tỏi băm nhỏ. Vớt hành tỏi phi ra đĩa riêng để nguội giòn tan, giữ lại phần dầu thơm óng ánh để phết bánh hoặc rưới bóng mặt món ăn.',6,'Tắt bếp ngay khi hành phi chuyển vàng sáng vì nhiệt dư trong dầu nóng sẽ tiếp tục làm hành sẫm màu thêm một nấc hoàn hảo.'),
(298,4,'Pha nước mắm chấm / sốt trộn tỷ lệ vàng chua ngọt','Hòa tan hoàn toàn đường cùng 30ml tắc và nước ấm trong chén sâu lòng, khuấy đến khi hơi sánh nhẹ mới cho tỏi ớt băm nhuyễn và nước cốt chanh/tắc vào sau cùng. Công thức pha này giúp tỏi ớt nổi đều đẹp mắt trên bề mặt bát nước chấm chuẩn vị Gỏi gà trộn bắp cải rau răm chua ngọt Nam Bộ.',6,'Băm tỏi ớt thật ráo trên thớt khô và cho vào sau khi đường mắm đã nguội thì tỏi ớt sẽ nổi bồng bềnh 100% không bị chìm đáy.'),
(298,5,'Phối trộn thấm vị / tráng hấp & cuốn đều tay','Tiến hành tráng hấp bánh mỏng mượt hoặc trải bánh cuốn gọn gàng 450g thịt gà (đùi) và 200g thịt gà (ức) cùng 300g bắp cải và 80g hành tây; nếu là món gỏi trộn thì rưới từ từ 2/3 lượng sốt chua ngọt vào bóp nhẹ tay cho thấm đều trong 3 phút. Giữ lực tay nhẹ nhàng để rau củ không bị dập nát mà vẫn ngấm trọn vị mặn chua ngọt hài hòa.',7,'Chia nước sốt gỏi làm 2 lần trộn và chắt bỏ phần nước tiết ra ở lần đầu giúp đĩa gỏi khô ráo, đậm đà như ngoài hàng.');
INSERT INTO `recipe_steps` (`recipe_id`,`step_order`,`title`,`instruction`,`duration_mins`,`tip_note`) VALUES
(298,6,'Bày biện ngũ sắc hài hòa & rắc topping giòn bùi','Xếp món Gỏi gà trộn bắp cải rau răm chua ngọt Nam Bộ ngay ngắn ra đĩa sứ trắng rộng, rải đều phần nhân tôm thịt sắc nét lên trên và rắc phủ 40g rau răm và 50g đậu phộng thơm giòn. Dọn kèm chén nước chấm đậm đà cho 4 người thưởng thức ngay khi rau bánh còn tươi giòn mướt mịn.',4,'Chỉ rắc đậu phộng rang và hành phi ngay trước lúc mang ra bàn ăn để giữ nguyên độ giòn tan bùi béo.'),
(299,1,'Sơ chế sạch & thấm thật khô bề mặt nguyên liệu','Rửa sạch 240g bột gạo và 300g tôm sú cùng chút muối loãng để khử mùi tự nhiên, sau đó dùng khăn giấy bếp thấm thật khô ráo hoàn toàn bề mặt. Khứa nhẹ các đường chéo hoặc cắt miếng vừa ăn dày 2–3cm để nhiệt và gia vị thấm sâu đều khắp bên trong.',8,'Bề mặt nguyên liệu càng khô ráo thì khi chiên không bị văng dầu và khi nướng sẽ lên màu vàng ruộm giòn rụm cực đẹp.'),
(299,2,'Chuẩn bị hỗn hợp sốt ướp / bột áo chuẩn tỷ lệ','Phối trộn 10g nghệ băm thật nhuyễn (hoặc vắt lấy nước cốt thơm) cùng gia vị chuẩn định lượng trong tô lớn cho quyện sánh đồng nhất. Nếu món có lớp vỏ bột hoặc bánh cuốn từ 240g bột gạo và 300g tôm sú, trộn đều hỗn hợp theo đúng định lượng để đạt độ giòn xốp mỏng nhẹ chuẩn vị.',7,'Vắt lấy nước cốt hành tỏi sả khi ướp đồ nướng giúp hương thơm thấm sâu mà không bị cháy đen phần xác băm trên lửa cao.'),
(299,3,'Ướp thấm thớ thịt / tạo hình cuốn khéo léo','Áo đều hỗn hợp gia vị hoặc lớp bột/vỏ cuốn quanh 240g bột gạo và 300g tôm sú, massage nhẹ nhàng rồi để nghỉ 15–20 phút cho gia vị thẩm thấu trọn vẹn. Trường hợp cuốn chả/nem hoặc đổ khuôn bánh, thao tác đều tay vừa chặt để nhân kết dính nhưng không bị bục rách khi gặp nhiệt.',9,'Để nguyên liệu nghỉ đủ thời gian trước khi chiên nướng giúp lớp áo bột bám chắc và phần nhân bên trong mọng ngọt.'),
(299,4,'Pha nước chấm cân vị & sơ chế rau đồ chua ăn kèm','Nhặt rửa sạch 120g đu đủ xanh và 180g xà lách ngâm nước mát cho giòn tươi, bào sợi hoặc thái lát gọn gàng bày sẵn bên cạnh. Pha chén nước chấm chua ngọt hoặc muối ớt chanh sả sánh thơm theo khẩu vị vùng miền của món Bánh khọt Vũng Tàu tôm tươi cốt dừa vàng giòn để cân bằng độ béo giòn.',6,'Luôn chuẩn bị xong rau sống và bát nước chấm trước khi chiên/nướng mẻ cuối để món ăn vừa ra lò là thưởng thức nóng giòn ngay.'),
(299,5,'Làm nóng dầu / lò nướng chuẩn nhiệt & làm chín đều lần 1','Làm nóng chảo dầu hoặc vỉ nướng/nồi chiên ở mức nhiệt vừa khoảng 165–175°C, xếp 240g bột gạo và 300g tôm sú vào với khoảng cách thoáng đều nhau. Chiên hoặc nướng trở mặt nhịp nhàng trên lửa vừa để nhiệt dẫn sâu làm chín mềm ngọt hoàn toàn phần nhân bên trong.',10,'Kiểm tra nhiệt dầu bằng đầu đũa tre thấy sủi tăm nhỏ đều là đạt chuẩn 170°C, giúp vỏ không cháy sớm khi bên trong còn sống.'),
(299,6,'Tăng nhiệt khóa giòn rụm vàng ươm bề mặt lần 2','Ở 2–3 phút cuối, tăng lên lửa vừa lớn (khoảng 190°C) hoặc phết thêm lớp dầu điều/mật ong mỏng để vỏ ngoài của Bánh khọt Vũng Tàu tôm tươi cốt dừa vàng giòn chuyển sắc vàng óng ánh và nổ giòn rụm. Lắng nghe tiếng xèo giòn rộn rã và hương thơm phức lan tỏa khắp bếp thì gắp ra vỉ thưa cho ráo dầu thừa.',6,'Đặt đồ chiên nướng lên giá inox thoáng khí thay vì giấy thấm dầu chồng khít để hơi nước thoát hết, giữ độ giòn lâu gấp 3 lần.'),
(299,7,'Trình bày bắt mắt kèm rau thơm & thưởng thức nóng','Xếp thành phẩm vàng giòn ra đĩa lớn có bày sẵn 120g đu đủ xanh và 180g xà lách và điểm xuyết 50g hành lá tươi xanh hài hòa màu sắc. Dọn kèm chén nước chấm sánh đậm ngay chính giữa mâm ăn cho 4 người thưởng thức khi vỏ ngoài còn nóng giòn rụm.',4,'Cắt miếng hoặc dọn ăn ngay trong vòng 10 phút sau khi rời bếp để cảm nhận trọn vẹn sự đối lập giòn ngoài - mềm ngọt bên trong.'),
(300,1,'Tuyển chọn, ngâm nở & sơ chế sạch nguyên liệu chè bánh','Đãi rửa sạch nhóm hạt, củ hoặc bột (250g khoai lang và 250g khoai môn), ngâm nước ấm theo đúng đặc tính từng loại để hạt nở mềm đồng đều và loại bỏ nhựa chát. Rửa sạch nhóm tạo hương tự nhiên gồm 30g lá dứa để ráo nước.',11,'Thêm một nhúm muối nhỏ vào nước ngâm khoai và đậu giúp nguyên liệu giữ màu tươi sáng và khi nấu chín bùi hơn.'),
(300,2,'Ninh mềm bùi nguyên liệu chính giữ nguyên hạt/khối','Cho phần nguyên liệu nền trong 250g khoai lang và 250g khoai môn vào nồi đáy dày cùng lượng nước vừa đủ, đun sôi rồi hạ lửa nhỏ ninh êm đến khi chín mềm bùi nhưng không bị vỡ nát đục nước. Nếu có trân châu, bột lọc hoặc hạt lựu, luộc riêng trong nồi nước sôi đến khi nổi trong veo rồi vớt ngâm ngay vào bát nước mát.',15,'Tuyệt đối không cho đường ngay từ đầu khi đậu và khoai chưa chín mềm vì đường sẽ làm săn vỏ hạt khiến nấu mãi vẫn sượng.'),
(300,3,'Nấu nước đường phèn / mật mía thanh trong dậy hương','Kết hợp chính xác định lượng 130g đường vào nồi cùng bó lá dứa hoặc gừng thái chỉ, khuấy nhẹ trên lửa nhỏ cho tan trong vắt. Đun liu riu thêm 5–7 phút để vị ngọt thấm sâu vào từng viên nguyên liệu và tỏa hương thơm dịu tao nhã.',10,'Dùng đường phèn hoặc mật mía đun lửa nhỏ hớt bọt kỹ giúp hậu vị chè ngọt thanh mát họng, không bị khé cổ.'),
(300,4,'Thắng nước cốt dừa béo mịn / chuẩn bị lớp kem phủ','Cho 250ml nước cốt dừa vào nồi nhỏ cùng 2g muối tinh và 5g bột năng/bột bắp hòa loãng, khuấy đều tay trên lửa nhỏ nhất đến khi vừa chớm sôi lăn tăn sánh mượt. Tắt bếp ngay để nước cốt dừa giữ màu trắng ngần béo ngậy mà không bị tách lớp dầu.',8,'Một chút xíu muối tinh trong nồi nước cốt dừa sẽ làm bật hẳn độ béo thơm tự nhiên và cân bằng vị ngọt của món tráng miệng.'),
(300,5,'Phối hợp độ sánh mượt & cân bằng hương vị tổng thể','Hợp nhất các thành phần của món Chè bà ba khoai lang khoai môn cốt dừa miền Tây, từ từ rưới nước bột năng hòa loãng (nếu là chè sánh) đồng thời khuấy nhẹ một chiều trên lửa nhỏ cho hỗn hợp bóng mượt như nhung. Kiểm tra độ mềm dẻo hài hòa và tắt bếp để ủ hương thảo mộc lan tỏa đều.',7,'Rót nước bột tạo sánh thành dòng mảnh vừa rót vừa khuấy đều tay giúp chè trong mượt, hoàn toàn không bị ốc trâu vón cục.'),
(300,6,'Múc ra chén sứ, điểm topping & thưởng thức ấm/lạnh','Múc chè hoặc bày bánh ra 4 chén nhỏ xinh, chan lớp nước cốt dừa trắng mịn lên mặt và rắc nhẹ 15g mè rang. Thưởng thức ấm nóng dịu dàng hoặc thêm đá bào mát lạnh tùy sở thích đều trọn vị ngon truyền thống.',4,'Để chè nguội bớt về khoảng 45°C hoặc ướp mát 30 phút trong ngăn mát tủ lạnh giúp các tầng hương vị kết tinh đậm đà hơn.');
INSERT IGNORE INTO `comments` (`comment_id`,`recipe_id`,`user_id`,`user_name`,`user_avatar`,`rating`,`comment`) VALUES
(1,1,2,'Giang Nguyễn','',5,'Nước phở bò trong vắt và dậy mùi quế hồi đúng vị Hà Nội xưa, định lượng gam rất chuẩn!'),
(2,6,3,'Bếp Minh Anh','',5,'Làm theo 7 bước hướng dẫn chi tiết thịt ba chỉ mềm rục lên màu cánh gián bóng đẹp, cả nhà khen tấm tắc.'),
(3,201,2,'Giang Nguyễn','',5,'Bún thang Hà Nội hướng dẫn tráng trứng mỏng và nấu nước dùng tôm khô cực kỳ tỉ mỉ, dễ thành công ngay lần đầu.'),
(4,204,3,'Bếp Minh Anh','',5,'Bánh đa cua đồng Hải Phòng chuẩn vị đất Cảng, riêu cua đóng tảng béo thơm ăn kèm chả lá lốt tuyệt ngon!'),
(5,239,2,'Giang Nguyễn','',5,'Cơm hến xứ Huế cay thơm đúng điệu, mắm ruốc pha theo tỷ lệ hướng dẫn rất vừa vặn không bị gắt.'),
(6,249,4,'Lan Hương Chay','',5,'Cơm sen chay gói lá sen thơm thanh tịnh, hạt sen bùi mềm rất hợp cúng Rằm và đãi tiệc gia đình.'),
(7,253,3,'Bếp Minh Anh','',5,'Sợi cao lầu trộn sốt xá xíu ngũ vị thơm nức mũi, có ghi rõ mức lửa và thời gian từng bước rất dễ theo dõi.'),
(8,271,2,'Giang Nguyễn','',5,'Cá basa tẩm bột bắp chiên giòn rụm bên ngoài mềm ngọt bên trong, sốt me chua ngọt bắt cơm vô cùng!'),
(9,287,3,'Bếp Minh Anh','',5,'Bún mắm miền Tây nấu theo công thức lọc mắm cá linh rất trong và thơm sả, topping tôm mực heo quay đầy đặn.'),
(10,300,4,'Lan Hương Chay','',5,'Chè bà ba miền Tây béo ngậy cốt dừa, khoai lang khoai môn chín bùi nguyên miếng không bị nát.');
INSERT INTO `chatbot_knowledge_base` (`topic`,`category`,`title`,`keywords_text`,`content`,`substitution_json`,`is_active`,`priority`) VALUES
('su_co_man','troubleshooting','Cứu món canh, súp hoặc lẩu bị quá mặn','bi man,qua man,canh man,sup man,lau man,chua man,cuu mon man','Khi canh hoặc súp bị mặn, thêm nước lọc sôi hoặc nước dùng không nêm để pha loãng. Có thể thả vài lát khoai tây sống gọt vỏ hoặc đậu hũ trắng vào đun 5-7 phút để hút bớt muối rồi vớt ra nếu không hợp món.','{"action": "dilute_or_absorb", "absorbers": ["khoai tây", "đậu hũ", "nước sôi"]}',1,20),
('su_co_man','troubleshooting','Xử lý món kho (cá kho, thịt kho) bị mặn','ca kho bi man,thit kho bi man,kho man,man qua,chua man kho','Với món kho bị mặn, chắt bớt một phần nước kho mặn, châm thêm nước dừa tươi hoặc nước lọc ấm cùng vài lát cà chua/thơm/củ cải trắng để dịu vị, kho lửa nhỏ thêm 5 phút rồi tắt bếp.','{"action": "drain_and_simmer", "add": ["nước dừa tươi", "nước ấm", "cà chua", "đường phèn"]}',1,20),
('su_co_man','troubleshooting','Chữa món xào lỡ tay nêm quá mặn','mon xao bi man,rau xao man,xao qua man','Cho thêm phần rau củ hoặc nguyên liệu chưa nêm gia vị vào đảo nhanh lửa lớn, hoặc vắt thêm 1/2 muỗng cà phê nước cốt chanh và 1/2 muỗng cà phê đường để cân bằng cảm giác mặn trên đầu lưỡi.','18',1,10),
('su_co_chay','troubleshooting','Xử lý món ăn bị cháy đáy nồi','bi chay,chay khet,chay day noi,khet mui,mui khet','Tuyệt đối không cạo lớp cháy ở đáy nồi. Nhanh chóng trút phần thức ăn phía trên chưa bị cháy sang một nồi sạch khác, bỏ hẳn phần cháy khét. Nếu còn mùi khét nhẹ, thêm gia vị thơm như hành phi, gừng hoặc sả tươi rồi đun lại nhanh.','20',1,10),
('su_co_chay','troubleshooting','Xử lý món chiên rán bị cháy vỏ ngoài nhưng sống bên trong','chien bi chay,song ben trong,lua qua to,chin khong deu','Vớt thực phẩm ra giấy thấm dầu, hạ dầu xuống lửa vừa-nhỏ hoặc chuyển vào nồi chiên không dầu ở 160°C trong 6-8 phút để nhiệt thấm chín đều vào lõi mà không làm khét thêm lớp vỏ.','17',1,10),
('su_co_cay','troubleshooting','Làm dịu món ăn lỡ nêm quá cay nồng','qua cay,cay qua,bi cay,giam cay','Vớt bỏ hạt và lát ớt nổi, thêm chút đường/mật ong, nước cốt dừa (với cà ri/kho) hoặc sữa tươi/sữa chua/khoai tây để chất béo và vị ngọt bọc lấy capsaicin làm dịu độ cay.','18',1,10),
('su_co_chua','troubleshooting','Chữa món canh chua hoặc nước sốt bị quá chua','bi chua,qua chua,canh chua qua,giam chua','Hòa tan từng chút đường phèn/đường cát và vài hạt muối để trung hòa vị gắt, hoặc thêm cà rốt/bí đỏ cắt nhỏ giúp tạo vị ngọt thanh tự nhiên mà không gắt cổ.','16',1,10),
('su_co_ngot','troubleshooting','Chữa món ăn nêm lỡ quá ngọt','qua ngot,bi ngot,giam ngot','Vắt thêm vài giọt nước cốt chanh hoặc giấm gạo (với món xào/sốt), hoặc dằn thêm chút muối tinh/nước mắm ngon và tiêu xay để cân bằng lại hậu vị ngọt gắt.','16',1,10),
('su_co_nuoc_dung','troubleshooting','Làm trong nước dùng phở, bún, súp bị đục','nuoc dung bi duc,nuoc leo duc,lam trong nuoc dung,pho duc','Hạ lửa về mức sôi lăn tăn, hớt sạch bọt rồi đánh tan 1-2 lòng trắng trứng gà cho vào nồi nước dùng khuấy đều theo vòng tròn để bã đục bám vào mảng trứng, sau đó vớt bỏ toàn bộ mảng trứng qua rây mịn.','19',1,10),
('su_co_dac_loang','troubleshooting','Xử lý nước sốt hoặc súp bị quá loãng hoặc vón cục','nuoc sot loang,sup loang,bi von cuc,bot nang von cuc','Nếu quá loãng, hòa tan 1 muỗng cà phê bột năng hoặc bột bắp với 2 muỗng canh nước lạnh (tỉ lệ 1:2) rồi rót từ từ vào nồi đang sôi nhẹ kết hợp khuấy đều tay. Nếu bị vón cục, dùng rây mịn lọc bỏ cục bột.','17',1,10),
('su_co_tanh','troubleshooting','Xử lý món cá đã nấu nhưng vẫn còn mùi tanh','ca bi tanh,nau ca bi tanh,khu tanh ca','Thêm vài lát gừng đập dập, hành lá, thì là, nghệ tươi hoặc chút rượu trắng/giấm bỗng và đun mở nắp 2-3 phút để hợp chất gây tanh bay hơi theo hơi nước.','18',1,10),
('su_co_banh','troubleshooting','Khắc phục bánh flan bị rỗ mặt và rỗ thân','banh flan bi ro,flan ro mat,hap flan khong min','Khi khuấy trứng và sữa chỉ khuấy nhẹ một chiều tránh tạo bọt khí, lọc hỗn hợp qua rây mịn 2 lần. Hấp với lửa cực nhỏ, bọc miệng khuôn hoặc đậy khăn sạch dưới nắp nồi để nước ngưng tụ không nhỏ xuống mặt bánh.','16',1,10),
('su_co_rau','troubleshooting','Giữ rau muống, cải thìa xào hoặc luộc xanh mướt không thâm','rau bi tham,rau xao bi den,giu rau xanh','Luộc với nhiều nước sôi già, thêm 1/2 muỗng cà phê muối và vài giọt dầu ăn; vớt ra ngâm ngay vào bát nước đá lạnh 1-2 phút. Khi xào để lửa lớn nhất và đảo nhanh tay trong 1.5-2 phút.','18',1,10),
('su_co_chien','troubleshooting','Chiên cá hoặc đậu hũ không bị dính chảo và bắn dầu','chien bi dinh chao,ban dau,vang dau,ca dinh chao','Lau thật khô bề mặt cá/đậu hũ bằng khăn giấy. Làm nóng chảo khô trước, thoa lớp dầu mỏng hoặc xát một lát gừng tươi lên lòng chảo nóng rồi mới đổ dầu vào chiên ở lửa vừa.','18',1,10),
('su_co_thit_bo','troubleshooting','Cứu thịt bò xào bị dai hoặc ra nhiều nước','thit bo bi dai,bo xao ra nuoc,xao bo mem','Thái thịt bò thật mỏng theo thớ ngang, ướp 15 phút với dầu hào, chút dầu ăn và 1/2 muỗng cà phê bột bắp. Làm chảo thật nóng bốc khói nhẹ mới trút bò vào đảo nhanh 60-90 giây trên lửa lớn.','18',1,10),
('su_co_com','troubleshooting','Xử lý cơm nấu bị nhão hoặc bị khê / sượng','com bi nhao,com bi khe,com suong,cuu com','Nếu cơm nhão: mở nắp xới tơi và đặt lát bánh mì khô lên mặt ủ 5 phút hút ẩm. Nếu cơm sượng: rưới 2-3 muỗng canh nước nóng pha 1 thìa rượu trắng, đậy nắp hấp lại 10 phút. Nếu cơm khê: đặt mẩu than hoa sạch hoặc vài cọng hành lá lên mặt nồi hấp 3 phút để hút mùi.','17',1,10),
('su_co_chao','troubleshooting','Chữa món ăn quá nhiều dầu mỡ bị ngấy','qua nhieu dau mo,bi ngay,hut dau thua','Hớt lớp váng dầu trên mặt nước dùng bằng muôi lạnh hoặc cho 1-2 viên đá lạnh bọc giấy thấm dầu lướt nhẹ bề mặt nước dùng để dầu đông bám vào viên đá; với món chiên, lót 2 lớp giấy thấm dầu.','15',1,10),
('su_co_gia_vi','troubleshooting','Sửa món kho hoặc xào bị nhạt sau khi đã gần hoàn tất','bi nhat,thieu dam da,can chinh vi','Nêm lại bằng hỗn hợp nước mắm ngon/nước tương pha chút nước ấm cho tan đều thay vì rắc muối hạt trực tiếp làm mặn cục bộ.','14',1,10),
('su_co_cha','troubleshooting','Khắc phục chả cá hoặc mọc giò sống bị bở không dai','cha ca bi bo,moc bi bo,khong dai','Nguyên liệu xay phải giữ lạnh (ngâm ngăn đá 30 phút trước khi quết), trộn cùng 1/2 muỗng cà phê bột năng, 1 thìa đá xay nhuyễn và quết đều theo một chiều để tạo liên kết protein dẻo mịn.','15',1,10),
('su_co_hat','troubleshooting','Chữa đậu phộng hoặc mè rang bị ỉu mất độ giòn','dau phong bi iu,lac iu,me iu','Đem rang lại trên chảo khô lửa nhỏ hoặc cho vào nồi chiên không dầu ở 140°C trong 3-4 phút, sau đó dàn mỏng để nguội hoàn toàn mới cất hũ kín.','14',1,10),
('so_che_ga','prep_safety','Khử mùi hôi thịt gà và xử lý an toàn thực phẩm','thit ga bi hoi,ga hoi,khu mui ga,so che ga','Chỉ chế biến khi thịt gà còn tươi, đàn hồi và được bảo quản lạnh đúng cách. Thấm khô, bỏ tuyến dầu ở phao câu và mỡ vàng dư, chà xát nhẹ muối hột + gừng đập dập hoặc giấm/chanh rồi rửa sạch, thấm khô trước khi ướp. Nếu thịt có mùi chua nồng, nhớt dính tay hoặc biến màu xanh tái thì bỏ ngay, không cố khử mùi để che thịt hỏng.','{"safe_spices": ["muối hột", "gừng", "chanh", "sả"], "spoilage_warning": true}',1,22),
('so_che_vit','prep_safety','Khử mùi hôi đặc trưng của thịt vịt, ngan','thit vit bi hoi,khu mui vit,so che vit,ngan hoi','Cắt bỏ phần phao câu. Chà toàn bộ da và bụng vịt với hỗn hợp gừng giã nhuyễn, rượu trắng và muối hạt trong 5 phút rồi xả sạch dưới vòi nước lạnh. Khi luộc thả thêm vài lát gừng và hành tím nướng.','19',1,10),
('so_che_ca','prep_safety','Làm sạch nhớt và khử mùi tanh các loại cá nước ngọt và cá biển','ca bi tanh,khu mui tanh ca,lam sach nhot ca,ca loc,ca basa','Cạo sạch vảy, moi bỏ mang và cạo hết màng đen trong bụng cá (nơi tập trung mùi tanh nhất). Rửa cá với nước vo gạo hoặc nước muối pha chanh/gừng, xả lại rồi thấm thật khô trước khi nấu.','20',1,10),
('so_che_heo','prep_safety','Khử mùi hôi thịt heo và sườn heo khi nấu canh hoặc kho','thit heo hoi,suon bi hoi,chan suon,chan thit','Chần sơ thịt hoặc sườn trong nước sôi có vài lát gừng và hành tím đập dập trong 2-3 phút, vớt ra rửa lại bằng nước ấm sạch rồi mới đem ướp kho hoặc ninh lấy nước dùng trong ngọt.','19',1,10),
('so_che_bo','prep_safety','Khử mùi gây thịt bò và làm mềm thịt bò kho/hầm','thit bo hoi,khu mui bo,bo kho mem','Chà nhẹ thịt bò với gừng nướng đập dập hoặc rượu trắng trước khi rửa, thấm khô. Nếu bò hơi dai, ướp thêm chút dầu ăn, gừng băm và vài lát dứa nghiền nhỏ trong 15 phút (tránh ướp dứa quá lâu khiến thịt bở nát).','18',1,10)
INSERT INTO `chatbot_knowledge_base` (`topic`,`category`,`title`,`keywords_text`,`content`,`substitution_json`,`is_active`,`priority`) VALUES
('so_che_hai_san','prep_safety','Sơ chế tôm sú, mực ống giòn ngọt không tanh','tom bi tanh,muc bi tanh,so che tom muc,rút chỉ lưng tôm','Rút chỉ đen dọc sống lưng tôm, cắt bỏ phần túi sạn trên đầu. Với mực, bóc bỏ màng tím, rút túi mực và mai cứng, bóp nhanh với muối và gừng/rượu trắng 1 phút rồi rửa sạch để ráo.','18',1,10),
('so_che_cua','prep_safety','Lọc cua đồng xay không bị vỡ gạch và không tanh','cua dong xay,loc cua dong,nau canh cua','Hòa cua xay với nước lọc, bóp nhẹ để thịt tan hết rồi để lắng 1 phút và chắt từ từ qua rây, bỏ bã vỏ. Khuấy tan chút muối trước khi bật lửa vừa; khi riêu cua bắt đầu đóng bánh thì vặn lửa nhỏ tránh trào vỡ gạch.','16',1,10),
('so_che_dau_hu','prep_safety','Sơ chế đậu hũ trắng mềm không nát và không chua','dau hu bi chua,dau hu nat,so che dau hu','Ngâm đậu hũ trong nước lọc pha xíu muối khoảng 10 phút giúp đậu săn chắc hơn trước khi cắt miếng chiên hoặc kho. Với đậu hũ non, dùng dao ướt cắt nhẹ trực tiếp trong khuôn.','16',1,10),
('so_che_nam','prep_safety','Rửa và ngâm các loại nấm khô, nấm tươi đúng cách','nam huong,nam meo,ngam nam,so che nam','Không ngâm nấm tươi quá lâu vì nấm hút nước mất vị ngọt, chỉ rửa nhanh dưới vòi nước nhẹ rồi vắt nhẹ cho ráo. Với nấm hương và nấm mèo khô, ngâm nước ấm 15-20 phút cho nở mềm rồi cắt bỏ chân nấm dai.','16',1,10),
('so_che_ra_dong','prep_safety','Rã đông thịt cá an toàn giữ nguyên chất lượng và dinh dưỡng','ra dong thit,ra dong ca,an toan thuc pham','Chuyển thực phẩm từ ngăn đá xuống ngăn mát tủ lạnh qua đêm (8-12 giờ) là an toàn nhất. Nếu cần gấp, bọc kín thực phẩm trong túi zip không thấm nước và ngâm vào tô nước lạnh, thay nước mỗi 30 phút. Tuyệt đối không rã đông bằng nước sôi hoặc để ngoài nhiệt độ phòng quá 2 giờ.','20',1,10),
('bao_quan_thuc_an','prep_safety','Bảo quản thức ăn thừa và nước dùng đúng nhiệt độ','bao quan thuc an,com thua,nuoc dung,tu lanh','Để món chín nguội về nhiệt độ phòng (trong vòng tối đa 2 giờ sau khi nấu), chia vào hộp thủy tinh đậy kín rồi cất ngăn mát ở 4°C (dùng trong 2-3 ngày) hoặc cấp đông đến 1 tháng. Khi ăn đun sôi kỹ lại trên 75°C.','17',1,10),
('so_che_rau','prep_safety','Loại bỏ nhựa đắng ở rau muống, bắp chuối, mướp đắng, dọc mùng','doc mung ngua,muop dang,bap chuoi tham,so che rau','Bào mỏng bắp chuối vào nước muối chanh loãng để không thâm. Với dọc mùng (bạc hà), tước vỏ xơ, thái vát rồi bóp với muối hạt 5 phút, rửa sạch vắt ráo để hết ngứa cổ.','16',1,10),
('so_che_trung','prep_safety','Bí quyết luộc trứng lòng đào hoặc trứng chín dễ bóc vỏ','luoc trung,trung long dao,boc vo trung','Dùng trứng ở nhiệt độ phòng thả nhẹ vào nước sôi vừa (lửa nhỏ tránh nứt vỏ): 6 phút 30 giây cho lòng đào dẻo, 9-10 phút cho chín hẳn. Vớt ngay vào tô nước đá lạnh 5 phút rồi mới bóc vỏ.','16',1,10),
('so_che_bun','prep_safety','Xử lý bún tươi bị chua nhẹ hoặc sợi mì bị dính','bun tuoi bi chua,tran bun,mi dinh','Chần nhanh bún tươi trong nồi nước sôi khoảng 20-30 giây rồi xả qua nước đun sôi để nguội để sạch bụi và giảm vị chua lên men nhẹ. Nếu bún có mùi ôi hoặc nhớt phải bỏ ngay.','15',1,10),
('thay_the_giavi','substitution','Thay thế Xì dầu / Nước tương khi hết','khong co xi dau,thieu xi dau,thay the xi dau,khong co nuoc tuong,thay nuoc tuong','Nếu thiếu xì dầu (nước tương), bạn có thể dùng một ít nước mắm pha loãng với nước lọc để tạo vị mặn (lưu ý vị mắm nồng hơn và không tạo màu nâu sẫm như xì dầu), hoặc dùng tương bần / dầu hào chay tùy món. Không dùng đường thay xì dầu.','{"missing": "xì dầu / nước tương", "alternatives": [{"name": "nước mắm pha loãng", "ratio": "1/2 phần mắm + 1/2 phần nước", "note": "vị khác, không có màu đậm"}, {"name": "dầu hào / tương đậu nành", "ratio": "tỉ lệ 1:1", "note": "nêm bớt muối và đường"}]}',1,22),
('thay_the_giavi','substitution','Thay thế Nước mắm cho món ăn (kể cả chế độ ăn chay)','thay nuoc mam,khong co nuoc mam,nuoc mam chay','Món mặn thông thường có thể thay bằng nước tương ngon + một ít muối tinh (tỉ lệ 2:1 theo lượng nước mắm). Món chay tuyệt đối dùng nước tương/xì dầu, nước mắm chay từ nấm hương/dứa hoặc muối hầm.','{"missing": "nước mắm", "alternatives": [{"name": "nước tương + chút muối", "note": "cho món chay và xào"}, {"name": "hạt nêm nấm hương", "note": "giữ vị ngọt umami"}]}',1,21),
('thay_the_giavi','substitution','Thay thế Dầu hào khi nấu món xào hoặc ướp nướng','khong co dau hao,thay dau hao,dau hao chay','Pha hỗn hợp 1 muỗng canh nước tương + 1 muỗng cà phê đường (hoặc mật ong) + 1/2 muỗng cà phê bột bắp hòa chút nước để tạo độ sánh, vị ngọt đậm tương tự dầu hào. Người ăn chay chọn dầu hào nấm hương.','{"missing": "dầu hào", "alternatives": [{"name": "nước tương + đường + bột bắp", "ratio": "1 muỗng nước tương : 1/2 muỗng đường"}]}',1,20),
('thay_the_dau','substitution','Chế biến món ăn không cần dầu ăn hoặc ít dầu','khong co dau an,khong can dau an,it dau mo,chiên khong dau','Với món luộc, hấp, canh hoặc áp chảo chống dính, hoàn toàn có thể nấu không dầu ăn. Khi xào rau hoặc thịt không dầu, cho 2-3 muỗng canh nước dùng/nước lọc vào chảo nóng để xào chín mềm (phương pháp thủy xào) hoặc dùng nồi chiên không dầu nướng ở 180°C.','{"missing": "dầu ăn", "alternatives": [{"name": "nước lọc / nước dùng (thủy xào)"}, {"name": "nồi chiên không dầu"}]}',1,22),
('thay_the_beo','substitution','Thay thế Nước cốt dừa trong món chè, cà ri hoặc kho','thieu nuoc cot dua,khong co nuoc cot dua,thay nuoc cot dua','Có thể thay nước cốt dừa bằng sữa tươi không đường pha chút bơ lạt (tỉ lệ 1:1 cho món mặn/bánh), sữa đặc pha loãng (cho món chè nhưng giảm đường lại) hoặc sữa hạt điều xay nhuyễn nếu muốn thuần chay nhẹ bụng.','{"missing": "nước cốt dừa", "alternatives": [{"name": "sữa tươi + bơ lạt"}, {"name": "sữa hạt điều"}]}',1,20),
('thay_the_beo','substitution','Thay thế Kem tươi (Whipping cream) làm sốt hoặc tráng miệng','thay kem tuoi,whipping cream,khong co kem tuoi','Với món sốt nóng, trộn 3 phần sữa tươi không đường + 1 phần bơ lạt đun ấm hoặc 1 muỗng cà phê bột bắp để tạo độ sánh béo. Với món nguội tráng miệng, dùng sữa chua Hy Lạp hoặc nước cốt dừa đặc để lạnh.','{"missing": "kem tươi", "alternatives": [{"name": "sữa tươi + bơ lạt (3:1)"}, {"name": "sữa chua không đường"}]}',1,18),
('thay_the_bot','substitution','Thay thế Bột năng bằng Bột bắp hoặc ngược lại','thay bot nang,thay bot bap,bot nang khac gi bot bap','Khi làm nước sốt sánh, dùng bột bắp thay bột năng theo tỉ lệ 1:1 (sốt bột bắp giữ độ sánh lâu hơn khi nguội, ít bị tách nước). Khi làm bánh giòn hoặc chả, ưu tiên bột năng để tạo độ dai kết dính tốt hơn.','{"missing": "bột năng", "alternatives": [{"name": "bột bắp (1:1 cho nước sốt)"}, {"name": "bột sắn dây"}]}',1,19),
('thay_the_chua','substitution','Thay thế Me vắt hoặc Quả sấu trong canh chua, nước sốt','thay me vat,khong co me,thay qua sau,tao vi chua','Có thể thay me vắt hoặc sấu bằng cà chua chín băm nấu nhừ, dứa tươi, giấm bỗng, nước cốt chanh hoặc quả dọc/lá giang. Chú ý cho chanh/tắc vào lúc tắt bếp để tránh bị đắng nước dùng.','{"missing": "me vắt / sấu", "alternatives": [{"name": "cà chua + dứa"}, {"name": "nước cốt chanh (thêm sau khi tắt bếp)"}]}',1,19),
('thay_the_thom','substitution','Thay thế Hành tím hoặc Tỏi khi hết trong bếp','khong co hanh tim,khong co toi,thay hanh tim','Có thể thay hành tím bằng phần đầu trắng của hành lá thái nhỏ hoặc hành tây băm nhỏ theo lượng tương đương. Với món chay kiêng ngũ vị tân, dùng phần gốc ngò rí, boaro hoặc gừng non thay cho hành tỏi.','{"missing": "hành tím / tỏi", "alternatives": [{"name": "đầu hành lá / hành tây"}, {"name": "hành boaro / rễ ngò (món chay)"}]}',1,18),
('thay_the_ngot','substitution','Thay thế Mật ong trong công thức nướng, ướp hoặc pha đồ uống','khong co mat ong,thay mat ong,an chay khong dung mat ong','Thay 1 muỗng canh mật ong bằng 1 muỗng canh mạch nha, siro phong, nước đường nâu thắng cô đặc hoặc đường thốt nốt hòa 1/2 thìa nước ấm để giữ độ bóng đẹp khi phết thịt nướng.','{"missing": "mật ong", "alternatives": [{"name": "đường thốt nốt / nước hàng"}, {"name": "siro ngô / mạch nha"}]}',1,18),
('thay_the_ruou','substitution','Thay thế Rượu vang đỏ hoặc Rượu nấu ăn (Mai Quế Lộ/rượu trắng)','thay ruou vang do,khong co ruou nau an,bo sot vang','Khi làm bò sốt vang hoặc khử mùi không dùng cồn, thay rượu vang đỏ bằng nước ép nho/táo nguyên chất pha 1 muỗng cà phê giấm táo hoặc giấm nho đỏ, thêm quế hồi thảo quả để giữ mùi thơm trầm ấm.','{"missing": "rượu vang đỏ", "alternatives": [{"name": "nước ép nho + chút giấm táo"}]}',1,16),
('thay_the_bo','substitution','Thay thế Bơ lạt khi áp chảo hoặc làm bánh','thay bo lat,khong co bo lat','Dùng dầu ô liu, dầu dừa tinh luyện hoặc dầu ăn tỉ lệ 3/4 so với lượng bơ (tức 75g dầu thay 100g bơ). Nếu cần hương thơm béo, có thể thêm vài giọt vani (cho bánh) hoặc tỏi phi (cho món mặn).','{"missing": "bơ lạt", "alternatives": [{"name": "dầu ô liu / dầu ăn (tỉ lệ 3:4)"}]}',1,17),
('thay_the_sua','substitution','Thay thế Sữa đặc hoặc Sữa tươi trong pha chế và làm bánh','khong co sua dac,thay sua dac,sua hat','Thay 100g sữa đặc bằng hỗn hợp 120ml sữa tươi nấu cô nhẹ cùng 40g đường. Người bất dung nạp lactose hoặc thuần chay thay sữa tươi bằng sữa đậu nành, sữa yến mạch hoặc sữa hạnh nhân không đường tỉ lệ 1:1.','{"missing": "sữa đặc / sữa tươi", "alternatives": [{"name": "sữa đậu nành / sữa yến mạch (1:1)"}]}',1,17),
('thay_the_giavi','substitution','Thay thế Sa tế khi hết sẵn hũ sa tế','khong co sa te,tu lam sa te nhanh','Phi thơm 1 thìa tỏi sả băm với 2 thìa dầu điều/dầu ăn rồi tắt bếp trộn 1 thìa ớt bột, 1/2 thìa đường và 1/2 thìa nước mắm (hoặc nước tương chay) sẽ cho vị sa tế thơm gấp đôi ngoài hàng.','16',1,10),
('thay_the_chua','substitution','Thay thế Chanh tươi bằng Tắc (Quất) hoặc Giấm ăn','khong co chanh,thay chanh bang tac,het chanh','Dùng 2-3 quả tắc vắt lấy nước (bỏ hạt) thay 1/2 quả chanh khi pha nước chấm, mùi thơm tinh dầu vỏ tắc sẽ rất dậy vị. Hoặc dùng giấm gạo/giấm táo tỉ lệ 1:1 cho món trộn gỏi.','17',1,10),
('thay_the_dong','substitution','Thay thế Gelatin bằng Bột rau câu khi làm chè khúc bạch hoặc thạch','thay gelatin,khong co gelatin,bot rau cau chay','Dùng bột rau câu dẻo (agar/jelly) tỉ lệ khoảng 1/3 lượng gelatin (vì agar tạo đông mạnh hơn); nhớ đun sôi bột rau câu với nước trước khi tắt bếp trộn sữa/kem, khác với gelatin chỉ ngâm nở rồi đun ấm.','{"missing": "gelatin", "alternatives": [{"name": "bột rau câu dẻo / agar (đặc biệt hợp món chay)"}]}',1,17)
INSERT INTO `chatbot_knowledge_base` (`topic`,`category`,`title`,`keywords_text`,`content`,`substitution_json`,`is_active`,`priority`) VALUES
('ky_thuat_chien','technique','So sánh chiên ngập dầu và chiên bằng Nồi chiên không dầu','noi chien khong dau,nhiet do noi chien,chien it dau','Nồi chiên không dầu giảm đến 75-85% lượng chất béo hấp thụ. Làm nóng nồi trước 3 phút ở 180°C, xịt lớp dầu cực mỏng lên da gà/cá/đậu hũ để không bị khô xác, lật mặt giữa giờ. Món tẩm bột ướt nên chiên chảo ngập dầu 170°C để lớp áo không chảy.','18',1,10),
('ky_thuat_luoc','technique','Luộc thịt gà nguyên con da vàng óng không bị nứt da','luoc ga da vang,luoc ga khong rach,thit ga chin mem','Cho gà vào nồi nước LẠNH ngập thân gà cùng vài lát gừng, hành tím nướng và xíu muối. Bật lửa vừa đến khi nước vừa sủi tăm thì hạ xuống lửa nhỏ nhất đậy hé nắp liu riu 15-20 phút, rồi tắt bếp đậy kín ủ thêm 15 phút trước khi vớt ngâm nước nguội.','19',1,10),
('ky_thuat_kho','technique','Bí quyết kho thịt cá lên màu cánh gián đẹp không bị đắng','thang nuoc mau,kho thit len mau dep,nuoc hang khong dang','Đun 2 muỗng canh đường với 1 muỗng canh nước trên lửa nhỏ, tuyệt đối không khuấy mạnh tay cho đến khi chuyển màu nâu cánh gián sủi bọt nhẹ thì tắt bếp, đợi vài giây mới rót 50ml nước nóng vào khuấy tan.','18',1,10),
('ky_thuat_nuoc_dung','technique','Ninh nước dùng xương bò, xương heo ngọt tự nhiên mà không cần nhiều bột ngọt','ninh xuong pho,nuoc dung ngot thanh,ham xuong bao lau','Chần xương qua nước sôi 3 phút rồi rửa sạch cặn. Cho vào nồi nước lạnh nấu cùng hành tây nướng, gừng nướng, củ cải trắng hoặc mía lau chẻ đôi; mở nắp hớt bọt kỹ lúc đầu rồi để lửa liu riu thật nhỏ trong 2-4 tiếng.','18',1,10),
('ky_thuat_xao','technique','Nguyên tắc lửa lớn và chia mẻ khi xào thập cẩm','cach xao ngon,xao khong ra nuoc,mon xao gion','Đảm bảo chảo đủ nóng và không cho quá nhiều nguyên liệu cùng lúc (tránh làm tụt nhiệt độ chảo khiến rau ra nước). Xào nguyên liệu lâu chín trước (cà rốt, thịt), rau lá mềm cho vào cuối cùng và nêm gia vị trong 30 giây cuối.','17',1,10),
('ky_thuat_hap','technique','Hấp cá, hải sản và rau củ giữ trọn dinh dưỡng','hap ca ngon,hap hai san,cach hap khong nuoc','Đun nước sôi bốc hơi mạnh trước khi đặt xửng hấp vào. Thời gian hấp cá nguyên con khoảng 12-18 phút tùy trọng lượng; mở nắp nhanh ở phút cuối để xả bớt nước đọng. Lót sả, gừng dưới đáy đĩa cá.','16',1,10),
('ky_thuat_uop','technique','Thứ tự ướp gia vị chuẩn để thịt thấm đều và không bị chảy nước','thu tu uop thit,uop nuong ngon,uop mem thit','Nguyên tắc cơ bản: ướp phần gia vị tạo mùi và vị đậm trước (tỏi băm, hành, tiêu, nước mắm/nước tương, dầu hào), để 10 phút cho ngấm sâu rồi mới thêm dầu ăn hoặc mật ong ở bước cuối để khóa ẩm bề mặt.','17',1,10),
('ky_thuat_nuong','technique','Nướng thịt bằng lò nướng hoặc nồi chiên không dầu không bị khô','nuong thit khong kho,nhiet do nuong thit','Thịt nạc thăn/ức gà nên ướp kèm 1 muỗng sữa tươi hoặc dầu ăn, nướng nhiệt cao vừa đủ (185-200°C trong 15-20 phút thay vì nướng quá lâu ở nhiệt thấp). Để thịt nghỉ 5 phút trước khi thái giúp giữ nước ngọt bên trong.','16',1,10),
('ky_thuat_pha_mam','technique','Công thức vàng pha nước mắm chua ngọt tỏi ớt sánh đẹp','pha nuoc mam chua ngot,nuoc cham nem,nuoc cham com tam','Áp dụng tỉ lệ dễ nhớ 1:1:1:4 (1 đường : 1 nước cốt chanh : 1 nước mắm ngon : 4 nước ấm) hoặc 1:1:1:2 cho nước mắm chấm sệt. Hòa tan đường vào nước ấm trước, thêm nước mắm và chanh, cuối cùng thả tỏi ớt băm nhuyễn sẽ nổi đẹp trên mặt bát.','20',1,10),
('dinh_duong_calo','nutrition','Ước lượng năng lượng chuẩn của các món Việt phổ biến mỗi phần','bao nhieu calo,calo pho bo,calo com tam,calo bun bo,tinh calo','Mỗi phần ăn chuẩn tại CookMate thường dao động: Cơm trắng 1 bát vừa ~200 kcal; Phở bò ~450-500 kcal; Bún bò Huế ~520-580 kcal; Cơm tấm sườn ~580-650 kcal; Canh rau thịt ~120-200 kcal; Gỏi cuốn 2 cuốn ~260-320 kcal. Tuy nhiên luônn kiểm tra chi tiết từng công thức đã lưu trong hệ thống.','21',1,10),
('dinh_duong_eatclean','nutrition','Nguyên tắc xây dựng thực đơn Eat Clean và giảm cân bền vững','eat clean,giam can,it dau mo,thuc don giam can,1500 kcal','Bữa ăn Eat Clean cân bằng gồm 50% rau củ giàu xơ, 25% đạm nạc (ức gà, cá, trứng, đậu hũ) và 25% tinh bột hấp thu chậm (gạo lứt, khoai lang, yến mạch). Hạn chế chiên ngập dầu, thay bằng luộc, hấp, áp chảo ít dầu và ưu tiên 3 bữa chính khoảng 400-500 kcal/bữa (~1400-1500 kcal/ngày).','21',1,10),
('dinh_duong_tieu_duong','nutrition','Cách nấu ăn phù hợp cho người cần kiểm soát đường huyết (tiểu đường)','tieu duong,duong huyet,it duong,chi so gi thap','Ưu tiên tăng rau xanh ăn trước bữa chính để làm chậm hấp thu đường, chọn đạm cá/gà/đậu hũ, thay đường cát bằng lượng rất ít hoặc gia vị tự nhiên từ quế, hành, tiêu. Giảm các món sốt sệt bột năng nhiều đường, chia khẩu phần cơm vừa phải (khoảng 100-120g cơm/bữa).','19',1,10),
('dinh_duong_chay','nutrition','Bổ sung đủ đạm (Protein) và sắt trong chế độ ăn chay thuần thực vật','an chay du chat,dam thuc vat,thuc don chay,mon chay giau dam','Chế độ ăn chay đầy đủ dưỡng chất nên kết hợp đa dạng đậu hũ, tàu hũ ky, các loại đậu (đậu đen, đậu xanh, đậu nành), nấm (nấm đùi gà, nấm hương), mè và các loại hạt. Dùng dầu thực vật giàu omega và bổ sung vitamin C từ cà chua, cam chanh giúp hấp thu sắt thực vật tốt hơn.','19',1,10),
('dinh_duong_tang_co','nutrition','Thực đơn giàu đạm cho người tập luyện và tăng cơ','tang co,giau dam,protein cao,uc ga,trung ga','Mỗi bữa nên đạt 25-35g protein từ ức gà áp chảo (150g ~ 46g protein), cá hồi/cá thu, thịt bò thăn, trứng gà (1 quả ~ 6g protein) hoặc đậu hũ. Kết hợp tinh bột sạch như khoai lang, cơm tẻ để phục hồi glycogen sau tập.','18',1,10),
('dinh_duong_be','nutrition','Lưu ý nêm nếm thực đơn dinh dưỡng cho trẻ nhỏ và người lớn tuổi','cho tre em,nguoi lon tuoi,an nhat,nau mem','Với người lớn tuổi và trẻ nhỏ dưới 2 tuổi nên giảm tối đa lượng muối, nước mắm và đường tinh luyện, cắt nhỏ hoặc hầm mềm nguyên liệu để dễ tiêu hóa; tránh dùng ớt cay nồng và hạt cứng dễ hóc.','16',1,10),
('dip_le_co','meal_planning','Gợi ý cân bằng thực đơn mâm cơm gia đình Việt 3-4 món','mam com gia dinh,bua com hang ngay,thuc don 3 mon','Một mâm cơm Việt hài hòa dinh dưỡng cho 3-4 người thường có: 1 món mặn giàu đạm (kho/rim/nướng), 1 món canh thanh nhiệt (canh chua/canh bí/canh rau), 1 món xào hoặc luộc nhiều chất xơ và chén nước chấm hợp vị.','20',1,10),
('dip_le_tet','meal_planning','Cân bằng dinh dưỡng cho mâm cỗ Tết cổ truyền đỡ ngấy','mam co tet,mon ngay tet,chong ngay ngay tet','Mâm cỗ truyền thống dễ giàu chất béo bão hòa (thịt kho tàu, chả giò, thịt đông). Nên kết hợp cùng dưa hành muối, gỏi ngó sen tôm thịt, canh măng hoặc canh khổ qua thanh mát để hỗ trợ tiêu hóa và giảm cảm giác ngấy.','18',1,10),
('dip_le_ram','meal_planning','Gợi ý mâm cơm chay thanh tịnh cho ngày Rằm và Mùng 1','ngay ram,mung 1,mam com chay,an chay ngay ram','Mâm cơm chay ngày Rằm có thể phối hợp 4 món thanh đạm: Đậu hũ kho nấm hương đậm đà, Canh nấm hạt sen/bí đỏ ngọt thanh, Rau muống hoặc cải thìa xào tỏi/gừng, và Chả giò chay hoặc Gỏi cuốn chay khai vị.','19',1,10),
('meo_mua_lua','ingredients','Cách chọn thịt, cá, rau củ tươi ngon ngoài chợ hoặc siêu thị','cach chon thit tuoi,chon ca tuoi,chon rau sach','Thịt heo/bò tươi có màu hồng đỏ tự nhiên, mặt khô ráo, ấn tay vào đàn hồi ngay không để lại vết lõm. Cá tươi mắt trong suốt không đục, mang đỏ tươi không nhớt đục. Rau lá tươi không dập nát hay sẫm úa quá mức.','17',1,10),
('meo_dung_cu','technique','Quy đổi nhanh các đơn vị đo lường nấu ăn thông dụng tại Việt Nam','quy doi don vi,muong canh bao nhieu ml,muong ca phe,chen com','1 muỗng cà phê (mcf) ≈ 5 ml (hoặc ~4-5g muối/đường); 1 muỗng canh (mc) ≈ 15 ml; 1 chén cơm (bát ăn cơm) gạo/nước ≈ 200-240 ml; 1 quả trứng gà ta trung bình ≈ 50g ruột.','20',1,10),
('meo_nau_nhanh','meal_planning','Thực đơn bữa tối nhanh gọn trong 20 phút cho người bận rộn','nau nhanh,20 phut,ban ron,bua toi nhanh','Ưu tiên món không cần ninh lâu: Trứng xào cà chua, Thịt băm rang sả ớt hoặc Ức gà áp chảo (10 phút), kết hợp Canh cải thìa nấu tôm/nấm (8 phút) và rau dưa ăn kèm giúp xong mâm cơm nóng hổi dưới 20 phút.','18',1,10),
('ing_guide_1','ingredient_guide','Bí quyết chế biến và dinh dưỡng của Ức gà & Thịt gà','thịt gà,ức gà,đùi gà','Không rã đông nóng; ướp xíu sữa tươi hoặc dầu ăn giúp ức gà áp chảo không bị khô xơ. Về dinh dưỡng: 25-31g protein/100g ức gà, rất ít béo (~3.6g).',NULL,1,13),
('ing_guide_2','ingredient_guide','Bí quyết chế biến và dinh dưỡng của Thịt bò thăn & Bò bắp','thịt bò,bò thăn,thịt bò bắp','Thái lát mỏng ngang thớ; xào nhanh lửa lớn 60-90 giây còn hầm bắp bò ở lửa nhỏ 60-90 phút để gân mềm tan. Về dinh dưỡng: ~26g protein và sắt heme dồi dào/100g.',NULL,1,13),
('ing_guide_3','ingredient_guide','Bí quyết chế biến và dinh dưỡng của Thịt ba chỉ & Sườn non','thịt ba chỉ,sườn non,thịt heo','Chần sơ gừng hành tím 2 phút trước khi kho/nướng để sạch mùi; áp chảo cho xém cạnh bớt mỡ thừa. Về dinh dưỡng: ~16-19g protein, giàu năng lượng; nên ăn kèm rau chua.',NULL,1,13),
('ing_guide_4','ingredient_guide','Bí quyết chế biến và dinh dưỡng của Cá hồi & Cá thu','cá hồi,cá thu','Không nấu chín quá lâu khiến thịt cá khô bã; áp chảo da xuống trước ở lửa vừa-cao 3-4 phút đến khi da giòn. Về dinh dưỡng: Giàu Omega-3 (EPA/DHA) tốt cho tim mạch và não bộ.',NULL,1,13)
INSERT INTO `chatbot_knowledge_base` (`topic`,`category`,`title`,`keywords_text`,`content`,`substitution_json`,`is_active`,`priority`) VALUES
('ing_guide_5','ingredient_guide','Bí quyết chế biến và dinh dưỡng của Cá lóc, Cá basa & Cá diêu hồng','cá lóc,cá basa,cá diêu hồng','Ướp nghệ gừng tiêu 15 phút và thắng nước màu nhẹ trước khi kho tộ; đun mở nắp 2 phút đầu để bay mùi tanh. Về dinh dưỡng: Nguồn đạm trắng dễ tiêu hóa, ít chất béo bão hòa.',NULL,1,13),
('ing_guide_6','ingredient_guide','Bí quyết chế biến và dinh dưỡng của Tôm sú & Mực ống','tôm sú,mực ống,hải sản','Chế biến nhanh trên lửa lớn 2-4 phút vừa chuyển màu cam đỏ / trắng đục săn lại; nấu lâu mực tôm sẽ bị dai. Về dinh dưỡng: Đạm cao (~20g/100g), rất ít calo (~90-100 kcal/100g).',NULL,1,13),
('ing_guide_7','ingredient_guide','Bí quyết chế biến và dinh dưỡng của Đậu hũ trắng & Đậu hũ non','đậu hũ,đậu phụ,đậu hũ non','Thấm khô nước mặt ngoài trước khi chiên áp chảo; kho cùng nấm hương, nước tương và chút dầu hào chay rất thấm vị. Về dinh dưỡng: Đạm thực vật hoàn chỉnh (~8-12g/100g), giàu canxi tự nhiên.',NULL,1,13),
('ing_guide_8','ingredient_guide','Bí quyết chế biến và dinh dưỡng của Trứng gà & Trứng cút','trứng gà,trứng cút','Khuấy trứng thêm 1 thìa nước lọc giúp trứng chiên xốp mềm hơn; đánh cùng cà chua chín để giảm mùi nồng lòng đỏ. Về dinh dưỡng: ~13g protein/100g, chứa choline tốt cho trí nhớ.',NULL,1,13),
('ing_guide_9','ingredient_guide','Bí quyết chế biến và dinh dưỡng của Nấm hương, Nấm đùi gà & Nấm rơm','nấm hương,nấm đùi gà,nấm rơm,nấm kim châm','Áp chảo nấm khô dầu trước cho dậy hương thơm umami tự nhiên rồi mới nêm sốt hoặc thả vào nồi canh. Về dinh dưỡng: Rất ít calo (~22-35 kcal/100g), giàu chất xơ và vị ngọt tự nhiên.',NULL,1,13),
('ing_guide_10','ingredient_guide','Bí quyết chế biến và dinh dưỡng của Cà chua & Dứa chín','cà chua,dứa','Phi thơm hành rồi đảo cà chua với nhúm muối nhỏ giúp cà chua nhanh nhừ sánh đỏ đẹp cho món sốt. Về dinh dưỡng: Chứa lycopene và enzyme bromelain giúp làm mềm thịt tự nhiên.',NULL,1,13),
('ing_guide_11','ingredient_guide','Bí quyết chế biến và dinh dưỡng của Rau muống, Cải thìa & Mồng tơi','rau muống,cải thìa,mồng tơi,rau ngót','Nhặt bỏ cọng già, rửa nhiều nước, chỉ thả vào khi nước thật sôi hoặc dầu thật nóng để giữ vitamin C và màu xanh. Về dinh dưỡng: Giàu chất xơ (~2-3g/100g), ít calo, hỗ trợ tiêu hóa.',NULL,1,13),
('ing_guide_12','ingredient_guide','Bí quyết chế biến và dinh dưỡng của Bí đỏ & Khoai lang','bí đỏ,khoai lang,khoai môn','Hấp hoặc nấu canh lửa vừa để giữ vị ngọt bùi tự nhiên mà không cần thêm nhiều đường. Về dinh dưỡng: Tinh bột phức giàu beta-carotene và vitamin A, no lâu.',NULL,1,13),
('ing_guide_13','ingredient_guide','Bí quyết chế biến và dinh dưỡng của Bông cải xanh & Đậu que','bông cải xanh,đậu que,cải xanh','Cắt kích thước đồng đều, chần sơ 45 giây rồi xào nhanh lửa lớn giữ độ giòn sần sật và màu xanh tươi. Về dinh dưỡng: Giàu vitamin C, K và chất xơ chống oxy hóa.',NULL,1,13),
('ing_guide_14','ingredient_guide','Bí quyết chế biến và dinh dưỡng của Gạo tẻ, Bún tươi & Miến dong','gạo tẻ,bún tươi,miến dong,phở','Vo gạo nhẹ tay giữ cám thơm; miến dong ngâm nước nguội 10 phút rồi trụng nhanh giúp sợi miến dai không nát khi xào. Về dinh dưỡng: Nguồn carbohydrate cung cấp năng lượng chính trong bữa Việt.',NULL,1,13),
('ing_guide_15','ingredient_guide','Bí quyết chế biến và dinh dưỡng của Gừng, Sả & Nghệ tươi','gừng,sả,nghệ','Đập dập phần củ già gần gốc để tinh dầu tiết ra mạnh nhất khi ướp hoặc phi dầu; lát gừng mỏng hợp canh cá gà. Về dinh dưỡng: Chất chống oxy hóa tự nhiên giúp khử tanh, ấm bụng.',NULL,1,13),
('ing_guide_16','ingredient_guide','Bí quyết chế biến và dinh dưỡng của Nước cốt dừa & Đậu phộng','nước cốt dừa,đậu phộng,mè rang','Không đun nước cốt dừa sôi bùng quá lâu dễ bị tách dầu lợn cợn; thả vào 2 phút cuối khi nấu chè hoặc cà ri. Về dinh dưỡng: Chất béo thực vật tạo độ ngậy thơm; chú ý lượng vừa phải nếu đang ăn kiêng.',NULL,1,13),
('chef_tip_1','technique','Món chiên bị ỉu nhanh sau khi vớt','chien bi iu,khong gion lau,gion lau','Phủ nhẹ lớp mỏng bột bắp hoặc bột năng pha loãng, chiên 2 lần lửa (lần 1 chín bên trong, để nguội 5 phút rồi chiên lửa cao 45 giây cho giòn vỏ), đặt lên rây thoáng thay vì ủ nắp.',NULL,1,14),
('chef_tip_2','technique','Nồi chiên không dầu nướng gà bị khô ức','ga nuong bi kho,nuong ức ga kho','Nhúng hoặc ướp ức gà với hỗn hợp 1 thìa sữa chua không đường và dầu hào 20 phút, bọc mặt bằng giấy bạc 10 phút đầu ở 180°C rồi mở giấy 4 phút cuối.',NULL,1,14),
('chef_tip_3','troubleshooting','Rán nem (chả giò) bị rách vỏ hoặc xì nhân','ran nem bi rach,cha gio vo,banh trang rach','Nhân trộn phải ráo nước (vắt nhẹ củ sắn/giá/miến), dùng ít nước cốt chanh hoặc bia pha loãng quét nhẹ lên bánh tráng trước khi cuốn đều tay không quá chặt.',NULL,1,14),
('chef_tip_4','troubleshooting','Gỏi/nộm bị ra nhiều nước khi trộn','goi ra nuoc,nom bi chay nuoc','Ngâm xoài bào/cà rốt/đu đủ với xíu muối 5 phút rồi vắt thật ráo, trộn các nguyên liệu ngay trước khi dọn ăn 5-10 phút và rưới nước sốt thành từng đợt.',NULL,1,14),
('chef_tip_5','troubleshooting','Chè nấu bằng bột năng bị loãng sau vài giờ','che bi vua nuoc,che bi loang,bot năng chay nuoc','Dùng thêm nước cốt dừa riêng khi ăn hoặc thay một phần bột năng bằng bột sắn dây và đun khuấy chín hoàn toàn trong 2 phút sau khi sánh.',NULL,1,14),
('chef_tip_6','troubleshooting','Bánh xèo đổ bị mềm không giòn rìa','banh xeo khong gion,banh xeo bi mem','Pha bột với nước cốt dừa + chút nước có ga/bia (hoặc 1 thìa bột nghệ+bột chiên giòn), để bột nghỉ 30 phút, tráng thật mỏng trên chảo nóng già.',NULL,1,14),
('chef_tip_7','technique','Bún bò Huế hoặc Phở bị thiếu hương vị đặc trưng','pho thieu mui,bun bo khong thom','Rang sơ thảo quả, quế, hoa hồi, hạt mùi trên chảo khô rồi bọc túi vải thả vào nồi nước dùng; với bún bò Huế cần sả cây đập dập phi thơm cùng mắm ruốc lọc cặn.',NULL,1,14),
('chef_tip_8','technique','Nước chấm gỏi cuốn tương đậu bị lợn cợn tách dầu','tuong cham goi cuon,tuong den dau phong','Phi thơm tỏi, hòa tan tương đen (hoặc tương hột xay) cùng bơ đậu phộng mịn với chút nước lọc khuấy liên tục lửa nhỏ đến khi sánh bóng mới tắt bếp.',NULL,1,14),
('chef_tip_9','troubleshooting','Nấu canh cua bị tanh hoặc không đóng riêu','canh cua khong dong,riêu cua tan','Thêm 1/2 muỗng cà phê muối trước khi nấu và không khuấy khi nước bắt đầu nóng già; hạ nhỏ lửa ngay lúc thịt cua nổi lên mặt để đóng thành tảng.',NULL,1,14),
('chef_tip_10','troubleshooting','Làm sinh tố bơ bị đắng hậu vị','sinh to bo bi dang,bo dang','Không gọt quá sát phần vỏ xanh đậm, bỏ phần xơ nâu dính hạt bơ, không xay bơ quá lâu ở tốc độ cao làm nóng máy, thêm chút sữa đặc và đá lạnh.',NULL,1,14),
('chef_tip_11','troubleshooting','Xào mì Ý / hủ tiếu / miến bị dính chùm nát sợi','mi y dinh,xao mien bi nat,hu tieu dinh','Trụng mì vừa chín còn lõi dai nhẹ (al dente), xóc ngay 1 thìa dầu ô liu/dầu ăn khi vừa vớt ráo; khi xào để lửa lớn đảo bằng đũa thay vì xẻng đè nát sợi.',NULL,1,14),
('chef_tip_12','technique','Kho cá nục/cá thu bị tanh và nát thịt','kho ca khong nat,ca kho ran','Áp chảo hoặc chiên sơ hai mặt cá cho se mặt rồi xếp lên lớp riềng sả/mía dưới đáy nồi trước khi chế nước sôi nóng (không chế nước lạnh vào cá đang nóng).',NULL,1,14),
('chef_tip_13','technique','Ướp thịt nướng mật ong dễ bị cháy khét ngoài mặt','nuong mat ong bi chay,thit nuong chay','Chỉ ướp phần gia vị mặn hành tỏi trước; đợi thịt nướng chín 70% mới phết lớp mỏng mật ong pha dầu ăn ở 3-4 phút cuối.',NULL,1,14)
INSERT INTO `chatbot_knowledge_base` (`topic`,`category`,`title`,`keywords_text`,`content`,`substitution_json`,`is_active`,`priority`) VALUES
('chef_tip_14','technique','Canh bí đỏ nấu bị sượng hoặc nát bét','canh bi do,bi do bi nat','Xào sơ bí đỏ với chút dầu và tỏi băm 1 phút trước khi đổ nước sôi; nấu lửa vừa 10-12 phút đến khi thử xiên đũa mềm vừa là tắt bếp.',NULL,1,14),
('chef_tip_15','technique','Rang thịt băm làm sao ráo dầu mà thơm ngon','rang thit bam,thit bam kho','Dùng thịt nạc vai có chút mỡ đảo khô trên chảo nóng trước cho tự ra bớt mỡ, sau đó chắt bớt mỡ thừa mới thêm hành tím băm, nước mắm và đường rim keo.',NULL,1,14),
('chef_tip_16','technique','Pha trà đào / trà vải không bị chát đắng','tra dao bi chat,ham tra khong dang','Chỉ ủ túi trà đen với nước 85-90°C trong 3-4 phút rồi nhấc túi trà ra ngay, không bóp túi trà; thêm chút nước cốt tắc tạo hương thanh mát.',NULL,1,14),
('chef_tip_17','troubleshooting','Cà tím xào bị thâm đen và hút quá nhiều dầu','ca tim bi den,ca tim hut dau','Cắt xong ngâm cà tím trong nước muối loãng có vài giọt giấm/chanh 10 phút; vắt ráo hoặc hấp sơ 3 phút trước khi xào giúp cà giữ màu tím đẹp và ít tốn dầu.',NULL,1,14),
('chef_tip_18','technique','Nấm đùi gà kho chay bị nhạt lõi bên trong','nam dui ga kho chay,nam chay dam vi','Khứa hình caro nhẹ trên thân nấm hoặc xé sợi dọc, áp chảo khô cho nấm ráo bớt nước rồi mới chan nước tương + đường thắng kho 8 phút.',NULL,1,14),
('chef_tip_19','technique','Tàu hũ ky (váng đậu) nấu canh hoặc chiên bị dai','tau hu ky,vang dau chay','Tàu hũ ky khô cần ngâm nước ấm 10 phút rửa sạch dầu cũ; chiên nhanh lửa vừa để giòn tan, hoặc cuộn nấm hấp 8 phút trước khi sốt.',NULL,1,14),
('chef_tip_20','technique','Gạo nếp đồ xôi bị khô hoặc nhão','do xoi,xoi bi kho,xoi nhao','Ngâm nếp 6-8 tiếng với nhúm muối nhỏ rồi xả sạch để ráo 15 phút trước khi đồ; rưới chút nước cốt dừa khi xôi chín 80% và xới tơi hai lần.',NULL,1,14),
('chef_tip_21','troubleshooting','Làm sữa chua dẻo không bị tách nước nhớt','sua chua bi tach nuoc,u sua chua','Dùng men cái từ hũ sữa chua không chất bảo quản còn hạn mới, khuấy tan nhẹ nhàng ở nhiệt độ 40-42°C (âm ấm như nước tắm) và ủ ổn định 6-8 giờ không rung lắc.',NULL,1,14),
('chef_tip_22','technique','Chiên khoai tây giòn lâu bên ngoài mềm bên trong','chien khoai tay gion','Luộc sơ khoai 3 phút trong nước pha chút giấm/muối, để nguội thật khô rồi cấp đông 30 phút trước khi chiên hai lửa hoặc nướng nồi chiên ở 195°C.',NULL,1,14),
('chef_tip_23','technique','Ướp sườn nướng cơm tấm mềm ngọt chuẩn quán','uop suon com tam,suon nuong mem','Dần nhẹ miếng sườn bằng sống dao cho mềm thớ, ướp hành tỏi băm nhuyễn (vắt lấy nước cốt ướp để không cháy xác hành khi nướng), mật ong, sữa đặc và dầu hào ít nhất 2 tiếng.',NULL,1,14),
('chef_tip_24','technique','Nấu canh chua không bị chát nước me và nát cà chua','canh chua ca,nau me','Dầm me với nước sôi gạn lọc lấy nước cốt trong bỏ hạt; thả cà chua và dứa vào xào thơm hoặc đun trước, thả dọc mùng và rau om ngò gai sau khi tắt bếp.',NULL,1,14),
('chef_tip_25','nutrition','Luộc rau củ ăn Eat Clean giữ trọn vitamin','luoc rau eat clean,hap rau','Ưu tiên hấp cách thủy 3-5 phút thay vì luộc lâu ngập nước để giữ tối đa vitamin B/C tan trong nước; chấm cùng muối mè hoặc nước tương gừng.',NULL,1,14),
('diet_1500','nutrition','Cơ cấu thực đơn 3 bữa 1500 kcal/ngày cho người giảm cân','thuc don 3 bua,1500 kcal,giam can,bua sang trua toi','Gợi ý phân bổ 1500 kcal: Sáng (~350-400 kcal): Phở gà ít bánh hoặc Trứng ốp + bánh mì nguyên cám + sinh tố rau; Trưa (~550-600 kcal): Cơm gạo lứt + Ức gà/Cá áp chảo + Canh bí/rau luộc; Tối (~450-500 kcal): Gỏi cuốn tôm thịt hoặc Đậu hũ kho nấm + Rau xào ít dầu.',NULL,1,15),
('diet_low_carb','nutrition','Thay thế tinh bột nhanh bằng nguồn ít GI trong bữa Việt','it tinh bot,low carb,giam beo bung,com trang','Có thể thay một nửa chén cơm trắng bằng súp lơ xanh băm nhỏ đảo nóng, bí đỏ hấp, đậu phụ non hoặc miến dong/bún gạo lứt để giảm tổng lượng carb tinh chế mà vẫn đủ no.',NULL,1,15),
('food_pair_1','meal_planning','Cặp gia vị vàng cho món kho Việt Nam theo từng nguyên liệu','gia vi kho ca,gia vi kho thit,gia vi kho ga','Cá đồng kho hợp riềng, nghệ, tiêu, nước hàng; Thịt kho hợp hành tím, nước dừa tươi, trứng; Gà kho hợp gừng sả ớt hoặc nghệ; Món chay kho hợp nấm hương, gừng, tiêu và nước tương.',NULL,1,15),
('food_pair_2','meal_planning','Rau thơm kết hợp chuẩn vị cho từng món bún phở gỏi Việt','rau thom,rau an kem,pho,bun bo,goi','Phở bò dùng hành lá, ngò gai, húng quế; Canh chua Nam Bộ không thể thiếu rau om, ngò gai; Bún chả ăn với tía tô, kinh giới, xà lách; Cá kho hợp thì là/hành lá; Ốc/lươn hợp lá lốt, tía tô.',NULL,1,15),
('safety_oil','prep_safety','Nhận biết dầu ăn đã chiên đi chiên lại bị oxy hóa không nên dùng tiếp','dau an cu,chien lai nhieu lan,an toan dau an','Dầu ăn chuyển màu sẫm đặc, có bọt li ti không tan hoặc mùi khét hăng bốc khói sớm khi mới làm nóng không nên tái sử dụng quá 2 lần vì sinh chất gây hại cho tim mạch.',NULL,1,15),
('safety_cutting','prep_safety','Tránh nhiễm chéo thực phẩm sống và chín trong bếp gia đình','thot song chin,nhiem cheo,an toan bep','Luôn dùng hai dao và hai thớt riêng biệt cho thịt cá sống và đồ chín/rau ăn sống (ví dụ băm thịt sống xong tuyệt đối không thái rau gỏi trên cùng mặt thớt chưa rửa nước sôi).',NULL,1,15),
('sub_spice_1','substitution','Thay thế Mì chính (Bột ngọt) bằng vị ngọt tự nhiên','khong dung bot ngot,thay mi chinh,ngot tu nhien','Thay bột ngọt bằng nước hầm xương/nấm hương, củ cải trắng, cà rốt, mía lau, táo lê hoặc 1 nhúm cực nhỏ đường phèn để món ăn ngọt hậu mà vẫn thanh sạch.',NULL,1,15),
('sub_spice_2','substitution','Thay thế Đường trắng tinh luyện trong nấu nướng healthy','thay duong trang,an it duong,duong an kieng','Với món kho/sốt, có thể dùng mật ong lượng nhỏ, đường thốt nốt, đường ăn kiêng stevia chịu nhiệt hoặc vị ngọt từ hành tây xào chín caramel hóa, cà rốt và dứa.',NULL,1,15),
('sub_spice_3','substitution','Thay thế Bột chiên giòn khi hết trong bếp','thay bot chien gion,het bot chien','Trộn 3 phần bột mì đa dụng + 1 phần bột bắp (hoặc bột năng) + 1/2 thìa cà phê bột nở hoặc nước có ga lạnh sẽ tạo lớp áo giòn rụm nhẹ xốp.',NULL,1,15),
('sub_spice_4','substitution','Thay thế Lá chanh khi làm gà hấp hoặc muối chấm gà','khong co la chanh,thay la chanh','Dùng vỏ chanh tươi bào cực mỏng (chỉ lấy lớp vỏ xanh ngoài, tránh cùi trắng đắng) kết hợp chút sả băm để tạo tinh dầu thơm tương tự lá chanh.',NULL,1,15),
('sub_spice_5','substitution','Thay thế Tiêu đen bằng tiêu trắng hoặc gừng ấm','thay tieu den,khong co tieu','Dùng gừng tươi băm nhuyễn hoặc ớt bột ngọt nhẹ để giữ vị ấm cay dịu trong các món súp, cháo và kho.',NULL,1,15),
('kitchen_scale_1','technique','Cách quy đổi nhanh công thức từ 4 người sang 2 hoặc 8 người','quy doi khau phan,nhan doi cong thuc,chia doi','Nguyên liệu chính nhân/chia đúng theo tỉ lệ số khẩu phần mới. Riêng gia vị mặn (muối, nước mắm, ớt) chỉ nên nhân khoảng 80% khi tăng khẩu phần lớn rồi nêm nếm lại lúc cuối để tránh bị mặn gắt.',NULL,1,15),
('kitchen_scale_2','technique','Mẹo tăng giảm thời gian nấu khi nấu gấp đôi khối lượng','nau nhieu hon,thoi gian nau','Khi tăng gấp đôi khẩu phần ăn, nguyên liệu chính như thịt cá cần thêm ~20-30% thời gian chín lõi, nước dùng cần thời gian sôi lâu hơn nhưng không nhân đôi thời gian kẻo món bị nát.',NULL,1,15)
INSERT INTO `chatbot_knowledge_base` (`topic`,`category`,`title`,`keywords_text`,`content`,`substitution_json`,`is_active`,`priority`) VALUES
('dish_archetype_1','technique','Kinh nghiệm chế biến chuẩn vị nhóm Phở bò & Phở gà','pho bo,pho ga,nuoc dung pho,gia vi pho','Hương vị phở chuẩn nằm ở thảo quả, quế thanh, hoa hồi, gừng và hành tây nướng thơm trước khi thả vào nước hầm xương lửa liu riu; chần bánh phở nhanh tay giữ sợi dẻo.',NULL,1,12),
('dish_archetype_2','technique','Kinh nghiệm chế biến chuẩn vị nhóm Bún chả & Cơm tấm sườn','bun cha,com tam,suon nuong,nuoc cham bun cha','Thịt nướng ngon cần ướp nước cốt hành tỏi, mật ong/nước màu và chút dầu ăn, nướng lửa vừa có rãnh thoát mỡ; nước chấm pha chua ngọt hài hòa thêm cà rốt đu đủ giòn.',NULL,1,12),
('dish_archetype_3','technique','Kinh nghiệm chế biến chuẩn vị nhóm Thịt kho tàu & Cá kho tộ','thit kho tau,ca kho to,thit kho hot vit','Thắng nước màu cánh gián nhạt và dùng nước dừa tươi thay nước lọc giúp thịt mềm bóng, cá săn thịt; kho mở nắp ở 10 phút đầu để bay mùi tanh.',NULL,1,12),
('dish_archetype_4','technique','Kinh nghiệm chế biến chuẩn vị nhóm Canh chua cá & Canh sườn rau củ','canh chua,canh suon,canh bi do,canh cua','Lấy vị chua thanh từ me/dứa/cà chua thay vì quá nhiều giấm; rau thơm (rau om, ngò gai, hành lá) luôn thêm cuối cùng lúc vừa tắt bếp.',NULL,1,12),
('dish_archetype_5','technique','Kinh nghiệm chế biến chuẩn vị nhóm Rau muống xào tỏi & Đậu que xào','rau muong xao toi,dau que xao,xao toi','Chia tỏi làm 2 phần: 1/2 phi thơm ban đầu, 1/2 cho vào lúc đảo cuối để rau vừa bóng dầu tỏi vừa dậy mùi thơm tươi.',NULL,1,12),
('dish_archetype_6','technique','Kinh nghiệm chế biến chuẩn vị nhóm Gỏi cuốn & Chả giò rán','goi cuon,cha gio,nem ran,cuon','Nhúng bánh tráng thật nhanh qua nước ấm pha xíu đường hoặc lau khăn ẩm cho dẻo không rách; chả giò chiên 2 lửa giữ giòn tới 3 tiếng.',NULL,1,12),
('dish_archetype_7','technique','Kinh nghiệm chế biến chuẩn vị nhóm Đậu hũ sốt cà chua & Món chay kho nấm','dau hu sot ca chua,mon chay,nam kho,dau hu kho','Chiên đậu hũ vàng giòn nhẹ mặt ngoài trước khi rim sốt cà chua hoặc kho nước tương giúp đậu hút sốt đậm đà mà không vỡ nát.',NULL,1,12),
('dish_archetype_8','technique','Kinh nghiệm chế biến chuẩn vị nhóm Chè bưởi, Chè đậu xanh & Chè khúc bạch','che buoi,che dau xanh,che khuc bach,nau che','Cùi bưởi phải bóp muối xả nhiều lần đến khi hết vị the đắng, luộc sôi rồi áo bột năng trong bóng; ăn kèm nước cốt dừa nấu lá dứa.',NULL,1,12),
('dish_archetype_9','technique','Kinh nghiệm chế biến chuẩn vị nhóm Sinh tố bơ, Nước ép & Trà trái cây','sinh to bo,tra dao,tra vai,nuoc ep','Dùng trái cây chín tự nhiên ướp lạnh thay vì quá nhiều đường tinh luyện, kết hợp chút muối tinh siêu nhỏ để kích vị ngọt trái cây.',NULL,1,12),
('dish_archetype_10','technique','Kinh nghiệm chế biến chuẩn vị nhóm Bánh flan & Sữa chua nhà làm','banh flan,sua chua,trang mieng','Khuấy trứng sữa nhẹ tay một chiều tránh bọt khí, lọc rây 2 lần và hấp nhỏ lửa có khăn lót nắp để mặt bánh flan láng mịn không rỗ.',NULL,1,12),
('dish_archetype_11','technique','Kinh nghiệm chế biến chuẩn vị nhóm Món nướng nồi chiên không dầu','noi chien khong dau,ga nuong sa ot,ba chi nuong','Luôn làm nóng nồi chiên 180°C trong 3 phút, lật giữa giờ và phết lớp dầu gia vị mỏng giúp thực phẩm chín vàng giòn đều hai mặt.',NULL,1,12),
('dish_archetype_12','nutrition','Kinh nghiệm chế biến chuẩn vị nhóm Món chay thanh đạm giàu dinh dưỡng','an chay,mon chay,dau hu,nam','Thay thế nước mắm bằng nước tương, muối hầm hoặc hạt nêm nấm hương; kết hợp đậu hũ, nấm đùi gà, hạt sen, các loại đậu để cân bằng đạm thực vật.',NULL,1,12),
('kitchen_detail_1','prep_safety','Rau xà lách và rau sống ăn kèm bị héo mềm','rau song bi heo,rau xa lach gion','Ngâm rau đã rửa sạch trong nước đá lạnh 5 phút rồi vẩy thật ráo nước bằng rổ quay rau trước khi dọn cùng bún chả hoặc gỏi cuốn.',NULL,1,11),
('kitchen_detail_2','technique','Cách nấu nước đường caramel cho bánh flan không bị lại đường','thang caramel,banh flan,caramel khong dang','Đun đường và nước với 2 giọt cốt chanh trên lửa vừa, tuyệt đối không dùng đũa khuấy mà chỉ lắc nhẹ chảo theo vòng tròn đến khi màu cánh gián.',NULL,1,11),
('kitchen_detail_3','prep_safety','Cách giữ chuối chín không bị thâm đen khi làm bánh hay sinh tố','chuoi bi tham,sinh to chuoi','Bóc vỏ cắt lát rưới vài giọt nước cốt chanh hoặc cấp đông chuối chín trong túi kín trước khi xay sinh tố cho độ sánh mịn như kem.',NULL,1,11),
('kitchen_detail_4','technique','Cá hồi áp chảo bị dính chảo và tróc da','ca hoi ap chao,da ca hoi gion','Thấm thật khô da cá, khứa nhẹ vài đường nông, đặt mặt da xuống chảo dầu nóng già không đảo trong 3 phút đầu cho đến khi lớp da tự tách mặt chảo.',NULL,1,11),
('kitchen_detail_5','technique','Thịt kho tàu bị đục mỡ và không trong nước','thit kho tau trong,nuoc dua kho thit','Luộc chần thịt ba chỉ 3 phút rửa sạch trước khi ướp; kho bằng nước dừa xiêm tươi lửa nhỏ không đậy kín nắp hoàn toàn.',NULL,1,11),
('kitchen_detail_6','technique','Sườn xào chua ngọt bị khô xác','suon xao chua ngot,suon mem','Luộc sơ sườn 10 phút với chút muối cho chín mềm trước rồi chiên vàng nhanh lớp ngoài 2 phút, sau đó mới đảo sốt chua ngọt sánh bóng.',NULL,1,11),
('kitchen_detail_7','technique','Canh chua nấu bị đục và rau nát nhừ','canh chua trong,rau canh chua','Chỉ thả bạc hà, giá đỗ, đậu bắp và rau om ngò gai vào khoảng 1-2 phút cuối rồi tắt bếp ngay để giữ độ giòn tươi.',NULL,1,11),
('kitchen_detail_8','technique','Đậu hũ chiên giòn để nguội bị xẹp mềm','dau hu chien gion,dau hu phong','Chiên đậu hũ ở nhiệt độ dầu cao vừa ổn định đến khi vỏ vàng giòn căng nhẹ, đặt lên giá lưới thoáng gió thay vì xếp chồng lên đĩa.',NULL,1,11),
('kitchen_detail_9','technique','Chiên khoai môn / khoai lang không bị ngấm dầu','khoai mon chien,khoai lang chien','Thấm khô nước hoặc áo lớp bột năng khô siêu mỏng, chiên khi dầu sôi thử đầu đũa sủi tăm mạnh, không cho quá nhiều một mẻ.',NULL,1,11),
('kitchen_detail_10','technique','Tôm rim mặn ngọt bị ra nước lõng bõng','tom rim man ngot,tom rim keo','Cắt râu và để tôm thật ráo; xóc tôm với chút đường và muối trước 10 phút để rút ẩm bề mặt, sau đó đảo lửa lớn cho sốt sánh kẹo bám vỏ.',NULL,1,11),
('kitchen_detail_11','prep_safety','Măng tươi hoặc măng khô nấu canh bị đắng hoặc mùi hăng','mang dang,so che mang,canh mang','Măng tươi thái lát luộc mở nắp 2 lần nước với nhúm muối rồi xả lạnh; măng khô ngâm nước vo gạo qua đêm và luộc thay nước 2-3 lần đến khi nước trong.',NULL,1,11),
('kitchen_detail_12','prep_safety','Khổ qua (mướp đắng) giảm vị đắng mà vẫn giữ màu xanh','kho qua bot dang,muop dang xao trung','Bổ đôi nạo thật sạch phần cùi trắng và màng hạt bên trong, thái lát ngâm nước đá lạnh 10 phút hoặc bóp muối xả sạch trước khi xào/nhồi thịt.',NULL,1,11),
('kitchen_detail_13','troubleshooting','Khắc phục canh bí xanh / canh bầu bị chua nước','canh bi bi chua,nau canh bau','Không đậy nắp nồi kín khi canh còn nóng trên bếp ủ quá lâu; múc canh ra tô thoáng khí khi nguội.',NULL,1,11)
INSERT INTO `chatbot_knowledge_base` (`topic`,`category`,`title`,`keywords_text`,`content`,`substitution_json`,`is_active`,`priority`) VALUES
('kitchen_detail_14','troubleshooting','Chả cá chiên bị phồng to rồi xẹp lép sau khi vớt','cha ca bi xep','Không đánh quá nhiều bột nở và giữ nhiệt dầu ổn định vừa phải 160-170°C để chả chín đều từ lõi ra ngoài.',NULL,1,11),
('kitchen_detail_15','technique','Thịt bò xào cần tây, hành tây giữ hành giòn thơm','bo xao can tay,bo xao hanh tay','Xào bò riêng trên lửa lớn cho chín tái 80% trút ra đĩa, dùng chảo đó xào cà rốt/cần tây/hành tây 1.5 phút rồi trút bò vào đảo hòa quyện 30 giây.',NULL,1,11),
('kitchen_detail_16','technique','Mì Quảng hoặc Bún mắm nấu tại nhà chuẩn vị','mi quang,nuoc nhan mi quang','Nước dùng mì Quảng ít và đậm đặc (nước nhân), không chan đầy bát như phở; phi thơm củ nén/hành tím với dầu điều để dậy hương miền Trung.',NULL,1,11),
('kitchen_detail_17','technique','Nước chấm gừng cho vịt luộc và gà luộc','nuoc mam gung,cham vit luoc','Giã nhuyễn gừng non, tỏi, ớt cùng đường trước trong cối để ra tinh dầu thơm rồi mới cho nước mắm ngon và nước cốt chanh hòa quyện.',NULL,1,11),
('kitchen_detail_18','troubleshooting','Cháo trắng hoặc cháo thịt bị vữa lỏng khi nguội','chao bi vua,nau chao sanh','Trộn 10% gạo nếp với 90% gạo tẻ khi nấu cháo, chỉ nêm mắm muối vào tô hoặc lúc ăn nóng; khuấy trực tiếp nước mắm vào nồi cháo lớn dễ làm cháo nhanh tách nước.',NULL,1,11),
('kitchen_detail_19','prep_safety','Làm nước ép cà rốt dứa táo không bị tách lớp bọt','nuoc ep tach lop,nuoc ep gung','Thêm 1/2 quả chanh tươi và dùng ngay sau khi ép ở tốc độ chậm; nếu bảo quản tủ lạnh chỉ giữ tối đa 24h trong chai thủy tinh đầy kín nắp.',NULL,1,11),
('kitchen_detail_20','technique','Bò khô / Gà xé lá chanh sấy nồi chiên không dầu bị cháy xém lá','ga xe la chanh,bo kho noi chien','Sấy phần thịt ở 120-130°C cho khô dần, chỉ cho lá chanh thái sợi vào 5 phút cuối cùng khi nhiệt hạ còn 100°C.',NULL,1,11),
('kitchen_detail_21','prep_safety','Cách chọn bơ sáp ngon béo mịn làm sinh tố','chon bo sap,bo ngon','Chọn quả vỏ xanh điểm lấm tấm vàng, cuống nhỏ hơi héo, cầm chắc nặng tay và ấn nhẹ thấy mềm đàn hồi; không bóp mạnh làm dập đen ruột.',NULL,1,11),
('kitchen_detail_22','prep_safety','Chân gà sả tắc ngâm không bị đắng vỏ tắc và không nhớt','chan ga sa tac','Luộc chân gà chín vừa ngâm nước đá thật giòn và để ráo hoàn toàn. Nước ngâm mắm đường nấu sôi để nguội hẳn 100% rồi mới thả chân gà, tắc bỏ hạt và ớt.',NULL,1,11),
('kitchen_detail_23','technique','Nước lẩu Thái / Lẩu nấm thanh ngọt không khé cổ','lau thai,lau nam,nuoc lau ngon','Phi thơm sả riềng lá chanh với cà chua và dứa cho lẩu Thái; dùng củ cải, táo lê, nấm đông cô và bắp ngọt ninh cho lẩu nấm.',NULL,1,11),
('kitchen_detail_24','prep_safety','Khử mùi ngái của lươn hoặc ốc nhồi trước khi nấu','luon het nhot,oc het ban','Ngâm ốc nước vo gạo có 2 trái ớt cắt đôi 3 tiếng cho nhả hết bùn; tuốt nhớt lươn bằng muối hạt và nước chanh hoặc tro sạch rồi rửa nước ấm.',NULL,1,11),
('kitchen_detail_25','nutrition','Cách chia thực đơn 1800 kcal giữ dáng cho người vận động vừa','thuc don 1800 kcal,dinh duong can bang','Duy trì 3 bữa chính ~500 kcal/bữa và 1 bữa phụ ~250-300 kcal (sữa chua không đường + trái cây + hạnh nhân), đảm bảo tối thiểu 90-110g protein/ngày.',NULL,1,11),
('kitchen_detail_26','technique','Mẹo nấu xôi gấc hoặc xôi lá dứa lên màu tự nhiên đẹp','xoi la dua,xoi gac,tao mau tu nhien','Xay lá dứa với nước lọc lọc bã lấy nước cốt ngâm nếp 6 tiếng; xôi gấc bóp thịt gấc với xíu rượu trắng và chút muối để màu đỏ cam tươi rực rỡ.',NULL,1,11),
('kitchen_detail_27','technique','Bí quyết làm tôm chiên xù giòn thẳng không bị cong vòng','tom chien xu,tom thang','Rút chỉ lưng tôm xong khứa 3-4 khía nông dưới bụng tôm rồi ấn nhẹ duỗi thẳng lưng tôm cho đứt gân trước khi nhúng bột chiên.',NULL,1,11),
('kitchen_detail_28','technique','Cách pha bột bánh tráng cuốn chả rế không bị thấm dầu','cha gio re,chien cha gio','Đặt vỏ bánh rế mặt nhám vào trong, không cuộn quá chặt tay để hơi ẩm thoát đều lúc chiên, chiên ở nhiệt ổn định 165°C.',NULL,1,11),
('kitchen_detail_29','technique','Làm muối tiêu chanh ớt xanh chấm hải sản chuẩn vị','muoi ot xanh,cham hai san','Xay nhuyễn ớt xiêm xanh bỏ hạt, lá chanh non, đường, muối, sữa đặc và nước cốt chanh để tạo độ sánh xanh mướt chấm tôm mực nướng cực kỳ bắt vị.',NULL,1,11),
('kitchen_detail_30','prep_safety','Cách sơ chế tim heo, cật heo hoặc lòng non không bị hôi đắng','so che long,khu mui long,tim heo','Lộn trái bóp kỹ với muối hạt, bột mì và giấm/chanh 5 phút, luộc qua nước sôi gừng rượu rồi ngâm ngay vào nước đá có vài giọt chanh cho trắng giòn.',NULL,1,11),
('kitchen_detail_31','prep_safety','Cách giữ màu trắng giòn cho ngó sen, củ sen làm gỏi','ngo sen trang gion,goi ngo sen','Ngó sen rửa sạch thái khúc chẻ đôi ngâm ngay vào thau nước đá pha nước cốt chanh + chút đường 15 phút rồi vớt để ráo trước khi trộn gỏi.',NULL,1,11),
('kitchen_detail_32','technique','Nướng cá bằng giấy bạc không bị ra nước nhão thịt','ca nuong giay bac','Thấm thật khô cá, lót hành sả phía dưới và mở hé mép giấy bạc trong 5 phút cuối ở nhiệt 200°C để hơi nước thoát ra làm săn mặt cá.',NULL,1,11),
('kitchen_detail_33','technique','Chua cay mặn ngọt trong nộm sứa/gỏi đu đủ Thái','goi du du,can bang vi chua ngot','Giã nhẹ tỏi ớt cùng đường thốt nốt trước, hòa tan nước mắm và cốt chanh theo tỉ lệ cân bằng 1 mắm : 1 đường : 1 chanh rồi rưới vào lúc sắp ăn.',NULL,1,11),
('kitchen_detail_34','nutrition','Cân bằng bữa ăn khi nấu món chiên nướng nhiều đạm béo','can bang dinh duong mon nuong','Luôn kết hợp 1 món salad rau xanh hoặc dưa góp chua ngọt ít đường cùng canh rau thanh mát giúp giảm tải chất béo bão hòa cho bữa ăn.',NULL,1,11),
('spice_fact_1','cooking_tip','Dầu mè (Dầu vừng)','dau me,thom dau me','Chỉ rưới 1/2-1 muỗng cà phê dầu mè sau khi tắt bếp hoặc trộn gỏi; không dùng dầu mè để chiên nhiệt cao lâu vì dễ bay mất hương thơm đặc trưng.',NULL,1,11),
('spice_fact_2','cooking_tip','Dầu ô liu trong nấu ăn Việt','dau o liu,xao dau o liu','Dầu ô liu nguyên chất (Extra Virgin) hợp trộn salad, gỏi hoặc áp chảo lửa vừa; tránh chiên ngập dầu bốc khói trên 200°C.',NULL,1,11),
('spice_fact_3','cooking_tip','Nước tương đậm và nước tương nhạt','nuoc tuong,xi dau','Nước tương nhạt (xì dầu loãng) dùng để nêm và chấm, còn hắc xì dầu dùng lượng ít 1/2-1 thìa để tạo màu nâu cánh gián bóng đẹp cho món kho.',NULL,1,11),
('spice_fact_4','cooking_tip','Nghệ tươi và bột nghệ','nghe tuoi,bot nghe','Nghệ tươi giã vắt cốt hoặc xào thơm nhẹ trong dầu giúp màu vàng tươi mà không bị hăng; tránh đun bột nghệ khô lửa quá gắt gây khét đắng.',NULL,1,11)
INSERT INTO `chatbot_knowledge_base` (`topic`,`category`,`title`,`keywords_text`,`content`,`substitution_json`,`is_active`,`priority`) VALUES
('spice_fact_5','cooking_tip','Hạt nêm từ nấm hương & rong biển','hat nem chay,hat nem nam','Dùng hạt nêm nấm hương giúp các món canh chay, xào chay có hậu vị ngọt thanh tròn trịa mà không cần nước hầm xương.',NULL,1,11),
('spice_fact_6','cooking_tip','Lá dứa tươi trong nấu chè & xôi','la dua,thom la dua','Rửa sạch lá dứa, cuộn gọn cho trực tiếp vào nồi chè lúc đun nhỏ lửa 5 phút cuối rồi vớt bỏ để chè thơm dịu tự nhiên.',NULL,1,11),
('spice_fact_7','cooking_tip','Quả gấc & Dầu điều tạo màu đỏ tự nhiên','dau dieu,mau dieu,tao mau do','Thắng hạt điều màu với dầu ăn lửa nhỏ vừa sủi tăm 2 phút rồi tắt bếp chắt bỏ hạt giúp món bún bò, bò kho, thịt nướng có màu đỏ cam an toàn.',NULL,1,11),
('spice_fact_8','cooking_tip','Me vắt chín bảo quản lâu','bao quan me,me vat','Bọc kín me vắt bằng màng bọc thực phẩm để ngăn mát dùng trong 6 tháng; khi nấu dầm nước nóng rây bỏ xơ hạt.',NULL,1,11),
('spice_fact_9','cooking_tip','Nước dừa xiêm tươi trong kho cá thịt','nuoc dua tuoi,kho nuoc dua','Dùng nước dừa tươi kho cá thịt giúp thịt mềm ngọt thấm vị tự nhiên; nhớ giảm lượng đường trong công thức lại khoảng 30% để không bị quá ngọt.',NULL,1,11),
('spice_fact_10','cooking_tip','Cơm nguội chiên hạt tơi giòn','com chien,com rang,com nguoi','Cơm nấu hơi khô ráo hoặc cơm nguội để ngăn mát không đậy kín 2 giờ, đánh tơi với 1 lòng đỏ trứng gà rồi mới rang trên chảo lửa vừa.',NULL,1,11),
('spice_fact_11','cooking_tip','Đậu đen & Đậu xanh nấu chè nhanh nhừ','dau den nhanh mem,dau xanh nhanh nhu','Ngâm đậu đen/đậu xanh vỏ nguyên hạt 4-6 tiếng với nước ấm, có thể chần nhanh hoặc rang sơ 3 phút trên chảo khô trước khi ninh cho hạt mềm bùi mà vỏ không bị bung nát.',NULL,1,11),
('spice_fact_12','cooking_tip','Nước dùng chay ngọt thanh không hóa chất','nuoc dung chay,nau nuoc dung chay','Ninh củ cải trắng, cà rốt, bắp ngọt, mướp hương hoặc su su cùng chân nấm hương và hành tây (hoặc hành boaro) trong 45 phút cho nồi nước dùng chay ngọt sâu.',NULL,1,11),
('spice_fact_13','cooking_tip','Cách chọn mực tươi giòn chuẩn vị','chon muc tuoi,muc ong','Mực tươi thân trắng sáng hơi trong, lớp màng nâu sẫm bám chắc không tróc nhớt, túi mực nguyên vẹn và râu mực săn bám chặt đầu.',NULL,1,11),
('spice_fact_14','cooking_tip','Làm sạch nhớt da cá trê và cá hú','ca tre,ca hu,het nhot','Chần nhanh nước nóng khoảng 70°C (không quá sôi làm rách da) rồi cạo nhẹ bằng dao cùn, rửa muối chanh sẽ sạch bong lớp nhớt.',NULL,1,11),
('spice_fact_15','cooking_tip','Bí quyết nấu súp cua sánh mịn không vữa','sup cua,bot nang sup cua','Hòa bột năng nước lạnh rót đều tay ở lửa vừa, chỉ đánh tan lòng trắng trứng rây nhỏ vào sau khi súp đã sánh đạt chuẩn để tạo vân mây tơ đẹp mắt.',NULL,1,11),
('spice_fact_16','cooking_tip','Cách thái thịt gà luộc gọn đẹp không nát da','chat ga dep,thai ga luoc','Để gà luộc nguội hẳn rồi chặt dứt khoát từng nhát bằng dao sắc bản to; có thể thoa nhẹ lớp dầu nghệ phi hành lên da cho vàng óng hấp dẫn.',NULL,1,11),
('spice_fact_17','cooking_tip','Bảo quản hành lá, rau mùi tươi cả tuần trong tủ lạnh','bao quan hanh la,bao quan rau thom','Nhặt bỏ lá úa, KHÔNG rửa trước khi cất (hoặc rửa xong phải quay thật khô), gói bằng giấy thấm ẩm nhẹ rồi cho vào túi zip đục vài lỗ nhỏ ngăn mát.',NULL,1,11),
('spice_fact_18','cooking_tip','Cách làm dưa cải chua nhanh giòn không bị khú','muoi dua cai,dua cai chua','Phơi héo nhẹ cải bẹ 2-3 giờ cho dẻo, pha nước muối đường (tỉ lệ 1 lít nước : 30g muối : 15g đường) đun ấm 40°C rồi ngập cải 2-3 ngày.',NULL,1,11),
('spice_fact_19','cooking_tip','Kiểm tra độ chín của thịt gà và sườn nướng','kiem tra chin thit,thit nuong chin','Xiên nhẹ đầu đũa vào phần thịt dày nhất sát xương: nếu nước tiết ra trong suốt không còn màu hồng đỏ là thịt đã chín đạt chuẩn an toàn.',NULL,1,11),
('spice_fact_20','cooking_tip','Định lượng khẩu phần ăn cân đối cho người tiểu đường','dinh duong tieu duong,phan an tieu duong','Áp dụng quy tắc Đĩa Ăn: 1/2 đĩa là rau củ luộc/hấp/xào ít dầu, 1/4 đĩa là cá/gà/đậu hũ, 1/4 đĩa còn lại là cơm gạo lứt/khoai lang/bún ít đường.',NULL,1,11),
('spice_fact_21','cooking_tip','Xử lý trứng luộc bị vỡ lòng trắng trong nồi','luoc trung khong vo,trung nut vo','Thêm 1 thìa cà phê giấm hoặc muối vào nước luộc giúp lòng trắng đông lại ngay lập tức nếu vỏ vô tình rạn nhẹ, giữ trứng tròn đẹp.',NULL,1,11),
('spice_fact_22','cooking_tip','Hâm nóng đồ chiên bằng nồi chiên không dầu để giòn lại','ham nong do chien','Xếp thành 1 lớp không chồng lên nhau, làm nóng ở 180°C trong 3-5 phút sẽ lấy lại độ giòn mà không cần thêm dầu ăn.',NULL,1,11),
('spice_fact_23','cooking_tip','Bí quyết nấu chè trôi nước không bị cứng vỏ khi để nguội','che troi nuoc,bot nep mem','Trộn thêm khoảng 15% khoai lang nghiền hoặc đậu hũ trắng nhuyễn vào bột nếp khi nhồi giúp viên chè mềm dẻo kể cả qua hôm sau.',NULL,1,11),
('spice_fact_24','cooking_tip','Tỉ lệ vàng bột bánh cuốn / bánh xèo không bị rách','pha bot banh xeo,bot gao','Ngâm hoặc để bột nghỉ tối thiểu 30-45 phút để hạt tinh bột ngậm đủ nước trương nở, giúp bánh dẻo mỏng mịn và dễ tróc chảo.',NULL,1,11),
('spice_fact_25','cooking_tip','Cách giải quyết nước sốt kho quá loãng khi sắp bắc bếp','nuoc kho loang,sot kho sanh','Vớt riêng phần thịt cá ra đĩa trước rồi bật lửa lớn cô phần nước sốt xuống 1/2 hoặc thêm 1/2 thìa bột năng pha nước trước khi rưới lại lên thịt.',NULL,1,11),
('spice_fact_26','cooking_tip','Mẹo cắt hành tây không bị cay mắt','cat hanh tay khong cay mat','Cho củ hành tây vào ngăn mát 20 phút (hoặc ngăn đá 10 phút) trước khi cắt và dùng dao thật bén để hạn chế vỡ tế bào giải phóng hơi cay.',NULL,1,11),
('spice_fact_27','cooking_tip','Cách bảo quản tỏi và hành khô không bị mọc mầm','bao quan toi,hanh tim moc mam','Để nơi khô ráo, thoáng gió trong túi lưới hoặc rổ thưa; tránh đặt cạnh khoai tây hoặc cất trong túi nilon kín dễ hấp hơi mốc.',NULL,1,11),
('spice_fact_28','cooking_tip','Món canh rau ngót thịt băm giữ màu xanh và không nồng','canh rau ngot','Tuốt lá rửa sạch, vò nhẹ tay cho hơi dập lá trước khi thả vào nồi nước thịt băm đang sôi nhẹ sẽ làm rau mềm ngọt thanh tự nhiên.',NULL,1,11),
('spice_fact_29','cooking_tip','Cách nấu canh khổ qua nhồi thịt không bị đắng hay bung nhân','canh kho qua nhoi thit','Trộn giò sống cùng thịt heo xay và miến/nấm mèo giúp nhân kết dính chặt với ruột khổ qua; chần khúc khổ qua 1 phút rồi mới nhồi để ruột giữ chắc.',NULL,1,11)
INSERT INTO `chatbot_knowledge_base` (`topic`,`category`,`title`,`keywords_text`,`content`,`substitution_json`,`is_active`,`priority`) VALUES
('spice_fact_30','cooking_tip','Lựa chọn loại dầu thực vật tốt cho tim mạch','dau an tot cho tim mach','Ưu tiên dầu đậu nành, dầu hướng dương, dầu gạo hoặc dầu ô liu ép lạnh thay cho mỡ động vật trong nấu ăn hàng ngày.',NULL,1,11),
('spice_fact_31','cooking_tip','Khắc phục nước dùng lẩu hải sản bị quá chua hoặc hăng sả','lau hai san,chinh vi lau','Dùng nước lọc thanh, chút đường phèn và cà rốt/bắp ngọt để cân bằng độ chua gắt, vớt bỏ phần bã sả ớt già sau khi đun sôi 10 phút.',NULL,1,11),
('spice_fact_32','cooking_tip','Cách ước lượng nhanh 100g thịt cá ngoài thực tế','100g thit bao nhieu,uoc luong gram','100g thịt ức gà/bò/cá phi lê sống tương đương kích thước lòng bàn tay người lớn (dày khoảng 1.5 cm), giúp dễ kiểm soát calo không cần cân.',NULL,1,11),
('spice_fact_33','cooking_tip','Bí quyết làm nước chấm muối ớt đỏ chuẩn vị Nha Trang','muoi ot do','Xay nhuyễn ớt sừng đỏ, ớt hiểm, muối hạt, đường, sữa đặc và nước cốt chanh hoặc quất; sắc đỏ cam tự nhiên dùng chấm gà nướng hoặc hải sản cực hợp.',NULL,1,11),
('spice_fact_34','cooking_tip','Mẹo hầm xương bằng nồi áp suất tiết kiệm thời gian','ham xuong noi ap suat','Chần xương sạch trước khi cho vào nồi áp suất, chỉ đổ nước tối đa 2/3 dung tích nồi và để van tự xả tự nhiên 10 phút sau khi tắt bếp để nước dùng trong không bị đục.',NULL,1,11),
('spice_fact_35','cooking_tip','Lý do nên nêm nước mắm ở bước cuối cùng của món canh','khi nao nem nuoc mam','Đun nước mắm sôi quá lâu ở nhiệt cao sẽ làm mất hương thơm đặc trưng và dễ chuyển vị hơi chua nhẹ; nên nêm ngay trước khi tắt bếp 1 phút.',NULL,1,11),
('spice_fact_36','cooking_tip','Cách làm nước sốt me chua ngọt sánh mịn chấm đồ chiên/nướng','sot me chua ngot','Me vắt lọc bỏ hạt nấu cùng đường thốt nốt, nước mắm/tương ớt và 1 thìa bột năng pha loãng ở lửa nhỏ đến khi sánh óng.',NULL,1,11),
('spice_fact_37','cooking_tip','Mẹo giữ bún bò/phở bò không bị nguội khi chan nước dùng','chan pho nong','Trần tô sứ bằng nước sôi trước khi xếp bánh phở và thịt bò thái mỏng, sau đó chan ngập nước dùng đang sôi bùng giúp thịt chín tái hoàn hảo và giữ nóng lâu.',NULL,1,11),
('spice_fact_38','cooking_tip','Thay đổi hương vị món trứng chiên quen thuộc cho bữa sáng','mon trung nhanh,trung chien','Kết hợp trứng gà đánh tan với hành lá, nấm băm, cà chua hạt lựu hoặc chút sữa tươi không đường áp chảo lửa nhỏ cho thành phẩm bông xốp bổ dưỡng.',NULL,1,11),
('spice_fact_39','cooking_tip','Mẹo nấu cơm gạo lứt mềm dẻo không bị cứng xác','nau com gao lut,gao lut mem','Ngâm gạo lứt tối thiểu 2-4 tiếng trước khi nấu, dùng tỉ lệ nước cao hơn gạo trắng (1 gạo : 1.8 đến 2 nước) và thêm vài giọt dầu ô liu + xíu muối.',NULL,1,11),
('spice_fact_40','cooking_tip','Cách kiểm soát lượng muối khuyến nghị hàng ngày khi nấu nướng','luong muoi an toan,giam muoi','Tổ chức Y tế Thế giới khuyến nghị dưới 5g muối/người/ngày (~1 muỗng cà phê); tận dụng gia vị thơm tự nhiên (tỏi, tiêu, chanh, gừng, rau thơm) để món ăn vẫn đậm đà mà ít natri.',NULL,1,11)
